insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description, public_access, image, source, verified_at, opening_hours, website, phone, osm_type, osm_id, timezone)
values
  ('Acton Bigfoot at YV Art Museum', 'acton-bigfoot-at-yv-art-museum', 'cryptids', 42.51841, -71.41825, 'Acton', 'MA', 'A roughly 23-foot steel Bigfoot towers among the outdoor sculptures at YV Art Museum and Contemporary Arts International. Rather than pretending to document a sighting, the massive Sasquatch works as a piece of monumental cryptid art in an already unusual sculpture landscape.', 'limited', null, 'https://www.roadsideamerica.com/tip/81876', '2026-09-09T04:43:56.902716+00:00', null, 'https://cai-yv.org/', null, null, null, 'America/New_York'),
  ('Albatwitch — Chickies Rock', 'albatwitch-chickies-rock', 'cryptids', 40.05231, -76.52491, 'West Hempfield Township', 'PA', 'Lancaster County folklore places the Albatwitch—a roughly four-foot hairy "apple-snitch" sometimes described as a miniature Bigfoot—in the woods surrounding Chickies Rock, where stories say it stole apples and threw the cores back at picnickers. The legend has been recorded in the area for generations and now has its own annual celebration; travelers can visit its traditional territory by hiking to the public Chickies Rock Overlook.', 'limited', null, 'https://susquehannagreenway.org/news-and-stories/susquehanna-greenway-ghouls-legends/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Beast of Bray Road', 'beast-of-bray-road', 'cryptids', 42.68185, -88.4828, 'Elkhorn', 'WI', 'Bray Road became nationally known after reports of a large wolf-like or upright canine creature were collected around Elkhorn beginning in the late 1980s. The legend is now one of Wisconsin''s signature cryptid stories. Treat the road as a normal public roadway: do not stop unsafely or enter private property.', 'roadside', null, 'https://www.atlasobscura.com/places/bray-road-2', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.visitwalworthcounty.com/', null, null, null, 'America/Chicago'),
  ('Beast of Busco', 'beast-of-busco', 'cryptids', 41.23583, -85.32519, 'Churubusco', 'IN', 'Churubusco''s signature legend began with reports of an enormous snapping turtle called Oscar in Fulk Lake, culminating in a highly publicized attempt to capture it in 1949. The town still embraces the "Beast of Busco" through Turtle Days and a large turtle statue in the community park, giving the cryptid story a clear public stop.', 'open', null, 'https://visitindiana.in.gov/listing/beast-of-busco/16069/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Big Muddy Monster Mural', 'big-muddy-monster-mural', 'cryptids', 37.76507, -89.33752, 'Murphysboro', 'IL', 'A downtown mural celebrates the shaggy three-toed creature reported around Murphysboro in 1973, keeping the Big Muddy Monster legend visible year-round.', 'roadside', null, 'https://southernillinoistourism.org/big-muddy-monster/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Big Muddy Monster Statue', 'big-muddy-monster-statue', 'cryptids', 37.7642, -89.3355, 'Murphysboro', 'IL', 'A dedicated Big Muddy Monster figure gives Murphysboro''s regional cryptid a physical roadside presence near the town connected to the 1973 sightings.', 'open', null, 'https://southernillinoistourism.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Front Yard Chainsaw Bigfoot', 'bigfoot', 'cryptids', 46.137069, -122.942008, 'Longview', 'WA', 'A twelve-foot Bigfoot carved from an evergreen stump by chainsaw artist Patrick Bryson in 2023, holding the house number. It stands in the front garden of a private home — view it from the road and do not enter the property.', 'private', null, 'https://www.roadsideamerica.com/tip/79870', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 9271115441, 'America/Los_Angeles'),
  ('Sherwood Bigfoot', 'bigfoot-2', 'cryptids', 45.36042, -122.856409, 'Sherwood', 'OR', 'A Bigfoot figure mapped beside a road in Sherwood, south-west of Portland. Nothing is published about who made it, when, or whether it stands on private ground — so treat it as a curiosity to look for rather than a destination, and do not go onto anyone''s property to find it.', 'roadside', null, 'https://www.openstreetmap.org/node/13670202967', null, null, null, null, 'node', 13670202967, 'America/Los_Angeles'),
  ('Bigfoot Discovery Museum', 'bigfoot-museum', 'cryptids', 37.041437, -122.072526, 'Felton', 'CA', 'A small roadside museum founded by longtime Bigfoot researcher Michael Rugg, holding footprint casts, local sighting reports, memorabilia and material relating to the Patterson-Gimlin film. Reported permanently closed — check before making the drive.', 'closed', null, 'https://www.roadsideamerica.com/story/17314', '2026-09-05T12:48:08.486466+00:00', null, 'https://www.bigfootdiscoveryproject.com/', '+1 831 335-4478', 'node', 797799539, 'America/Los_Angeles'),
  ('Bigfoot Statue', 'bigfoot-statue', 'cryptids', 40.93882, -123.628581, 'Willow Creek', 'CA', 'A standalone Bigfoot sculpture near Tonkin Park, one of several Sasquatch photo stops in the town that calls itself the Bigfoot Capital of the World. A roadside artwork rather than a staffed attraction.', 'roadside', null, 'https://mapcarta.com/N13526912734', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13526912734, 'America/Los_Angeles'),
  ('Bigfoot Trap', 'bigfoot-trap', 'cryptids', 42.056587, -123.137225, 'Jackson County', 'OR', 'A genuine wooden trap, built in 1974 by the North American Wildlife Research Team after reports of enormous human-like tracks. Long since disarmed, it sits on the Collings Mountain Trail in Rogue River-Siskiyou National Forest, about three quarters of a mile from the trailhead — you walk in.', 'open', null, 'https://www.fs.usda.gov/media/162817', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 10817099005, 'America/Los_Angeles'),
  ('Chamber of Commerce Hodag', 'chamber-of-commerce-hodag', 'cryptids', 45.632178, -89.423039, 'Rhinelander', 'WI', 'Rhinelander''s larger-than-life Hodag, sculpted by local artist Tracy Goberville and standing outside the Area Chamber of Commerce. The toothy green monster is the city''s signature landmark and a free photo stop year round, celebrating a hoax from the 1890s that never quite went away.', 'roadside', null, 'https://explorerhinelander.com/articles/4-spots-to-see-hodags-on-your-next-visit-to-rhinelander/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 2876677463, 'America/Chicago'),
  ('Champy Lake Monster Marker', 'champy-lake-monster-marker', 'cryptids', 44.70553, -73.40323, 'Plattsburgh', 'NY', 'This Legends & Lore marker on Cumberland Head commemorates Champ, the serpent-like creature allegedly seen in Lake Champlain for generations. More than 300 reported sightings have become part of regional folklore, and New York even symbolically protects the creature.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/10700-2/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Charles Mill Lake Monster', 'charles-mill-lake-monster', 'cryptids', 40.76533, -82.37155, 'Mifflin Township', 'OH', 'In 1959, three teenagers reported encountering a large armless humanoid with glowing green eyes and webbed feet near Charles Mill Lake, creating the legend of the Charles Mill Lake Monster. Charles Mill Marina has displayed the story for visitors behind its counter, giving the otherwise localized cryptid report a specific destination; the marina operates seasonally.', 'limited', null, 'https://www.richlandsource.com/2015/10/29/what-monster-lurks-at-charles-mill-lake/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elk River Bigfoot Statue', 'elk-river-bigfoot-statue', 'cryptids', 38.54886, -80.99986, 'Ivydale', 'WV', 'Clay County students built this roughly 10.5-foot, 1,800-pound Bigfoot sculpture for the Elk River Trail, giving the rail-trail its own Sasquatch landmark. The statue stands near Mile Marker 47 about two miles upstream from the Ivydale trailhead, so reaching it requires walking or biking the trail.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Expedition: Bigfoot! The Sasquatch Museum', 'expedition-bigfoot-the-sasquatch-museum', 'cryptids', 34.802273, -84.376175, 'Cherry Log', 'GA', 'Four thousand square feet given over entirely to Bigfoot: footprint casts, artifacts, life-size exhibits, sighting maps, photographs, a theatre, a reference library and a research vehicle. One of the most substantial dedicated Bigfoot attractions in the Southeast.', 'open', null, 'https://exploregeorgia.org/cherry-log/arts-culture/museums/expedition-bigfoot', '2026-09-05T12:48:08.486466+00:00', null, 'http://expeditionbigfoot.mdom.mobi/', '+1-706-946-2601', 'way', 380684000, 'America/New_York'),
  ('Ferry Fever', 'ferry-fever', 'cryptids', 47.566984, -122.630788, 'Bremerton', 'WA', 'A mural by Loc Hong at 532 5th Street, showing a Yeti taking a shower aboard a ferry against a backdrop of mountains — Pacific Northwest ferry culture crossed with cryptid humour. Visible from the street.', 'roadside', null, 'https://streetartcities.com/cities/seattle/markers/d3d8e61a-825e-4173-945e-4142ef7f5103', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 12672661145, 'America/Los_Angeles'),
  ('Gloucester Sea Serpent Statue', 'gloucester-sea-serpent-statue', 'cryptids', 42.61383, -70.66176, 'Gloucester', 'MA', 'A serpentine sculpture on the Gloucester Harborwalk commemorates the enormous sea creature reported by numerous witnesses off Cape Ann in 1817. Explanations for the historic sightings have ranged from ordinary marine animals to misidentification, but the Gloucester Sea Serpent remains one of Massachusetts'' defining cryptid legends.', 'open', null, 'https://www.atlasobscura.com/places/gloucester-sea-serpent-statue', '2026-09-09T04:43:56.902716+00:00', null, 'https://harborwalk.gloucester-ma.gov/locations/19-the-sea-serpent/', null, null, null, 'America/New_York'),
  ('Gonzalez Bigfoot Statue', 'gonzalez-bigfoot-statue', 'cryptids', 40.939748, -123.631694, 'Willow Creek', 'CA', 'A Bigfoot-themed roadside artwork in Willow Creek, California''s self-proclaimed Bigfoot Country. A quick photo stop near the centre of town and the Willow Creek-China Flat Museum rather than a full attraction.', 'roadside', null, 'https://mapcarta.com/N13531160722', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13531160722, 'America/Los_Angeles'),
  ('Great Cypress Swamp — Selbyville Swamp Monster', 'great-cypress-swamp-selbyville-swamp-monster', 'cryptids', 38.47825, -75.31934, 'Frankford', 'DE', 'Delaware’s huge Great Cypress Swamp accumulated monster stories long before the best-known 1960s sightings. The famous Selbyville Swamp Monster episode was ultimately a hoax involving local man Fred Stevens in a fur-covered costume, but it became a genuine piece of Delaware cryptid folklore. The swamp is conservation land, so interior access should be limited to authorized programs and public areas.', 'limited', null, 'https://whyy.org/articles/the-spooky-scam-that-haunted-southern-delaware/', '2026-09-08T18:31:51.932734+00:00', null, 'https://dewildlands.org/our-work/great-cypress-swamp/', null, null, null, 'America/New_York'),
  ('Hairy Women of Klipnocky Marker', 'hairy-women-of-klipnocky-marker', 'cryptids', 42.4277, -77.80109, 'Canaseraga', 'NY', 'Local legend says two girls disappeared into the Klipnocky forest after being told to hide there for safety and were later reported as large, hairy women living in the woods. The story was in circulation by the 1920s, and today a Legends & Lore marker on County Route 13C gives travelers a specific public-road stop tied to the tale.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/a-hairy-legend/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Head of the Egopantis', 'head-of-the-egopantis', 'cryptids', 42.58431, -71.64648, 'Shirley', 'MA', 'The Bull Run Restaurant displays the mounted ''head'' of a legendary creature called the Egopantis along with the musket said to have killed it in colonial times. The tavern presents the tale with a straight face, although the creature is almost certainly a modern fearsome-critter-style legend rather than an unknown species.', 'open', null, 'https://www.atlasobscura.com/places/head-of-the-egopantis-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.bullrunrestaurant.com/', null, null, null, 'America/New_York'),
  ('Hockomock Swamp', 'hockomock-swamp', 'cryptids', 41.99463, -71.04157, 'West Bridgewater', 'MA', 'Massachusetts'' largest freshwater wetland sits at the center of the region popularly called the Bridgewater Triangle. Generations of stories describe strange lights, ghostly voices, Bigfoot-like creatures and enormous winged animals in and around the swamp; these are folklore and reported experiences, not established phenomena.', 'limited', null, 'https://www.atlasobscura.com/places/hockomock-swamp-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hodag Statue, Rhinelander', 'hodag', 'cryptids', 45.655123, -89.400556, 'Rhinelander', 'WI', 'One of the many Hodags around Rhinelander — the horned, clawed beast Eugene Shepard claimed to have captured in 1893, later admitted as a hoax and adopted by the city as its emblem ever since. This one stands about two miles from the better-known Chamber of Commerce Hodag, so it is a second stop rather than the same one twice.', 'roadside', null, 'https://explorerhinelander.com/articles/take-a-hodag-tour-of-rhinelander/', null, null, null, null, 'node', 7815427682, 'America/Chicago'),
  ('Hodag Statue and Hodag Store', 'hodag-statue-and-hodag-store', 'cryptids', 45.63892, -89.41236, 'Rhinelander', 'WI', 'The Hodag is Rhinelander''s horned, tusked hometown monster, born from late-19th-century lumber-camp folklore and Eugene Shepard''s famous 1896 hoax photograph. The Chamber grounds give travelers a permanent giant Hodag statue, visitor information and a concrete stop tied directly to the legend.', 'open', null, 'https://www.explorerhinelander.com/hodag/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.explorerhinelander.com/', null, null, null, 'America/Chicago'),
  ('Honey Island Swamp', 'honey-island-swamp', 'cryptids', 30.21719, -89.64969, 'Pearl River', 'LA', 'Honey Island Swamp is the setting for Louisiana''s best-known cryptid tradition, the Honey Island Swamp Monster. Explore only through lawful public-water access or established tour operators rather than trespassing into remote marshland.', 'limited', null, 'https://www.explorelouisiana.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hoop Snake Hill Marker', 'hoop-snake-hill-marker', 'cryptids', 41.27935, -74.29825, 'Chester', 'NY', 'Generations of Warwick-area folklore describe an enormous snake that grabs its own tail, forms a hoop and rolls downhill toward its victims before striking with a spiked tail. The legend now has a dedicated marker overlooking the area associated with the creature.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/hoop-snake-hill/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('International Cryptozoology Museum', 'international-cryptozoology-museum', 'cryptids', 44.81827, -68.77495, 'Bangor', 'ME', 'The International Cryptozoology Museum moved to Bangor in 2026, bringing its collection of Bigfoot casts, cryptid artifacts, alleged evidence, pop-culture objects, and decades of cryptozoology history to a new home on Broadway. It is one of the most directly on-theme OddWay stops in the state.', 'limited', null, 'https://cryptozoologymuseum.com/plan-your-visit/', '2026-09-09T04:54:23.476824+00:00', null, 'https://cryptozoologymuseum.com/', null, null, null, 'America/New_York'),
  ('International Monster Museum', 'international-monster-museum', 'cryptids', 42.52224, -70.89314, 'Salem', 'MA', 'Visitors carry lanterns through a theatrical museum filled with werewolves, dragons, ghosts, cryptids and monsters drawn from folklore around the world. Created by special-effects artists, it sits inside Witch City Mall and leans fully into the creatures rather than Salem''s witch-trial history.', 'limited', null, 'https://www.internationalmonstermuseum.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.internationalmonstermuseum.com/', null, null, null, 'America/New_York'),
  ('Jersey Devil Coaster', 'jersey-devil', 'cryptids', 40.13439, -74.443789, 'Jackson', 'NJ', 'A single-rail roller coaster at Six Flags Great Adventure themed on the Pine Barrens legend: 130 feet, an 87-degree drop and three inversions. Park admission is required, so this is a day out rather than a roadside stop.', 'limited', null, 'https://www.sixflags.com/greatadventure/attractions/jersey-devil-coaster', '2026-09-05T12:48:08.486466+00:00', null, 'https://www.sixflags.com/greatadventure/attractions/jersey-devil-coaster', null, 'node', 12859899266, 'America/New_York'),
  ('Lake Champlain Monster Monument', 'lake-champlain-monster-monument', 'cryptids', 44.47347, -73.22155, 'Burlington', 'VT', 'A waterfront monument recognizes Champ, the long-necked creature said to inhabit Lake Champlain. Reports and legends surrounding Champ stretch back generations, making the lake monster one of the Northeast''s best-known cryptids even though no conclusive evidence has established its existence.', 'open', null, 'https://www.atlasobscura.com/places/lake-champlain-monster-monument', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Norman — “Normie” Monster', 'lake-norman-normie-monster', 'cryptids', 35.67213, -80.93259, 'Troutman', 'NC', 'North Carolina’s largest manmade lake has its own Nessie-style monster known as Normie. Reports collected over the years describe large wakes, unexplained splashes, and creatures compared with giant fish, crocodilians, or serpentine lake monsters; the pin uses Lake Norman State Park as a legitimate public access point.', 'open', null, 'https://www.atlasobscura.com/places/lake-norman', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Loveland Frogman Riverfront', 'loveland-frogman-riverfront', 'cryptids', 39.26984, -84.25816, 'Loveland', 'OH', 'The Loveland Frogman, a human-sized frog-like creature associated with the Little Miami River, has been part of local folklore since reported encounters beginning in 1955. Loveland now treats the creature as an official city mascot, and Nisbet Park gives travelers a public riverfront stop directly tied to the legend and the city''s recurring Return of the Frogman celebration.', 'open', null, 'https://lovelandoh.gov/491/City-Mascot', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lucille''s Jersey Devil Statue', 'lucilles-jersey-devil-statue', 'cryptids', 39.7426, -74.3701, 'Warren Grove', 'NJ', 'A winged Jersey Devil figure stands outside Lucille''s Luncheonette along Route 539 in the Pine Barrens. The restaurant embraces local Pine Barrens folklore, making the sculpture a useful physical stop for travelers following the legend of the Leeds Devil.', 'roadside', null, 'https://www.lucillescountrycooking.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lyonesse River Monster Marker', 'lyonesse-river-monster-marker', 'cryptids', 43.61615, -75.35691, 'Lyons Falls', 'NY', 'Lyonesse is a supposed 15-foot river creature first famously reported in the Black River in 1951, described as dark brown with unusual fins and silver-colored eyes. The town installed a Legends & Lore marker beside the river, making this unusually obscure New York cryptid easy to visit.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/lyonesse/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maryland Goatman at Governor''s Bridge', 'maryland-goatman-at-governors-bridge', 'cryptids', 38.95143, -76.69346, 'Bowie', 'MD', 'Governor''s Bridge is one of the locations most closely tied to Maryland''s Goatman legend, the half-man, half-goat creature said to stalk the woods and roads around Prince George''s County. The 1912 bridge itself is closed to vehicle traffic, so use the nearby public natural-area access and do not enter neighboring private property or wander the area after posted hours.', 'limited', null, 'https://historicbridges.org/bridges/browser/?bridgebrowser=maryland/governorsbridge/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Michigan Dogman — Mystery Town USA', 'michigan-dogman-mystery-town-usa', 'cryptids', 45.77956, -84.73281, 'Mackinaw City', 'MI', 'Michigan''s Dogman is a long-running canine-humanoid legend that became especially famous through northern Michigan storytelling and radio culture. Mystery Town USA gives the creature a real, legal destination through a dedicated Dogman exhibit inside its walkthrough of cryptids, UFOs and other mysteries.', 'open', null, 'https://mysterytownusa.com/portfolio-items/michigan-dogman/', '2026-09-08T14:53:55.160019+00:00', null, 'https://mysterytownusa.com/', null, null, null, 'America/Detroit'),
  ('Mothman Museum', 'mothman-museum', 'cryptids', 38.842731, -82.138529, 'Point Pleasant', 'WV', 'Point Pleasant spent thirteen months in 1966 and 1967 reporting a winged figure with red eyes, and it has never really stopped. The museum keeps the newspaper clippings, the witness statements and props from the film adaptation in one small storefront on Main Street, a short walk from the statue.', 'open', null, 'https://www.mothmanmuseum.com/', '2026-09-06T01:56:28.154232+00:00', 'Mo-Th 10:00-17:00; Fr-Sa 10:00-18:00; Su 12:00-17:00; Dec 25 off; Jan 1 off; Nov Th[4] off; easter off', 'https://www.mothmanmuseum.com/', '+1-304-812-5211', 'way', 904768521, 'America/New_York'),
  ('Mothman Statue', 'mothman-statue', 'cryptids', 38.842573, -82.13852, 'Point Pleasant', 'WV', 'Bob Roach''s twelve-foot stainless-steel Mothman, installed downtown in 2003 and now one of the best-known cryptid landmarks in the country. It stands beside the Mothman Museum and is free to visit day or night.', 'roadside', null, 'https://visitpointpleasantwv.com/see-do/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 5328446004, 'America/New_York'),
  ('Museum Bigfoot Statue', 'museum-bigfoot-statue', 'cryptids', 40.940121, -123.632084, 'Willow Creek', 'CA', 'An outdoor Bigfoot statue at the Community Commons, alongside the Willow Creek-China Flat Museum and the visitor information point. Another easy photo stop while working through the town''s Bigfoot landmarks.', 'roadside', null, 'https://www.willowcreekcsd.com/community-commons/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13527671968, 'America/Los_Angeles'),
  ('North American Bigfoot Center', 'north-american-bigfoot-center', 'cryptids', 45.431789, -122.340251, 'Boring', 'OR', 'A museum and research centre founded by Bigfoot researcher Cliff Barackman, with footprint casts, historical artifacts, films and a life-size Sasquatch. The gift shop and information area are free; the exhibit halls charge admission.', 'open', null, 'https://traveloregon.com/things-to-do/oregon-attractions/museums/north-american-bigfoot-center/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 8868908017, 'America/Los_Angeles'),
  ('Origin of Champ Marker', 'origin-of-champ-marker', 'cryptids', 44.03611, -73.45666, 'Port Henry', 'NY', 'Bulwagga Bay is one of the locations most closely associated with Champ, the legendary creature of Lake Champlain. The marker here preserves a local origin story in which a scorned suitor becomes the lake monster, while Port Henry has built a much broader identity around decades of alleged Champ sightings.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/origin-of-champ/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Otis the Fishing Sasquatch', 'otis-the-fishing-sasquatch', 'cryptids', 38.41535, -86.7601, 'French Lick', 'IN', 'Otis is a 25-foot wooden Sasquatch built by Bear Hollow Wood Carvers in 2023 and posed on a broken dock with an enormous fishing pole. He stands on the French Lick Cabins at Patoka Lake property and has become a destination in his own right, but visitors should remember that the surrounding cabins are an operating lodging property.', 'limited', null, 'https://www.roadsideamerica.com/tip/84642', '2026-09-08T13:53:25.695107+00:00', null, 'https://frenchlickcabins.net/', null, null, null, 'America/Indiana/Vincennes'),
  ('Peninsula Python Mural', 'peninsula-python-mural', 'cryptids', 41.2397, -81.55402, 'Peninsula', 'OH', 'In 1944, reports of a roughly 15-to-18-foot snake supposedly loose around Peninsula triggered searches and national attention, although the Peninsula Python was never found. The large 1964 mural on the front of Peninsula Library maps the winding Cuyahoga River valley and has become physically associated with the monster-snake legend, making it an easy public stop in town.', 'open', null, 'https://peninsulalibrary.org/about/mural/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pocomoonshine Lake — Serpent Legend', 'pocomoonshine-lake-serpent-legend', 'cryptids', 45.14628, -67.51144, 'Princeton', 'ME', 'Pocomoonshine Lake is tied to one of Maine’s lesser-known lake-monster traditions. Stories recorded in the region describe a huge serpent-like creature and strange trails supposedly left as it crossed between bodies of water. The coordinates lead to a legitimate public boat-launch access point, not to a claimed encounter location.', 'open', null, 'https://folkbestiary.com/maine/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pope Lick Monster — Pope Lick Park', 'pope-lick-monster-pope-lick-park', 'cryptids', 38.18781, -85.48466, 'Louisville', 'KY', 'Louisville folklore tells of a goat-man creature said to inhabit the area around the Pope Lick railroad trestle. The trestle is active railroad property and has been the site of fatal accidents, so OddWay should route travelers to public Pope Lick Park for the legend and never onto the tracks or bridge.', 'open', null, 'https://www.atlasobscura.com/places/the-pope-lick-monster', '2026-09-08T14:15:10.228298+00:00', null, 'https://louisvilleky.gov/government/parks/park-list/pope-lick-park', null, null, null, 'America/Kentucky/Louisville'),
  ('Riverside Park / Big Muddy Monster Sighting Area', 'riverside-park-big-muddy-monster-sighting-area', 'cryptids', 37.75623, -89.35776, 'Murphysboro', 'IL', 'The wooded riverfront area evokes the landscape around Murphysboro where residents reported the Big Muddy Monster during the 1973 flap.', 'open', null, 'https://southernillinoistourism.org/big-muddy-monster/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Salt Fork Bigfoot Search', 'salt-fork-bigfoot-search', 'cryptids', 40.10593, -81.52868, 'Jefferson Township', 'OH', 'Salt Fork State Park is one of Ohio''s best-known Bigfoot areas, with decades of reported sightings of the creature sometimes called the Ohio Grassman. Salt Fork Lodge actively embraces the legend: visitors can pick up a Bigfoot sightings map at the front desk and search the surrounding public park trails, and the lodge hosts the annual Ohio Bigfoot Conference.', 'open', null, 'https://www.saltforkparklodge.com/things-to-do/onsite-activities', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bloomfield Sasquatch', 'sasquatch', 'cryptids', 42.531314, -83.315132, 'Bloomfield', 'MI', 'A Sasquatch figure in Bloomfield Township, mapped close to the historic Franklin Cider Mill on Franklin Road. No artist, date or owner is recorded anywhere we can find. Visible from the road; the cider mill itself is the reason most people are on that stretch.', 'roadside', null, 'https://mapcarta.com/N12664732006', null, null, null, null, 'node', 12664732006, 'America/Detroit'),
  ('Sol Duc Sasquatch', 'sasquatch-2', 'cryptids', 47.98701, -124.393304, 'Clallam County', 'WA', 'A Sasquatch figure in the forest of Clallam County, mapped near the Sol Duc river east of Forks — deep in the country the Patterson-Gimlin era made famous. Nothing is published about it. Forest roads out here are remote and seasonal, so check conditions before going looking.', 'roadside', null, 'https://mapcarta.com/N7316891219', null, null, null, null, 'node', 7316891219, 'America/Los_Angeles'),
  ('Sasquatch Outpost', 'sasquatch-outpost', 'cryptids', 39.406045, -105.475045, 'Bailey', 'CO', 'A Bigfoot-themed shop and visitor attraction in Bailey, home to the Sasquatch Encounter Discovery Museum. Exhibits cover sightings, evidence, research and Colorado''s own Sasquatch stories, with a substantial gift shop attached.', 'open', null, 'https://www.colorado.com/bailey/attractions-entertainment/museums/sasquatch-outpost', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'way', 129813715, 'America/Denver'),
  ('Sasquatch - Photo Opp', 'sasquatch-photo-opp', 'cryptids', 37.036099, -88.271112, 'Livingston County', 'KY', 'A roadside Sasquatch photo opportunity near Kentucky Lake and Grand Rivers. A pose-and-go cryptid stop rather than a museum.', 'roadside', null, 'https://mapcarta.com/N12893412684', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 12893412684, 'America/Chicago'),
  ('Sasquatch Pushing Over a House', 'sasquatch-pushing-over-a-house', 'cryptids', 47.664314, -122.319674, 'Seattle', 'WA', 'Richard Beyer''s 1982 sculpture at University Playground: a full-size aluminium Sasquatch leaning into a brightly painted house frame and apparently pushing it over. Free and always there.', 'open', null, 'https://en.wikipedia.org/wiki/Sasquatch_Pushing_Over_a_House', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 3211770268, 'America/Los_Angeles'),
  ('Sasquatch Statue', 'sasquatch-statue', 'cryptids', 48.995582, -122.75162, 'Blaine', 'WA', 'A 3,500-pound concrete Sasquatch, six foot eight, standing downtown near the Welcome Center. Installed as a town landmark and free to visit at any hour.', 'roadside', null, 'https://blainebythesea.com/sasquatch-statue/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 10065644288, 'America/Los_Angeles'),
  ('Sassy the Shawnee Forest Bigfoot', 'sassy-the-shawnee-forest-bigfoot', 'cryptids', 37.58078, -88.36599, 'Herod', 'IL', 'A 2,600-pound roadside Sasquatch named Sassy stands near Garden of the Gods as southern Illinois'' most overt Bigfoot photo stop.', 'roadside', null, 'https://www.shawneeforest.com/big-foot/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Silver Lake Sea Serpent Marker', 'silver-lake-sea-serpent-marker', 'cryptids', 42.70068, -78.02302, 'Silver Lake', 'NY', 'Stories of a monster in Silver Lake became so popular that a local hotel owner built a mechanical sea serpent in 1855 and secretly launched it into the water to attract tourists. The hoax was eventually exposed, but the Silver Lake serpent survived as local folklore and now has its own Legends & Lore marker.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/sea-serpent-legend/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skunk Ape Research Headquarters', 'skunk-ape-center-and-museum', 'cryptids', 25.893918, -81.278523, 'Ochopee', 'FL', 'An Everglades stop devoted to Florida''s Skunk Ape, the swamp-dwelling cryptid often called the Southeast''s Bigfoot. Based at Trail Lakes Campground, it collects sighting reports, lore and research alongside a well-stocked gift counter.', 'open', null, 'https://www.skunkape.info/', '2026-09-05T12:48:08.486466+00:00', null, 'https://www.skunkape.info/', null, 'node', 10210835917, 'America/New_York'),
  ('South Carolina Cotton Museum — Lizard Man Exhibit', 'south-carolina-cotton-museum-lizard-man-exhibit', 'cryptids', 34.2205, -80.24694, 'Bishopville', 'SC', 'The museum’s lobby preserves the story of the Lizard Man of Scape Ore Swamp, the reptilian creature whose alleged 1988 encounters turned Bishopville into a cryptid destination. The current exhibit covers the original sightings and ensuing “Lizardmania,” making this the most concrete public stop for South Carolina’s signature cryptid.', 'open', null, 'https://sccotton.org/notable-mentions', '2026-09-09T05:53:13.784429+00:00', null, 'https://www.sccotton.org/', null, null, null, 'America/New_York'),
  ('Southern Oregon Bigfoot Experience', 'southern-oregon-bigfoot-experience', 'cryptids', 42.167613, -123.646048, 'Cave Junction', 'OR', 'A Bigfoot museum, gift shop and roadside attraction with footprint casts, alleged hair samples, regional sighting accounts and a large Bigfoot statue outside. Yeti''s Ice Cream & Treats is attached.', 'open', null, 'https://sobfe.com/', '2026-09-05T12:48:08.486466+00:00', null, 'https://sobfe.com/', null, 'node', 11343789706, 'America/Los_Angeles'),
  ('St. John’s Episcopal Church — Demon Dogs of Valle Crucis', 'st-johns-episcopal-church-demon-dogs-of-valle-crucis', 'cryptids', 36.23199, -81.79873, 'Sugar Grove', 'NC', 'This historic mountain church is tied to the legend of the Demon Dogs of Valle Crucis: enormous spectral black dogs, sometimes described with glowing eyes, said to appear along the dark roads around the church. The haunting is folklore, but the church and cemetery are real historic sites and remain in use. Location source: https://mapcarta.com/21324918', 'limited', null, 'https://www.visitnc.com/itinerary/uncover-mountain-mysteries-north-carolinas-haunted-trail', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Surfing Sasquatch', 'surfing-sasquatch', 'cryptids', 44.979731, -124.013634, 'Lincoln City', 'OR', 'A hand-carved wooden Sasquatch riding a surfboard, which is exactly right for the Oregon Coast. It stands at the Surfland Hotel — hotel property rather than a public park, so be considerate about photographs.', 'roadside', null, 'https://mapcarta.com/N13021851179', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13021851179, 'America/Los_Angeles'),
  ('The Cryptozoology & Paranormal Museum', 'the-cryptozoology-paranormal-museum', 'cryptids', 36.433169, -77.916204, 'Littleton', 'NC', 'The Cryptozoology & Paranormal Museum is a small Littleton museum devoted to Bigfoot, ghosts and other unexplained phenomena. Visitors can see footprint casts, reportedly haunted objects and paranormal displays, with separate ghost hunts and Bigfoot-related outings offered at times.', 'open', null, 'https://crypto-para.org/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 606784641, 'America/New_York'),
  ('Mission Ridge Yeti', 'the-yeti', 'cryptids', 47.275547, -120.428416, 'Wenatchee', 'WA', 'An eleven-foot metal Yeti high on Mission Ridge near the Liberator Express chairlift, welded from steel, recycled tire chains and scrap. The chain "fur" was designed to catch snow and frost. Reaching it means getting up the mountain, so this is a ski-area visit rather than a roadside stop.', 'limited', null, 'https://www.visitwenatchee.org/blog/behind-the-mission-ridge-yeti-three-years-later', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 9634773055, 'America/Los_Angeles'),
  ('TNT Area', 'tnt-area', 'cryptids', 38.92977, -82.07616, 'Point Pleasant', 'WV', 'The abandoned World War II explosives complex north of Point Pleasant is inseparable from the original Mothman story, with many early sightings reported around the old TNT bunkers in 1966–67. Portions can be explored on foot, but the former industrial landscape includes remediated Superfund land and mixed property boundaries, so visitors should stay on established public paths.', 'limited', null, 'https://www.atlasobscura.com/places/tnt-area', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wampahoofus Trail', 'wampahoofus-trail', 'cryptids', 44.50574, -72.84764, 'Underhill', 'VT', 'This rugged Mount Mansfield trail is named for the wampahoofus, a mythical Green Mountain creature said to have legs shorter on one side so it could circle steep hillsides. Reaching the trail requires a mountain hike from the Stevensville area, and mud, snow and ice can make access seasonal.', 'limited', null, 'https://www.atlasobscura.com/places/wampahoofus-trail', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Willow Creek-China Flat Museum & Bigfoot Collection', 'willow-creek-china-flat-museum-bigfoot-collection', 'cryptids', 40.94025, -123.632115, 'Willow Creek', 'CA', 'A seasonal local-history museum holding one of the area''s most important Bigfoot collections: footprint casts, photographs, historical documents and material from researcher Bob Titmus. It sits a short distance from Bluff Creek, where the Patterson-Gimlin film was shot in 1967.', 'limited', null, 'https://www.thebigfootmuseum.com/', '2026-09-05T12:48:08.486466+00:00', 'Seasonal', 'https://www.thebigfootmuseum.com/', null, 'node', 12892684891, 'America/Los_Angeles'),
  ('Woodbooger Statue and Sanctuary', 'woodbooger-statue-and-sanctuary', 'cryptids', 36.91951, -82.62718, 'Norton', 'VA', 'After Animal Planet''s Finding Bigfoot filmed in Southwest Virginia, Norton embraced its local Bigfoot-like creature known as the Woodbooger and designated Flag Rock Recreation Area as a Woodbooger Sanctuary. A large creature statue now stands just beyond the parking area on the footpath toward Flag Rock Overlook.', 'open', null, 'https://www.nortonva.gov/455/Woodbooger-Sanctuary', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yolo the Jackpotalope', 'yolo-the-jackalope', 'cryptids', 41.133566, -104.82535, 'Cheyenne', 'WY', 'A painted eight-foot boot outside the WyoLotto office in Cheyenne, carrying Yolo — the lottery''s jackalope mascot, and a nod to Wyoming''s horned-rabbit folklore. Whether there is a standalone jackalope statue here is unconfirmed.', 'roadside', null, 'https://wyolotto.com/', null, null, null, null, 'node', 14090479377, 'America/Denver'),
  ('Airport Road Weeping Bride', 'airport-road-weeping-bride', 'folklore', 38.62485, -75.57055, 'Seaford', 'DE', 'A Seaford-area ghost story tells of a weeping bride and a Confederate soldier appearing along Airport Road, with some versions placing the encounter around Valentine’s Day. The tale is unverified local folklore and the road remains active, so travelers should never stop in traffic or enter private property while looking for the location.', 'roadside', null, 'https://www.hauntedplaces.org/item/airport-road/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Alderson Lion Historical Marker', 'alderson-lion-historical-marker', 'folklore', 37.72538, -80.64115, 'Alderson', 'WV', 'This marker preserves the bizarre local story of "French," a lion kept in Alderson between 1890 and 1894 after being adopted from a traveling circus. According to the marker, the lion was allowed to roam until it frightened a salesman into the Greenbrier River, prompting the town to require lions to be leashed.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/alderson-lion/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('All Saints Way', 'all-saints-way', 'folklore', 42.36634, -71.0525, 'Boston', 'MA', 'A narrow North End alley has been transformed by one resident into a dense devotional display of saint statues, holy cards, lights and Catholic imagery. The collection sits on private property but is often visible from the entrance; access depends on the owner''s availability.', 'limited', null, 'https://www.atlasobscura.com/places/all-saints-way', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Society of Dowsers Headquarters', 'american-society-of-dowsers-headquarters', 'folklore', 44.40934, -72.13748, 'Danville', 'VT', 'The American Society of Dowsers maintains its headquarters in Danville for practitioners of the centuries-old practice of using rods, pendulums and other methods to locate water or other hidden targets. The organization remains active in 2026, although the headquarters should be treated as a limited-access organizational stop rather than a walk-in museum.', 'limited', null, 'https://dowsers.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('America''s Stonehenge', 'americas-stonehenge', 'folklore', 42.84379, -71.20574, 'Salem', 'NH', 'Formerly known as Mystery Hill, this wooded property contains stone chambers, walls and standing stones that have inspired claims of ancient ceremonial builders and pre-Columbian European visitors. Those dramatic interpretations are disputed, and archaeologists have also connected much of the site to historic-era land use and later reconstruction. Whatever its origin, the maze of stone structures remains one of New Hampshire''s defining mystery attractions.', 'open', null, 'https://www.atlasobscura.com/places/americas-stonehenge', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.stonehengeusa.com/', null, null, null, 'America/New_York'),
  ('Ann Arbor Fairy Doors', 'ann-arbor-fairy-doors', 'folklore', 42.27856, -83.75019, 'Ann Arbor', 'MI', 'Tiny decorative doors began appearing around Ann Arbor after artist Jonathan B. Wright created miniature ''fairy'' entrances in the 1990s and early 2000s. Several public examples survive around downtown buildings and shops, creating a walkable scavenger hunt for miniature architecture.', 'open', null, 'https://www.atlasobscura.com/places/ann-arbor-s-fairy-doors', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Aquinnah Cliffs', 'aquinnah-cliffs', 'folklore', 41.34758, -70.8376, 'Aquinnah', 'MA', 'Multicolored clay cliffs rise above Martha''s Vineyard at a place sacred to the Wampanoag people and connected with stories of the giant Moshup. The cliffs are both a dramatic geological formation and an important Indigenous cultural landscape; removing clay is prohibited.', 'open', null, 'https://www.atlasobscura.com/places/aquinnah-cliffs', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Avon Haunted Bridge', 'avon-haunted-bridge', 'folklore', 39.7579, -86.41402, 'Avon', 'IN', 'The railroad bridge west of Indianapolis has accumulated several local ghost stories, most famously involving a mother and child and another tale about a worker supposedly entombed in the structure. The bridge remains an active railroad structure, so OddWay visitors should view it only from legal public areas around Washington Township Park and never walk on the tracks.', 'roadside', null, 'https://visitindiana.in.gov/blog/post/5-weird-wonderful-must-see-places-near-indy/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Axe Murder Hollow', 'axe-murder-hollow', 'folklore', 42.03042, -80.15298, 'Millcreek Township', 'PA', 'For generations, Erie-area teenagers called the woods off Thomas Road "Axe Murder Hollow," telling stories about an axe murderer and ghosts haunting the hollow. Erie Reader''s archival investigation found no evidence that the legendary family massacre occurred; much of the old hollow is now residential private property, so experience the location only from public roads and **do not enter the woods or neighboring property**.', 'private', null, 'https://www.eriereader.com/article/exhuming-the-hollow', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bartlesville Gravity Hill', 'bartlesville-gravity-hill', 'folklore', 36.668327, -95.988965, 'Bartlesville', 'OK', 'A stretch of Gap Road near the railway tracks where cars in neutral appear to climb. The legend blames children killed in a school bus crash, pushing vehicles clear of the rails. Someone took a level to it: the road runs downhill.', 'roadside', null, 'https://www.greencountryok.com/listing/gravity-hill/1608/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bash Bish Falls', 'bash-bish-falls', 'folklore', 42.11481, -73.4929, 'Mount Washington', 'MA', 'Massachusetts'' largest waterfall drops through a dramatic Berkshire gorge with a long history of fatal accidents and local legends. Current restrictions prohibit access to the plunge pool and lower area, so visitors must obey barriers and use designated overlooks.', 'limited', null, 'https://www.atlasobscura.com/places/bash-bish-falls', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Beale Street Hoodoo History & Folklife Museum', 'beale-street-hoodoo-history-folklife-museum', 'folklore', 35.13955, -90.05276, 'Memphis', 'TN', 'Located above A. Schwab on Beale Street, this museum explores hoodoo, folk belief, spiritual practices and the cultural history surrounding the district. It gives physical context to traditions often sensationalized elsewhere and should be visited during posted museum access.', 'limited', null, 'https://hoodoomuseum.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Beinecke Rare Book Library — Voynich Manuscript', 'beinecke-rare-book-library-voynich-manuscript', 'folklore', 41.31153, -72.92714, 'New Haven', 'CT', 'Yale''s extraordinary rare-book library is home to the Voynich Manuscript, the famously undeciphered illustrated codex whose strange script has resisted generations of researchers. The original manuscript is not normally on public display, but the library itself is open to visitors and keeps a facsimile available.', 'open', null, 'https://www.atlasobscura.com/places/beinecke-rare-book-manuscript-library', '2026-09-08T18:39:47.144889+00:00', null, 'https://beinecke.library.yale.edu/', null, null, null, 'America/New_York'),
  ('Bell Witch Cave', 'bell-witch-cave', 'folklore', 36.58997, -87.06068, 'Adams', 'TN', 'The Bell Witch legend centers on the Bell family and a mysterious entity reported around their Robertson County farm in the early 1800s. The privately operated cave and property turn one of America''s most famous supernatural legends into an actual ticketed destination.', 'limited', null, 'https://www.bellwitchcave.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Black Diamond Road Ghost Lights', 'black-diamond-road-ghost-lights', 'folklore', 39.34734, -75.62159, 'Smyrna', 'DE', 'Black Diamond Road has a local reputation for unexplained glowing lights and floating orbs after dark. One version of the legend attempts to connect them with a supposed old burial ground, but that explanation is not established fact. This is a public-road folklore pin only; do not enter neighboring private property.', 'roadside', null, 'https://www.hauntedplaces.org/item/black-diamond-road/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bloody Bride Bridge Legend — Highway 66', 'bloody-bride-bridge-legend-highway-66', 'folklore', 44.56094, -89.49938, 'Stevens Point', 'WI', 'Local legend says a bride died in a crash on Highway 66 near Jordan Park and still appears along the road, sometimes in mirrors or beside passing cars. The story is folklore rather than documented paranormal fact. Visitors should experience it only from lawful public areas and never stop in a dangerous traffic location.', 'roadside', null, 'https://www.stevenspointarea.com/blog/stories/post/spooky-stevens-point-area/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.stevenspointarea.com/', null, null, null, 'America/Chicago'),
  ('Blue Mist Road Trail', 'blue-mist-road-trail', 'folklore', 40.62551, -80.00662, 'Pine Township', 'PA', 'The closed section of Irwin Road through Irwin Run Conservation Area is better known as Blue Mist Road, a longstanding Pittsburgh-area urban-legend location associated with ghosts, strange lights and a blue-tinged mist. The old road is now primarily a walking and biking trail rather than a spooky drive; the usual route is about 3.8 miles out and back, and the more sensational stories remain folklore rather than established history.', 'limited', null, 'https://myhikes.org/trails/blue-mist-road-trail', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blue Sulphur Springs Pavilion', 'blue-sulphur-springs-pavilion', 'folklore', 37.82791, -80.63852, 'Blue Sulphur Springs', 'WV', 'This Greek Revival pavilion is the lone major survivor of a nineteenth-century resort built around a mineral spring once advertised for its healing properties. After extensive restoration, the pavilion was rededicated in 2023 and is now open to the public daily during posted daytime hours.', 'open', null, 'https://greenbrierhistorical.org/preservation/blue-sulphur-springs-pavillion/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bonneville Boulevard Gravity Hill', 'bonneville-boulevard-gravity-hill-salt-lake-city-ut', 'folklore', 40.78944, -111.87917, 'Salt Lake City', 'UT', 'Stop on Bonneville Boulevard, looping around Memory Grove, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Bonwell House — Fence-Rail Dog Legend', 'bonwell-house-fence-rail-dog-legend', 'folklore', 39.02306, -75.50944, 'Frederica', 'DE', 'The National Register documentation for the Bonwell House records a curious local legend about a huge red-eyed canine apparition called the Fence-Rail Dog because it was supposedly as long as a fence rail. The supernatural story is folklore, but its appearance in the historic documentation makes this an unusually well-preserved Delaware legend. The house is private property and should only be viewed from lawful public areas.', 'private', null, 'https://npgallery.nps.gov/GetAsset/d7b631ae-a119-4699-9d9e-fa31f1ffdd7e', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bunny Man Bridge', 'bunny-man-bridge', 'folklore', 38.78989, -77.36238, 'Clifton', 'VA', 'This narrow railroad overpass on Colchester Road became the center of Northern Virginia''s Bunny Man legend after reports of a man in a rabbit suit threatening people with an axe or hatchet circulated in 1970. The bridge remains an active public road, so view it while passing through or from a safe legal spot nearby and never stop inside the one-lane tunnel or trespass along the tracks.', 'roadside', null, 'https://www.fotospot.com/attractions/virginia/bunny-man-bridge', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Buzzard Roost', 'buzzard-roost', 'folklore', 41.21561, -81.70902, 'Hinckley Township', 'OH', 'Hinckley has celebrated the supposed annual return of turkey vultures every March since the 1950s, creating one of Ohio''s strangest recurring local traditions. Buzzard Roost in Hinckley Reservation is the public viewing area associated with the event, where Cleveland Metroparks continues to welcome visitors looking for the returning birds.', 'open', null, 'https://www.clevelandmetroparks.com/parks/visit/parks/hinckley-reservation/buzzard-roost', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cape Henlopen Corpse Light', 'cape-henlopen-corpse-light', 'folklore', 38.79536, -75.09189, 'Lewes', 'DE', 'Delaware folklore describes a mysterious offshore beam known as the Corpse Light, appearing near Cape Henlopen where no working lighthouse should be seen. State sources preserve the ghost story as part of Delaware’s maritime folklore. This pin uses the public Cape Henlopen Point area as the safest place to connect with the legend.', 'open', null, 'https://gic.delaware.gov/lighthouse-ghost-stories/', '2026-09-08T18:31:51.932734+00:00', null, 'https://destateparks.com/CapeHenlopen', null, null, null, 'America/New_York'),
  ('Casey Jones Home & Railroad Museum', 'casey-jones-home-railroad-museum', 'folklore', 35.66054, -88.85496, 'Jackson', 'TN', 'Engineer Casey Jones died in a 1900 train collision and was transformed into an American folk hero through song and storytelling. His preserved home and railroad museum turn the legend back into a specific person, place and fatal event.', 'open', null, 'https://caseyjones.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cat Rocks Treasure Marker', 'cat-rocks-treasure-marker', 'folklore', 41.2454, -74.28533, 'Southfields', 'NY', 'Local legend says Revolutionary War loyalist and outlaw Claudius Smith hid stolen valuables inside caves at nearby Cat Rocks before his capture and execution. Treasure hunters have searched for the supposed cache for generations, and a Legends & Lore marker along Route 17 records the story; do not leave public access areas to hunt for it.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/cat-rocks-treasure/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Catman’s Grave — Long Cemetery', 'catmans-grave-long-cemetery', 'folklore', 38.50966, -75.24516, 'Frankford', 'DE', 'Long Cemetery is tied to the Delaware legend of Catman, a former cemetery caretaker said to keep watch over the grounds after death. Versions of the ritual involve knocking three times and later having car trouble, but these are local ghost stories rather than verified events, and some older descriptions no longer match what visitors report at the site. Treat it as a cemetery first: visit only when permitted and do not disturb graves or structures.', 'limited', null, 'https://www.hauntedplaces.org/item/long-cemetery-catmans-grave/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cave-in-Rock', 'cave-in-rock', 'folklore', 37.46927, -88.1522, 'Cave-in-Rock', 'IL', 'A huge riverside limestone cave once served as a landmark and shelter along the Ohio River and became notorious in stories about frontier outlaws.', 'open', null, 'https://dnr.illinois.gov/parks/park.caveinrock.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cave of Kelpius', 'cave-of-kelpius', 'folklore', 40.0238, -75.2016, 'Philadelphia', 'PA', 'Tradition connects this stone-lined chamber in the Wissahickon to Johannes Kelpius and his seventeenth-century community of mystics, who believed the end of the world was imminent. Historians debate whether the structure was actually Kelpius''s cave or a later springhouse, but visitors can reach it on foot from the public park trails.', 'limited', null, 'https://www.atlasobscura.com/places/cave-of-kelpius', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chained Rock', 'chained-rock', 'folklore', 36.75384, -83.70176, 'Pineville', 'KY', 'Pineville folklore says residents chained an enormous boulder to Pine Mountain to keep it from rolling down and crushing the town. The chain was actually installed in the 1930s as a publicity stunt inspired by the legend, and visitors can hike to the rock from Pine Mountain State Resort Park.', 'open', null, 'https://www.atlasobscura.com/places/chained-rock', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Charles Island', 'charles-island', 'folklore', 41.1912, -73.055, 'Milford', 'CT', 'Charles Island is wrapped in stories of curses, buried treasure and an alleged Captain Kidd connection. At low tide a sandbar can appear to connect it with shore, but currents and rapidly changing tides make crossing dangerous, and seasonal wildlife closures prohibit access during nesting periods.', 'limited', null, 'https://www.atlasobscura.com/places/cursed-charles-island', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chicken Farmer Rock', 'chicken-farmer-rock', 'folklore', 43.29656, -71.99594, 'Newbury', 'NH', 'For decades, a roadside boulder has carried the hand-painted message "Chicken Farmer, I Still Love You." Local versions of the story connect it to a long-ago romance, but the exact origin has become part fact and part community folklore. The rock is visible from the road; visitors should not stop in traffic or enter private property for a photograph.', 'roadside', null, 'https://www.atlasobscura.com/places/chicken-farmer-rock', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Church of the Atonement Cemetery', 'church-of-the-atonement-cemetery', 'folklore', 38.73475, -76.82288, 'Brandywine', 'MD', 'A small cemetery and surviving steps are all that remain of the Church of the Atonement, built in the 19th century and demolished decades after services ended. The isolated burial ground has accumulated witch and ghost folklore over the years; access is awkward near the railroad, so use only legitimate approaches and never cross active tracks unsafely.', 'limited', null, 'https://www.atlasobscura.com/places/church-of-the-atonement-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Colonel Buck’s Cursed Tomb', 'colonel-bucks-cursed-tomb', 'folklore', 44.57119, -68.78435, 'Bucksport', 'ME', 'A strange boot- or foot-shaped stain marks the monument of Colonel Jonathan Buck, the founder for whom Bucksport was named. Local legend claims the mark is tied to a curse involving an executed witch, although the story is folklore rather than documented history.', 'limited', null, 'https://www.roadsideamerica.com/story/6159', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Copperton Gravity Hill', 'copperton-gravity-hill-copperton-ut', 'folklore', 40.56611, -112.089028, 'Copperton', 'UT', 'Stop on State Route 48, under the train bridge, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Cornwallis Cave', 'cornwallis-cave', 'folklore', 37.23503, -76.50513, 'Yorktown', 'VA', 'For generations, local tradition claimed British General Cornwallis used this riverside cave as his headquarters during the 1781 Siege of Yorktown. Historians have since rejected that story and identify the cave as a later ammunition-storage site, making the debunked legend itself part of the stop; the opening is gated and should not be entered.', 'open', null, 'https://www.nps.gov/york/learn/historyculture/cornwallis-cave.htm', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cumberland Falls Moonbow and Lover''s Leap', 'cumberland-falls-moonbow-and-lovers-leap', 'folklore', 36.83973, -84.34452, 'Corbin', 'KY', 'Cumberland Falls is one of the few places where visitors can regularly see a lunar rainbow, or moonbow, under the right full-moon conditions. The surrounding gorge also carries the Lover''s Leap ghost story of a bride said to have fallen to her death and later appeared in a white dress near the falls.', 'open', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, 'https://parks.ky.gov/explore/cumberland-falls-state-resort-park-7786', null, null, null, 'America/New_York'),
  ('Cursed Self-Rocking Cradle', 'cursed-self-rocking-cradle', 'folklore', 37.41382, -79.14416, 'Lynchburg', 'VA', 'According to an 1839 Lynchburg legend, this mahogany cradle repeatedly rocked with no one touching it and would begin moving when a local minister challenged the unseen force to rock it. The actual cradle resurfaced through descendants of its original owners and was donated to the Lynchburg Museum in 2021, where visitors can now see the artifact behind the story.', 'open', null, 'https://lynchburgmuseum.org/2021-10-1-the-early-family-rocking-cradle/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil Anse Hatfield Grave', 'devil-anse-hatfield-grave', 'folklore', 37.70447, -81.99245, 'Sarah Ann', 'WV', 'Hatfield clan patriarch Anderson “Devil Anse” Hatfield is buried in the family cemetery beneath a life-size marble statue imported from Italy. The cemetery is publicly visited as part of Hatfield-McCoy heritage tourism, but reaching the graves requires a steep climb and visitors should use care on the slope.', 'limited', null, 'https://www.hmdb.org/m.asp?Result=1&m=49912', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Backbone Marker', 'devils-backbone-marker', 'folklore', 39.6258, -84.6705, 'Camden', 'OH', 'This rocky cliff along Paint Creek has been called the Devil''s Backbone since at least 1877 and has accumulated stories involving Bigfoot, hidden mines, missing skunks and a supposed curse. A Legends & Lore marker now stands at Herbert & Patricia Wagers Memorial Park, where visitors can also use the public walking and hiking trails.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/devils-backbone/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Chair', 'devils-chair', 'folklore', 28.96495, -81.23597, 'Cassadaga', 'FL', 'Cemetery bench surrounded by local legends claiming the Devil visits those who sit there at midnight.', 'open', null, 'https://www.lakehelencemetery.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Foot Rock', 'devils-foot-rock', 'folklore', 41.60245, -71.4557, 'North Kingstown', 'RI', 'Three unusual impressions in this roadside rock have long been explained through local folklore as footprints left by the Devil. Versions of the story vary, but the marks turned an otherwise ordinary boulder into a persistent Rhode Island legend. View from a safe lawful roadside area and do not enter neighboring private property.', 'roadside', null, 'https://basementofthebizarre.com/2021/03/02/roadside-rhode-island-devils-foot-rock-north-kingstown-rhode-island/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil’s Footprint', 'devils-footprint', 'folklore', 44.3635, -69.8693, 'Manchester', 'ME', 'A large foot-shaped depression in a boulder beside the North Manchester Meeting House has long been explained through local stories involving the Devil. The stone sits near the cemetery and can be viewed without wandering onto unrelated private property.', 'roadside', null, 'https://www.roadsideamerica.com/tip/67410', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Hopyard State Park', 'devils-hopyard-state-park', 'folklore', 41.47621, -72.34119, 'East Haddam', 'CT', 'Chapman Falls tumbles over bedrock pocked with near-cylindrical holes. Early folklore claimed the Devil made those holes with his burning hooves after getting his tail wet, while geology explains them as potholes ground out by stones spinning in river eddies. The state park is open daily.', 'open', null, 'https://ctparks.com/parks/devils-hopyard-state-park', '2026-09-08T18:47:23.721893+00:00', null, 'https://ctparks.com/parks/devils-hopyard-state-park', null, null, null, 'America/New_York'),
  ('Devil’s Kitchen at Caesars Head', 'devils-kitchen-at-caesars-head', 'folklore', 35.10586, -82.62611, 'Cleveland', 'SC', 'A narrow passage splits a massive rock formation near the Caesars Head overlook. Local legend claims the Devil accidentally carved the opening after burning his dinner and angrily stomping on the rock, while geology offers a less supernatural explanation.', 'limited', null, 'https://www.atlasobscura.com/places/devils-kitchen-at-caesars-head', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Tower', 'devils-tower', 'folklore', 40.93381, -73.93322, 'Alpine', 'NJ', 'This stone tower was built in the early twentieth century as part of an estate near the Palisades. Local legend claims the ghost of the owner''s wife haunts the tower and that driving around it backward can summon her, but the structure is on private property and should only be viewed from the public road.', 'roadside', null, 'https://www.atlasobscura.com/places/devils-tower-alpine-new-jersey', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil’s Tramping Ground', 'devils-tramping-ground', 'folklore', 35.58432, -79.48702, 'Bear Creek', 'NC', 'A nearly circular patch of bare earth in the woods has carried a sinister reputation for generations. Folklore claims the Devil walks the circle at night and that objects placed inside may be moved or disturbed. The supernatural story is legend, but the strange clearing itself is a long-running North Carolina curiosity.', 'limited', null, 'https://www.visitnc.com/first-in-fright', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Tree', 'devils-tree', 'folklore', 40.63034, -74.58266, 'Bernards Township', 'NJ', 'A solitary oak in a public park has accumulated stories involving curses, unexplained warmth and supposed hangings. Historical evidence does not support many of the more sensational claims, but the tree remains one of New Jersey''s best-known pieces of local supernatural folklore.', 'open', null, 'https://www.atlasobscura.com/places/devils-tree', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devou Park Gravity Hill', 'devou-park-gravity-hill-covington-ky', 'folklore', 39.08583, -84.52944, 'Covington', 'KY', 'Stop on Devou Park, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dighton Rock Museum', 'dighton-rock-museum', 'folklore', 41.81288, -71.10643, 'Berkley', 'MA', 'A roughly 40-ton boulder covered with carved symbols has inspired competing theories involving Indigenous people, Norse explorers, Portuguese navigators and other proposed creators. The rock was removed from the riverbed and placed inside a small museum at Dighton Rock State Park for preservation.', 'limited', null, 'https://www.mass.gov/locations/dighton-rock-state-park', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Drowned Forest at Odiorne Point', 'drowned-forest-at-odiorne-point', 'folklore', 43.04529, -70.71411, 'Rye', 'NH', 'At sufficiently low tide, ancient tree stumps and root systems appear along the shore near Odiorne Point, remnants of a forest drowned as sea level changed thousands of years ago. The exposed wood creates the eerie impression of a forest floor emerging from the ocean. Visibility depends on tide and conditions, so this is not guaranteed on every visit. Secondary source: https://www.nhmagazine.com/explore-nhs-drowned-forest/', 'limited', null, 'https://www.atlasobscura.com/places/sunken-forests-rye-nh', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Druid''s Chair and Stone Circle', 'druids-chair-and-stone-circle', 'folklore', 41.42639, -71.46868, 'Narragansett', 'RI', 'Near Gibson Avenue Cemetery is a collection of stone features known as the Druid''s Chair, stone circle and, in some accounts, the "witches'' altar." Rhode Island cemetery records attribute the unusual landscaping to eccentric spiritualist Joseph Peace Hazard in the late nineteenth century rather than an ancient ritual site. The area can be overgrown and should be approached only through lawful cemetery access. Secondary source: https://www.roadsideamerica.com/tip/38961', 'limited', null, 'https://rihistoriccemeteries.org/newsearchcemeterydetail.aspx?ceme_no=NG003', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dummerston Vine', 'dummerston-vine', 'folklore', 42.93529, -72.57698, 'Dummerston', 'VT', 'A nineteenth-century legend blamed the deaths of several members of the Spaulding family on a cursed vine creeping through their cemetery plot. The story likely grew from tuberculosis deaths, but the row of family graves in Dummerston Center Cemetery remains the physical location connected with the tale.', 'open', null, 'https://www.atlasobscura.com/places/dummerston-vine', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dunn''s Bridge', 'dunns-bridge', 'folklore', 41.22015, -86.96897, 'Wheatfield', 'IN', 'This unusual steel bridge over the Kankakee River carries a persistent local story that some of its metal came from the original 1893 Chicago World''s Fair Ferris wheel. The bridge itself is real and historically significant, while the Ferris-wheel connection is best treated as legend rather than settled fact.', 'open', null, 'https://www.hmdb.org/m.asp?m=269431', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dyer Gravity Hill', 'dyer-gravity-hill-dyer-ar', 'folklore', 35.50139, -94.1476389, 'Dyer', 'AR', 'Stop on just outside Dyer, near Alma, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Edna Collins Covered Bridge', 'edna-collins-covered-bridge', 'folklore', 39.7275, -86.97633, 'Clinton Falls', 'IN', 'The 1922 Edna Collins Covered Bridge crosses Little Walnut Creek and carries one of Putnam County''s persistent ghost stories. Local legend tells of a girl named Edna who would wait for her parents to honk three times at the bridge and is now supposedly connected to unexplained sounds and sightings around the structure.', 'roadside', null, 'https://ourhistoricalindiana.blogspot.com/2020/11/edna-collings-bridge.html', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Elijah Bond''s Ouija Board Grave', 'elijah-bonds-ouija-board-grave', 'folklore', 39.31036, -76.60674, 'Baltimore', 'MD', 'Elijah Bond patented the talking board that would become the Ouija board in 1891. His grave in Green Mount Cemetery was unmarked for decades until researchers installed a new headstone in 2008 with a full Ouija board carved into its reverse side; visit only during cemetery hours.', 'open', null, 'https://elijahbond.com/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Esperance Witch Marker', 'esperance-witch-marker', 'folklore', 42.76087, -74.26119, 'Esperance', 'NY', 'Local legend tells of a widowed French woman accused of witchcraft by neighboring settlers during the nineteenth century. The story claims she was eventually shot through her window with a silver bullet and buried beneath a pine tree so she could not return, and a Legends & Lore marker now preserves the tale along Route 20.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/esperance-witch/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eunice "Goody" Cole Memorial Stone', 'eunice-goody-cole-memorial-stone', 'folklore', 42.93344, -70.83482, 'Hampton', 'NH', 'Eunice "Goody" Cole was repeatedly accused of witchcraft in seventeenth-century Hampton and became one of the best-known witchcraft figures in New Hampshire history. A memorial stone on the town green acknowledges the accusations and the strange local legends that continued long after her death. It is a concrete stop tied to one of the state''s strongest witch-lore stories.', 'open', null, 'https://www.atlasobscura.com/places/eunice-goody-cole-memorial-stone', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eunice Williams Covered Bridge', 'eunice-williams-covered-bridge', 'folklore', 42.64654, -72.62018, 'Greenfield', 'MA', 'A covered bridge crosses the Green River near the place where Eunice Williams was killed during the 1704 Deerfield raid. Local ghost lore claims her apparition still appears near the bridge, especially on moonless nights. The haunting is folklore layered onto a documented historical tragedy.', 'open', null, 'https://www.atlasobscura.com/places/eunice-williams-covered-bridge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Evangeline Oak', 'evangeline-oak', 'folklore', 30.12202, -91.82756, 'St. Martinville', 'LA', 'A live oak on Bayou Teche is traditionally identified with the meeting place of Evangeline and Gabriel from Longfellow-inspired local lore. The story is literary rather than documented history, but the tree remains a major Acadiana folklore landmark.', 'open', null, 'https://www.stmartinville.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Face in the Rock', 'face-in-the-rock', 'folklore', 46.4374, -86.81683, 'Au Train', 'MI', 'A weathered human face carved into the sandstone along Lake Superior has become one of the Upper Peninsula''s stranger shoreline landmarks. Local interpretation connects the carving with a nineteenth-century story involving a French voyageur and an Ojibwe leader, although the exact origin of the carving is not firmly documented; reaching it requires a shoreline walk.', 'limited', null, 'https://www.michigan.org/article/road-trip/one-tank-road-trip-central-upper-peninsula', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Fairy Stone State Park', 'fairy-stone-state-park', 'folklore', 36.78439, -80.09372, 'Stuart', 'VA', 'The park is famous for naturally occurring staurolite crystals shaped like crosses, which local legend says formed from the tears of fairies who learned of Christ''s crucifixion. Visitors can hike, camp and search designated areas for the distinctive stones while the state park interprets both the geology and folklore.', 'open', null, 'https://www.dcr.virginia.gov/state-parks/fairy-stone', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fell Family Cemetery', 'fell-family-cemetery', 'folklore', 39.282, -76.59452, 'Baltimore', 'MD', 'The family that gave Fell''s Point its name once had a burial ground here, now reduced to a tiny graveyard squeezed between later Baltimore buildings. Very little remains above ground, and uncertainty over what happened to some of the burials has helped make the small plot a recurring stop in neighborhood ghost lore.', 'open', null, 'https://www.atlasobscura.com/places/fells-family-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fiddler’s Bridge — Scott’s Run Legend', 'fiddlers-bridge-scotts-run-legend', 'folklore', 39.53572, -75.64882, 'St. Georges', 'DE', 'A Delaware legend recorded in the twentieth century tells of a local Black fiddler who drowned near Scott’s Run and whose music could supposedly be summoned by tossing a dime from the bridge. The original bridge associated with the story was already gone by the 1950s, so the present crossing is a geographic folklore marker rather than the historic structure itself. Do not stop on active highway lanes.', 'roadside', null, 'https://www.hauntedplaces.org/item/fiddlers-bridge/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Flying Moose Statue', 'flying-moose-statue', 'folklore', 45.66789, -69.74436, 'Rockwood', 'ME', 'A carved moose with large wings stands beside the road north of Rockwood, accompanied by a sign recounting a locally attributed Abenaki flying-moose legend. It is best treated as a roadside viewing stop without entering the nearby private property.', 'roadside', null, 'https://www.roadsideamerica.com/tip/638', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fook C. Kan Plaque', 'fook-c-kan-plaque', 'folklore', 42.3523, -71.0553, 'Boston', 'MA', 'A memorial plaque dedicated to carpenter Fook C. Kan contains puzzling errors and inconsistencies that have made its exact backstory difficult to untangle. The modest marker is a small urban mystery hidden in plain sight.', 'open', null, 'https://www.atlasobscura.com/places/fook-c-kan-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Footprints of the Archangel Gabriel', 'footprints-of-the-archangel-gabriel', 'folklore', 38.12996, -87.93482, 'New Harmony', 'IN', 'New Harmony tradition once claimed that the Archangel Gabriel visited communal leader George Rapp in 1819 and left footprints impressed into a limestone slab. The weathered slab still survives behind a brick wall near Church and Main Streets, but it is on private property and should only be viewed from the public sidewalk through or over the wall.', 'private', null, 'https://www.roadsideamerica.com/story/19391', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fountain of Youth Archaeological Park', 'fountain-of-youth-archaeological-park', 'folklore', 29.90865, -81.31513, 'St. Augustine', 'FL', 'Archaeological attraction intertwined with the enduring Ponce de León Fountain of Youth legend.', 'limited', null, 'https://www.fountainofyouthflorida.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Franklin Spring Marker', 'franklin-spring-marker', 'folklore', 43.00845, -73.8436, 'Ballston Spa', 'NY', 'In 1869, Spiritualist Samuel Hides said a séance message from the spirit of Benjamin Franklin told him exactly where to drill for a healing mineral spring. A spring was struck at the predicted depth, and the story became part of Ballston Spa folklore; a Legends & Lore marker now identifies the site.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/franklin-spring/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fred Clifton Park Overlook - Lover''s Leap', 'fred-clifton-park-overlook-lover-s-leap', 'folklore', 36.720258, -80.325434, 'Stuart', 'VA', 'A wooded mountaintop park at about 2,930 feet with several overlook platforms and picnic tables. It carries the same Lover''s Leap story as the Route 58 pull-off nearby, but this is the park viewpoint rather than the highway one — they are two distinct stops.', 'open', null, 'https://visitpatrickcounty.org/parks-and-trails/fred-clifton-park/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Freeman Gravity Hill', 'freeman-gravity-hill-freeman-mo', 'folklore', 38.57972, -94.5943889, 'Freeman', 'MO', 'Stop on Route D at East 299th Street, near the Kansas line, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Freetown-Fall River State Forest', 'freetown-fall-river-state-forest', 'folklore', 41.77992, -71.04228, 'Assonet', 'MA', 'This large state forest forms another major point in Bridgewater Triangle lore. Stories attached to the woods include Pukwudgies, phantom lights and other unexplained encounters, while the forest also has a documented history of serious crimes. The paranormal material should be presented as regional folklore rather than fact.', 'open', null, 'https://newenglandhistoricalsociety.com/the-pukwudgies-of-the-bridgewater-triangle/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.mass.gov/locations/freetown-fall-river-state-forest', null, null, null, 'America/New_York'),
  ('Gapland Road Gravity Hill', 'gapland-road-gravity-hill-burkittsville-md', 'folklore', 39.396861, -77.63444, 'Burkittsville', 'MD', 'Stop on Gapland Road, West Main Street, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Garden Creek Gravity Hill', 'garden-creek-gravity-hill-casper-wy', 'folklore', 42.773722, -106.3329722, 'Casper', 'WY', 'Stop on Garden Creek Road, near the Rotary Park entrance, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Gates of Hell', 'gates-of-hell', 'folklore', 40.01839, -83.01199, 'Columbus', 'OH', 'A large storm-drain tunnel beneath North High Street has acquired the nickname Gates of Hell and a collection of urban legends involving deaths, strange noises and supposedly supernatural encounters. The tunnel itself is drainage infrastructure and should not be entered; treat this as a view-from-public-ground folklore stop only.', 'roadside', null, 'https://www.atlasobscura.com/places/gates-of-hell', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ghost Lake on Shades of Death Road', 'ghost-lake-on-shades-of-death-road', 'folklore', 40.92532, -74.89997, 'Knowlton Township', 'NJ', 'This small lake beside the famously named Shades of Death Road developed its eerie name from mist that rises from the water on cool mornings. The surrounding road has accumulated decades of murder tales, ghost stories and supernatural folklore; visitors should use the designated state-forest parking area rather than stop in traffic.', 'roadside', null, 'https://www.nj.gov/dep/parksandforests/maps/jennyjump-trail.pdf', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Glenwood Cemetery — Witch of Yazoo Grave', 'glenwood-cemetery-witch-of-yazoo-grave', 'folklore', 32.85156, -90.40048, 'Yazoo City', 'MS', 'Glenwood Cemetery contains the grave associated with the "Witch of Yazoo" legend, a local tale later popularized in Willie Morris''s writing. The grave is real; the witch story is folklore, and visitors should treat the cemetery respectfully.', 'open', null, 'https://visitmississippi.org/trip-ideas/ghostly-adventures-in-mississippi/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gnome Village', 'gnome-village', 'folklore', 44.95643, -70.5659, 'Rangeley', 'ME', 'Tiny houses and more than twenty gnome figures are scattered through the woods along trails at the Rangeley Lakes Trails Center. The handmade village turns a normal forest walk into a small-scale folklore scavenger hunt.', 'limited', null, 'https://www.atlasobscura.com/places/gnome-village-maine', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('God’s Acre Healing Springs', 'gods-acre-healing-springs', 'folklore', 33.39197, -81.27346, 'Blackville', 'SC', 'Local tradition says wounded British soldiers recovered after drinking from these springs during the Revolutionary War, creating a long-lasting belief in the water’s healing properties. In 1944 the surrounding land was deeded to “God Almighty” so the spring would remain freely accessible to the public.', 'open', null, 'https://discoversouthcarolina.com/articles/history-and-culture-at-the-healing-springs-in-blackville', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Golden Gate Park Gravity Hill', 'golden-gate-park-gravity-hill-san-francisco-ca', 'folklore', 37.770426, -122.480647, 'San Francisco', 'CA', 'Stop on JFK Drive, where water from Rainbow Falls appears to run towards Lloyd Lake, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Gorton Turtle Marker', 'gorton-turtle-marker', 'folklore', 42.86158, -75.352, 'West Edmeston', 'NY', 'A Brookfield-area tall tale tells of a turtle larger than a cottage emerging from Gorton Lake and dragging an impossibly heavy wagon of rocks into the water. A Legends & Lore marker on Gorton Lake Road preserves the story at a specific roadside location.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/gorton-turtle/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Marie Rose Ferron', 'grave-of-marie-rose-ferron', 'folklore', 42.01708, -71.50365, 'Woonsocket', 'RI', 'Marie "Little Rose" Ferron was a Franco-American Catholic mystic whose followers reported stigmata, visions and extraordinary religious experiences during her life. Her grave in Precious Blood Cemetery remains a devotional destination, and the foundation dedicated to her records continuing reports of favors and cures attributed to her intercession. These are matters of religious belief rather than verified medical claims.', 'limited', null, 'https://www.littleroseferron.org/grave-site/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Mercy Brown', 'grave-of-mercy-brown', 'folklore', 41.58061, -71.5598, 'Exeter', 'RI', 'Mercy Brown became the center of Rhode Island''s best-known vampire panic after several members of her family died from tuberculosis in the late 1800s. In 1892, townspeople exhumed her body, removed and burned her heart and liver, and used the ashes in an attempted folk remedy for her sick brother. Her grave survives in Chestnut Hill Cemetery and remains one of New England''s most important vampire-lore sites.', 'limited', null, 'https://www.atlasobscura.com/places/grave-mercy-brown', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Midnight Mary', 'grave-of-midnight-mary', 'folklore', 41.29941, -72.94975, 'New Haven', 'CT', 'Mary E. Hart''s grave carries an ominous inscription that helped inspire one of New Haven''s best-known cemetery legends. Later stories claimed she was buried alive and now punishes anyone who visits after midnight, although the dramatic tale is folklore rather than documented history.', 'open', null, 'https://www.atlasobscura.com/places/grave-midnight-mary', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Ocean-Born Mary', 'grave-of-ocean-born-mary', 'folklore', 43.17532, -71.82204, 'Henniker', 'NH', 'Mary Wallace became known as "Ocean-Born Mary" because she was born aboard a ship crossing the Atlantic in 1720. Later storytellers transformed her life into tales involving pirates, hidden treasure and a supposedly haunted house, although much of that lore has been debunked. Her actual grave behind Henniker''s town hall gives travelers a concrete stop tied to the legend. Secondary source: https://newenglandhistoricalsociety.com/ocean-born-mary-new-hampshire-legend/', 'limited', null, 'https://www.atlasobscura.com/places/ocean-born-mary', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of the Female Stranger', 'grave-of-the-female-stranger', 'folklore', 38.79985, -77.05652, 'Alexandria', 'VA', 'A white marble table tomb in St. Paul''s Cemetery marks the grave of an unidentified 23-year-old woman who died in Alexandria in 1816. Her true identity remains unknown and later legends have connected her to figures such as Theodosia Burr Alston; the grave is the third on the right after entering the St. Paul''s section and should be visited respectfully during cemetery hours.', 'open', null, 'https://www.alexandriava.gov/index.php/historic-alexandria/womens-history-in-alexandria', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravity Hill', 'gravity-hill', 'folklore', 42.547073, -90.233213, 'Shullsburg', 'WI', 'A rural stretch of County Road U south of Shullsburg, just past Rennick Road, where a slight descent reads as a climb. A car in neutral appears to roll backwards uphill. The effect is well documented and entirely optical.', 'roadside', null, 'https://walworth.extension.wisc.edu/gravity-hill/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gravity Hill - Folklore Destination', 'gravity-hill-folklore-destination', 'folklore', 35.582997, -80.245116, 'Richfield', 'NC', 'A gravity hill on Richfield Road where a car left in neutral appears to roll uphill, because the surrounding land hides the road''s true slope. The local story credits the ghosts of a mother and child killed there, complete with handprints said to appear on cars.', 'roadside', null, 'https://www.wral.com/archive/14764496/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravity Hill Lane', 'gravity-hill-lane-oak-grove-al', 'folklore', 33.2036944, -86.30806, 'Oak Grove', 'AL', 'Stop on Gravity Hill Lane, in Talladega County, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gravity Hill', 'gravity-hill-new-paris', 'folklore', 39.9856, -78.6486, 'New Paris', 'PA', 'Put the car in neutral at the marked spot on Gravity Hill Road and it rolls, slowly, in the wrong direction. The surrounding hills hide the true horizon well enough that your eyes lose the argument with the road. Bring a bottle of water to pour out and watch. There are two such stretches in the area.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:56:28.154232+00:00', null, null, null, null, null, 'America/New_York'),
  ('Great Hill Cemetery — Hookman''s Cemetery', 'great-hill-cemetery-hookmans-cemetery', 'folklore', 41.38328, -73.11901, 'Seymour', 'CT', 'Great Hill Cemetery is better known in local ghost lore as Hookman''s Cemetery. The legend tells of a hook-handed caretaker whose spirit supposedly scraped the roofs of cars parked near a particular tree. The tale is folklore; the cemetery remains an active burial place and should be treated accordingly.', 'limited', null, 'https://www.hauntedplaces.org/item/great-hill-cemetery/', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Green Man''s Tunnel', 'green-mans-tunnel', 'folklore', 40.27259, -79.96914, 'South Park Township', 'PA', 'Western Pennsylvania''s Green Man legend grew from the real life of Raymond Robinson, a badly disfigured man whose nighttime walks inspired generations of frightening stories about a glowing figure called Charlie No-Face. The legend was later attached to this abandoned railroad tunnel even though Robinson did not live there; view the tunnel from the legal road or trail area and do not enter blocked infrastructure or storage areas.', 'roadside', null, 'https://www.atlasobscura.com/places/green-man-s-tunnel', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbrier Ghost Historical Marker', 'greenbrier-ghost-historical-marker', 'folklore', 37.98912, -80.413, 'Smoot', 'WV', 'This roadside marker commemorates the extraordinary 1897 Greenbrier Ghost case, in which Zona Heaster Shue''s mother claimed her daughter''s ghost revealed that Zona had been murdered. The resulting murder conviction made the story one of America''s most famous cases in which alleged supernatural testimony played a role in bringing attention to a crime.', 'roadside', null, 'https://wvencprod.wvnet.edu/entries/2107', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbrier Valley Theatre', 'greenbrier-valley-theatre', 'folklore', 37.80017, -80.44284, 'Lewisburg', 'WV', 'Greenbrier Valley Theatre keeps the Greenbrier Ghost story alive through performances and displays connected with the famous Zona Heaster Shue case. The theatre is an active arts venue, so interior access follows box-office and performance schedules rather than open exploration.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haeger''s Vision Marker', 'haegers-vision-marker', 'folklore', 42.14329, -73.88886, 'Germantown', 'NY', 'According to local tradition, Rev. Johann Frederick Haeger was visited on Christmas Eve 1720 by a spirit calling itself the "Master of Time and Space." The spirit supposedly showed him visions of Germantown''s future, and a Legends & Lore marker now identifies the location tied to the story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/haegers-vision/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hardscrabble Historical Marker', 'hardscrabble-historical-marker', 'folklore', 38.61954, -75.48352, 'Seaford', 'DE', 'The marker preserves the local story behind the community name Hardscrabble. The colorful origin tale belongs more to local folklore than fully proven history, which is why it works better as an OddWay story stop than as a conventional historic landmark.', 'roadside', null, 'https://archives.delaware.gov/delaware-historical-markers/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harry S. Thobe Ghost Marker', 'harry-s-thobe-ghost-marker', 'folklore', 39.50051, -84.74575, 'Oxford', 'OH', 'Harry Thobe was a stonemason and famous Miami University superfan who built the house at this location and maintained a stone fountain on campus until his death in 1950. Legend says that calling Thobe''s name near the former fountain site may produce an answering echo; the Legends & Lore marker is at his former Chestnut Street home, so view it from the public right-of-way and do not disturb the residence.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/harry-s-thobe/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harvard Divinity School Labyrinth', 'harvard-divinity-school-labyrinth', 'folklore', 42.38043, -71.11361, 'Cambridge', 'MA', 'A small Chartres-inspired labyrinth is laid into a quiet Harvard Divinity School courtyard. The many-turning path is meant for slow contemplative walking and creates a hidden meditative space within the university campus.', 'open', null, 'https://www.atlasobscura.com/places/harvard-divinity-school-labyrinth', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Headless Horseman Marker', 'headless-horseman-marker', 'folklore', 41.09097, -73.86119, 'Sleepy Hollow', 'NY', 'Sleepy Hollow Cemetery and the adjoining Old Dutch Church landscape are inseparable from Washington Irving''s The Legend of Sleepy Hollow. A Legends & Lore marker inside the cemetery specifically commemorates the story that the Headless Horseman tethers his horse among the graves.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/headless-horseman/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Helltown at Boston Mill', 'helltown-at-boston-mill', 'folklore', 41.26259, -81.56031, 'Boston Township', 'OH', 'Federal land purchases around the former village of Boston in the 1970s left vacant buildings that helped fuel later urban legends about "Helltown," including stories of satanic churches, chemical disasters and mutant creatures. Most of the sensational landmarks described in those stories are gone or were never what the legends claimed, so Boston Mill Visitor Center in Cuyahoga Valley National Park is the legal public anchor for the story and visitors should not trespass on closed structures or private land.', 'open', null, 'https://en.wikipedia.org/wiki/Helltown,_Ohio', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Henry''s Hill', 'henry-s-hill-mount-hope-al', 'folklore', 34.4300278, -87.5054444, 'Mount Hope', 'AL', 'Stop on Henry''s Hill, in Lawrence County, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hoodoo Marker', 'hoodoo-marker', 'folklore', 39.45928, -76.41388, 'Kingsville', 'MD', 'This rough boundary stone has stood beside Bel Air Road since the early 1800s and carries a biblical warning cursing anyone who moves a neighbor''s landmark. It sits beside private commercial property near the roadside, so view it without blocking traffic or treating the surrounding land as public.', 'roadside', null, 'https://www.roadsideamerica.com/tip/3345', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hopkins Hall Handprint', 'hopkins-hall-handprint', 'folklore', 40.00098, -83.0116, 'Columbus', 'OH', 'Ohio State folklore says an art student became trapped in a Hopkins Hall elevator overnight and left frantic handprints behind while trying to escape. Versions of the story claim a mysterious handprint still reappears on the exterior of the building; the site is on a public university campus, though visitors should not disrupt classes or enter closed spaces looking for it.', 'open', null, 'https://artsandsciences.osu.edu/news/campus-legends-horrors-and-lore', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('House of Many Crosses — Harrison Mayes', 'house-of-many-crosses-harrison-mayes', 'folklore', 36.60508, -83.71966, 'Middlesboro', 'KY', 'Coal miner and self-taught folk artist Henry Harrison Mayes spent decades creating concrete crosses, hearts and religious messages that he distributed across America and envisioned sending around the world. He also constructed his Middlesboro home itself in the shape of a cross; it remains a private residence, with surviving original crosses visible from the public street.', 'private', null, 'https://folk-visions.com/marker/middlesboro-ky-house-of-many-crosses/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hubbard Park — Black Dog Legend', 'hubbard-park-black-dog-legend', 'folklore', 41.54959, -72.83563, 'Meriden', 'CT', 'The Hanging Hills around Hubbard Park are home to the legend of a small black dog whose appearances supposedly grow increasingly ominous: seeing it once brings joy, twice brings sorrow and a third sighting foretells death. The story is folklore, but it has been repeated for generations.', 'open', null, 'https://www.atlasobscura.com/places/hubbard-park', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.meridenct.gov/parks-and-recreation/parks/hubbard-park/', null, null, null, 'America/New_York'),
  ('Huey Cooper Lucky Rabbit''s Foot Statue', 'huey-cooper-lucky-rabbits-foot-statue', 'folklore', 33.87287, -79.75429, 'Lake City', 'SC', 'A bronze statue preserves the memory of Huey Cooper, a beloved Lake City character remembered for sitting at the corner of Acline and Main and letting passersby rub his lucky rabbit''s foot for a nickel. Sculptor Alex Palkovich installed the figure in 2014 at Cooper''s old corner. The statue still holds out the rabbit''s foot and even includes a slot in its pocket so visitors can continue the nickel tradition. Secondary source: https://saintteresacoe.org/tour/huey-cooper-statue/', 'open', null, 'https://www.visitlakecitysc.com/public-art/huey-cooper', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Huntress Hall', 'huntress-hall', 'folklore', 42.92722, -72.27929, 'Keene', 'NH', 'Keene State College students have long passed around stories of wheelchair sounds and other unexplained activity inside Huntress Hall, often attributing them to Harriet Huntress. Historical timelines complicate the legend because Huntress died before the residence hall opened, making this a good example of campus folklore evolving independently of fact. The hall is an active residence, so OddWay visitors should view it only from public campus areas.', 'roadside', null, 'https://spookfinder.com/place/huntress-hall', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Inez Clarke Memorial', 'inez-clarke-memorial', 'folklore', 41.95789, -87.66197, 'Chicago', 'IL', 'This life-sized statue of a young girl in Graceland Cemetery inspired persistent stories that the figure vanishes during thunderstorms.', 'limited', null, 'https://www.gracelandcemetery.org/tour-map-biographies/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jacksonboro Light', 'jacksonboro-light', 'folklore', 32.80321, -80.40098, 'Near Hollywood / Jacksonboro', 'SC', 'Lowcountry legend says a lantern-like light appears along Parkers Ferry Road, carried by the ghost of a preacher eternally searching for his missing daughter after he was killed by a train. Stories sometimes add the sound of a phantom train whistle to the moving light. This is a folklore route point only: remain on public roads, never enter railroad property and never stop where doing so would be unsafe or illegal.', 'roadside', null, 'https://www.hauntedplaces.org/item/jacksonboro-light/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jacob Conklin Pirate Legend Marker', 'jacob-conklin-pirate-legend-marker', 'folklore', 40.75868, -73.38299, 'Wheatley Heights', 'NY', 'Long Island legend says Jacob Conklin sailed with Captain William Kidd before building a home in this area around 1710. The house burned in 1918, but a Legends & Lore marker on Colonial Springs Road preserves the local pirate connection.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/jacob-conklin/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jennings Hall — Hill House Inspiration', 'jennings-hall-hill-house-inspiration', 'folklore', 42.92037, -73.23583, 'North Bennington', 'VT', 'This secluded stone mansion on the Bennington College campus is often identified as a possible visual inspiration for Shirley Jackson''s The Haunting of Hill House. The connection is literary lore rather than proven fact, but Jackson lived in North Bennington and the building''s isolated setting closely fits the association.', 'limited', null, 'https://www.atlasobscura.com/places/jennings-hall', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jewett City Vampires', 'jewett-city-vampires', 'folklore', 41.60638, -71.98696, 'Griswold', 'CT', 'After tuberculosis killed multiple members of the Ray family, frightened relatives exhumed corpses in the 1850s and burned remains in an attempt to stop what they believed was a vampire-like curse. The episode belongs to a documented New England tradition in which disease was blamed on the restless dead.', 'open', null, 'https://www.atlasobscura.com/places/jewett-city-vampires', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Joe Road Gravity Hill', 'joe-road-gravity-hill-stockbridge-wi', 'folklore', 44.02806, -88.3071389, 'Stockbridge', 'WI', 'Stop on Joe Road, south of Stockbridge off WIS 55, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('John Henry Historical Park', 'john-henry-historical-park', 'folklore', 37.64958, -80.76673, 'Talcott', 'WV', 'The park commemorates the legendary steel-driving man John Henry and the story of his race against a steam drill during construction of the nearby Big Bend Tunnel. Visitors now find a large John Henry statue, interpretive displays and walking areas at the location traditionally associated with the legend.', 'open', null, 'https://www.johnhenrypark.com/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Oliver Memorial Sewer Plant', 'john-oliver-memorial-sewer-plant', 'folklore', 41.4033, -73.42287, 'Danbury', 'CT', 'After comedian John Oliver mocked Danbury on television, the mayor jokingly threatened to name the city''s sewage plant after him — and the city ultimately followed through. A sign now officially identifies the John Oliver Memorial Sewer Plant, turning a municipal facility into a comedy landmark.', 'roadside', null, 'https://www.roadsideamerica.com/tip/71591', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Quincy Adams Summer Home Legend Marker', 'john-quincy-adams-summer-home-legend-marker', 'folklore', 40.76154, -73.33565, 'Deer Park', 'NY', 'For decades, local stories claimed President John Quincy Adams once owned a summer home in Deer Park. Research instead traced the property to a different John Quincy Adams, a clergyman who owned land here in the nineteenth century, and a Legends & Lore marker now explains how the presidential connection became local folklore.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/john-quincy-adams/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Johnny Appleseed Grave', 'johnny-appleseed-grave', 'folklore', 41.11223, -85.12244, 'Fort Wayne', 'IN', 'John Chapman, better known as Johnny Appleseed, died near Fort Wayne in 1845 after decades of planting and tending orchards across the frontier. A prominent memorial in Johnny Appleseed Park marks the burial place traditionally accepted as his grave, giving the American folk figure a real public destination.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-johnny-appleseed', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Judaculla Rock', 'judaculla-rock', 'folklore', 35.30093, -83.10986, 'Cullowhee', 'NC', 'This large soapstone boulder is covered with hundreds of ancient petroglyphs and is one of the most significant Native American rock-art sites in the Southeast. Cherokee tradition connects the stone with Judaculla, a powerful giant or supernatural being whose name is associated with the landscape.', 'open', null, 'https://www.visitnc.com/itinerary/uncover-mountain-mysteries-north-carolinas-haunted-trail', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Judgement Street Gravity Hill', 'judgement-street-gravity-hill-shullsburg-wi', 'folklore', 42.5475, -90.23333, 'Shullsburg', 'WI', 'Stop on Judgement Street, just past Rennick Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kagel Canyon Gravity Hill', 'kagel-canyon-gravity-hill-sylmar-ca', 'folklore', 34.3045833, -118.3755, 'Sylmar', 'CA', 'Stop on Kagel Canyon Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Kathryn Tucker Windham Museum', 'kathryn-tucker-windham-museum', 'folklore', 31.88889, -87.74466, 'Thomasville', 'AL', 'This small museum honors Alabama storyteller and journalist Kathryn Tucker Windham, whose books and performances preserved ghost stories and regional folklore across the state. Photographs, writings and personal material connect directly to the woman behind many Alabama supernatural tales.', 'limited', null, 'https://www.ruralswalabama.org/attraction/kathryn-tucker-windham-museum/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kau-Qua-Tau Witch Legend Marker', 'kau-qua-tau-witch-legend-marker', 'folklore', 42.83366, -78.74749, 'West Seneca', 'NY', 'A Legends & Lore marker at Ebenezer Cemetery preserves the story of Kau-Qua-Tau, a Seneca woman accused of witchcraft in 1821 and killed after fleeing the accusation. Later folklore blamed her spirit for disturbances in a cabin that once stood at the site.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/kau-qua-tau/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kindred Spirit Mailbox', 'kindred-spirit-mailbox', 'folklore', 33.86778, -78.53059, 'Sunset Beach', 'NC', 'A lone mailbox in the dunes of Bird Island has collected anonymous letters, confessions, wishes, and personal stories from visitors for decades. Reaching it requires a walk along the beach, and the notebooks inside have become a communal archive of strangers’ thoughts. Local information: https://www.sunsetbeachnc.gov/', 'limited', null, 'https://www.atlasobscura.com/places/kindred-spirit-mailbox', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Memorial Gravity Hill', 'king-memorial-gravity-hill-kirtland-hills-oh', 'folklore', 41.64125, -81.2956389, 'Kirtland Hills', 'OH', 'Stop on King Memorial Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Philip''s Cave', 'king-philips-cave', 'folklore', 41.98045, -71.13037, 'Norton', 'MA', 'A secluded rock shelter is traditionally associated with Metacomet, the Wampanoag leader known to English colonists as King Philip, during the final weeks of King Philip''s War. Modern ghost stories have added phantom drums, voices and lights to the location''s much more serious historical significance.', 'limited', null, 'https://www.atlasobscura.com/places/king-philips-cave', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kinstone Megalithic Garden', 'kinstone-megalithic-garden', 'folklore', 44.13144, -91.69977, 'Fountain City', 'WI', 'Modern standing stones, stone circles, earthworks, a labyrinth and other monumental landscape features occupy this private garden overlooking the Mississippi River region. The structures are contemporary rather than ancient, but intentionally evoke prehistoric ceremonial landscapes.', 'limited', null, 'https://www.kinstonecircle.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.kinstonecircle.com/', null, null, null, 'America/Chicago'),
  ('Kuwohi — Home of the Chief of All Bears', 'kuwohi-home-of-the-chief-of-all-bears', 'folklore', 35.56293, -83.49845, 'Bryson City', 'NC', 'At 6,644 feet, Kuwohi is the highest point in Great Smoky Mountains National Park and carries deep Cherokee cultural significance. Cherokee tradition associates the mountain with White Bear, chief of all bears, and with a sacred place where bears could heal; the former name Clingmans Dome was officially changed back to Kuwohi in 2024.', 'limited', null, 'https://www.atlasobscura.com/places/kuwohi-clingmans-dome', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lafitte''s Blacksmith Shop Bar', 'lafittes-blacksmith-shop-bar', 'folklore', 29.96074, -90.06389, 'New Orleans', 'LA', 'This eighteenth-century Creole cottage is wrapped in legends linking it to pirate and smuggler Jean Lafitte. The exact extent of Lafitte''s connection is debated, but the surviving building is one of Bourbon Street''s oldest and most atmospheric landmarks.', 'open', null, 'https://www.lafittesblacksmithshop.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lake Chargoggagoggmanchauggagoggchaubunagungamaugg', 'lake-chargoggagoggmanchauggagoggchaubunagungamaugg', 'folklore', 42.0409, -71.8438, 'Webster', 'MA', 'Webster Lake is famous for an extraordinarily long alternate name that has become a Massachusetts roadside and linguistic curiosity. The famous spelling is modern and its supposed translation is often repeated inaccurately, but the giant name itself has become the attraction.', 'open', null, 'https://www.atlasobscura.com/places/lake-chargoggagoggmanchauggagoggchaubunagungamaugg', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Drummond and the Phantom Lovers', 'lake-drummond-and-the-phantom-lovers', 'folklore', 36.60283, -76.46974, 'Chesapeake', 'VA', 'Lake Drummond lies deep within the Great Dismal Swamp and has inspired generations of supernatural stories, most famously the Phantom Lovers tale of a young man searching the lake for his dead bride. Reaching the lake requires using refuge roads, trails or waterways rather than a normal roadside pull-off, and access can vary with refuge conditions.', 'limited', null, 'https://www.fws.gov/refuge/great-dismal-swamp', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Winnipesaukee Mystery Stone', 'lake-winnipesaukee-mystery-stone', 'folklore', 43.20727, -71.53943, 'Concord', 'NH', 'This polished, egg-shaped stone was reportedly found near Lake Winnipesaukee in 1872 and is carved with a face, geometric designs and other symbols. Its maker and purpose have inspired more than a century of theories, though the precisely drilled holes have led some researchers to suspect a nineteenth-century origin rather than an ancient artifact. The stone is preserved by the New Hampshire Historical Society in Concord.', 'limited', null, 'https://www.atlasobscura.com/places/lake-winnipesaukee-mystery-stone', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.nhhistory.org/', null, null, null, 'America/New_York'),
  ('Laura Plantation', 'laura-plantation', 'folklore', 30.00813, -90.72533, 'Vacherie', 'LA', 'Laura preserves a Creole plantation complex and tells the intertwined histories of the Duparc-Locoul family and the people they enslaved. Folktales recorded from the region also contributed to later published Br''er Rabbit traditions.', 'limited', null, 'https://www.lauraplantation.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Learned Pond — Captain Kidd Treasure Legend', 'learned-pond-captain-kidd-treasure-legend', 'folklore', 42.28705, -71.41864, 'Framingham', 'MA', 'Local legend claims pirate William Kidd buried treasure around this otherwise ordinary pond. Historical evidence for Kidd visiting the spot is weak, though another pirate connected with him had regional ties, leaving a durable Massachusetts treasure story.', 'open', null, 'https://www.atlasobscura.com/places/learned-pond-farmingham-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Legend of Jenny Jump', 'legend-of-jenny-jump', 'folklore', 40.900861, -74.956664, 'Hope Township', 'NJ', 'The Jenny Jump legend as told inside Land of Make Believe, where an old house tied to the story is preserved. Around 1748 a nine-year-old girl was cornered on a rocky height and her father shouted "Jump, Jenny, jump". Note this is inside the ticketed park, not at Jenny Jump State Forest.', 'limited', null, 'https://www.lomb.com/group-trips/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Legend of June Lake Slot Machines', 'legend-of-june-lake-slot-machines', 'folklore', 37.799244, -119.06356, 'Mammoth Lakes', 'CA', 'A roadside marker shaped like a slot machine, complete with handle and reels, telling the story that June Lake''s illegal 1930s machines were dumped in the lake ahead of a state revenue raid. Installed around 2010. Divers have looked more than once and found nothing.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=37585', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Legend of Ondessonk', 'legend-of-ondessonk', 'folklore', 37.517881, -88.754435, 'Vienna', 'IL', 'A memorial inside Camp Ondessonk, the southern Illinois Catholic youth camp founded in 1959 and named for the Huron name given to St Isaac Jogues, meaning bird of prey. Not an open roadside stop: the camp admits day hikers from mid-August to mid-May during set hours and closes the grounds entirely in summer.', 'limited', null, 'https://www.ondessonk.com/camping-hiking/hiking-biking/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Legend of the Moon', 'legend-of-the-moon', 'folklore', 47.663388, -122.121976, 'Redmond', 'WA', 'A monumental cedar carving by Dudley Carter, made in 1977 from a 35-foot, six-ton section of old-growth cedar, interpreting a Coast Salish story of Moon the Transformer. Permanently installed near the entrance to Marymoor Park.', 'open', null, 'https://www.4culture.org/public_art/legend-of-the-moon/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Lewes Fountain of Youth', 'lewes-fountain-of-youth', 'folklore', 38.7815, -75.15342, 'Lewes', 'DE', 'A small stone well marks a spring that local tradition connected to a 1631 Dutch expedition and later dubbed the Fountain of Youth. The legend is the attraction here, not the water: modern visitors should treat the spring as a historic curiosity rather than a drinking source.', 'open', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lichau Road Gravity Hill', 'lichau-road-gravity-hill-rohnert-park-ca', 'folklore', 38.342361, -122.62028, 'Rohnert Park', 'CA', 'Stop on Lichau Road, on the western slope of Sonoma Mountain, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Loma Alta Gravity Hill', 'loma-alta-gravity-hill-altadena-ca', 'folklore', 34.2000278, -118.1218333, 'Altadena', 'CA', 'Stop on East Loma Alta Drive, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Longfellow-Evangeline State Historic Site', 'longfellow-evangeline-state-historic-site', 'folklore', 30.13554, -91.82263, 'St. Martinville', 'LA', 'This state site connects Acadian history with the literary legend of Evangeline popularized by Henry Wadsworth Longfellow. The grounds include a Creole plantation house and exhibits separating history from romanticized folklore.', 'open', null, 'https://www.lastateparks.com/historic-sites/longfellow-evangeline-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lost Children of the Alleghenies Monument', 'lost-children-of-the-alleghenies-monument', 'folklore', 40.29476, -78.60351, 'Pavia', 'PA', 'Brothers George and Joseph Cox disappeared from their Bedford County home in 1856 and were found dead in the mountains after a massive search, a tragedy later surrounded by stories of a local man''s prophetic dreams helping locate them. A stone memorial now stands near the place they were found, reached by a rough seasonal dirt road and a short walk into State Game Lands 26.', 'limited', null, 'https://pabucketlist.com/visiting-the-lost-children-of-the-alleghenies-monument-in-bedford-county/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lova''s Dollhouse Grave', 'lovas-dollhouse-grave', 'folklore', 39.63843, -85.56499, 'Arlington', 'IN', 'The grave of young Lova Cline is marked by an elaborate miniature house built by her family rather than a conventional headstone. Local stories later attached eerie details to the little structure, including claims that objects inside change position, making it one of Indiana''s better-known unusual cemetery monuments.', 'open', null, 'https://www.roadsideamerica.com/story/59389', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Lover''s Leap', 'lover-s-leap', 'folklore', 34.684831, -94.363664, 'Mena', 'AR', 'A hiking destination at the end of the 1.5-mile Lover''s Leap Trail in Queen Wilhelmina State Park, on Rich Mountain in the Ouachitas. The park still uses the trail for guided nature and history walks.', 'open', null, 'https://www.arkansasstateparks.com/trails/lovers-leap-trail', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lover''s Leap Lookout', 'lover-s-leap-lookout', 'folklore', 38.119628, -81.118475, 'Ansted', 'WV', 'A rocky overlook above the New River and marina at Hawks Nest State Park, normally reached by a short trail from behind the lodge. The local telling has a couple from opposing groups, forbidden to marry, leaping together. West Virginia State Parks currently lists the Lovers Leap trail as closed after extensive storm damage — check before you go, because the overlook is only reachable by that trail.', 'closed', null, 'https://wvstateparks.com/park/hawks-nest-state-park/', null, null, null, null, null, null, 'America/New_York'),
  ('Lover''s Leap Overlook', 'lover-s-leap-overlook', 'folklore', 36.701944, -82.743131, 'Duffield', 'VA', 'A viewpoint on the Lover''s Leap Trail at Natural Tunnel State Park, looking down toward the limestone tunnel and gorge. Just under a mile round trip with paved sections and stairs. The park opens daily from 8am to dusk.', 'open', null, 'https://www.dcr.virginia.gov/state-parks/natural-tunnel', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lover''s Leap Wayside', 'lover-s-leap-wayside', 'folklore', 36.717625, -80.323185, 'Stuart', 'VA', 'A roadside viewpoint on the US 58 mountain crossing in Patrick County, with a stone wall and long views over the Blue Ridge foothills. The name attaches to the local Morning Flower legend. Route 58 construction is still affecting the area in 2026, with access currently routed via Poor Farmers Farm Road.', 'roadside', null, 'https://visitpatrickcounty.org/attractions/lovers-leap/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lovers Leap', 'lovers-leap', 'folklore', 36.424372, -105.002916, 'Cimarron', 'NM', 'Lovers Leap is a cliff at roughly 7,300 feet on Philmont Scout Ranch, looking out over the backcountry and the Tooth of Time. Philmont runs a three-mile round trip to it, but this is ranch property rather than an open viewpoint, so arrange access rather than turning up.', 'limited', null, 'https://philmontscoutranch.org/ptc/activity-descriptions/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Denver'),
  ('Lovers Leap Overlook', 'lovers-leap-overlook', 'folklore', 37.281638, -82.288051, 'Breaks', 'VA', 'A Route 80 overlook beside Breaks Interstate Park, looking into the Russell Fork gorge toward the Towers. The legend here has two lovers from warring groups jumping from the rim rather than be separated. It sits outside the park gate, a very short walk from roadside parking.', 'roadside', null, 'https://byway.world/lookouts/lovers-leap-overlook-7e9c2886', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Machimoodus State Park — Moodus Noises', 'machimoodus-state-park-moodus-noises', 'folklore', 41.50236, -72.47731, 'Moodus', 'CT', 'For generations the area was famous for mysterious subterranean booms and rumblings remembered in Indigenous traditions and later colonial folklore. Geologists eventually linked the ''Moodus Noises'' to shallow microearthquakes, giving the park a rare combination of genuine geology and centuries of strange stories.', 'open', null, 'https://ctparks.com/parks/machimoodus-state-park', '2026-09-08T18:39:47.144889+00:00', null, 'https://ctparks.com/parks/machimoodus-state-park', null, null, null, 'America/New_York'),
  ('Maggie''s Bridge', 'maggies-bridge', 'folklore', 38.59391, -75.66612, 'Seaford', 'DE', 'Woodland Church Road''s small bridge is the center of one of Delaware''s best-known local ghost legends. Versions vary, but the ritual usually involves calling out to "Maggie" and claiming to have her baby; it should be treated strictly as roadside folklore, with no stopping in traffic or trespassing.', 'roadside', null, 'https://www.onlyinyourstate.com/delaware/maggies-bridge-de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Manchester Vampire Marker', 'manchester-vampire-marker', 'folklore', 43.17706, -73.0505, 'Manchester Center', 'VT', 'A historical marker near Factory Point Cemetery records the story of Rachel Harris Burton, whose body was reportedly exhumed and burned around 1792 after townspeople feared she had become a vampire. The episode belongs to the documented New England vampire panic surrounding tuberculosis and other unexplained illness.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/manchester-vampire/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marie Laveau Tomb — St. Louis Cemetery No. 1', 'marie-laveau-tomb-st-louis-cemetery-no-1', 'folklore', 29.95908, -90.07139, 'New Orleans', 'LA', 'The Glapion family tomb is widely associated with Marie Laveau and has become one of the most visited graves in New Orleans. It lies inside St. Louis Cemetery No. 1, so access is only through the cemetery''s authorized visitor system.', 'limited', null, 'https://nolacatholiccemeteries.org/st-louis-cemetery-1', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Marie Laveau''s House of Voodoo', 'marie-laveaus-house-of-voodoo', 'folklore', 29.95824, -90.06575, 'New Orleans', 'LA', 'This Bourbon Street shop and spiritual center is named for New Orleans Voodoo figure Marie Laveau and includes altars, spiritual supplies and Voodoo-related material. Readings and spiritual services may be available separately from normal shop access.', 'open', null, 'https://marielaveauvoodoo.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Merchant Ball', 'merchant-ball', 'folklore', 40.57664, -83.12201, 'Marion', 'OH', 'The Merchant family grave at Marion Cemetery is topped by a roughly 5,200-pound granite sphere that has slowly rotated on its pedestal over the decades. No definitive supernatural explanation is needed for the movement, but the visibly shifting stone has become a longstanding cemetery mystery; visit respectfully during cemetery hours.', 'open', null, 'https://www.atlasobscura.com/places/merchant-ball', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mile Marker No. 30', 'mile-marker-no-30', 'folklore', 41.155, -72.24116, 'Cutchogue', 'NY', 'Long Island tradition claimed Benjamin Franklin personally placed this stone mileage marker while serving as colonial postmaster in the 1750s. Later research indicates the marker was probably installed in the early nineteenth century, but the Franklin story endured for generations and is now explained by a Legends & Lore marker beside Route 25.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/mile-marker-30/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Misty of Chincoteague Statue', 'misty-of-chincoteague-statue', 'folklore', 37.93425, -75.37678, 'Chincoteague', 'VA', 'Marguerite Henry''s 1947 book Misty of Chincoteague turned the island''s pony culture and the real mare Misty into an enduring American children''s legend. A bronze Misty statue donated in 2006 stands along Main Street, giving visitors a physical stop connected to both the famous book and Chincoteague''s pony tradition.', 'open', null, 'https://www.hmdb.org/m.asp?m=181179', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mobile Carnival Museum', 'mobile-carnival-museum', 'folklore', 30.68844, -88.04527, 'Mobile', 'AL', 'Mobile’s museum of Carnival preserves elaborate royal costumes, floats, masks and material from the city’s long Mardi Gras tradition. Exhibits emphasize the secret societies, pageantry and ritual structure behind one of America’s oldest Carnival cultures.', 'open', null, 'https://www.mobilecarnivalmuseum.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Moll Dyer Rock', 'moll-dyer-rock', 'folklore', 38.28947, -76.63594, 'Leonardtown', 'MD', 'Local legend says Moll Dyer was driven from her home on a freezing night in the late 1600s after townspeople accused her of witchcraft, and that her frozen body was later found against a large rock. The stone associated with the story was moved in 2021 to Tudor Hall, where it is displayed outside the St. Mary''s County Historical Society.', 'open', null, 'https://www.stmaryshistory.org/content.aspx?club_id=706426&module_id=487754&page_id=22', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Money Diggers Marker', 'money-diggers-marker', 'folklore', 43.18124, -76.83584, 'North Rose', 'NY', 'During the 1830s, spirit mediums supposedly led groups into this area to dig for buried gold and jewels revealed by supernatural guidance. The legend held that everyone had to remain completely silent while digging or evil spirits would appear and the treasure would vanish; a marker now stands near Galen and Lasher roads.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/money-diggers/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moon-Eyed People Effigy', 'moon-eyed-people-effigy', 'folklore', 35.08674, -84.03294, 'Murphy', 'NC', 'The Cherokee County Historical Museum displays a small ancient soapstone figure popularly linked to the legend of the Moon-Eyed People, a mysterious group said in later folklore to have lived in the Appalachian region before Cherokee settlement. The artifact is real; its connection to the legendary people is speculative. Museum: https://www.cherokeecounty-nc.gov/183/Historical-Museum', 'limited', null, 'https://www.roadsideamerica.com/story/51476', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mooresville Gravity Hill', 'mooresville-gravity-hill-mooresville-in', 'folklore', 39.601306, -86.411, 'Mooresville', 'IN', 'Stop on Gravity Hill, outside Mooresville, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Moose Lodge Gravity Hill', 'moose-lodge-gravity-hill-bartlesville-ok', 'folklore', 36.670139, -95.98139, 'Bartlesville', 'OK', 'Stop on Moose Lodge Road, near the railway crossing, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mordington — Tom’s Daughter Ghost Legend', 'mordington-toms-daughter-ghost-legend', 'folklore', 38.96861, -75.49417, 'Frederica', 'DE', 'Mordington is tied to a grim local story about an enslaved girl remembered in folklore as Tom’s daughter, whose spirit was later said to haunt the property. Delaware archival materials preserve the story as part of the site’s local tradition. The historic house is private, so OddWay routing should keep visitors to public roads only.', 'private', null, 'https://archivesfiles.delaware.gov/markers/pdfs/kc-114-09.pdf', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moulton Mansion', 'moulton-mansion', 'folklore', 42.93277, -70.8401, 'Hampton', 'NH', 'The old Moulton property is connected to one of Hampton''s most enduring legends: General Jonathan Moulton supposedly promised the Devil his soul in exchange for having his boots filled with gold, then tried to cheat the bargain by cutting holes in the boots. Later versions of the tale add a mysterious fire and the disappearance of Moulton''s wife. The surviving property is private, so view only from lawful public areas. Secondary source: https://www.hampton.lib.nh.us/hampton/history/moulton/legend.htm', 'private', null, 'https://www.atlasobscura.com/places/moulton-mansion', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Horeb Trollway', 'mount-horeb-trollway', 'folklore', 43.00634, -89.73408, 'Mount Horeb', 'WI', 'Mount Horeb has filled its downtown with carved trolls inspired by Scandinavian folklore, earning the nickname Troll Capital of the World. The figures line the Trollway and turn an ordinary Main Street stroll into a scavenger hunt of wooden creatures.', 'open', null, 'https://www.trollway.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.trollway.com/', null, null, null, 'America/Chicago'),
  ('Mountain Springs Gravity Hill', 'mountain-springs-gravity-hill-ocotillo-ca', 'folklore', 32.6789722, -116.0991944, 'Ocotillo', 'CA', 'Stop on the Mountain Springs Road off-ramp from I-8 westbound, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Mountain Witch of Sugar Loaf', 'mountain-witch-of-sugar-loaf', 'folklore', 41.3155, -74.28789, 'Sugar Loaf', 'NY', 'Local folklore remembers Elizabeth Dobbin, a widow who supposedly lived alone near Sugar Loaf Mountain in the late 1700s and was accused by nearby villagers of practicing witchcraft. A Legends & Lore marker now marks the area associated with the Mountain Witch story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/mountain-witch/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Narragansett Rune Stone', 'narragansett-rune-stone', 'folklore', 41.57006, -71.45256, 'North Kingstown', 'RI', 'This large inscribed boulder generated theories involving Vikings, Norse explorers and even the Knights Templar after its markings became widely known in the twentieth century. Its true origin remains unresolved, and the state recovered the stone after it was removed from Narragansett Bay in 2012. It is now displayed publicly in Wickford at 55 Brown Street. Secondary source: https://www.ri.gov/press/view/19214', 'open', null, 'https://www.visitrhodeisland.com/listing/narragansett-rune-stone/7979/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nason Street Gravity Hill', 'nason-street-gravity-hill-moreno-valley-ca', 'folklore', 33.9406944, -117.1916389, 'Moreno Valley', 'CA', 'Stop on Nason Street, heading south just past Elder, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Nathaniel Knapp Bear Fight Marker', 'nathaniel-knapp-bear-fight-marker', 'folklore', 41.32864, -74.27994, 'Chester', 'NY', 'Local legend says Nathaniel Knapp killed a bear here around 1750 using only a knife and later asked to be buried at the site. The marker stands at Knapp''s View, a public passive park with walking and picnic access, though no confirmed grave marker for Knapp survives.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/nathaniel-knapp/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Harmony Labyrinth', 'new-harmony-labyrinth', 'folklore', 38.12244, -87.93591, 'New Harmony', 'IN', 'The Harmonists who founded New Harmony in the early nineteenth century used a labyrinth as a spiritual symbol of the difficult path toward enlightenment. Today''s hedge labyrinth recreates that tradition around a small temple and is open to visitors year-round without admission.', 'open', null, 'https://www.atlasobscura.com/places/new-harmony-labyrinth', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('New Orleans Historic Voodoo Museum', 'new-orleans-historic-voodoo-museum', 'folklore', 29.95981, -90.06379, 'New Orleans', 'LA', 'A compact French Quarter museum devoted to New Orleans Voodoo history, ritual objects, altars, art and local traditions. It is one of the city''s longest-running visitor sites focused specifically on Voodoo.', 'open', null, 'https://voodoomuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('New Prospect Road Gravity Hill', 'new-prospect-road-gravity-hill-jackson-nj', 'folklore', 40.1587778, -74.2676667, 'Jackson', 'NJ', 'Stop on New Prospect Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Newport Tower', 'newport-tower', 'folklore', 41.48581, -71.30987, 'Newport', 'RI', 'The circular stone tower in Touro Park has inspired centuries of speculation about Vikings, medieval explorers and other pre-Columbian visitors to New England. Archaeological and historical evidence instead strongly connects it to a seventeenth-century windmill associated with Governor Benedict Arnold. The competing theories have made it one of Rhode Island''s longest-running historical mysteries.', 'open', null, 'https://www.atlasobscura.com/places/newport-tower', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Noccalula Falls — Princess Noccalula Legend', 'noccalula-falls-princess-noccalula-legend', 'folklore', 34.0415, -86.0211, 'Gadsden', 'AL', 'A 90-foot waterfall is paired with the long-told legend of Noccalula, a young Cherokee woman said to have leapt from the cliff rather than accept an unwanted marriage. The story is folklore, while the waterfall and statue provide a concrete public destination.', 'open', null, 'https://noccalulafallspark.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('North Crosby Road Gravity Hill', 'north-crosby-road-gravity-hill-prosser-wa', 'folklore', 46.36222, -119.7238056, 'Prosser', 'WA', 'Stop on North Crosby Road, northeast of town, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('North Park Gravity Hill', 'north-park-gravity-hill-pittsburgh-pa', 'folklore', 40.6126944, -80.0258056, 'Pittsburgh', 'PA', 'Stop on McKinney Road at Kummer Road, in North Park, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Norumbega Tower', 'norumbega-tower', 'folklore', 42.35367, -71.26361, 'Weston', 'MA', 'A stone tower beside the Charles River marks the place nineteenth-century scholar Eben Horsford believed was a Norse fort connected to the legendary city of Norumbega. His Viking theory was not supported by convincing archaeological evidence, leaving the monument as an impressive memorial to a historical idea that did not hold up.', 'open', null, 'https://www.atlasobscura.com/places/norumbega-tower', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Octavia Hatcher Buried-Alive Grave', 'octavia-hatcher-buried-alive-grave', 'folklore', 37.47963, -82.5193, 'Pikeville', 'KY', 'Local tradition says Octavia Hatcher was mistakenly declared dead in 1891 during an illness that left several Pikeville residents in coma-like states. Her husband later reportedly exhumed her and found evidence she had awakened in the coffin; a fenced statue now marks her grave in Pikeville Cemetery.', 'open', null, 'https://www.roadsideamerica.com/story/23884', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Burying Ground — Rum Keg Girl', 'old-burying-ground-rum-keg-girl', 'folklore', 34.71857, -76.66357, 'Beaufort', 'NC', 'Beaufort’s old cemetery contains graves dating to the colonial period and several unusual burial stories. Its most famous legend concerns a young girl who died at sea and was supposedly preserved in a barrel of rum so her father could fulfill a promise to return her body home for burial.', 'limited', null, 'https://www.beauforthistoricsite.org/old-burying-ground/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Round Church', 'old-round-church', 'folklore', 44.39888, -72.99907, 'Richmond', 'VT', 'Built in the early nineteenth century, this rare many-sided meetinghouse looks almost circular from a distance. Local lore says its shape left the devil no corner in which to hide, adding a supernatural explanation to one of Vermont''s most unusual historic buildings.', 'limited', null, 'https://www.atlasobscura.com/places/old-round-church', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paulding Light Viewing Area', 'paulding-light-viewing-area', 'folklore', 46.40129, -89.17907, 'Watersmeet', 'MI', 'For generations, people have gathered at the end of an old roadway to watch a mysterious light appear in the distance, inspiring stories about a ghostly railroad worker and other supernatural explanations. Experiments have strongly connected the phenomenon to distant vehicle headlights, but the established public viewing area keeps the Paulding Light one of Michigan''s most enduring legend-tripping stops.', 'roadside', null, 'https://www.atlasobscura.com/places/the-paulding-light', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Peabody Duck March', 'peabody-duck-march', 'folklore', 35.14267, -90.05181, 'Memphis', 'TN', 'Twice daily, a small flock of ducks marches between a rooftop palace and the Peabody Hotel lobby fountain under the direction of a ceremonial Duckmaster. The ritual has become one of America''s strangest long-running hotel traditions.', 'limited', null, 'https://www.peabodymemphis.com/peabody-ducks', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pete the Talking Crow — Georgetown & Scott County Museum', 'pete-the-talking-crow-georgetown-scott-county-museum', 'folklore', 38.21858, -84.55624, 'Georgetown', 'KY', 'Local legend remembers Pete as a real talking crow that supposedly shouted "Go!" during early horse races and helped inspire the use of organized race starts. The Georgetown & Scott County Museum keeps the story alive with a mechanical Pete display among its local-history collections.', 'limited', null, 'https://www.roadsideamerica.com/story/16999', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.georgetownscottcountymuseum.com/', null, null, null, 'America/New_York'),
  ('Piasa Bird', 'piasa-bird', 'folklore', 38.89814, -90.19917, 'Alton', 'IL', 'A huge painted monster on the Mississippi bluffs revives the centuries-old Piasa legend recorded by early French explorers near Alton.', 'roadside', null, 'https://www.riversandroutes.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pickens County Courthouse — Face in the Window', 'pickens-county-courthouse-face-in-the-window', 'folklore', 33.26192, -88.09509, 'Carrollton', 'AL', 'A pale face-like image in an upstairs courthouse window is traditionally said to be that of Henry Wells, who was accused of burning an earlier courthouse and lynched in 1878. The supernatural explanation is folklore, but the mark in the glass is a long-standing local curiosity visible from lawful public areas.', 'roadside', null, 'https://www.tourwestalabama.com/attraction/pickens-county-courthouse/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pitt Road Gravity Hill', 'pitt-road-gravity-hill-springer-ok', 'folklore', 34.345972, -97.1779444, 'Springer', 'OK', 'Stop on Pitt Road, near Ardmore, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pleasant Valley Gravity Hill', 'pleasant-valley-gravity-hill-titusville-nj', 'folklore', 40.3379722, -74.8820556, 'Titusville', 'NJ', 'Stop on Pleasant Valley Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pleasantview Road Gravity Hill', 'pleasantview-road-gravity-hill-lewisberry-pa', 'folklore', 40.153194, -76.8398333, 'Lewisberry', 'PA', 'Stop on Pleasantview Road at PA 177, in York County, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ponce de Leon Springs State Park', 'ponce-de-leon-springs-state-park', 'folklore', 30.72217, -85.92633, 'Ponce de Leon', 'FL', 'Clear spring named for the enduring Fountain of Youth legend.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/ponce-de-leon-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Princeton Gravity Hill', 'princeton-gravity-hill-princeton-ky', 'folklore', 37.10722, -87.982556, 'Princeton', 'KY', 'Stop on KY 2618, under the Western Kentucky Parkway bridge, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Promised Land Gravity Hill', 'promised-land-gravity-hill-portville-ny', 'folklore', 42.0650833, -78.3528611, 'Portville', 'NY', 'Stop on Promised Land Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Purgatory Falls and the Devil''s Bean Pot', 'purgatory-falls-and-the-devils-bean-pot', 'folklore', 42.88671, -71.70856, 'Lyndeborough', 'NH', 'Local folklore says the Devil once tried to cook beans beside the falls and left behind a large pothole known as the Devil''s Bean Pot along with a nearby footprint-like impression in the rock. The actual landscape is a series of waterfalls and sculpted bedrock reached by hiking trails. The folklore gives an already unusual natural site a distinctly OddWay story.', 'open', null, 'https://www.atlasobscura.com/places/purgatory-falls', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Putney Road Gravity Hill', 'putney-road-gravity-hill-blaine-township-mi', 'folklore', 44.53028, -86.16056, 'Blaine Township', 'MI', 'Stop on Putney Road, south of Joyfield Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Reasner Road Gravity Hill', 'reasner-road-gravity-hill-rose-city-mi', 'folklore', 44.46333, -84.08722, 'Rose City', 'MI', 'Stop on the end of Reasner Road, past Heath Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Red Auerbach Good Luck Plaque', 'red-auerbach-good-luck-plaque', 'folklore', 42.36647, -71.06189, 'Boston', 'MA', 'A shamrock-shaped plaque inside North Station invites travelers to touch it for good luck in honor of legendary Celtics coach and executive Red Auerbach. Years of hands have turned an ordinary commemorative plaque into an interactive sports ritual.', 'open', null, 'https://www.atlasobscura.com/places/red-auerbach-good-luck-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Richfield Gravity Hill', 'richfield-gravity-hill-richfield-nc', 'folklore', 35.58333, -80.2450833, 'Richfield', 'NC', 'Stop on Richfield Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rose Hill Cemetery — Gypsy Queen Grave', 'rose-hill-cemetery-gypsy-queen-grave', 'folklore', 32.36355, -88.71895, 'Meridian', 'MS', 'A historic cemetery best known to odd-history travelers for the ornate grave of Kelly Mitchell, often called the "Gypsy Queen." The site has accumulated legends and offerings over time; visit as a cemetery and do not disturb memorial items or graves.', 'open', null, 'https://visitmississippi.org/trip-ideas/ghostly-adventures-in-mississippi/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sarah Tillinghast Family Cemetery', 'sarah-tillinghast-family-cemetery', 'folklore', 41.58133, -71.60419, 'Exeter', 'RI', 'Local tradition connects this small family cemetery with Sarah Tillinghast, whose father reportedly became convinced that she was returning from the grave while tuberculosis spread through the family. The story became one of Rhode Island''s lesser-known vampire legends, although the surviving historical record is less certain than the Mercy Brown case. The cemetery is a sensitive historic burial ground and should be visited respectfully in daylight. Secondary source: https://www.atlasobscura.com/places/grave-mercy-brown', 'limited', null, 'https://locationsoflore.com/2018/07/26/the-vampire-case-of-sarah-tillinghast/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Satan''s Kingdom State Recreation Area', 'satans-kingdom-state-recreation-area', 'folklore', 41.85725, -72.95835, 'New Hartford', 'CT', 'Despite the ominous name, Satan''s Kingdom is now a popular river recreation area. Competing stories have tried to explain the name through rough terrain, outlaw hideouts and local folklore, giving an otherwise scenic park one of Connecticut''s best place names.', 'open', null, 'https://www.atlasobscura.com/places/satans-kingdom', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Selee Satanic Mill Marker', 'selee-satanic-mill-marker', 'folklore', 42.0483, -71.15688, 'Easton', 'MA', 'A historical marker identifies the site of an eighteenth-century sawmill linked by later folklore to owner Israel Selee, who was said to be a wizard assisted by Satanic imps. The mill history is real; the demonic workforce belongs firmly to local legend.', 'roadside', null, 'https://www.atlasobscura.com/places/selee-satanic-mill-marker', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Seven Gates of Hell — Trout Run Road', 'seven-gates-of-hell-trout-run-road', 'folklore', 40.03967, -76.66169, 'Hellam Township', 'PA', 'York County''s Seven Gates of Hell legend claims that a chain of gates hidden around Hellam Township leads eventually to an entrance to hell, with versions involving either a burned asylum or an eccentric doctor. The alleged asylum never existed and the land connected to the story is private property; this is strictly a **public-road folklore stop, not an invitation to search the woods**.', 'private', null, 'https://en.wikipedia.org/wiki/Seven\_Gates\_of\_Hell', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shelburne Road Gravity Hill', 'shelburne-road-gravity-hill-greenfield-ma', 'folklore', 42.589306, -72.63028, 'Greenfield', 'MA', 'Stop on Shelburne Road, facing east just past the Route 2 overpass, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Singing Sands of Bete Grise', 'singing-sands-of-bete-grise', 'folklore', 47.38679, -87.95703, 'Bete Grise', 'MI', 'The pale sand along Bete Grise Bay can produce a squeaking or humming sound when rubbed or disturbed under the right dry conditions. Local legend gives the phenomenon a more romantic explanation, saying the beach sings back to a woman who once called across the water for her lost lover.', 'open', null, 'https://www.visitkeweenaw.com/outdoors/water-activities/beaches/', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Sleeping Giant Observation Tower & Hobbomock Legend', 'sleeping-giant-observation-tower-hobbomock-legend', 'folklore', 41.42097, -72.89924, 'Hamden', 'CT', 'The long ridge resembles a giant figure lying on its back and is tied to Indigenous traditions involving the giant spirit Hobbomock. A stone observation tower built in the 1930s stands at the end of one of the park''s best-known hikes.', 'open', null, 'https://www.atlasobscura.com/places/sleeping-giant-observation-tower', '2026-09-08T18:39:47.144889+00:00', null, 'https://ctparks.com/parks/sleeping-giant-state-park', null, null, null, 'America/New_York'),
  ('Smith''s Bull Ride Marker', 'smiths-bull-ride-marker', 'folklore', 40.8585, -73.2124, 'Smithtown', 'NY', 'Smithtown folklore claims founder Richard Smith received as much land as he could circle in a single day while riding a bull after helping return a kidnapped daughter to a Montauk leader. Historical deeds make the tale doubtful, but it remains central to the town''s identity and is commemorated by both a marker and the famous Whisper the Bull statue nearby.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/smiths-bull-ride/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Snowshoe Rock of Doom', 'snowshoe-rock-of-doom', 'folklore', 43.16937, -70.66381, 'York Harbor', 'ME', 'A plaque on a roadside boulder marks a local story connected to the Candlemas Massacre of 1692 and a pair of abandoned snowshoes said to have warned settlers of danger. The modern marker has an added OddWay twist: accounts say it was deliberately placed on a different rock so visitors would not trespass at the actual traditional site.', 'roadside', null, 'https://www.roadsideamerica.com/story/64305', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Solitude Stone', 'solitude-stone', 'folklore', 42.00148, -71.01711, 'West Bridgewater', 'MA', 'A boulder engraved in 1852 with a melancholy poem about solitude sits in the woods near the Bridgewater Triangle. Later stories connected the stone with death, disappearance and paranormal activity, although those claims are folklore layered onto a genuine nineteenth-century inscription.', 'open', null, 'https://www.atlasobscura.com/places/solitude-stone', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('South Mountain Fairy Trail', 'south-mountain-fairy-trail', 'folklore', 40.72657, -74.30478, 'Millburn Township', 'NJ', 'Tiny handmade doors, houses and miniature scenes appear along a wooded trail in South Mountain Reservation. The installations turn an ordinary family hike into a search for a hidden fairy village tucked into roots, trunks and rocks.', 'open', null, 'https://www.atlasobscura.com/places/south-mountain-fairy-trail', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spider Gates Cemetery', 'spider-gates-cemetery', 'folklore', 42.26444, -71.90005, 'Leicester', 'MA', 'The small Friends Cemetery became infamous under the nickname Spider Gates because of its former decorative entrance and wild stories claiming it was an entrance to Hell. The cemetery itself is real, peaceful and open to respectful visitors, while the surrounding watershed property is posted against trespassing.', 'limited', null, 'https://www.atlasobscura.com/places/spider-gates-cemetery', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spite Tower', 'spite-tower', 'folklore', 41.55383, -71.12765, 'Adamsville', 'RI', 'Local legend claims this three-story tower was deliberately built to block a neighbor''s view after a feud, earning it the name Spite Tower. Historical research indicates the much less dramatic truth: it was constructed around 1905 as a water tower supplying gravity-fed plumbing to the adjacent estate. The structure is private property but visible from the public road. Secondary source: https://www.roadsideamerica.com/tip/77134', 'roadside', null, 'https://www.rimonthly.com/spite-tower-in-little-compton/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spook Hill', 'spook-hill', 'folklore', 41.58642, -73.89194, 'Wappingers Falls', 'NY', 'Spook Hill Road supposedly earned its name when moonlight reflecting from a rocky hillside created a strange glow that terrified horses traveling the old dirt road. The original landscape has changed considerably, but a 2023 Legends & Lore marker in Spook Hill Park preserves the story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/spook-hill/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spook Hill', 'spook-hill-fort-gaines-ga', 'folklore', 31.729083, -85.01056, 'Fort Gaines', 'GA', 'Stop on Spook Hill, north of town, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spook Hill', 'spook-hill-lake-wales-fl', 'folklore', 27.91194, -81.5823611, 'Lake Wales', 'FL', 'Stop on Spook Hill, off US 27, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spook Hill', 'spook-hill-yates-county-ny', 'folklore', 42.7133889, -77.30925, 'Yates County', 'NY', 'Stop on Newell Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spook Rock Road', 'spook-rock-road-rockland-county-ny', 'folklore', 41.1626389, -74.0950278, 'Rockland County', 'NY', 'Stop on Spook Rock Road at US 202, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Peter’s Cemetery — Captain James Drew Ghost', 'st-peters-cemetery-captain-james-drew-ghost', 'folklore', 38.77539, -75.13982, 'Lewes', 'DE', 'Captain James Drew, commander of HMS DeBraak when the ship sank off Delaware in 1798, is buried in the historic churchyard at St. Peter’s. Local folklore says his ghost leaves the cemetery on moonless nights searching for his lost crew. The shipwreck and Drew’s burial are historical; the wandering captain is the legend.', 'open', null, 'https://www.visitrehoboth.com/things-to-do/coastal-delaware-ghost-stories', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.stpeterslewes.org/', null, null, null, 'America/New_York'),
  ('St. Roch Cemetery No. 1 and Chapel', 'st-roch-cemetery-no-1-and-chapel', 'folklore', 29.9754, -90.0525, 'New Orleans', 'LA', 'The nineteenth-century St. Roch Chapel became associated with healing petitions, and visitors historically left prosthetics, crutches and small offerings of thanks. The chapel and cemetery remain religious spaces, so visit quietly and during lawful access hours.', 'limited', null, 'https://nolacatholiccemeteries.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stephen Foster Folk Culture Center State Park', 'stephen-foster-folk-culture-center-state-park', 'folklore', 30.32808, -82.7614, 'White Springs', 'FL', 'Massive carillon tower, folk-culture exhibits, and Old Florida interpretation centered on ''Old Folks at Home.''', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/stephen-foster-folk-culture-center-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stepp Cemetery', 'stepp-cemetery', 'folklore', 39.31428, -86.43024, 'Martinsville', 'IN', 'This small cemetery inside Morgan-Monroe State Forest has become the center of a long-running "Lady in Black" legend involving a grieving woman said to linger near an old tree and grave. The haunting is folklore, not established fact, and visitors should treat the active cemetery respectfully and use normal daylight forest access.', 'open', null, 'https://www.hauntedplaces.org/item/stepp-cemetery/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Sterling Gravity Hill', 'sterling-gravity-hill-sterling-ct', 'folklore', 41.7353889, -71.82833, 'Sterling', 'CT', 'Stop on Main Street, just before Snake Meadow Hill Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stiffy Green Mausoleum', 'stiffy-green-mausoleum', 'folklore', 39.476, -87.3489, 'Terre Haute', 'IN', 'Terre Haute legend says a bulldog nicknamed Stiffy Green remained devoted to his owner, florist John Heinl, and later became associated with Heinl''s mausoleum in Highland Lawn Cemetery. Stories claim the dog''s green eyes could be seen glowing near the tomb; the original dog figure is now preserved at the Vigo County History Center, while the mausoleum remains the physical location tied to the legend.', 'open', null, 'https://www.terrehaute.com/things-to-do/experiences/legend-of-stiffy-green/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Stuckey''s Bridge', 'stuckeys-bridge', 'folklore', 32.25556, -88.85528, 'Chunky', 'MS', 'A historic bridge associated with the legend of an innkeeper-turned-outlaw named Stuckey and later ghost stories. The folklore is not the same thing as documented history; view the bridge only from lawful public access and do not enter unsafe or posted areas.', 'roadside', null, 'https://visitmississippi.org/trip-ideas/ghostly-adventures-in-mississippi/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sulphur Springs Gravity Hill', 'sulphur-springs-gravity-hill-helena-ar', 'folklore', 34.53583, -90.60583, 'Helena', 'AR', 'Stop on Sulphur Springs Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tate''s Hell State Forest', 'tates-hell-state-forest', 'folklore', 29.8427, -84.69603, 'Carrabelle', 'FL', 'Huge swampy forest named for the local legend of Cebe Tate''s disastrous trek through the wilderness.', 'open', null, 'https://www.fdacs.gov/Forest-Wildfire/Our-Forests/State-Forests/Tate-s-Hell-State-Forest', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Boston Stone', 'the-boston-stone', 'folklore', 42.36185, -71.0567, 'Boston', 'MA', 'A stone sphere embedded in a downtown wall is labeled ''Boston Stone 1737,'' but exactly what it originally signified remains debated. Explanations range from a paint-grinding stone to a deliberately manufactured historical curiosity, making the uncertainty part of the attraction.', 'open', null, 'https://www.atlasobscura.com/places/the-boston-stone-boston-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Chocorua Legend Historical Marker', 'the-chocorua-legend-historical-marker', 'folklore', 43.90887, -71.23431, 'Tamworth', 'NH', 'A state marker summarizes the legend of Chocorua, whose death on the mountain was later embellished into stories of revenge and a curse upon local settlers. Multiple versions disagree about what actually happened, and even the historical identity behind the legend is debated. The marker provides a concrete roadside point for a story that otherwise spreads across an entire mountain.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=152078', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Crossroads Blues Marker', 'the-crossroads-blues-marker', 'folklore', 34.19496, -90.56422, 'Clarksdale', 'MS', 'The famous Highway 61/49 crossroads is associated in popular culture with the legend that Robert Johnson sold his soul to the devil in exchange for musical ability. The crossroads is real; the supernatural bargain is folklore, and the stop should be presented that way.', 'roadside', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Devil''s Den', 'the-devils-den', 'folklore', 42.26016, -71.44783, 'Ashland', 'MA', 'A small talus cave beside Ashland High School was once feared by colonial settlers as a possible hiding place of the Devil. Archaeological evidence points instead to earlier Indigenous use, giving the cave both genuine history and a layer of Puritan-era supernatural folklore.', 'open', null, 'https://www.atlasobscura.com/places/the-devils-den', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Hippie Tree', 'the-hippie-tree', 'folklore', 44.75258, -85.65039, 'Traverse City', 'MI', 'A sprawling fallen willow on the former Traverse City State Hospital grounds has been covered in layers of colorful paint by generations of visitors. Local folklore claims the tree is connected with spirits from the old hospital and even calls it a portal to hell, while today it remains a strange trailside folk-art landmark.', 'open', null, 'https://www.atlasobscura.com/places/the-hippie-tree', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('The Legend of John Maynard Memorial', 'the-legend-of-john-maynard-memorial', 'folklore', 42.880979, -78.888742, 'Buffalo', 'NY', 'A four-foot plaque at the Erie Basin Marina commemorating Theodor Fontane''s poem about a helmsman who steers a burning Lake Erie steamer to shore. Maynard is a fictionalised name over a real rescue. Buffalo and its German sister city Dortmund dedicated it in 1997, with the finished plaque rededicated in 1998.', 'open', null, 'http://www.johnmaynard.net/mem.html', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Legend of the Iron Hoop', 'the-legend-of-the-iron-hoop', 'folklore', 41.145601, -81.339982, 'Kent', 'OH', 'A five-piece outdoor sculpture by Brinsley Tyrrell, professor emeritus at Kent State, made in 1980-81 and inspired by twisted dry wood near his home. After stints elsewhere in Ohio it was installed permanently near Henderson Hall in July 2011.', 'open', null, 'https://www.kent.edu/universityarchitect/sculptures-loan-ohio-arts-council', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Lewis Giant Marker', 'the-lewis-giant-marker', 'folklore', 44.2772, -73.56462, 'Lewis', 'NY', 'Joseph Call was a real nineteenth-century wrestler, logger and millwright whose unusual size and strength inspired stories of superhuman feats. Known as the Lewis Giant or the Paul Bunyan of the East, he is commemorated by a Legends & Lore marker along U.S. Route 9.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/the-lewis-giant/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Mysterious Witch Bonney', 'the-mysterious-witch-bonney', 'folklore', 42.62854, -71.29266, 'Lowell', 'MA', 'A nineteenth-century cemetery statue of a woman has accumulated stories that her dress changes length, that she moves, and that offerings left at the grave mysteriously disappear. The monument is real; the supernatural claims are cemetery folklore. Visit Lowell Cemetery respectfully and only during permitted hours.', 'limited', null, 'https://www.atlasobscura.com/places/mysterious-witch-bonney', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Old Leatherman''s Cave', 'the-old-leathermans-cave', 'folklore', 41.64017, -73.08796, 'Watertown', 'CT', 'One of the caves associated with the mysterious nineteenth-century wanderer known only as the Old Leatherman sits along his former Connecticut circuit. Dressed almost entirely in handmade leather, he repeatedly walked a roughly 365-mile route through Connecticut and New York while refusing to reveal much about himself.', 'open', null, 'https://www.atlasobscura.com/places/the-old-leathermans-cave', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Weeping Woman of Riverview Cemetery', 'the-weeping-woman-of-riverview-cemetery', 'folklore', 39.27477, -81.55457, 'Parkersburg', 'WV', 'A melancholy female statue in Riverview Cemetery has collected local legends claiming she weeps, changes position or grants wishes to visitors who approach her correctly. The monument is in an operating cemetery open during daytime hours, so this is a folklore stop that needs respectful cemetery behavior rather than nighttime ghost hunting.', 'open', null, 'https://www.atlasobscura.com/places/the-weeping-woman', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Witches’ Keyhole', 'the-witches-keyhole', 'folklore', 35.92733, -81.52582, 'Lenoir', 'NC', 'Local tradition says an unusual keyhole-shaped opening in George Powell’s old house was intended to give witches or “haints” a way to escape instead of tormenting the occupants. The house was demolished decades ago, but the keyhole feature was preserved in a roadside display at Trinity United Methodist Church.', 'roadside', null, 'https://www.strangecarolinas.com/2015/06/the-witches-keyhole-lenoir-nc.html', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Witches'' Tree', 'the-witches-tree', 'folklore', 38.23602, -85.73177, 'Louisville', 'KY', 'Local legend says a tree once used as a gathering place by witches was cut down before the 1890 tornado that devastated Louisville, and that the witches cursed the city in revenge. The gnarled replacement tree at Park Avenue and Sixth Street has become a neighborhood landmark where visitors still leave small offerings.', 'open', null, 'https://www.atlasobscura.com/places/the-witches-tree', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('Thompson Park Vortex', 'thompson-park-vortex', 'folklore', 43.96209, -75.89192, 'Watertown', 'NY', 'Local lore claims there is a strange area within Thompson Park where people become disoriented, lose several minutes of time, or briefly experience another time period. There is no proven supernatural vortex, but the story has become one of Watertown''s best-known modern legends and the public park can be visited normally.', 'open', null, 'https://hauntedhistorytrail.com/explore?category=creepy-locations\&utm_source=chatgpt.com', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thread City Crossing — Frog Bridge', 'thread-city-crossing-frog-bridge', 'folklore', 41.70997, -72.20954, 'Willimantic', 'CT', 'Four enormous bronze frogs perch on equally enormous thread spools at the corners of this bridge. The sculptures combine Willimantic''s textile history with the famous 1750s ''Battle of the Frogs,'' when mysterious nighttime noises terrified residents before being traced to masses of frogs.', 'roadside', null, 'https://www.atlasobscura.com/places/thread-city-crossing-bridge', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thunderbird Drive Gravity Hill', 'thunderbird-drive-gravity-hill-el-paso-tx', 'folklore', 31.84361, -106.5175, 'El Paso', 'TX', 'Stop on Thunderbird Drive, facing south, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Tomb of Julia Legare', 'tomb-of-julia-legare', 'folklore', 32.57996, -80.30819, 'Edisto Island', 'SC', 'A brick mausoleum at the ruins of the old Presbyterian church is tied to the legend of Julia Legare, who was supposedly mistakenly declared dead and buried alive. Folklore says the tomb’s heavy door repeatedly opened or was moved despite attempts to secure it. The buried-alive story is legend rather than established fact, but the unusual tomb is real.', 'open', null, 'https://www.scpictureproject.org/charleston-county/tomb-of-julia-legare.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Upper Huffman Gravity Hill', 'upper-huffman-gravity-hill-anchorage-ak', 'folklore', 61.10861, -149.73333, 'Anchorage', 'AK', 'Stop on Upper Huffman Road, on the Hillside, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Anchorage'),
  ('Upton Chamber', 'upton-chamber', 'folklore', 42.17601, -71.59782, 'Upton', 'MA', 'A long stone-lined underground chamber with a corbelled roof sits in Heritage Park, and its original purpose has puzzled researchers for generations. Archaeological study points to a historic construction rather than exotic ancient origins, but the dark artificial cave remains one of Massachusetts'' better physical mysteries.', 'open', null, 'https://www.atlasobscura.com/places/upton-chamber', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vampire Grasp Grave of Simon Whipple Aldrich', 'vampire-grasp-grave-of-simon-whipple-aldrich', 'folklore', 41.98806, -71.52972, 'North Smithfield', 'RI', 'Simon Whipple Aldrich''s 1841 gravestone contains the striking phrase "Consumption''s vampire grasp," referring poetically to tuberculosis rather than documenting an accusation that Aldrich was a vampire. The wording has nevertheless made the grave an unusual stop within New England''s broader vampire tradition. The stone is in the historic Union Cemetery Annex area; visit only during daylight and respect the graves. Secondary source: https://www.roadsideamerica.com/tip/43658', 'limited', null, 'https://rihistoriccemeteries.org/newgravedetails.aspx?ID=170741', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Villamain Road Gravity Hill', 'villamain-road-gravity-hill-san-antonio-tx', 'folklore', 29.31722, -98.44333, 'San Antonio', 'TX', 'Stop on the railway crossing at Villamain and Shane Roads, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Voodoo Authentica Cultural Center & Collection', 'voodoo-authentica-cultural-center-collection', 'folklore', 29.95919, -90.06277, 'New Orleans', 'LA', 'Voodoo Authentica combines a spiritual shop, cultural center and collection of works made by practitioners and artists connected with New Orleans Voodoo. It also hosts educational and ceremonial programming at selected times.', 'open', null, 'https://www.voodoauthentica.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Voodoo Spiritual Temple', 'voodoo-spiritual-temple', 'folklore', 29.96854, -90.06407, 'New Orleans', 'LA', 'Established in 1990, the Voodoo Spiritual Temple presents traditional West African-influenced spiritual and herbal practices while working to correct misconceptions about Voodoo. Its current location is 1428 N. Rampart Street; hours are flexible, so check ahead.', 'limited', null, 'https://voodoospiritualtemple.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('W. W. Pool Mausoleum — Richmond Vampire Tomb', 'w-w-pool-mausoleum-richmond-vampire-tomb', 'folklore', 37.53755, -77.45412, 'Richmond', 'VA', 'The ornate mausoleum of bookkeeper W. W. Pool in Hollywood Cemetery became attached to Richmond''s vampire legend after the 1925 Church Hill Tunnel disaster. There is no evidence Pool was a vampire, but the tomb remains the physical focus of the story; visit only during cemetery hours and do not damage or enter the structure.', 'open', null, 'https://www.atlasobscura.com/places/hollywood-cemetery', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Weeki Wachee Springs State Park', 'weeki-wachee-springs-state-park', 'folklore', 28.51667, -82.57222, 'Weeki Wachee', 'FL', 'Historic live-mermaid attraction built around a first-magnitude spring.', 'open', null, 'https://weekiwachee.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Where Shute Fell', 'where-shute-fell', 'folklore', 42.45232, -71.09628, 'Stoneham', 'MA', 'A lonely stone on Great Island in Spot Pond bears only the words ''WHERE SHUTE FELL.'' Stories propose a duel, a wrestling match and even a drunken accident, but the meaning was already uncertain in the nineteenth century. Reaching the island requires authorized boat access or a rental from the permitted Spot Pond boating operation.', 'limited', null, 'https://www.atlasobscura.com/places/where-shute-fell', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Witch Dance', 'witch-dance', 'folklore', 33.91162, -88.939, 'Houston', 'MS', 'A Natchez Trace stop tied to an old regional legend that witches once gathered here to dance, leaving places where grass would not grow. The story is folklore rather than documented fact, but the named NPS site is real and routable.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Witch of Pungo Statue', 'witch-of-pungo-statue', 'folklore', 36.86612, -76.13182, 'Virginia Beach', 'VA', 'This bronze statue honors Grace Sherwood, the Virginia woman convicted of witchcraft after a 1706 ducking trial in what was then Princess Anne County. The monument depicts Sherwood with a raccoon and stands on publicly accessible grounds near Sentara Bayside Hospital, giving the famous Witch of Pungo story a specific modern stop.', 'open', null, 'https://www.roadsideamerica.com/tip/34645', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Witch Rock', 'witch-rock', 'folklore', 41.72628, -70.84029, 'Rochester', 'MA', 'A huge boulder in a residential front yard has a broom-riding witch painted across its face and carries generations of ghost stories involving voices, laughter and apparitions. The supernatural claims are folklore, and the rock is on private residential property, so it should only be viewed respectfully from the public roadside.', 'private', null, 'https://www.atlasobscura.com/places/witch-rock', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Witch Windows of Craftsbury', 'witch-windows-of-craftsbury', 'folklore', 44.63672, -72.37261, 'Craftsbury', 'VT', 'Vermont is known for occasional windows installed diagonally beneath rooflines, commonly called witch windows. Folklore claims the crooked openings were meant to prevent witches from flying through them, though practical architectural explanations are far more likely; the pin represents a Craftsbury area where examples can be spotted from public roads.', 'roadside', null, 'https://www.atlasobscura.com/places/witch-windows', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('York Witch Grave — Mary Nasson', 'york-witch-grave-mary-nasson', 'folklore', 43.14388, -70.65244, 'York', 'ME', 'Mary Nasson’s 1774 grave is covered by a large stone slab, which later folklore claimed was placed there to keep a witch from rising from the dead. There is no evidence Nasson was a witch; the unusually protected grave itself is real and the legend has persisted for generations.', 'open', null, 'https://www.atlasobscura.com/places/york-witch-grave', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fear Columbus Haunted House', '13th-floor-haunted-house', 'haunted', 40.08219, -82.948515, 'Columbus', 'OH', 'The former 13th Floor Haunted House in Columbus now operates under local ownership as Fear Columbus Haunted House. It remains a large seasonal horror attraction with elaborate walk-through sets, live actors and additional special-event nights, but the OddWay record should be renamed and pointed to the current brand.', 'limited', null, 'https://fearcolumbus.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.13thfloorcolumbus.com', null, 'way', 637555091, 'America/New_York'),
  ('13th Hour Haunted House', '13th-hour-haunted-house', 'haunted', 40.905432, -74.586599, 'Wharton', 'NJ', '13th Hour Haunted House is a New Jersey horror complex offering multiple themed haunted houses at one location along with escape rooms and other experiences. The major walk-through haunts are seasonal, while some of the site''s non-haunt attractions operate more broadly.', 'limited', null, 'https://13thhour.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://13thhour.com/', null, 'node', 9201376625, 'America/New_York'),
  ('1754 House — Former Curtis House Inn', '1754-house-former-curtis-house-inn', 'haunted', 41.53321, -73.20639, 'Woodbury', 'CT', 'Connecticut''s long-running Curtis House Inn now operates as the 1754 House, but its old ghost stories have not disappeared with the name change. Reports attached to the historic property include apparitions, footsteps, voices and unexplained music. It remains an active inn and restaurant rather than an abandoned location.', 'open', null, 'https://www.hauntedplaces.org/item/curtis-house-restaurant-and-inn/', '2026-09-08T18:47:23.721893+00:00', null, 'https://1754house.com/', null, null, null, 'America/New_York'),
  ('217 Terror Haunted House', '217-terror-haunted-house', 'haunted', 39.485916, -90.372725, 'Roodhouse', 'IL', '217 Terror is a seasonal Illinois haunted attraction that bundles several themed walk-through haunts into one ticket. Live actors, dark sets and different horror environments make it a dedicated October scare stop operating only on select dates.', 'limited', null, 'https://217terror.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://217terror.com/', '+12173704650', 'node', 13947549128, 'America/Chicago'),
  ('Abandoned Haunted House Complex', 'abandoned-haunted-house-complex', 'haunted', 42.700534, -87.952816, 'Mount Pleasant', 'WI', 'Abandoned Haunted House Complex is a large seasonal Wisconsin scare destination combining multiple haunted houses, outdoor zones and additional Halloween activities at one property. It operates on select dates from late September into the fall, so access is seasonal and ticketed.', 'limited', null, 'https://abandonedhauntedhouse.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 330459556, 'America/Chicago'),
  ('Addy Sea Inn Ghost Stories', 'addy-sea-inn-ghost-stories', 'haunted', 38.54358, -75.0573, 'Bethany Beach', 'DE', 'The historic Addy Sea appears in Delaware haunted-history material and has accumulated room-specific ghost stories involving a shaking bathtub, phantom organ music and a handyman spirit. Independent evidence for the experiences is thin, so the stories are best presented as inn folklore rather than authenticated paranormal events. It remains an operating lodging property.', 'limited', null, 'https://www.hauntedplaces.org/item/addy-sea-inn/', '2026-09-08T18:31:51.932734+00:00', null, 'https://addysea.com/', null, null, null, 'America/New_York'),
  ('Admiral Fell Inn', 'admiral-fell-inn', 'haunted', 39.2818, -76.5933, 'Baltimore', 'MD', 'The Admiral Fell Inn occupies a collection of historic Fell''s Point buildings associated with the neighborhood''s long maritime history. Guests and tour guides have attached numerous ghost stories to its rooms and corridors, while the property continues to operate as a hotel.', 'open', null, 'https://www.visitmaryland.org/listing/hotels-motels/admiral-fell-inn', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aleister Crowley''s Magickal Retirement Cabin', 'aleister-crowleys-magickal-retirement-cabin', 'haunted', 43.69435, -71.80538, 'Hebron', 'NH', 'Occultist Aleister Crowley spent several months in Hebron in 1916 during what he described as a magickal retirement. The small house associated with that period still survives, giving New Hampshire a direct physical connection to one of the twentieth century''s most notorious occult figures. It is a private residence and should be viewed only from a lawful public road.', 'private', null, 'https://www.atlasobscura.com/places/aleister-crowley-s-magickal-retirement', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Alice Flagg’s Grave', 'alice-flaggs-grave', 'haunted', 33.46732, -79.1386, 'Pawleys Island', 'SC', 'A plain stone marked only “Alice” is associated with one of the Lowcountry’s best-known romantic ghost legends. Tradition says Alice Flagg died after her family opposed a secret engagement, and visitors still leave rings and tokens while searching for her supposed apparition.', 'open', null, 'https://www.atlasobscura.com/places/alice-flagg-s-grave', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Amityville Horror House', 'amityville-horror-house', 'haunted', 40.66661, -73.41481, 'Amityville', 'NY', 'The house associated with the 1974 DeFeo murders later became internationally famous through claims made by the Lutz family and The Amityville Horror books and films. It remains a private residence, so OddWay visitors should view only from public streets, should not enter the property, and should avoid disturbing the occupants.', 'private', null, 'https://www.wikidata.org/wiki/Q3597031', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Amos J. Blake House Museum', 'amos-j-blake-house-museum', 'haunted', 42.77998, -72.14557, 'Fitzwilliam', 'NH', 'The Fitzwilliam Historical Society preserves this nineteenth-century house as a local museum filled with period furnishings and artifacts. Staff and visitors have reported unexplained sounds, voices and other alleged activity, including stories of multiple spirits and even a phantom cat. Tours are currently arranged by appointment, so visitors should contact the museum in advance.', 'limited', null, 'https://www.verani.com/view-blog/wicked-spooky-spots-in-new-england-to-give-you-the-chills-this-halloween', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.fitzhistoric.org/', null, null, null, 'America/New_York'),
  ('Anderson Hotel', 'anderson-hotel', 'haunted', 38.03639, -84.89636, 'Lawrenceburg', 'KY', 'The nineteenth-century Anderson Hotel stopped operating as normal lodging decades ago but remains one of Lawrenceburg''s best-known paranormal locations. Investigators and local storytellers have reported apparitions, voices and violent unexplained activity inside; because the hotel is not a normal walk-in attraction, OddWay should route visitors only to public downtown viewing or explicitly scheduled events. Address: 116 S. Main St., Lawrenceburg, KY', 'roadside', null, 'https://www.kentuckyafterdark.com/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Apollo Civic Theatre', 'apollo-civic-theatre', 'haunted', 39.45798, -77.96218, 'Martinsburg', 'WV', 'This historic downtown theatre is one of the stops on West Virginia''s Paranormal Trail, with stories of unexplained activity tied to the old performance space. Visitors can see the building during scheduled performances and special haunted events, while paranormal investigations are offered only at selected times or by arrangement.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Astoria Ghost Tour', 'astoria-ghost-tour', 'haunted', 46.188873, -123.82965, 'Astoria', 'OR', 'Astoria Ghost Tour leads visitors into the city''s darker history and paranormal stories, including underground spaces and locations associated with reported hauntings. Access is through scheduled guided tours, so it is best treated as a book-ahead experience rather than a walk-in attraction.', 'limited', null, 'https://astoriaghosttour.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 8895654901, 'America/Los_Angeles'),
  ('Asylum 49', 'asylum-49', 'haunted', 40.526335, -112.295012, 'Tooele', 'UT', 'Asylum 49 is a seasonal haunted attraction inside Tooele''s former hospital complex, using medical-horror themes, actors and elaborate sets throughout the building. The property also operates a Museum of Horrors with unusual medical and macabre objects, but the main haunt is available only on scheduled dates.', 'limited', null, 'https://asylum49.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 9631849882, 'America/Denver'),
  ('Audubon House & Tropical Gardens', 'audubon-house-tropical-gardens', 'haunted', 24.55916, -81.80577, 'Key West', 'FL', 'Historic home associated with old-Key-West ghost stories and 19th-century maritime wealth.', 'limited', null, 'https://audubonhouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Auntie Mortem''s Abattoir at Hersheypark Dark Nights', 'auntie-mortem-s-abattoir', 'haunted', 40.293825, -76.654432, 'Derry Township', 'PA', 'Auntie Mortem''s Abattoir is one of the walk-through haunted houses inside Hersheypark''s Dark Nights Halloween event, built around a grotesque butcher-shop and slaughterhouse theme. It is not a standalone Derry Township business and can only be visited when the park''s seasonal Dark Nights event is operating.', 'limited', null, 'https://www.hersheypark.com/darknights/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 12995090391, 'America/New_York'),
  ('Bachelor''s Grove Cemetery', 'bachelors-grove-cemetery', 'haunted', 41.63089, -87.77072, 'Midlothian', 'IL', 'A tiny abandoned pioneer cemetery deep in the forest preserve, famous for decades of phantom-house, ghost-car, and apparition stories.', 'open', null, 'https://fpdcc.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Battleship North Carolina', 'battleship-north-carolina', 'haunted', 34.23645, -77.95424, 'Wilmington', 'NC', 'The World War II battleship North Carolina is preserved across the Cape Fear River from downtown Wilmington and can be explored through multiple decks, turrets, crew spaces, and machinery compartments. Along with its documented wartime history, the ship has a strong paranormal reputation and even hosts official paranormal-investigation programming. Paranormal program contact: https://battleshipnc.com/contact/', 'limited', null, 'https://battleshipnc.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belcourt of Newport', 'belcourt-of-newport', 'haunted', 41.45463, -71.30284, 'Newport', 'RI', 'Designed by Richard Morris Hunt and completed in 1894, Belcourt is one of Newport''s strangest Gilded Age mansions, combining French Gothic and Renaissance influences around enormous carriage spaces. Later owners promoted stories of haunted antiques and unexplained phenomena inside the house. Visits are through scheduled tours and events.', 'limited', null, 'https://www.atlasobscura.com/places/belcourt-castle', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.belcourt.com/', null, null, null, 'America/New_York'),
  ('Bellevue Hall Ghost Stories', 'bellevue-hall-ghost-stories', 'haunted', 39.77567, -75.495, 'Wilmington', 'DE', 'Bellevue Hall, the mansion at Bellevue State Park, has accumulated stories of unexplained shrieks, moved furniture and electrical disturbances attributed to resident ghosts. Delaware state sources preserve those claims as part of local paranormal lore. The park grounds are public, while mansion access depends on current programming and events.', 'limited', null, 'https://dnrec.delaware.gov/outdoor-delaware/unveiling-delawares-dark-secrets-exploring-the-haunted-fort-delaware-and-beyond/', '2026-09-08T18:31:51.932734+00:00', null, 'https://destateparks.com/Bellevue', null, null, null, 'America/New_York'),
  ('BK Historic House & Gardens', 'bk-historic-house-gardens', 'haunted', 29.96083, -90.06111, 'New Orleans', 'LA', 'The 1826 Beauregard-Keyes House is a preserved French Quarter residence associated with military, immigrant and literary history, along with local ghost lore. It operates as a ticketed historic house museum with scheduled programming.', 'limited', null, 'https://www.bkhouse.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Black Bass Hotel', 'black-bass-hotel', 'haunted', 40.40677, -75.03756, 'Lumberville', 'PA', 'The Black Bass Hotel has served travelers along the Delaware River for centuries and incorporates stories of unexplained visitors into its documented history and folklore. It remains a functioning hotel and restaurant, so travelers can visit normally without entering private guest spaces.', 'open', null, 'https://www.blackbasshotel.com/history/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brandy Gap Tunnel No. 2', 'brandy-gap-tunnel-no-2', 'haunted', 39.29296, -80.50363, 'Salem', 'WV', 'Also called the Flinderation Tunnel, this roughly Civil War-era railroad tunnel is now reached from the North Bend Rail Trail and has accumulated stories of ghostly voices and unexplained figures. The tunnel is dark enough that a flashlight is necessary, and reaching it requires trail travel rather than simply pulling off the highway.', 'limited', null, 'https://www.atlasobscura.com/places/brandy-gap-tunnel-2', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brighton Asylum', 'brighton-asylum', 'haunted', 40.858032, -74.143347, 'Passaic', 'NJ', 'Brighton Asylum is a large horror-entertainment complex themed around an abandoned institution, with elaborate haunted walkthroughs, escape rooms and special events. Its main haunted-house season is limited to selected dates, although the property hosts other horror experiences at different times of year.', 'limited', null, 'https://brightonasylum.com/', '2026-09-05T22:12:28.444612+00:00', null, null, '+1-201-716-2827', 'node', 4830873565, 'America/New_York'),
  ('Brownella Cottage', 'brownella-cottage', 'haunted', 40.73298, -82.79176, 'Galion', 'OH', 'Brownella Cottage was built in 1887 and later became the home of Bishop William Montgomery Brown and his wife Ella, with much of the house''s original character and furnishings preserved. The Galion History Center now offers scheduled paranormal investigations and ghost tours in the cottage, including recurring public investigation dates.', 'limited', null, 'https://galion.squarespace.com/paranormal', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bruce Mansion', 'bruce-mansion', 'haunted', 43.21022, -83.07791, 'Burnside Township', 'MI', 'Built in 1876, the Bruce Mansion is a Victorian landmark with decades of local ghost stories and reported paranormal experiences. The current operators lean directly into that reputation with scheduled mystery tours, events and paranormal visits, giving travelers legitimate access without trespassing on the property.', 'limited', null, 'https://www.thebrucemansion.com/', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.thebrucemansion.com/', null, null, null, 'America/Detroit'),
  ('Burial Chamber Haunted House', 'burial-chamber-haunted-house', 'haunted', 44.198521, -88.477679, 'Neenah', 'WI', 'Burial Chamber Haunted Complex is a seasonal Neenah-area destination with several different haunted attractions, including high-intensity walkthroughs and darker maze-style experiences. The complex operates on select fall nights and bundles multiple scares into a single visit.', 'limited', null, 'https://burialchamber.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 655102278, 'America/Chicago'),
  ('Café Lafitte in Exile', 'caf-lafitte-in-exile', 'haunted', 29.9604, -90.0642, 'New Orleans', 'LA', 'This long-running Bourbon Street gay bar has accumulated stories of apparitions associated in local lore with writers and former patrons. It remains an active nightlife business rather than a paranormal attraction.', 'open', null, 'https://www.lafittes.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Calumet Theatre', 'calumet-theatre', 'haunted', 47.24776, -88.45363, 'Calumet', 'MI', 'Opened in 1900 during the Copper Country boom, the ornate Calumet Theatre still hosts performances and scheduled historical tours. Local ghost lore centers on actress Helena Modjeska, whose apparition was reportedly seen by another performer in 1958; the story remains folklore rather than verified history.', 'limited', null, 'https://www.michigan.org/article/trip-idea/incredibly-haunted-places-upper-peninsula', '2026-09-08T15:12:49.285859+00:00', null, 'https://calumettheatre.com/', null, null, null, 'America/Detroit'),
  ('Cape Hatteras Lighthouse', 'cape-hatteras-lighthouse', 'haunted', 35.2512, -75.52818, 'Buxton', 'NC', 'The towering black-and-white spiral lighthouse is an Outer Banks icon and the tallest brick lighthouse in the United States. Its surrounding area also carries ghost stories, including tales of a spectral cat and maritime spirits linked with the dangerous waters of the Graveyard of the Atlantic.', 'limited', null, 'https://www.nps.gov/caha/planyourvisit/chls.htm', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain Daniel Packer Inne', 'captain-daniel-packer-inne', 'haunted', 41.35093, -71.97213, 'Mystic', 'CT', 'A 1756 waterfront building now operates as a restaurant and pub while preserving centuries of Mystic history. Local haunting stories include a young girl on the staircase and other unexplained activity, making it an unusually easy paranormal stop where visitors can simply book a meal.', 'open', null, 'https://www.hauntedplaces.org/item/captain-daniel-packer-inne/', '2026-09-08T18:47:23.721893+00:00', null, 'https://danielpacker.com/', null, null, null, 'America/New_York'),
  ('Captain Grant''s 1754', 'captain-grants-1754', 'haunted', 41.48579, -72.03961, 'Preston', 'CT', 'This operating eighteenth-century inn openly embraces its reputation as one of Connecticut''s haunted lodgings. Guests and investigators have reported apparitions, knocking, moving objects and activity associated with the Adelaide Room, while old cemeteries immediately around the property deepen the atmosphere.', 'limited', null, 'https://www.hauntedplaces.org/item/captain-grants-inn/', '2026-09-08T18:47:23.721893+00:00', null, 'https://captaingrants.com/', null, null, null, 'America/New_York'),
  ('Captain Tony''s Saloon', 'captain-tonys-saloon', 'haunted', 24.55815, -81.80566, 'Key West', 'FL', 'Former morgue and icehouse built around a hanging tree, packed with ghost stories and old graves.', 'limited', null, 'https://www.capttonyssaloon.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carnegie Hall', 'carnegie-hall', 'haunted', 37.80212, -80.44822, 'Lewisburg', 'WV', 'Built in 1902, Lewisburg''s Carnegie Hall has accumulated reports of footsteps, whispers, lights and other unexplained activity inside the historic arts venue. It remains an operating performance hall, so visitors should attend a scheduled event or view the exterior rather than treating it as an unrestricted investigation site.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Casey''s Cottage at Mexico Point', 'caseys-cottage-at-mexico-point', 'haunted', 43.51968, -76.25514, 'Mexico', 'NY', 'Dr. William Casey transformed this former carriage house into an elaborate medieval-style cottage before his death in 1978. Later visitors reported organ music, cries for help, moving furniture and the apparition of a young girl; tours, ghost hunts and investigations are arranged by reservation at Mexico Point State Park.', 'limited', null, 'https://hauntedhistorytrail.com/explore/caseys-cottage-at-mexico-point-state-park', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cassadaga Spiritualist Camp', 'cassadaga-spiritualist-camp', 'haunted', 28.96672, -81.23528, 'Cassadaga', 'FL', 'Historic community founded by Spiritualists, still known for mediums, séances, and metaphysical practice.', 'open', null, 'https://www.cassadaga.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ceely Rose House at Malabar Farm', 'ceely-rose-house-at-malabar-farm', 'haunted', 40.65021, -82.39502, 'Monroe Township', 'OH', 'In 1896, Celia "Ceely" Rose poisoned her parents and brother at the family home in Pleasant Valley after becoming fixated on a local man, creating one of Richland County''s most infamous stories. The house survives within Malabar Farm State Park and can be viewed from the park road or walking route, but the interior is not open to the public; local tradition also associates the house and nearby cemetery with Ceely''s ghost.', 'limited', null, 'https://malabarfarm.org/local-history/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chaos Haunted House', 'chaos-haunted-house', 'haunted', 33.624571, -85.10171, 'Carrollton', 'GA', 'Chaos Haunted House was a seasonal Carrollton-area haunt featuring actors, dark walk-through spaces and outdoor scares. I could not verify a current 2026 operating season, so it should not be presented to travelers as an active attraction without new confirmation.', 'closed', null, 'https://www.openstreetmap.org/way/981710792', null, null, null, null, 'way', 981710792, 'America/New_York'),
  ('Chesnut House', 'chesnut-house', 'haunted', 37.28889, -83.79631, 'Manchester', 'KY', 'The Chesnut House is an early twentieth-century residence that has become one of southeastern Kentucky''s dedicated paranormal-tourism stops. Investigators report voices, footsteps and apparitions, and the property has hosted scheduled tours and investigations rather than functioning as an abandoned legend-tripping site. Address: 32 Ells Branch Rd., Manchester, KY', 'limited', null, 'https://www.kentuckyafterdark.com/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chicago Water Tower', 'chicago-water-tower', 'haunted', 41.89717, -87.62444, 'Chicago', 'IL', 'One of the few structures to survive the Great Chicago Fire, later wrapped into local ghost stories involving a spectral hanging figure.', 'open', null, 'https://www.choosechicago.com/blog/tours-attractions/chicago-most-haunted-places/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cincinnati Music Hall', 'cincinnati-music-hall', 'haunted', 39.10939, -84.51922, 'Cincinnati', 'OH', 'Cincinnati Music Hall opened in 1878 and remains one of the city''s major performance venues, but its long history has also produced persistent stories of apparitions and unexplained activity. The building can be entered for performances and official tours, including occasional behind-the-scenes experiences that discuss its unusual history.', 'open', null, 'https://www.cincinnatiarts.org/plan-your-visit/visit-music-hall/tours-1', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Collingwood Arts Center', 'collingwood-arts-center', 'haunted', 41.66874, -83.55621, 'Toledo', 'OH', 'The massive building now known as the Collingwood Arts Center began as a convent and school complex associated with the Ursuline order and later became an arts facility. Its old dormitories, theater and corridors have generated enough paranormal reports that the center offers scheduled public and private ghost hunts; tours and investigations require arranging access rather than wandering the building.', 'limited', null, 'https://www.collingwoodartscenter.org/services', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Colonel Davenport House', 'colonel-davenport-house', 'haunted', 41.51939, -90.55636, 'Rock Island Arsenal', 'IL', 'The 1830s home of fur trader George Davenport stands on Arsenal Island, where his 1845 murder became part of local ghost lore.', 'limited', null, 'https://www.davenporthouse.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Congleton Building', 'congleton-building', 'haunted', 37.57121, -83.70601, 'Beattyville', 'KY', 'The Congleton Building began as a hardware business but also provided undertaking services, with bodies reportedly moved upstairs by a hand-cranked elevator for embalming. Kentucky After Dark features the building for its funeral history and reported paranormal activity; it now contains offices, so access should be limited to advertised tours or events. Address: 203 Main St., Beattyville, KY', 'limited', null, 'https://www.kentuckyafterdark.com/locations/beattyville-lee-county-ky', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Congress Plaza Hotel', 'congress-plaza-hotel', 'haunted', 41.87508, -87.62484, 'Chicago', 'IL', 'One of Chicago''s best-known haunted hotels, tied to decades of ghost stories, unexplained sightings, and dark tales surrounding its long history.', 'limited', null, 'https://www.congressplazahotel.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cooch''s Bridge Historic Site', 'coochs-bridge-historic-site', 'haunted', 39.64017, -75.7374, 'Newark', 'DE', 'The only Revolutionary War battle fought in Delaware took place around Cooch''s Bridge. State folklore sources also preserve the story of a headless soldier said to haunt the area after being decapitated by a cannonball; the historical site itself has controlled visitor access.', 'limited', null, 'https://dnrec.delaware.gov/outdoor-delaware/unveiling-delawares-dark-secrets-exploring-the-haunted-fort-delaware-and-beyond/', '2026-09-08T18:31:51.932734+00:00', null, 'https://history.delaware.gov/coochs-bridge-historic-site/', null, null, null, 'America/New_York'),
  ('Cresson Sanatorium and Prison', 'cresson-sanatorium-and-prison', 'haunted', 40.4563, -78.5642, 'Lilly', 'PA', 'This sprawling mountaintop complex began as a tuberculosis sanatorium, later became a state hospital and then a prison before closing in 2013. Its empty cellblocks, medical buildings and tunnels are now used for scheduled historical tours, photography and paranormal investigations; the property is controlled and should never be entered outside an authorized event.', 'limited', null, 'https://www.atlasobscura.com/places/cresson-sanatorium-and-prison', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crybaby Bridge — Old High Shoals Road Bridge', 'crybaby-bridge-old-high-shoals-road-bridge', 'haunted', 34.44718, -82.60219, 'Anderson', 'SC', 'An abandoned iron truss bridge sits beside the modern High Shoals Road crossing and has become one of South Carolina''s better-known "Crybaby Bridge" legend sites. Local stories describe a woman in white appearing on or near the old bridge while searching for someone, although the haunting is folklore rather than documented history. View the old structure only from safe, lawful public areas and do not climb onto the abandoned bridge. Coordinate check: https://maps.apple.com/place?place-id=ID331ABBFDABFF029', 'roadside', null, 'https://www.hauntedplaces.org/item/cry-baby-bridge-2/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Culbertson Mansion', 'culbertson-mansion', 'haunted', 38.2864, -85.8128, 'New Albany', 'IN', 'Industrialist William Culbertson began building this elaborate Second Empire mansion in 1867, filling it with ornate woodwork, painted ceilings and other high Victorian details. The state historic site is also widely associated with local haunting stories and seasonal paranormal programming, giving visitors a legitimate way to experience the building rather than approaching a private haunted house.', 'limited', null, 'https://www.in.gov/history/state-historical-markers/find-a-marker/culbertson-mansion/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.indianamuseum.org/historic-sites/culbertson-mansion/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Dark Chambers Haunted Attraction', 'dark-chambers-haunted-attraction', 'haunted', 42.555348, -90.61058, 'Hazel Green', 'WI', 'Dark Chambers is a seasonal haunted attraction in Hazel Green offering multiple themed walkthroughs at one location. The current official address is in Hazel Green, not Jamestown, so the city in the existing OddWay record should be corrected.', 'limited', null, 'https://darkchambers.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.darkchambers.com/', '+1-563-239-0367', 'node', 13891305702, 'America/Chicago'),
  ('Dartford Cemetery', 'dartford-cemetery', 'haunted', 43.8522, -88.96538, 'Green Lake', 'WI', 'This historic cemetery has become one of Green Lake''s best-known paranormal folklore locations, with stories of strange lights, apparitions and unexplained sounds. The claims remain local legend, but the cemetery itself is a real historic site. Visit respectfully during lawful cemetery hours.', 'limited', null, 'https://www.cityofgreenlake.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.cityofgreenlake.com/', null, null, null, 'America/Chicago'),
  ('Dave Push Ghost at Haviland-Davison Mill', 'dave-push-ghost-at-haviland-davison-mill', 'haunted', 40.63976, -73.65954, 'East Rockaway', 'NY', 'Local boatman David "Dave Push" Terrell was found dead in the water in 1910, and folklore says his spirit later haunted the Haviland-Davison Mill. The historic mill was moved to Memorial Park in 1963 and is now a museum, with a Legends & Lore marker preserving the ghost story.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/dave-push/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dead Children’s Playground — Maple Hill Cemetery', 'dead-childrens-playground-maple-hill-cemetery', 'haunted', 34.73148, -86.56519, 'Huntsville', 'AL', 'Behind Maple Hill Cemetery, a small playground has become one of Huntsville’s best-known ghost-story locations, with local tales of children’s apparitions and swings moving on their own. The supernatural claims are folklore, not established fact; visit only during lawful cemetery/park hours and remain respectful of graves and mourners.', 'limited', null, 'https://alabama.travel/article/the-most-haunted-places-in-alabama', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dells Ghost Boat', 'dells-ghost-boat', 'haunted', 43.62794, -89.77825, 'Wisconsin Dells', 'WI', 'This nighttime attraction carries visitors by boat into the sandstone landscape of the Wisconsin Dells before continuing through dark wooded and canyon environments built around regional ghost stories. It is a ticketed seasonal experience rather than an unsupervised haunted-location visit.', 'limited', null, 'https://www.dellsghostboat.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.dellsghostboat.com/', null, null, null, 'America/Chicago'),
  ('Demon Murder Trial Sites', 'demon-murder-trial-sites', 'haunted', 41.39046, -73.44739, 'Danbury', 'CT', 'Danbury became the center of national attention during the 1981 murder trial of Arne Cheyenne Johnson, whose defense attempted to argue that demonic possession played a role in the killing. The court rejected possession as a legal defense, but the case became one of Connecticut''s most famous intersections of true crime and paranormal belief.', 'roadside', null, 'https://www.atlasobscura.com/places/demon-murder-trial-sites', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('DeSoto House Hotel', 'desoto-house-hotel', 'haunted', 42.41467, -90.42968, 'Galena', 'IL', 'Illinois'' oldest operating hotel hosted Abraham Lincoln and Ulysses S. Grant and carries a substantial body of guest and staff ghost lore.', 'limited', null, 'https://desotohouse.com/hotel-history/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Doctor Morbid''s Haunted House', 'doctor-morbid-s-haunted-house', 'haunted', 43.422529, -73.714346, 'Village of Lake George', 'NY', 'Doctor Morbid''s Haunted House was a long-running Lake George walk-through horror attraction with animated figures and mad-scientist-themed scenes. The attraction has closed, so it should be removed from current OddWay routing rather than treated as an active stop.', 'closed', null, 'https://www.openstreetmap.org/node/4403648514', null, null, null, null, 'node', 4403648514, 'America/New_York'),
  ('Doherty Hotel', 'doherty-hotel', 'haunted', 43.81998, -84.7681, 'Clare', 'MI', 'The Doherty Hotel has operated since the 1920s and has a documented Prohibition-era history that includes the 1938 killing of Isaiah Leebove, a lawyer and businessman associated with Detroit underworld figures. The active hotel also carries longstanding ghost stories involving Leebove and members of the Doherty family, though those paranormal claims remain anecdotal.', 'open', null, 'https://www.michigan.org/article/trip-idea/look-haunted-places-michigan', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Drish House', 'drish-house', 'haunted', 33.19755, -87.56185, 'Tuscaloosa', 'AL', 'This distinctive Greek Revival and Italianate mansion is tied to long-running local stories of phantom lights and unexplained activity, often connected to the deaths of Dr. John Drish and his wife Sarah. It operates as a private event venue, so interior access requires permission or a scheduled event.', 'limited', null, 'https://historictuscaloosa.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dungeon Rock', 'dungeon-rock', 'haunted', 42.47505, -70.98611, 'Lynn', 'MA', 'Spiritualist Hiram Marble spent decades tunneling into a rock formation because he believed the ghost of pirate Thomas Veale was directing him toward buried treasure. Marble and his son died without finding it, but their narrow 135-foot excavation still exists in Lynn Woods and opens on a limited schedule.', 'limited', null, 'https://www.atlasobscura.com/places/dungeon-rock', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dunkirk Lighthouse', 'dunkirk-lighthouse', 'haunted', 42.4936, -79.3537, 'Dunkirk', 'NY', 'The Dunkirk light station dates to 1827, with the present Victorian keeper''s house and tower preserving maritime and military history along Lake Erie. Reports include footsteps, voices, humming and unexplained touches inside the keeper''s house and tower; the site operates as a museum and also schedules paranormal investigations.', 'open', null, 'https://hauntedhistorytrail.com/explore/dunkirk-historical-lighthouse-veterans-park-museum', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Earnestine & Hazel''s', 'earnestine-hazels', 'haunted', 35.13296, -90.05927, 'Memphis', 'TN', 'A former pharmacy and later nightclub became a beloved dive bar with layers of Memphis music, vice and ghost lore. Stories of unexplained jukebox behavior and apparitions are part of its reputation, but the building is best experienced as an operating business with documented history.', 'open', null, 'https://earnestineandhazels.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Eastern State Penitentiary', 'eastern-state-penitentiary', 'haunted', 39.968336, -75.172675, 'Philadelphia', 'PA', 'Eastern State Penitentiary is a preserved 19th-century prison where visitors can explore cell blocks, prison yards and exhibits about incarceration, including Al Capone''s restored cell. The historic site operates as a museum, while separate Halloween programming adds large-scale haunted attractions during the fall.', 'open', null, 'https://www.easternstate.org/', '2026-09-05T22:12:28.444612+00:00', 'Su-Sa 10:00-17:00; Jan 01, Dec 23, Dec 24 off', 'https://www.easternstate.org', null, 'way', 320052082, 'America/New_York'),
  ('Emily''s Bridge', 'emilys-bridge', 'haunted', 44.44023, -72.67998, 'Stowe', 'VT', 'The 1844 Gold Brook covered bridge is better known as Emily''s Bridge because of a local ghost story about a young woman who supposedly died there after being abandoned by her lover. Tales of scratches, voices and other activity are folklore rather than established history, but the bridge remains one of Vermont''s best-known haunted landmarks.', 'open', null, 'https://www.atlasobscura.com/places/emilys-bridge', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Emlen Physick Estate', 'emlen-physick-estate', 'haunted', 38.94034, -74.91478, 'Cape May', 'NJ', 'This 1879 Victorian mansion is preserved as a house museum filled with period architecture and furnishings. Cape May MAC also incorporates the estate into ghost-themed programming built around local reports and legends associated with the property.', 'limited', null, 'https://capemaymac.org/experience/emlen-physick-estate/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Erie Canal Museum', 'erie-canal-museum', 'haunted', 43.05065, -76.14872, 'Syracuse', 'NY', 'The museum occupies Syracuse''s 1850 Weighlock Building, the only surviving canal weighlock structure of its kind. Stories associated with the building include apparitions, footsteps and voices, while visitors can normally explore the canal exhibits during regular museum hours.', 'open', null, 'https://hauntedhistorytrail.com/explore/erie-canal-museum', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Estate of Evil at Hersheypark Dark Nights', 'estate-of-evil', 'haunted', 40.291262, -76.655507, 'Derry Township', 'PA', 'Estate of Evil is a haunted-house experience inside Hersheypark Dark Nights, taking visitors through a sinister mansion filled with themed rooms and live scares. It is part of the amusement park''s fall event rather than a separate attraction, so access requires the appropriate Hersheypark/Dark Nights admission.', 'limited', null, 'https://www.hersheypark.com/darknights/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 12995085649, 'America/New_York'),
  ('Exchange Hotel Civil War Medical Museum', 'exchange-hotel-civil-war-medical-museum', 'haunted', 38.13266, -78.18566, 'Gordonsville', 'VA', 'The Exchange Hotel became a receiving hospital during the Civil War and treated tens of thousands of sick and wounded soldiers before later serving other purposes. Today it operates as a museum with medical and wartime displays, while reported apparitions, voices and unexplained activity have made it a frequent paranormal destination.', 'open', null, 'https://www.theexchangehotelmuseum.org/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fairfield County Infirmary', 'fairfield-county-infirmary', 'haunted', 39.7394, -82.5881, 'Lancaster', 'OH', 'The former Fairfield County Infirmary is a large institutional building associated with generations of poor-farm and county-home residents. It now operates as a paranormal and historical venue offering scheduled tours, photography sessions, public ghost hunts and private investigations rather than everyday walk-in access.', 'limited', null, 'https://visitfairfieldcounty.org/listings/fairfield-county-infirmary/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fairport Harbor Ghost Cat Lighthouse', 'fairport-harbor-ghost-cat-lighthouse', 'haunted', 41.75709, -81.27734, 'Fairport Harbor', 'OH', 'The 1871 Fairport Harbor lighthouse and keeper''s house now operate as a seasonal marine museum, but their strangest resident is said to be a ghostly gray cat seen darting through the former living quarters. During renovation work, a mummified gray cat was found in a crawl space and is now part of the museum''s story; the museum and tower are seasonal.', 'limited', null, 'https://en.wikipedia.org/wiki/Fairport_Harbor_Light', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ferry Plantation House', 'ferry-plantation-house', 'haunted', 36.86194, -76.11806, 'Virginia Beach', 'VA', 'The current Federal-style house dates to about 1830 on a property whose history reaches back to a 17th-century ferry and an earlier courthouse site near the famous Grace Sherwood witch trial. It operates as a historic house museum on limited weekly tour hours and has also become well known locally for reported paranormal activity.', 'limited', null, 'https://www.visitvirginiabeach.com/listing/ferry-plantation-house/531/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fiddler''s Ghost', 'fiddlers-ghost', 'haunted', 41.87079, -73.8365, 'Staatsburg', 'NY', 'A local fiddler was reportedly robbed and murdered on a bridge here in September 1808. The bridge is gone, but folklore says his music can still be heard on moonlit nights, and a roadside Legends & Lore marker identifies the site.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/fiddlers-ghost/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('First Spiritualist Temple', 'first-spiritualist-temple', 'haunted', 42.35058, -71.07986, 'Boston', 'MA', 'A Romanesque building in Back Bay was constructed for a Spiritualist congregation during the movement''s nineteenth-century boom. Its history reflects the period when séances, spirit communication and Spiritualism became organized religious practices in New England.', 'roadside', null, 'https://www.atlasobscura.com/places/first-spiritualist-temple', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Delaware', 'fort-delaware', 'haunted', 39.58944, -75.56741, 'Delaware City', 'DE', 'The massive Civil War-era fortress on Pea Patch Island served as a prison for Confederate soldiers and is one of Delaware''s best-known haunted locations. State sources and the site''s own programming openly document its ghost lore and paranormal-tour reputation; access requires the seasonal ferry.', 'limited', null, 'https://dnrec.delaware.gov/outdoor-delaware/unveiling-delawares-dark-secrets-exploring-the-haunted-fort-delaware-and-beyond/', '2026-09-08T18:31:51.932734+00:00', null, 'https://destateparks.com/FortDelaware', null, null, null, 'America/New_York'),
  ('Fort East Martello Museum', 'fort-east-martello-museum', 'haunted', 24.55273, -81.75514, 'Key West', 'FL', 'Civil War-era fort museum best known as the home of Robert the Doll.', 'limited', null, 'https://www.kwahs.org/museums/fort-east-martello', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Mifflin', 'fort-mifflin', 'haunted', 39.87545, -75.21289, 'Philadelphia', 'PA', 'Fort Mifflin is a surviving Revolutionary-era fort on the Delaware River and saw intense bombardment during the 1777 defense of Philadelphia. The historic site is open for tours and events and has also developed a major paranormal reputation involving voices, footsteps and apparitions reported in its old barracks and casemates.', 'open', null, 'https://www.fortmifflin.us/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Ontario''s Post Ghost', 'fort-ontarios-post-ghost', 'haunted', 43.46454, -76.50697, 'Oswego', 'NY', 'Fort Ontario''s best-known ghost is George Fikes, a British soldier who died there in 1782 and is said to continue guarding the fort with a red lantern. The state historic site preserves the fort and its underground passages, while a Legends & Lore marker specifically records the Post Ghost story.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/the-post-ghost/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fox Sisters Property / Hydesville Memorial Park', 'fox-sisters-property-hydesville-memorial-park', 'haunted', 43.0705, -77.10768, 'Newark', 'NY', 'Maggie and Kate Fox reported mysterious rapping sounds here in 1848 and became central figures in the rise of modern Spiritualism. The original cottage is gone but its foundation remains inside Hydesville Memorial Park; the park itself is open to visitors while access to the enclosure and guided interpretation may require the caretaker.', 'limited', null, 'https://hauntedhistorytrail.com/explore/the-fox-sisters-propertyhydesville-memorial-park', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Franklin Castle', 'franklin-castle', 'haunted', 41.48611, -81.71611, 'Cleveland', 'OH', 'Built for German immigrant Hannes Tiedemann in the early 1880s, Franklin Castle became one of Cleveland''s most persistent haunted-house legends after a series of deaths and later stories of apparitions and hidden rooms. The restored private venue offers scheduled tours, storytelling events and overnight experiences, but it is not a casual walk-in attraction.', 'limited', null, 'https://thefranklincastle.com/stay-the-night/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frenier Cemetery', 'frenier-cemetery', 'haunted', 30.09303, -90.43274, 'LaPlace', 'LA', 'The isolated cemetery is tied to local stories about Julia Brown, a supposed folk healer whose death was later connected in legend with the devastating 1915 hurricane. The site is not a casual roadside cemetery; access is typically through authorized swamp-tour property arrangements.', 'limited', null, 'https://www.cajunprideswamptours.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fright Factory Haunted House', 'fright-factory-haunted-house', 'haunted', 47.165644, -122.000647, 'Buckley', 'WA', 'Fright Factory is a seasonal Buckley haunted house set in a secluded property and built around dark indoor scenes, actors and traditional Halloween scares. It operates on select nights in the fall rather than as a year-round destination.', 'limited', null, 'https://frightfactory.net/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.frightfactory.net', null, 'way', 753445391, 'America/Los_Angeles'),
  ('Fright Kingdom', 'fright-kingdom', 'haunted', 42.75151, -71.49023, 'Nashua', 'NH', 'Fright Kingdom is an indoor haunted attraction complex built around multiple themed environments, monsters and elaborate sets. The 2026 schedule includes its main Halloween season from late September through October with additional special events later in the year. Admission is ticketed and dates vary by event.', 'limited', null, 'https://frightkingdom.com/hours/', '2026-09-09T04:49:39.808526+00:00', null, 'https://frightkingdom.com/', null, null, null, 'America/New_York'),
  ('Frightland and Idalia Manor', 'frightland-and-idalia-manor', 'haunted', 39.54021, -75.64695, 'Middletown', 'DE', 'Frightland surrounds the historic Idalia Manor with a large seasonal haunted-attraction complex containing multiple horror experiences. The mid-1800s manor is a genuine historic structure incorporated into the attraction, while the elaborate horror mythology surrounding the event is theatrical entertainment rather than documented history. It normally operates during the Halloween season.', 'limited', null, 'https://frightland.com/', '2026-09-08T18:31:51.932734+00:00', null, 'https://frightland.com/', null, null, null, 'America/New_York'),
  ('Funland Haunted Mansion', 'funland-haunted-mansion', 'haunted', 38.71447, -75.07629, 'Rehoboth Beach', 'DE', 'Funland’s Haunted Mansion is a classic boardwalk dark ride known for its unusual hanging ride vehicles and generations of handmade scares. The original version is in its final operating season in 2026, with the attraction scheduled to close for 2027 while a reimagined Haunted Mansion is developed for a planned 2028 debut. Check current operating dates before routing travelers here.', 'limited', null, 'https://funlandrehoboth.com/mansion-updates', '2026-09-08T18:31:51.932734+00:00', null, 'https://funlandrehoboth.com/', null, null, null, 'America/New_York'),
  ('Gadsby''s Tavern Museum', 'gadsbys-tavern-museum', 'haunted', 38.80561, -77.04364, 'Alexandria', 'VA', 'These historic tavern buildings hosted travelers, political figures and social events in early Alexandria and are now preserved as a city museum. The site is also bound to the Female Stranger mystery, whose unidentified young woman allegedly died here in 1816 and is said in local lore to still haunt the building.', 'open', null, 'https://www.alexandriava.gov/museums/location/visit-gadsbys-tavern-museum', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('General Nathanael Greene Homestead', 'general-nathanael-greene-homestead', 'haunted', 41.69389, -71.54413, 'Coventry', 'RI', 'The 1770 homestead of Revolutionary War General Nathanael Greene preserves period rooms and artifacts connected to one of Rhode Island''s most important military figures. Visitors and paranormal groups have also reported footsteps, voices and other unexplained experiences in and around the house, though these remain folklore rather than verified phenomena. Tours operate on a limited schedule.', 'limited', null, 'https://www.rimonthly.com/haunted-places-rhode-island/', '2026-09-09T04:49:27.913704+00:00', null, 'https://nathanaelgreenehomestead.org/', null, null, null, 'America/New_York'),
  ('GHOST LIGHT at Jean''s Playhouse', 'ghost-light-at-jeans-playhouse', 'haunted', 44.03999, -71.66851, 'Lincoln', 'NH', 'Jean''s Playhouse turns its theater into an immersive walk-through horror experience called GHOST LIGHT. The 2026 event is scheduled for selected nights from October 9 through October 31 and uses theatrical performers, sets and effects rather than a conventional stage show. Tickets and age recommendations should be checked before visiting.', 'limited', null, 'https://www.visitnh.gov/things-to-do/events-calendar/ghost-light-a-haunting-experience', '2026-09-09T04:49:39.808526+00:00', null, 'https://jeansplayhouse.com/project/ghost-light/', null, null, null, 'America/New_York'),
  ('Ghost Tours of Harpers Ferry', 'ghost-tours-of-harpers-ferry', 'haunted', 39.32282, -77.73116, 'Harpers Ferry', 'WV', 'This guided walking tour uses the historic streets around Harpers Ferry to tell local ghost stories, Civil War tales and legends attached to the town''s old buildings. Tours meet near St. Peter''s Roman Catholic Church and run on a scheduled basis, so reservations are recommended.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ghost Tours of Historic Frederick', 'ghost-tours-of-historic-frederick', 'haunted', 39.4162, -77.4104, 'Frederick', 'MD', 'This long-running walking tour uses downtown Frederick''s wars, executions and local tragedies as the background for documented paranormal stories. Tours depart on scheduled evenings from the Market Street area and require a ticket or reservation.', 'limited', null, 'https://www.visitfrederick.org/event/ghost-tours-of-historic-frederick/24999/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ghostly Friendship at Historic Richmond Town', 'ghostly-friendship-at-historic-richmond-town', 'haunted', 40.57138, -74.14743, 'Staten Island', 'NY', 'A Staten Island legend tells of a Hessian drummer named Ernest and a young Van Pelt girl called Pretty who became friends in 1776 and died the same year. Stories claim drumbeats, footsteps and the girl''s apparition can still be encountered around the historic house, and a Legends & Lore marker records the tale at Historic Richmond Town.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/ghostly-friendship/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ghosts of Annapolis Tour', 'ghosts-of-annapolis-tour', 'haunted', 38.97756, -76.48768, 'Annapolis', 'MD', 'Annapolis ghost walks take visitors through the old waterfront and colonial core for stories involving historic taverns, pirates, former residents and reported hauntings. The current tour meets around Market Space on scheduled evenings, so this is a ticketed tour rather than an always-open attraction.', 'limited', null, 'https://www.visitmaryland.org/events/ashes-and-apparitions-annapolis-ghost-tour', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gilson Road Cemetery', 'gilson-road-cemetery', 'haunted', 42.71628, -71.513, 'Nashua', 'NH', 'This small historic cemetery has developed an outsized reputation among New Hampshire ghost hunters. Reported experiences include mist-like figures, a sensation compared with walking through water and sightings of a dark hooded form. The claims are unverified folklore, and the cemetery should be visited quietly and only during permitted hours.', 'limited', null, 'https://www.hauntedplaces.org/item/gilson-road-cemetery/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Glenn Dale Hospital', 'glenn-dale-hospital', 'haunted', 38.96286, -76.80991, 'Glenn Dale', 'MD', 'Opened in 1934 as a tuberculosis sanatorium for Washington, D.C., Glenn Dale later served other patients before closing in 1982. Its abandoned hospital buildings have become a major source of local ghost stories, but entering the structures is prohibited; view them only from legal public roads and trails.', 'roadside', null, 'https://www.atlasobscura.com/places/glenn-dale-hospital', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Golden Lamb Ghosts', 'golden-lamb-ghosts', 'haunted', 39.4336, -84.20846, 'Lebanon', 'OH', 'The Golden Lamb has operated in Lebanon since 1803 and is Ohio''s longest continually operating business, with a restaurant, guestrooms and fourth-floor historical displays. Staff and guests have long reported apparitions associated with figures including Sarah Stubbs and politician Clement Vallandigham, who accidentally shot himself at the inn in 1871; the property itself publishes and preserves these ghost stories.', 'open', null, 'https://www.goldenlamb.com/news/does-the-golden-lamb-have-ghostly-uninvited-guests/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Goodleburg Cemetery', 'goodleburg-cemetery', 'haunted', 42.71406, -78.53754, 'Wales', 'NY', 'This inactive town-owned cemetery dates to 1811 and became notorious in the late twentieth century for stories of apparitions and other paranormal activity. Ghost hunters also caused serious vandalism here, so visit only during lawful cemetery access, remain within the grounds and treat the surviving graves with particular care.', 'open', null, 'https://en.wikipedia.org/wiki/Goodleburg_Cemetery', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Governor William Sprague Mansion', 'governor-william-sprague-mansion', 'haunted', 41.79075, -71.45635, 'Cranston', 'RI', 'This nineteenth-century mansion was home to industrialist and Civil War-era Rhode Island governor William Sprague. Its long history, family tragedies and preserved interiors have produced decades of local ghost stories and reported paranormal encounters. The Cranston Historical Society opens the property for tours and special events rather than daily visitation.', 'limited', null, 'https://www.cranstonhistory.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.cranstonhistory.org/', null, null, null, 'America/New_York'),
  ('Gretchen''s Lock', 'gretchens-lock', 'haunted', 40.7076, -80.59396, 'St. Clair Township', 'OH', 'Gretchen''s Lock is a surviving ruin of the nineteenth-century Sandy and Beaver Canal inside Beaver Creek State Park. Legend says canal engineer E.H. Gill temporarily entombed his young daughter Gretchen in the lock after her death before attempting to return her body to Europe, and visitors still tell stories of her spirit near the stones; reaching the lock requires a park trail hike.', 'limited', null, 'https://www.carnegie.lib.oh.us/gretchen', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gudgeonville Bridge Ghost Site', 'gudgeonville-bridge-ghost-site', 'haunted', 41.9824, -80.26681, 'Girard Township', 'PA', 'The 1868 Gudgeonville Covered Bridge developed generations of folklore about phantom hoofbeats and ghostly figures around Elk Creek. Arson destroyed the historic covered portion in 2008 and the crossing was rebuilt, so travelers now visit the same folklore location rather than the original covered bridge.', 'roadside', null, 'https://www.eriereader.com/article/the-erie-experience-spooky-urban-legends-folktales-and-lore', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gunntown Cemetery', 'gunntown-cemetery', 'haunted', 41.49088, -73.10427, 'Naugatuck', 'CT', 'This small cemetery dates to around 1790 and is one of Connecticut''s better-known local haunting sites. Stories include a black ghost dog, a lantern-carrying man, a child near the back wall and unexplained music. Treat the reports as folklore and visit respectfully during permitted cemetery hours.', 'limited', null, 'https://www.hauntedplaces.org/item/gunntown-cemetery/', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hamilton Hoppin House', 'hamilton-hoppin-house', 'haunted', 41.50643, -71.29752, 'Middletown', 'RI', 'This Gothic Revival mansion, later known through its use as an inn, has been associated with stories of apparitions and unexplained activity. Its architecture alone gives the property a distinctly haunted-house silhouette, complete with steep gables and elaborate nineteenth-century detailing. It currently operates as lodging, so access should be limited to guests or authorized visits.', 'limited', null, 'https://www.pbs.org/video/3-inn-shadow-lawn-uppfjm/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.thehamiltonhoppinhouse.com/', null, null, null, 'America/New_York'),
  ('Haunted Coal Mine at Hersheypark Dark Nights', 'haunted-coal-mine', 'haunted', 40.288598, -76.653548, 'Derry Township', 'PA', 'Haunted Coal Mine is a mine-themed walk-through haunt included in Hersheypark''s Dark Nights event. Visitors encounter underground-style sets, actors and horror scenes during select autumn event nights, not as a year-round standalone coal-mine attraction.', 'limited', null, 'https://www.hersheypark.com/darknights/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 12994423868, 'America/New_York'),
  ('Haunted Elm Building', 'haunted-elm-building', 'haunted', 37.83937, -87.59032, 'Henderson', 'KY', 'The three-story building at 120 N. Elm Street has been featured by Kentucky After Dark for stories involving shadow figures, voices, a mysterious bell and other reported activity. The retail business formerly known as The Elm moved away from this address in 2025, so OddWay should treat the historic haunted building itself as an exterior stop unless a current tenant advertises public access.', 'roadside', null, 'https://www.kentuckyafterdark.com/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Haunted Forest At Panic Point', 'haunted-forest-at-panic-point', 'haunted', 36.028109, -78.459502, 'Youngsville', 'NC', 'Panic Point is a large seasonal outdoor haunt built around a wooded property near Youngsville, with a haunted forest and a rotating lineup of trails, mazes and other scare experiences. It operates on select fall nights and tickets are tied to the Halloween season.', 'limited', null, 'https://raleighhauntedhouse.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://raleighhauntedhouse.com', null, 'node', 5390039038, 'America/New_York'),
  ('Haunted Halloween House at Land of Make Believe', 'haunted-halloween-house', 'haunted', 40.901362, -74.95719, 'Hope Township', 'NJ', 'The Haunted Halloween House is part of the Land of Make Believe amusement park rather than a standalone New Jersey haunted attraction. Visitors encounter Halloween-themed characters and spooky scenes as one attraction within the larger seasonal family park.', 'limited', null, 'https://www.lomb.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 260858515, 'America/New_York'),
  ('Haunted Hollow', 'haunted-hollow', 'haunted', 38.693255, -77.778469, 'Warrenton', 'VA', 'Haunted Hollow at Maple Tree Farm is a seasonal Virginia haunted trail that leads visitors through wooded paths, barns and farm settings populated by live scare actors. It operates on selected fall nights and requires visitors to follow the event''s ticketing and safety rules.', 'limited', null, 'https://hauntedhollowva.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://hauntedhollowva.com', '+1 703-596-5113', 'node', 9597842952, 'America/New_York'),
  ('Haunted Hootchie', 'haunted-hootchie', 'haunted', 39.990871, -82.74832, 'Pataskala', 'OH', 'Haunted Hootchie at Dead Acres is an intense, adult-oriented Ohio haunted attraction known for large sets, live performers and deliberately extreme horror imagery. It is a seasonal fall destination and should be treated as limited access outside its posted operating nights.', 'limited', null, 'https://www.hauntedhootchie.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 3118461459, 'America/New_York'),
  ('Haunted House at Little Amerricka', 'haunted-house', 'haunted', 43.163323, -89.059251, 'Marshall', 'WI', 'This Haunted House is a dark ride inside Little Amerricka Amusement Park in Marshall, not a standalone Halloween haunt. Visitors board a ride vehicle and pass through old-school spooky scenes and effects during the amusement park''s operating season.', 'limited', null, 'https://www.littleamerricka.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 514606719, 'America/Chicago'),
  ('Haunted House of Wax', 'haunted-house-of-wax', 'haunted', 43.08584, -79.063278, 'City of Niagara Falls', 'NY', 'Haunted House of Wax was a Niagara Falls walk-through attraction mixing wax figures with horror scenes and jump scares. It is reported closed, so the record should be removed from active routing rather than presented as a current attraction.', 'closed', null, 'https://www.roadsideamerica.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 3964938709, 'America/New_York'),
  ('Knoebels Haunted Mansion', 'haunted-mansion', 'haunted', 40.879976, -76.505058, 'Ralpho Township', 'PA', 'The Haunted Mansion in Ralpho Township is the classic dark ride at Knoebels Amusement Resort, not a standalone haunted house. Riders travel through old-school spooky sets, practical effects and monsters whenever the ride is operating during the park''s season.', 'limited', null, 'https://www.knoebels.com/rides/haunted-mansion/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 3700461518, 'America/New_York'),
  ('Haunted Margaritas — Former Concord Jail', 'haunted-margaritas-former-concord-jail', 'haunted', 43.20496, -71.53663, 'Concord', 'NH', 'This Margaritas restaurant occupies Concord''s former police station and jail, and several old cells remain incorporated into the dining area. Local ghost stories describe a presence nicknamed "George," and paranormal investigators have visited the building. Even without the haunting claims, eating inside preserved jail cells makes it an unusually tangible stop.', 'open', null, 'https://www.atlasobscura.com/places/haunted-margaritas', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.margs.com/locations/concord/', null, null, null, 'America/New_York'),
  ('Bloody Mary''s Haunted Museum & Voodoo Shop', 'haunted-museum-voodoo-pharmacy', 'haunted', 29.961754, -90.067069, 'New Orleans', 'LA', 'Bloody Mary''s Haunted Museum & Voodoo Shop combines New Orleans paranormal history, occult objects, haunted artifacts, dolls and Voodoo-related displays in a small museum and shop. Daytime museum visits are supplemented by scheduled ghost hunts and paranormal investigations after hours.', 'open', null, 'https://www.bloodymarystours.com/hauntedmuseum.html', '2026-09-05T22:12:28.444612+00:00', 'Mo-Fr 12:00-17:00; Sa-Su 12:00-18:00', null, null, 'node', 6559071386, 'America/Chicago'),
  ('Haunted Overload', 'haunted-overload', 'haunted', 43.15699, -70.96663, 'Lee', 'NH', 'Haunted Overload transforms the woods of DeMeritt Hill Farm into a large-scale outdoor haunt filled with elaborate handmade sets, towering monsters and theatrical lighting. It has become one of New Hampshire''s best-known seasonal Halloween attractions. Admission is ticketed and operations are limited to the fall season.', 'limited', null, 'https://hauntedoverload.com/', '2026-09-09T04:49:39.808526+00:00', null, 'https://hauntedoverload.com/', null, null, null, 'America/New_York'),
  ('Haunted Picnic Table 29', 'haunted-picnic-table-29', 'haunted', 34.137186, -118.306787, 'Los Angeles', 'CA', 'Picnic Table 29 in Griffith Park is the subject of a Los Angeles urban legend involving a couple reportedly killed by a falling tree, with the damaged table and tree becoming an eerie hiking destination. Visitors reach the area on foot through Griffith Park, so this is a strange outdoor legend stop rather than a staffed attraction.', 'open', null, 'https://www.pinintheatlas.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://pinintheatlas.com/travel-blogs/haunted-picnic-table-29-griffith-park-california/', null, 'node', 11608850025, 'America/Los_Angeles'),
  ('Haunted Tales', 'haunted-tales', 'haunted', 39.356755, -74.427196, 'Atlantic City', 'NJ', 'Haunted Tales was an Atlantic City horror attraction built around spooky stories, theatrical effects and novelty scares. Current operation could not be reliably confirmed, and older haunt listings suggest the business is no longer a dependable active attraction, so it should remain unpublished until verified.', 'closed', null, 'https://www.hauntworld.com/haunted-house-in-atlantic-city-new-jersey-haunted-tales', null, null, null, null, 'way', 539916275, 'America/New_York'),
  ('Haunted Town Hall', 'haunted-town-hall', 'haunted', 40.759125, -83.948266, 'Lafayette', 'OH', 'Haunted Town Hall transforms Lafayette''s old town hall into a multi-level seasonal haunted attraction filled with actors, dark corridors and themed rooms. It operates on select September and October nights rather than year-round.', 'limited', null, 'https://hauntedtownhall.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://hauntedtownhall.com/', null, 'way', 703782669, 'America/New_York'),
  ('Haunted Trails', 'haunted-trails', 'haunted', 41.55012, -88.088541, 'Joliet', 'IL', 'Haunted Trails Joliet is a year-round family entertainment center with a Halloween theme, offering attractions such as go-karts, miniature golf, laser tag, rides and an arcade. It is not a seasonal scare haunt, so travelers should expect an amusement center rather than a paranormal or horror experience.', 'open', null, 'https://hauntedtrailsfun.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 495983548, 'America/Chicago'),
  ('Haunted Trails', 'haunted-trails-2', 'haunted', 41.749571, -87.799311, 'Burbank', 'IL', 'Haunted Trails Burbank is a year-round Halloween-themed family entertainment center with miniature golf, go-karts, arcade games, rides and other activities. Despite the spooky branding, it is not a haunted house and is specifically designed as family entertainment.', 'open', null, 'https://hauntedtrailsburbank.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://hauntedtrailsburbank.com/', null, 'way', 909609404, 'America/Chicago'),
  ('Haunted Washoe Club Museum', 'haunted-washoe-club-museum', 'haunted', 39.309319, -119.650222, 'Virginia City', 'NV', 'The Washoe Club is one of Virginia City''s best-known historic saloons and paranormal stops, with a museum and tours exploring the building''s history and reported ghost activity. Visitors can see preserved rooms and displays during regular visits, with more intensive paranormal investigations offered separately.', 'open', null, 'https://thewashoeclubmuseum.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.thewashoeclubmuseum.com/', '+1-775-847-4467', 'node', 4243505100, 'America/Los_Angeles'),
  ('Hazel Drew Ghost Marker', 'hazel-drew-ghost-marker', 'haunted', 42.64404, -73.52709, 'Sand Lake', 'NY', 'Twenty-year-old Hazel Drew was found murdered near Teal''s Pond in 1908, and the case was never solved. Stories of her ghost walking the nearby woods survived for generations and later helped inspire the mystery behind Twin Peaks; a Legends & Lore marker now marks the local story without requiring visitors to enter the woods.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/hazel-drew/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Headless Horseman Hayrides and Haunted Houses', 'headless-horseman-hayrides-and-haunted-houses', 'haunted', 41.851567, -73.972109, 'Town of Esopus', 'NY', 'Headless Horseman Hayrides & Haunted Attractions is a large seasonal Halloween destination in the Hudson Valley combining theatrical hayrides with multiple walk-through haunted attractions. The experience runs on select fall nights and is designed as a full evening horror event.', 'limited', null, 'https://headlesshorseman.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.headlesshorseman.com/', '+1-845-339-2666', 'way', 419550850, 'America/New_York'),
  ('Hearthside House Museum', 'hearthside-house-museum', 'haunted', 41.90675, -71.43014, 'Lincoln', 'RI', 'Built around 1810, Hearthside is a preserved Federal-style mansion filled with period rooms, historic objects and local stories. The house has also developed a reputation for reported footsteps, apparitions and unexplained activity during its long history. Access is through scheduled museum openings, tours and events.', 'limited', null, 'https://greatroadheritagecampus.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://greatroadheritagecampus.org/', null, null, null, 'America/New_York'),
  ('Helen’s Bridge', 'helens-bridge', 'haunted', 35.59547, -82.53806, 'Asheville', 'NC', 'A stone bridge built in 1909 near the Zealandia mansion is tied to one of Asheville’s best-known ghost legends. Folklore says a grieving woman named Helen hanged herself here after losing her daughter and still appears around the bridge; the story is unverified, and visitors should stay on public roads and away from the private mansion. Coordinates: https://maps.apple.com/place?place-id=I380314F2E1C7A93', 'roadside', null, 'https://www.atlasobscura.com/places/helen-s-bridge', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hempfield Tunnel', 'hempfield-tunnel', 'haunted', 40.07285, -80.71221, 'Wheeling', 'WV', 'This former railroad tunnel is now part of Wheeling''s trail system and has become associated with reports of voices, figures and other unexplained activity. It is publicly reachable on the trail, but the tunnel is dark and should be approached with a light and normal trail precautions.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hex House', 'hex-house', 'haunted', 36.081984, -96.047931, 'Tulsa', 'OK', 'Hex House is a Tulsa seasonal haunt with multiple walk-through attractions at one location, loosely drawing its name from the city''s infamous 1940s Hex House story. Visitors come for theatrical horror sets and live scares on select fall nights rather than for access to the original historical Hex House site.', 'limited', null, 'https://hexhouse.com/', '2026-09-05T22:12:28.444612+00:00', '"Tickets required. See website for ticketing information."', 'https://hexhouse.com/', null, 'node', 13719806084, 'America/Chicago'),
  ('Hirschi''s Haunted Hollow', 'hirschi-s-haunted-hollow', 'haunted', 42.099848, -111.896225, 'Preston', 'ID', 'Hirschi''s Haunted Hollow was a seasonal haunted attraction in the Preston area with Halloween scares and themed outdoor experiences. Idaho High Country now lists the attraction as permanently closed, so it should be removed from active OddWay routing.', 'closed', null, 'https://idahohighcountry.org/item/hirschis-haunted-hollow/', '2026-09-05T22:12:28.444612+00:00', null, 'https://idahohighcountry.org/event/hirschis-haunted-hollow/', null, 'node', 11279806881, 'America/Boise'),
  ('Historic Avenel', 'historic-avenel', 'haunted', 37.33792, -79.52444, 'Bedford', 'VA', 'Built around 1838, Avenel remained in only two families for nearly 150 years and is now preserved by the Avenel Foundation. The house has long-standing stories of a spectral woman known as the White Lady and other unexplained activity, but visits to the interior must be arranged through scheduled tours or events.', 'limited', null, 'https://www.historicavenel.com/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Bundy House', 'historic-bundy-house', 'haunted', 42.10164, -75.92793, 'Binghamton', 'NY', 'Built in the 1890s for clock manufacturer Harlow Bundy, this Victorian house is now a museum and a recurring stop for paranormal investigators. Visitors have reported footsteps, voices and other unexplained activity, and the museum hosts scheduled ghost tours and investigations in addition to regular public hours.', 'open', null, 'https://hauntedhistorytrail.com/explore/the-historic-bundy-house', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Buxton Inn', 'historic-buxton-inn', 'haunted', 40.0674, -82.51625, 'Granville', 'OH', 'The Buxton Inn traces its history to an 1812 tavern and stagecoach stop and has operated in Granville for more than two centuries. Stories of former owners, guests and even a ghostly cat have become part of the inn''s identity; it remains an active hospitality property, so public access is through its current lodging, dining and event operations.', 'open', null, 'https://www.buxtoninn.com/history', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Glen Ferris Inn', 'historic-glen-ferris-inn', 'haunted', 38.15025, -81.21472, 'Glen Ferris', 'WV', 'The riverside Glen Ferris Inn dates to the nineteenth century and has long been associated with stories of a resident spirit commonly called "The Colonel." It remains an operating inn and restaurant, so travelers can visit normally without needing a paranormal event.', 'open', null, 'https://www.glenferrisinn.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Hannah House', 'historic-hannah-house', 'haunted', 39.71167, -86.14305, 'Indianapolis', 'IN', 'Alexander Moore Hannah built this large brick house in the nineteenth century, and it later became one of Indianapolis''s best-known paranormal locations. The organization preserving the property offers historical access and scheduled paranormal investigations, allowing visitors to experience the site legally instead of relying on abandoned-building lore.', 'limited', null, 'https://www.historichannahhouse.net/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.historichannahhouse.net/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Historic Hotel Bethlehem', 'historic-hotel-bethlehem', 'haunted', 40.62009, -75.38244, 'Bethlehem', 'PA', 'Hotel Bethlehem stands on a historic Main Street site associated with hospitality going back to Bethlehem''s early years. Guests and staff have reported ghost stories throughout the building, including persistent lore surrounding Room 932, while the property remains a fully operating hotel.', 'open', null, 'https://www.hotelbethlehem.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Jail and Sheriff''s Residence', 'historic-jail-and-sheriffs-residence', 'haunted', 40.3018, -83.0689, 'Delaware', 'OH', 'Delaware County''s brick jail and attached sheriff''s residence were completed in 1878 and continued holding prisoners until 1988. The preserved complex now operates as a historic site with scheduled tours and seasonal lights-out ghost hunts, so visitors need to attend an official opening or event rather than entering on their own.', 'limited', null, 'https://www.visitdelohio.com/events/ghost-hunts-at-the-historic-jail-and-sheriffs-residence/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Prospect Place', 'historic-prospect-place', 'haunted', 40.13466, -82.01325, 'Trinway', 'OH', 'Prospect Place is an 1856 mansion built for abolitionist George W. Adams and is now preserved by a nonprofit historical organization. Its legends and reported paranormal activity are incorporated into scheduled flashlight tours and ghost hunts, while free daylight tours are offered seasonally from March through November.', 'limited', null, 'https://www.historicprospectplace.org/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Savage Mill Ghost Tour', 'historic-savage-mill-ghost-tour', 'haunted', 39.1354, -76.82521, 'Savage', 'MD', 'Historic Savage Mill dates to the 19th-century textile industry, and its organized ghost tour mixes mill history with reports of footsteps, apparitions and a mischievous child spirit. Tours require tickets and run on scheduled dates, so the haunting experience is limited even though the commercial mill complex is otherwise open.', 'limited', null, 'https://www.savagemill.com/ghost-tours/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Zoar Village Ghost Tours', 'historic-zoar-village-ghost-tours', 'haunted', 40.61232, -81.42259, 'Zoar', 'OH', 'Zoar was founded in 1817 by German religious Separatists who created a communal village that survives today as a collection of historic museum buildings. Seasonal lantern ghost tours use stories of unexplained encounters reported by residents, staff and visitors, so the paranormal version of the stop requires a scheduled ticket.', 'limited', null, 'https://historiczoarvillage.com/events/ghost-tours/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hope Furnace Ghost', 'hope-furnace-ghost', 'haunted', 39.33194, -82.34028, 'Brown Township', 'OH', 'Hope Furnace was built in 1853-54 to smelt iron and operated until 1874, leaving a large stone furnace stack beside present-day Lake Hope State Park. Local legend says a night watchman who died at the furnace still appears carrying a lantern during storms, while the surviving furnace and historical marker remain publicly accessible.', 'open', null, 'https://visitvintonohio.com/what-to-do/paranormal-investigation/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hotel Bentley', 'hotel-bentley', 'haunted', 31.31194, -92.445, 'Alexandria', 'LA', 'The grand 1908 Hotel Bentley has long accumulated stories involving wartime guests, political figures and reported paranormal activity. It is an operating hotel, so ghost lore should not interfere with normal guest areas or private rooms.', 'open', null, 'https://www.visithotelbentley.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hotel Morgan', 'hotel-morgan', 'haunted', 39.62849, -79.95761, 'Morgantown', 'WV', 'The restored Hotel Morgan is an operating downtown hotel with decades of guest stories about unexplained sounds and apparitions. It is included on West Virginia''s Paranormal Trail, but it remains a functioning hotel rather than a dedicated ghost attraction, so visit as a guest, diner or respectful sightseer.', 'open', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hundred Acres Manor Haunted House', 'hundred-acres-manor-haunted-house', 'haunted', 40.333511, -80.009363, 'Bethel Park', 'PA', 'Hundred Acres Manor is a large Pittsburgh-area seasonal haunt that combines several themed horror environments into one continuous attraction. Live actors, detailed sets, food and midway-style extras make it a destination haunt operating on selected fall nights.', 'limited', null, 'https://www.hundredacresmanor.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 699118501, 'America/New_York'),
  ('Hyde Hall', 'hyde-hall', 'haunted', 42.79231, -74.87513, 'Cooperstown', 'NY', 'This large early-nineteenth-century mansion overlooking Otsego Lake has more than a century of stories involving footsteps, whispers, phantom knocking and apparitions. Hyde Hall operates seasonal historic tours and scheduled haunted programming, including candlelit ghost tours in the fall.', 'limited', null, 'https://hauntedhistorytrail.com/explore/hyde-hall', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Imminent Doom Haunted House', 'imminent-doom-haunted-house', 'haunted', 32.433016, -94.844413, 'Kilgore', 'TX', 'Imminent Doom is a large Kilgore seasonal haunted attraction featuring live actors, animatronics and detailed horror sets across an indoor walkthrough. It operates on select dates around Halloween and is intended as a commercial scare experience rather than a historic haunted location.', 'limited', null, 'https://imminentdoomhaunt.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.facebook.com/people/Imminent-Doom-Haunted-House/61573117890491/?_rdr', '+1 9038086496', 'node', 12893715300, 'America/Chicago'),
  ('Imogene Remus Ghost at Spring House Gazebo', 'imogene-remus-ghost-at-spring-house-gazebo', 'haunted', 39.11422, -84.49353, 'Cincinnati', 'OH', 'Bootlegger George Remus fatally shot his wife Imogene near Eden Park''s Spring House Gazebo in 1927 while she was on her way to divorce proceedings. Local legend says a woman dressed in black still appears around the gazebo and former reflecting pool, which remain freely accessible within the public park during park hours.', 'open', null, 'https://en.wikipedia.org/wiki/Spring_House_Gazebo', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Irene Byron Tuberculosis Sanatorium', 'irene-byron-tuberculosis-sanatorium', 'haunted', 41.196455, -85.170248, 'Huntertown', 'IN', 'The Irene Byron Tuberculosis Sanatorium complex once treated tuberculosis patients outside Fort Wayne, but the surviving historic structures were ultimately demolished. There is no public sanatorium attraction left to visit, so this entry should not be routed as an active destination.', 'closed', null, 'https://en.wikipedia.org/wiki/Irene_Byron_Tuberculosis_Sanatorium', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 948717037, 'America/Indiana/Indianapolis'),
  ('Iron Island Museum', 'iron-island-museum', 'haunted', 42.88992, -78.81142, 'Buffalo', 'NY', 'This former church and funeral home is now both a neighborhood history museum and one of Buffalo''s established paranormal destinations. Visitors can take scheduled guided museum tours, while longer overnight investigations are available separately by reservation.', 'open', null, 'https://ironislandmuseum.com/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jailer''s Inn', 'jailers-inn', 'haunted', 37.80892, -85.46789, 'Bardstown', 'KY', 'Bardstown''s old jail operated from the eighteenth century until 1987 before portions of the complex became a bed-and-breakfast. Guests can sleep in rooms surrounded by original jail architecture and decades of stories involving executions, prisoners and reported paranormal activity.', 'limited', null, 'https://www.atlasobscura.com/places/jailers-inn-bed-and-breakfast', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.jailersinn.com/', null, null, null, 'America/New_York'),
  ('Jane Addams Hull-House Museum', 'jane-addams-hull-house-museum', 'haunted', 41.87165, -87.6474, 'Chicago', 'IL', 'The preserved Hull-House complex combines reform-era history with long-running stories of apparitions and the mansion''s famously unsettling Devil Baby legend.', 'limited', null, 'https://www.hullhousemuseum.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jean Bonnet Tavern', 'jean-bonnet-tavern', 'haunted', 40.04243, -78.56058, 'Napier Township', 'PA', 'The stone Jean Bonnet Tavern dates to the eighteenth century and served travelers along the historic Forbes Road and Lincoln Highway corridor. The owners openly document generations of ghost stories involving apparitions and unexplained activity, while the building continues to operate as a tavern and inn.', 'open', null, 'https://www.jeanbonnettavern.com/ghosts/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jennie Wade House', 'jennie-wade-house', 'haunted', 39.82332, -77.23079, 'Gettysburg', 'PA', 'Twenty-year-old Jennie Wade was killed inside this house by a stray bullet during the Battle of Gettysburg, making her the battle''s only civilian fatality killed by direct fire. The preserved house operates as a museum and has also accumulated stories of apparitions, voices and other paranormal activity.', 'open', null, 'https://www.gettysburgmuseum.com/jennie-wade-house/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jericho Covered Bridge', 'jericho-covered-bridge', 'haunted', 39.45911, -76.39022, 'Kingsville', 'MD', 'This one-lane covered bridge dates to the 1860s and still carries traffic across Little Gunpowder Falls. Local legends attach hanging apparitions, stalled vehicles and stranger creature stories to the bridge, but it remains an active narrow roadway, so do not stop a vehicle inside it or block traffic.', 'roadside', null, 'https://www.atlasobscura.com/places/jericho-covered-bridge-maryland', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Joshua Ward House', 'joshua-ward-house', 'haunted', 42.5204, -70.89595, 'Salem', 'MA', 'The Merchant hotel occupies the eighteenth-century Joshua Ward House, built on land once associated with Salem sheriff George Corwin. George Washington later stayed here. Ghost stories have accumulated around the property, but it remains an operating hotel rather than a paranormal attraction.', 'limited', null, 'https://www.atlasobscura.com/places/joshua-ward-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kilmer Mansion', 'kilmer-mansion', 'haunted', 42.09264, -75.92122, 'Binghamton', 'NY', 'Built in 1898 for the family behind the patent-medicine company that produced Swamp Root, Kilmer Mansion has accumulated reports of voices, footsteps, lights switching on and unexplained touches. The restored mansion opens for scheduled tours, events and paranormal programs rather than unrestricted daily access.', 'limited', null, 'https://hauntedhistorytrail.com/explore/kilmer-mansion', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lafayette Hotel', 'lafayette-hotel', 'haunted', 39.41076, -81.45234, 'Marietta', 'OH', 'The current Lafayette Hotel opened in 1918 after fire destroyed the earlier Bellevue Hotel at the riverfront site. Guests and staff have reported phantom footsteps, unexplained lights and apparitions including a former manager and a woman in dark clothing, while the building continues to operate as a normal hotel and public hospitality business.', 'open', null, 'https://www.ohiomagazine.com/travel/article/haunted-ohio-the-lafayette-hotel', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Geneva Ghost Walk', 'lake-geneva-ghost-walk', 'haunted', 42.58804, -88.43075, 'Lake Geneva', 'WI', 'Guided ghost walks use downtown Lake Geneva''s historic streets, hotels and lakefront stories as the setting for local legends, unexplained events and darker pieces of community history. Tours operate on scheduled dates, giving travelers a structured way to explore the city''s paranormal folklore.', 'limited', null, 'https://www.americanghostwalks.com/wisconsin/lake-geneva-ghost-walks/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.americanghostwalks.com/', null, null, null, 'America/Chicago'),
  ('Lake Shawnee Abandoned Amusement Park', 'lake-shawnee-abandoned-amusement-park', 'haunted', 37.40548, -81.14382, 'Rock', 'WV', 'The amusement park opened in 1926 and closed in the 1960s after multiple deaths, leaving behind a Ferris wheel, swings and other decaying structures that have since become the center of extensive paranormal lore. The property is private and visits are only permitted through scheduled tours, events or investigations—do not enter without an appointment.', 'limited', null, 'https://www.wvlakeshawnee.com/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('LaLaurie Mansion', 'lalaurie-mansion', 'haunted', 29.9618, -90.0612, 'New Orleans', 'LA', 'The Royal Street mansion is tied to the notorious 1834 fire that exposed abuse of enslaved people in Delphine LaLaurie''s household, later generating generations of ghost stories. It is private property; view only from the public sidewalk and do not disturb occupants.', 'private', null, 'https://www.neworleans.com/things-to-do/history/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Landmark Inn', 'landmark-inn', 'haunted', 46.54474, -87.39202, 'Marquette', 'MI', 'The Landmark Inn is a restored historic hotel in downtown Marquette that has accumulated several long-running ghost stories. The best-known is the legend of the "Lilac Lady," while other accounts involve unexplained calls and activity in upper-floor spaces; the inn remains a normal year-round hotel, restaurant and lounge rather than a dedicated ghost attraction.', 'open', null, 'https://www.michigan.org/article/trip-idea/incredibly-haunted-places-upper-peninsula', '2026-09-08T15:12:49.285859+00:00', null, 'https://thelandmarkinn.com/', null, null, null, 'America/Detroit'),
  ('Landmark Theatre', 'landmark-theatre', 'haunted', 43.04731, -76.15261, 'Syracuse', 'NY', 'The ornate theater opened in 1928 and has developed a long-running ghost story involving a woman named Clarissa, said to have fallen to her death and later appeared inside the building wearing white. It remains an active performance venue, with behind-the-scenes tours and paranormal investigations offered on selected dates or by arrangement.', 'open', null, 'https://hauntedhistorytrail.com/explore/the-landmark-theatre', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Landoll''s Mohican Castle Ghost Walk', 'landolls-mohican-castle-ghost-walk', 'haunted', 40.57289, -82.23377, 'Loudonville', 'OH', 'Landoll''s Mohican Castle runs guided haunted-history walks that lead visitors through the property, nearby Heyd Cemetery and a replica nineteenth-century cabin. The experience combines documented local history with the area''s ghost stories and is offered only on scheduled dates, so advance booking is required.', 'limited', null, 'https://landollsmohicancastle.com/events/ghost-walk-haunted-history-tours/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lemp Mansion', 'lemp-mansion', 'haunted', 38.593173, -90.215771, 'Saint Louis', 'MO', 'The Lemp Mansion is the historic home of St. Louis''s Lemp brewing family and now operates as a restaurant, inn and event venue. Its tragic family history and long-running ghost stories are explored through special haunted-history events, tours and paranormal investigations.', 'open', null, 'https://www.lempmansion.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 526334314, 'America/Chicago'),
  ('Lexington Opera House', 'lexington-opera-house', 'haunted', 38.05001, -84.49921, 'Lexington', 'KY', 'Opened in 1887 after an earlier theater burned, the Lexington Opera House remains an active performance venue with ornate nineteenth-century architecture. Staff and performers have also passed down ghost stories involving unexplained sounds and figures, earning the theater a place on Kentucky''s paranormal tourism trail.', 'limited', null, 'https://www.kentuckyafterdark.com/', '2026-09-08T14:42:00.461026+00:00', null, 'https://www.lexingtonoperahouse.com/', null, null, null, 'America/New_York'),
  ('Liberty Hall Gray Lady', 'liberty-hall-gray-lady', 'haunted', 38.20052, -84.87622, 'Frankfort', 'KY', 'Liberty Hall dates to the late eighteenth century and carries one of Kentucky''s oldest ghost traditions. The most famous apparition is the "Gray Lady," said to be connected to a visiting relative who died in the house, with additional stories involving other unexplained figures and sounds.', 'limited', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, 'https://libertyhall.org/', null, null, null, 'America/New_York'),
  ('Licking County Historic Jail', 'licking-county-historic-jail', 'haunted', 40.0562, -82.40139, 'Newark', 'OH', 'The Licking County Historic Jail opened in 1889 and held prisoners until 1987, preserving its original cells and sheriff''s residence in downtown Newark. Deaths, a notorious 1910 lynching and decades of incarceration helped create its paranormal reputation, and the building now hosts scheduled historical tours, paranormal investigations and the seasonal Jail of Terror attraction.', 'limited', null, 'https://www.newarkjail.com/about.html', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lincoln''s Ghost Train Marker', 'lincolns-ghost-train-marker', 'haunted', 41.78727, -73.94629, 'Hyde Park', 'NY', 'Abraham Lincoln''s funeral train passed through Hyde Park on April 25, 1865. Folklore later developed that a spectral version of the black-draped train returns along the Hudson River tracks on the anniversary of its passage, and a Legends & Lore marker now identifies the location associated with the story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/ghost-train/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Logan Inn', 'logan-inn', 'haunted', 40.3635, -74.9517, 'New Hope', 'PA', 'The Logan Inn traces its history to 1727 and is one of New Hope''s oldest continuously used buildings. Its long-running ghost lore centers on rooms and hallways where guests have reported apparitions and unexplained activity, while the property remains an active hotel and restaurant.', 'open', null, 'https://www.loganinn.com/press-blogs', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lord Baltimore Hotel', 'lord-baltimore-hotel', 'haunted', 39.2897, -76.61612, 'Baltimore', 'MD', 'Opened in 1928, the Lord Baltimore is a surviving grand downtown hotel with decades of stories involving a girl in white, unexplained elevator stops and other reported activity. The hotel actively embraces the reputation today with ghost tours, paranormal events and haunted-stay packages.', 'open', null, 'https://www.lordbaltimorehotel.com/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lums Pond Ghost Legends', 'lums-pond-ghost-legends', 'haunted', 39.57315, -75.70625, 'Bear', 'DE', 'Lums Pond State Park carries several long-running ghost stories, including tales connected to John Lum and another restless spirit said to haunt the area. Delaware’s own environmental agency includes the park among the state’s haunted places, while treating the stories as folklore rather than established fact.', 'open', null, 'https://dnrec.delaware.gov/outdoor-delaware/unveiling-delawares-dark-secrets-exploring-the-haunted-fort-delaware-and-beyond/', '2026-09-08T18:31:51.932734+00:00', null, 'https://destateparks.com/LumsPond', null, null, null, 'America/New_York'),
  ('Lydia’s Bridge — Phantom Hitchhiker Marker', 'lydias-bridge-phantom-hitchhiker-marker', 'haunted', 35.99744, -79.92582, 'Jamestown', 'NC', 'The legend of Lydia tells of a young woman killed in a crash who later appears along the road asking motorists for a ride home, only to vanish before reaching her destination. A historical folklore marker now identifies the tradition near the bridge most often connected with the story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/lydias-bridge/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Madison Seminary', 'madison-seminary', 'haunted', 41.79051, -81.04554, 'Madison', 'OH', 'Built in 1847 as a school, Madison Seminary later served as a home for Civil War veterans and their families before passing through several institutional uses. The restored building is now best known as a paranormal investigation venue, with tours and overnight ghost hunts offered by reservation rather than normal walk-in access.', 'limited', null, 'https://www.madisonseminary.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Magnolia Manor', 'magnolia-manor', 'haunted', 37.00944, -89.1825, 'Cairo', 'IL', 'A 14-room 1869 mansion preserves ornate Victorian interiors and furnishings from Cairo''s prosperous river-port era, with local ghost lore attached.', 'limited', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Majestic Theatre', 'majestic-theatre', 'haunted', 39.33489, -82.98105, 'Chillicothe', 'OH', 'Chillicothe''s Majestic Theatre traces its history to the nineteenth century and is tied in local lore to the devastating 1918 influenza epidemic at nearby Camp Sherman. Stories claim the theater was used to hold bodies during the crisis and now hosts apparitions and voices; it remains an active theater, with access through performances, scheduled tours and occasional ghost hunts.', 'limited', null, 'https://www.majesticchillicothe.net/wp-content/uploads/Haunted-Majestic-Ghost-Hunt.pdf', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Major Graham Mansion', 'major-graham-mansion', 'haunted', 36.91532, -80.87226, 'Max Meadows', 'VA', 'This 19th-century Wythe County mansion has accumulated stories of apparitions, voices and other reported paranormal activity tied to generations of the Graham family and the property''s history. Access is event-based and has included history tours, seasonal haunted attractions and paranormal investigations, so verify an authorized date before traveling.', 'limited', null, 'http://majorgrahammansion.com/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Martha Washington Inn', 'martha-washington-inn', 'haunted', 36.7096, -81.97539, 'Abingdon', 'VA', 'Built as a private home in 1832, the building later became a women''s college, served as a Civil War hospital and opened as a hotel in 1935. Stories of a ghostly violinist, wounded soldiers and a riderless horse remain part of the inn''s lore, while the property continues to operate as a hotel, restaurant and spa.', 'open', null, 'https://themartha.com/abingdon-hotel-history/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mary''s Ghost at the Friends Home', 'marys-ghost-at-the-friends-home', 'haunted', 39.53116, -84.08986, 'Waynesville', 'OH', 'Local legend says a young girl named Mary disappeared after her parents became ill in the early nineteenth century and that her laughing spirit still waits for her mother at what is now the Museum at the Friends Home. A Legends & Lore marker stands at the museum, where stories describe Mary rocking inside or appearing on the front porch; interior access follows the museum''s schedule.', 'limited', null, 'https://www.wgpfoundation.org/historic-markers/marys-ghost/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('May-Stringer House', 'may-stringer-house', 'haunted', 28.55573, -82.38747, 'Brooksville', 'FL', 'Victorian house museum with a strong reputation for hauntings and paranormal investigations.', 'limited', null, 'https://www.hernandohistoricalmuseumassoc.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('McPike Mansion', 'mcpike-mansion', 'haunted', 38.90606, -90.18364, 'Alton', 'IL', 'A long-vacant 1869 mansion undergoing restoration has become one of the Alton area''s best-known paranormal-tour locations.', 'limited', null, 'https://www.mcpikemansion.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('McRaven Tour Home', 'mcraven-tour-home', 'haunted', 32.34604, -90.87192, 'Vicksburg', 'MS', 'A layered historic house assembled in sections dating from the late 1700s through the antebellum era and used during the Civil War. The operator openly offers history tours, haunted tours and paranormal investigations, making the site''s paranormal identity part of its current public use rather than an unsupported rumor. Coordinate source: https://www.atlasobscura.com/places/mcraven-tour-home', 'open', null, 'https://mcraventourhome.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Merchant''s House Museum', 'merchants-house-museum', 'haunted', 40.72766, -73.99234, 'New York', 'NY', 'The preserved 1832 Tredwell family home calls itself Manhattan''s most haunted house and has collected reports of footsteps, voices, odors and apparitions since becoming a museum. It remains open for normal daytime tours and also runs scheduled candlelight ghost tours and paranormal programming.', 'open', null, 'https://merchantshouse.org/ghosts/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mineral Springs Mall / Former Mineral Springs Hotel', 'mineral-springs-mall-former-mineral-springs-hotel', 'haunted', 38.8895, -90.18192, 'Alton', 'IL', 'The 1914 former hotel and mineral-bath complex now houses shops and paranormal events, with extensive lore attached to its basement pool and old rooms.', 'limited', null, 'https://www.riversandroutes.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Missouri State Penitentiary Tours', 'missouri-state-penitentiary-tours', 'haunted', 38.573749, -92.161798, 'Jefferson City', 'MO', 'Missouri State Penitentiary operated for more than a century before closing in 2004, and today visitors can enter former housing units, yards and the gas chamber on guided tours. The site offers both historical tours and scheduled ghost or paranormal experiences.', 'limited', null, 'https://www.missouripentours.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.missouripentours.com/', null, 'node', 9694349988, 'America/Chicago'),
  ('Montgomery County Old Courthouse', 'montgomery-county-old-courthouse', 'haunted', 42.95294, -74.37553, 'Fonda', 'NY', 'Built in 1836, this courthouse witnessed generations of criminal trials and executions and now houses county historical records on its first floor. Paranormal reports include unexplained footsteps, voices, falling books and an apparition described as a woman in blue, while the public can visit during normal county history and archives hours.', 'open', null, 'https://hauntedhistorytrail.com/explore/montgomery-county-old-courthouse', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moonville Tunnel', 'moonville-tunnel', 'haunted', 39.30722, -82.32222, 'Brown Township', 'OH', 'Moonville was a remote mining and railroad settlement whose last residents left in the twentieth century, leaving behind its cemetery, foundations and brick-lined railroad tunnel. Numerous deaths along the old rail line produced stories of a spectral brakeman carrying a lantern and other apparitions; the tunnel is reached on the public Moonville Rail Trail, which is open from 6 a.m. to 11 p.m. and remains rugged in places.', 'limited', null, 'https://visitvintonohio.com/history/moonville-tunnel/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Morris-Jumel Mansion', 'morris-jumel-mansion', 'haunted', 40.83447, -73.93858, 'New York', 'NY', 'Manhattan''s oldest surviving house has accumulated stories of apparitions and unexplained activity connected with its long history, including former owner Eliza Jumel. The museum has offered dedicated paranormal investigations, although the mansion is temporarily undergoing roof work in 2026 and access should be checked before visiting.', 'limited', null, 'https://morrisjumel.org/programs/paranormal/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Muriel''s Jackson Square Séance Lounge', 'muriels-jackson-square-s-ance-lounge', 'haunted', 29.95843, -90.06309, 'New Orleans', 'LA', 'Muriel''s embraces the building''s ghost lore with a dedicated séance lounge and stories about former resident Pierre Antoine Lepardi Jourdan. It is an operating restaurant, so paranormal interest should remain secondary to normal guest access.', 'open', null, 'https://muriels.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nemacolin Castle', 'nemacolin-castle', 'haunted', 40.02258, -79.8837, 'Brownsville', 'PA', 'Nemacolin Castle grew from an eighteenth-century trading-post site into an elaborate nineteenth-century mansion overlooking the Monongahela River. The Brownsville Historical Society opens the castle for scheduled tours and events, including programs built around longstanding reports of unexplained activity.', 'limited', null, 'https://www.nemacolincastle.net/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('New London Ledge Light — Ernie''s Lighthouse', 'new-london-ledge-light-ernies-lighthouse', 'haunted', 41.30589, -72.07743, 'Groton', 'CT', 'The unusual brick lighthouse at the mouth of the Thames River is famous for a resident ghost nicknamed Ernie, traditionally described as a former keeper. The New London Maritime Society owns the light, and public access is available on selected boat tours rather than by road.', 'limited', null, 'https://ctvisit.com/articles/haunted-lighthouses', '2026-09-08T18:47:23.721893+00:00', null, 'https://lighthousefoundation.org/lighthouses/new-london-ledge-light/', null, null, null, 'America/New_York'),
  ('New Orleans Nightmare Haunted House', 'new-orleans-nightmare-haunted-house', 'haunted', 29.951386, -90.175612, 'Elmwood', 'LA', 'New Orleans Nightmare is a large seasonal haunted attraction with multiple themed horror environments, live actors, elaborate sets and optional add-on experiences. It runs on select nights around Halloween rather than as a normal year-round museum or historical site.', 'limited', null, 'https://neworleansnightmare.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://neworleansnightmare.com/', null, 'node', 11145766959, 'America/Chicago'),
  ('Newport Opera House', 'newport-opera-house', 'haunted', 43.3646, -72.17265, 'Newport', 'NH', 'The historic Newport Opera House has been investigated by paranormal groups after reports of unexplained sounds, shadowy figures and unusual experiences inside the building. Its preserved stage and upper-level spaces give the stories a strong physical setting. Access is through performances, events and authorized tours rather than unrestricted exploration.', 'limited', null, 'https://www.nhpr.org/nh-news/2023-10-27/newport-opera-house-ghosts-paranormal-new-hampshire', '2026-09-09T04:49:39.808526+00:00', null, 'https://newportoperahouse.com/', null, null, null, 'America/New_York'),
  ('Nightmare Factory Haunted Attraction', 'nightmare-factory-haunted-attraction', 'haunted', 34.884935, -76.915938, 'Havelock', 'NC', 'Nightmare Factory was a long-running Havelock haunted attraction, but the Havelock location has closed while the business prepares a future move to New Bern. The old Havelock record should not be routed as open; the operator currently plans to return at the new location in 2027.', 'closed', null, 'https://nightmarefactorync.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://nightmarefactorync.com', '+1-252-444-3327', 'way', 616191563, 'America/New_York'),
  ('Nightmare Haunted House', 'nightmare-haunted-house', 'haunted', 33.693626, -78.878382, 'Myrtle Beach', 'SC', 'Nightmare Haunted House is a long-running Myrtle Beach walk-through attraction using dark corridors, horror scenes and live or theatrical scares near the oceanfront. Unlike many temporary October haunts, it operates across a much broader portion of the tourist season and may be open year-round on selected schedules.', 'open', null, 'https://nightmarehauntedhouse.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 2722767216, 'America/New_York'),
  ('Notchland Inn — Nancy Barton Ghost', 'notchland-inn-nancy-barton-ghost', 'haunted', 44.11528, -71.35556, 'Hart''s Location', 'NH', 'The Notchland Inn sits near the setting of one of the White Mountains'' enduring ghost stories. Nancy Barton reportedly died in 1778 while searching the winter wilderness for her missing fiancé, and later folklore describes her spirit wandering the area around the old road and inn property. The inn remains an operating lodging property, so visitors should respect guests and private areas.', 'open', null, 'https://ournewenglandlegends.com/podcast-191-the-ghost-of-nancy-barton/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Octagon Hall', 'octagon-hall', 'haunted', 36.80725, -86.55754, 'Franklin', 'KY', 'This unusual eight-sided antebellum house became entangled with Civil War history when soldiers occupied and camped around the property. Today it operates as a museum and has become one of Kentucky''s best-known paranormal investigation sites, with numerous television ghost-hunting appearances.', 'limited', null, 'https://www.atlasobscura.com/places/octagon-hall-civil-war-museum', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.octagonhallmuseum.com/', null, null, null, 'America/Chicago'),
  ('Ohio State Reformatory', 'ohio-state-reformatory', 'haunted', 40.78373, -82.50275, 'Mansfield', 'OH', 'The Ohio State Reformatory was built beginning in 1886 and operated as a prison until 1990 before becoming a museum and preservation site. Beyond its use as a filming location for The Shawshank Redemption, the enormous cellblocks have a major paranormal reputation and the reformatory offers both regular tours and structured ghost-hunting programs.', 'open', null, 'https://www.mrps.org/visit/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Charleston City Jail', 'old-charleston-city-jail', 'haunted', 32.7785, -79.93717, 'Charleston', 'SC', 'Charleston’s old jail held criminals, pirates, enslaved people, and prisoners of war during more than a century of operation. Its grim history has given it one of the city’s strongest paranormal reputations, and guided haunted-jail tours continue to enter the building in 2026.', 'limited', null, 'https://www.charlestoncvb.com/plan-your-trip/tours-attractions~204/historic-sites~1146/haunted-jail-tour-at-the-old-city-jail~33433.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Idaho Penitentiary', 'old-idaho-penitentiary', 'haunted', 43.602249, -116.162206, 'Boise', 'ID', 'Idaho''s former territorial and state prison operated from the 1870s until 1973 and is now a museum complex of historic cell blocks, yards, solitary-confinement spaces and the gallows. Visitors can tour the prison''s history during regular museum hours, with occasional programs exploring the site''s darker and paranormal reputation.', 'open', null, 'https://history.idaho.gov/oldpen/', '2026-09-05T22:12:28.444612+00:00', null, 'https://history.idaho.gov/old-penitentiary-hours-location', null, 'way', 421958184, 'America/Boise'),
  ('Old Jail Museum Handprint', 'old-jail-museum-handprint', 'haunted', 40.86384, -75.74649, 'Jim Thorpe', 'PA', 'The former Carbon County Jail opened in 1871 and is infamous for the executions of men accused of belonging to the Molly Maguires. Cell 17 contains a dark handprint that local lore says repeatedly returned after attempts to remove it, and visitors can see it on seasonal guided tours of the jail.', 'limited', null, 'https://theoldjailmuseum.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Presque Isle Lighthouse', 'old-presque-isle-lighthouse', 'haunted', 45.34197, -83.47825, 'Presque Isle', 'MI', 'Built in 1840 and retired as the area''s primary light in 1871, this small Lake Huron lighthouse now operates as a township park and museum. Persistent local ghost stories claim unusual activity and a mysteriously illuminated lantern, although the museum itself explicitly treats the haunting stories with skepticism.', 'limited', null, 'https://www.presqueislelighthouses.org/lighthouses/old-presque-isle-lighthouse-1840/', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.presqueislelighthouses.org/', null, null, null, 'America/Detroit'),
  ('Old Stone Fort Museum', 'old-stone-fort-museum', 'haunted', 42.67773, -74.30214, 'Schoharie', 'NY', 'Originally built as a church in 1772, the stone structure was fortified during the Revolutionary War and attacked in 1780. Visitors and investigators have reported apparitions, footsteps, screams and other unexplained activity; the museum is seasonal, with special paranormal programs and ghost hunts offered on selected dates.', 'limited', null, 'https://hauntedhistorytrail.com/explore/old-stone-fort-museum', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Talbott Tavern', 'old-talbott-tavern', 'haunted', 37.809, -85.46746, 'Bardstown', 'KY', 'Operating from an eighteenth-century stone building, the Old Talbott Tavern has accumulated ghost stories involving former guests, unexplained apparitions and figures associated with Kentucky frontier history. Visitors can eat, drink or stay overnight rather than merely viewing the supposedly haunted building from outside.', 'open', null, 'https://www.hauntedplaces.org/item/old-talbott-tavern/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.talbotttavern.com/', null, null, null, 'America/New_York'),
  ('Omni Mount Washington Resort — Princess Carolyn Ghost', 'omni-mount-washington-resort-princess-carolyn-ghost', 'haunted', 44.25843, -71.43985, 'Bretton Woods', 'NH', 'The grand 1902 Mount Washington Hotel is associated with stories of Carolyn Stickney, whose apparition is said to appear in Victorian clothing and who is often nicknamed "the Princess." Room 314, once part of her private suite, is particularly tied to the hotel''s ghost lore. The property remains an operating resort, so paranormal interest should not interfere with guests.', 'open', null, 'https://www.historichotels.org/us/hotels-resorts/omni-mount-washington-resort/ghost-stories.php', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.omnihotels.com/hotels/bretton-woods-mount-washington', null, null, null, 'America/New_York'),
  ('Opera House at Boothbay Harbor', 'opera-house-at-boothbay-harbor', 'haunted', 43.85433, -69.62652, 'Boothbay Harbor', 'ME', 'The 1894 Opera House remains an active performance venue, but it also carries a long-running reputation for unexplained activity. Local ghost lore includes stories about sounds, movement, and a purported presence sometimes nicknamed “Fingers”; these are legends, not verified paranormal claims.', 'limited', null, 'https://boothbayoperahouse.com/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Owls Head Lighthouse', 'owls-head-lighthouse', 'haunted', 44.09224, -69.04408, 'Owls Head', 'ME', 'Perched above Penobscot Bay, Owls Head Light combines dramatic coastal scenery with a collection of long-running ghost and maritime legends. Stories associated with the site include unexplained footsteps and apparitions as well as tales of the lighthouse keeper’s dog Spot, who famously rang a bell to warn passing vessels. Paranormal claims remain folklore.', 'limited', null, 'https://lighthousefoundation.org/lighthouses/owls-head-light/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Palatine Graves', 'palatine-graves', 'haunted', 41.15519, -71.60266, 'New Shoreham', 'RI', 'This historic Block Island cemetery is traditionally associated with survivors and victims connected to the 1738 wreck of the Princess Augusta, remembered in folklore as the Palatine. The disaster later inspired stories of the Palatine Light, a flaming ghost ship said to appear offshore around the anniversary season. Historians dispute darker versions of the legend, but the cemetery remains a concrete location tied to the story. Secondary source: https://www.pbs.org/video/2-princess-augusta-jq5wjr/', 'limited', null, 'https://www.newshorehamri.gov/292/Cemetery', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paramount Joe — Paramount Arts Center', 'paramount-joe-paramount-arts-center', 'haunted', 38.47823, -82.63736, 'Ashland', 'KY', 'The restored Paramount theater is associated with a resident ghost known as "Paramount Joe," traditionally described as a worker who died while the building was being constructed. Employees and performers have reported missing objects, cold spots and unexplained appearances around the theater.', 'limited', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, 'https://paramountartscenter.com/', null, null, null, 'America/New_York'),
  ('Pemaquid Point Lighthouse', 'pemaquid-point-lighthouse', 'haunted', 43.83698, -69.50602, 'Bristol', 'ME', 'One of Maine’s most recognizable lighthouses also carries a local ghost tradition involving the apparition of a woman sometimes described as wearing a red shawl. The tower and surrounding rocky point are real public attractions; the haunting is regional folklore rather than a verified event.', 'limited', null, 'https://lighthousefoundation.org/lighthouses/pemaquid-point-light/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Penfield Reef Lighthouse', 'penfield-reef-lighthouse', 'haunted', 41.1171, -73.2221, 'Fairfield', 'CT', 'This isolated lighthouse stands more than a mile offshore on a dangerous reef. Its best-known legend concerns keeper Frederick Jordan, who drowned in 1916 and was later said to return as a protective ghost. There is no casual public walk-up access; view it from shore or by boat.', 'roadside', null, 'https://ctvisit.com/articles/haunted-lighthouses', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pennhurst Asylum', 'pennhurst-asylum', 'haunted', 40.19463, -75.56188, 'Spring City', 'PA', 'Pennhurst State School became nationally important after its abusive conditions were exposed and legal challenges helped push the disability-rights movement forward. Parts of the surviving campus now offer scheduled daytime history tours and museum interpretation alongside photography, paranormal and seasonal haunted-attraction experiences, so travelers need tickets for a specific event rather than wandering the property.', 'limited', null, 'https://pennhurstasylum.com/visit/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pere Cheney Cemetery', 'pere-cheney-cemetery', 'haunted', 44.57349, -84.63521, 'Beaver Creek Township', 'MI', 'This isolated cemetery is the most visible remnant of Pere Cheney, a nineteenth-century lumber town abandoned after disease and economic decline. Stories about a witch''s curse, ghostly lights and unexplained voices have accumulated around the site, but visitors should treat it primarily as a historic cemetery and remain respectful of the graves.', 'open', null, 'https://www.atlasobscura.com/places/pere-cheney-cemetery', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Peyton Randolph House', 'peyton-randolph-house', 'haunted', 37.27242, -76.70001, 'Williamsburg', 'VA', 'This restored Colonial Williamsburg house was home to prominent revolutionary-era statesman Peyton Randolph and generations of enslaved and free residents. Its long and sometimes violent history has produced some of Colonial Williamsburg''s most persistent ghost stories, and interior access is through the living-history site''s ticketed schedule.', 'limited', null, 'https://www.colonialwilliamsburg.org/locations/peyton-randolph-house/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Phelps Mansion Museum', 'phelps-mansion-museum', 'haunted', 42.10068, -75.90556, 'Binghamton', 'NY', 'Built beginning in 1870 for businessman and former Binghamton mayor Sherman D. Phelps, the mansion is associated with reports of period-dressed apparitions, unexplained footsteps, moving objects and a clock chiming without being wound. It is now a public museum with regular tours, while dedicated haunted tours and paranormal investigations are offered on scheduled dates or by reservation.', 'open', null, 'https://hauntedhistorytrail.com/explore/phelps-mansion-museum', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pine Hill Cemetery — Blood Cemetery', 'pine-hill-cemetery-blood-cemetery', 'haunted', 42.7682, -71.53861, 'Hollis', 'NH', 'Pine Hill Cemetery is widely nicknamed Blood Cemetery because of the Blood family buried there, especially Abel Blood and a gravestone whose carved hand helped fuel local legends. Stories describe apparitions, strange lights and other activity around the burial ground, though these remain folklore. Visit only during lawful cemetery hours and treat the graves respectfully. Secondary source: https://www.hauntedplaces.org/item/pine-hill-cemetery-blood-cemetery/', 'limited', null, 'https://www.nhmagazine.com/where-to-find-ghosts-ghouls-and-scares-in-the-granite-state/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pink Hill Ghost Marker', 'pink-hill-ghost-marker', 'haunted', 42.58108, -75.86414, 'Pitcher', 'NY', 'Local legend says Zella Droff was murdered after secretly attending dances at the former Pitcher Hotel, then returned years later as a ghost who accepted a ride from an unsuspecting salesman. A Legends & Lore marker on Pitcher Hill Road marks the area associated with the story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/pink-hill-legend/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Plain Meeting House Cemetery — Nellie Vaughn Legend', 'plain-meeting-house-cemetery-nellie-vaughn-legend', 'haunted', 41.63806, -71.75278, 'West Greenwich', 'RI', 'Nellie Vaughn died in 1889, but her grave later became surrounded by stories describing her as a witch, vampire or restless ghost. Investigations of the legend show that many of the supernatural claims appeared long after her death, making the site as much a lesson in how folklore evolves as a haunted stop. Her original marker is no longer present, so the cemetery itself is the route point. Secondary source: https://ournewenglandlegends.com/podcast-251-nellie-vaughn-vampire-witch-ghost/', 'limited', null, 'https://www.pbs.org/video/8-nelly-vaughn-gb2odo/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Poasttown Elementary School', 'poasttown-elementary-school', 'haunted', 39.54838, -84.38132, 'Middletown', 'OH', 'The former Poasttown Elementary School has been converted into a dedicated paranormal investigation destination rather than demolished or repurposed as a conventional museum. Visitors can enter during scheduled flashlight tours, public investigations and private bookings, but the building is not open for casual exploration.', 'limited', null, 'https://poasttownschool.com/flashlight-tours/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Point Lookout Civil War Prison Camp', 'point-lookout-civil-war-prison-camp', 'haunted', 38.05965, -76.33698, 'Scotland', 'MD', 'Point Lookout held tens of thousands of Confederate prisoners during the Civil War, with thousands dying from disease and harsh conditions before the camp closed in 1865. The state park preserves the landscape and interpretation today, while generations of visitors and staff have reported apparitions, voices and other ghost stories around the former prison grounds and lighthouse area.', 'open', null, 'https://dnr.maryland.gov/publiclands/Pages/southern/pointlookout.aspx', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Portal 31 Underground Mine', 'portal-31-underground-mine', 'haunted', 36.96592, -82.9177, 'Lynch', 'KY', 'Portal 31 takes visitors by rail into a former U.S. Steel coal mine in the historic company town of Lynch. Beyond its mining history, the site is included on Kentucky''s paranormal tourism trail because visitors and staff have reported unexplained lights and sounds underground.', 'limited', null, 'https://portal31.org/', '2026-09-08T14:15:10.228298+00:00', null, 'https://portal31.org/', null, null, null, 'America/New_York'),
  ('Proprietary House', 'proprietary-house', 'haunted', 40.50341, -74.2693, 'Perth Amboy', 'NJ', 'Built in the 1760s, this Georgian mansion served as the home of William Franklin, New Jersey''s last royal governor and Benjamin Franklin''s Loyalist son. The restored house is open for scheduled tours and has accumulated long-running reports of apparitions and unexplained activity.', 'limited', null, 'https://www.theproprietaryhouse.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Providence Biltmore — Graduate Providence', 'providence-biltmore-graduate-providence', 'haunted', 41.82432, -71.41328, 'Providence', 'RI', 'Opened in 1922, the former Providence Biltmore has accumulated decades of stories involving unexplained voices, apparitions and other alleged paranormal activity. Its history also includes Prohibition-era nightlife and a long list of prominent guests. The building remains an operating downtown hotel, now known as Graduate Providence.', 'open', null, 'https://www.atlasobscura.com/places/providence-biltmore-graduate', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pueblo Ghost Tour', 'pueblo-ghost-tour', 'haunted', 38.281267, -104.496886, 'Pueblo', 'CO', 'Pueblo Ghost Tour combines local history with paranormal stories during guided visits to reportedly active locations in the Pueblo area. Tours run on scheduled dates and may include access to sites not normally experienced as part of a regular museum visit.', 'limited', null, 'https://puebloghosttour.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 12068875894, 'America/Denver'),
  ('Punderson Manor', 'punderson-manor', 'haunted', 41.45108, -81.20787, 'Newbury Township', 'OH', 'The Tudor-style Punderson Manor operates as the lodge at Punderson State Park and has accumulated long-running stories of footsteps, children''s laughter, moving objects and other unexplained activity. It remains a working state-park lodge and restaurant, so visitors can experience the building normally without entering restricted guest areas.', 'open', null, 'https://www.ohiotraveler.com/punderson-manor/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Raven''s Grin Inn', 'ravens-grin-inn', 'haunted', 42.10053, -89.98004, 'Mount Carroll', 'IL', 'A former hotel converted by artist Jim Warfield into an eccentric handmade haunted house full of secret passages, mechanical gags, and surreal rooms.', 'limited', null, 'https://www.atlasobscura.com/places/ravens-grin-inn', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rebel Yell Haunted House', 'rebel-yell-haunted-house', 'haunted', 37.25026, -121.900745, 'San Jose', 'CA', 'Rebel Yell is a long-running San Jose home haunt built around a residential property, with elaborate Halloween displays and walk-through scares created for the season. It is a neighborhood attraction rather than a commercial year-round haunt, so visitors should only go during posted operating nights.', 'limited', null, 'https://rebelyell.info/', '2026-09-05T22:12:28.444612+00:00', null, 'http://www.rebelyell.info/rebelyell.html', null, 'way', 863999850, 'America/Los_Angeles'),
  ('Red Lion Pub', 'red-lion-pub', 'haunted', 41.92632, -87.65046, 'Chicago', 'IL', 'A British-style pub near the Biograph is associated with stories of phantom footsteps, shadowy figures, and other alleged paranormal activity.', 'limited', null, 'https://redlionchicago.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Redden State Forest Ranger House', 'redden-state-forest-ranger-house', 'haunted', 38.74111, -75.41056, 'Georgetown', 'DE', 'The historic Redden Forest complex includes an early-1900s lodge and ranger or forester’s house that originated with a Pennsylvania Railroad hunting retreat. Local ghost lore says a woman still haunts the old house. The surrounding state forest has public recreation areas, but access to historic buildings is more restricted.', 'limited', null, 'https://www.mlski.net/HOLIDAYS/hal3.html', '2026-09-08T18:31:51.932734+00:00', null, 'https://agriculture.delaware.gov/forest-service/state-forests/', null, null, null, 'America/New_York'),
  ('Resurrection Cemetery / Resurrection Mary', 'resurrection-cemetery-resurrection-mary', 'haunted', 41.75797, -87.82741, 'Justice', 'IL', 'The cemetery gates are inseparable from the legend of Resurrection Mary, the hitchhiking ghost said to disappear near Archer Avenue.', 'limited', null, 'https://www.enjoyillinois.com/plan-your-trip/road-trip-itineraries/haunted-chicago/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Retreat Tower', 'retreat-tower', 'haunted', 42.85755, -72.56599, 'Brattleboro', 'VT', 'Patients from the nearby Brattleboro Retreat built this stone observation tower in the nineteenth century as part of therapeutic outdoor work. The tower itself is no longer intended for climbing, but surrounding public trails reach the structure, which has accumulated grim local legends and ghost stories.', 'open', null, 'https://www.atlasobscura.com/places/retreat-tower', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ripley''s Haunted Adventure', 'ripley-s-haunted-adventure', 'haunted', 35.710543, -83.518941, 'Gatlinburg', 'TN', 'Ripley''s Haunted Adventure in Gatlinburg is a year-round walk-through horror attraction on the Parkway featuring live actors, dark sets and jump scares. It is part of Ripley''s cluster of tourist attractions and can be visited independently with a ticket.', 'open', null, 'https://www.ripleys.com/attractions/ripleys-haunted-adventure-gatlinburg', '2026-09-05T22:12:28.444612+00:00', 'Su 12:00-21:00; Mo-Th 11:00-22:00; Fr 11:00-23:00; Sa 10:00-23:00', 'https://www.ripleys.com/attractions/ripleys-haunted-adventure-gatlinburg', null, 'way', 1435782642, 'America/New_York'),
  ('Ripley''s Haunted Adventure', 'ripley-s-haunted-adventure-2', 'haunted', 33.693268, -78.87879, 'Myrtle Beach', 'SC', 'Ripley''s Haunted Adventure in Myrtle Beach is an interactive walk-through horror attraction on Ocean Boulevard featuring live scares, dark themed rooms and theatrical effects. It operates as a regular tourist attraction rather than only as an October pop-up.', 'open', null, 'https://www.ripleys.com/attractions/ripleys-haunted-adventure-myrtle-beach', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 2722767214, 'America/New_York'),
  ('Roberson Mansion', 'roberson-mansion', 'haunted', 42.094, -75.91866, 'Binghamton', 'NY', 'This Italian Renaissance-style mansion was completed in 1907 for Alonzo and Margaret Roberson and is now part of the Roberson Museum and Science Center. Staff and visitors have reported unexplained footsteps, voices and the sensation of unseen people in the house, while the mansion remains accessible through the museum and occasional ghost programs.', 'open', null, 'https://hauntedhistorytrail.com/explore/roberson-mansion', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Robert the Doll', 'robert-the-doll', 'haunted', 24.55273, -81.75514, 'Key West', 'FL', 'Infamous supposedly cursed doll displayed inside Fort East Martello.', 'limited', null, 'https://www.kwahs.org/exhibitions/robert-the-doll', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rockwood Park & Museum', 'rockwood-park-museum', 'haunted', 39.77311, -75.52077, 'Wilmington', 'DE', 'This Victorian estate is unusual for openly embracing its reported hauntings through county-run Ghost Walks and guided paranormal investigations using investigative equipment. As of September 2026, the mansion galleries are also undergoing accessibility work, so regular indoor access is more limited than usual.', 'limited', null, 'https://www.newcastlede.gov/431/Rockwood-Park-Museum', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.newcastlede.gov/431/Rockwood-Park-Museum', null, null, null, 'America/New_York'),
  ('Rohs Opera House', 'rohs-opera-house', 'haunted', 38.38869, -84.29636, 'Cynthiana', 'KY', 'Opened in 1871, Rohs Opera House is Kentucky''s oldest continuously operating theater and one of the state''s most openly paranormal-friendly venues. Staff and investigators have reported footsteps, voices, shadows and apparitions, and the theater hosts ghost walks and investigations.', 'limited', null, 'https://www.kentuckytourism.com/trip-planning/travel-inspiration/articles/2026/07/17/autumn-adventures-in-kentucky--spirits--scenery---spooky-stories', '2026-09-08T14:15:10.228298+00:00', null, 'https://rohsoperahouse.com/', null, null, null, 'America/New_York'),
  ('Rolling Hills Asylum', 'rolling-hills-asylum', 'haunted', 42.881184, -78.132805, 'East Bethany', 'NY', 'Rolling Hills Asylum occupies a former Genesee County poorhouse complex and is now operated specifically for paranormal tourism. Visits are reservation-based and include flashlight tours, self-guided ghost hunts and longer investigations inside the old institution.', 'limited', null, 'https://rollinghillsasylum.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.rollinghillsasylum.com/', '+1 585 502 4066', 'node', 5390600736, 'America/New_York'),
  ('Sachs Covered Bridge', 'sachs-covered-bridge', 'haunted', 39.79742, -77.2762, 'Cumberland Township', 'PA', 'Built in the 1850s, Sachs Covered Bridge carried both Union and Confederate troops during the Gettysburg campaign and is now preserved as a pedestrian bridge. It later accumulated extensive ghost lore involving apparitions, phantom sounds and Civil War soldiers, making it one of Gettysburg''s better-known paranormal stops while still being a legitimate historic structure visitors can walk across.', 'open', null, 'https://www.gettysburgbattlefieldtours.com/the-ghosts-of-gettysburg/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salem Wax Museum', 'salem-wax-museum', 'haunted', 42.52027, -70.89154, 'Salem', 'MA', 'Wax figures depict scenes and characters from Salem''s colonial history and witch-trial era in an intentionally old-school attraction. The museum is small and theatrical rather than academic, making the vintage presentation itself part of the OddWay appeal.', 'limited', null, 'https://www.salemwaxmuseum.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.salemwaxmuseum.com/', null, null, null, 'America/New_York'),
  ('Sassy Trash', 'sassy-trash', 'haunted', 36.84725, -83.3226, 'Harlan', 'KY', 'This downtown artisan shop occupies a three-story early twentieth-century building with stories of ringing bells, unexplained music and other reported activity. Harlan County tourism actively includes Sassy Trash on its Haunted Harlan County material, making it a rare paranormal stop that visitors can enter during normal retail hours. Address: 108 N. Main St., Harlan, KY', 'open', null, 'https://www.harlancountytrails.com/haunted-harlan-county-tour/sassy-trash/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Screaming Bridge of Maud Hughes Road', 'screaming-bridge-of-maud-hughes-road', 'haunted', 39.39449, -84.4104, 'Liberty Township', 'OH', 'The railroad overpass on Maud Hughes Road has accumulated decades of local stories involving screams, apparitions and a phantom train, alongside a documented history of serious accidents in the area. The old bridge was replaced and the roadway realigned in 2015, but the legend remains attached to the crossing; there is no pedestrian facility, so do not stop or park on the bridge or enter the railroad property.', 'roadside', null, 'https://www.ohioexploration.com/information/media/journalnews1/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Seabrook-Wilson House — The Spy House', 'seabrook-wilson-house-the-spy-house', 'haunted', 40.43923, -74.09273, 'Middletown Township', 'NJ', 'This eighteenth-century house overlooking Sandy Hook Bay is popularly known as the Spy House because of Revolutionary War stories attached to the property. It has also become one of the Jersey Shore''s better-known haunted-house legends and now serves as a public activity and history center.', 'limited', null, 'https://www.monmouthcountyparks.com/page.aspx?ID=2524', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Seul Choix Pointe Lighthouse', 'seul-choix-pointe-lighthouse', 'haunted', 45.92135, -85.91226, 'Gulliver', 'MI', 'This isolated Lake Michigan light station has become one of the Upper Peninsula''s better-known haunted lighthouse destinations, with stories of apparitions, voices and unexplained movement inside the keeper''s buildings. The Gulliver Historical Society operates the restored museum and tower, while special haunted tours lean directly into the site''s paranormal reputation.', 'limited', null, 'https://www.greatlakelighthouse.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.greatlakelighthouse.com/', null, null, null, 'America/Detroit'),
  ('Sheffield Island Lighthouse', 'sheffield-island-lighthouse', 'haunted', 41.04882, -73.41912, 'Norwalk', 'CT', 'An 1868 lighthouse on Sheffield Island is reached by seasonal boat excursions from Norwalk. Along with its maritime history, the island carries stories of phantom music, unexplained cries and other keeper-era ghost activity, giving the ferry trip a strong OddWay angle.', 'limited', null, 'https://ctvisit.com/articles/haunted-lighthouses', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.seaport.org/', null, null, null, 'America/New_York'),
  ('Shepherdstown Ghost Tours', 'shepherdstown-ghost-tours', 'haunted', 39.43067, -77.80492, 'Shepherdstown', 'WV', 'These guided evening walks explore reported hauntings and darker stories around one of West Virginia''s oldest towns. Tours operate on scheduled dates and require booking rather than offering unrestricted access to the buildings discussed along the route.', 'limited', null, 'https://www.smalltownghosttours.net/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shepherdstown Mystery Walks', 'shepherdstown-mystery-walks', 'haunted', 39.43075, -77.80591, 'Shepherdstown', 'WV', 'Shepherdstown Mystery Walks leads visitors through the historic district while recounting local ghost stories, strange incidents and town legends. Walks meet near the town''s visitor area and operate on scheduled dates, so check the current calendar before routing here.', 'limited', null, 'https://shepherdstownmysterywalks.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shubert Theatre Ghost Stories', 'shubert-theatre-ghost-stories', 'haunted', 41.30653, -72.92906, 'New Haven', 'CT', 'The historic 1914 Shubert has hosted generations of performers and is included in Connecticut''s haunted-theater lore. Reports have included unexplained sounds and apparitions in the old venue. It remains an active theater, so the proper way to experience the building is through a performance, tour or authorized event.', 'limited', null, 'https://ctvisit.com/articles/connecticuts-haunted-history-trail', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.shubert.com/', null, null, null, 'America/New_York'),
  ('Silver Run Tunnel', 'silver-run-tunnel', 'haunted', 39.20769, -81.19664, 'Cairo', 'WV', 'Tunnel No. 19 on the North Bend Rail Trail is associated with the “White Woman of Silver Run,” a ghost said to have appeared on the former B&O tracks in front of passing trains. The 1,376-foot tunnel is publicly reachable from the rail trail, but it is dark, damp and requires a walk or bike ride to reach, so visitors should bring a light.', 'limited', null, 'https://wvtourism.com/the-west-virginia-paranormal-trail-just-got-spookier-with-these-4-new-locations/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sinister Sidney', 'sinister-sidney', 'haunted', 40.748182, -95.635706, 'Sidney', 'IA', 'Sinister Sidney is a seasonal southwest Iowa haunted attraction built around dark trails, sets and live actors. It generally operates on select fall nights, making it a Halloween-season stop rather than a year-round destination.', 'limited', null, 'https://www.facebook.com/SinisterSidney/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 6239206983, 'America/Chicago'),
  ('South Bass Island Lighthouse', 'south-bass-island-lighthouse', 'haunted', 41.6291, -82.8414, 'Put-in-Bay Township', 'OH', 'The South Bass Island Lighthouse was completed in 1897, and tragedy arrived almost immediately when assistant keeper Harry Anderson died during the island''s 1898 smallpox outbreak. The lighthouse later developed stories of unexplained activity connected to its keepers; the grounds can be viewed publicly, while interior and tower access is limited to scheduled open houses or tours.', 'limited', null, 'https://www.visitputinbay.org/haunted-spirits-put-in-bay/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Split Rock Quarry and the Crusher', 'split-rock-quarry-and-the-crusher', 'haunted', 43.02454, -76.24219, 'Onondaga', 'NY', 'A massive explosion at the Split Rock munitions plant killed more than 50 workers in 1918, and the abandoned quarry later developed stories of phantom footsteps, voices and machinery. The surviving stone Crusher can still be reached on foot within the wooded former factory site, but it is an undeveloped hike and visitors should stay on the permitted public route.', 'limited', null, 'https://hauntedhistorytrail.com/explore/split-rock-quarry', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('SpookyWorld Presents Nightmare New England', 'spookyworld-presents-nightmare-new-england', 'haunted', 42.88052, -71.46828, 'Litchfield', 'NH', 'SpookyWorld and Nightmare New England combine several large haunted attractions on one property, including indoor haunts, outdoor trails and themed experiences. The operation traces its identity back to the influential SpookyWorld attraction that helped shape New England''s commercial haunted-house scene. It is ticketed and operates on selected dates during the Halloween season.', 'limited', null, 'https://www.nightmarenewengland.com/events', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.nightmarenewengland.com/', null, null, null, 'America/New_York'),
  ('Spring Street Historical Museum', 'spring-street-historical-museum', 'haunted', 32.51441, -93.74601, 'Shreveport', 'LA', 'The museum occupies the 1865 Tally''s Bank building, one of downtown Shreveport''s oldest surviving structures. Staff and local storytellers have also attached ghost reports to the building, adding paranormal lore to its architectural history.', 'limited', null, 'https://www.visitshreveportbossier.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Squire''s Castle', 'squires-castle', 'haunted', 41.57994, -81.41926, 'Willoughby Hills', 'OH', 'Squire''s Castle is the stone gatehouse of an estate that Standard Oil executive Feargus B. Squire planned but never completed. Stories later developed about the ghost of Squire''s wife haunting the building, although the tale does not match the documented family history; the castle itself remains freely accessible in Cleveland Metroparks during park hours.', 'open', null, 'https://www.atlasobscura.com/places/squires-castle', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Albans Sanatorium', 'st-albans-sanatorium', 'haunted', 37.13972, -80.57806, 'Fairlawn', 'VA', 'The property began as a boys'' school before becoming St. Albans psychiatric hospital in 1916, and its long institutional history has made it one of Virginia''s best-known paranormal investigation sites. The building is private and entry is allowed only through authorized tours, haunted events or scheduled investigations; never enter outside an official event.', 'limited', null, 'https://stalbans-sanatorium.com/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Augustine Lighthouse & Maritime Museum', 'st-augustine-lighthouse-maritime-museum', 'haunted', 29.88552, -81.28881, 'St. Augustine', 'FL', 'Historic lighthouse known for maritime archaeology, keeper history, and long-running ghost lore.', 'limited', null, 'https://www.staugustinelighthouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stepney Cemetery', 'stepney-cemetery', 'haunted', 41.32246, -73.2631, 'Monroe', 'CT', 'An old Monroe cemetery appears repeatedly in Connecticut ghost lore, particularly in stories connected with the region''s famous White Lady tradition. Ed and Lorraine Warren are also buried here. Visitors should observe posted hours and avoid nighttime investigation or disturbance.', 'limited', null, 'https://ctvisit.com/articles/haunted-cemeteries', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stetson Mansion', 'stetson-mansion', 'haunted', 29.01999, -81.31606, 'DeLand', 'FL', 'Elaborate 1886 mansion with unusual architectural details and persistent ghost stories.', 'limited', null, 'https://www.stetsonmansion.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stone''s Public House', 'stones-public-house', 'haunted', 42.25969, -71.46458, 'Ashland', 'MA', 'This 1830s former railroad inn openly embraces stories of apparitions, unexplained sounds and other paranormal activity. It remains an operating Irish-American restaurant and pub, making it one of the easiest alleged-haunting stops in Massachusetts to visit without trespassing or joining a special tour.', 'open', null, 'https://www.atlasobscura.com/places/stones-public-house', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.stonespublichouse.com/', null, null, null, 'America/New_York'),
  ('Story Inn Blue Lady', 'story-inn-blue-lady', 'haunted', 39.09898, -86.21411, 'Story', 'IN', 'Guests at the historic Story Inn have long reported a female apparition known as the Blue Lady, particularly around one of the inn''s rooms. Accounts collected by the property describe details such as the scent of peaches and sightings near a dressing table, while the active inn allows visitors to experience the location through normal lodging and dining access.', 'limited', null, 'https://storyinn.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://storyinn.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Stranahan House', 'stranahan-house', 'haunted', 26.11869, -80.14422, 'Fort Lauderdale', 'FL', 'Historic riverside house with pioneer history and long-running ghost stories.', 'limited', null, 'https://stranahanhouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sweet Dreams Haunted Attraction', 'sweet-dreams-haunted-attraction', 'haunted', 30.688622, -88.053745, 'Mobile', 'AL', 'Sweet Dreams is an immersive indoor haunted attraction in Mobile built around theatrical sets, live actors, scare zones and horror-themed side activities. It operates on select nights during the Halloween season rather than as a year-round attraction.', 'limited', null, 'https://sweetdreamshaunt.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://sweetdreamshaunt.com', null, 'node', 13565360401, 'America/Chicago'),
  ('Tampa Theatre', 'tampa-theatre', 'haunted', 27.95085, -82.45958, 'Tampa', 'FL', 'Ornate 1926 atmospheric movie palace with elaborate faux-Mediterranean interiors and ghost lore.', 'limited', null, 'https://tampatheatre.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Temple Heights Spiritual Camp', 'temple-heights-spiritual-camp', 'haunted', 44.34585, -68.95182, 'Northport', 'ME', 'Founded in the 1800s, Temple Heights developed as a Spiritualist camp centered on mediumship, spirit communication, healing, and religious gatherings. The community still hosts scheduled services, readings, and events, making it a living continuation of New England Spiritualism rather than simply a historic site.', 'limited', null, 'https://www.atlasobscura.com/places/temple-heights-spiritual-camp', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('The 1723 James House', 'the-1723-james-house', 'haunted', 42.94194, -70.86222, 'Hampton', 'NH', 'One of Hampton''s oldest surviving houses has developed a reputation for unexplained footsteps, laughter, slamming doors and other reported activity. The organization that preserves the property has hosted paranormal programs and investigations rather than distancing itself from the folklore. Visits should be made through scheduled openings or authorized events.', 'limited', null, 'https://www.visitnh.gov/blog/undiscovered-nh-spooky-stops', '2026-09-09T04:49:39.808526+00:00', null, 'https://jameshousemuseum.org/', null, null, null, 'America/New_York'),
  ('The 1890 House Museum', 'the-1890-house-museum', 'haunted', 42.59614, -76.18222, 'Cortland', 'NY', 'This elaborate stone mansion was built for industrialist Chester Wickwire and his family in 1890. Reports of footsteps, shadows, knocking and figures in the windows have made it a local paranormal destination; the museum operates seasonally and also offers scheduled ghost-hunting events and private investigations.', 'limited', null, 'https://hauntedhistorytrail.com/explore/the-1890-house-museum', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Anchorage Mansion', 'the-anchorage-mansion', 'haunted', 39.41441, -81.46333, 'Marietta', 'OH', 'The Anchorage, originally called Putnam Villa, was built in 1859 and survives as one of Marietta''s imposing nineteenth-century houses. Hidden Marietta uses the property for guided haunted-history tours, flashlight tours and paranormal investigations, with entry limited to scheduled programs and reservations.', 'limited', null, 'https://hiddenmarietta.com/the-anchorage-mansion', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Bates Motel & Haunted Hayride', 'the-bates-motel-haunted-hayride', 'haunted', 39.945144, -75.49665, 'Edgmont Township', 'PA', 'The Bates Motel & Haunted Hayride is a major Philadelphia-area Halloween attraction combining a haunted hayride with the Bates Motel walk-through and additional outdoor scare experiences. It operates on select dates during the fall season and is built as a theatrical haunt rather than a historic motel.', 'limited', null, 'https://thebatesmotel.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://thebatesmotel.com/', null, 'node', 12304730005, 'America/New_York'),
  ('The Bellaire House', 'the-bellaire-house', 'haunted', 40.00279, -80.74478, 'Bellaire', 'OH', 'This Belmont Street house has become one of eastern Ohio''s best-known dedicated paranormal investigation properties, with stories involving apparitions, voices and other unexplained activity. It operates as a ticketed paranormal attraction with tours and overnight investigations, so visitors need to book access and should not treat the residential property as an open walk-in site.', 'limited', null, 'https://www.bellairehousetours.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Brewerie at Union Station — Haunted History', 'the-brewerie-at-union-station-haunted-history', 'haunted', 42.12082, -80.0822, 'Erie', 'PA', 'Erie''s Union Station opened in 1927, and the Brewerie''s own history preserves the local legend of "Clara," a child said to have died on its marble stairs and linger in the station afterward. The Brewerie has operated here since 2006 as a normal restaurant and brewpub, with ticketed Haunted History Tours offered on selected dates.', 'open', null, 'https://www.brewerie.com/history.html', '2026-09-07T15:27:08.742137+00:00', null, 'https://www.brewerie.com/tours.html', null, null, null, 'America/New_York'),
  ('The Castle Historic House Museum', 'the-castle-historic-house-museum', 'haunted', 39.42054, -81.45502, 'Marietta', 'OH', 'This Gothic Revival mansion was completed in 1855 and is now preserved as a historic house museum in Marietta. The property also hosts ghost tours built around reported sightings, unexplained sounds and local stories associated with the house, while normal historical tours provide daytime access.', 'open', null, 'https://mariettaohio.org/events/the-castle-ghost-tour/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Conjuring House', 'the-conjuring-house', 'haunted', 42.00926, -71.70916, 'Harrisville', 'RI', 'The Arnold Estate farmhouse became internationally famous through claims investigated by Ed and Lorraine Warren and later dramatized in The Conjuring. The property has changed ownership and is undergoing restoration; the current operator states that it is private and plans to resume tours after restoration is complete. Do not enter the property unless an authorized visit is announced.', 'private', null, 'https://www.conjuringhouseofficial.com/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.conjuringhouseofficial.com/', null, null, null, 'America/New_York'),
  ('The Dark Manor Haunted House', 'the-dark-manor-haunted-house', 'haunted', 41.597772, -72.046822, 'Sprague', 'CT', 'Dark Manor is a seasonal Connecticut haunted attraction combining a large indoor haunted house with outdoor graveyard, village and trail-style scenes. It operates on select fall nights and is designed as a theatrical scare attraction rather than a genuinely historic haunted site.', 'limited', null, 'https://darkmanorproductions.com/', '2026-09-05T22:12:28.444612+00:00', null, null, '+1 860 822 8662', 'way', 926063400, 'America/New_York'),
  ('The Fear Factory', 'the-fear-factory', 'haunted', 36.425363, -89.056996, 'Union City', 'TN', 'The Fear Factory was a multi-floor seasonal haunted attraction in downtown Union City built inside a large old commercial building. Reliable current operating information is scarce, so it should not be marked open until a current season or operator is confirmed.', 'closed', null, 'https://www.thepacer.net/haunted-house-review-fear-factory/', null, null, null, null, 'node', 12165400492, 'America/Chicago'),
  ('The Haunted Blennerhassett Hotel', 'the-haunted-blennerhassett-hotel', 'haunted', 39.26477, -81.56154, 'Parkersburg', 'WV', 'The Blennerhassett opened in 1889 and remains an operating historic hotel in downtown Parkersburg. Guests and paranormal tours have attached numerous apparition, voice and unexplained-activity stories to the building, making it one of the city''s best-known haunted landmarks.', 'open', null, 'https://www.hauntedparkersburgtours.com/13-haunted-places-near-parkersburg', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Haunted Haymond', 'the-haunted-haymond', 'haunted', 38.6625, -80.70917, 'Sutton', 'WV', 'This century-old Sutton house is promoted for paranormal tours and overnight investigations centered on stories of former residents William and Emma Haymond. It is not a normal walk-in museum; tours and overnight access are by appointment or scheduled event.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Haunted Hinsdale House', 'the-haunted-hinsdale-house', 'haunted', 42.16731, -78.34226, 'Hinsdale', 'NY', 'The Dandy family reported lights switching on by themselves, chanting from the woods and apparitions after moving into this McMahon Road house in the early 1970s, eventually seeking an exorcism. The property is now a paranormal research site offering scheduled day tours, ghost tours and overnight investigations rather than ordinary walk-in access.', 'limited', null, 'https://hauntedhistorytrail.com/explore/the-haunted-hinsdale-house', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Haunted Hotel', 'the-haunted-hotel', 'haunted', 30.083183, -94.099344, 'Beaumont', 'TX', 'The Haunted Hotel is a long-running Beaumont seasonal haunt that fills a large indoor space with themed rooms, live actors, animatronics and horror sets. It operates on select fall nights and should be treated as limited outside Halloween season.', 'limited', null, 'https://hauntedhoteltx.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 542860725, 'America/Chicago'),
  ('The Haunted Jail', 'the-haunted-jail', 'haunted', 41.155809, -85.48714, 'Columbia City', 'IN', 'The Haunted Jail is a seasonal scare attraction in downtown Columbia City that transforms a jail-themed space into a live-actor Halloween walkthrough. It has operated for decades but is only available during its posted fall schedule.', 'limited', null, 'https://www.facebook.com/TheHauntedJail/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 5931585811, 'America/Indiana/Indianapolis'),
  ('The Haunted Mansion', 'the-haunted-mansion-3', 'haunted', 43.627582, -89.776242, 'Wisconsin Dells', 'WI', 'The Haunted Mansion in Wisconsin Dells is a classic downtown walk-through funhouse filled with monsters, spooky scenes, effects and old-school haunted-house gags. It operates during the Dells tourist season rather than only on Halloween, but its schedule is still seasonal.', 'limited', null, 'https://www.dellshauntedmansion.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 9189369882, 'America/Chicago'),
  ('The Horse You Came In On Saloon', 'the-horse-you-came-in-on-saloon', 'haunted', 39.28154, -76.5941, 'Baltimore', 'MD', 'A tavern has operated at this Fell''s Point location since the 18th century, and the modern saloon has long embraced stories linking the building to Edgar Allan Poe and a resident ghost known as Edgar. It remains an operating bar and live-music venue rather than a formal paranormal attraction.', 'open', null, 'https://www.atlasobscura.com/places/the-horse-you-came-in-on-saloon-baltimore-maryland', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Huntting''s Pumpkin Patch and Haunted Forest', 'the-huntting-s-pumpkin-patch-and-haunted-forest', 'haunted', 46.571092, -122.5542, 'Cinebar', 'WA', 'Huntting''s is a family-run pumpkin patch near Cinebar that adds a haunted forest and nighttime attractions during the Halloween season. Daytime visitors can expect the farm and pumpkin-patch experience, while the haunted portion is limited to specific fall evenings.', 'limited', null, 'https://thehunttings.business.site/', '2026-09-05T22:12:28.444612+00:00', 'Sep Fr[-1]-Oct 31 Mo-Su 10:00-23:00', 'https://thehunttings.business.site', '+1-360-388-7920', 'node', 11214339511, 'America/Los_Angeles'),
  ('The Myrtles Plantation', 'the-myrtles-plantation', 'haunted', 30.80369, -91.38785, 'St. Francisville', 'LA', 'The Myrtles is one of Louisiana''s most aggressively marketed haunted historic properties, with long-running legends of apparitions and a famously discussed mirror. It operates as an inn and tour attraction, so access depends on bookings and scheduled tours.', 'limited', null, 'https://www.myrtlesplantation.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Old Hospital on College Hill', 'the-old-hospital-on-college-hill', 'haunted', 37.67495, -82.27287, 'Williamson', 'WV', 'Opened as a hospital in 1928, this large hilltop building served medical and later office uses before becoming a public historic and paranormal-tour destination in 2021. Current visits are through scheduled tours, investigations and special events; it is not a daily walk-in attraction.', 'limited', null, 'https://www.collegehillhospital.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Paranormal Museum', 'the-paranormal-museum', 'haunted', 40.21596, -74.01142, 'Asbury Park', 'NJ', 'This small museum inside Paranormal Books & Curiosities is devoted to ghosts, legends, cursed objects and other unexplained material. Its collection includes haunted dolls, Ouija boards and rotating exhibits, with access generally through scheduled docent-led tours.', 'limited', null, 'https://visitnj.org/paranormal-museum-paranormal-books-curiosities', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Pfister Hotel', 'the-pfister-hotel', 'haunted', 43.03944, -87.90572, 'Milwaukee', 'WI', 'Milwaukee''s grand 1893 Pfister Hotel has accumulated decades of ghost stories, including reports from visiting professional athletes who have described unexplained noises, moving objects and apparitions. It remains a functioning luxury hotel, so the paranormal reputation can be experienced without treating the building like an abandoned haunt.', 'open', null, 'https://www.thepfisterhotel.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.thepfisterhotel.com/', null, null, null, 'America/Chicago'),
  ('The Ridges', 'the-ridges', 'haunted', 39.32026, -82.1094, 'Athens', 'OH', 'The Athens Lunatic Asylum opened in 1874 and eventually became the enormous complex now called The Ridges, which Ohio University acquired after the hospital era ended. The grounds and trails are public and parts of the complex now house university facilities and the Kennedy Museum, while abandoned or restricted buildings are off-limits; the site''s institutional history has made it one of Athens'' best-known paranormal locations.', 'limited', null, 'https://www.ohio.edu/ridges/visit', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('The White Lady of Durand Eastman Park', 'the-white-lady-of-durand-eastman-park', 'haunted', 43.23597, -77.55674, 'Irondequoit', 'NY', 'For generations, people around Durand Eastman Park have told stories of a white-clad woman wandering near Lake Ontario with ghostly hounds while searching for her missing daughter. A Legends & Lore marker now stands on Lakeshore Boulevard near the park and the stone ruins popularly called the White Lady''s Castle.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/the-white-lady/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Windham Restaurant', 'the-windham-restaurant', 'haunted', 42.80613, -71.26212, 'Windham', 'NH', 'This restaurant occupies a historic building that has accumulated stories of apparitions, footsteps and unexplained activity. Its ghost lore has been publicized alongside the building''s long local history, making it one of New Hampshire''s easier haunted stops to visit without joining a special tour. It remains an operating restaurant.', 'open', null, 'https://www.visitnh.gov/blog/undiscovered-nh-spooky-stops', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.windhamrestaurant.com/', null, null, null, 'America/New_York'),
  ('Thirteen Curves', 'thirteen-curves', 'haunted', 42.98883, -76.25056, 'Onondaga', 'NY', 'Cedarvale Road''s twisting section known as Thirteen Curves is associated with the legend of a newlywed bride who died with her husband and still wanders the road looking for him. A Legends & Lore marker stands near Cedarvale Road and West Seneca Turnpike, so visitors do not need to stop on the narrow curves themselves.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/thirteen-curves/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Three Chimneys Inn', 'three-chimneys-inn', 'haunted', 43.13225, -70.91877, 'Durham', 'NH', 'Built in 1649, Three Chimneys Inn occupies one of the oldest surviving homes in New Hampshire and still operates as lodging. Local ghost lore centers on a presence called Hannah, said to be connected to a drowning in the Oyster River and blamed for unexplained disturbances involving electronics. The haunting is folklore, but the building itself is a legitimate historic inn visitors can stay in.', 'open', null, 'https://www.ci.durham.nh.us/fridayupdate/friday-updates-august-17th-2018', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.threechimneysinn.com/', null, null, null, 'America/New_York'),
  ('Thurber House', 'thurber-house', 'haunted', 39.96578, -82.98522, 'Columbus', 'OH', 'Humorist James Thurber lived in this house as a child, and unexplained noises experienced by his family helped inspire his story "The Night the Ghost Got In." The restored house is now a literary museum with regular weekend hours, and it also permits scheduled private ghost investigations.', 'open', null, 'https://www.thurberhouse.org/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tilton Inn', 'tilton-inn', 'haunted', 43.44252, -71.58833, 'Tilton', 'NH', 'This historic inn has survived multiple fires and accumulated stories of unexplained footsteps, apparitions and other paranormal activity. One of the best-known legends concerns a young girl named Laura, while the Sanborn Room has also been singled out in ghost stories and investigations. It remains an active inn and restaurant rather than a dedicated haunted attraction.', 'open', null, 'https://www.visitnh.gov/blog/undiscovered-nh-spooky-stops', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.thetiltoninn.com/', null, null, null, 'America/New_York'),
  ('Tinker Swiss Cottage Museum', 'tinker-swiss-cottage-museum', 'haunted', 42.26528, -89.10194, 'Rockford', 'IL', 'A remarkable Swiss-inspired Victorian home whose preserved rooms, family artifacts, and long-running ghost stories make it unusually atmospheric.', 'limited', null, 'https://www.tinkercottage.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tomb of the Mather Family', 'tomb-of-the-mather-family', 'haunted', 42.36738, -71.05551, 'Boston', 'MA', 'Increase Mather and his son Cotton Mather are buried together in Copp''s Hill Burying Ground. Cotton became deeply connected to colonial writings about witchcraft and defended the Salem witch trials in ''Wonders of the Invisible World,'' giving this otherwise modest brick tomb an unusually dark historical association.', 'open', null, 'https://www.atlasobscura.com/places/tomb-mather-family', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Trans-Allegheny Lunatic Asylum', 'trans-allegheny-lunatic-asylum', 'haunted', 39.038246, -80.471814, 'Weston', 'WV', 'A quarter-mile of hand-cut sandstone, built for 250 patients and holding well over two thousand by the 1950s. Daytime tours cover the architecture and the medical history; the overnight ones cover the reason most people have heard of it.', 'limited', null, 'https://trans-alleghenylunaticasylum.com/', '2026-09-06T01:56:28.154232+00:00', null, 'https://trans-alleghenylunaticasylum.com/', '+1-304-259-5070', 'way', 374509925, 'America/New_York'),
  ('Trimper''s Haunted House', 'trimpers-haunted-house', 'haunted', 38.32653, -75.08808, 'Ocean City', 'MD', 'Built in 1964 and designed by legendary dark-ride creator Bill Tracy, Trimper''s Haunted House is one of the few surviving Tracy attractions still operating in its original location. The two-story boardwalk ride retains vintage stunts alongside newer effects and operates seasonally with Trimper Rides.', 'limited', null, 'https://trimpershauntedhouse.com/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Twin City Opera House', 'twin-city-opera-house', 'haunted', 39.649, -81.85349, 'McConnelsville', 'OH', 'Twin City Opera House opened in 1892 and still operates as a theater and movie house in downtown McConnelsville. Decades of reports involving footsteps, voices and apparitions have made it a major Ohio paranormal site, and the theater offers scheduled public ghost hunts and private investigations rather than unrestricted after-hours access.', 'limited', null, 'https://hauntedtwincityoperahouse.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Union Cemetery — White Lady Legend', 'union-cemetery-white-lady-legend', 'haunted', 41.27277, -73.29698, 'Easton', 'CT', 'Union Cemetery is associated with one of Connecticut''s most famous apparitions, the White Lady, along with stories of glowing red eyes and other roadside encounters. The haunting claims remain folklore, and local authorities have long discouraged trespassing and after-hours ghost hunting.', 'limited', null, 'https://ctvisit.com/articles/haunted-cemeteries', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vale End Cemetery — Blue Lady', 'vale-end-cemetery-blue-lady', 'haunted', 42.8438, -71.77255, 'Wilton', 'NH', 'Vale End Cemetery is associated with the legend of a glowing female apparition called the Blue Lady, often linked in modern retellings to Mary Ritter Spaulding. The story has become one of southern New Hampshire''s better-known cemetery legends despite limited historical evidence for the supernatural claims. Visit during cemetery hours and avoid disturbing graves or neighboring property. Secondary source: https://www.hauntedplaces.org/item/vale-end-cemetery/', 'limited', null, 'https://ournewenglandlegends.com/podcast-393-the-blue-lady-of-vale-end-cemetery/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Van Lear Historical Society Coal Miners'' Museum', 'van-lear-historical-society-coal-miners-museum', 'haunted', 37.77113, -82.75775, 'Van Lear', 'KY', 'The museum occupies the former Consolidation Coal Company office in the historic Van Lear coal camp and preserves artifacts from the surrounding mining community. Kentucky tourism also includes the building among locations with reported paranormal activity and occasional investigation events.', 'limited', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Victoria Theatre', 'victoria-theatre', 'haunted', 39.76223, -84.19174, 'Dayton', 'OH', 'Victoria Theatre opened in 1866 and has accumulated several long-running ghost stories during more than a century and a half of performances. The best-known involves the legendary "Miss Vicki," whose presence is associated with rose perfume, footsteps and a face in a dressing-room mirror; the theater remains an active public performance venue.', 'open', null, 'https://www.destinationdayton.org/blog/post/uncovering-eerie-legends-5-haunted-places-in-dayton-with-tales-to-know-about/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Waverly Hills Sanatorium', 'waverly-hills-sanatorium', 'haunted', 38.13031, -85.84151, 'Louisville', 'KY', 'Opened as a tuberculosis hospital and expanded into its famous five-story form in the 1920s, Waverly Hills later became one of America''s best-known paranormal destinations. The preserved building now offers historical tours, nighttime paranormal tours and longer investigations, including access to the notorious body chute area through authorized programs.', 'limited', null, 'https://thewaverlyhillssanatorium.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://thewaverlyhillssanatorium.com/', null, null, null, 'America/Kentucky/Louisville'),
  ('Weird Providence — Lovecraft Arts & Sciences', 'weird-providence-lovecraft-arts-sciences', 'haunted', 41.82382, -71.41015, 'Providence', 'RI', 'Located inside the historic Arcade, Weird Providence is the home of Lovecraft Arts & Sciences and specializes in weird fiction, cosmic horror, occult material and Providence''s H.P. Lovecraft legacy. The nonprofit also supports NecronomiCon Providence and maintains information about unusual sites around the city.', 'open', null, 'https://www.weirdprovidence.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.weirdprovidence.org/', null, null, null, 'America/New_York'),
  ('West Virginia State Penitentiary Tours', 'west-virginia-state-penitentiary-tours', 'haunted', 39.916014, -80.742304, 'Moundsville', 'WV', 'The former West Virginia Penitentiary is a massive Gothic prison that operated until 1995 and now offers guided history tours through cell blocks, yards and other restricted areas. Visitors can also book public ghost hunts, paranormal investigations and seasonal Halloween experiences, with the normal tour season running on scheduled dates.', 'limited', null, 'https://wvpentours.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.wvpentours.com/', '+1-304-845-6200', 'way', 829669282, 'America/New_York'),
  ('Whispers Estate', 'whispers-estate', 'haunted', 38.73332, -86.47452, 'Mitchell', 'IN', 'Built in the 1890s, this house has been operated specifically as a paranormal attraction rather than simply marketed through outside ghost stories. Whispers Estate offers scheduled investigations and events centered on reported voices, apparitions, movement and other unexplained activity inside the property.', 'limited', null, 'https://whispersestate.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://whispersestate.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('White Hall State Historic Site', 'white-hall-state-historic-site', 'haunted', 37.83292, -84.35241, 'Richmond', 'KY', 'A major nineteenth-century expansion transformed the Clay family home into the sprawling mansion now known as White Hall. The restored house is open for tours and is also associated with long-running reports of moving lights, footsteps, phantom music and apparitions attributed to members of the Clay family.', 'limited', null, 'https://visitrichmondky.com/listing/white-hall-state-historic-house/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('White Horse Inn;White Horse Inn & Bar', 'white-horse-inn-white-horse-inn-bar', 'haunted', 41.998436, -117.719895, 'McDermitt', 'NV', 'The old White Horse Inn near McDermitt is a historic roadside building, but current public records describe the structure as unsafe, with serious deterioration, asbestos and mold concerns. It is not a public haunted attraction and should not be routed for entry or exploration.', 'private', null, 'https://www.humboldtcountynv.gov/DocumentCenter/View/8501/HCC-031824', '2026-09-05T22:12:28.444612+00:00', null, 'http://www.pbase.com/nevada_beeutiful/white_horse_inn_nevada', null, 'way', 1121464184, 'America/Los_Angeles'),
  ('White Horse Tavern', 'white-horse-tavern', 'haunted', 41.4914, -71.31379, 'Newport', 'RI', 'Operating in a building dating to the seventeenth century, the White Horse Tavern is among America''s oldest surviving taverns. The restaurant has accumulated ghost stories involving colonial-era figures and unexplained activity, although these claims remain folklore rather than verified events. It remains an active restaurant rather than a dedicated paranormal attraction.', 'open', null, 'https://www.atlasobscura.com/places/white-horse-tavern', '2026-09-09T04:49:27.913704+00:00', null, 'https://whitehorsenewport.com/', null, null, null, 'America/New_York'),
  ('Whitehaven Welcome Center', 'whitehaven-welcome-center', 'haunted', 37.05087, -88.65298, 'Paducah', 'KY', 'This elaborate 1860s mansion was restored and repurposed as one of America''s most unusual interstate welcome centers. Visitors and employees have also reported apparitions, strange smells and unexplained activity attributed to former residents of the property.', 'open', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Widow Susan Road', 'widow-susan-road', 'haunted', 42.92811, -74.16155, 'Amsterdam', 'NY', 'The road is named for Susan DeGraff, whose ghost is said to appear wearing white and crying while searching for her husband''s grave. A Legends & Lore marker at 179 Widow Susan Road gives travelers a safe physical point for the story rather than encouraging anyone to wander the road at night.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/widow-susan-road/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wildwood Sanitarium', 'wildwood-sanitarium', 'haunted', 42.15829, -78.6924, 'Salamanca', 'NY', 'Wildwood opened in 1906 as a sanitarium and bath house and later served as a tuberculosis clinic and apartments. Visitors and investigators report shadow figures, voices and unexplained physical contact, and the restored property now offers history tours, ghost tours and investigations by reservation.', 'limited', null, 'https://hauntedhistorytrail.com/explore/wildwood-sanitarium', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Willard Library Grey Lady', 'willard-library-grey-lady', 'haunted', 37.97836, -87.57404, 'Evansville', 'IN', 'Willard Library''s best-known legend concerns the "Grey Lady," an apparition reportedly seen inside the Victorian Gothic library for decades. The library openly embraces the story with its long-running Ghost Cams and paranormal programming, making this an unusually accessible haunted-location stop rather than an abandoned site.', 'open', null, 'https://www.willardlib.org/ghost-cams', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.willardlib.org/', null, null, null, 'America/Chicago'),
  ('Wilson Castle', 'wilson-castle', 'haunted', 43.61218, -73.02763, 'Proctor', 'VT', 'This sprawling nineteenth-century mansion mixes Scottish, Romanesque, Dutch and Queen Anne architectural elements into an improbable Vermont castle. Seasonal tours explore its stained glass, antiques and eccentric rooms, while dedicated paranormal tours draw on the property''s long-running ghost stories.', 'limited', null, 'https://www.atlasobscura.com/places/wilson-castle', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Winegar Cemetery''s Mysterious Glowing Grave', 'winegar-cemeterys-mysterious-glowing-grave', 'haunted', 42.79347, -85.75046, 'Byron Center', 'MI', 'For decades, local legend has claimed that a faint greenish light can sometimes be seen around one grave in Winegar Cemetery after dark. Explanations range from ghost stories to reflected light and atmospheric effects, and the phenomenon is best treated as folklore rather than a verified paranormal event; visitors should obey cemetery hours and remain respectful.', 'limited', null, 'https://www.roadsideamerica.com/tip/2863', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Witch Dungeon Museum', 'witch-dungeon-museum', 'haunted', 42.52257, -70.89719, 'Salem', 'MA', 'This long-running Salem attraction combines a live witch-trial reenactment with a basement recreation of the cramped conditions endured by accused prisoners. It is more theatrical than scholarly, but its aging wax figures and dungeon scenes make it a particularly OddWay version of Salem tourism.', 'limited', null, 'https://www.atlasobscura.com/places/witch-dungeon-museum', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.witchdungeon.com/', null, null, null, 'America/New_York'),
  ('Witch History Museum', 'witch-history-museum', 'haunted', 42.52149, -70.89406, 'Salem', 'MA', 'A guided underground attraction recreates scenes from the Salem witch trials using figures, narration and dungeon-like spaces. It overlaps thematically with other Salem museums, but the basement walkthrough and reconstructed village scenes provide a distinct traveler experience.', 'limited', null, 'https://www.witchhistorymuseum.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.witchhistorymuseum.com/', null, null, null, 'America/New_York'),
  ('Witch Mansion Haunted House', 'witch-mansion-haunted-house', 'haunted', 42.521794, -70.89348, 'Salem', 'MA', 'Witch Mansion is a walk-through Salem attraction using witches, ghosts, monsters, lighting effects and animated scenes to create a traditional haunted-house experience. It operates on a seasonal schedule that expands heavily during Salem''s October crowds.', 'limited', null, 'https://www.witchmansion.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 13043301667, 'America/New_York'),
  ('Witch''s Tower', 'witchs-tower', 'haunted', 39.70992, -84.18012, 'Kettering', 'OH', 'The stone Lookout Tower at Hills & Dales MetroPark, commonly called the Witch''s Tower or Frankenstein''s Castle, was completed in 1941. A teenage girl was killed by lightning at the tower in 1967, after which stories of ghostly figures became attached to it; the tower''s entrance is sealed, but hikers can reach and view the exterior from the park trail.', 'limited', null, 'https://www.daytondailynews.com/what-to-do/the-ghostly-tales-behind-hills-dales-witchs-tower/M55XOSN3I5CTJKSAAITLOOPG4E/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wood Island Lighthouse', 'wood-island-lighthouse', 'haunted', 43.45679, -70.32898, 'Biddeford Pool', 'ME', 'Wood Island Light stands offshore from Biddeford Pool and has accumulated stories of unexplained voices, footsteps, and other activity tied to the island’s difficult past. The lighthouse is not connected to the mainland by road, so closer visits depend on seasonal boat access and tour availability.', 'limited', null, 'https://lighthousefoundation.org/lighthouses/wood-island-light/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Woodburn — The Governor''s Haunted House', 'woodburn-the-governors-haunted-house', 'haunted', 39.16097, -75.52378, 'Dover', 'DE', 'Delaware''s governor''s residence carries one of the state''s oldest official ghost stories: the so-called "tippling ghost," said to help itself to guests'' drinks. The Delaware Public Archives preserves the legend but explicitly does not authenticate paranormal claims; public access is limited to scheduled events.', 'limited', null, 'https://archives.delaware.gov/2010/03/17/haunted-delaware/', '2026-09-08T18:31:51.932734+00:00', null, 'https://governor.delaware.gov/woodburn/', null, null, null, 'America/New_York'),
  ('Woodland Cemetery and Sumner Knight Chapel', 'woodland-cemetery-and-sumner-knight-chapel', 'haunted', 42.94322, -72.2686, 'Keene', 'NH', 'Woodland Cemetery''s stone chapel and surrounding graves have generated local stories about laughter, apparitions and a spirit that supposedly reacts to visitors who swear. The Sumner Knight Chapel gives the folklore a dramatic physical setting within the cemetery. Public cemetery access does not imply permission to enter locked buildings or conduct investigations after hours.', 'limited', null, 'https://www.hauntedplaces.org/item/sumner-knight-chapel-woodland-cemetery/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Woodruff-Fontaine House Museum', 'woodruff-fontaine-house-museum', 'haunted', 35.14498, -90.03767, 'Memphis', 'TN', 'This ornate Victorian mansion preserves period interiors and has accumulated long-running stories of apparitions and unexplained activity. The house operates as a legitimate museum, giving visitors a structured way to experience the building without relying on trespass-based ghost hunting.', 'limited', null, 'https://woodruff-fontaine.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Zak Bagan''s The Haunted Museum', 'zak-bagan-s-the-haunted-museum', 'haunted', 36.158381, -115.145638, 'Las Vegas', 'NV', 'Zak Bagans'' The Haunted Museum fills a historic Las Vegas mansion with rooms devoted to paranormal objects, notorious crimes, occult artifacts and items claimed to be cursed or haunted. Visitors follow a guided experience through the collection, with age restrictions and upgraded experiences available.', 'open', null, 'https://thehauntedmuseum.com/', '2026-09-05T22:12:28.444612+00:00', 'Mo, We-Sa 13:00-21:00; Su 12:00-20:00', 'https://thehauntedmuseum.com/', '+1-702-444-0744', 'way', 806953202, 'America/Los_Angeles'),
  ('Alien Rock Formation near Cliff Dwellers', 'alien', 'ufos', 36.782399, -111.766073, 'Marble Canyon', 'AZ', 'An OpenStreetMap node named only Alien, about two and a half miles north of Cliff Dwellers in Coconino County — in the Vermilion Cliffs and Marble Canyon country, not near LeChee. No independent source explains what the feature is, who named it, or whether it is an established stop at all, and we have not confirmed the land status. Treat it as an unverified lead rather than a destination.', 'limited', null, 'https://www.openstreetmap.org/node/5596600521', null, null, null, null, null, null, 'America/Denver'),
  ('Alien Museum at Rockin'' Rollers', 'alien-museum', 'ufos', 35.662973, -105.998555, 'Santa Fe', 'NM', 'Mapped as the Alien Museum, this shares an address with Rockin'' Rollers Event Arena, a long-running roller rink known for its extensive alien-themed decor. There is no separate museum with its own hours — you see the extraterrestrial displays by turning up to a public skating session or an event.', 'limited', null, 'https://www.santafe.org/things-to-do/family-activities/', '2026-09-06T01:53:15.49385+00:00', null, null, null, null, null, 'America/Denver'),
  ('Alien Woman Hoodoo, Bisti Badlands', 'alien-woman', 'ufos', 36.270912, -108.226433, 'West Hammond', 'NM', 'Not a statue or a business but a naturally eroded rock formation in the Bisti Rock Garden, among named hoodoos including the Elegant Hoodoo and the Valley of Bones. This is BLM-managed federal wilderness rather than Navajo Nation land. Open to hikers, but there are no marked routes, effectively no phone signal or water, and access roads can become impassable after rain or snow.', 'limited', null, 'https://www.blm.gov/visit/bisti-de-na-zin-wilderness', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Denver'),
  ('Area 51 Alien Center', 'area-51-alien-center', 'ufos', 36.643767, -116.395984, 'Amargosa Valley', 'NV', 'A commercial alien-themed travel centre on US 95 — fuel, food, a gift shop and a great deal of Area 51 merchandise, rather than a museum or a crash site. Open daily from 5am to 11pm, and an easy walk-in stop rather than a destination.', 'open', null, 'https://area51aliencenter.net/', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Area 51 North Gate (Rachel Back Gate)', 'area-51-back-gate', 'ufos', 37.594035, -115.898805, 'Alamo', 'NV', 'Where a public desert road meets the heavily monitored northern boundary of the Nevada Test and Training Range. You may go as far as the warning signs, fence and gate and no further: beyond that line is restricted military property patrolled by armed security. Obey every posted trespass and photography warning.', 'roadside', null, 'https://travelnevada.com/extraterrestrial/area-51/', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Avrocar', 'avrocar', 'ufos', 39.78225, -84.10767, 'Dayton', 'OH', 'The Avrocar was a real Cold War attempt to build a disc-shaped vertical-takeoff aircraft that looked remarkably like the flying saucers dominating UFO culture at the time. One surviving example is displayed inside the National Museum of the United States Air Force, where admission is free during museum hours.', 'open', null, 'https://www.atlasobscura.com/places/avrocar', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belleville UFO Day and 1987 Sighting Story', 'belleville-ufo-day-and-1987-sighting-story', 'ufos', 42.85972, -89.53818, 'Belleville', 'WI', 'Belleville commemorates a January 1987 incident in which local residents and police reported unusual lights in the sky. The village now leans into the story with UFO Day, alien decorations and community programming, making downtown a practical public stop tied to the sighting lore.', 'limited', null, 'https://bellevillewi.com/ufo/', '2026-09-09T13:02:00.307533+00:00', null, 'https://bellevillewi.com/', null, null, null, 'America/Chicago'),
  ('Betty and Barney Hill Archive', 'betty-and-barney-hill-archive', 'ufos', 43.13551, -70.93323, 'Durham', 'NH', 'UNH''s Milne Special Collections at Dimond Library preserves the Betty and Barney Hill Papers, including journals, correspondence, photographs, recordings, Betty''s dress and other material connected to their reported encounter and later UFO research. The collection is open for research by appointment rather than as a walk-in exhibit. Special Collections currently requires advance appointments. Secondary source: https://innovation.unh.edu/unh-innovation-spotlight-betty-barney-hill-collection', 'limited', null, 'https://library.unh.edu/find/archives/collections', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Betty and Barney Hill Incident Historical Marker', 'betty-and-barney-hill-incident-historical-marker', 'ufos', 44.08547, -71.68413, 'Lincoln', 'NH', 'A state historical marker on U.S. Route 3 commemorates the 1961 experience reported by Betty and Barney Hill, who said they encountered a strange craft while driving through the White Mountains. Their later account became one of the most influential alleged alien-abduction stories in American popular culture. The marker gives OddWay travelers a concrete route point tied directly to the story.', 'roadside', null, 'https://www.visitnh.gov/blog/undiscovered-nh-spooky-stops', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brown Mountain Lights — Wiseman’s View', 'brown-mountain-lights-wisemans-view', 'ufos', 35.90383, -81.90476, 'Linville Falls', 'NC', 'Unexplained lights have been reported around Brown Mountain for more than a century, with theories ranging from atmospheric effects and vehicle lights to ghosts and UFOs. Wiseman’s View provides one of the best legitimate public viewpoints toward the mountain and is reached by a forest road that can be rough or seasonally affected. Viewing location: https://mapcarta.com/N356580279', 'limited', null, 'https://www.visitnc.com/itinerary/uncover-mountain-mysteries-north-carolinas-haunted-trail', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain Thomas Mantell Jr. UFO Death Marker', 'captain-thomas-mantell-jr-ufo-death-marker', 'ufos', 36.66772, -86.55768, 'Franklin', 'KY', 'On January 7, 1948, Kentucky Air National Guard pilot Thomas Mantell died after climbing while pursuing an unidentified object reported over Kentucky. The incident became an early landmark of the modern UFO era; later investigations have commonly connected the object to a high-altitude balloon and Mantell''s crash to hypoxia, while a Kentucky marker preserves the mystery.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=239316', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carbondale UFO Marker', 'carbondale-ufo-marker', 'ufos', 41.56985, -75.5034, 'Carbondale', 'PA', 'A city historical marker records the November 1974 incident in which teenagers reported a glowing object flying low over Carbondale and crashing into a silt pond near Russell Park. Crowds and investigators descended on the site before a lantern was eventually recovered from the water, but the case remains a major piece of local UFO folklore and now inspires the annual Carbondalien Festival.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=135019', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elmwood UFO Days and UFO Sighting Area', 'elmwood-ufo-days-and-ufo-sighting-area', 'ufos', 44.77939, -92.15131, 'Elmwood', 'WI', 'Elmwood built an unusual civic identity around a series of reported UFO sightings, including a well-known 1975 account involving a local police officer. The village''s annual UFO Days festival celebrates the lore with alien-themed events and gives OddWay a lawful public anchor for a story otherwise spread across rural roads.', 'limited', null, 'https://ufodays.net/', '2026-09-09T13:02:00.307533+00:00', null, 'https://ufodays.net/', null, null, null, 'America/Chicago'),
  ('Exeter Incident Site', 'exeter-incident-site', 'ufos', 42.981, -70.948, 'Kensington', 'NH', 'In September 1965, teenager Norman Muscarello reported a large object with flashing red lights near Route 150 outside Exeter. Police officers later said they also observed unexplained lights, and journalist John G. Fuller''s book "Incident at Exeter" helped turn the case into a classic of American UFO history. The original area is now developed/private land, so this is a roadside history stop only. Secondary source: https://www.visitnh.gov/blog/undiscovered-nh-spooky-stops', 'roadside', null, 'https://www.nhpr.org/nh-news/2015-09-03/50-years-later-the-incident-at-exeter-still-fascinates-ufo-enthusiasts', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graves of Betty and Barney Hill', 'graves-of-betty-and-barney-hill', 'ufos', 42.94318, -71.05854, 'Kingston', 'NH', 'Betty and Barney Hill are buried together in Greenwood Cemetery, far from the White Mountain road where their famous encounter was said to have occurred. Their shared grave has become a pilgrimage point for people interested in UFO history and the couple''s unusual place in American folklore. Visit respectfully and only during lawful cemetery access.', 'limited', null, 'https://www.atlasobscura.com/places/betty-and-barney-hill-graves', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hook-Up Towing UFO', 'hook-up-towing-ufo', 'ufos', 39.856108, -95.5433, 'Hiawatha', 'KS', 'A flying saucer parked outside a towing company in northeast Kansas — roadside advertising that outgrew its purpose. Visible from the road, but the yard is a working business, so look rather than wander in.', 'roadside', null, 'https://www.openstreetmap.org/node/9077872686', '2026-09-06T01:37:28.209467+00:00', null, null, null, null, null, 'America/Chicago'),
  ('International UFO Museum & Research Center', 'international-ufo-museum-research-center', 'ufos', 33.393705, -104.52322, 'Roswell', 'NM', 'The centre of the Roswell industry, in a former cinema on Main Street. Founded in 1991 by people connected to the 1947 incident, it holds exhibits, witness affidavits and a research library, and takes the documentary record rather more seriously than the gift shops around it.', 'open', null, 'https://www.openstreetmap.org/node/1806341993', '2026-09-06T01:37:28.209467+00:00', null, null, null, null, null, 'America/Denver'),
  ('Kecksburg UFO Monument', 'kecksburg-ufo-monument', 'ufos', 40.1834, -79.462, 'Kecksburg', 'PA', 'Something came down in the woods here on the evening of 9 December 1965, seen across several states. Astronomers called it a meteor; witnesses described an acorn-shaped object and a military convoy. The village settled the matter its own way: the large acorn outside the volunteer fire department is a prop built for an Unsolved Mysteries episode in 1990, and it has stood there ever since.', 'roadside', null, 'https://en.wikipedia.org/wiki/Kecksburg_UFO_incident', '2026-09-06T01:56:28.154232+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kelly Little Green Men Encounter', 'kelly-little-green-men-encounter', 'ufos', 36.95922, -87.47757, 'Kelly', 'KY', 'In August 1955, residents of a farmhouse near Kelly reported a nighttime encounter with small strange beings after seeing a bright object in the sky. The Kelly-Hopkinsville incident became one of America''s best-known UFO-era creature encounters, and the community still commemorates it through Little Green Men imagery and events; visitors should stay on public roads and avoid attempting to locate the original private farmhouse.', 'roadside', null, 'https://www.kellyky.com/', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Landing Zone by Peter Reiquam', 'landing-zone', 'ufos', 47.890874, -122.276852, 'Everett', 'WA', 'A public artwork at Paine Field Community Park: a sixteen-foot flying-saucer shelter surrounded by alien boulders and an X-shaped landing-zone bench, commissioned by Snohomish County in 2004 and recognised among the top public art projects of 2010. The park is public and open daily from 7am to dusk.', 'open', null, 'https://snohomishcountywa.gov/Facilities/Facility/Details/Paine-Field-Community-Park-83', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Notch Express Alien Abduction Display', 'notch-express-alien-abduction-display', 'ufos', 44.06418, -71.68695, 'Lincoln', 'NH', 'This otherwise ordinary roadside convenience store has embraced the Betty and Barney Hill story with an alien mural, newspaper clippings, photographs and UFO-related material. The result feels like a tiny roadside museum hidden inside a gas station. It is a separate stop from the nearby state historical marker.', 'open', null, 'https://www.visitnh.gov/blog/undiscovered-nh-spooky-stops', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.loc8nearme.com/new-hampshire/lincoln/notch-express/6382355/', null, null, null, 'America/New_York'),
  ('Pascagoula 1973 UFO Encounter Marker', 'pascagoula-1973-ufo-encounter-marker', 'ufos', 30.37133, -88.56103, 'Pascagoula', 'MS', 'A city-installed marker at Lighthouse Park commemorating the 1973 account in which Charles Hickson and Calvin Parker said they were abducted by strange beings while fishing nearby. The marker documents the cultural history of the claim without asserting that the reported encounter occurred as described.', 'open', null, 'https://www.cityofpascagoula.com/parksrec/page/lighthouse-park', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pine Bush UFO Museum', 'pine-bush-ufo-museum', 'ufos', 41.609741, -74.301059, 'Pine Bush', 'NY', 'The Pine Bush UFO & Paranormal Museum explores the Hudson Valley area''s long history of UFO sightings through interactive exhibits, witness accounts, displays and alien-themed experiences. This is clearly a UFO-focused attraction and belongs in the `ufos` category rather than `haunted`.', 'open', null, 'https://pinebushmuseum.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://pinebushmuseum.com/', null, 'node', 8703565078, 'America/New_York'),
  ('Presque Isle Beach 6 UFO Encounter', 'presque-isle-beach-6-ufo-encounter', 'ufos', 42.14441, -80.13804, 'Erie', 'PA', 'On July 31, 1966, witnesses stranded at Beach 6 reported a luminous metallic object descending near the beach, an incident later investigated as Project Blue Book case 10798. Beach 6 is still an ordinary public beach at Presque Isle State Park—there is no UFO monument—so the physical stop is the location associated with the documented Erie UFO story.', 'open', null, 'https://www.eriereader.com/article/eerie-erie-', '2026-09-07T15:27:08.742137+00:00', null, 'https://www.pa.gov/agencies/dcnr/recreation/where-to-go/state-parks/find-a-park/presque-isle-state-park/swimming', null, null, null, 'America/New_York'),
  ('Roswell crash site (1947)', 'roswell-crash-site-1947', 'ufos', 33.950328, -105.313908, 'Capitan', 'NM', 'These coordinates match the BLM''s Alleged UFO Skip Site, where the agency has built a legal public route: park on Lincoln County Road B007 and walk roughly a mile across BLM land. The old approaches from north and south cross private property and may not be used. Remote, unshaded, and with no water.', 'limited', null, 'https://www.blm.gov/visit/alleged-ufo-skip-site', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Denver'),
  ('Rt 30 Alien', 'rt-30-alien', 'ufos', 43.633298, -74.39443, 'Lake Pleasant', 'NY', 'A roadside alien figure on Route 30 in the Adirondacks, the sort of thing that exists purely so people slow down. A quick photograph rather than a destination.', 'roadside', null, 'https://www.openstreetmap.org/node/9925313103', '2026-09-06T01:37:28.209467+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Black Mailbox', 'the-black-mailbox', 'ufos', 37.457061, -115.482604, 'Alamo', 'NV', 'The long-running meeting point for UFO watchers on the Extraterrestrial Highway, named for rancher Steve Medlin''s mailbox. The original was removed years ago and a succession of replacements has followed; the one standing in July 2025 was reported destroyed by November. Treat the spot as the attraction rather than expecting a particular box to be there.', 'roadside', null, 'https://travelnevada.com/extraterrestrial/black-mailbox/', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Thom Reed UFO Encounter Site', 'thom-reed-ufo-encounter-site', 'ufos', 42.12391, -73.3546, 'Sheffield', 'MA', 'A small area near the covered-bridge site commemorates Thom Reed''s claim that members of his family encountered a UFO here in 1969. The original granite monument became the subject of a local dispute and was removed, but the site remains associated with one of the Berkshires'' best-known UFO stories.', 'open', null, 'https://assets.atlasobscura.com/places/thom-reed-ufo-monument-park', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Travis Walton''s Abduction Site', 'travis-walton-s-abduction-site', 'ufos', 34.299978, -110.649058, 'Heber-Overgaard', 'AZ', 'The Turkey Springs area of the Apache-Sitgreaves National Forest, associated with the incident of 5 November 1975 in which logger Travis Walton''s crew reported a luminous object and Walton disappeared for five days. There is nothing built here: it is public National Forest backcountry on forest and logging roads. Check current road conditions and which routes are legally open before going in.', 'limited', null, 'https://www.navajocountyaz.gov/597/NCSO-History-PDF', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('UFO crash site ( Aztec NM )', 'ufo-crash-site-aztec-nm', 'ufos', 36.878494, -107.841069, 'Aztec', 'NM', 'The claimed site of the alleged crash of 25 March 1948, marked by a plaque placed in 2007, sitting on the BLM-managed Alien Run trail system in Hart Canyon. Both the City of Aztec and the BLM point hikers and mountain bikers here. No admission fee, but it is a remote dirt-road and trail destination with no drinking water.', 'limited', null, 'https://www.blm.gov/visit/alien-run-mountain-bike-trail', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Denver'),
  ('UFO Experience', 'ufo-experience', 'ufos', 33.555006, -111.876563, 'Scottsdale', 'AZ', 'A ticketed indoor exhibition at Arizona Boardwalk covering famous UFO reports, alleged abductions, government and military material and science-fiction pop culture. Open daily 10am to 6pm. Worth knowing that Arizona Boardwalk sits within the Salt River Pima-Maricopa Indian Community: the Scottsdale label is geographically convenient but does not describe the jurisdiction.', 'limited', null, 'https://theufoexperience.com/', '2026-09-07T02:03:56.500228+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('UFO Landing Port', 'ufo-landing-port', 'ufos', 44.444383, -87.837378, 'Poland', 'WI', 'A marked landing pad built for visitors who have not arrived yet, standing by the roadside in rural Wisconsin. Free, always there, and entirely sincere about being a joke.', 'roadside', null, 'https://www.openstreetmap.org/node/4530157043', '2026-09-06T01:37:28.209467+00:00', null, null, null, null, null, 'America/Chicago'),
  ('''War of the Worlds'' Martian Landing Site Monument', 'war-of-the-worlds-martian-landing-site-monument', 'ufos', 40.31274, -74.60509, 'West Windsor Township', 'NJ', 'A bronze monument in Van Nest Park marks the fictional Martian landing site from Orson Welles''s famous 1938 War of the Worlds radio broadcast. Interpretive signs explain how the realistic program convinced some listeners that an alien invasion was actually unfolding in New Jersey.', 'open', null, 'https://www.roadsideamerica.com/story/2749', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('16th Street Baptist Church', '16th-street-baptist-church', 'weird-history', 33.51658, -86.81479, 'Birmingham', 'AL', 'The church was the target of the 1963 Ku Klux Klan bombing that killed four girls and became a defining event of the Civil Rights Movement. It remains an active congregation as well as a historic site; visits must respect services and church rules.', 'limited', null, 'https://16thstreetbaptist.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('1910 U.S. Population Center Marker', '1910-us-population-center-marker', 'weird-history', 39.16683, -86.5342, 'Bloomington', 'IN', 'A stone marker on the Monroe County Courthouse grounds commemorates the point calculated as the geographic center of the United States population after the 1910 Census. The actual statistical point reflected the country''s westward population shift, turning an abstract census calculation into a physical downtown landmark.', 'open', null, 'https://www.nps.gov/nr/feature/places/pdfs/76000013.pdf', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('1921 Standard Oil Gas Station', '1921-standard-oil-gas-station', 'weird-history', 36.9955, -86.43878, 'Bowling Green', 'KY', 'Built in 1921, this domestic-style filling station was Bowling Green''s first dedicated gas station and operated until the 1950s. The city restored it in 2008 with replica glass-topped pumps, and the little station now serves as part of public Circus Square Park.', 'open', null, 'https://www.roadsideamerica.com/tip/69146', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('1946 Nashua Dodgers Mural', '1946-nashua-dodgers-mural', 'weird-history', 42.75751, -71.46598, 'Nashua', 'NH', 'A large mural commemorates the 1946 Nashua Dodgers and players Roy Campanella and Don Newcombe. Their season in Nashua was an important early step in the integration of twentieth-century professional baseball before both men reached the major leagues. The artwork turns that history into an easily accessible downtown stop.', 'open', null, 'https://www.atlasobscura.com/places/1946-nashua-dodgers-mural', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('9/11 Beam Memorial to Local Flight Crew', '9-11-beam-memorial-to-local-flight-crew', 'weird-history', 41.96859, -72.34392, 'Stafford Springs', 'CT', 'A recovered steel beam from the World Trade Center stands outside the West Stafford Fire Department. The memorial particularly honors two local residents who were crew members aboard United Airlines Flight 175.', 'open', null, 'https://www.roadsideamerica.com/tip/42981', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Abandoned Fairy Village', 'abandoned-fairy-village', 'weird-history', 41.53916, -73.08517, 'Waterbury', 'CT', 'Tiny stone houses, miniature stairways and a strange little throne sit nearly swallowed by the woods beside an old service road. Local stories have connected the handmade ruins with fairies or elves, although their actual origin is much more earthly. Reach the area only by lawful public access and do not park on Old Waterbury Road.', 'limited', null, 'https://www.atlasobscura.com/places/abandoned-fairy-village', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Abandoned Lock No. 19', 'abandoned-lock-no-19', 'weird-history', 39.25509, -81.69157, 'Washington', 'WV', 'Built in 1916, Lock and Dam No. 19 once helped move river traffic past a wicket dam on the Ohio River before the system was replaced in 1968. Ruins of the old powerhouse remain near a public boat ramp, but the structure is deteriorated and should be viewed without climbing; the former lock houses uphill are private property and should not be approached.', 'limited', null, 'https://www.atlasobscura.com/places/abandoned-lock-no-19', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('abandoned mine marker', 'abandoned-mine-marker', 'weird-history', 35.464799, -106.12779, 'La Cienega', 'NM', 'A mapped abandoned-mine marker about seven miles south of La Cienega. No reliable source identifies which mine it commemorates or documents a visitor site, so expect a marker rather than anything explorable. Abandoned workings should never be entered.', 'roadside', null, 'https://www.blm.gov/programs/aml-environmental-cleanup/aml', null, null, null, null, null, null, 'America/Denver'),
  ('Abandoned Train Cars of Bartlett', 'abandoned-train-cars-of-bartlett', 'weird-history', 44.07768, -71.28004, 'Bartlett', 'NH', 'Several aging rail cars and a locomotive have long sat near the old Mountain Division rail corridor in Bartlett, creating the appearance of a forgotten train left in the woods. Their condition and exact access can change as rail and property work evolves. Follow current signage and lawful local access, stay off any active tracks, and do not climb into or damage the equipment.', 'limited', null, 'https://www.atlasobscura.com/places/the-abandoned-train-cars-of-bartlett-nh', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Abraham Lincoln Birthplace Symbolic Cabin', 'abraham-lincoln-birthplace-symbolic-cabin', 'weird-history', 37.53167, -85.73736, 'Hodgenville', 'KY', 'Inside a large neoclassical memorial building sits a small nineteenth-century log cabin once promoted as the actual birthplace cabin of Abraham Lincoln. Historians later determined the cabin was not the original, so the National Park Service now presents it as a symbolic reconstruction associated with the birthplace site.', 'open', null, 'https://www.nps.gov/abli/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.nps.gov/abli/', null, null, null, 'America/New_York'),
  ('Abrams Creek Underwater Bridge', 'abrams-creek-underwater-bridge', 'weird-history', 35.55542, -83.99885, 'Tallassee', 'TN', 'A former road crossing near Abrams Creek was submerged by the creation of Chilhowee Lake, leaving bridge remains beneath the water. Conditions and visibility vary, and this should be treated as an observation/history stop rather than an invitation to enter the water or climb submerged structures.', 'limited', null, 'https://www.atlasobscura.com/places/abrams-creek-underwater-bridge', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Absecon Lighthouse', 'absecon-lighthouse', 'weird-history', 39.36633, -74.41415, 'Atlantic City', 'NJ', 'First lit in 1857, Absecon Lighthouse is New Jersey''s tallest lighthouse and contains a 228-step climb to the lantern room. The preserved keeper''s complex provides an unusual historic counterpoint to Atlantic City''s casinos and boardwalk attractions.', 'open', null, 'https://abseconlighthouse.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aden Mounds', 'aden-mounds', 'weird-history', 32.63735, -90.8376, 'Valley Park', 'MS', 'A Coles Creek-era mound complex east of Valley Park where three mounds once framed a plaza along Jeff Davis Bayou. The site is private property; use the Mississippi Mound Trail marker/public roadway and do not enter the archaeological site.', 'roadside', null, 'https://trails.mdah.ms.gov/aden', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Advanced Redoubt', 'advanced-redoubt', 'weird-history', 30.35751, -87.30222, 'Pensacola', 'FL', 'Rare inland redoubt built to protect Pensacola''s naval yard from land attack.', 'open', null, 'https://www.nps.gov/guis/learn/historyculture/advanced-redoubt.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Adventure Mine', 'adventure-mine', 'weird-history', 46.77272, -89.08181, 'Greenland', 'MI', 'Adventure Mine preserves an authentic nineteenth-century copper mine where visitors can descend underground through old workings cut into the rock. Different tours range from conventional walking routes to more demanding excursions deeper into the mine, making access ticketed and seasonal rather than a casual open stop.', 'limited', null, 'https://adventureminetours.com/', '2026-09-08T15:31:15.588137+00:00', null, 'https://adventureminetours.com/', null, null, null, 'America/Detroit'),
  ('African Burying Ground Memorial Park', 'african-burying-ground-memorial-park', 'weird-history', 43.07513, -70.75903, 'Portsmouth', 'NH', 'Construction work in 2003 uncovered human remains beneath Chestnut Street, revealing a forgotten eighteenth-century African burial ground. Archaeological work identified multiple individuals of African descent, and the city later created a public memorial park over the site. It is a solemn burial and remembrance space and should be treated accordingly.', 'open', null, 'https://www.portsmouthnh.gov/publicworks/portsmouth-african-burying-ground-memorial-park', '2026-09-09T04:49:39.808526+00:00', null, 'https://africanburyinggroundnh.org/', null, null, null, 'America/New_York'),
  ('African Queen Canal Cruise', 'african-queen-canal-cruise', 'weird-history', 25.08685, -80.44486, 'Key Largo', 'FL', 'Restored boat used in the 1951 film The African Queen, now operating from Key Largo.', 'limited', null, 'https://africanqueenflkeys.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Africatown Heritage House', 'africatown-heritage-house', 'weird-history', 30.73844, -88.05861, 'Mobile', 'AL', 'The museum centers the story of the Clotilda, the last known slave ship to arrive in the United States, and the community founded by many of its survivors. Artifacts recovered from the wreck and community histories connect Africatown directly to the people who endured the voyage.', 'open', null, 'https://clotilda.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Al Capone Grave', 'al-capone-grave', 'weird-history', 41.86294, -87.90642, 'Hillside', 'IL', 'The grave of Chicago crime boss Al Capone sits in Mount Carmel Cemetery among other figures connected to the city''s organized-crime history.', 'limited', null, 'https://www.catholiccemeterieschicago.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Al Green''s Full Gospel Tabernacle Church', 'al-greens-full-gospel-tabernacle-church', 'weird-history', 35.02623, -90.03782, 'Memphis', 'TN', 'Soul singer Al Green became a minister and has long preached at this active Memphis church. It is a functioning house of worship, not a performance attraction; visitors should attend only public services, dress appropriately and respect the congregation.', 'limited', null, 'https://www.atlasobscura.com/places/al-greens-full-gospel-tabernacle-church', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Alabama Constitution Hall Park', 'alabama-constitution-hall-park', 'weird-history', 34.72862, -86.58737, 'Huntsville', 'AL', 'This reconstructed village interprets Huntsville in 1819, when delegates gathered here to draft Alabama’s first state constitution. Demonstrations and restored-style buildings turn a pivotal political moment into a physical historic district rather than a simple marker.', 'limited', null, 'https://earlyworks.com/achp/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Alabama Fan Club and Museum', 'alabama-fan-club-and-museum', 'weird-history', 34.43287, -85.73188, 'Fort Payne', 'AL', 'The hometown museum devoted to the country group Alabama displays awards, stage clothing, instruments and memorabilia spanning the band’s career. It is a concentrated piece of regional music history tied directly to Fort Payne.', 'open', null, 'https://fortpayne.org/community/museums/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Alabama Music Hall of Fame', 'alabama-music-hall-of-fame', 'weird-history', 34.71276, -87.70695, 'Tuscumbia', 'AL', 'Exhibits honor Alabama musicians across country, blues, gospel, soul and rock, with costumes, instruments, vehicles and recording memorabilia. The museum provides broad context for the state’s unusually dense music legacy.', 'open', null, 'https://www.alamhof.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Alabama Veterans Museum & Archives', 'alabama-veterans-museum-archives', 'weird-history', 34.80675, -86.9702, 'Athens', 'AL', 'Housed in a former railroad freight depot, the museum preserves uniforms, documents, vehicles and personal stories from Alabama veterans. Its collection connects local lives to conflicts from the Revolutionary War through the present.', 'open', null, 'https://www.alabamaveteransmuseum.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Alan Freed''s Jukebox Grave', 'alan-freeds-jukebox-grave', 'weird-history', 41.51413, -81.59282, 'Cleveland', 'OH', 'Disc jockey Alan Freed, who helped popularize the term rock and roll, was reinterred at Lake View Cemetery in 2016 after his ashes had previously been displayed at the Rock & Roll Hall of Fame. His grave is marked by a distinctive jukebox-shaped monument that can be visited during cemetery hours.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-alan-freed', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aldis Hill Wolf Monument', 'aldis-hill-wolf-monument', 'weird-history', 44.81549, -73.06676, 'St. Albans', 'VT', 'A heavy stone monument marks the place where Lawrence Brainerd reportedly killed an exceptionally large gray wolf in 1839. The monument was restored and reinstalled near the trail in recent years, preserving a strange local episode of human-wildlife history.', 'open', null, 'https://www.atlasobscura.com/places/aldis-hill-wolf-monument', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aldrich Coal Mine Museum', 'aldrich-coal-mine-museum', 'weird-history', 33.10812, -86.8932, 'Montevallo', 'AL', 'The museum occupies former Montevallo Coal Mine Company buildings and preserves mining tools, photographs, a company-store interior and a simulated slope mine. Nearby history includes convict labor and the remains of a once-company-controlled mining community; call ahead for current access.', 'limited', null, 'https://www.cityofmontevallo.com/AldrichCoalMineMuseum.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Alex Haley Museum & Interpretive Center', 'alex-haley-museum-interpretive-center', 'weird-history', 35.67337, -89.57646, 'Henning', 'TN', 'The childhood home of Roots author Alex Haley is preserved as a museum interpreting his family history, writing and the enormous cultural impact of Roots. The site connects national conversations about ancestry and slavery to a specific West Tennessee community.', 'limited', null, 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('American Museum of Science and Energy', 'american-museum-of-science-and-energy', 'weird-history', 36.01274, -84.25276, 'Oak Ridge', 'TN', 'AMSE explores nuclear science, national-security research and the technologies developed around Oak Ridge. Its hands-on exhibits help translate the city''s secret wartime origins into something visitors can understand without entering controlled facilities.', 'open', null, 'https://amse.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('An Gorta Mor — Michigan''s Great Hunger Memorial', 'an-gorta-mor-michigans-great-hunger-memorial', 'weird-history', 42.05698, -84.16708, 'Brooklyn', 'MI', 'A stone memorial at the Irish Hills'' St. Joseph Shrine commemorates the victims of Ireland''s Great Famine and the immigrants forced from the country during the nineteenth century. Dedicated in 2004, the monument adds an unexpectedly specific piece of Irish history to a rural Michigan religious complex.', 'open', null, 'https://www.hmdb.org/m.asp?m=165618', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Anamosa State Penitentiary Museum', 'anamosa-state-penitentiary-museum', 'weird-history', 42.112511, -91.29138, 'Anamosa', 'IA', 'The Anamosa State Penitentiary Museum sits outside the walls of the still-active prison and documents its history through uniforms, photographs, inmate-made objects, weapons and a replica cell. The museum operates on a limited seasonal schedule and is a prison-history stop rather than a conventional haunted house.', 'limited', null, 'https://www.asphistory.com/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 367089373, 'America/Chicago'),
  ('Ancient Burying Ground', 'ancient-burying-ground', 'weird-history', 41.76466, -72.67426, 'Hartford', 'CT', 'Hartford''s oldest surviving cemetery holds generations of the city''s earliest residents in an increasingly compressed downtown landscape. Thousands were buried here, sometimes in layered graves, while later city development transformed the land around the burial ground.', 'open', null, 'https://www.atlasobscura.com/places/ancient-burying-ground', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ancient Dugout Canoes at Lake Phelps', 'ancient-dugout-canoes-at-lake-phelps', 'weird-history', 35.7962, -76.421, 'Creswell', 'NC', 'Lake Phelps concealed an extraordinary archaeological record beneath its water: dozens of ancient Native American dugout canoes have been discovered in and around the lake. Pettigrew State Park interprets these finds and the long human history surrounding the unusual shallow lake.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/north-carolina/lakes', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ancient Spanish Monastery', 'ancient-spanish-monastery', 'weird-history', 25.93769, -80.14551, 'North Miami Beach', 'FL', '12th-century Spanish monastery dismantled stone by stone and rebuilt in Florida.', 'limited', null, 'https://spanishmonastery.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Andre the Giant Historical Marker', 'andre-the-giant-historical-marker', 'weird-history', 35.08927, -79.76253, 'Ellerbe', 'NC', 'A historical marker recognizes professional wrestling legend André René Roussimoff, better known as André the Giant, who owned a ranch outside Ellerbe and preferred the privacy of rural North Carolina when he was away from wrestling. The marker gives the state an unusually fitting memorial to a literal giant. Current listing: https://www.roadsideamerica.com/location/nc', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Andre the Seal Statue', 'andre-the-seal-statue', 'weird-history', 44.18617, -69.07379, 'Rockport', 'ME', 'A life-size granite statue on the Rockport waterfront honors Andre, the harbor seal who became a local celebrity through his relationship with harbor master Harry Goodridge. Andre’s true story inspired books and films and remains an unusually Maine piece of animal history.', 'open', null, 'https://www.roadsideamerica.com/story/3632', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Angel in Anguish 9/11 Memorial', 'angel-in-anguish-9-11-memorial', 'weird-history', 40.05748, -74.11116, 'Brick Township', 'NJ', 'A bronze angel bends forward in grief as the central figure of Brick Township''s September 11 memorial. The emotionally direct sculpture is surrounded by names and memorial elements honoring township residents lost in the attacks.', 'open', null, 'https://www.roadsideamerica.com/tip/29739', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Angel Mounds State Historic Site', 'angel-mounds-state-historic-site', 'weird-history', 37.93886, -87.46023, 'Evansville', 'IN', 'Between roughly A.D. 1000 and 1450, Mississippian people built a major town here containing large earthen platform mounds, plazas and houses. The preserved archaeological site and museum allow visitors to encounter the landscape without treating the Indigenous city as a mysterious or vanished-civilization legend.', 'limited', null, 'https://www.indianamuseum.org/historic-sites/angel-mounds/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Anguilla Mound', 'anguilla-mound', 'weird-history', 32.97255, -90.8413, 'Anguilla', 'MS', 'A surviving rectangular platform mound about 20 feet high, built and used over centuries before European settlement. It is on private property and should be observed only from the public viewing route identified by the Mississippi Mound Trail.', 'roadside', null, 'https://trails.mdah.ms.gov/anguilla', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Annmary Brown Memorial', 'annmary-brown-memorial', 'weird-history', 41.82431, -71.40222, 'Providence', 'RI', 'Brown University''s stone Annmary Brown Memorial was built in the early twentieth century as a library, art gallery and mausoleum. Rush Hawkins and his wife Annmary Brown are entombed inside, surrounded by a collection assembled by Hawkins. Public hours can be limited or suspended, so current access should be checked before routing here.', 'limited', null, 'https://lib.brown.edu/using-library/visiting-library/locations-hours/annmary-brown-memorial', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Apollo Moonprints in Cement', 'apollo-moonprints-in-cement', 'weird-history', 33.70645, -78.87417, 'Myrtle Beach', 'SC', 'Concrete slabs preserve boot impressions made by Apollo astronauts during appearances connected with Myrtle Beach’s former convention-hall Walk of Fame. They turn something as ordinary as footprints in wet cement into a strange relic of the Moon-landing era.', 'limited', null, 'https://www.atlasobscura.com/places/apollo-moonprints-in-cement', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Apple River Fort State Historic Site', 'apple-river-fort-state-historic-site', 'weird-history', 42.31851, -90.21275, 'Elizabeth', 'IL', 'A reconstruction of the small fort attacked during the Black Hawk War, with self-guided grounds and periodic living-history programming.', 'open', null, 'https://www.appleriverfort.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Aquia Church', 'aquia-church', 'weird-history', 38.46463, -77.40303, 'Stafford', 'VA', 'The present Aquia Church was completed in 1757 after its nearly finished predecessor burned, and the building later survived use by Union soldiers as a stable, hospital and campsite during the Civil War. It remains an active Episcopal church with remarkably preserved colonial woodwork, and historical tours should be arranged with the church office rather than treated as unrestricted sightseeing.', 'limited', null, 'https://aquiachurch.org/about/history/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Archduke Stefan of Austria''s Grave', 'archduke-stefan-of-austrias-grave', 'weird-history', 45.06225, -85.67276, 'Suttons Bay', 'MI', 'St. Wenceslaus Cemetery contains the grave of Archduke Stefan of Austria, a member of the Habsburg family who eventually settled in the United States and worked for General Motors. His quiet burial in rural Leelanau County creates an unexpected link between northern Michigan and European royalty.', 'open', null, 'https://www.atlasobscura.com/places/archduke-austria-grave-st-wenceslaus-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Arcola Mounds', 'arcola-mounds', 'weird-history', 33.245, -90.8819, 'Arcola', 'MS', 'Only part of a once larger six-mound Mississippian complex survives here, including a platform mound rising more than 30 feet. The remaining earthworks are private, so this is a lawful roadside/viewing stop rather than a walk-on site.', 'roadside', null, 'https://trails.mdah.ms.gov/arcola', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Arsenal Park — U.S. Arsenal Ghost Tower', 'arsenal-park-us-arsenal-ghost-tower', 'weird-history', 35.05393, -78.89455, 'Fayetteville', 'NC', 'Union troops destroyed the Fayetteville Arsenal in 1865, leaving foundations and scattered remains on the hillside. A modern steel framework outlines the shape of one of the vanished corner towers like an architectural ghost, making the missing structure visible without reconstructing it. Site information: https://museumofthecapefear.ncdcr.gov/', 'open', null, 'https://www.roadsideamerica.com/location/nc/all', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ashcroft Ghost Town', 'ashcroft-ghost-town', 'weird-history', 39.055591, -106.799564, 'Ashcroft', 'CO', 'Ashcroft is a preserved silver-mining ghost town outside Aspen where visitors can walk among surviving cabins, commercial buildings and other remnants of the short-lived 1880s boomtown. Seasonal interpretation and tours help explain the settlement''s mining history and rapid decline.', 'limited', null, 'https://aspenhistory.org/tours-sites/ashcroft/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 2965136490, 'America/Denver'),
  ('Ashland Witch Caves', 'ashland-witch-caves', 'weird-history', 42.27074, -71.47588, 'Ashland', 'MA', 'Collapsed rock shelters in Ashland Town Forest are traditionally associated with people fleeing persecution connected with the Salem witch trials. Very little of the original cave space remains, but the location preserves the broader story of displaced families who settled in the area once known as Salem End.', 'open', null, 'https://www.atlasobscura.com/places/ashland-witch-caves', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aspin Hill Pet Cemetery', 'aspin-hill-pet-cemetery', 'weird-history', 39.0799, -77.07629, 'Aspen Hill', 'MD', 'Established in the early 20th century, Aspin Hill is one of the country''s oldest pet cemeteries and contains tens of thousands of animal burials alongside a smaller number of human graves. Elaborate markers memorialize dogs, cats, birds and other pets, and the cemetery is open for respectful daytime visits.', 'open', null, 'https://www.atlasobscura.com/places/aspin-hill-pet-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Assabet River National Wildlife Refuge — WWII Bunkers', 'assabet-river-national-wildlife-refuge-wwii-bunkers', 'weird-history', 42.40785, -71.47149, 'Sudbury', 'MA', 'Dozens of sealed concrete ammunition bunkers from World War II remain scattered through today''s wildlife refuge. The military storage landscape has been reclaimed by forest, wetlands and trails, producing an unusual mix of bird habitat and wartime infrastructure. The bunker interiors are closed.', 'open', null, 'https://www.atlasobscura.com/places/assabet-river-national-wildlife-refuge', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.fws.gov/refuge/assabet-river', null, null, null, 'America/New_York'),
  ('Assassin''s End — John Wilkes Booth Marker', 'assassins-end-john-wilkes-booth-marker', 'weird-history', 38.14009, -77.2286, 'Port Royal', 'VA', 'John Wilkes Booth was cornered at Richard Garrett''s farm and fatally shot on April 26, 1865, twelve days after assassinating Abraham Lincoln. The farm buildings are gone and the actual site lies in a posted highway median with no public access, so OddWay should route travelers only to the roadside "Assassin''s End" historical marker and pull-off.', 'roadside', null, 'https://www.atlasobscura.com/places/assassins-end', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Astronaut Memorial Space Mirror', 'astronaut-memorial-space-mirror', 'weird-history', 28.52344, -80.68208, 'Merritt Island', 'FL', 'Black granite memorial inscribed with astronauts who died in the line of duty.', 'roadside', null, 'https://www.kennedyspacecenter.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Atsion Mansion', 'atsion-mansion', 'weird-history', 39.7425, -74.72611, 'Shamong Township', 'NJ', 'This 1826 Greek Revival mansion was built during Atsion''s ironmaking era in the Pine Barrens. The surrounding settlement largely disappeared, leaving the restored mansion as one of the clearest surviving structures from the old industrial village.', 'limited', null, 'https://dep.nj.gov/parksandforests/wharton-state-forest/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Audubon State Historic Site — Oakley House', 'audubon-state-historic-site-oakley-house', 'weird-history', 30.79907, -91.30789, 'St. Francisville', 'LA', 'John James Audubon spent part of 1821 at Oakley while tutoring a plantation family''s daughter and working on bird studies. The preserved house and grounds connect natural-history art with the plantation world that supported his stay.', 'open', null, 'https://www.lastateparks.com/historic-sites/audubon-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Austin Dam Ruins', 'austin-dam-ruins', 'weird-history', 41.65272, -78.08592, 'Keating Township', 'PA', 'The broken concrete walls in Austin Dam Memorial Park are the remains of the dam that failed catastrophically in 1911, sending water and debris through the valley and killing dozens of people. Visitors can walk among the enormous tilted sections of concrete and see interpretive material in the public park.', 'open', null, 'https://www.austindam.net/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Authors'' Ridge', 'authors-ridge', 'weird-history', 42.46065, -71.34034, 'Concord', 'MA', 'A wooded corner of Sleepy Hollow Cemetery holds the graves of Ralph Waldo Emerson, Henry David Thoreau, Nathaniel Hawthorne, Louisa May Alcott and other members of Concord''s extraordinary literary circle. The concentration of famous writers makes the ridge feel like a compact cemetery of American literature.', 'open', null, 'https://www.atlasobscura.com/places/authors-ridge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aztalan State Park', 'aztalan-state-park', 'weird-history', 43.06604, -88.8611, 'Lake Mills', 'WI', 'Large platform mounds and reconstructed stockade sections mark the remains of a major Mississippian settlement occupied roughly a thousand years ago. The state''s most prominent archaeological park gives travelers a rare public look at monumental pre-contact earthworks.', 'open', null, 'https://dnr.wisconsin.gov/topic/parks/aztalan', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/topic/parks/aztalan', null, null, null, 'America/Chicago'),
  ('B-1 Flat Top House', 'b-1-flat-top-house', 'weird-history', 36.02285, -84.27191, 'Oak Ridge', 'TN', 'One of Oak Ridge''s standardized wartime houses survives as a reminder of the instant city built to support the Manhattan Project. Its utilitarian prefabricated design reflects how quickly thousands of workers had to be housed under secrecy.', 'roadside', null, 'https://www.atlasobscura.com/places/oak-ridge-b1-flat-top', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('B-52 Crash Site Memorial — Elephant Mountain', 'b-52-crash-site-memorial-elephant-mountain', 'weird-history', 45.52778, -69.43472, 'Greenville', 'ME', 'Wreckage from a U.S. Air Force B-52 that crashed on Elephant Mountain during a 1963 training mission remains scattered in the woods near a memorial. Seven crew members died and two survived; visitors should treat the site as both a historical location and a memorial.', 'limited', null, 'https://www.visitmaine.net/b52-crash-site-maine/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bacon''s Castle', 'bacons-castle', 'weird-history', 37.10905, -76.72231, 'Surry', 'VA', 'Built in 1665, this extraordinary brick house acquired its misleading name after followers of Nathaniel Bacon seized and fortified it during Bacon''s Rebellion in 1676. The historic house is open for scheduled tours during its operating season, while the grounds generally have broader daytime access.', 'limited', null, 'https://preservationvirginia.org/historic-sites/bacons-castle/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ballarat', 'ballarat', 'weird-history', 36.047917, -117.225675, 'Searles Valley', 'CA', 'Founded in 1897 to serve gold mines in the Panamint Mountains, with around 400 residents by 1898. What is left is adobe ruins and scattered mining remains off Panamint Valley Road. Privately owned, genuinely remote, and with no dependable services.', 'limited', null, 'https://www.nps.gov/deva/learn/historyculture/death-valley-ghost-towns.htm', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Bancroft''s Castle', 'bancrofts-castle', 'weird-history', 42.60848, -71.55977, 'Groton', 'MA', 'Stone ruins on Gibbet Hill are all that remain of General William Bancroft''s ambitious early twentieth-century country estate. The unfinished structure later became a private club before burning, leaving castle-like walls that can now be reached by public hiking trails.', 'open', null, 'https://www.atlasobscura.com/places/bancroft-castle', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bannerman Castle', 'bannerman-castle', 'weird-history', 41.45531, -73.98887, 'Fishkill', 'NY', 'Military-surplus dealer Francis Bannerman built this eccentric castle-like arsenal on Pollepel Island between 1900 and 1918, later leaving a romantic ruin after explosions, fire and abandonment. The island is controlled by New York State Parks and can be visited only through authorized seasonal boat or kayak tours.', 'limited', null, 'https://bannermancastle.org/faq/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Barberville Pioneer Settlement', 'barberville-pioneer-settlement', 'weird-history', 29.18771, -81.42037, 'Barberville', 'FL', 'Open-air collection of relocated historic Florida buildings and folk-life artifacts.', 'limited', null, 'https://www.pioneersettlement.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Barcelona Lighthouse', 'barcelona-lighthouse', 'weird-history', 42.3411, -79.59483, 'Westfield', 'NY', 'Completed in 1829, Barcelona Lighthouse is recognized as the world''s first lighthouse powered by natural gas. The grounds are open year-round and the restored tower can be climbed during staffed seasonal hours when weather and staffing permit.', 'open', null, 'https://staffportal.parks.ny.gov/parks/196/details.aspx', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Barksdale Global Power Museum', 'barksdale-global-power-museum', 'weird-history', 32.51068, -93.68092, 'Bossier City', 'LA', 'Aircraft and exhibits at Barksdale Air Force Base trace strategic bombing and U.S. Air Force history. Since the museum is on an active military installation, visitors must follow current base-access and identification procedures.', 'limited', null, 'https://www.barksdaleglobalpowermuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Barnaby Castle', 'barnaby-castle', 'weird-history', 41.81754, -71.4302, 'Providence', 'RI', 'This extravagant 1875 Victorian mansion became connected to one of the country''s earliest nationally famous murder-by-mail cases after widow Josephine Barnaby was poisoned with whiskey in 1891. The castle-like house has also accumulated reports of cold spots, uneasy sensations and other alleged paranormal activity. It is private property outside select tours and events, so exterior viewing should remain on the public sidewalk. Secondary source: https://sah-archipedia.org/buildings/RI-01-PR186', 'limited', null, 'https://hauntbound.com/locations/ri/barnaby-castle-providence/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Barney Family Mausoleum — Sphinx Tomb', 'barney-family-mausoleum-sphinx-tomb', 'weird-history', 42.07456, -72.58041, 'Springfield', 'MA', 'A bronze sphinx guards the entrance to the Barney family mausoleum in Forest Park. The Egyptian-style tomb was commissioned by wealthy industrialist Everett Hosmer Barney and looks dramatically out of place amid the surrounding New England landscape.', 'open', null, 'https://www.atlasobscura.com/places/barney-family-mausoleum', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bartlettyarns Mill — Graveyard Shift Filming Location', 'bartlettyarns-mill-graveyard-shift-filming-location', 'weird-history', 44.9712, -69.54672, 'Harmony', 'ME', 'This working woolen mill supplied the exterior for the sinister textile mill in the 1990 Stephen King adaptation Graveyard Shift. It remains an active property, making this primarily a respectful exterior-viewing stop from public areas.', 'private', null, 'https://www.atlasobscura.com/places/bartlettyarns-mill', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Batesville Mounds', 'batesville-mounds', 'weird-history', 34.34572, -89.92393, 'Batesville', 'MS', 'A rare surviving Woodland-period mound group incorporated into Batesville''s public mound trail area. Several original mounds were destroyed, but the surviving earthworks and interpretive setting make this one of the easier archaeological stops to experience directly.', 'open', null, 'https://trails.mdah.ms.gov/batesville', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bath School Disaster Memorial', 'bath-school-disaster-memorial', 'weird-history', 42.8164, -84.44929, 'Bath', 'MI', 'On May 18, 1927, school-board member Andrew Kehoe used explosives to destroy part of Bath Consolidated School before detonating his truck outside, in an attack that killed 45 people including Kehoe. James Couzens Memorial Park preserves the school''s cupola, a historical marker and the Girl with a Cat memorial dedicated after the disaster.', 'open', null, 'https://www2.dnr.state.mi.us/publications/pdfs/ArcGISOnline/StoryMaps/mhc_historical_markers/pdfs/MHC191991013.pdf', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Batsto Village', 'batsto-village', 'weird-history', 39.64461, -74.64692, 'Washington Township', 'NJ', 'More than 40 surviving structures preserve a Pine Barrens industrial village built around ironmaking and later glass production. The grounds are open daily, with an 1852 post office, sawmill, mansion and other buildings forming a remarkably intact historic settlement.', 'open', null, 'https://dep.nj.gov/parksandforests/state-park/batsto-village/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Battery Steele', 'battery-steele', 'weird-history', 43.6587, -70.1798, 'Peaks Island, Portland', 'ME', 'Built during World War II, Battery Steele is a long concrete coastal-defense battery now covered in graffiti and surrounded by island trails. Visitors can walk through portions of its dark, bunker-like corridors, making it one of the more atmospheric ruins near Portland.', 'open', null, 'https://www.atlasobscura.com/places/battery-steele', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Battle of Virden Monument', 'battle-of-virden-monument', 'weird-history', 39.50117, -89.76667, 'Virden', 'IL', 'A public memorial recalls the deadly 1898 confrontation between striking union miners and armed guards brought in by a coal company.', 'open', null, 'https://www.hmdb.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bay Mills Old Indian Burial Ground', 'bay-mills-old-indian-burial-ground', 'weird-history', 46.4533, -84.60461, 'Brimley', 'MI', 'This historic Ojibwe burial ground contains weathered wooden spirit houses and a large white pine connected with Bay Mills community history. The cemetery is closed to general public entry, so travelers should view it only from permitted public areas along the perimeter and never enter the grounds.', 'private', null, 'https://www.atlasobscura.com/places/bay-mills-old-indian-burial-ground', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Bayou Pierre Mounds', 'bayou-pierre-mounds', 'weird-history', 31.9822, -91.00543, 'Port Gibson', 'MS', 'A prehistoric mound complex near Bayou Pierre where one large platform mound remains clearly visible from Old Mill Road. The property is private, so stay on the public road and use the trail marker as the stop.', 'roadside', null, 'https://trails.mdah.ms.gov/bayoupierre', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('B.B. King Museum and Delta Interpretive Center', 'bb-king-museum-and-delta-interpretive-center', 'weird-history', 33.44958, -90.64566, 'Indianola', 'MS', 'A museum built around B.B. King''s life while also interpreting Delta labor, migration, segregation and the regional culture that shaped the blues. King''s grave is on the grounds, making the site both museum and memorial.', 'open', null, 'https://bbkingmuseum.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bear Creek Mound', 'bear-creek-mound', 'weird-history', 34.64264, -88.14039, 'Tishomingo', 'MS', 'A prehistoric ceremonial mound preserved near the Alabama end of the Natchez Trace Parkway. The mound and interpretive stop provide one final ancient-site anchor before the Trace leaves Mississippi.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Beauvoir', 'beauvoir', 'weird-history', 30.39238, -88.97086, 'Biloxi', 'MS', 'The postwar home of Confederate president Jefferson Davis, now a historic site with a museum, archives, grounds and a Confederate veterans cemetery. OddWay should frame the site within Civil War, Lost Cause and memorial-history context rather than treating Confederate commemoration uncritically.', 'open', null, 'https://www.visitbeauvoir.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Becket Historic Quarry and Forest', 'becket-historic-quarry-and-forest', 'weird-history', 42.25509, -73.01574, 'Becket', 'MA', 'An abandoned granite-quarry operation has been preserved as a public forest filled with old machinery sites, derrick remains, quarry pits and interpretive trails. Instead of clearing away the industrial past, the Becket Land Trust has left much of it in place as an outdoor museum.', 'open', null, 'https://housatonicheritage.org/Places/becket-historic-quarry-forest-becket-mass/', '2026-09-09T04:43:56.902716+00:00', null, 'https://becketlandtrust.org/historic-quarry/', null, null, null, 'America/New_York'),
  ('Beckley Exhibition Coal Mine', 'beckley-exhibition-coal-mine', 'weird-history', 37.78434, -81.19614, 'Beckley', 'WV', 'Visitors ride a mine car roughly 1,500 feet into a historic drift mine while veteran miners explain the equipment and working conditions of West Virginia coal mining. The surrounding complex includes relocated coal-camp buildings, but the underground attraction operates seasonally.', 'limited', null, 'https://beckley.org/coal-mine/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belcamp (Ghost Town)', 'belcamp-ghost-town', 'weird-history', 33.443616, -98.685788, 'Olney', 'TX', 'A mapped ghost-town locality in rural Archer County, roughly six miles northeast of Olney near Anarene. No dependable published history or visitor facility could be found, so treat it as a drive-by locality and stay on public roads rather than entering ranch property.', 'roadside', null, 'https://mapcarta.com/N1731158405', null, null, null, null, null, null, 'America/Chicago'),
  ('Bell Ringing Chamber at Old North Church', 'bell-ringing-chamber-at-old-north-church', 'weird-history', 42.36634, -71.05443, 'Boston', 'MA', 'High inside Old North Church is the chamber containing the oldest set of change-ringing bells in North America. Paul Revere was among the early ringers, and scheduled tours climb into the tower to explain the highly mathematical ringing tradition.', 'limited', null, 'https://www.atlasobscura.com/places/bell-ringing-chamber-at-old-north-church', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bell Works — Former Bell Labs Holmdel Complex', 'bell-works-former-bell-labs-holmdel-complex', 'weird-history', 40.36433, -74.16606, 'Holmdel Township', 'NJ', 'Eero Saarinen''s enormous mirrored Bell Labs building housed research that helped transform telecommunications and computing. The former laboratory has been reused as the publicly accessible Bell Works complex while retaining its vast futuristic atrium and distinctive architecture.', 'open', null, 'https://bell.works/new-jersey/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belle of Louisville', 'belle-of-louisville', 'weird-history', 38.25924, -85.75555, 'Louisville', 'KY', 'Built in 1914, the Belle of Louisville is a surviving Mississippi River-style sternwheel steamboat that still operates passenger cruises on the Ohio River. Its working steam machinery and extraordinary longevity make it a piece of living transportation history rather than a static museum ship.', 'limited', null, 'https://www.atlasobscura.com/places/belle-of-louisville', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.belleoflouisville.org/', null, null, null, 'America/Kentucky/Louisville'),
  ('Bellows Falls Petroglyphs', 'bellows-falls-petroglyphs', 'weird-history', 43.13528, -72.44028, 'Bellows Falls', 'VT', 'Humanlike faces were carved into rock beside the Connecticut River long before modern Bellows Falls developed around the site. Their exact age and meaning remain uncertain, and travelers should view the protected carvings only from safe, permitted public areas rather than climbing onto the riverbank rocks.', 'limited', null, 'https://www.atlasobscura.com/places/bellows-falls-petroglyphs', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bell''s Tavern Ruins', 'bells-tavern-ruins', 'weird-history', 37.0918, -86.0499, 'Park City', 'KY', 'Bell''s Tavern became a major nineteenth-century stop for travelers heading toward Mammoth Cave, but a fire gutted the inn shortly before the Civil War. Plans to rebuild in stone were abandoned when the war began, leaving massive limestone walls and arched openings standing as picturesque public ruins.', 'open', null, 'https://www.atlasobscura.com/places/bells-tavern-ruins', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Belvedere Mansion', 'belvedere-mansion', 'weird-history', 42.40964, -90.42855, 'Galena', 'IL', 'A lavish 1857 mansion filled with period furnishings and film memorabilia, including pieces associated with Gone with the Wind.', 'limited', null, 'https://www.belvederemansionandgardens.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ben & Jerry''s First Store Plaque', 'ben-jerrys-first-store-plaque', 'weird-history', 44.47694, -73.21417, 'Burlington', 'VT', 'A plaque marks the downtown location where Ben Cohen and Jerry Greenfield opened their first ice-cream shop in a renovated gas station in 1978. The original building is gone, making the marker the physical reminder of where the Vermont brand began.', 'open', null, 'https://www.roadsideamerica.com/story/11912', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bennington Battle Monument', 'bennington-battle-monument', 'weird-history', 42.88922, -73.21562, 'Bennington', 'VT', 'The 306-foot obelisk is the tallest structure in Vermont and commemorates the 1777 Battle of Bennington. One of the odd historical details is that the battle carrying Bennington''s name was actually fought several miles away across the present-day New York state line.', 'limited', null, 'https://historicsites.vermont.gov/bennington-battle-monument', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bennington Centre Cemetery', 'bennington-centre-cemetery', 'weird-history', 42.88348, -73.21272, 'Bennington', 'VT', 'One of Vermont''s oldest cemeteries contains the graves of Revolutionary War soldiers, political figures and poet Robert Frost. Signs also identify the work of early local stone carvers, turning the burial ground into an outdoor archive of changing gravestone styles.', 'open', null, 'https://www.atlasobscura.com/places/bennington-centre-cemetery', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Benson Park Gorilla Cage', 'benson-park-gorilla-cage', 'weird-history', 42.76924, -71.40278, 'Hudson', 'NH', 'Benson''s Wild Animal Farm once drew crowds with elephants, lions, gorillas and other animals before closing in 1987. The land is now a public park, but several structures from the attraction remain, including the distinctive former gorilla cage that visitors can walk into. It is an unusually intact fragment of a vanished roadside zoo.', 'open', null, 'https://www.atlasobscura.com/places/bensons-animal-park', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.hudsonnh.gov/bensonpark', null, null, null, 'America/New_York'),
  ('Berlin Wall Slabs', 'berlin-wall-slabs', 'weird-history', 43.65557, -70.25228, 'Portland', 'ME', 'Several sections of the Berlin Wall stand outdoors near Portland’s waterfront, an unexpected fragment of Cold War history far from Germany. The slabs are publicly viewable along the Commercial Street/Long Wharf area.', 'open', null, 'https://www.waymarking.com/waymarks/WM10A1N_Berlin_Wall_Slabs_Portland_ME', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Beth Olem Cemetery', 'beth-olem-cemetery', 'weird-history', 42.38235, -83.05161, 'Detroit', 'MI', 'Beth Olem is a nineteenth-century Jewish cemetery completely enclosed by an active automotive manufacturing complex after later industrial development grew around it. Public access is extremely limited to specific scheduled days, making this one of Detroit''s strangest surviving pieces of urban history.', 'limited', null, 'https://www.atlasobscura.com/places/beth-olem', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Bethlehem Steel Blast Furnaces at SteelStacks', 'bethlehem-steel-blast-furnaces-at-steelstacks', 'weird-history', 40.61487, -75.36953, 'Bethlehem', 'PA', 'Five enormous blast furnaces from the former Bethlehem Steel plant loom over the SteelStacks arts campus, preserving the scale of a company that once employed tens of thousands of workers. Visitors can view the furnaces freely from the public campus and Hoover-Mason Trestle, with guided industrial-history tours available separately.', 'open', null, 'https://www.historicbethlehem.org/visit-us/experience/rise-and-fall-of-bethlehem-steel-walking-tour/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Biddison Family Cemetery', 'biddison-family-cemetery', 'weird-history', 39.34005, -76.5552, 'Baltimore', 'MD', 'A tiny 19th-century family cemetery survives improbably in the middle of a modern Baltimore neighborhood, a remnant of the much larger property once owned by the Biddison family. Most graves date to the 1800s, and neighborhood volunteers have periodically cleared vegetation from the otherwise easily overlooked burial ground.', 'open', null, 'https://www.atlasobscura.com/places/biddison-family-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Bone Lick State Historic Site', 'big-bone-lick-state-historic-site', 'weird-history', 38.88479, -84.75059, 'Union', 'KY', 'For thousands of years, mineral-rich salt licks drew enormous Ice Age animals to this area, where many became trapped and left fossil remains behind. The park now interprets mammoths, mastodons and other prehistoric animals and maintains a modern bison herd near the visitor center.', 'open', null, 'https://parks.ky.gov/explore/big-bone-lick-state-historic-site-7810', '2026-09-08T14:15:10.228298+00:00', null, 'https://parks.ky.gov/explore/big-bone-lick-state-historic-site-7810', null, null, null, 'America/New_York'),
  ('Bilby Tower', 'bilby-tower', 'weird-history', 39.11805, -85.29394, 'Osgood', 'IN', 'U.S. Coast and Geodetic Surveyor Jasper Bilby designed a distinctive steel surveying tower in the 1920s that could be erected quickly above trees and terrain. One surviving tower stands near Osgood as a rare monument to the pre-satellite era of precision mapping.', 'roadside', null, 'https://www.atlasobscura.com/places/bilby-tower', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.in.gov/history/markers/4326.htm', null, null, null, 'America/Indiana/Indianapolis'),
  ('Billingsgate Island', 'billingsgate-island', 'weird-history', 41.8684, -70.0659, 'Eastham', 'MA', 'A once-inhabited Cape Cod island with a lighthouse, homes and fishing community was gradually erased by erosion until it slipped beneath the water. At very low tides parts of the former island can reappear, but currents, tides and offshore access make this a view-or-boat-history stop rather than a casual walk.', 'roadside', null, 'https://www.atlasobscura.com/places/billingsgate-island', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Biloxi Wade-In Memorial', 'biloxi-wade-in-memorial', 'weird-history', 30.39398, -88.90162, 'Biloxi', 'MS', 'A memorial near the Biloxi Lighthouse commemorating Black residents who challenged segregation of the Mississippi Gulf Coast beaches beginning in 1959. The campaign culminated in violent attacks on protesters and became an important Mississippi civil-rights struggle. Secondary source: https://biloxi.ms.us/', 'open', null, 'https://www.hmdb.org/m.asp?m=243034', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Biograph Theater / John Dillinger Site', 'biograph-theater-john-dillinger-site', 'weird-history', 41.92652, -87.6498, 'Chicago', 'IL', 'Outside this historic theater, federal agents shot bank robber John Dillinger in 1934 after he left a movie screening.', 'roadside', null, 'https://www.fbi.gov/history/famous-cases/john-dillinger', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Birmingham Civil Rights Institute', 'birmingham-civil-rights-institute', 'weird-history', 33.51594, -86.81499, 'Birmingham', 'AL', 'The institute uses artifacts, recreated environments, photographs and oral histories to examine segregation and Birmingham’s central role in the Civil Rights Movement. It provides context for several nearby sites tied to protests and racial violence.', 'open', null, 'https://www.bcri.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Birthplace of Dixie Plaque', 'birthplace-of-dixie-plaque', 'weird-history', 29.95385, -90.06814, 'New Orleans', 'LA', 'A plaque near the French Quarter commemorates the place traditionally associated with the first performance of the song ''Dixie'' in 1859. The claim is part of a complicated performance history, but the marker gives it a fixed physical location.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Birthplace of the Commercial Broiler Industry', 'birthplace-of-the-commercial-broiler-industry', 'weird-history', 38.54802, -75.08908, 'Ocean View', 'DE', 'A marker in Ocean View commemorates Cecile Steele''s accidental 1923 order of 500 chicks, an event credited with helping launch the modern commercial broiler-chicken industry. A mundane shipping mistake became an agricultural turning point.', 'open', null, 'https://archives.delaware.gov/delaware-historical-markers/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Birthplace of the Snowmobile — Vilas County Historical Museum', 'birthplace-of-the-snowmobile-vilas-county-historical-museum', 'weird-history', 45.98502, -89.53136, 'Sayner', 'WI', 'Sayner celebrates Carl Eliason''s 1924 motor toboggan, an important ancestor of the modern snowmobile. The local museum preserves early machines and Northwoods history, turning a tiny community into a pilgrimage point for snowmobile enthusiasts.', 'limited', null, 'https://www.vilashistorical.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.vilashistorical.com/', null, null, null, 'America/Chicago'),
  ('Bishop Hill Colony Church', 'bishop-hill-colony-church', 'weird-history', 41.20031, -90.11889, 'Bishop Hill', 'IL', 'A surviving 1848 building from the Swedish religious commune that founded Bishop Hill, preserving the town''s unusual communal-colony history.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/northwest/bishop-hill.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Black Creek Baptist Church Ruins', 'black-creek-baptist-church-ruins', 'weird-history', 34.38642, -79.90811, 'Dovesville', 'SC', 'Three enormous brick columns stand in Black Creek Cemetery as the surviving pieces of a Greek Revival church destroyed by an accidental fire on Easter Sunday in 1922. Four columns originally survived, but one later fell after vandalism connected to rumors that a time capsule had been sealed inside. The active cemetery predates the ruins and should be visited respectfully during lawful access hours.', 'limited', null, 'https://www.scpictureproject.org/darlington-county/black-creek-baptist-church-ruins.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Black Hawk State Historic Site', 'black-hawk-state-historic-site', 'weird-history', 41.46698, -90.57236, 'Rock Island', 'IL', 'Wooded trails and museum exhibits interpret Sauk and Meskwaki history at the former location of the village associated with Black Hawk.', 'open', null, 'https://dnr.illinois.gov/parks/park.blackhawk.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Black Point Estate and Gardens', 'black-point-estate-and-gardens', 'weird-history', 42.55248, -88.57763, 'Lake Geneva', 'WI', 'A wealthy Chicago brewing family built this Queen Anne summer estate above Geneva Lake in the 1880s. Many visitors arrive by boat, climb a long staircase from the shore and enter a house still packed with generations of family objects.', 'limited', null, 'https://blackpointestate.wisconsinhistory.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://blackpointestate.wisconsinhistory.org/', null, null, null, 'America/Chicago'),
  ('Black Prairie Blues Museum', 'black-prairie-blues-museum', 'weird-history', 33.6067, -88.64833, 'West Point', 'MS', 'A developing museum in a historic downtown bank building focused on Howlin'' Wolf and the blues tradition of Mississippi''s Black Prairie. Its current public schedule is limited to specific days and appointments, so verify hours before routing travelers there. Coordinate source: official museum Google Maps link', 'limited', null, 'https://www.blackprairiebluesmuseum.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Black Tom Explosion Memorial', 'black-tom-explosion-memorial', 'weird-history', 40.69221, -74.05605, 'Jersey City', 'NJ', 'A memorial in Liberty State Park recalls the massive 1916 Black Tom explosion, when German agents sabotaged munitions stored on the New Jersey waterfront before the United States entered World War I. The blast shattered windows miles away and damaged the Statue of Liberty.', 'open', null, 'https://www.nps.gov/articles/black-tom-explosion.htm', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blackbeard''s Severed Head Marker', 'blackbeards-severed-head-marker', 'weird-history', 37.01663, -76.34278, 'Hampton', 'VA', 'After Blackbeard was killed off North Carolina in 1718, his severed head was brought back to Virginia and displayed at the mouth of the Hampton River as a warning to other pirates. A modern historical marker at Blackbeard''s Point identifies the tradition and gives travelers a physical stop tied to one of the grimmest episodes in Virginia''s pirate history.', 'roadside', null, 'https://www.roadsideamerica.com/tip/70036', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bladensburg Dueling Grounds', 'bladensburg-dueling-grounds', 'weird-history', 38.93356, -76.95199, 'Colmar Manor', 'MD', 'The fields near old Bladensburg became a notorious place for settling political and personal disputes with pistols during the 19th century, earning the nearby stream the nickname “Blood Run.” More than 50 duels are associated with the area, and a marker now interprets the history from the public grounds.', 'open', null, 'https://www.atlasobscura.com/places/bladensburg-dueling-grounds', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blenheim Mineral Springs', 'blenheim-mineral-springs', 'weird-history', 34.50999, -79.64756, 'Blenheim', 'SC', 'Mineral water from this site became famous in the 1800s and eventually inspired Blenheim Ginger Ale, one of South Carolina’s oldest soft-drink traditions. The historic spring area remains routeable, although water flow and site condition can vary and visitors should not assume the spring is always running.', 'open', null, 'https://www.findaspring.com/spring/locations/north-america/usa/south-carolina/blenheim-mineral-spring/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blennerhassett Island Historical State Park', 'blennerhassett-island-historical-state-park', 'weird-history', 39.27194, -81.62472, 'Parkersburg', 'WV', 'Harman and Margaret Blennerhassett built an extravagant estate on this Ohio River island, which later became tangled in Aaron Burr''s mysterious western political schemes. A reconstructed mansion and historical grounds can be toured today, but normal visitor access depends on the seasonal sternwheel boat from Parkersburg.', 'limited', null, 'https://wvstateparks.com/parks/blennerhassett-island-historical-state-park/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blessed Michael McGivney Pilgrimage Center', 'blessed-michael-mcgivney-pilgrimage-center', 'weird-history', 41.3021, -72.92386, 'New Haven', 'CT', 'The former Knights of Columbus Museum now centers on the life of founder Michael McGivney while retaining exhibits on the Catholic fraternal organization''s history and religious material culture. It is a specialized museum in an unexpectedly monumental downtown building.', 'open', null, 'https://www.roadsideamerica.com/tip/5688', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.michaelmcgivneycenter.org/', null, null, null, 'America/New_York'),
  ('Blue Front Cafe', 'blue-front-cafe', 'weird-history', 32.64075, -90.36474, 'Bentonia', 'MS', 'Opened in 1948, the Blue Front is one of Mississippi''s best-known surviving juke joints and is closely tied to the Bentonia school of blues. It remains an active cultural site; hours and performances can vary, so check before making it a timed stop.', 'limited', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Blue Heron Mining Community', 'blue-heron-mining-community', 'weird-history', 36.67141, -84.54775, 'Stearns', 'KY', 'Blue Heron was a remote coal camp operated by the Stearns Coal and Lumber Company before being abandoned in the early 1960s. The National Park Service reconstructed building outlines with open steel structures and audio exhibits, creating an eerie walk through the footprint of a vanished mining town.', 'open', null, 'https://www.nps.gov/biso/learn/historyculture/blueheron.htm', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.nps.gov/biso/', null, null, null, 'America/New_York'),
  ('Blue Lady of Yantic Cemetery', 'blue-lady-of-yantic-cemetery', 'weird-history', 41.53937, -72.0892, 'Norwich', 'CT', 'A distinctive blue-green bronze woman watches over a grave in Yantic Cemetery. The statue has inspired local stories about who she represents and what she once held, and after being stolen in 2010 she was recovered and returned to the cemetery.', 'open', null, 'https://www.atlasobscura.com/places/maud-s-grave', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blue Ridge Tunnel', 'blue-ridge-tunnel', 'weird-history', 38.03009, -78.85297, 'Afton', 'VA', 'Engineer Claudius Crozet''s 4,273-foot railroad tunnel opened in 1858 after nearly nine years of difficult construction through the Blue Ridge Mountains. The abandoned bore reopened as a pedestrian and bicycle trail in 2020, but it is completely dark inside and the walk to and through it requires a flashlight and appropriate trail access.', 'limited', null, 'https://www.nelsoncounty-va.gov/2020/11/20/claudius-crozet-blue-ridge-tunnel-open/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blues Hall of Fame Museum', 'blues-hall-of-fame-museum', 'weird-history', 35.13478, -90.05725, 'Memphis', 'TN', 'The Blues Foundation''s museum honors musicians, recordings and artifacts connected to the blues tradition. Its location near the Mississippi River and civil-rights landmarks makes it a concentrated stop for the music that shaped much of American popular culture.', 'open', null, 'https://blues.org/hall-of-fame-museum/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bollman Truss Bridge', 'bollman-truss-bridge', 'weird-history', 39.13486, -76.82538, 'Savage', 'MD', 'This bright iron bridge is the last surviving example of Wendel Bollman''s once-influential railroad truss design. Built in the 19th century and later moved to Savage, it now carries a pedestrian trail across the Little Patuxent River and can be walked through freely.', 'open', null, 'https://www.loc.gov/item/md0583/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bonnet House Museum & Gardens', 'bonnet-house-museum-gardens', 'weird-history', 26.13751, -80.10447, 'Fort Lauderdale', 'FL', 'Eccentric artist estate filled with murals, shells, monkeys in its history, and tropical gardens.', 'limited', null, 'https://www.bonnethouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bonnie & Clyde Ambush Museum', 'bonnie-clyde-ambush-museum', 'weird-history', 32.54508, -93.05313, 'Gibsland', 'LA', 'This small museum near the former cafe where Bonnie Parker and Clyde Barrow stopped before their deaths is packed with photographs, replicas and ambush-related memorabilia. It is intentionally focused on one of America''s most mythologized crime stories.', 'open', null, 'https://www.explorelouisiana.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bonnie & Clyde Ambush Site', 'bonnie-clyde-ambush-site', 'weird-history', 32.53146, -93.06446, 'Gibsland', 'LA', 'A roadside marker identifies the area where law officers ambushed Bonnie Parker and Clyde Barrow on May 23, 1934. Pull completely off the roadway only where lawful and safe, and never stand in traffic to recreate photographs.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Boon Island Light', 'boon-island-light', 'weird-history', 43.12116, -70.47597, 'York', 'ME', 'New England’s tallest lighthouse stands on an isolated rocky island several miles off York. Boon Island also carries grim maritime history, including an infamous 18th-century shipwreck whose stranded survivors were later associated with accounts of cannibalism.', 'roadside', null, 'https://www.atlasobscura.com/places/boon-island-light', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bosque Bello Cemetery', 'bosque-bello-cemetery', 'weird-history', 30.67355, -81.45027, 'Fernandina Beach', 'FL', 'Moss-draped historic cemetery with burials stretching back into Florida''s Spanish colonial era.', 'open', null, 'https://www.fbfl.us/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bosse Field — A League of Their Own Ballpark', 'bosse-field-a-league-of-their-own-ballpark', 'weird-history', 37.99284, -87.56279, 'Evansville', 'IN', 'Opened in 1915, Bosse Field is one of the oldest professional baseball parks still in regular use in the United States. It became even more recognizable after appearing as Racine''s ballpark in the 1992 film A League of Their Own, and visitors can see it during games and scheduled events.', 'limited', null, 'https://www.atlasobscura.com/places/bosse-field', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.evansvilleotters.com/', null, null, null, 'America/Chicago'),
  ('Bostic Lincoln Center', 'bostic-lincoln-center', 'weird-history', 35.36208, -81.83539, 'Bostic', 'NC', 'This small museum examines a persistent local claim that Abraham Lincoln was actually born in western North Carolina rather than Kentucky. Mainstream historians reject the theory, but the center preserves the documents, oral traditions, and arguments behind one of the state’s stranger historical disputes.', 'limited', null, 'https://bosticlincolncenter.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boston''s Old Burying Grounds', 'bostons-old-burying-grounds', 'weird-history', 42.3573, -71.0613, 'Boston', 'MA', 'Boston''s oldest downtown graveyards are filled with winged skulls, hourglasses, skeletons and other stark Puritan mortality symbols. A walk through the historic burying grounds becomes an outdoor gallery of macabre colonial stone carving.', 'open', null, 'https://www.atlasobscura.com/places/bostons-old-burying-grounds', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bottle Creek Indian Mounds', 'bottle-creek-indian-mounds', 'weird-history', 31.0088, -87.94057, 'Stockton', 'AL', 'On a remote island in the Mobile-Tensaw Delta, this major Mississippian ceremonial center contains numerous platform mounds built between roughly 1250 and 1550. Access is by water and is highly limited; travelers should use authorized tours or current Alabama Historical Commission guidance rather than attempting an unsupervised landing.', 'limited', null, 'https://ahc.alabama.gov/archaeology.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Boyd Mounds', 'boyd-mounds', 'weird-history', 32.45313, -90.068, 'Ridgeland', 'MS', 'A Woodland-period mound group beside the Natchez Trace Parkway, preserving ceremonial earthworks built long before the historic Trace. The site has an NPS pull-off/interpretive stop and is meant to be visited from public park land.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Brandywine Springs Amusement Park Ruins', 'brandywine-springs-amusement-park-ruins', 'weird-history', 39.74868, -75.64453, 'Wilmington', 'DE', 'Brandywine Springs was once a major amusement park filled with rides, pavilions and attractions before closing in the 1920s. Archaeological work has uncovered foundations and other remains throughout today’s county park, where interpretive markers reveal traces of the vanished amusement grounds beneath the woods.', 'open', null, 'https://www.delawarepublic.org/culture-lifestyle-sports/2016-10-28/history-matters-unearthing-brandywine-springs-historic-amusement-park', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.ecodelaware.com/place.php?id=334', null, null, null, 'America/New_York'),
  ('Branner Cemetery Field Stones', 'branner-cemetery-field-stones', 'weird-history', 36.13081, -83.48377, 'Jefferson City', 'TN', 'Rows of rough fieldstones mark burials whose identities have largely been lost, creating a stark contrast with conventional carved headstones. The cemetery should be visited respectfully during lawful access hours and without moving or touching markers.', 'limited', null, 'https://www.atlasobscura.com/places/branner-cemetery-field-stones', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Brices Cross Roads National Battlefield Site', 'brices-cross-roads-national-battlefield-site', 'weird-history', 34.50612, -88.72889, 'Baldwyn', 'MS', 'A small National Park Service battlefield site marking the 1864 Battle of Brices Cross Roads. The physical battlefield extends well beyond the monument, but the NPS site gives travelers a reliable, routable anchor for the conflict and its landscape. Coordinate source: https://www.recreation.gov/gateways/2600', 'open', null, 'https://www.nps.gov/brcr/index.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Brierfield Ironworks Historical State Park', 'brierfield-ironworks-historical-state-park', 'weird-history', 33.03944, -86.94889, 'Brierfield', 'AL', 'This wooded park preserves the remains of a Civil War-era ironworks, including furnace ruins and industrial archaeology. Trails and interpretation allow visitors to explore a landscape where large-scale iron production once dominated the valley.', 'open', null, 'https://brierfieldironworks.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('British Cemetery', 'british-cemetery', 'weird-history', 35.116, -75.97295, 'Ocracoke', 'NC', 'Four British sailors killed when the HMT Bedfordshire was torpedoed by a German U-boat in 1942 are buried in this tiny cemetery on Ocracoke. The plot is maintained in honor of the men and is treated ceremonially as British soil.', 'open', null, 'https://www.nps.gov/caha/learn/historyculture/british-cemetery.htm', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brunswick Stew Origin Marker', 'brunswick-stew-origin-marker', 'weird-history', 36.98743, -77.96328, 'Blackstone', 'VA', 'Virginia tradition says camp cook Jimmy Matthews created an early Brunswick stew during an 1828 hunting trip in Brunswick County, originally using squirrel, butter, onions, bread and seasoning. A Virginia historical marker erected in 1997 preserves the claim, though competing origin stories exist elsewhere, making this a suitably odd food-history roadside stop.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=107700', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brunswick Town / Fort Anderson', 'brunswick-town-fort-anderson', 'weird-history', 34.04045, -77.94617, 'Winnabow', 'NC', 'The ruins of a colonial port town sit beneath and around a later Confederate fort on the Cape Fear River. Excavated foundations, old streets, earthworks, and the surviving shell of St. Philip’s Church give the site the feel of multiple abandoned eras stacked on top of one another. Official site: https://historicsites.nc.gov/all-sites/brunswick-town-fort-anderson', 'limited', null, 'https://www.atlasobscura.com/places/brunswick-townfort-anderson', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brushy Mountain State Penitentiary', 'brushy-mountain-state-penitentiary', 'weird-history', 36.10452, -84.44865, 'Petros', 'TN', 'The former maximum-security prison operated for more than a century and now offers authorized history tours, museum exhibits and selected paranormal programs. Cell blocks, yards and prison infrastructure are preserved, providing legal access to a place that would otherwise be strictly off limits.', 'limited', null, 'https://tourbrushy.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bryant''s Grocery & Meat Market Ruins', 'bryants-grocery-meat-market-ruins', 'weird-history', 33.65249, -90.20877, 'Money', 'MS', 'The deteriorating remains of the store where 14-year-old Emmett Till encountered Carolyn Bryant in August 1955, an event followed by his kidnapping and murder. The ruins are historically important but are not an invitation to enter unstable or private property; view only from lawful public access.', 'roadside', null, 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Buffalo Central Terminal', 'buffalo-central-terminal', 'weird-history', 42.88965, -78.83024, 'Buffalo', 'NY', 'This enormous Art Deco railway terminal opened in 1929 and was abandoned by passenger trains in 1979, leaving its tower and concourse as one of Buffalo''s most imposing industrial-era landmarks. Interior historic tours are currently suspended during restoration work, but an official self-guided outdoor audio tour follows designated exterior paths.', 'limited', null, 'https://buffalocentralterminal.org/tours/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Buffalo Ridge Ghost Town', 'buffalo-ridge-ghost-town', 'weird-history', 43.607993, -96.885893, 'Hartford', 'SD', 'Buffalo Ridge Ghost Town is a quirky roadside Old West display near the Buffalo Ridge travel stop, with recreated frontier buildings and weathered western scenes. It is more roadside attraction than authentic abandoned settlement, making it a fun photo stop for travelers interested in kitschy ghost-town imagery.', 'open', null, 'https://maps.apple.com/?q=Buffalo%20Ridge%20Ghost%20Town', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 1063293375, 'America/Chicago'),
  ('Buford Pusser Home & Museum', 'buford-pusser-home-museum', 'weird-history', 35.23175, -88.3836, 'Adamsville', 'TN', 'The former home of sheriff Buford Pusser preserves artifacts connected to the violent law-enforcement career that inspired Walking Tall. The museum separates the real West Tennessee figure from the larger-than-life movie mythology built around him.', 'open', null, 'https://www.bufordpussermuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bulow Plantation Ruins Historic State Park', 'bulow-plantation-ruins-historic-state-park', 'weird-history', 29.43386, -81.1394, 'Flagler Beach', 'FL', 'Moss-covered coquina sugar-mill ruins burned during the Second Seminole War.', 'limited', null, 'https://www.floridastateparks.org/parks-and-trails/bulow-plantation-ruins-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bunker Hill Monument', 'bunker-hill-monument', 'weird-history', 42.37635, -71.06077, 'Boston', 'MA', 'A 221-foot granite obelisk marks the Revolutionary War Battle of Bunker Hill. The monument''s enormous interior staircase can be climbed when open, turning a familiar historical site into a surprisingly strenuous vertical stop.', 'limited', null, 'https://www.nps.gov/bost/learn/historyculture/bhm.htm', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Buried in Her Cadillac', 'buried-in-her-cadillac', 'weird-history', 39.02583, -84.88778, 'Aurora', 'IN', 'Aurora Schuck was buried at River View Cemetery in 1989 inside her red 1976 Cadillac Eldorado, reportedly requiring a burial area spanning multiple normal grave plots. Nothing dramatic rises above the burial today, but the cemetery itself is public and the bizarre interment story gives the site an unusually literal connection between car culture and burial custom.', 'open', null, 'https://www.roadsideamerica.com/tip/76516', '2026-09-08T13:20:58.818667+00:00', null, 'https://aurorariverviewcemetery.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Burned at the Stake Monument', 'burned-at-the-stake-monument', 'weird-history', 42.2955, -71.26557, 'Wellesley', 'MA', 'A stark stone monument on the Babson College campus memorializes Protestant martyr John Rogers, who was executed by burning in England in 1555. College founder Roger Babson believed Rogers was an ancestor and installed the memorial as one of several unusual monuments scattered around campus.', 'open', null, 'https://www.atlasobscura.com/places/burned-at-the-stake-monument-babson', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Burritt on the Mountain', 'burritt-on-the-mountain', 'weird-history', 34.71583, -86.53944, 'Huntsville', 'AL', 'Dr. William Burritt’s unusual 1930s mountaintop mansion combines eclectic architecture with a recreated nineteenth-century farm village. The elevated site, old cabins and distinctive mansion give it more OddWay character than a conventional house museum.', 'open', null, 'https://burrittonthemountain.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Butler''s Run', 'butlers-run', 'weird-history', 36.16314, -86.77584, 'Nashville', 'TN', 'This downtown passage preserves the name and history of a narrow historic route once used through the urban block. It is an easy-to-miss fragment of older Nashville embedded within the modern entertainment district.', 'open', null, 'https://nashvillesites.org/records/butlers-run', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bynum Mounds', 'bynum-mounds', 'weird-history', 33.89847, -88.94808, 'Houston', 'MS', 'Six Woodland-period burial mounds once stood here; surviving mounds and interpretive exhibits preserve evidence of ceremonial life roughly two millennia ago. The site is directly accessible from the Natchez Trace Parkway.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cades Cove Primitive Baptist Church', 'cades-cove-primitive-baptist-church', 'weird-history', 35.60203, -83.81351, 'Townsend', 'TN', 'A nineteenth-century church and adjoining cemetery survive in Cades Cove, preserving traces of the community that existed before creation of the national park. The weathered graves and isolated churchyard give travelers a concrete connection to a landscape whose residents were largely displaced.', 'open', null, 'https://www.nps.gov/grsm/planyourvisit/cadescove.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cadillac''s KISS Monument', 'cadillacs-kiss-monument', 'weird-history', 44.24968, -85.41393, 'Cadillac', 'MI', 'In October 1975, KISS visited Cadillac after the local high-school football team credited the band''s music with helping inspire a championship season. A granite-and-metal monument near the football field now commemorates the famously elaborate homecoming visit; travelers should visit outside school activities and respect campus rules.', 'limited', null, 'https://www.atlasobscura.com/places/cadillacs-kiss-monument', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Cahokia Courthouse State Historic Site', 'cahokia-courthouse-state-historic-site', 'weird-history', 38.57062, -90.19219, 'Cahokia Heights', 'IL', 'Illinois'' oldest surviving courthouse began as a French colonial house around 1740 and was later moved twice before returning to its original site.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/site.cahokia-courthouse.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cahokia Mounds State Historic Site', 'cahokia-mounds-state-historic-site', 'weird-history', 38.65485, -90.05928, 'Collinsville', 'IL', 'The remains of the largest pre-Columbian city north of Mexico include massive Monks Mound and dozens of surviving earthen structures.', 'open', null, 'https://cahokiamounds.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Calamity Corners', 'calamity-corners', 'weird-history', 41.31803, -74.29696, 'Sugar Loaf', 'NY', 'The intersection of Hambletonian Road and Pine Hill Road became known locally as Calamity Corners because of a succession of deaths, accidents and violent events associated with the area. Its reputation begins with the 1818 murder of Richard Jennings, a case often cited as an early American murder-for-hire, and a Legends & Lore marker was added in 2026.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/calamity-corners/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Calico Ghost Town', 'calico-ghost-town', 'weird-history', 34.948373, -116.864611, 'Yermo', 'CA', 'Calico grew around one of California''s richest silver districts from 1881, reaching roughly 1,200 residents before falling silver prices emptied it. Walter Knott restored the surviving town and gave it to San Bernardino County in 1966. Ticketed: historic buildings, shops, the Maggie Mine and a railroad.', 'limited', null, 'https://parks.sbcounty.gov/park/calico-ghost-town-regional-park/', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Camp Atterbury POW Chapel', 'camp-atterbury-pow-chapel', 'weird-history', 39.37572, -86.06832, 'Edinburgh', 'IN', 'Italian prisoners of war held at Camp Atterbury built this tiny Catholic chapel in 1943 using limited and salvaged materials. Restored after later vandalism and fire damage, the Chapel in the Meadow survives as a rare physical remnant of the camp''s World War II prisoner compound.', 'limited', null, 'https://www.atlasobscura.com/places/camp-atterbury-prisoner-of-war-chapel', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.in.gov/indiana-national-guard/about/history-and-museums/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Camp Gordon Johnston WWII Museum', 'camp-gordon-johnston-wwii-museum', 'weird-history', 29.82978, -84.69388, 'Carrabelle', 'FL', 'Museum preserving the enormous amphibious-training camp that prepared roughly a quarter-million troops during World War II.', 'limited', null, 'https://www.campgordonjohnston.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Camp Grayling Military Cemetery', 'camp-grayling-military-cemetery', 'weird-history', 44.64557, -84.75347, 'Grayling', 'MI', 'At the top of Mount Franklin in Hanson Hills is an exceptionally small military cemetery containing only two marked servicemen''s graves. The fenced plot is maintained in connection with Camp Grayling and can be reached on foot through the public recreation area.', 'open', null, 'https://www.atlasobscura.com/places/camp-grayling-military-cemetery', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Camp Merritt Memorial Monument', 'camp-merritt-memorial-monument', 'weird-history', 40.94121, -73.97653, 'Cresskill', 'NJ', 'A 66-foot granite obelisk stands in a traffic circle near the center of the former Camp Merritt, the enormous World War I embarkation camp through which more than a million people passed. The monument especially remembers hundreds who died during the 1918 influenza epidemic.', 'open', null, 'https://www.cresskillboro.com/resident/history', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Camp Milton Historic Preserve', 'camp-milton-historic-preserve', 'weird-history', 30.31644, -81.81965, 'Jacksonville', 'FL', 'Preserved Civil War earthworks from the largest Confederate encampment in Florida.', 'limited', null, 'https://www.jacksonville.gov/departments/parks-and-recreation/recreation-and-community-programming/parks/camp-milton-historic-preserve', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Camp No-Be-Bo-Sco — Camp Crystal Lake', 'camp-no-be-bo-sco-camp-crystal-lake', 'weird-history', 41.05596, -74.94877, 'Hardwick Township', 'NJ', 'This active Scout camp served as the primary filming location for the original 1980 Friday the 13th, standing in for Camp Crystal Lake. It is private property and closed to casual visitors, but officially sanctioned Crystal Lake Tours provide limited public access on specific dates.', 'limited', null, 'https://crystallaketours.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cannonball House', 'cannonball-house', 'weird-history', 38.77593, -75.13939, 'Lewes', 'DE', 'This historic house still carries physical evidence of the British bombardment of Lewes in April 1813. A cannonball associated with the attack is preserved inside, turning a quiet house museum into one of Delaware''s clearest pieces of visible War of 1812 damage.', 'limited', null, 'https://www.atlasobscura.com/places/the-cannonball-house', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.historiclewes.org/', null, null, null, 'America/New_York'),
  ('Cannonball in the Building', 'cannonball-in-the-building', 'weird-history', 37.69316, -85.85922, 'Elizabethtown', 'KY', 'A Confederate artillery shell struck a downtown building during the Civil War fighting at Elizabethtown in 1862. When the original structure burned in 1887, the cannonball was recovered and deliberately placed into the replacement building near its approximate original impact point, where it remains visible from the square.', 'open', null, 'https://www.roadsideamerica.com/tip/3905', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cannonball in the Crosswicks Meeting House', 'cannonball-in-the-crosswicks-meeting-house', 'weird-history', 40.15185, -74.64712, 'Crosswicks', 'NJ', 'A Revolutionary War cannonball remains mortared into the second-story brick wall of the 1773 Crosswicks Friends Meeting House. Both British and American forces were exchanging fire in the area in June 1778, so exactly which side fired the embedded shot is uncertain.', 'roadside', null, 'https://www.roadsideamerica.com/story/33804', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cape Florida Lighthouse', 'cape-florida-lighthouse', 'weird-history', 25.66632, -80.15829, 'Key Biscayne', 'FL', 'Historic lighthouse attacked during the Second Seminole War and rebuilt multiple times.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/bill-baggs-cape-florida-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cape May Lighthouse', 'cape-may-lighthouse', 'weird-history', 38.93299, -74.96037, 'Lower Township', 'NJ', 'The 1859 Cape May Lighthouse rises 157 feet above the southern New Jersey coast and can be climbed by visitors during operating hours. Its 199 steps lead to a panoramic view over Cape May Point State Park and the surrounding shoreline.', 'limited', null, 'https://capemaymac.org/experience/cape-may-lighthouse/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain Hanson Gregory Doughnut-Hole Monument', 'captain-hanson-gregory-doughnut-hole-monument', 'weird-history', 44.13407, -69.10012, 'Rockport', 'ME', 'Rockport honors sea captain Hanson Gregory, who is locally credited with inventing the hole in the center of the doughnut in 1847. A small monument marks the story, turning a piece of disputed food history into a routeable roadside stop.', 'roadside', null, 'https://www.rockportdonutfestival.com/history-of-the-donut', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain Jones''s Leg Grave', 'captain-joness-leg-grave', 'weird-history', 43.17594, -72.10087, 'Washington', 'NH', 'After Captain Samuel Jones lost a leg to amputation in 1804, the severed limb reportedly received its own funeral and burial while Jones himself lived for years afterward. A marker preserves the bizarre story in Washington''s cemetery landscape. It is one of the state''s clearest examples of a literal grave for only part of a person.', 'limited', null, 'https://www.atlasobscura.com/places/captain-jones-leg-grave', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain William Driver Grave', 'captain-william-driver-grave', 'weird-history', 36.14753, -86.76948, 'Nashville', 'TN', 'Sea captain William Driver, credited with popularizing the nickname ''Old Glory'' for the U.S. flag, is buried in Nashville City Cemetery. The grave provides a physical endpoint to an odd linguistic story that became national symbolism.', 'limited', null, 'https://www.atlasobscura.com/places/captain-william-driver-grave', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cardiff Giant', 'cardiff-giant', 'weird-history', 42.70598, -74.92973, 'Cooperstown', 'NY', 'The Cardiff Giant was a ten-foot stone figure secretly manufactured and buried before being "discovered" in 1869 and promoted as a petrified prehistoric man. One of America''s most famous nineteenth-century hoaxes survives today inside The Farmers'' Museum in Cooperstown.', 'open', null, 'https://www.atlasobscura.com/places/cardiff-giant', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carey Mansion', 'carey-mansion', 'weird-history', 41.468, -71.30385, 'Newport', 'RI', 'This sprawling French Renaissance-style mansion became Collinwood, the exterior of the haunted family estate in the cult television series "Dark Shadows." The building is part of a private property and is not a casual walk-in attraction. View only from lawful public areas and do not enter the grounds without permission.', 'private', null, 'https://www.atlasobscura.com/places/carey-mansion', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carlisle Old Jail Dungeon', 'carlisle-old-jail-dungeon', 'weird-history', 38.31255, -84.0287, 'Carlisle', 'KY', 'The restored old Nicholas County jail retains a basement dungeon with stone foundations, earthen flooring and graffiti left by prisoners. Local tourism groups have also used the exceptionally grim cells as a seasonal haunted attraction, and visits outside events should be arranged rather than assumed.', 'limited', null, 'https://www.roadsideamerica.com/tip/7607', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Caroline Cutter Headstone', 'caroline-cutter-headstone', 'weird-history', 42.83509, -71.65378, 'Milford', 'NH', 'Caroline Cutter''s gravestone carries an exceptionally long inscription placed there by her husband, who used the monument to accuse Baptist ministers and churches of contributing to her death. The result reads less like a conventional epitaph and more like a permanent public grievance carved into stone. It is located in Milford Cemetery.', 'limited', null, 'https://www.atlasobscura.com/places/caroline-cutter-headstone', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carranza Memorial', 'carranza-memorial', 'weird-history', 39.77734, -74.6321, 'Tabernacle Township', 'NJ', 'Deep in Wharton State Forest, a stone monument marks the 1928 crash site of Mexican aviation hero Emilio Carranza. The roughly 12-foot memorial incorporates an Aztec-inspired design and a falling eagle, turning a remote Pine Barrens clearing into an international aviation memorial.', 'open', null, 'https://dep.nj.gov/parksandforests/wharton-state-forest/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carrie Blast Furnaces', 'carrie-blast-furnaces', 'weird-history', 40.40757, -79.8867, 'Rankin', 'PA', 'Carrie Furnaces 6 and 7 are surviving pieces of the enormous Homestead Works steel complex that once dominated the Monongahela Valley. Rivers of Steel preserves the furnaces and offers scheduled industrial-history tours, but visitors cannot freely enter the site outside authorized programs.', 'limited', null, 'https://riversofsteel.com/attractions/carrie-furnaces/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carson Mounds', 'carson-mounds', 'weird-history', 34.2937, -90.6711, 'Stovall', 'MS', 'One of Mississippi''s largest archaeological complexes, once containing seven large mounds, dozens of smaller mounds and an earthen enclosure extending nearly a mile. The surviving mounds are on private property and are a view-only stop.', 'roadside', null, 'https://trails.mdah.ms.gov/carson', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carter Jackson Monument', 'carter-jackson-monument', 'weird-history', 41.44852, -71.47351, 'Wakefield', 'RI', 'Hidden in brush near Tower Hill Road, this tall granite monument is covered with an unusually long inscription recounting an eighteenth-century murder involving William Jackson and sea captain Thomas Carter. The monument was erected more than a century after the event by eccentric spiritualist Joseph Peace Hazard. It stands close to a busy roadway, so approach only from a safe lawful area.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=228064', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carter Mounds', 'carter-mounds', 'weird-history', 32.9244, -90.88145, 'Rolling Fork', 'MS', 'Two earthen mounds separated by a plaza survive north of Rolling Fork, representing a community that flourished roughly a thousand years ago. The site is private; use the public roadway/marker and do not cross onto the property.', 'roadside', null, 'https://trails.mdah.ms.gov/carter', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cary Mounds', 'cary-mounds', 'weird-history', 32.8035, -90.93143, 'Cary', 'MS', 'A Delta mound site associated with Native American settlement in the lower Yazoo Basin. The archaeological remains are privately held, making the Mississippi Mound Trail marker and lawful public-road view the appropriate way to visit.', 'roadside', null, 'https://trails.mdah.ms.gov/cary', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Casper Bluff Land & Water Reserve', 'casper-bluff-land-water-reserve', 'weird-history', 42.362, -90.43, 'Galena', 'IL', 'A Mississippi River bluff preserve containing Native American burial mounds, including a rare thunderbird-shaped effigy mound.', 'open', null, 'https://jdcf.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cass Scenic Railroad State Park', 'cass-scenic-railroad-state-park', 'weird-history', 38.39682, -79.91429, 'Cass', 'WV', 'Cass preserves a former lumber-company town and the steam railroad that once hauled timber out of the surrounding mountains. Visitors can explore the historic town area, while the famous Shay-locomotive train rides operate on scheduled, ticketed departures rather than as an always-available attraction.', 'limited', null, 'https://wvstateparks.com/parks/cass-scenic-railroad-state-park/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Castillo de San Marcos National Monument', 'castillo-de-san-marcos-national-monument', 'weird-history', 29.89785, -81.31151, 'St. Augustine', 'FL', 'Massive coquina fortress with centuries of warfare, imprisonment, and ghost lore.', 'open', null, 'https://www.nps.gov/casa/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Castle Dome Mine Museum', 'castle-dome-mine-museum', 'weird-history', 33.045874, -114.178023, 'Yuma', 'AZ', 'Castle Dome Mine Museum recreates and preserves the once-bustling Castle Dome mining district with dozens of historic buildings, mining artifacts and exhibits collected from the surrounding desert. It is primarily a mining and ghost-town history stop, with seasonal hours and additional mine/mineral experiences available.', 'limited', null, 'https://www.castledomemuseum.org/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 1137995652, 'America/Phoenix'),
  ('Castle Tower Civil War Monument', 'castle-tower-civil-war-monument', 'weird-history', 41.92472, -73.07278, 'Winsted', 'CT', 'Winsted''s 1890 Soldiers'' Monument looks less like a conventional obelisk and more like a small Gothic castle tower, complete with a soldier standing on its parapet. The hilltop structure overlooks town and opens for interior tours only on selected commemorative days.', 'limited', null, 'https://www.roadsideamerica.com/tip/50878', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Castle Windy Shell Midden', 'castle-windy-shell-midden', 'weird-history', 28.93081, -80.83279, 'New Smyrna Beach', 'FL', 'Remote archaeological shell midden reached by trail in Canaveral National Seashore.', 'open', null, 'https://www.nps.gov/cana/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cathedral Basilica of the Assumption Reliquaries', 'cathedral-basilica-of-the-assumption-reliquaries', 'weird-history', 39.0787, -84.50907, 'Covington', 'KY', 'Covington''s immense Gothic Revival cathedral contains elaborate stained glass and a reliquary chapel holding relics associated with Catholic saints. The combination of bones, ornate containers and cathedral architecture gives the active place of worship a distinctly unusual museum-like element; visitors should observe service schedules and church etiquette.', 'limited', null, 'https://www.atlasobscura.com/places/cathedral-basilica-of-the-assumption', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cathedral Tower', 'cathedral-tower', 'weird-history', 41.14894, -81.50628, 'Cuyahoga Falls', 'OH', 'Televangelist Rex Humbard began building a 750-foot tower in 1971 that was supposed to contain a revolving restaurant and support television broadcasting from his Cathedral of Tomorrow complex. Construction abruptly stopped when the concrete shaft reached 494 feet, and the unfinished tower still dominates the skyline as a communications structure; view it from public roads and do not enter the fenced property.', 'roadside', null, 'https://www.summitmemory.org/digital/collection/ABJarchives/id/2497/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Catoctin Furnace', 'catoctin-furnace', 'weird-history', 39.58116, -77.43445, 'Thurmont', 'MD', 'Iron production began at Catoctin Furnace in 1776 and relied in part on enslaved labor before the industrial village expanded through the 19th century. The surviving furnace stack, historic village, trails and Museum of the Ironworker now interpret both the industry''s technology and the lives of the people who worked there.', 'open', null, 'https://dnr.maryland.gov/publiclands/Pages/western/CunninghamFalls/Catoctin-Furnace.aspx', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cedar Hill Cemetery Faux-Bois Sculptures', 'cedar-hill-cemetery-faux-bois-sculptures', 'weird-history', 38.86023, -76.94105, 'Suitland-Silver Hill', 'MD', 'Cedar Hill Cemetery contains a surprising group of 1930s faux-bois concrete sculptures by Dionicio Rodriguez, made to resemble gnarled trees, logs and rustic wooden structures. The cemetery also contains a mass grave connected to the deadly 1906 Terra Cotta railroad wreck, giving the grounds an unusually layered history.', 'open', null, 'https://spacesarchives.org/explore/search-the-online-collection/cedar-hill-cemetery/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cedar Key Museum State Park', 'cedar-key-museum-state-park', 'weird-history', 29.14507, -83.04589, 'Cedar Key', 'FL', 'Old Florida museum preserving island history and naturalist John Muir''s Cedar Key connection.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/cedar-key-museum-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cemetery Island — Ghost Island', 'cemetery-island-ghost-island', 'weird-history', 34.59182, -82.85603, 'Townville', 'SC', 'When Lake Hartwell was created, a hill containing the Harris family cemetery remained above the rising water and became an island. Dozens of graves now sit isolated by the lake, and local stories have added ghost legends to the already eerie setting. The island is most practically reached by boat or kayak.', 'limited', null, 'https://www.atlasobscura.com/places/cemetery-island', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Center of the World', 'center-of-the-world', 'weird-history', 41.228, -80.91, 'Leavittsburg', 'OH', 'The tiny crossroads community called Center of the World was named in the 1840s by businessman Randall D. Wilmot, who hoped the stagecoach stop would become an important settlement. The dream never materialized, but an official green highway sign still marks the oddly named place near the junction of OH-82 and OH-5/OH-534; view it safely from a legal roadside position.', 'roadside', null, 'https://www.roadsideamerica.com/story/66691', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Central Railroad of New Jersey Terminal', 'central-railroad-of-new-jersey-terminal', 'weird-history', 40.70721, -74.03519, 'Jersey City', 'NJ', 'Millions of immigrants who had entered the United States through nearby Ellis Island continued their journeys through this enormous waterfront railroad terminal. The restored train sheds and terminal building survive inside Liberty State Park as a striking transportation ruin-turned-historic site.', 'open', null, 'https://www.nps.gov/places/000/central-railroad-of-new-jersey-terminal.htm', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Centralia', 'centralia', 'weird-history', 40.804, -76.3405, 'Centralia', 'PA', 'A coal seam under the borough caught fire in 1962 and is still burning. Almost everyone was bought out and moved; the street grid remains, the buildings mostly do not, and steam still works its way up through the ground on cold mornings.', 'roadside', null, null, null, null, null, null, null, null, 'America/New_York'),
  ('Century of Progress Homes', 'century-of-progress-homes', 'weird-history', 41.68476, -86.99881, 'Beverly Shores', 'IN', 'Five experimental houses from Chicago''s 1933–34 Century of Progress World''s Fair were moved across Lake Michigan to Indiana after the exposition. Their futuristic materials and designs survive along the lakeshore in Indiana Dunes National Park; exteriors can be viewed year-round, while interior tours are normally limited to special events.', 'open', null, 'https://www.atlasobscura.com/places/century-of-progress-architectural-district', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cerro Gordo Ghost Town', 'cerro-gordo-ghost-town', 'weird-history', 36.537743, -117.79506, 'Lone Pine', 'CA', 'A silver, lead and zinc town high in the Inyo Mountains from the 1860s, holding an unusually complete set of mining structures. The whole townsite is privately owned and reached up a steep eight-mile dirt road — follow the owner''s current visiting rules rather than treating it as open ground.', 'limited', null, 'https://lonepinechamber.org/sightseeing-in-the-lone-pine-area/ghost-towns/', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('C.H. Nash Museum at Chucalissa', 'ch-nash-museum-at-chucalissa', 'weird-history', 35.06231, -90.13009, 'Memphis', 'TN', 'Built beside a Mississippian mound complex, Chucalissa interprets Indigenous archaeology and the long history of Native communities in the Mississippi Valley. The preserved earthworks make the site a substantial archaeological landscape inside modern Memphis.', 'open', null, 'https://www.memphis.edu/chucalissa/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chamberlain Freedom Park', 'chamberlain-freedom-park', 'weird-history', 44.79773, -68.76144, 'Brewer', 'ME', 'This small park commemorates Maine’s connection to the Underground Railroad and includes a striking sculpture of a person emerging from a tunnel toward freedom. It stands near the former home of abolitionist John Holyoke and represents a side of Bangor-area history that is easy to overlook.', 'open', null, 'https://www.atlasobscura.com/places/chamberlain-freedom-park', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chaney-Goodman-Schwerner Murder Site Marker', 'chaney-goodman-schwerner-murder-site-marker', 'weird-history', 32.66353, -89.03163, 'Philadelphia', 'MS', 'A roadside historical marker near the rural location where James Chaney, Andrew Goodman and Michael Schwerner were murdered by members of the Ku Klux Klan in June 1964. Stop only where it is safe and lawful to pull off the road.', 'roadside', null, 'https://www.nps.gov/subjects/civilrights/mississippi.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Charley Patton Grave', 'charley-patton-grave', 'weird-history', 33.44472, -90.75806, 'Holly Ridge', 'MS', 'The grave of pioneering Delta blues musician Charley Patton, whose recordings and performance style influenced generations of later musicians. It is a cemetery stop and should be approached as a memorial, with normal cemetery etiquette.', 'open', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Charlotte Gemmell''s Teacher''s Desk Tombstone', 'charlotte-gemmells-teachers-desk-tombstone', 'weird-history', 42.94841, -72.31561, 'Keene', 'NH', 'Teacher Charlotte Gemmell''s granite grave marker is carved as a school desk complete with books and an apple. The personalized monument looks startlingly literal among conventional cemetery stones. The coordinate routes to Monadnock View Cemetery; follow the cemetery''s posted hours and directions to locate the individual grave.', 'limited', null, 'https://www.roadsideamerica.com/tip/33927', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chattanooga Choo Choo', 'chattanooga-choo-choo', 'weird-history', 35.03724, -85.30697, 'Chattanooga', 'TN', 'The former Terminal Station was transformed into a hotel-and-entertainment complex while retaining historic railcars and railroad architecture. Its name and identity were cemented by the famous big-band song, turning an old station into an unusually literal piece of pop-culture geography.', 'open', null, 'https://www.choochoo.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chef Boyardee''s Grave', 'chef-boyardees-grave', 'weird-history', 41.59212, -81.26771, 'Chardon', 'OH', 'Hector Boiardi, the Italian-born chef whose name became the Chef Boyardee brand, is entombed in the Crucifixion Mausoleum at All Souls Cemetery. Visitors can find his crypt in the Sacred Heart aisle during cemetery and mausoleum access hours, but this remains an active burial place and should be visited respectfully.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-chef-boyardee', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chennault Aviation & Military Museum', 'chennault-aviation-military-museum', 'weird-history', 32.51183, -92.05325, 'Monroe', 'LA', 'Named for General Claire Chennault, the museum explores the Flying Tigers, Selman Field navigation school and regional military history. Aircraft, uniforms and personal artifacts connect northeast Louisiana directly to global wartime stories.', 'open', null, 'https://chennaultmuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chester Inn State Historic Site', 'chester-inn-state-historic-site', 'weird-history', 36.29409, -82.4741, 'Jonesborough', 'TN', 'One of Jonesborough''s oldest commercial buildings survives as a museum interpreting travelers, politics and life in Tennessee''s oldest town. Its long association with stagecoach-era visitors makes it a physical remnant of early road travel.', 'limited', null, 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites/chester-inn.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chester Village Cemetery Carved Faces', 'chester-village-cemetery-carved-faces', 'weird-history', 42.95773, -71.25568, 'Chester', 'NH', 'Chester Village Cemetery contains a striking group of eighteenth-century gravestones carved with unusually expressive human faces. Several are attributed to local stonecarvers Stephen and Abel Webster, whose work ranges from smiling heads to grim or almost cartoonish expressions. The stones are historical funerary art, so visitors should look without touching or rubbing them.', 'limited', null, 'https://www.atlasobscura.com/places/chester-village-cemetery', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chicago Portage National Historic Site', 'chicago-portage-national-historic-site', 'weird-history', 41.80487, -87.80543, 'Lyons', 'IL', 'This quiet forest-preserve site marks the ancient portage that ultimately helped determine why Chicago grew where it did.', 'open', null, 'https://fpdcc.com/places/locations/chicago-portage-national-historic-site/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chickasaw Village Site', 'chickasaw-village-site', 'weird-history', 34.27795, -88.74178, 'Tupelo', 'MS', 'An NPS interpretive site focused on Chickasaw life and the Native landscape through which the Natchez Trace passed. A trail crosses the former village area and connects travelers with a history older than the roadway''s later Euro-American use.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chicken Bone Beach Marker', 'chicken-bone-beach-marker', 'weird-history', 39.35417, -74.43611, 'Atlantic City', 'NJ', 'A historical marker identifies the stretch of Atlantic City beach that Black visitors were informally restricted to during segregation. The nickname came from the picnic food reportedly left behind by beachgoers; today the location is interpreted as an important piece of Jersey Shore civil-rights history.', 'open', null, 'https://www.atlasobscura.com/places/chicken-bone-beach', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chief Menominee Monument and Trail of Death Site', 'chief-menominee-monument-and-trail-of-death-site', 'weird-history', 41.29565, -86.36177, 'Plymouth', 'IN', 'A 17-foot granite memorial marks the homeland of Potawatomi leader Menominee and the starting area associated with the forced 1838 removal remembered as the Potawatomi Trail of Death. The monument was dedicated in 1909 and is significant as an early government-funded memorial to a Native American leader.', 'open', null, 'https://www.visitmarshallcounty.in/history-culture', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Christmas Mound', 'christmas-mound', 'weird-history', 33.76952, -90.9807, 'Rosedale', 'MS', 'A solitary conical mound about 10 feet tall whose exact construction date remains uncertain, with evidence spanning Late Woodland and Mississippian periods. It stands on private property and should be viewed from the designated public route only.', 'roadside', null, 'https://trails.mdah.ms.gov/christmas', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Church Hill Tunnel Eastern Portal', 'church-hill-tunnel-eastern-portal', 'weird-history', 37.52719, -77.41489, 'Richmond', 'VA', 'The Church Hill railroad tunnel catastrophically collapsed on October 2, 1925 while crews were attempting to reopen it, entombing a locomotive and an uncertain number of workers underground. The tunnel was sealed and remains unsafe and inaccessible; only view the surviving portal area from legal public ground and never attempt to enter.', 'roadside', null, 'https://www.rva.gov/press-releases-and-announcements/news/city-commemorates-church-hill-tunnel-collapse', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Church Street Graveyard', 'church-street-graveyard', 'weird-history', 30.68572, -88.05074, 'Mobile', 'AL', 'Established after earlier burial grounds filled, this historic cemetery contains elaborate monuments and graves connected to Mobile’s nineteenth-century residents, epidemics and civic history. Treat it as an active historic cemetery rather than a paranormal playground.', 'open', null, 'https://www.cityofmobile.org/parks-rec/church-street-graveyard/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cincinnati Subway', 'cincinnati-subway', 'weird-history', 39.13663, -84.53281, 'Cincinnati', 'OH', 'Cincinnati began building an underground rapid-transit system in the 1920s using the former Miami and Erie Canal route, but the project was abandoned before any trains ever ran. Sections of tunnel and four unfinished stations still survive beneath the city, but official tours ended years ago and the sealed tunnels are illegal and unsafe to enter; record this as a closed historical stop only.', 'closed', null, 'https://www.atlasobscura.com/places/the-cincinnati-subway-cincinnati-ohio', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('City of Hawkinsville Underwater Archaeological Preserve', 'city-of-hawkinsville-underwater-archaeological-preserve', 'weird-history', 29.60775, -82.97083, 'Old Town', 'FL', 'Remarkably intact Suwannee River sternwheel steamboat abandoned as railroads ended the river-steamer era.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/city-of-hawkinsville/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('City West Ghost Town', 'city-west-ghost-town', 'weird-history', 41.6632, -87.06315, 'Chesterton', 'IN', 'City West was platted on the Lake Michigan shore in the 1830s with ambitions of becoming a major city and port. The Panic of 1837 helped kill the development, and shifting dunes eventually swallowed nearly every trace; the former townsite is now within Indiana Dunes State Park.', 'open', null, 'https://www.atlasobscura.com/places/city-west-ghost-town', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Civil War Grave in a Parking Lot', 'civil-war-grave-in-a-parking-lot', 'weird-history', 36.7918, -85.3729, 'Burkesville', 'KY', 'Civil War veteran Captain Jack McClain''s grave sits by itself on a small island in the parking lot of the Alpine resort. The burial predates the motel property and was preserved when the hilltop was developed, leaving a solitary nineteenth-century grave surrounded by asphalt and parked cars.', 'limited', null, 'https://www.roadsideamerica.com/tip/40304', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Civilian Conservation Corps Museum — DeSoto State Park', 'civilian-conservation-corps-museum-desoto-state-park', 'weird-history', 34.50056, -85.61833, 'Fort Payne', 'AL', 'A small seasonal museum preserves photographs, tools and artifacts connected to the Civilian Conservation Corps crews that built major portions of DeSoto State Park during the 1930s. The park itself still contains their stonework and structures.', 'limited', null, 'https://www.alapark.com/parks/desoto-state-park/civilian-conservation-corps-museum', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Clara Glen Pet Cemetery', 'clara-glen-pet-cemetery', 'weird-history', 39.33191, -74.58293, 'Egg Harbor Township', 'NJ', 'Weathered stones mark the graves of dogs and other pets in a small, easily overlooked burial ground surrounded by later residential development. The cemetery should be observed respectfully from legitimate public access without crossing neighboring private property.', 'roadside', null, 'https://www.atlasobscura.com/places/clara-glen-pet-cemetery', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clarkson Covered Bridge', 'clarkson-covered-bridge', 'weird-history', 34.2072, -86.99017, 'Cullman', 'AL', 'A nineteenth-century covered bridge preserved in a county park crosses Crooked Creek beside a restored grist mill and pioneer buildings. The bridge has been moved and repaired over time but remains one of Alabama’s best-preserved covered-bridge landmarks.', 'open', null, 'https://www.cullmancountyparks.com/clarkson.html', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Claude Rains Grave', 'claude-rains-grave', 'weird-history', 43.72593, -71.47517, 'Moultonborough', 'NH', 'Actor Claude Rains, remembered for films including "The Invisible Man" and "Casablanca," is buried in Red Hill Cemetery. His grave and his wife''s are marked by distinctive polished black stones with an almost futuristic shape. The secluded New Hampshire burial site makes an unexpected film-history stop.', 'limited', null, 'https://www.atlasobscura.com/places/claude-rains-grave', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clement Railroad Hotel Museum', 'clement-railroad-hotel-museum', 'weird-history', 36.07537, -87.38883, 'Dickson', 'TN', 'A former railroad hotel beside the tracks interprets travel, local history and the family of Tennessee governor Frank Clement. Its preserved railroad-era setting makes it a strong reminder of the town''s life around passenger rail.', 'limited', null, 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites/hotel-halbrook.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Clinton 12 Statue and Green McAdoo Cultural Center', 'clinton-12-statue-and-green-mcadoo-cultural-center', 'weird-history', 36.10233, -84.1399, 'Clinton', 'TN', 'The site interprets the twelve Black students who integrated Clinton High School in 1956 after a federal court order. Outdoor figures and museum exhibits make the confrontation over school desegregation concrete without reducing it to a generic historical marker.', 'open', null, 'https://greenmcadoo.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Clinton Train Tunnel', 'clinton-train-tunnel', 'weird-history', 42.40509, -71.68401, 'Clinton', 'MA', 'A disused railroad tunnel cuts beneath a wooded ridge near Clinton. The damp stone bore is a surviving remnant of nineteenth-century rail infrastructure and has the atmosphere of an abandoned underground passage; conditions and access can change, so follow current local rules and never enter if posted closed.', 'limited', null, 'https://www.atlasobscura.com/places/clinton-train-tunnel', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clopper Mill Ruins', 'clopper-mill-ruins', 'weird-history', 39.15313, -77.25369, 'Germantown', 'MD', 'A mill operated at this Seneca Creek location from the 18th century until the surviving structure burned in 1947, leaving picturesque stone walls beside the water. The area also has a Lincoln-assassination connection through conspirator George Atzerodt, who was familiar with and sought refuge around the region; reaching the ruins involves park trails and uneven ground.', 'limited', null, 'https://www.atlasobscura.com/places/ruins-of-clopper-mill', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clothespin Grave Marker', 'clothespin-grave-marker', 'weird-history', 44.31501, -72.6593, 'Middlesex', 'VT', 'A roughly five-foot granite clothespin marks the grave of Jack Crowell, associated with Vermont''s once-significant wooden clothespin industry. The monument turns an ordinary household object into an unexpectedly literal piece of funerary art.', 'open', null, 'https://www.roadsideamerica.com/tip/10414', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Club Ebony', 'club-ebony', 'weird-history', 33.44768, -90.64797, 'Indianola', 'MS', 'A historic Black nightclub that hosted major blues, soul and R&B performers and later became closely associated with B.B. King. The B.B. King Museum now stewards the property; public access is tied to scheduled programs/events rather than constant museum hours.', 'limited', null, 'https://bbkingmuseum.org/club-ebony/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cocaine Bear', 'cocaine-bear', 'weird-history', 38.04367, -84.45719, 'Lexington', 'KY', 'The Kentucky Fun Mall displays a taxidermied black bear presented as the animal that died after ingesting cocaine dropped by drug smuggler Andrew Thornton in Georgia in 1985. The bear''s later provenance has accumulated its own mythology, so the shop''s claim is best treated as part history and part modern roadside legend.', 'open', null, 'https://kyforky.com/pages/lexington-ky-s-kentucky-fun-mall-home-of-the-bear-who-ate-cocaine', '2026-09-08T14:30:49.642487+00:00', null, 'https://kyforky.com/', null, null, null, 'America/New_York'),
  ('Cocoanut Grove Fire Plaque', 'cocoanut-grove-fire-plaque', 'weird-history', 42.34998, -71.06814, 'Boston', 'MA', 'A plaque marks the neighborhood where the Cocoanut Grove nightclub burned in 1942, killing 492 people. The disaster led to major changes in fire codes, emergency exits and burn treatment, yet very little of the infamous nightclub is visible today beyond the memorial marker.', 'open', null, 'https://www.atlasobscura.com/places/cocoanut-grove-fire-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('COFO Civil Rights Education Center', 'cofo-civil-rights-education-center', 'weird-history', 32.29748, -90.20173, 'Jackson', 'MS', 'The former state headquarters of the Council of Federated Organizations, which coordinated major Mississippi civil-rights campaigns including the 1963 Freedom Vote and 1964 Freedom Summer. Jackson State University operates the restored site as an education center with regular weekday hours.', 'open', null, 'https://www.jsums.edu/cofo/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cold War Submarine Memorial', 'cold-war-submarine-memorial', 'weird-history', 32.79408, -79.90427, 'Mount Pleasant', 'SC', 'A memorial near Patriots Point commemorates Cold War submarine crews and features the sail and rudder of the nuclear-powered attack submarine USS Lewis and Clark. The preserved submarine pieces rise from the landscape like parts of a vessel still submerged underground.', 'open', null, 'https://www.hmdb.org/m.asp?m=19581', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Colebrook Murder Victims Memorial', 'colebrook-murder-victims-memorial', 'weird-history', 44.89496, -71.49688, 'Colebrook', 'NH', 'This memorial honors four people killed during Carl Drega''s 1997 shooting rampage in Colebrook: two New Hampshire state troopers, a judge and a newspaper editor. The monument gives visitors a concrete place to understand a violent event that deeply affected the North Country community. OddWay should present it strictly as a respectful memorial.', 'open', null, 'https://www.atlasobscura.com/places/colebrook-murder-victims-memorial', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coleman Veterans Memorial', 'coleman-veterans-memorial', 'weird-history', 43.75451, -84.5773, 'Coleman', 'MI', 'This memorial uses life-size soldier figures to represent veterans from multiple American conflicts. One of its most striking visual devices is the contrast between darker, solid figures representing those who returned and pale "ghost" soldiers representing those who did not.', 'open', null, 'https://www.michigan.org/property/coleman-veterans-memorial', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Colonel Sanders'' Grave', 'colonel-sanders-grave', 'weird-history', 38.24564, -85.71443, 'Louisville', 'KY', 'KFC founder Harland Sanders is buried in Cave Hill Cemetery beneath a monument featuring a sculpted bust with his unmistakable glasses, goatee and string tie. The cemetery marks the route to the grave with a colored road line for visitors.', 'open', null, 'https://www.roadsideamerica.com/tip/11451', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('Colonial Dorchester State Historic Site', 'colonial-dorchester-state-historic-site', 'weird-history', 32.94812, -80.17008, 'Summerville', 'SC', 'The ruins of the colonial town of Dorchester include brick foundations, an old church tower, cemetery, fortifications, and traces of streets from a settlement largely abandoned after the Revolutionary era. The preserved landscape functions like an archaeological ghost town beside the Ashley River.', 'limited', null, 'https://southcarolinaparks.com/colonial-dorchester', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coltsville & the Blue Onion Dome', 'coltsville-the-blue-onion-dome', 'weird-history', 41.75386, -72.67473, 'Hartford', 'CT', 'Samuel Colt built an enormous nineteenth-century industrial complex and planned community around his firearms factory. Its most immediately strange feature is the bright blue onion-shaped dome topped by a gilded colt, still visible above Hartford''s skyline.', 'open', null, 'https://www.atlasobscura.com/places/coltsville', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.nps.gov/colt/', null, null, null, 'America/New_York'),
  ('Concrete City', 'concrete-city', 'weird-history', 41.18852, -75.97528, 'Hanover Township', 'PA', 'Twenty reinforced-concrete houses were built here in 1911 as experimental company housing for coal workers, then abandoned little more than a decade later. The roofless shells still stand in the woods near Nanticoke, but reaching them requires walking from the public access area and the structures are deteriorated, so do not climb unstable walls or enter restricted land.', 'limited', null, 'https://en.wikipedia.org/wiki/Concrete_City', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Condé-Charlotte Museum', 'cond-charlotte-museum', 'weird-history', 30.68841, -88.04007, 'Mobile', 'AL', 'Built on the site of Mobile’s colonial fort and later used as a jailer’s residence, the house contains rooms interpreted through the city’s French, British, Spanish and American periods. Guided access reveals layers of Gulf Coast colonial history in one structure.', 'limited', null, 'https://condecharlotte.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Confederate Gravesites and Old Trace', 'confederate-gravesites-and-old-trace', 'weird-history', 34.36502, -88.67432, 'Tupelo', 'MS', 'A short segment of Old Trace leading to wartime graves associated with the Civil War era. The stop is quiet and historically sensitive; use the established path and treat the graves as a memorial rather than a paranormal attraction.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Confederate Memorial Park — Alabama Confederate Soldiers’ Home Site', 'confederate-memorial-park-alabama-confederate-soldiers-home-site', 'weird-history', 32.71812, -86.47442, 'Marbury', 'AL', 'This state historic site preserves the grounds of Alabama’s Confederate Soldiers’ Home, which operated from 1902 to 1939 for aging veterans and some wives and widows. A museum, cemeteries and surviving landscape interpret the institution and the postwar memory culture surrounding it.', 'open', null, 'https://ahc.alabama.gov/properties/confederate/confederate.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Congo Square', 'congo-square', 'weird-history', 29.96128, -90.06853, 'New Orleans', 'LA', 'Congo Square is historically associated with gatherings of enslaved and free people of African descent who played music, danced and traded on Sundays. The public space is foundational to histories of New Orleans music and African diasporic culture.', 'open', null, 'https://louisiana.edu/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Constitution Elm', 'constitution-elm', 'weird-history', 38.21348, -86.12734, 'Corydon', 'IN', 'Delegates drafting Indiana''s first state constitution met beneath a huge elm in Corydon in 1816 because the territorial capitol building was too hot. The tree died in 1925, but its enormous preserved trunk remains under a protective sandstone shelter at the historic site.', 'open', null, 'https://www.atlasobscura.com/places/constitution-elm', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Coral Castle Museum', 'coral-castle-museum', 'weird-history', 25.50063, -80.44404, 'Homestead', 'FL', 'Edward Leedskalnin''s one-man megalithic limestone complex, long surrounded by engineering and supernatural folklore.', 'limited', null, 'https://coralcastle.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coral Gables Merrick House', 'coral-gables-merrick-house', 'weird-history', 25.75149, -80.27175, 'Coral Gables', 'FL', 'Historic home of Coral Gables founder George Merrick, tied to the city''s planned Mediterranean fantasy.', 'limited', null, 'https://www.coralgables.com/merrickhouse', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Corbit-Sharp House Hidden Cubbyhole', 'corbit-sharp-house-hidden-cubbyhole', 'weird-history', 39.45383, -75.65714, 'Odessa', 'DE', 'The Corbit-Sharp House contains a concealed space associated with Underground Railroad history, hidden within an already unusual eighteenth-century home. Tours provide the context needed to understand the small secret compartment and the house''s role in Odessa''s history.', 'limited', null, 'https://www.atlasobscura.com/places/corbit-sharp-house', '2026-09-08T18:31:51.932734+00:00', null, 'https://historicodessa.org/', null, null, null, 'America/New_York'),
  ('Cornish-Windsor Covered Bridge', 'cornish-windsor-covered-bridge', 'weird-history', 43.47368, -72.38395, 'Windsor', 'VT', 'Built in 1866, this 449-foot covered bridge crosses the Connecticut River between Windsor and Cornish, New Hampshire. It remains one of the longest surviving wooden covered bridges in the United States and still carries road traffic across the state line.', 'open', null, 'https://www.loc.gov/pictures/item/nh0177/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cotton Museum at the Memphis Cotton Exchange', 'cotton-museum-at-the-memphis-cotton-exchange', 'weird-history', 35.14332, -90.0547, 'Memphis', 'TN', 'The former Cotton Exchange trading floor explains how cotton shaped Memphis commerce while confronting the crop''s connections to enslaved labor and the postwar agricultural economy. Original market infrastructure gives the museum an unusually direct setting.', 'open', null, 'https://www.memphiscottonmuseum.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Couch Tomb', 'couch-tomb', 'weird-history', 41.91293, -87.63142, 'Chicago', 'IL', 'An above-ground 1838 tomb left conspicuously standing inside Lincoln Park, a remnant of the cemetery that once occupied the grounds.', 'open', null, 'https://www.chicagoparkdistrict.com/parks-facilities/couch-tomb-artwork', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Crane Point Museum & Nature Center', 'crane-point-museum-nature-center', 'weird-history', 24.72684, -81.05246, 'Marathon', 'FL', 'Natural-history site with preserved Keys buildings, trails, and a wild-bird center.', 'limited', null, 'https://cranepoint.net/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crook Point Bascule Bridge', 'crook-point-bascule-bridge', 'weird-history', 41.82431, -71.38339, 'Providence', 'RI', 'The abandoned Crook Point railroad bridge has remained permanently raised over the Seekonk River since rail service ended in 1976. Its rusting draw span points sharply into the sky and has become one of Providence''s most recognizable pieces of industrial decay. View it from lawful public areas; the bridge itself is not an exploration site.', 'roadside', null, 'https://www.atlasobscura.com/places/crook-point-bascule-bridge', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crooked River Lighthouse', 'crooked-river-lighthouse', 'weird-history', 29.82688, -84.70157, 'Carrabelle', 'FL', 'Restored 1895 skeletal lighthouse with a keeper''s museum and original Fresnel lens.', 'limited', null, 'https://www.crookedriverlighthouse.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Croom Ghost Town Site', 'croom-ghost-town-site', 'weird-history', 28.60375, -82.36052, 'Brooksville', 'FL', 'Remnants of the former railroad and phosphate community of Croom survive within the Withlacoochee State Forest landscape.', 'limited', null, 'https://en.wikipedia.org/wiki/Croom,_Florida', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crown Point Bridge — What Lies Beneath Location', 'crown-point-bridge-what-lies-beneath-location', 'weird-history', 44.03612, -73.41892, 'Addison', 'VT', 'The Lake Champlain crossing at Crown Point played a prominent role in the 2000 supernatural film What Lies Beneath. The original bridge seen in the movie was demolished in 2009 and replaced, so today''s crossing is both a film-location stop and a reminder of a vanished landmark.', 'open', null, 'https://www.atlasobscura.com/places/crown-point-bridge', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crypt at Center Church-on-the-Green', 'crypt-at-center-church-on-the-green', 'weird-history', 41.30786, -72.92657, 'New Haven', 'CT', 'When Center Church was constructed over part of New Haven''s old burying ground, the builders preserved a section of the cemetery beneath the building. The resulting basement crypt surrounds visitors with 137 marked gravestones and additional burials believed to remain beneath the floor.', 'limited', null, 'https://www.atlasobscura.com/places/the-crypt-at-center-church-on-the-green', '2026-09-08T18:39:47.144889+00:00', null, 'https://centerchurchonthegreen.org/', null, null, null, 'America/New_York'),
  ('Crystal River Archaeological State Park', 'crystal-river-archaeological-state-park', 'weird-history', 28.89618, -82.62838, 'Crystal River', 'FL', 'Ancient ceremonial complex with temple mounds, burial mounds, middens, and a museum.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/crystal-river-archaeological-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cypress Grove Cemetery', 'cypress-grove-cemetery', 'weird-history', 29.97954, -90.11106, 'New Orleans', 'LA', 'Founded in 1840, Cypress Grove is known for elaborate above-ground tombs and large society mausoleums built by New Orleans fire companies. Visit only during posted cemetery hours and treat active gravesites respectfully.', 'limited', null, 'https://lcb.la.gov/cemetery-listings/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cypress Swamp', 'cypress-swamp', 'weird-history', 32.57952, -89.87002, 'Canton', 'MS', 'A short Natchez Trace trail loops through a water-filled cypress and tupelo swamp, creating one of the Parkway''s strangest and most atmospheric landscapes. Conditions can be wet and wildlife is present, so remain on the maintained trail.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dade Battlefield Historic State Park', 'dade-battlefield-historic-state-park', 'weird-history', 28.65269, -82.12888, 'Bushnell', 'FL', 'Site of the 1835 battle that ignited the Second Seminole War.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/dade-battlefield-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Daniel Boone''s Disputed Grave', 'daniel-boones-disputed-grave', 'weird-history', 38.19758, -84.86646, 'Frankfort', 'KY', 'Kentucky says Daniel Boone was reinterred here in Frankfort Cemetery in 1845, but Missouri has long disputed whether all of his remains were actually moved from his original grave. The resulting two-state burial controversy makes Boone''s elaborate Kentucky monument more unusual than a typical famous-person grave.', 'open', null, 'https://www.roadsideamerica.com/story/2507', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Daniel Boone''s Last Kentucky Home Marker', 'daniel-boones-last-kentucky-home-marker', 'weird-history', 38.33213, -84.06632, 'Carlisle', 'KY', 'A Kentucky historical marker identifies the area where Daniel and Rebecca Boone lived from 1795 until the family left Kentucky for Spanish Louisiana territory in 1799. The original cabin is not the attraction here; OddWay should route travelers to the official US 68 roadside marker.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=136919', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Daniels Ghost Town', 'daniels-ghost-town', 'weird-history', 39.31677, -76.81741, 'Ellicott City', 'MD', 'Daniels grew around a textile mill on the Patapsco River before the mill closed in the 1960s and Tropical Storm Agnes devastated the remaining community in 1972. Today hikers can find foundations, cemetery remnants and other traces of the vanished mill town inside the Patapsco Valley area.', 'limited', null, 'https://www.atlasobscura.com/places/daniels', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dark Dover Lantern Tours — John Bell House', 'dark-dover-lantern-tours-john-bell-house', 'weird-history', 39.156, -75.52308, 'Dover', 'DE', 'Seasonal Dark Dover tours begin at the historic John Bell House and lead visitors by lantern through the Dover Green area for darker stories, costumed encounters and occasional jump scares. It is a structured way to experience the capital’s stranger history rather than simply visiting another historic house.', 'limited', null, 'https://visitcentraldelaware.com/events-and-festivals/dark-dover-lantern-tours/', '2026-09-08T18:31:51.932734+00:00', null, 'https://history.delaware.gov/first-state-heritage-park/', null, null, null, 'America/New_York'),
  ('De Leon Springs State Park', 'de-leon-springs-state-park', 'weird-history', 29.13775, -81.36657, 'De Leon Springs', 'FL', 'Ancient canoes, sugar-mill history, Fountain of Youth branding, and the former water-skiing elephant attraction.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/de-leon-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('De Soto National Memorial', 'de-soto-national-memorial', 'weird-history', 27.52333, -82.64389, 'Bradenton', 'FL', 'Memorial landscape tied to Hernando de Soto''s violent 1539 expedition into the Southeast.', 'open', null, 'https://www.nps.gov/deso/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Deason Home', 'deason-home', 'weird-history', 31.60955, -89.19702, 'Ellisville', 'MS', 'A surviving 1800s house tied to the killing of Confederate deserter leader Newton Knight''s opponent Major Amos McLemore during the Civil War. Tours and special events are not always daily, so check current access before routing visitors onto the property.', 'limited', null, 'https://www.deasonhome.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Deep Throat Parking Garage Marker', 'deep-throat-parking-garage-marker', 'weird-history', 38.89601, -77.07308, 'Arlington', 'VA', 'During the Watergate investigation in 1972 and 1973, reporter Bob Woodward secretly met FBI official Mark Felt, later confirmed as "Deep Throat," in an underground garage in Rosslyn. A historical marker installed outside the complex in 2008 identifies the site; the garage remains an active parking facility, so OddWay visitors should use the exterior marker rather than wander through private parking levels.', 'roadside', null, 'https://www.atlasobscura.com/places/deep-throat-parking-garage', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Deerfield Massacre Mass Grave', 'deerfield-massacre-mass-grave', 'weird-history', 42.54539, -72.60816, 'Deerfield', 'MA', 'A communal grave in Deerfield marks the burial of residents killed during the 1704 French and Indigenous raid on the English settlement. The site is a serious memorial connected with a violent colonial frontier conflict rather than a paranormal attraction, but its concentrated history makes it a significant OddWay stop.', 'open', null, 'https://www.atlasobscura.com/places/deerfield-massacre-mass-grave', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Delaware Copper Mine', 'delaware-copper-mine', 'weird-history', 47.42417, -88.09861, 'Mohawk', 'MI', 'The Delaware Mine preserves an unsuccessful nineteenth-century copper operation whose underground levels can now be explored on a self-guided tour. Visitors descend into the mine at their own pace while the abandoned surface landscape preserves another chapter of the Keweenaw copper boom.', 'limited', null, 'https://www.delawareminetours.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.delawareminetours.com/', null, null, null, 'America/Detroit'),
  ('Delaware Wedge Plaque', 'delaware-wedge-plaque', 'weird-history', 39.718, -75.7848, 'Newark', 'DE', 'A small marker recalls the Delaware Wedge, a roughly 800-acre geographic anomaly created by conflicting colonial boundary surveys between Delaware, Pennsylvania and Maryland. The oddly shaped tract remained disputed for generations before the boundary was formally settled, turning a tiny roadside plaque into a marker for a surprisingly complicated cartographic problem.', 'roadside', null, 'https://history.delaware.gov/2023/01/11/delaware-wedge/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Delta Blues Museum', 'delta-blues-museum', 'weird-history', 34.20013, -90.57355, 'Clarksdale', 'MS', 'A major museum devoted to Delta blues history, housed in a former railroad depot and containing instruments, photographs, stage material and the reconstructed cabin associated with Muddy Waters. It is one of the strongest anchor stops for the state''s music-history route.', 'open', null, 'https://www.deltabluesmuseum.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Delta Music Museum', 'delta-music-museum', 'weird-history', 31.62955, -91.55355, 'Ferriday', 'LA', 'Ferriday''s free Delta Music Museum celebrates the region''s outsized influence on blues, gospel, country, rockabilly and rock and roll. Exhibits include performers such as Jerry Lee Lewis, Mickey Gilley and other musicians tied to the Mississippi Delta corridor.', 'open', null, 'https://deltamusicmuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Deserted Village of Feltville', 'deserted-village-of-feltville', 'weird-history', 40.6818, -74.3874, 'Berkeley Heights', 'NJ', 'Stone houses and other structures survive from a nineteenth-century mill community later reinvented as the summer resort Glenside Park. The abandoned settlement is preserved within Watchung Reservation and can be explored legally from public trails.', 'open', null, 'https://ucnj.org/parks-recreation/deserted-village/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Destrehan Plantation', 'destrehan-plantation', 'weird-history', 29.94539, -90.36532, 'Destrehan', 'LA', 'Destrehan is one of the lower Mississippi River valley''s oldest documented plantation houses and interprets slavery, sugar production and the site''s long social history. Access to the historic buildings is through the operating museum.', 'limited', null, 'https://www.destrehanplantation.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Detroit Eight Mile-Wyoming Wall', 'detroit-eight-mile-wyoming-wall', 'weird-history', 42.44222, -83.16611, 'Detroit', 'MI', 'This concrete wall was built in 1941 to physically separate a Black neighborhood from a planned white subdivision so developers could obtain federal housing financing under discriminatory lending practices. A section beside Alfonso Wells Memorial Playground now carries murals interpreting Black history, turning the surviving segregation barrier into an important public history site.', 'open', null, 'https://timeshiftamerica.com/birwood-wall/', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Detroit Industry Murals', 'detroit-industry-murals', 'weird-history', 42.3594, -83.0645, 'Detroit', 'MI', 'Diego Rivera''s monumental Detroit Industry fresco cycle covers the walls of the Detroit Institute of Arts'' Rivera Court with workers, machinery and industrial processes inspired by Ford factories. Painted in the early 1930s, the murals remain an unusually intense artistic record of Detroit''s manufacturing era.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/detroit-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Devil''s Hole Ruins', 'devils-hole-ruins', 'weird-history', 41.1403, -75.336, 'Paradise Township', 'PA', 'Deep in State Game Lands 221 are stone fireplaces, foundations and mechanical remnants from a large building whose exact purpose remains disputed, with stories ranging from a ski lodge to a Prohibition-era speakeasy. Reaching the ruins requires a secluded hike with multiple stream crossings, and hunters use the surrounding state game lands seasonally.', 'limited', null, 'https://www.atlasobscura.com/places/devils-hole-ruins', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dew Drop Inn', 'dew-drop-inn', 'weird-history', 29.93692, -90.09164, 'New Orleans', 'LA', 'The restored Dew Drop Inn was a major twentieth-century Black music venue and hotel that hosted rhythm-and-blues pioneers. It has reopened as a hotel, bar and performance space while preserving its music-history identity.', 'open', null, 'https://dewdropinnnola.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dew Drop Social & Benevolent Hall', 'dew-drop-social-benevolent-hall', 'weird-history', 30.356, -90.06226, 'Mandeville', 'LA', 'Built in 1895, the tiny wooden hall is one of the oldest surviving rural jazz venues in the country. It still hosts selected performances, making access event-dependent rather than daily.', 'limited', null, 'https://dewdropjazzhall.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dils Cemetery — Hatfield-McCoy Graves', 'dils-cemetery-hatfield-mccoy-graves', 'weird-history', 37.47785, -82.51477, 'Pikeville', 'KY', 'Dils Cemetery contains the graves of Randolph McCoy, his wife Sarah and several other people tied directly to the Hatfield-McCoy feud. The cemetery also has broader Civil War and local significance and can be reached from a designated parking area and stairway off Chloe Road.', 'open', null, 'https://www.hmdb.org/m.asp?m=146195', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dingess Tunnel', 'dingess-tunnel', 'weird-history', 37.86902, -82.17847, 'Dingess', 'WV', 'The 3,327-foot Dingess Tunnel opened in 1892 as part of the Norfolk & Western Railway and later became a one-lane county-road tunnel after the rail route was abandoned. It was substantially rehabilitated in 2019 with lighting, drainage and paving, and travelers can still drive through this unusually long former railroad bore today.', 'open', null, 'https://www.wvencyclopedia.org/entries/1867', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dinosaur Park Fossil Site', 'dinosaur-park-fossil-site', 'weird-history', 39.0708, -76.86861, 'Laurel', 'MD', 'This protected Early Cretaceous fossil site preserves one of the most important dinosaur deposits in the eastern United States, including material from Maryland''s state dinosaur, Astrodon. The fenced fossil area is only opened during scheduled public programs and dig experiences, although the surrounding playground and garden have broader access.', 'limited', null, 'https://www.pgparks.com/parks_trails/dinosaur-park', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dixville Notch Midnight Voting Site — The Balsams', 'dixville-notch-midnight-voting-site-the-balsams', 'weird-history', 44.88172, -71.31662, 'Dixville', 'NH', 'Dixville Notch became nationally famous for casting presidential-primary and general-election ballots just after midnight, traditionally inside The Balsams resort. The tiny community''s first-results ritual became one of New Hampshire''s strangest political traditions. The historic hotel has been closed while redevelopment plans continue, so this is an exterior and historical-routing stop only unless public access is officially announced.', 'private', null, 'https://www.historic-structures.com/nh/dixville/balsams_resort.php', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dizzy Gillespie Birthplace Park', 'dizzy-gillespie-birthplace-park', 'weird-history', 34.6987, -79.8929, 'Cheraw', 'SC', 'A small park and historical marker occupy the area associated with the birthplace of jazz trumpeter Dizzy Gillespie. The site celebrates the musician famous for his bent trumpet, puffed cheeks, and enormous influence on bebop.', 'open', null, 'https://www.hmdb.org/m.asp?m=28273', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Doc Blanchard Memorial', 'doc-blanchard-memorial', 'weird-history', 34.22018, -80.24617, 'Bishopville', 'SC', 'Bishopville honors Felix “Doc” Blanchard, the 1945 Heisman Trophy winner and West Point football star, with a downtown monument. Blanchard later became an Air Force pilot, giving the small town an unusually substantial memorial to a local sports legend.', 'open', null, 'https://www.scpictureproject.org/lee-county/doc-blanchard-memorial.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dockery Farms', 'dockery-farms', 'weird-history', 33.72889, -90.61278, 'Cleveland', 'MS', 'A former cotton plantation widely associated with early Delta blues history and musicians including Charley Patton. Surviving buildings, signs and interpretive material make the site physically meaningful, but access to individual structures/events varies, so check the operator before visiting.', 'limited', null, 'https://www.dockeryfarms.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dogtown and the Babson Boulder Trail', 'dogtown-and-the-babson-boulder-trail', 'weird-history', 42.63641, -70.66113, 'Gloucester', 'MA', 'The woods above Gloucester contain cellar holes from an abandoned colonial settlement known as Dogtown. Decades after the village vanished, millionaire Roger Babson had dozens of huge boulders carved with commands and maxims such as ''USE YOUR HEAD'' and ''GET A JOB,'' creating one of New England''s strangest hiking trails.', 'open', null, 'https://www.atlasobscura.com/places/dogtown-babson-words-rocks', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dolly Parton Statue', 'dolly-parton-statue', 'weird-history', 35.86772, -83.56604, 'Sevierville', 'TN', 'A bronze Dolly Parton sits with a guitar outside the Sevier County Courthouse in her hometown. The unusually approachable monument has become a pilgrimage point connecting one of Tennessee''s most famous performers directly to the place where her story began.', 'open', null, 'https://www.atlasobscura.com/places/dolly-parton-statue', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Doodletown Ghost Town', 'doodletown-ghost-town', 'weird-history', 41.29596, -73.9916, 'Stony Point', 'NY', 'Doodletown was a small Hudson Highlands settlement whose remaining residents left in the 1960s after the Palisades Interstate Park Commission acquired the property. House foundations, roads, cemeteries and interpretive signs remain in the woods, reached only by hiking trails inside Bear Mountain State Park.', 'limited', null, 'https://parks.ny.gov/sites/default/files/BearMountainSuggestedHikes.pdf', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Doris Duke''s Pet Cemetery', 'doris-dukes-pet-cemetery', 'weird-history', 40.54433, -74.62393, 'Hillsborough Township', 'NJ', 'Heiress Doris Duke buried a number of beloved dogs and other animals on her vast Duke Farms estate. Their individual markers form an unusual private-animal cemetery that can be reached only according to Duke Farms'' public access rules and trail hours.', 'limited', null, 'https://www.atlasobscura.com/places/doris-dukes-pet-cemetery', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Double Eagle II Balloon Site', 'double-eagle-ii-balloon-site', 'weird-history', 46.62732, -68.02103, 'Presque Isle', 'ME', 'A small park commemorates the field where Double Eagle II launched in 1978 before completing the first successful transatlantic balloon crossing. Displays and a balloon replica mark the beginning of a flight that ended thousands of miles away in France.', 'open', null, 'https://www.atlasobscura.com/places/double-eagle-balloon-site', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Double Parking Meter Tombstone', 'double-parking-meter-tombstone', 'weird-history', 41.24949, -84.83918, 'Harlan', 'IN', 'Archillous "Archie" Arnold''s grave in Scipio Cemetery is flanked by two old parking meters, both permanently reading "Expired." The intentionally comic memorial turns an ordinary rural cemetery visit into one of Indiana''s stranger examples of personalized grave art.', 'open', null, 'https://www.roadsideamerica.com/story/75086', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Double Trouble Village', 'double-trouble-village', 'weird-history', 39.89788, -74.22129, 'Berkeley Township', 'NJ', 'A former Pine Barrens company town survives inside Double Trouble State Park, where cranberry agriculture and Atlantic white-cedar logging once supported a small industrial community. Historic houses, a sawmill and other village structures remain along public trails.', 'open', null, 'https://dep.nj.gov/parksandforests/state-park/double-trouble-state-park/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Doumar''s Original Waffle Cone Machine', 'doumars-original-waffle-cone-machine', 'weird-history', 36.86616, -76.28485, 'Norfolk', 'VA', 'Doumar''s still uses the original-style four-iron waffle machine associated with founder Abe Doumar, who helped popularize the rolled waffle ice-cream cone at the 1904 St. Louis World''s Fair. The century-old drive-in remains in business, and visitors can often watch cones being made on the historic machine while ordering from the restaurant.', 'open', null, 'https://www.atlasobscura.com/places/doumar-s-barbecue', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dr. DeVore’s Trapdoor Grave', 'dr-devores-trapdoor-grave', 'weird-history', 33.7922, -81.9342, 'Edgefield', 'SC', 'The grave of Dr. William DeVore is associated with an unusual above-ground structure traditionally described as having a trapdoor or access hatch. Local stories offer competing explanations for the grave’s peculiar construction, helping turn a single burial into a longstanding Edgefield curiosity.', 'open', null, 'https://www.roadsideamerica.com/tip/46027', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dr. Samuel A. Mudd House Museum', 'dr-samuel-a-mudd-house-museum', 'weird-history', 38.60958, -76.8262, 'Waldorf', 'MD', 'Dr. Samuel Mudd treated John Wilkes Booth''s broken leg here after Lincoln''s assassination, helping make the farmhouse one of the most notorious stops on Booth''s escape route. The privately owned historic property operates as a seasonal museum on selected days rather than daily.', 'limited', null, 'https://drmudd.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Drake Well Museum and Park', 'drake-well-museum-and-park', 'weird-history', 41.61128, -79.65827, 'Titusville', 'PA', 'Edwin Drake''s successful 1859 oil well at this site helped launch the modern petroleum industry. The museum preserves a replica well house, operating historic oil-field equipment and exhibits explaining the chaotic oil boom that transformed northwestern Pennsylvania.', 'open', null, 'https://www.drakewell.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dry Tortugas National Park', 'dry-tortugas-national-park', 'weird-history', 24.62849, -82.87319, 'Key West', 'FL', 'Remote islands, shipwreck history, legends of treasure, and the giant Fort Jefferson.', 'limited', null, 'https://www.nps.gov/drto/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('D.T. Sheridan Shipwreck', 'dt-sheridan-shipwreck', 'weird-history', 43.75594, -69.30842, 'Monhegan', 'ME', 'The rusted remains of the tugboat D.T. Sheridan lie along the rocky shoreline of Monhegan Island after the vessel wrecked there in 1948. Reaching the site requires a ferry to the island followed by a hike, and visitors should stay well clear of dangerous surf.', 'limited', null, 'https://www.atlasobscura.com/places/d-t-sheridan-shipwreck', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ducktown Basin Museum and Burra Burra Mine', 'ducktown-basin-museum-and-burra-burra-mine', 'weird-history', 35.0276, -84.3872, 'Ducktown', 'TN', 'The museum occupies the former headquarters of a copper-mining operation in a landscape once heavily damaged by smelting and deforestation. Mining artifacts, the Burra Burra Mine site and the basin''s environmental recovery make this a stark industrial-history stop.', 'limited', null, 'https://ducktownbasinmuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Duncan Hines Home and Office Marker', 'duncan-hines-home-and-office-marker', 'weird-history', 37.01035, -86.3965, 'Bowling Green', 'KY', 'Before his name became synonymous with boxed cake mix, Bowling Green native Duncan Hines was a traveling salesman and restaurant critic whose guidebooks helped motorists find dependable places to eat. A historical marker identifies his former home and office and explains the real man behind the supermarket brand.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dunlawton Sugar Mill Gardens', 'dunlawton-sugar-mill-gardens', 'weird-history', 29.13395, -81.01374, 'Port Orange', 'FL', 'Botanical gardens surrounding plantation sugar-mill ruins and surviving old roadside-attraction dinosaur statues.', 'limited', null, 'https://www.dunlawtonsugarmillgardens.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dunn Mounds', 'dunn-mounds', 'weird-history', 34.21702, -90.47625, 'Tunica', 'MS', 'Three surviving earthen mounds visible from Mississippi Highway 6, including an unusually elongated oval mound. The site is private; the designated highway viewing area is the stop.', 'roadside', null, 'https://trails.mdah.ms.gov/dunn', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dutchman''s Curve', 'dutchmans-curve', 'weird-history', 36.1275, -86.8493, 'Nashville', 'TN', 'The 1918 collision at Dutchman''s Curve became one of the deadliest train wrecks in U.S. history. A public greenway and historical interpretation allow visitors to understand the disaster without entering active railroad property; tracks should never be crossed or followed.', 'open', null, 'https://www.atlasobscura.com/places/dutchmans-curve', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Eagle Lake Tramway and Abandoned Locomotives', 'eagle-lake-tramway-and-abandoned-locomotives', 'weird-history', 46.28611, -69.34837, 'T7 R13 WELS', 'ME', 'Deep in the North Maine Woods sit two abandoned steam locomotives and remnants of an elaborate tramway and railroad system once used to move timber between watersheds. Reaching them is a serious backcountry trip involving remote roads, trails, and careful trip planning.', 'limited', null, 'https://www.atlasobscura.com/places/eagle-lake-tramway', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('East Corinth — Beetlejuice Filming Location', 'east-corinth-beetlejuice-filming-location', 'weird-history', 44.06398, -72.22223, 'Corinth', 'VT', 'East Corinth stood in for the fictional Connecticut town of Winter River in Tim Burton''s 1988 film Beetlejuice. The village landscape and recognizable road views remain, but OddWay visitors should remember that most individual buildings are private homes rather than film attractions.', 'roadside', null, 'https://www.atlasobscura.com/places/east-corinth', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('East Rock Soldiers'' and Sailors'' Monument', 'east-rock-soldiers-and-sailors-monument', 'weird-history', 41.32725, -72.90462, 'New Haven', 'CT', 'A tall nineteenth-century war monument crowns East Rock above New Haven, reached by road or trail depending on seasonal access. The summit setting makes the ornate monument feel more like a hilltop shrine than a conventional downtown memorial.', 'open', null, 'https://www.roadsideamerica.com/story/26977', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eastern Cemetery', 'eastern-cemetery', 'weird-history', 43.66252, -70.25009, 'Portland', 'ME', 'Portland’s oldest historic cemetery contains markers dating to the early 1700s, underground tombs, maritime graves, and the burial places of captains connected with the War of 1812 battle between the Enterprise and Boxer. Seasonal guided tours reveal stories and structures that are easy to miss from the street.', 'limited', null, 'https://www.visitportland.com/event/spirits-alive-walking-tours/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ebright Azimuth — Delaware High Point Marker', 'ebright-azimuth-delaware-high-point-marker', 'weird-history', 39.8358, -75.5192, 'Wilmington', 'DE', 'Delaware''s famously modest high point is commemorated by the Ebright Azimuth benchmark near the Pennsylvania line. The marker is commonly treated as the state''s high-point stop even though the absolute highest ground is slightly offset nearby.', 'roadside', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eckley Miners'' Village', 'eckley-miners-village', 'weird-history', 40.99525, -75.85606, 'Foster Township', 'PA', 'Eckley is a remarkably intact nineteenth-century anthracite company town with miners'' houses, churches, a company store and other surviving structures. The village itself can be walked or driven through from dawn to dusk, while the museum and building interiors follow posted hours.', 'open', null, 'https://eckleyminersvillage.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe Grave', 'edgar-allan-poe-grave', 'weird-history', 39.29027, -76.62333, 'Baltimore', 'MD', 'Edgar Allan Poe was buried at Westminster Burying Ground after his mysterious death in Baltimore in 1849, then moved to the prominent monument near the cemetery entrance in 1875. Visitors can see both the monument and his original burial place inside the historic graveyard.', 'open', null, 'https://www.westminsterhall.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe Square and Statue', 'edgar-allan-poe-square-and-statue', 'weird-history', 42.3523, -71.06731, 'Boston', 'MA', 'Near the vanished street where Edgar Allan Poe was born, Boston has installed a dramatic statue of the writer striding forward with a raven and a heart spilling from his suitcase. The surrounding plaza is officially named for Poe, despite his famously complicated relationship with his birth city.', 'open', null, 'https://www.atlasobscura.com/places/edgar-allan-poe-square', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Cayce A.R.E. Headquarters', 'edgar-cayce-are-headquarters', 'weird-history', 36.8928, -75.98994, 'Virginia Beach', 'VA', 'Psychic Edgar Cayce and his supporters founded the Association for Research and Enlightenment in 1931 to preserve and study material from his thousands of claimed psychic readings. The Virginia Beach headquarters now includes a large metaphysical library, bookstore, meditation garden, historic hospital building and public programs on Cayce''s work.', 'open', null, 'https://edgarcayce.org/about-us/our-organization/', '2026-09-08T04:17:48.352537+00:00', null, 'https://edgarcayce.org/', null, null, null, 'America/New_York'),
  ('Edgefield Mounds', 'edgefield-mounds', 'weird-history', 34.99215, -90.21558, 'Lake Cormorant', 'MS', 'Three conical Mississippian mounds line an old Mississippi River levee near Lake Cormorant. Soil removal for levee work altered the landscape around them, and visitors should remain on the public road rather than entering the site.', 'roadside', null, 'https://trails.mdah.ms.gov/edgefield', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Edward Ball Wakulla Springs State Park', 'edward-ball-wakulla-springs-state-park', 'weird-history', 30.23553, -84.30169, 'Wakulla Springs', 'FL', 'Massive spring, mastodon finds, old Florida lodge, and filming history for classic creature movies.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/edward-ball-wakulla-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elaborate Grave of Singin'' Sam Stevens', 'elaborate-grave-of-singin-sam-stevens', 'weird-history', 40.68953, -74.21353, 'Hillside', 'NJ', 'Romani musician Singin'' Sam Stevens is memorialized with an extravagant black-granite monument featuring gold musical notes, a carved amplifier, electric guitar and oversized record. The grave sits inside Evergreen Cemetery, which has posted daily visiting hours.', 'limited', null, 'https://www.roadsideamerica.com/story/33809', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elijah P. Lovejoy Monument', 'elijah-p-lovejoy-monument', 'weird-history', 38.89016, -90.1659, 'Alton', 'IL', 'A tall cemetery monument honors abolitionist editor Elijah Lovejoy, murdered by a pro-slavery mob in Alton in 1837.', 'open', null, 'https://dnrhistoric.illinois.gov/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Elizabeth Harrison Memorial — Oak Hill Cemetery', 'elizabeth-harrison-memorial-oak-hill-cemetery', 'weird-history', 37.99045, -87.53525, 'Evansville', 'IN', 'Elizabeth Harrison, a recognized leader within a nineteenth-century Romani traveling community, died in 1895 and was buried at Oak Hill Cemetery after a funeral that drew widespread public attention. Her family monument remains in Section 23; historical sources often use the period title "Queen of the Gypsies," but OddWay should describe the site with the more respectful Romani terminology.', 'open', null, 'https://www.roadsideamerica.com/story/23179', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Elizabeth Short — Black Dahlia Memorial', 'elizabeth-short-black-dahlia-memorial', 'weird-history', 42.41949, -71.10244, 'Medford', 'MA', 'A memorial in Medford Cemetery remembers Elizabeth Short, the Massachusetts-born woman whose 1947 murder in Los Angeles became known as the Black Dahlia case. Short is not buried here, but the marker gives her hometown region a physical connection to one of America''s most famous unsolved murders.', 'open', null, 'https://www.atlasobscura.com/places/elizabeth-short-memorial', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elkmont Historic District', 'elkmont-historic-district', 'weird-history', 35.65429, -83.58057, 'Elkmont', 'TN', 'Elkmont grew from a logging settlement into a resort community before much of it was absorbed into Great Smoky Mountains National Park. Preserved cabins, restored structures and traces of vanished buildings create a rare legal-to-explore ghost-of-a-resort landscape.', 'open', null, 'https://www.nps.gov/grsm/learn/historyculture/elkmont-historic-district.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ellie Schiller Homosassa Springs Wildlife State Park', 'ellie-schiller-homosassa-springs-wildlife-state-park', 'weird-history', 28.79909, -82.5894, 'Homosassa', 'FL', 'Old Florida attraction with an underwater observatory and the state''s long-resident hippo, Lu.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/ellie-schiller-homosassa-springs-wildlife-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elmwood Cemetery', 'elmwood-cemetery', 'weird-history', 35.12183, -90.02901, 'Memphis', 'TN', 'Memphis''s historic garden cemetery contains elaborate monuments, mass-grave history, yellow-fever burials and generations of the city''s political and cultural figures. Its funerary art and difficult history make it an outdoor archive rather than simply a famous-person graveyard.', 'limited', null, 'https://www.elmwoodcemetery.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Elvis Presley Birthplace', 'elvis-presley-birthplace', 'weird-history', 34.25997, -88.67994, 'Tupelo', 'MS', 'The two-room house where Elvis Presley was born, preserved with a museum, chapel, church and interpretive grounds. The small scale of the birthplace against the later Elvis mythology makes it a particularly effective music-history stop.', 'open', null, 'https://elvispresleybirthplace.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Emerald Mound', 'emerald-mound', 'weird-history', 31.63542, -91.24767, 'Natchez', 'MS', 'One of the largest Native American ceremonial mounds in the United States, built by ancestors of the Natchez people and covering roughly eight acres. The National Park Service preserves the site and visitors can walk onto the massive earthwork.', 'open', null, 'https://trails.mdah.ms.gov/emerald', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.nps.gov/places/emerald-mound.htm', null, null, null, 'America/Chicago'),
  ('Emerson''s Pickle Factory Plaque', 'emersons-pickle-factory-plaque', 'weird-history', 42.4007, -71.11733, 'Somerville', 'MA', 'A stone marker and replica jars commemorate George W. Emerson''s once-successful pickle factory, which burned in the nineteenth century. It is a wonderfully specific monument to a vanished condiment empire, sitting near Somerville''s much older Powder House.', 'open', null, 'https://www.atlasobscura.com/places/george-w-emersons-pickle-factory-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Emil Hanslin''s Loaf of Bread Tomb', 'emil-hanslins-loaf-of-bread-tomb', 'weird-history', 43.40479, -71.99064, 'New London', 'NH', 'An above-ground stone tomb in Old Main Street Cemetery looks uncannily like an enormous loaf of bread. Roadside lore has sometimes claimed Hanslin was a baker, but he was actually involved in real estate—the resemblance appears to be coincidental. That lack of an elaborate legend arguably makes the oversized stone form stranger.', 'limited', null, 'https://www.roadsideamerica.com/tip/8519', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Emmett Till Interpretive Center', 'emmett-till-interpretive-center', 'weird-history', 33.9711, -90.3698, 'Sumner', 'MS', 'A museum and interpretive center across from the courthouse where the men accused of murdering Emmett Till were tried and acquitted in 1955. The center places the Till case within the broader history of racial violence, memory and reconciliation in the Mississippi Delta.', 'open', null, 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.emmett-till.org/', null, null, null, 'America/Chicago'),
  ('Endicott Rock', 'endicott-rock', 'weird-history', 43.60494, -71.45617, 'Laconia', 'NH', 'Protected beneath a small stone shelter is a boulder inscribed in 1652 during an early attempt to establish the northern boundary of Massachusetts. The marks are often described as among the oldest surviving public inscriptions or monuments of colonial government in New England. The state historic site is generally open for outdoor visitation unless otherwise posted.', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/endicott-rock-historic-site', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Endor Iron Furnace', 'endor-iron-furnace', 'weird-history', 35.55318, -79.21876, 'Cumnock', 'NC', 'A massive stone furnace built during the Civil War still stands near the Deep River. The short-lived industrial site once smelted local iron ore and today survives as a striking isolated ruin from North Carolina’s early heavy industry.', 'limited', null, 'https://carolinageologicalsociety.org/2010s_files/gb%202011.pdf', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ephraim Huit Grave', 'ephraim-huit-grave', 'weird-history', 41.85688, -72.63852, 'Windsor', 'CT', 'The 1644 gravestone of minister Ephraim Huit is generally regarded as Connecticut''s oldest surviving dated headstone and one of the oldest legible dated grave markers in the country. Its unusual carved inscription has survived for nearly four centuries.', 'open', null, 'https://www.atlasobscura.com/places/ephraim-huit-grave', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ernest Borgnine Park', 'ernest-borgnine-park', 'weird-history', 41.34427, -72.92923, 'Hamden', 'CT', 'A tiny patch of land at a shopping-center corner is officially dedicated to Hamden-born actor Ernest Borgnine. Its modest size compared with the Oscar-winning actor it honors is part of the charm.', 'open', null, 'https://www.roadsideamerica.com/tip/22258', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eternal Silence', 'eternal-silence', 'weird-history', 41.9588, -87.6615, 'Chicago', 'IL', 'A hooded bronze figure looms over the Graves family plot in Graceland Cemetery, producing one of Chicago''s most unnerving funerary monuments.', 'limited', null, 'https://www.gracelandcemetery.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ether Monument', 'ether-monument', 'weird-history', 42.35482, -71.07143, 'Boston', 'MA', 'A dramatic monument in Boston Public Garden commemorates the introduction of surgical anesthesia. The sculpture is unusually elaborate for a medical breakthrough, combining allegorical figures and biblical imagery around a discovery that transformed surgery.', 'open', null, 'https://www.atlasobscura.com/places/ether-monument', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eudora Welty House & Garden', 'eudora-welty-house-garden', 'weird-history', 32.31727, -90.17028, 'Jackson', 'MS', 'The longtime home of writer Eudora Welty, preserved with her books, furnishings, garden and personal environment substantially intact. Guided access is structured around museum hours and tours, making it a strong literary stop rather than a generic historic house.', 'limited', null, 'https://welty.mdah.ms.gov/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Evans City Cemetery — Night of the Living Dead', 'evans-city-cemetery-night-of-the-living-dead', 'weird-history', 40.76239, -80.064, 'Evans City', 'PA', 'The opening cemetery sequence in George A. Romero''s 1968 Night of the Living Dead was filmed here, including the first zombie attack on Johnny and Barbra. The cemetery is still active and open to respectful visitors, so stay on cemetery roads and paths and avoid disturbing graves while looking for recognizable filming locations.', 'open', null, 'https://filmoblivion.com/2021/10/20/night-of-the-living-dead-1968/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Evans-Ellis Cemetery', 'evans-ellis-cemetery', 'weird-history', 40.4892, -74.41658, 'North Brunswick Township', 'NJ', 'A tiny family cemetery survives in an unlikely island of grass beside modern commercial development. Old headstones belonging to early local families remain surrounded by the infrastructure that grew up around the once-rural burial ground.', 'limited', null, 'https://www.atlasobscura.com/places/evans-ellis-cemetery', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Evans Family Cemetery — Graves in a Mall Parking Lot', 'evans-family-cemetery-graves-in-a-mall-parking-lot', 'weird-history', 35.58635, -77.36881, 'Greenville', 'NC', 'A small fenced family cemetery containing 19th-century graves sits marooned inside the pavement surrounding Greenville Mall. Modern commercial development grew around the burial ground instead of removing it, leaving old headstones surrounded by parking spaces and traffic.', 'open', null, 'https://fotospot.com/attractions/north-carolina/cemetery-in-mall-parking-lot', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Evansville Mounds', 'evansville-mounds', 'weird-history', 34.64068, -90.39238, 'Evansville', 'MS', 'A prehistoric mound complex near the unincorporated community of Evansville in Tunica County. The surviving earthworks are part of the Mississippi Mound Trail but remain on private property, so use the public viewing route.', 'roadside', null, 'https://trails.mdah.ms.gov/evansville', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Expired Parking Meter Gravestone', 'expired-parking-meter-gravestone', 'weird-history', 42.66632, -73.01175, 'Florida', 'MA', 'Gordy and Joyce Burdick''s grave incorporates an actual parking meter labeled as expired, turning a roadside object into a permanent cemetery joke. The unusual marker sits in a small burial ground near the Hoosac Tunnel region. Visit respectfully during permitted hours.', 'limited', null, 'https://www.atlasobscura.com/places/expired-parking-meter-gravestone', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eyrie House Ruins', 'eyrie-house-ruins', 'weird-history', 42.28015, -72.62048, 'Holyoke', 'MA', 'Stone walls and cellar holes are all that remain of a once-popular mountaintop hotel. The Eyrie House was destroyed in 1901 after owner William Street tried to cremate two dead horses on a funeral pyre and accidentally set the property ablaze.', 'open', null, 'https://www.atlasobscura.com/places/eyrie-house-ruins', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('F. Scott and Zelda Fitzgerald Graves', 'f-scott-and-zelda-fitzgerald-graves', 'weird-history', 39.082, -77.14536, 'Rockville', 'MD', 'F. Scott Fitzgerald and Zelda Fitzgerald are buried together in the small cemetery at St. Mary''s Catholic Church, beneath a stone engraved with the final line of The Great Gatsby. The graves are easy to visit from the church property but should be treated as an active cemetery rather than a roadside photo prop.', 'open', null, 'https://www.roadsideamerica.com/location/md/all', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('F. Scott and Zelda Fitzgerald Museum', 'f-scott-and-zelda-fitzgerald-museum', 'weird-history', 32.35873, -86.2923, 'Montgomery', 'AL', 'The Fitzgeralds lived in this Old Cloverdale house in 1931–32, and it is now the world’s only museum dedicated to both F. Scott and Zelda Fitzgerald. Exhibits preserve their books, correspondence, photographs and Montgomery connections.', 'open', null, 'https://fitzmuse.squarespace.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fairbanks House', 'fairbanks-house', 'weird-history', 42.24323, -71.16776, 'Dedham', 'MA', 'Built around 1637–1641, the Fairbanks House is generally regarded as the oldest surviving timber-frame house in North America. Its irregular additions, low rooms and centuries of family occupation make it feel considerably stranger than a polished colonial reconstruction; tours are seasonal.', 'limited', null, 'https://www.fairbankshouse.org/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.fairbankshouse.org/', null, null, null, 'America/New_York'),
  ('FAME Recording Studios', 'fame-recording-studios', 'weird-history', 34.74506, -87.66667, 'Muscle Shoals', 'AL', 'FAME became one of the defining recording studios of the Muscle Shoals sound, hosting artists across soul, rock and country. Scheduled tours allow visitors into the still-working studio rather than a reconstructed museum space.', 'limited', null, 'https://famestudios.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fannie Lou Hamer Memorial Garden', 'fannie-lou-hamer-memorial-garden', 'weird-history', 33.73362, -90.54035, 'Ruleville', 'MS', 'The burial place and memorial garden of voting-rights leader Fannie Lou Hamer, with a bronze statue, Freedom Trail marker and quotations from her life and activism. A dedicated parking area was completed in 2024, making the memorial a practical public stop.', 'open', null, 'https://www.fannielouhamersamerica.com/driving-tour/fannie-lou-hamer-memorial-gardens', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fayette Historic State Park', 'fayette-historic-state-park', 'weird-history', 45.71669, -86.66111, 'Garden', 'MI', 'Fayette preserves the remains of a nineteenth-century iron-smelting company town on the Garden Peninsula. More than 20 historic buildings and ruins survive around the old harbor and industrial area, giving travelers a walkable, state-managed version of a genuine Upper Peninsula ghost town.', 'open', null, 'https://www.michigan.gov/recsearch/parks/fayette', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Fernald Preserve Visitors Center', 'fernald-preserve-visitors-center', 'weird-history', 39.28805, -84.68354, 'Hamilton', 'OH', 'The Fernald site produced uranium metal for the U.S. nuclear weapons program during the Cold War before shutting down production in 1989 and undergoing a massive environmental cleanup. It is now a Department of Energy nature preserve, and the free visitor center contains exhibits on uranium production, contamination, remediation and the site''s transformation into public trails and habitat.', 'open', null, 'https://www.energy.gov/lm/fernald-preserve-ohio-site', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Feudists on Trial Hanging Site Marker', 'feudists-on-trial-hanging-site-marker', 'weird-history', 37.47948, -82.52172, 'Pikeville', 'KY', 'A Kentucky historical marker on the University of Pikeville campus identifies the site where Ellison "Cottontop" Mounts was hanged on February 18, 1890 for his role in the murder of Alifair McCoy. His execution is often treated as one of the final official acts of violence connected to the Hatfield-McCoy feud.', 'roadside', null, 'https://history.ky.gov/markers/feudists-on-trial', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Firehorse Fred', 'firehorse-fred', 'weird-history', 35.10903, -77.04086, 'New Bern', 'NC', 'The preserved head of Fred, a New Bern fire horse who served the city in the early 1900s, is displayed at the New Bern Firemen’s Museum. According to museum history, Fred died while still harnessed after responding to what turned out to be a false alarm. Museum: https://newbernfiremuseum.com/', 'limited', null, 'https://www.roadsideamerica.com/story/2149', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('First Bowie Knife Historical Marker', 'first-bowie-knife-historical-marker', 'weird-history', 31.12735, -92.066, 'Marksville', 'LA', 'A roadside marker commemorates the violent 1827 Sandbar Fight and the rise of the large fighting knife associated with Jim Bowie. The exact evolution of the ''Bowie knife'' is more complicated than the legend, but Marksville claims an important part of that story.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('First Dunkin'' Donuts', 'first-dunkin-donuts', 'weird-history', 42.2529, -70.99293, 'Quincy', 'MA', 'The first Dunkin'' Donuts still operates at the site where William Rosenberg renamed his earlier Open Kettle shop in 1950. The modern store includes retro decor and displays recalling the chain''s beginnings.', 'open', null, 'https://www.atlasobscura.com/places/first-dunkin-donuts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('First Flight in America Marker', 'first-flight-in-america-marker', 'weird-history', 39.8411, -75.0913, 'Deptford Township', 'NJ', 'A public marker at Deptford Landing commemorates Jean-Pierre Blanchard''s 1793 balloon flight from Philadelphia to New Jersey, generally recognized as America''s first successful manned balloon flight. The original landing-site memorial behind the shopping center has become fenced and neglected, making the public marker the practical OddWay stop.', 'open', null, 'https://www.roadsideamerica.com/tip/39010', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('First Washington Monument', 'first-washington-monument', 'weird-history', 39.50047, -77.62315, 'Middletown', 'MD', 'Boonsboro residents climbed South Mountain on July 4, 1827 and built a rough stone tower honoring George Washington, making it the first completed monument to Washington in the country. The rebuilt tower stands inside Washington Monument State Park and requires a short uphill walk from the parking area.', 'limited', null, 'https://www.atlasobscura.com/places/first-washington-monument', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Florence Indian Mound Museum', 'florence-indian-mound-museum', 'weird-history', 34.7905, -87.67048, 'Florence', 'AL', 'A large prehistoric mound rises beside the museum, which interprets Native American cultures of the Tennessee Valley through artifacts and archaeology. The surviving earthwork gives visitors a direct physical connection to the region’s pre-European history.', 'limited', null, 'https://www.florencealmuseums.com/visit', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Floyd Collins Grave', 'floyd-collins-grave', 'weird-history', 37.19778, -86.07306, 'Mammoth Cave', 'KY', 'Cave explorer Floyd Collins became the center of a national media spectacle after becoming trapped in Sand Cave in 1925 and dying before rescuers could reach him. His remains had an equally strange afterlife, including years displayed in a glass-topped coffin and the theft of his body, before his eventual reburial at Mammoth Cave Baptist Church Cemetery.', 'open', null, 'https://www.roadsideamerica.com/story/11536', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fontainebleau Sugar Mill Ruins', 'fontainebleau-sugar-mill-ruins', 'weird-history', 30.3376, -90.0381, 'Mandeville', 'LA', 'Brick ruins from Bernard de Marigny''s early nineteenth-century sugar operation survive inside Fontainebleau State Park. The industrial remains sit incongruously among the park''s oak and lakeshore landscape.', 'open', null, 'https://www.lastateparks.com/parks-preserves/fontainebleau-state-park', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Foothills Parkway — The Missing Link', 'foothills-parkway-the-missing-link', 'weird-history', 35.68944, -83.8875, 'Townsend', 'TN', 'A long-unfinished section of the Foothills Parkway became known as the Missing Link because rugged terrain and engineering challenges delayed completion for decades. The finished roadway now lets travelers drive through a piece of National Park Service infrastructure history.', 'open', null, 'https://www.nps.gov/grsm/planyourvisit/foothillsparkway.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ford''s Folly', 'fords-folly', 'weird-history', 42.35418, -71.46019, 'Sudbury', 'MA', 'Automobile magnate Henry Ford attempted to build a dam near the Wayside Inn, only for the expensive project to fail at holding water as intended. The surviving stonework is a monument to an unusually literal piece of engineering folly.', 'open', null, 'https://www.atlasobscura.com/places/fords-folly', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Forest Hills Cemetery Miniature Village', 'forest-hills-cemetery-miniature-village', 'weird-history', 42.29487, -71.10566, 'Boston', 'MA', 'Hidden among the rocks and trees of Forest Hills Cemetery is a group of tiny stone buildings representing occupations such as architect, grocer, musician and poet. The miniature village is easy to miss inside the enormous Victorian cemetery and feels more like woodland folk art than a graveyard feature.', 'open', null, 'https://www.atlasobscura.com/places/forest-hills-cemetery', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.foresthillscemetery.com/', null, null, null, 'America/New_York'),
  ('Forest Home Cemetery', 'forest-home-cemetery', 'weird-history', 43.00301, -87.94459, 'Milwaukee', 'WI', 'Forest Home is one of Milwaukee''s great historic cemeteries, filled with elaborate monuments and the graves of major figures from the city''s brewing, industrial and political history. Local ghost stories have attached themselves to the landscape, but its stronger OddWay value is the dense collection of unusual monuments and Milwaukee history.', 'limited', null, 'https://foresthomecemetery.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://foresthomecemetery.com/', null, null, null, 'America/Chicago'),
  ('Forks of Cypress Ruins', 'forks-of-cypress-ruins', 'weird-history', 34.845, -87.72556, 'Florence', 'AL', 'Only the massive brick columns and archaeological remains survive from the Forks of Cypress plantation house after a 1966 fire. The property is not a normal walk-in attraction; OddWay should treat it as a view-only historic ruin and never direct users through private barriers.', 'roadside', null, 'https://encyclopediaofalabama.org/article/forks-of-cypress/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Forks of the Road Slave Market Site', 'forks-of-the-road-slave-market-site', 'weird-history', 31.55557, -91.38388, 'Natchez', 'MS', 'The preserved and interpreted location of one of the largest domestic slave markets in the antebellum South. The site is part of Natchez National Historical Park and should be presented directly as a place of enslavement and forced sale, not softened into generic antebellum tourism.', 'open', null, 'https://www.nps.gov/natc/learn/historyculture/slave-market-at-the-forks-of-the-road.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Former Ladd School Site', 'former-ladd-school-site', 'weird-history', 41.55222, -71.5431, 'Exeter', 'RI', 'The Joseph Ladd School was a state institution for people with intellectual and developmental disabilities and became notorious for overcrowding, abuse, segregation and Rhode Island''s eugenics-era policies. Most of the campus was demolished after the institution closed, and later ghost stories attached themselves to the abandoned buildings. OddWay should treat this primarily as institutional dark history; remaining structures are not an invitation to trespass.', 'roadside', null, 'https://www.theladdschool.com/history/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Adams Underground Tunnels', 'fort-adams-underground-tunnels', 'weird-history', 41.47847, -71.33818, 'Newport', 'RI', 'Fort Adams contains an extensive network of listening tunnels built beneath one of America''s largest coastal fortifications. Guided tours descend into the passageways and explain how soldiers used them to detect enemy attempts to tunnel beneath the walls. Tunnel access follows the fort''s operating season and tour schedule.', 'limited', null, 'https://fortadams.org/visit-fort-adams/', '2026-09-09T04:49:27.913704+00:00', null, 'https://fortadams.org/', null, null, null, 'America/New_York'),
  ('Fort Armistead', 'fort-armistead', 'weird-history', 39.20929, -76.53368, 'Baltimore', 'MD', 'Built around the turn of the 20th century as part of Baltimore''s coastal-defense system, Fort Armistead later became an abandoned military battery inside a public park. The concrete emplacements are heavily weathered and graffitied; stay in legitimate public areas and do not enter unsafe tunnels, sealed spaces or restricted sections.', 'limited', null, 'https://www.atlasobscura.com/places/fort-armistead', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Barrancas', 'fort-barrancas', 'weird-history', 30.34748, -87.29761, 'Pensacola', 'FL', 'Hilltop fortification incorporating Spanish, British, and American military layers.', 'open', null, 'https://www.nps.gov/guis/learn/historyculture/fort-barrancas.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Caroline National Memorial', 'fort-caroline-national-memorial', 'weird-history', 30.38655, -81.49854, 'Jacksonville', 'FL', 'Memorial to the doomed 1564 French colonial settlement on the St. Johns River.', 'open', null, 'https://www.nps.gov/timu/learn/historyculture/fort-caroline.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Clinch State Park', 'fort-clinch-state-park', 'weird-history', 30.70067, -81.4578, 'Fernandina Beach', 'FL', 'Large 19th-century brick fort with intact rooms, tunnels, and living-history interpretation.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/fort-clinch-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort de Chartres State Historic Site', 'fort-de-chartres-state-historic-site', 'weird-history', 38.08444, -90.15778, 'Prairie du Rocher', 'IL', 'Reconstructed stone walls and surviving powder magazine mark one of the most important French colonial military sites in the Illinois Country.', 'open', null, 'https://dnrhistoric.illinois.gov/experience/sites/southwest/fort-de-chartres.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort De Soto Batteries', 'fort-de-soto-batteries', 'weird-history', 27.61596, -82.73643, 'Tierra Verde', 'FL', 'Concrete coastal batteries and military ruins within Fort De Soto Park.', 'limited', null, 'https://pinellas.gov/parks/fort-de-soto-park/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort De Soto Park', 'fort-de-soto-park', 'weird-history', 27.61583, -82.73689, 'Tierra Verde', 'FL', 'Coastal fort ruins with batteries, military relics, and eerie empty casemates.', 'limited', null, 'https://pinellas.gov/parks/fort-de-soto-park/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Gaines', 'fort-gaines', 'weird-history', 30.24881, -88.075, 'Dauphin Island', 'AL', 'Fort Gaines guarded Mobile Bay and played a major role in the 1864 Battle of Mobile Bay. Visitors can explore brick passages, gun positions, tunnels and preserved fort spaces at the eastern tip of Dauphin Island.', 'open', null, 'https://www.townofdauphinisland.org/fort-gaines', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Gorges', 'fort-gorges', 'weird-history', 43.66312, -70.22164, 'Portland', 'ME', 'This granite Civil War-era fort occupies its own island in Portland Harbor and resembles a smaller coastal cousin of Fort Sumter. There is no road connection or regular public ferry, so visiting requires appropriate boat access and safe conditions.', 'limited', null, 'https://www.atlasobscura.com/places/fort-gorges', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Independence', 'fort-independence', 'weird-history', 42.33799, -71.01095, 'Boston', 'MA', 'Five-pointed Fort Independence dominates Castle Island at the edge of Boston Harbor. The present granite fort dates largely to the nineteenth century, but military defenses have occupied the site since the 1600s. The surrounding park is open broadly; interior fort access depends on seasonal tours and events.', 'limited', null, 'https://www.atlasobscura.com/places/fort-independence', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Jefferson', 'fort-jefferson', 'weird-history', 24.62852, -82.87321, 'Key West', 'FL', 'Enormous remote brick fortress on Garden Key in Dry Tortugas National Park.', 'open', null, 'https://www.nps.gov/drto/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Jesup State Historic Site', 'fort-jesup-state-historic-site', 'weird-history', 31.5274, -93.4024, 'Many', 'LA', 'Fort Jesup was established by Zachary Taylor near the old borderlands between the United States and Spanish Texas. Current state schedules can place the site on appointment-only access, so call before making a dedicated detour.', 'limited', null, 'https://www.lastateparks.com/historic-sites/fort-jesup-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Kaskaskia State Historic Site', 'fort-kaskaskia-state-historic-site', 'weird-history', 37.97059, -89.90927, 'Ellis Grove', 'IL', 'Earthwork remains of an 18th-century fort overlook the Mississippi and the vanished original townsite of Kaskaskia below.', 'open', null, 'https://dnr.illinois.gov/parks/park.fortkaskaskia.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Knox State Historic Site', 'fort-knox-state-historic-site', 'weird-history', 44.56615, -68.80243, 'Prospect', 'ME', 'This massive granite fortification was built in the 1800s to guard the Penobscot River and contains tunnels, stairways, cannon positions, and dark interior passages. The preserved fort is open to visitors seasonally, with some access varying by time of year.', 'limited', null, 'https://www.maine.gov/fortknox', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Lincoln Cemetery', 'fort-lincoln-cemetery', 'weird-history', 38.93048, -76.95672, 'Brentwood', 'MD', 'This large active cemetery occupies land with layers of history that include Civil War-era Fort Lincoln earthworks, an old spring house, monuments and a sprawling mausoleum complex. Visitors can see the historic features during cemetery hours but should stay on cemetery roads and treat active burial areas respectfully.', 'open', null, 'https://www.atlasobscura.com/places/fort-lincoln-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Mansfield Ruins', 'fort-mansfield-ruins', 'weird-history', 41.30639, -71.88361, 'Westerly', 'RI', 'Concrete remnants of Fort Mansfield survive in the dunes of Napatree Point, reached by a long coastal walk from Watch Hill. The Endicott-era fort operated in the early twentieth century before flaws in its defensive design helped make it obsolete. The surrounding conservation area is public, but seasonal wildlife restrictions and fragile dunes must be respected.', 'limited', null, 'https://fergusonmuseum.org/2020/06/fort-mansfield-napatree-point/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Matanzas National Monument', 'fort-matanzas-national-monument', 'weird-history', 29.71479, -81.23824, 'St. Augustine', 'FL', '1742 coquina watchtower reached by boat across the Matanzas River.', 'open', null, 'https://www.nps.gov/foma/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Menendez at Old Florida Museum', 'fort-menendez-at-old-florida-museum', 'weird-history', 29.9155, -81.32103, 'St. Augustine', 'FL', 'Living-history site interpreting Timucua, Spanish-colonial, and pioneer Florida.', 'limited', null, 'https://oldfloridamuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Miles Bunkers — Battery 118', 'fort-miles-bunkers-battery-118', 'weird-history', 38.77057, -75.08614, 'Lewes', 'DE', 'Concrete coastal-defense bunkers hide beneath the dunes of Cape Henlopen, remnants of the wartime Fort Miles complex built to protect Delaware Bay. Battery 118 is one of the most substantial surviving structures and anchors the fort''s museum and tour area.', 'limited', null, 'https://www.atlasobscura.com/places/bunkers-of-cape-henlopen-state-park', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.destateparks.com/fortmiles', null, null, null, 'America/New_York'),
  ('Fort Mims Historic Site', 'fort-mims-historic-site', 'weird-history', 31.1805, -87.83797, 'Tensaw', 'AL', 'The site preserves the location of the 1813 Fort Mims attack during the Creek War, where hundreds of people were killed or captured. Reconstructed palisade elements, markers and memorials interpret a violent and complex event involving Creek factions, settlers, enslaved people and militia.', 'limited', null, 'https://fortmims.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Morgan State Historic Site', 'fort-morgan-state-historic-site', 'weird-history', 30.22806, -88.02306, 'Gulf Shores', 'AL', 'Fort Morgan’s massive masonry walls guarded the entrance to Mobile Bay and figured prominently in the Battle of Mobile Bay. The preserved fort includes tunnels, batteries and later military additions spanning generations of coastal defense.', 'open', null, 'https://ahc.alabama.gov/properties/fortmorgan/fortmorgan.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Mose Historic State Park', 'fort-mose-historic-state-park', 'weird-history', 29.94783, -81.32483, 'St. Augustine', 'FL', 'Site of the first legally sanctioned free African settlement in what became the United States.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/fort-mose-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Mott', 'fort-mott', 'weird-history', 39.60379, -75.55232, 'Pennsville Township', 'NJ', 'Massive concrete gun batteries remain along the Delaware River from a late nineteenth-century coastal-defense system built to protect approaches to Philadelphia. Visitors can walk among the fortifications and see the disappearing-gun positions from public park grounds.', 'open', null, 'https://dep.nj.gov/parksandforests/state-park/fort-mott-state-park/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Payne Depot Museum', 'fort-payne-depot-museum', 'weird-history', 34.44429, -85.71846, 'Fort Payne', 'AL', 'The sandstone depot built for the Alabama Great Southern Railroad now houses local artifacts and railroad history. Its heavy stone architecture and preserved rail setting make it one of Fort Payne’s most distinctive historic structures.', 'limited', null, 'https://fortpayne.org/community/museums/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Payne Hosiery Museum', 'fort-payne-hosiery-museum', 'weird-history', 34.44588, -85.71984, 'Fort Payne', 'AL', 'Fort Payne once promoted itself as the Sock Capital of the World, and this small museum preserves machinery, products and stories from the city’s hosiery industry. Tours operate on a limited schedule, so visitors should check current hours before routing there.', 'limited', null, 'https://fortpayne.org/community/museums/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Pickens', 'fort-pickens', 'weird-history', 30.3266, -87.29155, 'Pensacola Beach', 'FL', 'Huge brick Gulf fortress where Apache leader Geronimo was imprisoned.', 'open', null, 'https://www.nps.gov/guis/learn/historyculture/fort-pickens.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Pillow State Historic Park', 'fort-pillow-state-historic-park', 'weird-history', 35.6403, -89.8365, 'Henning', 'TN', 'Fort Pillow preserves earthworks from the Civil War site where Confederate forces under Nathan Bedford Forrest captured the fort in 1864 and killed large numbers of Black Union troops after overrunning the position. The park interprets the battlefield and massacre through trails, exhibits and preserved terrain.', 'open', null, 'https://www.tnstateparks.com/parks/fort-pillow', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Raleigh National Historic Site — Lost Colony', 'fort-raleigh-national-historic-site-lost-colony', 'weird-history', 35.93694, -75.70896, 'Manteo', 'NC', 'Roanoke Island preserves the landscape associated with England’s first attempted permanent colony in North America. When a supply expedition returned in 1590, the settlers had vanished, leaving “CROATOAN” carved into a post. Their ultimate fate remains one of America’s best-known historical mysteries.', 'open', null, 'https://www.nps.gov/fora/index.htm', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Roberdeau', 'fort-roberdeau', 'weird-history', 40.58272, -78.27379, 'Tyrone Township', 'PA', 'Fort Roberdeau reconstructs a Revolutionary War-era lead-mining fort built in 1778 to protect local mining operations. The palisade, cabins and grounds can be explored during its seasonal tour season, while the exterior grounds remain visible outside normal interior-tour hours.', 'limited', null, 'https://fortroberdeau.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Standish', 'fort-standish', 'weird-history', 42.32981, -70.92765, 'Hull', 'MA', 'Overgrown coastal-defense ruins sprawl across Peddocks Island, including concrete batteries and abandoned military structures from the harbor''s defensive network. The island is reached seasonally; closed structures and unsafe interiors should not be entered.', 'limited', null, 'https://www.atlasobscura.com/places/fort-standish', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Stark', 'fort-stark', 'weird-history', 43.05759, -70.71302, 'New Castle', 'NH', 'Concrete batteries and defensive structures overlook Portsmouth Harbor at this former coastal fort. The site combines abandoned-looking military architecture with a dramatic oceanfront setting, while interpretive material explains its role in the harbor defense system. Grounds and interior access can vary by season and restoration status.', 'limited', null, 'https://www.nhstateparks.org/find-parks-trails/fort-stark-state-historic-site', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Taber Park', 'fort-taber-park', 'weird-history', 41.59498, -70.90247, 'New Bedford', 'MA', 'Multiple generations of coastal defenses occupy this New Bedford peninsula, including granite Fort Rodman, concrete batteries and underground-looking military structures. Much of the park can be explored from public paths, while individual fort interiors and restricted areas open only under current park rules or special programs.', 'open', null, 'https://www.atlasobscura.com/places/fort-taber-park-new-bedford', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Toulouse–Fort Jackson Park', 'fort-toulouse-fort-jackson-park', 'weird-history', 32.50663, -86.25158, 'Wetumpka', 'AL', 'At the meeting of the Coosa and Tallapoosa rivers, the park preserves reconstructed and archaeological remains from a French colonial fort, Fort Jackson and earlier Indigenous occupation. Trails connect forts, a mound and multiple layers of contested history.', 'open', null, 'https://ahc.alabama.gov/properties/fttoulouse/fttoulouse.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Wetherill', 'fort-wetherill', 'weird-history', 41.4801, -71.3618, 'Jamestown', 'RI', 'Concrete gun batteries from the former coastal-defense Fort Wetherill remain embedded in cliffs above Narragansett Bay. Many surfaces are covered with layers of graffiti, creating a striking collision of military ruins and constantly changing street art. The surrounding state park is public, but visitors should obey closures and never enter unsafe or restricted structures.', 'open', null, 'https://www.atlasobscura.com/places/fort-wetherill', '2026-09-09T04:49:27.913704+00:00', null, 'https://riparks.ri.gov/parks/fort-wetherill-state-park', null, null, null, 'America/New_York'),
  ('Fort William Henry at Colonial Pemaquid', 'fort-william-henry-at-colonial-pemaquid', 'weird-history', 43.87724, -69.52334, 'Bristol', 'ME', 'A reconstructed stone tower rises over the archaeological remains of Colonial Pemaquid, where multiple forts and settlements were repeatedly built, attacked, destroyed, and rebuilt along Maine’s contested early frontier. The current structure recreates part of the 1690s Fort William Henry and overlooks the harbor and excavation grounds.', 'limited', null, 'https://www.maine.gov/dacf/parks/contact.shtml', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Zachary Taylor Historic State Park', 'fort-zachary-taylor-historic-state-park', 'weird-history', 24.54742, -81.81071, 'Key West', 'FL', 'Seaside Civil War fort with one of the largest collections of Civil War-era seacoast cannon.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/fort-zachary-taylor-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Forts Ferry', 'forts-ferry', 'weird-history', 42.787988, -73.793012, 'Clifton Park', 'NY', 'One of the earliest European settlement sites in what is now Clifton Park, where Nicholas Fort ran a rope ferry across the Mohawk from 1728. It sits inside the public Vischer Ferry Nature and Historic Preserve, with a mile-and-a-half historic trail to the ferry site, the Fort homestead foundation and interpretive panels.', 'open', null, 'https://cliftonparkny.gov/document-center/open-space/3063-vischer-ferry-nature-and-historic-preserve-booklet-2002/file', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/New_York'),
  ('Forts Randolph & Buhlow State Historic Site', 'forts-randolph-buhlow-state-historic-site', 'weird-history', 31.32419, -92.44919, 'Pineville', 'LA', 'Earthworks and remains from two Civil War-era forts overlook the Red River near Alexandria. A visitor center and elevated walkways make the military landscape accessible without climbing fragile fortifications.', 'open', null, 'https://www.lastateparks.com/historic-sites/forts-randolph-buhlow-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Foster Mounds', 'foster-mounds', 'weird-history', 31.60015, -91.3285, 'Natchez', 'MS', 'Two prehistoric mounds flank a former village/plaza area near Natchez, with a historic house later constructed on one mound. The property is private, so this stop is exterior/view-only from the public route.', 'roadside', null, 'https://trails.mdah.ms.gov/foster', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Four Holes Swamp Bridge Historic Site', 'four-holes-swamp-bridge-historic-site', 'weird-history', 33.14267, -80.35209, 'Dorchester', 'SC', 'A tiny park squeezed into the junction of U.S. 78 and 178 marks a surprisingly layered piece of South Carolina history. A causeway crossed Four Holes Swamp here by 1753, a bridge followed in the 1770s, and Patriot and Loyalist forces fought around the crossing during the Revolutionary War. Just beyond the memorial area is a small hilltop cemetery containing several Confederate veterans'' graves.', 'open', null, 'https://www.scpictureproject.org/dorchester-county/four-holes-swamp-bridge.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frank L. White''s Cream of Wheat Gravestone', 'frank-l-whites-cream-of-wheat-gravestone', 'weird-history', 42.45777, -84.42944, 'Leslie', 'MI', 'Frank L. White is widely associated with the smiling chef image once used for decades on Cream of Wheat packaging. His grave in Woodlawn Cemetery was unmarked until a later memorial was installed featuring the familiar chef image, creating an unusual connection between advertising history and a quiet Michigan cemetery.', 'limited', null, 'https://www.roadsideamerica.com/tip/9567', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Frank Sinatra Birthplace Star', 'frank-sinatra-birthplace-star', 'weird-history', 40.74344, -74.0386, 'Hoboken', 'NJ', 'A sidewalk star marks 415 Monroe Street, where Frank Sinatra was born in 1915. The original house no longer survives, so the marker serves as the physical stop connecting Hoboken with the singer''s birthplace.', 'open', null, 'https://mapcarta.com/N5468067617', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Franklin Ghost Town', 'franklin-ghost-town', 'weird-history', 47.297998, -121.95874, 'Black Diamond', 'WA', 'A coal settlement from the 1880s, and the scene of an 1894 mine fire that killed thirty-seven men before operations largely ended in 1919. A 2.5-mile round trip now passes a coal cart, a sealed shaft, the powerhouse foundation and the cemetery. Trail parking is on a private field and costs five dollars a person.', 'limited', null, 'https://www.wta.org/go-hiking/hikes/franklin-ghost-town', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Franklin Park Overlook Shelter Ruins', 'franklin-park-overlook-shelter-ruins', 'weird-history', 42.308, -71.09716, 'Boston', 'MA', 'Stone walls and arches survive from an Olmsted-era field house in Franklin Park. The shelter burned in the twentieth century and later became a setting for outdoor concerts before settling into its current life as a picturesque public ruin along park trails.', 'open', null, 'https://www.atlasobscura.com/places/franklin-parks-overlook-shelter-ruins', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fred''s Lounge', 'freds-lounge', 'weird-history', 30.63095, -92.41947, 'Mamou', 'LA', 'Fred''s is a tiny bar famous for live Cajun music and Saturday-morning broadcasts that turned it into a pilgrimage point for traditional music fans. Its operating window is narrow, so verify the current Saturday schedule before detouring.', 'limited', null, 'https://www.explorelouisiana.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Freedlyville Quarry', 'freedlyville-quarry', 'weird-history', 43.28726, -73.01682, 'Dorset', 'VT', 'An abandoned marble quarry cuts deep into the mountain near Dorset, leaving underground workings where winter ice formations can develop. The quarry is not a maintained tourist cave, so access conditions, land permissions and underground hazards should be checked before any visit.', 'limited', null, 'https://www.atlasobscura.com/places/freedlyville-quarry', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Freedom Riders Greyhound Bus Burning Site', 'freedom-riders-greyhound-bus-burning-site', 'weird-history', 33.63527, -85.90643, 'Anniston', 'AL', 'A national monument site marks the location where a mob attacked and burned a Greyhound bus carrying Freedom Riders on May 14, 1961. Outdoor interpretation preserves the exact roadside landscape connected to the attack.', 'open', null, 'https://www.nps.gov/frri/index.htm', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Freedom Riders National Monument — Greyhound Bus Depot', 'freedom-riders-national-monument-greyhound-bus-depot', 'weird-history', 33.65803, -85.8311, 'Anniston', 'AL', 'The former downtown Greyhound station is part of Freedom Riders National Monument and preserves another key location in the 1961 attacks. Exterior interpretation and scheduled programming connect the depot to the nearby bus-burning site.', 'limited', null, 'https://www.nps.gov/frri/index.htm', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Freedom Rides Museum', 'freedom-rides-museum', 'weird-history', 32.37472, -86.30917, 'Montgomery', 'AL', 'Montgomery’s former Greyhound bus station preserves the site where Freedom Riders arrived in May 1961 and were attacked by a mob. Exhibits inside the restored station document the riders and the interstate travel campaign.', 'open', null, 'https://ahc.alabama.gov/properties/freedomrides/freedomrides.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Friendship Oak', 'friendship-oak', 'weird-history', 30.3519, -89.13608, 'Long Beach', 'MS', 'A massive live oak on the University of Southern Mississippi Gulf Park campus estimated to be centuries old and wrapped in local traditions about friendship and good fortune. Its enormous low limbs make it feel almost architectural rather than simply botanical.', 'open', null, 'https://www.usm.edu/gulf-park/friendship-oak.php', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Frozen GI — Rutland County Vietnam Veterans Memorial', 'frozen-gi-rutland-county-vietnam-veterans-memorial', 'weird-history', 43.60524, -72.97209, 'Rutland', 'VT', 'A helmeted soldier appears half-embedded in a block of marble in this unusual Vietnam veterans memorial. The sculpture was begun by veteran John Reno and later completed by another veteran after Reno''s death, producing a memorial that looks almost like a figure frozen inside stone.', 'open', null, 'https://www.roadsideamerica.com/story/11616', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gamble Place Historic District', 'gamble-place-historic-district', 'weird-history', 29.06338, -81.0389, 'Port Orange', 'FL', 'Rustic retreat built by the Gamble family, including the distinctive Snow White Cottage.', 'limited', null, 'https://www.volusia.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gardner Streetcar Diner', 'gardner-streetcar-diner', 'weird-history', 41.1882, -88.30484, 'Gardner', 'IL', 'A restored streetcar once used as a roadside diner sits next to Gardner''s old jail and historic Route 66 alignment.', 'open', null, 'https://illinoisroute66.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gardner Two-Cell Jail', 'gardner-two-cell-jail', 'weird-history', 41.1884, -88.30471, 'Gardner', 'IL', 'A tiny 1906 two-cell jail stands beside Route 66 as a remarkably intact piece of small-town law-enforcement history.', 'open', null, 'https://illinoisroute66.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Garnet Ghost Town', 'garnet-ghost-town', 'weird-history', 46.825141, -113.339388, 'Clinton', 'MT', 'A gold camp that reached around a thousand residents in the 1890s and dwindled as the gold ran out. The BLM keeps it as one of Montana''s best-preserved ghost towns, with historic buildings and a seasonal visitor centre. Ten dollars for visitors sixteen and over; the last roads are unpaved and winter access is over snow only.', 'limited', null, 'https://www.blm.gov/visit/garnet-ghost-town', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Denver'),
  ('Gateway to the Blues Museum', 'gateway-to-the-blues-museum', 'weird-history', 34.84066, -90.27307, 'Tunica Resorts', 'MS', 'A blues museum and visitor center inside a restored railroad depot along Highway 61. It works especially well as a northern gateway stop before travelers enter the Delta''s denser cluster of juke joints, markers and musician sites.', 'open', null, 'https://tunicatravel.com/things-to-do/the-blues/gateway/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gay City State Park Ruins', 'gay-city-state-park-ruins', 'weird-history', 41.72251, -72.43621, 'Hebron', 'CT', 'The forest hides stone foundations, cellar holes, a small cemetery and mill ruins left by an abandoned settlement that became known as Gay City. Stories of unexplained deaths and hauntings grew around the vanished community, but the physical ruins themselves are real and can be reached from public park trails.', 'open', null, 'https://www.atlasobscura.com/places/gay-city-state-park', '2026-09-08T18:39:47.144889+00:00', null, 'https://ctparks.com/parks/gay-city-state-park', null, null, null, 'America/New_York'),
  ('George Coryell''s Grave — Washington''s Pallbearer', 'george-coryells-grave-washingtons-pallbearer', 'weird-history', 40.36665, -74.94515, 'Lambertville', 'NJ', 'Revolutionary War officer George Coryell, later one of George Washington''s pallbearers, is buried beside the First Presbyterian Church in Lambertville. A historical marker identifies the small graveyard, which also contains Samuel Holcombe, remembered locally as one of Washington''s spies.', 'open', null, 'https://www.hmdb.org/m.asp?m=16861', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('George Washington Carver Interpretive Museum', 'george-washington-carver-interpretive-museum', 'weird-history', 31.22722, -85.39282, 'Dothan', 'AL', 'Located in downtown Dothan, this museum focuses on George Washington Carver and broader African American contributions to science, invention and culture. Exhibits connect Carver’s agricultural work with stories of other innovators.', 'open', null, 'https://www.gwcarvermuseum.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('George Washington Carver Museum', 'george-washington-carver-museum', 'weird-history', 32.4297, -85.7066, 'Tuskegee', 'AL', 'Located on the Tuskegee University campus, the National Park Service museum explores George Washington Carver’s scientific work, teaching and art. It preserves laboratory-related materials and exhibits within the institution where he spent much of his career.', 'open', null, 'https://www.nps.gov/tuin/planyourvisit/gw-carver-museum.htm', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('George Washington Statue with a Broken Cane', 'george-washington-statue-with-a-broken-cane', 'weird-history', 34.00032, -81.03313, 'Columbia', 'SC', 'The George Washington statue at the South Carolina State House still bears damage from Union occupation of Columbia during the Civil War. Soldiers broke off part of Washington’s walking cane, and the damaged monument was deliberately left unrepaired as part of its history.', 'open', null, 'https://www.scstatehouse.gov/studentpage/Explore/grounds.shtml', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('George''s Coney Island', 'georges-coney-island', 'weird-history', 42.2576, -71.804, 'Worcester', 'MA', 'A century-old hot-dog institution preserves a vintage Art Deco interior and the local tradition of Coney Island-style dogs. The neon, stools and old signage make the restaurant feel like a still-functioning piece of roadside food history.', 'open', null, 'https://www.atlasobscura.com/places/georges-coney-island', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Georges Island and Fort Warren', 'georges-island-and-fort-warren', 'weird-history', 42.32032, -70.92751, 'Boston', 'MA', 'Fort Warren occupies much of Georges Island in Boston Harbor, with granite corridors, casemates and defensive works open to explore during the ferry season. The fort is also tied to the legend of the Lady in Black, one of Boston Harbor''s best-known ghost stories.', 'limited', null, 'https://www.bostonharborislands.org/georges-island/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Georges Valentine Underwater Archaeological Preserve', 'georges-valentine-underwater-archaeological-preserve', 'weird-history', 27.19883, -80.16312, 'Stuart', 'FL', 'Iron-hulled vessel wrecked in 1904 just offshore from the historic House of Refuge.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/georges-valentine/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Germantown Colony Museum', 'germantown-colony-museum', 'weird-history', 32.70006, -93.23133, 'Minden', 'LA', 'The museum preserves surviving buildings from a nineteenth-century communal religious settlement founded by German immigrants. Current state museum hours are limited to specific days, so verify before making the rural detour.', 'limited', null, 'https://www.sos.la.gov/HistoricalResources/VisitMuseums/Pages/GermantownColonyMuseum.aspx', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Getty Tomb', 'getty-tomb', 'weird-history', 41.96111, -87.66111, 'Chicago', 'IL', 'Designed by Louis Sullivan, this striking mausoleum uses intricate geometric ornament unlike almost anything else in Chicago''s cemetery landscape.', 'limited', null, 'https://www.gracelandcemetery.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gettysburg Gun — Rhode Island State House', 'gettysburg-gun-rhode-island-state-house', 'weird-history', 41.83083, -71.415, 'Providence', 'RI', 'Inside the Rhode Island State House is a bronze Napoleon cannon disabled during the artillery barrage preceding Pickett''s Charge at Gettysburg. A Confederate projectile lodged in the muzzle, permanently freezing the weapon in the instant it was knocked out of battle. Visitors must follow current State House public-access and security procedures.', 'limited', null, 'https://en.wikipedia.org/wiki/Rhode_Island_State_House', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ghost Church at Polegreen', 'ghost-church-at-polegreen', 'weird-history', 37.6452, -77.32927, 'Mechanicsville', 'VA', 'Polegreen Church was destroyed by Confederate artillery in 1864 during the Civil War. In 2012, a stark white framework was erected on the footprint of the vanished meetinghouse, creating a skeletal "Ghost Church" that visitors can walk around during daylight hours.', 'open', null, 'https://www.roadsideamerica.com/tip/59428', '2026-09-08T04:17:48.352537+00:00', null, 'https://historicpolegreen.org/', null, null, null, 'America/New_York'),
  ('Ghost Town', 'ghost-town', 'weird-history', 36.011137, -114.945574, 'Henderson', 'NV', 'This Henderson entry appears to be tied to an old or temporary western ghost-town-style attraction rather than a currently documented permanent destination. I could not verify a public attraction operating here now, so the record should be removed or held unpublished until the exact coordinates and current operator are confirmed.', 'closed', null, 'https://www.openstreetmap.org/way/1377065863', null, null, null, null, 'way', 1377065863, 'America/Los_Angeles'),
  ('Ghost Town', 'ghost-town-2', 'weird-history', 40.958415, -83.671578, 'Eagle Township', 'OH', 'An OpenStreetMap-derived tourist-attraction record called Ghost Town exists in Eagle Township, but there is almost no current public information explaining what visitors would actually find there. It should not be routed as an active attraction until its ownership, access and purpose are independently verified.', 'closed', null, 'https://mapcarta.com/W421738252', null, null, null, null, 'way', 421738252, 'America/New_York'),
  ('Ghost Town of Clara', 'ghost-town-of-clara', 'weird-history', 34.09176, -98.69693, 'Burkburnett', 'TX', 'This is a Texas historical marker telling the story of Clara, a former German settlement near Burkburnett, rather than a preserved ghost town with buildings to explore. The marker is a roadside stop, although the Texas Historical Commission currently indicates that the physical marker is being replaced, so travelers may temporarily find no plaque on site.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, 'https://atlas.thc.texas.gov/Details/5485002180', null, 'node', 12453787783, 'America/Chicago'),
  ('Ghost Town of Cotton Gin', 'ghost-town-of-cotton-gin', 'weird-history', 31.68067, -96.35993, 'Teague', 'TX', 'Settled before 1848 around Dr J. S. Wills'' mule-powered cotton gin, growing to support churches, a school, a newspaper, stores and saloons. The businesses went when the railroad bypassed it in the 1870s. What stands now is a Texas historical marker explaining a settlement that is no longer there.', 'roadside', null, 'https://atlas.thc.state.tx.us/Details/5161009870', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ghost Town of White Hills', 'ghost-town-of-white-hills', 'weird-history', 35.700322, -114.474416, 'Dolan Springs', 'AZ', 'A short-lived silver boomtown of the 1890s that vanished when mining declined. Essentially nothing of the town remains, but historical markers at US 93 and White Hills Road explain the settlement and point toward the old district. Active and private mine areas should not be entered.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=31880', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Ghost Town Pahreah Old Cellar', 'ghost-town-pahreah-old-cellar', 'weird-history', 37.24808, -111.952794, 'Kanab', 'UT', 'A cellar remnant within the abandoned Pahreah townsite, settled by Mormon pioneers in 1865 and given up after repeated flooding along the Paria River. A five-mile dirt road reaches the wider site, where there are foundations, artefacts and a cemetery. One feature of a larger place rather than a separate stop.', 'limited', null, 'https://www.nps.gov/glca/planyourvisit/day-hikes.htm', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Denver'),
  ('Ghost Town Pahreah Old Chimney', 'ghost-town-pahreah-old-chimney', 'weird-history', 37.247594, -111.952313, 'Kanab', 'UT', 'Another surviving feature of the same Pahreah townsite, where settlement began in 1865 and recurring floods eventually drove everyone out. Same dirt-road approach as the rest of the site, and road and river conditions change quickly after rain.', 'limited', null, 'https://www.blm.gov/visit/paria-movie-set-day-use-site', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Denver'),
  ('Ghost Town Tours', 'ghost-town-tours', 'weird-history', 34.750699, -112.116606, 'Clarkdale', 'AZ', 'Ghost Town Tours offers guided walks through Jerome focused on the former mining town''s colorful history, old buildings, local legends and paranormal stories. Visitors should expect a scheduled tour rather than a self-guided attraction, so advance booking is the safest way to visit.', 'limited', null, 'https://ghosttowntours.org/', '2026-09-05T22:12:28.444612+00:00', null, 'https://ghosttowntours.org/', null, 'node', 9953774076, 'America/Phoenix'),
  ('Ghost Town Village', 'ghost-town-village', 'weird-history', 35.526815, -83.103619, 'Maggie Valley', 'NC', 'Ghost Town Village, better known as Ghost Town in the Sky, was a mountaintop Wild West amusement park overlooking Maggie Valley. The park has been closed for years and the property is not a normal public sightseeing stop, so it should be removed from active routing unless the site officially reopens.', 'closed', null, 'https://en.wikipedia.org/wiki/Ghost_Town_Village', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 1092172492, 'America/New_York'),
  ('Ghost Town Wild West Museum', 'ghost-town-wild-west-museum', 'weird-history', 38.840433, -104.860859, 'Colorado Springs', 'CO', 'Ghost Town Museum is an indoor Colorado Springs museum built around preserved Old West storefronts, rooms, wagons and artifacts rescued from the Pikes Peak region. Despite the name, it is a western-history museum rather than a paranormal attraction, with hands-on exhibits and seasonal gold panning.', 'open', null, 'https://www.ghosttownmuseum.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.ghosttownmuseum.com', null, 'way', 130923480, 'America/Denver'),
  ('Gilbert Ghost Town', 'gilbert-ghost-town', 'weird-history', 48.457381, -120.562214, 'Okanogan County', 'WA', 'A small mining camp in the North Creek drainage of Okanogan County during the late-nineteenth-century boom, reportedly about a dozen buildings at its peak. A cabin, partial ruins, foundations and mining traces remain deep in the Cascade backcountry near the Gilbert Trailhead. No staffed attraction.', 'limited', null, 'https://washingtonstate.fandom.com/wiki/Gilbert', null, null, null, null, null, null, 'America/Los_Angeles'),
  ('Glass Mounds', 'glass-mounds', 'weird-history', 32.22827, -90.92747, 'Utica', 'MS', 'A once four-mound Plaquemine-period complex unusually situated in the Mississippi River floodplain. Only portions survive; the site is private and MDAH specifically directs visitors to a designated viewing area.', 'roadside', null, 'https://trails.mdah.ms.gov/glass', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Goddard Mansion Ruins', 'goddard-mansion-ruins', 'weird-history', 43.62649, -70.21419, 'Cape Elizabeth', 'ME', 'The stone shell of an elaborate 19th-century mansion stands inside Fort Williams Park near Portland Head Light. After decades of abandonment and deterioration, only the atmospheric exterior walls remain and the interior is fenced off.', 'open', null, 'https://www.atlasobscura.com/places/goddard-mansion', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Goddard Rocket Launching Site', 'goddard-rocket-launching-site', 'weird-history', 42.21941, -71.81119, 'Auburn', 'MA', 'A modest rocket-shaped obelisk marks the field where Robert H. Goddard launched the world''s first successful liquid-fueled rocket on March 16, 1926. The flight lasted only a few seconds, but the experiment helped lay the groundwork for modern rocketry and spaceflight.', 'open', null, 'https://www.atlasobscura.com/places/goddard-rocket-launching-site', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gold King Mine Ghost Town', 'gold-king-mine-ghost-town', 'weird-history', 34.75655, -112.130827, 'Jerome', 'AZ', 'The camp began around 1890 north of Jerome, when miners looking for copper struck gold in a 1,270-foot shaft. The present attraction dates from 1982 and holds historic shafts, over a hundred vintage vehicles, mining equipment and a working sawmill. Admission charged, closed Tuesdays.', 'limited', null, 'https://goldkingmineghosttown.com/', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Golden Fleece Tavern Site', 'golden-fleece-tavern-site', 'weird-history', 39.15678, -75.52381, 'Dover', 'DE', 'Delaware delegates gathered at the Golden Fleece Tavern in 1787 around the time the state became the first to ratify the U.S. Constitution. The tavern itself is gone, but a surviving wall and marker preserve the unexpectedly ordinary setting of a major national event.', 'roadside', null, 'https://www.atlasobscura.com/places/golden-fleece-tavern', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Goldfield Ghost Town', 'goldfield-ghost-town', 'weird-history', 33.45733, -111.491847, 'Apache Junction', 'AZ', 'The original Goldfield boomed beside the Mammoth Mine in the 1890s and faded when the ore body disappointed. Bob and Lou Ann Schoose rebuilt the site from the 1980s as a commercial Old West attraction: shops, museum, mine tour, narrow-gauge train, gold panning and staged gunfights.', 'open', null, 'https://goldfieldghosttown.com/', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Goldsboro Nuclear Mishap Historical Marker', 'goldsboro-nuclear-mishap-historical-marker', 'weird-history', 35.54197, -77.87647, 'Eureka', 'NC', 'A state historical marker recalls the 1961 crash of a B-52 carrying two hydrogen bombs near Goldsboro. Neither weapon produced a nuclear explosion, but declassified information later showed how close one bomb came to completing parts of its arming sequence.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Goodsell Ridge Fossil Preserve', 'goodsell-ridge-fossil-preserve', 'weird-history', 44.85319, -73.33975, 'Isle La Motte', 'VT', 'Exposed limestone at this preserve contains remnants of the roughly 480-million-year-old Chazy fossil reef, one of the oldest known reef ecosystems. Trails and interpretive material let visitors literally walk across rock containing traces of an ancient tropical sea.', 'open', null, 'https://www.lclt.org/goodsell-and-fisk-quarry-preserves/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Goodwin', 'goodwin', 'weird-history', 34.355719, -112.380399, 'Mayer', 'AZ', 'Established in 1882 after the Nonsuch Mining Company bought the Goodwin Mine and built a mill and smelter, later serving as hotel, stage stop, store and supply centre. Almost nothing survives beyond sparse foundations and a sign on Senator Highway.', 'limited', null, 'https://www.arizonahighways.com/archive/issues/chapter/Doc.705.Chapter.6', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Goodyear Airdock', 'goodyear-airdock', 'weird-history', 41.03194, -81.47083, 'Akron', 'OH', 'Completed in 1929, the Goodyear Airdock was built to construct and house enormous lighter-than-air craft and was once one of the world''s largest buildings without interior supports. The industrial facility is not a public attraction, but the immense black hangar can be viewed from surrounding public roads without entering the secured property.', 'roadside', null, 'https://www.atlasobscura.com/places/goodyear-airdock', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Goshen Police Booth', 'goshen-police-booth', 'weird-history', 41.58655, -85.83472, 'Goshen', 'IN', 'Built in 1939, this small fortified police booth was designed as a bullet-resistant downtown lookout during an era when Midwestern communities were still conscious of automobile-era gangsters. The tiny structure survives as a public reminder of how seriously towns once planned for armed criminals traveling the Lincoln Highway.', 'open', null, 'https://www.roadsideamerica.com/tip/3819', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Gothic Hanging Jail — Beauregard Parish Jail', 'gothic-hanging-jail-beauregard-parish-jail', 'weird-history', 30.84625, -93.28821, 'DeRidder', 'LA', 'The 1914 Beauregard Parish Jail is a dramatic Gothic structure associated with the 1928 execution of two convicted killers, giving rise to its ''Hanging Jail'' nickname. Regular interior access is not guaranteed, so default to lawful exterior viewing unless an authorized tour is offered.', 'roadside', null, 'https://www.cityofderidder.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Graball Landing — Emmett Till National Monument Site', 'graball-landing-emmett-till-national-monument-site', 'weird-history', 33.83178, -90.27023, 'Glendora', 'MS', 'A Mississippi River landing area associated with the recovery of Emmett Till''s body in 1955 and now interpreted as part of the national monument. The road can be rural and conditions may vary, so travelers should remain in designated public areas and avoid adjacent private land.', 'roadside', null, 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grace Episcopal Church Cemetery', 'grace-episcopal-church-cemetery', 'weird-history', 30.7761, -91.3869, 'St. Francisville', 'LA', 'The cemetery and church grounds are tied to the Civil War episode remembered locally as ''The Day the War Stopped,'' when opposing forces paused fighting for the burial of a Union naval officer. Visit quietly during lawful church and cemetery access.', 'limited', null, 'https://www.gracechurchwfp.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grace Mounds', 'grace-mounds', 'weird-history', 32.98928, -90.96992, 'Grace', 'MS', 'Two major mounds survive from a five-mound complex near Steele Bayou, including a roughly 40-foot mound visible from nearby roads. The site produced the carved Issaquena Disk used as the Mississippi Mound Trail symbol; the property itself is private.', 'roadside', null, 'https://trails.mdah.ms.gov/grace', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('GRAMMY Museum Mississippi', 'grammy-museum-mississippi', 'weird-history', 33.74825, -90.73109, 'Cleveland', 'MS', 'A music museum connecting Mississippi''s outsized influence on American music with GRAMMY history, recording technology and interactive exhibits. Its focus spans blues, gospel, rock, country and other genres rather than treating the Delta as a single-style story.', 'open', null, 'https://www.grammymuseumms.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grand Gulf Military State Park and Ghost Town', 'grand-gulf-military-state-park-and-ghost-town', 'weird-history', 32.04439, -91.0513, 'Port Gibson', 'MS', 'A large historic park preserving the remnants of Grand Gulf, a river town damaged by war and ultimately abandoned after changes to the Mississippi River. Historic buildings, cemetery areas, military earthworks and moved structures create a rare combination of ghost town and museum landscape. Coordinate source: National Register documentation', 'open', null, 'https://www.grandgulfpark.ms.gov/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grand Village of the Natchez Indians / Natchez Tribal History Center', 'grand-village-of-the-natchez-indians-natchez-tribal-history-center', 'weird-history', 31.52565, -91.38067, 'Natchez', 'MS', 'A major Natchez ceremonial center with reconstructed features, preserved mounds, museum exhibits and direct interpretation of Natchez history. Unlike many mound sites, this is a staffed public historic site designed for visitors.', 'open', null, 'https://trails.mdah.ms.gov/grandvillage', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.mdah.ms.gov/explore-mississippi/grand-village-natchez-indians', null, null, null, 'America/Chicago'),
  ('Belgum (Grande Vista) Sanitarium Ruins', 'grande-vista-sanitarium', 'weird-history', 37.949607, -122.308551, 'Richmond', 'CA', 'The Grande Vista, later known as Belgum Sanitarium, closed in the 1960s and its main buildings were destroyed by fire. Today hikers in Wildcat Canyon Regional Park can find remnants such as foundations, stonework and old landscaping along the former sanitarium grounds.', 'open', null, 'https://www.ebparks.org/parks/wildcat-canyon', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 2640323068, 'America/Los_Angeles'),
  ('Grave Creek Mound Archaeological Complex', 'grave-creek-mound-archaeological-complex', 'weird-history', 39.91686, -80.74472, 'Moundsville', 'WV', 'Built by Adena people around 250–150 B.C., Grave Creek Mound is one of the largest surviving conical burial mounds of its culture and required the movement of tens of thousands of tons of earth. A free state museum beside the mound interprets West Virginia archaeology and the people who built it.', 'open', null, 'https://wvculture.org/explore/grave-creek-mound/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Albert DeSalvo', 'grave-of-albert-desalvo', 'weird-history', 42.52787, -70.92866, 'Peabody', 'MA', 'Albert DeSalvo, who confessed to being the Boston Strangler, is buried in Puritan Lawn Memorial Park. DNA later linked him to the murder of Mary Sullivan, although historians and investigators have long questioned whether he was responsible for every killing attributed to the Strangler. Visit only during cemetery hours.', 'limited', null, 'https://www.atlasobscura.com/places/grave-of-the-boston-strangler', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Amum-Her-Khepesh-Ef', 'grave-of-amum-her-khepesh-ef', 'weird-history', 44.00654, -73.17805, 'Middlebury', 'VT', 'A Middlebury cemetery contains the burial place of an ancient Egyptian mummy once owned by Middlebury College. After deterioration made the remains unsuitable for continued display, the thousands-of-years-old individual was given a modern Vermont burial.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-amum-her-khepesh-ef', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Arthur Twining Hadley', 'grave-of-arthur-twining-hadley', 'weird-history', 41.31378, -72.92705, 'New Haven', 'CT', 'Former Yale president Arthur Twining Hadley was reportedly buried wearing a Japanese samurai costume given to him during his travels. The grave itself is understated, but the bizarre burial detail has made it one of New Haven''s stranger cemetery stories.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-arthur-twining-hadley', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Chang and Eng Bunker', 'grave-of-chang-and-eng-bunker', 'weird-history', 36.45363, -80.62884, 'Mount Airy', 'NC', 'Chang and Eng Bunker, the conjoined twins whose fame popularized the term “Siamese twins,” settled in North Carolina, married sisters, raised large families, and became farmers. They are buried together beneath a shared marker in the White Plains Baptist Church cemetery.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-chang-and-eng-bunker', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Charles Stratton — General Tom Thumb', 'grave-of-charles-stratton-general-tom-thumb', 'weird-history', 41.17658, -73.22089, 'Bridgeport', 'CT', 'Charles Sherwood Stratton, the internationally famous performer promoted by P.T. Barnum as General Tom Thumb, is buried in Mountain Grove Cemetery. A life-size statue of the diminutive entertainer stands atop his monument, making the grave immediately recognizable.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-charles-stratton', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Christa McAuliffe', 'grave-of-christa-mcauliffe', 'weird-history', 43.22357, -71.55551, 'Concord', 'NH', 'Concord teacher Christa McAuliffe was selected for NASA''s Teacher in Space Project and died with the crew of Space Shuttle Challenger in 1986. Her grave remains in Concord and is part of the city''s enduring connection to her life and legacy. Visit respectfully during cemetery hours; the grave is in Block M, Lot 51L.', 'limited', null, 'https://www.concordmonitor.com/2026/01/29/christa-mcauliffe-legacy-concord/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Daisy and Violet Hilton', 'grave-of-daisy-and-violet-hilton', 'weird-history', 35.2578, -80.913, 'Charlotte', 'NC', 'Conjoined twins Daisy and Violet Hilton spent much of their lives performing in vaudeville, sideshows, and film before eventually settling in Charlotte. They died within days of one another during the 1968 flu pandemic and share a grave at Forest Lawn West Cemetery.', 'open', null, 'https://www.atlasobscura.com/places/daisy-and-violet-hilton-grave', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Doctor Pepper', 'grave-of-doctor-pepper', 'weird-history', 36.89056, -81.28028, 'Rural Retreat', 'VA', 'Dr. Charles T. Pepper is buried in Mountain View Cemetery, and a long-running local story connects him to the naming of the Dr Pepper soft drink through pharmacist Wade Morrison. The exact origin of the beverage''s name remains disputed, but the grave gives travelers a physical stop for one of Virginia''s most persistent soda-history stories.', 'open', null, 'https://www.roadsideamerica.com/tip/9262', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Don Featherstone', 'grave-of-don-featherstone', 'weird-history', 42.36606, -71.62873, 'Berlin', 'MA', 'Don Featherstone, designer of the iconic plastic pink lawn flamingo, is buried beneath a marker decorated with a flock of flamingos and an inscription crediting him as their original creator. It is an appropriately kitschy final memorial for one of America''s most recognizable lawn ornaments.', 'limited', null, 'https://www.atlasobscura.com/places/don-featherstone-grave', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Dunkin'' Donuts Founder', 'grave-of-dunkin-donuts-founder', 'weird-history', 42.14592, -71.16848, 'Sharon', 'MA', 'William Rosenberg, founder of Dunkin'' Donuts, is buried in Sharon Memorial Park. The otherwise conventional grave gives Massachusetts travelers a physical endpoint to the story of a regional doughnut-and-coffee business that grew into an international chain. Check cemetery access rules before visiting.', 'limited', null, 'https://www.atlasobscura.com/places/grave-of-dunkin-donuts-founder-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Felix Schlag — Jefferson Nickel Designer', 'grave-of-felix-schlag-jefferson-nickel-designer', 'weird-history', 42.98638, -84.16977, 'Owosso', 'MI', 'Felix Schlag won the 1938 competition to design the Jefferson nickel, creating the basic portrait and Monticello design used for decades. His grave in Oak Hill Cemetery is marked with a large representation of the coin, and visitors sometimes leave nickels on the stone.', 'limited', null, 'https://www.atlasobscura.com/places/grave-of-felix-schlag', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Grave of Florena Budwin', 'grave-of-florena-budwin', 'weird-history', 34.18509, -79.75433, 'Florence', 'SC', 'Florena Budwin is traditionally identified as a woman who disguised herself as a man in order to accompany her husband into Confederate military service. Captured and imprisoned, she died in 1865 and is buried at Florence National Cemetery; elements of her story remain debated, but the grave has become a local historical curiosity. Cemetery: https://www.cem.va.gov/cems/nchp/florence.asp', 'open', null, 'https://www.roadsideamerica.com/tip/36204', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of George Mendonsa — The Kissing Sailor', 'grave-of-george-mendonsa-the-kissing-sailor', 'weird-history', 41.54266, -71.30541, 'Middletown', 'RI', 'George Mendonsa, widely identified as the sailor in Alfred Eisenstaedt''s famous V-J Day Times Square photograph, is buried in St. Columba Cemetery. His grave marker reproduces the instantly recognizable embrace in etched stone. The coordinate routes to the cemetery; visitors should follow cemetery rules and locate the individual grave respectfully.', 'limited', null, 'https://www.roadsideamerica.com/tip/70203', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Grizzly Adams', 'grave-of-grizzly-adams', 'weird-history', 42.13127, -71.96878, 'Charlton', 'MA', 'John ''Grizzly'' Adams, the nineteenth-century mountain man and animal trainer, is buried beneath a monument topped by a carved bear. His traveling menageries and exaggerated frontier image helped turn him into a lasting American folk character.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-grizzly-adams', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of John King — Killed by an Elephant', 'grave-of-john-king-killed-by-an-elephant', 'weird-history', 35.23444, -80.84731, 'Charlotte', 'NC', 'John King was killed after being crushed by an escaped circus elephant in Charlotte. His gravestone carries a carved elephant, turning an already bizarre death into one of the city’s strangest cemetery markers.', 'open', null, 'https://www.atlasobscura.com/places/john-king-grave-crushed-by-elephant', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Millie-Christine McKoy', 'grave-of-millie-christine-mckoy', 'weird-history', 34.38772, -78.66041, 'Whiteville', 'NC', 'Conjoined twins Millie and Christine McKoy were born enslaved in North Carolina in 1851 and later became internationally known performers billed as the “Two-Headed Nightingale.” Their shared grave in Welches Creek Cemetery bears an inscription describing “two hearts that beat as one.” Cemetery coordinates: https://www.wikidata.org/wiki/Q68101741', 'open', null, 'https://www.roadsideamerica.com/tip/47271', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Mr. Barbo', 'grave-of-mr-barbo', 'weird-history', 43.16603, -73.11764, 'Manchester', 'VT', 'Near the summit of Equinox Mountain is the granite grave of Mr. Barbo, the beloved dog of industrialist Joseph George Davidson. The unusually elaborate canine memorial recounts how Barbo was killed by a hunter in 1955; reaching it requires seasonal access on Skyline Drive.', 'limited', null, 'https://www.atlasobscura.com/places/grave-of-mr-barbo', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Robert E. Harrill — The Fort Fisher Hermit', 'grave-of-robert-e-harrill-the-fort-fisher-hermit', 'weird-history', 34.01798, -77.91458, 'Carolina Beach', 'NC', 'Robert E. Harrill became a coastal celebrity after living for years in an abandoned World War II bunker near Fort Fisher and welcoming thousands of curious visitors. His grave preserves the story of the self-styled Fort Fisher Hermit after his mysterious death in 1972.', 'open', null, 'https://www.atlasobscura.com/places/newton-graveyard-and-homesite', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Sarah Ware', 'grave-of-sarah-ware', 'weird-history', 44.57505, -68.79688, 'Bucksport', 'ME', 'Sarah Ware was murdered in 1898 in a case that remains one of Bucksport’s enduring unsolved crimes. Her severed head was reportedly retained as evidence for decades before eventually being returned for burial near her cemetery marker.', 'open', null, 'https://www.atlasobscura.com/places/grave-sarah-ware', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Sevilla Jones', 'grave-of-sevilla-jones', 'weird-history', 42.97296, -71.68825, 'New Boston', 'NH', 'Seventeen-year-old Sevilla Jones was murdered by Henry Sargent in 1854 while walking to school. Her unusually blunt gravestone names Sargent as her killer and describes the shooting, turning the marker into a permanent public accusation. Sargent is buried only a short distance away in the same cemetery.', 'limited', null, 'https://www.atlasobscura.com/places/grave-of-sevilla-jones', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Sinbad the Coast Guard Dog', 'grave-of-sinbad-the-coast-guard-dog', 'weird-history', 39.75812, -74.10344, 'Barnegat Light', 'NJ', 'Sinbad served aboard the Coast Guard cutter Campbell for years, surviving combat and becoming one of the service''s most famous animal mascots. A memorial and burial site at Barnegat Light preserves the story of the mixed-breed dog whose service career included World War II.', 'limited', null, 'https://www.history.uscg.mil/Browse-by-Topic/Assets/Land/All/Article/1882479/sinbad-the-coast-guard-dog/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Spaghetti — The Carny Mummy', 'grave-of-spaghetti-the-carny-mummy', 'weird-history', 34.7846, -79.46227, 'Laurinburg', 'NC', 'Cancetto “Spaghetti” Farmica was a carnival worker whose unclaimed body reportedly spent years preserved at a Laurinburg funeral home before finally being buried in 1972. Local accounts say his grave was sealed beneath an extraordinary amount of concrete, giving the obscure showman one of North Carolina’s strangest burial stories.', 'open', null, 'https://www.roadsideamerica.com/tip/7849', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Speedy the Mortuary Mummy', 'grave-of-speedy-the-mortuary-mummy', 'weird-history', 37.08909, -88.62469, 'Paducah', 'KY', 'Charles "Speedy" Atkins drowned in 1928, was embalmed and then remained unclaimed at a Paducah funeral home for an astonishing 66 years. The preserved body became a local celebrity before finally being buried in Maplelawn Park Cemetery in 1994; his modest marker records the bizarre delay between death and burial.', 'open', null, 'https://www.roadsideamerica.com/story/34518', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grave of the Smiley Face Inventor', 'grave-of-the-smiley-face-inventor', 'weird-history', 42.23465, -71.83737, 'Worcester', 'MA', 'Harvey Ball, the Worcester artist who created the familiar yellow Smiley Face in 1963, is buried beneath a granite marker displaying his own cheerful design. Ball reportedly created the image in minutes for an insurance-company morale campaign and was paid only a small fee. Visit Notre Dame Cemetery respectfully from dawn to dusk.', 'limited', null, 'https://www.roadsideamerica.com/tip/58637', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of the Unknown Confederate Stranger', 'grave-of-the-unknown-confederate-stranger', 'weird-history', 43.88533, -70.33277, 'Gray', 'ME', 'A Confederate soldier whose identity remains unknown is buried in Gray after his body was mistakenly shipped north during the Civil War in place of Union soldier Charles Colley. Unable to determine who the stranger was or where to return him, local residents buried him in Maine, leaving one of the state’s strangest Civil War graves.', 'open', null, 'https://www.bangordailynews.com/2020/06/26/news/state-news/how-7-confederate-soldiers-came-to-be-buried-in-maine/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of the Unknown Woman', 'grave-of-the-unknown-woman', 'weird-history', 40.61772, -74.28624, 'Rahway', 'NJ', 'In 1887, the body of an unidentified murdered woman was found near Rahway, drawing national attention but never yielding a confirmed identity. Her simple grave survives at the rear of Rahway Cemetery and still bears the mystery in its inscription.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-the-unknown-woman', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of the Wienermobile''s Little Oscar', 'grave-of-the-wienermobiles-little-oscar', 'weird-history', 41.48603, -87.36562, 'Merrillville', 'IN', 'George Molchan spent decades portraying Little Oscar for Oscar Mayer and traveling with the Wienermobile before retiring in 1987. His grave in Calumet Park Cemetery includes a bronze image of his costumed alter ego and the Wienermobile; it is in Section 19, Marker 901.', 'open', null, 'https://www.roadsideamerica.com/tip/51527', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grave of Timothy Clark Smith', 'grave-of-timothy-clark-smith', 'weird-history', 44.11322, -73.16346, 'New Haven', 'VT', 'Doctor Timothy Clark Smith feared being buried alive, so his nineteenth-century grave was built with a window that allowed people above ground to look into the burial chamber. The unusual design survives in Evergreen Cemetery as a physical reminder of Victorian fears surrounding premature burial.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-timothy-clark-smith', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of William French', 'grave-of-william-french', 'weird-history', 43.07158, -72.45524, 'Westminster', 'VT', 'William French was killed during the 1775 Westminster confrontation between local protesters and New York authorities. His unusually direct gravestone inscription condemns King George III and his supporters, and French''s death became part of the political chain of events preceding Vermont''s declaration of independence.', 'open', null, 'https://www.atlasobscura.com/places/william-french-grave-westminster-vermont', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of Wolfman Jack', 'grave-of-wolfman-jack', 'weird-history', 36.2683, -76.5473, 'Belvidere', 'NC', 'Legendary radio personality Wolfman Jack, born Robert Weston Smith, spent his final years in rural northeastern North Carolina and was buried near his Belvidere home after his death in 1995. The gravesite can be seen from the road, but it is associated with private family property, so this should remain a respectful roadside-view stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/latest', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graves of David and Mabel Todd', 'graves-of-david-and-mabel-todd', 'weird-history', 42.38838, -72.51175, 'Amherst', 'MA', 'Astronomer David Todd repeatedly traveled around the world chasing solar eclipses only to encounter clouds and other failures, while his wife Mabel Loomis Todd became crucial to the publication of Emily Dickinson''s poetry. Their unusual memorials incorporate astronomical and botanical imagery tied to their lives.', 'limited', null, 'https://www.atlasobscura.com/places/graves-of-david-and-mabel-todd', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graves of John Cloyce & Abraham Rice', 'graves-of-john-cloyce-abraham-rice', 'weird-history', 42.2976, -71.4286, 'Framingham', 'MA', 'Two men killed by the same lightning strike in 1777 are remembered with neighboring stones. The paired graves preserve the bizarre shared fate of John Cloyce and Abraham Rice inside Framingham''s historic burial landscape.', 'limited', null, 'https://www.atlasobscura.com/places/graves-of-john-cloyce-abraham-rice', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graves of the McGuire Twins', 'graves-of-the-mcguire-twins', 'weird-history', 35.24562, -82.54773, 'Hendersonville', 'NC', 'Billy and Benny McCrary became internationally famous as the McGuire Twins, professional wrestlers and entertainers billed as the world’s heaviest twins. Their matching graves continue the pair’s visual symmetry even after death.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-the-worlds-largest-twins', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graves of the Smuttynose Murder Victims', 'graves-of-the-smuttynose-murder-victims', 'weird-history', 43.06603, -70.75788, 'Portsmouth', 'NH', 'Matching gravestones in South Cemetery mark Karen Christensen and Anethe Christensen, two women murdered on Smuttynose Island in 1873. A third woman escaped and accused Louis Wagner, who was later executed for the killings, though debate over the case persisted. The graves provide a mainland stop tied directly to one of the Isles of Shoals'' darkest stories.', 'limited', null, 'https://www.atlasobscura.com/places/graves-smuttynose-murder-victims', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravesite of Dixville''s First Settlers', 'gravesite-of-dixvilles-first-settlers', 'weird-history', 44.85643, -71.28597, 'Dixville', 'NH', 'A tiny burial site near Dixville Notch preserves the story of early settler Betsey Whittemore, who died in December 1815. Winter conditions were so severe that her body reportedly could not be transported out of the notch and had to remain until burial became possible. The graves are near the public waterfall parking area but should be treated as a cemetery, not a roadside prop.', 'limited', null, 'https://www.atlasobscura.com/places/gravesite-of-dixvilles-first-settlers', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravesite of Richard Potter', 'gravesite-of-richard-potter', 'weird-history', 43.43649, -71.85588, 'Andover', 'NH', 'Richard Potter, born in 1783, became one of the first American-born professional magicians and a prominent Black entertainer in the early United States. He and his wife Sally are buried near Potter Place, the village that eventually took his name. The graves are behind the historic railroad-station area and are accessible for respectful visits.', 'open', null, 'https://www.atlasobscura.com/places/gravesite-of-richard-potter-americas-first-professional-magician', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graveyard Island', 'graveyard-island', 'weird-history', 35.45801, -80.12372, 'Badin', 'NC', 'When the Yadkin River was dammed to create Badin Lake, hundreds of graves from threatened cemeteries were relocated to higher ground on what became an island. Roughly 300 burials are associated with the site, including marked and unmarked graves; portions have access restrictions, so visitors must respect posted rules and obtain permission where required.', 'limited', null, 'https://www.atlasobscura.com/places/graveyard-island', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Great Boston Molasses Flood Plaque', 'great-boston-molasses-flood-plaque', 'weird-history', 42.36834, -71.05585, 'Boston', 'MA', 'A small marker near the North End waterfront remembers the 1919 Great Molasses Flood, when a storage tank burst and a wave of molasses tore through the neighborhood, killing 21 people and injuring scores more. The understated plaque marks one of Boston''s strangest and deadliest industrial disasters.', 'open', null, 'https://www.atlasobscura.com/places/great-boston-molasses-flood-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Great Swamp Fight Monument', 'great-swamp-fight-monument', 'weird-history', 41.47307, -71.59642, 'South Kingstown', 'RI', 'A granite monument deep in the Great Swamp commemorates the December 1675 battle in which colonial forces attacked a fortified Narragansett settlement during King Philip''s War. Hundreds of Narragansett people, including noncombatants, were killed. The monument is reached by an undeveloped walk and should be treated as a historical memorial rather than a casual photo prop.', 'open', null, 'https://www.hmdb.org/m.asp?m=21276', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Great Wallace Shows Circus Train-Wreck Memorial', 'great-wallace-shows-circus-train-wreck-memorial', 'weird-history', 42.88123, -83.99195, 'Durand', 'MI', 'A 1903 collision involving the Great Wallace Shows circus train killed performers, workers and animals near Durand. Several unidentified victims were buried together in Lovejoy Cemetery, where a memorial preserves the story of one of America''s deadliest circus-train disasters.', 'open', null, 'https://www.atlasobscura.com/places/great-wallace-shows-circus-train-wreck-memorial', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Green Jacket Shoal Ship Graveyard Viewpoint', 'green-jacket-shoal-ship-graveyard-viewpoint', 'weird-history', 41.81579, -71.3917, 'East Providence', 'RI', 'Just offshore from Providence and East Providence lies Green Jacket Shoal, an underwater graveyard containing the remains of abandoned nineteenth- and twentieth-century vessels along with debris from the waterfront''s industrial past. The wrecks are most apparent at low tide and are the subject of ongoing maritime archaeology. Route visitors to the public waterfront at Bold Point Park rather than onto the shoal or wreckage.', 'open', null, 'https://www.crmc.ri.gov/newsandevents/2018/20180516-shipgraveyard.html', '2026-09-09T04:49:27.913704+00:00', null, 'https://eastprovidenceri.gov/facilities/park/bold-point-park', null, null, null, 'America/New_York'),
  ('Green Mill Cocktail Lounge', 'green-mill-cocktail-lounge', 'weird-history', 41.96918, -87.65989, 'Chicago', 'IL', 'A Prohibition-era jazz club strongly associated with Al Capone''s Chicago, complete with old booths, tunnels lore, and a remarkably preserved atmosphere.', 'limited', null, 'https://greenmilljazz.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Green Mount Cemetery', 'green-mount-cemetery', 'weird-history', 44.25703, -72.59742, 'Montpelier', 'VT', 'This hillside cemetery is packed with elaborate Victorian funerary art, including carved stairways, sculpted figures and the locally notorious Hubbard memorial. Ghost and curse stories have attached themselves to some of the monuments, but the carvings themselves are the documented attraction.', 'open', null, 'https://www.atlasobscura.com/places/green-mount-cemetery', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbank''s Hollow', 'greenbanks-hollow', 'weird-history', 44.37726, -72.12217, 'Danville', 'VT', 'A once-busy mill village largely disappeared after a destructive nineteenth-century fire. Today interpretive signs, foundations and landscape remnants allow visitors to walk through the remains of a Vermont community that effectively vanished.', 'open', null, 'https://www.atlasobscura.com/places/greenbanks-hollow', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbrier Congressional Bunker', 'greenbrier-congressional-bunker', 'weird-history', 37.78456, -80.30886, 'White Sulphur Springs', 'WV', 'Hidden beneath the Greenbrier resort during the Cold War, Project Greek Island was a massive fallout shelter designed to house the entire United States Congress after a nuclear attack. Its existence was exposed publicly in 1992, and the declassified bunker can now be visited only on scheduled guided tours.', 'limited', null, 'https://www.greenbrier.com/activities/bunker-tours/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbrier County Courthouse', 'greenbrier-county-courthouse', 'weird-history', 37.80323, -80.44514, 'Lewisburg', 'WV', 'This is the courthouse where Erasmus Shue was tried for the 1897 murder of his wife Zona, the crime at the center of the Greenbrier Ghost legend. The building remains a functioning courthouse, so it is a legitimate historical stop rather than a paranormal attraction and visitors should behave accordingly during business hours.', 'open', null, 'https://greenbrierwv.com/places/greenbrier-county-courthouse', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenup County War Memorial', 'greenup-county-war-memorial', 'weird-history', 38.55188, -82.85577, 'Greenup', 'KY', 'This unusually equipment-heavy veterans memorial surrounds its monuments with a full-size tank, fighter jet, helicopter and military boat. One of the Huey helicopter displays has held dog tags honoring veterans, turning the roadside park into a much more visually dramatic memorial than a conventional stone monument.', 'open', null, 'https://www.roadsideamerica.com/tip/30875', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenwich Tea Burning Monument', 'greenwich-tea-burning-monument', 'weird-history', 39.38833, -75.33833, 'Greenwich Township', 'NJ', 'A monument commemorates the December 1774 Greenwich Tea Party, when local patriots destroyed a shipment of tea in protest against British taxation. The New Jersey action occurred after the more famous Boston Tea Party but remains an important regional Revolutionary-era protest.', 'open', null, 'https://www.hmdb.org/m.asp?m=22044', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenwood Cemetery', 'greenwood-cemetery', 'weird-history', 28.52258, -81.35097, 'Orlando', 'FL', 'Historic cemetery with notable local burials and occasional guided moonlight walks.', 'open', null, 'https://www.orlando.gov/Parks-the-Environment/Directory/Greenwood-Cemetery', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Griffith & Feil Soda Fountain', 'griffith-feil-soda-fountain', 'weird-history', 38.39953, -82.57819, 'Kenova', 'WV', 'Griffith & Feil traces its pharmacy roots to 1892 and still operates an old-fashioned soda fountain inside the working business. Visitors can sit at the counter for ice cream and diner food while surrounded by a surviving piece of small-town pharmacy history.', 'open', null, 'https://gfsodafountain.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grindstone Ford', 'grindstone-ford', 'weird-history', 32.00276, -90.89508, 'Port Gibson', 'MS', 'A Natchez Trace stop where travelers historically crossed Bayou Pierre and where the old road alignment can still be followed on foot. The forested site combines Trace history with the feeling of a route reclaimed by nature.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Grove Park Inn — Secret Supreme Court Cold War Site', 'grove-park-inn-secret-supreme-court-cold-war-site', 'weird-history', 35.62018, -82.54287, 'Asheville', 'NC', 'During the Cold War, contingency plans designated Asheville’s Grove Park Inn as a relocation site where the U.S. Supreme Court could continue operating after a nuclear attack on Washington. The hotel is open to guests and visitors, but the former emergency shelter facilities themselves are not public.', 'limited', null, 'https://www.atlasobscura.com/places/grove-park-inn', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Guignard Brick Works', 'guignard-brick-works', 'weird-history', 33.9883, -81.05023, 'Cayce', 'SC', 'Beehive kilns and industrial remains survive from a brickworks that once produced huge quantities of building material near the Congaree River. The preserved circular kilns look almost like small ruined fortifications and are visible from the Three Rivers Greenway area.', 'open', null, 'https://www.scpictureproject.org/lexington-county/guignard-brickworks.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gungywamp', 'gungywamp', 'weird-history', 41.38348, -72.0608, 'Groton', 'CT', 'Gungywamp is a baffling archaeological landscape of stone chambers, walls, rings and other features representing centuries of Indigenous and colonial activity. Its unusual structures have also inspired plenty of speculative theories. Access is controlled and should be through an authorized guided program rather than independent exploration.', 'limited', null, 'https://www.atlasobscura.com/places/gungywamp', '2026-09-08T18:39:47.144889+00:00', null, 'https://dpnc.org/', null, null, null, 'America/New_York'),
  ('Hachiko Statue at Woonsocket Depot', 'hachiko-statue-at-woonsocket-depot', 'weird-history', 42.00355, -71.5133, 'Woonsocket', 'RI', 'A bronze statue of the famously loyal Japanese dog Hachiko stands outside Woonsocket''s former train depot. The location was used while filming the 2009 movie "Hachi: A Dog''s Tale," with the Rhode Island city standing in for the film''s New England setting. The statue gives the movie connection a permanent physical marker.', 'open', null, 'https://www.roadsideamerica.com/tip/33728', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hadrosaurus Foulkii Discovery Site', 'hadrosaurus-foulkii-discovery-site', 'weird-history', 39.9102, -75.02857, 'Haddonfield', 'NJ', 'A small wooded ravine marks the location where bones of Hadrosaurus foulkii were uncovered in 1858. The find became one of the first nearly complete dinosaur skeletons discovered and scientifically described in North America.', 'open', null, 'https://www.atlasobscura.com/places/hadrosaurus-foulkii-leidy-site', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hail to the Sunrise', 'hail-to-the-sunrise', 'weird-history', 42.63998, -72.91287, 'Charlemont', 'MA', 'A bronze Native American figure faces east with outstretched arms beside the Mohawk Trail. Installed in 1932, the monument was created by the Improved Order of Red Men and reflects an older, non-Native fraternal interpretation of Indigenous imagery, making its history more complicated than the striking roadside silhouette suggests.', 'open', null, 'https://www.atlasobscura.com/places/hail-to-the-sunrise', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Half Moon Underwater Archaeological Preserve', 'half-moon-underwater-archaeological-preserve', 'weird-history', 25.72707, -80.13463, 'Key Biscayne', 'FL', 'German-built racing yacht later used as a Miami floating saloon before wrecking off Key Biscayne around 1930.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/half-moon/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hancock House — Bayonet Massacre Site', 'hancock-house-bayonet-massacre-site', 'weird-history', 39.50807, -75.46029, 'Hancocks Bridge', 'NJ', 'British and Loyalist troops stormed this house in March 1778 and killed roughly two dozen people inside during the Hancock''s Bridge massacre. The preserved eighteenth-century building operates as a state historic site with limited tour hours.', 'limited', null, 'https://www.roadsideamerica.com/story/33807', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hand Out Grave', 'hand-out-grave', 'weird-history', 38.24608, -85.7162, 'Louisville', 'KY', 'George Anne Sotsky''s Cave Hill Cemetery monument takes the form of an enormous open stone hand with its palm facing upward. The gesture symbolizes generosity and creates one of the cemetery''s strangest pieces of funerary sculpture.', 'open', null, 'https://www.roadsideamerica.com/tip/79097', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('Hank Williams Boyhood Home & Museum', 'hank-williams-boyhood-home-museum', 'weird-history', 31.63946, -86.74195, 'Georgiana', 'AL', 'Hank Williams lived in this house as a child and began developing the musical skills that would define his career. The museum preserves family history, memorabilia and the local story of his early guitar lessons.', 'open', null, 'https://www.hankmuseum.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hank Williams Death Monument', 'hank-williams-death-monument', 'weird-history', 37.97603, -81.14121, 'Oak Hill', 'WV', 'A small monument in Oak Hill marks the city where driver Charles Carr discovered that country singer Hank Williams had died in the back seat of his Cadillac on New Year''s Day 1953. The marker gives travelers a physical stop tied to one of American music''s most famous and grim road-trip stories.', 'open', null, 'https://www.wvencyclopedia.org/entries/2277', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hank Williams Grave', 'hank-williams-grave', 'weird-history', 32.38543, -86.29106, 'Montgomery', 'AL', 'Hank Williams and his wife Audrey are buried beneath large white marble monuments in Oakwood Cemetery Annex. The graves have become a music-history pilgrimage site; visitors should observe cemetery hours and treat surrounding burials respectfully.', 'limited', null, 'https://www.montgomeryal.gov/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hank Williams Museum', 'hank-williams-museum', 'weird-history', 32.37948, -86.31068, 'Montgomery', 'AL', 'The museum preserves stage clothing, instruments, records, photographs and personal objects tied to Hank Williams. Its collection includes the Cadillac associated with his final journey, making it a particularly tangible stop for country-music history.', 'open', null, 'https://thehankwilliamsmuseum.net/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hannah Duston Memorial', 'hannah-duston-memorial', 'weird-history', 43.28816, -71.59071, 'Boscawen', 'NH', 'A 35-foot monument commemorates Hannah Duston, who was taken captive during King William''s War in 1697 and later killed ten Abenaki people at a camp before escaping. The nineteenth-century monument presents one version of a violent colonial story whose interpretation has become increasingly contested. The state historic site is currently listed as always open for recreation.', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/hannah-duston-memorial-historic-site', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hannibal Hamlin’s Death Couch', 'hannibal-hamlins-death-couch', 'weird-history', 44.80443, -68.77158, 'Bangor', 'ME', 'Bangor Public Library displays the couch on which Hannibal Hamlin, Abraham Lincoln’s first vice president, died in 1891. Rather than being hidden away in storage, the piece of furniture survives as an unusually direct artifact from a former vice president’s final moments.', 'limited', null, 'https://www.atlasobscura.com/places/hannibal-hamlin-death-couch', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harriet E. Wilson Memorial', 'harriet-e-wilson-memorial', 'weird-history', 42.83325, -71.64991, 'Milford', 'NH', 'A bronze memorial honors Harriet E. Wilson, author of the 1859 novel "Our Nig," a landmark work in African American literary history. Wilson was born in Milford and endured poverty and indentured servitude before becoming an author, lecturer and spiritualist. The statue stands in public Bicentennial Park.', 'open', null, 'https://www.atlasobscura.com/places/harriet-wilson-statue', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harry Houdini''s Grave', 'harry-houdinis-grave', 'weird-history', 40.69344, -73.8848, 'Queens', 'NY', 'Escape artist Harry Houdini is buried beneath a distinctive monument in Machpelah Cemetery, where magicians and fans have gathered for decades around the anniversary of his Halloween 1926 death. The grave can be visited during cemetery hours, but this is an active burial ground and should be treated respectfully.', 'open', null, 'https://houdinimuseum.wordpress.com/2013/02/05/houdini-grave-aerial-map/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hart Island', 'hart-island', 'weird-history', 40.85326, -73.77044, 'Bronx', 'NY', 'New York City has used Hart Island as its public cemetery for more than a century, burying more than a million people there in mass and individual graves. The island is not freely accessible, but NYC Parks now offers limited public ranger visits and scheduled gravesite visits using the city ferry.', 'limited', null, 'https://www.nyc.gov/site/hartisland/hart-island/visitation.page', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hartford Circus Fire Memorial', 'hartford-circus-fire-memorial', 'weird-history', 41.79497, -72.67445, 'Hartford', 'CT', 'A memorial marks the location of the July 6, 1944 Ringling Bros. and Barnum & Bailey circus fire, one of the deadliest circus disasters in American history. The memorial stands near the former big-top site and preserves the names and memory of the victims.', 'open', null, 'https://www.atlasobscura.com/places/hartford-circus-fire-memorial', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harvard Bridge Houdini Plaque', 'harvard-bridge-houdini-plaque', 'weird-history', 42.35213, -71.08991, 'Boston', 'MA', 'A plaque on the Harvard Bridge commemorates Harry Houdini''s 1908 leap into the Charles River while shackled in chains. Thousands reportedly watched the escape artist make the stunt, and the small marker preserves a surprisingly dramatic piece of Boston spectacle history.', 'open', null, 'https://www.atlasobscura.com/places/harvard-bridge-houdini-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harvey''s Lake — Jacques Cousteau''s Early Dive Site', 'harveys-lake-jacques-cousteaus-early-dive-site', 'weird-history', 44.30387, -72.13894, 'Barnet', 'VT', 'Harvey''s Lake is locally associated with Jacques Cousteau''s childhood and is promoted as the place where the future ocean explorer had his first significant diving experience while attending summer camp. The unlikely inland Vermont connection makes the lake a peculiar landmark in diving history.', 'open', null, 'https://www.atlasobscura.com/places/harveys-lake-home-of-jacques-cousteaus-first-dive', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haskell Free Library and Opera House', 'haskell-free-library-and-opera-house', 'weird-history', 45.00573, -72.09767, 'Derby Line', 'VT', 'The international boundary between the United States and Canada runs directly through this library and opera house, with a marked line crossing the interior. Border procedures changed in 2025 and a separate Canadian entrance opened in 2026, so visitors must use the proper entrance for the country from which they arrive and cannot treat the building as a border crossing.', 'limited', null, 'https://www.atlasobscura.com/places/haskell-free-library-and-opera-house', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hat Maker Statue', 'hat-maker-statue', 'weird-history', 41.39188, -73.45378, 'Danbury', 'CT', 'A bronze hatter commemorates the industry that once made Danbury one of America''s great hat-making centers. The cheerful-looking monument has a darker undertone: mercury used in felt production caused serious neurological illness among hat workers and helped popularize the phrase ''mad as a hatter.''', 'open', null, 'https://www.atlasobscura.com/places/hat-maker-statue', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hatch Show Print', 'hatch-show-print', 'weird-history', 36.15804, -86.77596, 'Nashville', 'TN', 'One of America''s oldest working letterpress poster shops preserves carved type, blocks and the bold visual language of country-music advertising. Visitors can see how hand-set print design became inseparable from Nashville''s musical identity.', 'open', null, 'https://hatchshowprint.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hatfield-McCoy Love Baby Grave', 'hatfield-mccoy-love-baby-grave', 'weird-history', 37.56786, -82.23755, 'Burnwell', 'KY', 'Roseanna McCoy and Johnse Hatfield''s relationship produced a daughter, Sarah Elizabeth "Sally" McCoy, during the bitter Hatfield-McCoy feud. The infant died after only a few months, and a staircase from a small public parking area now climbs to the hillside cemetery containing her grave and interpretive markers.', 'open', null, 'https://www.roadsideamerica.com/story/48376', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hatteras Weather Bureau Station', 'hatteras-weather-bureau-station', 'weird-history', 35.22022, -75.69044, 'Hatteras', 'NC', 'This bright historic weather station has an unexpected connection to the Titanic disaster. Operators here received early wireless information about the ship striking an iceberg in April 1912; the building later became a preserved National Park Service site and visitor facility. NPS: https://www.nps.gov/caha/planyourvisit/uswbs.htm', 'limited', null, 'https://www.atlasobscura.com/places/hatteras-weather-bureau-station', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haven Hill', 'haven-hill', 'weird-history', 42.64092, -83.56342, 'White Lake Township', 'MI', 'Henry and Clara Ford''s former country estate once included a large mansion, pool, gardens and recreational facilities high above the surrounding landscape. The mansion burned in 1999, but foundations, a chimney and other ruins remain along public trails within Highland Recreation Area.', 'open', null, 'https://www.atlasobscura.com/places/haven-hill', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Hawks Nest Tunnel Disaster Overlook', 'hawks-nest-tunnel-disaster-overlook', 'weird-history', 38.12267, -81.12752, 'Ansted', 'WV', 'From the Hawks Nest State Park overlook area, visitors can follow interpretation connected with the three-mile tunnel whose construction exposed thousands of workers to dangerous silica dust beginning in 1930. The National Park Service directs visitors here as a formal stop for understanding the disaster.', 'open', null, 'https://home.nps.gov/places/hawks-nest-tunnel-disaster.htm', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hawks Nest Workers Memorial and Grave Site', 'hawks-nest-workers-memorial-and-grave-site', 'weird-history', 38.23447, -80.85269, 'Lookout', 'WV', 'This memorial marks the burial area associated with African American workers who died after being exposed to enormous concentrations of silica dust during construction of the Hawks Nest Tunnel in the early 1930s. The National Park Service describes the project as one of America''s worst industrial tragedies.', 'open', null, 'https://home.nps.gov/places/hawks-nest-workers-memorial-and-grave-site.htm', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hawley Beehive Kiln', 'hawley-beehive-kiln', 'weird-history', 42.56312, -72.87948, 'Hawley', 'MA', 'A remarkably intact nineteenth-century stone charcoal kiln sits along a short woodland trail. The beehive-shaped structure once converted huge amounts of local wood into charcoal for industry and is among the best-preserved examples of its type in New England.', 'open', null, 'https://www.atlasobscura.com/places/hawley-beehive-kiln', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haymarket Martyrs'' Monument', 'haymarket-martyrs-monument', 'weird-history', 41.8698, -87.81977, 'Forest Park', 'IL', 'A National Historic Landmark monument over the graves of men executed after the Haymarket affair, central to international labor history.', 'limited', null, 'https://www.nps.gov/places/haymarket-martyrs-monument.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Heart of Dixie Railroad Museum', 'heart-of-dixie-railroad-museum', 'weird-history', 33.09945, -86.75075, 'Calera', 'AL', 'Alabama’s official railroad museum maintains locomotives, passenger cars, cabooses, depots and operating excursion trains. Train rides occur on selected dates, while the grounds and museum collections preserve multiple eras of rail travel.', 'limited', null, 'https://hodrrm.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hearthstone Castle', 'hearthstone-castle', 'weird-history', 41.3781, -73.44849, 'Danbury', 'CT', 'A crumbling stone castle built in the 1890s stands inside Tarrywile Park. The surrounding park is public, but the deteriorated castle itself is fenced and closed to entry, making this a legal exterior-view ruins stop rather than an urban-exploration site.', 'limited', null, 'https://www.atlasobscura.com/places/hearthstone-castle', '2026-09-08T18:47:23.721893+00:00', null, 'https://tarrywile.com/', null, null, null, 'America/New_York'),
  ('Hearthstone Historic House Museum', 'hearthstone-historic-house-museum', 'weird-history', 44.2546, -88.4147, 'Appleton', 'WI', 'Built in 1882, Hearthstone became one of the first residences in the world powered by a centrally located hydroelectric station using the Edison system. Restored interiors preserve both Victorian domestic life and the startling early arrival of electric lighting.', 'limited', null, 'https://www.hearthstonemuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.hearthstonemuseum.org/', null, null, null, 'America/Chicago'),
  ('Heigold House Facade', 'heigold-house-facade', 'weird-history', 38.26394, -85.72503, 'Louisville', 'KY', 'Only the intricately carved stone facade remains from German immigrant Christian Heigold''s nineteenth-century Louisville home. Covered in patriotic inscriptions and sculpted imagery created during a period of intense anti-immigrant sentiment, the facade was saved from demolition and relocated as a freestanding public monument.', 'open', null, 'https://www.atlasobscura.com/places/heigold-house', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('Henry B. Plant Museum', 'henry-b-plant-museum', 'weird-history', 27.94718, -82.46528, 'Tampa', 'FL', 'Former Gilded Age hotel with Moorish minarets, period rooms, and eccentric Victorian collections.', 'limited', null, 'https://www.ut.edu/plantmuseum/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Henry Morrison Flagler Museum', 'henry-morrison-flagler-museum', 'weird-history', 26.71477, -80.0368, 'Palm Beach', 'FL', 'Gilded Age mansion built by the railroad magnate who transformed Florida''s east coast.', 'limited', null, 'https://flaglermuseum.us/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Henry River Mill Village — District 12', 'henry-river-mill-village-district-12', 'weird-history', 35.69566, -81.42919, 'Hickory', 'NC', 'This preserved early-20th-century textile village became internationally recognizable after serving as District 12 in the first Hunger Games film. The property is privately operated and offers authorized tours; it should not be treated as an abandoned site open for unsupervised exploration. Location source: https://mapcarta.com/N9621020497', 'limited', null, 'https://henryrivermillvillage.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Her Vacant Chair', 'her-vacant-chair', 'weird-history', 41.92012, -71.08924, 'Taunton', 'MA', 'The grave of three-year-old Pearl French is marked by a carved stone rocking chair, an unusually intimate Victorian-style memorial. Local stories later attached ghostly movement and other paranormal claims to the chair, but those remain folklore. Visit the cemetery respectfully during open hours.', 'limited', null, 'https://www.atlasobscura.com/places/her-vacant-chair', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Heritage Canyon', 'heritage-canyon', 'weird-history', 41.87717, -90.16465, 'Fulton', 'IL', 'An abandoned quarry transformed into a wooded village of reconstructed historic buildings, machinery, and small-town scenes.', 'open', null, 'https://www.cityoffulton.us/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('High Point Monument', 'high-point-monument', 'weird-history', 41.32095, -74.66162, 'Montague Township', 'NJ', 'A 220-foot obelisk crowns New Jersey''s highest point at 1,803 feet above sea level. Dedicated to New Jersey veterans, the monument can be reached through High Point State Park, with interior access and road conditions varying by season.', 'limited', null, 'https://dep.nj.gov/parksandforests/state-park/high-point-state-park/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Highball Signal', 'highball-signal', 'weird-history', 38.45648, -75.57796, 'Delmar', 'DE', 'A rare old-style railroad ball signal survives in Delmar''s Railroad Park. The device used a raised or lowered ball to communicate train movement and is an unusual piece of pre-electric railroad signaling technology.', 'open', null, 'https://www.atlasobscura.com/things-to-do/delaware/places', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Highway 61 Blues Museum', 'highway-61-blues-museum', 'weird-history', 33.40573, -90.89755, 'Leland', 'MS', 'A community museum devoted to blues musicians connected to Leland and the surrounding Delta. Current Mississippi Blues Trail information lists it as open by appointment, so travelers should contact it before arrival.', 'limited', null, 'https://msbluestrail.org/museums', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hillandale Bridge', 'hillandale-bridge', 'weird-history', 41.59097, -81.49117, 'Euclid', 'OH', 'This abandoned concrete bridge was built for a 1920s residential development that never materialized, leaving a substantial bridge standing alone in the woods. It can be reached from trails in the Hillandale Park area, but the structure is weathered and damaged, so visitors should stay on established legal access routes and avoid climbing unsafe sections.', 'limited', null, 'https://www.atlasobscura.com/places/hillandale-bridge', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hillside Cemetery', 'hillside-cemetery', 'weird-history', 42.70089, -73.12115, 'North Adams', 'MA', 'This eighteenth-century cemetery is filled with unusually sculptural monuments, including tree-shaped stones and the elaborate Tinker Mausoleum. It functions almost like an outdoor art museum despite having few nationally famous burials.', 'limited', null, 'https://www.atlasobscura.com/places/hillside-cemetery', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hindenburg Crash Site', 'hindenburg-crash-site', 'weird-history', 40.03171, -74.32235, 'Lakehurst', 'NJ', 'The German airship Hindenburg caught fire while attempting to land at Lakehurst in 1937, killing 36 people and helping end the era of passenger zeppelins. The marked crash site lies inside an active military installation, so visitors can only access it through approved tours and base procedures.', 'limited', null, 'https://www.jbmdl.jb.mil/About-Us/History/Hindenburg/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hindostan Falls Ghost Town', 'hindostan-falls-ghost-town', 'weird-history', 38.6245, -86.85083, 'Shoals', 'IN', 'Hindostan was once a promising early Indiana settlement on the White River before disease and economic decline emptied the community in the 1820s. Little of the town survives today, but the public recreation area at Hindostan Falls preserves the landscape and remnants associated with one of the state''s earliest ghost towns.', 'open', null, 'https://www.in.gov/dnr/fish-and-wildlife/properties/hindostan-falls-public-fishing-area/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('Historic Blakeley State Park', 'historic-blakeley-state-park', 'weird-history', 30.74982, -87.91083, 'Spanish Fort', 'AL', 'Wooded roads and earthworks preserve the abandoned town of Blakeley and the battlefield of one of the Civil War’s final major engagements. Foundations, cemetery areas and old streets survive beneath the forest.', 'open', null, 'https://www.blakeleypark.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Historic Bridge Park', 'historic-bridge-park', 'weird-history', 42.29212, -85.1148, 'Battle Creek', 'MI', 'This county park functions as an open-air museum of rescued historic bridges, including several restored metal truss spans moved here from elsewhere in Michigan. Visitors can walk across the bridges, follow riverside trails and also see an unusual stone-and-concrete railroad overpass.', 'open', null, 'https://historicbridges.org/info/bridgepark/index.php', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Historic Pithole City', 'historic-pithole-city', 'weird-history', 41.52089, -79.58699, 'Cornplanter Township', 'PA', 'Pithole exploded into a booming oil town after nearby wells struck petroleum in 1865 and collapsed almost as quickly when the boom moved elsewhere. Little of the original city remains above ground, but paths, foundations, interpretation and a seasonal visitor center preserve one of Pennsylvania''s most dramatic ghost towns.', 'limited', null, 'https://www.drakewell.org/plan-your-visit/what-to-see-and-do', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Rugby', 'historic-rugby', 'weird-history', 36.36108, -84.70242, 'Rugby', 'TN', 'English author Thomas Hughes founded Rugby in 1880 as a utopian colony for younger sons of British families. Surviving Victorian buildings, a historic library, cemetery and preserved streets make the village a remarkably intact remnant of an ambitious social experiment.', 'limited', null, 'https://historicrugby.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Historic Village at Allaire', 'historic-village-at-allaire', 'weird-history', 40.16149, -74.12707, 'Wall Township', 'NJ', 'Allaire preserves an early nineteenth-century iron-producing company town complete with workers'' homes, workshops, a general store and other village buildings. Demonstrations and scheduled programs interpret the unusual self-contained industrial community that once operated here.', 'limited', null, 'https://allairevillage.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hollensbury Spite House', 'hollensbury-spite-house', 'weird-history', 38.80731, -77.04506, 'Alexandria', 'VA', 'John Hollensbury built this exceptionally narrow house in 1830 to fill an alley beside his home, reportedly after growing tired of people and wagons using the passage. The roughly seven-foot-wide residence still stands at 523 Queen Street, but it is a private home and should be viewed only from the public sidewalk.', 'private', null, 'https://www.atlasobscura.com/places/hollensbury-spite-house', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Holliston Moon Tree', 'holliston-moon-tree', 'weird-history', 42.20739, -71.4272, 'Holliston', 'MA', 'This American sycamore grew from a seed carried around the Moon aboard Apollo 14 in 1971. Massachusetts received two Moon Tree seeds for the Bicentennial; the other tree died, leaving Holliston''s specimen as the state''s surviving living link to the mission.', 'open', null, 'https://www.atlasobscura.com/places/apollo-14-holliston-moon-tree', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hollow Earth Monument', 'hollow-earth-monument', 'weird-history', 39.39477, -84.56241, 'Hamilton', 'OH', 'This unusual monument marks the grave of John Cleves Symmes Jr., the nineteenth-century Army officer who argued that the Earth was hollow and accessible through enormous openings near the poles. His son erected the stone topped with a hollow globe, and it remains publicly accessible in Hamilton''s Ludlow Park.', 'open', null, 'https://www.atlasobscura.com/places/hollow-earth-monument', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hollywood Cafe', 'hollywood-cafe', 'weird-history', 34.81733, -90.31555, 'Tunica Resorts', 'MS', 'A Delta restaurant/juke-joint landmark connected to the song "Walking in Memphis" and to the region''s blues-tourism history. Its roadside neon and long-running music associations make it more than a generic restaurant stop.', 'open', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hollywood Mounds', 'hollywood-mounds', 'weird-history', 34.77255, -90.3721, 'Tunica', 'MS', 'A large Mississippian ceremonial complex where remote sensing has revealed traces of many vanished boundary mounds around a raised plaza. The surviving mound site should be treated as view-only from public access points.', 'roadside', null, 'https://trails.mdah.ms.gov/hollywood', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Holmdel Horn Antenna', 'holmdel-horn-antenna', 'weird-history', 40.39072, -74.18484, 'Holmdel Township', 'NJ', 'This enormous horn-shaped radio antenna was used by Arno Penzias and Robert Wilson when they accidentally detected the cosmic microwave background, a key piece of evidence for the Big Bang. The National Historic Landmark survives on private property with access dependent on current site arrangements.', 'limited', null, 'https://www.atlasobscura.com/places/holmdel-horn-antenna', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Holsten''s — The Sopranos Final Booth', 'holstens-the-sopranos-final-booth', 'weird-history', 40.82828, -74.18663, 'Bloomfield', 'NJ', 'Holsten''s old-fashioned ice-cream parlor became television history when its corner booth was used for the final scene of The Sopranos. The restaurant remains an active local business and openly acknowledges its connection with the famously ambiguous ending.', 'open', null, 'https://www.atlasobscura.com/places/holstens', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Holt Cemetery', 'holt-cemetery', 'weird-history', 29.98455, -90.10482, 'New Orleans', 'LA', 'Holt Cemetery is unusual in New Orleans for its mostly in-ground burials, handmade markers and intensely personal memorial decorations. It remains an active cemetery and should be visited only during city-posted hours.', 'limited', null, 'https://nola.gov/cemeteries/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hoopar Brothers Gravestone', 'hoopar-brothers-gravestone', 'weird-history', 40.50042, -74.39606, 'Piscataway', 'NJ', 'An unusual double gravestone commemorates two young brothers and uses striking carved imagery characteristic of early American funerary art. It survives in the historic Piscatawaytown Burial Ground beside St. James Church.', 'open', null, 'https://www.atlasobscura.com/places/hoopar-brothers-gravestone', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hooper', 'hooper', 'weird-history', 34.26614, -112.382945, 'Mayer', 'AZ', 'A camp in the same Yavapai County district as the earlier settlement of Meesville, whose buildings were reportedly moved here when mining revived around 1900. No developed attraction and no well-documented surviving structures — a remote locality on the Senator Highway corridor.', 'limited', null, 'https://azgw.org/yavapai/ghosttowns.html', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Hoosac Tunnel East Portal', 'hoosac-tunnel-east-portal', 'weird-history', 42.67552, -72.99843, 'Florida', 'MA', 'The nearly five-mile Hoosac Tunnel earned the nickname ''Bloody Pit'' during its brutal nineteenth-century construction, when roughly 200 workers died. Stories of apparitions and unexplained voices followed the disaster history. The tunnel remains an active railroad: view the portal only from a safe lawful area and never enter or walk the tracks.', 'roadside', null, 'https://www.atlasobscura.com/places/hoosac-tunnel', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hootie & the Blowfish Monument', 'hootie-the-blowfish-monument', 'weird-history', 33.99846, -81.01598, 'Columbia', 'SC', 'A large stainless-steel monument in Five Points commemorates Hootie & the Blowfish, whose members met while attending the University of South Carolina. Lyrics, names, and references to the band are incorporated into a sculpture that is much larger than the average hometown music plaque.', 'open', null, 'https://www.atlasobscura.com/places/hootie-the-blowfish-monument-columbia', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hope Cemetery', 'hope-cemetery', 'weird-history', 44.21072, -72.49942, 'Barre', 'VT', 'Barre''s granite industry turned this cemetery into an outdoor gallery of unusually elaborate gravestones carved by local stoneworkers. Memorials include life-size figures, airplanes, soccer balls, race cars and other personalized sculptures cut from local granite.', 'open', null, 'https://www.atlasobscura.com/places/hope-cemetery', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hotel Victory Ruins', 'hotel-victory-ruins', 'weird-history', 41.64556, -82.83816, 'Put-in-Bay', 'OH', 'The enormous Hotel Victory opened on South Bass Island in the 1890s and burned in 1919, leaving behind foundations, portions of its pool and scattered structural remains. The ruins lie around South Bass Island State Park''s campground area, and some are within camper-only sections, so visitors should follow park access rules rather than wandering through occupied campsites.', 'limited', null, 'https://www.atlasobscura.com/places/hotel-victory-ruins', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('House of Refuge Museum', 'house-of-refuge-museum', 'weird-history', 27.18404, -80.16059, 'Stuart', 'FL', 'Last surviving shipwreck-rescue station of its kind on Florida''s Atlantic coast.', 'limited', null, 'https://hsmc-fl.com/house-of-refuge/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Howard Tunnel', 'howard-tunnel', 'weird-history', 39.89148, -76.7496, 'North Codorus Township', 'PA', 'Built in the 1830s, Howard Tunnel is one of the oldest surviving railroad tunnels in the United States and remains part of an active rail corridor. The York County Heritage Rail Trail passes beside and through the historic corridor, so visitors should use the designated trail and never walk on the active tracks.', 'limited', null, 'https://www.atlasobscura.com/places/howard-tunnel', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('H.P. Lovecraft House', 'hp-lovecraft-house', 'weird-history', 41.82856, -71.4052, 'Providence', 'RI', 'Lovecraft lived at 65 Prospect Street during the final years of his life, and the house appears in altered form in his story "The Haunter of the Dark." It is a private residence rather than a museum. OddWay visitors should view it only from the public sidewalk and should not disturb the occupants.', 'private', null, 'https://www.atlasobscura.com/places/hp-lovecraft-house', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('H.P. Lovecraft''s Grave', 'hp-lovecrafts-grave', 'weird-history', 41.854, -71.3811, 'Providence', 'RI', 'Horror writer H.P. Lovecraft is buried with his parents in Swan Point Cemetery beneath a modest stone bearing the phrase "I AM PROVIDENCE." Fans routinely leave notes, coins, drawings and other small tributes at the grave. Visit only during cemetery hours and follow cemetery rules.', 'limited', null, 'https://www.atlasobscura.com/places/hp-lovecrafts-grave', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Huguenot Cemetery', 'huguenot-cemetery', 'weird-history', 29.89957, -81.31622, 'St. Augustine', 'FL', 'Historic Protestant cemetery near the old city gate with yellow-fever-era burials.', 'open', null, 'https://www.citystaug.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Humpback Covered Bridge', 'humpback-covered-bridge', 'weird-history', 37.80054, -80.04711, 'Covington', 'VA', 'Built in 1857, this wooden bridge arches noticeably higher at its center than at either end, giving it the humpback profile that makes it unique. It is Virginia''s oldest surviving covered bridge and now stands in a public wayside park where travelers can walk through it rather than drive across it.', 'open', null, 'https://www.loc.gov/pictures/item/va0239/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Huntsville Depot Museum', 'huntsville-depot-museum', 'weird-history', 34.73454, -86.58991, 'Huntsville', 'AL', 'The surviving Huntsville Depot was once a major Memphis & Charleston Railroad stop and was used during the Civil War. Preserved rail-era spaces and exhibits document how the building moved soldiers, civilians and freight through north Alabama.', 'limited', null, 'https://earlyworks.com/huntsville-depot/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hurricane Katrina Memorial — Biloxi Town Green', 'hurricane-katrina-memorial-biloxi-town-green', 'weird-history', 30.39333, -88.8864, 'Biloxi', 'MS', 'A memorial dedicated in 2006 to Mississippi Gulf Coast residents killed by Hurricane Katrina. Its black granite wall, wave mosaic and case of storm-recovered personal objects make the scale of the 2005 disaster tangible in the center of Biloxi.', 'open', null, 'https://discover.biloxi.ms.us/town-green-katrina-memorial/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hut of Refuge', 'hut-of-refuge', 'weird-history', 42.32584, -70.92557, 'Hull', 'MA', 'A small lifesaving shelter survives on isolated Peddocks Island from the era when shipwreck survivors needed emergency refuge along Boston Harbor. Reaching it requires seasonal island access, making the journey part of the stop.', 'limited', null, 'https://www.atlasobscura.com/places/hut-of-refuge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ice Cream Sundae Birthplace Marker — Washington House Museum', 'ice-cream-sundae-birthplace-marker-washington-house-museum', 'weird-history', 44.15389, -87.56933, 'Two Rivers', 'WI', 'Two Rivers claims that the first ice cream sundae was served here in 1881. A marker and the Washington House Museum preserve the local version of the origin story, which remains disputed by other communities but has become a durable piece of American food folklore.', 'limited', null, 'https://www.tworiverseconomicdevelopment.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.tworivershistory.org/', null, null, null, 'America/Chicago'),
  ('Ichetucknee Springs State Park', 'ichetucknee-springs-state-park', 'weird-history', 29.98442, -82.76148, 'Fort White', 'FL', 'Crystal springs with submerged archaeology and remains of a Spanish mission and early phosphate mining.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/ichetucknee-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Illinois Iron Furnace', 'illinois-iron-furnace', 'weird-history', 37.4995, -88.32791, 'Rosiclare area', 'IL', 'A reconstructed 19th-century stone blast furnace recalls the brief iron industry that once operated deep in what is now Shawnee National Forest.', 'open', null, 'https://www.fs.usda.gov/recarea/shawnee/recarea/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Indianapolis Moon Tree', 'indianapolis-moon-tree', 'weird-history', 39.7683, -86.162, 'Indianapolis', 'IN', 'This sycamore grew from a seed carried around the Moon aboard Apollo 14 in 1971 as part of astronaut Stuart Roosa''s famous seed experiment. Planted in Indianapolis during the U.S. Bicentennial era, it is one of the surviving "Moon Trees" scattered across the country.', 'open', null, 'https://www.atlasobscura.com/places/indianapolis-moon-tree', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('International Mother''s Day Shrine', 'international-mothers-day-shrine', 'weird-history', 39.34073, -80.01854, 'Grafton', 'WV', 'The former Andrews Methodist Episcopal Church hosted the first official Mother''s Day observance on May 10, 1908 after Anna Jarvis began campaigning for a holiday honoring mothers. The 1873 church became the International Mother''s Day Shrine in 1962 and now operates as a seasonal historic attraction and museum.', 'limited', null, 'https://www.internationalmothersdayshrine.org/about-us', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Iron Mountain Iron Mine', 'iron-mountain-iron-mine', 'weird-history', 45.78242, -87.86402, 'Vulcan', 'MI', 'Visitors ride a small underground train into a former iron mine and walk through cool, dark workings beneath the Upper Peninsula. The combination of mining machinery, underground passages and old-fashioned tour presentation makes it a classic regional roadside attraction.', 'limited', null, 'https://www.michigan.org/property/iron-mountain-iron-mine', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Menominee'),
  ('Iroquois Theatre Fire Site / Death Alley', 'iroquois-theatre-fire-site-death-alley', 'weird-history', 41.88485, -87.62887, 'Chicago', 'IL', 'The area behind today''s Nederlander Theatre marks the 1903 Iroquois Theatre disaster, where more than 600 people died and ghost stories still linger.', 'roadside', null, 'https://www.choosechicago.com/blog/tours-attractions/chicago-most-haunted-places/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Italian Hall Memorial Park', 'italian-hall-memorial-park', 'weird-history', 47.24834, -88.45522, 'Calumet', 'MI', 'On Christmas Eve 1913, a false cry of fire caused a deadly panic during a striking miners'' holiday party at Italian Hall, killing more than 70 people, most of them children. The building was later demolished, but its original stone arch was preserved in this memorial park alongside the names of the victims.', 'open', null, 'https://www.nps.gov/places/italian-hall-memorial-park.htm', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Ivy Green — Helen Keller Birthplace', 'ivy-green-helen-keller-birthplace', 'weird-history', 34.73795, -87.70582, 'Tuscumbia', 'AL', 'Helen Keller was born at this preserved family property in 1880, and the grounds include the cottage where she lived and the water pump associated with her breakthrough in learning language. The site preserves artifacts and family spaces connected to Keller and Anne Sullivan.', 'open', null, 'https://www.helenkellerbirthplace.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Iwo Jima Survivors Memorial Park', 'iwo-jima-survivors-memorial-park', 'weird-history', 41.6982, -72.7586, 'Newington', 'CT', 'A dramatic bronze monument recreates the famous flag-raising on Iwo Jima and specifically honors Connecticut servicemen who fought in the battle. The park was developed with the involvement of surviving veterans and includes additional memorial elements.', 'open', null, 'https://www.roadsideamerica.com/story/7831', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('J Lorraine, Texas Ghost Town', 'j-lorraine-texas-ghost-town', 'weird-history', 30.332325, -97.509487, 'Manor', 'TX', 'J. Lorraine Ghost Town is a recreated Old West roadside attraction outside Austin, built with western storefronts, props and rustic structures meant to evoke a fictional frontier settlement. It is a playful man-made ghost town rather than an authentically abandoned community, with access depending on the property''s posted hours and events.', 'limited', null, 'https://ghosttownaustin.com/', '2026-09-05T22:12:28.444612+00:00', null, 'http://www.ghosttownaustin.com', '+1-512-922-2683', 'way', 962329436, 'America/Chicago'),
  ('Jack Daniel Distillery', 'jack-daniel-distillery', 'weird-history', 35.2836, -86.37013, 'Lynchburg', 'TN', 'The distillery occupies an enormous complex in tiny Lynchburg and still uses the cave spring that helped determine its location. Ticketed tours explain charcoal mellowing, barrelhouses and the industrial process behind one of Tennessee''s most globally recognized products.', 'limited', null, 'https://www.jackdaniels.com/en-us/visit-us', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jack Kerouac House', 'jack-kerouac-house', 'weird-history', 28.56331, -81.37868, 'Orlando', 'FL', 'Small house where Beat writer Jack Kerouac lived when On the Road became a sensation.', 'limited', null, 'https://kerouacproject.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jack Kerouac''s Grave', 'jack-kerouacs-grave', 'weird-history', 42.61808, -71.30747, 'Lowell', 'MA', 'Beat writer Jack Kerouac rests beneath an understated flat marker in Lowell''s Edson Cemetery. Admirers have traditionally left pens, cigarettes, notes and other offerings at the grave. Visit only during cemetery hours and leave the site undisturbed.', 'limited', null, 'https://www.atlasobscura.com/places/jack-kerouacs-grave', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jackson Grave Houses', 'jackson-grave-houses', 'weird-history', 36.40305, -77.3767, 'Jackson', 'NC', 'Several graves in this eastern North Carolina cemetery are enclosed by small house-like wooden structures rather than ordinary markers alone. These “grave houses” preserve a burial tradition once found more widely in parts of the American South but now rarely seen.', 'open', null, 'https://www.atlasobscura.com/places/jackson-grave-houses', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jaketown Mounds', 'jaketown-mounds', 'weird-history', 33.2371, -90.487, 'Belzoni', 'MS', 'A nationally significant archaeological site with evidence of long-distance trade and occupation stretching back thousands of years. Three of the many recorded mounds remain visible from the roadside; stay in designated public areas.', 'roadside', null, 'https://trails.mdah.ms.gov/jaketown', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('James Chaney Grave', 'james-chaney-grave', 'weird-history', 32.36431, -88.70366, 'Meridian', 'MS', 'The grave of civil-rights worker James Chaney, murdered in 1964 with Andrew Goodman and Michael Schwerner during Freedom Summer. This is a cemetery memorial stop; visit respectfully and do not treat the grave as spectacle.', 'open', null, 'https://crdl.usg.edu/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('James Dean''s Grave', 'james-deans-grave', 'weird-history', 40.43309, -85.64503, 'Fairmount', 'IN', 'James Dean was returned to his hometown after his fatal 1955 automobile crash and buried in Park Cemetery north of Fairmount. Fans still visit the simple headstone, often leaving small memorial items or lipstick marks, making the cemetery one of the most enduring pilgrimage sites connected to the actor.', 'open', null, 'https://www.roadsideamerica.com/tip/460', '2026-09-08T13:34:34.826362+00:00', null, 'https://showmegrantcounty.com/park-cemetery/', null, null, null, 'America/Indiana/Indianapolis'),
  ('James DeWolf Burial Mound', 'james-dewolf-burial-mound', 'weird-history', 41.66495, -71.25859, 'Bristol', 'RI', 'A large earthen burial mound in Juniper Hill Cemetery contains the remains of James DeWolf, a U.S. senator who became enormously wealthy through the transatlantic slave trade. The unusual family tomb was later broken into, with stories that thieves sought valuables and even gold dental work. Visit respectfully during cemetery hours.', 'limited', null, 'https://www.roadsideamerica.com/tip/37927', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('James Rumsey Monument', 'james-rumsey-monument', 'weird-history', 39.43288, -77.79913, 'Shepherdstown', 'WV', 'This 75-foot monument honors inventor James Rumsey, who demonstrated an early steam-powered boat on the Potomac River at Shepherdstown in 1787. The monument stands in a public park overlooking the river and marks one of America''s lesser-known early experiments with steam navigation.', 'open', null, 'https://www.canaltrust.org/pyv/james-rumsey-monument-and-park/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jean Baptiste Charbonneau Grave', 'jean-baptiste-charbonneau-grave', 'weird-history', 42.951943, -117.339185, 'Danner', 'OR', 'The infant who travelled with Sacagawea and the Lewis and Clark expedition died near Inskip Station in 1866, taken ill crossing the Owyhee country. His grave was rediscovered in the twentieth century, dedicated in 1971 and listed on the National Register in 1973. The signed site is reached by gravel road southwest of Jordan Valley — in Oregon, not Idaho.', 'limited', null, 'https://traveloregon.com/things-to-do/culture-history/historic-sites-oregon-trail/jean-baptiste-charbonneau-grave-site/', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Jeff Busby / Little Mountain', 'jeff-busby-little-mountain', 'weird-history', 33.41705, -89.26983, 'Ackerman', 'MS', 'A Natchez Trace stop on one of Mississippi''s higher natural points, with a short drive and trail to the top of Little Mountain. Its isolation, old-road setting and elevated view make it a distinctive break from the surrounding Trace landscape.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jefferson Davis Monument', 'jefferson-davis-monument', 'weird-history', 36.84194, -87.30056, 'Fairview', 'KY', 'A 351-foot concrete obelisk marks the Kentucky birthplace of Jefferson Davis, president of the Confederate States of America. The enormous monument was constructed between 1917 and 1924; interpretation of the site should place Davis and the Confederacy within the history of slavery, secession and the Civil War rather than treating the monument as neutral commemoration.', 'open', null, 'https://parks.ky.gov/explore/jefferson-davis-state-historic-site-7794', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jersey City and Harsimus Cemetery', 'jersey-city-and-harsimus-cemetery', 'weird-history', 40.72717, -74.05517, 'Jersey City', 'NJ', 'Founded in 1829, this sprawling historic cemetery contains old crypts, hillside graves and layers of Jersey City history. In recent years goats have also been used seasonally to control invasive vegetation, adding an unusual living element to the preservation work.', 'limited', null, 'https://www.jerseycitycemetery.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jesse Owens Memorial Park & Museum', 'jesse-owens-memorial-park-museum', 'weird-history', 34.43836, -87.16796, 'Oakville', 'AL', 'The park honors Olympic champion Jesse Owens near his birthplace with a museum, statue, track features and a replica of the sharecropper cabin where his family lived. It gives a physical route point to a globally significant Alabama-born athlete.', 'open', null, 'https://jesseowensmemorialpark.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('JFK Rejected Grave Slab', 'jfk-rejected-grave-slab', 'weird-history', 41.48908, -71.31463, 'Newport', 'RI', 'Outside the Boys & Girls Club sits a granite prototype created during development of President John F. Kennedy''s grave memorial. Newport stonecarver John E. Benson produced the slab using words from Kennedy''s inaugural address, but the design was not used at Arlington National Cemetery. The discarded prototype survives as an unexpectedly important artifact in an ordinary city setting. Secondary source: https://admiralsimsnewport.com/off-the-beaten-path-newport-ri/', 'open', null, 'https://www.roadsideamerica.com/story/46290', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jim Varney''s Grave', 'jim-varneys-grave', 'weird-history', 38.06074, -84.51042, 'Lexington', 'KY', 'Actor Jim Varney, best remembered as Ernest P. Worrell and the original voice of Slinky Dog, is buried in Lexington Cemetery. Fans frequently leave Mello Yello cans, photos and other Ernest-related objects at his grave.', 'open', null, 'https://www.atlasobscura.com/places/jim-varney-grave', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jimmie Rodgers Museum', 'jimmie-rodgers-museum', 'weird-history', 32.36898, -88.70013, 'Meridian', 'MS', 'A museum devoted to Meridian native Jimmie Rodgers and his foundational influence on country music, including memorabilia connected to the "Singing Brakeman." Current hours are limited compared with a large daily museum, so check before visiting.', 'limited', null, 'https://msbluestrail.org/museums', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.jimmierodgers.com/', null, null, null, 'America/Chicago'),
  ('John Deere Historic Site', 'john-deere-historic-site', 'weird-history', 41.89608, -89.41592, 'Grand Detour', 'IL', 'The reconstructed blacksmith shop and archaeological remains mark where John Deere developed the polished steel plow that transformed Midwestern farming.', 'limited', null, 'https://www.deere.com/en/connect-with-john-deere/visit-john-deere/historic-site/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('John Dillinger''s Grave', 'john-dillingers-grave', 'weird-history', 39.82212, -86.16484, 'Indianapolis', 'IN', 'Bank robber John Dillinger was killed by federal agents in Chicago in 1934 and returned to Indianapolis for burial in Crown Hill Cemetery. His granite grave has long attracted visitors interested in Depression-era outlaw history and has reportedly been replaced or repaired after decades of souvenir damage.', 'open', null, 'https://thetombstonetourist.com/graves/john-dillinger/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('John Ford Statue', 'john-ford-statue', 'weird-history', 43.65448, -70.25734, 'Portland', 'ME', 'Portland honors legendary director John Ford with a bronze statue showing him seated in a director’s chair with his trademark hat and pipe. Stones surrounding the sculpture recognize the films that earned Ford Academy Awards, linking an ordinary downtown corner to one of Hollywood’s most influential filmmakers.', 'open', null, 'https://www.atlasobscura.com/places/john-ford-statue', '2026-09-09T04:54:23.476824+00:00', null, 'https://www.publicartportland.org/project/the-john-ford-statue/', null, null, null, 'America/New_York'),
  ('John Gorrie Museum State Park', 'john-gorrie-museum-state-park', 'weird-history', 29.72506, -84.98548, 'Apalachicola', 'FL', 'Museum honoring the doctor whose ice-making experiments helped lead to mechanical refrigeration and air conditioning.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/john-gorrie-museum-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Harvard ''Statue of Three Lies''', 'john-harvard-statue-of-three-lies', 'weird-history', 42.37432, -71.11725, 'Cambridge', 'MA', 'Harvard''s famous bronze founder statue is nicknamed the Statue of Three Lies: the figure is not actually modeled on John Harvard, he was not technically the university''s founder, and the inscribed founding date does not match the institution''s history precisely. Students and tourists also rub its shoe for luck.', 'open', null, 'https://www.atlasobscura.com/places/john-harvard-statue-of-three-lies', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Paul Jones Crypt', 'john-paul-jones-crypt', 'weird-history', 38.98069, -76.48184, 'Annapolis', 'MD', 'Revolutionary War naval hero John Paul Jones died in Paris in 1792, disappeared beneath a later development, and was rediscovered more than a century afterward before being returned to the United States. His ornate black-and-white marble sarcophagus now sits beneath the U.S. Naval Academy Chapel; visitors must follow Naval Academy identification and security rules.', 'limited', null, 'https://www.atlasobscura.com/places/john-paul-jones-crypt', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Rogers Vinton Cannonball Grave', 'john-rogers-vinton-cannonball-grave', 'weird-history', 41.85257, -71.38294, 'Providence', 'RI', 'Army officer John Rogers Vinton was killed during the Mexican-American War, and his Swan Point Cemetery monument incorporates a cannonball into the memorial. The unusual detail has made the grave one of the cemetery''s most memorable military monuments. The coordinate routes to Swan Point; ask cemetery staff for current directions to the Vinton monument and follow photography rules. Secondary source: https://www.roadsideamerica.com/tip/61358', 'limited', null, 'https://swanpointcemetery.com/the-estate/art-and-architecture/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('John T. Scopes Grave', 'john-t-scopes-grave', 'weird-history', 37.08454, -88.60321, 'Paducah', 'KY', 'John T. Scopes, the teacher prosecuted in the famous 1925 "Monkey Trial" for teaching evolution in Tennessee, was a Paducah native and is buried in Oak Grove Cemetery. A historical marker near the cemetery entrance explains the trial and its role in the continuing American conflict over science, religion and education.', 'open', null, 'https://map-gis.paducahky.gov/node/2861', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('John Wilkes Booth Grave', 'john-wilkes-booth-grave', 'weird-history', 39.30711, -76.606, 'Baltimore', 'MD', 'Lincoln assassin John Wilkes Booth is buried in the Booth family plot at Green Mount Cemetery beneath a small, deliberately unremarkable marker. Visitors often leave pennies on the stone, but the cemetery is an active burial ground and should only be visited during its posted daytime hours.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-john-wilkes-booth', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Johnson Cemetery Mound', 'johnson-cemetery-mound', 'weird-history', 34.74102, -90.3667, 'Tunica', 'MS', 'A prehistoric mound incorporated into a later historic cemetery landscape in the northern Delta. It is part of the Mississippi Mound Trail but should be experienced only from lawful public viewing areas.', 'roadside', null, 'https://trails.mdah.ms.gov/johnson', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Johnsonville Village', 'johnsonville-village', 'weird-history', 41.49496, -72.46652, 'East Haddam', 'CT', 'A nineteenth-century mill village of old houses and industrial buildings survives along the Moodus River after decades of abandonment and repeated attempts at redevelopment. The village is now private property, so OddWay visitors should view only from lawful public roads and never enter buildings or grounds without permission.', 'private', null, 'https://www.atlasobscura.com/places/johnsonville-village', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Joliet Iron Works Historic Site', 'joliet-iron-works-historic-site', 'weird-history', 41.54008, -88.07932, 'Joliet', 'IL', 'Trails wind through the heavy foundations and archaeological remains of a once-enormous iron and steel complex beside the old canal corridor.', 'open', null, 'https://www.reconnectwithnature.org/preserves-trails/preserves/joliet-iron-works-historic-site/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jonathan Walker''s Branded Hand Grave', 'jonathan-walkers-branded-hand-grave', 'weird-history', 43.226, -86.23446, 'Muskegon', 'MI', 'Abolitionist sea captain Jonathan Walker was branded on his right hand with the letters "SS" for "slave stealer" after attempting to help seven enslaved people escape from Florida in 1844. His monument stands just inside Evergreen Cemetery and prominently reproduces the branded hand that became a symbol of the antislavery movement.', 'open', null, 'https://www.nps.gov/people/jonathan-walker.htm', '2026-09-08T14:53:55.160019+00:00', null, 'https://muskegon-mi.gov/city-services/public-works/cemetery/evergreen-cemetery-and-potters-field/', null, null, null, 'America/Detroit'),
  ('Joseph Smith Birthplace Memorial', 'joseph-smith-birthplace-memorial', 'weird-history', 43.82347, -72.47308, 'Royalton', 'VT', 'A tall polished-granite monument marks the Vermont birthplace of Joseph Smith, founder of the Latter Day Saint movement. The memorial rises dramatically from a wooded hillside near the site of the Smith family''s former home.', 'open', null, 'https://www.atlasobscura.com/places/joseph-smith-birthplace-memorial', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Josie Langmaid Monument', 'josie-langmaid-monument', 'weird-history', 43.14727, -71.44611, 'Suncook', 'NH', 'A tall monument commemorates Josie Langmaid, a 17-year-old murdered in 1875 in a case that shocked New Hampshire. The inscription records unusually direct details of her death, making the memorial far more explicit than most nineteenth-century grave markers. Treat the site as a memorial to a victim rather than a novelty.', 'limited', null, 'https://www.atlasobscura.com/places/josie-langmaid-monument', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Judges Cave', 'judges-cave', 'weird-history', 41.33857, -72.96666, 'New Haven', 'CT', 'A jumble of boulders in West Rock became the hiding place of English regicides Edward Whalley and William Goffe after the restoration of King Charles II. The natural shelter is now marked as Judges Cave and can be reached by park trails.', 'open', null, 'https://www.atlasobscura.com/places/judges-cave', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Julius Sturgis Pretzel Bakery', 'julius-sturgis-pretzel-bakery', 'weird-history', 40.15655, -76.3013, 'Lititz', 'PA', 'Julius Sturgis opened his commercial pretzel bakery here in 1861, and the historic stone building still operates as a visitor attraction. Guided bakery tours explain early pretzel making and let visitors try forming the traditional pretzel shape by hand.', 'open', null, 'https://juliussturgis.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jupiter Inlet Lighthouse', 'jupiter-inlet-lighthouse', 'weird-history', 26.94875, -80.08218, 'Jupiter', 'FL', '1860 lighthouse on an ancient shell mound landscape with maritime and Seminole history.', 'limited', null, 'https://www.jupiterlighthouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('K-25 History Center', 'k-25-history-center', 'weird-history', 35.93141, -84.39285, 'Oak Ridge', 'TN', 'The museum interprets the enormous K-25 uranium-enrichment complex built for the Manhattan Project. Exhibits explain gaseous diffusion, secrecy and the industrial workforce while keeping visitors safely outside restricted federal areas.', 'open', null, 'https://k25historycenter.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Karl Jansky Radio Astronomy Monument', 'karl-jansky-radio-astronomy-monument', 'weird-history', 40.36514, -74.16357, 'Holmdel Township', 'NJ', 'A monument on the former Bell Labs property honors Karl Jansky, whose 1930s experiments detected radio waves from the Milky Way and helped create the field of radio astronomy. The stop connects an otherwise quiet corporate campus with a major scientific discovery.', 'open', null, 'https://www.atlasobscura.com/places/karl-jansky-monument', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Katahdin Iron Works', 'katahdin-iron-works', 'weird-history', 45.41601, -69.07226, 'Katahdin Iron Works Township', 'ME', 'A surviving blast furnace and charcoal kiln mark the remains of a remote ironmaking settlement that operated in the Maine woods during the 1800s. Access uses private-resource roads shared with logging traffic and may involve checkpoint fees and seasonal conditions.', 'limited', null, 'https://www.atlasobscura.com/places/katahdin-iron-works', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Katherine Johnson Statue', 'katherine-johnson-statue', 'weird-history', 38.38023, -81.76765, 'Institute', 'WV', 'West Virginia State University unveiled this seven-foot bronze statue of NASA mathematician and alumna Katherine Johnson in 2018. It stands on the university campus as a public monument to the woman whose calculations helped make early American spaceflight possible.', 'open', null, 'https://wvstateu.edu/news/west-virginia-state-university-alumnus-creates-las/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Katyń Massacre Memorial', 'katyn-massacre-memorial', 'weird-history', 40.71626, -74.03298, 'Jersey City', 'NJ', 'A dramatic bronze soldier pierced by a bayonet stands at Exchange Place as a memorial to Polish officers and others murdered by the Soviet secret police during the 1940 Katyń massacres. The disturbing imagery makes the monument intentionally difficult to ignore.', 'open', null, 'https://www.atlasobscura.com/places/katyn-massacre-memorial', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kaymoor Mine Site', 'kaymoor-mine-site', 'weird-history', 38.04529, -81.06775, 'Fayetteville', 'WV', 'Kaymoor was one of the New River Gorge''s major coal operations, and its abandoned mine complex, coke ovens and town remains survive on the gorge wall. These coordinates route to the Kaymoor Top trailhead; reaching the mine requires a steep hike, and access conditions can change during trail rehabilitation.', 'limited', null, 'https://www.nps.gov/neri/learn/historyculture/visiting-kaymoor.htm', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kelleys Island Glacial Grooves', 'kelleys-island-glacial-grooves', 'weird-history', 41.61363, -82.70539, 'Kelleys Island', 'OH', 'A retreating Ice Age glacier carved enormous parallel grooves into the limestone of Kelleys Island, leaving some of the largest and most accessible glacial striations in the world. A walkway surrounds the protected geological feature, but reaching it requires travel to the Lake Erie island, with ferry service varying by season and weather.', 'limited', null, 'https://kelleysisland.com/listing/glacial-grooves/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kelleys Island Winery Ruins', 'kelleys-island-winery-ruins', 'weird-history', 41.60142, -82.72943, 'Kelleys Island', 'OH', 'Stone ruins from Kelleys Island''s nineteenth-century wine industry survive near Maple Drive, remnants of an era when Lake Erie islands were major American grape-growing centers. The ruins are on private property, so they should be viewed only from the public road without entering the site.', 'private', null, 'https://www.atlasobscura.com/places/kelleys-island-winery-ruins', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kelly Ingram Park', 'kelly-ingram-park', 'weird-history', 33.51631, -86.81339, 'Birmingham', 'AL', 'This downtown park was a major gathering and confrontation point during the 1963 Birmingham Campaign. Sculptures and markers now interpret police dogs, fire hoses and youth demonstrators in the exact landscape where the events unfolded.', 'open', null, 'https://www.birminghamal.gov/parks', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kentucky Bend', 'kentucky-bend', 'weird-history', 36.53957, -89.47605, 'Tiptonville', 'KY', 'Kentucky Bend is a geographical oddity where a looping Mississippi River left a small piece of Kentucky surrounded by Tennessee and the river. Road access comes only through Tennessee, creating an isolated Kentucky pocket that feels disconnected from the rest of the state; travelers should remain on public roads and respect the surrounding farmland.', 'roadside', null, 'https://www.atlasobscura.com/places/kentucky-bend', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kerr Lock Ruins', 'kerr-lock-ruins', 'weird-history', 40.83718, -85.72538, 'Lagro', 'IN', 'Stone remains beside the Wabash River preserve part of a lock from the Wabash and Erie Canal, once one of the longest canal systems in North America. A public trail now passes the nineteenth-century masonry, allowing travelers to inspect infrastructure from a transportation network that almost completely disappeared.', 'open', null, 'https://www.atlasobscura.com/places/kerr-lock', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Keweenaw Rocket Range', 'keweenaw-rocket-range', 'weird-history', 47.4303, -87.71481, 'Copper Harbor', 'MI', 'At the remote tip of the Keweenaw Peninsula, this former launch site was used during the 1960s for small sounding rockets that collected meteorological data over Lake Superior. A marker and surviving traces commemorate Michigan''s little-known role in early rocket research, but reaching the site involves remote roads and conditions can be highly seasonal.', 'limited', null, 'https://www.atlasobscura.com/places/keweenaw-rocket-range', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Key Underwood Coon Dog Memorial Graveyard', 'key-underwood-coon-dog-memorial-graveyard', 'weird-history', 34.63, -87.96667, 'Cherokee', 'AL', 'Established in 1937, this remote cemetery is reserved for coonhounds and contains headstones ranging from simple markers to elaborate memorials. It is a genuine cemetery for working dogs, not a novelty replica, so visitors should treat the grounds respectfully.', 'open', null, 'https://www.coondogcemetery.com/index.html', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Key West Cemetery', 'key-west-cemetery', 'weird-history', 24.55573, -81.79315, 'Key West', 'FL', 'Historic above-ground cemetery known for unusual epitaphs, local legends, and elaborate tombs.', 'open', null, 'https://www.cityofkeywest-fl.gov/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Key West Garden Club at West Martello Tower', 'key-west-garden-club-at-west-martello-tower', 'weird-history', 24.54848, -81.78162, 'Key West', 'FL', 'Lush tropical garden growing through the ruins of an unfinished Civil War fort.', 'limited', null, 'https://www.keywestgardenclub.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Key West Lighthouse', 'key-west-lighthouse', 'weird-history', 24.55195, -81.80096, 'Key West', 'FL', 'Historic lighthouse and keeper''s quarters with maritime history and local ghost lore.', 'limited', null, 'https://www.kwahs.org/museums/key-west-lighthouse-keepers-quarters', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Key West Shipwreck Museum', 'key-west-shipwreck-museum', 'weird-history', 24.5606, -81.80749, 'Key West', 'FL', 'Museum devoted to Key West''s wrecking industry and the dangerous reefs that made fortunes.', 'limited', null, 'https://www.keywestshipwreck.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Keystone Arch Bridges', 'keystone-arch-bridges', 'weird-history', 42.31158, -72.99261, 'Chester', 'MA', 'A woodland trail reaches enormous dry-laid stone railroad arches built in the nineteenth century without mortar. Some rise more than 70 feet and survive as monumental remnants of early American railroad engineering.', 'open', null, 'https://www.atlasobscura.com/places/keystone-arch-bridges', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Killiansburg Cave', 'killiansburg-cave', 'weird-history', 39.45879, -77.79609, 'Sharpsburg', 'MD', 'During the Battle of Antietam, local civilians reportedly sheltered beneath this large rock overhang along the Potomac while fighting raged nearby. The site is reached from the C&O Canal towpath near mile 75.7 and requires walking plus a short climb away from the canal, so it is not a drive-up stop.', 'limited', null, 'https://www.atlasobscura.com/places/killiansburg-cave', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Bhumibol Adulyadej Birthplace Marker', 'king-bhumibol-adulyadej-birthplace-marker', 'weird-history', 42.3723, -71.122, 'Cambridge', 'MA', 'A plaque marks the Cambridge birthplace of Thailand''s King Bhumibol Adulyadej, born while his father studied at Harvard. The future monarch would become one of the longest-reigning sovereigns in modern history.', 'open', null, 'https://www.atlasobscura.com/places/king-bhumibol-adulyadej-birthplace-marker', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('King''s Chapel Crypt', 'kings-chapel-crypt', 'weird-history', 42.35806, -71.06001, 'Boston', 'MA', 'Twenty-one tombs lie beneath King''s Chapel, including the Strangers'' Tomb, which contains dozens of people who died in Boston without the means for private burial. Authorized Bell and Bones tours descend below the church into the historic crypt.', 'limited', null, 'https://www.atlasobscura.com/places/kings-chapel-crypt', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.kings-chapel.org/', null, null, null, 'America/New_York'),
  ('Kings Park Psychiatric Center at Nissequogue River State Park', 'kings-park-psychiatric-center-at-nissequogue-river-state-park', 'weird-history', 40.89593, -73.23956, 'Kings Park', 'NY', 'The former Kings Park Psychiatric Center grew into a sprawling institutional campus that held more than 9,000 patients at its peak before closing in 1996. Much of the property is now Nissequogue River State Park, where public roads and trails pass surviving hospital buildings; the abandoned structures themselves are unsafe and off-limits, so do not enter them.', 'open', null, 'https://apps.cio.ny.gov/apps/mediacontact/public/view.cfm?backButton=&parm=DBCB9EAF-BB2B-D983-D05568DCB12EB50B', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kingsley Plantation', 'kingsley-plantation', 'weird-history', 30.43838, -81.43815, 'Jacksonville', 'FL', 'Preserved plantation complex with unusual tabby slave cabins and layered colonial history.', 'open', null, 'https://www.nps.gov/timu/learn/historyculture/kp.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kiptopeke Concrete Fleet', 'kiptopeke-concrete-fleet', 'weird-history', 37.16463, -75.97825, 'Kiptopeke', 'VA', 'Nine concrete cargo ships built during World War II were deliberately sunk off Kiptopeke in 1948 to form a protective breakwater for the former ferry terminal. Their decaying hulls still rise from Chesapeake Bay and can be viewed from Kiptopeke State Park, with kayaks offering a closer look when conditions permit.', 'open', null, 'https://www.dcr.virginia.gov/state-parks/kiptopeke', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Knights of the Golden Horseshoe Pyramid', 'knights-of-the-golden-horseshoe-pyramid', 'weird-history', 38.35781, -78.54741, 'Elkton', 'VA', 'A stone pyramid placed at Swift Run Gap in 1921 commemorates Governor Alexander Spotswood''s 1716 expedition across the Blue Ridge, later romanticized as the Knights of the Golden Horseshoe. The roadside monument preserves that colonial legend, although claims that the party "discovered" the region ignore Indigenous occupation and earlier European travel through the area.', 'roadside', null, 'https://www.atlasobscura.com/places/knights-of-the-golden-horseshoe-markers', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Koreshan State Park', 'koreshan-state-park', 'weird-history', 26.43044, -81.81583, 'Estero', 'FL', 'Preserved settlement of the Koreshan Unity, a utopian sect that taught a hollow-earth cosmology.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/koreshan-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Krispy Kreme Founder''s Birthplace Marker', 'krispy-kreme-founders-birthplace-marker', 'weird-history', 36.81862, -88.19791, 'Benton', 'KY', 'A modest roadside sign identifies the birthplace area of Vernon Rudolph, who went on to found Krispy Kreme. The original home is gone and the site is now an open field beside US 68, making the understated marker a strange contrast to the enormous brand Rudolph later created.', 'roadside', null, 'https://www.roadsideamerica.com/tip/82081', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kymulga Grist Mill & Covered Bridge', 'kymulga-grist-mill-covered-bridge', 'weird-history', 33.33452, -86.29968, 'Childersburg', 'AL', 'A nineteenth-century grist mill and covered bridge survive together beside Talladega Creek. The preserved machinery, timber bridge and riverside setting create a compact industrial-history stop.', 'limited', null, 'https://alstate.guide/metropolitan/talladega/childersburg/kymulga-grist-mill-covered-bridge', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ladd Observatory', 'ladd-observatory', 'weird-history', 41.83901, -71.39911, 'Providence', 'RI', 'Brown University''s 1891 observatory preserves historic astronomical instruments beneath its rotating dome. Public observing nights are normally held on Tuesday evenings when weather permits and require a free reservation. The combination of Victorian science, astronomy and a hilltop dome makes it a strong nighttime OddWay stop.', 'limited', null, 'https://physics.brown.edu/about/ladd-observatory', '2026-09-09T04:49:27.913704+00:00', null, 'https://physics.brown.edu/about/ladd-observatory', null, null, null, 'America/New_York'),
  ('LaGrange College Site Park', 'lagrange-college-site-park', 'weird-history', 34.6521, -87.5342, 'Leighton', 'AL', 'Alabama’s first chartered college once stood on this ridge before Union troops burned the campus during the Civil War. Today a historic park preserves the site with reconstructed buildings, markers and views over the Tennessee Valley.', 'open', null, 'https://www.lagrangehistoricsite.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lake Compounce — America''s Oldest Amusement Park', 'lake-compounce-americas-oldest-amusement-park', 'weird-history', 41.63882, -72.92295, 'Bristol', 'CT', 'Operating since 1846, Lake Compounce is widely recognized as the oldest continuously operating amusement park in the United States. Its mix of modern rides and surviving historic amusement-park traditions makes it a useful OddWay stop beyond the normal theme-park angle.', 'limited', null, 'https://www.roadsideamerica.com/tip/25260', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.lakecompounce.com/', null, null, null, 'America/New_York'),
  ('Lake George / Holly Bluff Mounds', 'lake-george-holly-bluff-mounds', 'weird-history', 32.81411, -90.683, 'Holly Bluff', 'MS', 'A major prehistoric ceremonial center, also known as the Holly Bluff site, containing a large plaza and surviving platform mounds. The mound group is best observed from the public road and trail marker rather than entered.', 'roadside', null, 'https://trails.mdah.ms.gov/lakegeorge', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lake Helen-Cassadaga Cemetery', 'lake-helen-cassadaga-cemetery', 'weird-history', 28.96506, -81.23616, 'Lake Helen', 'FL', 'Historic cemetery containing the infamous Devil''s Chair and Spiritualist-area lore.', 'open', null, 'https://www.lakehelencemetery.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Jackson Mounds Archaeological State Park', 'lake-jackson-mounds-archaeological-state-park', 'weird-history', 30.50567, -84.31622, 'Tallahassee', 'FL', 'Large Mississippian ceremonial mound complex just north of Tallahassee.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/lake-jackson-mounds-archaeological-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Michigan Underwater Crucifix', 'lake-michigan-underwater-crucifix', 'weird-history', 45.37706, -84.96269, 'Petoskey', 'MI', 'An 11-foot white-marble crucifix lies beneath the waters of Little Traverse Bay after being placed there in 1962 as a memorial to divers who had died. During rare winters with safe, clear ice, organized viewing events have allowed visitors to walk offshore and look down through a cut in the ice; access depends completely on conditions and authorization.', 'limited', null, 'https://petoskeyarea.com/places/underwater-crucifix/', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Lakeside Cemetery — Michigan''s Magic Graveyard', 'lakeside-cemetery-michigans-magic-graveyard', 'weird-history', 41.96699, -85.33624, 'Colon', 'MI', 'Colon calls itself the Magic Capital of the World, and Lakeside Cemetery contains the graves of numerous professional magicians connected with the town. Among the best known is Harry Blackstone Sr., making the cemetery an unusual pilgrimage site for the history of American stage magic.', 'open', null, 'https://www.atlasobscura.com/places/lakeside-cemetery', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Land of Oz', 'land-of-oz', 'weird-history', 36.211, -81.889, 'Beech Mountain', 'NC', 'This Wizard of Oz theme park opened in 1970 and later closed as a regular attraction, leaving behind a surreal mountaintop Yellow Brick Road, Dorothy’s farmhouse, and themed structures. It is not abandoned property open for exploration: the site operates through scheduled events and ticketed dates, and entering outside authorized events is trespassing. Visitor information: https://landofoznc.com/faq/', 'limited', null, 'https://landofoznc.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Landsford Canal State Park', 'landsford-canal-state-park', 'weird-history', 34.78118, -80.87858, 'Catawba', 'SC', 'Ruins of a 19th-century canal system sit along the Catawba River, including stonework left from an attempt to bypass dangerous rapids for commercial traffic. In late spring the river also becomes famous for enormous blooms of rare Rocky Shoals spider lilies.', 'limited', null, 'https://southcarolinaparks.com/landsford-canal', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Laurel Hill Cemetery', 'laurel-hill-cemetery', 'weird-history', 40.00483, -75.19018, 'Philadelphia', 'PA', 'Laurel Hill opened in 1836 as one of America''s early rural cemeteries and became a landscape of elaborate mausoleums, sculptures and graves of prominent Philadelphians. The cemetery welcomes self-guided visitors every day and also hosts historical, architectural and macabre-themed tours and events.', 'open', null, 'https://thelaurelhillcemetery.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Laurel Valley Village', 'laurel-valley-village', 'weird-history', 29.80124, -90.77915, 'Thibodaux', 'LA', 'Laurel Valley preserves rows of historic sugar-plantation workers'' houses and support buildings in one of the largest surviving complexes of its type. Much of the property remains privately managed, so use designated visitor areas and current tour rules.', 'limited', null, 'https://www.lafourche.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Law Mounds', 'law-mounds', 'weird-history', 33.09553, -91.01543, 'Hollandale', 'MS', 'A Mississippian mound complex associated with an abandoned Mississippi River channel near Swan Lake. The surviving main mound is on private property but can be seen from the road leading into the wildlife-refuge area.', 'roadside', null, 'https://trails.mdah.ms.gov/law', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lawrence Park Dinor', 'lawrence-park-dinor', 'weird-history', 42.15071, -80.01431, 'Lawrence Park Township', 'PA', 'This prefabricated Silk City "dinor" arrived in Lawrence Park in 1948 and retains much of its original mid-century diner architecture. It is listed on the National Register, still serves breakfast and lunch, and preserves the peculiar **dinor-with-an-o** spelling that became a Northwestern Pennsylvania tradition.', 'open', null, 'https://www.eriereader.com/article/prefab-but-uniquely-erie', '2026-09-07T15:27:08.742137+00:00', null, 'https://www.thelpdinor.com/', null, null, null, 'America/New_York'),
  ('Leadfield', 'leadfield', 'weird-history', 36.848316, -117.060807, 'Beatty', 'NV', 'The boom lasted under a year in 1926-27, after aggressive promotion pulled miners and investors into Titus Canyon and poor ore collapsed the whole thing. A few shacks, workings and ruins remain along the one-way Titus Canyon Road — which is scheduled to close from October 2026 to September 2027 for repairs.', 'limited', null, 'https://www.nps.gov/deva/planyourvisit/titus-canyon.htm', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Leefe', 'leefe', 'weird-history', 41.811762, -111.024733, 'Kemmerer', 'WY', 'A phosphate mining and processing locality in western Wyoming — not Utah, despite the nearest town being over the line. The Leefe Mine ran from 1947 until Wyoming phosphate production ended in 1977. The mine and plant area lies about thirty miles west of Kemmerer and is not maintained for visitors; do not enter old workings or industrial property.', 'limited', null, 'https://main.wsgs.wyo.gov/mineral-resources/industrial-minerals/phosphate', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Denver'),
  ('Legacy Museum at Tuskegee University', 'legacy-museum-at-tuskegee-university', 'weird-history', 32.4301, -85.7074, 'Tuskegee', 'AL', 'The museum occupies the former Infantile Paralysis Unit of John A. Andrew Memorial Hospital and examines bioethics, science and the U.S. Public Health Service syphilis study in Macon County. Campus visitors must follow Tuskegee University security and pass procedures.', 'limited', null, 'https://www.tuskegee.edu/libraries/Legacy-Museum.html', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Leif Erikson Plaque', 'leif-erikson-plaque', 'weird-history', 42.37331, -71.13431, 'Cambridge', 'MA', 'A small plaque marks the spot nineteenth-century chemist Eben Horsford claimed was the site of Leif Erikson''s home from around the year 1000. Mainstream archaeology has not supported Horsford''s theory, turning the marker into a physical relic of America''s enthusiasm for speculative Viking history.', 'open', null, 'https://www.atlasobscura.com/places/leif-erikson-plaque', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Leo Petroglyph', 'leo-petroglyph', 'weird-history', 39.15091, -82.67472, 'Ray', 'OH', 'The Leo Petroglyph contains dozens of prehistoric figures carved into a sandstone outcrop, including humans, animals and abstract forms associated with Indigenous people of the region. A protective shelter covers the carvings and the state historic site is accessible to visitors from the adjoining public area.', 'open', null, 'https://www.atlasobscura.com/places/leo-petroglyph', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lessley Mounds', 'lessley-mounds', 'weird-history', 31.15823, -91.44023, 'Woodville', 'MS', 'A prehistoric mound site in Wilkinson County representing the lower Mississippi Valley''s long ceremonial landscape. The mounds are part of the state driving trail but should be viewed from public access only.', 'roadside', null, 'https://trails.mdah.ms.gov/lessley', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Letchworth-Love Mounds Archaeological State Park', 'letchworth-love-mounds-archaeological-state-park', 'weird-history', 30.55758, -83.98613, 'Monticello', 'FL', 'Home to Florida''s tallest known Native American ceremonial mound.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/letchworth-love-mounds-archaeological-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Liberty Bell of the West', 'liberty-bell-of-the-west', 'weird-history', 37.92162, -89.91465, 'Kaskaskia', 'IL', 'A bell captured from the British at Kaskaskia in 1778 became known as the Liberty Bell of the West and remains on the isolated former state-capital island.', 'limited', null, 'https://www.randolphcountyillinois.net/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Liberty Theatre', 'liberty-theatre', 'weird-history', 30.49306, -92.41611, 'Eunice', 'LA', 'The 1924 Liberty Theatre became famous for live Cajun and zydeco programming and is a landmark of Eunice''s music district. Restoration work has affected interior access, so OddWay should treat it as an exterior stop unless a current event explicitly opens the building.', 'roadside', null, 'https://www.eunice-la.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Light Bulb Grave of the World''s Greatest Electrician', 'light-bulb-grave-of-the-worlds-greatest-electrician', 'weird-history', 40.89855, -74.20772, 'Totowa', 'NJ', 'Electrician Sal Giardino''s four-foot black granite tombstone is shaped like an incandescent bulb and includes lightning bolts, an electrical outlet and the words ''World''s Greatest Electrician.'' It stands inside Laurel Grove Cemetery, which maintains posted visiting hours.', 'limited', null, 'https://www.roadsideamerica.com/story/28572', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lincoln Highway Ideal Section Marker', 'lincoln-highway-ideal-section-marker', 'weird-history', 41.4928, -87.5095, 'Dyer', 'IN', 'In 1923, highway planners completed an experimental "Ideal Section" of the Lincoln Highway near Dyer to demonstrate what a modern road could be. The model section used unusually thick reinforced concrete along with drainage, lighting and pedestrian features, and a marker now identifies this influential piece of early highway engineering.', 'roadside', null, 'https://highways.fhwa.dot.gov/highway-history/general-highway-history/lincoln-highway', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lincoln Square — The Lottery Inspiration', 'lincoln-square-the-lottery-inspiration', 'weird-history', 42.929, -73.24207, 'North Bennington', 'VT', 'This small village square is associated with Shirley Jackson''s years in North Bennington and is commonly identified as an inspiration for the setting of her disturbing short story The Lottery. Jackson lived nearby while writing the story, making the ordinary-looking square a useful literary-horror stop.', 'open', null, 'https://www.atlasobscura.com/places/lincoln-square-lottery', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lincoln Tomb', 'lincoln-tomb', 'weird-history', 39.82338, -89.65566, 'Springfield', 'IL', 'Abraham Lincoln, Mary Todd Lincoln, and three of their sons are entombed inside an enormous state monument topped by a towering obelisk.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/central/lincoln-tomb.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lincoln''s New Salem State Historic Site', 'lincolns-new-salem-state-historic-site', 'weird-history', 39.9787, -89.84706, 'Petersburg', 'IL', 'A reconstructed 1830s frontier village recreates the small settlement where Abraham Lincoln lived before moving to Springfield.', 'open', null, 'https://dnr.illinois.gov/parks/park.lincolns-new-salem.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Little Bohemia Lodge', 'little-bohemia-lodge', 'weird-history', 46.11957, -89.85748, 'Manitowish Waters', 'WI', 'In April 1934, federal agents attempted to capture John Dillinger and members of his gang at this remote lodge, leading to a chaotic gun battle. The restaurant still embraces the history, and bullet damage and memorabilia preserve one of the most famous episodes of the Dillinger manhunt.', 'open', null, 'https://www.littlebohemialodge.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.littlebohemialodge.com/', null, null, null, 'America/Chicago'),
  ('Little Lost Cemetery', 'little-lost-cemetery', 'weird-history', 40.86732, -74.41633, 'Parsippany-Troy Hills', 'NJ', 'A handful of old gravestones survive behind a modern firehouse, almost completely disconnected from the landscape in which the cemetery was created. Its isolation amid later development gives the tiny burial ground its ''lost'' character.', 'limited', null, 'https://www.atlasobscura.com/places/little-lost-cemetery', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Livermore Ghost Town', 'livermore-ghost-town', 'weird-history', 44.07451, -71.3773, 'Livermore', 'NH', 'Livermore grew as a White Mountain logging company town in the late nineteenth century before fires, floods and changing timber economics helped empty it. Foundations, cellar holes and traces of the settlement remain along Sawyer River Road. The road is seasonal and may be gated, but the former village can be explored on foot without trespassing on the nearby private camp. Secondary source: https://ournewenglandlegends.com/podcast-439-the-ghost-town-of-livermore/', 'limited', null, 'https://www.nhpr.org/nh-news/2017-07-21/you-asked-we-answered-what-happened-to-the-people-in-that-n-h-ghost-town', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lizzie Borden House', 'lizzie-borden-house', 'weird-history', 41.69881, -71.15641, 'Fall River', 'MA', 'The house where Andrew and Abby Borden were murdered with a hatchet in 1892 now operates as a museum and inn. Guests can tour the rooms connected with the killings — or sleep in the house overnight — while the still-unsolved identity of the murderer keeps the case alive more than a century later.', 'limited', null, 'https://lizzie-borden.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://lizzie-borden.com/', null, null, null, 'America/New_York'),
  ('Lizzie Borden''s Grave', 'lizzie-bordens-grave', 'weird-history', 41.70766, -71.13827, 'Fall River', 'MA', 'Lizzie Borden is buried in Oak Grove Cemetery beside members of the same family whose murders made her infamous. Her own marker is unexpectedly small and simply reads ''Lizbeth''; painted arrows inside the cemetery guide visitors toward the Borden plot during open hours.', 'limited', null, 'https://www.roadsideamerica.com/story/50971', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lizzie Bourne Memorial', 'lizzie-bourne-memorial', 'weird-history', 44.2721, -71.30205, 'Jackson', 'NH', 'A stone memorial near the summit of Mount Washington marks where 23-year-old Lizzie Bourne died from exposure during a storm in September 1855. She was only a short distance from shelter when she died, and the location became a lasting warning about the mountain''s rapidly changing weather. There is no clear safe public footpath to the monument; the safest way to view it is from the Mount Washington Cog Railway as it passes nearby.', 'limited', null, 'https://www.atlasobscura.com/places/lizzie-bourne-memorial', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Location of the First Gas Street Lamp', 'location-of-the-first-gas-street-lamp', 'weird-history', 41.48615, -71.31471, 'Newport', 'RI', 'A memorial lamp and plaque mark the site where inventor David Melville demonstrated an early gas streetlight in Newport during the first years of the nineteenth century. Melville''s work predates the better-known municipal gas-lighting systems that followed elsewhere in the United States. The small marker is easy to miss on Pelham Street.', 'open', null, 'https://www.atlasobscura.com/places/location-of-the-first-gas-street-lamp', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Locust Grove State Historic Site', 'locust-grove-state-historic-site', 'weird-history', 30.83768, -91.33567, 'St. Francisville', 'LA', 'This small historic site preserves the family cemetery of Sarah Knox Taylor Davis, first wife of Jefferson Davis. Current state schedules list Locust Grove as appointment-based, so arrange access rather than arriving unannounced.', 'limited', null, 'https://www.lastateparks.com/historic-sites', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lofthus Underwater Archaeological Preserve', 'lofthus-underwater-archaeological-preserve', 'weird-history', 26.56293, -80.03848, 'Boynton Beach', 'FL', 'Iron-hulled merchant barque with painted false gunports that wrecked off South Florida in 1898.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/lofthus/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Logan City', 'logan-city', 'weird-history', 37.609462, -115.393523, 'Hiko', 'NV', 'Founded after silver was found at Mount Irish in 1865, with a post office by 1867 and largely abandoned by 1869 once the shallow high-grade ore ran out. Only stone foundations remain in the Pahranagat district, on rough desert roads.', 'limited', null, 'https://eplanning.blm.gov/public_projects/lup/87546/128764/156632/Appendix_Q.pdf', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Logtown Ghost Town Marker', 'logtown-ghost-town-marker', 'weird-history', 30.28207, -89.6238, 'Pearlington', 'MS', 'A marker for Logtown, a lumber community founded in 1848 and later emptied when residents were removed from the buffer zone around what became Stennis Space Center. Very little of the town survives, so the interpretive marker is the lawful, routable stop. Secondary source: https://www.mdah.ms.gov/', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Long Pond Ironworks', 'long-pond-ironworks', 'weird-history', 41.14525, -74.31178, 'West Milford', 'NJ', 'Ruins of furnaces, waterwheels, stone walls and workers'' buildings survive from an ironmaking community that operated for centuries near the New York border. Public trails weave through the industrial remains, while the museum follows a more limited schedule.', 'open', null, 'https://longpondironworks.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lonnie Holloway''s Pontiac Grave — Rock Hill Baptist Church Cemetery', 'lonnie-holloways-pontiac-grave-rock-hill-baptist-church-cemetery', 'weird-history', 33.99269, -81.75749, 'Saluda', 'SC', 'When Lonnie Holloway died at age 90 in 2009, his unusual burial instructions were carried out: he was placed in the driver''s seat of his green 1973 Pontiac Catalina and the entire car was buried with him. His gun collection was reportedly placed on the passenger seat because he did not want the firearms to fall into the wrong hands. The car itself is underground, so this is a cemetery-history stop rather than a visible-car attraction.', 'limited', null, 'https://www.roadsideamerica.com/story/76517', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lost Arch Historic Mining Camp', 'lost-arch-historic-mining-camp', 'weird-history', 34.436412, -114.824378, 'Needles', 'CA', 'A BLM-managed historic mining area in the remote Turtle Mountains, reached over roughly thirteen miles of backroads from US 95. You find an information kiosk, a mining landscape and primitive campsites rather than a reconstructed ghost town.', 'limited', null, 'https://www.blm.gov/visit/lost-arch-historic-mining-camp', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Lottie Cooper Shipwreck Remains', 'lottie-cooper-shipwreck-remains', 'weird-history', 43.75319, -87.70368, 'Sheboygan', 'WI', 'Timbers from the schooner Lottie Cooper, wrecked in an 1894 storm, were recovered during harbor construction and reassembled outdoors near the waterfront. The exposed wooden skeleton lets visitors walk around the remains of a nineteenth-century Great Lakes ship on dry land.', 'open', null, 'https://www.wisconsinshipwrecks.org/Vessel/Details/385', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.wisconsinshipwrecks.org/', null, null, null, 'America/Chicago'),
  ('Louis'' Lunch — Home of the Hamburger', 'louis-lunch-home-of-the-hamburger', 'weird-history', 41.30647, -72.93041, 'New Haven', 'CT', 'Louis'' Lunch claims to have served the first hamburger sandwich in 1900 and still cooks its burgers vertically in antique cast-iron broilers. The tiny restaurant also famously resists ketchup, preserving an unusually strict piece of food history.', 'open', null, 'https://www.roadsideamerica.com/story/15421', '2026-09-08T19:51:22.001704+00:00', null, 'https://louislunch.com/', null, null, null, 'America/New_York'),
  ('Louisiana Maneuvers & Military Museum', 'louisiana-maneuvers-military-museum', 'weird-history', 31.3333, -92.4105, 'Pineville', 'LA', 'Located at Camp Beauregard, this Louisiana National Guard museum interprets the massive pre-World War II Louisiana Maneuvers and later military history. Because it is on a Guard installation, check current public hours and identification requirements before visiting.', 'limited', null, 'https://geauxguardmuseums.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana Military Museum', 'louisiana-military-museum', 'weird-history', 32.52925, -92.63366, 'Ruston', 'LA', 'This specialized museum covers conflicts from the Civil War through modern deployments with deactivated weapons, uniforms, diaries, medals and heavy equipment. Personal artifacts keep the collection from feeling like only a display of hardware.', 'open', null, 'https://www.sos.la.gov/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana State Capitol — Huey Long Assassination Site', 'louisiana-state-capitol-huey-long-assassination-site', 'weird-history', 30.45709, -91.18737, 'Baton Rouge', 'LA', 'The present capitol is tied to the 1935 shooting of Senator Huey P. Long, one of the most consequential and disputed episodes in Louisiana political history. Visitors may enter through normal security procedures; some areas can close for government operations or renovation.', 'open', null, 'https://house.louisiana.gov/pubinfo/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana State Penitentiary Museum', 'louisiana-state-penitentiary-museum', 'weird-history', 30.94035, -91.56942, 'Angola', 'LA', 'The museum documents the history of the Louisiana State Penitentiary, better known as Angola, through prison artifacts and institutional history. Because it is connected with an active maximum-security prison complex, follow all current visitor rules and do not wander beyond designated areas.', 'limited', null, 'https://angolamuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisville Water Tower', 'louisville-water-tower', 'weird-history', 38.28056, -85.70139, 'Louisville', 'KY', 'Completed around 1860, this ornate column disguised a functioning water-system standpipe behind the appearance of a classical monument. Often described as the world''s oldest ornamental water tower, it stands beside the equally elaborate pumping station and WaterWorks Museum.', 'limited', null, 'https://commons.wikimedia.org/wiki/File:Louisville_water_tower.jpg', '2026-09-08T14:30:49.642487+00:00', null, 'https://louisvillewater.com/', null, null, null, 'America/Kentucky/Louisville'),
  ('LSU Campus Mounds', 'lsu-campus-mounds', 'weird-history', 30.41506, -91.18222, 'Baton Rouge', 'LA', 'Two Native American earthworks on LSU''s campus are among the oldest surviving human-made structures in the region. They are fragile archaeological sites, so observe university protections and never climb, dig or disturb them.', 'open', null, 'https://www.lsu.edu/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Luther Elkins Petroglyphs', 'luther-elkins-petroglyphs', 'weird-history', 37.68156, -81.66492, 'Clear Fork', 'WV', 'These rock carvings are genuine Indigenous petroglyphs generally attributed to Native peoples of the region, although they became famous in the 1980s after fringe claims tried to reinterpret them as ancient Irish writing. The site is undeveloped and reached through rough terrain near private property; stay on the legitimate access route and never touch, chalk or trace the carvings.', 'limited', null, 'https://www.atlasobscura.com/places/luther-elkins-petroglyphs', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lyceum Hall', 'lyceum-hall', 'weird-history', 42.52243, -70.89519, 'Salem', 'MA', 'Alexander Graham Bell demonstrated a successful long-distance telephone call from Salem''s Lyceum Hall in 1877. The original building has changed uses, but the location preserves an unexpectedly important milestone in communications history amid downtown Salem.', 'open', null, 'https://www.atlasobscura.com/places/lyceum-hall', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maconaquah''s Grave — Slocum Cemetery', 'maconaquahs-grave-slocum-cemetery', 'weird-history', 40.69852, -85.90759, 'Wabash', 'IN', 'This family cemetery contains the grave of Maconaquah, the Miami woman long known in American histories as Frances Slocum after she was taken from her Pennsylvania family as a child and raised among the Miami. She later chose to remain with her Miami family rather than return east, making the cemetery an important physical site for a complicated story often flattened into frontier folklore.', 'open', null, 'https://www.atlasobscura.com/places/the-slocum-cemetery', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Mad Anthony Wayne Blockhouse', 'mad-anthony-wayne-blockhouse', 'weird-history', 42.14003, -80.07432, 'Erie', 'PA', 'This reconstructed blockhouse marks the Fort Presque Isle site where Revolutionary War general Anthony Wayne died in 1796 and was first buried. When his son later came to move the body east, Wayne''s partially decomposed remains were boiled so the bones could be transported, leaving Erie associated with one of the strangest posthumous journeys in American military history; interior access is limited, but the grounds can be visited.', 'limited', null, 'https://historicsitemarkers.com/marker/anthony-wayne', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Madame Sherri''s Castle Ruins', 'madame-sherris-castle-ruins', 'weird-history', 42.86474, -72.51909, 'Chesterfield', 'NH', 'Costume designer Antoinette Sherri built an extravagant country estate here and became locally famous for lavish parties and eccentric behavior. The house burned in 1962, leaving stone foundations, columns and the remains of a dramatic staircase in the forest. The upper portion of the staircase collapsed in 2021, so visitors should admire the ruins without climbing them.', 'open', null, 'https://www.atlasobscura.com/places/madame-sherris-castle', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.chesterfield-conservation-commission.com/madame-sherri-forest', null, null, null, 'America/New_York'),
  ('Madira Bickel Mound State Archaeological Site', 'madira-bickel-mound-state-archaeological-site', 'weird-history', 27.57719, -82.58448, 'Terra Ceia', 'FL', 'Ancient ceremonial mound site and Florida''s first protected state archaeological site.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/madira-bickel-mound-state-archaeological-site', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Madison Dry Goods & Country Store', 'madison-dry-goods-country-store', 'weird-history', 36.38773, -79.95987, 'Madison', 'NC', 'This old-fashioned general store includes a small upstairs museum with local artifacts and material connected to one of the area’s most notorious crimes, the 1929 Lawson family murders. The building has also become associated with ghost stories and paranormal investigations.', 'open', null, 'https://www.atlasobscura.com/places/madison-dry-goods', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Magnolia Plantation — Cane River Creole NHP', 'magnolia-plantation-cane-river-creole-nhp', 'weird-history', 31.54921, -92.94157, 'Derry', 'LA', 'National Park Service holdings at Magnolia preserve slave/tenant cabins, a plantation store, gin barn and other structures within the Cane River landscape. The main house remains privately owned and is not open to the public, so stay strictly within NPS visitor areas.', 'limited', null, 'https://www.nps.gov/cari/planyourvisit/magnolia-plantation.htm', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Maiden Cliff Cross', 'maiden-cliff-cross', 'weird-history', 44.25528, -69.09338, 'Camden', 'ME', 'A large white cross stands high above Megunticook Lake at Maiden Cliff. It memorializes 12-year-old Elenora French, who died in 1864 after being swept from the cliff while visiting the area. The cross is reached by trail and has become a stark landmark above the lake.', 'limited', null, 'https://www.visitmaine.com/article/maiden-cliff-trail/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maine Lobsterman Statue', 'maine-lobsterman-statue', 'weird-history', 43.65752, -70.25582, 'Portland', 'ME', 'This bronze lobsterman traces its origin to a plaster sculpture commissioned for Maine’s display at the 1939 New York World’s Fair. The Portland version depicts a working fisherman kneeling over a lobster, turning a piece of World’s Fair history into a permanent monument to Maine’s best-known industry.', 'open', null, 'https://www.atlasobscura.com/places/maine-lobsterman-statue', '2026-09-09T04:54:23.476824+00:00', null, 'https://www.publicartportland.org/project/maine-lobsterman/', null, null, null, 'America/New_York'),
  ('Mallows Bay Ghost Fleet', 'mallows-bay-ghost-fleet', 'weird-history', 38.47195, -77.26863, 'Nanjemoy', 'MD', 'More than 100 wrecks from a fleet of World War I-era wooden steamships remain in and around Mallows Bay, forming one of the largest concentrations of shipwrecks in the Western Hemisphere. The best views come by kayak or other small craft from the public launch, though some remains can also be seen from shore and trails.', 'limited', null, 'https://dnr.maryland.gov/ccs/Pages/mallowsbay.aspx', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Man Mound', 'man-mound', 'weird-history', 43.53085, -89.79561, 'Baraboo', 'WI', 'This surviving effigy mound was built in the shape of a human figure by Indigenous mound builders centuries ago. It is the only known anthropomorphic effigy mound in North America still largely intact, and a county park protects the site.', 'open', null, 'https://www.co.sauk.wi.us/parksandrecreation/man-mound-park', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.co.sauk.wi.us/', null, null, null, 'America/Chicago'),
  ('Man o'' War''s Grave', 'man-o-wars-grave', 'weird-history', 38.15087, -84.5202, 'Lexington', 'KY', 'Legendary racehorse Man o'' War was embalmed and buried in an oversized casket before his remains and monumental bronze statue were later moved to the Kentucky Horse Park. The memorial now stands prominently near the park entrance among the graves of other famous horses.', 'limited', null, 'https://www.roadsideamerica.com/story/3613', '2026-09-08T14:15:10.228298+00:00', null, 'https://kyhorsepark.com/', null, null, null, 'America/New_York'),
  ('Manhattan Project National Historical Park — Oak Ridge', 'manhattan-project-national-historical-park-oak-ridge', 'weird-history', 36.02319, -84.27205, 'Oak Ridge', 'TN', 'Oak Ridge was created in secrecy during World War II as a major Manhattan Project site. The National Park Service interprets the city, its wartime role and surviving facilities; some associated federal sites require scheduled tours or remain restricted, so visitors should use official visitor points only.', 'limited', null, 'https://www.nps.gov/mapr/planyourvisit/oakridge-tn.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mansfield State Historic Site', 'mansfield-state-historic-site', 'weird-history', 32.01092, -93.66495, 'Mansfield', 'LA', 'This battlefield preserves the site of the 1864 Battle of Mansfield, where Confederate forces halted the Union Red River Campaign. Trails, monuments and a museum interpret a major Civil War battle west of the Mississippi.', 'open', null, 'https://www.lastateparks.com/historic-sites/mansfield-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mantle Rock', 'mantle-rock', 'weird-history', 37.35183, -88.42883, 'Smithland', 'KY', 'This enormous natural sandstone bridge spans roughly 150 feet and sheltered Cherokee people during the forced-removal journey remembered as the Trail of Tears. About 1,800 Cherokee were stranded in the area during the bitter winter of 1838–39 while waiting for ice conditions on the Ohio River to improve.', 'open', null, 'https://www.fraziermuseum.org/weekly/7-29-2024', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Marathon Park', 'marathon-park', 'weird-history', 42.26266, -71.47881, 'Ashland', 'MA', 'Before the Boston Marathon starting line moved to Hopkinton, early races began in Ashland. This small park preserves the original starting area with markers and displays tied to the world''s oldest annual marathon.', 'open', null, 'https://www.atlasobscura.com/places/marathon-park', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marconi Wireless Station Site', 'marconi-wireless-station-site', 'weird-history', 41.90466, -69.98479, 'Wellfleet', 'MA', 'The dunes preserve the site of Guglielmo Marconi''s enormous wireless station, where a transatlantic message from President Theodore Roosevelt was sent to King Edward VII in 1903. Most of the original station has vanished into the eroding Cape Cod shoreline, leaving interpretive remains and an unusually windswept communications landmark.', 'open', null, 'https://www.atlasobscura.com/places/marconi-wireless-station-site', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marian Coffin Garden', 'marian-coffin-garden', 'weird-history', 39.76083, -75.57424, 'Wilmington', 'DE', 'Formal gardens designed by pioneering landscape architect Marian Cruger Coffin surround the abandoned Gibraltar mansion behind a stone wall in Wilmington. The contrast between carefully restored grounds and the long-neglected mansion gives the site an unusually eerie atmosphere.', 'open', null, 'https://www.atlasobscura.com/places/marian-coffin-garden', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marineland Dolphin Adventure', 'marineland-dolphin-adventure', 'weird-history', 29.66939, -81.21273, 'Marineland', 'FL', 'Historic 1938 marine attraction originally built as an underwater motion-picture studio.', 'limited', null, 'https://www.marineland.net/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marjorie Kinnan Rawlings Historic State Park', 'marjorie-kinnan-rawlings-historic-state-park', 'weird-history', 29.48606, -82.16167, 'Cross Creek', 'FL', 'Preserved Florida Cracker farmhouse where the author of The Yearling lived and wrote.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/marjorie-kinnan-rawlings-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Market Street Catacombs', 'market-street-catacombs', 'weird-history', 39.76858, -86.15344, 'Indianapolis', 'IN', 'Beneath Indianapolis'' historic City Market lies roughly 20,000 square feet of brick and limestone passages once used for cool storage beneath the market halls. The catacombs have historically opened only for scheduled tours and were closed during City Market redevelopment, so access should be verified before OddWay routes a traveler inside.', 'limited', null, 'https://www.atlasobscura.com/places/market-street-catacombs', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.indianalandmarks.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Marksville State Historic Site', 'marksville-state-historic-site', 'weird-history', 31.12463, -92.0479, 'Marksville', 'LA', 'This state site preserves prehistoric Native American earthworks associated with the Marksville culture and interprets regional archaeology. Stay on designated visitor paths and never climb or disturb protected mounds.', 'open', null, 'https://www.lastateparks.com/historic-sites/marksville-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mars Bluff Atomic Bomb Accident Marker', 'mars-bluff-atomic-bomb-accident-marker', 'weird-history', 34.19668, -79.66327, 'Florence', 'SC', 'In 1958, a U.S. Air Force B-47 accidentally dropped a nuclear weapon near Mars Bluff. The nuclear capsule was not inside the bomb, but its conventional explosives detonated and blasted a crater roughly 50 to 70 feet across while injuring members of the Gregg family. This pin is the public historical marker; the actual crater nearby is on private property and should not be entered without permission. Artifacts: https://www.flocomuseum.org/featured-objects/mars-bluff-bomb/', 'roadside', null, 'https://www.hmdb.org/m.asp?m=132036', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mars Bluff Atomic Bomb Fragments', 'mars-bluff-atomic-bomb-fragments', 'weird-history', 34.19592, -79.76643, 'Florence', 'SC', 'The Florence County Museum preserves fragments and objects connected with the 1958 Mars Bluff nuclear-bomb accident, when a weapon accidentally fell from a B-47 and its conventional explosives detonated near a family home. These artifacts complement the public marker included in South Carolina Part 1.', 'limited', null, 'https://www.flocomuseum.org/featured-objects/mars-bluff-bomb/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marshall Hall Ruins', 'marshall-hall-ruins', 'weird-history', 38.68496, -77.09883, 'Accokeek', 'MD', 'The Marshall family built its Potomac River estate here in the 18th century, and the property later became a popular amusement park complete with rides and a roller coaster. The amusement park closed in 1979, but remnants of the old mansion and later recreational history survive within today''s Piscataway Park.', 'open', null, 'https://www.nps.gov/pisc/learn/historyculture/about-marshall-hall.htm', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Martin Augustine Mining Camp', 'martin-augustine-mining-camp', 'weird-history', 33.484085, -115.236058, 'Riverside County', 'CA', 'A remote mining locality near Augustine Pass, associated with the prospector Martin Augustine, photographed at his desert camp by the early 1930s. There is no attraction, museum or maintained buildings — treat it as backcountry mining history rather than a destination.', 'limited', null, 'https://www.parkrecord.com/2024/03/05/park-city-museum-puts-its-stamp-on-postcards-from-mecca/', null, null, null, null, null, null, 'America/Los_Angeles'),
  ('Matawan Shark Attack Memorial', 'matawan-shark-attack-memorial', 'weird-history', 40.41859, -74.22696, 'Matawan', 'NJ', 'A memorial in Matawan''s Memorial Park remembers Lester Stillwell and Stanley Fisher, who were killed during the 1916 Jersey Shore shark attacks. Their deaths were particularly shocking because the attacks occurred inland in Matawan Creek rather than in the open ocean.', 'open', null, 'https://www.atlasobscura.com/places/matawan-new-jersey-shark-attack-of-1916', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Matewan Massacre Historical Marker', 'matewan-massacre-historical-marker', 'weird-history', 37.62283, -82.1655, 'Matewan', 'WV', 'This downtown marker identifies the setting of the May 19, 1920 gunfight between Baldwin-Felts agents, local officials and miners during the struggle to unionize the southern West Virginia coalfields. Ten men were killed, and the confrontation helped trigger the escalation that ultimately led toward the Battle of Blair Mountain.', 'open', null, 'https://www.hmdb.org/m.asp?m=169678', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('McCoy Cemetery Historical Marker', 'mccoy-cemetery-historical-marker', 'weird-history', 37.58028, -82.17988, 'Hardy', 'KY', 'A roadside historical marker identifies the McCoy family cemetery associated with victims of the Hatfield-McCoy feud. Because access to the cemetery itself can be restricted, OddWay should route travelers to the public marker rather than encouraging entry onto private or controlled land.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=50661', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('McLarty Treasure Museum', 'mclarty-treasure-museum', 'weird-history', 27.82869, -80.41854, 'Vero Beach', 'FL', 'Museum overlooking the site of the 1715 Spanish treasure fleet disaster.', 'limited', null, 'https://www.floridastateparks.org/learn/mclarty-treasure-museum', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Meadowcroft Rockshelter', 'meadowcroft-rockshelter', 'weird-history', 40.28618, -80.49063, 'Jefferson Township', 'PA', 'Meadowcroft preserves a rock shelter containing evidence of human occupation dating back thousands of years and central to debates about the earliest settlement of North America. The archaeological site is protected beneath a modern enclosure and can be seen on guided tours during the museum''s operating season.', 'limited', null, 'https://www.heinzhistorycenter.org/visit/meadowcroft/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Medfield State Hospital', 'medfield-state-hospital', 'weird-history', 42.20722, -71.33129, 'Medfield', 'MA', 'More than 35 buildings from a former state psychiatric hospital remain standing across an unusually intact campus. The town allows daytime visitors to walk many outdoor areas, and the property has appeared in films including ''Shutter Island'' and ''Knives Out.'' Every building interior is off-limits, and construction or filming can close sections without much notice.', 'limited', null, 'https://www.atlasobscura.com/places/medfield-state-hospital', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Medgar and Myrlie Evers Home National Monument', 'medgar-and-myrlie-evers-home-national-monument', 'weird-history', 32.34096, -90.21265, 'Jackson', 'MS', 'The home where civil-rights leader Medgar Evers lived with his family and where he was assassinated in the driveway in 1963. The National Park Service preserves the house; interior visitation is structured around current tour availability rather than unrestricted entry.', 'limited', null, 'https://www.nps.gov/memy/index.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mel Fisher Maritime Museum', 'mel-fisher-maritime-museum', 'weird-history', 24.55942, -81.80624, 'Key West', 'FL', 'Treasure and artifacts recovered from famous Spanish shipwrecks including the Atocha.', 'limited', null, 'https://www.melfisher.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mel Fisher''s Treasure Museum', 'mel-fishers-treasure-museum', 'weird-history', 27.81704, -80.46977, 'Sebastian', 'FL', 'Treasure-hunting museum with recovered coins, artifacts, and stories from Spanish wrecks.', 'limited', null, 'https://www.melfisher.com/Sebastian/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Memorial to Betty the Learned Elephant', 'memorial-to-betty-the-learned-elephant', 'weird-history', 41.9138, -71.67011, 'Chepachet', 'RI', 'A small memorial recalls Betty, an elephant traveling with a nineteenth-century menagerie who was shot and killed in Chepachet in 1826. Accounts say a local man fired after becoming angry when the elephant would not respond to him. The understated roadside marker preserves one of Rhode Island''s strangest and saddest animal stories.', 'roadside', null, 'https://www.atlasobscura.com/places/memorial-to-betty-the-learned-elephant', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Menhaden Fishing Net Reel', 'menhaden-fishing-net-reel', 'weird-history', 38.77631, -75.14331, 'Lewes', 'DE', 'A huge industrial reel once used for the menhaden fishing industry sits on the Lewes Historical Society grounds. The machine-like spool is a tangible remnant of the massive nets and processing operations that once defined part of the town''s waterfront economy.', 'open', null, 'https://archives.delaware.gov/delaware-historical-markers/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.historiclewes.org/', null, null, null, 'America/New_York'),
  ('Mercedes-Benz Tombstone', 'mercedes-benz-tombstone', 'weird-history', 40.63813, -74.23869, 'Linden', 'NJ', 'A black granite gravestone is carved into the unmistakable front end of a Mercedes-Benz, complete with grille and three-pointed star. The monument stands inside Rosedale and Rosehill Cemetery and turns an enthusiasm for luxury cars into unusually literal funerary art.', 'limited', null, 'https://www.roadsideamerica.com/tip/7740', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Meridian-Baseline State Park', 'meridian-baseline-state-park', 'weird-history', 42.42302, -84.35616, 'Leslie', 'MI', 'Michigan''s principal meridian and baseline should have met cleanly here, but early nineteenth-century survey crews working independently created a mismatch of more than 900 feet. The small state park preserves survey monuments marking both lines, turning an old mapping error into a walkable geographic curiosity.', 'open', null, 'https://www.michigan.gov/recsearch/parks/meridian', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Meriwether Lewis Monument', 'meriwether-lewis-monument', 'weird-history', 35.5073, -87.4598, 'Hohenwald', 'TN', 'Explorer Meriwether Lewis died under mysterious circumstances at Grinder''s Stand along the Natchez Trace in 1809. A monument and gravesite mark the place, while debate over whether his death was suicide or murder has persisted for generations.', 'open', null, 'https://www.nps.gov/natr/learn/historyculture/exploring-the-meriwether-lewis-site.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Merle Travis Monument', 'merle-travis-monument', 'weird-history', 37.22388, -87.0063, 'Drakesboro', 'KY', 'Country musician Merle Travis, known for his influential fingerpicking style and for writing "Sixteen Tons," was cremated after his death in 1983. His ashes were scattered around this freestanding memorial near Ebenezer Missionary Baptist Church rather than placed beneath a conventional cemetery headstone.', 'open', null, 'https://www.roadsideamerica.com/tip/35082', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Metairie Cemetery', 'metairie-cemetery', 'weird-history', 29.98401, -90.11811, 'New Orleans', 'LA', 'The cemetery occupies the oval footprint of a former racetrack and contains some of Louisiana''s most elaborate mausoleums and funerary sculpture. Its architecture, political burials and unusual tombs make it one of the state''s strongest cemetery stops.', 'limited', null, 'https://www.lakelawnmetairie.com/cemetery/metairie-cemetery', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Metropolitan State Hospital — Surviving Administration Building', 'metropolitan-state-hospital-surviving-administration-building', 'weird-history', 42.40546, -71.21361, 'Waltham', 'MA', 'Most of this former state psychiatric hospital was demolished or redeveloped after its 1992 closure, but the old administration building survives beside public trails and open space. The institution''s history includes documented controversy over neglect and abuse as well as later ghost stories. The surrounding area is public; entering the surviving building is not permitted.', 'limited', null, 'https://www.atlasobscura.com/places/metropolitan-state-hospital-msh', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Michael and Alex Smith Memorial at John D. Long Lake', 'michael-and-alex-smith-memorial-at-john-d-long-lake', 'weird-history', 34.775, -81.511, 'Union', 'SC', 'A memorial near John D. Long Lake remembers Michael and Alex Smith, the two young boys killed by their mother Susan Smith in 1994 after she rolled her car into the lake with them strapped inside. The location became the center of an internationally covered murder case and should be treated respectfully. Lake access: https://www.dnr.sc.gov/lakes/state/johndlong/index.html', 'open', null, 'https://www.roadsideamerica.com/tip/67321', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Michigan Central Station', 'michigan-central-station', 'weird-history', 42.3287, -83.0775, 'Detroit', 'MI', 'Opened in 1913, Michigan Central Station became one of America''s most famous abandoned buildings after passenger service ended in 1988. Ford restored and reopened the monumental station in 2024 as part of an innovation campus, turning a long-standing ruin into one of Detroit''s most dramatic preservation reversals.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/detroit-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Michigan Theatre Parking Garage', 'michigan-theatre-parking-garage', 'weird-history', 42.3345, -83.0531, 'Detroit', 'MI', 'Detroit''s once-opulent 1920s Michigan Theatre was partially gutted and converted into a parking garage rather than completely demolished. Cars now park beneath surviving plasterwork, balconies and fragments of the old auditorium, creating one of the strangest adaptive-reuse spaces in the city.', 'limited', null, 'https://www.atlasobscura.com/places/michigan-theatre', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Michigan Transportation Employees Memorial', 'michigan-transportation-employees-memorial', 'weird-history', 43.85061, -84.77671, 'Clare', 'MI', 'A series of metal figures at the Clare Welcome Center honors Michigan transportation workers killed while performing their jobs. Dedicated in 1994, the memorial turns an interstate rest stop into an unexpectedly somber piece of roadside public art.', 'open', null, 'https://www.atlasobscura.com/places/michigan-transportation-employees-memorial', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Michigan War Dog Memorial', 'michigan-war-dog-memorial', 'weird-history', 42.47586, -83.61374, 'South Lyon', 'MI', 'This memorial park grew from a neglected pet cemetery into a dedicated burial and remembrance site for military, police and service dogs. Rows of markers, memorial walls and ceremonies recognize working animals whose service ranged from combat deployments to law enforcement and assistance work.', 'open', null, 'https://www.roadsideamerica.com/tip/63288', '2026-09-08T15:31:15.588137+00:00', null, 'https://mwdm.org/', null, null, null, 'America/Detroit'),
  ('Micrometer Grave Marker', 'micrometer-grave-marker', 'weird-history', 38.88995, -85.5153, 'Dupont', 'IN', 'Robert D. and Carol L. Hughes are commemorated in Dupont Cemetery with a large stone monument shaped like a precision micrometer, reflecting Robert''s work in the tool-and-die trade. The unusual marker is visible from State Road 7 but should be approached with normal cemetery etiquette.', 'open', null, 'https://www.roadsideamerica.com/tip/17415', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Millstone Bluff Archaeological Area', 'millstone-bluff-archaeological-area', 'weird-history', 37.46665, -88.68764, 'Glendale', 'IL', 'A bluff-top trail reaches a prehistoric stone fort, house depressions, petroglyphs, and burial mounds from Native communities that occupied the site.', 'open', null, 'https://www.fs.usda.gov/recarea/shawnee/recarea/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Milton House Museum', 'milton-house-museum', 'weird-history', 42.77561, -88.94441, 'Milton', 'WI', 'This distinctive hexagonal 1844 inn is Wisconsin''s only certified Underground Railroad site. Guided tours interpret the Goodrich family, abolitionist activity and a concealed passage associated with people escaping slavery.', 'limited', null, 'https://miltonhouse.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://miltonhouse.org/', null, null, null, 'America/Chicago'),
  ('Milton Theatre', 'milton-theatre', 'weird-history', 38.77818, -75.31107, 'Milton', 'DE', 'The historic Milton Theatre has served an unusually long list of purposes, including movie house, basketball hall, fire station, community center and performance venue. It survived major fires, storms, periods of neglect and repeated reinvention before becoming an active theater again.', 'limited', null, 'https://www.miltontheatre.com/history/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.miltontheatre.com/', null, null, null, 'America/New_York'),
  ('Mineral Hills Abandoned Rock Quarry', 'mineral-hills-abandoned-rock-quarry', 'weird-history', 42.31002, -72.73117, 'Northampton', 'MA', 'An abandoned quarry hides along conservation trails in Northampton''s Mineral Hills. The exposed rock walls and flooded or overgrown workings create a dramatic industrial scar inside otherwise wooded public land. Stay on legal trails and keep back from unstable quarry edges.', 'open', null, 'https://www.atlasobscura.com/places/mineral-hills-abandoned-rock-quarry', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mission Creek Cemetery', 'mission-creek-cemetery', 'weird-history', 43.61921, -84.79731, 'Mount Pleasant', 'MI', 'This small Native American cemetery beside Mission Creek contains the grave of Ojibwe leader Shaw-Shaw-Waw-Nay-Beece and memorials connected with local Indigenous history. The site is historically significant rather than a conventional attraction, so visitors should keep to public access areas and treat the burial ground with care.', 'open', null, 'https://www.atlasobscura.com/places/mission-creek-indian-cemetery', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Mississippi Civil Rights Museum', 'mississippi-civil-rights-museum', 'weird-history', 32.30181, -90.17811, 'Jackson', 'MS', 'The state museum devoted to Mississippi''s civil-rights history, including segregation, resistance, organizing, violence and the movement''s major figures. Its central galleries connect many of the individual sites on this list into a broader statewide story.', 'open', null, 'https://mcrm.mdah.ms.gov/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mississippi Industrial Heritage Museum / Soulé Steam Feed Works', 'mississippi-industrial-heritage-museum-soul-steam-feed-works', 'weird-history', 32.36558, -88.69618, 'Meridian', 'MS', 'A preserved late-19th- and early-20th-century industrial complex filled with belt-driven machinery, foundry equipment and steam-era manufacturing technology. Rather than a reconstructed display, much of the museum occupies the original Soulé factory environment.', 'open', null, 'https://www.industrialheritagemuseum.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mississippi Petrified Forest', 'mississippi-petrified-forest', 'weird-history', 32.51438, -90.32299, 'Flora', 'MS', 'A privately operated natural site where ancient petrified logs lie along a walking trail through a 36-million-year-old deposit. The on-site museum and gem/mineral displays push it firmly into OddWay territory without relying on folklore. Coordinate source: https://maps.roadtrippers.com/us/flora-ms/nature/mississippi-petrified-forest', 'open', null, 'https://www.mspetrifiedforest.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mississippi River Basin Model', 'mississippi-river-basin-model', 'weird-history', 32.30606, -90.31894, 'Jackson', 'MS', 'The enormous remains of a hydraulic scale model built by the U.S. Army Corps of Engineers to simulate flooding across the Mississippi River basin. Concrete channels and miniature river systems still spread through the park like the ruins of an abandoned scientific city.', 'open', null, 'https://www.asce.org/about-civil-engineering/history-and-heritage/historic-landmarks/mississippi-basin-model', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Missouri State Penitentiary Museum', 'missouri-state-penitentiary-museum', 'weird-history', 38.572044, -92.163583, 'Jefferson City', 'MO', 'The Missouri State Penitentiary Museum displays prison artifacts, photographs, a replica cell and exhibits covering inmate life, prison industries and the institution''s long history. It complements the nearby penitentiary tours and is more accurately a history museum than a haunted attraction.', 'open', null, 'https://www.missouripentours.com/museum/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.missouripentours.com/history/museum/', null, 'node', 9694350011, 'America/Chicago'),
  ('Moby-Dick Whaleman''s Pulpit', 'moby-dick-whalemans-pulpit', 'weird-history', 41.6352, -70.92375, 'New Bedford', 'MA', 'Herman Melville described a ship''s-bow pulpit inside the Seamen''s Bethel in ''Moby-Dick,'' even though no such pulpit existed there at the time. After a movie adaptation built one, the church eventually installed a permanent version, allowing fiction to reshape the real place that inspired it.', 'open', null, 'https://www.atlasobscura.com/places/seamens-bethel', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Modoc''s Market', 'modocs-market', 'weird-history', 40.79663, -85.82198, 'Wabash', 'IN', 'The shop''s name recalls Modoc, a circus elephant that escaped in Wabash in 1942 and famously crashed through a downtown drugstore during the commotion. A business now operating at the historic location keeps the story alive with elephant imagery and local memorabilia.', 'open', null, 'https://www.atlasobscura.com/places/modocs-market', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Monson Center Ghost Town', 'monson-center-ghost-town', 'weird-history', 42.8354, -71.695, 'Milford', 'NH', 'Monson was an early inland colonial settlement established in the 1730s and abandoned only a few decades later for reasons that remain debated. Today a Forest Society reservation preserves cellar holes, old roads, stone walls and marked homestead sites along roughly three miles of trails. Unlike many alleged ghost towns, this one is specifically protected for public exploration.', 'open', null, 'https://www.forestsociety.org/property/monson-center', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Monument to Birdboy Arthur Smith', 'monument-to-birdboy-arthur-smith', 'weird-history', 41.0779, -85.11295, 'Fort Wayne', 'IN', 'A 40-foot limestone shaft in Memorial Park supports an eight-foot winged figure honoring early aviation daredevil Arthur "Art" Smith. Nicknamed Birdboy, Smith built and flew his own airplane as a teenager, became a nationally known stunt pilot and died in a 1926 air-mail crash.', 'open', null, 'https://www.roadsideamerica.com/story/68684', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Monument to Miantonomo', 'monument-to-miantonomo', 'weird-history', 41.54892, -72.04978, 'Norwich', 'CT', 'A stone monument marks the area traditionally associated with the 1643 killing of Narragansett sachem Miantonomo after his capture during conflict with the Mohegan. The isolated marker preserves a grim episode from southern New England''s colonial and Indigenous history.', 'open', null, 'https://www.atlasobscura.com/places/monument-to-miantonomo', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Monumental Stone Sphere', 'monumental-stone-sphere', 'weird-history', 42.37824, -71.11467, 'Cambridge', 'MA', 'A massive, nearly perfect stone sphere from pre-Columbian Costa Rica sits outside Harvard''s Peabody Museum. Weighing thousands of pounds, it belongs to a mysterious archaeological tradition in which craftspeople shaped enormous boulders into remarkably smooth geometric forms.', 'open', null, 'https://www.atlasobscura.com/places/monumental-stone-sphere', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('MoonPie General Store', 'moonpie-general-store', 'weird-history', 35.0561, -85.31419, 'Chattanooga', 'TN', 'Chattanooga is the birthplace of MoonPie, and this downtown store leans fully into the marshmallow-and-cookie icon with branded merchandise and regional candy history. It is a compact stop tied to one of the South''s strangest enduring snack identities.', 'open', null, 'https://www.atlasobscura.com/places/moonpie-general-store', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Morgan County Dungeon', 'morgan-county-dungeon', 'weird-history', 39.64924, -81.86208, 'Malta', 'OH', 'An underground holding cell used for prisoners in the 1830s was forgotten for more than a century before being rediscovered during excavation in 1964. The dungeon survives near the county jail complex with a historical marker and artifacts, but interior access is not a normal anytime attraction and should be confirmed locally before visiting.', 'limited', null, 'https://www.atlasobscura.com/places/morgan-county-dungeon-ohio', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Morgantown Personal Rapid Transit', 'morgantown-personal-rapid-transit', 'weird-history', 39.62953, -79.9559, 'Morgantown', 'WV', 'Morgantown''s Personal Rapid Transit system is a 1970s federal transportation experiment that became a permanent part of West Virginia University. Small automated cars move riders between stations on a dedicated guideway, making the system itself an unusual piece of living transportation history; rides follow WVU''s current operating schedule.', 'open', null, 'https://www.atlasobscura.com/places/morgantown-prt', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Morikami Museum and Japanese Gardens', 'morikami-museum-and-japanese-gardens', 'weird-history', 26.42781, -80.15796, 'Delray Beach', 'FL', 'Japanese museum and gardens rooted in a little-known early-1900s farming colony.', 'limited', null, 'https://morikami.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mother Jones Museum', 'mother-jones-museum', 'weird-history', 39.0728, -89.7278, 'Mount Olive', 'IL', 'A small museum inside Mount Olive City Hall interprets coal mining, labor conflict, and the life and legacy of organizer Mother Jones.', 'limited', null, 'https://www.motherjonesmuseum.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mound City National Cemetery', 'mound-city-national-cemetery', 'weird-history', 37.08748, -89.178, 'Mound City', 'IL', 'Thousands of Civil War dead are buried in this national cemetery established beside wartime hospitals and naval facilities along the Ohio River.', 'open', null, 'https://www.cem.va.gov/cems/nchp/moundcity.asp', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mound House', 'mound-house', 'weird-history', 26.4461, -81.9279, 'Fort Myers Beach', 'FL', 'Museum and archaeological site built directly atop a nearly 2,000-year-old Calusa shell mound.', 'open', null, 'https://moundhouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mound Key Archaeological State Park', 'mound-key-archaeological-state-park', 'weird-history', 26.4317, -81.92249, 'Estero', 'FL', 'Boat-access shell-mound island believed to have been the capital of the Calusa.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/mound-key-archaeological-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mounds State Park Earthworks', 'mounds-state-park-earthworks', 'weird-history', 40.09576, -85.62007, 'Anderson', 'IN', 'Mounds State Park protects a group of prehistoric earthworks constructed by Indigenous peoples beginning more than two thousand years ago. The largest, the Great Mound, is an impressive circular earthwork that can be reached from maintained park trails.', 'open', null, 'https://www.in.gov/dnr/state-parks/parks-lakes/mounds-state-park/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Moundville Archaeological Park', 'moundville-archaeological-park', 'weird-history', 33.00272, -87.62814, 'Moundville', 'AL', 'Dozens of Mississippian platform mounds survive at one of the most important Indigenous archaeological sites in the Southeast. A museum and walking paths interpret the city that flourished here centuries before European colonization.', 'open', null, 'https://moundville.museums.ua.edu/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mount Arvon', 'mount-arvon', 'weird-history', 46.75549, -88.15596, 'Skanee', 'MI', 'Michigan''s highest point was not officially recognized as the state high point until improved measurements showed it exceeded nearby Mount Curwood by roughly 11 inches. Reaching the summit involves remote logging roads and a short hike, so road conditions can make access difficult during wet or snowy weather.', 'limited', null, 'https://www.atlasobscura.com/places/mount-arvon', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Mount Auburn Cemetery', 'mount-auburn-cemetery', 'weird-history', 42.3709, -71.14634, 'Cambridge', 'MA', 'America''s first large landscaped rural cemetery mixes elaborate monuments, mausoleums, unusual funerary sculpture, ponds and a hilltop tower across more than 170 acres. It helped change American ideas about what a cemetery could look like.', 'open', null, 'https://www.mountauburn.org/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Hope Cemetery', 'mount-hope-cemetery', 'weird-history', 44.82442, -68.71984, 'Bangor', 'ME', 'One of the country’s oldest garden cemeteries, Mount Hope is full of elaborate monuments, wooded lanes, and centuries of Bangor history. Horror fans also know it as a filming location used in Stephen King’s Pet Sematary.', 'limited', null, 'https://www.atlasobscura.com/places/mount-hope-cemetery-bangor', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Locust Historic Stand', 'mount-locust-historic-stand', 'weird-history', 31.68691, -91.18914, 'Lorman', 'MS', 'One of the last surviving historic stands on the Natchez Trace, where travelers once stopped for food and shelter. As of 2026 the historic structure has a closure tied to structural damage, although the site/grounds have had limited public access; verify conditions before routing a traveler here.', 'limited', null, 'https://www.nps.gov/places/mount-locust.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mount Mitchill 9/11 Memorial', 'mount-mitchill-9-11-memorial', 'weird-history', 40.40722, -74.00442, 'Atlantic Highlands', 'NJ', 'At New Jersey''s highest natural point on the Atlantic seaboard, a memorial overlooks the New York skyline and honors Monmouth County residents killed on September 11, 2001. Its centerpiece incorporates an eagle clutching a twisted steel beam recovered from the World Trade Center.', 'open', null, 'https://www.monmouthcountyparks.com/page.aspx?ID=2530', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Moriah Cemetery', 'mount-moriah-cemetery', 'weird-history', 39.93106, -75.23583, 'Philadelphia', 'PA', 'Once one of Pennsylvania''s largest Victorian cemeteries, Mount Moriah fell into severe abandonment after its old cemetery association disappeared, leaving mausoleums and graves swallowed by vegetation. Volunteers have reopened substantial sections, but public access is normally limited to weather-dependent weekend gate hours and visitors should stay on cleared routes.', 'limited', null, 'https://friendsofmountmoriahcemetery.org/visit/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Zion United Methodist Church — Freedom Summer Site', 'mount-zion-united-methodist-church-freedom-summer-site', 'weird-history', 32.7821, -88.99152, 'Philadelphia', 'MS', 'The church congregation was attacked and its building burned in 1964 during the campaign that preceded the murders of James Chaney, Andrew Goodman and Michael Schwerner. It remains a religious and memorial site, so visitors should respect church use and current access.', 'limited', null, 'https://www.nps.gov/subjects/civilrights/mississippi.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mountain Dew Headstone', 'mountain-dew-headstone', 'weird-history', 36.31472, -82.35667, 'Johnson City', 'TN', 'A cemetery marker celebrates the soft drink Mountain Dew with branding tied to the beverage''s East Tennessee origins. It is a compact piece of commercial folklore hidden among ordinary graves; visit respectfully and only during cemetery access.', 'limited', null, 'https://www.atlasobscura.com/places/mountain-dew-headstone', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Muhammad Ali Statue', 'muhammad-ali-statue', 'weird-history', 44.0979, -70.2203, 'Lewiston', 'ME', 'A 10-foot bronze Muhammad Ali was unveiled in 2025 near Bates Mill No. 5 to mark 60 years since Ali’s bizarrely brief 1965 rematch with Sonny Liston in Lewiston. The fight ended in the first round after the controversial “phantom punch,” creating one of the strangest heavyweight-title moments in boxing history.', 'open', null, 'https://www.roadsideamerica.com/tip/87760', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Murray Hall', 'murray-hall', 'weird-history', 41.809501, -96.024678, 'Little Sioux', 'IA', 'Built in 1877 as a two-storey false-front general store for the merchant Michael Murray, and a rare survivor of that kind of frontier commercial building. It is a museum and reception space in Little Sioux, Iowa — not Tekamah, Nebraska, as the mapping suggested. Walk-in hours are not clearly published, so check before making a special trip.', 'limited', null, 'https://www.nps.gov/places/little-sioux-iowa.htm', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Muscle Shoals Sound Studio — 3614 Jackson Highway', 'muscle-shoals-sound-studio-3614-jackson-highway', 'weird-history', 34.76778, -87.67389, 'Sheffield', 'AL', 'The small studio where the Muscle Shoals Rhythm Section recorded major artists remains preserved at its famous 3614 Jackson Highway address. Guided tours show the recording rooms and equipment tied to an outsized chapter of American music history.', 'limited', null, 'https://muscleshoalssoundstudio.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Myles Standish Monument', 'myles-standish-monument', 'weird-history', 42.01391, -70.68217, 'Duxbury', 'MA', 'A 116-foot granite tower topped by a statue of Pilgrim military leader Myles Standish rises from a hill overlooking Duxbury. The unusually tall nineteenth-century monument looks like a stone watchtower and opens for interior climbing only on selected dates.', 'limited', null, 'https://www.mass.gov/locations/myles-standish-monument-state-reservation', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mysterious Chappaquiddick Shipwreck', 'mysterious-chappaquiddick-shipwreck', 'weird-history', 41.37418, -70.4494, 'Edgartown', 'MA', 'The shifting sand of Chappaquiddick periodically exposes wooden wreckage believed to belong to the Christina, lost in 1866. One survivor reportedly clung to the mast for more than two days. Visibility changes with storms and sand movement, and reaching the area can require ferry and beach-access planning.', 'limited', null, 'https://www.atlasobscura.com/places/mysterious-chappaquiddick-shipwreck', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nancy Kerlin Barnett Grave', 'nancy-kerlin-barnett-grave', 'weird-history', 39.41989, -85.97592, 'Amity', 'IN', 'Nancy Kerlin Barnett was buried here in 1831, and when officials later wanted to build a road through the burial ground, her descendants resisted moving her grave. The compromise left the burial site protected in the middle of County Road 400 South, where traffic still splits around the fenced grave and the additional remains discovered there in 2016.', 'roadside', null, 'https://www.atlasobscura.com/places/nancy-kerlin-barnett-grave', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Nansen Ski Jump', 'nansen-ski-jump', 'weird-history', 44.53068, -71.16444, 'Milan', 'NH', 'The enormous Nansen Ski Jump rises above the North Country like an industrial skeleton built into the hillside. Completed in the 1930s, it hosted major competitions and Olympic trials and was once among the largest ski jumps in the eastern United States. The state historic site preserves the structure and surrounding grounds, but visitors should obey barriers and never climb the tower.', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/nansen-ski-jump-state-historic-site', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Napoleon House', 'napoleon-house', 'weird-history', 29.95586, -90.06507, 'New Orleans', 'LA', 'The building takes its name from an unrealized plan to shelter Napoleon Bonaparte in New Orleans after his exile. Its weathered interior, classical music tradition and layers of political lore make it unusually intact French Quarter history.', 'open', null, 'https://www.napoleonhouse.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nathan Stubblefield''s Grave', 'nathan-stubblefields-grave', 'weird-history', 36.62748, -88.29273, 'Murray', 'KY', 'Self-taught inventor Nathan Stubblefield publicly demonstrated wireless voice transmission in 1902 but died poor and largely forgotten in 1928. His later headstone in Bowman Cemetery boldly identifies him as the inventor of wireless telephony or radio, reflecting the continuing debate over how his experiments fit into radio history.', 'open', null, 'https://www.roadsideamerica.com/tip/55690', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Civil Rights Museum', 'national-civil-rights-museum', 'weird-history', 35.13469, -90.0577, 'Memphis', 'TN', 'The museum incorporates the Lorraine Motel, where Martin Luther King Jr. was assassinated in 1968, and traces a broad history of the struggle for civil rights. The preserved motel exterior and room context make this a major dark-history site that should be approached with appropriate seriousness.', 'open', null, 'https://www.civilrightsmuseum.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Corvette Museum Sinkhole', 'national-corvette-museum-sinkhole', 'weird-history', 37.0037, -86.3729, 'Bowling Green', 'KY', 'In February 2014, a sinkhole suddenly opened beneath the National Corvette Museum''s Skydome and swallowed eight rare Corvettes. The museum recovered the cars and incorporated the disaster into its exhibits, preserving damaged vehicles and the story of one of the strangest museum accidents in automotive history.', 'limited', null, 'https://www.corvettemuseum.org/sinkhole/', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.corvettemuseum.org/', null, null, null, 'America/Chicago'),
  ('National Hansen''s Disease Museum', 'national-hansens-disease-museum', 'weird-history', 30.21717, -91.09577, 'Carville', 'LA', 'The museum occupies part of the former national leprosarium at Carville and interprets Hansen''s disease, treatment, stigma and the lives of patients who lived there. It sits within a Louisiana National Guard installation, so visitors must follow current gate and identification procedures.', 'limited', null, 'https://www.hrsa.gov/hansens-disease/museum', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Memorial for Peace and Justice', 'national-memorial-for-peace-and-justice', 'weird-history', 32.37611, -86.31194, 'Montgomery', 'AL', 'The memorial honors thousands of victims of racial terror lynching with suspended steel monuments representing U.S. counties where documented killings occurred. It is a solemn site designed for remembrance and historical reckoning rather than casual sightseeing.', 'open', null, 'https://museumandmemorial.eji.org/memorial', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Monument to the Forefathers', 'national-monument-to-the-forefathers', 'weird-history', 41.96014, -70.67585, 'Plymouth', 'MA', 'An enormous 81-foot granite monument dominates a hill above Plymouth. Completed in the nineteenth century, it surrounds a towering central figure of Faith with allegorical sculptures representing morality, law, education and liberty, giving it the scale and visual drama of a fantasy monument.', 'open', null, 'https://www.atlasobscura.com/places/national-monument-to-the-forefathers', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Natural Bridge Battlefield Historic State Park', 'natural-bridge-battlefield-historic-state-park', 'weird-history', 30.28206, -84.1487, 'Tallahassee', 'FL', 'Civil War battlefield where the St. Marks River disappears underground before reemerging.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/natural-bridge-battlefield-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Navesink Twin Lights', 'navesink-twin-lights', 'weird-history', 40.39622, -73.98578, 'Highlands', 'NJ', 'Two lighthouse towers joined by a fortress-like building overlook Sandy Hook from the Navesink Highlands. The site played roles in lighthouse technology, early wireless communication and radar history, making it far stranger than a standard coastal light station.', 'limited', null, 'https://www.twinlightslighthouse.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Negro Southern League Museum', 'negro-southern-league-museum', 'weird-history', 33.50838, -86.80953, 'Birmingham', 'AL', 'The museum preserves uniforms, photographs, equipment and stories from Black baseball and the Negro Southern League. Its collection documents players and teams that operated within segregated American baseball.', 'open', null, 'https://www.birminghamnslm.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Neptune Memorial Reef', 'neptune-memorial-reef', 'weird-history', 25.70831, -80.09518, 'Key Biscayne', 'FL', 'Underwater memorial cemetery designed like a sunken city.', 'open', null, 'https://www.nmreef.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Neverbust Chain', 'neverbust-chain', 'weird-history', 34.0056, -81.03498, 'Columbia', 'SC', 'A heavy iron chain displayed near the South Carolina State House carries an old story that it was once stretched across the Congaree River and advertised as impossible to break. Whether every part of the legend is accurate or not, the surviving chain became a peculiar local monument.', 'open', null, 'https://www.atlasobscura.com/places/neverbust-chain', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Canal Lighthouse', 'new-canal-lighthouse', 'weird-history', 30.02717, -90.11317, 'New Orleans', 'LA', 'The reconstructed lighthouse on Lake Pontchartrain interprets local navigation, storms and coastal history at the mouth of the New Basin Canal. Museum access follows posted hours even though the exterior can be seen from the lakefront.', 'limited', null, 'https://scienceforourcoast.org/new-canal-lighthouse/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('New Castle-Frenchtown Railroad Ticket Office', 'new-castle-frenchtown-railroad-ticket-office', 'weird-history', 39.65781, -75.56219, 'New Castle', 'DE', 'A tiny surviving ticket office recalls the New Castle and Frenchtown Railroad, one of the earliest rail lines in the United States. The miniature building is fenced from entry but can be viewed as an exceptionally small remnant of early American rail travel.', 'open', null, 'https://www.atlasobscura.com/things-to-do/delaware/places', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Haven Green — Bodies Underfoot', 'new-haven-green-bodies-underfoot', 'weird-history', 41.3076, -72.92649, 'New Haven', 'CT', 'New Haven''s central Green looks like an ordinary civic park, but it served as the community burial ground for generations. Most old headstones were moved elsewhere while thousands of human remains were left underground; Hurricane Sandy famously exposed skeletal remains beneath a fallen tree in 2012.', 'open', null, 'https://thenewhavengreen.org/history/', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Hope''s Sodom Renaming Marker', 'new-hopes-sodom-renaming-marker', 'weird-history', 42.7979, -76.34678, 'Moravia', 'NY', 'This hamlet was once known as Sodom until, according to local lore, a man climbed the ridgepole of a new gristmill in 1823 with a jug of whiskey and proclaimed that the struggling village had "new hope." The story of the unusual christening is now preserved on a Legends & Lore marker along NY-41A.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/new-hope-named/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Orleans Jazz Museum at the Old U.S. Mint', 'new-orleans-jazz-museum-at-the-old-us-mint', 'weird-history', 29.96136, -90.05781, 'New Orleans', 'LA', 'The former U.S. Mint now houses Louisiana State Museum collections tracing the development of jazz. Instruments, recordings and a building that once produced money create an unusual overlap of music and industrial history.', 'open', null, 'https://nolajazzmuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('New Smyrna Sugar Mill Ruins', 'new-smyrna-sugar-mill-ruins', 'weird-history', 29.02488, -81.05664, 'New Smyrna Beach', 'FL', 'Atmospheric coquina ruins of a 19th-century sugar mill.', 'limited', null, 'https://www.volusia.org/services/community-services/parks-recreation-and-culture/parks-and-trails/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nicholas Jarrot Mansion', 'nicholas-jarrot-mansion', 'weird-history', 38.57, -90.1875, 'Cahokia Heights', 'IL', 'A rare surviving example of Federal-period architecture built for a French-American merchant stands within the historic Cahokia settlement area.', 'limited', null, 'https://dnrhistoric.illinois.gov/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nina Simone’s Childhood Home', 'nina-simones-childhood-home', 'weird-history', 35.21385, -82.23216, 'Tryon', 'NC', 'A modest three-room wooden house is where Eunice Kathleen Waymon, later known as Nina Simone, spent part of her childhood and began playing piano at an exceptionally young age. The historically significant home has been preserved through an artist-led effort rather than turned into a conventional museum.', 'roadside', null, 'https://www.atlasobscura.com/places/nina-simone-childhood-home', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nine Men''s Misery', 'nine-mens-misery', 'weird-history', 41.93982, -71.40662, 'Cumberland', 'RI', 'A stone monument in the woods marks the place where nine colonial soldiers were killed during King Philip''s War in 1676. Their remains were later excavated and reburied more than once before eventually being returned to the site. The memorial is reached by trail inside the Monastery property.', 'open', null, 'https://www.atlasobscura.com/places/nine-mens-misery', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('North Alabama Railroad Museum', 'north-alabama-railroad-museum', 'weird-history', 34.78347, -86.54588, 'Huntsville', 'AL', 'The museum preserves locomotives, passenger cars, freight equipment and the historic Chase Depot, with excursion trains offered on selected dates. The combination of rolling stock and a functioning heritage railroad makes it a strong industrial-history stop.', 'limited', null, 'https://narm.info/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('North Brother Island', 'north-brother-island', 'weird-history', 40.80066, -73.89875, 'Bronx', 'NY', 'North Brother Island held Riverside Hospital, where New York isolated patients with contagious diseases and where Mary Mallon, better known as Typhoid Mary, spent years in quarantine. Hospital ruins remain overgrown across the island, but it is a protected wildlife area with no ordinary public access, so travelers should not attempt to land there.', 'closed', null, 'https://en.wikipedia.org/wiki/North_and_South_Brother_Islands_(New_York_City)', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Northeast Historic Film at the Alamo Theatre', 'northeast-historic-film-at-the-alamo-theatre', 'weird-history', 44.57225, -68.79543, 'Bucksport', 'ME', 'A restored 1916 cinema houses Northeast Historic Film, an archive dedicated to preserving moving images from northern New England. The collection includes home movies, local television, industrial films, advertisements, and other footage that might otherwise have disappeared.', 'limited', null, 'https://www.atlasobscura.com/places/northeast-historic-film', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Northfield Drive-In Theater', 'northfield-drive-in-theater', 'weird-history', 42.72724, -72.44959, 'Hinsdale', 'NH', 'The Northfield Drive-In sits directly along the New Hampshire–Massachusetts state line, and its unusual placement is tied to historic differences in movie-projection labor rules. The drive-in also appeared in the film "The Cider House Rules." It continues to operate seasonally, so check the current movie schedule before routing here.', 'limited', null, 'https://www.atlasobscura.com/places/northfield-drive-in-theater', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.northfielddrivein.com/', null, null, null, 'America/New_York'),
  ('Nuclear Energy Sculpture / Chicago Pile-1 Site', 'nuclear-energy-sculpture-chicago-pile-1-site', 'weird-history', 41.79249, -87.60106, 'Chicago', 'IL', 'Henry Moore''s looming sculpture marks the site where scientists achieved the first controlled, self-sustaining nuclear chain reaction in 1942.', 'open', null, 'https://www.nps.gov/places/site-of-the-first-self-sustaining-controlled-nuclear-chain-reaction.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nuttallburg', 'nuttallburg', 'weird-history', 38.05019, -81.03976, 'Nuttallburg', 'WV', 'Nuttallburg was once a major New River Gorge coal town and later became associated with Henry Ford''s attempt to control his own industrial supply chain. Today the National Park Service preserves mine structures, foundations and the enormous coal conveyor, but getting into the site involves narrow roads, trails and steep terrain.', 'limited', null, 'https://www.nps.gov/neri/learn/historyculture/nuttallburg.htm', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oak Ridge History Museum', 'oak-ridge-history-museum', 'weird-history', 36.01274, -84.26533, 'Oak Ridge', 'TN', 'This local museum focuses on everyday life in the secret wartime city, including housing, schools, security and the people who built Oak Ridge. It complements the larger science museums by emphasizing the strange social reality of a city that barely existed on public maps.', 'open', null, 'https://www.oakridgemuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Oakland Plantation — Cane River Creole NHP', 'oakland-plantation-cane-river-creole-nhp', 'weird-history', 31.66561, -93.00359, 'Natchez', 'LA', 'Oakland preserves a remarkably complete plantation complex with quarters, store, barns and the main house, allowing the National Park Service to interpret generations of Creole plantation life and enslaved labor. Building access varies by day even when grounds are open.', 'limited', null, 'https://www.nps.gov/cari/planyourvisit/oakland-plantation.htm', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Oaklawn Cemetery', 'oaklawn-cemetery', 'weird-history', 27.95832, -82.45976, 'Tampa', 'FL', 'Tampa''s oldest public cemetery with pioneer graves and layers of local lore.', 'open', null, 'https://www.tampa.gov/parks-and-recreation', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ohio Statehouse Fossils', 'ohio-statehouse-fossils', 'weird-history', 39.9601, -82.99946, 'Columbus', 'OH', 'The limestone used throughout the Ohio Statehouse contains visible fossils from ancient seas, including corals, brachiopods, sponges and other marine life hundreds of millions of years old. Visitors can use the state''s fossil guide to hunt for them in public portions of the Capitol building during open hours.', 'open', null, 'https://www.atlasobscura.com/places/ohio-statehouse-fossils', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('O''Hurley''s General Store', 'ohurleys-general-store', 'weird-history', 39.42788, -77.80427, 'Shepherdstown', 'WV', 'O''Hurley''s operates as an old-fashioned general store filled with hardware, household goods, musical instruments and objects that feel pulled from an earlier version of the town. The working store is open to visitors and is also known for recurring traditional music gatherings.', 'open', null, 'https://www.ohurleys.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Absinthe House', 'old-absinthe-house', 'weird-history', 29.95537, -90.06845, 'New Orleans', 'LA', 'The Old Absinthe House has served drinks near Bourbon Street since the nineteenth century and accumulated stories involving pirates, politicians, writers and supposed secret meetings. Its surviving marble fountains and long bar history make it a classic New Orleans odd-history stop.', 'open', null, 'https://www.ruebourbon.com/oldabsinthehouse', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Bet Elephant Memorial', 'old-bet-elephant-memorial', 'weird-history', 43.45722, -70.71944, 'Alfred', 'ME', 'A roadside marker commemorates the place where the traveling circus elephant Old Bet was reportedly shot and killed in 1816. The bizarre episode became part of early American circus history, and a granite monument now marks the location.', 'roadside', null, 'https://www.roadsideamerica.com/story/53175', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Biloxi Cemetery', 'old-biloxi-cemetery', 'weird-history', 30.39611, -88.91056, 'Biloxi', 'MS', 'One of the Gulf Coast''s oldest surviving cemeteries, with French-inscribed stones, above-ground tombs, notable coastal figures and visible evidence of repeated hurricane damage and restoration. The cemetery remains active historic ground, so visitors should stay respectful and follow city rules. Secondary source: https://msgulfcoastheritage.ms.gov/historic/sites/old-biloxi-cemetery/', 'open', null, 'https://discover.biloxi.ms.us/old-biloxi-cemetery/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Cahawba Archaeological Park', 'old-cahawba-archaeological-park', 'weird-history', 32.31963, -87.10463, 'Orrville', 'AL', 'Alabama’s first permanent state capital was abandoned after floods, political change and economic decline. Roads, ruins, cemeteries and archaeological remains now form an official historic park where an entire former town can be explored.', 'open', null, 'https://www.oldcahawba.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Cannonball Jail', 'old-cannonball-jail', 'weird-history', 39.27845, -89.87755, 'Carlinville', 'IL', 'The thick-walled 1869 stone jail preserves cells, sheriff quarters, and frontier-era incarceration history and reopened for visitors after restoration.', 'limited', null, 'https://cityofcarlinville.com/tourism/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Capitol Museum', 'old-capitol-museum', 'weird-history', 32.2981, -90.18, 'Jackson', 'MS', 'Mississippi''s former state capitol, now a museum interpreting the building''s political history and the events that occurred inside it. Its Greek Revival interiors, layered state history and longstanding local ghost stories make it relevant to OddWay, though paranormal claims should remain clearly identified as stories rather than fact.', 'open', null, 'https://www.mdah.ms.gov/explore-mississippi/old-capitol-museum', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Carbonton Dam Powerhouse', 'old-carbonton-dam-powerhouse', 'weird-history', 35.52043, -79.34891, 'Sanford', 'NC', 'Most of the Carbonton Dam was removed to restore the Deep River, but a tall abandoned concrete powerhouse was left behind beside a small public recreation area. The graffiti-covered shell now stands as an eerie industrial remnant beside the restored river.', 'open', null, 'https://www.atlasobscura.com/places/old-carbonton-dam', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Catskill Game Farm', 'old-catskill-game-farm', 'weird-history', 42.23924, -74.00823, 'Catskill', 'NY', 'The Catskill Game Farm operated from 1933 to 2006 and was once promoted as America''s largest privately owned zoo. Many empty cages, paths and zoo buildings still survive, but the property is now an inn and campground and only overnight guests currently have permission to explore the abandoned zoo grounds.', 'limited', null, 'https://www.theoldgamefarm.com/faqs', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old City Hall Subway Station', 'old-city-hall-subway-station', 'weird-history', 40.71264, -74.00668, 'New York', 'NY', 'The ornate original City Hall subway station opened with New York''s first subway line in 1904 and closed to passengers in 1945, leaving its Guastavino tile vaults and chandeliers intact underground. Entry is restricted to rare New York Transit Museum member tours that require advance tickets and a security background check.', 'limited', null, 'https://www.nytransitmuseum.org/old-city-hall/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Courthouse Heritage Museum', 'old-courthouse-heritage-museum', 'weird-history', 28.83675, -82.33049, 'Inverness', 'FL', 'Historic courthouse museum tied to Citrus County history and Elvis Presley''s filming of Follow That Dream.', 'limited', null, 'https://cccourthouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Economy Village', 'old-economy-village', 'weird-history', 40.59611, -80.23194, 'Ambridge', 'PA', 'The Harmony Society established Economy in 1824 as a highly organized religious communal settlement while its members awaited the Second Coming. Seventeen historic buildings, gardens and original artifacts survive as a state historic site, with public access during its seasonal operating schedule.', 'limited', null, 'https://www.pa.gov/agencies/phmc/historic-sites-and-museums/rural-farm-and-village-history-trail/old-economy', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Fort Park Ruins', 'old-fort-park-ruins', 'weird-history', 29.02566, -80.92334, 'New Smyrna Beach', 'FL', 'Mysterious coquina foundation traditionally called the ''Old Fort,'' with disputed original purpose.', 'limited', null, 'https://www.cityofnsb.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Franklin Park Zoo Bear Pens', 'old-franklin-park-zoo-bear-pens', 'weird-history', 42.30248, -71.087, 'Boston', 'MA', 'Concrete and stone remnants of the old Franklin Park Zoo bear enclosures survive in the woods, long after the animals moved to modern habitats. The abandoned pens were also used as a filming location for ''Mystic River.'' Current signs prohibit entry into the structures, so view them only from permitted trails and areas.', 'roadside', null, 'https://www.atlasobscura.com/places/old-franklin-park-zoo-bear-pens', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Gray Cemetery', 'old-gray-cemetery', 'weird-history', 35.97423, -83.92587, 'Knoxville', 'TN', 'Established in the nineteenth century, Old Gray is filled with elaborate monuments, Victorian funerary art and the graves of prominent East Tennesseans. Its sculpture and symbolism make it an outdoor museum of death customs, but normal cemetery etiquette applies.', 'limited', null, 'https://www.oldgraycemetery.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Jail', 'old-jail', 'weird-history', 29.90169, -81.31577, 'St. Augustine', 'FL', '1908 jail preserved with cells, sheriff''s quarters, and gallows-era interpretation.', 'limited', null, 'https://www.trolleytours.com/st-augustine/old-jail', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Joliet Prison', 'old-joliet-prison', 'weird-history', 41.54572, -88.0729, 'Joliet', 'IL', 'The massive limestone prison operated from 1858 to 2002 and now offers tours through cellblocks, yards, and locations familiar from film and television.', 'limited', null, 'https://www.jolietprison.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Lake County Sheriff''s House and Jail', 'old-lake-county-sheriffs-house-and-jail', 'weird-history', 41.41563, -87.36373, 'Crown Point', 'IN', 'This historic jail became nationally famous after John Dillinger escaped from it in March 1934, reportedly using a fake gun to bluff his way past guards. The preserved complex has also developed a reputation among paranormal groups, but visitors should use official tours and events rather than attempting unscheduled access.', 'limited', null, 'https://www.hauntedplaces.org/item/crown-point-sheriffs-house-and-jail/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Lebanon Church Ruins', 'old-lebanon-church-ruins', 'weird-history', 34.38974, -81.17967, 'Winnsboro', 'SC', 'Isolated along Old Airport Road are the stone remains of the original Lebanon Presbyterian Church, a congregation organized in 1774. The surviving stone sanctuary was erected around 1780 and served for more than a century before being judged unsafe and abandoned when the congregation moved in 1893. An old graveyard surrounds the ruins; treat the site as a historic cemetery and obey any fencing or posted restrictions.', 'limited', null, 'https://www.scpictureproject.org/fairfield-county/old-lebanon-church.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Man of the Mountain Profile Plaza', 'old-man-of-the-mountain-profile-plaza', 'weird-history', 44.16568, -71.67882, 'Franconia', 'NH', 'New Hampshire''s famous Old Man of the Mountain rock profile collapsed from Cannon Cliff in 2003. At Profile Plaza, steel "profilers" allow visitors to stand at specific points and visually reconstruct the vanished face against the cliff. The memorial turns an absent landmark into something visitors can still physically line up and see. Secondary source: https://www.hmdb.org/m.asp?m=81875', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/franconia-notch-state-park', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Market House State Historic Site', 'old-market-house-state-historic-site', 'weird-history', 42.41575, -90.42739, 'Galena', 'IL', 'A preserved 1845 market building now interprets Galena''s boom years, including mining, river commerce, and Ulysses S. Grant-era history.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/northwest/old-market-house.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Molson Ghost Town Museum', 'old-molson-ghost-town-museum', 'weird-history', 48.976171, -119.19968, 'Oroville', 'WA', 'Old Molson Ghost Town Museum preserves a collection of pioneer buildings, farm machinery, mining equipment and other artifacts in the former townsite of Molson. The outdoor museum is free to explore, but remote location, snow and seasonal conditions can affect practical access.', 'limited', null, 'https://molsonmuseums.org/', '2026-09-05T22:12:28.444612+00:00', null, 'https://molsonmuseums.org/gallery1/', '+1-509-485-3292', 'way', 428128256, 'America/Los_Angeles'),
  ('Old Monroe County Courthouse Museum', 'old-monroe-county-courthouse-museum', 'weird-history', 31.5271, -87.3242, 'Monroeville', 'AL', 'The preserved courtroom helped inspire the fictional trial setting in Harper Lee’s To Kill a Mockingbird and was carefully recreated for the film adaptation. Exhibits also cover Lee, Truman Capote and Monroe County history.', 'open', null, 'https://www.monroecountymuseum.org/old-courthouse-museum', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old New-Gate Prison & Copper Mine', 'old-new-gate-prison-copper-mine', 'weird-history', 41.96272, -72.745, 'East Granby', 'CT', 'America''s first state prison was created inside an old copper mine, where prisoners were lowered into underground chambers that proved almost impossible to manage. The preserved ruins and mine tunnels can be toured seasonally.', 'limited', null, 'https://www.atlasobscura.com/places/old-newgate-prison', '2026-09-08T18:39:47.144889+00:00', null, 'https://portal.ct.gov/DECD/Content/Historic-Preservation/04_State_Museums/Old-New-Gate-Prison-and-Copper-Mine', null, null, null, 'America/New_York'),
  ('Old Post Sanitarium', 'old-post-sanitarium', 'weird-history', 33.19201, -101.38364, 'Post', 'TX', 'The Old Post Sanitarium marker documents the early hospital established in Post in the 1910s and the development of organized medical care in the area. OddWay visitors are primarily stopping for the roadside historical plaque and exterior historic setting rather than a haunted-hospital experience.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, 'https://atlas.thc.texas.gov/Details/5169003783', null, 'node', 12403562982, 'America/Chicago'),
  ('Old Powder House', 'old-powder-house', 'weird-history', 42.40007, -71.11622, 'Somerville', 'MA', 'A squat stone tower built around 1703 began as a windmill before becoming a colonial gunpowder magazine. Its stored powder played a role in rising tensions before the American Revolution, and the lonely tower now sits inside a public neighborhood park.', 'open', null, 'https://www.atlasobscura.com/places/old-powder-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Saluda Factory Ruins', 'old-saluda-factory-ruins', 'weird-history', 34.01058, -81.08136, 'West Columbia', 'SC', 'Blue-granite foundations and old waterworks survive along the Saluda River from one of the South''s early textile mills, begun in 1834. The site later became Camp Sorghum, where roughly 1,300 Union prisoners were held during the Civil War; the factory was burned in 1865, rebuilt, and destroyed by another fire in 1884. The ruins are visible along the River Trail at Riverbanks Zoo and Botanical Garden, so access follows the surrounding attraction and trail rules.', 'limited', null, 'https://www.scpictureproject.org/lexington-county/old-saluda-factory.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Sheldon Church Ruins', 'old-sheldon-church-ruins', 'weird-history', 32.61853, -80.78044, 'Yemassee', 'SC', 'Brick columns and walls from an 18th-century church stand roofless beneath live oaks in the Lowcountry. The building was damaged during the Revolutionary War, rebuilt, and later left in ruins after the Civil War, producing one of South Carolina’s most atmospheric roadside historic sites.', 'open', null, 'https://www.scpictureproject.org/beaufort-county/old-sheldon-church.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Slave Mart Museum', 'old-slave-mart-museum', 'weird-history', 32.77795, -79.92842, 'Charleston', 'SC', 'This building is part of the only known surviving complex once used as a commercial slave auction facility in South Carolina. The museum confronts Charleston’s central role in the domestic slave trade through artifacts, documents, and interpretation of the people bought and sold here.', 'limited', null, 'https://www.charleston-sc.gov/160/Old-Slave-Mart-Museum', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Spanish Fort Site', 'old-spanish-fort-site', 'weird-history', 30.0224, -90.0842, 'New Orleans', 'LA', 'This lakefront area passed through Native American use, colonial fortification, resort development and an amusement-park era. Very little of the entertainment complex survives, making the site a layered landscape of vanished New Orleans recreation.', 'open', null, 'https://www.atlasobscura.com/places/old-spanish-fort', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old State Bank', 'old-state-bank', 'weird-history', 34.61432, -86.98365, 'Decatur', 'AL', 'This Greek Revival bank building opened in the 1830s and survived the Civil War destruction that erased much of Decatur. Its survival makes it a rare physical remnant of the city that existed before wartime rebuilding.', 'limited', null, 'https://www.decatur-al.gov/explore/things_to_do/museums_and_tours/old_state_bank.php', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Stone Church', 'old-stone-church', 'weird-history', 42.37504, -71.78286, 'West Boylston', 'MA', 'A roofless stone church stands beside the Wachusett Reservoir as one of the few visible remnants of a community displaced when the reservoir was created. The building was stripped and preserved rather than submerged, leaving a lonely Gothic-looking shell beside the water.', 'open', null, 'https://www.atlasobscura.com/places/old-stone-church', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Stone Fort State Archaeological Park', 'old-stone-fort-state-archaeological-park', 'weird-history', 35.48261, -86.10479, 'Manchester', 'TN', 'An ancient Native American ceremonial enclosure occupies a dramatic plateau above river gorges and waterfalls. As of September 2026, bridge construction affects some vehicle and pedestrian circulation, so check current park alerts before routing.', 'limited', null, 'https://tnstateparks.com/parks/old-stone-fort', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Tennessee State Prison', 'old-tennessee-state-prison', 'weird-history', 36.17781, -86.86597, 'Nashville', 'TN', 'The castle-like former state prison operated from the nineteenth century into the 1990s and later became a recognizable film location. The complex is restricted and unsafe for casual entry; OddWay should route only to lawful exterior viewpoints and never encourage trespassing.', 'roadside', null, 'https://www.atlasobscura.com/places/old-tennessee-state-prison', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Oldest House Museum & Garden', 'oldest-house-museum-garden', 'weird-history', 24.55554, -81.80314, 'Key West', 'FL', 'One of Key West''s oldest surviving houses, filled with island history and period artifacts.', 'limited', null, 'https://www.oldesthousekeywest.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oldest Metal Bridge in Virginia', 'oldest-metal-bridge-in-virginia', 'weird-history', 37.23912, -80.2249, 'Elliston', 'VA', 'Built in 1878, this metal truss bridge carried traffic until 1971 before being preserved at the northbound Ironto Safety Rest Area on Interstate 81. It has been restored as a pedestrian bridge, turning a highway rest stop into an unexpectedly good piece of surviving nineteenth-century transportation history.', 'open', null, 'https://www.roadsideamerica.com/tip/40448', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oldest Store Museum Experience', 'oldest-store-museum-experience', 'weird-history', 29.90156, -81.31586, 'St. Augustine', 'FL', 'Living-history store crowded with turn-of-the-century gadgets, patent medicines, and strange household inventions.', 'limited', null, 'https://www.trolleytours.com/st-augustine/oldest-store-museum', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oldest Wooden School House', 'oldest-wooden-school-house', 'weird-history', 29.89872, -81.31413, 'St. Augustine', 'FL', 'Tiny cedar-and-cypress schoolhouse promoted as one of the country''s oldest surviving wooden school buildings.', 'limited', null, 'https://oldestwoodenschoolhouse.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Olustee Battlefield Historic State Park', 'olustee-battlefield-historic-state-park', 'weird-history', 30.20861, -82.40875, 'Olustee', 'FL', 'Preserved battlefield landscape from Florida''s largest Civil War battle.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/olustee-battlefield-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('One Love Park — Bob Marley’s Delaware Years', 'one-love-park-bob-marleys-delaware-years', 'weird-history', 39.75422, -75.53843, 'Wilmington', 'DE', 'Wilmington renamed this small park One Love Park in recognition of Bob Marley’s time living and working in Delaware. State historical material notes that Marley lived nearby in the 1960s and worked local industrial jobs while raising money for his music career. His former residence is private and should not be approached as part of the stop.', 'open', null, 'https://archives.delaware.gov/delaware-historical-markers/one-love-park/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.wilmingtonde.gov/Home/Components/FacilityDirectory/FacilityDirectory/104/118', null, null, null, 'America/New_York'),
  ('Oneida Community Mansion House', 'oneida-community-mansion-house', 'weird-history', 43.06034, -75.60462, 'Oneida', 'NY', 'Nearly 300 members of the radical Oneida Community once lived communally in this enormous mansion while practicing group marriage, communal child rearing and religious Perfectionism. The 93,000-square-foot building survives as a museum, inn and residence with daily self-guided museum access and scheduled deeper tours.', 'open', null, 'https://www.oneidacommunity.org/our-history', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Original Old Rugged Cross Church & Museum', 'original-old-rugged-cross-church-museum', 'weird-history', 41.91208, -86.17393, 'Pokagon Township', 'MI', 'This restored nineteenth-century church is where the final version of George Bennard''s hymn "The Old Rugged Cross" was first sung publicly in 1913. The building now operates as a historical site and small museum, preserving the unexpectedly specific Michigan origin story of one of America''s best-known Christian hymns.', 'limited', null, 'https://the-oldruggedcross.org/', '2026-09-08T15:31:15.588137+00:00', null, 'https://the-oldruggedcross.org/', null, null, null, 'America/Detroit'),
  ('Original Site of St. Mary''s Orphan Asylum', 'original-site-of-st-mary-s-orphan-asylum', 'weird-history', 29.26287, -94.83266, 'Galveston', 'TX', 'A roadside historical marker near Galveston''s seawall commemorates the original St. Mary''s Orphan Asylum and the devastating loss of the orphanage during the 1900 hurricane. The institution itself no longer stands here, so visitors are stopping for the plaque and the history of the former site.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, 'https://atlas.thc.texas.gov/Details/5167007175', null, 'node', 12403616528, 'America/Chicago'),
  ('Overlook Mountain House Ruins', 'overlook-mountain-house-ruins', 'weird-history', 42.08439, -74.09972, 'Woodstock', 'NY', 'Concrete walls and staircases from the abandoned Overlook Mountain House still stand high above Woodstock after repeated fires and unfinished rebuilding attempts ended the resort''s history. The ruins are reached by a steep multi-mile hike, and the state warns visitors not to enter or climb the unstable structures.', 'limited', null, 'https://dec.ny.gov/places/overlook-mountain-wild-forest', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Overton Park Shell', 'overton-park-shell', 'weird-history', 35.14547, -89.99455, 'Memphis', 'TN', 'This open-air bandshell hosted an early Elvis Presley performance and survived repeated threats of demolition. Free concerts and events continue the venue''s history, but access to programmed areas depends on the park and event schedule.', 'limited', null, 'https://overtonparkshell.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Packard Proving Grounds', 'packard-proving-grounds', 'weird-history', 42.66139, -83.03422, 'Shelby Township', 'MI', 'Packard opened this engineering complex in 1928 to test cars at high speeds on its track and through specialized durability courses. Surviving garages, gatehouses and portions of the test facility are now preserved by a nonprofit and can be explored during scheduled tours and public events.', 'limited', null, 'https://packardprovinggrounds.org/', '2026-09-08T14:53:55.160019+00:00', null, 'https://packardprovinggrounds.org/', null, null, null, 'America/Detroit'),
  ('Packet Alley', 'packet-alley', 'weird-history', 39.65906, -75.5619, 'New Castle', 'DE', 'This narrow passage to the Delaware River recalls the packet boats, stagecoaches and early railroad connections that once converged in New Castle. The small alley marks a surprisingly important transportation link between water and land travel.', 'open', null, 'https://archives.delaware.gov/delaware-historical-markers/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Palace Saloon', 'palace-saloon', 'weird-history', 30.67034, -81.4625, 'Fernandina Beach', 'FL', 'Historic port-town saloon with ornate interiors and more than a century of Amelia Island lore.', 'limited', null, 'https://thepalacesaloon.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Palisades Amusement Park Site', 'palisades-amusement-park-site', 'weird-history', 40.8281, -73.9778, 'Cliffside Park', 'NJ', 'Palisades Amusement Park operated above the Hudson River for generations before closing in 1971 and being replaced by high-rise development. A public memorial and historical marker preserve the location of the once-famous park, remembered for rides, music and its enormous saltwater pool.', 'open', null, 'https://www.roadsideamerica.com/tip/18383', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Palmyra Mining Camp', 'palmyra-mining-camp', 'weird-history', 39.165714, -119.500106, 'Dayton', 'NV', 'Gold in the Pine Nut Mountains drew several hundred miners and merchants here from about 1860. The neighbouring camp of Como overtook it within a few years and Palmyra vanished. Reached over a long rocky unpaved road southeast of Dayton; scattered ruins only.', 'limited', null, 'https://www.nvexpeditions.com/lyon/como.php', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Panarchy Tomb Room', 'panarchy-tomb-room', 'weird-history', 43.70148, -72.29148, 'Hanover', 'NH', 'The Panarchy undergraduate society occupies a former fraternity house containing a basement room decorated like a ritual chamber, complete with a stone tomb-like centerpiece. The unusual interior has become an online curiosity, but Panarchy is a private residential society rather than a public attraction. OddWay visitors should treat this as an exterior-only history stop and should not attempt to enter.', 'private', null, 'https://www.atlasobscura.com/places/panarchy-tomb-room', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Parrish Shoes Jumanji Sign', 'parrish-shoes-jumanji-sign', 'weird-history', 42.93365, -72.27865, 'Keene', 'NH', 'Downtown Keene stood in for the fictional town of Brantford in the 1995 film "Jumanji." A Parrish Shoes sign connected to the movie was later recreated and became a local memorial to Robin Williams after his death. The sign remains an easy public stop for fans of the film.', 'open', null, 'https://www.atlasobscura.com/places/parrish-shoes-sign', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paterson Great Falls', 'paterson-great-falls', 'weird-history', 40.91533, -74.17992, 'Paterson', 'NJ', 'A 77-foot waterfall in the middle of Paterson powered Alexander Hamilton''s planned industrial city and generations of mills and factories. Today the natural spectacle and surviving industrial landscape are protected as a National Historical Park.', 'open', null, 'https://www.nps.gov/pagr/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Patsy Cline Crash Site Memorial', 'patsy-cline-crash-site-memorial', 'weird-history', 36.06007, -88.15898, 'Camden', 'TN', 'A memorial in the woods marks the area where a 1963 plane crash killed Patsy Cline, Cowboy Copas, Hawkshaw Hawkins and Randy Hughes. The route can be muddy or rough, and the site should be treated as a memorial rather than a disaster-photo attraction.', 'limited', null, 'https://www.atlasobscura.com/places/patsy-cline-crash-site-memorial', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Paul Revere Lantern', 'paul-revere-lantern', 'weird-history', 42.45771, -71.34226, 'Concord', 'MA', 'The Concord Museum preserves one of the original lanterns associated with the ''one if by land, two if by sea'' signal from Old North Church on April 18, 1775. It is a small physical object tied to one of America''s most famous historical warnings.', 'limited', null, 'https://www.atlasobscura.com/places/paul-revere-lantern', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paw Paw Tunnel', 'paw-paw-tunnel', 'weird-history', 39.55556, -78.46278, 'Oldtown', 'MD', 'Construction of this 3,118-foot C&O Canal tunnel began in 1836 and took 14 years amid unstable rock, funding problems and violent labor disputes. The towpath still passes through the completely dark tunnel, which is reached on foot or bicycle; bring a flashlight and follow any temporary NPS closure notices.', 'limited', null, 'https://www.nps.gov/places/paw-paw-tunnel.htm', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Peg Leg Bates Statue', 'peg-leg-bates-statue', 'weird-history', 34.69478, -82.20036, 'Fountain Inn', 'SC', 'A statue honors Clayton “Peg Leg” Bates, the Fountain Inn native who lost a leg in a cotton-gin accident and became a celebrated one-legged tap dancer. Bates later appeared repeatedly on national television and operated a major Black-owned resort in New York.', 'open', null, 'https://www.scpictureproject.org/greenville-county/peg-leg-bates.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pendarvis', 'pendarvis', 'weird-history', 42.86029, -90.17937, 'Mineral Point', 'WI', 'Stone cottages built by Cornish miners survive along a steep Mineral Point street and now form a Wisconsin Historical Society site. The preserved buildings tell the story of immigration, lead mining and a restoration movement that helped save the town''s unusual architecture.', 'limited', null, 'https://pendarvis.wisconsinhistory.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://pendarvis.wisconsinhistory.org/', null, null, null, 'America/Chicago'),
  ('Penitentiary Avenue', 'penitentiary-avenue', 'weird-history', 32.72843, -114.615586, 'Yuma', 'AZ', 'Penitentiary Avenue is a historic roadway beside Yuma''s Territorial Prison area and formed part of the old Ocean-to-Ocean Highway route through Yuma. There is no standalone haunted attraction here; the meaningful visitor stops are the nearby Yuma Territorial Prison and historic Ocean-to-Ocean Bridge.', 'roadside', null, 'https://npgallery.nps.gov/NRHP/GetAsset/NHLS/66000197_text', null, null, null, null, 'way', 337523589, 'America/Los_Angeles'),
  ('Pensacola Lighthouse & Maritime Museum', 'pensacola-lighthouse-maritime-museum', 'weird-history', 30.34631, -87.30803, 'Pensacola', 'FL', '1859 lighthouse on Naval Air Station Pensacola with keeper history, maritime exhibits, and a dramatic tower climb.', 'limited', null, 'https://www.pensacolalighthouse.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pepsi Inventor Caleb Bradham’s Grave', 'pepsi-inventor-caleb-bradhams-grave', 'weird-history', 35.114, -77.04399, 'New Bern', 'NC', 'Caleb Bradham created the drink that became Pepsi-Cola at his New Bern pharmacy before losing control of the company after a disastrous sugar-market gamble. His surprisingly modest grave lies in Cedar Grove Cemetery only a short distance from Pepsi’s birthplace.', 'open', null, 'https://www.atlasobscura.com/places/pepsi-inventor-caleb-bradham-s-grave', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Peshtigo Fire Museum and Mass Grave', 'peshtigo-fire-museum-and-mass-grave', 'weird-history', 45.05576, -87.75386, 'Peshtigo', 'WI', 'The museum preserves artifacts and accounts from the October 8, 1871 Peshtigo Fire, the deadliest wildfire in recorded U.S. history. Beside it, a mass grave holds unidentified victims, creating a powerful and somber stop that should be visited respectfully.', 'limited', null, 'https://peshtigofiremuseum.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://peshtigofiremuseum.com/', null, null, null, 'America/Chicago'),
  ('Pet Sematary Creed House', 'pet-sematary-creed-house', 'weird-history', 44.50839, -68.25468, 'Hancock', 'ME', 'This private home at 303 Point Road served as the exterior of the Creed family house in the 1989 adaptation of Stephen King’s Pet Sematary. The nearby road was also used in scenes connected with the film’s deadly highway, making the location recognizable to horror fans despite being an ordinary residence today. View only from public areas and do not enter the property.', 'private', null, 'https://www.roadsideamerica.com/tip/40892', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pharr Mounds', 'pharr-mounds', 'weird-history', 34.47098, -88.42052, 'Tupelo', 'MS', 'A group of eight Woodland-period burial mounds spread across a broad field along the Natchez Trace. The NPS pull-off gives travelers a rare panoramic view of multiple ancient earthworks without entering private land.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Philippe Park Temple Mound', 'philippe-park-temple-mound', 'weird-history', 28.00863, -82.67818, 'Safety Harbor', 'FL', 'Large Tocobaga-era shell temple mound overlooking Old Tampa Bay.', 'open', null, 'https://pinellas.gov/parks/philippe-park/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Phineas Gage Memorial', 'phineas-gage-memorial', 'weird-history', 43.38215, -72.60939, 'Cavendish', 'VT', 'A marker commemorates the 1848 accident in which railroad foreman Phineas Gage survived an iron tamping rod passing through his skull. His survival and subsequent behavioral changes became one of the most famous cases in the history of neuroscience.', 'open', null, 'https://www.atlasobscura.com/places/phineas-gage-memorial', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Phineas Gage Skull and Iron Rod', 'phineas-gage-skull-and-iron-rod', 'weird-history', 42.3352, -71.1038, 'Boston', 'MA', 'Harvard''s Warren Anatomical Museum preserves the skull of railroad foreman Phineas Gage along with the iron tamping rod that blasted through his head in an 1848 accident. Gage survived, and the case became one of the most famous episodes in the early history of neuroscience. The collection is housed at Harvard Medical School; check current public-access rules before visiting.', 'limited', null, 'https://www.atlasobscura.com/places/warren-anatomical-museum', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Phoenix Shot Tower', 'phoenix-shot-tower', 'weird-history', 39.29073, -76.60547, 'Baltimore', 'MD', 'Completed in 1828, the 234-foot brick tower was briefly the tallest structure in the United States and manufactured lead shot by dropping molten metal from its upper levels. The landmark remains standing downtown, with interior access available only during limited tour hours and events.', 'limited', null, 'https://baltimore.org/listings/phoenix-shot-tower/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pieces of the Battleship Indiana', 'pieces-of-the-battleship-indiana', 'weird-history', 39.1809, -86.5261, 'Bloomington', 'IN', 'Large surviving pieces of USS Indiana, including guns and part of the ship''s mast, stand outside Indiana University''s Memorial Stadium. The display has been assembled over decades from remnants of the battleship, creating a strange naval monument hundreds of miles from the sea.', 'open', null, 'https://www.roadsideamerica.com/tip/84479', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Pierre Menard Home State Historic Site', 'pierre-menard-home-state-historic-site', 'weird-history', 37.9614, -89.9065, 'Ellis Grove', 'IL', 'The elegant French-influenced home of Illinois'' first lieutenant governor survives above the Mississippi bottomlands near old Kaskaskia.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/southwest/pierre-menard-home.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pigeon Roost State Historic Site', 'pigeon-roost-state-historic-site', 'weird-history', 38.617, -85.77644, 'Scottsburg', 'IN', 'This rural memorial marks the location of the Pigeon Roost settlement and a deadly 1812 attack during the violent frontier conflict surrounding the War of 1812. The state historic site preserves the location and memorial while modern interpretation places the event within the larger conflict between Indigenous nations, settlers and U.S. expansion.', 'open', null, 'https://secure.in.gov/history/state-historical-markers/find-a-marker/pigeon-roost/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Pikeville Cut-Through Overlook', 'pikeville-cut-through-overlook', 'weird-history', 37.47246, -82.53852, 'Pikeville', 'KY', 'The Pikeville Cut-Through rerouted a river, railroad and highway through Peach Orchard Mountain in one enormous engineering project. A public overlook gives travelers a clear view of the artificial gap and the reshaped landscape below.', 'open', null, 'https://www.hmdb.org/m.asp?m=212047', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pine Ridge Pet Cemetery', 'pine-ridge-pet-cemetery', 'weird-history', 42.26598, -71.18377, 'Dedham', 'MA', 'Founded in the nineteenth century, Pine Ridge is one of America''s oldest pet cemeteries. Thousands of animal graves include those of explorer Richard Byrd''s dog Igloo and several dogs once owned by Lizzie Borden, making the peaceful grounds unexpectedly rich in famous-animal history.', 'limited', null, 'https://www.atlasobscura.com/places/pine-ridge-pet-cemetery', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pinson Mounds State Archaeological Park', 'pinson-mounds-state-archaeological-park', 'weird-history', 35.4975, -88.68674, 'Pinson', 'TN', 'This complex preserves some of the largest Middle Woodland ceremonial earthworks in the United States, including towering mounds built nearly two thousand years ago. Trails and a museum allow legal exploration without treating Indigenous sacred landscapes as mysterious ruins.', 'open', null, 'https://tnstateparks.com/parks/pinson-mounds', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pioneer Florida Museum & Village', 'pioneer-florida-museum-village', 'weird-history', 28.35968, -82.18719, 'Dade City', 'FL', 'Open-air pioneer village with historic buildings, machinery, and Florida Cracker culture.', 'limited', null, 'https://www.pioneerfloridamuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pioneer Village at Shingle Creek', 'pioneer-village-at-shingle-creek', 'weird-history', 28.29515, -81.45585, 'Kissimmee', 'FL', 'Open-air village of relocated pioneer buildings on historic Shingle Creek.', 'limited', null, 'https://osceolahistory.org/pioneer-village/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pirate Cat Memorial', 'pirate-cat-memorial', 'weird-history', 39.92696, -86.13658, 'Carmel', 'IN', 'Pirate Cat was a wandering orange-and-white cat who became a familiar sight to people using the Monon Trail and earned the unofficial title "Mayor of the Monon." After his death in 2020, admirers installed a black granite memorial topped with a life-size cat statue; some of his ashes are sealed inside.', 'open', null, 'https://www.roadsideamerica.com/story/75578', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Pizzaland — The Sopranos Opening-Credits Pizzeria', 'pizzaland-the-sopranos-opening-credits-pizzeria', 'weird-history', 40.78165, -74.138, 'North Arlington', 'NJ', 'This small pizzeria appears in the opening credits of The Sopranos as Tony Soprano drives through North Jersey. Pizzaland remains an operating restaurant at the same location, making it a straightforward stop for fans of the series.', 'open', null, 'https://sirstoria.com/locations/new-jersey/north-arlington/sopranos-pizza-land', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Plane Crash in a Cemetery Marker', 'plane-crash-in-a-cemetery-marker', 'weird-history', 39.60532, -85.43274, 'Arlington', 'IN', 'East Hill Cemetery contains a marker tied to a bizarre 1978 accident in which a small airplane crashed into the cemetery while carrying figures from the auto-racing world. The cemetery itself is active and public, so visitors should approach the memorial respectfully and remain on normal cemetery drives and paths.', 'open', null, 'https://www.roadsideamerica.com/location/in/all', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.arlingtoneasthillcemetery.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Pleasure Beach Ghost Town', 'pleasure-beach-ghost-town', 'weird-history', 41.15779, -73.16913, 'Bridgeport', 'CT', 'Once home to an amusement park, cottages and summer crowds, Pleasure Beach was largely abandoned after a bridge fire cut off road access in 1996. Nature has reclaimed much of the former community. The City of Bridgeport operates seasonal water-taxi access, including during the 2026 season.', 'limited', null, 'https://www.bridgeportct.gov/government/departments/parks-recreation/pleasure-beach', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pocahontas Mound', 'pocahontas-mound', 'weird-history', 32.46768, -90.28877, 'Pocahontas', 'MS', 'A surviving Native American mound preserved in a small public roadside park in Pocahontas. It is one of the most straightforward Mound Trail stops for travelers because the mound and marker are intentionally accessible.', 'open', null, 'https://trails.mdah.ms.gov/pocahontas', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pocket Watch Grave', 'pocket-watch-grave', 'weird-history', 40.48559, -85.98776, 'Greentown', 'IN', 'A grave in Greenlawn Cemetery is marked with an oversized stone pocket watch rather than a standard rectangular monument. The carved watch face and chain make the memorial immediately recognizable and give travelers a specific, respectful cemetery oddity to locate.', 'open', null, 'https://www.roadsideamerica.com/tip/76259', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Point Judith Lighthouse Cairns', 'point-judith-lighthouse-cairns', 'weird-history', 41.36139, -71.48108, 'Narragansett', 'RI', 'Visitors around Point Judith have built clusters of small stone cairns near the dramatic lighthouse and rocky shoreline. The area also looks over waters tied to the 1945 sinking of German submarine U-853 and other maritime losses, giving the scenic stop a darker historical layer. Stay within areas legally open to the public and respect Coast Guard restrictions around the lighthouse.', 'roadside', null, 'https://www.atlasobscura.com/places/point-judith-lighthouse-cairns', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Polar Bear Memorial', 'polar-bear-memorial', 'weird-history', 42.5845, -83.16509, 'Troy', 'MI', 'A white marble polar bear marks the burial and memorial area for American soldiers who served in northern Russia during the Allied intervention following World War I. The men became known as the Polar Bears, and the monument preserves a little-known episode in which Michigan troops fought Bolshevik forces thousands of miles from home.', 'limited', null, 'https://www.roadsideamerica.com/story/19832', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Ponce de Leon Inlet Lighthouse', 'ponce-de-leon-inlet-lighthouse', 'weird-history', 29.08078, -80.92809, 'Ponce Inlet', 'FL', 'Florida''s tallest lighthouse and one of the tallest masonry lighthouses in the United States.', 'limited', null, 'https://www.ponceinlet.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pond Spring — General Joe Wheeler Home', 'pond-spring-general-joe-wheeler-home', 'weird-history', 34.65062, -87.25388, 'Hillsboro', 'AL', 'The 50-acre historic site contains multiple houses, outbuildings, cemeteries, gardens and archaeological features associated with generations of Native, enslaved and later residents, as well as General Joseph Wheeler’s family. Tours operate on a limited schedule.', 'limited', null, 'https://ahc.alabama.gov/PondSpringHistoryFacts.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Poogan’s Grave', 'poogans-grave', 'weird-history', 32.77813, -79.93194, 'Charleston', 'SC', 'A small grave outside Poogan’s Porch honors the neighborhood dog for whom the restaurant was named. Poogan reportedly wandered from porch to porch before adopting the restaurant as his home, and staff and guests have since attached ghost stories to the beloved canine’s memory. Restaurant: https://www.poogansporch.com/', 'open', null, 'https://www.roadsideamerica.com/location/sc/all', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pope’s Tavern Museum', 'popes-tavern-museum', 'weird-history', 34.80498, -87.67693, 'Florence', 'AL', 'This early Florence tavern later served as a hospital during the Civil War and now contains local and wartime artifacts. Its layered use as inn, gathering place and medical site gives the small building an unusually dense history.', 'limited', null, 'https://www.florencealmuseums.com/home/popes-tavern', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Port Hudson State Historic Site', 'port-hudson-state-historic-site', 'weird-history', 30.68876, -91.28158, 'Zachary', 'LA', 'Port Hudson preserves portions of the battlefield associated with one of the longest sieges in American military history. Earthworks, museum exhibits and trails provide a concrete landscape for the 1863 campaign.', 'open', null, 'https://www.lastateparks.com/historic-sites/port-hudson-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Porter Creek Bridge Ruins', 'porter-creek-bridge-ruins', 'weird-history', 41.48764, -81.93649, 'Bay Village', 'OH', 'Concrete bridge piers from an early-twentieth-century electric railway still rise from the wooded Porter Creek valley after the line was abandoned and dismantled. The ruins can be reached legally on foot from the Lake Erie Nature & Science Center area using public paths, but visitors need to hike into the valley rather than drive directly to them.', 'limited', null, 'https://www.atlasobscura.com/places/porter-creek-bridge-ruins', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Portland Observatory', 'portland-observatory', 'weird-history', 43.66537, -70.24824, 'Portland', 'ME', 'Built in 1807, this octagonal wooden tower allowed signalmen to identify incoming ships before they reached Portland Harbor. It survives as the only known remaining historic maritime signal tower of its type in the United States.', 'limited', null, 'https://www.atlasobscura.com/places/the-portland-observatory', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Portsmouth Village Ghost Town', 'portsmouth-village-ghost-town', 'weird-history', 35.04835, -76.0798, 'Ocracoke', 'NC', 'Once an important Outer Banks shipping settlement, Portsmouth declined after hurricanes, shifting inlets, war, and isolation undermined the village. Its final residents left in 1971, leaving a collection of preserved houses, church, post office, and other structures on a remote island reached by boat. NPS: https://www.nps.gov/calo/learn/historyculture/portsmouth.htm', 'limited', null, 'https://www.atlasobscura.com/places/portsmouth-village', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Postville Courthouse State Historic Site', 'postville-courthouse-state-historic-site', 'weird-history', 40.14727, -89.38045, 'Lincoln', 'IL', 'A reconstruction of the 1840s courthouse where Abraham Lincoln practiced law while traveling Illinois'' Eighth Judicial Circuit.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/central/postville-courthouse.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Poverty Point World Heritage Site', 'poverty-point-world-heritage-site', 'weird-history', 32.63622, -91.40503, 'Pioneer', 'LA', 'Poverty Point preserves a vast complex of Indigenous earthworks built more than three thousand years ago by hunter-gatherers who organized long-distance trade and monumental construction. It is a UNESCO World Heritage Site and one of Louisiana''s most important archaeological stops.', 'open', null, 'https://www.lastateparks.com/historic-sites/poverty-point-world-heritage-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('President Chester A. Arthur State Historic Site', 'president-chester-a-arthur-state-historic-site', 'weird-history', 44.81445, -72.9324, 'Fairfield', 'VT', 'The site preserves a reconstructed house long promoted as Chester A. Arthur''s birthplace even though later research showed that the exact birthplace remains disputed and the replica is not on the original house site. That historical uncertainty is now part of the interpretation.', 'limited', null, 'https://historicsites.vermont.gov/chester-arthur', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('President James K. Polk''s Tomb', 'president-james-k-polks-tomb', 'weird-history', 36.1666, -86.784, 'Nashville', 'TN', 'James K. Polk''s remains were moved multiple times before arriving at the Tennessee State Capitol grounds. The ornate tomb''s unusual relocation history makes it more than a standard presidential burial site.', 'open', null, 'https://www.atlasobscura.com/places/president-james-k-polks-tomb', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('President McKinley Statue', 'president-mckinley-statue', 'weird-history', 43.23299, -86.25273, 'Muskegon', 'MI', 'Muskegon''s William McKinley statue was dedicated in May 1902, only months after the president''s assassination, making it one of the earliest public monuments erected to him. Its unusually naturalistic pose has also earned it a reputation as one of the less flattering presidential statues in the country.', 'open', null, 'https://www.roadsideamerica.com/story/32295', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Prince Frederick’s Chapel Ruins', 'prince-fredericks-chapel-ruins', 'weird-history', 33.5056, -79.1803, 'Plantersville', 'SC', 'Only the Gothic Revival front wall and tower remain from a church begun just before the Civil War and completed years afterward. The main body was demolished in 1966 after becoming unsafe. The National Register property is privately owned, so visitors should view it only where lawful and not assume public entry.', 'private', null, 'https://www.nationalregister.sc.gov/georgetown/S10817722008/index.htm', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Princess Place Preserve', 'princess-place-preserve', 'weird-history', 29.61083, -81.24926, 'Palm Coast', 'FL', 'Historic hunting lodge tied to an actual Russian princess and surrounded by secluded Old Florida landscape.', 'limited', null, 'https://www.flaglercounty.gov/departments/parks-recreation/princess-place-preserve', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Proctor''s Ledge Memorial', 'proctors-ledge-memorial', 'weird-history', 42.51761, -70.90909, 'Salem', 'MA', 'Researchers identified Proctor''s Ledge as the location where 19 people accused of witchcraft were hanged in 1692. A small memorial now marks the execution site in a residential neighborhood; there is no dedicated parking, so visitors should approach quietly and respect nearby homes.', 'open', null, 'https://www.atlasobscura.com/places/proctors-ledge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Prophet of Oak Ridge Grave', 'prophet-of-oak-ridge-grave', 'weird-history', 36.01241, -84.23387, 'Oak Ridge', 'TN', 'The grave of John Hendrix recalls a local figure whose pre-Manhattan Project visions were later interpreted as eerily anticipating the sudden wartime transformation of the area. The story sits at the intersection of prophecy folklore and Oak Ridge''s extraordinary twentieth-century history.', 'limited', null, 'https://www.atlasobscura.com/places/prophet-of-oak-ridge-grave', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Prophet''s Rock', 'prophets-rock', 'weird-history', 40.50458, -86.85153, 'Battle Ground', 'IN', 'Tradition identifies this rocky overlook as the place where Tenskwatawa, known as the Prophet, watched or encouraged Native forces during the Battle of Tippecanoe in November 1811. A marker and public pull-off identify the location today, though interpretations of the battle should be understood within the larger history of Indigenous resistance to U.S. expansion.', 'open', null, 'https://www.hmdb.org/m.asp?m=6434', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Providence Athenaeum', 'providence-athenaeum', 'weird-history', 41.8258, -71.4063, 'Providence', 'RI', 'This 1838 independent library is closely tied to Edgar Allan Poe, who spent time here during his courtship of poet Sarah Helen Whitman, and it was later frequented by H.P. Lovecraft. Its narrow galleries, old collections and literary associations give the building an atmosphere that fits naturally into a Providence weird-fiction route.', 'open', null, 'https://www.atlasobscura.com/places/providence-athenaeum', '2026-09-09T04:49:27.913704+00:00', null, 'https://providenceathenaeum.org/', null, null, null, 'America/New_York'),
  ('P.T. Barnum Birthplace Statue', 'pt-barnum-birthplace-statue', 'weird-history', 41.3712, -73.41382, 'Bethel', 'CT', 'A life-size bronze P.T. Barnum stands outside the Bethel Public Library in the showman''s hometown. The statue was commissioned for the 200th anniversary of Barnum''s birth and gives OddWay travelers a direct stop tied to America''s most famous promoter of curiosities.', 'open', null, 'https://www.roadsideamerica.com/story/60492', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('P.T. Barnum Statue at Seaside Park', 'pt-barnum-statue-at-seaside-park', 'weird-history', 41.16176, -73.19073, 'Bridgeport', 'CT', 'An imposing seated statue of circus impresario P.T. Barnum overlooks the waterfront park he helped create for Bridgeport. Installed after his death, it connects the city directly to the man whose museums, sideshows and spectacles helped define nineteenth-century American entertainment.', 'open', null, 'https://www.roadsideamerica.com/story/10867', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.bridgeportct.gov/government/departments/parks-recreation/seaside-park-history', null, null, null, 'America/New_York'),
  ('Pullman National Historical Park Visitor Center', 'pullman-national-historical-park-visitor-center', 'weird-history', 41.69429, -87.60874, 'Chicago', 'IL', 'The preserved company town tells an unusually complete story of industrial paternalism, railroad sleeping cars, labor conflict, and the Pullman Strike.', 'limited', null, 'https://www.nps.gov/pull/planyourvisit/visitorcenters.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pulpit Rock Tower', 'pulpit-rock-tower', 'weird-history', 43.03322, -70.72108, 'Rye', 'NH', 'This concrete World War II observation tower was part of the coastal fire-control network protecting Portsmouth Harbor. Its tall, windowed silhouette rises unexpectedly from the trees and looks more like a small brutalist castle than a military instrument. The exterior can be viewed from the site, while interior openings are limited and should be checked in advance.', 'limited', null, 'https://www.atlasobscura.com/places/pulpit-rock-tower', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Quecreek Mine Rescue Site', 'quecreek-mine-rescue-site', 'weird-history', 40.07781, -79.08605, 'Somerset', 'PA', 'Nine miners were trapped underground by flooding at Quecreek in July 2002 and were brought out alive after a highly publicized 77-hour rescue. The rescue field is now Monument for Life Memorial Park, where visitors can see the rescue shaft, a miner statue and outdoor memorials; the educational center has separate operating hours.', 'open', null, 'https://www.quecreekrescue.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Queen Anne’s Revenge Artifacts — North Carolina Maritime Museum', 'queen-annes-revenge-artifacts-north-carolina-maritime-museum', 'weird-history', 34.71767, -76.66704, 'Beaufort', 'NC', 'Artifacts recovered from the wreck believed to be Blackbeard’s flagship Queen Anne’s Revenge are displayed at the North Carolina Maritime Museum. Cannons, medical equipment, navigational objects, and everyday shipboard finds give the famous pirate a physical archaeological footprint. Artifact project: https://www.qaronline.org/', 'limited', null, 'https://ncmaritimemuseumbeaufort.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Quick Stop — Clerks Filming Location', 'quick-stop-clerks-filming-location', 'weird-history', 40.4152, -74.05712, 'Leonardo', 'NJ', 'The operating Quick Stop convenience store became a cult-film landmark after Kevin Smith shot much of the 1994 movie Clerks here. The familiar storefront remains recognizable to fans and continues to function as a normal neighborhood store.', 'open', null, 'https://www.atlasobscura.com/places/quick-stop-groceries', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Quincy Dredge No. 2', 'quincy-dredge-no-2', 'weird-history', 47.14558, -88.45681, 'Hancock', 'MI', 'The rusting remains of a massive copper-reclamation dredge sit partly submerged in Torch Lake as a relic of Keweenaw mining. The dredge operated until the 1960s and is now best viewed from public roadside or trail vantage points rather than approached directly.', 'roadside', null, 'https://www.atlasobscura.com/places/quincy-dredge-2', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Quincy Mine', 'quincy-mine', 'weird-history', 47.13702, -88.57477, 'Hancock', 'MI', 'The Quincy Mining Company became one of the Keweenaw Peninsula''s most successful copper operations and left behind an enormous industrial landscape. Guided tours descend underground and visit the massive No. 2 hoist house, home to one of the world''s largest steam-powered mine hoists.', 'limited', null, 'https://www.quincymine.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.quincymine.com/', null, null, null, 'America/Detroit'),
  ('Quincy Quarries', 'quincy-quarries', 'weird-history', 42.2444, -71.03421, 'Quincy', 'MA', 'Granite quarried here helped build major nineteenth-century structures, and the abandoned pits later became legendary among climbers and graffiti artists. Much of the old quarry landscape is now incorporated into public reservation land, where towering cut-stone walls remain visible.', 'open', null, 'https://www.atlasobscura.com/places/quincy-quarries-reservation', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Radium Girls Memorial Park', 'radium-girls-memorial-park', 'weird-history', 40.78172, -74.22713, 'Orange', 'NJ', 'A public park and memorial stand near the former U.S. Radium Corporation site where women painted luminous watch dials with radioactive radium paint. Their illnesses and legal battle became a major turning point in occupational-safety history.', 'open', null, 'https://www.atlasobscura.com/places/us-radium-corporation-site', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rainbow Springs State Park', 'rainbow-springs-state-park', 'weird-history', 29.10263, -82.43769, 'Dunnellon', 'FL', 'Former roadside attraction with artificial waterfalls, old zoo remnants, and a huge spring system.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/rainbow-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Randell Research Center & Calusa Heritage Trail', 'randell-research-center-calusa-heritage-trail', 'weird-history', 26.66081, -82.15078, 'Pineland', 'FL', 'Public trail through the Pineland archaeological site, including huge Calusa shell mounds, canals, and an ancient village landscape.', 'open', null, 'https://www.floridamuseum.ufl.edu/rrc/visit/trail/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Randolph McCoy Well and Homeplace', 'randolph-mccoy-well-and-homeplace', 'weird-history', 37.60278, -82.215, 'Hardy', 'KY', 'The original well survives at the site of Randolph McCoy''s home, where the Hatfields attacked the family on New Year''s night in 1888 and burned the cabin. Archaeological work recovered bullets, nails and household fragments, and the site now includes interpretation and a chainsaw-carved Randolph McCoy.', 'open', null, 'https://mccoywelltour.com/about-the-mccoy-well', '2026-09-08T14:30:49.642487+00:00', null, 'https://mccoywelltour.com/', null, null, null, 'America/New_York'),
  ('Rausch Gap Ghost Town', 'rausch-gap-ghost-town', 'weird-history', 40.49953, -76.59774, 'Cold Spring Township', 'PA', 'Rausch Gap was a nineteenth-century railroad and coal settlement that disappeared after industry moved away, leaving foundations, a cemetery and other traces in the forest. The abandoned town site is reached on foot along the Appalachian Trail and related trails, so it requires a hike rather than a roadside visit.', 'limited', null, 'https://en.wikipedia.org/wiki/Rausch_Gap,_Pennsylvania', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Reading Pagoda', 'reading-pagoda', 'weird-history', 40.33609, -75.90567, 'Reading', 'PA', 'William Abbott Witman constructed Reading''s Japanese-inspired Pagoda in 1908 as the centerpiece of a proposed mountaintop resort, but the resort plan collapsed after he failed to secure a liquor license. The city acquired it for $1 in 1911; following a major restoration, the grounds are open daily while the building itself currently opens only for selected ticketed walkthroughs and arranged group tours.', 'limited', null, 'https://www.readingpagoda.com/visit', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Real Pirates Salem', 'real-pirates-salem', 'weird-history', 42.51964, -70.89131, 'Salem', 'MA', 'Artifacts recovered from the wreck of the Whydah Gally tell the story of the pirate ship that sank off Cape Cod in 1717. Coins, weapons and other objects come from the only authenticated Golden Age pirate shipwreck discovered in North American waters.', 'limited', null, 'https://www.realpiratessalem.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.realpiratessalem.com/', null, null, null, 'America/New_York'),
  ('Rebecca Nurse Homestead and Graveyard', 'rebecca-nurse-homestead-and-graveyard', 'weird-history', 42.55836, -70.9483, 'Danvers', 'MA', 'The preserved homestead of Rebecca Nurse includes a family graveyard where a monument stands over remains traditionally identified as hers. Nurse was executed for witchcraft in 1692 despite an initial not-guilty verdict, and another executed victim, George Jacobs Sr., was later reburied on the property.', 'limited', null, 'https://www.atlasobscura.com/places/rebecca-nurse-homestead-and-graveyard', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.rebeccanurse.org/', null, null, null, 'America/New_York'),
  ('Rebel State Historic Site', 'rebel-state-historic-site', 'weird-history', 31.74963, -93.42052, 'Marthaville', 'LA', 'The site evolved from a Confederate memorial into a broader museum of northwestern Louisiana culture and country music. Current state schedules may require appointment access, so check before routing.', 'limited', null, 'https://www.lastateparks.com/historic-sites/rebel-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Red Bird Petroglyph', 'red-bird-petroglyph', 'weird-history', 37.15856, -83.76175, 'Manchester', 'KY', 'A large sandstone block known as the Red Bird Petroglyph bears a confusing mixture of carved markings and inscriptions and was moved for preservation after falling from its original cliff in 1994. Some writers have claimed the markings represent ancient Old World scripts, but those interpretations are controversial and are not accepted as established archaeological evidence.', 'open', null, 'https://www.fraziermuseum.org/weekly/3-25-2024', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Red Mountain Park', 'red-mountain-park', 'weird-history', 33.44518, -86.86233, 'Birmingham', 'AL', 'Trails cross former iron-ore mining land filled with mine entrances, foundations and industrial remnants on Red Mountain. Visitors should stay on marked routes and obey closures around shafts and unstable structures.', 'open', null, 'https://redmountainpark.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Red''s Lounge', 'reds-lounge', 'weird-history', 34.19772, -90.57412, 'Clarksdale', 'MS', 'A small, long-running juke joint closely associated with Clarksdale''s living blues scene. It is an active nightlife venue rather than a daytime museum, so hours and performances should be checked before routing travelers there.', 'limited', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Redstone Rocket Replica', 'redstone-rocket-replica', 'weird-history', 43.22416, -71.53259, 'Concord', 'NH', 'A 92-foot Redstone rocket replica towers outside the McAuliffe-Shepard Discovery Center. The Redstone family of rockets included the vehicle that launched New Hampshire native Alan Shepard on the first American crewed spaceflight. The outdoor rocket can be seen without entering the museum.', 'open', null, 'https://www.atlasobscura.com/places/redstone-rocket-replica', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.starhop.com/', null, null, null, 'America/New_York'),
  ('Reed Gold Mine', 'reed-gold-mine', 'weird-history', 35.28459, -80.46451, 'Midland', 'NC', 'The first authenticated gold discovery in the United States occurred here after a 12-year-old found a large yellow rock that the family initially used as a doorstop. Visitors can tour portions of the underground mine and, seasonally, try gold panning.', 'limited', null, 'https://historicsites.nc.gov/all-sites/reed-gold-mine', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rees Sanitarium', 'rees-sanitarium', 'weird-history', 30.1615, -96.39863, 'Brenham', 'TX', 'This stop is a Texas historical marker identifying the site of Rees Sanitarium, Brenham''s first hospital, rather than an abandoned hospital visitors can enter. Travelers will find a roadside plaque explaining the former institution and its place in local medical history.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, 'https://atlas.thc.texas.gov/Details/5477008379', null, 'node', 12454130589, 'America/Chicago'),
  ('Regina Underwater Archaeological Preserve', 'regina-underwater-archaeological-preserve', 'weird-history', 27.46892, -82.70215, 'Bradenton Beach', 'FL', 'Shallow wreck of a 1904 steel tanker-barge that went down carrying molasses in 1940.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/regina/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rehmeyer''s Hollow Hex House', 'rehmeyers-hollow-hex-house', 'weird-history', 39.80208, -76.64471, 'Stewartstown', 'PA', 'Powwow practitioner Nelson Rehmeyer was murdered inside this house in 1928 by men who believed he had placed a hex on one of them, producing the sensational case remembered as the York Witch Trial. The house survives, but it no longer has dependable public tour hours, so treat it as private property and view only from the public road unless an official event specifically grants access.', 'private', null, 'https://www.atlasobscura.com/places/rehmeyers-hollow', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rehoboth Beach Temperance Fountain', 'rehoboth-beach-temperance-fountain', 'weird-history', 38.71639, -75.07611, 'Rehoboth Beach', 'DE', 'This granite public drinking fountain was erected in 1929 by the Woman’s Christian Temperance Union to commemorate the Delaware organization’s fiftieth anniversary. Temperance fountains were meant to provide readily available water as an alternative to alcoholic drinks, leaving an unusual piece of Prohibition-era social history directly beside the beach.', 'open', null, 'https://npgallery.nps.gov/GetAsset/c5ad9348-ef15-4c61-ad87-984e682d28ef', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Remains of the Truxton Circle Fountain', 'remains-of-the-truxton-circle-fountain', 'weird-history', 38.71027, -77.02762, 'Fort Washington', 'MD', 'A fountain once stood in Washington, D.C.''s Truxton Circle before the traffic circle was removed in the 1940s and the monument seemingly disappeared. Pieces were later identified among discarded stone at Fort Washington Park, where the surviving fragments can be seen in the park rather than at their original D.C. location.', 'open', null, 'https://www.atlasobscura.com/places/remains-of-truxton-circle-fountain', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Remington Shot Tower', 'remington-shot-tower', 'weird-history', 41.18826, -73.17462, 'Bridgeport', 'CT', 'A tall industrial tower survives within the abandoned Remington Arms complex, where molten lead was once dropped from above so it cooled into round shot while falling. The factory property is not an urban-exploration destination: view the tower only from lawful public areas.', 'roadside', null, 'https://www.atlasobscura.com/places/remington-shot-tower', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Renwick Smallpox Hospital Ruin', 'renwick-smallpox-hospital-ruin', 'weird-history', 40.75159, -73.95956, 'New York', 'NY', 'This Gothic Revival ruin on Roosevelt Island opened as a smallpox hospital in the nineteenth century and later became a nurses'' residence before abandonment. The shell remains fenced and cannot be entered, but it is clearly visible from the public paths in Southpoint Park while preservation groups work toward eventual safe access.', 'closed', null, 'https://www.theruin.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Republic of Indian Stream Historical Marker', 'republic-of-indian-stream-historical-marker', 'weird-history', 45.05152, -71.38706, 'Pittsburg', 'NH', 'For several years in the 1830s, residents north of Pittsburg organized the self-declared Republic of Indian Stream amid a border dispute between the United States and British Canada. The tiny government had its own constitution and local institutions before the territory was absorbed into New Hampshire. A state marker on U.S. Route 3 commemorates the unlikely republic. Coordinate source: https://mm.nh.gov/files/uploads/dhr/documents/highway-markers-by-number.pdf', 'roadside', null, 'https://www.nhpr.org/nh-news/2014-01-24/marking-history-republic-of-indian-stream-in-pittsburg', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rhea County Courthouse — Scopes Trial Museum', 'rhea-county-courthouse-scopes-trial-museum', 'weird-history', 35.495, -85.01306, 'Dayton', 'TN', 'The 1925 Scopes ''Monkey Trial'' over teaching evolution unfolded inside this courthouse. A museum and preserved courtroom connect visitors to one of America''s most famous clashes over science, religion, education and law.', 'open', null, 'https://rheacountyheritage.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rhyolite Ghost Town', 'rhyolite-ghost-town', 'weird-history', 36.900897, -116.829335, 'Beatty', 'NV', 'Rhyolite appeared during the Bullfrog gold rush of the early 1900s and emptied almost as fast when the boom collapsed. The BLM manages the townsite, where you can walk freely among the ruins including the Cook Bank and the bottle house. Day use, four miles west of Beatty.', 'open', null, 'https://www.blm.gov/visit/rhyolite-historic-area', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Rhythm Night Club Memorial Museum', 'rhythm-night-club-memorial-museum', 'weird-history', 31.55925, -91.39742, 'Natchez', 'MS', 'A memorial museum at the site of the 1940 Rhythm Night Club fire, one of the deadliest nightclub fires in U.S. history. Exhibits preserve victim names, photographs, recordings and survivor accounts from a tragedy that killed more than 200 people.', 'open', null, 'https://visitmississippi.org/things-to-do/history/rhythm-night-club-memorial-museum/', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.rnconsitemm.org/', null, null, null, 'America/Chicago'),
  ('Ribault Column', 'ribault-column', 'weird-history', 30.38518, -81.50027, 'Jacksonville', 'FL', 'Monument marking the 1562 French claim to Florida near Fort Caroline.', 'open', null, 'https://www.nps.gov/timu/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Richard McDonald''s Niche', 'richard-mcdonalds-niche', 'weird-history', 43.0057, -71.48595, 'Manchester', 'NH', 'Richard McDonald, one of the brothers whose restaurant system became McDonald''s, is interred at Mount Calvary Cemetery in Manchester. His niche includes imagery referencing the Golden Arches and his role in the company''s history. The understated cemetery stop is an unusual endpoint for one of America''s most recognizable business stories.', 'limited', null, 'https://www.atlasobscura.com/places/richard-mcdonalds-niche', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Richardson Olmsted Campus', 'richardson-olmsted-campus', 'weird-history', 42.93001, -78.88258, 'Buffalo', 'NY', 'H.H. Richardson designed this monumental complex as the Buffalo State Asylum for the Insane, with Frederick Law Olmsted and Calvert Vaux shaping the grounds around it. The grounds remain accessible and scheduled seasonal tours enter portions of the restored complex, while other former hospital buildings are not open for exploration.', 'limited', null, 'https://richardson-olmsted.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ricker Basin Ghost Settlement', 'ricker-basin-ghost-settlement', 'weird-history', 44.38984, -72.76728, 'Waterbury', 'VT', 'Forest trails in Little River State Park pass cellar holes, stone walls, cemeteries and other remains of settlements that once occupied the Ricker Basin. Flood-control projects and changing rural life eventually emptied the area, leaving a walkable archaeological landscape in the woods.', 'limited', null, 'https://www.atlasobscura.com/places/ricker-basin', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rickwood Field', 'rickwood-field', 'weird-history', 33.50263, -86.85566, 'Birmingham', 'AL', 'Opened in 1910, Rickwood Field is widely recognized as the oldest surviving professional baseball park in the United States. Its preserved grandstand and history involving Negro League and major-league players make it a rare living sports artifact.', 'limited', null, 'https://www.mlb.com/rickwood', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ringwood Manor', 'ringwood-manor', 'weird-history', 41.14444, -74.25278, 'Ringwood', 'NJ', 'This sprawling historic estate is tied to the iron-industry families who controlled large areas of northern New Jersey. The mansion contains layered collections from generations of owners, while the surrounding state-park grounds include cemeteries, outbuildings and remnants of the iron community.', 'limited', null, 'https://dep.nj.gov/parksandforests/state-park/ringwood-manor/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rip Van Winkle Gardens — Jefferson Island', 'rip-van-winkle-gardens-jefferson-island', 'weird-history', 29.96997, -91.97333, 'New Iberia', 'LA', 'The gardens and Joseph Jefferson mansion sit atop a salt dome beside Lake Peigneur, whose 1980 drilling disaster famously drained the lake into an underground mine. The landscape combines theatrical history, geology and one of Louisiana''s strangest industrial accidents.', 'limited', null, 'https://www.ripvanwinklegardens.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Riverside Hotel Museum', 'riverside-hotel-museum', 'weird-history', 34.19517, -90.57255, 'Clarksdale', 'MS', 'The former G.T. Thomas Afro-American Hospital became a Green Book-era hotel run by the Ratliff family and hosted generations of blues musicians and Black travelers. As of 2026 it is no longer operating as a hotel and functions as a museum/interpretive site with tours arranged by contact.', 'limited', null, 'https://visitmississippi.org/things-to-do/blues-attractions/riverside-hotel/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Robert Johnson Grave Claim — Payne Chapel Memorial Baptist Church', 'robert-johnson-grave-claim-payne-chapel-memorial-baptist-church', 'weird-history', 33.44081, -90.30361, 'Quito', 'MS', 'A headstone erected at Payne Chapel marks another location once claimed as Robert Johnson''s burial place. It is useful as part of the unusual three-grave story surrounding Johnson, but should not be described as the accepted burial site.', 'open', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Robert Johnson Grave — Little Zion Missionary Baptist Church', 'robert-johnson-grave-little-zion-missionary-baptist-church', 'weird-history', 33.5637, -90.21637, 'Greenwood', 'MS', 'The grave at Little Zion is the burial location most widely accepted for blues musician Robert Johnson. Because Johnson has multiple memorial/grave claimant sites in Mississippi, OddWay should identify this one specifically rather than presenting all three as equally certain.', 'open', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Robert Johnson Memorial — Mount Zion Missionary Baptist Church', 'robert-johnson-memorial-mount-zion-missionary-baptist-church', 'weird-history', 33.39225, -90.31033, 'Morgan City', 'MS', 'A Robert Johnson memorial/cenotaph at Mount Zion, one of several places historically proposed as his burial site. Current scholarship generally favors Little Zion, so this stop should be labeled as a memorial and former grave claimant rather than the confirmed grave.', 'open', null, 'https://msbluestrail.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Roche-A-Cri State Park Petroglyphs', 'roche-a-cri-state-park-petroglyphs', 'weird-history', 44.00301, -89.81962, 'Friendship', 'WI', 'A sandstone outcrop rises abruptly above central Wisconsin and preserves Indigenous rock art along its base. A stairway also climbs the formation seasonally for long views, but visitors must stay off protected petroglyph surfaces.', 'limited', null, 'https://dnr.wisconsin.gov/topic/parks/rocheacri', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/topic/parks/rocheacri', null, null, null, 'America/Chicago'),
  ('Rock in the House', 'rock-in-the-house', 'weird-history', 44.14124, -91.73086, 'Fountain City', 'WI', 'In 1995, a massive boulder broke from the bluff and crashed directly into this house. Rather than remove the rock, the owners preserved the damage as a tiny museum, leaving the enormous stone lodged inside the building where it came to rest.', 'limited', null, 'https://www.roadsideamerica.com/story/2880', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/story/2880', null, null, null, 'America/Chicago'),
  ('Rock of Ages Granite Quarry', 'rock-of-ages-granite-quarry', 'weird-history', 44.15673, -72.49142, 'Graniteville', 'VT', 'Rock of Ages operates one of the world''s largest deep-hole dimension-granite quarries, where sheer gray walls descend hundreds of feet into water. Seasonal tours overlook the active quarry, and the visitor center even includes an outdoor granite bowling lane.', 'limited', null, 'https://www.atlasobscura.com/places/rock-of-ages-granite-quarry', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rock Quarry Cave', 'rock-quarry-cave', 'weird-history', 36.3166, -87.71318, 'Erin', 'TN', 'An old quarry opening has attracted explorers because of its dramatic man-made cavern appearance, but current access is posted and should not be treated as public. OddWay should route only to lawful exterior viewpoints and explicitly discourage entry or trespassing.', 'roadside', null, 'https://www.atlasobscura.com/places/rock-quarry-cave', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rocky Mount State Historic Site', 'rocky-mount-state-historic-site', 'weird-history', 36.40555, -82.33657, 'Piney Flats', 'TN', 'This preserved homestead served as the territorial capital of the Southwest Territory in the 1790s. Living-history interpretation and original structures make the site a rare surviving administrative center from before Tennessee became a state.', 'limited', null, 'https://www.rockymountmuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rocky Point Water-Tank Ruins', 'rocky-point-water-tank-ruins', 'weird-history', 41.6892, -71.36636, 'Warwick', 'RI', 'Rocky Point State Park preserves scattered remnants of the amusement park that operated here for generations before closing in the 1990s. Among the most evocative remains are concrete ruins associated with the old water-tank structure, separate from the World''s Fair arch included in Rhode Island Part 1. The ruins sit within the public state park and should be viewed without climbing unstable remnants.', 'open', null, 'https://riparks.ri.gov/parks/rocky-point-state-park', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rocky Springs Cemetery', 'rocky-springs-cemetery', 'weird-history', 32.09015, -90.81344, 'Rocky Springs', 'MS', 'The cemetery of the vanished Rocky Springs community, with old stones remaining after most of the town itself disappeared. Treat it as a historic cemetery: visit during lawful access hours, keep to paths and do not disturb graves.', 'open', null, 'https://www.nps.gov/places/rocky-springs.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rocky Springs Ghost Town Site', 'rocky-springs-ghost-town-site', 'weird-history', 32.08655, -90.79887, 'Rocky Springs', 'MS', 'The remains of a once-prosperous settlement abandoned after disease, erosion, war and economic decline. The NPS site preserves traces of the town, interpretive features and paths through a landscape that has largely returned to woods.', 'open', null, 'https://www.nps.gov/places/rocky-springs.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rocky Springs Methodist Church', 'rocky-springs-methodist-church', 'weird-history', 32.08977, -90.81348, 'Rocky Springs', 'MS', 'A surviving 1800s church standing near the vanished community of Rocky Springs. Its isolated setting beside a ghost-town landscape gives travelers a rare physical anchor to a town that otherwise almost disappeared.', 'open', null, 'https://www.nps.gov/places/rocky-springs.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rodney Presbyterian Church and Ghost Town', 'rodney-presbyterian-church-and-ghost-town', 'weird-history', 31.86278, -91.19983, 'Rodney', 'MS', 'A surviving 1830s church anchors the remains of Rodney, once an important Mississippi River town that declined after the river shifted away. Roads can be rough and surrounding property may be private; this is a ghost-town driving stop, not permission to enter abandoned structures. Coordinate source: https://www.hmdb.org/', 'roadside', null, 'https://www.apps.mdah.ms.gov/Public/prop.aspx?id=20435&view=facts', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Roger Williams Grave at Prospect Terrace', 'roger-williams-grave-at-prospect-terrace', 'weird-history', 41.82982, -71.407, 'Providence', 'RI', 'Roger Williams and his wife Mary were reinterred beneath the large monument at Prospect Terrace in 1939. Their earlier burial became famous because an apple-tree root grew through the grave in a human-like shape, the same root preserved by the Rhode Island Historical Society. This stop completes that story at Williams''s present resting place.', 'open', null, 'https://www.nps.gov/places/prospect-terrace.htm', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Roger Williams Root', 'roger-williams-root', 'weird-history', 41.82292, -71.40344, 'Providence', 'RI', 'When Roger Williams''s remains were exhumed in 1860, workers found an apple-tree root growing through the old grave in a shape interpreted as resembling a human body. The preserved "root that ate Roger Williams" belongs to the Rhode Island Historical Society and has been displayed at the John Brown House Museum. As of September 2026 the museum lists the root as temporarily off-view for exhibit maintenance, so check before visiting specifically for it.', 'limited', null, 'https://www.rihs.org/locations/the-john-brown-house-museum/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.rihs.org/locations/the-john-brown-house-museum/', null, null, null, 'America/New_York'),
  ('Rolling Fork Mounds', 'rolling-fork-mounds', 'weird-history', 32.89603, -90.8772, 'Rolling Fork', 'MS', 'A prehistoric mound site embedded in the modern Rolling Fork landscape, preserving part of the Delta''s much older human history. Use the public marker/viewing area and respect any adjacent private property.', 'roadside', null, 'https://trails.mdah.ms.gov/rollingfork', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ronald E. McNair Memorial Park', 'ronald-e-mcnair-memorial-park', 'weird-history', 33.87067, -79.75157, 'Lake City', 'SC', 'Lake City honors hometown astronaut Ronald McNair, who died aboard Space Shuttle Challenger in 1986, with a dedicated memorial park. The site connects a small South Carolina community directly to one of the defining tragedies of the American space program.', 'open', null, 'https://www.scpictureproject.org/florence-county/ronald-mcnair-memorial-park.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rose Island Lighthouse', 'rose-island-lighthouse', 'weird-history', 41.49549, -71.34271, 'Newport', 'RI', 'Built in 1870 on tiny Rose Island beneath the Newport Pell Bridge, this restored lighthouse can be reached by boat for tours and even overnight stays. The island also contains remnants of historic Fort Hamilton and protected wildlife habitat. Public access is seasonal and depends on transportation, weather and nesting restrictions.', 'limited', null, 'https://www.roseisland.org/daytrips', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.roseisland.org/', null, null, null, 'America/New_York'),
  ('Rose Island Ruins', 'rose-island-ruins', 'weird-history', 38.44975, -85.64556, 'Charlestown', 'IN', 'Rose Island was once a popular amusement park with rides, a swimming pool, zoo attractions and river access before the catastrophic Ohio River flood of 1937 left it beyond repair. Charlestown State Park now maintains a trail to the former park area, where visitors can see surviving foundations, the old pool and other ruins in the woods.', 'open', null, 'https://www.in.gov/dnr/state-parks/parks-lakes/charlestown-state-park/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Rowan Oak', 'rowan-oak', 'weird-history', 34.35981, -89.52469, 'Oxford', 'MS', 'William Faulkner''s longtime home, preserved by the University of Mississippi with his rooms, grounds and writing environment still central to the visit. The estate gives travelers a direct physical setting for one of the South''s most influential and famously gothic literary imaginations.', 'open', null, 'https://www.rowanoak.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rudolf Anderson F-86 Sabre Memorial', 'rudolf-anderson-f-86-sabre-memorial', 'weird-history', 34.84623, -82.38762, 'Greenville', 'SC', 'A jet displayed in Cleveland Park honors Greenville native Rudolf Anderson Jr., the only American killed by enemy fire during the Cuban Missile Crisis. Anderson was shot down while flying a U-2 reconnaissance mission over Cuba in 1962.', 'open', null, 'https://www.roadsideamerica.com/tip/24858', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ruggles Mine', 'ruggles-mine', 'weird-history', 43.58966, -71.99455, 'Grafton', 'NH', 'This enormous former mica mine cuts open the side of Isinglass Mountain with tunnels, pits and mineral-rich rock faces. After years of closure, Ruggles reopened to the public and again allows visitors to explore and collect a limited amount of minerals under site rules. The 2026 season is scheduled to run through October 11.', 'limited', null, 'https://www.rugglesmine.net/', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.rugglesmine.net/', null, null, null, 'America/New_York'),
  ('Ruins of Schoolmaster Hill', 'ruins-of-schoolmaster-hill', 'weird-history', 42.30305, -71.09572, 'Boston', 'MA', 'Stone walls and terraces remain from an Olmsted-designed Franklin Park structure that once served visitors and later golfers. Fire reduced the building to a scenic ruin on the same hill where Ralph Waldo Emerson had lived decades earlier.', 'open', null, 'https://www.atlasobscura.com/places/ruins-of-schoolmaster-hill', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Russell Cave National Monument', 'russell-cave-national-monument', 'weird-history', 34.9786, -85.80977, 'Bridgeport', 'AL', 'Russell Cave contains one of the Southeast’s most important archaeological records of repeated human occupation stretching back thousands of years. Visitors can follow the boardwalk to the massive shelter entrance, but entering the cave itself is prohibited.', 'open', null, 'https://www.nps.gov/ruca/index.htm', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ruth Ann Miller Shrine', 'ruth-ann-miller-shrine', 'weird-history', 47.26112, -88.46025, 'Calumet Township', 'MI', 'This remote memorial marks the abandoned mine shaft where six-year-old Ruth Ann Miller fell in 1966 during a tragedy that drew a major rescue effort. The incident helped focus attention on dangerous unsealed shafts across Copper Country; the shrine is reached by an unmarked dirt road and should be treated as a memorial rather than a curiosity to disturb.', 'limited', null, 'https://www.atlasobscura.com/places/ruth-ann-miller-memorial-shrine', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Rutland Prison Camp Ruins', 'rutland-prison-camp-ruins', 'weird-history', 42.40318, -72.0023, 'Rutland', 'MA', 'Concrete foundations, tunnels, root cellars and other remnants of an early twentieth-century prison farm are slowly disappearing into the woods. The complex once housed minor offenders and operated a large agricultural program before being abandoned in the 1930s; the ruins are now accessible on public recreation land.', 'open', null, 'https://www.atlasobscura.com/places/rutland-prison-camp', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ryman Alley', 'ryman-alley', 'weird-history', 36.16106, -86.77839, 'Nashville', 'TN', 'The narrow alley behind the Ryman Auditorium has served for generations as a backstage threshold between performers and downtown Nashville. Its loading doors, brick walls and music lore give travelers a less polished view of the city''s most famous venue.', 'open', null, 'https://www.ryman.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ryves Holt House', 'ryves-holt-house', 'weird-history', 38.77584, -75.14108, 'Lewes', 'DE', 'Often promoted as one of Delaware''s oldest surviving houses, the Ryves Holt House has traditionally been dated to 1665. Recent archival work has questioned that exact date, which makes the building an interesting stop not only for its age but for the evolving detective work around its history.', 'limited', null, 'https://www.historiclewes.org/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.historiclewes.org/', null, null, null, 'America/New_York'),
  ('Sacrifice Rock', 'sacrifice-rock', 'weird-history', 41.90227, -70.59672, 'Plymouth', 'MA', 'A large glacial boulder beside Old Sandwich Road is historically associated with Wampanoag travelers leaving offerings before journeys. Colonial writers later called it Sacrifice Rock. The site is best understood as a surviving landscape feature tied to Indigenous tradition rather than a supernatural roadside attraction.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=73683', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Saint Mary of the Seven Sorrows Catholic Church', 'saint-mary-of-the-seven-sorrows-catholic-church', 'weird-history', 36.16578, -86.78158, 'Nashville', 'TN', 'One of Nashville''s oldest surviving churches retains nineteenth-century architecture and a long urban history amid modern downtown development. It remains an active sacred space, so visitors should enter only during appropriate public hours.', 'limited', null, 'https://stmarysdowntown.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Salem Village Parsonage Site', 'salem-village-parsonage-site', 'weird-history', 42.56593, -70.9625, 'Danvers', 'MA', 'Archaeological foundations mark the home of Reverend Samuel Parris, where Betty Parris and Abigail Williams began exhibiting the strange behavior that helped ignite the 1692 witchcraft crisis. The house is gone, but the exposed foundation makes the beginning of the panic physically routeable.', 'open', null, 'https://www.atlasobscura.com/places/salem-village-parsonage', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salem Village Witchcraft Victims Memorial', 'salem-village-witchcraft-victims-memorial', 'weird-history', 42.56532, -70.9594, 'Danvers', 'MA', 'Unlike the better-known memorial in modern Salem, this monument stands in Danvers — the community that was Salem Village in 1692, where the crisis began. Stone panels commemorate the accused and preserve excerpts from their words, giving OddWay a second, geographically distinct witch-trial memorial tied directly to the village.', 'open', null, 'https://www.atlasobscura.com/places/salem-village-witchcraft-victims-memorial', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salem Witch Museum', 'salem-witch-museum', 'weird-history', 42.52371, -70.89113, 'Salem', 'MA', 'One of Salem''s longest-running witch-trial attractions uses life-size stage sets and narration to tell the story of the 1692 crisis, followed by an exhibit examining changing ideas about witches. Its presentation is theatrical, making it distinct from the city''s preserved trial sites and memorials.', 'limited', null, 'https://salemwitchmuseum.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://salemwitchmuseum.com/', null, null, null, 'America/New_York'),
  ('Salem Witch Trials Memorial', 'salem-witch-trials-memorial', 'weird-history', 42.52038, -70.89157, 'Salem', 'MA', 'Twenty stone benches set into a quiet memorial courtyard bear the names and execution dates of the people killed during the Salem witch trials. Rather than turning the history into a Halloween attraction, the site functions as a restrained memorial beside the Old Burying Point.', 'open', null, 'https://www.atlasobscura.com/places/salem-witch-trials-memorial', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salomon Mounds', 'salomon-mounds', 'weird-history', 34.37697, -90.48927, 'Coahoma', 'MS', 'A once larger Mississippian mound-and-plaza complex near Coahoma, including a large surviving platform mound with a historic cemetery on its summit. MDAH identifies it as private property with a designated viewing area.', 'roadside', null, 'https://trails.mdah.ms.gov/salomon', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sam Houston Schoolhouse State Historic Site', 'sam-houston-schoolhouse-state-historic-site', 'weird-history', 35.80194, -83.90444, 'Maryville', 'TN', 'A one-room schoolhouse preserves the place where Sam Houston taught before his later careers as governor of Tennessee and president of the Republic of Texas. The modest building is an unexpectedly small starting point for an outsized political life.', 'limited', null, 'https://samhoustonschoolhouse.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Samantha Smith — America’s Little Ambassador Statue', 'samantha-smith-americas-little-ambassador-statue', 'weird-history', 44.30591, -69.78281, 'Augusta', 'ME', 'A bronze statue outside the Maine State Museum honors Samantha Smith, the Maine schoolgirl who wrote to Soviet leader Yuri Andropov in 1982 asking why the Soviet Union wanted war. Her letter led to an invitation to visit the USSR, turning her into an unlikely child peace ambassador before her death in a 1985 plane crash. The sculpture shows Samantha releasing a dove while a bear cub sits beside her.', 'open', null, 'https://www.roadsideamerica.com/tip/22890', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sami Swings', 'sami-swings', 'weird-history', 38.24537, -85.71713, 'Louisville', 'KY', 'The grave of three-year-old Samantha "Sami" McDonald is marked by a life-size bronze sculpture depicting the child happily swinging while Jesus holds the ropes. The unusual and deeply personal memorial stands in Cave Hill Cemetery and is officially titled "Sami Swings."', 'open', null, 'https://www.atlasobscura.com/places/jesus-is-my-swingset', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('San Marcos de Apalache Historic State Park', 'san-marcos-de-apalache-historic-state-park', 'weird-history', 30.15363, -84.20662, 'St. Marks', 'FL', 'Ruins and reconstructed remains of a strategic fort site used by multiple empires and armies.', 'limited', null, 'https://www.floridastateparks.org/parks-and-trails/san-marcos-de-apalache-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('San Pedro Underwater Archaeological Preserve State Park', 'san-pedro-underwater-archaeological-preserve-state-park', 'weird-history', 24.85556, -80.76361, 'Islamorada', 'FL', 'Submerged 1733 Spanish treasure-fleet wreck preserved as an underwater archaeological park.', 'limited', null, 'https://www.floridastateparks.org/parks-and-trails/san-pedro-underwater-archaeological-preserve-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sand Cave — Floyd Collins Rescue Site Trail', 'sand-cave-floyd-collins-rescue-site-trail', 'weird-history', 37.15255, -86.04767, 'Cave City', 'KY', 'A short National Park Service trail leads to an overlook near Sand Cave, where Floyd Collins became trapped during a 1925 exploration attempt and died after a rescue effort followed across the country. The cave itself is dangerous and not open for entry; OddWay should route visitors only to the established boardwalk and overlook.', 'open', null, 'https://myhikes.org/trails/sand-cave-trail', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sandy Hook Lighthouse', 'sandy-hook-lighthouse', 'weird-history', 40.46173, -74.00202, 'Middletown Township', 'NJ', 'First lit in 1764, Sandy Hook Lighthouse is the oldest continuously operating lighthouse in the United States. The tower stands inside the Fort Hancock area of Gateway National Recreation Area, with scheduled ranger access to the interior.', 'limited', null, 'https://www.nps.gov/gate/learn/historyculture/sandy-hook-lighthouse.htm', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sandy Hook Nike Missile Radar Site', 'sandy-hook-nike-missile-radar-site', 'weird-history', 40.44895, -73.9927, 'Middletown Township', 'NJ', 'Surviving radar structures mark part of the Cold War Nike missile system that once defended the New York metropolitan area from air attack. The National Park Service still offers occasional guided tours of this former top-secret radar and guidance site near Horseshoe Cove.', 'limited', null, 'https://www.nps.gov/planyourvisit/event-details.htm?id=67AA9F42-DF76-6986-CA7F9F2192CABADB', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sanilac Petroglyphs Historic State Park', 'sanilac-petroglyphs-historic-state-park', 'weird-history', 43.65778, -83.01861, 'Cass City', 'MI', 'A sandstone outcrop here contains Michigan''s largest known collection of Indigenous rock carvings, including figures and teachings associated with Anishinaabe history. The site is jointly interpreted with the Saginaw Chippewa Indian Tribe, and the protected petroglyph viewing area is accessed through scheduled seasonal tours rather than unrestricted handling of the carvings.', 'limited', null, 'https://www.michigan.gov/recsearch/parks/sanilac', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Sarah Clayes House', 'sarah-clayes-house', 'weird-history', 42.28722, -71.46303, 'Framingham', 'MA', 'This early house is associated with Sarah Clayes, who survived accusations during the Salem witch trials and later settled in the area known as Salem End. The restored building is a private residence, so view only from lawful public space.', 'private', null, 'https://www.atlasobscura.com/places/sarah-clayes-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sarah Helen Whitman House', 'sarah-helen-whitman-house', 'weird-history', 41.83106, -71.40923, 'Providence', 'RI', 'Poet Sarah Helen Whitman lived at 88 Benefit Street and became briefly engaged to Edgar Allan Poe in 1848. Their intense and unsuccessful courtship is one of Providence''s strongest direct links to Poe. The building is a private residence, so it should be viewed only from the public sidewalk. Secondary source: https://edgarallanpoeri.com/contact/', 'roadside', null, 'https://literaryprovidence.com/authors', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sarah Swan Tombstone — Original Stone', 'sarah-swan-tombstone-original-stone', 'weird-history', 41.66956, -71.27508, 'Bristol', 'RI', 'The original eighteenth-century gravestone of Sarah Swan became a local curiosity because its carved portrait appears unusually expressive and distinctive compared with standard New England funerary art. To protect it from weather and vandalism, the original stone was moved to the Bristol Historical & Preservation Society while a replica marks the grave. Check museum hours before visiting specifically for the original.', 'limited', null, 'https://www.atlasobscura.com/places/sarah-swan-tombstone', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.bhpsri.org/', null, null, null, 'America/New_York'),
  ('Schoellkopf Power Station Ruins', 'schoellkopf-power-station-ruins', 'weird-history', 43.0928, -79.06283, 'Niagara Falls', 'NY', 'The Schoellkopf complex was once the world''s largest hydroelectric power station before a catastrophic rockslide and collapse destroyed most of it in 1956. A seasonal elevator at Niagara Falls State Park now carries visitors into the gorge, where surviving walls and industrial remnants can be seen along the official ruins trail.', 'limited', null, 'https://www.niagarafallsstatepark.com/attractions/schoellkopf-power-station-ruins-site/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Schoenhofen Pyramid Mausoleum', 'schoenhofen-pyramid-mausoleum', 'weird-history', 41.95959, -87.65954, 'Chicago', 'IL', 'An Egyptian Revival pyramid mausoleum with a sphinx-like entrance makes this one of the most visually unusual tombs in Graceland Cemetery.', 'limited', null, 'https://www.gracelandcemetery.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Schooner Fame of Salem', 'schooner-fame-of-salem', 'weird-history', 42.51964, -70.88806, 'Salem', 'MA', 'A working replica of the War of 1812 privateer Fame sails from Salem Harbor. The original ship captured multiple vessels before being lost, while the modern schooner gives visitors a rare chance to experience Salem''s privateering history under sail.', 'limited', null, 'https://schoonerfame.com/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Scottsboro Boys Museum & Cultural Center', 'scottsboro-boys-museum-cultural-center', 'weird-history', 34.67395, -86.04134, 'Scottsboro', 'AL', 'Located in the former Joyce Chapel, the museum documents the Scottsboro Boys cases, in which nine Black teenagers were falsely accused of rape in 1931. Exhibits focus on the trials, appeals and their lasting significance in American civil-rights and legal history.', 'limited', null, 'https://www.thescottsboroboysmuseum.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Seaside Sanatorium', 'seaside-sanatorium', 'weird-history', 41.30155, -72.12957, 'Waterford', 'CT', 'This dramatic shoreline complex opened in 1934 as a tuberculosis hospital designed around sunlight and sea air, then later served other institutional uses before closing in 1996. The grounds are now a state park, while the striking abandoned hospital buildings remain fenced and off-limits.', 'open', null, 'https://www.atlasobscura.com/places/seaside-sanitorium', '2026-09-08T18:39:47.144889+00:00', null, 'https://ctparks.com/parks/seaside-state-park', null, null, null, 'America/New_York'),
  ('Seneca Quarry', 'seneca-quarry', 'weird-history', 39.06988, -77.34408, 'Poolesville', 'MD', 'This abandoned quarry supplied the distinctive reddish Seneca sandstone used in major Washington-area buildings, most famously the Smithsonian Castle. Quarry cuts, ruins and related historic features remain within the C&O Canal National Historical Park landscape and are reached on foot.', 'limited', null, 'https://www.atlasobscura.com/places/seneca-quarry', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sequoyah Birthplace Museum', 'sequoyah-birthplace-museum', 'weird-history', 35.5068, -84.19487, 'Vonore', 'TN', 'This museum interprets Sequoyah, creator of the Cherokee syllabary, near his traditional birthplace in the Tennessee Valley. Exhibits place the writing system within Cherokee history and survival rather than treating Sequoyah as a roadside curiosity.', 'open', null, 'https://sequoyahmuseum.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sergeant Stubby Statue', 'sergeant-stubby-statue', 'weird-history', 41.55968, -72.6703, 'Middletown', 'CT', 'A bronze monument honors Sergeant Stubby, the stray dog adopted by Connecticut soldiers who became one of World War I''s most famous military animals. Stubby reportedly warned troops of gas attacks, located wounded soldiers and served with the 102nd Infantry.', 'open', null, 'https://www.atlasobscura.com/places/sergeant-stubby-statue', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Serpent Mound', 'serpent-mound', 'weird-history', 39.02414, -83.4296, 'Bratton Township', 'OH', 'Serpent Mound is a massive prehistoric effigy earthwork shaped like an undulating snake and is one of the most distinctive archaeological sites in North America. Visitors can follow the path around the protected mound, use the observation tower and visit the museum during posted hours; climbing on the earthwork or entering the site after the gates close is prohibited.', 'open', null, 'https://www.ohiohistory.org/visit/browse-historical-sites/serpent-mound/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Severed Arm of Saint Edmund', 'severed-arm-of-saint-edmund', 'weird-history', 41.32232, -71.96281, 'Stonington', 'CT', 'A chapel at Enders Island preserves a mummified arm traditionally identified as a relic of Saint Edmund of Canterbury. The centuries-old human relic makes an unexpectedly macabre stop within an otherwise peaceful Catholic retreat setting; visitors should respect chapel rules and scheduled access.', 'limited', null, 'https://www.atlasobscura.com/places/severed-arm-saint-edmund', '2026-09-08T18:39:47.144889+00:00', null, 'https://endersisland.org/', null, null, null, 'America/New_York'),
  ('Shade Swamp Sanctuary — Abandoned Zoo', 'shade-swamp-sanctuary-abandoned-zoo', 'weird-history', 41.70512, -72.86087, 'Farmington', 'CT', 'Stone and concrete remnants of a Depression-era wildlife facility hide in the woods of today''s Shade Swamp Sanctuary. Old cages and foundations give the otherwise ordinary nature preserve the atmosphere of an abandoned woodland zoo.', 'open', null, 'https://www.atlasobscura.com/places/shade-swamp-sanctuary', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shadows-on-the-Teche', 'shadows-on-the-teche', 'weird-history', 30.00439, -91.81566, 'New Iberia', 'LA', 'This 1830s house on Bayou Teche survives with extensive family records that document plantation life, slavery and the Civil War era. The National Trust operates it as a guided historic site rather than an unrestricted property.', 'limited', null, 'https://savingplaces.org/shadows-on-the-teche', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shakespeare Ghost Town Tours', 'shakespeare-ghost-town-tours', 'weird-history', 32.32479, -108.738557, 'Lordsburg', 'NM', 'Several mining booms passed through before the town took its present name in 1879. The Hill family began preserving the surviving buildings after buying the property in 1935. This National Historic Site is private and can only be seen on a guided tour — unescorted access is prohibited, and the owners warn about rattlesnakes and open shafts.', 'limited', null, 'https://www.shakespeareghostown.com/tours', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Denver'),
  ('Shearwater Pottery', 'shearwater-pottery', 'weird-history', 30.405, -88.82056, 'Ocean Springs', 'MS', 'A family pottery compound founded by Peter Anderson in 1928 and still producing ceramics using long-established forms, glazes and local traditions. The showroom is public while the working property remains an active craft site, so visitors should follow posted access rules.', 'open', null, 'https://www.shearwaterpottery.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shelburne Farms', 'shelburne-farms', 'weird-history', 44.39547, -73.24712, 'Shelburne', 'VT', 'This enormous former Vanderbilt-Webb country estate was laid out with landscape work by Frederick Law Olmsted and includes monumental barns, an inn and more than a thousand acres along Lake Champlain. The scale and theatrical design make the property feel closer to a self-contained Gilded Age world than an ordinary Vermont farm.', 'limited', null, 'https://www.atlasobscura.com/places/shelburne-farms', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shell Mound Archaeological Site', 'shell-mound-archaeological-site', 'weird-history', 29.20575, -83.06445, 'Cedar Key', 'FL', 'Massive ancient shell-mound complex in Lower Suwannee National Wildlife Refuge.', 'open', null, 'https://www.fws.gov/refuge/lower-suwannee', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shipwreck Park — Mary E. Morris', 'shipwreck-park-mary-e-morris', 'weird-history', 33.90945, -78.08295, 'Oak Island', 'NC', 'The skeletal remains of the 138-foot cargo ship Mary E. Morris sit in a landscaped median in an Oak Island neighborhood. The vessel sank in 1893, spent roughly a century underwater, and was eventually moved onto land, creating the surreal sight of a shipwreck sitting in the middle of a street.', 'open', null, 'https://www.atlasobscura.com/places/shipwreck-park', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shot Tower Historical State Park', 'shot-tower-historical-state-park', 'weird-history', 36.8838, -80.8529, 'Max Meadows', 'VA', 'This roughly 75-foot stone tower was built in the early 1800s to manufacture lead shot by dropping molten lead from the top so it formed into spheres while falling. The grounds are accessible as part of Virginia''s state park system, while entry into the tower itself is restricted to scheduled openings and programs.', 'limited', null, 'https://www.dcr.virginia.gov/state-parks/shot-tower', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shreveport Municipal Auditorium', 'shreveport-municipal-auditorium', 'weird-history', 32.50808, -93.75319, 'Shreveport', 'LA', 'This Art Deco auditorium is a cornerstone of Louisiana Hayride history and helped launch performers including Elvis Presley. It remains an active event venue, so interior access depends on tours, shows and the building calendar.', 'limited', null, 'https://www.shreveportmunicipalauditorium.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shunpike', 'shunpike', 'weird-history', 42.63604, -72.90576, 'Charlemont', 'MA', 'A Mohawk Trail rest area marks the place where travelers historically forded the Deerfield River to avoid paying a turnpike toll. The act helped popularize the term ''shunpike'' for deliberately bypassing toll roads.', 'roadside', null, 'https://www.atlasobscura.com/places/shunpike', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sideling Hill Tunnel on the Abandoned Pennsylvania Turnpike', 'sideling-hill-tunnel-on-the-abandoned-pennsylvania-turnpike', 'weird-history', 40.04851, -78.12915, 'Fulton County', 'PA', 'Sideling Hill Tunnel is a 6,782-foot former Pennsylvania Turnpike tunnel abandoned when the highway was rerouted in 1968. It is now part of the informal Pike2Bike route; reaching it requires hiking or cycling, and the interior is completely unlit, wet and rough, so visitors need lights and should use the established access points.', 'limited', null, 'https://highways.dot.gov/highway-history/general-highway-history/back-time/abandoned-pennsylvania-turnpike', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Siege of Brookfield Historic Markers', 'siege-of-brookfield-historic-markers', 'weird-history', 42.34328, -72.1428, 'New Braintree', 'MA', 'Several lonely roadside stones mark locations connected with the 1675 Siege of Brookfield during King Philip''s War, including an ambush and a camp associated with Metacomet. The markers preserve a violent chapter of colonial and Indigenous history that is otherwise easy to drive past.', 'roadside', null, 'https://www.atlasobscura.com/places/siege-of-brookfield-historic-markers', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Silver City Ghost Town', 'silver-city-ghost-town', 'weird-history', 35.597694, -118.4916, 'Bodfish', 'CA', 'More than twenty historic structures rescued from abandoned Kern Valley mining camps since the 1970s. The Corlew family bought the property in 1988, restored it and reopened in 1992. Now a small museum and film location with posted daily hours that depend on the weather.', 'limited', null, 'https://linktr.ee/silvercityghosttown', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Silver Springs State Park', 'silver-springs-state-park', 'weird-history', 29.21635, -82.05595, 'Silver Springs', 'FL', 'Historic glass-bottom boats, submerged archaeology, film history, and famous rhesus monkeys nearby.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/silver-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Simpson Spring', 'simpson-spring', 'weird-history', 42.03728, -71.07933, 'Easton', 'MA', 'An independent bottling plant operating over a natural spring since the nineteenth century still produces old-fashioned sodas and lets visitors fill water jugs from the source. The property preserves vintage equipment and a stubbornly old-school soda-making tradition.', 'open', null, 'https://www.atlasobscura.com/places/simpson-spring', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Site of Boston''s First Bell', 'site-of-bostons-first-bell', 'weird-history', 42.3637, -71.05369, 'Boston', 'MA', 'A small display at the Paul Revere House recalls the first bell cast in Boston by Paul Revere. Contemporary criticism suggested his earliest effort sounded rather bad, giving the celebrated craftsman a refreshingly imperfect first attempt.', 'open', null, 'https://www.atlasobscura.com/places/site-of-boston-s-first-bell', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Site of Edgar Allan Poe''s Death', 'site-of-edgar-allan-poes-death', 'weird-history', 39.29293, -76.59421, 'Baltimore', 'MD', 'Edgar Allan Poe died on October 7, 1849 at what was then Washington College Hospital after being found delirious several days earlier, and the circumstances of his final days remain disputed. The original hospital is gone, but a plaque on the later hospital complex marks the location traditionally associated with the room where Poe died.', 'roadside', null, 'https://www.atlasobscura.com/places/edgar-allen-poes-site-of-death', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Site of Sanitarium of Alonzo Orrin Scarborough (1860-1952) Pioneer Doctor', 'site-of-sanitarium-of-alonzo-orrin-scarborough-1860-1952-pioneer-doctor', 'weird-history', 32.716, -100.91725, 'Snyder', 'TX', 'This roadside Texas historical marker on Snyder''s courthouse square identifies the site of Dr. Alonzo Orrin Scarborough''s early sanitarium. No sanitarium attraction remains to tour; the value of the stop is the plaque and its short piece of local medical history.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, 'https://atlas.thc.texas.gov/Details/5415004883', null, 'node', 12453536656, 'America/Chicago'),
  ('Site of The Odessa Sanitarium', 'site-of-the-odessa-sanitarium', 'weird-history', 31.84679, -102.36865, 'Odessa', 'TX', 'A Texas historical marker in downtown Odessa identifies the former site of an early sanitarium that opened in the 1880s and later became part of the city''s civic history. The sanitarium no longer survives as an attraction, so this is a roadside plaque stop rather than a building visitors can enter.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, 'https://atlas.thc.texas.gov/Details/5135004898', null, 'node', 12403576671, 'America/Chicago'),
  ('Site of the Pine Tree Riot', 'site-of-the-pine-tree-riot', 'weird-history', 43.05226, -71.70555, 'Weare', 'NH', 'In 1772, New Hampshire mill owners resisted royal officials attempting to enforce laws reserving the colony''s largest white pines for the British Crown. The confrontation became known as the Pine Tree Riot and is often remembered as an early act of resistance preceding the American Revolution. A marker and millstone identify the historic tavern site.', 'roadside', null, 'https://www.wearehistoricalsociety.org/pineriot.php', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Site of the Z. Alexander Looby House Bombing', 'site-of-the-z-alexander-looby-house-bombing', 'weird-history', 36.16831, -86.80861, 'Nashville', 'TN', 'A bombing destroyed civil-rights attorney Z. Alexander Looby''s home in 1960 and helped trigger a major student march on Nashville City Hall. The residential location should be approached as a history stop from public space, with respect for current neighbors.', 'roadside', null, 'https://www.atlasobscura.com/places/z-alexander-looby-house-bombing-site', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Site of Tilly''s Escape', 'site-of-tillys-escape', 'weird-history', 38.64181, -75.60931, 'Seaford', 'DE', 'A marker and public site commemorate Harriet Tubman''s 1856 effort to guide an enslaved woman known as Tilly through the Seaford area toward freedom. It is a precise physical stop tied to one of Tubman''s documented rescue missions.', 'open', null, 'https://archives.delaware.gov/delaware-historical-markers/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skull Cave', 'skull-cave', 'weird-history', 45.859, -84.6221, 'Mackinac Island', 'MI', 'This shallow limestone cave earned its name after human bones were reportedly found inside during the eighteenth century. The cave is tied to Mackinac Island''s wartime and burial history and can be reached from the island''s public road-and-trail network without motor vehicles.', 'open', null, 'https://www.atlasobscura.com/things-to-do/michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Slave Haven Underground Railroad Museum — Burkle Estate', 'slave-haven-underground-railroad-museum-burkle-estate', 'weird-history', 35.16464, -90.04326, 'Memphis', 'TN', 'The Burkle Estate interprets local slavery, escape networks and Underground Railroad history through guided museum visits. Claims about specific secret passages should be understood through the museum''s interpretation, but the broader history of slavery and resistance is central to the stop.', 'limited', null, 'https://slavehavenmemphis.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sloss Furnaces National Historic Landmark', 'sloss-furnaces-national-historic-landmark', 'weird-history', 33.52066, -86.79131, 'Birmingham', 'AL', 'Two blast furnaces, stoves, pipes and industrial structures survive from Birmingham’s ironmaking era, creating one of America’s most complete preserved furnace complexes. The raw machinery and towering infrastructure make Sloss one of the state’s defining OddWay industrial sites.', 'open', null, 'https://www.slossfurnaces.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Smallpox Mass Grave Monument', 'smallpox-mass-grave-monument', 'weird-history', 41.2258, -73.05226, 'Milford', 'CT', 'A sandstone obelisk in Milford Cemetery marks a mass grave connected to Continental Army prisoners suffering from smallpox after being released from a British prison ship in 1777. Forty-six prisoners died within weeks, leaving one of Connecticut''s grimmer Revolutionary War memorials.', 'limited', null, 'https://www.roadsideamerica.com/tip/24369', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Smith Creek Mounds', 'smith-creek-mounds', 'weird-history', 31.14023, -91.5156, 'Woodville', 'MS', 'Three substantial Coles Creek-era ceremonial mounds surround a central plaza near Mississippi Highway 24. The site is archaeologically important but private, so observe it from the highway/public viewing area only.', 'roadside', null, 'https://trails.mdah.ms.gov/smithcreek', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Smith Robertson Museum and Cultural Center', 'smith-robertson-museum-and-cultural-center', 'weird-history', 32.30541, -90.18677, 'Jackson', 'MS', 'A museum of African American history and culture housed in Jackson''s first public school building for Black children. Exhibits cover slavery, migration, civil rights, Mississippi Black institutions and figures including former student Richard Wright.', 'open', null, 'https://jacksonms.gov/government/city-departments/human-and-cultural-services/cultural-services/smith-robertson-museum/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Smugglers'' Notch', 'smugglers-notch', 'weird-history', 44.52097, -72.77416, 'Stowe', 'VT', 'The narrow mountain pass is filled with enormous glacial boulders and a twisting road so tight that large vehicles cannot safely pass through. Its name comes from stories of nineteenth-century smuggling through the Green Mountains, and the road closes seasonally when snow makes the notch impassable.', 'limited', null, 'https://www.atlasobscura.com/places/smugglers-notch', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Smuttynose Island', 'smuttynose-island', 'weird-history', 42.98242, -70.60606, 'Kittery', 'ME', 'This small Isles of Shoals island became notorious after the brutal 1873 murders of two women living there, a crime that inspired books, poems, and later retellings. The island is privately owned but traditionally allows respectful daylight visitors who arrive by their own boat and follow posted rules.', 'limited', null, 'https://www.atlasobscura.com/places/smutttynose-island', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Snurfer Monument — Birthplace of Snowboarding', 'snurfer-monument-birthplace-of-snowboarding', 'weird-history', 43.23386, -86.25308, 'Muskegon', 'MI', 'Sherm Poppen invented the Snurfer in Muskegon in 1965 by fastening skis together as a toy for his daughters, helping launch what became modern snowboarding. The downtown sculpture called The Turning Point shows a child riding a Snurfer above a modern snowboarder.', 'open', null, 'https://www.roadsideamerica.com/tip/33885', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Snyder Sanitarium', 'snyder-sanitarium', 'weird-history', 32.23366, -97.756, 'Glen Rose', 'TX', 'Snyder Sanitarium is a historic Glen Rose medical building associated with early local health care, with a Texas historical marker explaining its story. Travelers should treat it primarily as a roadside historic-site/exterior stop unless a current occupant specifically permits interior access.', 'roadside', null, 'https://atlas.thc.state.tx.us/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 12453473996, 'America/Chicago'),
  ('Soldier Creek B-29 Crash Memorial', 'soldier-creek-b-29-crash-memorial', 'weird-history', 36.7896, -88.42902, 'Benton', 'KY', 'A black stone memorial near Soldier Creek remembers a B-29 Superfortress that crashed in this area on July 1, 1945. Nine men were killed and one survived, turning an otherwise quiet rural roadside into the marker for a largely forgotten wartime aviation disaster.', 'roadside', null, 'https://www.waymarking.com/waymarks/WMB0M5_Soldier_Creek_B_29_Crash_Memorial_Marshall_Co_Kentucky', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Soul City — Unrealized Utopia', 'soul-city-unrealized-utopia', 'weird-history', 36.40848, -78.27027, 'Manson', 'NC', 'Civil-rights leader Floyd McKissick envisioned Soul City as a new, racially integrated community with jobs, housing, industry, and political power built from the ground up. Federal support ended before the ambitious plan was realized, leaving a scattered landscape of surviving buildings and infrastructure from one of America’s most unusual planned-community experiments.', 'open', null, 'https://www.atlasobscura.com/places/soul-city', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Southeast Lighthouse', 'southeast-lighthouse', 'weird-history', 41.1513, -71.5737, 'New Shoreham', 'RI', 'Block Island''s dramatic brick Southeast Lighthouse was completed in the 1870s near the Mohegan Bluffs. Coastal erosion eventually brought the cliffs dangerously close, forcing the entire lighthouse to be moved back from the edge in 1993. Tours and interior access are seasonal, while exterior access depends on current site conditions.', 'limited', null, 'https://www.atlasobscura.com/places/southeast-lighthouse', '2026-09-09T04:49:27.913704+00:00', null, 'https://southeastlighthouse.org/', null, null, null, 'America/New_York'),
  ('Southern Museum of Flight', 'southern-museum-of-flight', 'weird-history', 33.56349, -86.73806, 'Birmingham', 'AL', 'Aircraft, engines, military displays and experimental aviation artifacts fill indoor and outdoor exhibits near the Birmingham airport. The collection includes unusual prototypes and restored aircraft spanning multiple eras.', 'open', null, 'https://southernmuseumofflight.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Space Shuttle Challenger Memorial', 'space-shuttle-challenger-memorial', 'weird-history', 44.25644, -72.59164, 'Montpelier', 'VT', 'A small granite monument memorializes the seven astronauts killed in the 1986 Challenger disaster despite Vermont having little direct connection to the shuttle program. The understated memorial has survived relocation and remains an unexpectedly space-themed landmark in the state capital.', 'open', null, 'https://www.atlasobscura.com/places/challenger-memorial-park', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spanish Military Hospital Museum', 'spanish-military-hospital-museum', 'weird-history', 29.89565, -81.31214, 'St. Augustine', 'FL', 'Recreated colonial hospital interpreting early surgery, medicines, and battlefield treatment.', 'limited', null, 'https://smhmuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spectacle Island Sea Glass Beaches', 'spectacle-island-sea-glass-beaches', 'weird-history', 42.3224, -70.9877, 'Boston', 'MA', 'Boston Harbor''s former garbage dump was capped and remade into Spectacle Island, but its beaches still reveal colorful sea glass, ceramics and fragments of the city''s discarded past. Park rules require visitors to leave these cultural materials where they find them. Ferry access is seasonal.', 'limited', null, 'https://www.atlasobscura.com/places/spectacle-island', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spencer´s Mining Camp', 'spencer-s-mining-camp', 'weird-history', 37.246992, -111.952239, 'Kanab', 'UT', 'Mapped within the same small Pahreah historic area as the cellar and the chimney. No reliable source establishes a separate history for Spencer''s as its own settlement, so treat it as one mining-era remnant of the larger site, on the same dirt-road route.', 'limited', null, 'https://www.nps.gov/glca/planyourvisit/day-hikes.htm', null, null, null, null, null, null, 'America/Denver'),
  ('Spocott Windmill Village', 'spocott-windmill-village', 'weird-history', 38.58958, -76.18149, 'Cambridge', 'MD', 'The current post windmill is a reconstruction of a 19th-century mill destroyed by a blizzard, surrounded by a collection of relocated and restored historic buildings. The grounds are generally accessible from dawn to dusk, while buildings and milling demonstrations have more limited schedules.', 'open', null, 'https://visitdorchester.org/spocott-windmill/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spooner Well', 'spooner-well', 'weird-history', 42.22553, -72.085, 'Brookfield', 'MA', 'A marker identifies the well where Joshua Spooner''s body was dumped after his wife Bathsheba arranged his murder in 1778. The resulting trial ended with Bathsheba and three accomplices being executed and became one of colonial Massachusetts'' most notorious criminal cases.', 'open', null, 'https://www.atlasobscura.com/places/spooner-well', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Springsteen ''Born to Run'' House', 'springsteen-born-to-run-house', 'weird-history', 40.29931, -73.99323, 'Long Branch', 'NJ', 'The modest house at 7½ West End Court is closely associated with Bruce Springsteen''s mid-1970s period and the creation of Born to Run. It remains a private residence rather than a museum, so OddWay travelers should only view it from the public street without disturbing occupants.', 'private', null, 'https://www.roadsideamerica.com/location/map?mode=detail&id=28887', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sputnik IV Crash Site Marker', 'sputnik-iv-crash-site-marker', 'weird-history', 44.09883, -87.6577, 'Manitowoc', 'WI', 'A brass ring embedded in North 8th Street marks where a fragment associated with the Soviet Sputnik IV spacecraft crashed back to Earth in 1962. Manitowoc later embraced the bizarre Cold War incident with the annual Sputnikfest celebration.', 'open', null, 'https://www.manitowoc.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.manitowoc.org/', null, null, null, 'America/Chicago'),
  ('Squire Boone Caverns', 'squire-boone-caverns', 'weird-history', 38.065, -86.13355, 'Mauckport', 'IN', 'Squire Boone, younger brother of Daniel Boone, settled in this area and developed a gristmill near the cave system in the early nineteenth century. His remains are associated with the cavern property, where guided tours descend through underground rooms, streams and formations around a site carrying both natural and frontier history.', 'limited', null, 'https://squireboonecaverns.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://squireboonecaverns.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('SS Copenhagen Underwater Archaeological Preserve', 'ss-copenhagen-underwater-archaeological-preserve', 'weird-history', 26.20582, -80.08513, 'Lauderdale-by-the-Sea', 'FL', '1898 steamship wrecked on a reef in 1900 and now a shallow protected dive site.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/ss-copenhagen/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('SS Morro Castle Memorial', 'ss-morro-castle-memorial', 'weird-history', 40.22355, -73.99904, 'Asbury Park', 'NJ', 'A memorial near the Asbury Park waterfront remembers the victims of the SS Morro Castle disaster, a 1934 passenger-ship fire that killed more than 130 people offshore. The burned ship eventually grounded near the city and became a grim temporary tourist spectacle.', 'open', null, 'https://www.atlasobscura.com/places/morro-castle-monument', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('SS Tarpon Underwater Archaeological Preserve', 'ss-tarpon-underwater-archaeological-preserve', 'weird-history', 30.09503, -85.94258, 'Panama City', 'FL', 'Passenger-and-freight steamer lost in a 1937 gale, now a protected deep-water archaeological preserve.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/ss-tarpon/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Albans Raid Marker', 'st-albans-raid-marker', 'weird-history', 44.81137, -73.08328, 'St. Albans', 'VT', 'A historical marker recalls the 1864 St. Albans Raid, when Confederate operatives crossed from Canada and robbed local banks before fleeing north. The attack is remembered as the northernmost major land action associated with the American Civil War.', 'open', null, 'https://oakcrestheritage.com/markers/vermont/franklin-county/st-albans-raid', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Augustine National Cemetery', 'st-augustine-national-cemetery', 'weird-history', 29.89169, -81.30583, 'St. Augustine', 'FL', 'Compact military cemetery holding Seminole War dead and the distinctive Dade monuments.', 'open', null, 'https://www.cem.va.gov/cems/nchp/staugustine.asp', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Helena Parish Chapel of Ease Ruins', 'st-helena-parish-chapel-of-ease-ruins', 'weird-history', 32.37528, -80.57667, 'Saint Helena Island', 'SC', 'Tabby walls are all that remain of a chapel built in the 1700s for plantation families who lived too far from Beaufort’s main parish church. Fire destroyed the chapel after the Civil War, leaving a stark shell and adjoining cemetery beneath Lowcountry trees.', 'open', null, 'https://www.atlasobscura.com/places/st-helena-parish-chapel-of-ease-ruins', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. Joan of Arc Chapel', 'st-joan-of-arc-chapel', 'weird-history', 43.03761, -87.931, 'Milwaukee', 'WI', 'A medieval European chapel dismantled and moved to the United States now stands in the middle of Marquette University''s campus. Its stones were reassembled in Milwaukee, creating a genuine piece of medieval architecture in an unexpectedly modern setting.', 'limited', null, 'https://www.marquette.edu/st-joan-of-arc-chapel/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.marquette.edu/st-joan-of-arc-chapel/', null, null, null, 'America/Chicago'),
  ('St. Louis Cemetery No. 1', 'st-louis-cemetery-no-1', 'weird-history', 29.95936, -90.07144, 'New Orleans', 'LA', 'New Orleans'' oldest surviving municipal cemetery is a dense landscape of above-ground tombs tied to some of the city''s best-known historical and supernatural stories. Public entry is controlled through authorized tours, so do not expect unrestricted walk-in access.', 'limited', null, 'https://nolacatholiccemeteries.org/st-louis-cemetery-1', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stand on Three States Marker', 'stand-on-three-states-marker', 'weird-history', 41.69612, -84.80596, 'Fremont', 'IN', 'Near Indiana''s northeastern corner, a small benchmark marks the point where Indiana, Michigan and Ohio meet. A larger nearby monument makes the tri-state junction easier to find, but the actual survey point is much more modest and sits close to the road, so visitors should watch for traffic.', 'roadside', null, 'https://www.roadsideamerica.com/tip/50657', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Starting Point of the First New Orleans Mardi Gras Parade Marker', 'starting-point-of-the-first-new-orleans-mardi-gras-parade-marker', 'weird-history', 29.94547, -90.06934, 'New Orleans', 'LA', 'A historical marker identifies the area associated with the Mistick Krewe of Comus procession of 1857, a major turning point in the development of organized Mardi Gras parades. It gives travelers a concrete point for a tradition otherwise spread across the city.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('State Penitentiary C.S.A. and Texas Civil War Manufacturing', 'state-penitentiary-c-s-a-and-texas-civil-war-manufacturing', 'weird-history', 30.72307, -95.54688, 'Huntsville', 'TX', 'This Huntsville stop is a roadside Texas historical marker describing the state penitentiary''s role in Confederate-era manufacturing during the Civil War. It is not an abandoned prison attraction or paranormal tour, so visitors should expect a plaque and exterior historical context rather than building access.', 'roadside', null, 'https://www.hmdb.org/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'node', 12454128116, 'America/Chicago'),
  ('Station Fire Memorial Park', 'station-fire-memorial-park', 'weird-history', 41.6843, -71.5109, 'West Warwick', 'RI', 'This memorial occupies the site of The Station nightclub, where a pyrotechnic fire on February 20, 2003 killed 100 people and injured more than 200. The park was created by victims'' families, survivors and supporters as a permanent place of remembrance. This should be presented by OddWay as respectful dark history, not as a paranormal attraction.', 'open', null, 'https://www.stationfirememorialfoundation.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.stationfirememorialfoundation.org/', null, null, null, 'America/New_York'),
  ('Stax Museum of American Soul Music', 'stax-museum-of-american-soul-music', 'weird-history', 35.11578, -90.0312, 'Memphis', 'TN', 'Built on the site of Stax Records, the museum preserves the story of the integrated label that produced Otis Redding, Isaac Hayes and many other soul artists. Exhibits include stage clothing, recording history and famously extravagant vehicles.', 'open', null, 'https://staxmuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stede Bonnet Hanging Site', 'stede-bonnet-hanging-site', 'weird-history', 32.77003, -79.92978, 'Charleston', 'SC', 'A small monument marks the area where the “Gentleman Pirate” Stede Bonnet and members of his crew were executed in 1718. Bonnet’s strange career—from wealthy plantation owner to inept pirate associate of Blackbeard—makes the quiet waterfront location unusually rich in pirate history.', 'open', null, 'https://www.atlasobscura.com/places/pirate-hanging-site-monument', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Steeple Building Museum', 'steeple-building-museum', 'weird-history', 41.20049, -90.11861, 'Bishop Hill', 'IL', 'The 1854 Steeple Building now houses exhibits and artifacts from Bishop Hill''s once-thriving Swedish communal colony.', 'limited', null, 'https://bishophillheritage.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stellafane Observatory', 'stellafane-observatory', 'weird-history', 43.27677, -72.51657, 'Springfield', 'VT', 'Amateur telescope makers have gathered on Breezy Hill for the Stellafane Convention since the 1920s. The site preserves the clubhouse and observing traditions of one of America''s oldest organized communities devoted to building telescopes by hand, with access centered around scheduled events.', 'limited', null, 'https://stellafane.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Steps to Nowhere', 'steps-to-nowhere', 'weird-history', 43.2006, -71.53348, 'Concord', 'NH', 'Two stone staircases stand without a house, leading upward into empty space beside a Concord street. They are remnants of the final home of President Franklin Pierce, which survived long after his death before being demolished in the twentieth century. The stairs are a compact physical ghost of a building that no longer exists.', 'roadside', null, 'https://www.atlasobscura.com/places/steps-to-nowhere', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stern Plate of the USS Enterprise', 'stern-plate-of-the-uss-enterprise', 'weird-history', 41.00794, -74.01057, 'River Vale', 'NJ', 'A large steel stern plate bearing the name ENTERPRISE survives from the World War II aircraft carrier USS Enterprise, one of the most decorated U.S. Navy ships of the conflict. The relic is displayed as part of the township''s veterans memorial.', 'open', null, 'https://www.roadsideamerica.com/tip/15144', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stevenson Railroad Depot Museum', 'stevenson-railroad-depot-museum', 'weird-history', 34.86763, -85.83977, 'Stevenson', 'AL', 'This nineteenth-century depot preserves the story of Stevenson’s position at a major railroad junction used heavily during the Civil War. Artifacts, local history and the depot itself make the surviving structure the centerpiece.', 'limited', null, 'https://encyclopediaofalabama.org/article/stevenson-railroad-depot-museum/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stiltsville', 'stiltsville', 'weird-history', 25.65792, -80.17084, 'Key Biscayne', 'FL', 'Cluster of historic wooden houses standing on stilts in Biscayne Bay.', 'open', null, 'https://www.nps.gov/bisc/learn/historyculture/stiltsville.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stone Man of Bowman Family Crypt', 'stone-man-of-bowman-family-crypt', 'weird-history', 43.48574, -72.87974, 'Shrewsbury', 'VT', 'A life-size marble figure appears to creep eternally up the steps of the Bowman family mausoleum in a rural cemetery. The strange composition is part of an elaborate nineteenth-century family memorial and gives the crypt a far more theatrical appearance than the surrounding graves.', 'open', null, 'https://www.atlasobscura.com/places/stone-man-of-bowman-family-crypt', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stone''s Bridge', 'stones-bridge', 'weird-history', 42.33917, -71.39541, 'Framingham', 'MA', 'A dry-laid stone bridge from the 1850s extends partway across the Sudbury River after flood damage removed one approach. The structure is stabilized but closed to crossing, leaving a historic bridge that quite literally leads nowhere.', 'roadside', null, 'https://www.atlasobscura.com/places/stones-bridge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stonewall Jackson''s Arm Grave', 'stonewall-jacksons-arm-grave', 'weird-history', 38.31803, -77.73239, 'Locust Grove', 'VA', 'After Stonewall Jackson was accidentally shot by Confederate troops at Chancellorsville in 1863, surgeons amputated his left arm and a chaplain buried it in the Lacy family cemetery at Ellwood Manor. Jackson himself died days later and was buried in Lexington, leaving this small marked arm grave as one of Virginia''s strangest Civil War burial sites; access follows National Park Service and Ellwood hours.', 'limited', null, 'https://www.nps.gov/places/000/stonewall-jackson-arm.htm', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stopping Stones Memorial', 'stopping-stones-memorial', 'weird-history', 44.47576, -73.21563, 'Burlington', 'VT', 'Small brass markers embedded in the sidewalk commemorate Lavinia Parker and her son Francis, who were enslaved in nineteenth-century Burlington. The memorial follows the concept of European stumbling stones, using an easily overlooked street-level marker to force attention toward a difficult local history.', 'open', null, 'https://www.atlasobscura.com/places/stopping-stone-marker-of-enslaved-vermonters', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stumphouse Tunnel', 'stumphouse-tunnel', 'weird-history', 34.76482, -83.06404, 'Walhalla', 'SC', 'Workers began boring this railroad tunnel through Stumphouse Mountain in the 1850s as part of an ambitious route through the Blue Ridge, but construction ended before the tunnel was completed. Visitors can walk into part of the dark unfinished passage, which later became useful for aging Clemson blue cheese.', 'limited', null, 'https://www.stumphousetunnel.com/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sultana Disaster Memorial', 'sultana-disaster-memorial', 'weird-history', 35.90902, -83.93642, 'Knoxville', 'TN', 'A memorial in Mount Olive Cemetery honors East Tennessee soldiers lost in the 1865 explosion and sinking of the steamboat Sultana, one of the deadliest maritime disasters in U.S. history. Visit as a cemetery memorial rather than a novelty stop.', 'limited', null, 'https://www.knoxhistoryproject.org/sultana/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sun Studio', 'sun-studio', 'weird-history', 35.13929, -90.03771, 'Memphis', 'TN', 'The tiny studio where Elvis Presley, Johnny Cash, Jerry Lee Lewis and others recorded is preserved as a guided-tour destination. Its modest size contrasts sharply with its enormous influence on rock and roll history.', 'limited', null, 'https://www.sunstudio.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sunken Gardens', 'sunken-gardens', 'weird-history', 27.78733, -82.63979, 'St. Petersburg', 'FL', 'Century-old roadside botanical attraction built around a drained sinkhole.', 'limited', null, 'https://www.stpete.org/visitors/sunken_gardens.php', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sunken Trace', 'sunken-trace', 'weird-history', 31.9702, -90.95558, 'Port Gibson', 'MS', 'A deeply eroded remnant of the Old Natchez Trace where centuries of foot, horse and wagon traffic carved the roadbed below the surrounding ground. A short path from the Parkway pull-off lets visitors walk directly into the historic corridor.', 'open', null, 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Surratt House Museum', 'surratt-house-museum', 'weird-history', 38.76417, -76.89729, 'Clinton', 'MD', 'Mary Surratt''s country home and tavern became a meeting point and supply stop connected to the Lincoln assassination conspiracy. Restored as a museum, it focuses on the Surratt family, the Confederate underground and Booth''s escape; current public access is limited to scheduled tour and walk-in hours.', 'limited', null, 'https://www.surrattmuseum.org/visitor-information', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Susanna Jayne Headstone', 'susanna-jayne-headstone', 'weird-history', 42.5103, -70.84642, 'Marblehead', 'MA', 'This extraordinarily elaborate 1776 gravestone crowds together a skeleton, scythe, sun, moon, ouroboros, angels and other mortality symbols. It is an unusually dense example of New England funerary art and looks closer to an occult illustration than a typical colonial marker. Visit the burial ground respectfully during permitted hours.', 'limited', null, 'https://www.atlasobscura.com/places/susanna-jayne-headstone', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Swan Lake Mounds', 'swan-lake-mounds', 'weird-history', 33.09845, -90.99668, 'Hollandale', 'MS', 'A Native American mound site inside Yazoo National Wildlife Refuge, where two of four original mounds remain visible near the lake. Refuge roads, trails and visitor facilities make this a comparatively accessible archaeological stop; check refuge conditions before going.', 'open', null, 'https://trails.mdah.ms.gov/swanlake', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.fws.gov/refuge/yazoo', null, null, null, 'America/Chicago'),
  ('Swift-Coles Historic Home', 'swift-coles-historic-home', 'weird-history', 30.31278, -87.72648, 'Bon Secour', 'AL', 'This Gulf Coast house began as a small dogtrot cabin in 1882 and expanded into a sprawling 6,000-square-foot home filled with period antiques. County preservation staff operate tours on a limited schedule.', 'limited', null, 'https://www.baldwincountyal.gov/departments/archives-history/bchdc/swift-coles-historic-home', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sybil Ludington Statue', 'sybil-ludington-statue', 'weird-history', 41.39291, -73.45137, 'Danbury', 'CT', 'A bronze Sybil Ludington rides through downtown Danbury in memory of the teenage messenger traditionally credited with a long Revolutionary War nighttime ride. Historians debate parts of the famous story, which gives the monument an interesting mix of history and legend.', 'open', null, 'https://www.roadsideamerica.com/tip/23188', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sybil''s Cave', 'sybils-cave', 'weird-history', 40.74533, -74.02298, 'Hoboken', 'NJ', 'A stone portal along the Hoboken waterfront recreates the entrance to a nineteenth-century spring grotto once promoted for its supposedly healthful water. The original cave also became connected with a notorious unsolved murder after the 1841 death of Mary Rogers.', 'open', null, 'https://www.atlasobscura.com/places/sybils-cave', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tahawus Ghost Town', 'tahawus-ghost-town', 'weird-history', 44.05061, -74.05098, 'Newcomb', 'NY', 'The abandoned mining settlement of Tahawus sits deep in the Adirondacks near the old iron and titanium works where Theodore Roosevelt began his famous 1901 ride to the presidency. Furnace ruins and surviving structures remain around the remote historic district, reached by a long drive into public forest lands and short walks from established access areas.', 'limited', null, 'https://www.adirondackhub.com/history/tahawus', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tallahatchie County Courthouse', 'tallahatchie-county-courthouse', 'weird-history', 33.97064, -90.3696, 'Sumner', 'MS', 'The courthouse where the 1955 murder trial following Emmett Till''s killing took place. It remains a functioning civic building as well as a major civil-rights historic site, so interior access depends on courthouse schedules and current visitor arrangements.', 'limited', null, 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tannehill Ironworks Historical State Park', 'tannehill-ironworks-historical-state-park', 'weird-history', 33.25781, -87.05946, 'McCalla', 'AL', 'Ruins and reconstructed structures preserve an ironmaking community whose furnaces supplied Confederate industry before Union forces destroyed the works in 1865. The park combines furnace remains, historic buildings, trails and an iron-and-steel museum.', 'open', null, 'https://www.tannehillstatepark.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tarpon Springs Sponge Docks', 'tarpon-springs-sponge-docks', 'weird-history', 28.1558, -82.75625, 'Tarpon Springs', 'FL', 'Historic Greek sponge-diving district with old diving traditions, sponge boats, and maritime culture.', 'open', null, 'https://www.visitstpeteclearwater.com/communities/tarpon-springs', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Teddy Bear Origin Marker', 'teddy-bear-origin-marker', 'weird-history', 32.90858, -90.87658, 'Rolling Fork', 'MS', 'A roadside marker tied to Theodore Roosevelt''s 1902 Mississippi bear hunt and the story that helped inspire the name "teddy bear." The event''s popular retelling has become part of American toy folklore, making this a compact but meaningful OddWay stop.', 'roadside', null, 'https://visitmississippi.org/trip-ideas/mississippi-eccentricities-you-have-to-see/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Teddy''s Juke Joint', 'teddys-juke-joint', 'weird-history', 30.59315, -91.16818, 'Zachary', 'LA', 'Teddy''s is a decorated shotgun-house blues club covered inside with lights, memorabilia and handmade details. Live music follows a changing schedule, so it is a destination to verify before making a dedicated detour.', 'limited', null, 'https://www.visitbatonrouge.com/directory/teddys-juke-joint/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Temple Bell', 'temple-bell', 'weird-history', 42.34134, -71.09429, 'Boston', 'MA', 'A huge seventeenth-century Japanese temple bell sits outdoors near the Back Bay Fens. Taken from Japan as wartime scrap after World War II, it was later formally presented to Boston as a symbol of peace, giving the object an unusually complicated journey from temple artifact to public monument.', 'open', null, 'https://www.atlasobscura.com/places/temple-bell', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tennessee Pride Sausage Grave', 'tennessee-pride-sausage-grave', 'weird-history', 36.23397, -86.72467, 'Nashville', 'TN', 'The grave associated with the founder of Tennessee Pride became known for imagery tied to the sausage brand and its country-boy mascot. It is a small piece of commercial culture inside a cemetery, so respectful daytime visitation is essential.', 'limited', null, 'https://www.atlasobscura.com/places/tennessee-pride-sausage-grave', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tent Graves of Mt. Gilead Cemetery', 'tent-graves-of-mt-gilead-cemetery', 'weird-history', 35.89534, -85.50331, 'Sparta', 'TN', 'Several graves are covered by pitched stone slabs that resemble tiny tents, a regional burial tradition concentrated in parts of Tennessee and Kentucky. The unusual forms should be viewed respectfully without climbing or disturbing the stones.', 'limited', null, 'https://www.atlasobscura.com/places/tent-graves', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Brickyard', 'the-brickyard', 'weird-history', 41.3769, -70.74429, 'Chilmark', 'MA', 'A tall brick chimney and scattered machinery survive from a Martha''s Vineyard brickmaking operation with roots reaching back to the seventeenth century. A formal conservation trail leads through the site, where industrial ruins sit unexpectedly amid coastal woodland.', 'open', null, 'https://www.atlasobscura.com/places/the-brickyard', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Ether Dome', 'the-ether-dome', 'weird-history', 42.36243, -71.06978, 'Boston', 'MA', 'Inside Massachusetts General Hospital is the historic operating theater where ether anesthesia was publicly demonstrated during surgery in 1846. The room also contains antique surgical material, a skeleton and an Egyptian mummy, making it one of Boston''s strongest medical-history oddities.', 'limited', null, 'https://www.atlasobscura.com/places/ether-dome', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Evil Dead Cabin Site', 'the-evil-dead-cabin-site', 'weird-history', 36.22263, -83.37659, 'Morristown', 'TN', 'The remote property associated with the cabin used in Sam Raimi''s original The Evil Dead has become a cult-horror pilgrimage point. The cabin itself is gone and the land is private; OddWay visitors should never enter the property or attempt to hunt for remnants beyond lawful public access.', 'private', null, 'https://www.atlasobscura.com/places/the-evil-dead-cabin-morristown-tennessee', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Four Way', 'the-four-way', 'weird-history', 35.11976, -90.04127, 'Memphis', 'TN', 'This historic soul-food restaurant served major civil-rights figures, musicians and neighborhood residents through decades of Memphis history. Its significance lies as much in the conversations and community it hosted as in the food itself.', 'open', null, 'https://www.atlasobscura.com/places/the-four-way', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Fugitive Train Wreck', 'the-fugitive-train-wreck', 'weird-history', 35.37043, -83.26325, 'Sylva', 'NC', 'Rusting train and bus wreckage from the practical-effects crash sequence in the 1993 film The Fugitive still sits beside the Great Smoky Mountains Railroad. The wreckage is on railroad property and trespassing is prohibited; it can be viewed from legitimate public areas or from the railroad’s Tuckasegee River excursion.', 'private', null, 'https://www.atlasobscura.com/places/the-fugitive-train-wreck', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Garfield Tea House', 'the-garfield-tea-house', 'weird-history', 40.26643, -73.99708, 'Long Branch', 'NJ', 'A small structure in Church of the Presidents park was built using railroad ties from the emergency rail spur constructed to carry wounded President James A. Garfield to the shore in 1881. Garfield died nearby after the assassination attempt, leaving this unusual reuse of the temporary railroad as a memorial.', 'open', null, 'https://www.roadsideamerica.com/location/map?mode=detail&id=22598', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Girl in Blue Grave', 'the-girl-in-blue-grave', 'weird-history', 41.63921, -81.4115, 'Willoughby', 'OH', 'An unidentified young woman dressed entirely in blue was struck and killed by a train in Willoughby on Christmas Eve 1933, and local residents paid for her burial and a marker reading "Unknown but not forgotten." She was identified decades later as Josephine "Sophie" Klimczak, and a second marker now gives her name beside the original grave in Willoughby Village Cemetery.', 'open', null, 'https://www.atlasobscura.com/places/the-girl-in-blue-willoughby-ohio', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Grave of XYZ', 'the-grave-of-xyz', 'weird-history', 41.38548, -72.42816, 'Deep River', 'CT', 'A tiny stone marked only ''XYZ'' identifies the burial place of an unidentified bank robber killed during an 1899 attempted robbery. For decades, local lore said a mysterious woman dressed in black appeared at the grave every year around the anniversary of his death.', 'open', null, 'https://www.atlasobscura.com/places/the-grave-of-xyz-deep-river-connecticut', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Holy Land Experience Ruins/Site', 'the-holy-land-experience-ruins-site', 'weird-history', 28.49301, -81.43395, 'Orlando', 'FL', 'Former biblical theme park site remembered for full-scale Jerusalem-style architecture and theatrical religious exhibits.', 'limited', null, 'https://www.orlando.gov/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('The House of the Seven Gables', 'the-house-of-the-seven-gables', 'weird-history', 42.52176, -70.88351, 'Salem', 'MA', 'This seventeenth-century mansion inspired Nathaniel Hawthorne''s 1851 novel and has accumulated centuries of architectural alterations, hidden spaces and family stories. The museum complex includes Hawthorne''s birthplace and guided access to the famously named house.', 'limited', null, 'https://7gables.org/', '2026-09-09T04:43:56.902716+00:00', null, 'https://7gables.org/', null, null, null, 'America/New_York'),
  ('The Kampong', 'the-kampong', 'weird-history', 25.71315, -80.25383, 'Miami', 'FL', 'Historic tropical estate of plant explorer David Fairchild with rare specimens and unusual botanical history.', 'limited', null, 'https://ntbg.org/gardens/the-kampong/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Leatherman Grave and Marker', 'the-leatherman-grave-and-marker', 'weird-history', 41.1369, -73.86219, 'Ossining', 'NY', 'The mysterious wanderer known as the Leatherman repeatedly walked a roughly 365-mile circuit through New York and Connecticut in the 1880s while wearing a handmade suit of heavy leather. He died in 1889 and is buried in Ossining, where a Legends & Lore marker records one of New York''s strangest real-life folk figures.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/the-leatherman/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Legacy Museum', 'the-legacy-museum', 'weird-history', 32.38248, -86.30833, 'Montgomery', 'AL', 'Equal Justice Initiative’s museum examines enslavement, racial terror lynching, segregation and mass incarceration through documents, artifacts, art and immersive interpretation. It connects multiple periods of American racial injustice within a single museum experience.', 'open', null, 'https://museumandmemorial.eji.org/museum', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Lost Town of Proctor', 'the-lost-town-of-proctor', 'weird-history', 35.4733, -83.7264, 'Bryson City', 'NC', 'The remains of Proctor sit in one of the more isolated sections of Great Smoky Mountains National Park. Once a logging and settlement community, the town declined after the creation of the park and the construction of Fontana Dam; scattered foundations and remnants now require a substantial backcountry journey to reach.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/north-carolina/history', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Parker Brothers'' Grave', 'the-parker-brothers-grave', 'weird-history', 42.52433, -70.91135, 'Salem', 'MA', 'Game-company founders George, Charles and Edward Parker are buried in Salem, linking the city to the company behind generations of American board games. Parker Brothers later published titles ranging from Monopoly and Clue to the Ouija talking board, giving the family plot an appropriately game-filled legacy.', 'limited', null, 'https://www.atlasobscura.com/places/the-grave-of-the-parker-brothers', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Peaslee Sphinx', 'the-peaslee-sphinx', 'weird-history', 38.24493, -85.71648, 'Louisville', 'KY', 'Installed in 1907, this 14-foot granite sphinx guards the Peaslee family plot in Cave Hill Cemetery. Its Egyptian styling was unusually exotic for Kentucky cemetery art at the time and remains one of the cemetery''s most conspicuous monuments.', 'open', null, 'https://www.roadsideamerica.com/story/63563', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('The Road to Nowhere', 'the-road-to-nowhere', 'weird-history', 35.45906, -83.53803, 'Bryson City', 'NC', 'A mountain road built after the creation of Great Smoky Mountains National Park ends abruptly at a long tunnel through the mountain. Construction was abandoned before the promised route was completed, leaving a paved road and dark pedestrian-access tunnel that literally lead nowhere.', 'open', null, 'https://www.nps.gov/grsm/learn/historyculture/north-shore-road.htm', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Spot Where World War I Ended', 'the-spot-where-world-war-i-ended', 'weird-history', 40.57698, -74.63143, 'Bridgewater Township', 'NJ', 'A small plaque marks the location where a local false report of the armistice triggered an early celebration on November 7, 1918, four days before the actual end of fighting. The episode became one of the strangest American footnotes to the close of World War I.', 'roadside', null, 'https://www.roadsideamerica.com/tip/12535', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Spruces', 'the-spruces', 'weird-history', 42.70238, -73.17832, 'Williamstown', 'MA', 'A former mobile-home community devastated by flooding was cleared and transformed into a public park. Roads, plantings and other subtle traces of the vanished neighborhood remain, giving the open landscape the feel of a community erased without being completely forgotten.', 'open', null, 'https://www.atlasobscura.com/places/the-spruces', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Witch House', 'the-witch-house', 'weird-history', 42.52155, -70.8989, 'Salem', 'MA', 'The seventeenth-century home of Judge Jonathan Corwin is the only surviving building in Salem with direct ties to the 1692 witch trials. Corwin participated in the proceedings, and the preserved house now interprets the trials, colonial life and the beliefs that helped fuel the panic.', 'limited', null, 'https://www.atlasobscura.com/places/the-witch-house', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.thewitchhouse.org/', null, null, null, 'America/New_York'),
  ('Theater of the Sea', 'theater-of-the-sea', 'weird-history', 24.94304, -80.60883, 'Islamorada', 'FL', 'Old Florida marine attraction built into former railroad quarries.', 'limited', null, 'https://theaterofthesea.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Theodore Roosevelt''s ''McKinley Shot'' Marker', 'theodore-roosevelts-mckinley-shot-marker', 'weird-history', 44.84677, -73.36417, 'Isle La Motte', 'VT', 'A marker identifies the Fisk home where Vice President Theodore Roosevelt was visiting when word arrived that President William McKinley had been shot in 1901. Roosevelt soon left Vermont as the national crisis deepened, eventually becoming president after McKinley''s death.', 'open', null, 'https://oakcrestheritage.com/markers/vermont/grand-isle-county/theodore-roosevelt-s-visit-to-isle-la-motte', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thomas Bullitt''s Lone Grave', 'thomas-bullitts-lone-grave', 'weird-history', 38.33835, -81.62033, 'Charleston', 'WV', 'A single 18th-century grave sits by itself inside a modern Charleston park, the burial place of colonial-era surveyor and soldier Thomas Bullitt. The isolated stone is an unusual survival from a much earlier landscape and can be visited from the park during public hours.', 'open', null, 'https://www.atlasobscura.com/places/the-grave-of-thomas-bullitt', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thomas Hill Standpipe', 'thomas-hill-standpipe', 'weird-history', 44.80741, -68.7825, 'Bangor', 'ME', 'Built in 1897, this enormous wooden water tank is enclosed by a shingled structure that looks more like an oversized lighthouse than municipal infrastructure. Its exterior is easy to see, while interior access is limited to occasional public open houses.', 'limited', null, 'https://fotospot.com/attractions/maine/thomas-hill-standpipe', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Three Stooges Tombstone', 'three-stooges-tombstone', 'weird-history', 40.53669, -74.36175, 'Metuchen', 'NJ', 'Firefighter James Bechtold''s gravestone features Moe, Larry and Curly looking down from the stone above the message ''Laugh, Don''t Weep — It Feels Better!'' The personalized memorial stands in Hillside Cemetery and should be visited respectfully during cemetery hours.', 'limited', null, 'https://www.roadsideamerica.com/tip/33275', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thurmond Historic District', 'thurmond-historic-district', 'weird-history', 37.95712, -81.07879, 'Thurmond', 'WV', 'Once one of the busiest railroad towns in the New River Gorge, Thurmond declined until its preserved commercial district became an almost ghost-town-like National Park Service site. Visitors can walk past the old bank, hotel buildings and rail structures, while the restored depot operates seasonally as a visitor center.', 'open', null, 'https://www.nps.gov/neri/learn/historyculture/thurmond.htm', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Timothy Demonbreun''s Cave', 'timothy-demonbreuns-cave', 'weird-history', 36.1608, -86.7089, 'Nashville', 'TN', 'A cave along the Cumberland River is traditionally associated with early settler Timothy Demonbreun, who used the river corridor during Nashville''s frontier period. Access around the bluff and riverbank can be constrained, so visitors should remain in designated public areas.', 'limited', null, 'https://www.atlasobscura.com/places/timothy-demonbreuns-cave', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tina Turner Museum at Flagg Grove School', 'tina-turner-museum-at-flagg-grove-school', 'weird-history', 35.54108, -89.24605, 'Brownsville', 'TN', 'The one-room schoolhouse Tina Turner attended was moved and restored as a museum devoted to her life and career. Costumes, memorabilia and the tiny rural classroom connect an international superstar to her West Tennessee beginnings.', 'open', null, 'https://westtnheritage.com/tina-turner-museum/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tippecanoe Battlefield Monument and Museum', 'tippecanoe-battlefield-monument-and-museum', 'weird-history', 40.5069, -86.8438, 'Battle Ground', 'IN', 'An 85-foot marble monument marks the landscape of the November 1811 Battle of Tippecanoe, fought between William Henry Harrison''s forces and warriors associated with Tecumseh''s Native confederacy. The adjacent museum provides context for the battle and the broader Indigenous resistance to U.S. expansion rather than reducing the location to battlefield folklore.', 'open', null, 'https://tippecanoehistory.org/our-places/tippecanoe-battlefield-museum/', '2026-09-08T13:53:25.695107+00:00', null, 'https://tippecanoehistory.org/our-places/tippecanoe-battlefield-museum/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Tipton-Haynes State Historic Site', 'tipton-haynes-state-historic-site', 'weird-history', 36.29361, -82.335, 'Johnson City', 'TN', 'The Tipton-Haynes property preserves an eighteenth-century house, outbuildings, a spring and layers of Tennessee political and frontier history. Guided access and seasonal hours make it a check-ahead stop rather than an unrestricted historic landscape.', 'limited', null, 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites/tipton-haynes.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tolomato Cemetery', 'tolomato-cemetery', 'weird-history', 29.89835, -81.31506, 'St. Augustine', 'FL', 'One of Florida''s oldest European cemeteries, with colonial graves and persistent ghost stories.', 'open', null, 'https://www.tolomatocemetery.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tombstone House', 'tombstone-house', 'weird-history', 37.20209, -77.42703, 'Petersburg', 'VA', 'Oswald Young built this house in 1934 using pieces of thousands of discarded government headstones that had once marked Union graves at nearby Poplar Grove National Cemetery. The strange stone residence still survives on Youngs Road, but it is private property and should be viewed only from the public roadway.', 'private', null, 'https://www.atlasobscura.com/places/the-tombstone-house', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tombstone in the Middle of a Cotton Field', 'tombstone-in-the-middle-of-a-cotton-field', 'weird-history', 35.2117, -78.3473, 'Newton Grove', 'NC', 'A solitary grave marker for Adolphus Rob Lee stands isolated in an agricultural field rather than within a conventional cemetery. It is best viewed respectfully from legitimate roadside access without entering planted private land.', 'roadside', null, 'https://www.roadsideamerica.com/tip/21918', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tory’s Den Cave', 'torys-den-cave', 'weird-history', 36.4019, -80.2995, 'Westfield', 'NC', 'A short trail in Hanging Rock State Park leads to a cool natural cave about twenty feet deep that is linked with Revolutionary War-era Tory history. The same access also reaches Tory’s Falls; this coordinate intentionally pins the official Tory’s Den parking area rather than an unreliable point in the woods. Access: https://www.ncparks.gov/park-features/hanging-rock-state-park-torys-den-parking-area', 'limited', null, 'https://www.ncparks.gov/state-parks/hanging-rock-state-park/trails', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Traffic Control Tower', 'traffic-control-tower', 'weird-history', 41.53769, -72.80267, 'Meriden', 'CT', 'This tiny 1925 tower once held a police officer who manually controlled traffic lights at a busy Meriden intersection. Restored as a monument, it preserves an odd transitional stage between hand signals and automated traffic systems.', 'roadside', null, 'https://www.atlasobscura.com/places/traffic-control-tower', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Transcontinental Airway Arrow', 'transcontinental-airway-arrow', 'weird-history', 41.43967, -72.99229, 'Bethany', 'CT', 'A huge concrete arrow survives from the era when pilots navigated early U.S. airmail routes by following giant ground markers and beacon towers. The preserved arrow sits at the historic Bethany Airport site and is one of the clearest remnants of pre-radio air navigation in the state.', 'open', null, 'https://www.roadsideamerica.com/tip/89842', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Transpeninsular Line Marker', 'transpeninsular-line-marker', 'weird-history', 38.45125, -75.05478, 'Fenwick Island', 'DE', 'An eighteenth-century boundary marker records the survey line drawn across the Delmarva Peninsula before the better-known Mason-Dixon survey. It is a small stone remnant of the complicated colonial boundary dispute that shaped Delaware and Maryland.', 'roadside', null, 'https://archives.delaware.gov/delaware-historical-markers/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Traverse Colantha Walker''s Grave', 'traverse-colantha-walkers-grave', 'weird-history', 44.7482, -85.6476, 'Traverse City', 'MI', 'Traverse Colantha Walker was a prize Holstein associated with the former Northern Michigan Asylum farm and became famous for extraordinary milk production. Her stone grave marker survives on the grounds of Historic Barns Park, preserving one of Traverse City''s stranger pieces of agricultural history.', 'open', null, 'https://www.roadsideamerica.com/tip/2850', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Tu-Endie-Wei State Park and Battle Monument', 'tu-endie-wei-state-park-and-battle-monument', 'weird-history', 38.83919, -82.14081, 'Point Pleasant', 'WV', 'At the confluence of the Ohio and Kanawha rivers, this small state park preserves the site and memory of the 1774 Battle of Point Pleasant. Visitors find an imposing granite monument, historical markers and the seasonal Mansion House museum, all just a short distance from Point Pleasant''s Mothman attractions.', 'open', null, 'https://wvstateparks.com/parks/tu-endie-wei-state-park/park-history/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tupelo Hardware Company — Elvis''s First Guitar Site', 'tupelo-hardware-company-elviss-first-guitar-site', 'weird-history', 34.25752, -88.70353, 'Tupelo', 'MS', 'The still-operating hardware store where Elvis Presley''s mother bought him his first guitar after he reportedly asked for a rifle. Visitors can stand at the marked location inside the store where the purchase story is interpreted.', 'open', null, 'https://www.tupelo.net/directory/tupelo-hardware-company/', '2026-09-09T12:59:48.572362+00:00', null, 'https://tupelohardware.com/', null, null, null, 'America/Chicago'),
  ('Tupelo National Battlefield', 'tupelo-national-battlefield', 'weird-history', 34.25558, -88.73709, 'Tupelo', 'MS', 'A one-acre National Park Service site marking the July 1864 Battle of Tupelo, where Union forces sought to protect critical railroad supply lines. The compact monument is easy to route and serves as a physical stop for a battle whose wider landscape has largely been absorbed by modern Tupelo. Coordinate source: https://www.recreation.gov/gateways/2959', 'open', null, 'https://www.nps.gov/tupe/index.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Turtle Mound', 'turtle-mound', 'weird-history', 28.92952, -80.82511, 'New Smyrna Beach', 'FL', 'Massive ancient shell midden visible from the road at Canaveral National Seashore.', 'open', null, 'https://www.nps.gov/cana/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Turtle Submarine Replica', 'turtle-submarine-replica', 'weird-history', 41.35133, -72.38645, 'Essex', 'CT', 'The Connecticut River Museum displays a full-size working reconstruction of the Turtle, the tiny one-man submersible built during the American Revolution for an attempted underwater attack on British warships. Its cramped wooden design looks more like a barrel than a modern submarine.', 'open', null, 'https://www.atlasobscura.com/places/turtle-submarine-at-connecticut-river-museum', '2026-09-08T18:47:23.721893+00:00', null, 'https://ctrivermuseum.org/turtle-submarine/', null, null, null, 'America/New_York'),
  ('Tuskegee Airmen Monument', 'tuskegee-airmen-monument', 'weird-history', 32.91635, -80.63761, 'Walterboro', 'SC', 'A memorial at the former Walterboro Army Airfield honors the Tuskegee Airmen who trained here during World War II. The site preserves the connection between this quiet Lowcountry airfield and the pioneering Black pilots whose service helped challenge segregation in the U.S. military.', 'open', null, 'https://www.scpictureproject.org/colleton-county/tuskegee-airmen-monument.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tuskegee Airmen National Historic Site', 'tuskegee-airmen-national-historic-site', 'weird-history', 32.45539, -85.67983, 'Tuskegee', 'AL', 'Moton Field preserves hangars, exhibits and the training landscape of the Tuskegee Airmen, the pioneering Black military aviators and support personnel of World War II. The National Park Service site occupies the actual airfield where much of the training took place.', 'open', null, 'https://www.nps.gov/tuai/index.htm', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tuskegee History Center', 'tuskegee-history-center', 'weird-history', 32.42296, -85.6915, 'Tuskegee', 'AL', 'The center interprets Macon County’s Native American, European American and African American histories, including civil-rights struggles and the U.S. Public Health Service syphilis study. Exhibits emphasize the people affected by these events rather than treating them as abstract history.', 'limited', null, 'https://tuskegeecenter.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ultimate Frisbee Monument', 'ultimate-frisbee-monument', 'weird-history', 40.73151, -74.2769, 'Maplewood', 'NJ', 'A disc-shaped plaque mounted on a rock marks the parking lot where Columbia High School students developed the game that became Ultimate Frisbee in 1968. The small monument sits beside West Parker Avenue near the original playing area.', 'roadside', null, 'https://www.roadsideamerica.com/story/62666', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Uncle Sam House', 'uncle-sam-house', 'weird-history', 42.72814, -71.76323, 'Mason', 'NH', 'Samuel Wilson, the meatpacker traditionally associated with the American "Uncle Sam" nickname, spent part of his early life in this Mason house. The exact development of the national symbol is more complicated than the popular legend suggests, but Wilson''s connection has been officially commemorated. The house is private property, so view the marker and exterior only from a lawful public area.', 'private', null, 'https://www.atlasobscura.com/places/the-uncle-sam-house-mason-new-hampshire', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Uncle Sam Plaza', 'uncle-sam-plaza', 'weird-history', 42.41584, -71.1532, 'Arlington', 'MA', 'A bronze statue honors Arlington-born Samuel Wilson, the meatpacker traditionally associated with the origin of the national personification ''Uncle Sam.'' Whether the familiar story is completely accurate is debated, but Arlington has firmly embraced the connection with this dedicated plaza.', 'open', null, 'https://www.atlasobscura.com/places/uncle-sam-plaza', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Union Miners Cemetery / Mother Jones Monument', 'union-miners-cemetery-mother-jones-monument', 'weird-history', 39.08069, -89.73336, 'Mount Olive', 'IL', 'Mother Jones chose burial among union miners here, where a large monument and graves connect directly to Illinois'' violent labor struggles.', 'open', null, 'https://www.motherjonesmuseum.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Unitarian Church Cemetery', 'unitarian-church-cemetery', 'weird-history', 32.77857, -79.93444, 'Charleston', 'SC', 'Dense vegetation, leaning stones, elaborate monuments, and deliberately overgrown paths give this historic churchyard a distinctive appearance. Charleston folklore connects the cemetery with ghost stories, including traditions surrounding the mysterious “Lady in White.”', 'limited', null, 'https://www.atlasobscura.com/places/unitarian-church-cemetery', '2026-09-09T05:53:13.784429+00:00', null, 'https://charlestonuu.org/cemetery/', null, null, null, 'America/New_York'),
  ('United States Army Aviation Museum', 'united-states-army-aviation-museum', 'weird-history', 31.32419, -85.71311, 'Fort Novosel', 'AL', 'Helicopters, fixed-wing aircraft and experimental machines document U.S. Army aviation from its earliest years through modern rotary-wing operations. The museum is on an active military installation, so visitors must comply with current gate, identification and security requirements.', 'limited', null, 'https://www.armyaviationmuseum.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('United States War Dogs Memorial', 'united-states-war-dogs-memorial', 'weird-history', 40.38928, -74.17565, 'Holmdel Township', 'NJ', 'A bronze soldier and military dog stand together in a memorial dedicated to American war dogs and their handlers. The sculpture sits near the New Jersey Vietnam Veterans'' Memorial and honors animal teams used across multiple conflicts.', 'open', null, 'https://www.hmdb.org/m.asp?m=209032', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Upper Big Branch Miners Memorial', 'upper-big-branch-miners-memorial', 'weird-history', 37.97968, -81.53437, 'Whitesville', 'WV', 'This public memorial honors the 29 miners killed in the Upper Big Branch Mine disaster on April 5, 2010. Dedicated in 2012, its long granite wall includes life-size silhouettes and the names of the victims, with parking and year-round public access.', 'open', null, 'https://www.ubbminersmemorial.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Urca de Lima Underwater Archaeological Preserve', 'urca-de-lima-underwater-archaeological-preserve', 'weird-history', 27.50528, -80.29917, 'Fort Pierce', 'FL', '1715 Spanish treasure-fleet storeship and Florida''s first designated underwater archaeological preserve.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/urca-de-lima/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('U.S. Army Parachute Test Platoon Monument', 'us-army-parachute-test-platoon-monument', 'weird-history', 40.25879, -74.54065, 'East Windsor Township', 'NJ', 'A small monument along Route 130 marks the former site of tall wooden parachute-training towers used by the Army''s experimental parachute test platoon in 1940. The towers disappeared long ago, but the marker preserves an obscure location from the birth of American airborne forces.', 'roadside', null, 'https://www.roadsideamerica.com/tip/41908', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('U.S. Space & Rocket Center', 'us-space-rocket-center', 'weird-history', 34.71139, -86.65417, 'Huntsville', 'AL', 'One of the largest spaceflight museums in the country preserves rockets, spacecraft, engines and artifacts connected to Huntsville’s role in the American space program. Its full-scale Saturn V and dense collection of hardware make it one of Alabama’s strongest science-history OddWay stops.', 'open', null, 'https://www.rocketcenter.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('U.S. Veterans Memorial Museum', 'us-veterans-memorial-museum', 'weird-history', 34.69063, -86.5858, 'Huntsville', 'AL', 'This volunteer-run museum displays military vehicles, uniforms, weapons and artifacts spanning conflicts from the Revolutionary era through the modern military. Its collection includes rare early military vehicles and unusual equipment not normally seen in general history museums.', 'limited', null, 'https://www.memorialmuseum.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('USS Alabama Battleship Memorial Park', 'uss-alabama-battleship-memorial-park', 'weird-history', 30.68399, -88.01555, 'Mobile', 'AL', 'Visitors can enter the World War II battleship USS Alabama, submarine USS Drum and extensive aircraft displays at this waterfront park. Tight compartments, gun turrets and preserved machinery turn the warships themselves into the museum.', 'open', null, 'https://www.ussalabama.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('USS KIDD Veterans Museum', 'uss-kidd-veterans-museum', 'weird-history', 30.44434, -91.1915, 'Baton Rouge', 'LA', 'The preserved Fletcher-class destroyer USS KIDD serves as a floating museum on the Mississippi River. Ship access depends on restoration status, river conditions and museum procedures, so check the current visitor notice before going.', 'limited', null, 'https://www.usskidd.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('USS Maine Bathtub', 'uss-maine-bathtub', 'weird-history', 41.0374, -83.6561, 'Findlay', 'OH', 'The Hancock Historical Museum preserves a bathtub recovered from the wreckage of the USS Maine, whose 1898 destruction in Havana Harbor helped push the United States toward the Spanish-American War. The oddly domestic survivor is displayed inside the museum and can be seen during regular public hours.', 'open', null, 'https://www.ohiomagazine.com/ohio-life/article/bathtub-from-the-uss-maine-findlay', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('USS Massachusetts Underwater Archaeological Preserve', 'uss-massachusetts-underwater-archaeological-preserve', 'weird-history', 30.29567, -87.31203, 'Pensacola', 'FL', 'The nation''s oldest surviving battleship rests beneath Pensacola Pass after being sunk for target practice in 1921.', 'limited', null, 'https://museumsinthesea.fpan.us/history/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('USS Narcissus Underwater Archaeological Preserve', 'uss-narcissus-underwater-archaeological-preserve', 'weird-history', 27.6258, -82.79968, 'Egmont Key', 'FL', 'Civil War Navy tug lost with all hands after its boiler exploded near Egmont Key in 1866.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/uss-narcissus/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('USS Shangri-La Propeller', 'uss-shangri-la-propeller', 'weird-history', 38.9887, -75.44655, 'Milford', 'DE', 'An enormous propeller from the aircraft carrier USS Shangri-La sits beside Bay Road as a piece of naval hardware turned roadside monument. The scale is difficult to appreciate until standing beside it.', 'roadside', null, 'https://www.roadsideamerica.com/story/19107', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vamar Underwater Archaeological Preserve', 'vamar-underwater-archaeological-preserve', 'weird-history', 29.89902, -85.46343, 'Port St. Joe', 'FL', 'Former Byrd Antarctic-expedition support vessel that later sank under mysterious wartime circumstances.', 'limited', null, 'https://museumsinthesea.fpan.us/preserves/vamar/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Van Hise Rock', 'van-hise-rock', 'weird-history', 43.48944, -89.91528, 'Rock Springs', 'WI', 'This roadside quartzite outcrop played an important role in geologist Charles Van Hise''s work interpreting folded and metamorphosed rock layers. A scientific landmark sits almost directly beside the highway, turning a rock face into a stop in the history of geology.', 'open', null, 'https://dnr.wisconsin.gov/topic/parks/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.wisconsinhistory.org/', null, null, null, 'America/Chicago'),
  ('Van Slyke Castle Ruins', 'van-slyke-castle-ruins', 'weird-history', 41.04486, -74.26278, 'Ringwood', 'NJ', 'Stone walls, foundations and a large swimming-pool ruin remain from a mansion that once stood high above the Wanaque Reservoir. Fire destroyed the house in the 1950s, and the legal public trail now leads hikers through the atmospheric remains.', 'open', null, 'https://www.atlasobscura.com/places/van-slyke-castle', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Venetian Pool', 'venetian-pool', 'weird-history', 25.7453, -80.27311, 'Coral Gables', 'FL', '1920s public pool carved from a coral-rock quarry with caves, bridges, and waterfalls.', 'limited', null, 'https://www.coralgables.com/venetianpool', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Venezia', 'venezia', 'weird-history', 34.393082, -112.416834, 'Mayer', 'AZ', 'A gold-mining and milling settlement on Senator Highway, named after Venice by the Italian settler F. Scopel in the early 1900s. It had a twenty-stamp mill, store, saloon, stage stop and post office. Today the rugged backroad passes collapsed structures and mining remnants.', 'limited', null, 'https://www.arizonahighways.com/archive/issues/chapter/Doc.705.Chapter.6', '2026-09-07T01:28:12.240723+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Vicksburg National Cemetery', 'vicksburg-national-cemetery', 'weird-history', 32.37517, -90.86775, 'Vicksburg', 'MS', 'A vast national cemetery containing the graves of more than 17,000 Union soldiers, many of them unidentified, along with later veterans. It is a powerful physical record of Civil War loss and should be visited as a cemetery and memorial.', 'open', null, 'https://www.nps.gov/vick/learn/historyculture/national-cemetery.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Vicksburg National Military Park — Visitor Center', 'vicksburg-national-military-park-visitor-center', 'weird-history', 32.36213, -90.8503, 'Vicksburg', 'MS', 'The main entry point to the vast battlefield landscape surrounding Vicksburg, with earthworks, monuments, artillery positions and preserved siege terrain. The park documents the 1863 campaign whose outcome helped give the Union control of the Mississippi River. Coordinate source: https://www.recreation.gov/gateways/2782', 'open', null, 'https://www.nps.gov/vick/index.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Villa Louis', 'villa-louis', 'weird-history', 43.05877, -91.15825, 'Prairie du Chien', 'WI', 'This Victorian estate stands on St. Feriole Island at a site tied to the Dousman family, the fur trade and the long cultural history of Prairie du Chien. Restored interiors and outbuildings preserve an unusually complete upper-class nineteenth-century estate on the Mississippi frontier.', 'limited', null, 'https://villalouis.wisconsinhistory.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://villalouis.wisconsinhistory.org/', null, null, null, 'America/Chicago'),
  ('Vivian''s Dollhouse Grave', 'vivians-dollhouse-grave', 'weird-history', 39.65025, -85.1383, 'Connersville', 'IN', 'Vivian May Allison died as a young child in 1899, and her family placed a fully furnished miniature house over her grave rather than a conventional monument. Community members have maintained the unusual memorial for generations; it was temporarily removed for restoration in 2025 before being scheduled to return to City Cemetery.', 'open', null, 'https://historicconnersville.org/cemeteteries', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Vizcaya Museum & Gardens', 'vizcaya-museum-gardens', 'weird-history', 25.74442, -80.21038, 'Miami', 'FL', 'Gilded-age estate packed with imported European fragments, hidden grotto-like spaces, and elaborate gardens.', 'limited', null, 'https://vizcaya.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Volcano Historic Boomtown Ruins', 'volcano-historic-boomtown-ruins', 'weird-history', 39.23138, -81.29039, 'Walker', 'WV', 'Volcano exploded into existence during the 1860s West Virginia oil boom and was largely destroyed by fire in 1879. Scattered industrial and community remains survive in the woods near Mountwood Park, but reaching them requires a moderately challenging hike rather than a roadside stop.', 'limited', null, 'https://www.atlasobscura.com/places/ghost-town-volcano-west-virginia', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vulture Mine Tours / Vulture City Ghost Town', 'vulture-mine-tours-vulture-city-ghost-town', 'weird-history', 33.816527, -112.828828, 'Wickenburg', 'AZ', 'Vulture City preserves the remains of the historic mining settlement that grew around Arizona''s Vulture Mine, with restored buildings, mining equipment and artifacts spread across the property. Visitors can explore on self-guided or scheduled history tours, with occasional paranormal and special-event programming.', 'open', null, 'https://vulturecityghosttown.com/', '2026-09-05T22:12:28.444612+00:00', null, 'https://www.vultureminetours.com/', '+1-877-425-9229', 'node', 3274100436, 'America/Phoenix'),
  ('Wahbememe Burial Site and Monument', 'wahbememe-burial-site-and-monument', 'weird-history', 41.79782, -85.66268, 'White Pigeon', 'MI', 'A roadside monument and burial site honors Potawatomi leader Wahbememe, or White Pigeon, for whom the community is named. A dramatic local story claims he ran roughly 150 miles to warn settlers of an attack, although later historical research casts doubt on that version of events.', 'open', null, 'https://www.atlasobscura.com/places/chief-wahbememe-white-pigeon-memorial', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Waldameer Pirates Cove', 'waldameer-pirates-cove', 'weird-history', 42.1083, -80.1581, 'Erie', 'PA', 'Bill Tracy created this walk-through pirate funhouse for Waldameer in 1972, combining tilted rooms, blacklight figures, optical illusions and deliberately disorienting passages. It remains an operating piece of vintage amusement architecture inside the seasonal park rather than a modern haunted-house attraction.', 'limited', null, 'https://www.weirderie.com/pirates-cove', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Waldameer Whacky Shack', 'waldameer-whacky-shack', 'weird-history', 42.10864, -80.15767, 'Erie', 'PA', 'Dark-ride designer Bill Tracy built Waldameer''s Whacky Shack in 1970, filling the tracked ride with blacklight monsters, optical gags and old-school funhouse effects. It is still operating at Waldameer and is a rare surviving example of Tracy''s once-widespread amusement-park work, but it is available only when the seasonal park is operating.', 'limited', null, 'https://www.weirderie.com/the-wacky-shack', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wallace Horse Cemetery', 'wallace-horse-cemetery', 'weird-history', 44.29677, -71.77234, 'Littleton', 'NH', 'This tiny fenced cemetery is dedicated to three Morgan horses, Maud, Mollie and Maggie, that belonged to Eli and Myra Wallace. The horses were buried with equipment including harnesses, bridles, blankets and feed boxes, and Wallace''s estate provided for the site''s continued care. It is one of New England''s most unusual purpose-built animal cemeteries. Secondary source: https://www.visitwhitemountains.com/blog/post/scary-tales-of-the-white-mountains/', 'open', null, 'https://www.roadsideamerica.com/tip/31777', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Walnut Street Bridge', 'walnut-street-bridge', 'weird-history', 35.0583, -85.3073, 'Chattanooga', 'TN', 'This long nineteenth-century truss bridge survived demolition and was converted into a pedestrian crossing over the Tennessee River. Its huge steel framework and adaptive reuse make it a walkable remnant of Chattanooga''s industrial-era transportation system.', 'open', null, 'https://www.atlasobscura.com/places/walnut-street-bridge', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('War Correspondents Memorial Arch', 'war-correspondents-memorial-arch', 'weird-history', 39.40571, -77.63931, 'Jefferson', 'MD', 'Journalist George Alfred Townsend erected this unusual stone arch in 1896 as a memorial to journalists and artists who covered wars. The roughly 50-foot monument now stands in Gathland State Park beside the Appalachian Trail and can be visited from the park''s public grounds.', 'open', null, 'https://www.atlasobscura.com/places/war-correspondents-memorial', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Waterloo Village', 'waterloo-village', 'weird-history', 40.91556, -74.75611, 'Byram Township', 'NJ', 'This preserved canal village grew beside the Morris Canal and contains historic homes, shops, a mill and other nineteenth-century structures. The grounds are open from dawn to dusk, while interior tours and interpretive buildings follow a more limited seasonal schedule.', 'open', null, 'https://dep.nj.gov/parksandforests/state-park/waterloo-village/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Waters Mill Ruins', 'waters-mill-ruins', 'weird-history', 39.19995, -77.28416, 'Germantown', 'MD', 'The remains of an early-19th-century saw and grist mill sit near Little Seneca Creek along the Black Hill trail system. The site is made darker by the 1920 dynamiting of the nearby miller''s house, an attack that killed three people and eventually led to the execution of Guy Thompson.', 'limited', null, 'https://www.atlasobscura.com/places/waters-mill-ruins', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Waveland''s Ground Zero Hurricane Museum', 'wavelands-ground-zero-hurricane-museum', 'weird-history', 30.2863, -89.37438, 'Waveland', 'MS', 'A museum in one of the Mississippi communities hit hardest by Hurricane Katrina, preserving photographs, personal accounts, artifacts and recovery stories. Its hurricane simulator and Katrina recovery collections make it both memorial and disaster-history museum.', 'open', null, 'https://www.wavelandgroundzero.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('W.C. Handy Home and Museum', 'wc-handy-home-and-museum', 'weird-history', 35.13972, -90.04956, 'Memphis', 'TN', 'The modest house associated with composer W.C. Handy, often called the Father of the Blues, was moved to Beale Street and preserved as a small museum. Its scale provides a sharp contrast with the enormous cultural influence of the music created around it.', 'limited', null, 'https://www.memphistravel.com/arts-culture/wc-handy-home-museum', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Weeden House Museum and Garden', 'weeden-house-museum-and-garden', 'weird-history', 34.72896, -86.58369, 'Huntsville', 'AL', 'This early nineteenth-century home survived Huntsville’s transformation and later became associated with artist and poet Maria Howard Weeden. Guided access preserves both the architecture and the complicated history of the people who lived and worked there.', 'limited', null, 'https://weedenhousemuseum.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Weedon Island Preserve Cultural and Natural History Center', 'weedon-island-preserve-cultural-and-natural-history-center', 'weird-history', 27.85038, -82.60583, 'St. Petersburg', 'FL', 'Interpretive center for a major Indigenous archaeological landscape and famous ancient canoe discovery.', 'open', null, 'https://pinellas.gov/parks/weedon-island-preserve/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Weehawken Dueling Grounds', 'weehawken-dueling-grounds', 'weird-history', 40.7708, -74.0168, 'Weehawken', 'NJ', 'A monument and stone mark the Palisades area associated with the 1804 duel in which Aaron Burr mortally wounded Alexander Hamilton. The exact historical firing spot is debated, but the public memorial preserves the location traditionally connected with the famous encounter.', 'open', null, 'https://www.atlasobscura.com/places/weehawken-dueling-grounds', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('West Baden Springs Hotel', 'west-baden-springs-hotel', 'weird-history', 38.56722, -86.61806, 'West Baden Springs', 'IN', 'When the present hotel opened in 1902, its enormous free-spanning atrium dome was considered an engineering marvel and was promoted as the "Eighth Wonder of the World." The restored building is again an operating hotel, but public areas and scheduled tours allow travelers to see the surreal circular interior legally.', 'limited', null, 'https://www.asce.org/about-civil-engineering/history-and-heritage/historic-landmarks/west-baden-springs-hotel/', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.frenchlick.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Westford Knight', 'westford-knight', 'weird-history', 42.5874, -71.43437, 'Westford', 'MA', 'Marks on a roadside rock have been promoted as the carved image of a medieval Scottish knight and evidence of a pre-Columbian Templar expedition to New England. Most researchers favor natural weathering and later human markings, but a plaque and knight statue ensure the disputed theory remains physically memorialized.', 'open', null, 'https://www.atlasobscura.com/places/westford-knight', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Whipple Company Store', 'whipple-company-store', 'weird-history', 37.95882, -81.1656, 'Whipple', 'WV', 'Built in the 1890s, this unusual coal-company store once served the surrounding mining community and later operated as a museum interpreting company-town life. The museum closed and the building was sold to a private owner in 2018, so OddWay travelers should only view the exterior from the public road unless a new authorized access program is announced.', 'private', null, 'https://www.hmdb.org/m.asp?m=140168', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('White Cliffs of Conoy', 'white-cliffs-of-conoy', 'weird-history', 40.07237, -76.65304, 'Conoy Township', 'PA', 'These stark white cliffs above the Susquehanna are not natural limestone bluffs but piles of industrial waste left by a nineteenth- and twentieth-century quarry operation. They are reached by walking or cycling the Northwest Lancaster County River Trail, with additional ruins from the former company town of Billmyer nearby.', 'limited', null, 'https://www.discovermariettapa.org/business-directory/white-cliffs-of-conoy', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Whitesbog Historic Village', 'whitesbog-historic-village', 'weird-history', 39.95945, -74.50956, 'Pemberton Township', 'NJ', 'This preserved company village grew around cranberry farming and became the site where Elizabeth White and Frederick Coville developed the first cultivated highbush blueberries in the early twentieth century. Historic buildings, bogs and trails remain across the publicly accessible property.', 'open', null, 'https://whitesbog.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Whitney Plantation', 'whitney-plantation', 'weird-history', 30.03994, -90.64908, 'Wallace', 'LA', 'Whitney Plantation is operated as a museum centered on the history and experiences of enslaved people rather than plantation nostalgia. Memorials, restored buildings and first-person historical evidence make it one of Louisiana''s most important difficult-history stops.', 'limited', null, 'https://www.whitneyplantation.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Widow Jane Mine', 'widow-jane-mine', 'weird-history', 41.84284, -74.09827, 'Rosendale', 'NY', 'This enormous former cement mine is part of the Snyder Estate, where Rosendale cement was once quarried for major American construction projects. The cavernous mine now hosts concerts and special events, so interior access is limited to scheduled programs rather than unrestricted exploration.', 'limited', null, 'https://www.centuryhouse.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Willey House Historic Site', 'willey-house-historic-site', 'weird-history', 44.16646, -71.38563, 'Hart''s Location', 'NH', 'The Willey family lived beneath the steep walls of Crawford Notch when a catastrophic landslide struck in August 1826. Their house was miraculously spared by the debris, but the entire family and two hired men died after apparently fleeing it. The tragedy became one of the White Mountains'' most famous nineteenth-century disaster stories. Secondary source: https://www.topozone.com/new-hampshire/carroll-nh/locale/willey-house/', 'limited', null, 'https://www.nhstateparks.org/find-parks-trails/crawford-notch-state-park', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('William G. Bruce''s Granite Dog Grave', 'william-g-bruces-granite-dog-grave', 'weird-history', 42.89453, -71.67424, 'Mont Vernon', 'NH', 'William G. Bruce died in a hunting accident, and his grave was given an unusually elaborate memorial featuring a life-size granite hunting dog. The animal appears to stand guard beside the marker long after Bruce''s death. Visit respectfully and only during permitted cemetery access.', 'limited', null, 'https://www.atlasobscura.com/places/william-g-bruce-grave', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('William Goebel Assassination Site', 'william-goebel-assassination-site', 'weird-history', 38.19853, -84.87788, 'Frankfort', 'KY', 'William Goebel was shot outside Kentucky''s Old State Capitol on January 30, 1900 during a bitterly disputed gubernatorial election. He was sworn in as governor while dying and died days later, becoming the only U.S. state governor assassinated while in office; a marker identifies the attack site.', 'open', null, 'https://www.atlasobscura.com/places/site-william-goebel-assassination', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('William McKinley Coffee Break Monument', 'william-mckinley-coffee-break-monument', 'weird-history', 39.75102, -75.54791, 'Wilmington', 'DE', 'A monument in Brandywine Park remembers teenage William McKinley serving coffee to Union soldiers under fire during the Battle of Antietam. It is an unusually specific presidential memorial — less about office and more about a battlefield coffee run.', 'open', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Windover Archaeological Site Marker', 'windover-archaeological-site-marker', 'weird-history', 28.59832, -80.80732, 'Titusville', 'FL', 'Nearby marker and interpretive context for the famous 7,000-year-old Windover bog-burial discovery.', 'roadside', null, 'https://dos.fl.gov/historical/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Windsor Mounds', 'windsor-mounds', 'weird-history', 31.94599, -91.1265, 'Port Gibson', 'MS', 'Four prehistoric mounds sit roughly half a mile north of the better-known Windsor Ruins, showing that this landscape was significant long before the plantation era. At least one mound is visible from the public road; do not enter private land.', 'roadside', null, 'https://trails.mdah.ms.gov/windsor', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Windsor Ruins', 'windsor-ruins', 'weird-history', 31.94071, -91.12928, 'Port Gibson', 'MS', 'Twenty-three enormous Corinthian columns are nearly all that remain of Windsor, an antebellum mansion destroyed by fire in 1890. The freestanding columns look more like an abandoned classical temple than a former Mississippi house and are one of the state''s strongest ruin stops.', 'open', null, 'https://visitmississippi.org/things-to-do/architecture/windsor-ruins/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Winterville Mounds', 'winterville-mounds', 'weird-history', 33.48635, -91.064, 'Greenville', 'MS', 'A major Mississippian ceremonial center with a museum and a group of large platform mounds, including one of the tallest in the region. It is a public MDAH site and one of Mississippi''s strongest archaeological road-trip stops.', 'open', null, 'https://trails.mdah.ms.gov/winterville', '2026-09-09T12:59:48.572362+00:00', null, 'https://www.mdah.ms.gov/explore-mississippi/winterville-mounds', null, null, null, 'America/Chicago'),
  ('Withers Collection Museum & Gallery', 'withers-collection-museum-gallery', 'weird-history', 35.13938, -90.05035, 'Memphis', 'TN', 'Photographer Ernest Withers documented the civil-rights movement, Memphis music and Black life across the twentieth-century South. The Beale Street gallery presents that immense visual record while also confronting the complicated later revelations about Withers''s FBI relationship.', 'open', null, 'https://thewitherscollection.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wood County Museum', 'wood-county-museum', 'weird-history', 41.35028, -83.61586, 'Bowling Green', 'OH', 'The Wood County Museum occupies the county''s former nineteenth-century infirmary and poor farm complex. Visitors can explore exhibits on the people who lived and died there along with the grounds, paupers cemetery, former Lunatic Asylum site and Pestilence House, making it far stranger than a typical county history museum.', 'open', null, 'https://woodcountyhistory.org/visit/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Woodrow Wilson''s Canoe', 'woodrow-wilsons-canoe', 'weird-history', 41.32574, -72.32694, 'Old Lyme', 'CT', 'The Florence Griswold Museum preserves a canoe used by Woodrow Wilson during visits to the Lyme Art Colony before his presidency. The ordinary-looking boat is an unusually personal artifact tucked into a museum better known for American Impressionism.', 'open', null, 'https://www.roadsideamerica.com/tip/67054', '2026-09-08T19:51:22.001704+00:00', null, 'https://florencegriswoldmuseum.org/', null, null, null, 'America/New_York'),
  ('Wooldridge Monuments', 'wooldridge-monuments', 'weird-history', 36.74948, -88.63653, 'Mayfield', 'KY', 'Colonel Henry Wooldridge commissioned a crowded cemetery tableau of 18 life-size statues depicting himself, relatives, dogs, a horse, a deer and a fox. Often called "the strange procession which never moves," the restored group fills his plot in Maplewood Cemetery.', 'open', null, 'https://www.roadsideamerica.com/story/2504', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Woolsey Memorial Airport', 'woolsey-memorial-airport', 'weird-history', 45.16435, -85.57548, 'Northport', 'MI', 'This public grass-strip airport commemorates Army aviator Clinton F. Woolsey, who died during the 1927 Pan-American Goodwill Flight. Its rustic stone terminal and open field make the site look more like an early aviation outpost than a modern airport; winter operations are restricted and visitors should stay clear of active runways.', 'limited', null, 'https://www.atlasobscura.com/places/woolsey-memorial-airport', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('World War II Bunker at Cape May Point', 'world-war-ii-bunker-at-cape-may-point', 'weird-history', 38.93284, -74.96077, 'Lower Township', 'NJ', 'A huge concrete coastal-defense bunker sits directly on the beach, where shoreline erosion gradually moved it from its original inland position toward the surf. Built during World War II, the structure is now one of Cape May Point''s most conspicuous military ruins.', 'open', null, 'https://www.atlasobscura.com/places/cape-may-bunker', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('World War II Lookout Tower', 'world-war-ii-lookout-tower', 'weird-history', 38.94343, -74.96699, 'Lower Township', 'NJ', 'Fire Control Tower No. 23 was part of the coastal-defense system protecting the Delaware Bay during World War II. The restored concrete tower now contains interpretive exhibits and can be climbed during seasonal public hours for views across Cape May''s shoreline.', 'limited', null, 'https://www.capemaymac.org/experience/world-war-ii-tower/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('World War II V-1 Buzz Bomb', 'world-war-ii-v-1-buzz-bomb', 'weird-history', 39.64402, -86.86519, 'Greencastle', 'IN', 'A captured German V-1 flying bomb is mounted outdoors on a distinctive V-shaped memorial near the Putnam County Courthouse. The weapon, infamous for its use against European cities during World War II, now forms part of a memorial to local servicemembers who died in the war.', 'open', null, 'https://www.coveredbridgecountry.com/attractions/wwii-buzzbomb', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('World''s Only Pulpwood Stacker', 'worlds-only-pulpwood-stacker', 'weird-history', 45.16614, -91.15512, 'Cornell', 'WI', 'A preserved mechanical pulpwood stacker rises over Mill Yard Park, once used to pile enormous quantities of cut timber for the paper industry. Its skeletal machinery makes it look like industrial sculpture while preserving a highly specific piece of Wisconsin logging technology.', 'open', null, 'https://www.roadsideamerica.com/tip/1428', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.cityofcornell.com/', null, null, null, 'America/Chicago'),
  ('WPTF AM Radio Building', 'wptf-am-radio-building', 'weird-history', 35.79107, -78.76113, 'Cary', 'NC', 'This 1930s AM transmitter building is still in operation, but its newer claim to OddWay fame is television: it inspired the WSQK radio station building seen in the final season of Stranger Things. The building itself is across from the listed roadside viewing point and is not a public attraction to enter.', 'roadside', null, 'https://www.atlasobscura.com/places/wptf-am-radio-building', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wreck of the SS Atlantus', 'wreck-of-the-ss-atlantus', 'weird-history', 38.94434, -74.97206, 'Lower Township', 'NJ', 'The remains of a World War I-era concrete ship sit just offshore from Sunset Beach. The Atlantus broke loose during a storm in 1926 and became permanently stranded, leaving a slowly collapsing piece of experimental shipbuilding visible from shore.', 'open', null, 'https://www.atlasobscura.com/places/ss-atlantus', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wrong Site of Amelia Earhart''s Secret Wedding', 'wrong-site-of-amelia-earharts-secret-wedding', 'weird-history', 41.32596, -71.99136, 'Noank', 'CT', 'A plaque at the Latham/Chester Store identifies the building with Amelia Earhart''s secret 1931 wedding — except local historical research places the actual ceremony at a different house nearby. The confidently incorrect memorial makes the mistake itself the attraction.', 'limited', null, 'https://www.roadsideamerica.com/tip/49401', '2026-09-08T19:51:22.001704+00:00', null, 'https://noankhistoricalsociety.org/', null, null, null, 'America/New_York'),
  ('Wrong Way Cemetery', 'wrong-way-cemetery', 'weird-history', 30.23191, -92.26871, 'Rayne', 'LA', 'St. Joseph Cemetery became a roadside curiosity because some graves are oriented in a direction visitors perceive as ''wrong'' compared with conventional expectations. It is an active burial ground, so visit respectfully during lawful hours.', 'limited', null, 'https://www.atlasobscura.com/places/wrong-way-cemetery', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wyatt Earp Birthplace', 'wyatt-earp-birthplace', 'weird-history', 40.90796, -90.64487, 'Monmouth', 'IL', 'The restored birthplace of Wyatt Earp interprets the Illinois childhood of the future lawman before the family moved west.', 'limited', null, 'https://www.wyattearp.org/history/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ybor City Museum State Park', 'ybor-city-museum-state-park', 'weird-history', 27.96156, -82.43689, 'Tampa', 'FL', 'Museum inside a former bakery chronicling cigar-city immigration, mutual-aid societies, and neighborhood history.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/ybor-city-museum-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ye Olde Pepper Candy Companie', 'ye-olde-pepper-candy-companie', 'weird-history', 42.5225, -70.88476, 'Salem', 'MA', 'One of America''s oldest candy companies still sells old-fashioned sweets near the House of the Seven Gables. Its famous Gibralters and Black Jacks preserve recipes and candy traditions reaching back to the early nineteenth century.', 'open', null, 'https://www.atlasobscura.com/places/ye-olde-pepper-candy-companie', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yellow Bluff Fort Historic State Park', 'yellow-bluff-fort-historic-state-park', 'weird-history', 30.40644, -81.5742, 'Jacksonville', 'FL', 'Civil War earthwork fortifications overlooking routes into Jacksonville.', 'limited', null, 'https://www.floridastateparks.org/parks-and-trails/yellow-bluff-fort-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yulee Sugar Mill Ruins Historic State Park', 'yulee-sugar-mill-ruins-historic-state-park', 'weird-history', 28.78547, -82.61371, 'Homosassa', 'FL', 'Stone ruins of a Civil War-era sugar mill complex.', 'limited', null, 'https://www.floridastateparks.org/parks-and-trails/yulee-sugar-mill-ruins-historic-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('A World of Accordions Museum', 'a-world-of-accordions-museum', 'museums', 46.72086, -92.09826, 'Superior', 'WI', 'A former church houses hundreds of accordions and related free-reed instruments from many countries and eras. The sheer density of ornate, mechanical instruments makes the museum both a music archive and an unusually specific visual collection.', 'limited', null, 'https://www.worldofaccordions.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.worldofaccordions.org/', null, null, null, 'America/Chicago'),
  ('Acadian Memorial', 'acadian-memorial', 'museums', 30.12197, -91.82754, 'St. Martinville', 'LA', 'The Acadian Memorial commemorates Acadian refugees who arrived in Louisiana after deportation from Canada and includes a mural, genealogical resources and memorial installations. It stands beside the Evangeline Oak but is a distinct museum and remembrance site.', 'open', null, 'https://www.acadianmemorial.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Action Wildlife Taxidermy Museum', 'action-wildlife-taxidermy-museum', 'museums', 41.83254, -73.19709, 'Goshen', 'CT', 'Beyond the live-animal park, Action Wildlife maintains a museum filled with mounted animals and natural-history displays. The unusual concentration of taxidermy makes it a distinct stop within the larger wildlife property; current park admission includes museum access.', 'limited', null, 'https://www.roadsideamerica.com/location/ct', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.actionwildlifefoundation.com/', null, null, null, 'America/New_York'),
  ('Air Mobility Command Museum', 'air-mobility-command-museum', 'museums', 39.11869, -75.45664, 'Dover', 'DE', 'A free aviation museum housed in a restored World War II hangar that was once used for secret rocket development. More than 35 aircraft and unusual airlift artifacts fill the hangar and outdoor airpark, with some aircraft opened for visitor access on selected days.', 'open', null, 'https://www.amcmuseum.org/visit/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.amcmuseum.org/', null, null, null, 'America/New_York'),
  ('Air Power Park', 'air-power-park', 'museums', 37.04272, -76.36602, 'Hampton', 'VA', 'This free city park displays aircraft, rockets, missiles and space hardware outdoors in a landscape tied closely to Hampton''s aerospace history. The outdoor collection is accessible daily during park hours, while the indoor museum adds exhibits on aviation and space exploration.', 'open', null, 'https://www.hampton.gov/4233/Air-Power-Park', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Air Zoo Aerospace & Science Museum', 'air-zoo-aerospace-science-museum', 'museums', 42.22867, -85.55563, 'Portage', 'MI', 'The Air Zoo mixes more than a hundred aircraft and space artifacts with flight simulators and indoor amusement-style rides. Highlights include rare military aircraft and an SR-71B Blackbird, creating an unusually theatrical aviation museum rather than a quiet hangar display.', 'open', null, 'https://www.airzoo.org/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.airzoo.org/', null, null, null, 'America/Detroit'),
  ('Alabama Museum of the Health Sciences', 'alabama-museum-of-the-health-sciences', 'museums', 33.49931, -86.80439, 'Birmingham', 'AL', 'UAB’s medical museum preserves historic surgical tools, diagnostic devices, an iron lung and other objects documenting how medicine changed over time. The collection is displayed in the Pappas Historical Collections Gallery inside Lister Hill Library.', 'open', null, 'https://www.uab.edu/amhs/visit', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Allegan County Old Jail Museum', 'allegan-county-old-jail-museum', 'museums', 42.52857, -85.85297, 'Allegan', 'MI', 'Built in 1906, this former county jail and sheriff''s residence remained in use until 1963 and now houses the Allegan County Historical Society''s museum collection. Visitors can see original jail spaces alongside thousands of local artifacts, photographs and historical displays.', 'limited', null, 'https://alleganchamber.org/members/allegan-county-historical-society/', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Aluminum Tree & Ornament Museum', 'aluminum-tree-ornament-museum', 'museums', 35.23458, -82.73771, 'Brevard', 'NC', 'ATOM is a seasonal pop-up museum devoted to vintage aluminum Christmas trees and the strange color wheels, ornaments, and decorations that accompanied them. The deliberately kitschy collection appears at the Transylvania Heritage Museum around the holiday season rather than operating year-round. Seasonal information: https://www.romanticasheville.com/aluminum_tree_museum.htm', 'limited', null, 'https://aluminumtrees.weebly.com/contact.html', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Amelia Island Museum of History', 'amelia-island-museum-of-history', 'museums', 30.6693, -81.46383, 'Fernandina Beach', 'FL', 'Museum in a former jail covering pirates, smugglers, colonial powers, and the island''s unusual succession of flags.', 'limited', null, 'https://ameliamuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Antiquarian Society', 'american-antiquarian-society', 'museums', 42.27724, -71.81034, 'Worcester', 'MA', 'One of the nation''s great collections of early American printed material preserves newspapers, books, broadsides and ephemera reaching back centuries. Exhibits and public programs expose strange fragments of everyday history that usually remain inside research archives.', 'limited', null, 'https://www.americanantiquarian.org/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Celebration on Parade', 'american-celebration-on-parade', 'museums', 38.71551, -78.66929, 'Quicksburg', 'VA', 'A warehouse beside Shenandoah Caverns is packed with enormous retired parade floats from presidential inaugurations, Rose Parades and other major celebrations. Visitors walk among giant genies, animals, patriotic displays and repurposed float pieces on seasonal guided tours, generally from Memorial Day through Labor Day with selected additional dates.', 'limited', null, 'https://shenandoahcaverns.com/attractions/american-celebration-on-parade/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Classic Arcade Museum', 'american-classic-arcade-museum', 'museums', 43.61298, -71.47748, 'Laconia', 'NH', 'Hidden inside Funspot is a museum devoted to the golden age of coin-operated video games. Roughly 180 classic machines from the 1970s and 1980s are displayed at a time, with additional games rotated from storage. The combination of museum preservation and functioning arcade floor makes it far more interactive than a typical technology exhibit.', 'open', null, 'https://www.atlasobscura.com/places/american-classic-arcade-museum', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.classicarcademuseum.org/', null, null, null, 'America/New_York'),
  ('American Clock & Watch Museum', 'american-clock-watch-museum', 'museums', 41.67958, -72.94081, 'Bristol', 'CT', 'Hundreds of American clocks and watches trace Connecticut''s outsized role in mass-produced timekeeping. Rooms filled with ticking mechanisms, novelty clocks and elaborate cases make this specialized museum much stranger than its quiet historic-house exterior suggests.', 'open', null, 'https://www.atlasobscura.com/places/american-clock-and-watch-museum', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.clockandwatchmuseum.org/', null, null, null, 'America/New_York'),
  ('American Giants Museum', 'american-giants-museum', 'museums', 40.261, -89.23082, 'Atlanta', 'IL', 'A museum dedicated to Muffler Men and other giant fiberglass advertising figures explains the history of these classic roadside colossi.', 'limited', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('American Museum of Fly Fishing', 'american-museum-of-fly-fishing', 'museums', 43.168, -73.06713, 'Manchester', 'VT', 'This specialized museum preserves rods, reels, flies, art and archival material documenting the history of angling. Its intense focus on a single outdoor pastime makes it a strong niche museum stop rather than a general regional-history museum.', 'limited', null, 'https://amff.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Museum of Magic', 'american-museum-of-magic', 'museums', 42.27229, -84.95832, 'Marshall', 'MI', 'Founded in 1978, this downtown museum preserves an enormous collection of stage-magic history, including posters, props, costumes, illusions and material connected with famous performers. It is one of the strongest OddWay museum stops in southern Michigan because the collection focuses on the mechanics, showmanship and history of supposedly impossible acts.', 'limited', null, 'https://americanmuseumofmagic.com/', '2026-09-08T15:12:49.285859+00:00', null, 'https://americanmuseumofmagic.com/', null, null, null, 'America/Detroit'),
  ('American Museum of the House Cat', 'american-museum-of-the-house-cat', 'museums', 35.31328, -83.2609, 'Sylva', 'NC', 'An entire museum is devoted to the domestic cat, with thousands of cat-related objects ranging from antique art and advertising to toys, carvings, clocks, and historic memorabilia. It is one of the most narrowly themed museums in the state.', 'limited', null, 'https://www.catman2.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Museum of Tort Law', 'american-museum-of-tort-law', 'museums', 41.9228, -73.07543, 'Winsted', 'CT', 'Founded by Ralph Nader, this museum is devoted to civil wrongs, product-liability cases and the lawsuits that changed American consumer safety. Exhibits turn famous cases involving automobiles, dangerous products and corporate negligence into an unexpectedly strange museum subject.', 'limited', null, 'https://www.atlasobscura.com/places/american-museum-of-tort-law', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.tortmuseum.org/', null, null, null, 'America/New_York'),
  ('American Precision Museum', 'american-precision-museum', 'museums', 43.47476, -72.38939, 'Windsor', 'VT', 'Inside a nineteenth-century armory, this museum preserves early machine tools and manufacturing technology tied to interchangeable parts and precision production. The dense collection of unusual industrial machinery makes it one of Vermont''s strongest mechanical-history stops.', 'limited', null, 'https://americanprecision.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Sign Museum', 'american-sign-museum', 'museums', 39.14354, -84.53986, 'Cincinnati', 'OH', 'The American Sign Museum preserves more than a century of American commercial signage, from hand-painted storefronts and roadside signs to enormous glowing neon displays. Visitors can walk through recreated streetscapes and see neon craftsmanship during regular museum hours.', 'open', null, 'https://www.americansignmuseum.org/visit/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Space Museum & Space Walk of Fame', 'american-space-museum-space-walk-of-fame', 'museums', 28.6123, -80.80784, 'Titusville', 'FL', 'Spaceflight artifacts and monuments dedicated to workers behind America''s launch program.', 'limited', null, 'https://spacewalkoffame.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Toby Jug Museum', 'american-toby-jug-museum', 'museums', 42.03459, -87.67977, 'Evanston', 'IL', 'Thousands of figural ceramic jugs fill a museum devoted almost entirely to Toby and character jugs, from historic examples to modern pop culture.', 'limited', null, 'https://www.tobyjugmuseum.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('American Treasure Tour Museum', 'american-treasure-tour-museum', 'museums', 40.12749, -75.45356, 'Upper Providence Township', 'PA', 'The American Treasure Tour fills a huge former industrial building with automatic music machines, classic automobiles, animated store displays, advertisements and other pieces of American popular culture. Much of the collection is seen from a guided tram ride through rows of densely packed artifacts.', 'open', null, 'https://americantreasuretour.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Visionary Art Museum', 'american-visionary-art-museum', 'museums', 39.2804, -76.60689, 'Baltimore', 'MD', 'Rather than concentrating on conventionally trained artists, this Baltimore museum is devoted to self-taught and visionary creators. The campus is packed with giant sculptures, mosaics, kinetic pieces and objects made from unexpected materials, making the exterior alone an OddWay-worthy stop.', 'open', null, 'https://www.avam.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Anatomy of Death Museum', 'anatomy-of-death-museum', 'museums', 42.59822, -82.89161, 'Mount Clemens', 'MI', 'This small museum focuses directly on death, medicine, mourning and mortuary history rather than conventional local history. Displays include embalming and funeral equipment, anatomical material and other macabre artifacts, making it one of Michigan''s strongest indoor OddWay stops.', 'open', null, 'https://www.atlasobscura.com/places/the-anatomy-of-death-museum', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.anatomyofdeathmuseum.com/', null, null, null, 'America/Detroit'),
  ('Anna Jarvis Birthplace Museum', 'anna-jarvis-birthplace-museum', 'museums', 39.29458, -80.04447, 'Webster', 'WV', 'Anna Jarvis, the woman who successfully campaigned for the creation of Mother''s Day, was born at this house in Webster in 1864. The restored home now interprets Jarvis''s life as well as its Civil War connection to Union General George B. McClellan, but it is a small attraction with a limited operating season.', 'limited', null, 'https://www.nps.gov/people/anna-maria-jarvis.htm', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Anniston Museum of Natural History', 'anniston-museum-of-natural-history', 'museums', 33.69642, -85.82016, 'Anniston', 'AL', 'Dioramas, fossils, minerals, mounted animals and archaeological objects fill a museum built around wide-ranging natural-history collections. The specimen-heavy galleries retain the feel of an older encyclopedic museum.', 'open', null, 'https://www.exploreamag.org/anniston-museum', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Anti-Saloon League Museum', 'anti-saloon-league-museum', 'museums', 40.12295, -82.92939, 'Westerville', 'OH', 'Westerville was national headquarters of the Anti-Saloon League, one of the organizations most responsible for pushing the United States toward Prohibition. The Westerville History Museum occupies part of the League''s former headquarters and preserves its propaganda, publications and archives; walk-in visitors can view current exhibits during library museum hours.', 'open', null, 'https://westervillelibrary.org/museum/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Appalachian Pinball Museum', 'appalachian-pinball-museum', 'museums', 35.31868, -82.46033, 'Hendersonville', 'NC', 'Dozens of playable pinball machines and classic arcade games fill this downtown museum, with admission generally allowing unlimited play rather than charging by the game. The collection spans multiple eras of mechanical and electronic arcade history.', 'open', null, 'https://www.atlasobscura.com/places/appalachian-pinball-museum', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Archive of the Afterlife: The National Museum of the Paranormal', 'archive-of-the-afterlife-the-national-museum-of-the-paranormal', 'museums', 39.82631, -80.56853, 'Cameron', 'WV', 'This small paranormal museum houses allegedly haunted and unusual artifacts collected by investigator Steve Hummel, with displays built around the stories attached to each object. Its official information lists an April–November tour season but currently also displays a temporary-closure notice, so it should be verified before OddWay actively routes someone there.', 'limited', null, 'https://archive-afterlife.weebly.com/hours--admission.html', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Art Preserve', 'art-preserve', 'museums', 43.74306, -87.75472, 'Sheboygan', 'WI', 'This museum was built specifically to house artist-built environments and vernacular art that would otherwise be difficult to preserve. Entire rooms and large fragments from outsider-art sites are reconstructed inside, making the building feel like a warehouse of transplanted worlds.', 'open', null, 'https://www.jmkac.org/art-preserve/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.jmkac.org/art-preserve/', null, null, null, 'America/Chicago'),
  ('Asheville Pinball Museum', 'asheville-pinball-museum', 'museums', 35.59646, -82.55694, 'Asheville', 'NC', 'Rows of playable pinball machines and classic arcade cabinets turn this museum into an interactive history of coin-operated games. Admission typically allows visitors to play rather than merely look at the machines behind barriers.', 'open', null, 'https://www.atlasobscura.com/places/asheville-pinball-museum', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Asheville Radio Museum', 'asheville-radio-museum', 'museums', 35.57114, -82.55586, 'Asheville', 'NC', 'A volunteer-run museum on the A-B Tech campus preserves more than a century of radio history through antique receivers, transmitters, vacuum tubes, early televisions, amateur-radio equipment, and working demonstrations. Its limited weekly hours make it a check-before-you-go stop.', 'limited', null, 'https://www.radiomuseum.org/museum/usa/southern-appalachian-radio-museum-asheville-nc/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Auburn Cord Duesenberg Automobile Museum', 'auburn-cord-duesenberg-automobile-museum', 'museums', 41.35579, -85.0573, 'Auburn', 'IN', 'This museum occupies the restored 1930 Art Deco headquarters of the Auburn Automobile Company and preserves more than a century of Indiana automotive history. The building itself is part of the attraction, with period offices and showrooms surrounding rare Auburn, Cord and Duesenberg automobiles.', 'open', null, 'https://automobilemuseum.org/', '2026-09-08T13:34:34.826362+00:00', null, 'https://automobilemuseum.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Aurora Fossil Museum & Fossil Pits', 'aurora-fossil-museum-fossil-pits', 'museums', 35.30461, -76.78771, 'Aurora', 'NC', 'The museum interprets the enormous fossil deposits exposed by phosphate mining in eastern North Carolina. Outdoor fossil pits allow visitors to sift through material for shark teeth and other marine fossils, turning the stop into a hands-on hunt for remnants of prehistoric oceans.', 'limited', null, 'https://aurorafossilmuseum.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aviation Heritage Park', 'aviation-heritage-park', 'museums', 36.91951, -86.43594, 'Bowling Green', 'KY', 'This free aviation park displays restored military aircraft connected to aviators from south-central Kentucky, including fighters and other Cold War-era machines mounted outdoors. An indoor museum adds personal stories and artifacts tied to the people who flew them.', 'open', null, 'https://www.aviationheritagepark.com/about/location/', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.aviationheritagepark.com/', null, null, null, 'America/Chicago'),
  ('Babe Ruth Birthplace Museum', 'babe-ruth-birthplace-museum', 'museums', 39.28558, -76.6248, 'Baltimore', 'MD', 'George Herman “Babe” Ruth was born in this Baltimore rowhouse in 1895, just a few blocks from what is now Camden Yards. The restored house operates as a museum containing Ruth memorabilia, photographs and exhibits covering his life and baseball career.', 'open', null, 'https://baberuthmuseum.org/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Backstreet Cultural Museum', 'backstreet-cultural-museum', 'museums', 29.96583, -90.07011, 'New Orleans', 'LA', 'Backstreet preserves Mardi Gras Indian suits, social aid and pleasure club material, jazz funeral traditions and neighborhood parade culture. The collection gives travelers a close look at traditions often seen only briefly in street processions.', 'limited', null, 'https://www.backstreetmuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Baker Mansion History Museum', 'baker-mansion-history-museum', 'museums', 40.4906, -78.4083, 'Altoona', 'PA', 'Ironmaster Elias Baker completed this imposing Greek Revival mansion in 1849 after construction costs pushed him close to financial ruin. The Blair County Historical Society now fills the house with period rooms and regional artifacts, with public tours offered during its seasonal museum schedule.', 'limited', null, 'https://www.blairhistory.org/baker-mansion.html', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ballard Institute and Museum of Puppetry', 'ballard-institute-and-museum-of-puppetry', 'museums', 41.80471, -72.24277, 'Storrs', 'CT', 'More than 2,500 puppets from different cultures and theatrical traditions make up this University of Connecticut collection. Changing exhibitions range from folk puppetry to highly experimental creations, making it one of the state''s stranger specialized museums.', 'open', null, 'https://www.atlasobscura.com/places/ballard-institute-museum-of-puppetry', '2026-09-08T18:39:47.144889+00:00', null, 'https://bimp.uconn.edu/', null, null, null, 'America/New_York'),
  ('Barber Vintage Motorsports Museum', 'barber-vintage-motorsports-museum', 'museums', 33.53305, -86.61368, 'Birmingham', 'AL', 'Thousands of motorcycles and historic racing vehicles fill a multi-story museum beside Barber Motorsports Park. The sheer scale and density of machines make the collection visually unlike a normal automotive museum.', 'open', null, 'https://www.barbermuseum.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bare Dark Sky Observatory', 'bare-dark-sky-observatory', 'museums', 35.9305, -82.18247, 'Burnsville', 'NC', 'The Mayland Earth to Sky Park became the first certified International Dark Sky Park in the southeastern United States. Its observatory hosts scheduled astronomy programs in a mountain location selected specifically for exceptionally dark skies.', 'limited', null, 'https://www.atlasobscura.com/places/bare-dark-sky-observatory', '2026-09-09T05:34:33.398594+00:00', null, 'https://www.mayland.edu/foundation/foundation-events/earth-to-sky-observatory/', null, null, null, 'America/New_York'),
  ('Barker Character, Comic and Cartoon Museum', 'barker-character-comic-and-cartoon-museum', 'museums', 41.53143, -72.8944, 'Cheshire', 'CT', 'Tens of thousands of character toys, lunchboxes, figures, advertising pieces and cartoon collectibles crowd this family-run museum. The collection spans generations of American pop culture and has the dense, slightly overwhelming feel of a giant toy attic.', 'open', null, 'https://www.atlasobscura.com/places/barker-character-comic-and-cartoon-museum-2', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.barkermuseum.com/', null, null, null, 'America/New_York'),
  ('Battleship New Jersey', 'battleship-new-jersey', 'museums', 39.9401, -75.13196, 'Camden', 'NJ', 'The USS New Jersey, one of the most decorated battleships in U.S. history, is preserved as a floating museum on the Delaware River. Visitors can explore gun turrets, crew spaces, command areas and other sections of the enormous Iowa-class warship.', 'open', null, 'https://www.battleshipnewjersey.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bayernhof Museum', 'bayernhof-museum', 'museums', 40.49839, -79.91589, 'O''Hara Township', 'PA', 'This eccentric mansion was built by Charles Brown III and hides secret doors, concealed passages, unusual architecture and a large collection of antique automatic music machines. Tours are by advance appointment only, so this is a planned stop rather than a walk-in museum.', 'limited', null, 'https://www.bayernhofmuseum.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bayou Teche Museum', 'bayou-teche-museum', 'museums', 30.00508, -91.81741, 'New Iberia', 'LA', 'Interactive exhibits cover Bayou Teche culture, industry, music, food, local lore and Blue Dog artist George Rodrigue. Current public hours are Thursday through Saturday, with other visits available by appointment.', 'limited', null, 'https://bayoutechemuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bayou Terrebonne Waterlife Museum', 'bayou-terrebonne-waterlife-museum', 'museums', 29.59852, -90.72041, 'Houma', 'LA', 'The museum explains life, work and environmental change along Bayou Terrebonne through fisheries, wetlands and local industries. Its focus on a disappearing coastal landscape gives it unusual relevance beyond ordinary local history.', 'open', null, 'https://www.houmatravel.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Beaver Island Toy Museum', 'beaver-island-toy-museum', 'museums', 45.74601, -85.50797, 'St. James', 'MI', 'This tiny seasonal museum mixes vintage toys, dolls, miniature objects, handmade art and an eclectic collection assembled over many years on remote Beaver Island. Its informal, densely packed displays make it feel closer to a personal cabinet of curiosities than a conventional museum.', 'limited', null, 'https://www.atlasobscura.com/places/toy-museum-beaver-island-michigan', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Beer Can Museum', 'beer-can-museum', 'museums', 42.3165, -72.62611, 'Northampton', 'MA', 'A private collection has accumulated thousands of beer cans spanning decades of packaging, brewing history and graphic design. The walls of cans turn an ordinary object into a dense visual archive; this is a small private museum, so visitors should verify current access before making a dedicated trip.', 'limited', null, 'https://www.roadsideamerica.com/location/ma', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belhaven Memorial Museum', 'belhaven-memorial-museum', 'museums', 35.53914, -76.62153, 'Belhaven', 'NC', 'This old-school cabinet-of-curiosities museum grew from the collection of local resident Eva Blount Way. Its crowded displays include taxidermy, shells, dolls, antique tools, odd natural specimens, household objects, and miscellaneous artifacts gathered over decades.', 'limited', null, 'https://www.atlasobscura.com/places/belhaven-memorial-museum', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belle Boyd House', 'belle-boyd-house', 'museums', 39.45966, -77.96177, 'Martinsburg', 'WV', 'Built in 1853, this was the childhood home of Confederate spy Belle Boyd, one of the Civil War''s most notorious civilian intelligence figures. The restored house now serves as a historical museum and visitor center with exhibits on Boyd, local history and the surrounding region.', 'open', null, 'https://www.cityofmartinsburg.org/about-us/belle-boyd-house', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belle Gunness Exhibit — La Porte County Historical Society Museum', 'belle-gunness-exhibit-la-porte-county-historical-society-museum', 'museums', 41.58711, -86.70125, 'La Porte', 'IN', 'La Porte''s museum maintains an exhibit on Belle Gunness, the Norwegian-born woman linked to a series of killings discovered after her farm burned in 1908. The case remains unusually murky because the headless woman''s body recovered from the house was never conclusively established to be Gunness, and her ultimate fate is still debated.', 'open', null, 'https://laportecountyhistory.org/exhibits/belle-gunness/', '2026-09-08T13:34:34.826362+00:00', null, 'https://laportecountyhistory.org/', null, null, null, 'America/Chicago'),
  ('Belle Isle Aquarium', 'belle-isle-aquarium', 'museums', 42.3379, -82.9856, 'Detroit', 'MI', 'Opened in 1904, Belle Isle Aquarium is one of America''s oldest surviving public aquarium buildings and is known for its long, green-tiled gallery. The restored aquarium now displays freshwater and saltwater species during limited weekly public hours.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/detroit-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Belz Museum of Asian and Judaic Art', 'belz-museum-of-asian-and-judaic-art', 'museums', 35.1419, -90.05436, 'Memphis', 'TN', 'Large carved jade pieces, monumental Asian works and Judaic art fill this downtown museum. The scale and density of the collection make it a surprising hidden museum only steps from Memphis''s better-known music attractions.', 'open', null, 'https://www.belzmuseum.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ben E. Clement Mineral Museum', 'ben-e-clement-mineral-museum', 'museums', 37.33368, -88.07821, 'Marion', 'KY', 'Ben E. Clement spent decades assembling an extraordinary collection of fluorite from the Kentucky-Illinois mining district. The museum now houses thousands of vivid mineral specimens along with fossils, mining tools and geological curiosities.', 'open', null, 'https://clementmineralmuseum.org/about-the-mineral-museum/', '2026-09-08T14:30:49.642487+00:00', null, 'https://clementmineralmuseum.org/', null, null, null, 'America/Chicago'),
  ('Berman Museum', 'berman-museum', 'museums', 33.69744, -85.81904, 'Anniston', 'AL', 'The Berman Museum displays weapons, armor, espionage objects, decorative arts and unusual artifacts collected by Farley and Germaine Berman. The eclectic collection includes objects ranging from Asian arms to twentieth-century spy equipment.', 'open', null, 'https://www.exploreamag.org/berman-museum', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('BibleWalk', 'biblewalk', 'museums', 40.78577, -82.49666, 'Mansfield', 'OH', 'BibleWalk is a wax museum containing more than 300 figures arranged in dozens of life-sized scenes drawn from the Bible. Built largely through the work of the neighboring church congregation, it now offers multiple self-guided ticketed tours alongside smaller free exhibits.', 'open', null, 'https://biblewalk.us/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bicycle Heaven', 'bicycle-heaven', 'museums', 40.45631, -80.03241, 'Pittsburgh', 'PA', 'Bicycle Heaven combines a working bike shop with a sprawling museum packed with vintage bicycles, rare models, movie bikes and unusual cycling memorabilia. The collection fills multiple rooms and is open to visitors during posted business hours.', 'open', null, 'https://www.bicycleheaven.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Biedenharn Coca-Cola Museum', 'biedenharn-coca-cola-museum', 'museums', 32.35172, -90.88165, 'Vicksburg', 'MS', 'A museum in the building where Joseph Biedenharn first bottled Coca-Cola on a large commercial basis in 1894. Vintage advertising, bottling equipment and soda-fountain material make it a compact example of American commercial odd-history.', 'open', null, 'https://www.biedenharncoca-colamuseum.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Biedenharn Museum & Gardens', 'biedenharn-museum-gardens', 'museums', 32.5197, -92.13132, 'Monroe', 'LA', 'The museum preserves the home of Joseph Biedenharn, credited with first bottling Coca-Cola commercially, alongside Bible and regional collections. That mix of soft-drink history, formal gardens and religious artifacts makes it an unexpectedly eclectic stop.', 'open', null, 'https://www.bmuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Big Camera Obscura', 'big-camera-obscura', 'museums', 44.45966, -68.92489, 'Searsport', 'ME', 'A room-size camera obscura on the Penobscot Marine Museum campus is built to resemble an old box camera. Visitors can step inside and see a live, inverted image of the outside world projected through a small opening onto the interior surface. Museum: https://penobscotmarinemuseum.org/', 'limited', null, 'https://www.roadsideamerica.com/tip/92146', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Mac Museum', 'big-mac-museum', 'museums', 40.32091, -79.69198, 'North Huntingdon Township', 'PA', 'This McDonald''s contains a small museum devoted to the Big Mac, which was created by western Pennsylvania franchisee Jim Delligatti in 1967. Displays include memorabilia and an oversized Big Mac sculpture inside an otherwise operating restaurant.', 'open', null, 'https://www.atlasobscura.com/places/big-mac-museum', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Birds of Vermont Museum', 'birds-of-vermont-museum', 'museums', 44.35161, -73.00664, 'Huntington', 'VT', 'Hundreds of life-size wooden bird carvings fill this small museum, each painstakingly shaped and painted to represent species found in Vermont and beyond. The collection blurs the line between natural-history display and obsessive folk craftsmanship.', 'limited', null, 'https://birdsofvermont.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Birthplace of Kermit the Frog Museum', 'birthplace-of-kermit-the-frog-museum', 'museums', 33.40009, -90.89068, 'Leland', 'MS', 'A small museum celebrating Jim Henson''s Delta childhood and the local landscape that helped inspire Kermit the Frog. Displays include Muppets-related material and the stop sits beside Deer Creek in Henson''s hometown.', 'open', null, 'https://visitmississippi.org/trip-ideas/mississippi-eccentricities-you-have-to-see/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Blaschka Glass Flowers', 'blaschka-glass-flowers', 'museums', 42.37843, -71.11573, 'Cambridge', 'MA', 'Harvard''s famous Glass Flowers are thousands of astonishingly realistic plant models made almost entirely from glass by Leopold and Rudolf Blaschka. Their botanical accuracy is so convincing that visitors often struggle to believe the leaves, stems, blossoms and tiny anatomical details are glasswork.', 'limited', null, 'https://www.hmnh.harvard.edu/glass-flowers', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.hmnh.harvard.edu/', null, null, null, 'America/New_York'),
  ('Boardwalk Hall Auditorium Organ', 'boardwalk-hall-auditorium-organ', 'museums', 39.35361, -74.43861, 'Atlantic City', 'NJ', 'Hidden inside Jim Whelan Boardwalk Hall is an enormous pipe organ built with more than 30,000 pipes and designed to fill the gigantic auditorium without electronic amplification. Restoration work continues, and public access is mainly through scheduled recitals, tours and events.', 'limited', null, 'https://www.boardwalkorgans.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bob Ross Experience', 'bob-ross-experience', 'museums', 40.20269, -85.39274, 'Muncie', 'IN', 'Many episodes of The Joy of Painting were recorded in an unassuming studio inside Muncie''s historic Lucius L. Ball home. The room has been recreated as part of the Bob Ross Experience, with original paintings, artifacts and the actual setting associated with one of television''s most recognizable painters.', 'limited', null, 'https://visitindiana.in.gov/listing/bob-ross-experience/11963/', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.minnetrista.net/bobrossexperience', null, null, null, 'America/Indiana/Indianapolis'),
  ('Boonsborough Museum of History', 'boonsborough-museum-of-history', 'museums', 39.50829, -77.65283, 'Boonsboro', 'MD', 'This eccentric small-town collection ranges far beyond local history, with Civil War weapons sitting alongside Egyptian material, carved bullets, unusual medical and military objects, and a bouquet made from human hair. Tours operate on selected weekends from May through December or by appointment.', 'limited', null, 'https://boonsboroughmoh.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boston Athenaeum Skin Book', 'boston-athenaeum-skin-book', 'museums', 42.35808, -71.06234, 'Boston', 'MA', 'The Boston Athenaeum holds the memoir of highwayman James Allen, historically described as being bound in his own skin at his request. Conservation concerns mean the book is no longer permanently displayed, so the stop is the library and its morbid collection history rather than guaranteed viewing of the object.', 'limited', null, 'https://www.atlasobscura.com/places/boston-athenaeum-skin-book', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bottle House Museum', 'bottle-house-museum', 'museums', 44.37337, -86.00935, 'Kaleva', 'MI', 'John Makinen built this unusual house in 1941 using about 60,000 chipped or flawed glass bottles from his local bottling business. The Kaleva Historical Society now operates it as a museum of Finnish-American community history, with the colored bottle walls remaining the building''s main curiosity.', 'limited', null, 'https://www.kalevamichigan.com/bottle-house-museum', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.kalevamichigan.com/bottle-house-museum', null, null, null, 'America/Detroit'),
  ('Brady C. Jefcoat Museum of Americana', 'brady-c-jefcoat-museum-of-americana', 'museums', 36.43995, -77.10222, 'Murfreesboro', 'NC', 'More than 13,000 everyday objects fill an old high school, including huge collections of washing machines, irons, phonographs, radios, mousetraps, tools, furniture, and household devices. The scale turns ordinary domestic objects into an overwhelming cabinet of American material culture. Location: https://mapcarta.com/W1192052560', 'limited', null, 'https://www.visitnc.com/brady-c-jefcoat-museum-americana', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bread and Puppet Museum and Theater', 'bread-and-puppet-museum-and-theater', 'museums', 44.68416, -72.17799, 'Glover', 'VT', 'Bread and Puppet Theater preserves decades of enormous masks, political puppets and handmade performance figures inside a converted barn. The collection is dense, theatrical and intentionally rough-edged, with seasonal performances continuing on the surrounding farm.', 'limited', null, 'https://www.atlasobscura.com/places/bread-and-puppet-museum-and-theater', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bridgestone Arena Smilodon Bones', 'bridgestone-arena-smilodon-bones', 'museums', 36.1592, -86.7785, 'Nashville', 'TN', 'Fossils from a saber-toothed cat were discovered during construction near the arena, inspiring the Nashville Predators'' saber-toothed identity. Displays or references to the find are tied to the venue, so access may depend on arena hours or events.', 'limited', null, 'https://www.atlasobscura.com/places/bridgestone-arena-smilodon-bones', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Brimstone Museum Complex', 'brimstone-museum-complex', 'museums', 30.23107, -93.37702, 'Sulphur', 'LA', 'Built around a relocated railroad depot, the Brimstone Museum interprets Sulphur''s industrial and community history and hosts changing exhibits. The neighboring Henning Cultural Center adds rotating art and regional programming.', 'open', null, 'https://brimstonemuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Buckland Museum of Witchcraft and Magick', 'buckland-museum-of-witchcraft-and-magick', 'museums', 41.43812, -81.69976, 'Cleveland', 'OH', 'Raymond Buckland created the collection that became the Buckland Museum of Witchcraft and Magick, one of the oldest collections of its kind in the United States. The Cleveland museum displays ritual objects, occult artifacts and material connected to modern witchcraft and ceremonial magic, and visitors can enter during ticketed public hours.', 'open', null, 'https://bucklandmuseum.org/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Burlington County Prison Museum', 'burlington-county-prison-museum', 'museums', 39.9966, -74.78931, 'Mount Holly', 'NJ', 'Designed by Robert Mills and opened in 1811, this stone jail remained in use for more than 150 years. Cells, corridors, graffiti and execution-related history remain inside, and the building has also developed a strong reputation in local ghost lore.', 'limited', null, 'https://www.co.burlington.nj.us/954/Prison-Museum', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Burpee Museum of Natural History', 'burpee-museum-of-natural-history', 'museums', 42.2773, -89.08817, 'Rockford', 'IL', 'Home of Jane, one of the world''s best-preserved juvenile Tyrannosaurus rex specimens, along with fossils and unusual regional natural-history collections.', 'limited', null, 'https://burpee.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Busy Beaver Button Museum', 'busy-beaver-button-museum', 'museums', 41.91719, -87.71227, 'Chicago', 'IL', 'A working button factory houses a free museum tracing more than a century of pin-back buttons, slogans, politics, advertising, and novelty design.', 'limited', null, 'https://www.busybeaver.net/button-museum/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Call of the Wild Museum', 'call-of-the-wild-museum', 'museums', 45.01892, -84.68254, 'Gaylord', 'MI', 'This old-school wildlife museum uses dozens of taxidermy animals in large dioramas to recreate North American habitats. The dense arrangement of bears, wolves, deer and other mounted animals gives it the distinctive feel of a classic northern Michigan roadside attraction.', 'open', null, 'https://www.michigan.org/property/call-wild', '2026-09-08T15:31:15.588137+00:00', null, 'https://callofthewildgaylord.com/', null, null, null, 'America/Detroit'),
  ('Camera Heritage Museum', 'camera-heritage-museum', 'museums', 38.14964, -79.07276, 'Staunton', 'VA', 'This independent museum has assembled thousands of cameras spanning the history of photography, including espionage cameras disguised as everyday objects, early daguerreotype equipment and hundreds of Brownie models. The collection also includes historic photographs and material connected to figures such as John Wilkes Booth.', 'open', null, 'https://cameraheritagemuseum.org/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Camp Breckinridge Museum and Art Center', 'camp-breckinridge-museum-and-art-center', 'museums', 37.6776, -87.8887, 'Morganfield', 'KY', 'This museum occupies one of the few surviving buildings from Camp Breckinridge, a World War II training installation that once contained roughly 1,800 structures. Among its most distinctive remnants are murals of European scenes painted by German prisoners of war held at the camp.', 'open', null, 'https://www.unioncountyky.org/our-county/camp-breckinridge-museum-and-arts-center/camp-breckinridge-museum', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Camp Five Museum and Lumberjack Steam Train', 'camp-five-museum-and-lumberjack-steam-train', 'museums', 45.56359, -88.67187, 'Laona', 'WI', 'A vintage steam train carries visitors from Laona to a preserved logging-camp museum complex. Historic machinery, camp buildings and forestry exhibits make the ride feel like a functioning fragment of Northwoods industrial history.', 'limited', null, 'https://www.lumberjacksteamtrain.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.lumberjacksteamtrain.com/', null, null, null, 'America/Chicago'),
  ('Capital City Museum', 'capital-city-museum', 'museums', 38.19852, -84.87569, 'Frankfort', 'KY', 'Frankfort''s city museum mixes state-capital history with odd local stories, political artifacts and material connected to events such as the assassination of Governor William Goebel. The museum is also a stop on Kentucky''s paranormal-tourism program, adding reported ghost activity to an already unusual local collection.', 'open', null, 'https://frankforthistory.org/capital-city-museum/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cardboard Boat Museum', 'cardboard-boat-museum', 'museums', 38.95218, -84.28484, 'New Richmond', 'OH', 'The Cardboard Boat Museum calls itself the world''s only museum devoted entirely to boats made from cardboard and preserves vessels, photographs and history connected to New Richmond''s famous cardboard-boat races. Admission is free during its posted seasonal or weekend hours.', 'open', null, 'https://cardboardboatmuseum.com/visitors/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Castle Halloween Museum', 'castle-halloween-museum', 'museums', 40.50766, -78.40791, 'Altoona', 'PA', 'More than 35,000 Halloween and macabre objects fill this private museum, ranging from nineteenth-century decorations and costumes to funeral-related pieces and modern holiday collectibles. Tours are arranged in advance rather than offered as normal daily walk-in admission.', 'limited', null, 'https://www.atlasobscura.com/places/castle-halloween-museum', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Castle Museum of Saginaw County History', 'castle-museum-of-saginaw-county-history', 'museums', 43.43095, -83.93552, 'Saginaw', 'MI', 'Saginaw''s history museum occupies a spectacular 1898 federal building deliberately designed to resemble a French château. Behind the turrets and stone walls are local-history exhibits and remnants of its former postal role, making the architecture alone worth the OddWay stop.', 'open', null, 'https://www.castlemuseum.org/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.castlemuseum.org/', null, null, null, 'America/Detroit'),
  ('Castle Noel', 'castle-noel', 'museums', 41.13689, -81.86363, 'Medina', 'OH', 'Castle Noel is a year-round Christmas museum built around an enormous collection of Hollywood holiday-movie props, costumes, department-store displays and animated window scenes. It opened in Medina in 2013 and operates as a guided ticketed attraction, so reservations are recommended even though it is not limited to the Christmas season.', 'open', null, 'https://castlenoel.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Castlerock Museum', 'castlerock-museum', 'museums', 44.3197, -91.91374, 'Alma', 'WI', 'Rows of arms, armor and historical weapons fill this privately built museum overlooking the Mississippi River. Exhibits span centuries and cultures, including suits of armor, swords and polearms that make the collection feel more like a castle armory than a small-town museum.', 'limited', null, 'https://www.castlerockmuseum.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.castlerockmuseum.com/', null, null, null, 'America/Chicago'),
  ('Cedar Key Historical Society Museum', 'cedar-key-historical-society-museum', 'museums', 29.13889, -83.03655, 'Cedar Key', 'FL', 'Island museum covering shipwrecks, railroads, pencil manufacturing, hurricanes, and early settlement.', 'limited', null, 'https://cedarkeyhistory.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Charles River Museum of Industry and Innovation', 'charles-river-museum-of-industry-and-innovation', 'museums', 42.37319, -71.23369, 'Waltham', 'MA', 'Inside the former Boston Manufacturing Company complex, machinery and artifacts trace the transition from hand production to industrial manufacturing. The museum occupies a birthplace of America''s factory system, with large mechanical objects filling the old mill space.', 'limited', null, 'https://www.charlesrivermuseum.org/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Circus World', 'circus-world', 'museums', 43.46695, -89.7371, 'Baraboo', 'WI', 'Baraboo was winter headquarters for the Ringling Brothers, and Circus World preserves historic circus buildings, wagons, posters, costumes and performance traditions on the original grounds. Seasonal live programming turns the site into both a museum and a surviving fragment of circus culture.', 'limited', null, 'https://circusworld.wisconsinhistory.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://circusworld.wisconsinhistory.org/', null, null, null, 'America/Chicago'),
  ('Cliff''s Museum of Car Memorabilia', 'cliffs-museum-of-car-memorabilia', 'museums', 39.21006, -81.05037, 'Harrisville', 'WV', 'This privately owned collection packs thousands of pieces of automobile, gasoline-station and roadside memorabilia into a roughly 13,000-square-foot building. The owner welcomes visitors without a normal admission charge, but the museum operates largely by appointment or when someone is available, so call before making a detour.', 'limited', null, 'https://cliffwvathebuilding.com/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coffin and Mummy of Nesmin — RISD Museum', 'coffin-and-mummy-of-nesmin-risd-museum', 'museums', 41.82675, -71.40855, 'Providence', 'RI', 'RISD Museum preserves the coffin and mummified remains of Nesmin, an Egyptian priest who lived during the Ptolemaic period. The elaborately decorated coffin and surviving mummy make this one of Rhode Island''s most unusual museum objects. The museum currently lists the object as on view, but gallery rotations and hours should be checked before visiting.', 'limited', null, 'https://risdmuseum.org/art-design/collection/coffin-and-mummy-nesmin-38206', '2026-09-09T04:49:27.913704+00:00', null, 'https://risdmuseum.org/', null, null, null, 'America/New_York'),
  ('Cole Land Transportation Museum', 'cole-land-transportation-museum', 'museums', 44.78517, -68.80457, 'Bangor', 'ME', 'This large transportation museum preserves an eclectic collection of Maine road, rail, military, farm, and commercial vehicles. Exhibits range from snowplows and fire engines to motorcycles, trains, military equipment, and historic machinery, making it much broader and stranger than a conventional car museum.', 'limited', null, 'https://fotospot.com/attractions/maine/cole-land-transportation-museum', '2026-09-09T04:54:23.476824+00:00', null, 'https://www.colemuseum.org/', null, null, null, 'America/New_York'),
  ('College Park Aviation Museum', 'college-park-aviation-museum', 'museums', 38.97883, -76.92231, 'College Park', 'MD', 'The museum stands beside the world''s oldest continuously operating airport, where the Wright brothers trained military pilots beginning in 1909. Exhibits cover early flight, unusual aircraft and the airport''s long experimental history, with active aircraft often visible just outside.', 'open', null, 'https://www.pgparks.com/facilities/college-park-aviation-museum', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Colonial Tavern Sign Collection', 'colonial-tavern-sign-collection', 'museums', 41.77293, -72.70528, 'Hartford', 'CT', 'The Connecticut Museum of Culture and History holds an exceptional collection of early American tavern signs painted with animals, symbols, portraits and sometimes bizarre imagery meant to attract travelers who could not necessarily read. Display availability can rotate with exhibitions.', 'open', null, 'https://www.atlasobscura.com/places/the-largest-collection-of-colonial-american-tavern-signs', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.connecticutmuseum.org/', null, null, null, 'America/New_York'),
  ('Columbus Chapel and Boal Mansion Museum', 'columbus-chapel-and-boal-mansion-museum', 'museums', 40.77906, -77.79929, 'Boalsburg', 'PA', 'The Boal estate contains an imported European chapel associated with the Columbus family along with an unusually eclectic collection of historic objects. Guided tours include claims of Columbus-family artifacts, religious pieces, weapons, carriages and other material gathered by generations of the Boal family.', 'limited', null, 'https://boalmuseum.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Connecticut Trolley Museum', 'connecticut-trolley-museum', 'museums', 41.9314, -72.59472, 'East Windsor', 'CT', 'Historic streetcars and electric railway equipment are preserved on a working museum line where visitors can ride vintage trolleys. The collection is particularly atmospheric during its seasonal nighttime and Halloween programs.', 'limited', null, 'https://www.atlasobscura.com/places/connecticut-trolley-museum', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.ct-trolley.org/', null, null, null, 'America/New_York'),
  ('Connecticut Valley Tobacco Museum', 'connecticut-valley-tobacco-museum', 'museums', 41.89909, -72.70355, 'Windsor', 'CT', 'Inside Northwest Park, historic tobacco sheds and exhibits preserve the tools and techniques behind Connecticut River Valley shade tobacco. The highly specialized museum explains an agricultural industry that once shaped the region''s landscape and international trade.', 'limited', null, 'https://ctvalleytobaccohistorical.org/', '2026-09-08T19:51:22.001704+00:00', null, 'https://ctvalleytobaccohistorical.org/', null, null, null, 'America/New_York'),
  ('Cook Museum of Natural Science', 'cook-museum-of-natural-science', 'museums', 34.60511, -86.98339, 'Decatur', 'AL', 'The Cook family’s collections grew from an interest in insects and pest-control education into a full natural-science museum. Today the exhibits range from preserved specimens and fossils to live animals and immersive ecosystems.', 'open', null, 'https://www.cookmuseum.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Count Orlok''s Nightmare Gallery', 'count-orloks-nightmare-gallery', 'museums', 42.52142, -70.89485, 'Salem', 'MA', 'A horror and monster museum packed with life-size creatures, film props and highly detailed recreations of famous movie monsters. The gallery has moved within Salem over the years and is now on Essex Street, so older location pins should not be used.', 'limited', null, 'https://www.atlasobscura.com/places/count-orloks-nightmare-gallery', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.nightmaregallery.com/', null, null, null, 'America/New_York'),
  ('Country Doctor Museum', 'country-doctor-museum', 'museums', 35.77875, -78.12241, 'Bailey', 'NC', 'This museum preserves the tools and working world of rural physicians from the days of house calls, horse-drawn transportation, and small-town pharmacies. Antique surgical equipment, medical instruments, medicine bottles, and doctors’ vehicles make the collection unusually tangible.', 'limited', null, 'https://countrydoctormuseum.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cow Vomit Rope — Little Compton Historical Society', 'cow-vomit-rope-little-compton-historical-society', 'museums', 41.49202, -71.18452, 'Little Compton', 'RI', 'Among Little Compton''s stranger preserved artifacts is a rope-like mass traditionally described as having been vomited up by a cow. The object has survived as part of the local historical collection precisely because generations found it too bizarre to discard. Museum access is seasonal, so confirm current hours before traveling.', 'limited', null, 'https://littlecompton.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://littlecompton.org/', null, null, null, 'America/New_York'),
  ('Crazy 80''s Car Museum', 'crazy-80s-car-museum', 'museums', 41.09645, -88.43685, 'Dwight', 'IL', 'An independent collection celebrates 1980s cars, memorabilia, toys, and pop culture in a deliberately nostalgic specialty museum.', 'limited', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Creation Museum', 'creation-museum', 'museums', 39.08629, -84.78301, 'Petersburg', 'KY', 'This large museum presents a young-Earth creationist interpretation of natural history through elaborate displays, animatronics and recreated environments. OddWay can treat it as an unusual themed museum rather than endorsing its scientific claims, which differ from the mainstream scientific consensus on Earth''s age and evolution.', 'limited', null, 'https://creationmuseum.org/', '2026-09-08T14:15:10.228298+00:00', null, 'https://creationmuseum.org/', null, null, null, 'America/New_York'),
  ('Creole Nature Trail Adventure Point', 'creole-nature-trail-adventure-point', 'museums', 30.21137, -93.37689, 'Sulphur', 'LA', 'This visitor center uses interactive exhibits on alligators, marsh ecology, Cajun and Creole food and local music to prepare travelers for the Creole Nature Trail. It is a compact hands-on introduction to southwest Louisiana''s coastal weirdness.', 'open', null, 'https://www.visitlakecharles.org/creole-nature-trail/adventure-point/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cross in the Woods and Nun Doll Museum', 'cross-in-the-woods-and-nun-doll-museum', 'museums', 45.39783, -84.63091, 'Indian River', 'MI', 'This Catholic shrine is dominated by an enormous outdoor crucifix and also contains an unexpectedly specific museum of more than 500 dolls dressed to represent hundreds of religious orders. The grounds are open year-round during daylight hours, while the doll museum follows posted daily hours.', 'open', null, 'https://crossinthewoods.com/doll-museum/', '2026-09-08T14:53:55.160019+00:00', null, 'https://crossinthewoods.com/', null, null, null, 'America/Detroit'),
  ('Curwood Castle', 'curwood-castle', 'museums', 42.99944, -84.17528, 'Owosso', 'MI', 'Adventure novelist James Oliver Curwood built this miniature French-style castle in 1922 as his private writing studio beside the Shiawassee River. The fanciful stone building is now a museum containing Curwood artifacts and feels far more like a storybook fortress than an author''s office.', 'limited', null, 'https://www.atlasobscura.com/places/curwood-castle', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Danbury Railway Museum', 'danbury-railway-museum', 'museums', 41.39784, -73.45046, 'Danbury', 'CT', 'A former railroad station and yard preserve locomotives, rolling stock, a working turntable and other heavy railway equipment. The station also has a film connection: Danbury''s railroad facilities appeared in Alfred Hitchcock''s ''Strangers on a Train.''', 'limited', null, 'https://www.atlasobscura.com/things-to-do/danbury-connecticut', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.danburyrail.org/', null, null, null, 'America/New_York'),
  ('Darlington Raceway Stock Car Museum', 'darlington-raceway-stock-car-museum', 'museums', 34.29732, -79.90515, 'Darlington', 'SC', 'Beside one of NASCAR’s oldest major tracks, this museum preserves historic race cars, trophies, memorabilia, engines, and artifacts from stock-car racing history. The collection makes a good OddWay stop even when no race is taking place.', 'limited', null, 'https://www.darlingtonraceway.com/museum/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('DEA Museum', 'dea-museum', 'museums', 38.86467, -77.05821, 'Arlington', 'VA', 'The Drug Enforcement Administration''s museum documents the history of illicit drugs, federal enforcement and major investigations through seized objects, undercover material and unusual artifacts. Admission is free, but the museum is inside a federal building and adult visitors must meet current government identification and security-screening requirements.', 'open', null, 'https://museum.dea.gov/visit', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Deke Slayton Memorial Space & Bicycle Museum', 'deke-slayton-memorial-space-bicycle-museum', 'museums', 43.94468, -90.81269, 'Sparta', 'WI', 'This small-town museum combines two subjects that rarely share a building: astronaut Deke Slayton''s space career and Sparta''s bicycle-manufacturing heritage. Space hardware, astronaut material and historic bikes make the pairing uniquely OddWay.', 'limited', null, 'https://dekeslaytonmuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://dekeslaytonmuseum.org/', null, null, null, 'America/Chicago'),
  ('D''Elia Antique Tool Museum', 'delia-antique-tool-museum', 'museums', 41.69661, -72.08215, 'Scotland', 'CT', 'A small museum connected to the Scotland Public Library preserves an obsessive collection of roughly 1,500 woodworking planes spanning several centuries. Its extremely narrow subject matter is exactly what makes it an OddWay-worthy stop.', 'limited', null, 'https://www.roadsideamerica.com/tip/62387', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil Anse Hatfield Homeplace & Museum', 'devil-anse-hatfield-homeplace-museum', 'museums', 37.69978, -81.99419, 'Sarah Ann', 'WV', 'This museum occupies the Hatfield homeplace area and preserves family material connected with Devil Anse, the famous feud and later generations of the family. It operates with varying hours and visitors should call ahead.', 'limited', null, 'https://hatfieldmccoyfoundation.org/devil-anse-homeplace-museum/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dinosaur Discovery Museum', 'dinosaur-discovery-museum', 'museums', 42.5839, -87.82367, 'Kenosha', 'WI', 'Skeletons and casts focus on the evolutionary link between meat-eating dinosaurs and modern birds. The museum''s dramatic central displays include large theropod skeletons, while an on-site laboratory shows how fossils are prepared and studied.', 'open', null, 'https://museums.kenosha.org/dinosaur-discovery-museum', '2026-09-09T13:02:00.307533+00:00', null, 'https://museums.kenosha.org/', null, null, null, 'America/Chicago'),
  ('Dinosaur Footprints of Holyoke', 'dinosaur-footprints-of-holyoke', 'museums', 42.24169, -72.62341, 'Holyoke', 'MA', 'Hundreds of Early Jurassic dinosaur tracks are exposed in sandstone beside the Connecticut River. The three-toed prints were once thought to belong to giant birds and helped shape early American paleontology; the preserve is normally open from April through November.', 'limited', null, 'https://www.atlasobscura.com/places/dinosaur-footprints-holyoke', '2026-09-09T04:43:56.902716+00:00', null, 'https://thetrustees.org/place/dinosaur-footprints/', null, null, null, 'America/New_York'),
  ('Dinosaur State Park', 'dinosaur-state-park', 'museums', 41.65118, -72.65851, 'Rocky Hill', 'CT', 'Thousands of Early Jurassic dinosaur tracks were uncovered here by accident in 1966. Hundreds remain visible beneath a retro-futuristic geodesic dome, while many more were reburied for preservation below the surrounding landscape.', 'open', null, 'https://www.atlasobscura.com/places/dinosaur-state-park', '2026-09-08T18:39:47.144889+00:00', null, 'https://ctparks.com/parks/dinosaur-state-park', null, null, null, 'America/New_York'),
  ('DiscoverSea Shipwreck Museum', 'discoversea-shipwreck-museum', 'museums', 38.4573, -75.0526, 'Fenwick Island', 'DE', 'An unusually dense private collection of shipwreck treasure and maritime artifacts, with roughly 10,000 objects displayed at a time. Alongside coins, weapons and recovered cargo are stranger pieces that have included a Fiji-style merman and other natural-history curiosities.', 'limited', null, 'https://www.discoversea.com/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.discoversea.com/', null, null, null, 'America/New_York'),
  ('Don Garlits Museum of Drag Racing', 'don-garlits-museum-of-drag-racing', 'museums', 29.02284, -82.15483, 'Ocala', 'FL', 'Major collection preserving drag-racing history, unusual race cars, engines, and speed-culture artifacts.', 'limited', null, 'https://garlits.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Donora Smog Museum', 'donora-smog-museum', 'museums', 40.1777, -79.85649, 'Donora', 'PA', 'The museum documents the deadly 1948 Donora smog, when industrial air pollution became trapped over the Monongahela Valley and sickened thousands of residents. Photographs, newspapers and artifacts explain the disaster''s role in the development of modern American air-pollution law; public hours are limited, so check before traveling.', 'limited', null, 'https://www.donorahistoricalsociety.org/donora-smog-museum/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Doo Wop Experience Museum and Neon Sign Garden', 'doo-wop-experience-museum-and-neon-sign-garden', 'museums', 38.98281, -74.8179, 'Wildwood', 'NJ', 'This seasonal museum preserves Wildwood''s exuberant 1950s and 1960s motel culture through neon signs, furniture, architecture and pop-culture artifacts. Its outdoor Neon Sign Garden contains restored signs rescued from demolished or remodeled shore motels.', 'limited', null, 'https://www.doowopusa.org/the-museum', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dr. Carter G. Woodson African American Museum', 'dr-carter-g-woodson-african-american-museum', 'museums', 27.75679, -82.65212, 'St. Petersburg', 'FL', 'Focused museum preserving Black history in St. Petersburg''s historic Deuces neighborhood.', 'limited', null, 'https://woodsonmuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dr. J.H. Kellogg Discovery Center', 'dr-jh-kellogg-discovery-center', 'museums', 42.32781, -85.19686, 'Battle Creek', 'MI', 'Part of Historic Adventist Village, this museum explores Dr. John Harvey Kellogg''s unusual ideas about exercise, nutrition and preventive health. Displays include reproductions and examples of the mechanical exercise devices, light treatments and other inventions associated with Battle Creek''s sanitarium era.', 'limited', null, 'https://www.michigan.org/property/historic-adventist-village', '2026-09-08T15:12:49.285859+00:00', null, 'https://adventistheritage.org/', null, null, null, 'America/Detroit'),
  ('Dr. Kate Museum', 'dr-kate-museum', 'museums', 45.89546, -89.70031, 'Woodruff', 'WI', 'The museum tells the story of physician Kate Pelham Newcomb and the community penny drive that helped fund a hospital in the 1950s. It adds human context to the nearby giant penny and preserves the unusual publicity campaign that put tiny Woodruff in national headlines.', 'limited', null, 'https://www.drkatemuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.drkatemuseum.org/', null, null, null, 'America/Chicago'),
  ('Dr. Seuss Museum', 'dr-seuss-museum', 'museums', 42.1045, -72.58742, 'Springfield', 'MA', 'The Amazing World of Dr. Seuss Museum recreates parts of Theodor Geisel''s Springfield childhood and fills galleries with characters and environments from his books. It complements the outdoor sculpture garden with a separate indoor museum experience.', 'limited', null, 'https://www.atlasobscura.com/places/dr-seuss-museum', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dr. Ted''s Musical Marvels', 'dr-teds-musical-marvels', 'museums', 38.20816, -86.97477, 'Dale', 'IN', 'Dr. Ted Waflart assembled a collection of self-playing musical machines ranging from small music boxes to enormous orchestrions and dance organs. The unusual part is that many of the instruments are demonstrated rather than left silent, but access is generally arranged for pre-scheduled groups, so travelers should call before routing here.', 'limited', null, 'https://www.atlasobscura.com/places/dr-teds-musical-marvels', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('Dryptosaurus Skeletal Mount', 'dryptosaurus-skeletal-mount', 'museums', 40.22107, -74.77309, 'Trenton', 'NJ', 'The New Jersey State Museum displays a skeletal reconstruction of Dryptosaurus, a large predatory dinosaur first discovered in the state. The mount gives physical form to a dinosaur whose fossils helped shape early American paleontology.', 'limited', null, 'https://www.nj.gov/state/museum/explore-natural-history.shtml', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Duck of Justice — Bangor Police Museum', 'duck-of-justice-bangor-police-museum', 'museums', 44.79717, -68.77299, 'Bangor', 'ME', 'The unlikely star of the Bangor Police Museum is the Duck of Justice, a taxidermied wood duck rescued from a trash bin and transformed into the department’s internet-famous mascot. The small museum is inside the police department and is currently viewed by appointment.', 'limited', null, 'https://www.bangormaine.gov/389/Police-Department-Museum', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dymaxion House — The Henry Ford', 'dymaxion-house-the-henry-ford', 'museums', 42.30369, -83.23422, 'Dearborn', 'MI', 'Buckminster Fuller''s experimental Dymaxion House was designed as a lightweight, mass-producible aluminum home suspended around a central mast. A surviving prototype has been reconstructed inside The Henry Ford, allowing visitors to walk through one of the twentieth century''s strangest attempts to reinvent ordinary housing.', 'limited', null, 'https://www.atlasobscura.com/places/dymaxion-house', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.thehenryford.org/', null, null, null, 'America/Detroit'),
  ('EAA Aviation Museum', 'eaa-aviation-museum', 'museums', 43.984, -88.57726, 'Oshkosh', 'WI', 'Oshkosh''s aviation museum displays experimental aircraft, warbirds, early planes and one-of-a-kind flying machines. Its connection to the enormous annual EAA AirVenture gathering makes the site a pilgrimage point for unusual aircraft and homebuilt-flight culture.', 'open', null, 'https://www.eaa.org/eaa-museum', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.eaa.org/eaa-museum', null, null, null, 'America/Chicago'),
  ('Early Ford V-8 Foundation Museum', 'early-ford-v-8-foundation-museum', 'museums', 41.335, -85.08964, 'Auburn', 'IN', 'This museum is devoted to Ford vehicles and history from the flathead V-8 era, especially 1932 through 1953. Its collection includes dozens of restored automobiles, period displays and a recreation of an early Ford dealership, making it a much more specific stop than a general car museum.', 'open', null, 'https://fordv8foundation.org/', '2026-09-08T13:53:25.695107+00:00', null, 'https://fordv8foundation.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Early Television Museum', 'early-television-museum', 'museums', 40.03451, -83.16161, 'Hilliard', 'OH', 'The Early Television Museum preserves more than 150 television sets and related artifacts spanning mechanical television, early electronic sets, color television and broadcast history. Visitors can see restored equipment and rare experimental technology during the museum''s posted weekend hours.', 'open', null, 'https://www.earlytelevision.org/museum.html', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eartha — Giant Rotating Globe', 'eartha-giant-rotating-globe', 'museums', 43.80794, -70.16399, 'Yarmouth', 'ME', 'Eartha is an enormous rotating globe installed inside the former DeLorme headquarters, now associated with Garmin. The three-story sphere turns slowly inside a glass atrium and can also be seen from outside the building.', 'limited', null, 'https://www.atlasobscura.com/places/eartha-delorme-headquarters', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe Cottage', 'edgar-allan-poe-cottage', 'museums', 40.86551, -73.89424, 'Bronx', 'NY', 'Edgar Allan Poe lived in this small Fordham cottage from 1846 until shortly before his death, and his wife Virginia died here in 1847. The preserved house is now a museum containing exhibits and period furnishings connected to Poe''s final years, with regular weekend hours and additional private tours by arrangement.', 'open', null, 'https://bronxhistoricalsociety.org/poe-cottage', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe House & Museum', 'edgar-allan-poe-house-museum', 'museums', 39.2913, -76.63313, 'Baltimore', 'MD', 'Edgar Allan Poe lived in this tiny Baltimore rowhouse with members of his family from roughly 1833 to 1835. The preserved house now operates as a museum devoted to Poe''s life and writing, with period rooms, exhibits and artifacts connected to one of America''s most enduring masters of the macabre.', 'open', null, 'https://www.poeinbaltimore.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe Museum', 'edgar-allan-poe-museum', 'museums', 37.53216, -77.42608, 'Richmond', 'VA', 'Richmond''s Poe Museum holds the world''s largest collection of Edgar Allan Poe manuscripts, letters, first editions, personal belongings and memorabilia. The museum opened in 1922 in Richmond''s oldest surviving residential building and includes the atmospheric Enchanted Garden inspired by Poe''s writing.', 'open', null, 'https://poemuseum.org/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe National Historic Site', 'edgar-allan-poe-national-historic-site', 'museums', 39.962, -75.15, 'Philadelphia', 'PA', 'Edgar Allan Poe lived in this Philadelphia house during one of the most productive periods of his writing career in the 1840s. The National Park Service preserves the empty rooms and exhibits about Poe''s work, including the dark stories that helped define American horror literature.', 'open', null, 'https://www.nps.gov/edal/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edna W. Lawrence Nature Lab', 'edna-w-lawrence-nature-lab', 'museums', 41.827, -71.40803, 'Providence', 'RI', 'RISD''s Nature Lab holds tens of thousands of natural-history specimens used for art and design study, including bones, shells, insects, preserved animals and other biological material. Dense cabinets of specimens make the collection feel somewhere between an art studio and an old cabinet of curiosities. Public access varies with RISD programming, so check ahead.', 'limited', null, 'https://naturelab.risd.edu/', '2026-09-09T04:49:27.913704+00:00', null, 'https://naturelab.risd.edu/', null, null, null, 'America/New_York'),
  ('Edward Gorey House', 'edward-gorey-house', 'museums', 41.7054, -70.24252, 'Yarmouth Port', 'MA', 'The former home of illustrator Edward Gorey preserves the wonderfully macabre world behind his small, grim books and drawings. Exhibitions mix original art, personal objects and eccentric collections from an artist whose work was filled with mysterious deaths, ominous children and dark humor.', 'limited', null, 'https://www.edwardgoreyhouse.org/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.edwardgoreyhouse.org/', null, null, null, 'America/New_York'),
  ('Electromagnetic Pinball Museum and Restoration', 'electromagnetic-pinball-museum-and-restoration', 'museums', 41.86799, -71.3992, 'Pawtucket', 'RI', 'This hands-on museum packs a large rotating collection of vintage and modern pinball machines, electromechanical games and classic arcade cabinets into a former industrial building. Admission currently covers unlimited free play rather than individual tokens or quarters. It is both a museum and a functioning preservation workshop for old amusement technology.', 'open', null, 'https://www.electromagneticpinballmuseum.com/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.electromagneticpinballmuseum.com/', null, null, null, 'America/New_York'),
  ('Elliott Museum', 'elliott-museum', 'museums', 27.21423, -80.17645, 'Stuart', 'FL', 'Museum with a mechanical multi-level robotic vehicle storage system and eclectic local collections.', 'limited', null, 'https://hsmc-fl.com/elliott-museum/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elloree Heritage Museum — Animatronic Mr. Snider and Stuffed Mule', 'elloree-heritage-museum-animatronic-mr-snider-and-stuffed-mule', 'museums', 33.5299, -80.5739, 'Elloree', 'SC', 'Elloree’s local-history museum contains an unexpectedly theatrical recreation of an old general store featuring an animatronic shopkeeper, Mr. Snider, along with a preserved mule and other artifacts. The moving figure gives the small-town museum a distinctly OddWay quality.', 'limited', null, 'https://www.elloreemuseum.org/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Emerald Hollow Mine', 'emerald-hollow-mine', 'museums', 35.91373, -81.0829, 'Hiddenite', 'NC', 'This working mineral site allows visitors to prospect for emeralds, hiddenite, quartz, sapphires, garnets, and other stones by sluicing, creeking, or digging. The mine promotes itself as the only emerald mine in the United States open to public prospecting. Location reference: https://rockhoundr.com/emerald-hollow-mine-hiddenite-north-carolina/', 'limited', null, 'https://www.emeraldhollowmine.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Endicott Pear Tree', 'endicott-pear-tree', 'museums', 42.54822, -70.93006, 'Danvers', 'MA', 'Traditionally dated to the 1630s, this ancient pear tree is often called the oldest cultivated fruit tree in North America. It has survived storms, vandalism and centuries of development and still produces fruit, although access is restricted because it stands on private corporate property.', 'limited', null, 'https://www.atlasobscura.com/places/endicott-pear-tree', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eric Carle Museum of Picture Book Art', 'eric-carle-museum-of-picture-book-art', 'museums', 42.32109, -72.53298, 'Amherst', 'MA', 'A museum devoted specifically to picture-book illustration celebrates the visual worlds of Eric Carle and other children''s artists. Rotating exhibits expose original artwork and process material normally hidden behind familiar printed books.', 'limited', null, 'https://www.carlemuseum.org/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ernest Warther Museum & Gardens', 'ernest-warther-museum-gardens', 'museums', 40.52566, -81.48804, 'Dover', 'OH', 'Master carver Ernest "Mooney" Warther spent decades creating extraordinarily detailed working models of steam engines from wood, ivory and other materials. His workshop, family home, carvings, button collection and gardens are preserved together as a museum complex that visitors can tour during posted hours.', 'open', null, 'https://thewarthermuseum.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ernie Pyle World War II Museum', 'ernie-pyle-world-war-ii-museum', 'museums', 39.80438, -87.49514, 'Dana', 'IN', 'Pulitzer Prize-winning war correspondent Ernie Pyle was born outside the tiny town of Dana, and his birthplace farmhouse has been preserved beside museum galleries housed in Quonset-style buildings. The exhibits focus on Pyle''s reporting and the ordinary soldiers whose experiences made his wartime columns famous.', 'limited', null, 'https://erniepyle.org/visit-the-ernie-pyle-wwii-museum/', '2026-09-08T13:34:34.826362+00:00', null, 'https://erniepyle.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Estey Organ Museum', 'estey-organ-museum', 'museums', 42.84738, -72.56655, 'Brattleboro', 'VT', 'Brattleboro once produced hundreds of thousands of reed and pipe organs under the Estey name. The museum occupies part of the old factory complex and preserves instruments, manufacturing history and machinery from a company whose organs were shipped around the world.', 'limited', null, 'https://www.atlasobscura.com/places/estey-organ-museum', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Experimental Balloon and Airship Museum', 'experimental-balloon-and-airship-museum', 'museums', 43.88372, -72.25208, 'Post Mills', 'VT', 'The late balloonist and inventor Brian Boland assembled an eccentric collection of experimental balloons, airships, machinery and aviation debris at Post Mills Airport. Public access is limited, but the surviving collection remains a remarkable monument to homemade flight and mechanical experimentation.', 'limited', null, 'https://www.roadsideamerica.com/story/70883', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fairbanks Museum and Planetarium', 'fairbanks-museum-and-planetarium', 'museums', 44.42005, -72.01985, 'St. Johnsbury', 'VT', 'Founded from Franklin Fairbanks''s Victorian natural-history collection, this museum still feels like an enormous old curiosity cabinet. Tens of thousands of specimens include taxidermy, birds, insects, ethnographic material and scientific objects displayed inside an equally distinctive nineteenth-century building.', 'open', null, 'https://www.atlasobscura.com/places/fairbanks-museum-and-planetarium', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fiberglass Freaks'' Batman Museum', 'fiberglass-freaks-batman-museum', 'museums', 40.75303, -86.36319, 'Logansport', 'IN', 'Fiberglass Freaks opened its expanded downtown museum in 2024 as a tribute to the 1966 Batman television series and related superhero history. Displays include thousands of items, recreated environments and Batmobile-related material assembled by a builder known for licensed replicas of the show''s famous car.', 'open', null, 'https://fiberglassfreaksmuseum.com/', '2026-09-08T13:53:25.695107+00:00', null, 'https://fiberglassfreaksmuseum.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Finny — 50-Foot Whale Skeleton', 'finny-50-foot-whale-skeleton', 'museums', 43.83941, -70.12115, 'Freeport', 'ME', 'A roughly 50-foot fin-whale skeleton nicknamed “Finny” hangs overhead inside Maine Beer Company’s Freeport facility. The enormous specimen turns a commercial stop into an unexpected natural-history display and was installed after the whale’s remains were recovered and prepared for exhibition.', 'open', null, 'https://www.atlasobscura.com/places/maine-beer-company', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Flatwoods Monster Museum', 'flatwoods-monster-museum', 'museums', 38.6651, -80.7059, 'Sutton', 'WV', 'In September 1952 a group of Braxton County children went up a hill after a light in the sky and came back down describing something ten feet tall in a pleated metal skirt. The museum grew out of a single display case in the county visitor centre and now holds the clippings, the witness accounts and a wall of Flatwoods Monster memorabilia. Admission is free, and it doubles as the Braxton County Visitors Center.', 'open', null, 'https://braxtonwv.org/the-flatwoods-monster/visit-the-museum/', '2026-09-06T01:56:28.154232+00:00', null, null, null, null, null, 'America/New_York'),
  ('Flexible Flyer Museum', 'flexible-flyer-museum', 'museums', 39.96475, -74.95025, 'Moorestown', 'NJ', 'A small display inside the Moorestown Library preserves the history of Samuel Leeds Allen''s Flexible Flyer, one of America''s most famous sled designs. Vintage sleds, photographs and manufacturing material document the locally invented winter icon.', 'limited', null, 'https://www.roadsideamerica.com/tip/4852', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Forbes Pigment Collection', 'forbes-pigment-collection', 'museums', 42.37418, -71.11408, 'Cambridge', 'MA', 'Thousands of pigment samples at Harvard range from rare mineral colors to historically toxic compounds and the infamous ''mummy brown,'' once manufactured using ground Egyptian remains. The collection belongs to the museum''s conservation department; portions can be seen from public museum space, while direct research access is restricted.', 'limited', null, 'https://www.atlasobscura.com/places/forbes-pigment-collection', '2026-09-09T04:43:56.902716+00:00', null, 'https://harvardartmuseums.org/', null, null, null, 'America/New_York'),
  ('Fort St. Jean Baptiste State Historic Site', 'fort-st-jean-baptiste-state-historic-site', 'museums', 31.75127, -93.08809, 'Natchitoches', 'LA', 'A reconstruction of the early French fort on Cane River uses period methods and materials to interpret colonial life and regional trade. The recreated stockade gives travelers a rare immersive stop from Louisiana''s pre-American period.', 'open', null, 'https://www.lastateparks.com/historic-sites/fort-st-jean-baptiste-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fostoria Glass Museum', 'fostoria-glass-museum', 'museums', 39.91956, -80.74539, 'Moundsville', 'WV', 'This museum preserves glass made by the Fostoria Glass Company, which moved from Ohio to Moundsville in 1891 and became one of the city''s major manufacturers. Displays include tableware, specialty pieces and company history, with limited seasonal afternoon hours rather than daily year-round access.', 'limited', null, 'https://www.fostoriaglass.org/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Franklin Mineral Museum', 'franklin-mineral-museum', 'museums', 41.11361, -74.58889, 'Franklin', 'NJ', 'Franklin sits in one of the world''s most famous fluorescent-mineral districts, and this museum preserves thousands of local mineral specimens along with mining and geology exhibits. Its displays make visible the unusual colors and mineral diversity that earned the area an international reputation.', 'limited', null, 'https://franklinmineralmuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frost Entomological Museum', 'frost-entomological-museum', 'museums', 40.80296, -77.86241, 'State College', 'PA', 'Penn State''s entomology museum maintains a research collection of more than one million arthropod specimens representing thousands of species. A free public gallery displays insects, collecting equipment and other entomological material on weekdays during university operating hours.', 'open', null, 'https://ento.psu.edu/about/facilities/frost/visit', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gary Bowling''s House of Art', 'gary-bowlings-house-of-art', 'museums', 37.26753, -81.22354, 'Bluefield', 'WV', 'This Appalachian art center occupies the former Ramsey School, a 1926 hillside building with entrances on seven different levels. Inside are rotating works by regional artists, but hours are limited and appointment visits are also used, so check before making a dedicated detour.', 'limited', null, 'https://visitmercercounty.com/company/gary-bowlings-house-of-art/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Geodetic Survey Stones', 'geodetic-survey-stones', 'museums', 35.78044, -78.63995, 'Raleigh', 'NC', 'A small arrangement of precisely placed stones on the State Capitol grounds looks like a miniature Stonehenge. The stones mark an 1850s geodetic experiment that used star observations, telegraph communication, and simultaneous measurements to establish accurate latitude and longitude.', 'open', null, 'https://www.atlasobscura.com/places/geodetic-survey-stones', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('George Peabody Library', 'george-peabody-library', 'museums', 39.2972, -76.61502, 'Baltimore', 'MD', 'Completed in the 19th century, the Peabody Library''s soaring atrium is lined with multiple tiers of cast-iron balconies and hundreds of thousands of books. Often described as a cathedral of books, the historic research library is open to visitors during posted public hours when not closed for events.', 'open', null, 'https://www.atlasobscura.com/places/george-peabody-library', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gertrude Chandler Warner Boxcar Children Museum', 'gertrude-chandler-warner-boxcar-children-museum', 'museums', 41.90946, -71.90347, 'Putnam', 'CT', 'Putnam honors Boxcar Children author Gertrude Chandler Warner with a museum housed inside a real 1920s railroad boxcar. The tiny seasonal museum contains books, memorabilia and personal objects connected with the author.', 'limited', null, 'https://www.roadsideamerica.com/tip/10028', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gilboa Fossil Forest', 'gilboa-fossil-forest', 'museums', 42.40046, -74.45014, 'Gilboa', 'NY', 'Gilboa became famous after quarrying exposed fossilized tree stumps from one of the oldest known forests on Earth, dating back roughly 380 million years. The local museum and outdoor fossil displays preserve examples from the site, with regular public hours concentrated on summer and early-fall weekends.', 'limited', null, 'https://www.atlasobscura.com/places/gilboa-fossil-forest', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gilmore Car Museum', 'gilmore-car-museum', 'museums', 42.43978, -85.42007, 'Hickory Corners', 'MI', 'More than 400 vehicles fill a sprawling 90-acre campus of historic barns, recreated dealerships and automotive displays. The scale, unusual prototypes and preserved pieces of roadside motoring culture make Gilmore much more than a conventional rows-of-cars museum.', 'open', null, 'https://gilmorecarmuseum.org/', '2026-09-08T14:53:55.160019+00:00', null, 'https://gilmorecarmuseum.org/', null, null, null, 'America/Detroit'),
  ('Glen Haven Cannery Boat Museum', 'glen-haven-cannery-boat-museum', 'museums', 44.90154, -86.02815, 'Glen Arbor', 'MI', 'A former fruit cannery in the historic village of Glen Haven now houses a collection of traditional Great Lakes and inland-water boats. Dugout canoes, fishing craft and lifesaving vessels fill the bright red building, combining unusual maritime artifacts with the preserved remains of a once-busy Lake Michigan port.', 'limited', null, 'https://www.atlasobscura.com/places/cannery-boat-museum', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Glencairn Museum', 'glencairn-museum', 'museums', 40.13694, -75.06389, 'Bryn Athyn', 'PA', 'Glencairn is a castle-like former residence built between the 1920s and 1930s for the Pitcairn family and now used as a museum of religious art and history. Its galleries contain medieval stained glass, ancient artifacts and objects from religious traditions around the world, with access through the museum''s posted visit schedule.', 'open', null, 'https://www.glencairnmuseum.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gold Coast Railroad Museum', 'gold-coast-railroad-museum', 'museums', 25.61622, -80.39974, 'Miami', 'FL', 'Rail museum with historic locomotives, presidential railcars, and unusual rolling stock.', 'limited', null, 'https://www.goldcoastrailroadmuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Granville Whiskey Decanter Museum', 'granville-whiskey-decanter-museum', 'museums', 36.27175, -85.79708, 'Granville', 'TN', 'Historic Granville displays roughly 5,000 limited-edition whiskey decanters shaped like vehicles, people, animals, landmarks and other objects. The collection is promoted as the world''s largest of its kind and operates on Granville''s limited weekly museum schedule.', 'limited', null, 'https://www.granvilletn.com/whiskey-decanter-museum', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Great American Alligator Museum', 'great-american-alligator-museum', 'museums', 29.93034, -90.07575, 'New Orleans', 'LA', 'This Magazine Street museum is devoted to the American alligator in Louisiana culture, history, science and popular imagery. It turns a single animal into a focused, unusually specific museum experience.', 'open', null, 'https://www.gator-museum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Great American Dollhouse Museum', 'great-american-dollhouse-museum', 'museums', 37.65005, -84.77803, 'Danville', 'KY', 'More than 200 dollhouses and miniature room boxes form a densely detailed fictional American town and surrounding countryside. Tiny businesses, homes and historical scenes are filled with hidden jokes and objects, making this one of Kentucky''s most distinctive miniature museums.', 'open', null, 'https://thedollhousemuseum.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://thedollhousemuseum.com/', null, null, null, 'America/New_York'),
  ('Great Lakes Maritime Heritage Center', 'great-lakes-maritime-heritage-center', 'museums', 45.06698, -83.43282, 'Alpena', 'MI', 'NOAA''s free visitor center interprets the extraordinary concentration of shipwrecks protected in Thunder Bay National Marine Sanctuary. Visitors can walk through a life-size schooner recreation, experience a simulated Great Lakes storm and examine enormous timbers from wrecked vessels without going underwater.', 'open', null, 'https://thunderbay.noaa.gov/visit/great-lakes-maritime-heritage-center.html', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Great Lakes Shipwreck Museum', 'great-lakes-shipwreck-museum', 'museums', 46.77056, -84.95667, 'Paradise', 'MI', 'Whitefish Point has witnessed some of Lake Superior''s most notorious maritime disasters, and its museum preserves artifacts recovered from Great Lakes wrecks. The collection''s centerpiece is the bell recovered from the Edmund Fitzgerald, displayed as a memorial to the ship''s 29 crew members.', 'limited', null, 'https://shipwreckmuseum.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://shipwreckmuseum.com/', null, null, null, 'America/Detroit'),
  ('Grissom Air Museum', 'grissom-air-museum', 'museums', 40.66952, -86.13061, 'Peru', 'IN', 'Located just outside the former Grissom Air Force Base, the museum preserves a large outdoor air park of military aircraft along with indoor Cold War and aviation exhibits. The collection includes fighters, bombers, transports and other aircraft that make the site visually distinct from a conventional local museum.', 'limited', null, 'https://www.grissomairmuseum.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.grissomairmuseum.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Gus Grissom Boyhood Home', 'gus-grissom-boyhood-home', 'museums', 38.72994, -86.47267, 'Mitchell', 'IN', 'Virgil "Gus" Grissom grew up in this modest Mitchell house before becoming one of the original Mercury Seven astronauts and later commanding Gemini 3. The preserved home is operated as a small museum devoted to his childhood and early life, providing a more personal counterpoint to large space museums.', 'limited', null, 'https://www.hmdb.org/m.asp?m=195330', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Gwen Frostic Prints', 'gwen-frostic-prints', 'museums', 44.61911, -86.13728, 'Benzonia', 'MI', 'Artist Gwen Frostic created her nature-inspired block prints inside a remarkable boulder-and-timber studio built into the northern Michigan landscape. Vintage Heidelberg presses still produce work from her original designs, and the studio can be visited during its seasonal operating period.', 'limited', null, 'https://www.atlasobscura.com/places/gwen-frostic-prints-2', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Haddam Shad Museum', 'haddam-shad-museum', 'museums', 41.50003, -72.5657, 'Haddam', 'CT', 'A tiny museum dedicated almost entirely to the Connecticut River''s historic shad-fishing industry preserves nets, tools, boats, photographs and wonderfully specific fish-related artifacts. It traditionally opens only during the spring shad season and by appointment.', 'limited', null, 'https://www.atlasobscura.com/places/haddam-shad-museum', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hagenbeck-Wallace Circus Diorama', 'hagenbeck-wallace-circus-diorama', 'museums', 38.54896, -86.6204, 'French Lick', 'IN', 'The French Lick West Baden Museum houses an enormous miniature circus display devoted to the Hagenbeck-Wallace Circus, which once wintered in nearby Peru. The museum describes the sprawling model as containing well over 150,000 individual pieces, creating a dense miniature world of tents, wagons, performers and animals.', 'open', null, 'https://www.flwbmuseum.com/', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.flwbmuseum.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Hall of Heroes Superhero Museum', 'hall-of-heroes-superhero-museum', 'museums', 41.71065, -85.97253, 'Elkhart', 'IN', 'The Hall of Heroes is a museum devoted specifically to the history of superheroes across comics, film, animation, toys and related memorabilia. Its large collection includes rare comics, original art and screen-related artifacts, giving OddWay a strong niche museum stop rather than a general history museum.', 'limited', null, 'https://hallofheroesmuseum.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://hallofheroesmuseum.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Hamlin Memorial Library & Museum — Museum in a Jail', 'hamlin-memorial-library-museum-museum-in-a-jail', 'museums', 44.26011, -70.50221, 'South Paris', 'ME', 'This local library and museum occupies Oxford County’s former stone jail, giving visitors a chance to see historic cells alongside collections tied to the area and the Hamlin family. The unusual reuse leaves much of the old lockup atmosphere intact instead of disguising the building’s original purpose.', 'limited', null, 'https://www.hamlin.lib.me.us/contact_us.html', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harland Sanders Cafe and Museum', 'harland-sanders-cafe-and-museum', 'museums', 36.95993, -84.09375, 'Corbin', 'KY', 'Colonel Harland Sanders developed the recipe and restaurant operation that became Kentucky Fried Chicken at this roadside cafe. The restored site combines an operating KFC with museum displays and a reconstruction of Sanders'' original kitchen, motel room and early restaurant equipment.', 'open', null, 'https://www.roadsideamerica.com/location/ky/all', '2026-09-08T14:42:00.461026+00:00', null, 'https://www.kfc.com/harrland-sanders-cafe-and-museum', null, null, null, 'America/New_York'),
  ('Harley-Davidson Museum', 'harley-davidson-museum', 'museums', 43.03182, -87.91639, 'Milwaukee', 'WI', 'Harley-Davidson''s museum preserves motorcycles ranging from the company''s earliest machines to racing bikes, custom motorcycles and famous one-offs. The industrial campus and rows of historic machines make it a strong mechanical-history stop even for travelers who are not riders.', 'open', null, 'https://www.harley-davidson.com/us/en/experiences/museum.html', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.harley-davidson.com/us/en/experiences/museum.html', null, null, null, 'America/Chicago'),
  ('Harrison Brothers Hardware', 'harrison-brothers-hardware', 'museums', 34.72981, -86.58433, 'Huntsville', 'AL', 'Operating in a downtown storefront dating to the nineteenth century, Harrison Brothers preserves old counters, fixtures and merchandise displays while still functioning as a shop. It feels like a hardware store frozen between museum and working business.', 'open', null, 'https://harrisonbrothershardware.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hasbro Gameland', 'hasbro-gameland', 'museums', 42.1045, -72.58742, 'Springfield', 'MA', 'Inside the Springfield History Museum, an interactive exhibit celebrates Milton Bradley and the games later associated with Hasbro. Oversized and playable elements turn board-game history into a hands-on museum stop.', 'limited', null, 'https://www.atlasobscura.com/places/hasbro-gameland-exhibit', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Havre de Grace Decoy Museum', 'havre-de-grace-decoy-museum', 'museums', 39.53966, -76.08693, 'Havre de Grace', 'MD', 'The Decoy Museum preserves the Chesapeake Bay tradition of carved waterfowl decoys, working boats, hunting gear and folk art. Its large collection includes historic and contemporary carvings that turn an otherwise ordinary hunting tool into a distinctly regional art form.', 'open', null, 'https://www.decoymuseum.com/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Henager''s Memories and Nostalgia Museum', 'henagers-memories-and-nostalgia-museum', 'museums', 38.23142, -87.42672, 'Buckskin', 'IN', 'James Henager assembled a sprawling rural collection of tens of thousands of nostalgic objects, including toys, military items, advertising pieces, radios and pop-culture memorabilia. Because this is a small independently operated museum at 8837 S. State Road 57, travelers should verify current hours before making it a major detour.', 'limited', null, 'https://www.roadsideamerica.com/tip/15491', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Henry Sheldon Museum of Vermont History', 'henry-sheldon-museum-of-vermont-history', 'museums', 44.01255, -73.16998, 'Middlebury', 'VT', 'Founded in 1882, this long-running local museum grew from Henry Sheldon''s intensely personal collecting habits. Its holdings mix documents, household objects, art and regional artifacts into the kind of broad nineteenth-century collection that predates today''s highly specialized museums.', 'limited', null, 'https://www.henrysheldonmuseum.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Heritage Farm Museum & Village', 'heritage-farm-museum-village', 'museums', 38.37643, -82.46994, 'Huntington', 'WV', 'Heritage Farm recreates an Appalachian village with historic-style buildings, craft demonstrations, machinery and multiple museums devoted to regional life. The attraction first opened in the 1990s and now operates on a seasonal schedule, so check current dates before routing travelers there.', 'limited', null, 'https://www.heritagefarmwv.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Heritage Glass Museum', 'heritage-glass-museum', 'museums', 39.70267, -75.11067, 'Glassboro', 'NJ', 'Glassboro''s name reflects the industry that shaped the community, and this small museum preserves bottles, tools and locally manufactured glass from that history. Its specialized collection gives travelers a compact look at an industry that once dominated the region.', 'limited', null, 'https://www.glassborohistory.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hidden South — The Confessional', 'hidden-south-the-confessional', 'museums', 29.95622, -90.00146, 'Arabi', 'LA', 'Hidden South''s gallery and shop grew from photographer Brent Walker''s documentation of overlooked people, places and folk art across the South. The space functions as a compact museum-store for outsider culture and unusual regional stories.', 'open', null, 'https://thehiddensouth.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Historic Auto Attractions', 'historic-auto-attractions', 'museums', 42.46141, -89.01412, 'Roscoe', 'IL', 'An enormous private museum mixing celebrity vehicles, presidential artifacts, movie props, military displays, crime-history objects, and other eclectic Americana.', 'limited', null, 'https://historicautoattractions.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Historic RailPark and Train Museum', 'historic-railpark-and-train-museum', 'museums', 37.00018, -86.43826, 'Bowling Green', 'KY', 'Bowling Green''s restored Louisville & Nashville depot now anchors a museum where visitors can tour historic railroad cars rather than simply view them behind barriers. The collection includes passenger and service cars that preserve the strange, self-contained world of long-distance rail travel.', 'limited', null, 'https://www.historicrailpark.com/museum/', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.historicrailpark.com/', null, null, null, 'America/Chicago'),
  ('History Museum at the Castle', 'history-museum-at-the-castle', 'museums', 44.26186, -88.40216, 'Appleton', 'WI', 'A dramatic former Masonic temple now houses local-history exhibits, including material on Appleton native Harry Houdini. The castle-like building and recurring focus on magic, invention and Fox Valley history make it more unusual than a conventional county museum.', 'open', null, 'https://www.myhistorymuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.myhistorymuseum.org/', null, null, null, 'America/Chicago'),
  ('History of Diving Museum', 'history-of-diving-museum', 'museums', 24.92477, -80.62983, 'Islamorada', 'FL', 'Huge collection of antique diving helmets, suits, and underwater exploration equipment.', 'limited', null, 'https://divingmuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('History of the Florida Keys Museum', 'history-of-the-florida-keys-museum', 'museums', 24.92211, -80.62804, 'Islamorada', 'FL', 'Local museum focused on hurricanes, wreckers, railroads, Indigenous history, and Keys folklore.', 'limited', null, 'https://keysdiscovery.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('H.J. Smith''s Sons General Store & Museum', 'hj-smiths-sons-general-store-museum', 'museums', 30.47604, -90.09427, 'Covington', 'LA', 'Behind a functioning old general store is an eclectic free museum of tools, farm equipment, household objects, weapons and regional artifacts accumulated over generations. The result feels more like a family cabinet of curiosities than a polished museum.', 'open', null, 'https://www.covla.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Holmes Medical Museum', 'holmes-medical-museum', 'museums', 30.40616, -87.6848, 'Foley', 'AL', 'Foley’s first hospital has been preserved with operating-room equipment, patient rooms, instruments and displays of medical quackery. The old tools and intact hospital spaces make it one of Alabama’s best medical-curiosity museums.', 'limited', null, 'https://foleyhistoricalarchives.com/holmes-medical-museum/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Holyoke''s Frog Circus', 'holyokes-frog-circus', 'museums', 42.20479, -72.61735, 'Holyoke', 'MA', 'A miniature circus populated by taxidermied frogs performs frozen acrobatics inside the Wistariahurst visitor area. The bizarre tableau belongs to a long tradition of anthropomorphic taxidermy and is one of Massachusetts'' smallest but most memorable museum oddities. Check current visitor-center hours.', 'limited', null, 'https://www.atlasobscura.com/places/holyoke-frog-circus', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Houdini Museum', 'houdini-museum', 'museums', 41.4326, -75.66307, 'Scranton', 'PA', 'This Scranton museum is devoted to escape artist and magician Harry Houdini, with memorabilia, photographs, props and material examining his career and his campaigns against fraudulent spiritualists. Visits are structured as scheduled museum-and-magic experiences rather than ordinary anytime walk-in admission.', 'limited', null, 'https://www.houdinimuseum.net/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('House of Dance & Feathers', 'house-of-dance-feathers', 'museums', 29.95187, -90.00428, 'New Orleans', 'LA', 'This Lower Ninth Ward community collection documents Mardi Gras Indians, second lines, social aid and pleasure clubs and neighborhood culture. It has historically operated more like a living community archive than a conventional museum, so arrange access before going.', 'limited', null, 'https://houseofdanceandfeathers.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('House of Frankenstein Wax Museum', 'house-of-frankenstein-wax-museum', 'museums', 43.42436, -73.71361, 'Lake George', 'NY', 'This old-fashioned horror wax museum fills a Canada Street building with moving monsters, gruesome tableaux and classic horror characters. It operates seasonally in Lake George, so current opening dates should be checked before treating it as a guaranteed walk-in stop.', 'limited', null, 'https://frankensteinwaxmuseum.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hugh Mercer Apothecary Shop', 'hugh-mercer-apothecary-shop', 'museums', 38.30409, -77.45987, 'Fredericksburg', 'VA', 'This restored 18th-century apothecary interprets medicine from an era when treatments included bloodletting, leeches, lancets, snakeroot and other remedies that look alarming by modern standards. Costumed interpretation and demonstrations make the small museum much stranger than a conventional colonial house tour.', 'limited', null, 'https://washingtonheritagemuseums.org/hugh-mercer-apothecary-shop/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Illinois Route 66 Hall of Fame & Museum', 'illinois-route-66-hall-of-fame-museum', 'museums', 40.88095, -88.62904, 'Pontiac', 'IL', 'A free museum packed with road signs, vehicles, memorabilia, photographs, and stories from the Illinois section of the Mother Road.', 'limited', null, 'https://visitpontiac.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Indiana Dinosaur Museum', 'indiana-dinosaur-museum', 'museums', 41.70768, -86.34659, 'South Bend', 'IN', 'This newer South Bend museum is devoted to dinosaurs and paleontology, with large fossil displays, mounted skeletons and working scientific material rather than only fiberglass roadside models. Its unusual pairing with the adjacent South Bend Chocolate Company destination makes it a strong family-friendly OddWay stop.', 'limited', null, 'https://www.indianadinosaurmuseum.org/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.indianadinosaurmuseum.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Indiana Medical History Museum', 'indiana-medical-history-museum', 'museums', 39.7699, -86.21336, 'Indianapolis', 'IN', 'The museum occupies the 1896 Old Pathology Building of the former Central State Hospital, the oldest surviving pathology facility in the United States. Guided tours retain original laboratories, an autopsy room and an anatomical museum containing preserved specimens, while the remaining former hospital buildings and tunnels elsewhere on the property are posted no-trespassing.', 'limited', null, 'https://www.imhm.org/about/', '2026-09-08T13:20:58.818667+00:00', null, 'https://imhm.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('InfoAge Science & History Museums — Historic Camp Evans', 'infoage-science-history-museums-historic-camp-evans', 'museums', 40.18596, -74.06158, 'Wall Township', 'NJ', 'The former Camp Evans military research complex now contains more than 20 museums and exhibits devoted to radio, radar, computing, military technology, spaceflight and other scientific history. The site preserves buildings tied to early wireless communication and World War II radar research.', 'limited', null, 'https://www.infoage.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Insectropolis', 'insectropolis', 'museums', 40.01493, -74.21631, 'Toms River', 'NJ', 'New Jersey''s "Bugseum" is devoted entirely to insects and other arthropods, with live specimens, preserved collections and interactive displays. Scheduled touch presentations give visitors a chance to meet some of the museum''s stranger living residents.', 'limited', null, 'https://insectropolis.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('International Circus Hall of Fame', 'international-circus-hall-of-fame', 'museums', 40.75444, -86.01972, 'Peru', 'IN', 'The museum occupies part of the former Wallace Circus winter quarters, a site that helped make Peru one of America''s most important circus towns. Historic wagons, circus buildings, memorabilia and performers'' history survive on the property, which is designated a National Historic Landmark.', 'limited', null, 'https://circushalloffame.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://circushalloffame.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('International Clown Hall of Fame and Research Center', 'international-clown-hall-of-fame-and-research-center', 'museums', 43.47115, -89.74273, 'Baraboo', 'WI', 'This museum preserves costumes, props, portraits, tiny cars and archival material from notable clowns and circus performers. Located in circus-heavy Baraboo, it gives OddWay a concentrated collection devoted to one of entertainment history''s strangest professions.', 'open', null, 'https://www.theclownmuseum.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.theclownmuseum.com/', null, null, null, 'America/Chicago'),
  ('International Independent Showmen''s Museum', 'international-independent-showmens-museum', 'museums', 27.81189, -82.31948, 'Riverview', 'FL', 'Huge museum devoted to carnival, circus, midway, and traveling-show history.', 'limited', null, 'https://showmensmuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('International Lineman Museum', 'international-lineman-museum', 'museums', 35.25624, -81.48236, 'Shelby', 'NC', 'A museum devoted entirely to electrical lineworkers preserves old climbing equipment, hot sticks, pliers, insulators, meter boxes, cutouts, and even the upper portion of an early-1900s utility pole. It turns a profession most travelers rarely think about into a specialized historical collection.', 'limited', null, 'https://www.atlasobscura.com/places/international-lineman-museum', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('International Monster Truck Museum & Hall of Fame', 'international-monster-truck-museum-hall-of-fame', 'museums', 41.42985, -84.88196, 'Butler', 'IN', 'This museum preserves the history of monster trucks through full-size historic trucks, photographs, memorabilia and a hall of fame devoted to the sport''s major builders and drivers. The rotating vehicle lineup makes it a particularly strong automotive OddWay stop.', 'open', null, 'https://monstermuseum.org/', '2026-09-08T13:53:25.695107+00:00', null, 'https://monstermuseum.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('International Motorsports Hall of Fame', 'international-motorsports-hall-of-fame', 'museums', 33.57821, -86.07239, 'Talladega', 'AL', 'Beside Talladega Superspeedway, the museum and Hall of Fame display race cars, motorcycles, trophies and artifacts covering many forms of motorsport. The collection includes machines tied to record runs and major racing figures.', 'open', null, 'https://www.motorsportshalloffame.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('International Museum of Surgical Science', 'international-museum-of-surgical-science', 'museums', 41.91031, -87.62661, 'Chicago', 'IL', 'A mansion packed with antique surgical instruments, anatomical art, early medical equipment, and enough historical medicine to make this a natural OddWay stop.', 'limited', null, 'https://imss.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('International Paranormal Museum and Research Center', 'international-paranormal-museum-and-research-center', 'museums', 37.09226, -84.60419, 'Somerset', 'KY', 'This small downtown museum is dedicated to paranormal claims, cryptids, UFOs and unexplained phenomena. Displays include investigation equipment, unusual artifacts, research material and rotating pieces tied to ghost stories and other unexplained events.', 'open', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('International Towing & Recovery Museum', 'international-towing-recovery-museum', 'museums', 35.01692, -85.32315, 'Chattanooga', 'TN', 'Antique wreckers, towing equipment and industry artifacts fill a museum devoted to the tow-truck trade, which has deep roots in Chattanooga. The Wall of the Fallen also memorializes operators killed while working roadside recoveries.', 'open', null, 'https://towingmuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('James Dean Museum and Garfield Museum', 'james-dean-museum-and-garfield-museum', 'museums', 40.41582, -85.65035, 'Fairmount', 'IN', 'Fairmount manages to combine two very different pieces of pop culture in one small museum: hometown actor James Dean and Garfield creator Jim Davis, who grew up nearby. The collection contains Dean memorabilia alongside Garfield material, including a Garfield Trail statue dressed as Dean.', 'limited', null, 'https://www.atlasobscura.com/places/james-dean-museum-and-garfield-museum', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Japanese Giant Spider Crab — Rutgers Geology Museum', 'japanese-giant-spider-crab-rutgers-geology-museum', 'museums', 40.49864, -74.44667, 'New Brunswick', 'NJ', 'Rutgers University''s geology museum contains fossils, minerals, dinosaurs and an enormous preserved Japanese spider crab with an extraordinary leg span. The nineteenth-century museum is free, but public hours follow the university''s schedule.', 'limited', null, 'https://geologymuseum.rutgers.edu/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jell-O Gallery Museum', 'jell-o-gallery-museum', 'museums', 42.97885, -77.98569, 'Le Roy', 'NY', 'Jell-O was developed in Le Roy in 1897, and this museum preserves advertising, packaging, recipes and artifacts from the dessert''s unusually successful history. The gallery operates seasonally from spring until shortly before Christmas, so check its current schedule before routing here.', 'limited', null, 'https://leroyhistoricalsociety.org/visit-us/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jesse Brent Lower Mississippi River Museum', 'jesse-brent-lower-mississippi-river-museum', 'museums', 32.35343, -90.88185, 'Vicksburg', 'MS', 'A free U.S. Army Corps of Engineers museum about the Mississippi River, flood control and river life, including an outdoor scale river model and the retired Motor Vessel Mississippi IV. The combination of engineering history, flood disasters and a walk-through workboat gives it strong OddWay value. Coordinate source: https://www.atlasobscura.com/places/lower-mississippi-river-museum', 'open', null, 'https://www.mvk.usace.army.mil/Missions/Recreation/Lower-Mississippi-River-Museum/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('John Hay Library', 'john-hay-library', 'museums', 41.82592, -71.40458, 'Providence', 'RI', 'Brown University''s John Hay Library preserves major H.P. Lovecraft collections along with unusual rare books and artifacts. The library has also become known for books in Brown''s collections that were historically bound in human skin. Public access is possible during designated service hours, but identification and current visitor rules should be checked before arrival.', 'limited', null, 'https://www.atlasobscura.com/places/john-hay-library', '2026-09-09T04:49:27.913704+00:00', null, 'https://library.brown.edu/hay/', null, null, null, 'America/New_York'),
  ('Johnson-Shaw Stereoscopic Museum', 'johnson-shaw-stereoscopic-museum', 'museums', 41.63738, -80.1469, 'Meadville', 'PA', 'Meadville was once home to the Keystone View Company, which became one of the world''s largest producers of stereoscopic photographs. This small museum preserves cameras, viewers and three-dimensional image sets from that industry and is normally open Saturdays from April through November, with other visits by appointment.', 'limited', null, 'https://www.johnsonshawmuseum.org/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Joseph Barratt''s Grave', 'joseph-barratts-grave', 'museums', 41.55841, -72.66281, 'Middletown', 'CT', 'Physician and amateur naturalist Joseph Barratt chose a fittingly strange monument: his grave incorporates casts connected with Connecticut dinosaur tracks and fossil plant material. It is an eccentric intersection of nineteenth-century science and funerary art.', 'open', null, 'https://www.atlasobscura.com/places/joseph-barratts-grave', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kazoobie Kazoo Museum', 'kazoobie-kazoo-museum', 'museums', 32.43468, -80.72016, 'Beaufort', 'SC', 'Hundreds of kazoos and related instruments trace the surprisingly elaborate history of one of the world’s simplest musical devices. Visitors can see unusual novelty kazoos, historic examples, and the manufacturing operation that still produces the instruments.', 'open', null, 'https://www.atlasobscura.com/places/kazoo-museum', '2026-09-09T05:53:13.784429+00:00', null, 'https://kazoomuseum.org/', null, null, null, 'America/New_York'),
  ('Kenneth E. Stoddard Shell Museum', 'kenneth-e-stoddard-shell-museum', 'museums', 43.90734, -69.6166, 'Boothbay', 'ME', 'Thousands of seashells from around the world fill a covered-bridge-style structure at the Dolphin Mini Golf property. The dense collection ranges from familiar Maine shells to exotic specimens and is generally tied to the property’s seasonal schedule.', 'limited', null, 'https://www.atlasobscura.com/places/kenneth-e-stoddard-shell-museum', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kentucky Coal Museum', 'kentucky-coal-museum', 'museums', 36.96425, -82.95131, 'Benham', 'KY', 'Housed in the former company store of a coal town, this museum preserves mining equipment, company scrip, household artifacts and a recreated underground mine environment. The building''s solar-panel installation also became nationally notable because a museum devoted to coal partially powers itself with solar energy.', 'open', null, 'https://kycoalmuseum.southeast.kctcs.edu/', '2026-09-08T14:15:10.228298+00:00', null, 'https://kycoalmuseum.southeast.kctcs.edu/', null, null, null, 'America/New_York'),
  ('Kentucky Folk Art Center', 'kentucky-folk-art-center', 'museums', 38.18167, -83.43306, 'Morehead', 'KY', 'Morehead State University''s Kentucky Folk Art Center preserves a large collection of work by self-taught and Appalachian artists. The collection''s carved figures, visionary art and unconventional materials make it much stranger and more personal than a conventional fine-art gallery.', 'open', null, 'https://www.moreheadstate.edu/kfac/', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kentucky Military History Museum', 'kentucky-military-history-museum', 'museums', 38.1976, -84.87262, 'Frankfort', 'KY', 'Kentucky''s military museum occupies the fortress-like nineteenth-century State Arsenal, a building that looks unusually defensive even before entering. Exhibits cover weapons, military technology and Kentuckians at war, including material from the large George M. Chinn collection.', 'limited', null, 'https://history.ky.gov/visit/kentucky-military-history-museum/', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kentucky Music Hall of Fame and Museum', 'kentucky-music-hall-of-fame-and-museum', 'museums', 37.38979, -84.33175, 'Mount Vernon', 'KY', 'The museum preserves artifacts connected to Kentucky musicians across country, bluegrass, gospel, folk and other genres. Its Renfro Valley location ties the collection to one of the state''s oldest country-music entertainment traditions while providing a physical hall of fame for performers with Kentucky roots.', 'open', null, 'https://kentuckymusichalloffame.com/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kentucky Reptile Zoo', 'kentucky-reptile-zoo', 'museums', 37.79311, -83.70394, 'Slade', 'KY', 'This small zoo maintains one of the largest collections of venomous snakes in the United States and supplies venom for scientific and medical research. Visitors can see cobras, rattlesnakes, vipers and other reptiles at close range during seasonal operating hours.', 'limited', null, 'https://www.kyreptilezoo.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.kyreptilezoo.com/', null, null, null, 'America/New_York'),
  ('Kruger Street Toy & Train Museum', 'kruger-street-toy-train-museum', 'museums', 40.04055, -80.65832, 'Wheeling', 'WV', 'Opened to the public in 1998 inside a former 1906 schoolhouse, this museum is packed with model trains, dolls, games, toys and pop-culture collectibles. It maintains regular seasonal public hours and is a substantial stop rather than a single roadside display.', 'open', null, 'https://www.toyandtrain.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('KSB Miniatures Collection', 'ksb-miniatures-collection', 'museums', 38.64816, -83.76701, 'Maysville', 'KY', 'Inside the Kentucky Gateway Museum Center is an extensive collection of intricately detailed miniature rooms, buildings and objects. Displays range from domestic interiors to tiny specialty pieces such as an exceptionally small Swiss Army knife, all presented at miniature scale.', 'open', null, 'https://www.atlasobscura.com/places/kentucky-gateway-museum-center', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.kygmc.org/', null, null, null, 'America/New_York'),
  ('La Salette International Crèche Museum', 'la-salette-international-cr-che-museum', 'museums', 41.93055, -71.26231, 'Attleboro', 'MA', 'More than 1,500 Nativity scenes from over 100 countries fill the International Crèche Museum at the National Shrine of Our Lady of La Salette. The enormous collection ranges across cultures and artistic styles, making a single biblical scene repeat in hundreds of dramatically different forms.', 'open', null, 'https://lasaletteattleboroshrine.org/museum', '2026-09-09T04:43:56.902716+00:00', null, 'https://lasaletteattleboroshrine.org/museum', null, null, null, 'America/New_York'),
  ('Lackawanna Coal Mine Tour', 'lackawanna-coal-mine-tour', 'museums', 41.4167, -75.71524, 'Taylor', 'PA', 'Visitors descend roughly 300 feet underground into a former anthracite mine beneath McDade Park. Guides lead groups through old gangways and coal veins while explaining the dangerous work of northeastern Pennsylvania miners; tours operate seasonally.', 'limited', null, 'https://www.visitnepa.org/things-to-do/attractions/lackawanna-coal-mine-tour/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lakehurst Historical Society Museum', 'lakehurst-historical-society-museum', 'museums', 40.01306, -74.32028, 'Lakehurst', 'NJ', 'Inside a former Catholic church, this local museum packs together Hindenburg wreckage, airship artifacts, railroad history, a hand-carved Jersey Devil and ''Stuffy,'' a taxidermied dachshund whose damaged feet were fitted with little shoes. Public hours are limited.', 'limited', null, 'https://www.roadsideamerica.com/story/74973', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lane Motor Museum', 'lane-motor-museum', 'museums', 36.14036, -86.73444, 'Nashville', 'TN', 'This museum specializes in strange, tiny, experimental and unconventional vehicles rather than only famous sports cars. Microcars, amphibious machines, unusual prototypes and European oddities make it one of Tennessee''s strongest mechanical-curiosity museums.', 'open', null, 'https://www.lanemotormuseum.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Langsdon Mineral Collection', 'langsdon-mineral-collection', 'museums', 40.55122, -84.57146, 'Celina', 'OH', 'The Mercer County District Library displays the Ron and Ruth Langsdon Mineral Collection, containing hundreds of colorful and rare mineral specimens from around the world. The collection is free to view during library hours, with occasional guided programs offering a closer look at the specimens.', 'open', null, 'https://mercerlibrary.org/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('LARC''s Acadian Village', 'larcs-acadian-village', 'museums', 30.17665, -92.09235, 'Lafayette', 'LA', 'A collection of moved and reconstructed nineteenth-century buildings forms a small village interpreting Acadian life in South Louisiana. The site also hosts seasonal events that can change normal access.', 'open', null, 'https://www.acadianvillage.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('L.C. Bates Museum', 'lc-bates-museum', 'museums', 44.66274, -69.62694, 'Hinckley', 'ME', 'The L.C. Bates feels like an old-fashioned cabinet of curiosities preserved inside a museum, with historic taxidermy, minerals, fossils, cultural artifacts, dioramas, and unusual specimens. Among its stranger holdings are a marlin associated with Ernest Hemingway and a piece of early transatlantic cable.', 'limited', null, 'https://www.gwh.org/programs/lc-bates-museum/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lightship Overfalls', 'lightship-overfalls', 'museums', 38.77801, -75.14114, 'Lewes', 'DE', 'A preserved lightship — essentially a floating lighthouse — sits permanently moored in Lewes. The ship can be toured seasonally, while the surrounding park also includes an enormous fishing-bobber sculpture.', 'limited', null, 'https://www.roadsideamerica.com/tip/7280', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.overfalls.org/', null, null, null, 'America/New_York'),
  ('Lily Dale Museum', 'lily-dale-museum', 'museums', 42.35302, -79.3231, 'Lily Dale', 'NY', 'Lily Dale has operated as a Spiritualist community since the nineteenth century, and its museum occupies a former schoolhouse filled with photographs, documents and artifacts from generations of mediums and séances. Access is tied to the Lily Dale grounds and its seasonal programming, with a gate fee required during the summer season.', 'limited', null, 'https://www.lilydaleassembly.org/pointsofinterest', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Little Sorrel — Stonewall Jackson''s Stuffed Horse', 'little-sorrel-stonewall-jacksons-stuffed-horse', 'museums', 37.79006, -79.4358, 'Lexington', 'VA', 'Stonewall Jackson''s small sorrel horse survived the Civil War and lived for decades after the general''s death before being preserved by a taxidermist. Little Sorrel is now displayed at the VMI Museum, where visitors can see the actual mounted horse rather than a replica.', 'open', null, 'https://www.vmi.edu/museums-and-archives/vmi-museum/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Living Dead Museum', 'living-dead-museum', 'museums', 40.42916, -79.79536, 'Monroeville', 'PA', 'The Living Dead Museum sits inside Monroeville Mall, the shopping center used for George A. Romero''s 1978 *Dawn of the Dead*. The museum follows zombies through cinema and pop culture with props, memorabilia and interactive displays, turning an actual horror-film location into part of the exhibit.', 'open', null, 'https://monroevillemall.com/store/living\_dead\_museum', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Living Sharks Museum', 'living-sharks-museum', 'museums', 41.3788, -71.82991, 'Westerly', 'RI', 'Living Sharks Museum calls itself America''s first shark-history museum and uses fossils, biological material, historic artifacts and pop-culture objects to tell the story of sharks and their conservation. Its collection also includes substantial material connected to "Jaws." Admission is free, and the museum currently lists a Memorial Day through Labor Day public season.', 'limited', null, 'https://www.livingsharks.org/visit', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.livingsharks.org/', null, null, null, 'America/New_York'),
  ('Lock Museum of America', 'lock-museum-of-america', 'museums', 41.67915, -73.01242, 'Terryville', 'CT', 'Thousands of locks, keys, safes and lock-making tools fill a museum in a town once central to the American lock industry. Displays range from ancient locking concepts to an enormous cannonball safe, and the museum operates on a limited schedule.', 'limited', null, 'https://www.atlasobscura.com/places/lock-museum-of-america-connecticut', '2026-09-08T18:47:23.721893+00:00', null, 'https://lockmuseumofamerica.org/', null, null, null, 'America/New_York'),
  ('Lodge Museum of Cast Iron', 'lodge-museum-of-cast-iron', 'museums', 35.01101, -85.70276, 'South Pittsburg', 'TN', 'Lodge''s museum explains cast-iron manufacturing and cookware history while displaying an enormous skillet billed as the world''s largest. The mix of industrial history and intentionally oversized cookware makes this an especially strong OddWay museum stop.', 'open', null, 'https://www.lodgecastiron.com/pages/museum', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Longest Known Mastodon Trackway', 'longest-known-mastodon-trackway', 'museums', 42.27887, -83.73375, 'Ann Arbor', 'MI', 'Inside the University of Michigan Museum of Natural History is a roughly 40-foot cast of more than 20 mastodon footprints discovered near Saline in 1992. Individual mastodon tracks are rare, and this sequence is considered the longest known trackway made by one mastodon.', 'open', null, 'https://www.atlasobscura.com/places/longest-known-mastodon-trackway', '2026-09-08T15:31:15.588137+00:00', null, 'https://lsa.umich.edu/ummnh', null, null, null, 'America/Detroit'),
  ('Louisiana Art & Science Museum — Ancient Egyptian Gallery', 'louisiana-art-science-museum-ancient-egyptian-gallery', 'museums', 30.44641, -91.19041, 'Baton Rouge', 'LA', 'This former railroad station contains an art museum, planetarium and an Ancient Egyptian gallery with a Ptolemaic-era mummy. The mixture of astronomy, fine art and mummification makes it a surprisingly eclectic stop.', 'open', null, 'https://www.lasm.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana Orphan Train Museum', 'louisiana-orphan-train-museum', 'museums', 30.53158, -92.07467, 'Opelousas', 'LA', 'The museum preserves records and artifacts connected with more than 2,000 children sent from New York institutions to Louisiana families during the orphan-train era. It occupies a restored depot and keeps limited weekly hours.', 'limited', null, 'https://www.laorphantrainmuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana Political Museum & Hall of Fame', 'louisiana-political-museum-hall-of-fame', 'museums', 31.92678, -92.63538, 'Winnfield', 'LA', 'Louisiana''s famously colorful political history gets its own museum in the hometown region of several major politicians. Campaign objects, memorabilia and exhibits turn state politics into a specialized museum subject.', 'open', null, 'https://lapoliticalmuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana State Exhibit Museum', 'louisiana-state-exhibit-museum', 'museums', 32.4817, -93.7856, 'Shreveport', 'LA', 'This circular 1939 museum is filled with large WPA-era dioramas showing Louisiana agriculture, industry and culture in miniature. The building itself and the old-fashioned immersive exhibits make it unusually distinctive.', 'open', null, 'https://www.laexhibitmuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lucky Cat Museum', 'lucky-cat-museum', 'museums', 39.12722, -84.49917, 'Cincinnati', 'OH', 'The Lucky Cat Museum contains thousands of maneki-neko, the Japanese beckoning-cat figures associated with good fortune, inside Cincinnati''s Essex Studios. The collection moved into its current first-floor space in 2016 and is free to visit, but current visits are by appointment during limited afternoon hours.', 'limited', null, 'https://www.visitcincy.com/listing/lucky-cat-museum/6267/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Macaulay Museum of Dental History', 'macaulay-museum-of-dental-history', 'museums', 32.78673, -79.94735, 'Charleston', 'SC', 'MUSC''s dental-history museum contains historic tools, dental chairs, a nineteenth-century dental-office display and a traveling dentist''s chest from the Civil War era. Among its stranger artifacts is an instrument attributed to silversmith and Revolutionary War figure Paul Revere. The museum is accessed through the Waring Historical Library; appointments are strongly encouraged and required for larger groups.', 'limited', null, 'https://waring.library.musc.edu/exhibits/macaulay/index.php', '2026-09-09T05:53:13.784429+00:00', null, 'https://waring.library.musc.edu/exhibits/macaulay/', null, null, null, 'America/New_York'),
  ('Mad Century Studios and the House of the Improbable', 'mad-century-studios-and-the-house-of-the-improbable', 'museums', 34.91043, -82.35939, 'Taylors', 'SC', 'This eccentric studio and folk-art environment mixes oddities, preserved specimens, found-object sculptures, fairy-garden spaces, interactive art and a collection that deliberately blurs the line between museum and backyard art project. Visitors have been encouraged to make or add art to the environment rather than simply look at it. It is run by local artists at a residential-scale property, so OddWay visitors should check ahead before arriving. Secondary source: https://www.scartshub.com/venues/mad-century-studios-and-the-house-of-the-improbable/', 'limited', null, 'https://www.atlasobscura.com/places/mad-century-studios-and-the-house-of-the-improbable-south-carolina', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Main Street Museum', 'main-street-museum', 'museums', 43.64997, -72.31902, 'White River Junction', 'VT', 'This small museum operates more like a cabinet of curiosities than a conventional historical collection. Its eclectic holdings mix local artifacts, natural-history specimens, odd objects, ephemera and items whose significance comes largely from the stories attached to them.', 'limited', null, 'https://www.atlasobscura.com/places/main-street-museum', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maine Classic Car Museum', 'maine-classic-car-museum', 'museums', 43.45171, -70.4973, 'Arundel', 'ME', 'This museum displays an eclectic collection of restored automobiles, motorcycles, automobilia, and unusual vehicles rather than focusing on a single make or era. Its highly visual collection makes it an easy OddWay stop even for travelers who are not dedicated car enthusiasts.', 'limited', null, 'https://www.mainecarmuseum.com/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maine Coast Sardine History Museum', 'maine-coast-sardine-history-museum', 'museums', 44.54029, -67.58804, 'Jonesport', 'ME', 'This small Downeast museum preserves the vanished world of Maine’s sardine canneries through old tins, labels, photographs, machinery, packing tables, workers’ tools, and other industrial artifacts. One especially personal display preserves scissors once used by individual cannery workers.', 'limited', null, 'https://www.downeastfisheriestrail.org/sites/maine-coast-sardine-history-museum/', '2026-09-09T04:54:23.476824+00:00', null, 'https://mainesardinemuseum.tripod.com/', null, null, null, 'America/New_York'),
  ('Maine Mineral & Gem Museum', 'maine-mineral-gem-museum', 'museums', 44.4077, -70.7887, 'Bethel', 'ME', 'This museum combines Maine mining history with an unusually strong meteorite collection, including material from the Moon and Mars. Its mix of gemstones, space rocks, and geological specimens makes it much stranger than a standard local-history museum.', 'limited', null, 'https://mainemineralmuseum.org/visit/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maine Narrow Gauge Railroad Co. & Museum', 'maine-narrow-gauge-railroad-co-museum', 'museums', 43.66042, -70.24663, 'Portland', 'ME', 'Historic two-foot-gauge railway equipment still operates along Portland’s waterfront, preserving a form of railroading once unusually common in Maine. The museum runs scheduled passenger trips in restored equipment rather than displaying the collection only as static artifacts.', 'limited', null, 'https://mainenarrowgauge.org/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maine Solar System Model — The Sun', 'maine-solar-system-model-the-sun', 'museums', 46.67222, -68.01717, 'Presque Isle', 'ME', 'The Sun inside Folsom Hall at the University of Maine at Presque Isle anchors a huge scale model of the solar system whose planetary installations stretch along roads through Aroostook County. Travelers can turn the model into its own multi-stop OddWay route.', 'limited', null, 'https://www.mainesolarsystem.com/destinations/the-sun/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marathon Air Museum', 'marathon-air-museum', 'museums', 24.72622, -81.05088, 'Marathon', 'FL', 'Small volunteer-run aviation museum inside a hangar at Marathon''s airport.', 'limited', null, 'https://www.marathonairmuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mardi Gras World', 'mardi-gras-world', 'museums', 29.93483, -90.06139, 'New Orleans', 'LA', 'Blaine Kern''s working float facility lets visitors walk among oversized parade props and see how Mardi Gras floats are built and painted. Because it is both workshop and attraction, displays can change substantially between visits.', 'open', null, 'https://www.mardigrasworld.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Maritime & Seafood Industry Museum', 'maritime-seafood-industry-museum', 'museums', 30.39335, -88.85911, 'Biloxi', 'MS', 'A museum covering more than three centuries of Gulf Coast shipbuilding, seafood work, storms and maritime culture. It also houses the Hurricane Camille Memorial, linking everyday coastal industry with one of the region''s most destructive disasters.', 'open', null, 'https://www.maritimemuseum.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Marshall Steam Museum at Auburn Heights', 'marshall-steam-museum-at-auburn-heights', 'museums', 39.80926, -75.67959, 'Yorklyn', 'DE', 'The Marshall Steam Museum preserves what it describes as the world’s largest operating collection of Stanley steam cars along with other antique automobiles. Auburn Valley also operates a miniature live-steam railroad on selected event days, making the site part museum and part functioning mechanical time capsule.', 'limited', null, 'https://auburnheights.org/', '2026-09-08T18:31:51.932734+00:00', null, 'https://auburnheights.org/', null, null, null, 'America/New_York'),
  ('Marvin Johnson Gourd Museum', 'marvin-johnson-gourd-museum', 'museums', 35.50759, -78.74051, 'Angier', 'NC', 'A room inside the Angier Public Library contains hundreds of gourds collected and decorated by Marvin Johnson, including vessels, instruments, carvings, and unusually shaped natural specimens. Ask library staff for access when the room is not otherwise in use.', 'limited', null, 'https://www.atlasobscura.com/places/gourd-museum-angier-north-carolina', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Matchbox Road Museum', 'matchbox-road-museum', 'museums', 39.5458, -75.022, 'Newfield', 'NJ', 'Collector Everett Marshall has assembled an enormous private museum devoted to Matchbox vehicles, with thousands of miniature cars and related material displayed behind his home. Visits are by appointment, making this a legitimate but deliberately limited OddWay stop.', 'limited', null, 'https://www.facebook.com/MatchboxRoadMuseum', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mattatuck Museum Button Gallery', 'mattatuck-museum-button-gallery', 'museums', 41.55741, -73.04315, 'Waterbury', 'CT', 'Thousands of buttons form a permanent collection inside the Mattatuck Museum, ranging from military and fashion pieces to unusually elaborate carved and novelty examples. The collection grew from a much larger archive assembled during Waterbury''s industrial era.', 'open', null, 'https://www.roadsideamerica.com/tip/6857', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.mattmuseum.org/', null, null, null, 'America/New_York'),
  ('McCandless Collection', 'mccandless-collection', 'museums', 36.05843, -79.445, 'Burlington', 'NC', 'This appointment-only museum is packed with rare Mopar vehicles, historic race cars, vintage signs, clocks, and automobilia. The collection focuses heavily on the Forward Look era and American automotive history, making it much more specialized than a general car museum.', 'limited', null, 'https://www.atlasobscura.com/places/mccandless-collection', '2026-09-09T05:34:33.398594+00:00', null, 'https://www.mccandlesscollection.com/', null, null, null, 'America/New_York'),
  ('Medical Exhibit of Yesteryear', 'medical-exhibit-of-yesteryear', 'museums', 39.47521, -77.98086, 'Martinsburg', 'WV', 'Inside Berkeley Medical Center is a small display of antique medical equipment, old nursing uniforms, wooden wheelchairs, handmade crutches and other artifacts from earlier eras of medicine. Because the exhibit is inside an operating hospital, visit only during permitted public hours and do not interfere with patients or staff.', 'limited', null, 'https://www.roadsideamerica.com/tip/40978', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Medieval Torture Museum', 'medieval-torture-museum', 'museums', 41.88478, -87.62775, 'Chicago', 'IL', 'A large collection of torture-device reconstructions and dark historical displays in downtown Chicago, presented as an immersive walk-through museum.', 'limited', null, 'https://medievaltorturemuseum.com/chicago/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Medieval Torture Museum', 'medieval-torture-museum-st-augustine', 'museums', 29.89569, -81.31319, 'St. Augustine', 'FL', 'Dark-history museum filled with recreated torture and punishment devices.', 'limited', null, 'https://medievaltorturemuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Memphis Railroad & Trolley Museum', 'memphis-railroad-trolley-museum', 'museums', 35.13207, -90.05916, 'Memphis', 'TN', 'Located at Central Station, this volunteer-run museum preserves Memphis railroad and streetcar history through models, artifacts and transportation exhibits. Limited operating schedules make it a check-ahead destination rather than a guaranteed daily stop.', 'limited', null, 'https://mrtm.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mercer Museum', 'mercer-museum', 'museums', 40.3079, -75.12734, 'Doylestown', 'PA', 'Archaeologist and collector Henry Chapman Mercer filled this castle-like concrete museum with tools and objects documenting preindustrial American life. Thousands of artifacts hang from balconies, walls and ceilings in a towering central atrium, including wagons, boats and machinery suspended overhead.', 'open', null, 'https://www.mercermuseum.org/visit/mercer-museum/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Merry-Go-Round Museum', 'merry-go-round-museum', 'museums', 41.45393, -82.7129, 'Sandusky', 'OH', 'The Merry-Go-Round Museum opened in 1990 inside Sandusky''s former post office to preserve the art and history of carousel carving. Visitors can see restored and in-progress carousel figures, watch carving demonstrations when available and ride the museum''s working indoor carousel.', 'open', null, 'https://merrygoroundmuseum.org/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Metal Museum at Overton Park', 'metal-museum-at-overton-park', 'museums', 35.1448, -89.9932, 'Memphis', 'TN', 'The Metal Museum moved to 1930 Poplar Avenue in Overton Park, expanding its focus on metalworking, sculpture and live craft demonstrations. As of September 9, 2026, the official site says the museum is temporarily closed and will reopen Friday, September 11, 2026; re-check before routing.', 'limited', null, 'https://www.metalmuseum.org/directions', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Michigan Flywheelers Museum', 'michigan-flywheelers-museum', 'museums', 42.39531, -86.20227, 'South Haven', 'MI', 'The Michigan Flywheelers preserve antique tractors, steam engines, farm machinery and other pieces of mechanical agricultural history across a large rural site. Demonstrations and major annual events bring many of the machines back to life rather than displaying everything as static museum pieces.', 'limited', null, 'https://michiganflywheelers.org/', '2026-09-08T15:31:15.588137+00:00', null, 'https://michiganflywheelers.org/', null, null, null, 'America/Detroit'),
  ('Michigan Heroes Museum', 'michigan-heroes-museum', 'museums', 43.31841, -83.73537, 'Frankenmuth', 'MI', 'This small museum focuses specifically on Michigan men and women connected with military service and the U.S. space program. Uniforms, photographs and personal artifacts create an unusually local approach to wars, veterans and astronauts rather than a generic military collection.', 'open', null, 'https://www.frankenmuth.org/directory/michigan-heroes-museum/', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Michigan Whitetail Hall of Fame Museum', 'michigan-whitetail-hall-of-fame-museum', 'museums', 42.29385, -84.22937, 'Grass Lake', 'MI', 'This museum is devoted almost entirely to exceptionally large whitetail deer and antler records. Displays include dozens of notable racks and hunting-history exhibits, while live deer on the property make the stop part museum and part highly specialized wildlife attraction.', 'open', null, 'https://www.michigan.org/property/michigan-whitetail-hall-fame-museum', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Midwest Miniatures Museum', 'midwest-miniatures-museum', 'museums', 43.06221, -86.22617, 'Grand Haven', 'MI', 'This museum displays highly detailed miniature rooms, buildings and scenes created by artists working at tiny scales. Its current home in downtown Grand Haven contains multiple floors of miniature collections, including architectural interiors and unusually meticulous handmade environments.', 'limited', null, 'https://www.midwestminiaturesmuseum.org/', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.midwestminiaturesmuseum.org/', null, null, null, 'America/Detroit'),
  ('Millville Army Air Field Museum', 'millville-army-air-field-museum', 'museums', 39.37199, -75.07248, 'Millville', 'NJ', 'Millville''s wartime airfield trained thousands of fighter pilots during World War II. The museum preserves aircraft, uniforms, photographs and personal stories from the base, including the dangerous training work that earned Millville its place in military aviation history.', 'limited', null, 'https://p47millville.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mining & Rollo Jamison Museums', 'mining-rollo-jamison-museums', 'museums', 42.73271, -90.47321, 'Platteville', 'WI', 'Platteville''s museum complex combines regional history with an underground lead-and-zinc mining experience. Guided tours descend into the 1845 Bevans Lead Mine, giving visitors a tangible look at the industry that shaped southwest Wisconsin.', 'limited', null, 'https://mining.jamison.museum/', '2026-09-09T13:02:00.307533+00:00', null, 'https://mining.jamison.museum/', null, null, null, 'America/Chicago'),
  ('Mister Ed''s Elephant Museum & Candy Emporium', 'mister-eds-elephant-museum-candy-emporium', 'museums', 39.89843, -77.43013, 'Orrtanna', 'PA', 'Ed and Pat Gotwalt opened the original Mister Ed''s roadside store in 1975, and its later incarnation turned Ed''s growing elephant collection into an entire museum-and-candy-store destination. Visitors now find roughly 12,000 elephant objects, a teapot museum, whimsical gardens and a huge candy selection, with free museum admission.', 'open', null, 'https://mistereds.com/pages/visit', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('MIT Museum', 'mit-museum', 'museums', 42.3623, -71.0868, 'Cambridge', 'MA', 'MIT''s museum turns experimental science and engineering into a public collection of robots, holography, kinetic art, early computing, artificial intelligence and prototypes. Its current home at the Gambrill Center in Kendall Square makes it one of the easiest places in Massachusetts to encounter genuinely strange technology.', 'open', null, 'https://mitmuseum.mit.edu/', '2026-09-09T04:43:56.902716+00:00', null, 'https://mitmuseum.mit.edu/', null, null, null, 'America/New_York'),
  ('Mmuseumm', 'mmuseumm', 'museums', 40.71736, -74.00282, 'New York', 'NY', 'Mmuseumm is a tiny cabinet-of-curiosities museum built inside a former freight elevator in a Tribeca alley. Its displays focus on overlooked everyday objects and contemporary artifacts, and the interior has very limited seasonal hours even though the exhibits can often be viewed through the windows from the alley.', 'limited', null, 'https://mmuseumm.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mobile Medical Museum', 'mobile-medical-museum', 'museums', 30.69301, -88.07754, 'Mobile', 'AL', 'Historic medical instruments, pharmacy objects, anatomical material and archival collections document centuries of medicine on the Gulf Coast. The museum occupies the Vincent-Doan House and presents tools that can look startling by modern standards.', 'limited', null, 'https://www.mobilemedicalmuseum.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Moist Towelette Museum', 'moist-towelette-museum', 'museums', 42.72562, -84.47603, 'East Lansing', 'MI', 'Hidden inside an office at Michigan State University''s Abrams Planetarium is an actual collection devoted to packaged moist towelettes. The tiny museum contains examples from businesses and countries around the world, but because it is inside a working office, visitors should call ahead rather than assume drop-in access.', 'limited', null, 'https://abramsplanetarium.natsci.msu.edu/about/moist-towelette.aspx', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Monroe Moosnick Medical and Science Museum', 'monroe-moosnick-medical-and-science-museum', 'museums', 38.05272, -84.49403, 'Lexington', 'KY', 'Transylvania University''s medical collection contains nineteenth-century scientific instruments and anatomical curiosities, including a huge buffalo hairball and an anatomical figure associated with early medical teaching. Public access is limited and may require advance arrangements, so travelers should confirm availability before routing here.', 'limited', null, 'https://www.atlasobscura.com/places/the-monroe-moosnick-medical-and-science-museum-lexington-kentucky', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Montrose Historical and Telephone Pioneer Museum', 'montrose-historical-and-telephone-pioneer-museum', 'museums', 43.17778, -83.89056, 'Montrose', 'MI', 'This small local museum preserves switchboards, telephones and other equipment from the era when operators manually connected calls. The collection turns an everyday technology that largely vanished from modern life into a hands-on look at how complicated making a simple phone call once was.', 'limited', null, 'https://montrosemuseum.com/historical/', '2026-09-08T15:31:15.588137+00:00', null, 'https://montrosemuseum.com/historical/', null, null, null, 'America/Detroit'),
  ('Moogseum', 'moogseum', 'museums', 35.59729, -82.55216, 'Asheville', 'NC', 'Dedicated to synthesizer pioneer Bob Moog, this museum combines music history with hands-on electronic experiments, prototypes, instruments, and an interactive theremin. Exhibits explain how electrical signals are transformed into the strange sounds that made Moog synthesizers famous.', 'limited', null, 'https://www.atlasobscura.com/places/moogseum', '2026-09-09T05:34:33.398594+00:00', null, 'https://moogseum.org/', null, null, null, 'America/New_York'),
  ('Mormon Print Shop Museum', 'mormon-print-shop-museum', 'museums', 45.74609, -85.52084, 'St. James', 'MI', 'Built in 1850, this small Beaver Island building was used by followers of James Jesse Strang, the self-proclaimed Mormon king whose island community became one of Michigan''s strangest religious experiments. The restored print shop now interprets Strang''s kingdom along with broader Beaver Island history.', 'limited', null, 'https://www.beaverislandhistory.org/print-shop/', '2026-09-08T15:31:15.588137+00:00', null, 'https://www.beaverislandhistory.org/print-shop/', null, null, null, 'America/Detroit'),
  ('Morris Museum — Mechanical Music and Automata Collection', 'morris-museum-mechanical-music-and-automata-collection', 'museums', 40.79561, -74.448, 'Morris Township', 'NJ', 'The Morris Museum houses the Murtogh D. Guinness Collection of mechanical musical instruments and automata. Self-playing organs, music boxes and elaborate moving figures preserve a world of entertainment machinery built before electronic media.', 'open', null, 'https://morrismuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mourning Museum at Borrowed Time Oddities', 'mourning-museum-at-borrowed-time-oddities', 'museums', 41.83013, -86.25585, 'Niles', 'MI', 'Inside Borrowed Time Oddities is a small museum focused on mourning customs, funerary objects and material culture surrounding death. The collection turns a modern oddities shop into a more structured historical stop, with displays interpreting how people have remembered and cared for the dead.', 'limited', null, 'https://www.atlasobscura.com/places/the-mourning-museum-at-borrowed-time-oddities', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Mummers Museum', 'mummers-museum', 'museums', 39.93345, -75.14757, 'Philadelphia', 'PA', 'Philadelphia''s elaborate Mummers tradition fills this museum with feathered costumes, sequined suits, parade props, photographs and artifacts from more than a century of New Year''s performances. The collection explains one of the city''s strangest long-running civic traditions and is open during posted museum hours.', 'open', null, 'https://mummersmuseum.com/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mummies of Philippi', 'mummies-of-philippi', 'museums', 39.15342, -80.04246, 'Philippi', 'WV', 'In 1888, amateur scientist Graham Hamrick experimented with embalming two cadavers and produced a pair of remarkably preserved mummies that later traveled with sideshows. They eventually returned to Philippi and are now displayed at the Barbour County Historical Museum, whose schedule is more limited than a conventional year-round museum.', 'limited', null, 'https://www.hmdb.org/m.asp?m=211802', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Musée Patamécanique', 'mus-e-patam-canique', 'museums', 41.67711, -71.2662, 'Bristol', 'RI', 'Musée Patamécanique is an intentionally strange cabinet of curiosities inspired by pataphysics, automata and absurdist invention. Its objects and installations blur the line between museum, mechanical theater and conceptual art. Access has historically been appointment-based and irregular, so availability should be confirmed before routing a trip around it.', 'limited', null, 'https://www.atlasobscura.com/places/musee-patamecanique', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Bad Art', 'museum-of-bad-art', 'museums', 42.3222, -71.06248, 'Boston', 'MA', 'The Museum of Bad Art deliberately collects artwork judged too strange, awkward or unsuccessful for conventional museums. Its current Boston gallery is inside Dorchester Brewing Company, where rotating selections from a collection of hundreds of pieces are displayed with deadpan curatorial interpretations.', 'open', null, 'https://museumofbadart.org/location/', '2026-09-09T04:43:56.902716+00:00', null, 'https://museumofbadart.org/', null, null, null, 'America/New_York'),
  ('Museum of Beadwork', 'museum-of-beadwork', 'museums', 43.67906, -70.28788, 'Portland', 'ME', 'This specialized museum focuses entirely on beadwork as art, craft, and cultural expression. Exhibitions range from contemporary pieces to traditions from different communities, creating a museum around a material that is usually relegated to a small section elsewhere.', 'limited', null, 'https://www.atlasobscura.com/places/museum-of-beadwork', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Death New Orleans', 'museum-of-death-new-orleans', 'museums', 29.9559, -90.0698, 'New Orleans', 'LA', 'This macabre museum displays material connected with funerary practices, crime history, forensic subjects and death culture. The subject matter can be graphic, so it is best treated as an adult-oriented OddWay museum stop.', 'open', null, 'https://www.museumofdeath.net/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Museum of Everyday Life', 'museum-of-everyday-life', 'museums', 44.6409, -72.20582, 'Glover', 'VT', 'This self-service museum gives ordinary objects the kind of attention normally reserved for fine art or major historical artifacts. Rotating exhibits have examined everything from pencils and matches to locks, toothbrushes and other objects people usually overlook.', 'open', null, 'https://www.atlasobscura.com/places/museum-of-everyday-life', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Historic Torture Devices', 'museum-of-historic-torture-devices', 'museums', 43.62668, -89.77317, 'Wisconsin Dells', 'WI', 'This compact museum displays replicas and historical examples of punishment and torture devices, pairing grim subject matter with downtown Wisconsin Dells tourism. The attraction operates seasonally, so hours should be checked before routing.', 'limited', null, 'https://torturemuseumdells.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://torturemuseumdells.com/', null, null, null, 'America/Chicago'),
  ('Museum of Military History', 'museum-of-military-history', 'museums', 28.30617, -81.45229, 'Kissimmee', 'FL', 'Military museum with uniforms, vehicles, weapons displays, and local veteran history.', 'limited', null, 'https://museumofmilitaryhistory.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Natural and Other Curiosities', 'museum-of-natural-and-other-curiosities', 'museums', 41.76585, -72.6733, 'Hartford', 'CT', 'Hidden inside Connecticut''s Old State House is a recreated early American cabinet of curiosities packed with taxidermy, unusual specimens and historical oddments. Its best-known residents include a two-headed calf and a giant preserved alligator.', 'open', null, 'https://www.atlasobscura.com/places/museum-natural-other-curiosities', '2026-09-08T18:39:47.144889+00:00', null, 'https://wp.cga.ct.gov/osh/', null, null, null, 'America/New_York'),
  ('Museum of Physical Security', 'museum-of-physical-security', 'museums', 37.8626, -84.5793, 'Nicholasville', 'KY', 'Lockmasters Security Institute maintains an unusual museum devoted to locks, safes and physical security technology stretching across centuries. Its collection has included historic locks, safecracking equipment and specialized security devices rarely displayed together elsewhere; visitors should call ahead before planning a tour.', 'limited', null, 'https://www.roadsideamerica.com/story/24045', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Radio and Technology', 'museum-of-radio-and-technology', 'museums', 38.40129, -82.47315, 'Huntington', 'WV', 'This volunteer-run museum fills roughly 10,000 square feet with vintage radios, televisions, broadcast equipment, computers and other pieces of communication technology. It maintains regular weekend public hours and is free to visit, making it an unusually substantial stop for a specialized collection.', 'open', null, 'https://www.radiomuseum.org/museum/usa/museum-of-radio-and-technology-huntington-wv/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Root Beer', 'museum-of-root-beer', 'museums', 43.62692, -89.7727, 'Wisconsin Dells', 'WI', 'A museum dedicated entirely to root beer covers brands, bottling, advertising and the drink''s place in American soda culture. Hundreds of labels and artifacts make an everyday soft drink into an unexpectedly deep collecting obsession.', 'open', null, 'https://museumofrootbeer.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://museumofrootbeer.com/', null, null, null, 'America/Chicago'),
  ('Museum of the Alphabet', 'museum-of-the-alphabet', 'museums', 34.86457, -80.74182, 'Waxhaw', 'NC', 'Created by JAARS, this specialized museum explores writing systems from around the world and the development of alphabets, scripts, printing, and language. Exhibits range from ancient systems to modern linguistic work, making written language itself the museum’s central artifact.', 'limited', null, 'https://www.jaars.org/visit/museum-of-the-alphabet/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of the Bizarre', 'museum-of-the-bizarre', 'museums', 34.23272, -77.94905, 'Wilmington', 'NC', 'Housed in an 1869 brick building near Wilmington’s riverfront, this museum mixes curiosities, unusual artifacts, movie props, true-crime material, strange machines, and sideshow-style displays. Exhibits have included a purported Houdini Ouija board, a crystal skull, and a Van de Graaff generator.', 'open', null, 'https://www.wilmingtonandbeaches.com/listing/museum-of-the-bizarre/1073/', '2026-09-09T05:34:33.398594+00:00', null, 'https://museumbizarre.com/', null, null, null, 'America/New_York'),
  ('Museum of the Gilding Arts', 'museum-of-the-gilding-arts', 'museums', 40.88155, -88.63065, 'Pontiac', 'IL', 'A museum devoted to gold and silver leaf explains gilding tools and techniques and recreates a historic gold-beating workshop.', 'limited', null, 'https://societyofgilders.org/museum/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Museum of the Middle Appalachians', 'museum-of-the-middle-appalachians', 'museums', 36.88002, -81.76386, 'Saltville', 'VA', 'Saltville''s museum tells an unusually broad story that stretches from Ice Age animals and archaeological finds to salt production, Civil War battles and the town''s chemical industry. Fossils and prehistoric remains from the region make it especially useful as an OddWay stop rather than a standard local-history museum.', 'open', null, 'https://www.museumofthemiddleappalachians.org/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of the Southern Jewish Experience', 'museum-of-the-southern-jewish-experience', 'museums', 29.9442, -90.0742, 'New Orleans', 'LA', 'The museum explores Jewish life across the American South through migration, small-town communities, civil rights history and regional culture. Its geographic focus makes it a distinctive counterpart to more conventional Jewish-history museums.', 'open', null, 'https://msje.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Museum of York County — Stans African Halls', 'museum-of-york-county-stans-african-halls', 'museums', 35.01014, -81.06237, 'Rock Hill', 'SC', 'The Museum of York County grew around the Stans African animal collection, a huge assemblage of full-mounted African specimens displayed in immersive dioramas. Its Naturalist Center now adds more than 2,000 specimens that visitors can study, while the larger museum also covers fossils, regional natural history and a planetarium. The dense taxidermy halls give this otherwise conventional science museum a distinctly old-school cabinet-of-natural-history feel. Secondary source: https://chmuseums.org/collections/', 'limited', null, 'https://chmuseums.org/myco/', '2026-09-09T05:53:13.784429+00:00', null, 'https://chmuseums.org/myco/', null, null, null, 'America/New_York'),
  ('Museum Ship Valley Camp', 'museum-ship-valley-camp', 'museums', 46.49944, -84.335, 'Sault Ste. Marie', 'MI', 'A 550-foot Great Lakes freighter launched in 1917 now serves as a floating museum beside the St. Marys River. Among its many maritime exhibits are two lifeboats recovered from the wreckage of the Edmund Fitzgerald, making the ship especially significant to Great Lakes disaster history.', 'limited', null, 'https://www.saulthistoricsites.com/museum-ship-valley-camp/', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Music House Museum', 'music-house-museum', 'museums', 44.77922, -85.49524, 'Williamsburg', 'MI', 'The Music House Museum is filled with mechanical musical instruments that play without conventional live performers, including music boxes, player pianos, organs and large automated machines. Demonstrations turn the collection into a noisy tour through the engineering history of self-playing music.', 'limited', null, 'https://musichouse.org/hours-location-directions-music-house-museum-michigan/', '2026-09-08T15:31:15.588137+00:00', null, 'https://musichouse.org/', null, null, null, 'America/Detroit'),
  ('Mütter Museum', 'mutter-museum', 'museums', 39.95333, -75.17639, 'Philadelphia', 'PA', 'The Mütter began with surgeon Thomas Dent Mütter''s 1859 donation of 1,700 objects and money to establish a permanent medical teaching collection. It has grown to more than 25,000 objects covering medical history, anatomical specimens and pathology, with ticketed public galleries at the College of Physicians.', 'open', null, 'https://muttermuseum.org/about/overview/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mythos Museum of Oddities & Curiosities', 'mythos-museum-of-oddities-curiosities', 'museums', 42.63671, -83.291, 'Pontiac', 'MI', 'Mythos is a compact museum devoted to the macabre and unusual, with displays involving funerary objects, bones, medical material, vintage Halloween pieces and other curiosities. Its collection intentionally sits somewhere between oddities shop, sideshow history and modern cabinet of curiosities.', 'limited', null, 'https://mythosmuseum.com/', '2026-09-08T15:31:15.588137+00:00', null, 'https://mythosmuseum.com/', null, null, null, 'America/Detroit'),
  ('Nantucket Whaling Museum', 'nantucket-whaling-museum', 'museums', 41.28553, -70.09891, 'Nantucket', 'MA', 'A massive sperm-whale skeleton hangs over a museum devoted to Nantucket''s whaling era. Scrimshaw, ship material and maritime artifacts tell the darker industrial history behind the island''s picturesque image.', 'limited', null, 'https://nha.org/visit/museums-and-tours/whaling-museum/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Auto & Truck Museum', 'national-auto-truck-museum', 'museums', 41.35558, -85.05868, 'Auburn', 'IN', 'NATMUS occupies surviving Auburn Automobile Company factory buildings next door to the Auburn Cord Duesenberg Museum. Its collection includes unusual cars, trucks, prototypes, automotive signs and GM Futurliner No. 10, one of the enormous vehicles built for General Motors'' Parade of Progress.', 'open', null, 'https://natmus.org/', '2026-09-08T13:34:34.826362+00:00', null, 'https://natmus.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('National Barber Museum and Hall of Fame', 'national-barber-museum-and-hall-of-fame', 'museums', 39.84087, -82.81024, 'Canal Winchester', 'OH', 'The National Barber Museum preserves barber chairs, razors, signs, poles, tools and other material from the history of barbering in America. The collection dates back to the museum''s founding in 1988, but current public hours are limited, so check the museum''s schedule or appointment information before routing here.', 'limited', null, 'https://www.nationalbarbermuseum.com/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Bird Dog Museum', 'national-bird-dog-museum', 'museums', 35.04982, -89.1933, 'Grand Junction', 'TN', 'A museum devoted to pointing dogs, field trials and sporting-dog history contains trophies, art and breed-specific displays. Its singular subject matter makes it one of the state''s strongest niche museums.', 'open', null, 'https://www.birddogfoundation.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Bobblehead Hall of Fame and Museum', 'national-bobblehead-hall-of-fame-and-museum', 'museums', 43.02972, -87.91056, 'Milwaukee', 'WI', 'Thousands of nodding figures fill display cases devoted to sports, celebrities, mascots, politics and pop culture. The museum also documents the history and manufacture of bobbleheads, turning a novelty collectible into an improbably comprehensive archive.', 'open', null, 'https://www.bobbleheadhall.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.bobbleheadhall.com/', null, null, null, 'America/Chicago'),
  ('National Bottle Museum', 'national-bottle-museum', 'museums', 43.00312, -73.84872, 'Ballston Spa', 'NY', 'The National Bottle Museum treats bottle making as America''s first major industry and fills its galleries with historic bottles, molds, tools and glassmaking equipment. It is open year-round on posted Wednesday-through-Saturday hours and also maintains a research collection devoted to historic glass.', 'open', null, 'https://nationalbottlemuseum.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Brewery Museum at Potosi Brewery', 'national-brewery-museum-at-potosi-brewery', 'museums', 42.67694, -90.72556, 'Potosi', 'WI', 'A restored historic brewery houses a museum devoted to American brewing and brewery advertising. Neon signs, bottles, trays and brewery artifacts make the collection a dense archive of an industry deeply tied to Wisconsin identity.', 'open', null, 'https://www.potosibrewery.com/museums', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.potosibrewery.com/', null, null, null, 'America/Chicago'),
  ('National Capital Radio & Television Museum', 'national-capital-radio-television-museum', 'museums', 38.92631, -76.73332, 'Bowie', 'MD', 'A 1906 storekeeper''s house is packed with early radios, televisions, crystal sets, vacuum tubes and broadcasting equipment. The museum traces the rapid transformation from wireless telegraphy to household television and operates on limited weekly public hours.', 'open', null, 'https://www.cityofbowie.org/292/National-Capital-Radio-Television-Museum', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Capital Trolley Museum', 'national-capital-trolley-museum', 'museums', 39.09581, -77.03139, 'Colesville', 'MD', 'This volunteer museum preserves historic streetcars and the technology of electric urban transportation. On operating days visitors can inspect restored cars and ride along the museum''s demonstration railway, so access depends on the published schedule.', 'limited', null, 'https://www.dctrolley.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Cave Museum and Library', 'national-cave-museum-and-library', 'museums', 37.11677, -86.06247, 'Park City', 'KY', 'The National Cave Museum and Library preserves material on cave exploration, geology and the long history of commercial and scientific caving around Mammoth Cave. Its specialized collection makes it a natural OddWay stop for travelers interested in what lies beneath Kentucky rather than another general local-history museum.', 'limited', null, 'https://mapcarta.com/N10757547905', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Cleveland-Style Polka Hall of Fame', 'national-cleveland-style-polka-hall-of-fame', 'museums', 41.59907, -81.52569, 'Euclid', 'OH', 'This small museum documents Cleveland-style polka and the musicians, accordions, recordings and immigrant communities that shaped it. Exhibits and the hall of fame are open only on limited weekly hours, making it a niche but very specific destination rather than an anytime stop.', 'limited', null, 'https://clevelandstyle.com/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Corvair Museum', 'national-corvair-museum', 'museums', 39.6004, -89.6541, 'Glenarm', 'IL', 'A volunteer-run museum devoted to Chevrolet''s rear-engine Corvair preserves cars, engines, prototypes, specialty vehicles, and technical displays on old Route 66.', 'limited', null, 'https://museum.corvair.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Cryptologic Museum', 'national-cryptologic-museum', 'museums', 39.11487, -76.77473, 'Annapolis Junction', 'MD', 'The National Security Agency''s public museum explores codebreaking, espionage and communications intelligence from early ciphers through modern computing. Displays include historic cryptographic machines, Cold War equipment and artifacts from some of the most secretive parts of American history.', 'open', null, 'https://www.nsa.gov/museum/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Dairy Shrine and Hoard Historical Museum', 'national-dairy-shrine-and-hoard-historical-museum', 'museums', 42.92376, -88.83591, 'Fort Atkinson', 'WI', 'The Hoard Historical Museum includes the National Dairy Shrine, a collection devoted to the people, cattle, equipment and ideas that shaped the American dairy industry. In Wisconsin, a museum that treats dairy history as a national shrine feels entirely appropriate.', 'limited', null, 'https://www.hoardmuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.hoardmuseum.org/', null, null, null, 'America/Chicago'),
  ('National Electronics Museum', 'national-electronics-museum', 'museums', 39.48578, -76.66327, 'Cockeysville', 'MD', 'The National Electronics Museum preserves more than 10,000 objects related to radar, radio, sonar, satellites, communications and electronic warfare. The collection has moved to the Hunt Valley/Cockeysville area, so travelers should use the museum''s current address and check its posted schedule before visiting.', 'limited', null, 'https://www.nationalelectronicsmuseum.org/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Great Blacks In Wax Museum', 'national-great-blacks-in-wax-museum', 'museums', 39.31182, -76.59685, 'Baltimore', 'MD', 'Founded in 1983, this museum uses more than 100 life-size wax figures and immersive scenes to interpret Black history. Some exhibits intentionally confront slavery, lynching and racial violence in unusually direct and graphic ways, making it very different from a conventional wax museum.', 'open', null, 'https://www.greatblacksinwax.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Helicopter Museum', 'national-helicopter-museum', 'museums', 41.19474, -73.13048, 'Stratford', 'CT', 'A small museum inside Stratford''s railroad station explores the town''s central role in helicopter development, including Igor Sikorsky''s work. Exhibits include aircraft components, models, a Sikorsky cockpit and a helicopter flight simulator. The museum operates seasonally.', 'limited', null, 'https://nationalhelicoptermuseum.org/', '2026-09-08T18:47:23.721893+00:00', null, 'https://nationalhelicoptermuseum.org/', null, null, null, 'America/New_York'),
  ('National Museum of Civil War Medicine', 'national-museum-of-civil-war-medicine', 'museums', 39.41379, -77.40932, 'Frederick', 'MD', 'This museum examines the grim realities and surprising advances of medicine during the Civil War through surgical instruments, field-hospital material and stories of doctors, nurses and patients. Its displays include subjects such as battlefield surgery, embalming and wartime disease that fit OddWay''s darker-history side particularly well.', 'open', null, 'https://www.civilwarmed.org/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Museum of Dentistry', 'national-museum-of-dentistry', 'museums', 39.2896, -76.62548, 'Baltimore', 'MD', 'The University of Maryland''s dental collection preserves thousands of objects tracing the strange, painful and occasionally ingenious history of dentistry. Holdings include early instruments, dentures, dental advertising and other material from the national collection of the American dental profession; confirm public visiting access before routing because it is housed within the dental school.', 'limited', null, 'https://www.dental.umaryland.edu/museum/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Museum of Health and Medicine', 'national-museum-of-health-and-medicine', 'museums', 39.00889, -77.05389, 'Silver Spring', 'MD', 'Founded during the Civil War as the Army Medical Museum, this institution holds one of America''s most unusual medical collections. Visitors encounter anatomical specimens, pathological material, military medicine exhibits and artifacts tied to major events including the assassination of Abraham Lincoln.', 'open', null, 'https://medicalmuseum.health.mil/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Mustard Museum', 'national-mustard-museum', 'museums', 43.09539, -89.51111, 'Middleton', 'WI', 'This museum treats mustard with scholarly seriousness and comic enthusiasm, displaying thousands of jars from around the world alongside advertising, history and tasting opportunities. The gift shop and tasting bar make it one of Wisconsin''s most accessible odd museums.', 'open', null, 'https://mustardmuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://mustardmuseum.org/', null, null, null, 'America/Chicago'),
  ('National Railroad Museum', 'national-railroad-museum', 'museums', 44.48312, -88.04789, 'Green Bay', 'WI', 'Historic locomotives and railcars fill this large museum, including streamlined, military and luxury passenger equipment. Visitors can walk through selected cars and see the immense scale of machines that shaped American transportation.', 'open', null, 'https://nationalrrmuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://nationalrrmuseum.org/', null, null, null, 'America/Chicago'),
  ('National Road Museum', 'national-road-museum', 'museums', 39.50926, -77.65397, 'Boonsboro', 'MD', 'The museum tells the story of the National Road, America''s first federally funded highway and one of the routes that transformed early road travel westward. Exhibits recreate pieces of the road''s tavern, transportation and roadside history, and the museum also serves as Boonsboro''s visitor center during its limited open hours.', 'limited', null, 'https://nationalrdfoundation.org/boonsboro-visitor-center/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Watch and Clock Museum', 'national-watch-and-clock-museum', 'museums', 40.03699, -76.50223, 'Columbia', 'PA', 'The National Watch and Clock Museum houses thousands of timekeeping objects ranging from early sundials and tall clocks to pocket watches and modern precision devices. Its galleries make the mechanics and strange variety of human timekeeping the focus of a dedicated public museum.', 'open', null, 'https://www.nawcc.org/index.php/museum/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nature Museum Feejee Mermaid', 'nature-museum-feejee-mermaid', 'museums', 43.17025, -72.61053, 'Grafton', 'VT', 'The Nature Museum keeps an old Feejee-mermaid-style specimen made from combined animal remains, part of the long tradition of sideshow creatures presented as impossible zoological discoveries. It is not always on regular display, so visitors interested specifically in the mermaid should contact the museum before traveling.', 'limited', null, 'https://www.atlasobscura.com/places/the-nature-museum-feejee-mermaid-grafton-vermont', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Naval Air Station Wildwood Aviation Museum', 'naval-air-station-wildwood-aviation-museum', 'museums', 39.00509, -74.90972, 'Lower Township', 'NJ', 'A preserved World War II hangar houses aircraft, engines, military vehicles and aviation artifacts at the former Naval Air Station Wildwood. The setting gives visitors access to both the collection and an authentic wartime training structure.', 'limited', null, 'https://usnasw.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Navy SEAL Museum', 'navy-seal-museum', 'museums', 27.48958, -80.30331, 'Fort Pierce', 'FL', 'Museum at the birthplace of the Navy''s underwater demolition teams, with submersibles and special-operations artifacts.', 'limited', null, 'https://www.navysealmuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('New England Carousel Museum', 'new-england-carousel-museum', 'museums', 41.67103, -72.93949, 'Bristol', 'CT', 'Antique carousel horses and other hand-carved animals fill this museum devoted to the art and mechanics of the American carousel. Visitors can also see restoration work and ride a working indoor carousel.', 'open', null, 'https://www.atlasobscura.com/places/new-england-carousel-museum', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.thecarouselmuseum.org/', null, null, null, 'America/New_York'),
  ('New England Wireless and Steam Museum', 'new-england-wireless-and-steam-museum', 'museums', 41.62427, -71.51302, 'East Greenwich', 'RI', 'This specialized museum preserves early radio equipment, wireless technology and working steam engines in several historic buildings. Its collections connect the development of communications with the machinery that powered nineteenth-century industry. Public openings and demonstrations are scheduled rather than daily, so check the museum calendar before routing here.', 'limited', null, 'https://newsm.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://newsm.org/', null, null, null, 'America/New_York'),
  ('New Hampshire Telephone Museum', 'new-hampshire-telephone-museum', 'museums', 43.27984, -71.81503, 'Warner', 'NH', 'This museum traces the evolution of telephones through switchboards, early handsets, novelty phones and communications equipment that spans generations. Many exhibits emphasize the physical machinery that once connected calls before digital networks made it invisible. Public hours are seasonal, so check the current calendar. Secondary source: https://www.visitnh.gov/blog/5-odd-museums', 'limited', null, 'https://www.nhtelephonemuseum.org/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Jersey Maritime Museum', 'new-jersey-maritime-museum', 'museums', 39.56613, -74.24433, 'Beach Haven', 'NJ', 'This shore museum concentrates on New Jersey shipwrecks, maritime disasters, diving and coastal history. Displays include artifacts recovered from wrecks and extensive research material on vessels lost along the state''s notoriously dangerous coastline.', 'limited', null, 'https://njmaritimemuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Jersey State Police Museum & Learning Center', 'new-jersey-state-police-museum-learning-center', 'museums', 40.26293, -74.83911, 'Ewing Township', 'NJ', 'The State Police museum preserves uniforms, vehicles, forensic material and evidence associated with major New Jersey cases. Its best-known collection covers the Lindbergh kidnapping investigation, including artifacts and investigative material from one of America''s most famous crimes.', 'limited', null, 'https://www.nj.gov/njsp/about/museum.shtml', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Orleans Pharmacy Museum', 'new-orleans-pharmacy-museum', 'museums', 29.95605, -90.0649, 'New Orleans', 'LA', 'Housed in an early nineteenth-century apothecary, the museum preserves antique medicines, surgical tools, patent remedies and pharmacy equipment. Its collection includes objects that show how strange and dangerous medicine could be before modern regulation.', 'limited', null, 'https://pharmacymuseum.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('No. 9 Coal Mine and Museum', 'no-9-coal-mine-and-museum', 'museums', 40.82867, -75.89693, 'Lansford', 'PA', 'No. 9 operated as an anthracite mine from the nineteenth century until 1972 and was later reopened as a preserved underground attraction. Seasonal tours take visitors about 1,600 feet into the mountain by rail before a guided walk past the mine shaft, mule way and underground hospital.', 'limited', null, 'https://no9coalmine.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('North Carolina Taxidermy Hall of Fame, Creation Museum & Antique Tool Museum', 'north-carolina-taxidermy-hall-of-fame-creation-museum-antique-tool-museum', 'museums', 35.17465, -79.39135, 'Southern Pines', 'NC', 'Several highly unusual collections share this roadside museum complex, combining elaborate taxidermy, antique tools, and creationist displays under one roof. The mix makes it one of the stranger museum combinations in North Carolina. Current local listing: https://www.moorechoices.net/', 'limited', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Northlandz', 'northlandz', 'museums', 40.5171, -74.81933, 'Raritan Township', 'NJ', 'This enormous indoor model-railroad world contains miles of track, hundreds of bridges, miniature cities and an almost overwhelming amount of handmade scenery. The sprawling attraction feels less like a conventional train layout and more like walking around an invented miniature country.', 'open', null, 'https://northlandz.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nostalgia Station Toy Museum', 'nostalgia-station-toy-museum', 'museums', 38.05569, -84.72602, 'Versailles', 'KY', 'A former railroad depot houses a collection of antique and vintage toys, model trains and related memorabilia. The combination of railroad architecture and decades of childhood objects gives the small museum the feeling of a carefully preserved time capsule.', 'limited', null, 'https://museumsdatabase.com/museums/view/11796', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ohr-O''Keefe Museum of Art', 'ohr-okeefe-museum-of-art', 'museums', 30.39361, -88.87167, 'Biloxi', 'MS', 'A Frank Gehry-designed museum campus centered on the wildly experimental ceramic work of Biloxi''s self-described "Mad Potter," George Ohr. The eccentric pottery and unusual architecture make the museum a natural OddWay stop even without paranormal or roadside folklore.', 'open', null, 'https://georgeohr.org/visit/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Barracks Museum', 'old-barracks-museum', 'museums', 40.21988, -74.76865, 'Trenton', 'NJ', 'Built in 1758 during the French and Indian War, these military barracks later housed troops during the American Revolution. The surviving complex now interprets eighteenth-century soldier life and Trenton''s role in the Revolutionary War.', 'limited', null, 'https://www.barracks.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Country Store and Museum', 'old-country-store-and-museum', 'museums', 43.75516, -71.39632, 'Moultonborough', 'NH', 'Operating in a building with roots dating to 1781, the Old Country Store combines a working general store with an upstairs collection of historical objects and curiosities. The densely packed rooms feel closer to an old cabinet of local oddities than a polished modern museum. The business currently operates year-round.', 'open', null, 'https://nhcountrystore.com/', '2026-09-09T04:49:39.808526+00:00', null, 'https://nhcountrystore.com/', null, null, null, 'America/New_York'),
  ('Old Court House Museum', 'old-court-house-museum', 'museums', 32.35205, -90.87862, 'Vicksburg', 'MS', 'An 1858-60 courthouse turned local-history museum, filled with Civil War artifacts, furniture, portraits, tools and other objects tied to Vicksburg''s past. The building itself survived the siege and remains one of the city''s most recognizable historic structures. Coordinate source: National Register documentation', 'open', null, 'https://oldcourthouse.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Optical Heritage Museum', 'optical-heritage-museum', 'museums', 42.08035, -72.03516, 'Southbridge', 'MA', 'Southbridge''s long history as an optical-manufacturing center survives in a museum filled with antique spectacles, lenses, machinery, microscopes and experimental eyewear. The collection follows the evolution of vision technology through objects that range from elegant to genuinely bizarre.', 'limited', null, 'https://www.atlasobscura.com/places/optical-heritage-museum', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.opticalheritagemuseum.org/', null, null, null, 'America/New_York'),
  ('Original American Kazoo Company Museum', 'original-american-kazoo-company-museum', 'museums', 42.64911, -78.89839, 'Eden', 'NY', 'The Original American Kazoo Company began producing metal kazoos here in 1916, and the surviving factory now includes a small museum packed with historic kazoos and production equipment. Visitors can see how the instruments are made and, on operating days, make a kazoo of their own.', 'open', null, 'https://www.edenkazoo.com/museum.php', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oscar Getz Museum of Whiskey History', 'oscar-getz-museum-of-whiskey-history', 'museums', 37.81008, -85.47022, 'Bardstown', 'KY', 'Rather than functioning as another bourbon tasting room, this museum follows American whiskey history through old bottles, advertising, distilling equipment and Prohibition-era artifacts. Its collection has included objects associated with figures ranging from George Washington to early Kentucky whiskey producers.', 'open', null, 'https://www.atlasobscura.com/places/oscar-getz-museum-of-whiskey-history', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.oscargetzwhiskeymuseum.com/', null, null, null, 'America/New_York'),
  ('Otherworld', 'otherworld', 'museums', 39.92214, -82.83583, 'Columbus', 'OH', 'Otherworld is a 32,000-square-foot immersive art attraction made up of dozens of interconnected rooms filled with large-scale installations, secret passages, surreal creatures and interactive technology. The Columbus experience opened in 2019 and operates as a ticketed indoor attraction during posted sessions.', 'open', null, 'https://www.otherworld.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Owls Head Transportation Museum', 'owls-head-transportation-museum', 'museums', 44.06617, -69.10127, 'Owls Head', 'ME', 'This working transportation museum preserves early aircraft, automobiles, motorcycles, engines, and other machines, with many exhibits maintained in operating condition. Demonstrations and special events can make the collection feel more like a living mechanical time capsule than a static museum.', 'limited', null, 'https://www.atlasobscura.com/places/owls-head-transportation-museum', '2026-09-09T04:54:23.476824+00:00', null, 'https://owlshead.org/', null, null, null, 'America/New_York'),
  ('Pachinko World', 'pachinko-world', 'museums', 34.19477, -77.91997, 'Wilmington', 'NC', 'This unusual arcade focuses on Japanese pachinko machines, combining playable vintage machines with other retro games and memorabilia. The dense rows of flashing vertical games look very different from a standard American arcade.', 'open', null, 'https://www.atlasobscura.com/places/pachinko-world', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paterson Museum', 'paterson-museum', 'museums', 40.91348, -74.17882, 'Paterson', 'NJ', 'Housed in the former Rogers Locomotive Works, the Paterson Museum preserves locomotives, industrial machinery, Colt firearms, minerals and objects tied to the city''s manufacturing history. The eclectic collection reflects how many different industries once clustered around the Great Falls.', 'limited', null, 'https://www.patersonnj.gov/department/division.php?structureid=16', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul A. Johnson Pencil Sharpener Museum', 'paul-a-johnson-pencil-sharpener-museum', 'museums', 39.53632, -82.44459, 'Logan', 'OH', 'This tiny museum beside the Hocking Hills Regional Welcome Center holds thousands of pencil sharpeners collected by the late Paul A. Johnson and later expanded through additional donations. The display ranges from ordinary desk sharpeners to novelty designs shaped like animals, landmarks and household objects and can be visited during welcome-center hours.', 'open', null, 'https://www.explorehockinghills.com/things-to-do/arts-museums/museums/pencil-sharpener-museum/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan Historical Museum', 'paul-bunyan-historical-museum', 'museums', 47.003669, -94.730578, 'Akeley', 'MN', 'Opened in 1984, combining Paul Bunyan memorabilia with photographs and artefacts from Akeley''s years as a logging and sawmill town. Volunteer-run, directly behind the town''s giant kneeling Paul Bunyan statue, and generally open in summer when volunteers are available.', 'limited', null, 'https://akeleymn.com/pbhs/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Paul Bunyan Logging Camp Museum', 'paul-bunyan-logging-camp-museum', 'museums', 44.810459, -91.517919, 'Eau Claire', 'WI', 'A reproduction of an 1890s Wisconsin logging camp, built in Carson Park in 1934-35 with help from men who had actually done the work. Now part of the Chippewa Valley Museum campus: bunkhouse, cook shanty, blacksmith shop and equipment exhibits. Seasonal, and admission is charged.', 'limited', null, 'https://www.cvmuseum.com/explore/museum-exhibits/47/logging-center-and-paul-bunyan-logging-camp/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Peary-MacMillan Arctic Museum', 'peary-macmillan-arctic-museum', 'museums', 43.90777, -69.9599, 'Brunswick', 'ME', 'Bowdoin College’s Arctic museum preserves artifacts, photographs, equipment, and records connected with Arctic exploration and northern cultures. Its collections are closely tied to explorers Robert E. Peary and Donald B. MacMillan, both Bowdoin graduates.', 'limited', null, 'https://www.atlasobscura.com/places/peary-macmillan-arctic-museum', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pencil Collection and Odd Dummies — Old Lake County Courthouse', 'pencil-collection-and-odd-dummies-old-lake-county-courthouse', 'museums', 41.41722, -87.36583, 'Crown Point', 'IN', 'Inside the historic Old Lake County Courthouse is an eccentric collection that has included thousands of pencils alongside mannequins, local memorabilia and displays tied to courthouse history. The strange assortment makes the building more than a conventional courthouse museum, but exhibit access follows the historical society''s seasonal hours.', 'limited', null, 'https://www.roadsideamerica.com/tip/6135', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Percy Skuy Collection on the History of Contraception', 'percy-skuy-collection-on-the-history-of-contraception', 'museums', 41.50596, -81.60844, 'Cleveland', 'OH', 'The Dittrick Medical History Center holds the Percy Skuy Collection, roughly 1,100 historical contraceptive devices, prototypes, packaging pieces and related artifacts assembled into one of the most extensive collections of its kind. The museum is free and open to the public, but as of 2026 its regular gallery hours are limited to Fridays and Saturdays.', 'limited', null, 'https://artsci.case.edu/dittrick/collections/aritfacts/contraception-collection/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Periodic Display of the Elements', 'periodic-display-of-the-elements', 'museums', 39.6364, -86.86195, 'Greencastle', 'IN', 'Inside DePauw University''s Julian Science and Mathematics Center is a large periodic table containing actual element samples or representative objects whenever safety allows. Instead of treating the periodic table as a flat chart, the installation turns chemistry into a cabinet of physical curiosities.', 'limited', null, 'https://www.roadsideamerica.com/tip/53091', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Pest House Medical Museum', 'pest-house-medical-museum', 'museums', 37.4157, -79.15795, 'Lynchburg', 'VA', 'Lynchburg''s Pest House served as a quarantine facility for contagious patients and later became closely associated with Civil War-era medical history. The building was moved to Old City Cemetery in 1987 and now contains period medical displays that visitors can examine as part of the cemetery''s historic grounds.', 'open', null, 'https://www.atlasobscura.com/places/pest-house-medical-museum', '2026-09-08T04:17:48.352537+00:00', null, 'https://gravegarden.org/', null, null, null, 'America/New_York'),
  ('PEZ Visitor Center', 'pez-visitor-center', 'museums', 41.26367, -72.99754, 'Orange', 'CT', 'PEZ''s Connecticut visitor center holds the world''s largest public collection of PEZ memorabilia, a giant dispenser and windows into the working candy factory. It turns one of the world''s strangest candy-delivery systems into a full museum stop.', 'open', null, 'https://www.atlasobscura.com/places/pez-visitor-center', '2026-09-08T18:39:47.144889+00:00', null, 'https://us.pez.com/pages/hours-and-location', null, null, null, 'America/New_York'),
  ('Pickle Barrel House', 'pickle-barrel-house', 'museums', 46.67092, -85.98469, 'Grand Marais', 'MI', 'Cartoonist William Donahey received this barrel-shaped cottage in the 1920s, inspired by the tiny barrel homes in his Teenie Weenies comic strip. The restored structure now operates seasonally as a museum and looks exactly like two giant wooden pickle barrels joined together.', 'limited', null, 'https://www.atlasobscura.com/places/pickle-barrel-house', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Pioneer Museum of Alabama', 'pioneer-museum-of-alabama', 'museums', 31.82453, -85.9962, 'Troy', 'AL', 'A collection of relocated historic buildings, farm equipment, a logging locomotive, grist mill and period interiors recreates pieces of rural Alabama life. The grounds function as an open-air museum rather than a single gallery building.', 'open', null, 'https://www.pioneer-museum.org/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pioneer Tunnel Coal Mine', 'pioneer-tunnel-coal-mine', 'museums', 40.77821, -76.35255, 'Ashland', 'PA', 'Pioneer Tunnel has taken visitors into an authentic anthracite mine since 1962. Seasonal tours ride underground in mine cars, and a separate narrow-gauge steam train follows the mountainside above Ashland.', 'limited', null, 'https://www.pioneertunnel.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pocahontas Exhibition Coal Mine', 'pocahontas-exhibition-coal-mine', 'museums', 37.30725, -81.34627, 'Pocahontas', 'VA', 'Coal mining began at Pocahontas in the 1880s, helping launch the region''s industrial boom and feed the Norfolk and Western Railway. Part of the historic mine is now preserved as the Pocahontas Exhibition Mine, where seasonal tours take visitors underground to see mining equipment, coal seams and the working environment of early miners.', 'limited', null, 'https://www.atlasobscura.com/places/pocahontas-exhibition-coal-mine', '2026-09-08T04:17:48.352537+00:00', null, 'https://www.pocahontasva.org/', null, null, null, 'America/New_York'),
  ('Pontiac-Oakland Automobile Museum', 'pontiac-oakland-automobile-museum', 'museums', 40.8798, -88.62993, 'Pontiac', 'IL', 'A specialty museum devoted entirely to Pontiac and Oakland automobiles, advertising, dealer materials, engines, and related brand history.', 'limited', null, 'https://www.pontiacoaklandmuseum.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Popeye Museum / Spinach Can Collectibles', 'popeye-museum-spinach-can-collectibles', 'museums', 37.91227, -89.82303, 'Chester', 'IL', 'The former opera house where young E. C. Segar worked now contains thousands of Popeye collectibles and one of the world''s most concentrated Popeye displays.', 'limited', null, 'https://www.greatriverroad-illinois.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Potter''s Wax Museum', 'potters-wax-museum', 'museums', 29.89868, -81.31494, 'St. Augustine', 'FL', 'Long-running wax museum mixing historic figures, celebrities, and horror displays.', 'limited', null, 'https://www.potterswax.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Powder Hill Dinosaur Park', 'powder-hill-dinosaur-park', 'museums', 41.50272, -72.73062, 'Middlefield', 'CT', 'Exposed rock at this small park preserves Early Jurassic dinosaur footprints that visitors can see and touch without entering a museum. It is a compact but unusually direct encounter with Connecticut''s prehistoric past.', 'open', null, 'https://www.atlasobscura.com/places/powder-hill-dinosaur-park', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Prairie Acadian Cultural Center', 'prairie-acadian-cultural-center', 'museums', 30.49315, -92.41731, 'Eunice', 'LA', 'This National Park Service center explores Cajun and Creole prairie culture through music, foodways, language and demonstrations. Live programs vary by day, making the calendar worth checking.', 'open', null, 'https://www.nps.gov/jela/planyourvisit/prairie-acadian-cultural-center.htm', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ragtops Motorcars Museum', 'ragtops-motorcars-museum', 'museums', 26.61668, -80.06977, 'Lake Worth Beach', 'FL', 'Vintage-car collection and memorabilia in a retro event space.', 'limited', null, 'https://ragtopsmotorcars.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rahr-West Art Museum', 'rahr-west-art-museum', 'museums', 44.09772, -87.65668, 'Manitowoc', 'WI', 'A Victorian mansion and modern gallery addition contain fine art, decorative objects and local-history material. The grounds also connect directly with Manitowoc''s Sputnik story, making the museum a useful stop for both art and space-age weird history.', 'open', null, 'https://www.rahrwestartmuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.rahrwestartmuseum.org/', null, null, null, 'America/Chicago'),
  ('Red Mill Museum Village', 'red-mill-museum-village', 'museums', 40.63715, -74.914, 'Clinton', 'NJ', 'The striking red mill beside the South Branch Raritan River operated in several industrial roles before becoming the centerpiece of a historical museum complex. More than a dozen buildings and thousands of artifacts preserve the site''s industrial and local history.', 'limited', null, 'https://theredmill.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ripley''s Believe It or Not! Orlando', 'ripleys-believe-it-or-not-orlando', 'museums', 28.44818, -81.47001, 'Orlando', 'FL', 'Tilted ''sinking'' building packed with sideshow-style oddities and unusual artifacts.', 'limited', null, 'https://www.ripleys.com/orlando', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ripley''s Believe It or Not! St. Augustine', 'ripleys-believe-it-or-not-st-augustine', 'museums', 29.90174, -81.31547, 'St. Augustine', 'FL', 'Original permanent Ripley''s museum inside a castle-like former hotel packed with unusual artifacts.', 'limited', null, 'https://www.ripleys.com/staugustine', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Roanoke Pinball Museum', 'roanoke-pinball-museum', 'museums', 37.27156, -79.93956, 'Roanoke', 'VA', 'The Roanoke Pinball Museum preserves dozens of playable machines tracing pinball from early mechanical games through modern electronic tables. Admission is built around actually playing the collection rather than viewing it behind glass, making it an interactive history of arcade technology.', 'open', null, 'https://roanokepinball.org/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rock Island Arsenal Museum', 'rock-island-arsenal-museum', 'museums', 41.51781, -90.54038, 'Rock Island Arsenal', 'IL', 'One of the U.S. Army''s oldest museums traces weapons, manufacturing, and the history of the active Rock Island Arsenal.', 'limited', null, 'https://www.army.mil/arsenal/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Roebling Museum', 'roebling-museum', 'museums', 40.11865, -74.77318, 'Roebling', 'NJ', 'The former John A. Roebling''s Sons factory site interprets the wire-rope company responsible for material used in famous suspension bridges including the Brooklyn and Golden Gate bridges. Industrial machinery, photographs and factory artifacts survive inside the company-town museum.', 'limited', null, 'https://www.roeblingmuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rose Ferron Foundation Museum & Domestic Chapel', 'rose-ferron-foundation-museum-domestic-chapel', 'museums', 42.00693, -71.5118, 'Woonsocket', 'RI', 'The Rose Ferron Foundation preserves personal objects, devotional material and portions of an elaborate handmade Domestic Chapel connected to Marie "Little Rose" Ferron. The organization occupies a castle-like former commercial building at 339 Arnold Street and continues restoring the museum complex. Check ahead because renovation can affect what is open to visitors.', 'limited', null, 'https://roseferronfri.org/new-location', '2026-09-09T04:49:27.913704+00:00', null, 'https://roseferronfri.org/', null, null, null, 'America/New_York'),
  ('Rota the Lion at the Lightner Museum', 'rota-the-lion-at-the-lightner-museum', 'museums', 29.89112, -81.31406, 'St. Augustine', 'FL', 'Taxidermy lion with an unusual Winston Churchill connection inside an already eccentric Gilded Age collection.', 'limited', null, 'https://lightnermuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rotary Jail Museum', 'rotary-jail-museum', 'museums', 40.04385, -86.90174, 'Crawfordsville', 'IN', 'Built around a rotating circular cell block, Crawfordsville''s 1882 jail used a hand-cranked mechanism to bring individual cells to the only opening. The preserved structure is now a museum and is notable as the only surviving rotary jail whose cell block can still be operated.', 'limited', null, 'https://www.rotaryjailmuseum.org/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.rotaryjailmuseum.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Rothschild Patent Model Collection', 'rothschild-patent-model-collection', 'museums', 39.78594, -75.58056, 'Wilmington', 'DE', 'Hagley preserves nearly 5,000 nineteenth-century patent models — tiny working proofs once required with U.S. patent applications. About 100 are displayed in the library, creating a room full of miniature Victorian inventions, mechanisms and forgotten ideas.', 'limited', null, 'https://www.hagley.org/patentmodels', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.hagley.org/', null, null, null, 'America/New_York'),
  ('Route 66 Arcade Museum', 'route-66-arcade-museum', 'museums', 40.26024, -89.23142, 'Atlanta', 'IL', 'A compact museum of vintage coin-operated amusements preserves old pinball machines, arcade games, mechanical devices, and roadside entertainment history.', 'limited', null, 'https://www.atlantaillinois.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Route 66 Motorheads Museum', 'route-66-motorheads-museum', 'museums', 39.713, -89.6474, 'Springfield', 'IL', 'A restaurant and museum complex crams vintage race cars, neon, pumps, signs, engines, and Route 66 artifacts into a former truck stop.', 'limited', null, 'https://66motorheads.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ruby City Museum', 'ruby-city-museum', 'museums', 35.18228, -83.37888, 'Franklin', 'NC', 'Hidden inside a long-running gem shop is a free museum packed with minerals, fossils, artifacts, skulls, and unusual specimens. Highlights have included an enormous sapphire, a huge amethyst, fossilized dinosaur coprolite, and a purported shrunken head. Location: https://www.visitsmokies.org/listings/ruby-city-gems-minerals/', 'open', null, 'https://www.rubycity.com/home', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('RV/MH Hall of Fame and Museum', 'rv-mh-hall-of-fame-and-museum', 'museums', 41.72924, -85.87985, 'Elkhart', 'IN', 'Elkhart''s RV/MH Hall of Fame preserves historic recreational vehicles ranging from primitive camping trailers to elaborate motorhomes. Walking through decades of changing interiors and technology makes the collection feel like a timeline of increasingly strange mobile living spaces.', 'open', null, 'https://www.rvmhhalloffame.org/', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.rvmhhalloffame.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Safety Harbor Museum & Cultural Center', 'safety-harbor-museum-cultural-center', 'museums', 27.99055, -82.68913, 'Safety Harbor', 'FL', 'Local museum built near ancient shell mounds and focused on Tocobaga and regional history.', 'limited', null, 'https://www.cityofsafetyharbor.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Saint Anthony Chapel', 'saint-anthony-chapel', 'museums', 40.46489, -79.98369, 'Pittsburgh', 'PA', 'Saint Anthony Chapel in Troy Hill houses more than 5,000 religious relics, one of the largest publicly accessible collections outside the Vatican. The active Catholic chapel is open during posted hours, and visitors can see reliquaries containing remains and objects associated with hundreds of saints.', 'open', null, 'https://saintanthonyschapel.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salem Witch Board Museum', 'salem-witch-board-museum', 'museums', 42.52222, -70.89089, 'Salem', 'MA', 'A small museum explores Ouija boards, spirit communication and talking-board history through vintage boards and related objects. It gives Salem a paranormal stop centered on Spiritualism and commercial occult culture rather than the 1692 trials.', 'limited', null, 'https://www.atlasobscura.com/places/salem-witch-board-museum', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salt Museum', 'salt-museum', 'museums', 43.10002, -76.20705, 'Liverpool', 'NY', 'Built beside Onondaga Lake in 1933, this small museum preserves the story of the salt industry that gave nearby Syracuse its nickname, the Salt City. Exhibits explain brine wells, boiling blocks and salt production, with free public hours running seasonally from May into October.', 'limited', null, 'https://onondagacountyparks.com/parks/onondaga-lake-park/salt-museum/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salt & Pepper Shaker Museum', 'salt-pepper-shaker-museum', 'museums', 35.71623, -83.50247, 'Gatlinburg', 'TN', 'Tens of thousands of salt and pepper shakers fill this small museum, arranged by subject, era and design. The obsessive scale of the collection turns an ordinary tabletop object into one of Gatlinburg''s most genuinely eccentric museums.', 'open', null, 'https://thesaltandpeppershakermuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Schimpff''s Confectionery and Candy Museum', 'schimpffs-confectionery-and-candy-museum', 'museums', 38.27258, -85.74136, 'Jeffersonville', 'IN', 'The Schimpff family has operated this downtown candy business at its present site since 1891. Its museum preserves antique candy equipment, packaging and memorabilia, and visitors can often watch candy being made on machinery that looks almost as unusual as the collection itself.', 'open', null, 'https://www.atlasobscura.com/places/schimpffs-confectionery', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.schimpffs.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Scottish Tartans Museum', 'scottish-tartans-museum', 'museums', 35.18213, -83.37962, 'Franklin', 'NC', 'The only museum of its kind in the United States is devoted to tartans, kilts, Highland dress, weaving, Scottish weaponry, and Scottish migration to the Carolinas. Its collection includes centuries-old tartan samples and hundreds of patterns.', 'open', null, 'https://www.atlasobscura.com/places/scottish-tartans-museum', '2026-09-09T05:34:33.398594+00:00', null, 'https://scottishtartansmuseum.org/', null, null, null, 'America/New_York'),
  ('Seal Cove Auto Museum', 'seal-cove-auto-museum', 'museums', 44.30542, -68.40422, 'Tremont', 'ME', 'This Mount Desert Island museum concentrates on automobiles and motorcycles from the earliest decades of motoring, including exceptionally old and unusual vehicles. Period accessories and devices help show just how experimental road travel looked before modern cars became standardized.', 'limited', null, 'https://www.atlasobscura.com/places/seal-cove-auto-museum', '2026-09-09T04:54:23.476824+00:00', null, 'https://www.sealcoveautomuseum.org/', null, null, null, 'America/New_York'),
  ('Seashore Trolley Museum', 'seashore-trolley-museum', 'museums', 43.407, -70.4896, 'Kennebunkport', 'ME', 'The Seashore Trolley Museum preserves a huge collection of historic streetcars, buses, rapid-transit vehicles, and other public transportation equipment. Seasonal operating days can include rides aboard restored railway vehicles.', 'limited', null, 'https://trolleymuseum.org/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shelburne Museum', 'shelburne-museum', 'museums', 44.37325, -73.23227, 'Shelburne', 'VT', 'Rather than fitting its collection into one building, Shelburne Museum spreads art, Americana and historic structures across a large campus. Its stranger holdings include an entire steamboat brought inland, a lighthouse, circus material, historic houses and other full-size structures collected as museum objects.', 'limited', null, 'https://shelburnemuseum.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shoeless Joe Jackson Museum', 'shoeless-joe-jackson-museum', 'museums', 34.84121, -82.40841, 'Greenville', 'SC', 'The former home of baseball legend “Shoeless” Joe Jackson was moved beside Fluor Field and transformed into a museum. Exhibits cover Jackson’s remarkable playing career and the enduring controversy surrounding the 1919 Black Sox scandal.', 'limited', null, 'https://www.shoelessjoejackson.org/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shrine of the Pines', 'shrine-of-the-pines', 'museums', 43.85983, -85.8483, 'Baldwin', 'MI', 'Raymond Overholzer spent years turning naturally fallen pine roots, stumps and branches into highly polished furniture without conventional metal fasteners. The hunting-lodge museum now contains more than 200 of his handmade pieces, including enormous tables, beds and chandeliers.', 'limited', null, 'https://www.michigan.org/property/shrine-pines', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Silverball Retro Arcade', 'silverball-retro-arcade', 'museums', 40.2208, -73.99998, 'Asbury Park', 'NJ', 'Rows of playable pinball machines and classic arcade games fill this boardwalk museum, with machines spanning many decades of amusement history. Admission is time-based rather than coin-operated, so the collection functions as both museum and working arcade.', 'open', null, 'https://www.silverballmuseum.com/asbury-park/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Simpson Funeral Museum', 'simpson-funeral-museum', 'museums', 36.82576, -79.39869, 'Chatham', 'VA', 'Tucked into a working funeral home, this small museum preserves antique caskets, embalming equipment, hearses, burial clothing and other artifacts from the funeral profession. Because it is attached to an active business rather than a conventional attraction, visitors should verify hours before making a special trip.', 'limited', null, 'https://www.roadsideamerica.com/tip/10262', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skeletons: Museum of Osteology', 'skeletons-museum-of-osteology', 'museums', 28.44206, -81.46891, 'Orlando', 'FL', 'Hundreds of real animal skeletons arranged as a comparative anatomy museum.', 'limited', null, 'https://skeletonmuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Slater Memorial Museum — Mummified Human Arm', 'slater-memorial-museum-mummified-human-arm', 'museums', 41.53629, -72.08152, 'Norwich', 'CT', 'Among the art and historical collections at the Slater Memorial Museum is a preserved human arm brought back from Egypt during the nineteenth century. The unexpected mummy fragment is one of the strangest objects in an otherwise traditional museum.', 'limited', null, 'https://www.roadsideamerica.com/story/56735', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.slatermuseum.org/', null, null, null, 'America/New_York'),
  ('''Snowflake'' Bentley Exhibit', 'snowflake-bentley-exhibit', 'museums', 44.50468, -72.99952, 'Jericho', 'VT', 'Wilson Bentley became the first person to successfully photograph a single snow crystal in 1885 and went on to create thousands of images. The Old Red Mill preserves his equipment, photographs and story in the Vermont community where his fascination with snow began.', 'limited', null, 'https://www.atlasobscura.com/places/snowflake-bentley', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Snowmobile Hall of Fame', 'snowmobile-hall-of-fame', 'museums', 45.90828, -89.48965, 'St. Germain', 'WI', 'Historic racing sleds, pioneering machines, trophies and memorabilia fill a museum dedicated to snowmobiling. The collection fits naturally in the Northwoods, where the machine became both transportation and winter culture.', 'limited', null, 'https://www.snowmobilehalloffame.com/museum/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.snowmobilehalloffame.com/', null, null, null, 'America/Chicago'),
  ('Sock Monkey Museum', 'sock-monkey-museum', 'museums', 42.1784, -87.9979, 'Long Grove', 'IL', 'More than 2,000 sock monkeys and related displays fill this specialty museum devoted to the humble red-heel folk toy.', 'limited', null, 'https://sockmonkeymuseum.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Space Farms Zoo & Museum', 'space-farms-zoo-museum', 'museums', 41.20925, -74.69494, 'Wantage Township', 'NJ', 'This family-run complex combines a zoo with nine buildings packed with antique cars, motorcycles, farm equipment, minerals and other collected objects. The unusually broad museum collection makes Space Farms much stranger than a standard animal park; its public season runs primarily from spring through fall.', 'limited', null, 'https://spacefarms.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spinning Top & Yo-Yo Museum', 'spinning-top-yo-yo-museum', 'museums', 42.67863, -88.27698, 'Burlington', 'WI', 'A small museum is devoted almost entirely to spinning tops, yo-yos and related kinetic toys. Demonstrations and hands-on displays turn simple childhood objects into a deep dive on balance, motion and toy history.', 'limited', null, 'https://www.topmuseum.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.topmuseum.org/', null, null, null, 'America/Chicago'),
  ('Spongeorama Sponge Factory', 'spongeorama-sponge-factory', 'museums', 28.15611, -82.75664, 'Tarpon Springs', 'FL', 'Old-school sponge museum and retail attraction explaining the region''s diving industry.', 'limited', null, 'https://spongeorama.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spring Grove Hospital Center Alumni Museum', 'spring-grove-hospital-center-alumni-museum', 'museums', 39.26692, -76.72195, 'Catonsville', 'MD', 'Spring Grove traces its institutional history to 1797, making it one of the oldest continuously operating psychiatric hospitals in the United States. Its small alumni museum preserves early medical equipment, photographs, furniture and records from the hospital''s past, but visits are guided and by appointment.', 'limited', null, 'https://health.maryland.gov/springgrove/phototours/Pages/museum.aspx', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Spring Lake Arcade', 'spring-lake-arcade', 'museums', 41.98668, -71.65689, 'Glendale', 'RI', 'Inside Spring Lake Beach is a remarkable collection of vintage coin-operated amusement machines, including mechanical games dating back generations. The arcade is often described as one of the country''s oldest penny arcades still in operation. It follows the seasonal schedule of the town beach, so verify the current season before traveling.', 'limited', null, 'https://www.burrillville.org/business-directory/spring-lake-arcade', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.burrillville.org/parks-recreation/pages/spring-lake-beach', null, null, null, 'America/New_York'),
  ('S.S. City of Milwaukee', 'ss-city-of-milwaukee', 'museums', 44.2594, -86.31496, 'Manistee', 'MI', 'Built in 1930, the City of Milwaukee carried railroad cars across Lake Michigan before being preserved as a museum ship. Guided tours pass through the working spaces and steep stairways of the old car ferry; the 2026 regular tour season ended August 30, so fall access should be checked before routing here.', 'limited', null, 'https://www.carferry.com/tours', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.carferry.com/', null, null, null, 'America/Detroit'),
  ('SS Meteor Whaleback Ship Museum', 'ss-meteor-whaleback-ship-museum', 'museums', 46.68934, -92.01955, 'Superior', 'WI', 'SS Meteor is the last surviving example of the unusual whaleback cargo-ship design developed for Great Lakes service. The vessel''s rounded cigar-like hull can be toured seasonally at Barker''s Island.', 'limited', null, 'https://www.superiorwi.gov/60/SS-Meteor', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.superiorhistoricproperties.org/', null, null, null, 'America/Chicago'),
  ('St. Augustine Pirate & Treasure Museum', 'st-augustine-pirate-treasure-museum', 'museums', 29.89789, -81.31266, 'St. Augustine', 'FL', 'Pirate museum with shipwreck objects, weapons, treasure, and rare historic pirate artifacts.', 'limited', null, 'https://thepiratemuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stabler-Leadbeater Apothecary Museum', 'stabler-leadbeater-apothecary-museum', 'museums', 38.80472, -77.0425, 'Alexandria', 'VA', 'This remarkably preserved pharmacy operated from 1792 until 1933 and reopened almost immediately as a museum, leaving shelves, bottles, medical ingredients and equipment largely frozen in place. Visitors can see thousands of historical medical and commercial objects on scheduled museum tours.', 'limited', null, 'https://www.alexandriava.gov/museums/location/visit-stabler-leadbeater-apothecary-museum', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stahls Automotive Foundation Museum', 'stahls-automotive-foundation-museum', 'museums', 42.71783, -82.80683, 'Chesterfield Township', 'MI', 'Stahls combines rare and unusual automobiles with a large collection of automated musical instruments, organs and mechanical music machines. The mixture of transportation and giant self-playing instruments makes the museum substantially stranger than a standard classic-car collection.', 'limited', null, 'https://www.stahlsauto.com/', '2026-09-08T15:31:15.588137+00:00', null, 'https://www.stahlsauto.com/', null, null, null, 'America/Detroit'),
  ('Stanley Museum', 'stanley-museum', 'museums', 44.95536, -70.1553, 'Kingfield', 'ME', 'The Stanley family produced far more than the famous Stanley Steamer automobile. This museum explores their steam cars alongside photography, early airbrush technology, violins, and other inventions connected to a remarkably inventive Maine family.', 'limited', null, 'https://stanleymuseum.org/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sterling Hill Mining Museum', 'sterling-hill-mining-museum', 'museums', 41.08344, -74.60426, 'Ogdensburg', 'NJ', 'An underground zinc mine has been transformed into one of New Jersey''s strangest geology museums. Tours descend into the mine and pass the fluorescent Rainbow Tunnel, while the surface museum preserves an enormous collection of glowing minerals from the famous Franklin-Sterling Hill mining district.', 'limited', null, 'https://sterlinghillminingmuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stonewall National Museum & Archives', 'stonewall-national-museum-archives', 'museums', 26.14215, -80.12992, 'Fort Lauderdale', 'FL', 'Specialized archive and museum documenting LGBTQ history and culture.', 'limited', null, 'https://stonewall-museum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Studebaker National Museum', 'studebaker-national-museum', 'museums', 41.67471, -86.26193, 'South Bend', 'IN', 'South Bend''s Studebaker museum preserves vehicles and artifacts from the company that evolved from nineteenth-century wagon building into a major automobile manufacturer. Among its most unusual historic vehicles are presidential carriages, including the carriage associated with Abraham Lincoln''s final trip to Ford''s Theatre.', 'limited', null, 'https://www.studebakermuseum.org/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.studebakermuseum.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Submarine Force Museum & USS Nautilus', 'submarine-force-museum-uss-nautilus', 'museums', 41.3875, -72.087, 'Groton', 'CT', 'The world''s first nuclear-powered submarine, USS Nautilus, is preserved beside the official U.S. Navy Submarine Force Museum. Visitors can descend into the submarine''s cramped interior and explore the strange engineering of life underwater.', 'open', null, 'https://www.atlasobscura.com/places/submarine-force-museum', '2026-09-08T18:39:47.144889+00:00', null, 'https://ussnautilus.org/', null, null, null, 'America/New_York'),
  ('Super Museum', 'super-museum', 'museums', 37.15117, -88.732, 'Metropolis', 'IL', 'Tens of thousands of Superman collectibles, costumes, props, toys, comics, and memorabilia fill a museum directly beside the town''s giant Superman statue.', 'limited', null, 'https://supermuseum.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sussex Tavern — Stockley-Street House', 'sussex-tavern-stockley-street-house', 'museums', 38.77679, -75.14294, 'Lewes', 'DE', 'The Lewes Historical Society operates a recreated colonial tavern inside the circa-1740 Stockley-Street House, drawing inspiration from a real local tavern that operated around the turn of the nineteenth century. Historic drinks, period surroundings and occasional community events turn the preserved house into something much more experiential than a conventional museum room.', 'limited', null, 'https://www.historiclewes.org/locations/sussex-tavern/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.historiclewes.org/locations/sussex-tavern/', null, null, null, 'America/New_York'),
  ('Swamp Pop Music Museum', 'swamp-pop-music-museum', 'museums', 30.6893, -92.27345, 'Ville Platte', 'LA', 'The museum documents swamp pop, the South Louisiana blend of rhythm and blues, country and Cajun influences that produced a distinctive regional sound. Displays focus on performers, recordings and local music infrastructure.', 'limited', null, 'https://www.evangelineparishtourism.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sylvia Hardy — Life-Size Maine Giantess', 'sylvia-hardy-life-size-maine-giantess', 'museums', 44.58617, -70.23395, 'Wilton', 'ME', 'The Wilton Farm and Home Museum displays a life-size figure of Sylvia Hardy, a Maine woman who stood more than seven and a half feet tall and later toured with P.T. Barnum’s shows. The exhibit includes one of Hardy’s actual dresses, making her extraordinary height much easier to comprehend.', 'limited', null, 'https://www.roadsideamerica.com/tip/36288', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tahquamenon Logging Museum', 'tahquamenon-logging-museum', 'museums', 46.37083, -85.50917, 'Newberry', 'MI', 'This seasonal museum preserves the machinery, buildings and daily-life artifacts of Michigan''s Upper Peninsula logging era. Its grounds include reconstructed camp spaces and equipment that show how crews lived and worked when timber drives shaped much of the region.', 'limited', null, 'https://www.loggingmuseum.com/', '2026-09-08T15:31:15.588137+00:00', null, 'https://www.loggingmuseum.com/', null, null, null, 'America/Detroit'),
  ('Tallahassee Automobile Museum', 'tallahassee-automobile-museum', 'museums', 30.48644, -84.16249, 'Tallahassee', 'FL', 'A ''collection of collections'' featuring vintage cars, authentic movie Batmobiles, antique machines, and assorted Americana.', 'limited', null, 'https://tacm.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tantaquidgeon Museum', 'tantaquidgeon-museum', 'museums', 41.4742, -72.0997, 'Uncasville', 'CT', 'Founded in 1931 by Mohegan medicine woman Gladys Tantaquidgeon with her father and brother, this is one of the oldest Native American-owned and-operated museums in the United States. Its collections and setting preserve Mohegan material culture from a community-controlled perspective.', 'limited', null, 'https://www.mohegan.nsn.us/explore/museum', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.mohegan.nsn.us/explore/museum', null, null, null, 'America/New_York'),
  ('Telephone Museum', 'telephone-museum', 'museums', 44.63743, -68.56956, 'Ellsworth', 'ME', 'This hands-on museum preserves working switchboards, telephone exchanges, switching systems, and equipment spanning generations of communication technology. Its limited seasonal schedule and appointment options make it a check-ahead stop rather than a spontaneous year-round visit.', 'limited', null, 'https://thetelephonemuseum.org/plan-your-visit/', '2026-09-09T04:54:23.476824+00:00', null, 'https://thetelephonemuseum.org/', null, null, null, 'America/New_York'),
  ('Tennessee River Freshwater Pearl Museum', 'tennessee-river-freshwater-pearl-museum', 'museums', 35.96867, -88.04889, 'Camden', 'TN', 'Birdsong Resort''s pearl operation interprets Tennessee River freshwater pearls, mussels and the unusual industry built around them. Museum access and pearl-farm activities can be seasonal or scheduled, so check before making a dedicated trip.', 'limited', null, 'https://www.birdsongresort.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Apron Museum', 'the-apron-museum', 'museums', 34.81195, -88.1903, 'Iuka', 'MS', 'A tiny specialty museum devoted entirely to aprons, domestic history and the stories attached to handmade examples from different eras. It is a genuine niche collection rather than a conventional local-history museum; hours can be limited, so check ahead.', 'limited', null, 'https://visitmississippi.org/trip-ideas/mississippi-eccentricities-you-have-to-see/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Bone Museum', 'the-bone-museum', 'museums', 40.70589, -73.93718, 'Brooklyn', 'NY', 'This Brooklyn museum displays a large educational collection of real human skeletal material, including unusual pathologies, traumatic injuries and what it describes as the world''s largest public collection of human spines. It operates as a ticketed museum inside the McKibbin Lofts during posted Wednesday-through-Sunday hours.', 'open', null, 'https://www.thebonemuseum.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('The City Reliquary', 'the-city-reliquary', 'museums', 40.71395, -73.95574, 'Brooklyn', 'NY', 'The City Reliquary is a tiny community museum devoted to ordinary and eccentric pieces of New York life, from subway tokens and fragments of landmarks to collections assembled by neighborhood residents. It began as a window display and now occupies a small Williamsburg storefront with limited weekend public hours.', 'limited', null, 'https://www.cityreliquary.org/plan-your-visit/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Cushing Center', 'the-cushing-center', 'museums', 41.30318, -72.93348, 'New Haven', 'CT', 'Yale''s Cushing Center preserves more than 2,200 neurosurgical case studies along with human brain and tumor specimens collected by pioneering neurosurgeon Harvey Cushing. It is one of Connecticut''s most unusual medical collections; visitor access policies can change, so check ahead.', 'limited', null, 'https://www.atlasobscura.com/places/cushing-brain-collection', '2026-09-08T18:39:47.144889+00:00', null, 'https://library.medicine.yale.edu/cushingcenter', null, null, null, 'America/New_York'),
  ('The Dowager Empress Crystal Ball', 'the-dowager-empress-crystal-ball', 'museums', 39.9494, -75.1916, 'Philadelphia', 'PA', 'A massive rock-crystal sphere once owned by China''s Dowager Empress Cixi sits inside the Penn Museum under heavy security. The ball was famously stolen in 1988 and later recovered, adding a bizarre crime story to an already unusual object that visitors can see with normal museum admission.', 'open', null, 'https://www.atlasobscura.com/places/crystal-ball-dowager-empress-penn-museum', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Mermaid Museum', 'the-mermaid-museum', 'museums', 38.32432, -75.21907, 'Berlin', 'MD', 'This small upstairs museum in downtown Berlin treats mermaids as a mixture of folklore, art, popular culture and imagined natural history. Displays include mermaid artifacts, stories and curiosities assembled into an intentionally unusual cabinet-of-wonders experience.', 'open', null, 'https://www.berlinmermaidmuseum.com/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Mill Museum on Route 66', 'the-mill-museum-on-route-66', 'museums', 40.1434, -89.38252, 'Lincoln', 'IL', 'A restored 1929 roadside restaurant now operates as a museum interpreting Lincoln''s local Route 66 history and the building''s colorful past.', 'limited', null, 'https://www.lincolnil.gov/lincoln-route-66', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Oddporium', 'the-oddporium', 'museums', 39.81296, -75.49281, 'Arden', 'DE', 'Part oddities shop and part cabinet-of-curiosities museum, the Oddporium fills a 1911 building with antique medical equipment, funerary objects, taxidermy, preserved specimens, strange art and other deliberately bizarre finds. The owners also lean into the building''s paranormal lore, making this one of Delaware''s strongest pure OddWay stops.', 'open', null, 'https://www.roadsideamerica.com/story/62307', '2026-09-08T18:31:51.932734+00:00', null, 'https://oddporium.com/', null, null, null, 'America/New_York'),
  ('The Ohio Museum of Horror', 'the-ohio-museum-of-horror', 'museums', 40.73362, -82.78674, 'Galion', 'OH', 'The Ohio Museum of Horror is a year-round multi-floor collection devoted to horror films, true crime, occult material and macabre artifacts. Displays include movie memorabilia, Ouija boards, anatomical and funerary objects and other intentionally unsettling pieces, with public admission during posted museum hours.', 'open', null, 'https://www.natethompsonvideo.com/ohio', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Oozing Whale Skeleton of New Bedford', 'the-oozing-whale-skeleton-of-new-bedford', 'museums', 41.63547, -70.9231, 'New Bedford', 'MA', 'A huge blue whale skeleton called KOBO hangs in the New Bedford Whaling Museum and famously continued leaking natural oil for years after preparation. The massive bones are surrounded by one of the country''s most extensive whaling collections.', 'limited', null, 'https://www.atlasobscura.com/places/the-oozing-whale-skeleton-of-new-bedford-new-bedford-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Presbytère — Mardi Gras & Katrina Exhibits', 'the-presbyt-re-mardi-gras-katrina-exhibits', 'museums', 29.95826, -90.0634, 'New Orleans', 'LA', 'The Louisiana State Museum uses the Presbytère for major exhibits on Mardi Gras and Hurricane Katrina. Costumes, parade objects and disaster-history material make this far stranger than a standard civic museum.', 'open', null, 'https://louisianastatemuseum.org/museum/presbytere', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Sanctuary Museum', 'the-sanctuary-museum', 'museums', 41.47671, -81.77833, 'Lakewood', 'OH', 'Formerly known as the Museum of Divine Statues, the Sanctuary Museum preserves statues, stained glass and other sacred artwork rescued largely from closed or altered Catholic churches. The collection includes elaborate saints, relic-related objects and large architectural pieces and can be visited during its limited posted public hours.', 'open', null, 'https://www.thesanctuarymuseum.org/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Sarnoff Collection', 'the-sarnoff-collection', 'museums', 40.27096, -74.77737, 'Ewing Township', 'NJ', 'More than 6,000 artifacts at The College of New Jersey document the history of RCA, radio, television and experimental electronics. Strange prototypes include early electronic displays, obsolete video technologies and equipment tied to major twentieth-century communications breakthroughs; visits are currently by appointment.', 'limited', null, 'https://davidsarnoff.tcnj.edu/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Satanic Temple Salem Art Gallery', 'the-satanic-temple-salem-art-gallery', 'museums', 42.53138, -70.88911, 'Salem', 'MA', 'The headquarters and gallery of The Satanic Temple displays occult-themed art, organizational history and a large bronze Baphomet figure. The group describes itself as nontheistic, so the site is better understood as contemporary religious and political culture than evidence of literal devil worship.', 'limited', null, 'https://www.atlasobscura.com/places/the-satanic-temple-salem-art-gallery', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.salemartgallery.com/', null, null, null, 'America/New_York'),
  ('The Stoogeum', 'the-stoogeum', 'museums', 40.17797, -75.22414, 'Lower Gwynedd Township', 'PA', 'The Stoogeum is a museum devoted entirely to the Three Stooges, with thousands of photographs, costumes, props, posters, toys and personal artifacts. Public openings are limited and irregular compared with a conventional museum, so travelers should confirm an open house or appointment before routing here.', 'limited', null, 'https://stoogeum.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Wacky Taxidermy and Miniatures Museum', 'the-wacky-taxidermy-and-miniatures-museum', 'museums', 45.78052, -84.72625, 'Mackinaw City', 'MI', 'This small museum combines taxidermy animals with more than 60 elaborate miniature dioramas, creating deliberately absurd scenes at tiny scale. It is a legitimate walk-in attraction rather than simply a roadside display, with self-guided viewing through two buildings.', 'limited', null, 'https://www.michigan.org/property/wacky-taxidermy-and-miniatures-museum', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Thompson Ice House Harvesting Museum', 'thompson-ice-house-harvesting-museum', 'museums', 43.879, -69.5603, 'South Bristol', 'ME', 'This preserved ice house keeps alive the pre-refrigeration practice of cutting large blocks of natural pond ice during winter and storing them under insulating sawdust. Special events still demonstrate traditional ice harvesting using old tools and techniques.', 'limited', null, 'https://www.atlasobscura.com/places/the-thompson-ice-house-harvesting-museum-south-bristol-maine', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Timber Tina’s Great Maine Lumberjack Show', 'timber-tinas-great-maine-lumberjack-show', 'museums', 44.50267, -68.38465, 'Trenton', 'ME', 'Timber Tina’s outdoor show turns traditional lumberjack skills into a competitive performance featuring axe throwing, log rolling, chopping, sawing, and other old logging-camp techniques. It has the feel of a surviving piece of exaggerated North Woods culture performed live rather than preserved behind museum glass.', 'limited', null, 'https://mainelumberjack.com/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Titanic Museum', 'titanic-museum', 'museums', 42.15962, -72.50026, 'Springfield', 'MA', 'The Titanic Historical Society maintains a surprisingly deep collection of artifacts connected with the doomed ocean liner, many donated by survivors and their families. The museum occupies an unassuming building in Indian Orchard and includes documents, personal objects and a large ship model. Verify current hours before making a dedicated trip.', 'limited', null, 'https://www.atlasobscura.com/places/the-titanic-museum-springfield-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Titanic: The Artifact Exhibition', 'titanic-the-artifact-exhibition', 'museums', 28.44967, -81.47059, 'Orlando', 'FL', 'Immersive Titanic exhibit with recovered artifacts and recreated ship interiors.', 'limited', null, 'https://titanicorlando.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Top of the Lake Snowmobile Museum', 'top-of-the-lake-snowmobile-museum', 'museums', 46.09463, -85.45048, 'Naubinway', 'MI', 'More than 150 antique and unusual snow machines trace the evolution of snow travel in a region where winter transportation became a way of life. The collection includes prototypes, rare rear-engine sleds and machines that look far stranger than modern snowmobiles.', 'open', null, 'https://www.michigan.org/property/top-lake-snowmobile-museum', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.snowmobilemuseum.com/', null, null, null, 'America/Detroit'),
  ('Tour-Ed Mine', 'tour-ed-mine', 'museums', 40.61677, -79.7592, 'Tarentum', 'PA', 'Tour-Ed Mine preserves a former western Pennsylvania coal mine as an underground educational attraction. Guides take visitors into the mine to see equipment, tunnels and demonstrations of historic mining work, with tours operating on a seasonal schedule.', 'limited', null, 'https://tour-edmine.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tremé''s Petit Jazz Museum', 'trem-s-petit-jazz-museum', 'museums', 29.96693, -90.0682, 'New Orleans', 'LA', 'This small museum tells jazz history through Tremé''s musicians, neighborhoods and cultural traditions rather than through a huge institutional collection. Its intimate scale and highly local focus make it especially well suited to OddWay.', 'limited', null, 'https://tremejazzmuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Trenton Teapot Museum', 'trenton-teapot-museum', 'museums', 35.97825, -88.94135, 'Trenton', 'TN', 'An unusual municipal collection displays hundreds of ornate teapots, including elaborate porcelain and novelty forms gathered over generations. The obsessive single-object theme fits OddWay better than a conventional local-history museum.', 'limited', null, 'https://www.atlasobscura.com/places/trenton-teapot-museum', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Troll Hole Museum', 'troll-hole-museum', 'museums', 40.92191, -81.10204, 'Alliance', 'OH', 'The Troll Hole Museum is devoted to trolls and houses a collection recognized for its enormous number of troll dolls and related artifacts. Guided visits wind through themed rooms, troll displays and a fantasy-style troll cave, making it one of Ohio''s more deliberately strange museums.', 'open', null, 'https://www.thetrollhole.com/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Trundle Manor', 'trundle-manor', 'museums', 40.42274, -79.88053, 'Swissvale', 'PA', 'Trundle Manor is an inhabited private home turned appointment-only museum of taxidermy, medical devices, bizarre art and miscellaneous unsettling objects. Visitors can tour the bottom-floor collection, but **appointments are required** and the owners specifically ask people not to simply appear at the house.', 'limited', null, 'https://trundlemanor.com/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Twig''s Beverage Museum', 'twigs-beverage-museum', 'museums', 44.77471, -88.60924, 'Shawano', 'WI', 'Twig''s preserves the history of Sun Drop and the local bottling business through vintage bottles, machinery, advertising and soda memorabilia. Visitors can watch bottling activity and sample soda, making it a working-industry museum rather than a static display.', 'open', null, 'https://twigsbeverage.net/', '2026-09-09T13:02:00.307533+00:00', null, 'https://twigsbeverage.net/', null, null, null, 'America/Chicago'),
  ('Two-Headed Calf — Behringer-Crawford Museum', 'two-headed-calf-behringer-crawford-museum', 'museums', 39.0812, -84.53872, 'Covington', 'KY', 'Among the eclectic regional-history displays inside the Behringer-Crawford Museum is a preserved two-headed calf, one of the museum''s signature curiosities. The museum also contains fossils, historic vehicles and an elaborate model railroad inside a former mansion in Devou Park.', 'open', null, 'https://www.bcmuseum.org/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.bcmuseum.org/', null, null, null, 'America/New_York'),
  ('Umbrella Cover Museum', 'umbrella-cover-museum', 'museums', 43.6561, -70.198, 'Peaks Island, Portland', 'ME', 'This tiny museum is devoted entirely to umbrella sleeves and covers collected from around the world. Reaching it requires a ferry ride to Peaks Island, and its operating schedule is seasonal.', 'limited', null, 'https://www.umbrellacovermuseum.org/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Unclaimed Baggage Museum', 'unclaimed-baggage-museum', 'museums', 34.67318, -86.04459, 'Scottsboro', 'AL', 'Inside the famous retailer that sells items from lost airline luggage is a museum of particularly bizarre, valuable or memorable objects recovered from suitcases over the years. The exhibit turns the mystery of lost baggage into a compact cabinet of curiosities.', 'open', null, 'https://www.unclaimedbaggage.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('U.S. Ski and Snowboard Hall of Fame', 'us-ski-snowboard-hall-of-fame', 'museums', 46.48823, -87.66626, 'Ishpeming', 'MI', 'Ishpeming played a major role in organized American skiing, and this hall of fame preserves equipment, photographs, trophies and stories connected with the sport''s development. Hundreds of inductees are represented inside a museum that also traces the strange evolution from early wooden skis to modern competition equipment.', 'limited', null, 'https://www.skihall.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.skihall.com/', null, null, null, 'America/Detroit'),
  ('USS Cairo Museum and Gunboat', 'uss-cairo-museum-and-gunboat', 'museums', 32.3758, -90.86649, 'Vicksburg', 'MS', 'The recovered remains of USS Cairo, an ironclad gunboat sunk by electrically detonated mines in 1862 and later raised from the Yazoo River. The preserved vessel and artifacts form one of Mississippi''s strangest large-scale archaeological museum displays.', 'open', null, 'https://www.nps.gov/vick/learn/historyculture/uss-cairo-gunboat.htm', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('USS Edson — Saginaw Valley Naval Ship Museum', 'uss-edson-saginaw-valley-naval-ship-museum', 'museums', 43.61389, -83.86889, 'Bay City', 'MI', 'The retired destroyer USS Edson now serves as a floating naval museum on the Saginaw River. Visitors can tour the ship''s decks, weapons systems, living quarters and machinery spaces, and the museum also schedules special overnight and paranormal-themed programs.', 'limited', null, 'https://svnsm.com/', '2026-09-08T15:31:15.588137+00:00', null, 'https://svnsm.com/', null, null, null, 'America/Detroit'),
  ('USS LST-325', 'uss-lst-325', 'museums', 37.9525, -87.5768, 'Evansville', 'IN', 'USS LST-325 is a surviving World War II landing ship of the type used to carry tanks, vehicles and troops directly onto beaches. The restored vessel is now permanently based on the Ohio River in Evansville and offers guided tours through a working piece of wartime naval engineering.', 'limited', null, 'https://lstmemorial.org/', '2026-09-08T13:34:34.826362+00:00', null, 'https://lstmemorial.org/', null, null, null, 'America/Chicago'),
  ('USS Salem', 'uss-salem', 'museums', 42.24232, -70.97113, 'Quincy', 'MA', 'The massive Cold War-era heavy cruiser USS Salem is preserved as a museum ship at the former Quincy shipyard. Visitors can move through cramped compartments, machinery spaces and gun areas inside a vessel large enough to feel like a floating industrial complex.', 'limited', null, 'https://www.uss-salem.org/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.uss-salem.org/', null, null, null, 'America/New_York'),
  ('USS Silversides Submarine Museum', 'uss-silversides-submarine-museum', 'museums', 43.22958, -86.33264, 'Muskegon', 'MI', 'USS Silversides is a highly decorated World War II submarine preserved as a museum ship beside Lake Michigan. As of September 2026 the submarine itself is temporarily away for scheduled dry-dock work through roughly mid-October, while the shore museum remains open, so OddWay should flag the current limited access.', 'limited', null, 'https://silversidesmuseum.org/', '2026-09-08T14:53:55.160019+00:00', null, 'https://silversidesmuseum.org/', null, null, null, 'America/Detroit'),
  ('V & E Simonetti Historic Tuba Collection', 'v-e-simonetti-historic-tuba-collection', 'museums', 35.98896, -78.92469, 'Durham', 'NC', 'Hundreds of tubas, sousaphones, euphoniums, helicons, and related brass instruments fill this specialized collection. The museum traces the evolution of low-brass instruments through examples that range from elegant antiques to huge and strangely shaped horns.', 'limited', null, 'https://simonettitubacollection.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Valiant Air Command Warbird Museum', 'valiant-air-command-warbird-museum', 'museums', 28.5135, -80.79919, 'Titusville', 'FL', 'Large collection of restored military aircraft beside the Space Coast.', 'limited', null, 'https://www.valiantaircommand.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vent Haven Museum', 'vent-haven-museum', 'museums', 39.05298, -84.55198, 'Fort Mitchell', 'KY', 'Vent Haven is the world''s only museum devoted entirely to ventriloquism, with nearly a thousand figures and puppets plus photographs, posters and recordings. Rows of staring dummies make it visually perfect for OddWay, but all visits require an advance guided-tour reservation during the museum''s May-through-September season.', 'limited', null, 'https://www.venthaven.org/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.venthaven.org/', null, null, null, 'America/New_York'),
  ('Vermilionville Historic Village', 'vermilionville-historic-village', 'museums', 30.21457, -91.9971, 'Lafayette', 'LA', 'Vermilionville recreates and preserves Acadian, Creole and Native cultural landscapes using historic buildings, crafts and music. Demonstrations and performances make it more immersive than a static museum.', 'open', null, 'https://bayouvermiliondistrict.org/vermilionville/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Vermont Granite Museum', 'vermont-granite-museum', 'museums', 44.2117, -72.52115, 'Barre', 'VT', 'Housed in a former granite manufacturing shed, this museum explains how Barre stone was quarried, carved and shipped around the country. Tools, machinery and stoneworking displays make it a useful companion stop to the city''s unusual granite monuments and cemeteries.', 'limited', null, 'https://www.vtgranitemuseum.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vermont Ski and Snowboard Museum', 'vermont-ski-and-snowboard-museum', 'museums', 44.47528, -72.70222, 'Stowe', 'VT', 'Historic skis, snowboards, clothing, photographs and Hall of Fame material trace Vermont''s unusually important role in American snow sports. The museum documents both technological changes and the personalities who turned skiing into a defining part of the state''s identity.', 'limited', null, 'https://www.vtssm.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vintage Radio and Communications Museum', 'vintage-radio-and-communications-museum', 'museums', 41.86314, -72.64052, 'Windsor', 'CT', 'A hands-on collection follows communications technology from telegraphy and crystal radios through broadcasting, television and early computers. Many displays still function, allowing visitors to operate equipment rather than simply look at it behind glass.', 'limited', null, 'https://www.atlasobscura.com/places/vintage-radio-and-communications-museum-of-connecticut', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.vrcmct.org/', null, null, null, 'America/New_York'),
  ('Vintage Wings & Wheels Museum', 'vintage-wings-wheels-museum', 'museums', 42.3255, -88.83953, 'Poplar Grove', 'IL', 'A small airfield museum pairs vintage aircraft with antique cars, motorcycles, engines, uniforms, and regional aviation history.', 'limited', null, 'https://www.wingsandwheelsmuseum.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Volo Museum', 'volo-museum', 'museums', 42.32687, -88.17145, 'Volo', 'IL', 'A sprawling collection of famous movie cars, bizarre customs, vintage machines, animatronics, military pieces, and oversized roadside-style displays.', 'limited', null, 'https://www.volofun.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wagner Free Institute of Science', 'wagner-free-institute-of-science', 'museums', 39.9806, -75.1629, 'Philadelphia', 'PA', 'The Wagner Free Institute preserves a nineteenth-century natural-history museum that has changed remarkably little since its displays were arranged in the 1800s. Thousands of fossils, shells, minerals, skeletons and taxidermy specimens remain in wooden cases under the original gallery structure.', 'open', null, 'https://www.wagnerfreeinstitute.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Walter Anderson Museum of Art', 'walter-anderson-museum-of-art', 'museums', 30.4105, -88.8275, 'Ocean Springs', 'MS', 'A museum devoted to Walter Inglis Anderson''s highly distinctive paintings, block prints, carvings and coastal imagery. Anderson''s intense relationship with Horn Island and the natural world gives the collection an unusually personal, almost mythic sense of place.', 'open', null, 'https://www.walterandersonmuseum.org/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wedell-Williams Aviation & Cypress Sawmill Museum', 'wedell-williams-aviation-cypress-sawmill-museum', 'museums', 29.67738, -91.29232, 'Patterson', 'LA', 'One half of this state museum covers early Louisiana aviation and speed-record pilots, while the other preserves the machinery and labor history of cypress logging. The unlikely pairing makes it one of the state''s more eccentric museum combinations.', 'open', null, 'https://louisianastatemuseum.org/museum/wedell-williams-aviation-and-cypress-sawmill-museum', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('West Virginia Bigfoot Museum', 'west-virginia-bigfoot-museum', 'museums', 38.6643, -80.70776, 'Sutton', 'WV', 'Opened in 2021, this downtown Sutton museum is dedicated entirely to Bigfoot research and Appalachian sightings. Inside are footprint casts, hair samples, reports, photographs and other Sasquatch material, including what West Virginia tourism describes as the largest collection of its kind in the Mid-Atlantic.', 'open', null, 'https://wvbigfootmuseum.org/virtual-tour', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('West Virginia Mine Wars Museum', 'west-virginia-mine-wars-museum', 'museums', 37.62277, -82.16538, 'Matewan', 'WV', 'Founded in 2015, this museum preserves the story of the violent early-20th-century struggles between coal miners, mine guards and coal companies, including Matewan and Blair Mountain. Its current Matewan location contains artifacts, weapons, photographs, firsthand accounts and other material from the Mine Wars.', 'open', null, 'https://wvminewars.org/visit-the-museum', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('West Virginia State Farm Museum', 'west-virginia-state-farm-museum', 'museums', 38.92043, -82.08964, 'Point Pleasant', 'WV', 'This sprawling museum recreates a historic West Virginia farming community with relocated buildings, farm machinery and unusual collections spread over dozens of acres. One of its stranger highlights is “General,” an enormous taxidermied horse once reported to weigh 2,850 pounds; the museum operates seasonally from spring into fall.', 'limited', null, 'https://www.wvfarmmuseum.org/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wetlands Acadian Cultural Center', 'wetlands-acadian-cultural-center', 'museums', 29.79619, -90.82495, 'Thibodaux', 'LA', 'This National Park Service center interprets Cajun culture, bayou life and the wetlands of the Mississippi Delta. Ranger programs and boat activities can be seasonal or scheduled, so confirm the day''s offerings.', 'limited', null, 'https://www.nps.gov/jela/planyourvisit/wetlands-acadian-cultural-center.htm', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('WheatonArts — Museum of American Glass', 'wheatonarts-museum-of-american-glass', 'museums', 39.4106, -75.02057, 'Millville', 'NJ', 'The Museum of American Glass preserves thousands of examples of American glassmaking inside a larger arts complex rooted in southern New Jersey''s glass industry. Furnaces and artist demonstrations help connect unusual historic objects with the techniques used to create them.', 'limited', null, 'https://www.wheatonarts.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wheels Through Time Museum', 'wheels-through-time-museum', 'museums', 35.51372, -83.07695, 'Maggie Valley', 'NC', 'Hundreds of rare American motorcycles, automobiles, and machines fill this museum, with an emphasis on vehicles that still run rather than static restorations. The collection includes extremely early motorcycles, racing machines, military bikes, and unusual mechanical survivors.', 'limited', null, 'https://wheelsthroughtime.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Who North America', 'who-north-america', 'museums', 39.63295, -86.34522, 'Camby', 'IN', 'Who North America began as a Doctor Who merchandise business in 1998 and later opened a dedicated physical location in Camby. Along with the store, visitors can see a museum of Doctor Who merchandise and memorabilia spanning the program''s history, making it one of the country''s most unusually specific pop-culture museums.', 'limited', null, 'https://www.visitindy.com/directory/who-north-america/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.whona.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Whydah Pirate Museum', 'whydah-pirate-museum', 'museums', 41.65004, -70.22501, 'West Yarmouth', 'MA', 'The museum displays treasure and artifacts recovered from the Whydah Gally, the pirate ship commanded by Samuel Bellamy that wrecked off Cape Cod in 1717. Its discovery produced the first authenticated pirate-ship wreck ever identified, giving the collection a much stronger historical basis than typical pirate attractions.', 'limited', null, 'https://www.discoverpirates.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.discoverpirates.com/', null, null, null, 'America/New_York'),
  ('Wilhelm Reich Museum at Orgonon', 'wilhelm-reich-museum-at-orgonon', 'museums', 44.98442, -70.71083, 'Rangeley', 'ME', 'This former research estate preserves the life and work of controversial psychoanalyst Wilhelm Reich, including his theories about an energy he called “orgone.” The property is associated with Reich’s unusual experiments, cloudbuster devices, laboratory work, and later conflict with federal authorities.', 'limited', null, 'https://www.atlasobscura.com/places/wilhelm-reich-museum', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('William P. Didusch Center for Urologic History', 'william-p-didusch-center-for-urologic-history', 'museums', 39.20978, -76.67239, 'Linthicum Heights', 'MD', 'Housed at the American Urological Association, this highly specialized museum preserves the history of urology through antique cystoscopes, surgical instruments, microscopes, medical illustrations and other unusual artifacts. Public visits are generally arranged in advance, so contact the museum rather than treating it as a drop-in attraction.', 'limited', null, 'https://urologichistory.museum/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wilmington & Western Railroad', 'wilmington-western-railroad', 'museums', 39.73917, -75.63209, 'Wilmington', 'DE', 'This heritage railroad runs vintage trains through the Red Clay Valley past mills, bridges and a notably tight rock cut where the stone walls crowd close to the cars. The route operates scheduled excursions and seasonal themed trains from its Greenbank station.', 'limited', null, 'https://www.atlasobscura.com/places/wilmington-western-railroad', '2026-09-08T18:31:51.932734+00:00', null, 'https://wwrr.com/', null, null, null, 'America/New_York'),
  ('Wings Over Miami Air Museum', 'wings-over-miami-air-museum', 'museums', 25.64944, -80.43235, 'Miami', 'FL', 'Volunteer aviation museum with vintage aircraft and military aviation history.', 'limited', null, 'https://www.wingsovermiami.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wisconsin Automotive Museum', 'wisconsin-automotive-museum', 'museums', 43.32023, -88.38097, 'Hartford', 'WI', 'The museum specializes in Wisconsin-connected automobiles, especially Kissel cars once built in Hartford. Historic vehicles share the building with engines and transportation displays, preserving a lesser-known chapter of the state''s manufacturing history.', 'open', null, 'https://wisconsinautomuseum.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://wisconsinautomuseum.com/', null, null, null, 'America/Chicago'),
  ('Wisconsin Cranberry Discovery Center', 'wisconsin-cranberry-discovery-center', 'museums', 44.13094, -90.50057, 'Warrens', 'WI', 'Located in one of the state''s major cranberry-growing areas, this museum explains how the fruit is cultivated, harvested and processed. Historic equipment and agricultural displays turn an everyday juice ingredient into a surprisingly specialized Wisconsin story.', 'limited', null, 'https://www.discovercranberries.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.discovercranberries.com/', null, null, null, 'America/Chicago'),
  ('Wisconsin Maritime Museum and USS Cobia', 'wisconsin-maritime-museum-and-uss-cobia', 'museums', 44.09295, -87.65566, 'Manitowoc', 'WI', 'The museum''s centerpiece is USS Cobia, a World War II submarine permanently moored on the Manitowoc River. Visitors can tour the cramped vessel while learning how Manitowoc shipyards built submarines for the war effort.', 'open', null, 'https://www.wisconsinmaritime.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.wisconsinmaritime.org/', null, null, null, 'America/Chicago'),
  ('Witch Board Museum Baltimore', 'witch-board-museum-baltimore', 'museums', 39.33086, -76.62962, 'Baltimore', 'MD', 'This Hampden museum is devoted to the history, mythology and pop-culture legacy of the Ouija board, which has deep roots in Baltimore. Opened as the Baltimore branch of the Salem Witch Board Museum, it sits inside Bazaar and covers figures such as Elijah Bond and Helen Peters alongside the board''s stranger cultural history.', 'open', null, 'https://www.salemwitchboardmuseum.com/copy-of-home-2', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Witch''s Dungeon Classic Movie Museum', 'witchs-dungeon-classic-movie-museum', 'museums', 41.67346, -72.86261, 'Plainville', 'CT', 'One of America''s longest-running classic monster attractions displays life-size horror figures, movie memorabilia and handmade recreations inspired by Universal-era monsters. Created by Cortlandt Hull, whose family had ties to classic horror cinema, the museum operates on a limited schedule.', 'limited', null, 'https://www.atlasobscura.com/places/witchs-dungeon', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.preservehollywood.org/', null, null, null, 'America/New_York'),
  ('Witch''s Hat Depot Museum', 'witchs-hat-depot-museum', 'museums', 42.45479, -83.65352, 'South Lyon', 'MI', 'South Lyon''s former railroad depot earned the nickname "Witch''s Hat" from its steep conical roof. Saved from demolition and moved to McHattie Park in 1976, the unusual building now anchors the local historical museum complex and opens on a limited schedule.', 'limited', null, 'https://www.downtownsouthlyon.com/visit/', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Woodman Museum Oddities', 'woodman-museum-oddities', 'museums', 43.18969, -70.8747, 'Dover', 'NH', 'The Woodman Museum is an old-fashioned local museum packed with the kind of objects that rarely survive modern exhibit design. Its collections have included taxidermy, a four-legged chicken, a man-eating clam shell, military artifacts and other curiosities spread through several historic buildings. Seasonal hours make this a check-ahead stop. Secondary source: https://www.roadsideamerica.com/tip/21104', 'limited', null, 'https://woodmanmuseum.org/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Working Men''s Institute', 'working-mens-institute', 'museums', 38.12867, -87.93636, 'New Harmony', 'IN', 'Founded in 1838 with help from scientist and philanthropist William Maclure, the Working Men''s Institute is Indiana''s oldest continuously operating public library. Its upstairs museum contains natural-history specimens, artifacts and collections that preserve New Harmony''s unusually dense legacy of utopian communities and scientific experimentation.', 'open', null, 'https://www.atlasobscura.com/places/working-mens-institute', '2026-09-08T13:34:34.826362+00:00', null, 'https://workingmensinstitute.org/', null, null, null, 'America/Chicago'),
  ('World AIDS Museum', 'world-aids-museum', 'museums', 26.15558, -80.11563, 'Fort Lauderdale', 'FL', 'Specialized museum documenting the history and human impact of the AIDS epidemic.', 'limited', null, 'https://worldaidsmuseum.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Toy Museum', 'world-s-largest-toy-museum', 'museums', 36.646433, -93.287465, 'Branson', 'MO', 'Started in 2001 when collectors Tom and Wendy Beck moved their collection from Texas to Branson. It now fills more than 26,000 square feet across two buildings — over a million toys in six collections, from the 1800s to modern pop culture. Ticketed, with seasonal hours.', 'limited', null, 'https://worldslargesttoymuseum.com/worlds-largest-toy-museum/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Toilet — kidscommons', 'worlds-largest-toilet-kidscommons', 'museums', 39.19921, -85.92143, 'Columbus', 'IN', 'Inside the kidscommons children''s museum, visitors can climb into a comically oversized toilet that doubles as part of the building''s interactive plumbing-themed exhibit. The attraction is intentionally playful rather than a world-record engineering claim, but its giant scale makes it one of downtown Columbus''s stranger indoor stops.', 'limited', null, 'https://www.roadsideamerica.com/tip/22492', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.kidscommons.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('World''s Oldest Edible Ham', 'worlds-oldest-edible-ham', 'museums', 36.98208, -76.63111, 'Smithfield', 'VA', 'A Smithfield ham cured in 1902 was forgotten in storage until meat magnate Pembroke Gwaltney Jr. turned it into a publicity object and carried it to events. The famously ancient ham is now displayed at the Isle of Wight County Museum alongside the museum''s equally odd World''s Oldest Peanut.', 'open', null, 'https://www.historicisleofwight.com/isle-of-wight-county-museum.html', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wyandot Popcorn Museum', 'wyandot-popcorn-museum', 'museums', 40.58705, -83.12685, 'Marion', 'OH', 'The Wyandot Popcorn Museum fills a large historic building with antique popcorn wagons, peanut roasters and other equipment from the history of America''s popcorn industry. The museum is seasonal and closes for part of the year, so visitors should check current hours before making it a route stop.', 'limited', null, 'https://www.marionhistory.com/explore/wyandot-popcorn-museum/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yamato-kan at Morikami', 'yamato-kan-at-morikami', 'museums', 26.42848, -80.15676, 'Delray Beach', 'FL', 'Original museum building modeled after a traditional Japanese villa.', 'limited', null, 'https://morikami.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yogi Berra Museum & Learning Center', 'yogi-berra-museum-learning-center', 'museums', 40.8684, -74.19456, 'Little Falls', 'NJ', 'This museum at Montclair State University preserves memorabilia from Yankees catcher Yogi Berra, including championship material, photographs and artifacts from his baseball career. Exhibits also examine Berra''s military service and the famous sayings associated with him.', 'limited', null, 'https://yogiberramuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Zaharakos Soda Fountain and Museum', 'zaharakos-soda-fountain-and-museum', 'museums', 39.20018, -85.92143, 'Columbus', 'IN', 'Zaharakos opened in 1900 and preserves an elaborate turn-of-the-century soda-fountain interior filled with marble, stained glass and mechanical music machines. The business functions as both an operating restaurant and a small museum, allowing visitors to eat among restored pieces of early American soda-fountain culture.', 'open', null, 'https://www.zaharakos.com/', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.zaharakos.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Zippo/Case Museum & Flagship Store', 'zippo-case-museum-flagship-store', 'museums', 41.94339, -78.65071, 'Bradford Township', 'PA', 'The current Zippo/Case museum opened in 1997 after an earlier museum proved too small for the growing collection. Visitors now find the first Zippo lighter, rare Case knives, military and advertising exhibits, the working Zippo Repair Clinic and an enormous Zippo-and-knife display outside; admission is free.', 'open', null, 'https://zippo.com/pages/zippo-case-museum-flagship-store', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Zwaanendael Museum Merman', 'zwaanendael-museum-merman', 'museums', 38.77407, -75.13919, 'Lewes', 'DE', 'Inside Delaware''s Dutch-style Zwaanendael Museum is a classic Fiji-style merman — a grotesque composite curiosity made from animal parts — displayed alongside maritime and shipwreck history. It is one of the state''s strongest museum oddities.', 'open', null, 'https://www.atlasobscura.com/places/zwaanendael-museum', '2026-09-08T18:31:51.932734+00:00', null, 'https://history.delaware.gov/zwaanendael-museum/', null, null, null, 'America/New_York'),
  ('10-Foot-High Robot Head', '10-foot-high-robot-head', 'roadside-oddities', 34.00043, -81.0163, 'Columbia', 'SC', 'A huge metal robot head rises beside Harden Street in Five Points, staring out over passing cars without a body attached. The deliberately oversized face looks like the remains of a buried machine or a prop from a forgotten science-fiction movie.', 'roadside', null, 'https://www.roadsideamerica.com/tip/85881', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('12-Foot-Tall Pear', '12-foot-tall-pear', 'roadside-oddities', 42.31998, -71.06216, 'Boston', 'MA', 'An enormous bright-yellow pear stands outside a Dorchester property on Columbia Road. The oversized fruit is a classic giant-object roadside attraction: simple, unexplained at a glance, and almost impossible to miss once you know where to look.', 'roadside', null, 'https://www.roadsideamerica.com/location/ma', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('18-Foot Fish Made of Dining Utensils', '18-foot-fish-made-of-dining-utensils', 'roadside-oddities', 41.35497, -71.96805, 'Mystic', 'CT', 'Hundreds of forks, knives and spoons were welded into an 18-foot upright striped bass outside S&P Oyster Restaurant. The fish was created in 2022 using utensils supplied by the restaurant itself.', 'open', null, 'https://www.roadsideamerica.com/tip/81872', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.sp-oyster.com/', null, null, null, 'America/New_York'),
  ('1938 Police Station Archway', '1938-police-station-archway', 'roadside-oddities', 33.56005, -81.7209, 'Aiken', 'SC', 'A decorative archway in downtown Aiken survives from a tiny police station built as a New Deal-era project in 1938. The station itself is gone, but the entrance structure remains tucked into the pedestrian lanes around The Alley like a doorway to a vanished building.', 'open', null, 'https://www.roadsideamerica.com/tip/66815', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('1964 World''s Fair General Foods Arch', '1964-worlds-fair-general-foods-arch', 'roadside-oddities', 41.68775, -71.3683, 'Warwick', 'RI', 'A 60-foot parabolic arch from the 1964–65 New York World''s Fair now stands inside Rocky Point State Park. It was one of 11 General Foods "Archways to Understanding" that originally carried electronic information displays for fairgoers. After relocation to Rocky Point it became a familiar meeting landmark and survived the amusement park itself.', 'open', null, 'https://www.roadsideamerica.com/tip/56662', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('20-Foot California Raisin', '20-foot-california-raisin', 'roadside-oddities', 39.36549, -74.59592, 'Egg Harbor Township', 'NJ', 'A giant purple California Raisin figure towers outside a roadside property on Zion Road, preserving one of the strangest physical remnants of the once-ubiquitous advertising characters. The oversized fiberglass figure is best viewed from the public roadside.', 'roadside', null, 'https://www.roadsideamerica.com/tip/22811', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('20-Foot Poseidon Tree Sculpture', '20-foot-poseidon-tree-sculpture', 'roadside-oddities', 44.46542, -68.91053, 'Searsport', 'ME', 'A dead roadside tree outside the Yardarm Motel was transformed in 2025 into an approximately 20-foot carving of Poseidon by artist Josh Landry. The sea god rises from the trunk holding a trident, creating a particularly fitting giant figure along Maine’s coast.', 'roadside', null, 'https://www.roadsideamerica.com/tip/89762', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('25-Foot Hanuman Statue', '25-foot-hanuman-statue', 'roadside-oddities', 39.79063, -75.68812, 'Hockessin', 'DE', 'A monumental statue of the Hindu deity Hanuman rises over the grounds of the Hindu Temple of Delaware. The roughly 25-foot figure is an unexpected landmark in northern Delaware and is visible as part of the active temple complex.', 'open', null, 'https://www.roadsideamerica.com/story/74093', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.hindutemplede.com/', null, null, null, 'America/New_York'),
  ('27-Foot Blue Deity — Omkaar Temple', '27-foot-blue-deity-omkaar-temple', 'roadside-oddities', 41.123, -85.3435, 'Fort Wayne', 'IN', 'A 27-foot seated blue Hindu deity statue rises from the rural grounds of Omkaar Temple west of Fort Wayne, creating an unexpectedly monumental sight among surrounding farm fields. The scale and setting—not the religion itself—make this an OddWay stop; visitors should respect the temple as an active place of worship and follow posted access rules.', 'limited', null, 'https://www.roadsideamerica.com/story/74029', '2026-09-08T13:53:25.695107+00:00', null, 'https://www.omkaartemple.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('30-Foot Gold Statue of David', '30-foot-gold-statue-of-david', 'roadside-oddities', 38.25657, -85.76144, 'Louisville', 'KY', 'A towering gold-painted reproduction inspired by Michelangelo''s David stands outside the 21c Museum Hotel on Main Street. The roughly 30-foot sculpture is intentionally oversized and impossible to miss among Louisville''s downtown buildings.', 'open', null, 'https://www.roadsideamerica.com/tip/33453', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Kentucky/Louisville'),
  ('34-Foot Stainless Steel Mary', '34-foot-stainless-steel-mary', 'roadside-oddities', 39.69845, -75.5552, 'New Castle', 'DE', 'A towering stainless-steel statue of Mary rises beside Holy Spirit Catholic Church near the Delaware Memorial Bridge. At roughly 34 feet tall, the polished figure is one of the state''s most conspicuous religious roadside landmarks.', 'open', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('45°N 90°W Geographic Marker', '45-n-90-w-geographic-marker', 'roadside-oddities', 45, -90, 'Poniatowski', 'WI', 'Near Poniatowski, the 45th parallel north meets the 90th meridian west—halfway between the Equator and North Pole and one-quarter of the way around the globe from Greenwich. A marker and small park turn an otherwise invisible grid intersection into a physical destination.', 'open', null, 'https://www.marathoncounty.gov/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.marathoncounty.gov/', null, null, null, 'America/Chicago'),
  ('8th Avenue Reservoir', '8th-avenue-reservoir', 'roadside-oddities', 36.13943, -86.78075, 'Nashville', 'TN', 'A large historic water reservoir sits unexpectedly close to central Nashville, enclosed by infrastructure and fencing rather than designed as a tourist attraction. View only from lawful public areas and do not cross gates or barriers.', 'roadside', null, 'https://www.atlasobscura.com/places/nashville-8th-ave-reservoir', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('A. Everett Austin Facade House', 'a-everett-austin-facade-house', 'roadside-oddities', 41.78093, -72.70919, 'Hartford', 'CT', 'Museum director A. Everett ''Chick'' Austin designed this 1930s home to resemble a grand European villa, but much of the impressive facade conceals a house only one room deep. The theatrical architecture fits its famously eccentric former owner; interior access is by scheduled museum programming.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/hartford-connecticut', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.thewadsworth.org/', null, null, null, 'America/New_York'),
  ('A Healing Palindrome', 'a-healing-palindrome', 'roadside-oddities', 38.13186, -87.93856, 'New Harmony', 'IN', 'Behind New Harmony''s Atheneum stands a marker for the Kcymaerxthaere project, a worldwide network of plaques and installations describing an invented parallel geography. This piece, titled "A Healing Palindrome," deliberately blurs public art, fictional history and real-world place.', 'open', null, 'https://kcymaerxthaere.com/historicalsite/a-healing-palindrome/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Abita Mystery House', 'abita-mystery-house', 'roadside-oddities', 30.47741, -90.03627, 'Abita Springs', 'LA', 'A classic roadside attraction packed with homemade inventions, taxidermy, arcade machines, folk art and deliberately fake creatures. Its best-known exhibits blur museum display and prank in exactly the way OddWay is built for.', 'open', null, 'https://abitamysteryhouse.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('African Village in America — Joe Minter', 'african-village-in-america-joe-minter', 'roadside-oddities', 33.47593, -86.84317, 'Birmingham', 'AL', 'Artist Joe Minter transformed his yard into a sprawling environment of welded scrap, signs and sculptures addressing African American history, religion, violence and memory. Because this remains a privately rooted art environment, current visitor access should be checked and all property rules respected.', 'limited', null, 'https://www.spacesarchives.org/explore/search-the-online-collection/jo-minter-african-village-in-america/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Air Force Armament Museum', 'air-force-armament-museum', 'roadside-oddities', 30.46659, -86.56118, 'Eglin AFB', 'FL', 'Specialized museum devoted to U.S. Air Force weapons, aircraft, missiles, and armament technology.', 'limited', null, 'https://afarmamentmuseum.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Al Johnson''s Goats on the Roof', 'al-johnsons-goats-on-the-roof', 'roadside-oddities', 45.18987, -87.11996, 'Sister Bay', 'WI', 'Al Johnson''s Swedish Restaurant became a Door County icon after goats began grazing on its sod-covered roof. The living rooftop spectacle, Scandinavian architecture and adjacent Goat Cam turn an operating restaurant into one of Wisconsin''s most recognizable roadside attractions.', 'open', null, 'https://aljohnsons.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://aljohnsons.com/', null, null, null, 'America/Chicago'),
  ('Al. Ringling Theatre', 'al-ringling-theatre', 'roadside-oddities', 43.47111, -89.74361, 'Baraboo', 'WI', 'Al Ringling built this ornate 1915 theater as a lavish gift to Baraboo. Its French-inspired interior, chandeliers, boxes and decorative plasterwork make the venue an unexpectedly grand movie palace in a small Wisconsin city.', 'limited', null, 'https://alringling.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://alringling.org/', null, null, null, 'America/Chicago'),
  ('Alabama Museum of Natural History — Hodges Meteorite', 'alabama-museum-of-natural-history-hodges-meteorite', 'roadside-oddities', 33.21189, -87.54398, 'Tuscaloosa', 'AL', 'The museum’s collections include the famous Sylacauga/Hodges meteorite connected to the 1954 incident in which Ann Hodges was struck by a meteorite fragment inside her home. The object anchors a broader museum of geology, fossils and Alabama natural history.', 'open', null, 'https://almnh.museums.ua.edu/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Albany Shoe Tree', 'albany-shoe-tree', 'roadside-oddities', 40.29242, -85.25238, 'Albany', 'IN', 'A roadside tree on Edgewater Road became covered with shoes tossed and tied into its branches, turning an otherwise ordinary rural tree into a local landmark. The display has changed over the years as shoes disappear and new ones are added, so it is best treated as an evolving roadside oddity rather than a formal attraction.', 'roadside', null, 'https://www.atlasobscura.com/places/albany-shoe-tree', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Alexander Art Trail', 'alexander-art-trail', 'roadside-oddities', 45.056, -67.4956, 'Alexander', 'ME', 'More than two dozen large hand-carved wooden sculptures line a trail through the woods in rural Washington County. The privately created but visitor-friendly outdoor collection includes human figures, animals, and imaginative forms carved primarily from local trees.', 'open', null, 'https://www.atlasobscura.com/places/alexander-art-trail', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Alligator Adventure', 'alligator-adventure', 'roadside-oddities', 33.79974, -78.73738, 'North Myrtle Beach', 'SC', 'This reptile park at Barefoot Landing holds an enormous collection of alligators, crocodiles, snakes, lizards, and other unusual animals. Its residents have included exceptionally large crocodilians, making it a far stranger stop than a conventional small coastal zoo.', 'limited', null, 'https://alligatoradventure.com/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Alluvial Decoder at Crabtree Creek', 'alluvial-decoder-at-crabtree-creek', 'roadside-oddities', 35.83698, -78.67369, 'Raleigh', 'NC', 'A series of colorful poles along the greenway marks the heights reached by historic floods in Raleigh. A decoder beneath the bridge identifies the storms represented, turning destructive flood levels into a strange walk-through data visualization.', 'open', null, 'https://www.atlasobscura.com/places/alluvial-decoder-crabtree-creek', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ambler''s Texaco Gas Station', 'amblers-texaco-gas-station', 'roadside-oddities', 41.09392, -88.43956, 'Dwight', 'IL', 'A beautifully restored 1930s gas station and visitor center preserves the look of early Route 66 automobile travel.', 'limited', null, 'https://www.nps.gov/places/ambler-s-texaco-gas-station.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Amelia Bedelia Statue', 'amelia-bedelia-statue', 'roadside-oddities', 33.69963, -80.21083, 'Manning', 'SC', 'A bronze statue honors the famously literal-minded children’s-book character Amelia Bedelia and her creator, Peggy Parish, who was born in Manning. The sculpture turns misunderstandings like “dust the furniture” and “dress the chicken” into a permanent piece of hometown literary history.', 'open', null, 'https://www.scpictureproject.org/clarendon-county/amelia-bedelia-statue.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('America’s First Mile', 'americas-first-mile', 'roadside-oddities', 47.24845, -68.60232, 'Fort Kent', 'ME', 'A monument in Fort Kent marks the northern beginning of U.S. Route 1, the highway that runs from northern Maine to Key West, Florida. It is a clean geographic bookend stop for anyone traveling the far northern reaches of the state.', 'roadside', null, 'https://www.atlasobscura.com/places/americas-first-mile', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Andres Institute of Art Sculpture Park', 'andres-institute-of-art-sculpture-park', 'roadside-oddities', 42.72813, -71.66877, 'Brookline', 'NH', 'More than 100 large-scale sculptures are scattered through roughly 140 acres of wooded hiking trails on Potanipo Hill. The pieces appear unexpectedly among rocks, trees and former ski-area terrain, turning the mountain into an outdoor gallery that feels more like a scavenger hunt than a conventional museum. Trails are open daily from dawn to dusk.', 'open', null, 'https://andresinstitute.org/visit/', '2026-09-09T04:49:39.808526+00:00', null, 'https://andresinstitute.org/', null, null, null, 'America/New_York'),
  ('Andrew Johnson Tailor Shop and National Historic Site', 'andrew-johnson-tailor-shop-and-national-historic-site', 'roadside-oddities', 36.16267, -82.82942, 'Greeneville', 'TN', 'The preserved tailor shop where Andrew Johnson worked before entering politics sits within his National Historic Site. The tiny trade shop offers an unusually intimate physical link to a president whose later impeachment and Reconstruction politics remain deeply contested parts of U.S. history.', 'open', null, 'https://www.nps.gov/anjo/index.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Andrews Geyser', 'andrews-geyser', 'roadside-oddities', 35.65105, -82.24167, 'Old Fort', 'NC', 'Despite its name, this tall plume of water is not a natural geyser. The gravity-fed fountain was created as a railroad-era scenic feature and memorial, producing an unexpectedly dramatic jet of water against the mountain landscape when operating.', 'open', null, 'https://www.roadsideamerica.com/tip/19729', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Androscoggin Swinging Bridge', 'androscoggin-swinging-bridge', 'roadside-oddities', 43.91729, -69.97244, 'Brunswick', 'ME', 'Built in 1892 by John A. Roebling’s Sons, the company associated with the Brooklyn Bridge, this pedestrian suspension bridge crosses the Androscoggin River between Brunswick and Topsham. Locals call it the Swinging Bridge because the narrow span noticeably moves beneath walkers.', 'open', null, 'https://www.androscogginriverwalk.org/riverwalk-photo-tour.html', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Andy Griffith Museum', 'andy-griffith-museum', 'roadside-oddities', 36.49822, -80.60878, 'Mount Airy', 'NC', 'Mount Airy’s museum preserves one of the largest collections of Andy Griffith memorabilia, much of it donated by Griffith’s longtime friend Emmett Forrest. Costumes, props, personal items, and television artifacts connect the real North Carolina town with the fictional Mayberry it helped inspire.', 'limited', null, 'https://www.surryarts.org/agmuseum/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Andy Gump Statue', 'andy-gump-statue', 'roadside-oddities', 42.58949, -88.43413, 'Lake Geneva', 'WI', 'A bronze statue honors cartoon character Andy Gump and his creator Sidney Smith, who had strong ties to the Lake Geneva area. The public monument is a niche pilgrimage point for early newspaper-comic history.', 'open', null, 'https://www.roadsideamerica.com/story/11771', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.visitlakegeneva.com/', null, null, null, 'America/Chicago'),
  ('Angel Oak', 'angel-oak', 'roadside-oddities', 32.72144, -80.08239, 'Johns Island', 'SC', 'This enormous Southern live oak spreads massive limbs across more than 17,000 square feet of shade, with some branches resting on the ground before rising again. Estimates place it at several centuries old, and local folklore has also attached ghost stories to the tree. The City of Charleston operates the surrounding park with set visiting hours.', 'limited', null, 'https://www.atlasobscura.com/places/the-angel-oak-tree-johns-island-south-carolina', '2026-09-09T05:53:13.784429+00:00', null, 'https://www.charleston-sc.gov/153/Angel-Oak', null, null, null, 'America/New_York'),
  ('Annunciation Greek Orthodox Church', 'annunciation-greek-orthodox-church', 'roadside-oddities', 43.0989, -88.02888, 'Wauwatosa', 'WI', 'One of Frank Lloyd Wright''s final designs reinterprets a Byzantine church through a low circular form and broad blue dome. The building remains an active place of worship, so visitors should use scheduled architectural opportunities or respectfully view the exterior.', 'limited', null, 'https://www.annunciationwi.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.annunciationwi.org/', null, null, null, 'America/Chicago'),
  ('Anti-Gravity Monument', 'anti-gravity-monument', 'roadside-oddities', 44.01018, -73.17542, 'Middlebury', 'VT', 'A granite monument on the Middlebury College campus promotes the eccentric dream of defeating or controlling gravity. It was connected with Roger Babson''s Gravity Research Foundation, an organization that funded unconventional gravity research and placed similar monuments at colleges around the country.', 'open', null, 'https://middleburymagazine.com/essays/editors-note/the-gravity-of-it-all/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Apostle Islands Meyers Beach Sea Caves', 'apostle-islands-meyers-beach-sea-caves', 'roadside-oddities', 46.81083, -91.09978, 'Cornucopia', 'WI', 'Lake Superior has carved arches, chambers and cliffside caves into the Apostle Islands sandstone. In warm seasons visitors reach overlooks by trail or the caves by water; in rare safe winters ice can transform the formations completely. Conditions must be checked before attempting access.', 'limited', null, 'https://www.nps.gov/apis/learn/nature/caves.htm', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.nps.gov/apis/', null, null, null, 'America/Chicago'),
  ('Apple Basket Water Tower', 'apple-basket-water-tower', 'roadside-oddities', 38.7538, -78.6436, 'Mount Jackson', 'VA', 'Mount Jackson turned an otherwise ordinary municipal water tower into an enormous basket of apples as a tribute to the Shenandoah Valley''s apple-growing heritage. The painted tower has been a roadside landmark for decades and remains easily visible from Interstate 81 and nearby public roads.', 'roadside', null, 'https://www.roadsideamerica.com/tip/30023', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Apple Valley Hillbilly Garden and Toyland', 'apple-valley-hillbilly-garden-and-toyland', 'roadside-oddities', 37.02731, -88.33261, 'Calvert City', 'KY', 'This former roadside store has evolved into a sprawling collection of pun-heavy junk sculptures, folk art, vintage toys and old gas-station memorabilia. The outdoor Hillbilly Garden and indoor Toyland collection contain thousands of objects arranged with intentionally eccentric humor.', 'open', null, 'https://applevalleyhillbillygardenandtoyland.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://applevalleyhillbillygardenandtoyland.com/', null, null, null, 'America/Chicago'),
  ('Archbald Pothole', 'archbald-pothole', 'roadside-oddities', 41.51175, -75.57408, 'Archbald', 'PA', 'A glacial waterfall drilled this enormous vertical pothole into bedrock thousands of years ago, leaving a cavity roughly large enough to hold dozens of fire trucks'' worth of water. A viewing platform inside Archbald Pothole State Park lets visitors look directly into the formation during park hours.', 'open', null, 'https://www.atlasobscura.com/places/archbald-pothole', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ark Encounter', 'ark-encounter', 'roadside-oddities', 38.6222, -84.59451, 'Williamstown', 'KY', 'The centerpiece of this religious theme park is an enormous timber-frame interpretation of Noah''s Ark measuring more than 500 feet long. The scale of the structure makes it a legitimate roadside architectural oddity, while its exhibits present a young-Earth creationist interpretation rather than mainstream scientific geology and biology.', 'limited', null, 'https://arkencounter.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://arkencounter.com/', null, null, null, 'America/New_York'),
  ('Armour-Stiner Octagon House', 'armour-stiner-octagon-house', 'roadside-oddities', 41.03085, -73.87047, 'Irvington', 'NY', 'This exuberant pink Victorian residence was transformed in the 1870s into an eight-sided domed house inspired by nineteenth-century octagon-house theories. It remains a private residence, and both the house and grounds are accessible only through advance ticketed guided tours.', 'limited', null, 'https://armourstiner.com/visit/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Arnold Schwarzenegger Statue', 'arnold-schwarzenegger-statue', 'roadside-oddities', 39.9721, -83.00225, 'Columbus', 'OH', 'An approximately eight-foot bronze statue of Arnold Schwarzenegger in a bodybuilding pose stands outside the Greater Columbus Convention Center. The sculpture honors Schwarzenegger''s long connection to Columbus and the Arnold Sports Festival and is freely visible from the public plaza.', 'open', null, 'https://www.atlasobscura.com/places/arnold-schwarzenegger-statue', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('ART the Dalmatian', 'art-the-dalmatian', 'roadside-oddities', 32.5106, -93.7502, 'Shreveport', 'LA', 'A roughly twenty-foot spotted dog sculpture by artist William Joyce guards Central ARTSTATION, with its spots recognizing arts supporters. The outdoor work is visible from the public arts district even when the building is closed.', 'open', null, 'https://www.shrevearts.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Arthur Fiedler Memorial', 'arthur-fiedler-memorial', 'roadside-oddities', 42.35651, -71.07545, 'Boston', 'MA', 'The enormous head of Boston Pops conductor Arthur Fiedler is assembled from dozens of stacked aluminum plates. From a distance the face looks solid, while closer views break it into thin shimmering slices, creating an unusually effective optical illusion along the Charles River Esplanade.', 'open', null, 'https://www.atlasobscura.com/places/arthur-fiedler-memorial', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Arthur Kill Vertical Lift Bridge', 'arthur-kill-vertical-lift-bridge', 'roadside-oddities', 40.63757, -74.19565, 'Elizabeth', 'NJ', 'This enormous railroad lift bridge raises its center span hundreds of feet to allow ships through the Arthur Kill between New Jersey and Staten Island. It remains an active piece of rail infrastructure and should only be viewed from legitimate public vantage points rather than approached on the tracks.', 'roadside', null, 'https://www.atlasobscura.com/places/arthur-kill-vertical-lift-bridge', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('ASM International Geodesic Dome', 'asm-international-geodesic-dome', 'roadside-oddities', 41.46009, -81.29941, 'Novelty', 'OH', 'ASM International''s headquarters is covered by a huge open-air geodesic dome built in the late 1950s from an aluminum framework. The office building itself is not a general tourist attraction, but the landscaped Materials Park and exterior dome can be viewed during the property''s posted public-ground hours.', 'open', null, 'https://www.atlasobscura.com/places/asm-international-materials-park', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Atalaya Castle', 'atalaya-castle', 'roadside-oddities', 33.50179, -79.06767, 'Murrells Inlet', 'SC', 'Industrialist Archer Huntington and sculptor Anna Hyatt Huntington built this sprawling Moorish-inspired winter residence in the 1930s. Its stark brick corridors, enclosed courtyards, ironwork, studios, and strange floor plan feel more like an abandoned Mediterranean fortress than a South Carolina beach house.', 'limited', null, 'https://www.atlasobscura.com/places/atalaya', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Atomic Waste Container Art', 'atomic-waste-container-art', 'roadside-oddities', 33.55915, -81.7221, 'Aiken', 'SC', 'Aiken’s long relationship with the nearby Savannah River Site inspired this unusual piece of public art made to resemble a radioactive-waste shipping container. The sculpture turns one of the region’s most consequential industries into an unexpectedly playful downtown object.', 'open', null, 'https://www.roadsideamerica.com/tip/55488', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Aullwood Giant Trolls', 'aullwood-giant-trolls', 'roadside-oddities', 39.88121, -84.27081, 'Dayton', 'OH', 'Artist Thomas Dambo created three enormous trolls named Bo, Bodil and Bibbi from reclaimed wood for Aullwood Audubon, turning the preserve into a giant-creature scavenger hunt. The trolls remain on the nature trails even though the original giant nest was removed in 2025; admission is required and reaching all of them involves roughly one to two miles of walking.', 'limited', null, 'https://www.audubon.org/aullwood/explore/troll-hatched-egg-exhibit', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ave Maria Grotto', 'ave-maria-grotto', 'roadside-oddities', 34.17535, -86.81646, 'Cullman', 'AL', 'Brother Joseph Zoettl spent decades building a miniature world of shrines, churches, temples and imaginary structures from stone, concrete, shells and discarded materials. More than a hundred miniature buildings fill the landscaped hillside at St. Bernard Abbey.', 'open', null, 'https://www.avemariagrotto.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Babson Globe', 'babson-globe', 'roadside-oddities', 42.29773, -71.26411, 'Wellesley', 'MA', 'A 28-foot rotating globe weighing roughly 25 tons dominates the Babson College campus. Built at the direction of eccentric businessman Roger Babson, the enormous sphere was designed as an educational model of the world and remains one of the largest rotating globes ever constructed.', 'open', null, 'https://www.atlasobscura.com/places/babson-globe', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Backyard Terrors Dinosaur Park', 'backyard-terrors-dinosaur-park', 'roadside-oddities', 36.43913, -82.23112, 'Bluff City', 'TN', 'A backyard in northeast Tennessee evolved into a homemade dinosaur park filled with large creature sculptures and prehistoric scenes. The hand-built quality makes it feel closer to outsider art than a polished theme park; check current visitor hours before making the detour.', 'limited', null, 'https://www.atlasobscura.com/places/backyard-terrors-dinosaur-park', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bahá''í House of Worship', 'bah-house-of-worship', 'roadside-oddities', 42.07444, -87.68444, 'Wilmette', 'IL', 'One of only a handful of continental Bahá''í temples worldwide, with an elaborate white dome covered in intricate symbols and lace-like ornament.', 'open', null, 'https://www.bahai.us/bahai-temple/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bailey Island Bridge — Cribstone Bridge', 'bailey-island-bridge-cribstone-bridge', 'roadside-oddities', 43.7489, -69.98893, 'Harpswell', 'ME', 'This unusual bridge is built from massive granite blocks stacked in an open crib-like pattern instead of a conventional solid foundation. Gaps between the stones allow tides to flow through while the heavy granite keeps the structure anchored between Bailey and Orr’s islands.', 'open', null, 'https://www.atlasobscura.com/places/bailey-island-bridge-cribstone-bridge', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Balanced Rock', 'balanced-rock', 'roadside-oddities', 43.41118, -89.72427, 'Baraboo', 'WI', 'A large quartzite boulder appears to balance precariously atop a narrower pedestal on the East Bluff above Devil''s Lake. The rock is reached by a steep trail and has been a landmark for generations of park visitors.', 'open', null, 'https://dnr.wisconsin.gov/topic/parks/devilslake', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/topic/parks/devilslake', null, null, null, 'America/Chicago'),
  ('Bald Knob Cross of Peace', 'bald-knob-cross-of-peace', 'roadside-oddities', 37.55195, -89.34638, 'Alto Pass', 'IL', 'A 111-foot white cross crowns a high point above the Shawnee hills, creating a stark landmark visible across much of southern Illinois.', 'open', null, 'https://www.baldknobcross.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bamahenge', 'bamahenge', 'roadside-oddities', 30.33155, -87.5672, 'Elberta', 'AL', 'Artist Mark Cline created a full-size fiberglass Stonehenge replica hidden in the woods near Barber Marina. The stones are arranged to echo the English monument, producing an intentionally surreal roadside destination on the Gulf Coast.', 'open', null, 'https://barbermarina.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bancroft Tower', 'bancroft-tower', 'roadside-oddities', 42.27551, -71.81734, 'Worcester', 'MA', 'A 56-foot miniature feudal castle rises from Salisbury Park as a memorial to historian and U.S. Navy secretary George Bancroft. The stone folly contains small rooms and battlements but was built mainly as an elaborate decorative monument; the grounds are normally open even when the tower interior is locked.', 'open', null, 'https://www.atlasobscura.com/places/bancroft-tower', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Banded Iron Formation Stone', 'banded-iron-formation-stone', 'roadside-oddities', 42.27765, -83.73541, 'Ann Arbor', 'MI', 'A massive specimen of banded iron formation sits outdoors on the University of Michigan campus as a physical remnant of Earth''s ancient oxygenation history. The alternating iron-rich layers formed billions of years ago and create an unusually deep-time roadside geology stop in the middle of campus.', 'open', null, 'https://www.atlasobscura.com/places/banded-iron-formation-stone', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Bangor Viking Muffler Man', 'bangor-viking-muffler-man', 'roadside-oddities', 42.30778, -86.12167, 'Bangor', 'MI', 'A vintage giant fiberglass Viking serves as a mascot at Bangor High School, adapting the classic roadside Muffler Man form into school spirit. Because the figure is on school property near athletic facilities, travelers should view it only from publicly accessible areas and avoid entering restricted grounds.', 'limited', null, 'https://www.roadsideamerica.com/tip/18457', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Barnwell Sundial', 'barnwell-sundial', 'roadside-oddities', 33.24362, -81.36484, 'Barnwell', 'SC', 'A freestanding vertical sundial erected in the 1800s still occupies a traffic circle in downtown Barnwell. Its highly visible location and uncommon design turn an old timekeeping device into the town’s defining roadside monument.', 'open', null, 'https://www.scpictureproject.org/barnwell-county/barnwell-sundial.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Baseball Water Tower', 'baseball-water-tower', 'roadside-oddities', 35.05409, -80.95757, 'Fort Mill', 'SC', 'Fort Mill’s water tower is painted to resemble an enormous baseball, complete with curved red stitching visible across the white tank. It turns ordinary municipal infrastructure into a giant sports object hanging over town.', 'roadside', null, 'https://fotospot.com/attractions/south-carolina/baseball-water-tower', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bass Pro Shops at the Pyramid', 'bass-pro-shops-at-the-pyramid', 'roadside-oddities', 35.15545, -90.05199, 'Memphis', 'TN', 'A gigantic stainless-steel pyramid originally built as an arena now contains a vast outdoor-retail complex, hotel, swamp-like interior and elevated observation deck. The sheer mismatch between ancient-Egypt-inspired architecture and its current use makes it peak OddWay.', 'open', null, 'https://stores.basspro.com/us/tn/memphis/1-bass-pro-dr.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bath–Tsugaru Sister City Torii Gate', 'bath-tsugaru-sister-city-torii-gate', 'roadside-oddities', 43.91147, -69.81239, 'Bath', 'ME', 'An authentic Japanese torii gate stands unexpectedly on Bath’s waterfront as a symbol of the city’s relationship with Tsugaru, Japan. The connection grew from the 1889 rescue of shipwrecked American sailors from a Bath-built vessel off the Japanese coast.', 'open', null, 'https://www.atlasobscura.com/places/bath-tsugaru-sister-city-torii-gate', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Baughman Center', 'baughman-center', 'roadside-oddities', 29.63893, -82.3822, 'Gainesville', 'FL', 'Small lakeside chapel with dramatic gothic-like windows and an unusually secluded atmosphere.', 'limited', null, 'https://performingarts.ufl.edu/venues/baughman-center/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Beach Guy Muffler Man at the Pink Elephant', 'beach-guy-muffler-man-at-the-pink-elephant', 'roadside-oddities', 38.96147, -89.76369, 'Livingston', 'IL', 'A towering fiberglass beach-guy Muffler Man joins the mall''s collection of giant animals and Route 66 photo props.', 'roadside', null, 'https://www.pinkelephantantiquemall.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bealeton''s Giant Roller Skate', 'bealetons-giant-roller-skate', 'roadside-oddities', 38.53652, -77.72916, 'Bealeton', 'VA', 'An enormous fiberglass roller skate has stood outside the former skating-rink property since the roller-disco era of the 1980s. The weathered oversized shoe remains visible from the public-facing commercial area and is best treated as a quick roadside photo stop.', 'roadside', null, 'https://www.fotospot.com/attractions/virginia/bealetons-giant-roller-skate', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bear Grass Giant Fanged Bear', 'bear-grass-giant-fanged-bear', 'roadside-oddities', 35.76812, -77.12726, 'Bear Grass', 'NC', 'A large concrete bear with conspicuous fangs stands at Bear Grass Charter School as an unusually aggressive version of the community mascot. Sculptor Henry C. Cowan created the figure decades ago, and it remains visible from legitimate public approaches; avoid entering school grounds unnecessarily during class hours.', 'roadside', null, 'https://www.roadsideamerica.com/tip/42712', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bear Head Rock', 'bear-head-rock', 'roadside-oddities', 44.90934, -66.98482, 'Eastport', 'ME', 'A cliff and rock profile across the water resembles the head of a bear when viewed from the right angle. This coordinate is a practical public viewing area on the Eastport waterfront rather than a claim that the pin sits directly on the rock formation itself.', 'open', null, 'https://www.roadsideamerica.com/tip/44869', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Beasts of Beaver Meadows', 'beasts-of-beaver-meadows', 'roadside-oddities', 40.93178, -75.92267, 'Beaver Meadows', 'PA', 'Dragons, dinosaurs, owls and other monsters made from concrete, scrap metal and old vehicle parts line Route 93 north of Beaver Meadows. The sculptures were created by Joseph J. Woitko and sit on private land, so they should be viewed from the road without wandering onto the property.', 'private', null, 'https://www.atlasobscura.com/places/beaver-meadows-roadside-scuptures', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bedford Coffee Pot', 'bedford-coffee-pot', 'roadside-oddities', 40.02303, -78.51759, 'Bedford Township', 'PA', 'Bert Koontz built this 18-foot coffee-pot-shaped building in 1927 to lure Lincoln Highway motorists into his adjacent service station and lunch business. Saved from demolition, it was moved to the Bedford County Fairgrounds and restored in 2003–04; the exterior and historical marker are always the attraction, while the interior has no dependable regular public hours.', 'roadside', null, 'https://www.bedboro.com/about-us/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bee City Zoo & Honey Bee Farm', 'bee-city-zoo-honey-bee-farm', 'roadside-oddities', 32.97455, -80.46585, 'Cottageville', 'SC', 'What began around honey-bee education has grown into an interactive rural zoo with lemurs, monkeys, giraffes, kangaroos, reptiles, farm animals, and other species. Feeding opportunities and safari-style rides make it more hands-on than a conventional roadside animal park.', 'limited', null, 'https://www.beecityzoo.com/contact', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Belle Mont Mansion', 'belle-mont-mansion', 'roadside-oddities', 34.66724, -87.66958, 'Tuscumbia', 'AL', 'This early nineteenth-century house is one of Alabama’s most important examples of Jeffersonian or Palladian-influenced architecture. The restored mansion is operated as a historic site with limited public hours and special events.', 'limited', null, 'https://ahc.alabama.gov/properties/bellemont/bellemont.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ben Bikin''', 'ben-bikin', 'roadside-oddities', 43.93902, -90.8095, 'Sparta', 'WI', 'Sparta''s giant cyclist celebrates the town''s long connection to bicycle manufacturing and its identity as the Bicycling Capital of America. The oversized figure stands downtown as an easy public photo stop.', 'open', null, 'https://www.bikesparta.us/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.bikesparta.us/', null, null, null, 'America/Chicago'),
  ('Ben & Jerry''s Flavor Graveyard', 'ben-jerrys-flavor-graveyard', 'roadside-oddities', 44.35292, -72.74019, 'Waterbury', 'VT', 'Behind Ben & Jerry''s Waterbury factory, faux headstones memorialize discontinued ice-cream flavors with names, dates and rhyming epitaphs. The hillside cemetery turns failed and retired products into one of Vermont''s most recognizable corporate oddities.', 'limited', null, 'https://www.atlasobscura.com/places/ben-jerrys-flavor-graveyard', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Benson Ford Shiphouse', 'benson-ford-shiphouse', 'roadside-oddities', 41.65072, -82.83951, 'Put-in-Bay', 'OH', 'The forward section of the 1924 lake freighter Benson Ford was removed from the ship and placed on a South Bass Island bluff in 1986, creating a private residence that looks like a ship sailing through the trees. The house is not normally open to the public except for occasional announced charity tours, so view it only from legal public areas and do not enter the property.', 'private', null, 'https://www.shiponthebay.com/', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Berne Clock Tower', 'berne-clock-tower', 'roadside-oddities', 40.65815, -84.95537, 'Berne', 'IN', 'Berne built its 160-foot clock tower in 2010 as an elaborate tribute to the Zytglogge in Bern, Switzerland and the town''s Swiss heritage. The public Muensterberg Plaza also stages a mechanical glockenspiel presentation several times a day, complete with large moving figures.', 'open', null, 'https://www.berneclocktower.org/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.berneclocktower.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Bert Parks Crowns You Miss America', 'bert-parks-crowns-you-miss-america', 'roadside-oddities', 39.36231, -74.43961, 'Atlantic City', 'NJ', 'A bronze Bert Parks holds a Miss America crown overhead beside the convention-center complex, inviting visitors to stand beneath it for a mock crowning. The interactive sculpture commemorates the longtime pageant host and Atlantic City''s deep Miss America history.', 'open', null, 'https://www.roadsideamerica.com/location/map?mode=detail&id=21611', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bessie the Giant Cow', 'bessie-the-giant-cow', 'roadside-oddities', 32.78155, -79.98988, 'Charleston', 'SC', 'A huge fiberglass cow named Bessie has watched over the St. Andrews shopping area for decades. She once rotated atop a dairy store and held a giant milk bottle; current reports say she remains in place even though the rotating mechanism and bottle are gone.', 'roadside', null, 'https://www.roadsideamerica.com/tip/14236', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Betsy the Giant Lobster', 'betsy-the-giant-lobster', 'roadside-oddities', 24.93049, -80.62895, 'Islamorada', 'FL', 'Massive roadside spiny-lobster sculpture, one of the Keys'' most recognizable oddities.', 'roadside', null, 'https://www.rainbarrelvillage.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bewitched Statue', 'bewitched-statue', 'roadside-oddities', 42.52133, -70.89585, 'Salem', 'MA', 'A bronze Elizabeth Montgomery as Samantha Stephens sits astride a crescent moon in downtown Salem. The statue was installed as a promotional tribute to the television series ''Bewitched,'' which filmed several episodes in Salem, and its cheerful sitcom witch makes a strange contrast with the city''s real 1692 history.', 'open', null, 'https://www.roadsideamerica.com/story/16317', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bicentennial Chair', 'bicentennial-chair', 'roadside-oddities', 42.57603, -71.9839, 'Gardner', 'MA', 'Gardner''s history as ''Chair City'' produced a series of oversized chairs competing for world-record status. The surviving Bicentennial Chair was erected in 1976 and, although no longer the world''s largest, remains a giant monument to the city''s furniture-making past.', 'open', null, 'https://www.atlasobscura.com/places/bicentennial-chair', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Amish Man Statue', 'big-amish-man-statue', 'roadside-oddities', 38.96054, -75.42883, 'Milford', 'DE', 'A roughly 20-foot fiberglass Amish man stands outside Xtreme Graphix after changing homes more than once over the years. The towering bearded figure is a classic Muffler-Man-era roadside sculpture with distinctly Delmarva styling.', 'roadside', null, 'https://www.roadsideamerica.com/tip/1613', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Apple Time Capsule', 'big-apple-time-capsule', 'roadside-oddities', 39.45754, -77.97133, 'Martinsburg', 'WV', 'This oversized fiberglass apple was installed in 1990 as a Community Pride Project honoring Berkeley County''s apple-growing history. The base contains a time capsule intended to remain sealed until 2040, while the apple itself is a permanent public photo stop.', 'open', null, 'https://www.atlasobscura.com/places/big-apple-time-capsule', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Black Bull', 'big-black-bull', 'roadside-oddities', 37.58171, -84.28918, 'Berea', 'KY', 'A large fiberglass black bull has stood outside the used-car property at 200 Richmond Road North for decades. The figure predates the current business and survives as an old-school example of oversized commercial roadside advertising.', 'roadside', null, 'https://www.roadsideamerica.com/tip/57398', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Blue Bug', 'big-blue-bug', 'roadside-oddities', 41.80707, -71.40588, 'Providence', 'RI', 'A gigantic blue termite named Nibbles Woodaway has stared down at Interstate 95 traffic since 1980. The roughly 58-foot-long insect became so recognizable that it evolved from a pest-control advertisement into one of Rhode Island''s best-known roadside icons.', 'roadside', null, 'https://www.atlasobscura.com/places/big-blue-bug', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.bigbluebug.com/', null, null, null, 'America/New_York'),
  ('Big Blue Teapot', 'big-blue-teapot', 'roadside-oddities', 33.52984, -80.57455, 'Elloree', 'SC', 'A building shaped like an enormous blue teapot once housed thousands of teapots collected by Julian and Sybil Boland. The museum closed in 2020, but the giant teapot remains; a June 2026 visitor report confirms it is still standing, although visibly deteriorated.', 'roadside', null, 'https://www.roadsideamerica.com/tip/33987', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Bob — Cowboy Muffler Man', 'big-bob-cowboy-muffler-man', 'roadside-oddities', 41.52194, -72.0918, 'Norwich', 'CT', 'A giant cowboy Muffler Man has been part of Norwich since the 1960s and has watched over the West Main Street shopping area for decades. Big Bob wears a cowboy hat and holds an American flag, preserving a classic piece of fiberglass roadside culture.', 'open', null, 'https://www.roadsideamerica.com/tip/5908', '2026-09-08T18:47:23.721893+00:00', null, 'https://surplusunlimitedoffice.com/', null, null, null, 'America/New_York'),
  ('The Iconic Jamestown Chair', 'big-chair', 'roadside-oddities', 42.095702, -79.244411, 'Jamestown', 'NY', 'Jamestown’s giant chair is the Iconic Jamestown Chair, a public-art tribute to the city’s once-dominant furniture industry. Fancher Chair Co. built the oversized oak club chair from a historic Jamestown Lounge Company design and installed it downtown in July 2019; it remains a public photo spot at West Third and Lafayette streets.', 'roadside', null, 'https://www.jamestownrenaissance.org/installation-of-oversized-chair-honors-jamestowns-history/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Cow of Middlebush', 'big-cow-of-middlebush', 'roadside-oddities', 40.48465, -74.53236, 'Franklin Township', 'NJ', 'A large fiberglass dairy cow stands as a roadside reminder of the farmland that once dominated this part of Somerset County. The oversized bovine has survived development around it and remains a quick public-roadside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/23718', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Crab at Old Mill Crab House', 'big-crab-at-old-mill-crab-house', 'roadside-oddities', 38.45645, -75.58417, 'Delmar', 'DE', 'A giant red crab hangs above the ground outside the Old Mill Crab House, claws dangling over the photo spot below. It sits only about a hundred feet north of the Maryland line and has become a long-running Delmar roadside landmark.', 'roadside', null, 'https://www.roadsideamerica.com/tip/50755', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Easy Chair', 'big-easy-chair', 'roadside-oddities', 43.08693, -70.75096, 'Kittery', 'ME', 'A roughly 12-foot-tall easy chair with a fiberglass shell sits beside Government Street in Kittery. Vandals destroyed the original oversized chair in 2011, but the community rebuilt it the following year, preserving one of southern Maine’s simplest and most photogenic giant-object stops.', 'roadside', null, 'https://fotospot.com/attractions/maine/big-easy-chair', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Golden Propeller — Merchant Marine Memorial', 'big-golden-propeller-merchant-marine-memorial', 'roadside-oddities', 39.9424, -75.13217, 'Camden', 'NJ', 'A huge polished ship propeller forms the centerpiece of Camden''s World War II American Merchant Marine Memorial. The unidentified propeller sits on the waterfront within sight of Battleship New Jersey and honors merchant mariners and Navy Armed Guard sailors who died at sea.', 'open', null, 'https://www.roadsideamerica.com/story/33801', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big High Heel at Craddock Terry', 'big-high-heel-at-craddock-terry', 'roadside-oddities', 37.4115, -79.1375, 'Lynchburg', 'VA', 'The Craddock Terry complex grew from Lynchburg''s shoe-manufacturing industry, which began here in the late nineteenth century and once produced thousands of pairs a day. A giant red high-heel sculpture with a built-in seat now stands outside the converted hotel, turning that industrial history into a deliberately oversized photo stop.', 'open', null, 'https://www.roadsideamerica.com/tip/58033', '2026-09-08T04:17:48.352537+00:00', null, 'https://www.craddockterryhotel.com/', null, null, null, 'America/New_York'),
  ('Big Kids Sculptures', 'big-kids-sculptures', 'roadside-oddities', 35.15343, -90.01102, 'Memphis', 'TN', 'Large childlike figures in public space exaggerate ordinary play into oversized sculpture. Their scale and cartoonish presence make the installation an easy OddWay-style visual stop rather than a traditional monument.', 'open', null, 'https://www.atlasobscura.com/places/big-kids-sculptures', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Big Leaping Bass', 'big-leaping-bass', 'roadside-oddities', 37.719, -77.4532, 'Ashland', 'VA', 'A fiberglass bass roughly 27 feet tall leaps from an equally oversized faux splash at the entrance to the Winding Brook development. The sculpture was installed as a commercial landmark in the early 2010s and remains visible from the surrounding public roads near Interstate 95.', 'roadside', null, 'https://www.roadsideamerica.com/tip/33429', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Man, Little Car', 'big-man-little-car', 'roadside-oddities', 36.97875, -86.42968, 'Bowling Green', 'KY', 'A cartoonish metal strongman outside Walt''s Allstate Transmission holds a real vintage Renault Dauphine high over his head. The car once had neon trim and is now outlined with newer lighting, preserving the strange roadside sign well into the twenty-first century.', 'roadside', null, 'https://www.roadsideamerica.com/tip/86463', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Big Metal Abacus', 'big-metal-abacus', 'roadside-oddities', 38.40588, -85.58139, 'Goshen', 'KY', 'A giant steel-and-chrome abacus stands at the entrance to St. Francis School along US 42. The ancient calculating device has been enlarged to architectural scale, giving an elementary-school entrance the appearance of a piece of oversized mathematical machinery. Address: 10728 US Hwy 42, Goshen, KY', 'roadside', null, 'https://www.roadsideamerica.com/tip/46360', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Mike''s Rock Shop and Mystery House', 'big-mikes-rock-shop-and-mystery-house', 'roadside-oddities', 37.14429, -86.03745, 'Cave City', 'KY', 'Big Mike''s has been a Cave City roadside fixture for decades, combining a rock and fossil shop with a deliberately old-school Mystery House full of tilted rooms and gravity-defying visual tricks. Outside, an enormous mosasaur advertises the attraction while the shop displays "Big Mo," a massive real mosasaur skull.', 'open', null, 'https://www.roadsideamerica.com/story/12182', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.bigmikesrocks.com/', null, null, null, 'America/Chicago'),
  ('Big Muskie Bucket', 'big-muskie-bucket', 'roadside-oddities', 39.69927, -81.73128, 'Bristol Township', 'OH', 'Big Muskie was once the world''s largest dragline excavator, working Ohio coal country from 1969 until 1991 before the machine was dismantled. Its enormous surviving bucket now sits at Miner''s Memorial Park, where visitors can walk directly up to it, climb inside and see the mining memorials and overlook.', 'open', null, 'https://www.visitmorgancountyohio.com/Explore/Destinations/Miner-s-Memorial-Park-Big-Muskie-Bucket-68/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Musky and National Fresh Water Fishing Hall of Fame', 'big-musky-and-national-fresh-water-fishing-hall-of-fame', 'roadside-oddities', 46.00773, -91.47934, 'Hayward', 'WI', 'The museum''s landmark is an enormous fiberglass muskellunge large enough for visitors to walk inside and climb to an observation platform in its mouth. The surrounding Fishing Hall of Fame adds displays of record catches, boats, tackle and freshwater-angling history.', 'open', null, 'https://www.freshwater-fishing.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.freshwater-fishing.org/', null, null, null, 'America/Chicago'),
  ('Big Red — Bronze Monster Mascot', 'big-red-bronze-monster-mascot', 'roadside-oddities', 36.98714, -86.45561, 'Bowling Green', 'KY', 'Western Kentucky University''s famously undefined red mascot became permanent public art in 2014 when alumnus Russ Faxon sculpted Big Red in bronze. The statue stands near the Alumni Center and captures the creature in its familiar wide-mouthed, sideline-cheering pose.', 'open', null, 'https://www.roadsideamerica.com/tip/42367', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Big Rusty', 'big-rusty', 'roadside-oddities', 39.97618, -74.82632, 'Hainesport Township', 'NJ', 'Danish artist Thomas Dambo built this roughly 20-foot troll from recycled materials collected around a former industrial property. Big Rusty crouches beside the remains of an old structure and has become the anchor for Burlington County''s expanded public Troll Trek.', 'open', null, 'https://www.burlingtoncountynj.gov/2076/Troll-Trek', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Shoals State Park', 'big-shoals-state-park', 'roadside-oddities', 30.35209, -82.69206, 'White Springs', 'FL', 'Florida''s largest whitewater rapids at high water.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/big-shoals-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Talbot Island Boneyard Beach', 'big-talbot-island-boneyard-beach', 'roadside-oddities', 30.48172, -81.44422, 'Jacksonville', 'FL', 'Eroding shoreline scattered with giant sun-bleached skeletons of fallen trees.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/big-talbot-island-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Turkey Statues', 'big-turkey-statues', 'roadside-oddities', 33.7895, -81.92985, 'Edgefield', 'SC', 'Edgefield celebrates its connection to the National Wild Turkey Federation with oversized fiberglass turkeys scattered around town. Several were decorated as public art, turning the community into an informal turkey-statue scavenger hunt.', 'open', null, 'https://www.roadsideamerica.com/tip/29075', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Big Walker Lookout', 'big-walker-lookout', 'roadside-oddities', 37.04567, -81.22843, 'Wytheville', 'VA', 'This privately operated mountain stop combines a country store with a 100-foot observation tower perched high on Big Walker Mountain. The attraction has been family-run for more than 75 years and hosts seasonal craftspeople and music; tower and store access follow business hours rather than being a 24-hour overlook.', 'limited', null, 'https://www.scenicbeauty-va.com/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bigger Big Chair by David Ireland', 'bigger-big-chair', 'roadside-oddities', 48.738238, -122.485014, 'Bellingham', 'WA', 'Bellingham artist David Ireland created “Bigger Big Chair” in 2004–06 as a monumental painted-steel version of an ordinary club chair. The 12.5-foot sculpture belongs to Western Washington University’s outdoor art collection and remains publicly viewable on campus.', 'roadside', null, 'https://westerngallery.wwu.edu/david-ireland-bigger-big-chair-2004-06', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Billy Bob''s Wonderland Rock-afire Explosion', 'billy-bobs-wonderland-rock-afire-explosion', 'roadside-oddities', 38.41523, -82.25553, 'Barboursville', 'WV', 'Billy Bob''s Wonderland is a family entertainment center that preserves a working Rock-afire Explosion animatronic band, the characters made famous by ShowBiz Pizza Place in the 1980s. It has become a destination for animatronic enthusiasts because very few complete public shows remain in operation.', 'open', null, 'https://billybobs-wonderland.com/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Billy Graham Library — Talking Cow', 'billy-graham-library-talking-cow', 'roadside-oddities', 35.19048, -80.90931, 'Charlotte', 'NC', 'Among the serious exhibits at the Billy Graham Library is an unexpectedly strange animatronic dairy cow named Bessie that talks about Graham’s childhood on a North Carolina farm. The contrast between the robot cow and the surrounding presidential and religious memorabilia makes this one of Charlotte’s odder museum details. Oddity reference: https://www.roadsideamerica.com/location/nc', 'limited', null, 'https://billygrahamlibrary.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Billy Tripp''s Mindfield', 'billy-tripps-mindfield', 'roadside-oddities', 35.59283, -89.2669, 'Brownsville', 'TN', 'Billy Tripp has spent decades assembling towering steel beams, signs, found objects and personal symbols into an ever-growing outdoor sculpture. The work resembles a private industrial monument gradually consuming its lot and is one of Tennessee''s premier outsider-art landmarks.', 'open', null, 'https://www.atlasobscura.com/places/billy-tripps-mindfield', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Biloxi Lighthouse', 'biloxi-lighthouse', 'roadside-oddities', 30.39442, -88.90122, 'Biloxi', 'MS', 'An 1848 cast-iron lighthouse unusually positioned in the median of U.S. 90 and long used as a symbol of Gulf Coast hurricane survival. Tours operate on a limited schedule and, as of 2026, access to the upper deck is temporarily restricted for repairs.', 'limited', null, 'https://biloxi.ms.us/visitor-info/museums/lighthouse/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Biltmore Estate’s Secret Passages', 'biltmore-estates-secret-passages', 'roadside-oddities', 35.56703, -82.54425, 'Asheville', 'NC', 'The enormous Biltmore mansion hides disguised doors, servant passages, concealed rooms, a library passageway, a trap door, and other architectural tricks. Not every hidden area is included on every tour, so visitors specifically interested in the secret spaces should check current tour offerings.', 'limited', null, 'https://www.atlasobscura.com/places/biltmore-secret-doors-hidden-passages', '2026-09-09T05:34:33.398594+00:00', null, 'https://www.biltmore.com/', null, null, null, 'America/New_York'),
  ('Bishop Baraga Shrine', 'bishop-baraga-shrine', 'roadside-oddities', 46.74941, -88.47446, 'L''Anse', 'MI', 'A towering metal statue of nineteenth-century Catholic missionary Bishop Frederic Baraga stands above the wooded hillside near L''Anse. The roughly 35-foot monument shows Baraga holding a cross and snowshoes, referencing the long winter journeys that earned him the nickname "Snowshoe Priest."', 'open', null, 'https://www.atlasobscura.com/places/bishop-baraga-shrine', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Black Hawk Statue / Eternal Indian', 'black-hawk-statue-eternal-indian', 'roadside-oddities', 42.03416, -89.33321, 'Oregon', 'IL', 'Lorado Taft''s colossal concrete figure towers above the Rock River at Lowden State Park; ongoing preservation work can affect close viewing.', 'limited', null, 'https://dnr.illinois.gov/parks/park.lowden.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Black Veil Shoppe of Drear & Wonder', 'black-veil-shoppe-of-drear-wonder', 'roadside-oddities', 42.52154, -70.91475, 'Salem', 'MA', 'A darkly theatrical Salem shop from twin artists Matt and Ryan Murray combines macabre artwork, apparel, curiosities and an immersive gothic interior. It is a contemporary oddities stop rather than a witch-trial site.', 'open', null, 'https://www.blackveilshoppe.com/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blenko Man', 'blenko-man', 'roadside-oddities', 39.03852, -80.46659, 'Weston', 'WV', 'This strange life-size glass figure was constructed from Blenko glass pieces by sculptor John Zidek and is distinctive enough that even its two right feet have become part of the story. It now stands inside the Museum of American Glass, where visitors can see it along with a much broader collection of American glassware.', 'open', null, 'https://www.atlasobscura.com/places/blenko-man', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blue Ghost Fireflies', 'blue-ghost-fireflies', 'roadside-oddities', 35.19702, -82.59431, 'Hendersonville', 'NC', 'For only a short period each year, rare blue ghost fireflies produce a sustained blue-green glow low over the forest floor rather than the familiar flashing pattern of common fireflies. The phenomenon is most associated with parts of western North Carolina and is best viewed through legitimate scheduled viewing opportunities when available. Tour information: https://www.visitnc.com/list/10-dark-sky-adventures-north-carolina', 'limited', null, 'https://www.atlasobscura.com/places/blue-ghost-fireflies', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blue Spring State Park', 'blue-spring-state-park', 'roadside-oddities', 28.94717, -81.33964, 'Orange City', 'FL', 'Major winter manatee refuge centered on a powerful spring and historic Thursby House.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bluespring Caverns', 'bluespring-caverns', 'roadside-oddities', 38.79618, -86.54603, 'Bedford', 'IN', 'Bluespring Caverns contains one of the longest known cave systems in Indiana and an extensive navigable underground river. Commercial tours take visitors by boat through the dark cave system rather than along a standard walking path.', 'limited', null, 'https://www.atlasobscura.com/places/bluespring-caverns', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.bluespringcaverns.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Bob the Bull', 'bob-the-bull', 'roadside-oddities', 38.54042, -75.22007, 'Dagsboro', 'DE', 'This enormous fiberglass bull spent decades outside an Ocean City steakhouse before being rescued, restored and moved to Parsons Farms in Delaware. Bob still wears his oversized chef hat and sunglasses, preserving one of Delmarva''s classic roadside mascots.', 'open', null, 'https://www.roadsideamerica.com/story/21619', '2026-09-08T18:31:51.932734+00:00', null, 'https://parsonsfarmsproduce.com/', null, null, null, 'America/New_York'),
  ('Bok Tower Gardens', 'bok-tower-gardens', 'roadside-oddities', 27.93594, -81.57533, 'Lake Wales', 'FL', 'Art Deco singing tower and carillon standing atop one of peninsular Florida''s highest points.', 'roadside', null, 'https://boktowergardens.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boll Weevil Monument', 'boll-weevil-monument', 'roadside-oddities', 31.31444, -85.85403, 'Enterprise', 'AL', 'Enterprise erected a monument to the boll weevil after the pest devastated cotton farming and pushed local agriculture toward diversification. A classical female figure holds an oversized insect above her head in one of America’s strangest civic monuments.', 'roadside', null, 'https://www.enterpriseal.gov/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Bondurant''s Giant Mortar and Pestle', 'bondurants-giant-mortar-and-pestle', 'roadside-oddities', 38.04775, -84.54955, 'Lexington', 'KY', 'Joe Bondurant designed his 1970s pharmacy as an enormous mortar and pestle, complete with a tall pestle projecting from the roof. The pharmacy eventually closed, but the bizarre building survived under new commercial uses and remains one of Lexington''s most literal pieces of novelty architecture.', 'roadside', null, 'https://www.atlasobscura.com/places/bondurants-pharmacy', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Book Barn', 'book-barn', 'roadside-oddities', 41.32184, -72.20824, 'Niantic', 'CT', 'Hundreds of thousands of used books are scattered through buildings, sheds and themed corners at this sprawling book compound. Cats, goats, strange decorations and sections with names such as Hades and The Haunted make it feel more like a literary scavenger hunt than a normal bookstore.', 'open', null, 'https://www.atlasobscura.com/places/book-barn', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.bookbarnniantic.com/', null, null, null, 'America/New_York'),
  ('Boothe Memorial Park', 'boothe-memorial-park', 'roadside-oddities', 41.23521, -73.10946, 'Stratford', 'CT', 'The eccentric Boothe brothers filled their property with unusual structures and collections, many of which survive in today''s public park. Highlights include a miniature lighthouse, an old tollbooth, a blacksmith shop with dozens of sides and the wonderfully strange Technocratic Cathedral.', 'open', null, 'https://www.atlasobscura.com/places/boothe-memorial-park', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.stratfordct.gov/content/39832/39846/39914.aspx', null, null, null, 'America/New_York'),
  ('Borderland State Park Mansion', 'borderland-state-park-mansion', 'roadside-oddities', 42.06561, -71.1092, 'Easton', 'MA', 'A stone mansion built for eccentric botanist Oakes Ames and artist Blanche Ames stands amid the unusual landscaped estate that became Borderland State Park. Blanche designed much of the house herself and filled the property with artistic and scientific experimentation.', 'limited', null, 'https://www.atlasobscura.com/places/borderland-state-park', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boston History Dioramas', 'boston-history-dioramas', 'roadside-oddities', 42.35115, -71.07456, 'Boston', 'MA', 'Four elaborate historical dioramas hide inside the lobby of a Back Bay office building. The miniature scenes are easy to walk past from the street, making them a genuinely hidden bit of Boston history rather than a conventional museum exhibit.', 'limited', null, 'https://www.atlasobscura.com/places/boston-history-dioramas', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boston Tea Kettle', 'boston-tea-kettle', 'roadside-oddities', 42.3593, -71.05924, 'Boston', 'MA', 'A giant gilded kettle has hung above downtown Boston since the nineteenth century. It was originally installed as an advertising stunt, complete with a contest to guess how much liquid it could hold, and has survived as a rare piece of oversized Victorian commercial signage.', 'open', null, 'https://www.atlasobscura.com/places/boston-tea-kettle', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boy and the Boot Fountain', 'boy-and-the-boot-fountain', 'roadside-oddities', 46.125, -67.83028, 'Houlton', 'ME', 'A statue of a boy holding a leaking boot has stood in Houlton for more than a century as one of many versions of the once-popular “Boy and the Boot” fountain design. The Houlton figure is traditionally removed or protected during the harshest part of winter, so visibility can be seasonal.', 'limited', null, 'https://www.roadsideamerica.com/story/7825', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Boy Scout Catfish', 'boy-scout-catfish', 'roadside-oddities', 36.11417, -86.80987, 'Nashville', 'TN', 'An oversized catfish sculpture connected with Nashville''s old civic and fairground culture survives as a deliberately strange public-facing landmark. It is a quick photo stop rather than a staffed attraction.', 'roadside', null, 'https://www.atlasobscura.com/places/boy-scout-catfish', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Boy Scout Preserve Caves', 'boy-scout-preserve-caves', 'roadside-oddities', 28.54254, -82.43152, 'Brooksville', 'FL', 'Karst landscape with small caves and sinkholes in Hernando County.', 'open', null, 'https://www.hernandocounty.us/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Brevard White Squirrels', 'brevard-white-squirrels', 'roadside-oddities', 35.23345, -82.73429, 'Brevard', 'NC', 'Brevard is famous for a population of white Eastern gray squirrels that are not true albinos. Local lore traces the population to two pale squirrels connected with a traveling carnival in the late 1940s; the Brevard College campus is one of the better places to look for them.', 'open', null, 'https://www.atlasobscura.com/places/brevard-white-squirrels', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bromo-Seltzer Arts Tower', 'bromo-seltzer-arts-tower', 'roadside-oddities', 39.28768, -76.62065, 'Baltimore', 'MD', 'Built between 1907 and 1911 for the company behind Bromo-Seltzer headache remedy, this clock tower was originally crowned by a giant glowing blue medicine bottle. The bottle is gone, but the tower now contains artist studios and a Bromo-Seltzer museum, with scheduled access to the clock room.', 'limited', null, 'https://www.bromoseltzertower.com/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bronze Fonz', 'bronze-fonz', 'roadside-oddities', 43.04038, -87.91099, 'Milwaukee', 'WI', 'A life-size bronze Arthur ''Fonzie'' Fonzarelli stands beside the Milwaukee River, commemorating the fictional Happy Days character whose show was set in Milwaukee. Visitors can pose beside the permanently frozen thumbs-up.', 'open', null, 'https://www.roadsideamerica.com/story/18990', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.visitmilwaukee.org/', null, null, null, 'America/Chicago'),
  ('Bruce the Shark at Flo''s Clam Shack', 'bruce-the-shark-at-flos-clam-shack', 'roadside-oddities', 41.48991, -71.28474, 'Middletown', 'RI', 'A roughly 25-foot shark hangs above Flo''s Clam Shack, looking like a creature that landed on the building rather than a restaurant decoration. The fiberglass-and-foam shark previously belonged to a Cranston nightclub before being rescued and relocated to Aquidneck Island. It is visible from the restaurant exterior.', 'open', null, 'https://admiralsimsnewport.com/off-the-beaten-path-newport-ri/', '2026-09-09T04:49:27.913704+00:00', null, 'https://flosclamshacks.com/locations/', null, null, null, 'America/New_York'),
  ('Bubble Rock', 'bubble-rock', 'roadside-oddities', 44.33856, -68.27334, 'Mount Desert', 'ME', 'A giant glacial boulder appears to balance precariously near the edge of South Bubble Mountain in Acadia National Park. The rock was carried and deposited by ancient ice, leaving it looking as though a small push could send it over the cliff.', 'limited', null, 'https://www.atlasobscura.com/places/bubble-rock', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bucko’s Giant Moose', 'buckos-giant-moose', 'roadside-oddities', 35.59943, -80.81159, 'Mooresville', 'NC', 'A roughly 15-foot fiberglass moose known as Bucko stands beside East Plaza Drive. The oversized animal is a surviving example of the kind of attention-grabbing commercial sculpture that once appeared far more frequently along American highways.', 'roadside', null, 'https://fotospot.com/attractions/north-carolina/buckos-moose-statue', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bunker Hill Covered Bridge', 'bunker-hill-covered-bridge', 'roadside-oddities', 35.72155, -81.11525, 'Claremont', 'NC', 'Built in the 1890s, this pedestrian-only covered bridge is one of only two surviving covered bridges in North Carolina and is recognized as a National Civil Engineering Landmark. Its lattice-truss structure survives in a wooded setting over Lyle Creek.', 'open', null, 'https://www.atlasobscura.com/places/the-bunker-hill-covered-bridge-claremont-north-carolina', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Burlington Earth Clock', 'burlington-earth-clock', 'roadside-oddities', 44.45311, -73.22957, 'Burlington', 'VT', 'A ring of large stones at Oakledge Park forms a modern megalithic calendar designed to mark solar and seasonal events. Visitors can stand among the stones and use their alignments to observe the sun in a setting that resembles a miniature Vermont Stonehenge.', 'open', null, 'https://www.atlasobscura.com/places/burlington-earth-clock', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Burnside Fountain — Turtle Boy', 'burnside-fountain-turtle-boy', 'roadside-oddities', 42.26139, -71.80032, 'Worcester', 'MA', 'A nude boy rides an enormous sea turtle at the center of this eccentric downtown fountain. Officially named the Burnside Fountain, the sculpture is universally known as Turtle Boy and has become one of Worcester''s most recognizable unofficial mascots.', 'open', null, 'https://www.atlasobscura.com/places/burnside-fountain-aka-turtle-boy', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bush Bug', 'bush-bug', 'roadside-oddities', 33.29725, -81.0345, 'Bamberg', 'SC', 'A Volkswagen Beetle covered in artificial greenery has been transformed into a rolling-looking topiary known as the Bush Bug. The plant-covered car is one of those simple roadside objects that becomes considerably stranger the longer you look at it.', 'roadside', null, 'https://www.roadsideamerica.com/tip/52101', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bush''s Beans Visitor Center', 'bushs-beans-visitor-center', 'roadside-oddities', 35.92979, -83.33934, 'Chestnut Hill', 'TN', 'The Bush''s visitor center turns baked-bean history into a museum experience with company artifacts, interactive displays and unapologetically bean-themed photo opportunities. It is an unusually elaborate monument to a grocery-shelf product born in East Tennessee.', 'open', null, 'https://bushbeans.com/en_US/about-us/visitor-center', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Buster Keaton Statue', 'buster-keaton-statue', 'roadside-oddities', 43.23507, -86.25337, 'Muskegon', 'MI', 'Silent-film legend Buster Keaton spent important childhood summers performing with his family in the Muskegon Actors'' Colony. A bronze statue installed downtown shows Keaton beside an old motion-picture camera, connecting the city to one of early cinema''s strangest physical comedians.', 'open', null, 'https://www.hmdb.org/m.asp?m=119651', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Butterfly Rainforest', 'butterfly-rainforest', 'roadside-oddities', 29.63581, -82.37076, 'Gainesville', 'FL', 'Living rainforest exhibit with hundreds of free-flying butterflies and tropical birds.', 'limited', null, 'https://www.floridamuseum.ufl.edu/exhibits/butterfly-rainforest/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Button Museum', 'button-museum', 'roadside-oddities', 34.24581, -80.3339, 'Bishopville', 'SC', 'Dalton Stevens, the “Button King,” covered a suit, car, hearse, coffin, piano, toilet, and numerous other objects with thousands of buttons after insomnia led him into an obsessive art project. His family continues to preserve the collection in a small museum that remains free and open to visitors.', 'open', null, 'https://apnews.com/article/a5c8456bb621110922eee99cc221df71', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cadi the Pig', 'cadi-the-pig', 'roadside-oddities', 36.8795, -87.73679, 'Cadiz', 'KY', 'A large pink fiberglass pig named Cadi stands beside Hopkinsville Road as a local roadside mascot. The cheerful pig has been repainted and maintained over time and remains an easy drive-up example of Kentucky''s oversized fiberglass advertising tradition.', 'roadside', null, 'https://www.roadsideamerica.com/location/ky/all', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cadillac Ranch', 'cadillac-ranch', 'roadside-oddities', 35.187229, -101.987069, 'Amarillo', 'TX', 'The Ant Farm art collective created Cadillac Ranch in 1974 for Amarillo millionaire Stanley Marsh 3, burying ten Cadillacs nose-first in a field at matching angles. The installation was moved west in 1997 as Amarillo expanded, and today it remains free to visit, with travelers walking out into the field and commonly adding their own spray paint.', 'roadside', null, 'https://www.visitamarillo.com/listing/cadillac-ranch/595/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Caffe Vittoria', 'caffe-vittoria', 'roadside-oddities', 42.364, -71.0543, 'Boston', 'MA', 'Boston''s oldest Italian café doubles as a museum of vintage espresso machines, coffee equipment and old advertising. The dense collection gives a cup of coffee the surroundings of an accidental technology museum.', 'open', null, 'https://www.atlasobscura.com/places/caffe-vittoria', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Caged Monument of Important Rocks', 'caged-monument-of-important-rocks', 'roadside-oddities', 35.53455, -83.17181, 'Maggie Valley', 'NC', 'A fenced stone monument near Black Camp Gap contains hundreds of rocks gathered from around the world and cemented together in 1938. Accounts of the collection identify pieces associated with famous locations and events, including an Egyptian pyramid, the Alamo, and other improbably far-flung sources.', 'limited', null, 'https://www.roadsideamerica.com/story/68670', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cameron Barnstormer Murals', 'cameron-barnstormer-murals', 'roadside-oddities', 35.32682, -79.2553, 'Cameron', 'NC', 'Beginning in 1999, artists from New York and Tokyo covered aging tobacco barns and farm equipment around Cameron with large contemporary murals. Some of the barns have disappeared, but surviving examples turn the rural landscape into a fading open-air graffiti gallery.', 'roadside', null, 'https://www.atlasobscura.com/places/cameron-barnstormer-murals', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Campbell’s Covered Bridge', 'campbells-covered-bridge', 'roadside-oddities', 35.08583, -82.26417, 'Landrum', 'SC', 'Built in 1909, Campbell’s Covered Bridge is the only surviving historic covered bridge in South Carolina. Its bright red wooden enclosure spans Beaverdam Creek beside old mill remnants and walking trails.', 'open', null, 'https://greenvillerec.com/parks/campbells-covered-bridge/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cape Cinema', 'cape-cinema', 'roadside-oddities', 41.74034, -70.19346, 'Dennis', 'MA', 'A 1930 movie theater hides an enormous Rockwell Kent mural across its curved ceiling, filled with constellations, floating figures and celestial imagery. Moviegoers often find the ceiling as memorable as whatever is playing on the screen.', 'limited', null, 'https://www.atlasobscura.com/places/cape-cinema', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain Brown — Giant Old Salt Fisherman', 'captain-brown-giant-old-salt-fisherman', 'roadside-oddities', 43.845, -69.626, 'Boothbay Harbor', 'ME', 'A roughly 25-foot fiberglass fisherman has watched over Brown’s Wharf since the late 1960s. The oversized old salt, complete with rain gear and pipe, is one of the classic giant figures of Maine roadside culture.', 'roadside', null, 'https://www.roadsideamerica.com/tip/1955', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Captain Sam Greele Monument', 'captain-sam-greele-monument', 'roadside-oddities', 42.82105, -71.78314, 'Wilton', 'NH', 'A roadside obelisk marks the place where Captain Samuel Greele was killed by a falling tree in 1798. Instead of moving the memorial into a cemetery or town square, later residents preserved the exact location of the freak accident. The monument is visible from the roadside but should be approached only where it is safe to pull off legally.', 'roadside', null, 'https://www.atlasobscura.com/places/captain-sam-greele-monument', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Car Parts Pumping Iron', 'car-parts-pumping-iron', 'roadside-oddities', 36.9588, -86.48737, 'Bowling Green', 'KY', 'Several weightlifters assembled from automobile and machine parts stand outside the business on Dishman Lane. The welded figures use wheels, springs and scrap components as bodies and barbells, turning discarded automotive material into an unexpected roadside gym.', 'roadside', null, 'https://www.roadsideamerica.com/location/ky/all', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carhenge', 'carhenge', 'roadside-oddities', 42.142284, -102.85796, 'Alliance', 'NE', 'Artist Jim Reinders and about 35 family members built Carhenge in the summer of 1987 as a memorial to Reinders’ father. Thirty-eight gray-painted American cars recreate the scale and arrangement of Stonehenge, and today visitors can freely walk the outdoor site and see additional automobile sculptures in the surrounding Car Art Reserve.', 'roadside', null, 'https://history.nebraska.gov/carhenge/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Denver'),
  ('Carl Sandburg State Historic Site', 'carl-sandburg-state-historic-site', 'roadside-oddities', 40.93628, -90.36595, 'Galesburg', 'IL', 'The poet''s tiny birthplace, museum, grave, and memorial grounds preserve the Midwestern roots of one of America''s most recognizable literary voices.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/northwest/carl-sandburg.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carlisle Futuro House', 'carlisle-futuro-house', 'roadside-oddities', 39.58866, -84.33806, 'Carlisle', 'OH', 'This flying-saucer-shaped residence is an example of the Futuro, the late-1960s prefabricated plastic house designed by Finnish architect Matti Suuronen. The Carlisle property is privately owned, so it should be viewed only from a legal public roadside position without entering the driveway, yard or property.', 'private', null, 'https://www.ohiomagazine.com/ohio-life/article/-the-futuro-house', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Carousel Bar & Lounge', 'carousel-bar-lounge', 'roadside-oddities', 29.95435, -90.06787, 'New Orleans', 'LA', 'The Hotel Monteleone''s bar is built as a rotating carousel that slowly carries seated guests around its center. It has operated for decades and remains one of the city''s best-known pieces of functioning novelty architecture.', 'open', null, 'https://hotelmonteleone.com/entertainment/carousel-bar/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carpenter Park Original Route 66 Pavement', 'carpenter-park-original-route-66-pavement', 'roadside-oddities', 39.8675, -89.62661, 'Springfield', 'IL', 'A newly accessible trail reaches a rare abandoned stretch of early Route 66 pavement hidden in Carpenter Park woods.', 'open', null, 'https://www.visitspringfieldillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carter-Calloway Steamboat House', 'carter-calloway-steamboat-house', 'roadside-oddities', 30.41475, -88.82427, 'Ocean Springs', 'MS', 'A private 1906-07 residence whose layered porches, railings and nautical detailing earned it the nickname "Steamboat House." It remains a private home, so OddWay users should view it only from the public street without entering the property.', 'roadside', null, 'https://www.apps.mdah.ms.gov/Public/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Carter Caves State Resort Park', 'carter-caves-state-resort-park', 'roadside-oddities', 38.37412, -83.1216, 'Olive Hill', 'KY', 'Carter Caves protects a concentration of caves, natural bridges and unusual limestone formations in northeastern Kentucky. Several caves are accessible by scheduled guided tours, while surface trails reach arches and rock formations without requiring underground travel.', 'limited', null, 'https://parks.ky.gov/explore/carter-caves-state-resort-park-7780', '2026-09-08T14:15:10.228298+00:00', null, 'https://parks.ky.gov/explore/carter-caves-state-resort-park-7780', null, null, null, 'America/New_York'),
  ('Caryatids of Book Tower', 'caryatids-of-book-tower', 'roadside-oddities', 42.3335, -83.05145, 'Detroit', 'MI', 'Twelve sculpted female figures line the exterior of Detroit''s restored Book Tower, appearing to support part of the building high above Washington Boulevard. The unusual caryatids survive from the tower''s elaborate early twentieth-century design and can be viewed from public downtown streets.', 'open', null, 'https://www.atlasobscura.com/places/the-book-tower-detroit-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Castle Farms', 'castle-farms', 'roadside-oddities', 45.28052, -85.2302, 'Charlevoix', 'MI', 'Sears executive Albert Loeb built this sprawling Norman-style complex in 1918 as a model farm, creating an improbable stone castle amid northern Michigan farmland. After decades of changing uses, the restored property now offers tours and events that let visitors legally explore the towers, courtyards and collections.', 'limited', null, 'https://castlefarms.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://castlefarms.com/', null, null, null, 'America/Detroit'),
  ('Castle in the Clouds', 'castle-in-the-clouds', 'roadside-oddities', 43.72061, -71.32245, 'Moultonborough', 'NH', 'The mountaintop mansion known as Lucknow was completed in the early twentieth century for industrialist Thomas Plant. Its Arts and Crafts design incorporated then-cutting-edge technology including unusual plumbing, refrigeration and electrical systems. The estate, trails and mansion are ticketed or seasonally operated depending on the area.', 'limited', null, 'https://www.castleintheclouds.org/hours-admission/', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.castleintheclouds.org/', null, null, null, 'America/New_York'),
  ('Castle Rock and Paul Bunyan', 'castle-rock-and-paul-bunyan', 'roadside-oddities', 45.91013, -84.74319, 'St. Ignace', 'MI', 'Castle Rock has operated as an old-school Upper Peninsula tourist stop since 1929, sending visitors up a steep staircase to the top of a nearly 200-foot limestone stack. Large Paul Bunyan and Babe the Blue Ox figures wait outside the gift shop, adding classic roadside kitsch to the natural formation.', 'limited', null, 'https://www.atlasobscura.com/places/castle-rock-st-ignace', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Cat Alley', 'cat-alley', 'roadside-oddities', 42.99002, -71.46303, 'Manchester', 'NH', 'An otherwise ordinary pedestrian alley in downtown Manchester has been turned into a gallery of cat-themed murals. More than 20 painted cats appear in styles ranging from realistic portraits to pop-culture riffs. The public walkway is free and open year-round.', 'open', null, 'https://www.visitmanchesternh.com/things-to-do/cat-alley/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cateraptasaurus', 'cateraptasaurus', 'roadside-oddities', 38.9832, -75.56874, 'Felton', 'DE', 'A mechanical dinosaur assembled from Caterpillar equipment parts has been associated with the Carter Machinery property in Felton. Recent reports indicate the sculpture may travel to events rather than remaining permanently planted, so this pin should be treated as a call-ahead stop.', 'limited', null, 'https://www.roadsideamerica.com/tip/45297', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.cartermachinery.com/', null, null, null, 'America/New_York'),
  ('Cathedral Caverns State Park', 'cathedral-caverns-state-park', 'roadside-oddities', 34.5737, -86.2216, 'Woodville', 'AL', 'The enormous entrance to Cathedral Caverns opens into a commercial cave filled with stalagmites, flowstone and immense chambers. Guided tours are required for cave access, while the surrounding state park offers surface recreation.', 'limited', null, 'https://www.alapark.com/parks/cathedral-caverns-state-park', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cathedral of the Pines', 'cathedral-of-the-pines', 'roadside-oddities', 42.77481, -71.98834, 'Rindge', 'NH', 'This outdoor sanctuary spreads memorials, stonework and worship spaces across a hill facing Mount Monadnock. Its centerpiece is a massive open-air altar assembled as a memorial to Americans who died in military service. The grounds are generally open dawn to dusk year-round, although staffed facilities have more limited hours.', 'open', null, 'https://www.cathedralofthepines.org/', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.cathedralofthepines.org/', null, null, null, 'America/New_York'),
  ('Cave of the Mounds', 'cave-of-the-mounds', 'roadside-oddities', 43.01674, -89.81486, 'Blue Mounds', 'WI', 'Discovered accidentally during quarry blasting in 1939, this limestone cave contains flowstone, stalactites, columns and colorful mineral formations. Guided tours follow paved underground passages through one of Wisconsin''s best-known cave systems.', 'limited', null, 'https://www.caveofthemounds.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.caveofthemounds.com/', null, null, null, 'America/Chicago'),
  ('Cave Point County Park', 'cave-point-county-park', 'roadside-oddities', 44.93036, -87.17244, 'Sturgeon Bay', 'WI', 'Lake Michigan waves have carved caves, arches and undercut ledges into the limestone shoreline. On rough days water explodes through openings below the cliffs, but visitors must remain behind barriers and away from dangerous edges.', 'open', null, 'https://www.co.door.wi.gov/554/Cave-Point-County-Park', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.co.door.wi.gov/', null, null, null, 'America/Chicago'),
  ('Cedars of Lebanon State Park', 'cedars-of-lebanon-state-park', 'roadside-oddities', 36.07369, -86.3115, 'Lebanon', 'TN', 'The park protects rare limestone cedar glades filled with sinkholes, thin soils and plants adapted to extreme conditions. The unusual barrens look deceptively empty but contain one of Middle Tennessee''s most distinctive natural ecosystems.', 'open', null, 'https://tnstateparks.com/parks/cedars-of-lebanon', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Center for Birds of Prey', 'center-for-birds-of-prey', 'roadside-oddities', 32.91844, -79.70683, 'Awendaw', 'SC', 'Dozens of eagles, owls, hawks, falcons, vultures, and other raptors are housed at this avian conservation center outside Charleston. Scheduled programs include live flight demonstrations that bring large birds of prey surprisingly close to visitors.', 'limited', null, 'https://thecenterforbirdsofprey.org/center-for-birds-of-prey/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Center of the Universe Monument', 'center-of-the-universe-monument', 'roadside-oddities', 44.01262, -69.19795, 'Saint George', 'ME', 'A roughly 16-foot granite monument topped by a monkey blowing a horn stands on private property and announces this patch of Maine as the “Center of the Universe.” It is an eccentric roadside-art stop; view it from the public road and do not enter the property.', 'private', null, 'https://www.roadsideamerica.com/story/70879', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chain of Rocks Bridge', 'chain-of-rocks-bridge', 'roadside-oddities', 38.76077, -90.17326, 'Madison', 'IL', 'This old Route 66 bridge crosses the Mississippi with an unusual 22-degree bend in the middle and is now open to pedestrians and cyclists.', 'open', null, 'https://www.nps.gov/places/chain-of-rocks-bridge.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Champ the Giant Great Dane', 'champ-the-giant-great-dane', 'roadside-oddities', 39.5395, -87.0577, 'Brazil', 'IN', 'A towering fiberglass Great Dane named Champ has watched over this US 40 property for decades. The dog dates to the classic era of oversized roadside advertising and has been restored and repainted several times while remaining a recognizable Brazil-area landmark.', 'roadside', null, 'https://www.roadsideamerica.com/tip/16289', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Charleston Tea Garden', 'charleston-tea-garden', 'roadside-oddities', 32.61814, -80.18522, 'Wadmalaw Island', 'SC', 'Rows of tea plants spread across hundreds of acres at one of the few large-scale tea-growing operations in the continental United States. Visitors can see tea being processed and tour the fields, making an ordinarily imported drink into an unexpected Lowcountry agricultural attraction.', 'open', null, 'https://charlestonteagarden.com/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Charlie the Coal Miner', 'charlie-the-coal-miner', 'roadside-oddities', 39.38024, -80.31443, 'Shinnston', 'WV', 'Charlie is a 21-foot scrap-metal coal miner with a lunch pail and a working light in his helmet, unveiled in 1999 as a memorial to local miners. He stands outside the Repair King property at 253 Lincoln Drive and can be photographed from the parking-area approach without entering any restricted industrial space.', 'roadside', null, 'https://www.atlasobscura.com/places/charlie-coal-miner', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Charlton Route 20 Cow Tunnel', 'charlton-route-20-cow-tunnel', 'roadside-oddities', 42.14659, -71.93708, 'Charlton', 'MA', 'A narrow concrete tunnel built in 1926 allowed cattle to pass safely beneath busy Route 20 instead of crossing traffic. The unusual agricultural underpass was preserved during recent trail work and now sits along the Midstate Trail as a wonderfully specific piece of roadside infrastructure.', 'open', null, 'https://www.atlasobscura.com/places/charlton-route-20-cow-tunnel', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chaser the Border Collie Statue', 'chaser-the-border-collie-statue', 'roadside-oddities', 34.9495, -81.93296, 'Spartanburg', 'SC', 'A bronze statue honors Chaser, the Border Collie who learned the names of more than 1,000 toys during groundbreaking canine-cognition research. Her work with psychologist John Pilley made her one of the most scientifically famous dogs in the world.', 'open', null, 'https://www.roadsideamerica.com/location/sc/all', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chatty Belle and Wisconsin Pavilion', 'chatty-belle-and-wisconsin-pavilion', 'roadside-oddities', 44.55315, -90.58052, 'Neillsville', 'WI', 'Chatty Belle is a giant fiberglass dairy cow whose recorded voice once explained Wisconsin''s dairy industry to visitors. She stands beside the Wisconsin Pavilion, a surviving World''s Fair structure that was moved to Neillsville after the 1964 New York World''s Fair.', 'limited', null, 'https://www.neillsville.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.neillsville.org/', null, null, null, 'America/Chicago'),
  ('Chauvin Sculpture Garden', 'chauvin-sculpture-garden', 'roadside-oddities', 29.44371, -90.59276, 'Chauvin', 'LA', 'Artist Kenny Hill transformed a bayou-side property into a dense concrete landscape of angels, self-portraits, towers and religious imagery before abruptly leaving it behind. Nicholls State University now preserves the environment as a public folk-art site.', 'open', null, 'https://www.nicholls.edu/folkartcenter/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cherney Maribel Caves County Park', 'cherney-maribel-caves-county-park', 'roadside-oddities', 44.2864, -87.7706, 'Maribel', 'WI', 'Sinkholes, limestone caves, rock shelters and remnants of a historic stone hotel make this county park unusually varied. Cave access can be seasonal or guided to protect bats and fragile formations.', 'limited', null, 'https://manitowoccountywi.gov/departments/public-works/parks/cherney-maribel-caves-county-park/', '2026-09-09T13:02:00.307533+00:00', null, 'https://manitowoccountywi.gov/', null, null, null, 'America/Chicago'),
  ('Cherokee Rock Village', 'cherokee-rock-village', 'roadside-oddities', 34.18213, -85.81292, 'Leesburg', 'AL', 'Massive sandstone formations rise above Weiss Lake in a maze of cliffs, crevices and balancing-looking rocks. The landscape has long attracted climbers and hikers and also preserves evidence of Native American use.', 'open', null, 'https://www.cherokeerockvillage.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Chief Little Owl', 'chief-little-owl', 'roadside-oddities', 38.53823, -75.05896, 'Bethany Beach', 'DE', 'A 24-foot red-cedar head of Nanticoke Chief Little Owl stands in the highway median greeting visitors to Bethany Beach. It is the third version of the town''s Peter "Wolf" Toth Whispering Giant after earlier carvings were lost to a storm and decay.', 'roadside', null, 'https://www.roadsideamerica.com/tip/50775', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chief Pontiac Muffler Man — Pontiac Transportation Museum', 'chief-pontiac-muffler-man-pontiac-transportation-museum', 'roadside-oddities', 42.63575, -83.30079, 'Pontiac', 'MI', 'A roughly 25-foot fiberglass figure depicting Chief Pontiac now stands indoors at the Pontiac Transportation Museum after decades as a piece of commercial roadside advertising. The restored figure belongs to the same broad family of giant fiberglass "Muffler Man" statues that once towered over businesses across America.', 'limited', null, 'https://www.roadsideamerica.com/tip/802', '2026-09-08T15:31:15.588137+00:00', null, 'https://www.pontiactransportationmuseum.org/visit/', null, null, null, 'America/Detroit'),
  ('Children’s Shoe House', 'childrens-shoe-house', 'roadside-oddities', 35.4615, -81.2816, 'Lincolnton', 'NC', 'A small building shaped like a giant child’s shoe sits in the yard at the historic Woodside property, birthplace of Texas’s first governor, James Pinckney Henderson. The property is private, and recent 2026 reports confirm the shoe is still visible from the road. Historic property reference: https://lincolncountyhistory.com/national-registry-of-historic-places/', 'private', null, 'https://www.roadsideamerica.com/tip/23004', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Christ of the Abyss', 'christ-of-the-abyss', 'roadside-oddities', 25.12313, -80.29704, 'Key Largo', 'FL', 'Submerged bronze statue of Christ standing beneath the waters of John Pennekamp Coral Reef State Park.', 'limited', null, 'https://pennekamppark.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Christy Buchanan’s SHE Garden & Gallery', 'christy-buchanans-she-garden-gallery', 'roadside-oddities', 34.3929, -81.10282, 'Winnsboro', 'SC', 'Artist Christy Buchanan has filled her property with a bottle house, sculptural figures, decorated vehicles, arches, found-object art, and other handmade installations. The garden is on private property, with the gallery generally open on weekends or by appointment, so visitors should respect posted access.', 'limited', null, 'https://www.roadsideamerica.com/tip/68124', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chuang Yen Monastery Giant Buddha', 'chuang-yen-monastery-giant-buddha', 'roadside-oddities', 41.48333, -73.79444, 'Kent', 'NY', 'Chuang Yen Monastery occupies more than 200 wooded acres and houses an enormous indoor Buddha surrounded by thousands of smaller Buddha images. The Buddhist Association of the United States welcomes visitors to the monastery at designated times, but religious services and current visitor schedules should be respected.', 'limited', null, 'https://www.baus.org/en/visit-us/chuang-yen-monastery/introducing-cym/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chutters — 112-Foot Candy Counter', 'chutters-112-foot-candy-counter', 'roadside-oddities', 44.30651, -71.77199, 'Littleton', 'NH', 'Chutters'' downtown store contains a candy counter stretching 112 feet along the shop, once recognized by Guinness as the world''s longest. Rows of jars and bins turn an ordinary candy shop into a deliberately excessive roadside attraction. The business is currently open seven days a week.', 'open', null, 'https://www.atlasobscura.com/places/chutters-candy-store', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.chutters.com/littleton', null, null, null, 'America/New_York'),
  ('Ciderville Music Store', 'ciderville-music-store', 'roadside-oddities', 36.02867, -84.09225, 'Powell', 'TN', 'This old-school music store became known for bluegrass, country instruments and an atmosphere that feels more like a regional music clubhouse than conventional retail. Hours can be irregular, so travelers should check ahead before making it a dedicated detour.', 'limited', null, 'https://www.atlasobscura.com/places/ciderville-music-store', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cincinnati Mushroom House', 'cincinnati-mushroom-house', 'roadside-oddities', 39.14118, -84.42371, 'Cincinnati', 'OH', 'Architect and University of Cincinnati professor Terry Brown spent more than a decade transforming a small Hyde Park house into an organic structure covered with warped shingles, stained glass, porthole windows and a bright spiral staircase. It remains private property, so OddWay visitors should admire and photograph the exterior only from the public sidewalk without entering the lot or stairs.', 'private', null, 'https://www.ohiomagazine.com/ohio-life/article/mushroom-house-cincinnati', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Claire d''Loon', 'claire-dloon', 'roadside-oddities', 46.16448, -90.06023, 'Mercer', 'WI', 'Mercer''s enormous fiberglass loon, Claire d''Loon, celebrates the town''s identity as the Loon Capital of the World. The bird stands roughly two stories tall and makes an unmistakable roadside photo stop beside the visitor center.', 'roadside', null, 'https://www.mercercc.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.mercercc.com/', null, null, null, 'America/Chicago'),
  ('Clarendon Gorge Suspension Bridge', 'clarendon-gorge-suspension-bridge', 'roadside-oddities', 43.52123, -72.92547, 'Shrewsbury', 'VT', 'A narrow cable suspension footbridge carries the Appalachian and Long Trail high above the Mill River gorge. The bridge was rebuilt after a deadly 1973 flood and reopened after repairs in 2025; the surrounding cliffs remain hazardous and require normal hiking caution.', 'limited', null, 'https://www.atlasobscura.com/places/clarendon-gorge-bridge', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clark''s Bears', 'clarks-bears', 'roadside-oddities', 44.04833, -71.68556, 'Lincoln', 'NH', 'Clark''s has operated as a White Mountains roadside attraction for generations, combining trained bear shows, the White Mountain Central Railroad and a collection of intentionally old-fashioned amusements. Its mix of live animals, steam trains and roadside-showmanship history makes it a distinctly New Hampshire oddity. The attraction is ticketed and seasonal.', 'limited', null, 'https://www.clarksbears.com/detailsAdmission.php', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.clarksbears.com/', null, null, null, 'America/New_York'),
  ('Clayshire Castle', 'clayshire-castle', 'roadside-oddities', 39.39782, -86.94701, 'Bowling Green', 'IN', 'This modern medieval-style castle was built in the Indiana countryside as a private residence and bed-and-breakfast, complete with towers, stonework and themed rooms. It is not an abandoned castle or public park, so interior access should be limited to booked guests or scheduled events.', 'limited', null, 'https://www.roadsideamerica.com/tip/43906', '2026-09-08T13:34:34.826362+00:00', null, 'https://clayshirecastle.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Clifford Brown Listening Garden', 'clifford-brown-listening-garden', 'roadside-oddities', 39.74807, -75.54085, 'Wilmington', 'DE', 'This compact memorial garden honors Wilmington-born jazz trumpeter Clifford Brown with a towering pair of sculptural obelisks, mosaics, benches and a sound installation. When the interactive system is operating, motion sensors can trigger Brown’s music as visitors move through the garden.', 'open', null, 'https://www.visitwilmingtonde.com/listing/clifford-brown-listening-garden/8397/', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clive the Alien', 'clive-the-alien', 'roadside-oddities', 39.08678, -84.50903, 'Covington', 'KY', 'A huge green alien named Clive peers through a magnifying glass from Covington''s Midtown Parking Garage. The playful public sculpture turns a utilitarian garage into an unexpected UFO-themed downtown photo stop.', 'open', null, 'https://www.atlasobscura.com/places/clive-covington-kentucky', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Clothespin', 'clothespin', 'roadside-oddities', 39.9524, -75.1657, 'Philadelphia', 'PA', 'Claes Oldenburg installed *Clothespin* in 1976, turning an ordinary spring clothespin into monumental public art opposite Philadelphia City Hall. It stands directly above the downtown transit concourse at 15th and Market and is freely visible from the public plaza at any time.', 'open', null, 'https://www.philart.net/art/Clothespin/75.html', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cloud Chamber for the Trees and Sky', 'cloud-chamber-for-the-trees-and-sky', 'roadside-oddities', 35.80605, -78.69902, 'Raleigh', 'NC', 'Artist Chris Drury built this stone chamber at the North Carolina Museum of Art as a giant camera obscura. A small opening projects an upside-down moving image of the surrounding trees and sky onto the interior walls, turning the room itself into a simple optical machine. Museum: https://ncartmuseum.org/', 'open', null, 'https://www.atlasobscura.com/places/cloud-chamber-for-the-trees-and-sky', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coal House', 'coal-house', 'roadside-oddities', 36.6086, -83.71435, 'Middlesboro', 'KY', 'Built in 1926 as a tourism gimmick, this Arts and Crafts-style building is faced with blocks of locally mined coal rather than ordinary stone or brick. The unusual structure later served civic and tourism functions and survives downtown as a literal house made from the material that shaped the region.', 'open', null, 'https://commons.wikimedia.org/wiki/File:Coal_House,_20th_Street_and_Lothbury_Avenue,_Middlesboro,_KY.jpg', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cofrin Asian Art Garden', 'cofrin-asian-art-garden', 'roadside-oddities', 29.63731, -82.37089, 'Gainesville', 'FL', 'Sculptural garden mixing Asian art, water features, and Florida landscape beside the Harn Museum.', 'roadside', null, 'https://harn.ufl.edu/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cold Hollow Sculpture Park', 'cold-hollow-sculpture-park', 'roadside-oddities', 44.85986, -72.76238, 'Enosburg Falls', 'VT', 'More than 70 large-scale sculptures by David Stromeyer are spread across roughly 200 acres of fields and woods. The seasonal park lets visitors wander among massive steel forms in a landscape that functions as both sculpture garden and outdoor gallery.', 'limited', null, 'https://www.coldhollowsculpturepark.com/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Colgate Clock', 'colgate-clock', 'roadside-oddities', 38.27463, -85.75287, 'Clarksville', 'IN', 'The enormous Colgate Clock was originally installed at the company''s Jersey City plant before being moved to the Clarksville factory complex in the 1920s. Its roughly 40-foot face survives as a giant industrial landmark along the Ohio River even though toothpaste production at the old plant has ended.', 'roadside', null, 'https://www.atlasobscura.com/places/colgate-clock', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Colonial Oak', 'colonial-oak', 'roadside-oddities', 29.89664, -81.31357, 'St. Augustine', 'FL', 'Huge old live oak anchoring the courtyard of the Colonial Quarter.', 'open', null, 'https://www.thecolonialoakmusicpark.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Colossal Head of Franklin D. Roosevelt', 'colossal-head-of-franklin-d-roosevelt', 'roadside-oddities', 40.22062, -74.47366, 'Roosevelt', 'NJ', 'A monumental sculpted head of Franklin D. Roosevelt sits in a wooded amphitheater in the town renamed for him. Roosevelt began as a New Deal resettlement community, making the enormous presidential head both civic monument and unusual roadside art.', 'open', null, 'https://www.roadsideamerica.com/tip/7845', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Columcille Megalith Park', 'columcille-megalith-park', 'roadside-oddities', 40.92692, -75.20227, 'Bangor', 'PA', 'This privately owned but publicly accessible sanctuary contains more than 90 large stone settings spread across more than 20 wooded acres, with most placed between 1980 and 2005. Visitors can wander several miles of rough trails from dawn to dusk for free; climbing the stones is prohibited and organized activities require permission.', 'open', null, 'https://www.columcille.org/visitingthepark', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Concrete Kingdom', 'concrete-kingdom', 'roadside-oddities', 38.32315, -85.76723, 'Clarksville', 'IN', 'The main yard of Concrete Kingdom contains thousands of concrete figures, fountains and lawn ornaments ranging from animals and religious pieces to oversized characters. Because it is an active statuary business rather than a museum, inventory changes constantly and the grounds can look different from one visit to the next.', 'open', null, 'https://concretekingdom65.com/', '2026-09-08T13:53:25.695107+00:00', null, 'https://concretekingdom65.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Conewago Potholes at Falmouth', 'conewago-potholes-at-falmouth', 'roadside-oddities', 40.11921, -76.70916, 'Conoy Township', 'PA', 'When the Susquehanna River drops low enough, the exposed diabase bedrock at Conewago Falls reveals deep circular potholes, sculpted channels and ripple-like forms carved by powerful water and sediment. The formations are only safely visible at low river levels; use the public boat-launch access and never walk onto exposed river rock during high or rising water.', 'limited', null, 'https://www.atlasobscura.com/places/conewago-potholes', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coney Island Circus Sideshow', 'coney-island-circus-sideshow', 'roadside-oddities', 40.5753, -73.9798, 'Brooklyn', 'NY', 'Coney Island USA''s Sideshows by the Seashore continues the neighborhood''s freak-show and circus-sideshow tradition with sword swallowers, fire performers and other live acts. The organization describes it as the last permanently housed circus sideshow in the United States, but performances follow a seasonal schedule rather than running every day of the year.', 'limited', null, 'https://www.coneyisland.com/coneyislandcircussideshow', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Conny the Whale''s Tail', 'conny-the-whales-tail', 'roadside-oddities', 41.76203, -72.73678, 'West Hartford', 'CT', 'Conny was once a walk-through, life-size sperm-whale sculpture outside the Children''s Museum. When the museum moved, the enormous whale was cut apart; its surviving tail was reinstalled beside the Trout Brook Trail as an intentionally strange remnant of the original landmark.', 'open', null, 'https://www.roadsideamerica.com/tip/1810', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Conrad Rice Mill / KONRIKO', 'conrad-rice-mill-konriko', 'roadside-oddities', 29.99783, -91.81094, 'New Iberia', 'LA', 'The historic Conrad Rice Mill preserves belt-driven equipment and the industrial process behind one of Louisiana''s staple foods. Tours operate on a schedule, so check current availability before routing.', 'limited', null, 'https://www.conradrice.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Contoocook Railroad Covered Bridge', 'contoocook-railroad-covered-bridge', 'roadside-oddities', 43.2231, -71.71387, 'Contoocook', 'NH', 'This long wooden bridge was built for railroad traffic rather than wagons or automobiles and survives as one of the country''s oldest covered railroad bridges. Its heavy timber trusses once carried trains across the Contoocook River. Today the preserved structure can be explored on foot from public areas.', 'open', null, 'https://www.new.coveredbridges.net/new-hampshire-bridges/contoocook', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cookie Jar House', 'cookie-jar-house', 'roadside-oddities', 39.84178, -75.07808, 'Glendora', 'NJ', 'This round novelty house was constructed to resemble an enormous cookie jar, complete with a lid-like roof. It remains a private residence, so OddWay travelers should view the unusual architecture only from public roads without entering the property.', 'private', null, 'https://www.atlasobscura.com/places/cookie-jar-house', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cooper''s Cabin', 'coopers-cabin', 'roadside-oddities', 43.63539, -72.87023, 'Mendon', 'VT', 'A rough stone-and-timber shelter sits high in the Killington backcountry along the Appalachian and Long Trail system. The primitive cabin is open to hikers but requires a real mountain approach rather than a roadside visit, so weather and trail conditions matter.', 'limited', null, 'https://www.atlasobscura.com/places/coopers-cabin', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Corolla Wild Horses', 'corolla-wild-horses', 'roadside-oddities', 36.37891, -75.83219, 'Corolla', 'NC', 'A herd of Colonial Spanish mustangs lives along the remote northern Outer Banks, descendants of horses brought to the region centuries ago. They roam freely in the beach and dune environment north of Corolla; guided tours are the safest and most practical way for travelers to see them without disturbing the herd.', 'limited', null, 'https://www.atlasobscura.com/places/corolla-wild-horses', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Coudersport Ice Mine', 'coudersport-ice-mine', 'roadside-oddities', 41.75456, -77.95533, 'Sweden Township', 'PA', 'Billy O''Neil discovered this strange cavity in 1894 while prospecting, and it became famous because ice forms inside as outside temperatures rise and retreats again as the weather cools. After decades as a roadside attraction and a long closure beginning in 1990, new owners restored and reopened it in 2014; visitation remains seasonal.', 'limited', null, 'https://coudersporticemineonline.com/pages/about-the-coudersport-ice-mine', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cranston Street Armory', 'cranston-street-armory', 'roadside-oddities', 41.81259, -71.43054, 'Providence', 'RI', 'Completed in 1907, the massive Cranston Street Armory resembles a medieval fortress planted in a Providence neighborhood, with twin towers and an enormous drill hall. Its scale and castle-like exterior have made it a favorite landmark even when the interior is not open. Unless an official event or tour is scheduled, treat this as an exterior viewing stop. Secondary source: https://www.atlasobscura.com/places/cranston-street-armory', 'roadside', null, 'https://www.goprovidence.com/listing/cranston-street-armory/24202/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cray-1 Supercomputer — Chippewa Falls Museum of Industry & Technology', 'cray-1-supercomputer-chippewa-falls-museum-of-industry-technology', 'roadside-oddities', 44.93697, -91.39258, 'Chippewa Falls', 'WI', 'Chippewa Falls helped launch the era of supercomputing through Seymour Cray''s work. The museum preserves a Cray-1 and other computing hardware whose curved cabinets and dense wiring look almost sculptural beside today''s tiny electronics.', 'limited', null, 'https://www.cfmit.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.cfmit.org/', null, null, null, 'America/Chicago'),
  ('Cross at the Crossroads', 'cross-at-the-crossroads', 'roadside-oddities', 39.10759, -88.5712, 'Effingham', 'IL', 'A 198-foot white cross rises beside Interstates 57 and 70, visible for miles and surrounded by smaller religious monuments.', 'open', null, 'https://www.enjoyillinois.com/explore/listing/cross-at-the-crossroads/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Cross Island Chapel', 'cross-island-chapel', 'roadside-oddities', 43.0995, -75.6374, 'Oneida', 'NY', 'Built in 1989 on a tiny platform in the middle of Mason''s Pond, Cross Island Chapel measures only about 28 square feet and has been promoted as the world''s smallest church. The chapel is reached by boat for private ceremonies, but ordinary travelers should view it from the public roadside rather than attempting to cross the pond.', 'roadside', null, 'https://www.oneidacityny.gov/sites/default/files/fileattachments/community/page/3217/may_newsletter.pdf', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Croswell Swinging Bridge', 'croswell-swinging-bridge', 'roadside-oddities', 43.27522, -82.6237, 'Croswell', 'MI', 'Built in 1905, this narrow pedestrian suspension bridge sways above the Black River and carries the famously odd instruction "Be Good to Your Mother-in-Law." The bridge remains a free public landmark and gives travelers a quick, slightly unnerving walk across the river.', 'open', null, 'https://www.michigan.org/property/croswell-swinging-bridge', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Crystal Cave', 'crystal-cave', 'roadside-oddities', 41.64661, -82.82672, 'Put-in-Bay', 'OH', 'Stairs descend beneath a working winery on South Bass Island into a small chamber lined with celestite crystals, some of them among the largest ever found. It was discovered in 1897 by men digging a well, and the tour takes in both the cave and the winery above it.', 'limited', null, 'https://heinemanswinery.com/', '2026-09-09T13:20:00.632788+00:00', null, 'https://www.acoolcave.org/', null, null, null, 'America/New_York'),
  ('Crystal Cave', 'crystal-cave-kutztown', 'roadside-oddities', 40.52614, -75.84249, 'Richmond Township', 'PA', 'Crystal Cave was discovered in 1871 and became one of Pennsylvania''s earliest commercial show caves. Seasonal guided tours descend into passages filled with stalactites, stalagmites and crystalline formations, with additional exhibits and attractions above ground.', 'limited', null, 'https://crystalcavepa.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crystal Cave', 'crystal-cave-spring-valley', 'roadside-oddities', 44.83295, -92.2508, 'Spring Valley', 'WI', 'Stairs descend into passages lined with stalactites, flowstone and other limestone formations at Wisconsin''s longest known cave. Guided tours run seasonally, and the temperature underground stays around fifty degrees whatever the weather above.', 'limited', null, 'https://www.acoolcave.org/', '2026-09-09T13:20:00.632788+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Crystal Grottoes Caverns', 'crystal-grottoes-caverns', 'roadside-oddities', 39.49806, -77.67694, 'Boonsboro', 'MD', 'Discovered during quarry work in 1920, Crystal Grottoes developed into Maryland''s only commercial show cave. Guided tours descend into chambers filled with stalactites, flowstone and other formations, so visitors must enter during the attraction''s operating season and tour hours.', 'limited', null, 'https://www.mgs.md.gov/geology/caves/crystal_grottoes.html', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Crystal Onyx Cave', 'crystal-onyx-cave', 'roadside-oddities', 37.11073, -85.97347, 'Cave City', 'KY', 'Discovered in 1960, Crystal Onyx is a privately operated show cave packed with calcite formations beneath Prewitts Knob. Guided tours descend into the cave through a developed route, giving travelers another underground stop that feels very different from the huge passages of nearby Mammoth Cave.', 'limited', null, 'https://cavecountrytrails.com/trails/crystal-onyx-cave/', '2026-09-08T14:30:49.642487+00:00', null, 'https://crystalonyxcaveky.com/', null, null, null, 'America/Chicago'),
  ('Crystal Shrine Grotto', 'crystal-shrine-grotto', 'roadside-oddities', 35.11044, -89.874, 'Memphis', 'TN', 'Artist Dionicio Rodriguez transformed part of Memorial Park Cemetery into a crystal-studded artificial cave filled with biblical tableaux and faux-natural concrete forms. The grotto feels like a fantasy cavern hidden inside an otherwise conventional cemetery landscape.', 'open', null, 'https://www.atlasobscura.com/places/the-crystal-shrine-grotto', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('CSS Albemarle Replica', 'css-albemarle-replica', 'roadside-oddities', 35.86853, -76.74787, 'Plymouth', 'NC', 'A full-size floating replica of the Confederate ironclad CSS Albemarle sits beside the Port O’Plymouth Museum. The original armored vessel terrorized Union forces on eastern North Carolina rivers before being sunk by a daring torpedo attack in 1864. Location: https://www.waymarking.com/waymarks/wm17Z0H_The_Port_o_Plymouth_Museum_Plymouth_NC', 'limited', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cumberlandite at Iron Mine Hill', 'cumberlandite-at-iron-mine-hill', 'roadside-oddities', 42.00399, -71.45663, 'Cumberland', 'RI', 'Iron Mine Hill contains one of the best-known exposures of Cumberlandite, an unusually dense magnetic rock found in significant quantities almost nowhere outside this part of Rhode Island. The material was named the official state rock in 1966. Reaching the outcrops involves a real hike, so visitors should use established trails and leave the rock in place.', 'open', null, 'https://www.oceanstatemedia.org/climate-environment/2026-07-15/rhode-island-rocks-our-quest-for-cumberlandite', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Curioporium', 'curioporium', 'roadside-oddities', 41.60079, -72.88188, 'Southington', 'CT', 'A curiosity shop inside Factory Square filled with taxidermy, natural-history specimens, antiques, strange artwork, unusual collectibles and other objects selected for maximum oddity. It functions as both a shop and a cabinet-of-curiosities-style browsing stop.', 'open', null, 'https://www.atlasobscura.com/places/curioporium', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.curioporium.com/', null, null, null, 'America/New_York'),
  ('CVRATED by Ryan Matthew Cohn', 'cvrated-by-ryan-matthew-cohn', 'roadside-oddities', 41.18185, -73.16495, 'Bridgeport', 'CT', 'A new Bridgeport curiosity shop from oddities collector Ryan Matthew Cohn combines antique medical objects, taxidermy, natural-history pieces and unusual decorative material. It opened in 2026 and currently keeps limited public hours with additional visits available by arrangement.', 'limited', null, 'https://www.atlasobscura.com/places/cvrated-by-ryan-matthew-cohn', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Da Crusher Statue', 'da-crusher-statue', 'roadside-oddities', 42.91028, -87.86289, 'South Milwaukee', 'WI', 'A bronze statue honors professional wrestler Reggie ''Da Crusher'' Lisowski, the beer-drinking, blue-collar wrestling icon closely associated with South Milwaukee. Fans crowdfunded the memorial, which now stands publicly in his hometown.', 'open', null, 'https://www.roadsideamerica.com/story/65895', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.southmilwaukee.gov/', null, null, null, 'America/Chicago'),
  ('Da Yoopers Tourist Trap', 'da-yoopers-tourist-trap', 'roadside-oddities', 46.49228, -87.69794, 'Ishpeming', 'MI', 'This proudly ridiculous Upper Peninsula attraction mixes Yooper humor with homemade machines, mining jokes and enormous outdoor sculptures. Its best-known pieces include Big Gus, an oversized working chainsaw, and Big Ernie, a gigantic rifle, giving travelers multiple oddities at one easy roadside stop.', 'open', null, 'https://www.michigan.org/property/da-yoopers-tourist-trap', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Damariscotta Mills Historic Fish Ladder', 'damariscotta-mills-historic-fish-ladder', 'roadside-oddities', 44.06194, -69.52656, 'Newcastle', 'ME', 'A historic stone fish ladder climbs from the Damariscotta River system toward Damariscotta Lake, allowing enormous runs of alewives to bypass the old mill site. During the spring migration, thousands of fish can crowd the narrow channel at once, turning a piece of practical infrastructure into a strange natural spectacle.', 'open', null, 'https://www.newenglandswimmingholes.com/maine/waterfalls/damariscotta-mills', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dana-Thomas House', 'dana-thomas-house', 'roadside-oddities', 39.79414, -89.65142, 'Springfield', 'IL', 'Frank Lloyd Wright''s extraordinary Prairie-style house contains more original Wright furniture and art glass than nearly any other site.', 'limited', null, 'https://dnrhistoric.illinois.gov/experience/sites/central/dana-thomas-house.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Daniel Boone Pioneer Giant at Bill’s Truck Stop', 'daniel-boone-pioneer-giant-at-bills-truck-stop', 'roadside-oddities', 35.75604, -80.34575, 'Linwood', 'NC', 'A giant bearded pioneer figure stands in the parking lot of Bill’s Truck Stop, where the old fiberglass advertising statue has survived multiple decades and relocations. A 2026 traveler report confirms the giant and the old-school truck stop are both still operating as an easy I-85 detour. Coordinates: https://virtualglobetrotting.com/map/pioneer-giant/ Current status: https://www.thetriumphadventures.com/glmc-trip-3/', 'open', null, 'https://www.roadsideamerica.com/tip/9085', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dark & Deviant Oddities', 'dark-deviant-oddities', 'roadside-oddities', 35.5291, -82.5282, 'Asheville', 'NC', 'Tucked inside Valiant Inscriptions Tattoo Gallery, this collection specializes in wet specimens, taxidermy, bones, skulls, malformed animals, and other macabre curiosities. Displays have included a cyclops deer, six-legged calf, Fiji-mermaid-style specimen, and human skulls. Current address: https://porcupine-icosahedron-hjxm.squarespace.com/faq', 'open', null, 'https://www.darkdeviantoddities.com/about', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dark Matter Oddities & Artisan Collective', 'dark-matter-oddities-artisan-collective', 'roadside-oddities', 29.95871, -90.06262, 'New Orleans', 'LA', 'Dark Matter specializes in taxidermy, wet specimens, fossils, Victorian ephemera, medical objects and macabre art. Inventory changes constantly, but the shop remains one of the French Quarter''s most concentrated cabinets of curiosities.', 'open', null, 'https://darkmatteroddities.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dark Star Park', 'dark-star-park', 'roadside-oddities', 38.89375, -77.07176, 'Arlington', 'VA', 'Artist Nancy Holt designed Dark Star Park as Arlington''s first county-commissioned public artwork, and it was installed in 1984. Its concrete spheres, tunnels, poles and carefully placed shadows form a strange astronomical landscape, with a famous annual alignment occurring around 9:32 a.m. every August 1.', 'open', null, 'https://www.arlingtonva.us/Government/Departments/Parks-Recreation/Locations/Parks/Dark-Star-Park', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dawes Arboretum Hedge Letters', 'dawes-arboretum-hedge-letters', 'roadside-oddities', 39.98013, -82.4131, 'Newark', 'OH', 'More than a thousand northern white cedars planted beginning in 1942 form enormous letters spelling out DAWES ARBORETUM across the landscape. Visitors can walk near the hedge and climb the arboretum''s observation tower for a better view, with entry subject to the arboretum''s current admission and operating hours.', 'open', null, 'https://www.atlasobscura.com/places/dawes-arboretum-hedge-letters', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('De Immigrant Windmill', 'de-immigrant-windmill', 'roadside-oddities', 41.86715, -90.16846, 'Fulton', 'IL', 'A full-size working Dutch windmill built in the Netherlands and reassembled on the Mississippi Riverfront, complete with traditional milling machinery.', 'open', null, 'https://www.cityoffulton.us/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Deed to God Rock', 'deed-to-god-rock', 'roadside-oddities', 42.25627, -71.86239, 'Worcester', 'MA', 'In 1840, miller and Millerite believer Solomon Parsons Jr. carved a roughly 215-word deed into a boulder declaring ten surrounding acres conveyed to God. Parts of the inscription remain legible along trails in the city-owned God''s Acre conservation land.', 'open', null, 'https://www.roadsideamerica.com/tip/59714', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.worcesterma.gov/city-parks', null, null, null, 'America/New_York'),
  ('Deere John Project', 'deere-john-project', 'roadside-oddities', 37.9317, -85.31892, 'Bloomfield', 'KY', 'Inspired by Cadillac Ranch, Linda Bruckheimer planted ten John Deere tractors nose-first in a field north of Bloomfield in 2020. The machines progress from older to newer models and are intended as a tribute to the area''s farming history; a roadside pull-off allows legal viewing without entering the private field.', 'roadside', null, 'https://www.roadsideamerica.com/tip/72508', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dells of the Wisconsin River State Natural Area', 'dells-of-the-wisconsin-river-state-natural-area', 'roadside-oddities', 43.68034, -89.79875, 'Wisconsin Dells', 'WI', 'Sandstone cliffs, narrow channels, pillars and side canyons line the Wisconsin River north of the tourist district. Much of the most dramatic scenery is easiest to see from the water, while protected natural-area lands require visitors to respect access rules.', 'limited', null, 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=109', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/', null, null, null, 'America/Chicago'),
  ('Dentzel Carousel', 'dentzel-carousel', 'roadside-oddities', 32.37685, -88.71861, 'Meridian', 'MS', 'A rare 1895 Dentzel menagerie carousel housed in its historic carousel building and long operated as a public attraction in Highland Park. As of September 2026 Visit Meridian lists the carousel as temporarily closed for renovations, so keep it in the database as `limited` until reopening is confirmed.', 'limited', null, 'https://visitmeridian.com/things_to_do/dentzel-carousel/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dequindre Cut Greenway', 'dequindre-cut-greenway', 'roadside-oddities', 42.3439, -83.0336, 'Detroit', 'MI', 'A former below-grade railroad corridor has been converted into a public greenway lined with large murals and layers of Detroit street art. The unusual sunken route lets walkers and cyclists move through the city inside what feels like a long outdoor graffiti gallery.', 'open', null, 'https://www.atlasobscura.com/things-to-do/detroit-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Desert of Maine', 'desert-of-maine', 'roadside-oddities', 43.85921, -70.15544, 'Freeport', 'ME', 'A broad expanse of exposed glacial sand sits unexpectedly among the forests of Freeport, creating one of Maine’s strangest landscapes. Despite the name, it is not a true climatic desert; the unusual sand deposit became a long-running roadside attraction.', 'limited', null, 'https://desertofmaine.com/visit', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Detroit Geodesic Dome House', 'detroit-geodesic-dome-house', 'roadside-oddities', 42.32652, -83.07973, 'Detroit', 'MI', 'This pair of steel-reinforced concrete domes forms one of Detroit''s most recognizable unconventional private homes. Built around 2000, the structure can be seen from public streets, but it remains a residence and OddWay visitors should not enter the property.', 'private', null, 'https://www.atlasobscura.com/places/geodesic-dome-house', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Detroit Industrial Gallery', 'detroit-industrial-gallery', 'roadside-oddities', 42.38736, -82.9513, 'Detroit', 'MI', 'Artist Tim Burke created an outdoor sculpture environment using architectural fragments salvaged from demolished Detroit landmarks. Stone, metal and building pieces from lost factories, institutions and department stores have been repurposed into a physical collage of the city''s disappearing industrial landscape.', 'roadside', null, 'https://www.atlasobscura.com/places/detroit-industrial-gallery', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Devil''s Den Prehistoric Spring', 'devils-den-prehistoric-spring', 'roadside-oddities', 29.40734, -82.47678, 'Williston', 'FL', 'Underground prehistoric spring inside a collapsed limestone cavern.', 'open', null, 'https://devilsden.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Doorway', 'devils-doorway', 'roadside-oddities', 43.42514, -89.72837, 'Baraboo', 'WI', 'Two vertical quartzite pillars support a horizontal slab high above Devil''s Lake, forming a natural doorway in the bluff. A steep hiking route reaches the formation, so weather, footwear and trail conditions matter.', 'open', null, 'https://dnr.wisconsin.gov/topic/parks/devilslake', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/topic/parks/devilslake', null, null, null, 'America/Chicago'),
  ('Devil''s Millhopper Geological State Park', 'devils-millhopper-geological-state-park', 'roadside-oddities', 29.70696, -82.39553, 'Gainesville', 'FL', 'A huge bowl-shaped sinkhole exposing more than 100 feet of Florida geology.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/devils-millhopper-geological-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Punchbowl', 'devils-punchbowl', 'roadside-oddities', 44.85375, -91.94881, 'Menomonie', 'WI', 'A short trail descends into a cool sandstone amphitheater carved by water and weather. Mossy walls, overhangs and the bowl-shaped ravine create a miniature canyon hidden close to Menomonie.', 'open', null, 'https://www.dunncountywi.gov/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.dunncountywi.gov/', null, null, null, 'America/Chicago'),
  ('Devil''s Standtable at Giant City State Park', 'devils-standtable-at-giant-city-state-park', 'roadside-oddities', 37.59957, -89.19339, 'Makanda', 'IL', 'A mushroom-shaped sandstone formation rises from the forest near Giant City, one of the park''s most recognizable erosion-sculpted rock forms.', 'open', null, 'https://dnr.illinois.gov/parks/park.giantcity.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Diamond Caverns', 'diamond-caverns', 'roadside-oddities', 37.17438, -86.12624, 'Park City', 'KY', 'Discovered in 1859, Diamond Caverns became one of Kentucky''s earliest commercial cave attractions. Guided tours descend through passages densely packed with stalactites, flowstone and other formations just outside Mammoth Cave National Park.', 'limited', null, 'https://diamondcaverns.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://diamondcaverns.com/', null, null, null, 'America/Chicago'),
  ('Dickeyville Grotto', 'dickeyville-grotto', 'roadside-oddities', 42.62738, -90.59507, 'Dickeyville', 'WI', 'Father Mathias Wernerus covered shrines with colored glass, stones, shells, fossils and found objects to create a dense devotional landscape beside Holy Ghost Church. Religious imagery mixes with patriotic symbols and glittering folk-art surfaces.', 'open', null, 'https://www.dickeyvillegrotto.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.dickeyvillegrotto.com/', null, null, null, 'America/Chicago'),
  ('Diehl''s Jalopy Junction', 'diehls-jalopy-junction', 'roadside-oddities', 41.3917, -85.382, 'Albion', 'IN', 'This rural property is packed with vintage gas-station signs, old cars, petroleum memorabilia and other roadside relics arranged into a sprawling personal collection. The owners have historically welcomed respectful visitors, but it remains private property and should only be entered when permission or visitor access is clearly offered.', 'private', null, 'https://www.roadsideamerica.com/tip/61661', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Dinosaur Gardens', 'dinosaur-gardens', 'roadside-oddities', 44.91536, -83.43996, 'Ossineke', 'MI', 'Artist Paul Domke began building this wooded prehistoric attraction in the 1930s, filling the property with hand-built concrete dinosaurs and other oversized creatures. The old-school sculptures and forest trail preserve the look of an early American roadside dinosaur park rather than a modern theme-park interpretation.', 'limited', null, 'https://www.dinosaurgardensllc.com/', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.dinosaurgardensllc.com/', null, null, null, 'America/Detroit'),
  ('Dinosaur Kingdom II', 'dinosaur-kingdom-ii', 'roadside-oddities', 37.64899, -79.52483, 'Natural Bridge', 'VA', 'Artist Mark Cline''s Dinosaur Kingdom II imagines an alternate Civil War in which Union soldiers discover dinosaurs and attempt to use them as weapons. The walk-through attraction is packed with life-size fiberglass dinosaurs, soldiers and absurd battle scenes and operates seasonally rather than year-round.', 'limited', null, 'https://www.dinosaurkingdomii.com/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dinosaur Land', 'dinosaur-land', 'roadside-oddities', 39.06003, -78.13997, 'White Post', 'VA', 'Opened in the early 1960s, Dinosaur Land is an old-school roadside attraction filled with more than 50 large prehistoric creature statues. Its deliberately dated dinosaurs, giant shark, octopus and other oversized beasts preserve the feel of mid-century American roadside tourism.', 'open', null, 'https://dinosaurlandva.com/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dinosaur Skeleton Sculptures', 'dinosaur-skeleton-sculptures', 'roadside-oddities', 35.4978, -77.9409, 'Pikeville', 'NC', 'Large steel dinosaur skeletons stand outside Benton & Sons Fabrication along NC 581, showing off the company’s metalworking skills in prehistoric form. Several of the skeletal creatures are illuminated or decorated during holiday periods. Address reference: https://www.osha.gov/ords/imis/establishment.inspection_detail?id=1369557.015', 'roadside', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dinosaur World', 'dinosaur-world', 'roadside-oddities', 37.13667, -85.97156, 'Cave City', 'KY', 'More than a hundred life-size dinosaur models populate the wooded trails at this classic Cave City roadside attraction. The giant prehistoric figures, fossil activities and oversized entrance make it a strong family-friendly OddWay stop near Mammoth Cave.', 'limited', null, 'https://www.atlasobscura.com/places/dinosaur-world', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.dinosaurworld.com/kentucky/', null, null, null, 'America/Chicago'),
  ('Dinosaur World Florida', 'dinosaur-world-florida', 'roadside-oddities', 28.02814, -82.1922, 'Plant City', 'FL', 'Twenty-two-acre roadside jungle filled with hundreds of life-size dinosaur models.', 'roadside', null, 'https://www.dinosaurworld.com/florida', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Diorama of Venetian Palace', 'diorama-of-venetian-palace', 'roadside-oddities', 42.34931, -71.07824, 'Boston', 'MA', 'A painstaking miniature Venetian palace scene is tucked inside the Boston Public Library''s McKim Building. The architectural model grew out of one collector''s obsession with recreating an ornate European interior in tiny scale.', 'limited', null, 'https://www.atlasobscura.com/places/diorama-of-venetian-palace', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dismals Canyon', 'dismals-canyon', 'roadside-oddities', 34.32722, -87.7825, 'Phil Campbell', 'AL', 'This narrow sandstone gorge shelters colonies of bioluminescent larvae known locally as Dismalites, visible on certain guided night tours. Day hiking and night-tour schedules vary by season and weather, so advance checking is essential.', 'limited', null, 'https://www.dismalscanyon.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dixie Cup Water Tower', 'dixie-cup-water-tower', 'roadside-oddities', 38.08004, -84.52675, 'Lexington', 'KY', 'A giant Dixie cup still sits high above the former Dixie Cup plant even though the property changed corporate ownership long ago. The tower became such a recognizable navigation landmark that it survived the brand''s departure and remains visible from surrounding public roads.', 'roadside', null, 'https://www.atlasobscura.com/places/dixie-cup-water-tower', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Doane Rock', 'doane-rock', 'roadside-oddities', 41.84426, -69.95777, 'Eastham', 'MA', 'A massive glacial erratic rests beside the road within Cape Cod National Seashore. The boulder was carried here by ice and left behind as the glaciers retreated, producing one of the Cape''s largest and easiest-to-reach pieces of Ice Age geology.', 'open', null, 'https://www.nps.gov/places/doane-rock.htm', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dog Chapel', 'dog-chapel', 'roadside-oddities', 44.43553, -71.98185, 'St. Johnsbury', 'VT', 'Artist Stephen Huneck created this small hilltop chapel as a place for people to remember dogs they have lost. Its walls are covered with thousands of handwritten memorial notes, while dog-themed carvings and sculptures fill the surrounding grounds.', 'open', null, 'https://www.atlasobscura.com/places/dog-chapel', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Don Knotts Statue', 'don-knotts-statue', 'roadside-oddities', 39.63075, -79.95524, 'Morgantown', 'WV', 'Morgantown unveiled this life-size bronze statue of hometown actor Don Knotts in 2016 outside the Metropolitan Theatre. The sculpture includes references to his best-known roles and is freely accessible from the downtown sidewalk area.', 'open', null, 'https://www.atlasobscura.com/places/statue-of-don-knotts', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Don Q Inn — Boeing C-97 and Fantasy Rooms', 'don-q-inn-boeing-c-97-and-fantasy-rooms', 'roadside-oddities', 43.0207, -90.13196, 'Dodgeville', 'WI', 'A retired Boeing C-97 transport plane sits improbably outside this roadside inn, while themed rooms inside include caves, spaceships, hot-air balloons and other elaborate fantasy environments. The combination makes the motel itself an OddWay attraction.', 'open', null, 'https://www.donqinn.net/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.donqinn.net/', null, null, null, 'America/Chicago'),
  ('Donkey Kong Mural', 'donkey-kong-mural', 'roadside-oddities', 43.20342, -71.5365, 'Concord', 'NH', 'A downtown mural transforms a tall elevator shaft into a giant level of the classic Donkey Kong arcade game. Painted in 2022, the work uses the building''s vertical shape as part of the joke, with pixel-style platforms climbing toward the roof. It is best viewed from public streets without entering the residential property.', 'open', null, 'https://www.atlasobscura.com/places/donkey-kong-mural', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Doullut Steamboat Houses', 'doullut-steamboat-houses', 'roadside-oddities', 29.95582, -90.02173, 'New Orleans', 'LA', 'Two Lower Ninth Ward houses were designed with towers and galleries that deliberately echo Mississippi River steamboats. They are private residences, so appreciate the architecture from public streets only.', 'roadside', null, 'https://www.nps.gov/nr/travel/louisiana/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dowling House', 'dowling-house', 'roadside-oddities', 42.41711, -90.42699, 'Galena', 'IL', 'Built in 1826, this rough limestone trading house is one of Galena''s oldest surviving structures and feels dramatically older than the city around it.', 'limited', null, 'https://www.galenahistory.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Downtown Presbyterian Church', 'downtown-presbyterian-church', 'roadside-oddities', 36.16317, -86.77976, 'Nashville', 'TN', 'The church''s Egyptian Revival interior and exterior use columns, lotus-like forms and other motifs rarely seen in American Protestant architecture. Public access depends on worship, tours and events, so check before expecting an interior visit.', 'limited', null, 'https://www.dpchurch.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dr. Bob Folk Art', 'dr-bob-folk-art', 'roadside-oddities', 29.9642, -90.043, 'New Orleans', 'LA', 'Local artist Dr. Bob is known for handmade signs, assemblages and the recurring ''Be Nice or Leave'' slogan. His Chartres Street studio is a dense folk-art environment rather than a conventional gallery; verify current hours before visiting.', 'limited', null, 'https://drbobart.net/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dr. Evermor''s Forevertron', 'dr-evermors-forevertron', 'roadside-oddities', 43.3637, -89.77085, 'North Freedom', 'WI', 'Artist Tom Every transformed salvaged industrial machinery into the Forevertron, a massive retro-futurist sculpture imagined as a device that could launch its creator into the heavens. The surrounding art park is packed with metal birds, machines and other outsider-art constructions.', 'limited', null, 'https://www.worldofdrevermor.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.worldofdrevermor.com/', null, null, null, 'America/Chicago'),
  ('Dr. Seuss Sculpture Garden', 'dr-seuss-sculpture-garden', 'roadside-oddities', 42.10455, -72.58731, 'Springfield', 'MA', 'Bronze versions of the Cat in the Hat, Horton, the Grinch and other Dr. Seuss characters surround a sculpture of Springfield-born author Theodor Geisel. The outdoor garden turns his illustrated universe into a walkable cluster of oversized characters.', 'open', null, 'https://springfieldmuseums.org/about/dr-seuss-sculpture-garden/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dragon Park — Fannie Mae Dees Park', 'dragon-park-fannie-mae-dees-park', 'roadside-oddities', 36.13813, -86.80594, 'Nashville', 'TN', 'A long mosaic dragon coils through this neighborhood park, covered in brightly colored tile and community-made details. The creature is climbable public art and has become one of Nashville''s most distinctive non-music landmarks.', 'open', null, 'https://www.atlasobscura.com/places/dragon-park', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dressed John Milton Statue', 'dressed-john-milton-statue', 'roadside-oddities', 38.77592, -75.31199, 'Milton', 'DE', 'A life-size statue of poet John Milton stands along Governor’s Walk and regularly turns up wearing seasonal costumes and accessories. The anonymous dressing tradition has become a local mystery of its own, with no single person consistently taking credit for the statue’s changing wardrobe.', 'open', null, 'https://www.atlasobscura.com/places/dressed-john-milton-statue', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dry Land Dock and Boat', 'dry-land-dock-and-boat', 'roadside-oddities', 44.03436, -72.599, 'Brookfield', 'VT', 'A full-size boat sits permanently ''docked'' on dry land in a deliberately nautical roadside display. The joke works especially well in rural Vermont, where the vessel looks spectacularly out of place away from any navigable water.', 'roadside', null, 'https://www.roadsideamerica.com/tip/22092', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Duke Lemur Center', 'duke-lemur-center', 'roadside-oddities', 35.9942, -78.96247, 'Durham', 'NC', 'Duke University maintains the world’s largest population of lemurs outside Madagascar in a research and conservation center hidden in the woods near campus. Public visits are controlled through scheduled tours rather than ordinary zoo-style walk-in access.', 'limited', null, 'https://lemur.duke.edu/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dungeons & Dragons — Gary Gygax Memorial Plaque', 'dungeons-dragons-gary-gygax-memorial-plaque', 'roadside-oddities', 42.59113, -88.43391, 'Lake Geneva', 'WI', 'Lake Geneva was the home base of Gary Gygax and the early tabletop-gaming community that produced Dungeons & Dragons. A public plaque commemorates Gygax and the city''s outsized role in creating modern role-playing games.', 'open', null, 'https://www.visitlakegeneva.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.visitlakegeneva.com/', null, null, null, 'America/Chicago'),
  ('Duquesne Brewery Clock', 'duquesne-brewery-clock', 'roadside-oddities', 40.42615, -79.97652, 'Pittsburgh', 'PA', 'This enormous 60-foot-square clock was built in 1933 and later moved onto the former Duquesne Brewing Company building. Its face and hands dwarf those of many traditional clock towers, and it remains visible from surrounding public streets and bridges even though the old brewery itself is not a visitor attraction.', 'roadside', null, 'https://www.atlasobscura.com/places/duquesne-brewery-clock', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eagle Rock', 'eagle-rock', 'roadside-oddities', 41.64707, -72.40763, 'Amston', 'CT', 'A large natural rock outcrop beside Route 66 has been painted into a giant American bald eagle, with local volunteers periodically refreshing the image. It is a simple but unmistakable piece of Connecticut roadside folk art.', 'roadside', null, 'https://www.roadsideamerica.com/tip/3449', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Earl the Mechanic Muffler Man', 'earl-the-mechanic-muffler-man', 'roadside-oddities', 38.73132, -90.12372, 'Granite City', 'IL', 'A vintage-style mechanic Muffler Man stands along Nameoki Road as another oversized addition to Granite City''s growing giant-statue collection.', 'roadside', null, 'https://www.riversandroutes.com/blog/giants-of-granite-city/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Earl Young Mushroom Houses', 'earl-young-mushroom-houses', 'roadside-oddities', 45.31806, -85.2584, 'Charlevoix', 'MI', 'Self-taught builder Earl Young created a group of stone cottages with curved roofs, massive boulders and storybook proportions that have become known as Charlevoix''s Mushroom Houses. Most are private residences, so travelers should view them respectfully from public streets or use an authorized walking tour rather than entering yards.', 'private', null, 'https://www.atlasobscura.com/places/earl-young-gnome-homes', '2026-09-08T14:53:55.160019+00:00', null, 'https://visitcharlevoix.com/earl-young-mushroom-houses/', null, null, null, 'America/Detroit'),
  ('Early Cotton Press', 'early-cotton-press', 'roadside-oddities', 34.33811, -79.52364, 'Latta', 'SC', 'A massive wooden screw press survives as a rare example of the machinery once used to compress cotton into transportable bales. Its oversized timbers and primitive mechanical design make the structure look almost like a wooden siege engine.', 'open', null, 'https://www.scpictureproject.org/dillon-county/early-cotton-press.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Earthoid Water Tower', 'earthoid-water-tower', 'roadside-oddities', 39.18472, -77.24961, 'Germantown', 'MD', 'A huge spherical water tank has been painted as a remarkably detailed globe of the Earth, turning a piece of utility infrastructure into a giant roadside planet. It is best viewed from nearby public roads and areas around the Montgomery College Germantown campus rather than approached as an attraction with its own visitor entrance.', 'roadside', null, 'https://www.roadsideamerica.com/location/md/all', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Easter Island Fisherman', 'easter-island-fisherman', 'roadside-oddities', 42.39374, -71.14122, 'Cambridge', 'MA', 'A giant fisherman statue stands outside the Royal Sonesta-area/Alewife corridor like a survivor from the classic fiberglass roadside era. The oversized figure has moved over the years, so older photos and maps may show him elsewhere; this pin reflects the currently documented Cambridge location.', 'roadside', null, 'https://www.roadsideamerica.com/location/ma', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Easter Island Head with Topknot', 'easter-island-head-with-topknot', 'roadside-oddities', 41.55232, -73.03456, 'Waterbury', 'CT', 'A roughly 40-foot moai replica with a red topknot survives beside the former Timexpo Museum. The museum closed in 2015, but the enormous concrete head remains beside the shopping complex as a bizarre leftover from an attempt to connect Timex with explorer Thor Heyerdahl.', 'roadside', null, 'https://www.roadsideamerica.com/story/83637', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Echo Bridge', 'echo-bridge', 'roadside-oddities', 42.31478, -71.22698, 'Newton', 'MA', 'A nineteenth-century aqueduct bridge over the Charles River creates an unusually strong repeating echo beneath its stone arch. A public stairway leads to the echo platform, where a shout or clap can bounce back several times in rapid succession.', 'open', null, 'https://www.atlasobscura.com/places/echo-bridge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Eddie — World’s Biggest Kid', 'eddie-worlds-biggest-kid', 'roadside-oddities', 33.99723, -81.04819, 'Columbia', 'SC', 'Inside EdVenture stands Eddie, a roughly 40-foot-tall child that visitors can actually climb through. His internal organs, bones, stomach, brain, and other body systems become tunnels and exhibits, essentially turning a giant human body into a playground. Museum: https://www.edventure.org/', 'limited', null, 'https://www.roadsideamerica.com/story/12960', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgar Allan Poe Library in a Military Bunker', 'edgar-allan-poe-library-in-a-military-bunker', 'roadside-oddities', 32.75965, -79.84058, 'Sullivan’s Island', 'SC', 'The island’s public library occupies part of Battery Gadsden, a former coastal-defense bunker, and is named for Edgar Allan Poe. Poe was stationed on Sullivan’s Island as a young soldier, and the setting later influenced stories including “The Gold-Bug.”', 'limited', null, 'https://sullivansisland.sc.gov/node/120', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Edgehill Polar Bears', 'edgehill-polar-bears', 'roadside-oddities', 36.14201, -86.78656, 'Nashville', 'TN', 'Large white polar-bear statues preserve the memory of a long-gone frozen-custard business in the Edgehill neighborhood. The animals survived their original commercial purpose and became neighborhood mascots in their own right.', 'open', null, 'https://www.atlasobscura.com/places/edgehill-polar-bears', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Edisto Mystery Tree', 'edisto-mystery-tree', 'roadside-oddities', 32.55092, -80.28033, 'Edisto Island', 'SC', 'For years, passing motorists have decorated this roadside tree with an ever-changing collection of seasonal props, signs, toys, and costumes. No single display lasts forever, so the fun is seeing what bizarre version of the tree happens to exist when you arrive.', 'roadside', null, 'https://www.roadsideamerica.com/location/sc', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Egyptian Theatre', 'egyptian-theatre', 'roadside-oddities', 41.93118, -88.75278, 'DeKalb', 'IL', 'A rare 1929 Egyptian Revival movie palace filled with scarabs, pharaoh motifs, hieroglyphic decoration, and an atmospheric auditorium.', 'limited', null, 'https://egyptiantheatre.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Eiffel Tower Park', 'eiffel-tower-park', 'roadside-oddities', 36.28678, -88.30011, 'Paris', 'TN', 'Paris, Tennessee answers its French namesake with a large Eiffel Tower replica rising over a city park. The intentionally literal landmark is classic small-city roadside branding and an easy photo stop.', 'open', null, 'https://www.paristn.gov/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Elsewhere Living Museum', 'elsewhere-living-museum', 'roadside-oddities', 36.06573, -79.79108, 'Greensboro', 'NC', 'A former three-story thrift store containing decades of accumulated merchandise was transformed into a living museum and artist residency where the old objects themselves become raw material for installations. Nothing about the building resembles a conventional gallery. Location: https://publicartgso.org/2018/06/12/elsewhere/', 'limited', null, 'https://www.elsewheremuseum.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Emily the Cow Statue', 'emily-the-cow-statue', 'roadside-oddities', 42.24294, -71.36948, 'Sherborn', 'MA', 'A bronze cow marks the grave of Emily, who escaped a slaughterhouse in 1995 and survived hidden in the woods for weeks before being rescued by the Peace Abbey. She became a local symbol of animal welfare, and the memorial preserves one of Massachusetts'' strangest animal-escape stories.', 'open', null, 'https://www.atlasobscura.com/places/emily-the-cow-statue-peace-abbey-sherborn-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Emperor Larry Bird', 'emperor-larry-bird', 'roadside-oddities', 38.5578, -86.62085, 'French Lick', 'IN', 'An outdoor bust of French Lick native Larry Bird depicts the basketball legend with the severe styling of an ancient Roman emperor. The sculpture stands outside the Springs Valley recreation-center area on Larry Bird Boulevard, making it an easy public tribute with a deliberately unusual visual twist.', 'open', null, 'https://www.roadsideamerica.com/tip/85109', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Empire Garden Restaurant', 'empire-garden-restaurant', 'roadside-oddities', 42.3515, -71.0628, 'Boston', 'MA', 'A cavernous Chinatown restaurant occupies the former Globe Theatre, leaving diners surrounded by balconies, ornate plasterwork and remnants of a grand performance hall while eating dim sum.', 'open', null, 'https://www.atlasobscura.com/places/empire-garden-restaurant', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Enchanted Forest at Clark''s Elioak Farm', 'enchanted-forest-at-clarks-elioak-farm', 'roadside-oddities', 39.23701, -76.87535, 'Ellicott City', 'MD', 'Maryland''s original Enchanted Forest storybook park opened in 1955 and eventually closed, but many of its giant fairy-tale structures were rescued and restored at Clark''s Elioak Farm. Visitors can now wander among pieces such as Cinderella''s pumpkin coach and the Old Woman''s Shoe during the farm''s seasonal operating dates.', 'limited', null, 'https://clarklandfarm.com/enchanted_forest.html', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Enishkeetompauog Narragansett — Whispering Giant', 'enishkeetompauog-narragansett-whispering-giant', 'roadside-oddities', 41.43363, -71.46615, 'Narragansett', 'RI', 'This approximately 20-foot wooden figure was carved by artist Peter Toth as part of his nationwide Whispering Giants series honoring Indigenous peoples. Installed in 1982, the sculpture is known as Enishkeetompauog Narragansett and stands in Sprague Park. Weathering has made the towering face even more striking over time.', 'open', null, 'https://www.southcountyri.com/blog/post/peter-toth-and-the-narragansett-whispering-giant/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.narragansettri.gov/Facilities/Facility/Details/Sprague-Park-16', null, null, null, 'America/New_York'),
  ('Epic Systems Campus', 'epic-systems-campus', 'roadside-oddities', 42.9964, -89.56854, 'Verona', 'WI', 'The software company''s enormous campus is filled with themed buildings, fantasy interiors, underground passages, giant sculptures and environments inspired by everything from storybooks to science fiction. Visitor access policies should be checked before going because it remains an active workplace.', 'limited', null, 'https://www.epic.com/visiting/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.epic.com/', null, null, null, 'America/Chicago'),
  ('Erik Rock — Rhode Island Troll Trail', 'erik-rock-rhode-island-troll-trail', 'roadside-oddities', 41.36747, -71.66166, 'Charlestown', 'RI', 'Erik Rock is one of five giant Rhode Island trolls built from reclaimed materials by Danish artist Thomas Dambo. Installed at Ninigret Park in 2024, Erik sits near Little Ninigret Pond and contains clues directing visitors toward companion troll Greta Granit. The sculpture is free to visit; climbing on the troll is discouraged.', 'open', null, 'https://www.southcountyri.com/thomas-dambo-trolls/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('E.T. Wickham Sculpture Trail', 'et-wickham-sculpture-trail', 'roadside-oddities', 36.4158, -87.4645, 'Palmyra', 'TN', 'Concrete statues and weathered figures created by E.T. Wickham line a rural landscape, forming one of Tennessee''s stranger outsider-art environments. Ownership and access conditions can change; stay on clearly permitted routes and respect posted property boundaries.', 'limited', null, 'https://www.atlasobscura.com/places/et-wickham-sculpture-trail', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Eternal Flame Falls', 'eternal-flame-falls', 'roadside-oddities', 42.70158, -78.75113, 'Orchard Park', 'NY', 'A natural gas seep burns inside a small grotto behind this waterfall in Chestnut Ridge Park, creating the strange sight of fire flickering through falling water. Reaching the flame requires a wooded hike and a walk along Shale Creek, and muddy or wet conditions are common.', 'limited', null, 'https://www3.erie.gov/parks/chestnut-ridge', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Exchange Place Staircase to Nowhere', 'exchange-place-staircase-to-nowhere', 'roadside-oddities', 42.35851, -71.05618, 'Boston', 'MA', 'An ornate nineteenth-century staircase survives inside a modern office tower even though the building it once served is gone. The preserved steps rise dramatically into contemporary space, looking like a grand staircase disconnected from its original world.', 'limited', null, 'https://www.atlasobscura.com/places/exchange-place-staircase-to-nowhere', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Exploration Tower', 'exploration-tower', 'roadside-oddities', 28.41193, -80.60892, 'Cape Canaveral', 'FL', 'Seven-story sail-shaped tower overlooking active launch complexes and the port.', 'roadside', null, 'https://www.portcanaveral.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Extreme Mount Washington', 'extreme-mount-washington', 'roadside-oddities', 44.27059, -71.30327, 'Sargent''s Purchase', 'NH', 'Inside the Sherman Adams Visitor Center at the summit of Mount Washington, this museum recreates the extreme weather that made the mountain famous. Exhibits cover the observatory, brutal wind, cold and the 231-mph gust measured here in 1934. Reaching the museum requires reaching the summit by hiking, the Auto Road or the Cog Railway, and seasonal mountain access can change rapidly.', 'limited', null, 'https://www.nhsgc.sr.unh.edu/about.html', '2026-09-09T04:49:39.808526+00:00', null, 'https://mountwashington.org/about-us/visit-us/', null, null, null, 'America/New_York'),
  ('Fabulous Paradise Point', 'fabulous-paradise-point', 'roadside-oddities', 36.84268, -86.07395, 'Scottsville', 'KY', 'Paradise Point is a deliberately eclectic roadside marketplace packed with brightly painted vehicles, handmade signs, unusual decor and an anything-goes mixture of food, art and local merchandise. Its constantly changing collection makes the stop feel more like a living folk-art environment than a conventional country store.', 'open', null, 'https://www.paradisepointky.com/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fairlee Drive-In Theater and Motel', 'fairlee-drive-in-theater-and-motel', 'roadside-oddities', 43.9225, -72.12611, 'Fairlee', 'VT', 'Fairlee combines a classic seasonal drive-in theater with an adjacent motel, preserving a kind of roadside entertainment landscape that has disappeared from most of the country. Guests and visitors can still experience movies on the outdoor screen during the operating season.', 'limited', null, 'https://fairleedrivein.com/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fairy Ring', 'fairy-ring', 'roadside-oddities', 35.2102, -80.86024, 'Charlotte', 'NC', 'More than one hundred glowing fiberglass mushrooms form a permanent artificial fairy ring in Charlotte’s South End. Each mushroom contains internal lighting, creating a small illuminated fantasy landscape after dark.', 'open', null, 'https://www.atlasobscura.com/places/fairy-ring-light', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fall Creek Falls State Park', 'fall-creek-falls-state-park', 'roadside-oddities', 35.65646, -85.35004, 'Spencer', 'TN', 'Deep gorges, caves, rock shelters and one of the tallest waterfalls in the eastern United States make this plateau landscape feel more geologically extreme than a standard state park. Stay on designated overlooks and trails around cliffs and sinkhole terrain.', 'open', null, 'https://tnstateparks.com/parks/fall-creek-falls', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Falling Waters State Park', 'falling-waters-state-park', 'roadside-oddities', 30.72934, -85.52883, 'Chipley', 'FL', 'Florida''s tallest waterfall drops into a deep cylindrical sinkhole.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/falling-waters-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Falls of the Ohio Fossil Beds', 'falls-of-the-ohio-fossil-beds', 'roadside-oddities', 38.2725, -85.7609, 'Clarksville', 'IN', 'When river conditions are low, enormous exposed limestone beds reveal fossils from a Devonian sea that covered the region roughly 390 million years ago. The state park protects one of the world''s largest exposed Devonian fossil beds and provides a visitor center overlooking the site.', 'open', null, 'https://www.in.gov/dnr/state-parks/parks-lakes/falls-of-the-ohio-state-park/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Fanning Springs State Park', 'fanning-springs-state-park', 'roadside-oddities', 29.5873, -82.93579, 'Fanning Springs', 'FL', 'Historic roadside spring and aquifer window along the Suwannee River.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/fanning-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fantasy Forest', 'fantasy-forest', 'roadside-oddities', 42.3359, -85.21406, 'Battle Creek', 'MI', 'After emerald ash borers killed many of the trees at Leila Arboretum, artists transformed the dead trunks into a strange outdoor forest of large carved creatures and figures. The project began in 2015 and now contains more than two dozen sculptures that can be explored on foot for free.', 'open', null, 'https://lasgarden.org/fantasy-forest/', '2026-09-08T15:12:49.285859+00:00', null, 'https://lasgarden.org/fantasy-forest/', null, null, null, 'America/Detroit'),
  ('Fantasy of Flight', 'fantasy-of-flight', 'roadside-oddities', 28.16765, -81.807, 'Polk City', 'FL', 'Eccentric aviation collection of historic aircraft presented by pilot and collector Kermit Weeks.', 'limited', null, 'https://www.fantasyofflight.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('F.A.S.T. Fiberglass Mold Graveyard', 'fast-fiberglass-mold-graveyard', 'roadside-oddities', 43.96874, -90.78208, 'Sparta', 'WI', 'Hundreds of weathered molds used to manufacture America''s giant fiberglass roadside figures are stored in an outdoor field at F.A.S.T. Fiberglass. Visitors can walk among molds for animals, characters, food and Muffler Men; the owners ask guests not to climb on them and to watch for insects.', 'open', null, 'https://www.fastfiberglass.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.fastfiberglass.com/', null, null, null, 'America/Chicago'),
  ('Fayetteville Eiffel Tower', 'fayetteville-eiffel-tower', 'roadside-oddities', 35.03029, -78.93064, 'Fayetteville', 'NC', 'An approximately 80-foot Eiffel Tower replica rises above the Bordeaux Center, a shopping complex whose French name inspired the landmark. Built in 1971 at roughly one-twelfth the height of the Paris original, it is one of Fayetteville’s most conspicuous pieces of roadside architecture.', 'roadside', null, 'https://www.roadsideamerica.com/tip/8512', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Field of Corn', 'field-of-corn', 'roadside-oddities', 40.08501, -83.12333, 'Dublin', 'OH', 'Field of Corn, also known as Cornhenge, consists of 109 human-sized concrete ears of corn arranged in rows in Frantz Park. The public artwork was commissioned in 1993 as a reference to the area''s agricultural history and remains free to walk around during park hours.', 'open', null, 'https://www.dublinarts.org/fieldofcorn', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fierce Encounter — Giant Bronze Bears', 'fierce-encounter-giant-bronze-bears', 'roadside-oddities', 41.9646, -83.6743, 'Dundee', 'MI', 'Two enormous bronze grizzly bears battle over an animal carcass outside the Dundee Cabela''s in a sculpture commonly promoted as one of the world''s largest bronze wildlife monuments. The roughly 24-foot composition is directly accessible around the store entrance as a free exterior photo stop.', 'open', null, 'https://www.waymarking.com/waymarks/wmEHRN_Dundee_Michigan_Worlds_Largest_Bronze_Wildlife_Sculpture', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Fifty-Foot Wooden Alligator', 'fifty-foot-wooden-alligator', 'roadside-oddities', 30.06561, -90.48411, 'LaPlace', 'LA', 'An enormous wooden alligator sculpture has long served as a roadside landmark on Belle Terre Boulevard. Treat it as a quick exterior photo stop and do not obstruct the surrounding business property.', 'roadside', null, 'https://www.roadsideamerica.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fighter Jet in Pennies', 'fighter-jet-in-pennies', 'roadside-oddities', 38.87275, -77.16028, 'Falls Church', 'VA', 'Artist Courtney Stevens Hengerer created "Pennies from Heaven" in 2008 by covering a miniature fiberglass F-14 jet with roughly 14,000 pennies as part of a public-art project. The sculpture was later moved to Falls Church and now sits in the open-air plaza between office buildings at Seven Corners.', 'open', null, 'https://www.roadsideamerica.com/tip/60805', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fighting Seabee Statue', 'fighting-seabee-statue', 'roadside-oddities', 41.60647, -71.44985, 'North Kingstown', 'RI', 'A muscular bronze Seabee carrying a rifle and heavy tools stands outside the Seabee Museum and Memorial Park near the former Quonset Point naval base. The figure reproduces the famous "Fighting Seabee" image associated with the U.S. Naval Construction Battalions. Check museum and grounds hours before visiting.', 'limited', null, 'https://www.seabeesmuseum.com/', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.seabeesmuseum.com/', null, null, null, 'America/New_York'),
  ('Finn’s Irish Pub — Historic Dining Car', 'finns-irish-pub-historic-dining-car', 'roadside-oddities', 44.54208, -68.42327, 'Ellsworth', 'ME', 'Hidden inside Finn’s is an original 1930s Jerry O’Mahony dining car, complete with its compact metal structure, counter, stools, and distinctive interior details. The modern restaurant was effectively built around the old diner, leaving a historic structure embedded inside another building.', 'open', null, 'https://www.atlasobscura.com/places/finns-irish-pub-jerry-omahony-dining-car', '2026-09-09T04:54:23.476824+00:00', null, 'https://www.finnsirishpub.com/', null, null, null, 'America/New_York'),
  ('Fire Hydrant Jack', 'fire-hydrant-jack', 'roadside-oddities', 44.37951, -73.22762, 'Shelburne', 'VT', 'A giant version of the children''s toy jack has been welded together from numerous retired fire hydrants beside Route 7. Artist Chris Sharp created the growing sculpture partly as a tribute to firefighters, turning familiar pieces of street infrastructure into an oversized roadside object.', 'roadside', null, 'https://www.atlasobscura.com/places/fire-hydrant-jack', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fish Ladder Park', 'fish-ladder-park', 'roadside-oddities', 42.97391, -85.67635, 'Grand Rapids', 'MI', 'Artist Joseph Kinnebrew designed this concrete structure as both public sculpture and a functioning fish ladder around a man-made obstacle in the Grand River. During migration periods, visitors can watch fish work their way through the brutalist-looking channels, making the site an unusual mix of infrastructure, ecology and art.', 'open', null, 'https://www.michigan.org/property/fish-ladder-park', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Five Elm Arches', 'five-elm-arches', 'roadside-oddities', 43.62362, -72.54845, 'Woodstock', 'VT', 'Artist Dan Ladd trained living elm trees into a sequence of architectural arches, using the trees themselves as a slowly changing sculptural material. Only part of the original work survives, but it remains visible at the Sculpturefest site in Woodstock.', 'limited', null, 'https://www.atlasobscura.com/places/five-elm-arches', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fleur-de-Lys Studio', 'fleur-de-lys-studio', 'roadside-oddities', 41.82771, -71.40862, 'Providence', 'RI', 'Built in 1885 for the Providence Art Club, this highly decorated half-timbered studio looks dramatically different from the surrounding Colonial-era buildings on Thomas Street. Carved figures, patterned panels and an asymmetrical façade give it the appearance of an illustrated storybook building dropped into College Hill.', 'roadside', null, 'https://www.atlasobscura.com/places/fleur-de-lys-studio', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('FLOAT House', 'float-house', 'roadside-oddities', 29.96875, -90.02152, 'New Orleans', 'LA', 'The FLOAT House was designed after Hurricane Katrina as a prototype home able to rise vertically during flooding. It remains a private residence, so OddWay visitors should view it only from the street.', 'roadside', null, 'https://www.makeitright.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Floating Bridge of Brookfield', 'floating-bridge-of-brookfield', 'roadside-oddities', 44.04263, -72.60478, 'Brookfield', 'VT', 'A bridge has floated across Sunset Lake at this location in several different forms since the nineteenth century because the deep lakebed made conventional supports difficult. The present structure preserves the unusual floating-crossing tradition while serving as a distinctive village landmark.', 'open', null, 'https://www.atlasobscura.com/places/floating-bridge-brookfield-vt', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Florence Y''all Water Tower', 'florence-yall-water-tower', 'roadside-oddities', 38.99773, -84.64785, 'Florence', 'KY', 'The famous tower originally advertised "Florence Mall," but highway regulations objected to using the structure as an advertisement before the mall had opened. Rather than repaint the entire tower, workers changed the M into a Y and added an apostrophe, creating the now-iconic "Florence Y''all."', 'roadside', null, 'https://www.atlasobscura.com/places/florence-y-all-water-tower', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Florida Caverns State Park', 'florida-caverns-state-park', 'roadside-oddities', 30.80699, -85.23217, 'Marianna', 'FL', 'Florida''s only state park with public guided tours through large dry limestone caves.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/florida-caverns-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Florida Citrus Tower', 'florida-citrus-tower', 'roadside-oddities', 28.56389, -81.74306, 'Clermont', 'FL', '1956 observation tower surviving from the era when citrus groves and roadside attractions defined Central Florida tourism.', 'roadside', null, 'https://citrustower.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Flying Horse Carousel', 'flying-horse-carousel', 'roadside-oddities', 41.30912, -71.85814, 'Watch Hill', 'RI', 'This nineteenth-century carousel uses horses suspended from chains instead of the up-and-down poles found on most carousels. As the ride spins, centrifugal force sends the wooden horses outward, creating the impression that they are flying. It is one of the oldest continuously operating carousels of its type and runs seasonally.', 'limited', null, 'https://www.atlasobscura.com/places/flying-horse-carousel', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Flying Monkey Sculptures', 'flying-monkey-sculptures', 'roadside-oddities', 44.47579, -73.21951, 'Burlington', 'VT', 'Winged monkey figures perch above Burlington''s former Union Station, a strange architectural reference to The Wizard of Oz. The sculptures are easily visible from public areas around the station and have become a small but unmistakable downtown oddity.', 'roadside', null, 'https://www.atlasobscura.com/places/flying-monkey-sculptures', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Flying Saucer by Jene Highstein', 'flying-saucer-university-park', 'roadside-oddities', 41.451633, -87.718737, 'University Park', 'IL', 'A 1977 sculpture by Jene Highstein: concrete over a steel frame, a dark oval sitting in the prairie grass like something that landed and settled. It is part of the permanent collection at Governors State University''s Nathan Manilow Sculpture Park, which is free, has free parking, and is open dawn to dusk every day of the year. Walk out to it — just don''t climb on it.', 'open', null, 'https://www.govst.edu/theNate', '2026-09-06T01:53:15.49385+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Foamhenge at Cox Farms', 'foamhenge-at-cox-farms', 'roadside-oddities', 38.88162, -77.4863, 'Centreville', 'VA', 'Artist Mark Cline built this full-size Stonehenge replica from giant Styrofoam blocks in 2004, and it later moved from Natural Bridge to Cox Farms. Foamhenge is on private property and is accessible only during designated Cox Farms seasons and hours, including Fall Festival and very limited shuttle access at other times.', 'limited', null, 'https://coxfarmsva.com/about/foamhenge/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fonthill Castle', 'fonthill-castle', 'roadside-oddities', 40.32113, -75.12293, 'Doylestown Township', 'PA', 'Henry Chapman Mercer built Fonthill between 1908 and 1912 as an experimental reinforced-concrete home filled with handmade tiles and architectural fragments. Guided tours wind through dozens of irregular rooms, stairways, terraces and alcoves in one of Pennsylvania''s strangest private homes turned museum.', 'open', null, 'https://www.mercermuseum.org/visit/fonthill-castle/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Food Gatherers'' Giant Carrots', 'food-gatherers-giant-carrots', 'roadside-oddities', 42.3178, -83.72719, 'Ann Arbor', 'MI', 'Six oversized concrete carrots stand outside the Food Gatherers warehouse at the appropriately named 1 Carrot Way. The sculptures turn the nonprofit food bank''s carrot logo into a large roadside landmark; visitors should keep the active warehouse driveway clear.', 'roadside', null, 'https://www.atlasobscura.com/places/food-gatherers-giant-carrots', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.foodgatherers.org/', null, null, null, 'America/Detroit'),
  ('Forbidden Caverns', 'forbidden-caverns', 'roadside-oddities', 35.9042, -83.34685, 'Sevierville', 'TN', 'Guided tours descend through a large cave system once associated with Eastern Woodland peoples and later moonshiners. Illuminated formations, underground streams and the cavern''s regional history give it a much stranger character than a typical scenic stop.', 'limited', null, 'https://www.forbiddencavern.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Forest Giants in a Giant Forest', 'forest-giants-in-a-giant-forest', 'roadside-oddities', 37.91765, -85.65708, 'Clermont', 'KY', 'Danish artist Thomas Dambo built three enormous troll-like figures from recycled wood inside Bernheim Forest in 2019. The giants are hidden along trails rather than clustered beside a parking lot, turning the search for the sculptures into part of the attraction.', 'open', null, 'https://bernheim.org/must-sees/forest-giants/', '2026-09-08T14:30:49.642487+00:00', null, 'https://bernheim.org/', null, null, null, 'America/New_York'),
  ('Fork in the Road', 'fork-in-the-road', 'roadside-oddities', 36.7898, -86.58908, 'Franklin', 'KY', 'A roughly 21-foot stainless-steel dinner fork rises from a literal fork in a rural Simpson County road. The deliberately obvious visual pun has become one of the county''s signature roadside-photo stops.', 'roadside', null, 'https://www.roadsideamerica.com/tip/64026', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Defiance Park', 'fort-defiance-park', 'roadside-oddities', 36.98524, -89.14487, 'Cairo', 'IL', 'At Illinois'' southern tip, visitors can stand where the muddy Mississippi and Ohio rivers visibly meet at a site once fortified during the Civil War.', 'open', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Fort Dobbs', 'fort-dobbs', 'roadside-oddities', 35.82164, -80.89737, 'Statesville', 'NC', 'Archaeology allowed historians to reconstruct North Carolina’s only preserved French and Indian War fort on its original site. Costumed interpretation and a full-scale fortified barracks recreate the frontier outpost that was attacked during the Anglo-Cherokee War. Official site: https://historicsites.nc.gov/all-sites/fort-dobbs', 'limited', null, 'https://www.atlasobscura.com/places/fort-dobbs', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fort Edgecomb', 'fort-edgecomb', 'roadside-oddities', 43.99361, -69.65722, 'Edgecomb', 'ME', 'Built in 1808–09 to defend the busy port of Wiscasset, Fort Edgecomb is dominated by an unusual two-story octagonal wooden blockhouse. The rare structure survives as a state historic site overlooking the Sheepscot River and is among Maine’s most distinctive early coastal defenses.', 'limited', null, 'https://www.maine.gov/mhpc/index.php/did-you-know/fort-edgecomb-c1808-edgecomb-lincoln-county', '2026-09-09T04:54:23.476824+00:00', null, 'https://www.maine.gov/fortedgecomb', null, null, null, 'America/New_York'),
  ('Fort McClary State Historic Site', 'fort-mcclary-state-historic-site', 'roadside-oddities', 43.08244, -70.71037, 'Kittery', 'ME', 'Fortifications have guarded this bluff above the Piscataqua River for centuries, although the site saw remarkably little actual combat. Surviving earthworks, granite structures, and the distinctive blockhouse create a layered military ruin spanning multiple periods of American history.', 'limited', null, 'https://www.atlasobscura.com/places/fort-mcclary-state-historic-site', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fortress of Faith — Greenback Castle', 'fortress-of-faith-greenback-castle', 'roadside-oddities', 35.66119, -84.17214, 'Greenback', 'TN', 'Floyd Banks spent decades constructing towers, walls, tunnels and religiously themed concrete forms by hand, creating a sprawling castle-like environment on private property. Access depends on the owner''s current rules; visitors should never assume unrestricted entry.', 'limited', null, 'https://spacesarchives.org/explore/search-the-online-collection/floyd-banks-fortress-of-faith/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Forty Acre Rock Heritage Preserve', 'forty-acre-rock-heritage-preserve', 'roadside-oddities', 34.66748, -80.52569, 'Kershaw', 'SC', 'Despite its name, the centerpiece is an exposed granite outcrop of roughly 14 acres rather than forty. Shallow pools on the almost lunar-looking stone support rare plants, while the preserve also contains trails, a waterfall, cave-like formations, and other granite exposures.', 'limited', null, 'https://www.sctrails.net/trails/trail/forty-acre-rock', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fountain of Time', 'fountain-of-time', 'roadside-oddities', 41.78675, -87.60775, 'Chicago', 'IL', 'A massive procession of 100 human figures marches past Father Time in one of the city''s strangest and most imposing public sculptures.', 'open', null, 'https://www.chicagoparkdistrict.com/parks-facilities/washington-fountain-time', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Francis Marion — Swamp Fox Statue', 'francis-marion-swamp-fox-statue', 'roadside-oddities', 33.81715, -79.4497, 'Johnsonville', 'SC', 'An unusual statue of Revolutionary War commander Francis Marion stands near Johnsonville, depicting the guerrilla leader remembered as the “Swamp Fox.” The figure’s stylized appearance makes the monument considerably stranger than the average military statue.', 'roadside', null, 'https://www.roadsideamerica.com/tip/38025', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frank and Buddy — Seeing Eye Dog Statue', 'frank-and-buddy-seeing-eye-dog-statue', 'roadside-oddities', 40.79762, -74.4815, 'Morristown', 'NJ', 'A bronze man and German shepherd commemorate Morris Frank and Buddy, whose partnership helped establish The Seeing Eye in Morristown and popularize guide dogs in the United States. The public sculpture captures Frank walking confidently with Buddy at his side.', 'open', null, 'https://www.roadsideamerica.com/location/map?mode=detail&id=48333', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frank Lloyd Wright Rosenbaum House', 'frank-lloyd-wright-rosenbaum-house', 'roadside-oddities', 34.79278, -87.68028, 'Florence', 'AL', 'Frank Lloyd Wright designed this Usonian house for the Rosenbaum family in 1939, integrating furniture, built-ins and low horizontal spaces into the plan. It is one of the few Wright houses in the Southeast open as a public museum.', 'limited', null, 'https://www.wrightinalabama.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Frank Sinatra in Bronze', 'frank-sinatra-in-bronze', 'roadside-oddities', 40.73718, -74.02641, 'Hoboken', 'NJ', 'A life-size bronze Frank Sinatra leans casually against a lamppost on the Hoboken waterfront, microphone in hand and overlooking Manhattan. The sculpture provides a second, visually distinct Sinatra stop separate from the marker at his birthplace.', 'open', null, 'https://www.roadsideamerica.com/location/map?mode=detail&id=83543', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frankenstein Cliff Trailhead', 'frankenstein-cliff-trailhead', 'roadside-oddities', 44.14781, -71.36781, 'Hart''s Location', 'NH', 'Frankenstein Cliff rises dramatically above Crawford Notch and is reached as part of a steep hiking loop near Arethusa Falls. Despite the horror-movie association the name suggests, the cliff honors nineteenth-century landscape painter Godfrey Frankenstein rather than Mary Shelley''s creature. The coordinate routes to the established trailhead rather than to the cliff face itself. Trail source: https://www.trailfinder.info/trails/trail/crawford-notch-state-park-frankenstein-cliff-loop', 'open', null, 'https://www.atlasobscura.com/places/frankenstein-cliff', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Free Expression Tunnel', 'free-expression-tunnel', 'roadside-oddities', 35.78548, -78.67174, 'Raleigh', 'NC', 'North Carolina State University’s pedestrian tunnel has been a legal graffiti wall since the 1960s. Layers of paint change constantly as students cover old messages with art, jokes, announcements, memorials, and political commentary.', 'open', null, 'https://www.atlasobscura.com/places/free-expression-tunnel-at-nc-state', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Freeport McDonald’s — The Gore House', 'freeport-mcdonalds-the-gore-house', 'roadside-oddities', 43.86032, -70.10167, 'Freeport', 'ME', 'Instead of a standard fast-food building, this McDonald’s occupies the historic mid-1800s Gore House near downtown Freeport. Local design restrictions helped preserve the mansion-like exterior, producing one of the chain’s strangest-looking locations.', 'open', null, 'https://www.atlasobscura.com/places/mcdonalds-freeport-mansion', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frisbee Dog Statue', 'frisbee-dog-statue', 'roadside-oddities', 44.00985, -73.17782, 'Middlebury', 'VT', 'A bronze dog catches a flying disc in a sculpture celebrating the Frisbee''s connection to Middlebury. The statue plays on the story that students helped popularize throwing pie tins and similar discs long before the modern plastic Frisbee became ubiquitous.', 'open', null, 'https://www.roadsideamerica.com/story/11914', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frog Rock', 'frog-rock', 'roadside-oddities', 42.93231, -71.72304, 'New Boston', 'NH', 'A massive split boulder in the woods resembles a crouching frog when viewed from the right angle. Frog Rock was once a well-known nineteenth-century scenic curiosity before changing roads and travel patterns left it comparatively obscure. The natural formation remains reachable on foot and makes a strong old-school roadside-oddity detour.', 'open', null, 'https://www.atlasobscura.com/places/frog-rock-new-hampshire', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frog Rock Roadside Park', 'frog-rock-roadside-park', 'roadside-oddities', 41.86899, -72.05202, 'Eastford', 'CT', 'A huge glacial boulder has been painted to resemble a frog since the nineteenth century. The surrounding roadside rest area has repeatedly faded, closed and revived over the years, but the green frog itself remains a beloved Route 44 landmark; services around it may be seasonal.', 'limited', null, 'https://www.roadsideamerica.com/tip/48905', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Frying Pan Tower', 'frying-pan-tower', 'roadside-oddities', 33.48333, -77.58333, 'Southport', 'NC', 'Far offshore from North Carolina, an old Coast Guard light station rises from the ocean like a rusting oil rig. The decommissioned platform has been privately restored and is not a casual roadside stop; visits require arranged boat, helicopter, or special access.', 'limited', null, 'https://www.atlasobscura.com/places/frying-pan-tower', '2026-09-09T05:34:33.398594+00:00', null, 'https://fptower.org/', null, null, null, 'America/New_York'),
  ('Fusion — Steel Workers and Fairies', 'fusion-steel-workers-and-fairies', 'roadside-oddities', 41.6025, -87.33743, 'Gary', 'IN', 'Artist Omri Amrany''s 2006 sculpture combines muscular steelworkers gathered around molten metal with winged dancers appearing to burst upward from the pour. The intentionally surreal mix of heavy industry and fantasy stands downtown beside the former convention-center area.', 'open', null, 'https://www.roadsideamerica.com/tip/42823', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Future Birthplace of Captain Kathryn Janeway', 'future-birthplace-of-captain-kathryn-janeway', 'roadside-oddities', 39.16589, -86.53617, 'Bloomington', 'IN', 'Star Trek: Voyager establishes Captain Kathryn Janeway as being born in Bloomington in the twenty-fourth century, giving the real city the unusual opportunity to commemorate a person who has not technically been born yet. A dedicated monument marks her "future birthplace" downtown and has become a pilgrimage stop for Star Trek fans.', 'open', null, 'https://janewaystatue.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://janewaystatue.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Futuro House', 'futuro-house', 'roadside-oddities', 39.08817, -84.52642, 'Covington', 'KY', 'One of architect Matti Suuronen''s rare surviving Futuro Houses sits in Covington looking like a small fiberglass flying saucer that has just landed among ordinary homes. The structure is privately owned, so OddWay visitors should view it only from the public street and sidewalk.', 'private', null, 'https://thefuturohouse.com/Futuro-Covington-Kentucky-USA.html', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Futuro House at the Pink Elephant', 'futuro-house-at-the-pink-elephant', 'roadside-oddities', 38.96123, -89.76331, 'Livingston', 'IL', 'A rare UFO-shaped Futuro house sits beside the Pink Elephant complex, creating one of Illinois'' strongest retro-futurist roadside sights.', 'roadside', null, 'https://www.pinkelephantantiquemall.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Futuro House — Eagle Crest Airport', 'futuro-house-eagle-crest-airport', 'roadside-oddities', 38.7734, -75.22844, 'Milton', 'DE', 'A rare 1960s Futuro House sits at the edge of the small Eagle Crest-Hudson Airport looking like a landed flying saucer. The fiberglass pod is architecture, not a UFO claim, and is on private property, so it should only be viewed from lawful public areas.', 'private', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gaffney Peachoid', 'gaffney-peachoid', 'roadside-oddities', 35.09527, -81.68588, 'Gaffney', 'SC', 'A 135-foot water tower painted as a gigantic peach looms beside Interstate 85, complete with leaf, stem, and a carefully modeled crease. The Peachoid honors the region’s peach industry and became nationally recognizable after appearing in House of Cards.', 'roadside', null, 'https://discoversouthcarolina.com/products/1470', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gaineswood', 'gaineswood', 'roadside-oddities', 32.50555, -87.83445, 'Demopolis', 'AL', 'Gaineswood grew over decades into an unusually elaborate Greek Revival mansion with domed ceilings, columned rooms and complex decorative details. The site also preserves the history of the enslaved laborers whose work supported the estate.', 'limited', null, 'https://ahc.alabama.gov/properties/gaineswood/gaineswood.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gallier House', 'gallier-house', 'roadside-oddities', 29.96172, -90.06132, 'New Orleans', 'LA', 'Architect James Gallier Jr. designed this 1857 townhouse with advanced-for-its-era indoor plumbing, ventilation and service spaces. Guided museum access reveals the technology hidden behind its formal French Quarter facade.', 'limited', null, 'https://hgghh.org/gallier-house/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Garden of the Gods', 'garden-of-the-gods', 'roadside-oddities', 37.60338, -88.38449, 'Herod', 'IL', 'Wind and erosion sculpted dramatic sandstone formations into strange profiles, overhangs, cliffs, and balanced-looking shapes above Shawnee National Forest.', 'open', null, 'https://www.fs.usda.gov/recarea/shawnee/recarea/?recid=10685', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Garnet Pool', 'garnet-pool', 'roadside-oddities', 44.30312, -71.22119, 'Greens', 'NH', 'Garnet Pool was once promoted as a scenic Victorian-era swimming hole near Mount Washington before fading from mainstream tourist maps. The secluded pool and surrounding rock formations survive without the formal infrastructure of a modern attraction. There is no clearly signed official trail, conditions can be slippery, and the source warns that common map directions can be wrong, so visitors should use caution and avoid treating it as a guaranteed swimming stop.', 'limited', null, 'https://www.atlasobscura.com/places/garnet-pools', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gates of the City — Portas da Cidade', 'gates-of-the-city-portas-da-cidade', 'roadside-oddities', 41.70055, -71.16583, 'Fall River', 'MA', 'A 60-foot replica of the famous city gates of Ponta Delgada in the Azores rises beside Fall River''s waterfront. The monument honors the city''s large Portuguese and Azorean community and looks startlingly monumental beside modern streets.', 'open', null, 'https://www.atlasobscura.com/places/gates-of-the-city-or-portas-da-cidade', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gator Chateau', 'gator-chateau', 'roadside-oddities', 30.24742, -92.66688, 'Jennings', 'LA', 'This city-supported visitor center houses rescued alligators and gives visitors a close, controlled look at Louisiana''s signature reptile. Admission policies and animal-contact rules can change, so follow staff instructions.', 'open', null, 'https://cityofjennings.com/gator-chateau/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gatorland', 'gatorland', 'roadside-oddities', 28.35525, -81.40278, 'Orlando', 'FL', 'Classic Old Florida attraction entered through a giant alligator mouth.', 'roadside', null, 'https://www.gatorland.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gaylordsville Spite House', 'gaylordsville-spite-house', 'roadside-oddities', 41.6478, -73.4829, 'New Milford', 'CT', 'This extraordinarily narrow house was constructed in a form local history has long connected with a property dispute, earning it the label of a spite house. It is a private residence, so the stop is strictly an exterior view from lawful public space.', 'private', null, 'https://www.atlasobscura.com/places/gaylordsville-spite-house', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('GE Chandelier', 'ge-chandelier', 'roadside-oddities', 41.50068, -81.68159, 'Cleveland', 'OH', 'Playhouse Square''s outdoor chandelier was installed in 2014 above East 14th Street and was promoted as the largest outdoor chandelier in North America. Thousands of crystals and LED lights hang above the theater district, and visitors can walk beneath it from the public sidewalk and plaza.', 'open', null, 'https://www.playhousesquare.org/news/detail/all-about-our-ge-chandelier', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gemini Giant', 'gemini-giant', 'roadside-oddities', 41.30622, -88.14968, 'Wilmington', 'IL', 'The iconic green-suited Muffler Man has been restored and moved to South Island Park, preserving one of Illinois Route 66''s defining roadside figures.', 'open', null, 'https://media.enjoyillinois.com/press-releases/illinois-gears-up-for-the-route-66-centennial-in-2026-with-exciting-new-attractions-experiences-and-events/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('General Laundry Cleaners and Dyers Building', 'general-laundry-cleaners-and-dyers-building', 'roadside-oddities', 29.9687, -90.08132, 'New Orleans', 'LA', 'This Art Deco industrial building is famous for a facade decorated with oversized soap bubbles and stylized laundry imagery. It is best treated as an exterior architectural photo stop.', 'roadside', null, 'https://www.nps.gov/nr/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Geographical Center of Michigan''s Lower Peninsula', 'geographical-center-of-michigans-lower-peninsula', 'roadside-oddities', 43.40822, -84.6053, 'Saint Louis', 'MI', 'A roadside monument near Saint Louis marks the calculated geographic center of Michigan''s mitten-shaped Lower Peninsula. The marker turns an otherwise anonymous rural point into a destination for travelers who want to stand, at least by one commonly used calculation, in the literal middle of the Mitten.', 'open', null, 'https://www.roadsideamerica.com/tip/77961', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('George Boedecker''s Sculpture Garden', 'george-boedeckers-sculpture-garden', 'roadside-oddities', 36.05698, -86.95677, 'Nashville', 'TN', 'An eccentric private landscape filled with oversized sculptures, repurposed objects and surreal forms sits along the outskirts of Nashville. Because it is private property, OddWay users should view only from lawful public areas unless explicit access is offered.', 'roadside', null, 'https://www.atlasobscura.com/places/george-boedeckers-sculpture-garden', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('George Washington''s Bathtub', 'george-washingtons-bathtub', 'roadside-oddities', 39.62556, -78.22694, 'Berkeley Springs', 'WV', 'A small stone-lined outdoor bath in Berkeley Springs State Park marks the tradition of George Washington bathing in the warm mineral springs here during the 18th century. The present structure is a reconstruction rather than Washington''s literal surviving bathtub, but it has become one of the state''s most photographed historical oddities.', 'open', null, 'https://washingtonheritagetrail.com/morgan-county/george-washingtons-bathtub/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('German Cuckoo Clock Tower', 'german-cuckoo-clock-tower', 'roadside-oddities', 39.30055, -85.22232, 'Batesville', 'IN', 'Completed in 2021, this downtown clock tower plays with Batesville''s German heritage through two carved, lederhosen-clad woodsmen who mechanically saw a log every hour. Despite the cuckoo-clock appearance, the moving woodsmen rather than a bird are the centerpiece.', 'open', null, 'https://www.roadsideamerica.com/tip/75247', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Giant Ball Sculpture', 'giant-ball', 'roadside-oddities', 34.154524, -118.281061, 'Glendale', 'CA', 'This OpenStreetMap-mapped outdoor artwork is a large ball sculpture near the Ferraro Soccer Fields and the Glendale/Los Angeles boundary. I could not find a reliable published artist, official title or construction date, so the safest description is simply a public-facing oversized sculpture that travelers can view as a quick roadside curiosity.', 'roadside', null, 'https://mapcarta.com/N6862517420', null, null, null, null, null, null, 'America/Los_Angeles'),
  ('Giant Chicken', 'giant-chicken', 'roadside-oddities', 39.28054, -86.75718, 'Spencer', 'IN', 'This oversized white chicken once advertised a local drive-in restaurant and became familiar enough that residents objected when redevelopment threatened it. The community rescued the fiberglass bird and moved it to the entrance of the Owen County Fairgrounds, where it still stands at East and Cooper streets.', 'open', null, 'https://www.roadsideamerica.com/tip/476', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Giant Coke Bottle', 'giant-coke-bottle', 'roadside-oddities', 38.76525, -87.42074, 'Bruceville', 'IN', 'Built in 1949 for an Indianapolis Coca-Cola plant, this huge bottle eventually ended up on a trailer outside a private home in Bruceville. It has occasionally appeared in parades, but travelers should photograph the bottle only from the public road unless the property owner explicitly invites closer access.', 'private', null, 'https://www.roadsideamerica.com/tip/15522', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('Giant Cootie', 'giant-cootie', 'roadside-oddities', 38.71444, -78.66767, 'Shenandoah Caverns', 'VA', 'This enormous version of the classic Cootie toy began life as a parade float and was later retired to the Shenandoah Caverns complex. The colorful bug now sits outside near American Celebration on Parade, where it can be seen as a roadside curiosity even when the neighboring museum is closed.', 'roadside', null, 'https://www.roadsideamerica.com/tip/68787', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Cow Head', 'giant-cow-head', 'roadside-oddities', 42.38504, -82.96106, 'Detroit', 'MI', 'An enormous cow head still watches over Mack Avenue from the roof of a former dairy and ice-cream building. The oversized relic of roadside advertising survived long after the original business disappeared and can be viewed from surrounding public streets.', 'roadside', null, 'https://www.atlasobscura.com/places/giant-cow-head', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Giant Crash Test Dummy', 'giant-crash-test-dummy', 'roadside-oddities', 39.19661, -76.60995, 'Glen Burnie', 'MD', 'A 34-foot-tall yellow crash-test dummy stands outside Maryland Motor Vehicle Administration headquarters as an oversized traffic-safety mascot. Installed in 2012, it is a permanent outdoor photo stop visible from the public MVA complex.', 'roadside', null, 'https://www.roadsideamerica.com/tip/36232', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Fishing Lure', 'giant-fishing-lure', 'roadside-oddities', 38.26812, -85.74804, 'Jeffersonville', 'IN', 'An enormous fishing lure hangs over the Ohio River outside Upland Brewing''s Jeffersonville location. Installed as public art in 2021, the shiny oversized tackle turns the riverfront setting into a literal visual joke about fishing.', 'open', null, 'https://www.roadsideamerica.com/tip/84706', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Giant Fork in the Road', 'giant-fork-in-the-road', 'roadside-oddities', 38.70015, -90.15185, 'Granite City', 'IL', 'A giant dining fork planted at a literal fork in the road turned a downtown intersection into a deliberately corny Route 66 photo stop.', 'open', null, 'https://www.riversandroutes.com/blog/giants-of-granite-city/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Giant Hood Ornament', 'giant-hood-ornament', 'roadside-oddities', 39.92798, -86.0909, 'Carmel', 'IN', 'Unveiled in 2024, this giant Art Deco winged hood ornament rises from the roundabout at 96th Street and Gray Road as a tribute to Indiana''s historic Stutz automobile company. It is one of several automotive-themed roundabout sculptures in the area, but its enormous transparent form makes it the standout.', 'roadside', null, 'https://www.roadsideamerica.com/tip/85807', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Giant Legs of Ricky Pearce', 'giant-legs-of-ricky-pearce', 'roadside-oddities', 36.30071, -78.39951, 'Henderson', 'NC', 'A pair of enormous human legs stands upright beside a rural property, with no torso attached and little context for passing drivers. Artist Ricky Pearce created the surreal roadside sculpture, which looks like a giant has disappeared into the ground.', 'roadside', null, 'https://www.roadsideamerica.com/story/19708', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant L.L.Bean Boot', 'giant-llbean-boot', 'roadside-oddities', 43.85788, -70.10389, 'Freeport', 'ME', 'A huge version of L.L.Bean’s signature Maine Hunting Shoe stands outside the company’s flagship complex in Freeport. It is a simple but iconic oversized-object stop that works well as a quick route detour.', 'roadside', null, 'https://fotospot.com/attractions/maine/giant-ll-bean-boot', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Maple Syrup Jug at Dakin Farm', 'giant-maple-syrup-jug-at-dakin-farm', 'roadside-oddities', 44.24348, -73.2304, 'Ferrisburgh', 'VT', 'An oversized maple-syrup jug advertises Dakin Farm along Route 7, turning Vermont''s best-known food product into literal roadside architecture. It is a quick exterior photo stop attached to an active Vermont specialty-food business.', 'roadside', null, 'https://www.roadsideamerica.com/tip/39047', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Mermaid and Lighthouse Souvenir Building', 'giant-mermaid-and-lighthouse-souvenir-building', 'roadside-oddities', 28.33119, -81.58505, 'Kissimmee', 'FL', 'Souvenir-store facade dominated by a huge sculpted mermaid and fake lighthouse.', 'limited', null, 'https://www.roadsideamerica.com/tip/43768', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Needle and Thread', 'giant-needle-and-thread', 'roadside-oddities', 37.08617, -88.60372, 'Paducah', 'KY', 'Artist Michael Terra created a 22-foot chrome-plated needle with a bright red thread extending dozens of feet through the ground. Formally titled E Pluribus Unum, the sculpture celebrates Paducah''s internationally known quilting culture with an appropriately enormous sewing tool. Address: 533 N. 5th St., Paducah, KY', 'open', null, 'https://www.roadsideamerica.com/tip/82097', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Giant Popcorn Box', 'giant-popcorn-box', 'roadside-oddities', 38.4006, -86.93185, 'Jasper', 'IN', 'A roughly 17-foot popcorn carton rises outside the business at 1522 Newton Street, complete with oversized kernels spilling from the top. Built to advertise a popcorn shop known for dozens of flavors, the sculpture remains an unmistakable roadside landmark on US 231.', 'roadside', null, 'https://www.roadsideamerica.com/tip/46315', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('Giant Quarter', 'giant-quarter', 'roadside-oddities', 40.01599, -78.36026, 'Everett', 'PA', 'Students at Bedford County Technical Center built this roughly 20-foot-wide quarter as a tribute to George Washington''s connections to Bedford County. The nearly one-ton coin stands near Down River Golf Course and makes an easy oversized-object photo stop from the public-facing area.', 'roadside', null, 'https://www.atlasobscura.com/places/giant-quarter-everett-pennsylvania', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Santa', 'giant-santa', 'roadside-oddities', 38.08585, -87.55695, 'Evansville', 'IN', 'Built in 1974, this approximately 35-foot Santa spent years moving between displays, a truck stop and even a junkyard before supporters restored it in 2016. It now stands upright again beside US 41, with a walkway and parking specifically allowing travelers to stop for photos.', 'open', null, 'https://www.roadsideamerica.com/story/11853', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Giant Shark Entrance', 'giant-shark-entrance', 'roadside-oddities', 34.52658, -77.43444, 'Sneads Ferry', 'NC', 'Shark Attack Souvenirs requires shoppers to walk directly through the open mouth of a huge fiberglass shark. The giant jaws remain one of the most blatant and effective examples of coastal roadside architecture in the state. Current location: https://nextdoor.com/pages/shark-attack-souvenir-gift-shop-sneads-ferry-nc/', 'open', null, 'https://www.roadsideamerica.com/tip/30533', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Speared Sturgeon — George W. Brown Jr. Ojibwe Museum', 'giant-speared-sturgeon-george-w-brown-jr-ojibwe-museum', 'roadside-oddities', 45.96941, -89.89262, 'Lac du Flambeau', 'WI', 'A giant speared sturgeon sculpture outside the museum connects immediately to the Lac du Flambeau community''s fishing traditions. Inside, exhibits interpret Ojibwe history and culture, giving the oversized fish a much richer context than a stand-alone roadside statue.', 'open', null, 'https://www.roadsideamerica.com/tip/10426', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.lacduflambeau.com/', null, null, null, 'America/Chicago'),
  ('Giant Statues of Vulcan and Venus', 'giant-statues-of-vulcan-and-venus', 'roadside-oddities', 38.4819, -82.6395, 'Ashland', 'KY', 'Two roughly 30-foot bronze figures of the Roman deities Vulcan and Venus stand along the Ohio River beside an even taller abstract sculpture called Genesis. Installed at Riverfront Park in 2019, the enormous figures turn Ashland''s public riverfront into a surprisingly monumental art stop.', 'open', null, 'https://www.roadsideamerica.com/tip/67669', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Stick of Butter', 'giant-stick-of-butter', 'roadside-oddities', 44.14445, -72.8432, 'Warren', 'VT', 'An old shipping container at Cloud Water Farm has been painted into an enormous yellow stick of butter. Created as a playful celebration of food and farm culture, it became an instant Route 100 roadside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/89492', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Giant Stormy Kromer Cap', 'giant-stormy-kromer-cap', 'roadside-oddities', 46.4616, -90.14394, 'Ironwood', 'MI', 'Stormy Kromer''s famous wool cap is manufactured in Ironwood, and an enormous version of it sits outside the factory on Wall Street. The giant cap can be viewed anytime, while the factory store and scheduled tours provide a closer look at the century-old Michigan clothing brand.', 'open', null, 'https://www.atlasobscura.com/places/stormy-kromer-cap-factory', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.stormykromer.com/', null, null, null, 'America/Menominee'),
  ('Giant’s Causeway Pillar', 'giants-causeway-pillar', 'roadside-oddities', 32.77744, -79.93128, 'Charleston', 'SC', 'A genuine basalt column removed from Northern Ireland’s Giant’s Causeway stands thousands of miles away in Charleston. The strange transplanted piece of geology gives visitors a small physical fragment of one of Europe’s most famous natural formations.', 'limited', null, 'https://www.atlasobscura.com/places/giants-causeway-pillar-section', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gibraltar Rock State Natural Area', 'gibraltar-rock-state-natural-area', 'roadside-oddities', 43.3431, -89.60032, 'Lodi', 'WI', 'A flat-topped sandstone bluff rises hundreds of feet above the surrounding countryside. Trails climb through forest to dramatic cliff views, creating a geological landmark that looks far more mountainous than its southern Wisconsin setting.', 'open', null, 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=73', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/', null, null, null, 'America/Chicago'),
  ('Gift from Brazil to Brazil', 'gift-from-brazil-to-brazil', 'roadside-oddities', 39.50105, -87.12428, 'Brazil', 'IN', 'In the 1950s, the nation of Brazil gave its Indiana namesake a massive granite reproduction of the Chafariz de São José fountain as a gesture of friendship. The roughly 40-foot-wide monument still stands near Nabuca Drive, although the fountain itself is generally dry.', 'open', null, 'https://www.roadsideamerica.com/tip/69438', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Gillette Castle State Park', 'gillette-castle-state-park', 'roadside-oddities', 41.423, -72.4284, 'East Haddam', 'CT', 'Actor William Gillette, famous for portraying Sherlock Holmes, built this eccentric stone castle above the Connecticut River with secret doors, custom wooden locks, unusual built-in furniture and an estate railroad. The grounds are broadly accessible while interior castle tours are seasonal.', 'limited', null, 'https://www.atlasobscura.com/places/gillette-castle-state-park', '2026-09-08T18:39:47.144889+00:00', null, 'https://ctparks.com/parks/gillette-castle-state-park', null, null, null, 'America/New_York'),
  ('Gingerbread Castle', 'gingerbread-castle', 'roadside-oddities', 41.14939, -74.57478, 'Hamburg', 'NJ', 'This elaborate fairy-tale castle was built in the 1920s as part of a children''s attraction associated with a local flour mill. Its towers, figures and storybook details survive, but public access has changed repeatedly; travelers should treat it as an exterior roadside landmark unless an official opening is advertised.', 'roadside', null, 'https://www.atlasobscura.com/places/gingerbread-castle', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('''Glove Cycle''', 'glove-cycle', 'roadside-oddities', 42.3884, -71.1191, 'Cambridge', 'MA', 'Dozens of bronze gloves are scattered through Porter Square station as if lost by generations of commuters. The installation turns one of the most commonly misplaced winter objects in New England into a permanent underground art cycle.', 'open', null, 'https://www.atlasobscura.com/places/glove-cycle', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('God''s Ark of Safety', 'gods-ark-of-safety', 'roadside-oddities', 39.63428, -78.92898, 'Frostburg', 'MD', 'A church congregation began planning a full-scale Noah''s Ark beside Interstate 68 after its pastor said he received a divine command to build it in 1976. The enormous steel skeleton remains an unfinished landmark decades later; view it from legitimate public roadside areas and do not enter the construction property without permission.', 'roadside', null, 'https://www.atlasobscura.com/places/gods-ark-of-safety', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gozzi''s Colorful Turkeys', 'gozzis-colorful-turkeys', 'roadside-oddities', 41.30931, -72.72274, 'Guilford', 'CT', 'Each holiday season, Gozzi''s Turkey Farm displays live turkeys whose feathers are dyed vivid colors including pink, purple and green. The tradition has become a peculiar local Thanksgiving and Christmas-season ritual rather than a normal farm visit.', 'limited', null, 'https://www.roadsideamerica.com/tip/14180', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graffiti Alley', 'graffiti-alley', 'roadside-oddities', 39.31153, -76.61881, 'Baltimore', 'MD', 'This alley behind Baltimore''s Motor House is one of the city''s best-known legal graffiti spaces, with nearly every wall and surface repeatedly covered by new layers of paint. Because the artwork constantly changes, repeat travelers may find an almost entirely different alley from one visit to the next.', 'open', null, 'https://www.atlasobscura.com/places/graffiti-alley', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graffiti Alley', 'graffiti-alley-ann-arbor', 'roadside-oddities', 42.27945, -83.74442, 'Ann Arbor', 'MI', 'A narrow downtown passage off East Liberty Street has evolved into an ever-changing public graffiti environment. Layers of tags, murals, stickers and new paintings regularly cover earlier work, making the alley look different from one visit to the next.', 'open', null, 'https://www.atlasobscura.com/places/graffiti-alley-ann-arbor', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Grahamland Attractions', 'grahamland-attractions', 'roadside-oddities', 34.31711, -78.24314, 'Bolton', 'NC', 'A sprawling private folk-art environment contains hundreds of fiberglass animals, cartoon figures, giant characters, statues, and repurposed roadside objects. The collection feels like pieces of several extinct amusement parks gathered into one rural property.', 'limited', null, 'https://www.atlasobscura.com/places/grahamland-attractions-north-carolina', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grand Haven Musical Fountain', 'grand-haven-musical-fountain', 'roadside-oddities', 43.06603, -86.23782, 'Grand Haven', 'MI', 'Operating since 1962, this enormous synchronized fountain sends water more than 100 feet into the air while lights and music are choreographed to the jets. Free shows run on seasonal evenings, so the installation is a legitimate stop only when the fountain''s current show calendar is active.', 'limited', null, 'https://www.ghfountain.org/', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Grand Kugel', 'grand-kugel', 'roadside-oddities', 37.56064, -77.46627, 'Richmond', 'VA', 'The Grand Kugel outside the Science Museum of Virginia is a roughly 29-ton granite globe that appears to float and rotate on an extremely thin layer of pressurized water. The current globe replaced an earlier damaged version, and visitors can still push the enormous stone sphere by hand when the fountain system is operating.', 'open', null, 'https://www.atlasobscura.com/places/the-grand-kugel-richmond-virginia', '2026-09-08T04:17:48.352537+00:00', null, 'https://smv.org/', null, null, null, 'America/New_York'),
  ('Grave Digger’s Dungeon', 'grave-diggers-dungeon', 'roadside-oddities', 36.28542, -75.9198, 'Poplar Branch', 'NC', 'The home base of the Grave Digger monster truck has become a roadside attraction filled with retired trucks, memorabilia, displays, animals, and other motorsports oddities. Current operations also include monster-truck ride experiences on selected days.', 'open', null, 'https://www.diggersdungeon.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graveyard of the Atlantic Museum', 'graveyard-of-the-atlantic-museum', 'roadside-oddities', 35.20635, -75.70406, 'Hatteras', 'NC', 'This museum is dedicated to the thousands of shipwrecks, storms, wars, rescues, pirates, and maritime disasters associated with the dangerous waters off the Outer Banks. Its location near Hatteras Inlet puts it directly beside the landscape that earned the region the name “Graveyard of the Atlantic.”', 'limited', null, 'https://graveyardoftheatlantic.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravity Research Foundation Anti-Gravity Monument', 'gravity-research-foundation-anti-gravity-monument', 'roadside-oddities', 42.4069, -71.11915, 'Medford', 'MA', 'A monument at Tufts University recalls eccentric businessman Roger Babson''s Gravity Research Foundation, established partly from his desire to understand — and potentially defeat — gravity. Babson funded anti-gravity research monuments on college campuses across the country after blaming gravity for a family drowning.', 'open', null, 'https://www.hmdb.org/m.asp?m=108006', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Graylyn Estate', 'graylyn-estate', 'roadside-oddities', 36.11807, -80.28332, 'Winston-Salem', 'NC', 'This sprawling 1930s estate looks more like a transplanted European manor than a North Carolina mansion. Its 60-room design mixes medieval and Renaissance influences with extravagant details including marble tubs, gold fixtures, numerous radios, and showers originally fitted with 17 heads. Current tours: https://www.visitwinstonsalem.com/event/tour-pour-du-jour-graylyn-estate-1', 'limited', null, 'https://www.atlasobscura.com/places/graylyn', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Great Brook Farm Robotic Milking Barn', 'great-brook-farm-robotic-milking-barn', 'roadside-oddities', 42.55583, -71.35333, 'Carlisle', 'MA', 'At a working dairy farm inside Great Brook Farm State Park, cows can use an automated robotic milking system largely on their own schedule. Visitors can see modern dairy technology operating inside a historic New England farm landscape; barn access and demonstrations vary by season and program.', 'limited', null, 'https://www.mass.gov/locations/great-brook-farm-state-park', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.mass.gov/locations/great-brook-farm-state-park', null, null, null, 'America/New_York'),
  ('Great Scott Moon Rock', 'great-scott-moon-rock', 'roadside-oddities', 41.76469, -72.66945, 'Hartford', 'CT', 'The Connecticut Science Center displays a genuine lunar sample associated with Apollo astronaut David Scott. It is a small object with an enormous backstory: a physical piece of the Moon sitting in downtown Hartford.', 'open', null, 'https://www.atlasobscura.com/places/great-scott-moon-rock', '2026-09-08T18:47:23.721893+00:00', null, 'https://ctsciencecenter.org/', null, null, null, 'America/New_York'),
  ('Great Stalacpipe Organ at Luray Caverns', 'great-stalacpipe-organ-at-luray-caverns', 'roadside-oddities', 38.66407, -78.48383, 'Luray', 'VA', 'The Great Stalacpipe Organ is a working musical instrument that uses rubber-tipped strikers to play carefully selected stalactites spread through Luray Caverns. Built in the 1950s, it turns the cave itself into the instrument and can be heard as part of the normal cavern tour.', 'open', null, 'https://luraycaverns.com/discover/caverns/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Great Vermont Corn Maze', 'great-vermont-corn-maze', 'roadside-oddities', 44.49905, -72.09134, 'Danville', 'VT', 'Each season, this farm builds an enormous multi-acre corn maze intended to take visitors hours rather than minutes to solve. The attraction changes annually and has also featured smaller mazes and nighttime or blacklight experiences.', 'limited', null, 'https://www.vermontcornmaze.com/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greek Revival Folk Art Chicken Coop', 'greek-revival-folk-art-chicken-coop', 'roadside-oddities', 34.88295, -82.42159, 'Greenville', 'SC', 'Behind an antique shop and artist studios sits a chicken coop built to resemble a miniature Southern Greek Revival mansion. Look closely and the formal architecture turns into folk art: golf clubs, alphabet blocks, toy cars, seashells and other found objects are worked into the structure. Because the coop is in the back garden of an operating shop/studio property, visit only during business hours and respect any access restrictions.', 'limited', null, 'https://www.atlasobscura.com/places/greek-revival-folk-art-chicken-coop', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Green Animals Topiary Garden', 'green-animals-topiary-garden', 'roadside-oddities', 41.6055, -71.2707, 'Portsmouth', 'RI', 'Dozens of shrubs have been clipped into oversized animals and geometric forms across this historic estate, including bears, birds, a camel and a giraffe. The collection dates back more than a century and is considered the oldest topiary garden in the United States. Admission and operating dates follow the Preservation Society''s seasonal schedule.', 'limited', null, 'https://www.atlasobscura.com/places/green-animals-topiary-garden', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.newportmansions.org/mansions-and-gardens/green-animals-topiary-garden/', null, null, null, 'America/New_York'),
  ('Green Bank Telescope', 'green-bank-telescope', 'roadside-oddities', 38.43312, -79.83984, 'Green Bank', 'WV', 'The Robert C. Byrd Green Bank Telescope is one of the largest fully steerable radio telescopes on Earth and dominates the landscape inside the National Radio Quiet Zone. Visitors can explore Green Bank Observatory through its science center and public programs, although access immediately around the telescope itself is controlled rather than a casual walk-up.', 'open', null, 'https://greenbankobservatory.org/portal/gbt/instruments/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greeneville Cumberland Presbyterian Church Cannonball', 'greeneville-cumberland-presbyterian-church-cannonball', 'roadside-oddities', 36.16501, -82.83021, 'Greeneville', 'TN', 'A Civil War cannonball remains embedded in the exterior of this Greeneville church, turning battle damage into a permanent architectural artifact. It is a tiny but unusually direct physical remnant of wartime violence in the middle of town.', 'open', null, 'https://www.atlasobscura.com/places/greeneville-cumberland-presbyterian-church', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Greta Granit — Rhode Island Troll Trail', 'greta-granit-rhode-island-troll-trail', 'roadside-oddities', 41.37199, -71.66117, 'Charlestown', 'RI', 'Greta Granit crouches in the woods of Ninigret Park at the end of a marked search from fellow troll Erik Rock. Built with community volunteers and recycled wood, she is distinguished by a long bamboo ponytail. Greta and Erik are separate permanent installations and each functions as its own routable stop.', 'open', null, 'https://www.southcountyri.com/thomas-dambo-trolls/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Griffis Sculpture Park', 'griffis-sculpture-park', 'roadside-oddities', 42.36938, -78.69151, 'East Otto', 'NY', 'More than 250 large-scale sculptures are scattered through fields, forests and ponds across one of the oldest outdoor sculpture parks in the country. The main Mill Valley Road section is generally open from May through October and involves walking trails over varied terrain.', 'limited', null, 'https://griffissculpturepark.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grimshawes Post Office', 'grimshawes-post-office', 'roadside-oddities', 35.0664, -83.1199, 'Cashiers', 'NC', 'This tiny wooden post-office building measures only about five by six feet and is commonly described as the smallest historic post office in the United States. Its miniature scale makes it look more like a shed or playhouse than functioning postal architecture.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/north-carolina/places?page=5', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grounds For Sculpture', 'grounds-for-sculpture', 'roadside-oddities', 40.23679, -74.71889, 'Hamilton Township', 'NJ', 'Hundreds of large-scale sculptures are scattered through landscaped gardens, ponds and wooded paths at this 42-acre art park. Some installations recreate famous paintings as life-size three-dimensional scenes, producing deliberately surreal encounters around the grounds.', 'limited', null, 'https://www.groundsforsculpture.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Guardians of the Seeds Trolls', 'guardians-of-the-seeds-trolls', 'roadside-oddities', 43.8736, -69.66072, 'Boothbay', 'ME', 'Five enormous wooden trolls created by artist Thomas Dambo are hidden along trails at Coastal Maine Botanical Gardens. The sculptures form the “Guardians of the Seeds” installation and turn a garden hike into a giant-creature scavenger hunt.', 'limited', null, 'https://www.mainegardens.org/classes-and-events/hike-the-trolls/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gulf Hagas', 'gulf-hagas', 'roadside-oddities', 45.49628, -69.35773, 'Bowdoin College Grant East Township', 'ME', 'Nicknamed the “Grand Canyon of Maine,” Gulf Hagas is a remote slate gorge filled with waterfalls, narrow rock walls, old-growth forest, and dramatic drops along the West Branch of the Pleasant River. Reaching the best features requires a substantial wilderness hike with no reliable cell service.', 'limited', null, 'https://www.atlasobscura.com/places/maine-gulf-hagas', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gun Totem', 'gun-totem', 'roadside-oddities', 41.82512, -71.40759, 'Providence', 'RI', 'Artist Boris Bally built this roughly 3,500-pound obelisk from more than 1,000 firearms surrendered during a gun buyback. The weapons were crushed and welded into a towering public sculpture outside Providence''s federal courthouse. From a distance it resembles a dark stone monument; up close the individual gun parts become visible.', 'open', null, 'https://www.atlasobscura.com/places/gun-totem', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gunnar Schonbeck Exhibit', 'gunnar-schonbeck-exhibit', 'roadside-oddities', 42.70187, -73.11519, 'North Adams', 'MA', 'More than 200 wildly unconventional instruments at MASS MoCA include a nine-foot banjo, aircraft-fuselage drums and giant sound towers. Visitors are encouraged to play many of them, fulfilling artist Gunnar Schonbeck''s belief that everyone can make music.', 'limited', null, 'https://www.atlasobscura.com/places/no-experience-required', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hachi and Professor Ueno Statue', 'hachi-and-professor-ueno-statue', 'roadside-oddities', 41.09115, -74.7106, 'Lafayette Township', 'NJ', 'A life-size bronze replica shows the famously loyal Japanese Akita Hachiko joyfully reunited with Professor Hidesaburo Ueno. Installed at Abbey Glen Pet Memorial Park in 2016, it reproduces the paired statue created for the University of Tokyo.', 'open', null, 'https://www.roadsideamerica.com/story/55089', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haddy the Hadrosaurus', 'haddy-the-hadrosaurus', 'roadside-oddities', 39.89706, -75.03437, 'Haddonfield', 'NJ', 'A life-size bronze Hadrosaurus foulkii stands downtown in honor of the dinosaur discovered nearby in 1858. Nicknamed Haddy, the sculpture gives Haddonfield a visible prehistoric mascot linked to one of the most important early dinosaur discoveries in North America.', 'open', null, 'https://www.atlasobscura.com/places/haddy-the-hadrosaurus', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haines Shoe House', 'haines-shoe-house', 'roadside-oddities', 39.99899, -76.63714, 'Hellam Township', 'PA', 'Shoe magnate Mahlon Haines built this five-level work-boot-shaped house in 1948–49 as an enormous advertisement and promotional guesthouse for his shoe business. It is now a short-term rental rather than a public museum: **only registered guests may enter**, although the owners explicitly welcome photographs from the public roadside.', 'private', null, 'https://www.hainesshoehouse.com/history', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Half-Buried Cars and Dinosaurs', 'half-buried-cars-and-dinosaurs', 'roadside-oddities', 40.08764, -85.69818, 'Anderson', 'IN', 'Outside an Anderson collision shop, automobiles appear to dive nose-first into the ground alongside large dinosaur figures and other automotive art. The display sits at an active business at 1400 W. 29th Street, so it is best visited during normal business access rather than after the gates are closed.', 'limited', null, 'https://www.roadsideamerica.com/location/in/all', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Hammond Castle Museum', 'hammond-castle-museum', 'roadside-oddities', 42.58521, -70.69276, 'Gloucester', 'MA', 'Inventor John Hays Hammond Jr. built a medieval-style seaside castle as his home, laboratory and showcase for antiquities. The eccentric structure mixes genuine old architectural fragments with twentieth-century technology, and current programming even explores Hammond''s experiments involving parapsychology and Spiritualism.', 'limited', null, 'https://hammondcastle.org/', '2026-09-09T04:43:56.902716+00:00', null, 'https://hammondcastle.org/', null, null, null, 'America/New_York'),
  ('Hamtramck Disneyland', 'hamtramck-disneyland', 'roadside-oddities', 42.40722, -83.05862, 'Hamtramck', 'MI', 'Ukrainian immigrant Dmytro Szylak spent decades filling the space above and behind his garages with whirligigs, wooden figures, airplanes, lights and handmade moving sculptures. Hatch Art now preserves the folk-art environment, which can be viewed from the alley and has scheduled volunteer restoration days. Address: 12087 Klinger St., Hamtramck, MI', 'open', null, 'https://www.hatchart.org/hamtramck-disneyland', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Handfuls of Small Stones', 'handfuls-of-small-stones', 'roadside-oddities', 42.97985, -85.67293, 'Grand Rapids', 'MI', 'A small plaque beside the Grand River commemorates an event that never happened in this universe. It belongs to Eames Demetrios''s worldwide Kcymaerxthaere project, which installs physical markers describing people, places and events from an elaborate fictional parallel world.', 'open', null, 'https://www.atlasobscura.com/places/handfuls-of-small-stones', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Hanging Rock National Natural Landmark', 'hanging-rock-national-natural-landmark', 'roadside-oddities', 40.83, -85.70733, 'Lagro', 'IN', 'Hanging Rock is the exposed remnant of an ancient coral reef formed hundreds of millions of years before Indiana existed as dry land. The limestone bluff rises abruptly over the Wabash River and is protected as a National Natural Landmark.', 'open', null, 'https://www.atlasobscura.com/places/hanging-rock-national-natural-landmark', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Hanging Rock Raptor Observatory', 'hanging-rock-raptor-observatory', 'roadside-oddities', 37.50448, -80.45293, 'Waiteville', 'WV', 'This former fire lookout sits on a narrow ridge reached by roughly a 1.2-mile hike and became a famous place for watching migrating hawks and other raptors. The trail remains open, but the tourism authority currently reports the observation structure itself as temporarily closed, so check status before building a route around it.', 'limited', null, 'https://visitwv.com/partners/hanging-rock-raptor-observatory/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harborcreek Dinosaur Family', 'harborcreek-dinosaur-family', 'roadside-oddities', 42.18045, -79.95712, 'Harborcreek', 'PA', 'A field of large metal sculptures on Bartlett Road east of Erie: a tyrannosaurus and its young, a triceratops, a woolly mammoth, and a welder among them. They stand on private land beside the road, so look from public ground rather than crossing the grass. Catalogues of the work list it under North East, which is the wrong township and about ten miles off — this entry is placed from the sculptures themselves.', 'private', null, 'https://maps.app.goo.gl/', '2026-09-08T01:45:42.030388+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harlan — World''s Largest Anatomically Accurate Brain Sculpture', 'harlan-worlds-largest-anatomically-accurate-brain-sculpture', 'roadside-oddities', 39.17207, -86.52017, 'Bloomington', 'IN', 'Indiana University''s Psychological and Brain Sciences building has a seven-foot-tall, roughly 10,000-pound human brain carved from Indiana limestone outside its entrance. Artist Amy Brier and carver Mike Donham created the anatomically detailed sculpture, nicknamed Harlan, for the department''s 125th anniversary.', 'open', null, 'https://www.atlasobscura.com/places/the-world-s-largest-anatomically-accurate-limestone-brain-sculpture-bloomington-indiana', '2026-09-08T13:34:34.826362+00:00', null, 'https://psych.indiana.edu/about/harlan-brain/index.html', null, null, null, 'America/Indiana/Indianapolis'),
  ('Harmonic Bridge', 'harmonic-bridge', 'roadside-oddities', 42.70093, -73.11374, 'North Adams', 'MA', 'Resonating tubes mounted beneath a highway overpass transform traffic vibration into a low, continuous musical drone. Instead of hiding road noise, artists Bruce Odland and Sam Auinger turned the bridge itself into a massive instrument.', 'open', null, 'https://www.atlasobscura.com/places/harmonic-bridge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harrier Jump Jet Display', 'harrier-jump-jet-display', 'roadside-oddities', 34.88252, -76.90652, 'Havelock', 'NC', 'Havelock’s close relationship with Marine Corps aviation is represented by a static AV-8 Harrier display in town. In 2026 Fleet Readiness Center East also restored and moved a two-seat TAV-8B Harrier to the Havelock Tourist and Event Center, adding another retired jump jet to a public collection of Marine aircraft. 2026 update: https://www.linkedin.com/posts/fleet-readiness-center-east_frce-fleetreadinesscentereast-av8bharrier-activity-7496225697993175040-6J6o Coordinate reference: https://virtualglobetrotting.com/map/mcdonnell-douglas-av-8-harrier-ii/', 'open', null, 'https://www.roadsideamerica.com/tip/3325', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hartman Rock Garden', 'hartman-rock-garden', 'roadside-oddities', 39.90498, -83.83247, 'Springfield', 'OH', 'Ben Hartman began building this elaborate folk-art garden in 1932 after losing his job during the Great Depression. Miniature castles, cathedrals, historical scenes and hundreds of figures made from concrete, stone, glass and other materials fill the yard, which is preserved as a free public attraction from dawn to dusk.', 'open', null, 'https://hartmanrocks.org/visit/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harvard Bridge Smoot Measurements', 'harvard-bridge-smoot-measurements', 'roadside-oddities', 42.35474, -71.09141, 'Boston', 'MA', 'Painted marks across Harvard Bridge measure its length in ''smoots,'' a unit created in 1958 by repeatedly laying MIT pledge Oliver Smoot end to end. The final measurement — 364.4 smoots plus one ear — became a lasting engineering-school joke.', 'open', null, 'https://www.atlasobscura.com/places/harvard-bridge-smoot-measurements', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haserot Angel', 'haserot-angel', 'roadside-oddities', 41.51302, -81.59038, 'Cleveland', 'OH', 'The Haserot family memorial in Lake View Cemetery features a life-sized bronze angel created by sculptor Herman Matzen in 1919. Weathering has produced dark streaks beneath its eyes that make the figure appear to cry black tears, earning it the nickname Angel of Death; visitors can see it in Section 9 during cemetery hours.', 'open', null, 'https://www.atlasobscura.com/places/the-haserot-angel', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hattiesburg Pocket Museum', 'hattiesburg-pocket-museum', 'roadside-oddities', 31.32623, -89.29023, 'Hattiesburg', 'MS', 'A miniature outdoor museum hidden in a downtown alley, filled with rotating tiny exhibits, miniature scenes and public art. The alley is designed to be discovered on foot and is accessible without entering a conventional museum building.', 'open', null, 'https://hattiesburgpocketmuseum.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hawthorne II — Rooftop Elephant', 'hawthorne-ii-rooftop-elephant', 'roadside-oddities', 44.42649, -69.00779, 'Belfast', 'ME', 'A life-size elephant named Hawthorne II has stood above the Colonial Theatre since 1997, staring down over downtown Belfast from the roof and marquee area. The elephant originally came from Perry’s Nut House and became one of the theater’s most recognizable eccentric features.', 'roadside', null, 'https://www.roadsideamerica.com/tip/49944', '2026-09-09T04:54:23.476824+00:00', null, 'https://colonialtheatre.com/about/', null, null, null, 'America/New_York'),
  ('Headless General John Sevier Statue', 'headless-general-john-sevier-statue', 'roadside-oddities', 35.96378, -83.91829, 'Knoxville', 'TN', 'A statue of Tennessee''s first governor acquired a strange visual reputation because its composition and viewing angle can make the figure appear headless from certain positions. The effect turns an otherwise formal civic monument into a small downtown visual oddity.', 'open', null, 'https://www.atlasobscura.com/places/gen-john-sevier-statue', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Heart of the Forest — 27-Foot Tin Man', 'heart-of-the-forest-27-foot-tin-man', 'roadside-oddities', 37.91859, -85.66183, 'Clermont', 'KY', 'Artist Bill Secunda unveiled this 27-foot metal reinterpretation of the Tin Woodsman at Bernheim Forest in 2025. Rather than carrying his ax as a weapon, the giant figure embraces the forest, turning the familiar Wizard of Oz character into a towering environmental sculpture at the Jackson-Yoe trailhead.', 'open', null, 'https://www.roadsideamerica.com/tip/89361', '2026-09-08T14:42:00.461026+00:00', null, 'https://bernheim.org/', null, null, null, 'America/New_York'),
  ('Hell, Michigan', 'hell-michigan', 'roadside-oddities', 42.4331, -83.9842, 'Hell', 'MI', 'The tiny community of Hell has fully embraced its name with the Gates of Hell, a tiny post office that singes mail, Damnation University diplomas, novelty mayor-for-a-day appointments and appropriately infernal souvenirs. Screams Souvenirs serves as the easiest routable center of the attraction.', 'open', null, 'https://www.gotohellmi.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.gotohellmi.com/', null, null, null, 'America/Detroit'),
  ('Herb Mackey''s Metal Sculpture Yard', 'herb-mackeys-metal-sculpture-yard', 'roadside-oddities', 42.52299, -70.88239, 'Salem', 'MA', 'A Salem yard is crowded with creatures assembled from discarded metal, tools and machine parts. The handmade figures sit near the ferry route and turn a residential property into an evolving outsider-art menagerie. View respectfully from public space unless invited closer.', 'roadside', null, 'https://www.atlasobscura.com/places/herb-mackey-s-metal-sculpture-yard', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Herkimer Diamond Mines', 'herkimer-diamond-mines', 'roadside-oddities', 43.12871, -74.97665, 'Newport', 'NY', 'Visitors break apart exposed dolostone to search for naturally double-terminated quartz crystals known as Herkimer diamonds, which formed roughly 500 million years ago. The fee-dig surface mine operates seasonally and provides basic tools and instruction, with anything found by visitors theirs to keep.', 'limited', null, 'https://herkimerdiamond.com/mine/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hermitage Hotel Men''s Bathroom', 'hermitage-hotel-mens-bathroom', 'roadside-oddities', 36.16368, -86.78231, 'Nashville', 'TN', 'The ornate Art Deco men''s room inside the historic Hermitage Hotel became famous for its green-and-black tilework and unusual elegance. It is inside an operating hotel, so visitors should treat the stop as part of a respectful hotel visit rather than wandering private areas.', 'limited', null, 'https://www.thehermitagehotel.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Herreshoff Castle', 'herreshoff-castle', 'roadside-oddities', 42.5035, -70.84886, 'Marblehead', 'MA', 'A 1920 stone castle inspired by Viking-era Greenland hides in Marblehead, complete with turrets and Gothic windows. Legends mention secret stairs and buried treasure, though those stories are unproven. The property has operated as lodging and is not a free-roaming public ruin.', 'limited', null, 'https://www.atlasobscura.com/places/herreshoff-castle', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Heublein Tower', 'heublein-tower', 'roadside-oddities', 41.8259, -72.7985, 'Avon', 'CT', 'A 165-foot hilltop tower rises above Talcott Mountain and looks more like a European country estate than a Connecticut observation structure. It can only be reached on foot, and the interior museum operates seasonally, but the tower and its setting make the hike worthwhile.', 'limited', null, 'https://www.atlasobscura.com/places/heublein-tower', '2026-09-08T18:47:23.721893+00:00', null, 'https://friendsofheubleintower.org/', null, null, null, 'America/New_York'),
  ('Hiawatha Statue', 'hiawatha-world-s-largest-indian-statue', 'roadside-oddities', 46.449723, -90.162138, 'Ironwood', 'MI', 'Ironwood’s 52-foot fiberglass Hiawatha statue was built in 1964 as a roadside tourist attraction and local landmark. It has since been refurbished and remains the centerpiece of Hiawatha Park, where travelers can walk up for photos.', 'roadside', null, 'https://travelironwood.com/hiawatha-statue/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Menominee'),
  ('Hickory Run Boulder Field', 'hickory-run-boulder-field', 'roadside-oddities', 41.0501, -75.6436, 'Kidder Township', 'PA', 'A roughly 16-acre field of bare sandstone boulders stretches across Hickory Run State Park with almost no soil or vegetation between the rocks. The formation dates to cold-climate conditions near the end of the Ice Age; a gravel road reaches it in warmer months, while winter closures can require a much longer hike.', 'limited', null, 'https://www.pa.gov/agencies/dcnr/recreation/where-to-go/state-parks/find-a-park/hickory-run-state-park', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hidden Heart of Music Row', 'hidden-heart-of-music-row', 'roadside-oddities', 36.14862, -86.79312, 'Nashville', 'TN', 'A heart-shaped detail hidden in the Music Row streetscape became a small local scavenger-hunt landmark. It is the kind of easily overlooked urban feature that rewards travelers who look beyond the recording studios and industry offices.', 'open', null, 'https://www.atlasobscura.com/places/hidden-heart-of-music-row', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hidden River Cave', 'hidden-river-cave', 'roadside-oddities', 37.17916, -85.90671, 'Horse Cave', 'KY', 'Hidden River Cave opens directly beneath downtown Horse Cave and was once badly polluted before becoming a major cave-restoration success story. Visitors can descend beneath Main Street for guided cave tours and visit the American Cave Museum above the entrance.', 'limited', null, 'https://hiddenrivercave.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://hiddenrivercave.com/', null, null, null, 'America/Chicago'),
  ('High Point Restaurant — RyeMabee Mansion', 'high-point-restaurant-ryemabee-mansion', 'roadside-oddities', 35.2393, -85.82872, 'Monteagle', 'TN', 'This stone mansion is wrapped in stories linking it to Al Capone-era travel and Prohibition folklore, although some claims are difficult to verify. Today it operates as a restaurant, allowing visitors to experience the unusual house legally rather than treating it as an abandoned mystery site.', 'open', null, 'https://www.atlasobscura.com/places/high-point-restaurant', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('High Rock Tower', 'high-rock-tower', 'roadside-oddities', 42.46802, -70.94647, 'Lynn', 'MA', 'A stone observatory tower rises high above Lynn from a hill long associated with astronomy and nineteenth-century Spiritualist experiments. The exterior grounds are accessible, while interior observatory access depends on scheduled public programs.', 'limited', null, 'https://www.atlasobscura.com/places/high-rock-tower', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hillbilly Hot Dogs', 'hillbilly-hot-dogs', 'roadside-oddities', 38.50659, -82.29823, 'Lesage', 'WV', 'This deliberately over-the-top roadside restaurant is built around buses, junkyard art, hand-painted signs and hillbilly-themed structures along the Ohio River. It has been operating for more than two decades and remains a working restaurant, so visitors can explore the public grounds while stopping for food.', 'open', null, 'https://www.hillbillyhotdogs.com/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hillside of Concrete Statues — Slick’s Pottery', 'hillside-of-concrete-statues-slicks-pottery', 'roadside-oddities', 36.53671, -80.51104, 'Mount Airy', 'NC', 'A hillside beside Slick’s Pottery is crowded with concrete animals, people, religious figures, fountains, and assorted lawn statues. Seen together, the inventory resembles an army of stone creatures gathering along the road. Location: https://nextdoor.com/pages/slicks-pottery-mount-airy-nc/', 'open', null, 'https://www.roadsideamerica.com/story/33938', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pine River Depot 1887 Caboose', 'historic-caboose', 'roadside-oddities', 46.716906, -94.403555, 'Pine River', 'MN', 'This is the historic 1887 caboose displayed near the Pine River Depot in Pine River, not Pequot Lakes. Heritage Group North restored the aging railroad car in 2019, and travelers now find it beside the depot as an outdoor piece of local railroad history.', 'roadside', null, 'https://www.pineandlakes.com/news/pine-river-pine-ridge-cemetery-historic-caboose-repaired', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Historic Cherokee Caverns', 'historic-cherokee-caverns', 'roadside-oddities', 35.98002, -84.16514, 'Knoxville', 'TN', 'This privately managed cave opens for selected tours, concerts and seasonal events rather than maintaining ordinary daily cave hours. Its large underground rooms give Knoxville an unusual event venue beneath the surface.', 'limited', null, 'https://www.historiccherokeecaverns.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Historic Salvo Post Office', 'historic-salvo-post-office', 'roadside-oddities', 35.54, -75.47417, 'Salvo', 'NC', 'This tiny historic post-office building measures only about eight by twelve feet and once served one of the Outer Banks’ small communities. It no longer provides postal service but has been preserved as a roadside landmark and is listed on the National Register of Historic Places. Historic coordinates: https://en.chped.com/wiki/National_Register_of_Historic_Places_listings_in_Dare_County%2C_North_Carolina', 'roadside', null, 'https://www.roadsideamerica.com/tip/27430', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Historic Santa Claus Statue', 'historic-santa-claus-statue', 'roadside-oddities', 38.11567, -86.91013, 'Santa Claus', 'IN', 'This large Santa statue was dedicated in 1935 and became an early physical symbol of the town that had already turned its unusual name into a Christmas identity. Restored and now standing at the Santa Claus Museum & Village, it gives visitors a historic roadside Santa rather than a modern seasonal decoration.', 'open', null, 'https://www.hmdb.org/m.asp?m=286726', '2026-09-08T13:20:58.818667+00:00', null, 'https://santaclausmuseum.org/', null, null, null, 'America/Chicago'),
  ('H.L. Hunley Submarine', 'hl-hunley-submarine', 'roadside-oddities', 32.85625, -79.95827, 'North Charleston', 'SC', 'The Confederate submarine H.L. Hunley became the first combat submarine to sink an enemy warship and then vanished with its crew in 1864. After being recovered from the ocean floor in 2000, the real vessel was placed in a conservation tank where weekend visitors can see it alongside recovered artifacts.', 'limited', null, 'https://www.hunley.org/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Holy Hill Basilica and Scenic Tower', 'holy-hill-basilica-and-scenic-tower', 'roadside-oddities', 43.24479, -88.32678, 'Hubertus', 'WI', 'A twin-spired basilica rises above a heavily wooded glacial hill, visible for miles across southeastern Wisconsin. The complex combines pilgrimage shrines, chapels and a seasonal observation tower reached by a long staircase.', 'limited', null, 'https://www.holyhill.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.holyhill.com/', null, null, null, 'America/Chicago'),
  ('Holy Land USA', 'holy-land-usa', 'roadside-oddities', 41.54925, -73.02981, 'Waterbury', 'CT', 'A former religious theme park covers a Waterbury hillside with miniature biblical buildings, grottoes and other handmade structures beneath a huge illuminated cross. The attraction fell into decay after closing in the 1980s but is now being gradually restored, leaving an unusual mix of folk art, ruins and active pilgrimage site.', 'open', null, 'https://www.atlasobscura.com/places/holy-land-usa', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Homeless Jesus', 'homeless-jesus', 'roadside-oddities', 35.49359, -80.83224, 'Davidson', 'NC', 'A bronze sculpture depicts Jesus as an anonymous homeless person sleeping beneath a blanket on a park bench, recognizable primarily by the wounds on his feet. The installation initially startled residents who mistook the figure for an actual person sleeping outside the church.', 'open', null, 'https://www.atlasobscura.com/places/homeless-jesus', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hood Milk Bottle', 'hood-milk-bottle', 'roadside-oddities', 42.35165, -71.05017, 'Boston', 'MA', 'A 40-foot wooden milk bottle stands beside the Boston Children''s Museum. Originally constructed in 1930 as a novelty ice-cream stand, it was later moved to Boston by ferry and remains one of the city''s clearest examples of giant-object roadside architecture.', 'open', null, 'https://www.atlasobscura.com/places/hood-milk-bottle', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Horseshoe Falls at Musgrove Mill', 'horseshoe-falls-at-musgrove-mill', 'roadside-oddities', 34.5933, -81.85279, 'Clinton', 'SC', 'A short trail leads to a broad horseshoe-shaped waterfall inside a Revolutionary War historic site. The unusual combination of battlefield interpretation and a photogenic curved cascade makes it more than a standard history stop.', 'limited', null, 'https://southcarolinaparks.com/musgrove-mill', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hot Air Balloon Water Tower', 'hot-air-balloon-water-tower', 'roadside-oddities', 36.96459, -81.07928, 'Wytheville', 'VA', 'Wytheville''s municipal water tower has been painted to resemble a colorful hot-air balloon, turning a piece of utility infrastructure into a highway landmark. The balloon design has become a recognizable local oddity and is best treated as a drive-by or public-road photo stop rather than a site to approach directly.', 'roadside', null, 'https://fotospot.com/attractions/virginia/hot-air-balloon-water-tower', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('House of Bells', 'house-of-bells', 'roadside-oddities', 39.43855, -86.7455, 'Cloverdale', 'IN', 'Dozens of bells share this rural yard with oversized chains, huge buckets, traps jokingly sized for gigantic animals and other industrial curiosities. The unusual collection surrounds an unoccupied private house, so it should be viewed from the road unless access is clearly permitted.', 'private', null, 'https://www.roadsideamerica.com/tip/455', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('House of Mews', 'house-of-mews', 'roadside-oddities', 35.12017, -89.99123, 'Memphis', 'TN', 'This cat-focused nonprofit adoption space and shop has placed rescued cats at the center of a retail storefront for decades. For travelers, it functions as an unexpectedly feline destination in the middle of Cooper-Young.', 'open', null, 'https://houseofmews.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('House of Mugs', 'house-of-mugs', 'roadside-oddities', 35.9585, -81.71102, 'Collettsville', 'NC', 'Thousands of coffee mugs cover the exterior walls, fences, trees, and outbuildings around this rural property, creating a dense folk-art environment assembled from ordinary cups. Visitors should follow the owners’ posted access expectations and treat it as a private-property attraction rather than a public park.', 'limited', null, 'https://www.atlasobscura.com/places/house-of-mugs', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Howe Caverns', 'howe-caverns', 'roadside-oddities', 42.69624, -74.39852, 'Howes Cave', 'NY', 'Howe Caverns takes visitors deep underground through limestone passages, enormous chambers and an underground lake first explored commercially in the nineteenth century. The cave operates as a guided attraction with scheduled tours from its Discovery Drive visitor complex.', 'open', null, 'https://howecaverns.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hubbard Tower', 'hubbard-tower', 'roadside-oddities', 44.26539, -72.57808, 'Montpelier', 'VT', 'A five-story stone observation tower rises above Montpelier from Hubbard Park after a construction process that stretched across many years. The rough stone structure looks much older than its twentieth-century completion date and can be reached by park trails.', 'open', null, 'https://www.roadsideamerica.com/tip/48334', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hubcap Pyramid', 'hubcap-pyramid', 'roadside-oddities', 39.45024, -74.70419, 'Mays Landing', 'NJ', 'Hundreds of shiny hubcaps are stacked into a large pyramid outside a long-running hubcap business on the Black Horse Pike. The reflective roadside structure turns an ordinary pile of automotive parts into a deliberately oversized advertising landmark.', 'roadside', null, 'https://www.roadsideamerica.com/tip/13914', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Huey P. Long Tomb', 'huey-p-long-tomb', 'roadside-oddities', 30.45562, -91.18763, 'Baton Rouge', 'LA', 'Huey Long''s grave sits directly in front of the Louisiana State Capitol beneath a large statue of the populist politician. The monument''s placement makes his political legacy physically dominate the approach to the building.', 'open', null, 'https://www.hmdb.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Huge Doctor''s Bag with Stethoscope', 'huge-doctors-bag-with-stethoscope', 'roadside-oddities', 39.69843, -75.65197, 'Newark', 'DE', 'An oversized doctor''s bag and stethoscope form the sign/sculpture outside a medical-office property near Christiana. It is exactly the kind of giant-object roadside landmark OddWay is built to surface.', 'roadside', null, 'https://www.roadsideamerica.com/tip/18430', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hurdy Gurdy Man and Monkey', 'hurdy-gurdy-man-and-monkey', 'roadside-oddities', 41.48855, -71.3156, 'Newport', 'RI', 'A bronze street performer and his small monkey occupy a permanent spot in downtown Newport. The life-size pair look like buskers frozen in place and have become a whimsical photo stop amid the historic commercial district.', 'open', null, 'https://www.roadsideamerica.com/tip/21184', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('I Love You Hand Sculpture', 'i-love-you-hand-sculpture', 'roadside-oddities', 33.99862, -81.0374, 'Columbia', 'SC', 'A large metal hand forms the American Sign Language gesture for “I love you” near Columbia’s convention-center district. Its oversized scale makes the familiar hand sign into a quick, unmistakable downtown photo stop.', 'open', null, 'https://www.roadsideamerica.com/tip/67330', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ice Castles', 'ice-castles', 'roadside-oddities', 44.03438, -71.69884, 'North Woodstock', 'NH', 'Each winter, crews build a walk-through landscape from hundreds of thousands of icicles and massive frozen walls. Tunnels, towers, slides and illuminated chambers change shape as the weather changes, making the attraction temporary by design. Opening dates depend heavily on winter conditions and tickets can sell out.', 'limited', null, 'https://icecastles.com/new-hampshire/', '2026-09-09T04:49:39.808526+00:00', null, 'https://icecastles.com/new-hampshire/', null, null, null, 'America/New_York'),
  ('Igloo Ice Cream & Sandwich Shop', 'igloo-ice-cream-sandwich-shop', 'roadside-oddities', 36.20627, -81.24501, 'Millers Creek', 'NC', 'This old-school roadside restaurant is built with a rounded white facade designed to resemble an igloo. The business is still serving hot dogs, burgers, sandwiches, and ice cream in 2026, making the architecture a living roadside attraction rather than a preserved shell. Current listing: https://www.restaurantji.com/nc/millers-creek/igloo-ice-cream-and-sandwich-shop-/ Location reference: https://mapcarta.com/N6984550225', 'open', null, 'https://www.roadsideamerica.com/location/nc/all', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Igor the Cheese-Loving Rat', 'igor-the-cheese-loving-rat', 'roadside-oddities', 42.97723, -90.65551, 'Fennimore', 'WI', 'A giant fiberglass rat clutching cheese stands outside a Fennimore cheese business, leaning fully into Wisconsin''s dairy identity. The oversized rodent is a classic highway-photo oddity rather than a formal attraction.', 'roadside', null, 'https://www.roadsideamerica.com/tip/21372', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/tip/21372', null, null, null, 'America/Chicago'),
  ('Illinois Railway Museum', 'illinois-railway-museum', 'roadside-oddities', 42.22643, -88.52617, 'Union', 'IL', 'The country''s largest railway museum preserves an enormous operating collection of locomotives, streetcars, interurbans, and historic transit equipment.', 'limited', null, 'https://www.irm.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Illinois State Fair Route 66 Experience & Legends Neon Sign Park', 'illinois-state-fair-route-66-experience-legends-neon-sign-park', 'roadside-oddities', 39.83216, -89.63707, 'Springfield', 'IL', 'A walk-through Route 66 attraction at the fairgrounds combines recreated roadside scenes with restored and replica neon signs.', 'open', null, 'https://statefair.illinois.gov/ridesattractions/route-66-experience.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Independence Hall Replica', 'independence-hall-replica', 'roadside-oddities', 39.78078, -75.5441, 'Wilmington', 'DE', 'A scaled replica of Philadelphia''s Independence Hall sits unexpectedly along Concord Pike. The miniature landmark is easy to overlook from the road, which is exactly what makes it useful as a quick OddWay detour.', 'roadside', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Indiana Caverns', 'indiana-caverns', 'roadside-oddities', 38.1825, -86.15017, 'Corydon', 'IN', 'Indiana Caverns provides public access to part of the Binkley Cave system, one of the state''s major underground networks. Cave exploration in the system has revealed Ice Age animal remains and other paleontological material, while the commercial tour combines walking and underground boat travel.', 'limited', null, 'https://indianacaverns.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://indianacaverns.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Ingalls Rink — The Yale Whale', 'ingalls-rink-the-yale-whale', 'roadside-oddities', 41.31655, -72.92504, 'New Haven', 'CT', 'Eero Saarinen''s dramatic hockey arena is nicknamed the Yale Whale because its sweeping roof and curved concrete spine resemble a giant marine animal. It remains an active Yale athletic venue, so interior access depends on games and university events.', 'limited', null, 'https://www.atlasobscura.com/things-to-do/connecticut/architecture', '2026-09-08T18:47:23.721893+00:00', null, 'https://yalebulldogs.com/facilities/david-s-ingalls-rink/8', null, null, null, 'America/New_York'),
  ('Insta-Gator Ranch', 'insta-gator-ranch', 'roadside-oddities', 30.51857, -90.0081, 'Covington', 'LA', 'This working alligator ranch offers guided visits explaining the commercial alligator industry and allows unusually close viewing of large numbers of animals. Tours are controlled experiences, so use the ranch''s reservation and operating rules.', 'limited', null, 'https://insta-gatorranch.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('International Petroleum Museum — Mr. Charlie', 'international-petroleum-museum-mr-charlie', 'roadside-oddities', 29.69122, -91.20971, 'Morgan City', 'LA', 'Mr. Charlie is a preserved offshore drilling rig that helped pioneer movable offshore oil production in the Gulf. Guided access turns a major piece of industrial infrastructure into a walk-through museum.', 'limited', null, 'https://www.rigmuseum.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('It''s Electric Neon Sign Park', 'its-electric-neon-sign-park', 'roadside-oddities', 38.70063, -90.15135, 'Granite City', 'IL', 'Three recreated historic business signs glow after dark alongside murals and interpretive displays celebrating Granite City''s Route 66-era commercial history.', 'open', null, 'https://www.riversandroutes.com/directory/its-electric-neon-sign-park-on-route-66/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Iver Mudslider — Rhode Island Troll Trail', 'iver-mudslider-rhode-island-troll-trail', 'roadside-oddities', 41.56955, -71.48851, 'North Kingstown', 'RI', 'Iver Mudslider joined Rhode Island''s Thomas Dambo Troll Trail in 2025 and hides along a short walk in Ryan Park. Like Dambo''s other giant trolls, Iver is constructed largely from discarded and reclaimed wood and is intended to draw visitors into the landscape rather than simply sit beside a road.', 'open', null, 'https://www.southcountyri.com/thomas-dambo-trolls/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jacques the World''s Largest Bobblehead', 'jacques-the-worlds-largest-bobblehead', 'roadside-oddities', 40.64728, -82.54066, 'Bellville', 'OH', 'Jacques is a roughly 35-foot-tall fiberglass chef standing outside the Buckeye Express Diner along Route 97. The giant figure was restored after weather damage and remains an easy public-facing stop on the diner property.', 'open', null, 'https://www.atlasobscura.com/places/jacques-worlds-largest-bobblehead', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jamaica Pond Bench', 'jamaica-pond-bench', 'roadside-oddities', 42.31701, -71.11719, 'Boston', 'MA', 'A professor secretly installed a U-shaped, two-backed bench beside Jamaica Pond as a guerrilla-art prank. Parks officials removed it, reconsidered, and ultimately allowed the strange seat to return, transforming unauthorized furniture into permanent public art.', 'open', null, 'https://www.atlasobscura.com/places/jamacia-pond-bench', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('James Tellen Woodland Sculpture Garden', 'james-tellen-woodland-sculpture-garden', 'roadside-oddities', 43.6897, -87.70885, 'Sheboygan', 'WI', 'James Tellen filled his wooded property with hand-built concrete people, animals and religious scenes. The figures emerge between trees like a homemade storybook and are now preserved for public viewing.', 'open', null, 'https://www.jmkac.org/artist/james-tellen/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.jmkac.org/', null, null, null, 'America/Chicago'),
  ('Jasper Knob', 'jasper-knob', 'roadside-oddities', 46.48559, -87.65659, 'Ishpeming', 'MI', 'This small rocky hill overlooking Ishpeming is composed largely of ancient banded iron formation, preserving geology tied directly to the region''s mining history. A short trail and stair access let visitors climb onto some of the oldest exposed rock found in Michigan.', 'open', null, 'https://www.atlasobscura.com/places/jasper-knob', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Jaws Bridge', 'jaws-bridge', 'roadside-oddities', 41.41612, -70.54872, 'Edgartown', 'MA', 'The small bridge between Edgartown and Oak Bluffs became famous through Steven Spielberg''s ''Jaws.'' Fans still recognize it as the location of a shark-attack sequence, making an otherwise ordinary Martha''s Vineyard bridge a horror-film pilgrimage stop.', 'open', null, 'https://www.atlasobscura.com/places/jaws-bridge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jenny Globe', 'jenny-globe', 'roadside-oddities', 40.0151, -79.07583, 'Somerset', 'PA', 'A huge rotating fiberglass globe has stood outside Jenny Products since the late 1960s, built to celebrate the company''s growth as a maker of pressure-washing equipment. It resembles a water tower but is actually a giant spinning advertisement, with parking available at the business for visitors who want a closer look.', 'roadside', null, 'https://www.atlasobscura.com/places/jenny-globe', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jeremy ''Boo'' Rochman Memorial Park', 'jeremy-boo-rochman-memorial-park', 'roadside-oddities', 37.68699, -89.17527, 'Carbondale', 'IL', 'A free public park is filled with dragons, wizards, castles, giant creatures, and fantasy sculptures created in memory of a local young man.', 'open', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jerimoth Hill', 'jerimoth-hill', 'roadside-oddities', 41.84942, -71.77887, 'Foster', 'RI', 'At 812 feet, Jerimoth Hill is Rhode Island''s highest natural point. It was once notorious among highpointers because access crossed private land whose former owner sharply restricted visitors, but the approach is now publicly accessible. The summit itself is subtle rather than dramatic, making the historical difficulty of reaching it part of the oddity.', 'open', null, 'https://www.atlasobscura.com/places/jerimoth-hill', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jim Henson and Kermit the Frog Statue', 'jim-henson-and-kermit-the-frog-statue', 'roadside-oddities', 38.98763, -76.94505, 'College Park', 'MD', 'A life-size bronze Jim Henson sits on a bench beside Kermit the Frog on the University of Maryland campus, where Henson studied before creating the Muppets. The memorial garden is outdoors and publicly viewable while campus access is open.', 'open', null, 'https://arboretum.umd.edu/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jockey’s Ridge', 'jockeys-ridge', 'roadside-oddities', 35.96241, -75.6339, 'Nags Head', 'NC', 'A huge field of shifting sand rises unexpectedly in the Outer Banks, forming the tallest active natural sand-dune system in the eastern United States. The landscape can feel like a small desert despite sitting between maritime forest and the Atlantic coast.', 'open', null, 'https://www.atlasobscura.com/places/jockey-s-ridge', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Pennekamp Coral Reef State Park', 'john-pennekamp-coral-reef-state-park', 'roadside-oddities', 25.1241, -80.40566, 'Key Largo', 'FL', 'America''s first undersea park, including reefs, wrecks, and underwater statues.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/john-pennekamp-coral-reef-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Johnny Cash ''One Piece at a Time'' Cadillac', 'johnny-cash-one-piece-at-a-time-cadillac', 'roadside-oddities', 35.95343, -87.32702, 'Bon Aqua', 'TN', 'The Storytellers Museum displays a bizarre Cadillac assembled in the spirit of Johnny Cash''s song ''One Piece at a Time.'' Its mismatched body parts turn a novelty-song premise into a real, drivable-looking object tied to Cash''s former farm area.', 'limited', null, 'https://www.storytellersmuseum.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jolly Green Giant', 'jolly-green-giant', 'roadside-oddities', 43.650675, -94.095708, 'Blue Earth', 'MN', 'Blue Earth’s 55-foot Jolly Green Giant was fabricated in 1978 and dedicated that September, becoming a permanent installation in 1979. The fiberglass advertising icon now stands in Giant Statue Park, where travelers can walk up to the pedestal, take photos and visit the surrounding Green Giant-themed displays.', 'roadside', null, 'https://www.si.edu/object/jolly-green-giant-sculpture%3Asiris_ari_336561', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('José Martí Park', 'jos-mart-park', 'roadside-oddities', 27.96181, -82.43909, 'Tampa', 'FL', 'Tiny park whose land was deeded to the Republic of Cuba, making it a unique symbolic enclave.', 'open', null, 'https://www.tampa.gov/parks-and-recreation', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Judy''s Jungle', 'judys-jungle', 'roadside-oddities', 41.68056, -81.32993, 'Mentor', 'OH', 'Judy''s Jungle is a collection of large fiberglass animals gathered outside an industrial property in Mentor, including elephants, giraffes and other oversized creatures. The quirky display is intentionally visible to passersby and visitors can stop to see the figures without entering restricted industrial areas.', 'open', null, 'https://www.atlasobscura.com/places/judys-jungle', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jug Rock', 'jug-rock', 'roadside-oddities', 38.67593, -86.79715, 'Shoals', 'IN', 'Jug Rock is an isolated sandstone formation shaped like a giant stone vessel and is one of the largest free-standing table-rock formations east of the Mississippi River. It sits beside a short public access trail near Shoals, giving OddWay a natural oddity that can be visited without a major hike.', 'open', null, 'https://www.atlasobscura.com/places/jug-rock', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('Jules'' Undersea Lodge', 'jules-undersea-lodge', 'roadside-oddities', 25.09662, -80.43826, 'Key Largo', 'FL', 'Underwater hotel reached by scuba diving into a former marine research habitat.', 'limited', null, 'https://jul.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jumbo the Elephant Statue', 'jumbo-the-elephant-statue', 'roadside-oddities', 42.40775, -71.12058, 'Medford', 'MA', 'A bronze Jumbo stands on the Tufts University campus honoring the enormous circus elephant that became the school''s mascot. After Jumbo died in an 1885 train collision, P.T. Barnum donated his hide to Tufts; the original specimen was destroyed by fire in 1975, leaving the statue as the campus''s most visible elephant memorial.', 'open', null, 'https://www.atlasobscura.com/places/jumbo-the-elephant', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jungle Gardens Buddha Shrine', 'jungle-gardens-buddha-shrine', 'roadside-oddities', 29.90805, -91.91613, 'Avery Island', 'LA', 'A centuries-old Buddha statue sits unexpectedly among subtropical gardens, bamboo and wildlife on Avery Island. The shrine is inside ticketed Jungle Gardens and should be treated as a contemplative site rather than a prop.', 'open', null, 'https://www.junglegardens.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jungle Jim''s International Market', 'jungle-jims-international-market', 'roadside-oddities', 39.33508, -84.52425, 'Fairfield', 'OH', 'Jungle Jim''s is a massive international grocery store that doubles as a roadside attraction, filling its aisles with oversized decorations, animatronics, themed storefronts and deliberately bizarre displays. Travelers can shop normally while finding features such as singing characters and the famous faux portable-toilet entrance to the restrooms.', 'open', null, 'https://junglejims.com/', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jungle Room at Graceland', 'jungle-room-at-graceland', 'roadside-oddities', 35.04611, -90.02583, 'Memphis', 'TN', 'Elvis Presley''s Jungle Room is an aggressively themed interior of green carpet, carved furniture, faux-waterfall décor and 1970s excess. It is accessible only as part of authorized Graceland admission rather than as a separate room visitors can enter freely.', 'limited', null, 'https://www.graceland.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Jurustic Park', 'jurustic-park', 'roadside-oddities', 44.73561, -90.16676, 'Marshfield', 'WI', 'Clyde Wynia builds whimsical metal creatures from scrap and presents them as the fossilized remains of extinct creatures from the fictional Jurustic Age. Dragons, insects and impossible animals fill the outdoor property in a mix of sculpture and deadpan mythology.', 'limited', null, 'https://jurustic.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://jurustic.com/', null, null, null, 'America/Chicago'),
  ('Körner’s Folly', 'k-rners-folly', 'roadside-oddities', 36.11522, -80.07876, 'Kernersville', 'NC', 'Artist and designer Jule Gilmer Körner created this wildly eccentric house as a showcase for his interior-design work. Its rooms differ dramatically in size and style, with odd stairways, decorative experiments, unusually low and high ceilings, and a private theater built into the house. Location source: https://www.wikizero.net/wiki/en/National_Register_of_Historic_Places_listings_in_Forsyth_County%2C_North_Carolina', 'limited', null, 'https://www.kornersfolly.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kaiser Paul — Bunyan Made of Car Parts', 'kaiser-paul-bunyan-made-of-car-parts', 'roadside-oddities', 45.08181, -83.44635, 'Alpena', 'MI', 'This giant Paul Bunyan figure was assembled from pieces of old Kaiser automobiles, turning car fenders and body panels into a northern Michigan folk hero. The roughly 30-foot sculpture now stands at Alpena Community College as a particularly literal combination of auto history and roadside giant.', 'roadside', null, 'https://www.roadsideamerica.com/story/2421', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Kennedy Space Center Rocket Garden', 'kennedy-space-center-rocket-garden', 'roadside-oddities', 28.5232, -80.68191, 'Merritt Island', 'FL', 'Forest of historic rockets and missiles displayed vertically like technological monuments.', 'limited', null, 'https://www.kennedyspacecenter.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kenova Pumpkin House', 'kenova-pumpkin-house', 'roadside-oddities', 38.39974, -82.56686, 'Kenova', 'WV', 'What began with a handful of carved pumpkins in 1978 has grown into an annual display covering the historic Griffith house and grounds with roughly 3,000 jack-o''-lanterns. It is a private residence transformed into a public attraction around Halloween, so this should only route travelers during the seasonal display.', 'limited', null, 'https://wvtourism.com/the-pumpkin-house-how-this-small-town-home-became-a-national-attraction/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kent Plantation House', 'kent-plantation-house', 'roadside-oddities', 31.30611, -92.48361, 'Alexandria', 'LA', 'Kent House preserves one of central Louisiana''s oldest surviving Creole plantation dwellings along with reconstructed and moved outbuildings. Tours interpret building methods, household life and plantation labor.', 'limited', null, 'https://www.kenthouse.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kentucky Floral Clock', 'kentucky-floral-clock', 'roadside-oddities', 38.18604, -84.87641, 'Frankfort', 'KY', 'Dedicated in 1961 behind the Kentucky State Capitol, this functioning clock uses a massive planted face that changes with seasonal flowers. The mechanism moves oversized hands across the living display while coins tossed into the pool below help support horticultural scholarships.', 'open', null, 'https://www.atlasobscura.com/places/kentucky-floral-clock', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kentucky Stonehenge', 'kentucky-stonehenge', 'roadside-oddities', 37.27186, -85.89144, 'Munfordville', 'KY', 'Chester Fryer hauled huge rocks from the surrounding area to create his own interpretation of Stonehenge beside his Munfordville home. The property also includes other rock installations such as Earth Mysteries and the Garden of Gethsemane, with designated visitor parking.', 'open', null, 'https://www.visitmunfordville.com/kentucky-stone-henge', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Keweenaw County Snow Stick', 'keweenaw-county-snow-stick', 'roadside-oddities', 47.35898, -88.30343, 'Mohawk', 'MI', 'This towering measuring-stick display visualizes just how much snow can fall in Michigan''s Keweenaw Peninsula. Markers climb far above a person''s head to represent record seasonal snowfall totals, turning local weather statistics into a memorable roadside landmark.', 'roadside', null, 'https://www.waymarking.com/waymarks/WMCEM2_The_Snow_Stick_Mohawk_MI', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Key West Butterfly & Nature Conservatory Flamingos', 'key-west-butterfly-nature-conservatory-flamingos', 'roadside-oddities', 24.54816, -81.79642, 'Key West', 'FL', 'Indoor tropical habitat famous for free-roaming butterflies and resident flamingos Rhett and Scarlett.', 'limited', null, 'https://keywestbutterfly.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kid Groot Tree Carving', 'kid-groot-tree-carving', 'roadside-oddities', 41.52091, -72.89538, 'Cheshire', 'CT', 'A dead roadside tree was carved into an oversized version of Kid Groot from Guardians of the Galaxy. The sculpture is illuminated after dark and is occasionally dressed for holidays, giving the residential roadside piece an evolving personality.', 'roadside', null, 'https://www.roadsideamerica.com/tip/85729', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Neptune', 'king-neptune', 'roadside-oddities', 34.71953, -76.71281, 'Morehead City', 'NC', 'A giant, brightly painted King Neptune rises from the waterfront near Shepard Street, while his oversized mermaid-like tail appears separately behind him. The deliberately theatrical sea god has become a longtime fixture of downtown Morehead City’s docks. Coordinates: https://fotospot.com/attractions/north-carolina/goofy-king-neptune-statue', 'open', null, 'https://www.roadsideamerica.com/tip/29124', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Neptune Statue', 'king-neptune-statue', 'roadside-oddities', 36.85963, -75.9773, 'Virginia Beach', 'VA', 'A massive bronze King Neptune rises over the Virginia Beach Boardwalk at 31st Street, surrounded by sculpted sea creatures and holding an enormous trident. Installed in 2005, the roughly 12-ton monument has become one of the city''s defining roadside-scale photo stops.', 'open', null, 'https://www.visitvirginiabeach.com/listing/king-neptune-statue/1173/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Neptune Sundial', 'king-neptune-sundial', 'roadside-oddities', 32.1805, -80.72867, 'Hilton Head Island', 'SC', 'A huge bronze Neptune towers over Shelter Cove Harbour while also functioning as part of a working sundial. The sculpture’s scale, trident, and unusual practical purpose make it far stranger than a standard waterfront monument.', 'open', null, 'https://www.atlasobscura.com/places/king-neptune-sundial', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Nyani — Giant Bronze Gorilla', 'king-nyani-giant-bronze-gorilla', 'roadside-oddities', 41.01986, -73.62293, 'Greenwich', 'CT', 'An enormous reclining bronze gorilla reaches an open hand toward visitors outside the Bruce Museum. Created by artists Gillie and Marc, King Nyani is intended as a gentle counterpoint to monster-movie gorillas and is currently listed by the museum as an ongoing installation.', 'open', null, 'https://brucemuseum.org/exhibitions/king-nyani/', '2026-09-08T18:47:23.721893+00:00', null, 'https://brucemuseum.org/', null, null, null, 'America/New_York'),
  ('Kinzua Bridge Skywalk and Tornado Ruins', 'kinzua-bridge-skywalk-and-tornado-ruins', 'roadside-oddities', 41.75952, -78.58694, 'Hamlin Township', 'PA', 'The Kinzua Viaduct once stretched more than 2,000 feet across Kinzua Gorge before a tornado tore away much of the structure in 2003. The surviving towers now form a public skywalk with a glass viewing area, while the twisted fallen towers remain visible across the valley below.', 'open', null, 'https://www.pa.gov/agencies/dcnr/recreation/where-to-go/state-parks/find-a-park/kinzua-bridge-state-park', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kip''s Castle', 'kips-castle', 'roadside-oddities', 40.82866, -74.22446, 'Verona', 'NJ', 'A turreted early twentieth-century mansion modeled loosely on a medieval Norman castle rises above the surrounding suburbs. Essex County now operates the estate as a public cultural site, with interior access tied to tours and scheduled programs.', 'limited', null, 'https://www.essexcountyparks.org/parks/kips-castle', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Kitch-iti-kipi', 'kitch-iti-kipi', 'roadside-oddities', 46.00417, -86.38195, 'Manistique', 'MI', 'Michigan''s largest freshwater spring is a brilliant emerald pool about 40 feet deep, constantly replenished by thousands of gallons of clear groundwater. Visitors cross the spring on a hand-operated observation raft that provides views of trout, submerged trees and the bubbling bottom.', 'open', null, 'https://www.atlasobscura.com/places/kitch-iti-kipi', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Knoxville Weather Kiosk', 'knoxville-weather-kiosk', 'roadside-oddities', 35.96398, -83.91865, 'Knoxville', 'TN', 'A vintage downtown weather kiosk preserves an era when public instruments displayed temperature and atmospheric information on the street. It is an easy-to-miss piece of civic technology surrounded by modern Knoxville.', 'open', null, 'https://www.atlasobscura.com/places/knoxville-weather-kiosk', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('KokoMantis', 'kokomantis', 'roadside-oddities', 40.48658, -86.13351, 'Kokomo', 'IN', 'KokoMantis is a giant praying mantis assembled from salvaged industrial material, including World War II-era fuel pontoons and recycled traffic-light poles. The roughly 17-foot-high sculpture stands downtown at Washington and Sycamore Streets and is one of Kokomo''s most recognizable modern roadside oddities.', 'open', null, 'https://www.atlasobscura.com/places/kokomantis-scrap-art-sculpture', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Lake Eola ''Muse of Discovery''', 'lake-eola-muse-of-discovery', 'roadside-oddities', 28.54556, -81.37232, 'Orlando', 'FL', 'Giant partially buried human figure appearing to emerge from the ground beside Lake Eola.', 'roadside', null, 'https://www.orlando.gov/Parks-the-Environment/Directory/Lake-Eola-Park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake George Mystery Spot', 'lake-george-mystery-spot', 'roadside-oddities', 43.42263, -73.713, 'Lake George', 'NY', 'Stand on the marked X behind the Lake George Visitor Center and speak toward the lake; your voice returns as a strange focused echo that people standing only a few feet away may not hear the same way. The free public spot has accumulated both acoustic explanations and supernatural folklore and remains physically marked in Blais Park.', 'open', null, 'https://www.lakegeorge.com/guides/things-to-do/mystery-spot/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lakenenland Sculpture Park', 'lakenenland-sculpture-park', 'roadside-oddities', 46.4923, -87.15205, 'Chocolay Township', 'MI', 'Artist Tom Lakenen has filled a large wooded property east of Marquette with more than 100 sculptures made largely from scrap iron and industrial leftovers. Visitors can walk or drive through the free outdoor art park at any hour, encountering everything from humorous figures to political and environmental pieces.', 'open', null, 'https://lakenenland.com/', '2026-09-08T15:12:49.285859+00:00', null, 'https://lakenenland.com/', null, null, null, 'America/Detroit'),
  ('Lakota Wolf Preserve', 'lakota-wolf-preserve', 'roadside-oddities', 40.97093, -75.07223, 'Knowlton Township', 'NJ', 'Guided visits lead to observation areas overlooking packs of wolves, foxes, bobcats and other animals at this privately operated preserve near the Delaware Water Gap. Access is controlled by tour schedule and reservation rather than casual roaming through the property.', 'limited', null, 'https://www.lakotawolf.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Langlais Art Preserve', 'langlais-art-preserve', 'roadside-oddities', 44.04165, -69.21083, 'Cushing', 'ME', 'The former home and studio property of Maine sculptor Bernard Langlais is filled with his large, rough-hewn wooden and outdoor artworks. Visitors can walk through an unusual landscape where the art, workshop, fields, and forest all blend together.', 'open', null, 'https://www.langlaisartpreserve.org/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Large Santa of Vale Road', 'large-santa-of-vale-road', 'roadside-oddities', 41.42771, -73.39389, 'Brookfield', 'CT', 'A giant waving Santa Claus stands year-round outside a storage property on Vale Road. The restored fiberglass figure has become an all-season roadside landmark where Christmas never really ends.', 'roadside', null, 'https://www.roadsideamerica.com/tip/60708', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Largest Shotgun Shell', 'largest-shotgun-shell', 'roadside-oddities', 37.68458, -77.45387, 'Ashland', 'VA', 'A roughly 30-foot-tall green shotgun shell stands outside Green Top as a giant tribute to the area''s hunting culture. Built by Hudson Sheet Metal, the oversized shell is positioned along the store property and works as a quick roadside photo stop during normal access to the commercial site.', 'roadside', null, 'https://www.roadsideamerica.com/tip/84714', '2026-09-08T04:17:48.352537+00:00', null, 'https://www.greentophuntfish.com/', null, null, null, 'America/New_York'),
  ('Largest Zipper in America — Unzipping the Earth', 'largest-zipper-in-america-unzipping-the-earth', 'roadside-oddities', 44.1992, -72.5035, 'Barre', 'VT', 'Artist Chris Miller carved a 74-foot granite zipper into the ground along North Main Street, making it look as though the city itself is being unzipped. The piece, titled Unzipping the Earth, turns Barre''s signature stone into an oversized piece of public art.', 'open', null, 'https://www.roadsideamerica.com/tip/40682', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Larry the Lobster at Taste of Maine', 'larry-the-lobster-at-taste-of-maine', 'roadside-oddities', 43.9208, -69.79909, 'Woolwich', 'ME', 'A gigantic inflatable lobster named Larry sprawls across the roof of Taste of Maine Restaurant. The oversized crustacean has become a highly visible Route 1 landmark and one of the state’s easiest drive-by oddities.', 'roadside', null, 'https://tasteofmaine.com/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Last Shell Oil Clamshell Station', 'last-shell-oil-clamshell-station', 'roadside-oddities', 36.0677, -80.2141, 'Winston-Salem', 'NC', 'This restored 1930s service station is literally shaped like a giant yellow scallop shell. Quality Oil built several shell-shaped stations as advertising, but the Sprague Street building is the only surviving example and is now preserved as an architectural roadside oddity. Address: https://www.cityofws.org/DocumentCenter/View/25690', 'roadside', null, 'https://qualityoilnc.com/mural/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Last Supper in Concrete', 'last-supper-in-concrete', 'roadside-oddities', 37.38973, -86.88989, 'Beaver Dam', 'KY', 'Folk artist Donald Bray created a full Last Supper scene from concrete along with additional homemade sculpture and mural work on his rural property. The installation is visible beside Rochester Road, but there is little parking and the art is on private land, so OddWay visitors should remain roadside unless invited closer.', 'private', null, 'https://www.roadsideamerica.com/tip/74119', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Laurel Caverns', 'laurel-caverns', 'roadside-oddities', 39.7996, -79.7113, 'Wharton Township', 'PA', 'Pennsylvania''s largest cave system by volume extends beneath Chestnut Ridge in Fayette County. The underground caverns are open only from mid-April through late October for guided and self-guided experiences, closing each winter to protect hibernating bats.', 'limited', null, 'https://www.pa.gov/agencies/dcnr/recreation/where-to-go/state-parks/find-a-park/laurel-caverns-state-park', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lauterbach Giant', 'lauterbach-giant', 'roadside-oddities', 39.76429, -89.67982, 'Springfield', 'IL', 'A classic Muffler Man in a tire-shop uniform has stood in Springfield since 1978 and even survived a tornado that tore off his head.', 'roadside', null, 'https://www.lauterbachtire.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lawrence Brook Carvings', 'lawrence-brook-carvings', 'roadside-oddities', 40.47342, -74.42274, 'New Brunswick', 'NJ', 'Faces and figures carved into stone appear near Lawrence Brook within the Rutgers Gardens area. The weathered carvings are easy to miss among the landscape and are accessible only during the gardens'' normal public hours.', 'limited', null, 'https://www.atlasobscura.com/places/lawrence-brook-carvings', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Leaning Tower of Niles', 'leaning-tower-of-niles', 'roadside-oddities', 42.01242, -87.78406, 'Niles', 'IL', 'A half-scale 1930s recreation of Italy''s Leaning Tower of Pisa stands beside a suburban YMCA complex as one of Chicagoland''s classic oddities.', 'open', null, 'https://www.vniles.com/883/Leaning-Tower-of-Niles', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Leatherlips Monument', 'leatherlips-monument', 'roadside-oddities', 40.11702, -83.11057, 'Dublin', 'OH', 'This 12-foot stone portrait of Wyandot leader Leatherlips was created by artist Ralph Helmick and installed at Scioto Park in 1990 near the area traditionally associated with Leatherlips'' 1810 execution. Visitors can walk into the limestone sculpture and look through it toward the Scioto River; the City of Dublin and Wyandotte Nation have also worked to correct a later, inaccurate "curse" legend attached to his name.', 'open', null, 'https://www.dublinarts.org/leatherlips', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Legs Inn', 'legs-inn', 'roadside-oddities', 45.64262, -85.03721, 'Cross Village', 'MI', 'Polish immigrant Stanley Smolak built this eccentric stone-and-timber restaurant with driftwood, local rock and handmade decorations, then lined the roof with upside-down cast-iron stove legs that gave the inn its name. The heavily decorated interior adds taxidermy, carved wood and folk-art details to the already unusual building.', 'limited', null, 'https://www.atlasobscura.com/places/legs-inn', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.legsinn.com/', null, null, null, 'America/Detroit'),
  ('Lenny the Chocolate Moose', 'lenny-the-chocolate-moose', 'roadside-oddities', 43.58673, -70.35322, 'Scarborough', 'ME', 'Lenny is a life-size moose made from about 1,700 pounds of milk chocolate and displayed inside Len Libby Candies. He is joined by other chocolate woodland figures in one of Maine’s strangest edible-looking roadside displays.', 'limited', null, 'https://www.atlasobscura.com/places/lenny-the-chocolate-moose', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Leslie Murray''s Junk People', 'leslie-murrays-junk-people', 'roadside-oddities', 41.54804, -73.18971, 'Woodbury', 'CT', 'Scrap metal, discarded machinery and automotive parts have been assembled into human figures outside Murray Brothers Garage. The homemade characters turn an ordinary repair-shop lot into a compact roadside sculpture garden.', 'roadside', null, 'https://www.roadsideamerica.com/story/71908', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lewes Town Clock', 'lewes-town-clock', 'roadside-oddities', 38.77558, -75.13974, 'Lewes', 'DE', 'This freestanding town clock is intentionally designed to look much older than it is. Installed in 2022 and funded by local donors, the roughly ten-foot landmark commemorates Lewes and its 1631 Dutch-settlement history while blending into the town’s centuries-old streetscape.', 'open', null, 'https://www.atlasobscura.com/places/lewes-town-clock', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lichgate on High Road', 'lichgate-on-high-road', 'roadside-oddities', 30.46083, -84.31361, 'Tallahassee', 'FL', 'Fairy-tale Tudor cottage, giant ancient live oak, gardens, and a labyrinth hidden beside a busy city road.', 'limited', null, 'https://www.lichgateonhighroad.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lincoln Career Column', 'lincoln-career-column', 'roadside-oddities', 41.7687, -72.66353, 'East Hartford', 'CT', 'One of the pieces on the Hartford-area Lincoln Financial Sculpture Walk compresses major stages of Abraham Lincoln''s life and career into a vertical sculptural column. It is part history lesson and part unconventional presidential monument.', 'open', null, 'https://www.roadsideamerica.com/tip/65811', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lincoln Caverns', 'lincoln-caverns', 'roadside-oddities', 40.50735, -78.07132, 'Porter Township', 'PA', 'Lincoln Caverns and adjoining Whisper Rocks contain passageways filled with flowstone, crystals and other limestone formations discovered during road construction in the 1930s. Guided underground tours operate from the visitor center, with special black-light and themed programs offered on selected dates.', 'open', null, 'https://lincolncaverns.com/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lincoln Welcomes Your Conversation', 'lincoln-welcomes-your-conversation', 'roadside-oddities', 41.76846, -72.66276, 'East Hartford', 'CT', 'A life-size young Abraham Lincoln sits on a boulder with his hand extended toward an empty neighboring rock, deliberately inviting visitors to sit beside him. The 2006 sculpture is one of the more interactive presidential monuments in Connecticut.', 'open', null, 'https://www.roadsideamerica.com/tip/65809', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Linville Caverns', 'linville-caverns', 'roadside-oddities', 35.91919, -81.9388, 'Marion', 'NC', 'North Carolina’s only show cave leads visitors through narrow underground passages filled with mineral formations, pools, bats, and trout living in total darkness. Tours have operated here since the 1930s.', 'limited', null, 'https://linvillecaverns.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Little Cubs Field', 'little-cubs-field', 'roadside-oddities', 42.28775, -89.64091, 'Freeport', 'IL', 'A meticulously scaled neighborhood baseball field recreates Wrigley Field''s ivy, scoreboard, rooftops, and marquee in miniature.', 'open', null, 'https://www.littlecubsfield.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Little Debbie Park', 'little-debbie-park', 'roadside-oddities', 35.05692, -85.07107, 'Collegedale', 'TN', 'Giant sculptures of Little Debbie snack cakes turn a public park into a playful monument to the brand headquartered nearby. Oversized oatmeal creme pies and other familiar treats make the park intentionally absurd without requiring a ticket.', 'open', null, 'https://www.atlasobscura.com/places/little-debbie-park', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Little River Canyon National Preserve', 'little-river-canyon-national-preserve', 'roadside-oddities', 34.39866, -85.63382, 'Fort Payne', 'AL', 'Little River cuts a deep canyon across Lookout Mountain, creating waterfalls, cliffs and dramatic overlooks unusual for Alabama. Route visitors to the Canyon Center or established overlooks and trails rather than unmarked cliff edges.', 'open', null, 'https://www.nps.gov/liri/index.htm', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lois Lane Statue', 'lois-lane-statue', 'roadside-oddities', 37.15449, -88.73061, 'Metropolis', 'IL', 'A bronze likeness of actress Noel Neill as Lois Lane stands a few blocks from Superman, expanding Metropolis into a full comic-book pilgrimage.', 'open', null, 'https://www.metropolistourism.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Longaberger Basket Building', 'longaberger-basket-building', 'roadside-oddities', 40.06376, -82.34646, 'Newark', 'OH', 'Longaberger opened this seven-story headquarters in 1997 in the shape of one of the company''s Medium Market Baskets, complete with enormous handles. The office building has spent years largely vacant and was again being marketed for sale in 2026, so treat it as an exterior roadside stop unless an officially announced tour or event specifically allows entry.', 'roadside', null, 'https://www.axios.com/local/columbus/2026/07/10/longaberger-basket-building-history-for-sale-newark', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Longwood', 'longwood', 'roadside-oddities', 31.53667, -91.40472, 'Natchez', 'MS', 'The largest octagonal house in the United States, topped by an onion-shaped dome and famously left unfinished when construction stopped during the Civil War. Visitors can tour the finished lower level and the raw upper stories, where building materials and structural framing remain exposed. Secondary source: https://visitmississippi.org/things-to-do/architecture/longwood/', 'open', null, 'https://natchezpilgrimage.com/year-round/longwood-circa-1860-1861/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Looking Glass Rock', 'looking-glass-rock', 'roadside-oddities', 35.30372, -82.79346, 'Brevard', 'NC', 'This enormous exposed granite pluton rises abruptly from Pisgah National Forest like a giant stone dome. Its name comes from the way water or ice on the rock face can reflect sunlight, while the unusually sheer formation has also become a major climbing landmark.', 'limited', null, 'https://www.atlasobscura.com/places/looking-glass-rock', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lookout Mountain Incline Railway', 'lookout-mountain-incline-railway', 'roadside-oddities', 35.00778, -85.33556, 'Chattanooga', 'TN', 'This historic funicular climbs Lookout Mountain on a grade that becomes dramatically steep near the summit. The unusual rail engineering and nearly vertical-looking ride make the Incline itself the attraction rather than simply transportation to a viewpoint.', 'limited', null, 'https://ridetheincline.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lord''s Prayer Rock', 'lords-prayer-rock', 'roadside-oddities', 44.1295, -73.06956, 'Bristol', 'VT', 'A large roadside boulder bears the Lord''s Prayer carved directly into its face. The labor-intensive inscription has made the rock a long-standing local landmark along the road outside Bristol.', 'roadside', null, 'https://www.roadsideamerica.com/story/9784', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lorelei Giant Mermaid', 'lorelei-giant-mermaid', 'roadside-oddities', 24.92222, -80.63147, 'Islamorada', 'FL', 'Oversized wooden mermaid tied to maritime folklore and classic Keys roadside kitsch.', 'roadside', null, 'https://www.loreleicabanabar.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Los Adaes State Historic Site', 'los-adaes-state-historic-site', 'roadside-oddities', 31.7085, -93.29323, 'Robeline', 'LA', 'Los Adaes was once the capital of Spanish Texas and a frontier settlement facing French Louisiana. Archaeological remains rather than a recreated town survive today, and public schedules can be seasonal or limited.', 'limited', null, 'https://www.lastateparks.com/historic-sites/los-adaes-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lost River Cave', 'lost-river-cave', 'roadside-oddities', 36.95192, -86.47225, 'Bowling Green', 'KY', 'Lost River Cave carries visitors by boat into an underground river system beneath Bowling Green. The site also has a strange human history involving mills, Civil War activity and an underground nightclub that once operated inside the cave entrance.', 'limited', null, 'https://www.lostrivercave.org/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.lostrivercave.org/', null, null, null, 'America/Chicago'),
  ('Lost World Caverns', 'lost-world-caverns', 'roadside-oddities', 37.83265, -80.44684, 'Lewisburg', 'WV', 'Discovered through a surface opening and developed as a show cave, Lost World Caverns takes visitors through a huge underground chamber filled with stalactites and other formations. The standard attraction is self-guided, while a separate wild-cave experience goes much deeper and requires advance arrangements.', 'open', null, 'https://www.showcaves.com/english/usa/showcaves/LostWorld.html', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Louisiana Sports Hall of Fame & Northwest Louisiana History Museum', 'louisiana-sports-hall-of-fame-northwest-louisiana-history-museum', 'roadside-oddities', 31.76345, -93.08845, 'Natchitoches', 'LA', 'A highly sculptural contemporary building houses both Louisiana sports history and exhibits on the cultures of northwest Louisiana. Its flowing interior geometry makes the architecture as memorable as the collections.', 'open', null, 'https://louisianastatemuseum.org/museum/louisiana-sports-hall-fame-northwest-louisiana-history-museum', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisiana State Oil & Gas Museum', 'louisiana-state-oil-gas-museum', 'roadside-oddities', 32.74128, -93.97088, 'Oil City', 'LA', 'Located in a town literally named for petroleum, this museum uses photographs, machinery, rigs and life-size scenes to tell the story of Louisiana''s early oil boom. Outdoor equipment around the old depot extends the exhibits beyond the museum building.', 'open', null, 'https://www.sos.la.gov/museums/louisiana-state-oil-and-gas-museum', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Louisville Mega Cavern', 'louisville-mega-cavern', 'roadside-oddities', 38.20138, -85.7041, 'Louisville', 'KY', 'A former limestone mine beneath Louisville was expanded into an enormous man-made underground space stretching beneath part of the city. The cavern has been used for storage and civil-defense planning and now hosts commercial underground attractions and tours.', 'limited', null, 'https://mapcarta.com/W332447080', '2026-09-08T14:30:49.642487+00:00', null, 'https://louisvillemegacavern.com/', null, null, null, 'America/Kentucky/Louisville'),
  ('Love Valley — Town with No Cars, Only Horses', 'love-valley-town-with-no-cars-only-horses', 'roadside-oddities', 35.98944, -80.98833, 'Love Valley', 'NC', 'Love Valley was deliberately built to resemble an Old West town and still keeps motor vehicles off its central streets. Visitors park outside the core and enter an unusual community where horses remain a normal form of transportation and hitching rails line the wooden storefronts.', 'open', null, 'https://lovevalley.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Loveland Castle', 'loveland-castle', 'roadside-oddities', 39.28358, -84.266, 'Loveland', 'OH', 'Harry Andrews began building Château Laroche, better known as Loveland Castle, along the Little Miami River in the 1920s using stone and hand-formed construction methods. The medieval-style castle became headquarters for his Knights of the Golden Trail and now operates as a museum where visitors can explore the rooms, towers and grounds during posted hours.', 'open', null, 'https://lovelandcastle.com/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lowe Mill ARTS & Entertainment', 'lowe-mill-arts-entertainment', 'roadside-oddities', 34.71515, -86.59704, 'Huntsville', 'AL', 'A sprawling former textile mill has been converted into a maze of artist studios, galleries, performance rooms and maker spaces. The building’s industrial shell and dense creative reuse make it feel closer to an inhabited art labyrinth than a conventional gallery complex.', 'open', null, 'https://lowemill.art/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lower Trenton Bridge — TRENTON MAKES Sign', 'lower-trenton-bridge-trenton-makes-sign', 'roadside-oddities', 40.21037, -74.76907, 'Trenton', 'NJ', 'The Delaware River bridge carries the enormous illuminated slogan ''TRENTON MAKES THE WORLD TAKES,'' first created to advertise the city''s manufacturing power. The blunt industrial boast remains one of New Jersey''s most recognizable pieces of infrastructure lettering.', 'open', null, 'https://www.atlasobscura.com/places/trenton-makes-the-world-takes-bridge', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lucette Statue (Paul Bunyan''s Sweetheart)', 'lucette-statue-paul-bunyan-s-sweetheart', 'roadside-oddities', 46.930974, -94.523008, 'Hackensack', 'MN', 'Lucette is in Hackensack, not Walker, and was created as Paul Bunyan’s fictional sweetheart for the town’s 1952 celebration. The statue has been repaired after weather damage over the decades and still stands in Birch Lake Park near the visitor center as a free public landmark.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=235099', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lucy the Elephant', 'lucy-the-elephant', 'roadside-oddities', 39.32084, -74.51159, 'Margate City', 'NJ', 'Built in 1881, Lucy is a six-story elephant-shaped building overlooking the Jersey Shore and one of America''s oldest surviving pieces of novelty architecture. Visitors can tour the interior and climb to the howdah on her back during scheduled operating hours.', 'limited', null, 'https://lucytheelephant.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Luling Mansion', 'luling-mansion', 'roadside-oddities', 29.9826, -90.0862, 'New Orleans', 'LA', 'This sprawling Italianate mansion was built in the 1860s for cotton merchant Florence Luling and now survives inside a later apartment complex. Its scale and secluded appearance make it a striking architectural anomaly; view only from lawful public areas.', 'roadside', null, 'https://www.nps.gov/nr/travel/louisiana/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Richwood Lumberjack Muffler Man', 'lumberjack-muffler-man-statue', 'roadside-oddities', 38.225668, -80.5261, 'Richwood', 'WV', 'Richwood’s giant lumberjack is a modified fiberglass Muffler Man used as the Richwood High School Lumberjacks mascot beside the football field. Roadside America was tracking the figure in Richwood by 1990, though its original manufacture date is not documented; it has been repaired and repainted repeatedly and is best viewed from permitted public areas around school events.', 'limited', null, 'https://www.roadsideamerica.com/tip/2832', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('Luna Parc', 'luna-parc', 'roadside-oddities', 41.25231, -74.78795, 'Sandyston Township', 'NJ', 'Artist Ricky Boscarino has spent decades transforming his home and studio into a fantastical mosaic-covered environment of towers, color, sculpture and found objects. Because Luna Parc is also a private residence, public access is limited to scheduled open-house events.', 'limited', null, 'https://www.lunaparc.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('M65 Atomic Cannon', 'm65-atomic-cannon', 'roadside-oddities', 41.5177, -90.54037, 'Rock Island Arsenal', 'IL', 'A surviving M65 ''Atomic Annie'' nuclear-capable artillery piece sits on the active arsenal as an outsized Cold War relic.', 'limited', null, 'https://www.aschq.army.mil/About/History/Tours/RIA/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Macoupin County ''Million Dollar'' Courthouse', 'macoupin-county-million-dollar-courthouse', 'roadside-oddities', 39.27894, -89.87927, 'Carlinville', 'IL', 'A lavish 1870 courthouse became notorious for enormous cost overruns that turned an ambitious civic project into a statewide symbol of excess.', 'limited', null, 'https://cityofcarlinville.com/tourism/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Madawaska Four Corners Park — Long-Distance Biker Shrine', 'madawaska-four-corners-park-long-distance-biker-shrine', 'roadside-oddities', 47.35596, -68.33242, 'Madawaska', 'ME', 'This unusual park marks the northeastern corner of a four-corners touring tradition for long-distance motorcyclists crossing the continental United States. Monuments, engraved pavers, and rider records commemorate travelers who complete enormous cross-country circuits linking Madawaska with the other recognized corners.', 'open', null, 'https://www.roadsideamerica.com/tip/29863', '2026-09-09T04:54:23.476824+00:00', null, 'https://madawaskafourcorners.org/', null, null, null, 'America/New_York'),
  ('Madison Blue Spring State Park', 'madison-blue-spring-state-park', 'roadside-oddities', 30.48031, -83.2447, 'Lee', 'FL', 'Deep blue first-magnitude spring feeding an extensive underwater cave system.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/madison-blue-spring-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Madison Boulder', 'madison-boulder', 'roadside-oddities', 43.93121, -71.16797, 'Madison', 'NH', 'Madison Boulder is an enormous glacial erratic carried and deposited by moving ice during the last Ice Age. The exposed granite block is roughly the size of a small building and has long been promoted as one of the largest known glacial erratics in New England. A short approach makes the scale easy to appreciate from ground level.', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/madison-boulder-natural-area', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Madonna of the Trail', 'madonna-of-the-trail', 'roadside-oddities', 38.98392, -77.09425, 'Bethesda', 'MD', 'Maryland''s Madonna of the Trail is one of 12 nearly identical pioneer-woman monuments installed across the country along the National Old Trails Road in 1928 and 1929. Dedicated in Bethesda in 1929, the massive stone figure has been moved several times as the surrounding downtown developed but remains publicly viewable beside Wisconsin Avenue.', 'open', null, 'https://highways.dot.gov/highway-history/general-highway-history/part-4-named-trails-us-numbered-highways/part-j', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Madonna, Queen of the Universe', 'madonna-queen-of-the-universe', 'roadside-oddities', 42.39052, -71.00501, 'Boston', 'MA', 'A roughly 40-foot statue of Mary stands on a globe above East Boston, created in the 1950s by the Don Orione religious order. The oversized shrine is an unexpected landmark near Logan Airport and includes additional devotional spaces and religious objects.', 'open', null, 'https://www.atlasobscura.com/places/madonna-queen-of-the-universe', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Magnolia Mound', 'magnolia-mound', 'roadside-oddities', 30.42965, -91.18894, 'Baton Rouge', 'LA', 'Magnolia Mound preserves a late-eighteenth-century Creole plantation house built with cypress and bousillage construction. Museum interpretation addresses the site''s architecture, material culture and enslaved labor.', 'limited', null, 'https://www.brec.org/facility/MagnoliaMound', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Maine State Building', 'maine-state-building', 'roadside-oddities', 44.0273, -70.36134, 'Poland', 'ME', 'This elaborate building was Maine’s pavilion at the 1893 World’s Columbian Exposition in Chicago. After the fair, it was dismantled, transported back to Maine by rail, and reconstructed at Poland Spring, where the former world’s-fair building still survives.', 'limited', null, 'https://www.atlasobscura.com/places/maine-state-building', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maine State Prison Showroom', 'maine-state-prison-showroom', 'roadside-oddities', 44.07756, -69.1915, 'Thomaston', 'ME', 'This unusual state-run showroom sells furniture, carved objects, toys, artwork, and other goods made by incarcerated people in Maine’s correctional system. The tradition dates back generations and makes the store far stranger than a typical roadside craft shop.', 'limited', null, 'https://www.atlasobscura.com/places/maine-state-prison-showroom', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Majestic Caverns', 'majestic-caverns', 'roadside-oddities', 33.30678, -86.27771, 'Childersburg', 'AL', 'Formerly known as DeSoto Caverns, this commercial cave features a huge main chamber, formations and a long history of human use. Cave tours are scheduled and ticketed, with current operating days varying through the year.', 'limited', null, 'https://majesticcaverns.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mama Shug — Shark Made of Plastic Trash', 'mama-shug-shark-made-of-plastic-trash', 'roadside-oddities', 42.04416, -70.21647, 'Provincetown', 'MA', 'A giant shark sculpture near Herring Cove Beach is assembled from plastic debris collected from beaches. Nicknamed Mama Shug, the creature turns marine trash into an oversized predator while making the scale of ocean pollution impossible to ignore.', 'open', null, 'https://www.atlasobscura.com/places/mama-shug', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mammoth Cave', 'mammoth-cave', 'roadside-oddities', 37.18699, -86.10049, 'Mammoth Cave', 'KY', 'Mammoth Cave National Park protects the longest known cave system on Earth, with hundreds of miles of surveyed passages beneath central Kentucky. Ranger-led tours range from enormous historic corridors to tight stair-filled cave routes, while the park above ground remains open without an entrance fee.', 'limited', null, 'https://www.nps.gov/maca/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.nps.gov/maca/', null, null, null, 'America/Chicago'),
  ('Mammy''s Cupboard', 'mammys-cupboard', 'roadside-oddities', 31.47801, -91.37129, 'Natchez', 'MS', 'A restaurant built in the form of a giant skirted woman, one of Mississippi''s most recognizable pieces of vernacular roadside architecture. The imagery and name reflect a racist "mammy" stereotype from the Jim Crow era, so the stop is best presented with that historical context rather than as neutral kitsch.', 'open', null, 'https://www.mammyscupboard.com/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Man in the Sea Museum', 'man-in-the-sea-museum', 'roadside-oddities', 30.23246, -85.8933, 'Panama City Beach', 'FL', 'Military diving museum where visitors can explore SEALAB I and decades of experimental undersea technology.', 'limited', null, 'https://www.maninthesea.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Manatee Springs State Park', 'manatee-springs-state-park', 'roadside-oddities', 29.48989, -82.9754, 'Chiefland', 'FL', 'Ancient spring system with underwater caves and seasonal manatee gatherings.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/manatee-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Manchac Swamp Bridge', 'manchac-swamp-bridge', 'roadside-oddities', 30.30295, -90.40581, 'Manchac', 'LA', 'Interstate 55 crosses miles of cypress swamp on one of the longest bridge structures in the United States. The experience is the drive itself; never stop on the interstate or attempt to access bridge infrastructure.', 'roadside', null, 'https://www.fhwa.dot.gov/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Maniac — Indian Death Tiki of Awesomeness', 'maniac-indian-death-tiki-of-awesomeness', 'roadside-oddities', 35.51401, -83.12958, 'Maggie Valley', 'NC', 'A roughly 16-foot carved skeletal warrior stands outside Soco Cycles with huge teeth, empty eye sockets, a feathered headdress, and an oversized club. The deliberately monstrous carving has become one of Maggie Valley’s most unmistakable roadside figures.', 'roadside', null, 'https://www.roadsideamerica.com/story/42403', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Manning Memorial Lighthouse', 'manning-memorial-lighthouse', 'roadside-oddities', 44.8143, -86.06725, 'Empire', 'MI', 'This small working lighthouse was completed in 1991 as a memorial to local fisherman Robert H. Manning, who had long wanted a light in Empire. It stands in a public lakeside park and operates seasonally as a private aid to navigation rather than as a traditional staffed lighthouse.', 'open', null, 'https://www.atlasobscura.com/places/manning-memorial-lighthouse', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Mapparium Globe', 'mapparium-globe', 'roadside-oddities', 42.34546, -71.08685, 'Boston', 'MA', 'A three-story stained-glass globe built in 1935 lets visitors walk through the center of a frozen-in-time world map. Because the political boundaries were never updated, countries such as Siam and the Soviet Union remain on the glass, while the sphere''s acoustics create a dramatic whispering-gallery effect.', 'limited', null, 'https://www.marybakereddylibrary.org/visit/', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.christianscience.com/find-us/visit-the-mother-church/mapparium', null, null, null, 'America/New_York'),
  ('Marengo Cave', 'marengo-cave', 'roadside-oddities', 38.37552, -86.3395, 'Marengo', 'IN', 'Discovered by children in 1883, Marengo Cave grew into one of Indiana''s best-known commercial cave systems and is designated a U.S. National Natural Landmark. Guided routes take visitors through large underground rooms and extensive formations while preserving a very old-school roadside cave-attraction feel.', 'limited', null, 'https://www.marengocave.com/', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.marengocave.com/', null, null, null, 'America/Indiana/Marengo'),
  ('Margaret''s Grocery', 'margarets-grocery', 'roadside-oddities', 32.41094, -90.84218, 'Vicksburg', 'MS', 'The visionary-art environment created by Reverend H.D. Dennis around Margaret Rogers Dennis''s former grocery store, covered with hand-built towers, signs, painted masonry and religious messages. The site is undergoing preservation work and should not be treated as freely open; arrange access where required and respect barriers.', 'limited', null, 'https://spacesarchives.org/explore/search-the-online-collection/margarets-grocery/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mars Cheese Castle', 'mars-cheese-castle', 'roadside-oddities', 42.61461, -87.95444, 'Kenosha', 'WI', 'This castle-shaped cheese shop near I-94 combines Wisconsin food culture with deliberately oversized roadside architecture. Turrets, a throne, cheese displays and a gift-heavy interior make it much more than a normal highway store.', 'open', null, 'https://www.marscheese.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.marscheese.com/', null, null, null, 'America/Chicago'),
  ('Mars Flying Saucer', 'mars-flying-saucer', 'roadside-oddities', 40.69615, -80.01032, 'Mars', 'PA', 'Mars embraces its name with a nearly 3,000-pound flying-saucer sculpture assembled from industrial tanks and displayed downtown. The statue was already documented by 1989 and has become one of Butler County''s recognizable roadside landmarks, sitting in a public downtown space for easy photographs.', 'open', null, 'https://www.atlasobscura.com/places/mars-flying-saucer', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Martian Brick Head', 'martian-brick-head', 'roadside-oddities', 34.009, -81.021, 'Columbia', 'SC', 'A brick building sprouts an enormous three-dimensional face assembled directly into its masonry. The strange expression and exaggerated features make the head look as though a giant stone creature is pushing outward through the wall.', 'roadside', null, 'https://www.roadsideamerica.com/tip/63982', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Martin Luther Statue', 'martin-luther-statue', 'roadside-oddities', 35.74143, -81.32622, 'Hickory', 'NC', 'A 12-foot granite Martin Luther stands on the campus of Lenoir-Rhyne University atop an additional four-foot pedestal. Atlas Obscura describes it as the largest stone statue of Luther in North America, giving the campus an unexpectedly monumental Reformation landmark.', 'open', null, 'https://www.atlasobscura.com/places/the-martin-luther-statue', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Martini-Drinking Pink Elephant', 'martini-drinking-pink-elephant', 'roadside-oddities', 39.92987, -85.85252, 'Fortville', 'IN', 'A huge pink elephant holding a martini glass sits on a trailer outside a Fortville beverage business, turning the old "seeing pink elephants" expression into literal advertising. The statue is occasionally moved for parades but normally serves as one of central Indiana''s most unmistakable roadside photo stops.', 'roadside', null, 'https://visitindiana.in.gov/blog/post/roadside-attractions/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Martini Junction', 'martini-junction', 'roadside-oddities', 42.26898, -71.24728, 'Needham', 'MA', 'A tiny railroad junction complete with miniature signs appears along a wooded trail, built around a small-scale railway installation. The unexpected infrastructure feels like stumbling across a functioning transportation system for woodland creatures.', 'open', null, 'https://www.atlasobscura.com/places/martini-junction', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Marty the Musky', 'marty-the-musky', 'roadside-oddities', 46.11131, -89.64668, 'Boulder Junction', 'WI', 'Boulder Junction''s giant musky statue celebrates the community''s self-proclaimed status as the Musky Capital of the World. The fish stands in town as a public landmark and a compact stop for Wisconsin''s obsession with oversized freshwater creatures.', 'open', null, 'https://boulderjct.org/why-is-boulder-junction-the-musky-capital-of-the-world/', '2026-09-09T13:02:00.307533+00:00', null, 'https://boulderjct.org/', null, null, null, 'America/Chicago'),
  ('Mary Nohl Art Environment', 'mary-nohl-art-environment', 'roadside-oddities', 43.15659, -87.89076, 'Fox Point', 'WI', 'Artist Mary Nohl transformed her lakeside property with concrete figures, painted surfaces, sculptures and handmade objects until the entire home became an art environment. The property is preserved but not a normal walk-in attraction; view only from lawful public areas unless attending an authorized program.', 'limited', null, 'https://www.spacesarchives.org/explore/search-the-online-collection/mary-nohl-art-environment/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.jmkac.org/', null, null, null, 'America/Chicago'),
  ('Mary’s Gone Wild', 'marys-gone-wild', 'roadside-oddities', 33.93461, -78.29365, 'Supply', 'NC', 'Artist Mary Paulsen transformed her property into a dense environment of bottle houses, painted figures, dolls, recycled materials, signs, shrines, and handmade structures. The result is an intensely personal piece of outsider art that looks unlike almost anything else along the North Carolina coast. Location reference: https://www.strangecarolinas.com/', 'limited', null, 'https://www.roadsideamerica.com/tip/6636', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mary''s River Covered Bridge', 'marys-river-covered-bridge', 'roadside-oddities', 37.94861, -89.76583, 'Chester', 'IL', 'A rare 1854 covered bridge survives outside Chester, carrying pedestrians through a timber Burr-arch truss over the old Mary''s River channel.', 'open', null, 'https://www.chesterill.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Maxie, The World''s Largest Goose', 'maxie-the-world-s-largest-goose', 'roadside-oddities', 39.652974, -93.24626, 'Sumner', 'MO', 'Maxie is in Sumner, not Brookfield. Sculptor David Jackson built the 40-foot-tall, 62-foot-wingspan Canada goose in 1974 and it was formally dedicated October 30, 1975; today the fiberglass-and-steel bird stands in a public park and can pivot with the wind.', 'roadside', null, 'https://www.roadsideamerica.com/story/7248', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mayna Treanor Avent Studio', 'mayna-treanor-avent-studio', 'roadside-oddities', 35.63795, -83.58599, 'Gatlinburg', 'TN', 'Artist Mayna Treanor Avent used a small Appalachian cabin as a studio, preserving a rare combination of vernacular mountain architecture and early Smokies art history. Reaching the site requires trail access and conditions can vary.', 'limited', null, 'https://www.atlasobscura.com/places/mayna-treanor-avent-studio', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('McCourtie Park Concrete Bridges', 'mccourtie-park-concrete-bridges', 'roadside-oddities', 42.0528, -84.4094, 'Somerset Center', 'MI', 'In the 1930s, Mexican artisans built a series of bridges and structures from sculpted concrete carefully shaped and painted to resemble logs, ropes and rustic woodwork. The surreal faux-timber bridges now form the centerpiece of a public park on the former McCourtie estate.', 'open', null, 'https://www.atlasobscura.com/places/mccourtie-park', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Medieval Times Castle', 'medieval-times-castle', 'roadside-oddities', 28.32042, -81.48984, 'Kissimmee', 'FL', 'Full-scale roadside castle housing a long-running jousting dinner show.', 'limited', null, 'https://www.medievaltimes.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Melrose Plantation', 'melrose-plantation', 'roadside-oddities', 31.59998, -92.96574, 'Melrose', 'LA', 'Melrose developed from a complex Creole community and later became an arts center associated with Clementine Hunter, whose murals survive in the African House. Guided access links plantation history, architecture and outsider art in one site.', 'limited', null, 'https://www.melroseonthecane.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Memorial Arch of Tilton', 'memorial-arch-of-tilton', 'roadside-oddities', 43.44049, -71.58881, 'Northfield', 'NH', 'Industrialist Charles E. Tilton built this massive Roman-style stone arch as a memorial to his ancestors. It stands high above the Winnipesaukee River and looks wildly oversized for the rural hilltop around it. A short trail leads visitors to the monument and surrounding views.', 'open', null, 'https://www.atlasobscura.com/places/memorial-arch-of-tilton', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Memory Wall of Love and Peace', 'memory-wall-of-love-and-peace', 'roadside-oddities', 36.09903, -80.24568, 'Winston-Salem', 'NC', 'Artist Gregory Warmack, better known as Mr. Imagination, created this community folk-art wall from concrete, found objects, personal keepsakes, and sculpted figures. After years of deterioration, the installation was extensively restored and remains an unusual public memorial built partly from objects contributed by local residents.', 'open', null, 'https://www.atlasobscura.com/places/memory-wall-of-love-and-peace', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Memphis Chess Club', 'memphis-chess-club', 'roadside-oddities', 35.14397, -90.05008, 'Memphis', 'TN', 'One of the country''s historic chess organizations operates a downtown clubhouse centered on casual play, tournaments and chess culture. It gives travelers a niche social-history stop in a city better known for music and food.', 'open', null, 'https://www.memphischessclub.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Memphis Gong Chamber', 'memphis-gong-chamber', 'roadside-oddities', 35.12176, -89.99064, 'Memphis', 'TN', 'A private sound space built around large gongs offers immersive vibration and resonance sessions unlike a conventional concert. Visits are appointment-based, so travelers should never expect walk-in access.', 'limited', null, 'https://www.atlasobscura.com/places/memphis-gong-chamber', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Memphis Listening Lab', 'memphis-listening-lab', 'roadside-oddities', 35.15214, -90.01559, 'Memphis', 'TN', 'Thousands of records, CDs, books and music-related materials form a public listening library where visitors can actually hear much of the collection. The emphasis on deep listening rather than retail makes it an unusually hands-on archive of recorded sound.', 'open', null, 'https://memphislisteninglab.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Menz Restaurant & Bar Oddities', 'menz-restaurant-bar-oddities', 'roadside-oddities', 39.03737, -74.91993, 'Rio Grande', 'NJ', 'Menz surrounds diners with decades of accumulated roadside kitsch, taxidermy and unusual objects. Among its best-known curiosities are a two-headed calf and an eccentric statue honoring the restaurant''s one-legged founder.', 'open', null, 'https://www.roadsideamerica.com/story/2023', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mepkin Abbey Oak-Wood Sculptures', 'mepkin-abbey-oak-wood-sculptures', 'roadside-oddities', 33.11596, -79.95091, 'Moncks Corner', 'SC', 'The public grounds of this working Trappist monastery contain a series of unusual oak-wood sculptures incorporated into the abbey landscape. Mepkin''s own visitor map identifies the sculptures as a point of interest alongside its gardens, cemeteries, labyrinth and historic sites. The coordinates route to the Reception Center parking area; visitors should obtain a map there and respect all areas marked for monastic or limited access.', 'limited', null, 'https://www.mepkinapp.org/virtual-tour/', '2026-09-09T05:53:13.784429+00:00', null, 'https://mepkinabbey.org/day-visits/', null, null, null, 'America/New_York'),
  ('Mepkin Abbey Tree Carvings', 'mepkin-abbey-tree-carvings', 'roadside-oddities', 33.11534, -79.94447, 'Moncks Corner', 'SC', 'The grounds of this Trappist monastery contain large sculptural figures carved directly from dead or damaged trees. Faces, religious imagery, and other forms emerge from trunks around the property, adding an unexpected folk-art layer to the quiet abbey landscape. Oddity listing: https://www.roadsideamerica.com/location/sc/all', 'limited', null, 'https://mepkinabbey.org/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mercury Cougar Statue', 'mercury-cougar-statue', 'roadside-oddities', 38.8266, -76.9261, 'Temple Hills', 'MD', 'This enormous fiberglass cougar survives from the days when the property operated as a Lincoln-Mercury dealership. Once mounted on the roof, the 1960s advertising cat now sits at ground level near the dealership and is easily visible from the public-facing commercial area.', 'roadside', null, 'https://www.roadsideamerica.com/tip/46420', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Metal Dinosaur and Big Chicken', 'metal-dinosaur-and-big-chicken', 'roadside-oddities', 40.58535, -86.6751, 'Delphi', 'IN', 'A homemade metal dinosaur stands outside a rural Delphi property alongside an oversized fiberglass rooster. The mismatched pair gives travelers two classic forms of roadside folk art—scrap-metal sculpture and reused commercial fiberglass—in one stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/75392', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Metal T-Rex and TV Characters', 'metal-t-rex-and-tv-characters', 'roadside-oddities', 38.62122, -75.198, 'Millsboro', 'DE', 'A homemade roadside menagerie led by a large scrap-metal Tyrannosaurus rex, accompanied by pop-culture and television-inspired figures. Recent traveler reports still place the sculptures along DE-24 east of Millsboro.', 'roadside', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Metalmorphosis — Giant Moving Head', 'metalmorphosis-giant-moving-head', 'roadside-oddities', 35.1511, -80.9477, 'Charlotte', 'NC', 'Czech artist David Černý created this enormous stainless-steel human head from multiple horizontal layers that independently rotate. As the sections move, the face repeatedly breaks apart into abstract forms and then reassembles. Official property information: https://www.whitehallcorporatecenter.com/metalmorphosis', 'open', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mice Manor', 'mice-manor', 'roadside-oddities', 42.54227, -70.88483, 'Beverly', 'MA', 'Inside a Beverly artisan shop is an elaborate black dollhouse populated by taxidermied mice dressed as horror and pop-culture characters. Residents have included miniature versions of Lizzie Borden, Norman Bates and Buffalo Bill, and the tiny cast changes as individual pieces are sold.', 'open', null, 'https://www.atlasobscura.com/places/mice-manor', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mice on Main Street', 'mice-on-main-street', 'roadside-oddities', 34.85202, -82.39998, 'Greenville', 'SC', 'Nine tiny bronze mice are hidden along several blocks of downtown Greenville’s Main Street. The sculptures were inspired by the children’s book Goodnight Moon and create a miniature scavenger hunt that rewards travelers for paying attention to curbs, planters, and storefronts.', 'open', null, 'https://www.atlasobscura.com/places/mice-on-main-street', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mighty Joe the Gorilla', 'mighty-joe-the-gorilla', 'roadside-oddities', 39.81017, -74.73678, 'Shamong Township', 'NJ', 'A giant fiberglass gorilla towers over Route 206 outside Mighty Joe''s Gas, gripping a sign high above passing traffic. The old-school roadside figure is part of the American tradition of oversized advertising statues and has become a recognizable Pine Barrens landmark.', 'roadside', null, 'https://www.atlasobscura.com/places/mighty-joe-the-gorilla', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mike the Tiger Habitat', 'mike-the-tiger-habitat', 'roadside-oddities', 30.41342, -91.18507, 'Baton Rouge', 'LA', 'LSU''s live tiger mascot inhabits a large landscaped enclosure beside Tiger Stadium. The habitat is a public-facing university landmark, but visitors should respect animal-care barriers and any temporary closure notices.', 'open', null, 'https://www.mikethetiger.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mile High Swinging Bridge', 'mile-high-swinging-bridge', 'roadside-oddities', 36.09505, -81.83224, 'Linville', 'NC', 'A suspension footbridge stretches across an exposed gap near the summit of Grandfather Mountain at roughly a mile above sea level. Wind and elevation make the crossing feel far more dramatic than its modest length suggests.', 'limited', null, 'https://grandfather.com/mile-high-swinging-bridge/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Miles the Monster', 'miles-the-monster', 'roadside-oddities', 39.18839, -75.52692, 'Dover', 'DE', 'Dover Motor Speedway''s enormous concrete mascot erupts from the ground clutching a full-size race car in one hand. The snarling figure is one of Delaware''s largest and most recognizable roadside monsters.', 'open', null, 'https://www.atlasobscura.com/places/miles-the-monster', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.dovermotorspeedway.com/', null, null, null, 'America/New_York'),
  ('Milford Irish Round Tower', 'milford-irish-round-tower', 'roadside-oddities', 42.15637, -71.50831, 'Milford', 'MA', 'A tall pink-granite tower modeled after medieval Irish round towers rises unexpectedly from St. Mary''s Cemetery. Built as a memorial to local Irish immigrants, it gives the cemetery the silhouette of an ancient monastic site transplanted into Massachusetts.', 'open', null, 'https://www.atlasobscura.com/places/milford-irish-round-tower', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Milford Swing Bridge', 'milford-swing-bridge', 'roadside-oddities', 42.83655, -71.64569, 'Milford', 'NH', 'A narrow iron suspension footbridge crosses the Souhegan River in Milford, swaying noticeably as pedestrians move across it. The current bridge dates to the nineteenth century and feels more like a miniature Victorian suspension bridge than a typical town walkway. It remains a pedestrian crossing, so visitors can experience the movement directly.', 'open', null, 'https://www.atlasobscura.com/places/the-swing-bridge', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mill Bluff State Park', 'mill-bluff-state-park', 'roadside-oddities', 43.94108, -90.31902, 'Camp Douglas', 'WI', 'Steep sandstone buttes rise from otherwise flat terrain, remnants of ancient sea stacks that became dramatic landmarks along today''s interstate corridor. A staircase climbs Mill Bluff for a view across the strange isolated formations.', 'open', null, 'https://dnr.wisconsin.gov/topic/parks/millbluff', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/topic/parks/millbluff', null, null, null, 'America/Chicago'),
  ('Millennium Manor', 'millennium-manor', 'roadside-oddities', 35.78, -83.965, 'Alcoa', 'TN', 'Built largely from stone in the 1930s, Millennium Manor was intended by its creators to survive catastrophic events and even the biblical apocalypse. It remains private property, making the strange survivalist house an exterior-only roadside curiosity unless the owner explicitly offers access.', 'private', null, 'https://www.atlasobscura.com/places/millennium-manor', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Million Dollar Birdhouse Wall', 'million-dollar-birdhouse-wall', 'roadside-oddities', 45.14011, -69.94844, 'Moscow', 'ME', 'More than a hundred imaginative birdhouses line a long roadside display north of Moscow. They are constructed in an array of shapes and materials, turning an otherwise remote stretch of U.S. Route 201 into an unexpectedly elaborate folk-art installation.', 'roadside', null, 'https://www.atlasobscura.com/places/roadside-birdhouses-of-moscow-maine', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Milwaukee Art Museum — Quadracci Pavilion', 'milwaukee-art-museum-quadracci-pavilion', 'roadside-oddities', 43.03918, -87.89707, 'Milwaukee', 'WI', 'Santiago Calatrava''s lakefront pavilion is topped by a movable brise soleil whose enormous white wings open and close over the building. The kinetic architecture turns a major art museum into a mechanical landmark.', 'open', null, 'https://mam.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://mam.org/', null, null, null, 'America/Chicago'),
  ('Mini Lincoln Meets Harriet Beecher Stowe', 'mini-lincoln-meets-harriet-beecher-stowe', 'roadside-oddities', 41.76521, -72.66715, 'Hartford', 'CT', 'Miniature bronze versions of Abraham Lincoln and Harriet Beecher Stowe face one another across an outdoor table on the riverwalk. The sculpture commemorates their real 1862 meeting but intentionally presents the famously tall Lincoln at a surprisingly tiny scale.', 'open', null, 'https://www.roadsideamerica.com/story/48207', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Miniature Castles of South Hero', 'miniature-castles-of-south-hero', 'roadside-oddities', 44.64532, -73.30235, 'South Hero', 'VT', 'A collection of small stone castles, towers and miniature architectural structures is scattered around South Hero. Many sit on or near private property, so they are best treated as a roadside viewing hunt rather than places to enter or explore closely.', 'private', null, 'https://www.atlasobscura.com/places/miniature-castles-of-south-hero', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Minnie Evans Bottle Chapel', 'minnie-evans-bottle-chapel', 'roadside-oddities', 34.2143, -77.8244, 'Wilmington', 'NC', 'At the Minnie Evans Sculpture Garden, a chapel-like structure made from colored bottles, cement, and found material honors visionary artist Minnie Evans. Sunlight passing through the bottles gives the small structure a stained-glass effect unlike a conventional garden sculpture.', 'limited', null, 'https://www.cameronartmuseum.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Minnie Pearl Chicken-Wire Statue', 'minnie-pearl-chicken-wire-statue', 'roadside-oddities', 35.77867, -87.46685, 'Centerville', 'TN', 'A folk-art portrait of comedian Minnie Pearl uses chicken wire and other humble materials to honor the Centerville native. The intentionally homespun construction suits the public persona that made her a Grand Ole Opry icon.', 'open', null, 'https://www.atlasobscura.com/places/minnie-pearl-chicken-wire-statue', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Miracle Survivor Mary Statue', 'miracle-survivor-mary-statue', 'roadside-oddities', 41.57138, -72.33705, 'Colchester', 'CT', 'A statue of Mary survived a 2004 explosion and fire that destroyed the former St. Mary''s Ukrainian Catholic Church around it. The congregation preserved the surviving figure at the rebuilt church as a physical reminder of the disaster.', 'open', null, 'https://www.roadsideamerica.com/tip/9620', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Miss Pearl Giant Alligator', 'miss-pearl-giant-alligator', 'roadside-oddities', 30.37665, -89.74823, 'Pearl River', 'LA', 'A giant alligator sculpture named Miss Pearl sits outside a Pearl River business and gives the Honey Island area an appropriately oversized roadside mascot. It is a quick exterior photo stop; stay within customer or public access areas.', 'roadside', null, 'https://www.roadsideamerica.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mission Creep Fire Hydrant', 'mission-creep-fire-hydrant', 'roadside-oddities', 41.25887, -72.89824, 'New Haven', 'CT', 'A cast-iron sculpture outside Lighthouse Fire Station began as a tribute to firefighters and gradually accumulated more symbolic details, including an oversized hydrant. The finished piece is part monument and part wonderfully overbuilt firehouse lawn art.', 'roadside', null, 'https://www.roadsideamerica.com/story/68758', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mission Nombre de Dios Great Cross', 'mission-nombre-de-dios-great-cross', 'roadside-oddities', 29.90571, -81.3155, 'St. Augustine', 'FL', 'A 208-foot stainless-steel cross towers over the historic mission grounds.', 'limited', null, 'https://missionandshrine.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Modern Diner', 'modern-diner', 'roadside-oddities', 41.86883, -71.38688, 'Pawtucket', 'RI', 'This streamlined stainless-steel diner is a surviving 1940 Sterling Streamliner and became the first diner placed on the National Register of Historic Places. Its rounded, locomotive-like exterior looks more like a retro-futurist railcar than a conventional restaurant. It remains open for breakfast and lunch.', 'open', null, 'https://www.atlasobscura.com/places/modern-diner', '2026-09-09T04:49:27.913704+00:00', null, 'https://moderndinerri.com/', null, null, null, 'America/New_York'),
  ('Modica Way', 'modica-way', 'roadside-oddities', 42.36487, -71.10224, 'Cambridge', 'MA', 'A narrow Central Square passage has become a constantly changing legal graffiti gallery. One wall is regularly repainted by street artists, turning the alley into an artwork that may look completely different every time OddWay sends someone through.', 'open', null, 'https://www.atlasobscura.com/places/modica-way', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mohegan Sun Walk of Fame', 'mohegan-sun-walk-of-fame', 'roadside-oddities', 41.49185, -72.09084, 'Uncasville', 'CT', 'Blue stars embedded around the Mohegan Sun Arena entrance commemorate performers who have appeared at the casino resort. The casino''s take on a Hollywood-style walk of fame has steadily accumulated names over the years.', 'open', null, 'https://www.roadsideamerica.com/tip/5169', '2026-09-08T19:51:22.001704+00:00', null, 'https://mohegansun.com/', null, null, null, 'America/New_York'),
  ('Monkey Island', 'monkey-island', 'roadside-oddities', 28.78694, -82.61555, 'Homosassa', 'FL', 'Tiny island in the Homosassa River long inhabited by a colony of spider monkeys.', 'roadside', null, 'https://www.monkeyislandhomosassa.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Monona Terrace Community and Convention Center', 'monona-terrace-community-and-convention-center', 'roadside-oddities', 43.07143, -89.37982, 'Madison', 'WI', 'Frank Lloyd Wright first proposed a civic center for this lakefront site in the 1930s, but the completed building did not open until 1997, decades after his death. The sweeping structure and public rooftop preserve a rare posthumously realized Wright concept.', 'open', null, 'https://www.mononaterrace.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.mononaterrace.com/', null, null, null, 'America/Chicago'),
  ('Monsieur Jacques Frog Statue', 'monsieur-jacques-frog-statue', 'roadside-oddities', 30.24838, -92.26989, 'Rayne', 'LA', 'A giant tuxedoed frog tips his hat in the town that calls itself the Frog Capital of the World. The statue is an easy public photo stop and a strong visual anchor for Rayne''s frog-themed identity.', 'open', null, 'https://www.rayne.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Monster of Unfathomable Pedigree', 'monster-of-unfathomable-pedigree', 'roadside-oddities', 43.90695, -69.82946, 'Bath', 'ME', 'This strange red creature is assembled from salvaged metal and found objects, producing something between a dragon, mechanical beast, and junkyard monster. It sits where passing travelers can get a look without needing a full museum stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/25676', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Montague Bookmill', 'montague-bookmill', 'roadside-oddities', 42.5378, -72.5389, 'Montague', 'MA', 'A used-book store fills a nineteenth-century gristmill beside the rushing Sawmill River. Its famously fatalistic slogan — ''Books you don''t need in a place you can''t find'' — fits the maze of shelves, old machinery and riverside rooms.', 'open', null, 'https://www.montaguebookmill.com/', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Monte Casino Chapel', 'monte-casino-chapel', 'roadside-oddities', 39.02157, -84.56867, 'Crestview Hills', 'KY', 'Two Benedictine monks built this tiny fieldstone chapel in the late nineteenth century, and Ripley''s Believe It or Not later promoted it as an exceptionally small church. The entire building was moved to what is now Thomas More University, where it sits beside a pond near the campus entrance.', 'open', null, 'https://www.crestviewhills.gov/Archive.aspx?ADID=139', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Montgomery Bell Tunnel', 'montgomery-bell-tunnel', 'roadside-oddities', 36.14694, -87.12194, 'Kingston Springs', 'TN', 'Industrialist Montgomery Bell had enslaved laborers cut a tunnel through rock in the early nineteenth century to divert water for an ironworks. The short stone passage survives inside Harpeth River State Park as an unusually visible remnant of early industrial engineering and coerced labor.', 'open', null, 'https://tnstateparks.com/parks/harpeth-river', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Monument of States', 'monument-of-states', 'roadside-oddities', 28.29174, -81.40702, 'Kissimmee', 'FL', '1940s tower built from rocks and objects sent from every U.S. state and many foreign countries.', 'roadside', null, 'https://www.kissimmee.gov/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Monument to a Century of Flight', 'monument-to-a-century-of-flight', 'roadside-oddities', 36.09667, -75.71569, 'Kitty Hawk', 'NC', 'Hidden surprisingly well among trees near the Outer Banks visitor center, fourteen stainless-steel wing-shaped pylons commemorate one hundred major moments in aviation. The installation also contains a bronze globe, the poem “High Flight,” and a time capsule intended to remain sealed until 2103.', 'open', null, 'https://www.atlasobscura.com/places/monument-to-a-century-of-flight', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Morgan Island — “Monkey Island”', 'morgan-island-monkey-island', 'roadside-oddities', 32.47741, -80.51955, 'Morgan Island', 'SC', 'Thousands of free-ranging rhesus macaques live on this isolated Lowcountry island, earning it the nickname Monkey Island. The colony exists for research purposes, and the island is not open to public landing; travelers should view it only legally from the water and keep their distance.', 'roadside', null, 'https://www.atlasobscura.com/places/morgan-island', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moriarty Monument', 'moriarty-monument', 'roadside-oddities', 29.9825, -90.1145, 'New Orleans', 'LA', 'This towering monument in Metairie Cemetery was commissioned by Mary Moriarty in memory of her husband and rises dramatically above neighboring tombs. Its scale makes it one of the cemetery''s easiest landmarks to recognize.', 'limited', null, 'https://www.lakelawnmetairie.com/cemetery/metairie-cemetery', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Morris the Horse', 'morris-the-horse', 'roadside-oddities', 35.20865, -82.23823, 'Tryon', 'NC', 'A giant fiberglass horse has represented Tryon’s equestrian and toy-making history for generations. The original wooden Morris was created for a 1928 horse show; the current figure is the fourth version after earlier horses met unusually destructive ends. Local source: https://exploretryon.com/business-listings/morris-the-horse/', 'open', null, 'https://www.atlasobscura.com/places/morris-the-horse', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mortar Man', 'mortar-man', 'roadside-oddities', 38.34931, -81.63556, 'Charleston', 'WV', 'High on a downtown Charleston wall is an absurdly tiny human figure only a few inches tall, installed in a mortar joint by artist P. Joseph Mullins. It is around twelve feet above street level and intended to be spotted from the public sidewalk rather than approached or climbed toward.', 'roadside', null, 'https://www.atlasobscura.com/places/mortar-man', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mother Goose House', 'mother-goose-house', 'roadside-oddities', 37.27275, -83.19301, 'Hazard', 'KY', 'George Stacy built this circular stone home beneath the enormous body of a goose beginning in the 1930s. The bird''s eyes were made from automobile headlights and still illuminate, but the structure remains a private residence and should only be admired from the public roadside.', 'private', null, 'https://www.atlasobscura.com/places/mother-goose-house', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Desert Spring Blues Brothers', 'mount-desert-spring-blues-brothers', 'roadside-oddities', 44.28867, -68.33049, 'Southwest Harbor', 'ME', 'Life-size figures of Jake and Elwood Blues stand unexpectedly outside a water-bottling facility on Mount Desert Island. The sunglasses, suits, and deadpan poses make the pair an easy-to-spot piece of roadside pop-culture weirdness.', 'roadside', null, 'https://www.atlasobscura.com/places/blues-brothers', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Greylock War Memorial Tower', 'mount-greylock-war-memorial-tower', 'roadside-oddities', 42.63758, -73.16622, 'Adams', 'MA', 'Massachusetts'' highest summit is crowned by a 93-foot granite war memorial tower shaped like an austere lighthouse. The beacon and mountaintop setting make it look almost otherworldly above the Berkshires. Summit-road access is seasonal, while hiking access depends on current trail and weather conditions.', 'limited', null, 'https://www.atlasobscura.com/places/mount-greylock', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Trashmore', 'mount-trashmore', 'roadside-oddities', 36.83096, -76.12425, 'Virginia Beach', 'VA', 'Virginia Beach converted an abandoned landfill into this 165-acre public park beginning in the 1970s, covering compacted layers of trash with soil to form its signature artificial hills. What was once a dump is now a landscaped recreation area with trails, playgrounds, lakes and one of the most literal odd-place names in the state.', 'open', null, 'https://parks.virginiabeach.gov/outdoors/city-parks/mount-trashmore-park', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mount Wood Castle and Cemetery', 'mount-wood-castle-and-cemetery', 'roadside-oddities', 40.08042, -80.72227, 'Wheeling', 'WV', 'This unfinished stone mansion above Wheeling was begun in the 1920s by a physician whose grand plans collapsed after legal trouble, leaving a castle-like shell overlooking the Ohio Valley. The city-owned Mount Wood Cemetery and overlook can be visited, but the deteriorating ruins and steep overgrown areas should be treated as look-don''t-climb features.', 'limited', null, 'https://www.atlasobscura.com/places/mount-wood-castle-and-cemetery', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moxie Bottle House', 'moxie-bottle-house', 'roadside-oddities', 44.21427, -69.28451, 'Union', 'ME', 'A roughly 32-foot-tall wooden bottle shaped like Maine’s famously divisive Moxie soda stands at the Union Fairgrounds. The structure was originally created as a promotional building for the 1906 New England Food Fair before eventually being preserved in Maine.', 'limited', null, 'https://www.atlasobscura.com/places/moxie-bottle-house', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moxie — Manhole Mastodon', 'moxie-manhole-mastodon', 'roadside-oddities', 43.23408, -86.25215, 'Muskegon', 'MI', 'A life-size bronze mastodon with bright blue tusks appears to climb out of an enormous manhole outside the Muskegon Museum of History and Science. Unveiled in 2019, the sculpture gives Michigan''s official state fossil a deliberately impossible return to the streets of downtown Muskegon.', 'open', null, 'https://www.roadsideamerica.com/tip/83011', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Mr. Bendo Muffler Man', 'mr-bendo-muffler-man', 'roadside-oddities', 39.78887, -86.18398, 'Indianapolis', 'IN', 'Mr. Bendo is a towering fiberglass Muffler Man that has served as an Indianapolis auto-shop landmark for decades. The giant figure has survived moves, repairs and changing businesses and remains a recognizable piece of classic American roadside advertising on West 16th Street.', 'roadside', null, 'https://fotospot.com/attractions/indiana/mr-bendo-muffler-man', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Mr. Peanut Statue — Suffolk Visitor Center', 'mr-peanut-statue-suffolk-visitor-center', 'roadside-oddities', 36.73745, -76.58227, 'Suffolk', 'VA', 'Mr. Peanut''s familiar character traces back to a 1916 Planters logo contest won by a young Suffolk-area boy, linking the advertising icon directly to the city''s peanut history. A Mr. Peanut statue at the Suffolk Visitor Center gives travelers an easy public photo stop while the center interprets Suffolk''s broader agricultural story.', 'open', null, 'https://www.visitsuffolkva.com/itineraries/all-about-mr-peanut-itinerary/', '2026-09-08T04:17:48.352537+00:00', null, 'https://www.visitsuffolkva.com/', null, null, null, 'America/New_York'),
  ('Mrs. Skipper — Rhode Island Troll Trail', 'mrs-skipper-rhode-island-troll-trail', 'roadside-oddities', 41.79588, -71.37996, 'East Providence', 'RI', 'Mrs. Skipper is the easternmost member of Rhode Island''s five-troll Thomas Dambo trail and sits near Kettle Point in East Providence. The oversized figure was completed in 2025 from reclaimed materials and expanded the project beyond South County. It is free to visit and intended as an interactive outdoor artwork rather than a climbing structure.', 'open', null, 'https://www.southcountyri.com/thomas-dambo-trolls/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mt. Atlanticus Minotaur Goff', 'mt-atlanticus-minotaur-goff', 'roadside-oddities', 33.69337, -78.88364, 'Myrtle Beach', 'SC', 'A giant minotaur-like figure named Goff presides over the wildly themed Mt. Atlanticus miniature golf complex. Its mythological creatures, faux ruins, towers, and rooftop course turn a beach-town mini-golf stop into a deliberately surreal environment.', 'open', null, 'https://www.atlasobscura.com/places/mt-atlanticus-minotaur-goff', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mud Island River Park', 'mud-island-river-park', 'roadside-oddities', 35.1529, -90.0575, 'Memphis', 'TN', 'The park contains a long-scale model of the lower Mississippi River that visitors can physically walk alongside. The concrete Riverwalk turns hundreds of miles of geography into an oversized outdoor map and is most practical during normal park operating periods.', 'limited', null, 'https://www.memphisriverparks.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Joor Muffler Man', 'muffler-man', 'roadside-oddities', 33.124128, -117.079365, 'Escondido', 'CA', 'This is the Joor Muffler Man, a classic oversized fiberglass roadside figure associated with Joor Muffler in Escondido. Escondido tourism material dates the figure to 1969, and travelers still find the giant as a piece of old-school roadside Americana outside the business.', 'roadside', null, 'https://visitescondido.com/info/maps-getting-around/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Museum of Modern Renaissance', 'museum-of-modern-renaissance', 'roadside-oddities', 42.39991, -71.11803, 'Somerville', 'MA', 'Two artists transformed a former Masonic hall into a floor-to-ceiling ''Temple of Art'' covered with mythological figures, geometric patterns and intensely colored murals. Public access is event-based or arranged rather than conventional daily museum hours.', 'limited', null, 'https://www.atlasobscura.com/places/museum-of-modern-renaissance', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Museum of Science & History — Pink Palace Mansion', 'museum-of-science-history-pink-palace-mansion', 'roadside-oddities', 35.12488, -89.95953, 'Memphis', 'TN', 'A massive pink-marble mansion built for Piggly Wiggly founder Clarence Saunders became the centerpiece of Memphis''s science and history museum. The unfinished personal palace turned public museum mixes eccentric architecture with natural-history and regional exhibits.', 'open', null, 'https://moshmemphis.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Museum of Wonder Drive-Thru Museum', 'museum-of-wonder-drive-thru-museum', 'roadside-oddities', 32.32926, -85.1682, 'Seale', 'AL', 'Butch Anthony turned stacked shipping containers into a free drive-through gallery filled with folk art, taxidermy, bones, found objects and visual oddities. The drive-through portion is open 24/7; tours of Anthony’s original museum and studio require separate arrangements.', 'open', null, 'https://museumofwonder.com/visit', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Music Box Village', 'music-box-village', 'roadside-oddities', 29.96361, -90.02934, 'New Orleans', 'LA', 'Music Box Village is a walk-through environment of artist-built structures that double as playable musical instruments. Performances and public hours follow a changing calendar, so confirm an event or open day before routing there.', 'limited', null, 'https://musicboxvillage.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Musical Parking Garage', 'musical-parking-garage', 'roadside-oddities', 35.22781, -80.83781, 'Charlotte', 'NC', 'Artist Christopher Janney turned a nine-story parking garage into an enormous playable instrument. Touch-sensitive architectural fins light up and produce sounds, while programmed performances and a hidden puzzle add to the building’s interactive weirdness.', 'open', null, 'https://www.atlasobscura.com/places/musical-parking-garage', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mystery Hill', 'mystery-hill', 'roadside-oddities', 42.05594, -84.1399, 'Onsted', 'MI', 'Mystery Hill has been confusing Irish Hills travelers since 1952 with rooms and demonstrations where water, balls and people appear to defy gravity. The revived attraction also includes Ward Hall''s Strange Oddities, with sideshow-style curiosities and unusual animal specimens.', 'limited', null, 'https://visitmysteryhill.com/', '2026-09-08T14:53:55.160019+00:00', null, 'https://visitmysteryhill.com/', null, null, null, 'America/Detroit'),
  ('Mystery Hill', 'mystery-hill-blowing-rock', 'roadside-oddities', 36.1633, -81.64417, 'Blowing Rock', 'NC', 'This classic roadside “gravity hill” attraction has operated for decades around rooms and structures designed to distort visitors’ sense of level, balance, and gravity. The site has expanded with optical illusions, Appalachian exhibits, and other attractions while keeping the tilted Mystery House as its centerpiece. Location source: https://mapcarta.com/N2385806042', 'open', null, 'https://mysteryhill.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mystery Spot', 'mystery-spot', 'roadside-oddities', 37.017283, -122.003751, 'Santa Cruz', 'CA', 'The Mystery Spot is a classic gravity-house roadside attraction in the redwoods outside Santa Cruz, where tilted structures and forced perspective make visitors appear to lean at impossible angles. It was discovered in 1939 and opened to the public around 1940; today visitors buy tickets for a roughly 45-minute guided experience and can also use the hiking trail and gift shop.', 'limited', null, 'https://www.mysteryspot.com/what-is-it', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Mystery Spot', 'mystery-spot-st-ignace', 'roadside-oddities', 45.8758, -84.80803, 'St. Ignace', 'MI', 'Opened in the 1950s, this classic roadside "mystery spot" uses tilted construction and visual cues to make visitors feel as though gravity is behaving incorrectly. The seasonal attraction has grown to include the original gravity experience plus other family attractions, but the old mystery-house presentation remains the reason it belongs on OddWay.', 'limited', null, 'https://www.atlasobscura.com/places/mystery-spot', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.mysteryspotstignace.com/', null, null, null, 'America/Detroit'),
  ('Mystic Pizza', 'mystic-pizza', 'roadside-oddities', 41.35463, -71.97164, 'Mystic', 'CT', 'The real Mystic Pizza inspired the title and setting of the 1988 film that helped launch Julia Roberts'' career. The restaurant was not the movie''s interior filming location, but it embraces the connection with photographs, memorabilia and its now-famous name.', 'open', null, 'https://www.roadsideamerica.com/tip/6540', '2026-09-08T19:51:22.001704+00:00', null, 'https://mysticpizzaoriginal.com/', null, null, null, 'America/New_York'),
  ('Nada Tunnel', 'nada-tunnel', 'roadside-oddities', 37.81703, -83.68102, 'Stanton', 'KY', 'This narrow, unlit tunnel was blasted through solid rock in the early twentieth century for a logging railroad before being converted into a one-lane automobile road. Now known as the Gateway to Red River Gorge, it is just wide enough for a single vehicle and still carries normal traffic through the mountain.', 'open', null, 'https://www.atlasobscura.com/places/nada-tunnel', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('NASA Goddard Rocket Garden and Moon Tree', 'nasa-goddard-rocket-garden-and-moon-tree', 'roadside-oddities', 38.9928, -76.84699, 'Greenbelt', 'MD', 'Outside NASA''s Goddard Visitor Center is a collection of rockets and space hardware that gives travelers an up-close look at the scale of sounding rockets and launch technology. The grounds also include a Moon Tree descended from seeds carried around the Moon during Apollo 14, while the visitor center contains additional free exhibits.', 'open', null, 'https://www.nasa.gov/goddard/visitor-center/', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nashville Clayscape', 'nashville-clayscape', 'roadside-oddities', 36.15409, -86.72564, 'Nashville', 'TN', 'A large ceramic public-art installation creates a strange miniature landscape of sculpted forms rather than a conventional statue. Its tactile, earth-toned construction makes it an unusual break from Nashville''s bronze monuments and music murals.', 'open', null, 'https://www.atlasobscura.com/places/nashville-clayscape', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('National Park Seminary', 'national-park-seminary', 'roadside-oddities', 39.0121, -77.05641, 'Silver Spring', 'MD', 'This former women''s school developed an extraordinary campus of architectural fantasies including a Japanese pagoda, Dutch windmill, Swiss chalet and English-style buildings before becoming part of an Army medical complex. Much of the property has since been redeveloped as residences, so visitors should stick to public roads, sidewalks and designated public areas rather than entering private buildings.', 'limited', null, 'https://www.loc.gov/pictures/item/md1503/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('National Shrine of Blessed Francis Xavier Seelos', 'national-shrine-of-blessed-francis-xavier-seelos', 'roadside-oddities', 29.92907, -90.07454, 'New Orleans', 'LA', 'The shrine preserves relics and a museum connected with nineteenth-century priest Francis Xavier Seelos, including objects tied to his ministry during a yellow-fever epidemic. It is an active religious site rather than a curiosity museum, so visit respectfully.', 'open', null, 'https://seelos.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Natural Bridge and Rockshelter', 'natural-bridge-and-rockshelter', 'roadside-oddities', 43.34403, -89.92933, 'North Freedom', 'WI', 'A large sandstone arch spans a wooded hillside above a rock shelter used by people thousands of years ago. The combination of unusual geology and deep human history makes the small state park unusually dense with significance.', 'open', null, 'https://dnr.wisconsin.gov/topic/parks/naturalbridge', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/topic/parks/naturalbridge', null, null, null, 'America/Chicago'),
  ('Natural Bridge of Alabama', 'natural-bridge-of-alabama', 'roadside-oddities', 34.09416, -87.61334, 'Natural Bridge', 'AL', 'A massive sandstone arch spans the forest and is promoted as the longest natural bridge east of the Rockies. The privately operated attraction uses established walking paths; visitors should check current operating hours before making a detour.', 'limited', null, 'https://alabama.travel/places-to-go/natural-bridge-of-alabama', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Natural Bridge State Park', 'natural-bridge-state-park', 'roadside-oddities', 42.70675, -73.09288, 'North Adams', 'MA', 'A natural white-marble arch spans a rushing brook inside the remains of an old marble quarry. The unusual combination of natural bridge, carved marble gorge and industrial quarry history makes this one of western Massachusetts'' strongest geology stops.', 'limited', null, 'https://www.mass.gov/locations/natural-bridge-state-park', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Natural Stone Bridge and Caves', 'natural-stone-bridge-and-caves', 'roadside-oddities', 43.74739, -73.85192, 'Pottersville', 'NY', 'A massive marble arch spans Trout Brook here, forming what is promoted as the largest marble cave entrance in the eastern United States. Seasonal trails lead through caves, potholes and unusual rock formations, with access dependent on the attraction''s operating schedule and weather.', 'limited', null, 'https://stonebridgeandcaves.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Natural Tunnel State Park', 'natural-tunnel-state-park', 'roadside-oddities', 36.69698, -82.73858, 'Duffield', 'VA', 'A naturally carved limestone tunnel about 850 feet long and up to roughly 100 feet high forms the centerpiece of this Southwest Virginia state park, with an active railroad still passing through it. Visitors can hike or use the seasonal chairlift toward the gorge and observation areas, but the railroad tunnel itself is not a pedestrian passage.', 'open', null, 'https://www.dcr.virginia.gov/state-parks/natural-tunnel', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Neah Bay Big Chair', 'neah-bay-big-chair', 'roadside-oddities', 48.368772, -124.601439, 'Neah Bay', 'WA', 'This oversized chair is in Neah Bay, not Forks, and is mapped near the Makah Museum/harbor area as a local roadside attraction. I could not locate a reliable artist or construction date in current published sources, so OddWay should keep the history minimal and present it simply as a giant chair photo stop.', 'roadside', null, 'https://mapcarta.com/N12247217710', null, null, null, null, null, null, 'America/Los_Angeles'),
  ('Necco Wafer Sculpture', 'necco-wafer-sculpture', 'roadside-oddities', 42.36198, -71.10129, 'Cambridge', 'MA', 'Metal Necco wafers appear to spill from a crumpled candy bag onto a boulder near the site of the former New England Confectionery Company factory. The tiny sculpture preserves a candy-making history that once filled this part of Cambridge with sugar and peppermint smells.', 'open', null, 'https://www.atlasobscura.com/places/necco-wafer-sculpture', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Neighborhood Menagerie', 'neighborhood-menagerie', 'roadside-oddities', 37.79443, -81.18773, 'Beckley', 'WV', 'Dozens of fiberglass animals, dinosaurs and a Bigfoot fill several residential yards along Conway Street, all part of a collection owned by the same local resident. The owner has welcomed visitors, but these are still private residential properties, so OddWay travelers should view the figures from the public street unless they receive clear permission to enter a yard.', 'private', null, 'https://www.roadsideamerica.com/tip/69799', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nerida the Mermaid', 'nerida-the-mermaid', 'roadside-oddities', 44.90471, -66.98408, 'Eastport', 'ME', 'Nerida is a bronze mermaid sculpture installed on the Eastport waterfront in 2015. The figure ties the city’s working waterfront to maritime myth and makes an easy stop while exploring the eastern edge of Maine.', 'open', null, 'https://www.roadsideamerica.com/tip/82628', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nervous Nellie’s — Nellieville Sculpture Village', 'nervous-nellies-nellieville-sculpture-village', 'roadside-oddities', 44.20433, -68.58275, 'Deer Isle', 'ME', 'Behind a jam and jelly business is an sprawling handmade village of sculptures, buildings, figures, vehicles, creatures, and found-object scenes known as Nellieville. The dense folk-art environment is strange enough to be a destination on its own.', 'limited', null, 'https://www.nervousnellies.com/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Neversink Cave Preserve', 'neversink-cave-preserve', 'roadside-oddities', 34.8041, -86.007, 'Fackler', 'AL', 'Neversink is a spectacular open-air pit cave known for waterfalls, moss-covered walls and a deep vertical drop. It is a protected SCCi preserve requiring a permit, and entering the pit is technical vertical caving—not a casual hike.', 'limited', null, 'https://saveyourcaves.org/visit.html', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('New England Peace Pagoda', 'new-england-peace-pagoda', 'roadside-oddities', 42.49896, -72.49116, 'Leverett', 'MA', 'A gleaming white Buddhist peace pagoda rises from rural western Massachusetts, one of the first structures of its kind built in the United States. The grounds include shrines, gardens and spaces intended for quiet reflection.', 'open', null, 'https://www.atlasobscura.com/places/new-england-peace-pagoda', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Orleans Musical Legends Park', 'new-orleans-musical-legends-park', 'roadside-oddities', 29.95585, -90.06844, 'New Orleans', 'LA', 'This compact Bourbon Street courtyard contains bronze statues honoring New Orleans musicians such as Fats Domino, Pete Fountain and Al Hirt. It is an easy public stop that turns local music history into a small sculpture garden.', 'open', null, 'https://www.neworleansmusicallegends.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nick Engelbert''s Grandview', 'nick-engelberts-grandview', 'roadside-oddities', 42.87345, -89.94726, 'Hollandale', 'WI', 'Immigrant farmer Nick Engelbert surrounded his home with colorful concrete sculptures depicting animals, people, fairy tales and family memories. The restored site preserves both the sculpture garden and the painted house.', 'limited', null, 'https://nicksgrandview.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://nicksgrandview.com/', null, null, null, 'America/Chicago'),
  ('Nickajack Cave Wildlife Refuge', 'nickajack-cave-wildlife-refuge', 'roadside-oddities', 34.99251, -85.61282, 'South Pittsburg', 'TN', 'Nickajack Cave was partly flooded by reservoir construction and now shelters major bat colonies. Visitors can observe the cave area from approved water or shoreline locations, especially during seasonal bat emergence; entering the cave or disturbing wildlife is not appropriate.', 'limited', null, 'https://www.tn.gov/twra/wildlife-management-areas/cumberland-plateau-r3/nickajack-cave-wma.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nicolas Cage Pyramid Tomb', 'nicolas-cage-pyramid-tomb', 'roadside-oddities', 29.95903, -90.07116, 'New Orleans', 'LA', 'Actor Nicolas Cage purchased cemetery plots and built a stark nine-foot pyramid mausoleum marked with the Latin phrase ''Omnia Ab Uno.'' It is inside St. Louis Cemetery No. 1 and can only be seen through lawful cemetery access.', 'limited', null, 'https://nolacatholiccemeteries.org/st-louis-cemetery-1', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Nike Missile Site HM-69', 'nike-missile-site-hm-69', 'roadside-oddities', 25.36972, -80.68472, 'Homestead', 'FL', 'Exceptionally preserved Cold War Nike Hercules missile base hidden inside Everglades National Park.', 'open', null, 'https://www.nps.gov/ever/learn/historyculture/hm69.htm', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nitro Girl — Uniroyal SuperGal', 'nitro-girl-uniroyal-supergal', 'roadside-oddities', 39.82345, -75.06788, 'Blackwood', 'NJ', 'A towering fiberglass woman stands outside Werbany Tire Town, adapted from the classic Uniroyal Gal advertising figures once placed outside tire stores around the country. This surviving example has been repainted as ''Nitro Girl'' and remains visible from the Black Horse Pike.', 'roadside', null, 'https://www.roadsideamerica.com/tip/18893', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nori the Dragon', 'nori-the-dragon', 'roadside-oddities', 41.81651, -71.40939, 'Providence', 'RI', 'A gigantic green dragon appears to crawl over the roof of the Providence Children''s Museum, with its head and tail visible on opposite sides of the building. The sculpture survived an earlier home before being adopted by the museum and later received the name Nori through a children''s contest. Museum admission is required for the full visit, though portions of the dragon can be seen from outside.', 'limited', null, 'https://www.atlasobscura.com/places/nori-the-dragon', '2026-09-09T04:49:27.913704+00:00', null, 'https://providencechildrensmuseum.org/', null, null, null, 'America/New_York'),
  ('Norma Jean Circus Elephant Monument', 'norma-jean-circus-elephant-monument', 'roadside-oddities', 40.93998, -90.94931, 'Oquawka', 'IL', 'A large stone monument marks the 1972 death of Norma Jean, a circus elephant killed by lightning while tethered in town.', 'open', null, 'https://www.hmdb.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('North America''s Tallest Elevator Test Tower', 'north-americas-tallest-elevator-test-tower', 'roadside-oddities', 41.65213, -72.91495, 'Bristol', 'CT', 'A roughly 383-foot elevator research tower rises over Bristol like a windowless skyscraper. Built for testing high-speed elevator systems, it is not a public attraction inside, but its strange scale makes it visible from public roads around the facility.', 'roadside', null, 'https://www.roadsideamerica.com/tip/8718', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('North Carolina Transportation Museum', 'north-carolina-transportation-museum', 'roadside-oddities', 35.68718, -80.4347, 'Spencer', 'NC', 'A former Southern Railway repair complex now holds locomotives, railcars, automobiles, aircraft, and other transportation artifacts. Its enormous surviving roundhouse and working turntable make the industrial site as interesting as the collection.', 'limited', null, 'https://www.nctransportationmuseum.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('North End Street Utensils', 'north-end-street-utensils', 'roadside-oddities', 42.36297, -71.05644, 'Boston', 'MA', 'Actual knives and forks are embedded in sidewalks outside Italian food businesses in Boston''s North End. The easy-to-miss cutlery reflects an old visual tradition of identifying food shops and rewards travelers who remember to look down.', 'open', null, 'https://www.atlasobscura.com/places/north-end-street-utensils', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('North Shore Dance Paving Stones', 'north-shore-dance-paving-stones', 'roadside-oddities', 35.06233, -85.30624, 'Chattanooga', 'TN', 'Embedded paving stones on Chattanooga''s North Shore diagram dance steps for pedestrians to follow. The installation turns an ordinary walkway into an interactive public-art lesson that many visitors cross without realizing what the markings mean.', 'open', null, 'https://www.atlasobscura.com/places/north-shore-dance-paving-stones', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Norton Museum Sculpture Garden', 'norton-museum-sculpture-garden', 'roadside-oddities', 26.70027, -80.05311, 'West Palm Beach', 'FL', 'Outdoor sculpture garden with monumental contemporary works.', 'limited', null, 'https://www.norton.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Norwich Horton Sphere', 'norwich-horton-sphere', 'roadside-oddities', 41.51205, -72.07586, 'Norwich', 'CT', 'A huge rusting steel sphere rises behind a former industrial property like an abandoned science-fiction prop. The roughly 37-foot Horton sphere was an industrial pressure vessel; it remains fenced off, so this is strictly a lawful public-road viewing stop.', 'roadside', null, 'https://www.atlasobscura.com/places/norwich-horton-sphere', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nuclear Cruise Missile in a Church Parking Lot', 'nuclear-cruise-missile-in-a-church-parking-lot', 'roadside-oddities', 35.48608, -77.90059, 'Pikeville', 'NC', 'A decommissioned TM-61C Matador cruise missile stands outside a church on land formerly associated with a private airstrip and restaurant. The weapon type was designed to carry a nuclear warhead, making the forty-foot missile an unusually ominous piece of roadside advertising history.', 'roadside', null, 'https://www.atlasobscura.com/places/cruise-missile-in-a-parking-lot', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ocean Gallery World Center', 'ocean-gallery-world-center', 'roadside-oddities', 38.33335, -75.08409, 'Ocean City', 'MD', 'Ocean Gallery''s boardwalk building looks like a chaotic collision of scrap metal, signs, art and old vehicles rather than a normal gallery storefront. The family-run business has evolved into one of Ocean City''s most recognizable visual oddities, and the exterior is worth seeing even without shopping.', 'open', null, 'https://www.roadsideamerica.com/location/md/all', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ochopee Post Office', 'ochopee-post-office', 'roadside-oddities', 25.90125, -81.29735, 'Ochopee', 'FL', 'A former irrigation-pipe shed converted into the smallest operating U.S. Post Office after a 1953 fire.', 'roadside', null, 'https://facts.usps.com/smallest-post-office/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Octagon House Museum', 'octagon-house-museum', 'roadside-oddities', 43.19447, -88.7241, 'Watertown', 'WI', 'Built in 1854, this unusual eight-sided house follows the nineteenth-century fascination with octagonal architecture. Its preserved rooms, central staircase and historic grounds make the geometry itself the main attraction.', 'limited', null, 'https://www.watertownhistory.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.watertownhistory.org/', null, null, null, 'America/Chicago'),
  ('Ohio Caverns', 'ohio-caverns', 'roadside-oddities', 40.23853, -83.69922, 'West Liberty', 'OH', 'Ohio Caverns was discovered in 1897 and contains extensive passageways filled with stalactites, stalagmites and other mineral formations, including the enormous white formation known as the Crystal King. The privately operated attraction offers guided underground tours during posted hours.', 'open', null, 'https://www.atlasobscura.com/places/ohio-caverns', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Ben and the Giant Sycamore Stump', 'old-ben-and-the-giant-sycamore-stump', 'roadside-oddities', 40.46917, -86.14389, 'Kokomo', 'IN', 'Highland Park preserves two major Kokomo oddities under neighboring shelters: Old Ben, a famously enormous steer born in 1902 and preserved by taxidermy after his death, and the huge stump of an ancient sycamore. Combining them into one stop avoids sending travelers to duplicate coordinates while preserving both pieces of Kokomo roadside history.', 'open', null, 'https://www.atlasobscura.com/places/old-ben-pavilion-worlds-largest-steer', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Old Brontosaurus & Dinosaur Trail', 'old-brontosaurus-dinosaur-trail', 'roadside-oddities', 36.0294, -78.89941, 'Durham', 'NC', 'The Museum of Life and Science preserves a vintage concrete dinosaur from an earlier era of roadside science attractions alongside a modern dinosaur trail. The surviving old Brontosaurus is especially appealing because it looks more like a mid-century monster than a scientifically current reconstruction. Museum: https://www.lifeandscience.org/visit/', 'limited', null, 'https://www.roadsideamerica.com/tip/3495', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Joe Clark Statue', 'old-joe-clark-statue', 'roadside-oddities', 37.38714, -84.33087, 'Mount Vernon', 'KY', 'A bronze banjo player at Renfro Valley honors Manuel Dewey Clark Jr., who performed the comic old-time character "Old Joe Clark" for decades. The statue freezes the entertainer in mid-performance beside the historic Barn Dance complex.', 'open', null, 'https://www.roadsideamerica.com/tip/52377', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Louisiana State Capitol', 'old-louisiana-state-capitol', 'roadside-oddities', 30.44694, -91.18889, 'Baton Rouge', 'LA', 'Louisiana''s Gothic Revival former capitol looks more like a castle than a conventional government building. It now operates as a political-history museum with an especially theatrical interior.', 'open', null, 'https://louisianaoldstatecapitol.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Old Salem Coffee Pot', 'old-salem-coffee-pot', 'roadside-oddities', 36.0908, -80.2428, 'Winston-Salem', 'NC', 'A giant metal coffee pot has been a Winston-Salem landmark since the 1800s. Originally built as advertising for a tinsmith business, the oversized pot survived relocation and generations of local folklore to become one of the city’s oldest roadside oddities.', 'open', null, 'https://www.atlasobscura.com/things-to-do/north-carolina/places?page=4', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Senator Tree', 'old-senator-tree', 'roadside-oddities', 29.90535, -81.31589, 'St. Augustine', 'FL', 'Ancient live oak estimated to be several centuries old near St. Augustine''s historic mission grounds.', 'open', null, 'https://www.visitstaugustine.com/thing-to-do/senator', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Sow Whirlpool', 'old-sow-whirlpool', 'roadside-oddities', 44.92375, -66.98714, 'Eastport', 'ME', 'Powerful tides in the waters between Eastport and Deer Island create Old Sow, generally regarded as the largest tidal whirlpool in the Western Hemisphere. It can sometimes be seen from shore, but boat tours provide closer views when tides and conditions cooperate.', 'limited', null, 'https://www.atlasobscura.com/places/old-sow-whirlpool', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oldest 45th Parallel Marker in the U.S.', 'oldest-45th-parallel-marker-in-the-us', 'roadside-oddities', 44.99961, -67.08866, 'Perry', 'ME', 'An old granite marker beside the road commemorates the halfway point between the Equator and North Pole. Modern surveying places the exact 45th parallel a short distance away, making the historic marker both a geographic landmark and a surveying curiosity.', 'roadside', null, 'https://www.atlasobscura.com/places/the-oldest-45th-parallel-marker-in-the-us-perry-maine', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oliver Pollock Sculpture', 'oliver-pollock-sculpture', 'roadside-oddities', 30.44664, -91.18838, 'Baton Rouge', 'LA', 'This unusual downtown sculpture honors Oliver Pollock, a merchant credited with helping popularize the dollar sign in American financial correspondence. It is a small public-art stop with an unexpectedly large connection to everyday symbolism.', 'open', null, 'https://www.atlasobscura.com/places/oliver-pollock', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Omiskanoagwiah', 'omiskanoagwiah', 'roadside-oddities', 42.07268, -72.58171, 'Springfield', 'MA', 'A 15-foot wooden head carved by Peter Wolf Toth stands at the Route 5 entrance to Forest Park. It belongs to Toth''s nationwide ''Whispering Giants'' series and is dedicated to Indigenous peoples of the Pioneer Valley.', 'open', null, 'https://www.atlasobscura.com/places/omiskanoagwiah-springfield-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Onaway Steers the World', 'onaway-steers-the-world', 'roadside-oddities', 45.35556, -84.23459, 'Onaway', 'MI', 'A roughly 30-foot steering wheel towers beside the road in Onaway as a tribute to the city''s history manufacturing wooden automobile steering wheels. Built by local metal artist Tom Moran, the sculpture turns a forgotten piece of Michigan automotive history into an oversized visual pun.', 'open', null, 'https://www.atlasobscura.com/places/onaway-steers-the-world', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Only Octagonal Post Office', 'only-octagonal-post-office', 'roadside-oddities', 44.39194, -69.30722, 'Liberty', 'ME', 'This tiny eight-sided building began as a harness shop in 1870 and later served as Liberty’s post office. The town promotes it as the only octagonal post-office building in the United States; it now operates as a small historical museum with limited summer access.', 'limited', null, 'https://www.roadsideamerica.com/tip/58804', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Opus 40', 'opus-40', 'roadside-oddities', 42.05067, -74.03169, 'Saugerties', 'NY', 'Sculptor Harvey Fite spent nearly four decades assembling this sprawling bluestone earthwork by hand from millions of pieces of local stone. The six-acre labyrinth of ramps, terraces, walls and platforms is open seasonally as an outdoor arts site.', 'limited', null, 'https://opus40.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('O''Reilly Spite House', 'oreilly-spite-house', 'roadside-oddities', 42.38321, -71.13301, 'Cambridge', 'MA', 'After a neighboring landowner reportedly refused to buy his narrow parcel, Francis O''Reilly built an eight-foot-wide building on it in 1908 simply to make use of the strip and spite the neighbor. The tiny structure still stands and remains occupied, so it should be viewed only from the public sidewalk.', 'private', null, 'https://www.atlasobscura.com/places/o-reilly-spite-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Original Giant Hex Nut', 'original-giant-hex-nut', 'roadside-oddities', 44.46672, -88.06794, 'Green Bay', 'WI', 'This enormous industrial fastener was long promoted as the world''s largest hex nut. Larger examples have since appeared elsewhere, so OddWay should present it as the original famous Green Bay giant rather than an uncontested current record-holder.', 'roadside', null, 'https://www.roadsideamerica.com/tip/53193', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/tip/53193', null, null, null, 'America/Chicago'),
  ('Orozco''s "The Epic of American Civilization"', 'orozcos-the-epic-of-american-civilization', 'roadside-oddities', 43.7052, -72.28897, 'Hanover', 'NH', 'Mexican muralist José Clemente Orozco covered the walls of Dartmouth''s Baker-Berry Library reserve corridor with a dark, violent and often surreal interpretation of the history of the Americas. Gods, skeletons, machinery, conquest and war fill the panels rather than the genteel imagery expected in an Ivy League library. Public viewing follows current library access policies. Secondary source: https://www.nps.gov/places/orozco-murals.htm', 'limited', null, 'https://hoodmuseum.dartmouth.edu/explore/oorozco-mural', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Our Lady of the Pines', 'our-lady-of-the-pines', 'roadside-oddities', 39.25242, -79.49874, 'Eglon', 'WV', 'Built in 1958, this tiny stone church measures only about 24 by 12 feet and was once promoted as the smallest church in the 48 contiguous states. Six small pews, an altar and religious statuary fit inside, and the carefully maintained building remains a peaceful roadside curiosity open to respectful visitors.', 'open', null, 'https://www.atlasobscura.com/places/our-lady-of-the-pines', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Our Lady of Vietnam Park', 'our-lady-of-vietnam-park', 'roadside-oddities', 35.04504, -82.26243, 'Greer', 'SC', 'A striking Marian shrine created by South Carolina’s Vietnamese Catholic community includes a large statue of Our Lady of La Vang and landscaped devotional spaces. The elaborate monument looks unexpectedly transported from a major pilgrimage site into suburban Upstate South Carolina.', 'open', null, 'https://www.scpictureproject.org/greenville-county/our-lady-of-vietnam-park.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Oyotunji African Village', 'oyotunji-african-village', 'roadside-oddities', 32.60994, -80.80291, 'Seabrook', 'SC', 'Founded in 1970, Oyotunji was created as a Yoruba cultural and religious community in rural South Carolina. Shrines, ceremonial spaces, traditional artwork, festivals, and an unusual political structure make the village unlike virtually any other community in the United States.', 'limited', null, 'https://www.atlasobscura.com/places/oyotunji-african-village', '2026-09-09T05:53:13.784429+00:00', null, 'https://www.oyotunji.org/', null, null, null, 'America/New_York'),
  ('Oz Park', 'oz-park', 'roadside-oddities', 41.9206, -87.64567, 'Chicago', 'IL', 'A neighborhood park filled with permanent bronze Wizard of Oz character statues, including Dorothy, Tin Man, Scarecrow, and Cowardly Lion.', 'open', null, 'https://www.chicagoparkdistrict.com/parks-facilities/oz-park', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Painted Rock', 'painted-rock', 'roadside-oddities', 41.15702, -71.58608, 'New Shoreham', 'RI', 'Since 1962, residents and visitors have repeatedly repainted this boulder at the junction of Mohegan Trail, Lakeside Drive and Snake Hole Road. Designs can change within days during the summer, leaving countless older layers sealed underneath the newest message. It is one of Block Island''s most enduring handmade roadside traditions. Secondary source: https://torijonesstudio.com/pages/visit-us-on-block-island', 'open', null, 'https://www.blockislandinfo.com/plan-your-visit/maps/bike-tour-map/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Palace of Depression', 'palace-of-depression', 'roadside-oddities', 39.48414, -75.0612, 'Vineland', 'NJ', 'George Daynor originally built his bizarre "palace" from junk, mud, concrete and discarded materials after losing his fortune during the Great Depression. Volunteers have spent years reconstructing the folk-art landmark; access is restricted and visitors should follow current tour or event information rather than enter uninvited.', 'limited', null, 'https://www.facebook.com/thepalaceofdepression/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Panama Rocks', 'panama-rocks', 'roadside-oddities', 42.07322, -79.48881, 'Panama', 'NY', 'Towering conglomerate formations create narrow passageways, caves and crevices through an old-growth forest at this privately operated park. The one-mile rock trail is open seasonally with paid admission, and visitors can walk directly among the formations rather than viewing them from a distance.', 'limited', null, 'https://www.panamarocks.com/visitforday.html', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Papermoon Diner', 'papermoon-diner', 'roadside-oddities', 39.32244, -76.62123, 'Baltimore', 'MD', 'Papermoon is less a normal diner than a giant assemblage artwork with mannequins, toys, Pez dispensers, dolls, brightly painted objects and bizarre decorations covering nearly every available surface. The restaurant is still operating, so travelers can actually go inside rather than merely photographing the exterior.', 'open', null, 'https://www.roadsideamerica.com/tip/37475', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Parfrey''s Glen', 'parfreys-glen', 'roadside-oddities', 43.40978, -89.63676, 'Merrimac', 'WI', 'A narrow sandstone-and-quartzite gorge shelters cool-climate plants and a stream that winds between high rock walls. Flooding has repeatedly changed the trail infrastructure, so visitors should expect a natural route rather than a manicured boardwalk.', 'open', null, 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=1', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/', null, null, null, 'America/Chicago'),
  ('Park-McCullough Children''s Play House', 'park-mccullough-childrens-play-house', 'roadside-oddities', 42.92848, -73.24658, 'North Bennington', 'VT', 'On the grounds of the Park-McCullough Historic Governor''s Mansion is an elaborate child-sized Victorian playhouse built with far more architectural ambition than an ordinary backyard toy. Access follows the historic estate''s public schedule and rules.', 'limited', null, 'https://www.roadsideamerica.com/tip/27710', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Path of Life Sculpture Garden', 'path-of-life-sculpture-garden', 'roadside-oddities', 43.51296, -72.39999, 'Windsor', 'VT', 'Large outdoor sculptures are arranged along a riverside route to symbolize stages and experiences across a human lifetime. The walk includes conceptual pieces and landscape installations rather than a conventional formal sculpture garden.', 'open', null, 'https://www.greatriveroutfitters.com/path-of-life', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Patriot Fireworks Mega Missile', 'patriot-fireworks-mega-missile', 'roadside-oddities', 39.33426, -78.06315, 'Bunker Hill', 'WV', 'A tall grain silo beside Patriot Fireworks has been transformed into a fake missile labeled as a giant roadside weapon. The "Mega Missile" is visible from the road and business parking area, making it a quick photo stop rather than an attraction that requires entering the structure.', 'roadside', null, 'https://www.roadsideamerica.com/tip/63258', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Patterson Park Pagoda', 'patterson-park-pagoda', 'roadside-oddities', 39.28995, -76.58349, 'Baltimore', 'MD', 'Built in 1891 as an observation tower, this brightly painted four-story structure is popularly called a pagoda despite being designed in a fanciful Victorian interpretation of Asian architecture. The exterior can be visited in Patterson Park year-round, while interior stair access is limited to scheduled open hours and events.', 'open', null, 'https://www.atlasobscura.com/places/patterson-park-observatory', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan & Babe the Blue Ox', 'paul-bunyan', 'roadside-oddities', 44.902028, -83.443236, 'Ossineke', 'MI', 'This record refers to the concrete Paul Bunyan and Babe the Blue Ox now standing in Ossineke, not Hubbard Lake. Paul N. Domke built the pair in the 1940s; after being moved to a site near Hubbard Lake/Spruce for years, they were returned to their original Ossineke roadside location in 2006, where travelers can see them today.', 'roadside', null, 'https://www.roadsideamerica.com/story/2125', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Paul Bunyan and Babe', 'paul-bunyan-and-babe', 'roadside-oddities', 41.584584, -124.085805, 'Klamath', 'CA', 'The giant Paul Bunyan and Babe the Blue Ox guard the entrance to Trees of Mystery on California’s Redwood Highway. The attraction’s Bunyan figures evolved through several versions beginning in the 1940s, with Babe added in 1951 and the current giant Paul dating to the late 1950s/early 1960s; travelers can photograph the statues at the entrance while the forest attraction beyond them is ticketed.', 'roadside', null, 'https://www.roadsideamerica.com/story/2040', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Paul Bunyan and Babe', 'paul-bunyan-and-babe-nitro', 'roadside-oddities', 38.44557, -81.8231, 'Nitro', 'WV', 'A giant fiberglass Paul Bunyan and blue Babe the Ox stand along First Avenue outside a local supply business in Nitro. These classic oversized advertising figures are visible from the road and are best treated as a quick public-road photo stop.', 'roadside', null, 'https://fotospot.com/attractions/west-virginia/paul-bunyan-and-babe', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan and Babe the Blue Ox Statue', 'paul-bunyan-and-babe-the-blue-ox-statue', 'roadside-oddities', 47.470418, -94.878892, 'Bemidji', 'MN', 'Bemidji’s Paul Bunyan and Babe the Blue Ox statues were built in 1937 for the city’s winter carnival and quickly became one of Minnesota’s defining roadside images. They remain beside Lake Bemidji near the visitor center, where travelers can walk up and photograph the historic pair for free.', 'roadside', null, 'https://www.exploreminnesota.com/profile/paul-bunyan-babe-blue-ox/1982', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Paul Bunyan & Babe the Blue Ox', 'paul-bunyan-babe-the-blue-ox', 'roadside-oddities', 44.542467, -70.548499, 'Rumford', 'ME', 'Rumford’s Paul Bunyan is an approximately 18-foot fiberglass Muffler Man that has stood in the area since at least the mid-20th century and was later donated to the town and rebuilt with internal supports. Babe the Blue Ox joined him at the visitor-center site much later, and travelers can photograph the pair for free beside Route 2.', 'roadside', null, 'https://www.roadsideamerica.com/tip/2556', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan & Babe the Blue Ox — Log Cabin Homes', 'paul-bunyan-babe-the-blue-ox-log-cabin-homes', 'roadside-oddities', 36.0439, -77.8439, 'Battleboro', 'NC', 'A towering fiberglass Paul Bunyan stands beside Interstate 95 at a log-home sales center, accompanied by Babe the Blue Ox. The figure began life as a classic Muffler Man and was later transformed into a lumberjack advertising landmark. Current business: https://www.logcabinhomes.com/', 'roadside', null, 'https://www.roadsideamerica.com/tip/8857', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan Bouquet no. 2', 'paul-bunyan-bouquet-no-2', 'roadside-oddities', 29.716318, -95.397803, 'Houston', 'TX', 'Jim Love created “Paul Bunyan Bouquet No. 2” in 1968, turning heavy industrial forms into a whimsical monumental bouquet. The sculpture is on the Rice University campus in Houston rather than West University Place, and travelers can see it as part of the university’s outdoor public-art collection.', 'roadside', null, 'https://publicart.rice.edu/artworks/paul-bunyan-bouquet-no-2', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Paul Bunyan Muffler Man', 'paul-bunyan-muffler-man', 'roadside-oddities', 40.18319, -85.4207, 'Muncie', 'IN', 'A roughly 25-foot Paul Bunyan-style fiberglass giant has stood in Muncie since the mid-twentieth-century roadside-advertising era. Originally connected to a lumber business, the figure later moved to the property near Kilgore Avenue and remains one of Indiana''s classic Muffler Man survivors.', 'roadside', null, 'https://visitindiana.in.gov/blog/post/roadside-attractions/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Paul Bunyan Muffler Man', 'paul-bunyan-muffler-man-cheshire', 'roadside-oddities', 41.55781, -72.90662, 'Cheshire', 'CT', 'A 26-foot fiberglass Paul Bunyan towers over West Johnson Avenue. When local height rules complicated his oversized axe, it was replaced with an American flag, allowing the classic Muffler Man to remain one of Connecticut''s biggest roadside figures.', 'open', null, 'https://www.atlasobscura.com/places/paul-bunyan-muffler-man', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan''s Boat-Anchor', 'paul-bunyan-s-boat-anchor', 'roadside-oddities', 45.29691, -96.432457, 'Ortonville', 'MN', 'Paul Bunyan’s “Boat-Anchor” is a 110-ton granite-and-iron monument dedicated in 1958 for Minnesota’s statehood centennial. It sits on a hilltop at the Big Stone County Historical Society Museum grounds in Ortonville, where travelers can view the enormous tongue-in-cheek Bunyan relic and the surrounding lake country.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=101378', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Paul Bunyan''s Woodpile', 'paul-bunyan-s-woodpile', 'roadside-oddities', 39.766429, -112.115293, 'Mona', 'UT', 'Paul Bunyan’s Woodpile is a natural geologic formation of columnar volcanic rock, not a man-made Bunyan prop. The “logs” formed roughly 30 million years ago, and travelers reach them on BLM land by driving about 3.5 miles on a dirt road and then hiking roughly one mile to the formation.', 'limited', null, 'https://www.blm.gov/visit/paul-bunyons-woodpile', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Denver'),
  ('Paul Bunyan''s Woodpile Overlook', 'paul-bunyan-s-woodpile-overlook', 'roadside-oddities', 39.765628, -112.115667, 'Mona', 'UT', 'This viewpoint looks across the same Paul Bunyan’s Woodpile geologic formation rather than being a separate constructed attraction. The volcanic columns formed about 30 million years ago, and reaching the overlook involves the same rough BLM access road and hiking route used for the Woodpile itself.', 'limited', null, 'https://www.blm.gov/visit/paul-bunyons-woodpile', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Denver'),
  ('Paul Bunyan Statue', 'paul-bunyan-statue', 'roadside-oddities', 40.260799, -89.23153, 'Atlanta', 'IL', 'Atlanta’s giant is the famous Bunyon Giant, an original fiberglass Muffler Man installed at Bunyon’s restaurant in Cicero when it opened in 1966. After the restaurant closed, the figure was moved to Atlanta in November 2003 and dedicated there in 2004; travelers now find him standing along the town’s Route 66 corridor holding a giant hot dog.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=270597', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Paul Bunyan Statue', 'paul-bunyan-statue-bangor', 'roadside-oddities', 44.78795, -68.77828, 'Bangor', 'ME', 'Bangor’s 31-foot Paul Bunyan has stood near Main Street since 1959 and represents the city’s claim to the legendary lumberjack. The giant fiberglass figure also fits neatly into Bangor’s larger Stephen King and folklore identity.', 'open', null, 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/paul-bunyan-statue', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan Tree', 'paul-bunyan-tree', 'roadside-oddities', 43.135958, -70.944342, 'Durham', 'NH', 'The Paul Bunyan Tree was a famously massive old tree in the University of New Hampshire’s College Woods, estimated to be more than two centuries old rather than something “built.” Current map data identifies the individual tree as deceased, so a traveler should not expect to find the living giant that originally earned the nickname.', 'closed', null, 'https://mapcarta.com/N2581720749', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paul Bunyan’s Severed Head', 'paul-bunyans-severed-head', 'roadside-oddities', 43.15635, -70.7371, 'York', 'ME', 'An enormous fiberglass Paul Bunyan head appears among the trees near the York River with the rest of the legendary lumberjack nowhere in sight. The head is associated with private land, so it should be viewed only from legitimate public access without entering the property.', 'private', null, 'https://www.atlasobscura.com/places/paul-bunyans-severed-head', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paulverizer — Cyborg Muffler Man', 'paulverizer-cyborg-muffler-man', 'roadside-oddities', 37.72855, -79.3581, 'Buena Vista', 'VA', 'Artist Mark Cline unveiled the 24-foot Paulverizer in 2013, transforming the familiar Muffler Man form into a giant science-fiction cyborg with a control pod and robotic details. It remains outside the Auto Recyclers property on Sycamore Avenue and can be appreciated as a roadside photo stop without interfering with the operating business.', 'roadside', null, 'https://www.roadsideamerica.com/story/40615', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paynes Prairie Preserve State Park', 'paynes-prairie-preserve-state-park', 'roadside-oddities', 29.57955, -82.30416, 'Micanopy', 'FL', 'Wild bison and horses roam a vast sink-like prairie basin in central Florida.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/paynes-prairie-preserve-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Peace Gardens & Market', 'peace-gardens-market', 'roadside-oddities', 35.58286, -82.58502, 'Asheville', 'NC', 'This community garden doubles as a dense found-object art environment filled with sculptures, paintings, reclaimed materials, and tributes to major figures in Black history. Food-growing spaces, art, neighborhood history, and environmental work are intentionally mixed together.', 'limited', null, 'https://www.atlasobscura.com/places/burton-street-community-peace-gardens', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pearl Fryar Topiary Garden', 'pearl-fryar-topiary-garden', 'roadside-oddities', 34.20577, -80.27101, 'Bishopville', 'SC', 'Self-taught artist Pearl Fryar transformed rescued and discarded shrubs into hundreds of sweeping, abstract topiary sculptures across his three-acre yard. Fryar died in April 2026, but the nonprofit preserving his work continues to operate the garden as a free public attraction and living memorial.', 'limited', null, 'https://www.pearlfryargarden.org/home', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Peggotty at the Wilbor House', 'peggotty-at-the-wilbor-house', 'roadside-oddities', 41.49528, -71.18639, 'Little Compton', 'RI', 'Peggotty is an eccentric thatched artist''s studio designed to resemble an overturned boat and built by Rhode Island artist Sydney Burleigh in the early 1900s. The unusual structure was preserved and relocated to the Little Compton Historical Society''s Wilbor House property. Museum access is seasonal.', 'limited', null, 'https://littlecompton.org/', '2026-09-09T04:49:27.913704+00:00', null, 'https://littlecompton.org/', null, null, null, 'America/New_York'),
  ('PennDOT Road Sign Sculpture Garden', 'penndot-road-sign-sculpture-garden', 'roadside-oddities', 41.62086, -80.16704, 'Vernon Township', 'PA', 'A roughly quarter-mile art wall outside PennDOT''s Crawford County offices turns retired road signs into barns, animals, a Ferris wheel, a roller coaster, oil wells and other Pennsylvania scenes. It grew from a collaboration between PennDOT employees and Allegheny College artists; there is no dedicated attraction parking, so it works best as a roadside view along Smock Highway.', 'roadside', null, 'https://paroute6.com/art-culture/penndot-road-sign-sculpture-garden/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Penn''s Cave', 'penns-cave', 'roadside-oddities', 40.88256, -77.61223, 'Gregg Township', 'PA', 'Penn''s Cave is a limestone cavern explored almost entirely by boat, with tours traveling along an underground stream before emerging onto the property''s lake. The attraction operates on a seasonal schedule and also includes wildlife and farm tours above ground.', 'limited', null, 'https://www.pennscave.com/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Penobscot Narrows Bridge Observatory', 'penobscot-narrows-bridge-observatory', 'roadside-oddities', 44.56053, -68.80378, 'Prospect', 'ME', 'An elevator inside one of the Penobscot Narrows Bridge towers carries visitors to an observation room about 420 feet above the river. The enclosed observatory offers a 360-degree view and is accessed through the Fort Knox historic-site entrance.', 'limited', null, 'https://www.maine.gov/dot/pnbo', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Perry’s Nut House', 'perrys-nut-house', 'roadside-oddities', 44.43323, -68.99848, 'Belfast', 'ME', 'Perry’s Nut House is a surviving piece of old-school Maine roadside culture, historically famous for taxidermy, curiosities, oversized objects, souvenirs, and odd displays. The revived shop continues the name and keeps the strange roadside-stop tradition alive.', 'limited', null, 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/perrys-nut-house', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pewit''s Nest State Natural Area', 'pewits-nest-state-natural-area', 'roadside-oddities', 43.46303, -89.79514, 'Baraboo', 'WI', 'Skillet Creek cuts through a narrow sandstone gorge filled with dark pools, ledges and small waterfalls. The fragile site has special rules and no cliff jumping; OddWay should route visitors only to legal trails and viewpoints.', 'open', null, 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=200', '2026-09-09T13:02:00.307533+00:00', null, 'https://dnr.wisconsin.gov/', null, null, null, 'America/Chicago'),
  ('Philadelphia''s Magic Gardens', 'philadelphias-magic-gardens', 'roadside-oddities', 39.94274, -75.15941, 'Philadelphia', 'PA', 'Artist Isaiah Zagar transformed buildings and vacant lots along South Street into a dense mosaic environment of mirrors, tiles, bottles, bicycle wheels and found objects. The nonprofit attraction preserves a multi-level indoor and outdoor labyrinth that visitors can enter with a timed ticket.', 'open', null, 'https://www.phillymagicgardens.org/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Piatt Castle Mac-A-Cheek', 'piatt-castle-mac-a-cheek', 'roadside-oddities', 40.25106, -83.72691, 'West Liberty', 'OH', 'Mac-A-Cheek is an elaborate nineteenth-century stone mansion built by the Piatt family and filled with unusual carved woodwork, painted ceilings and family collections. It survives as the publicly toured half of the Piatt Castles property, with access generally limited to seasonal scheduled hours.', 'limited', null, 'https://www.atlasobscura.com/places/piatt-castles', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Piazza d''Italia', 'piazza-ditalia', 'roadside-oddities', 29.94798, -90.06646, 'New Orleans', 'LA', 'Designed by Charles Moore, this postmodern plaza uses bright colors, classical columns, neon and a fountain shaped around the map of Italy. It looks like a theatrical Roman ruin built for the late twentieth century.', 'open', null, 'https://www.tclf.org/landscapes/piazza-ditalia', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pine Mountain Ski Jump', 'pine-mountain-ski-jump', 'roadside-oddities', 45.8375, -88.09111, 'Iron Mountain', 'MI', 'The towering Pine Mountain ski jump rises above Iron Mountain as one of the Upper Peninsula''s most dramatic pieces of sports infrastructure. It hosts major ski-jumping competition and can be seen year-round, but access to the jump structure and event areas depends on current schedules and restrictions.', 'limited', null, 'https://www.roadsideamerica.com/location/mi/all', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Menominee'),
  ('Pine State Creamery Butter Churn', 'pine-state-creamery-butter-churn', 'roadside-oddities', 35.78566, -78.64674, 'Raleigh', 'NC', 'A giant concrete butter churn survives atop the former Pine State Creamery building, advertising the site’s dairy past long after the creamery itself disappeared. Its oversized handle makes the rooftop object particularly easy to spot.', 'roadside', null, 'https://www.atlasobscura.com/places/creamery-butter-churn', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('“Pinecone” — Giant Shovel Sculpture', 'pinecone-giant-shovel-sculpture', 'roadside-oddities', 43.65884, -70.27189, 'Portland', 'ME', 'An eight-foot steel pine cone stands in Deering Oaks Park, but its overlapping scales are actually made from roughly 140 recycled shovel heads. The transformation is obvious only when viewed closely, making the sculpture a good quick OddWay reveal.', 'open', null, 'https://www.atlasobscura.com/places/pinecone', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pink Elephant', 'pink-elephant', 'roadside-oddities', 36.64645, -87.19675, 'Guthrie', 'KY', 'A bright pink fiberglass elephant stands with its trunk raised outside a roadside gas-station property on Dixie Beeline Highway. The statue has been repainted several shades of pink over the years and was still being photographed in 2026.', 'roadside', null, 'https://fotospot.com/attractions/kentucky/pink-elephant', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pink Elephant Antique Mall', 'pink-elephant-antique-mall', 'roadside-oddities', 38.96131, -89.76351, 'Livingston', 'IL', 'A former school complex turned antique mall is surrounded by huge fiberglass animals and novelty figures visible from old Route 66.', 'limited', null, 'https://www.pinkelephantantiquemall.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Pink Elephant', 'pink-elephant-mio', 'roadside-oddities', 44.64778, -84.12976, 'Mio', 'MI', 'A large bright-pink elephant has stood along M-33 in Mio for decades, surviving changing businesses and becoming a local roadside landmark in its own right. The oversized animal now remains outside a commercial property as a quick, unmistakable photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/54657', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Pink Floyd — Pink Dinosaur Skeleton', 'pink-floyd-pink-dinosaur-skeleton', 'roadside-oddities', 44.43345, -68.9982, 'Belfast', 'ME', 'Beside Perry’s Nut House stands a bright pink metal dinosaur skeleton known as Pink Floyd. The current version was built by Skowhegan High School students as a sturdier replacement for an earlier wooden dinosaur, continuing the site’s long tradition of bizarre roadside displays.', 'roadside', null, 'https://www.roadsideamerica.com/tip/10583', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pinkie the Pink Elephant', 'pinkie-the-pink-elephant', 'roadside-oddities', 43.25761, -89.33579, 'DeForest', 'WI', 'A giant pink fiberglass elephant wearing glasses stands beside County Highway V, a surviving piece of classic roadside advertising that has become a local landmark in its own right. It is best treated as a quick photo stop from the business property or other lawful public areas.', 'roadside', null, 'https://www.travelwisconsin.com/stories/photo-ops-and-quirky-stops-14-must-see-wisconsin-roadside-attractions', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.travelwisconsin.com/', null, null, null, 'America/Chicago'),
  ('Pioneer Mom and Daughter Roadside Statue', 'pioneer-mom-and-daughter-roadside-statue', 'roadside-oddities', 40.77563, -76.2256, 'Frackville', 'PA', 'This roughly 15-foot roadside figure of a bonneted mother holding a pie beside her daughter became a famously unsettling piece of Pennsylvania roadside kitsch outside a former motel. The attraction is now listed as permanently closed and no longer reliably accessible, but its former location is worth recording as part of the state''s roadside-history layer.', 'closed', null, 'https://www.atlasobscura.com/places/pioneer-mom-and-daughter-roadside-statue', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pitot House', 'pitot-house', 'roadside-oddities', 29.98247, -90.08687, 'New Orleans', 'LA', 'The Pitot House is a rare surviving example of a late-eighteenth-century Creole colonial country house along Bayou St. John. Guided or posted museum access is required rather than unrestricted entry.', 'limited', null, 'https://louisianalandmarks.org/pitot-house/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Plaquemine Lock State Historic Site', 'plaquemine-lock-state-historic-site', 'roadside-oddities', 30.29243, -91.23431, 'Plaquemine', 'LA', 'This early twentieth-century lock connected Bayou Plaquemine with the Mississippi River and preserves massive engineering machinery from the era of inland waterway expansion. The locally operated museum schedule can vary, so check ahead.', 'limited', null, 'https://www.lastateparks.com/historic-sites/plaquemine-lock-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Playthings Etc. Spaceship Toy Store', 'playthings-etc-spaceship-toy-store', 'roadside-oddities', 40.96719, -79.96891, 'Clay Township', 'PA', 'Playthings Etc. opened in 2005 inside a purpose-built futuristic building the business itself describes as spaceship-shaped, complete with "engine doors." More than 7,000 toys fill the interior and many are available to try, making the strange building an actual walk-in destination rather than just novelty architecture.', 'open', null, 'https://playthings-etc.com/about/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Plum Island Pink House', 'plum-island-pink-house', 'roadside-oddities', 42.79706, -70.83062, 'Newbury', 'MA', 'An isolated pink house stands in the salt marsh beside the Plum Island Turnpike, surrounded by decades of local stories about divorce, spite and why anyone would build there. The property has faced repeated preservation and demolition controversies; view only from legal public areas and never enter the house.', 'roadside', null, 'https://www.atlasobscura.com/places/plum-island-pink-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Poet''s Seat Tower', 'poets-seat-tower', 'roadside-oddities', 42.5946, -72.5865, 'Greenfield', 'MA', 'A stone observation tower crowns Rocky Mountain above Greenfield. Its name recalls nineteenth-century writers who gathered on the hill, while the current tower gives the wooded summit the look of a miniature medieval fortification.', 'limited', null, 'https://www.atlasobscura.com/places/poets-seat-tower', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Poinsett Bridge', 'poinsett-bridge', 'roadside-oddities', 35.12941, -82.38432, 'Landrum', 'SC', 'Built in 1820, this stone bridge features a distinctive Gothic arch and is commonly identified as South Carolina’s oldest surviving bridge. Its isolated forest setting has also accumulated ghost stories and legends involving unexplained lights and sounds.', 'open', null, 'https://greenvillerec.com/parks/poinsett-bridge/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Poki, World''s Largest Desert Tortoise', 'poki-world-s-largest-desert-tortoise', 'roadside-oddities', 35.138551, -114.570245, 'Bullhead City', 'AZ', 'Poki is a roughly two-ton desert-tortoise sculpture commissioned by local resident Bill Hayes and originally displayed on his property. Hayes donated it to the community when he moved in late 2013, and it was moved to a public location in January 2014; travelers can still see Poki as a roadside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/41526', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Phoenix'),
  ('Polar Caves', 'polar-caves', 'roadside-oddities', 43.7812, -71.78112, 'Rumney', 'NH', 'Glacial boulders piled against one another here to form narrow passages, chambers and squeezes with names such as the Lemon Squeezer and Devil''s Turnpike. Unlike a traditional limestone cavern, these "caves" are spaces between enormous granite blocks left by glacial activity. The attraction is ticketed and seasonal.', 'limited', null, 'https://polarcaves.com/', '2026-09-09T04:49:39.808526+00:00', null, 'https://polarcaves.com/', null, null, null, 'America/New_York'),
  ('Pole Licker Statue — A Christmas Story', 'pole-licker-statue-a-christmas-story', 'roadside-oddities', 41.57405, -87.47055, 'Hammond', 'IN', 'A bronze boy has his tongue permanently frozen to a real flagpole outside the Indiana Welcome Center, recreating one of the best-known scenes from A Christmas Story. The tribute belongs in Hammond because author Jean Shepherd based the fictional hometown in his stories on his own northwest Indiana upbringing, even though the movie itself was filmed elsewhere.', 'open', null, 'https://visitindiana.in.gov/listing/pole-licker-statue%3A-a-christmas-story/16187/', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Polk-a-Dot Drive In', 'polk-a-dot-drive-in', 'roadside-oddities', 41.26526, -88.20999, 'Braidwood', 'IL', 'A neon-heavy Route 66 diner surrounded by fiberglass figures of Elvis, Marilyn Monroe, Superman, and other oversized pop-culture characters.', 'limited', null, 'https://www.enjoyillinois.com/explore/listing/polk-a-dot-drive-in/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ponchatoula Giant Strawberry', 'ponchatoula-giant-strawberry', 'roadside-oddities', 30.4388, -90.4401, 'Ponchatoula', 'LA', 'A giant strawberry sculpture celebrates Ponchatoula''s identity as a strawberry-growing center and festival town. The oversized fruit is an easy downtown roadside landmark.', 'roadside', null, 'https://www.ponchatoulachamber.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ponemah Bog Boardwalk', 'ponemah-bog-boardwalk', 'roadside-oddities', 42.8167, -71.5883, 'Amherst', 'NH', 'A boardwalk enters a floating bog landscape filled with sphagnum, pitcher plants, sundews and other species adapted to acidic wetland conditions. The environment can feel more like a northern peatland than suburban southern New Hampshire. Visitors should remain on the boardwalk to protect the fragile habitat.', 'open', null, 'https://www.nhaudubon.org/lands/sanctuaries/ponemah-bog/', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ponyhenge', 'ponyhenge', 'roadside-oddities', 42.40193, -71.32879, 'Lincoln', 'MA', 'A mysterious herd of rocking horses, hobby horses and plastic ponies gathers in a roadside field and continually changes as strangers add, remove and rearrange animals. The privately owned field has become an evolving folk-art installation with no formal curator.', 'open', null, 'https://www.atlasobscura.com/places/ponyhenge', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pooh''s House', 'poohs-house', 'roadside-oddities', 42.3763, -71.1166, 'Cambridge', 'MA', 'A miniature painted door at the base of a tree on Harvard''s campus has long been treated as the home of Winnie-the-Pooh. The tiny installation has been repaired and recreated over the years, turning an ordinary stump into a persistent campus folk-art landmark.', 'open', null, 'https://www.atlasobscura.com/places/poohs-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Popeye Statue', 'popeye-statue', 'roadside-oddities', 37.90507, -89.83392, 'Chester', 'IL', 'A bronze Popeye stands in Segar Memorial Park in the hometown of creator E. C. Segar, anchoring Chester''s larger Popeye character trail.', 'open', null, 'https://www.chesterill.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Potato Shed Memorial', 'potato-shed-memorial', 'roadside-oddities', 42.37195, -71.06575, 'Boston', 'MA', 'A stack of stone potato sacks marks the site of Charlestown''s old railroad potato sheds, destroyed by fire in 1962. The deliberately mundane sculpture memorializes a vanished industrial landscape with one of Boston''s strangest monuments.', 'open', null, 'https://www.atlasobscura.com/places/potato-shed-memorial', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('POW / Hanoi Hilton Monument', 'pow-hanoi-hilton-monument', 'roadside-oddities', 33.99515, -81.01408, 'Columbia', 'SC', 'This unusually severe-looking monument incorporates a fragment associated with Hanoi’s infamous Hỏa Lò Prison, nicknamed the “Hanoi Hilton” by American prisoners of war. The memorial honors South Carolinians held captive during the Vietnam War.', 'open', null, 'https://www.roadsideamerica.com/tip/70839', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Prabhupada''s Palace of Gold', 'prabhupadas-palace-of-gold', 'roadside-oddities', 39.96199, -80.60407, 'New Vrindaban', 'WV', 'Started in the 1970s as a residence for ISKCON founder A. C. Bhaktivedanta Swami Prabhupada, the project evolved into an ornate gold-covered palace decorated with stained glass, marble and elaborate interior work. It now operates as a public attraction within the New Vrindaban community and looks wildly out of place in rural West Virginia.', 'open', null, 'https://www.palaceofgold.com/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Prairie Moon Sculpture Garden', 'prairie-moon-sculpture-garden', 'roadside-oddities', 44.19721, -91.79899, 'Fountain City', 'WI', 'Retired farmer Herman Rusch created dozens of concrete and found-object sculptures across his property, including animals, people and whimsical constructions. The site is preserved as an outdoor folk-art environment and museum.', 'limited', null, 'https://www.kohlerfoundation.org/preservation/major-preservation-projects/prairie-moon-sculpture-garden-and-museum/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.kohlerfoundation.org/', null, null, null, 'America/Chicago'),
  ('Pratt Rock', 'pratt-rock', 'roadside-oddities', 42.30982, -74.42314, 'Prattsville', 'NY', 'Nineteenth-century businessman and congressman Zadock Pratt commissioned enormous carvings of himself, his family and symbols of his life directly into a Catskills cliff face. The free public park requires a steep climb from the road to reach the carvings, including an unfinished chamber originally intended as Pratt''s tomb.', 'limited', null, 'https://townofprattsville.com/historic-prattsville', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Praying Mantis Reading Lord of the Flies', 'praying-mantis-reading-lord-of-the-flies', 'roadside-oddities', 41.38257, -72.44544, 'Deep River', 'CT', 'A large scrap-metal praying mantis sits reading Lord of the Flies — an appropriately insect-themed literary joke. The sculpture moved from the local library in 2025 and now stands at the Pandemonium Rainforest Project.', 'open', null, 'https://www.roadsideamerica.com/tip/73599', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.pandemoniumrainforestproject.org/', null, null, null, 'America/New_York'),
  ('Presidents Hall of Fame', 'presidents-hall-of-fame', 'roadside-oddities', 28.56309, -81.74377, 'Clermont', 'FL', 'Old-school presidential roadside attraction with wax figures, a massive miniature White House, and a small Mount Rushmore replica.', 'limited', null, 'http://thepresidentshalloffame.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Princeton Chapel Bulldog', 'princeton-chapel-bulldog', 'roadside-oddities', 40.34871, -74.65739, 'Princeton', 'NJ', 'Among the Gothic details of Princeton University Chapel is a small bulldog incorporated into the stonework, reportedly a playful reference to rival Yale''s mascot. Finding the hidden animal turns the massive chapel exterior into an architectural scavenger hunt.', 'open', null, 'https://www.atlasobscura.com/places/princeton-chapel-bulldog', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Providence Home Geode Grotto', 'providence-home-geode-grotto', 'roadside-oddities', 38.3943, -86.93718, 'Jasper', 'IN', 'Beginning in the 1960s, Father Phillip Ottavi directed the creation of an enormous religious art environment using geodes, concrete, stone and imported statuary. The resulting shrines, grottoes, planters and garden structures spread across several blocks and remain free and open to the public.', 'open', null, 'https://spacesarchives.org/explore/search-the-online-collection/o1182449609/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('Punkyville', 'punkyville', 'roadside-oddities', 38.6452, -84.32179, 'Falmouth', 'KY', 'Beginning in 2003, Charles "Punky" Beckett built a miniature nostalgic town beside his home using vintage signs, tools and salvaged material. The personal folk-art environment includes a gas station, jail, church, bank and water tower; because it shares private residential property, visitors should arrange access or remain respectful from the roadside.', 'private', null, 'https://fotospot.com/attractions/kentucky/punkyville', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Purgatory Chasm', 'purgatory-chasm', 'roadside-oddities', 42.13634, -71.71776, 'Sutton', 'MA', 'A half-mile ravine slices through enormous blocks of granite, creating narrow passages, caves and overhangs with names that sound straight out of folklore. Glacial meltwater formed the chasm thousands of years ago; trail access can be restricted during hazardous winter conditions.', 'limited', null, 'https://www.atlasobscura.com/places/purgatory-chasm-2', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Purgatory Chasm', 'purgatory-chasm-middletown', 'roadside-oddities', 41.48733, -71.2694, 'Middletown', 'RI', 'A narrow coastal gorge cuts roughly 50 feet down through the rock at this small public overlook. Its dramatic name and sudden drop have inspired local stories while the actual formation offers a striking example of erosion along Aquidneck Island''s shoreline. Stay behind barriers and follow seasonal town access rules.', 'limited', null, 'https://www.middletownri.gov/Facilities/Facility/Details/Purgatory-Chasm-34', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pushcart Press — Tiny Roadside Bookstore', 'pushcart-press-tiny-roadside-bookstore', 'roadside-oddities', 44.323, -68.63839, 'Sedgwick', 'ME', 'A tiny self-service roadside bookshop associated with Pushcart Press claims the title of the world’s smallest bookstore. The roughly shed-sized structure uses an honor-system setup and looks more like a miniature book stand than a conventional store.', 'roadside', null, 'https://www.atlasobscura.com/places/pushcart-press-maine', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Q.J. Stephenson’s Earth Museum', 'qj-stephensons-earth-museum', 'roadside-oddities', 36.44883, -77.55425, 'Garysburg', 'NC', 'Folk artist, trapper, and fossil collector Q.J. Stephenson covered a small cinder-block museum with animal tracks, fossils, shells, artifacts, petrified wood, and bizarre handmade creatures. The privately owned site was restored after years of decline and remains viewable during daylight hours; be respectful of the surrounding residence.', 'open', null, 'https://www.roadsideamerica.com/story/15624', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Calcite Quarry Viewpoint', 'quarry-view', 'roadside-oddities', 45.389405, -83.801163, 'Rogers City', 'MI', 'Quarry View is a public turnout overlooking the enormous active Calcite limestone quarry outside Rogers City. The quarry began operating in 1911–1912 and a formal visitor overlook was first developed in 1949; today travelers stop at the roadside viewpoint to look into the working mine rather than entering the industrial site itself.', 'roadside', null, 'https://www.rogerscity.com/harbor-view.html', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Queen Connie', 'queen-connie', 'roadside-oddities', 43.88442, -73.10325, 'Leicester', 'VT', 'A roughly 19-foot concrete gorilla stands beside Route 7 while holding an old Volkswagen Beetle high above the ground. The absurd King Kong-inspired sculpture has become one of Vermont''s most recognizable roadside giants.', 'roadside', null, 'https://www.atlasobscura.com/places/queen-connie', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Quentin Compson Memorial', 'quentin-compson-memorial', 'roadside-oddities', 42.36896, -71.1232, 'Boston', 'MA', 'A tiny brass plaque on Anderson Memorial Bridge commemorates the fictional suicide of William Faulkner character Quentin Compson as if he were a real person. Literature has been quietly inserted into Boston''s physical landscape.', 'open', null, 'https://www.atlasobscura.com/places/quentin-compson-memorial', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rabbit Hash General Store and Dog Mayor Town', 'rabbit-hash-general-store-and-dog-mayor-town', 'roadside-oddities', 38.94219, -84.84598, 'Rabbit Hash', 'KY', 'Tiny Rabbit Hash is famous for ceremonially electing dogs as mayors, turning a historic Ohio River community into one of Kentucky''s strangest civic traditions. Its nineteenth-century general store remains the center of town after being rebuilt following a devastating 2016 fire.', 'open', null, 'https://www.rabbithash.com/about-us/directions.html', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.rabbithash.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('Raccoon Mountain Caverns', 'raccoon-mountain-caverns', 'roadside-oddities', 35.02122, -85.40793, 'Chattanooga', 'TN', 'Raccoon Mountain contains miles of mapped cave passage beneath the campground, with standard walking tours and more demanding wild-cave trips offered under controlled conditions. Its extensive network makes it a practical, legal alternative to unsafe abandoned-cave exploration.', 'limited', null, 'https://www.raccoonmountain.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Raleigh Muffler Man — Giant Decorator', 'raleigh-muffler-man-giant-decorator', 'roadside-oddities', 35.88054, -78.57758, 'Raleigh', 'NC', 'A towering fiberglass Muffler Man stands on private commercial property near Overlook Road, repurposed from the classic roadside-advertising giant form. It is visible from public roads and should be treated strictly as a drive-by/photo stop.', 'private', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ralph Baer Memorial', 'ralph-baer-memorial', 'roadside-oddities', 42.99333, -71.46777, 'Manchester', 'NH', 'A bronze statue of inventor Ralph Baer sits on a bench in Arms Park near the Manchester mill buildings where he developed pioneering home video-game technology. Baer is widely credited as the "father of the video game" for work that led to the Magnavox Odyssey. Visitors can sit beside the life-size figure overlooking the Merrimack River.', 'open', null, 'https://www.atlasobscura.com/places/ralph-baer-memorial', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Randyland', 'randyland', 'roadside-oddities', 40.45793, -80.00975, 'Pittsburgh', 'PA', 'Artist Randy Gilson transformed his North Side property into a brightly painted outdoor folk-art environment beginning in the 1990s. Visitors can walk through courtyards filled with murals, mannequins, mirrors, signs and repurposed objects during posted hours.', 'open', null, 'https://randy.land/', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rattlesnake Saloon', 'rattlesnake-saloon', 'roadside-oddities', 34.64816, -87.91091, 'Tuscumbia', 'AL', 'A restaurant and saloon sits beneath a huge natural rock overhang on the Seven Springs property, giving the dining area the appearance of a cave-front hideout. Operations are seasonal and days are limited, so check the current calendar before routing.', 'limited', null, 'https://www.rattlesnakesaloon.net/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Redstone Missile', 'redstone-missile', 'roadside-oddities', 43.95877, -71.90769, 'Warren', 'NH', 'A full-size Redstone missile stands improbably in a small New Hampshire town park. The missile type was originally developed as a ballistic weapon and later adapted to launch Alan Shepard, the New Hampshire-born first American in space. Its towering presence beside ordinary village surroundings makes it one of the state''s strongest roadside oddities.', 'open', null, 'https://www.atlasobscura.com/places/redstone-rocket', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Reptile World Serpentarium', 'reptile-world-serpentarium', 'roadside-oddities', 28.24275, -81.21049, 'St. Cloud', 'FL', 'Long-running serpentarium focused on venomous snakes, reptiles, and live educational snake demonstrations.', 'limited', null, 'https://www.reptileworldserpentarium.net/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Restored 1953 Sinclair Gas Station', 'restored-1953-sinclair-gas-station', 'roadside-oddities', 35.2016, -83.8229, 'Andrews', 'NC', 'A vintage Sinclair service station was restored in 2025 with period pumps, signage, and the brand’s familiar green dinosaur imagery. It no longer operates as a normal gas station, making it more of a preserved roadside time capsule and photo stop. Restoration background: https://towns-and-nature.blogspot.com/2025/11/andrews-nc-old-sinclair-gas-station.html', 'roadside', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('''Reverence'' — Whale Tails', 'reverence-whale-tails', 'roadside-oddities', 44.4455, -73.14314, 'South Burlington', 'VT', 'Two enormous black-granite whale tails appear to dive into a grassy field beside Interstate 89. Jim Sardonis created the sculpture in 1989, and its marine subject has become particularly memorable in landlocked Vermont.', 'open', null, 'https://www.atlasobscura.com/places/whale-tails', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Reversing Falls Park', 'reversing-falls-park', 'roadside-oddities', 44.8917, -67.1272, 'Pembroke', 'ME', 'Powerful tides force water through a narrow channel here, creating standing waves, whirlpools, and rapids that reverse direction as the tide changes. It is a dramatic natural oddity best treated as a viewing stop rather than a swimming location.', 'open', null, 'https://www.newenglandswimmingholes.com/maine/waterfalls/pembroke-reversing-falls', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rhinelapus', 'rhinelapus', 'roadside-oddities', 45.57678, -89.15872, 'Monico', 'WI', 'This giant jackalope-like roadside creature combines a rabbit body with antlers and has become known as the Rhinelapus. It is exactly the kind of improbable fiberglass animal OddWay is built for, but visitors should view it only from safe lawful areas near the roadside property.', 'roadside', null, 'https://www.roadsideamerica.com/location/wi/all', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/location/wi/all', null, null, null, 'America/Chicago'),
  ('Rhode Island Red Monument', 'rhode-island-red-monument', 'roadside-oddities', 41.55359, -71.12889, 'Adamsville', 'RI', 'A granite monument in the village of Adamsville commemorates the Rhode Island Red, the chicken breed developed in this area during the nineteenth century. The bird later became Rhode Island''s official state bird. The monument turns an otherwise ordinary roadside corner into a shrine to poultry history.', 'roadside', null, 'https://www.atlasobscura.com/places/rhode-island-red-monument', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rice Family Mausoleum', 'rice-family-mausoleum', 'roadside-oddities', 29.98391, -90.11761, 'New Orleans', 'LA', 'The Rice family mausoleum in Metairie Cemetery is a striking Egyptian Revival tomb whose severe geometry stands out among the surrounding monuments. It is a distinct architectural target within the cemetery.', 'limited', null, 'https://www.lakelawnmetairie.com/cemetery/metairie-cemetery', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rickwood Caverns State Park', 'rickwood-caverns-state-park', 'roadside-oddities', 33.99648, -86.76014, 'Warrior', 'AL', 'Guided tours descend into a cave system filled with formations created over immense spans of geologic time. Surface trails and recreation are generally available more broadly, while cave access follows scheduled guided-tour operations.', 'limited', null, 'https://www.alapark.com/parks/rickwood-caverns-state-park', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rim Rock National Recreation Trail', 'rim-rock-national-recreation-trail', 'roadside-oddities', 37.60253, -88.27834, 'Karbers Ridge', 'IL', 'A loop trail passes towering rock walls, narrow passages, ancient Native American stonework, and the deep canyon around Ox-Lot Cave.', 'open', null, 'https://www.fs.usda.gov/recarea/shawnee/recarea/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Ringing Rocks County Park', 'ringing-rocks-county-park', 'roadside-oddities', 40.56448, -75.12997, 'Bridgeton Township', 'PA', 'This county park contains a field of unusual diabase boulders that produce bell-like metallic tones when struck, turning the rocks themselves into a natural percussion instrument. A trail from the parking area reaches the boulder field, with High Falls elsewhere in the 128-acre park; bring a small hammer if you want to test the rocks yourself.', 'limited', null, 'https://www.buckscounty.gov/Facilities/Facility/Details/Ringing-Rocks-Park-5', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Roadside America Miniature Village', 'roadside-america-miniature-village', 'roadside-oddities', 40.51667, -76.11806, 'Shartlesville', 'PA', 'Roadside America was a massive hand-built miniature landscape that grew for decades into an elaborate model of small-town America filled with trains, buildings, lights and moving figures. The attraction permanently closed in 2020 and the collection was dispersed, so the former location is worth recording historically but there is nothing to enter today.', 'closed', null, 'https://en.wikipedia.org/wiki/Roadside_America', '2026-09-08T02:16:36.257931+00:00', null, null, null, null, null, 'America/New_York'),
  ('Roanoke Bunyan Muffler Man', 'roanoke-bunyan-muffler-man', 'roadside-oddities', 37.29893, -79.94041, 'Roanoke', 'VA', 'This roughly 25-foot fiberglass Paul Bunyan figure has served as a Williamson Road landmark for decades, with local accounts placing a giant figure at the site by the mid-twentieth century. The statue has been repeatedly repainted and still stands outside the auto-service property, where it is easily visible from the public road.', 'roadside', null, 'https://www.roadsideamerica.com/story/11784', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Roanoke Star', 'roanoke-star', 'roadside-oddities', 37.25083, -79.9325, 'Roanoke', 'VA', 'Built in 1949 as a temporary Christmas-season publicity stunt, the 88.5-foot neon star on Mill Mountain proved so popular that it became permanent. It remains the world''s largest freestanding illuminated man-made star and overlooks Roanoke from a public park and scenic viewpoint.', 'open', null, 'https://www.playroanoke.com/parks-facilities/mill-mountain-park/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Robert Wadlow Statue', 'robert-wadlow-statue', 'roadside-oddities', 38.9042, -90.1436, 'Alton', 'IL', 'A life-sized statue and replica chair honor Alton-born Robert Wadlow, the tallest reliably recorded person in human history at 8 feet 11 inches.', 'open', null, 'https://www.riversandroutes.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('RoboCop Statue', 'robocop-statue', 'roadside-oddities', 42.35116, -83.04349, 'Detroit', 'MI', 'After years of fundraising and fabrication, Detroit''s long-planned RoboCop statue was installed at Eastern Market in December 2025. The roughly 10-foot bronze figure recreates the armored police cyborg from the 1987 film, which is set in a dystopian version of Detroit.', 'open', null, 'https://easternmarket.org/robo-cop-statue/', '2026-09-08T15:31:15.588137+00:00', null, 'https://easternmarket.org/robo-cop-statue/', null, null, null, 'America/Detroit'),
  ('Rock Zoo', 'rock-zoo', 'roadside-oddities', 34.79217, -86.03698, 'Fackler', 'AL', 'A roadside menagerie of painted boulders has been transformed into bulls, turtles, roosters and other animals. The folk-art display began with a single painted rock and grew into one of north Alabama’s strangest free roadside collections.', 'roadside', null, 'https://alabamarockzoo.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rockford Tower', 'rockford-tower', 'roadside-oddities', 39.76731, -75.57489, 'Wilmington', 'DE', 'Rockford Tower looks like a stone observation tower but was built around a massive municipal water tank at the turn of the twentieth century. The roughly 115-foot structure includes an observation level that opens only on scheduled days, turning a piece of water infrastructure into one of Wilmington’s stranger viewpoints.', 'limited', null, 'https://archives.delaware.gov/delaware-historical-markers/rockford-tower/', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.visitwilmingtonde.com/listing/rockford-park/940/', null, null, null, 'America/New_York'),
  ('Rockmen Guardians', 'rockmen-guardians', 'roadside-oddities', 42.28056, -89.07655, 'Rockford', 'IL', 'Large stone-and-concrete humanoid figures stand along the Rock River like strange sentinels, making an easy, surreal photo stop.', 'open', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rollstone Boulder', 'rollstone-boulder', 'roadside-oddities', 42.58668, -71.80595, 'Fitchburg', 'MA', 'When quarrying threatened a 110-ton glacial boulder beloved by Fitchburg residents, workers blasted it into pieces, hauled those pieces downtown and painstakingly reassembled the rock on a traffic island. The resulting landmark is both an Ice Age remnant and a giant stone puzzle.', 'open', null, 'https://www.atlasobscura.com/places/rollstone-boulder', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Roofless Church', 'roofless-church', 'roadside-oddities', 38.13138, -87.93501, 'New Harmony', 'IN', 'Architect Philip Johnson designed this open-air sacred space in 1960 around a central sculptural canopy rather than enclosing the congregation beneath a conventional roof. Its stark walls, gates and dome make it one of New Harmony''s most visually unusual structures.', 'open', null, 'https://www.atlasobscura.com/places/the-roofless-church-new-harmony-indiana', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rooftop Phone Booth at Lincoln City Hall', 'rooftop-phone-booth-at-lincoln-city-hall', 'roadside-oddities', 40.14609, -89.36152, 'Lincoln', 'IL', 'A full telephone booth inexplicably sits on the roof of city hall, a surviving oddity from the days of rooftop firefighter communications.', 'roadside', null, 'https://www.lincolnil.gov/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Roscoe the Rooster Statue', 'roscoe-the-rooster-statue', 'roadside-oddities', 38.97433, -77.01216, 'Takoma Park', 'MD', 'Roscoe was a free-roaming rooster that wandered Takoma Park for roughly a decade and became so beloved that residents memorialized him after he was killed by a vehicle in 1999. A life-size bronze statue now stands along Laurel Avenue and is occasionally dressed or decorated by locals.', 'roadside', null, 'https://www.atlasobscura.com/places/roscoe-the-rooster', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Rosedown Plantation State Historic Site', 'rosedown-plantation-state-historic-site', 'roadside-oddities', 30.79602, -91.37095, 'St. Francisville', 'LA', 'Rosedown preserves a large antebellum house and formal gardens while interpreting the plantation economy and enslaved labor that sustained it. The state historic site gives travelers extensive lawful access to a landscape that would otherwise be private.', 'open', null, 'https://www.lastateparks.com/historic-sites/rosedown-plantation-state-historic-site', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Roseland Cottage — 1846 Bowling Alley', 'roseland-cottage-1846-bowling-alley', 'roadside-oddities', 41.94938, -71.97625, 'Woodstock', 'CT', 'Inside the bright Gothic Revival Roseland Cottage is an indoor bowling alley dating to 1846, often described as the oldest surviving example in the United States. The alley is included on seasonal guided tours of the house.', 'limited', null, 'https://www.roadsideamerica.com/tip/48563', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.historicnewengland.org/property/roseland-cottage/', null, null, null, 'America/New_York'),
  ('Rotting President Heads', 'rotting-president-heads', 'roadside-oddities', 37.38258, -76.75431, 'Croaker', 'VA', 'Forty-two enormous presidential busts rescued from the failed Presidents Park now decay together in a field on private industrial property near Williamsburg. The heads cannot be seen through normal walk-in access and trespassing is prohibited; visits are allowed only during occasional pre-ticketed tours and photography events.', 'limited', null, 'https://www.roadsideamerica.com/tip/2502', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Route 66 Memory Lane', 'route-66-memory-lane', 'roadside-oddities', 40.65119, -88.77946, 'Lexington', 'IL', 'A preserved stretch of original Route 66 is lined with vintage billboards, Burma-Shave signs, and period roadside displays.', 'open', null, 'https://www.enjoyillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Royal Swans of Swanton', 'royal-swans-of-swanton', 'roadside-oddities', 44.91848, -73.12498, 'Swanton', 'VT', 'Swans have been kept in the village park since the early 1960s, when the community''s original pair arrived through an arrangement associated with Queen Elizabeth II. Today''s birds are successors rather than the original royal pair, but the unusual local tradition continues.', 'open', null, 'https://www.roadsideamerica.com/tip/48674', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ruby Falls', 'ruby-falls', 'roadside-oddities', 35.0191, -85.3394, 'Chattanooga', 'TN', 'An elevator and guided cave route lead deep inside Lookout Mountain to a tall underground waterfall discovered during twentieth-century cave exploration. The combination of subterranean passages, unusual geology and the hidden waterfall makes Ruby Falls a classic Tennessee oddity.', 'limited', null, 'https://www.rubyfalls.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Rudolph Grotto Gardens', 'rudolph-grotto-gardens', 'roadside-oddities', 44.4991, -89.80063, 'Rudolph', 'WI', 'Hand-built stone shrines, winding paths and religious tableaux spread through several acres beside St. Philip Church. Local rock, shells and decorative masonry turn the grounds into one of Wisconsin''s major Catholic folk-art environments.', 'open', null, 'https://www.rudolphgrotto.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.rudolphgrotto.org/', null, null, null, 'America/Chicago'),
  ('Rusty the Muffler Man', 'rusty-the-muffler-man', 'roadside-oddities', 38.70123, -90.16732, 'Granite City', 'IL', 'Installed in 2025, this 20-foot hard-hat-wearing giant holds a sledgehammer as a tribute to Granite City''s steelworkers and industrial laborers.', 'open', null, 'https://www.riversandroutes.com/blog/giants-of-granite-city/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('SafeHouse Milwaukee', 'safehouse-milwaukee', 'roadside-oddities', 43.04071, -87.91125, 'Milwaukee', 'WI', 'This spy-themed restaurant hides behind a deliberately secretive entrance and fills its interior with espionage props, passages, gadgets and Cold War-style jokes. Guests without the password may have to prove themselves before entering, making dinner part attraction and part interactive gag.', 'open', null, 'https://www.safe-house.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.safe-house.com/', null, null, null, 'America/Chicago'),
  ('Saint Anne Shell Chapel', 'saint-anne-shell-chapel', 'roadside-oddities', 39.5093, -87.4579, 'Saint Mary-of-the-Woods', 'IN', 'Sisters of Providence constructed this tiny nineteenth-century chapel and covered its interior with shells, creating an unexpectedly ornate space in the Indiana woods. The historic structure has undergone preservation work, so interior access can vary and tours should be checked before visiting.', 'limited', null, 'https://spsmw.org/visit/must-sees/saint-anne-shell-chapel/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Sallie Howard Memorial Chapel', 'sallie-howard-memorial-chapel', 'roadside-oddities', 34.50556, -85.61556, 'Mentone', 'AL', 'Built in the 1930s as a memorial to Sallie Howard, this tiny chapel incorporates a huge natural boulder directly into its rear wall and altar area. It remains a functioning religious site, so visitors should respect services and private events.', 'limited', null, 'https://www.alapark.com/sites/default/files/2025-07/desoto%20sp_2024%20media%20Campground%20Map.pdf', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Salty the Seahorse', 'salty-the-seahorse', 'roadside-oddities', 41.66367, -70.81218, 'Mattapoisett', 'MA', 'A towering blue-green seahorse survives from a 1950s roadside gift shop and now stands preserved in a small public park. Salty is pure mid-century roadside advertising: oversized, cheerful and completely unrelated in scale to the animal it represents.', 'open', null, 'https://www.atlasobscura.com/places/salty-the-seahorse', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Salvador Dalí Museum', 'salvador-dal-museum', 'roadside-oddities', 27.76598, -82.63139, 'St. Petersburg', 'FL', 'Surrealist museum whose collection and architecture both fit the OddWay aesthetic.', 'limited', null, 'https://thedali.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Santa Claus Post Office', 'santa-claus-post-office', 'roadside-oddities', 38.12065, -86.92477, 'Santa Claus', 'IN', 'The real U.S. Post Office in a town genuinely named Santa Claus receives huge volumes of holiday mail from people seeking the town''s distinctive postmark. Local volunteers have answered children''s Santa letters for generations, turning an otherwise ordinary federal post office into a functioning piece of Christmas folklore.', 'open', null, 'https://tools.usps.com/locations/details/1380746', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Santarella', 'santarella', 'roadside-oddities', 42.25466, -73.21422, 'Tyringham', 'MA', 'A storybook estate in the Berkshires includes a dramatically curved shingle-roofed structure commonly called the Gingerbread House. Sculptor Henry Hudson Kitson reshaped the property into an architectural fantasy that looks closer to a fairy-tale illustration than a conventional New England home. Access is limited to current events, rentals or authorized visits.', 'limited', null, 'https://www.atlasobscura.com/places/santarella', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Santa’s Land Fun Park & Zoo', 'santas-land-fun-park-zoo', 'roadside-oddities', 35.4677, -83.26504, 'Cherokee', 'NC', 'This old-school Christmas amusement park has operated in the Smoky Mountains since the 1960s with Santa, rides, holiday displays, animals, and retro attractions. Its permanently festive setting feels particularly strange during warm-weather visits.', 'limited', null, 'https://santaslandnc.net/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Santa''s Land USA', 'santas-land-usa', 'roadside-oddities', 43.01038, -72.46962, 'Putney', 'VT', 'Opened in 1957, Santa''s Land is a classic Christmas-themed roadside park filled with vintage storybook buildings, figures and holiday attractions. The property has gone through multiple closures and revivals, so visitors should verify the current 2026 operating schedule before making it a dedicated stop.', 'limited', null, 'https://www.santaslandusa.com/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Santa''s Workshop at North Pole', 'santas-workshop-at-north-pole', 'roadside-oddities', 44.40088, -73.84889, 'Wilmington', 'NY', 'This vintage Christmas theme park opened in 1949 and helped pioneer the modern American theme-park concept with a year-round North Pole village built around Santa Claus. The park is closed for much of 2026 for improvements but has announced limited winter-season reopening dates, so verify the calendar before routing visitors here.', 'limited', null, 'https://www.northpoleny.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sauta Cave National Wildlife Refuge', 'sauta-cave-national-wildlife-refuge', 'roadside-oddities', 34.61314, -86.13192, 'Scottsboro', 'AL', 'Sauta Cave protects major bat colonies, including large summer emergence flights. The cave entrances themselves are closed to public entry, but designated refuge areas allow lawful observation of the landscape and seasonal bat activity.', 'limited', null, 'https://www.recreation.gov/gateways/3925', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('SC Johnson Administration Building and Research Tower', 'sc-johnson-administration-building-and-research-tower', 'roadside-oddities', 42.71352, -87.79047, 'Racine', 'WI', 'Frank Lloyd Wright''s SC Johnson complex uses mushroom-like dendriform columns, curving brick walls and a glass-tube Research Tower that looks unlike a conventional factory headquarters. Interior access is through scheduled company tours.', 'limited', null, 'https://www.scjohnson.com/en/a-family-company/architecture-and-tours/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.scjohnson.com/en/a-family-company/architecture-and-tours/', null, null, null, 'America/Chicago'),
  ('Scargo Tower', 'scargo-tower', 'roadside-oddities', 41.73944, -70.18021, 'Dennis', 'MA', 'A 30-foot cobblestone observation tower rises on Scargo Hill above Cape Cod. The present tower dates to 1901 and replaced two earlier structures, giving visitors a castle-like viewpoint over Scargo Lake and, on clear days, Cape Cod Bay.', 'open', null, 'https://www.dennishistsoc.org/scargo-tower', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Schaefer''s Auto Art', 'schaefers-auto-art', 'roadside-oddities', 42.04365, -80.13418, 'Erie', 'PA', 'Richard Schaefer transformed discarded automotive parts into an outdoor collection of enormous bugs, a rocket, "Automan," and a two-headed dinosaur along Hershey Road. The installation has existed for more than 25 years and SPACES still lists it as extant; there is a small roadside pull-off, but visitors should not park in the driveway.', 'roadside', null, 'https://www.spacesarchives.org/explore/search-the-online-collection/richard-schaefer/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Schoolhouse Beach', 'schoolhouse-beach', 'roadside-oddities', 45.39811, -86.92733, 'Washington Island', 'WI', 'Instead of sand, this Lake Michigan beach is covered with smooth white limestone cobbles polished by waves. Removing the distinctive stones is prohibited, so the unusual shoreline should be enjoyed in place.', 'open', null, 'https://www.washingtonisland-wi.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.washingtonisland-wi.com/', null, null, null, 'America/Chicago'),
  ('Scoops Sculpture Garden', 'scoops-sculpture-garden', 'roadside-oddities', 36.48166, -80.76025, 'Mount Airy', 'NC', 'Behind a seasonal ice-cream stand, a wooded path leads through a surprisingly elaborate sculpture garden. The collection includes handmade figures, a forest chapel, religious-themed artwork, and a treehouse where visitors leave written messages; the sculpture garden itself is open beyond the ice-cream season.', 'open', null, 'https://www.atlasobscura.com/places/scoops-ice-cream-and-sculpture-garden', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Scrap Metal Mariachi Band', 'scrap-metal-mariachi-band', 'roadside-oddities', 41.11188, -85.14118, 'Fort Wayne', 'IN', 'A group of mariachi musicians fabricated from scrap metal performs permanently outside Cebolla''s Mexican Grill. The welded figures transform automotive and industrial pieces into instruments, sombreros and human forms, creating an effective roadside-art stop at an active restaurant.', 'roadside', null, 'https://www.roadsideamerica.com/tip/58221', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Sculpture Fields at Montague Park', 'sculpture-fields-at-montague-park', 'roadside-oddities', 35.0286, -85.29444, 'Chattanooga', 'TN', 'Large-scale contemporary sculptures rise from a broad former industrial landscape, creating a free outdoor art park where monumental forms can be explored on foot. The scale makes the field feel more like a landscape of strange machines than a conventional gallery.', 'open', null, 'https://www.sculpturefields.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sculptured Rocks Natural Area', 'sculptured-rocks-natural-area', 'roadside-oddities', 43.70716, -71.85465, 'Groton', 'NH', 'The Cockermouth River has carved deep potholes, bowls and smooth twisting channels into the bedrock here over thousands of years. The shapes look almost intentionally sculpted, which gives the gorge its name. The state natural area is generally open for recreation, though conditions can become hazardous around high water and ice.', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/sculptured-rocks-natural-area', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sculpturedale', 'sculpturedale', 'roadside-oddities', 41.78388, -73.41756, 'Kent', 'CT', 'Sculptor Denis Curtiss has filled his rural studio grounds with more than 100 large steel and bronze animals, people and other figures. The property is an active studio and gallery, so visitors should stick to posted open hours or arrange an appointment.', 'limited', null, 'https://www.roadsideamerica.com/tip/76115', '2026-09-08T19:51:22.001704+00:00', null, 'https://kentct.com/shop', null, null, null, 'America/New_York'),
  ('Secret Caverns', 'secret-caverns', 'roadside-oddities', 42.70934, -74.39185, 'Howes Cave', 'NY', 'Secret Caverns is a deliberately old-school show cave reached by descending 103 steps into a winding underground passage. The guided route ends at a roughly 100-foot underground waterfall, and the attraction is open daily during its 2026 season.', 'open', null, 'https://secretcaverns.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('SECU Daily Planet — Giant Globe', 'secu-daily-planet-giant-globe', 'roadside-oddities', 35.7821, -78.63958, 'Raleigh', 'NC', 'A roughly three-story globe projects from the Nature Research Center of the North Carolina Museum of Natural Sciences. The giant Earth is not merely decoration: its interior contains a theater used for science programming. Museum: https://naturalsciences.org/', 'open', null, 'https://www.strangecarolinas.com/2015/01/secu-daily-planethuge-freakin-globe.html', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Seneca White Deer at Deer Haven Park', 'seneca-white-deer-at-deer-haven-park', 'roadside-oddities', 42.74418, -76.86922, 'Romulus', 'NY', 'The fenced former Seneca Army Depot became home to the world''s largest known herd of all-white white-tailed deer, descended from animals protected inside the military property for decades. Deer Haven Park now runs seasonal driving and bus tours through the old depot, combining the unusual herd with abandoned ammunition igloos and Cold War history.', 'limited', null, 'https://deerhavenpark.org/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Serenity Glass Park', 'serenity-glass-park', 'roadside-oddities', 41.811, -78.28001, 'Port Allegany', 'PA', 'Dedicated in 2017, this small public park uses etched glass-block towers, a glass castle and other artwork to tell Port Allegany''s glassmaking, lumber and natural-gas story. Travelers can walk through it freely at Route 6 and Mill Street.', 'open', null, 'https://visitanf.com/serenity-glass-park/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Seurat at Saugatuck', 'seurat-at-saugatuck', 'roadside-oddities', 42.65797, -86.20548, 'Saugatuck', 'MI', 'A public restroom building in Wicks Park carries a large community-painted adaptation of Georges Seurat''s famous Sunday-afternoon scene. First painted in 1977, the mural was saved from demolition and has been refreshed by local artists over the years.', 'open', null, 'https://www.atlasobscura.com/places/seurat-at-saugatuck-s-restroom', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Seven Sisters Oak', 'seven-sisters-oak', 'roadside-oddities', 30.3671, -90.0991, 'Mandeville', 'LA', 'This enormous live oak is recognized as one of Louisiana''s most celebrated ancient trees and is named for seven sisters connected with the property. It stands on private land, so visitors must obtain permission rather than entering uninvited.', 'private', null, 'https://www.lgcfinc.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Seven Tubs Recreation Area', 'seven-tubs-recreation-area', 'roadside-oddities', 41.23544, -75.81026, 'Plains Township', 'PA', 'Glacial meltwater and Kitchen Creek carved a chain of smooth bowls, chutes and potholes into the bedrock here, creating the formations known as the Seven Tubs. The features are reached on foot from the public recreation-area parking lot, and wet rock around the creek can be extremely slippery.', 'limited', null, 'https://pennsylvaniastateparks.reserveamerica.com/camping/pinchot-state-forest/r/facilityDetails.do?contractCode=PA&parkId=880252', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sewanee Natural Bridge', 'sewanee-natural-bridge', 'roadside-oddities', 35.1541, -85.92316, 'Sewanee', 'TN', 'A naturally eroded sandstone arch spans a wooded ravine on the Cumberland Plateau. The formation resembles deliberately constructed stonework but is entirely geological, making it a compact and easily reached natural oddity.', 'open', null, 'https://www.tn.gov/environment/natural-areas/what-we-do/sna/cu/natural-bridge.html', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shangri-La Stone Village', 'shangri-la-stone-village', 'roadside-oddities', 36.29968, -79.21458, 'Prospect Hill', 'NC', 'Retired tobacco farmer Henry Warren spent years constructing a miniature stone village beside his home. Tiny churches, theaters, homes, mills, and other buildings form a remarkably elaborate fantasy community made largely from local stone.', 'limited', null, 'https://www.atlasobscura.com/places/shangri-la-stone-village', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shark in a Box', 'shark-in-a-box', 'roadside-oddities', 39.45713, -75.657, 'Odessa', 'DE', 'A life-size fiberglass replica of Delaware''s record 840-pound mako shark hangs inside a glass-sided roadside box outside Captain Bones. After a vehicle destroyed the display in 2022, locals repaired it and returned the shark to its longtime spot.', 'open', null, 'https://www.roadsideamerica.com/story/68689', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.captainbones.net/', null, null, null, 'America/New_York'),
  ('Shea''s Gas Station Museum', 'sheas-gas-station-museum', 'roadside-oddities', 39.829, -89.63831, 'Springfield', 'IL', 'A restored service-station collection preserves pumps, signs, garage equipment, and artifacts gathered from decades of Route 66 motoring culture.', 'limited', null, 'https://www.visitspringfieldillinois.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shelby Farms Park Buffalo Herd', 'shelby-farms-park-buffalo-herd', 'roadside-oddities', 35.13881, -89.8325, 'Memphis', 'TN', 'A resident herd of American bison lives inside one of the country''s largest urban parks. Seeing massive prairie animals within metropolitan Memphis creates a surreal contrast with the surrounding city and greenway network.', 'open', null, 'https://www.shelbyfarmspark.org/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sherman Memorial Lighthouse', 'sherman-memorial-lighthouse', 'roadside-oddities', 41.49008, -79.45822, 'Tionesta', 'PA', 'A 75-foot lighthouse rises beside the Allegheny River in inland Forest County, far from any place where a navigation lighthouse would normally be needed. Jack Sherman built it as a family memorial and filled its seven floors with lighthouse-related exhibits; Peace Park and the exterior are freely accessible, while tower tours are offered only on selected dates.', 'limited', null, 'https://pabucketlist.com/exploring-the-sherman-memorial-lighthouse-in-forest-county/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shit Fountain', 'shit-fountain', 'roadside-oddities', 41.89972, -87.67463, 'Chicago', 'IL', 'A deliberately crude bronze coil created by artist Jerzy Kenar as a pointed response to dog owners who refused to clean up after pets.', 'roadside', null, 'https://www.atlasobscura.com/places/shit-fountain', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shogun Sanders Mural', 'shogun-sanders-mural', 'roadside-oddities', 39.07664, -84.5178, 'Covington', 'KY', 'Artist Jonathan Queen reimagined Colonel Sanders as a roughly 20-foot futuristic Japanese-style warrior on the exterior of Earth To Kentucky. The mural is based on a physical Shogun Sanders figure displayed inside the collectible shop, giving Kentucky''s most famous colonel a deliberately bizarre pop-culture makeover.', 'open', null, 'https://www.roadsideamerica.com/tip/85476', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shoney''s Big Boy Museum', 'shoneys-big-boy-museum', 'roadside-oddities', 38.36651, -81.6663, 'Charleston', 'WV', 'At the site where Alex Schoenbaum opened the Parkette Drive-In in 1947 stands a small outdoor monument and display telling the story of the chain that became Shoney''s Big Boy. It is more roadside kiosk than full museum, but the Big Boy-topped structure and vintage display panels remain accessible from the public parking area.', 'roadside', null, 'https://www.roadsideamerica.com/tip/34673', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Shreveport Water Works Museum', 'shreveport-water-works-museum', 'roadside-oddities', 32.5174, -93.75722, 'Shreveport', 'LA', 'The preserved McNeill Street water plant contains historic steam pumps and machinery from Shreveport''s early municipal water system. The industrial complex is unusually intact, but public access depends on current museum operations.', 'limited', null, 'https://shreveportwaterworks.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Shrine of Christ''s Passion', 'shrine-of-christs-passion', 'roadside-oddities', 41.42581, -87.47078, 'St. John', 'IN', 'This large outdoor devotional attraction uses dozens of life-size bronze sculptures to create an immersive walking route through scenes from the Passion of Christ. Regardless of religious interest, its scale and elaborate staged environments make it an unusually ambitious roadside art installation.', 'open', null, 'https://shrineofchristspassion.org/', '2026-09-08T13:34:34.826362+00:00', null, 'https://shrineofchristspassion.org/', null, null, null, 'America/Chicago'),
  ('Shrine of the Most Blessed Sacrament', 'shrine-of-the-most-blessed-sacrament', 'roadside-oddities', 34.05568, -86.68859, 'Hanceville', 'AL', 'This large Catholic shrine complex combines a Romanesque-Gothic church, cloisters and elaborate devotional architecture in rural Alabama. It remains an active religious site with visitor rules, dress expectations and service schedules.', 'limited', null, 'https://www.olamshrine.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Silky O''Sullivan''s Goats', 'silky-osullivans-goats', 'roadside-oddities', 35.13957, -90.05199, 'Memphis', 'TN', 'This Beale Street bar became famous for keeping goats in an outdoor enclosure and leaning heavily into eccentric Memphis nightlife tradition. Access follows the operating business and age rules rather than functioning as a standalone animal attraction.', 'open', null, 'https://silkyosullivans.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sing the River Sculpture', 'sing-the-river-sculpture', 'roadside-oddities', 30.44925, -91.19066, 'Baton Rouge', 'LA', 'The riverfront sculpture by Po Shu Wang responds to Mississippi River data with shifting light and sound. It turns the river''s changing conditions into a public sensory installation.', 'open', null, 'https://www.visitbatonrouge.com/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Singer Castle', 'singer-castle', 'roadside-oddities', 44.45223, -75.81216, 'Hammond', 'NY', 'This stone castle on Dark Island was built beginning in 1902 for Frederick Gilbert Bourne, president of the Singer Sewing Machine Company. Guided seasonal tours reveal hidden passageways, concealed doors and secret observation spaces, but reaching the island requires a boat.', 'limited', null, 'https://www.singercastle.com/', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Singing Beach', 'singing-beach', 'roadside-oddities', 42.57058, -70.76065, 'Manchester-by-the-Sea', 'MA', 'Under the right dry conditions, shuffling across this beach produces a distinct squeak or ''singing'' sound as similarly sized sand grains rub together. Summer parking and access are tightly controlled, so check current municipal rules before routing here.', 'limited', null, 'https://www.atlasobscura.com/places/singing-beach-at-manchester-by-the-sea', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skinny House', 'skinny-house', 'roadside-oddities', 42.36691, -71.0562, 'Boston', 'MA', 'Boston''s famously narrow ''spite house'' squeezes into a tiny North End lot. Local tradition says one brother built it to block another brother''s view after a property dispute, although details of the story vary. It remains a private residence.', 'roadside', null, 'https://www.atlasobscura.com/places/skinny-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skowhegan Indian — Bernard Langlais Sculpture', 'skowhegan-indian-bernard-langlais-sculpture', 'roadside-oddities', 44.76777, -69.7198, 'Skowhegan', 'ME', 'Bernard Langlais created this approximately 62-foot wooden sculpture for Maine’s 1969 bicentennial, and it became one of the state’s most recognizable roadside giants. The weather-damaged sculpture is undergoing an active preservation effort in 2026, so its appearance may change as work continues. Preservation update: https://www.wagmtv.com/2026/08/31/new-local-group-steps-save-restore-famous-62-foot-skowhegan-indian-sculpture/', 'roadside', null, 'https://www.roadsideamerica.com/story/6162', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skull Cliff', 'skull-cliff', 'roadside-oddities', 42.51127, -71.00806, 'Lynnfield', 'MA', 'A large skull face peers from an exposed rock wall beside the road. The painted or carved-looking feature has become a local visual landmark that makes an otherwise ordinary stretch of stone suddenly resemble a giant human head.', 'roadside', null, 'https://www.atlasobscura.com/places/skull-cliff', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sliding Rock', 'sliding-rock', 'roadside-oddities', 35.31147, -82.78758, 'Pisgah Forest', 'NC', 'A smooth 60-foot rock face functions as a natural waterslide as thousands of gallons of cold mountain water rush over it each minute. Visitors can slide down the rock into the pool below when conditions and seasonal operations allow.', 'limited', null, 'https://www.atlasobscura.com/places/sliding-rock', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Small Town X Fisherman Statue', 'small-town-x-fisherman-statue', 'roadside-oddities', 44.90444, -66.98442, 'Eastport', 'ME', 'This oversized fiberglass fisherman was created during production of the reality series Murder in Small Town X, which filmed in Eastport. The statue later took on a more serious meaning as a memorial to the show’s winner, New York firefighter Ángel Juarbe Jr., who died on September 11, 2001.', 'open', null, 'https://www.atlasobscura.com/places/small-town-x-fisherman-statue', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Smiley Face Water Tank', 'smiley-face-water-tank', 'roadside-oddities', 33.9431, -80.98965, 'Columbia', 'SC', 'A spherical blue water tank at Columbia’s wastewater facility wears a huge white line-art smile. Security fencing prevents close access, but the absurdly cheerful face remains visible from the public approach along Simon Tree Lane.', 'roadside', null, 'https://www.roadsideamerica.com/tip/9975', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Smiley Face Water Tower', 'smiley-face-water-tower', 'roadside-oddities', 41.52581, -85.06694, 'Ashley', 'IN', 'A water tower painted with an enormous smiling face, visible from the road through Ashley. It has been repainted over the years and is the thing the town is known for.', 'roadside', null, 'https://www.atlantaillinois.org/', null, null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Smiley Face Water Tower', 'smiley-face-water-tower-atlanta', 'roadside-oddities', 40.25833, -89.23537, 'Atlanta', 'IL', 'Atlanta''s bright yellow water tower wears an enormous painted smile, one of the easiest drive-by oddities on this stretch of Route 66.', 'roadside', null, 'https://www.atlantaillinois.org/', '2026-09-09T13:20:00.632788+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Smiley Face Water Tower', 'smiley-face-water-tower-longport', 'roadside-oddities', 39.31637, -74.52206, 'Longport', 'NJ', 'Longport''s blue municipal water tower wears an enormous smiling face visible above the barrier-island houses. The town restored the cheerful design after tower repairs, preserving one of the Jersey Shore''s friendliest pieces of infrastructure.', 'roadside', null, 'https://fotospot.com/attractions/new-jersey/smiley-face-water-tower', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Smoke Hole Caverns', 'smoke-hole-caverns', 'roadside-oddities', 38.98614, -79.26592, 'Cabins', 'WV', 'These commercial caverns descend beneath the mountains of Pendleton County and feature flowstone, underground pools and other formations. Access to the cave itself is by guided tour, making it a limited stop even though the associated visitor facilities are open to the public.', 'limited', null, 'https://www.smokehole.com/contact.html', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Smoky Mountain Knife Works', 'smoky-mountain-knife-works', 'roadside-oddities', 35.93447, -83.58428, 'Sevierville', 'TN', 'This enormous knife store mixes retail with museum-like displays of blades, militaria, fossils, taxidermy and other curiosities. Its scale and eclectic interior make it function as a roadside cabinet of curiosities even for travelers not shopping for knives.', 'open', null, 'https://www.smkw.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Snake Rock', 'snake-rock', 'roadside-oddities', 41.62837, -72.46252, 'Marlborough', 'CT', 'A large roadside boulder has been repeatedly painted into a bright reptilian creature, usually interpreted as a snake or turtle. The identity of the original artist is murky, and generations of repainting have turned it into a persistent piece of local roadside folk art.', 'roadside', null, 'https://www.atlasobscura.com/places/snake-rock', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Snoopy Rock', 'snoopy-rock', 'roadside-oddities', 41.52676, -72.0526, 'Preston', 'CT', 'A giant glacial boulder has been painted into Snoopy''s smiling profile, with a plywood Charlie Brown standing nearby to complete the scene. The attraction is on private property where visitors have historically been tolerated, so stay in the designated approach area and be respectful.', 'private', null, 'https://www.roadsideamerica.com/tip/45889', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Soccer Ball Rock', 'soccer-ball-rock', 'roadside-oddities', 39.5465, -86.19394, 'Bargersville', 'IN', 'A large, naturally lumpy boulder outside the South Central Soccer Academy has been painted again and again to resemble a giant soccer ball. The simple gag has survived for more than a decade and is visible from the soccer-complex grounds along Whiteland Road.', 'roadside', null, 'https://www.roadsideamerica.com/tip/73328', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Soco Tower — “Most Photographed View in the Smokies”', 'soco-tower-most-photographed-view-in-the-smokies', 'roadside-oddities', 35.51264, -83.13508, 'Maggie Valley', 'NC', 'A tall roadside observation tower behind Soco Crafts has long advertised itself as offering the “Most Photographed View in the Smokies.” For a small admission fee, visitors climb above the trees for a panoramic mountain view; the attraction remains listed by Haywood County tourism with seasonal operation.', 'limited', null, 'https://visithaywood.com/listings/soco-tower-craft-shop/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Solomon''s Castle', 'solomons-castle', 'roadside-oddities', 27.43723, -81.92193, 'Ona', 'FL', 'Hand-built silver castle filled with Howard Solomon''s found-object art and eccentric architecture.', 'limited', null, 'https://solomonscastle.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Soulsby Service Station', 'soulsby-service-station', 'roadside-oddities', 39.07111, -89.73541, 'Mount Olive', 'IL', 'The tiny 1926 Soulsby station is one of the oldest surviving filling stations along the Illinois Route 66 corridor.', 'roadside', null, 'https://illinoisroute66.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('South of the Border', 'south-of-the-border', 'roadside-oddities', 34.49778, -79.30972, 'Hamer', 'SC', 'This sprawling Interstate 95 tourist complex is impossible to miss thanks to its giant sombrero tower, neon signs, oversized animals, fiberglass figures, shops, motel, and aggressively kitschy Mexican-themed architecture. Decades of highway advertising make the attraction part roadside stop and part surreal landmark.', 'open', null, 'https://www.sobpedro.com/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('South Solon Meeting House', 'south-solon-meeting-house', 'roadside-oddities', 44.91311, -69.77861, 'Solon', 'ME', 'The plain exterior of this early-1800s meeting house hides an interior almost completely covered in vivid frescoes painted by artists in the 1950s. Biblical, symbolic, and surreal imagery fills walls and ceilings, creating one of Maine’s most unexpected historic interiors.', 'limited', null, 'https://www.atlasobscura.com/places/south-solon-meeting-house', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Souvenir Shop Gator', 'souvenir-shop-gator', 'roadside-oddities', 34.44613, -77.5614, 'Surf City', 'NC', 'Visitors enter this beach souvenir store through the open jaws of a gigantic alligator facade. The oversized reptile turns an otherwise ordinary coastal shop into a classic piece of tourist-strip roadside architecture. Current business location: https://us.nextdoor.com/pages/waves-surf-sport-holly-ridge-nc/', 'open', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Space Shuttle Discovery Tire', 'space-shuttle-discovery-tire', 'roadside-oddities', 41.5257, -73.42602, 'New Milford', 'CT', 'A real tire flown aboard Space Shuttle Discovery is mounted outside the John J. McCarthy Observatory at New Milford High School. The tire touched down after traveling millions of miles in space, turning an otherwise disposable spacecraft component into a hands-on local artifact.', 'limited', null, 'https://www.roadsideamerica.com/story/72060', '2026-09-08T18:47:23.721893+00:00', null, 'https://www.mccarthyobservatory.org/', null, null, null, 'America/New_York'),
  ('Spaceship House', 'spaceship-house', 'roadside-oddities', 35.1063, -85.34841, 'Signal Mountain', 'TN', 'This saucer-shaped Futuro-style house looks like a landed spacecraft above the Tennessee River. It is a private residence rather than a public attraction, so travelers should view it only from lawful public areas and avoid disturbing occupants.', 'private', null, 'https://www.atlasobscura.com/places/spaceship-house', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Sparky the Firehouse Dog Rock', 'sparky-the-firehouse-dog-rock', 'roadside-oddities', 41.4403, -72.11465, 'Montville', 'CT', 'A boulder outside the Montville fire company has been painted into a spotted firehouse dog named Sparky. It joins eastern Connecticut''s unusual local tradition of turning roadside rocks into oversized canine faces.', 'roadside', null, 'https://www.roadsideamerica.com/tip/45645', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sparty the Spartan', 'sparty-the-spartan', 'roadside-oddities', 42.73108, -84.48753, 'East Lansing', 'MI', 'Michigan State University''s massive Spartan figure is one of the school''s defining landmarks and was originally created from glazed terra-cotta sections. A bronze replica now stands outdoors at the prominent campus site while the fragile original is preserved indoors.', 'open', null, 'https://www.waymarking.com/waymarks/WM1B98J_Sparty_the_Spartan_Worlds_Largest_Free_Standing_Ceramic_Figure_East_Lansing_MI', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Spotty the Rock Dog', 'spotty-the-rock-dog', 'roadside-oddities', 41.52274, -72.01883, 'Preston', 'CT', 'This black-and-white dog-shaped boulder has reportedly been maintained as ''Spotty'' since 1935. A small plaque credits the original painter, making it one of the oldest surviving examples in eastern Connecticut''s peculiar painted-dog-rock tradition.', 'roadside', null, 'https://www.roadsideamerica.com/tip/22504', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sprague''s Super Service', 'spragues-super-service', 'roadside-oddities', 40.51753, -88.98074, 'Normal', 'IL', 'A restored 1931 Tudor Revival gas station is one of the most architecturally distinctive filling stations on Illinois Route 66.', 'limited', null, 'https://www.nps.gov/places/sprague-s-super-service.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Spud of Steel — Potato Head', 'spud-of-steel-potato-head', 'roadside-oddities', 42.02102, -71.49356, 'Bellingham', 'MA', 'A large Mr. Potato Head styled as a construction worker stands outside Hilltop Farms only a short distance from Rhode Island. The metal ''Spud of Steel'' is one of the few publicly displayed Potato Head statues surviving outside the toy''s home state.', 'roadside', null, 'https://www.roadsideamerica.com/tip/84008', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('St. John Cathedral Oak', 'st-john-cathedral-oak', 'roadside-oddities', 30.22328, -92.02344, 'Lafayette', 'LA', 'The enormous live oak beside the Cathedral of St. John the Evangelist is estimated to be centuries old and spreads across much of the churchyard. Its branches form a natural architectural landmark in downtown Lafayette.', 'open', null, 'https://saintjohncathedral.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('St. Joseph Shrine''s Faux-Wood Stations of the Cross', 'st-joseph-shrines-faux-wood-stations-of-the-cross', 'roadside-oddities', 42.0571, -84.16477, 'Brooklyn', 'MI', 'The outdoor Stations of the Cross at this Irish Hills shrine were built from concrete sculpted and painted to imitate logs, roots and rough-hewn wood. Created during the 1930s, the convincing faux-bois work makes the devotional landscape look as if it were constructed from enormous twisted trees rather than cement.', 'open', null, 'https://www.waymarking.com/waymarks/wm1B2JM_St_Josephs_Shrine_Fake_Wood_Sculptures_Brooklyn_MI', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('St. Margaret Shrine — Vatican Gardens Knockoff', 'st-margaret-shrine-vatican-gardens-knockoff', 'roadside-oddities', 41.19223, -73.21466, 'Bridgeport', 'CT', 'The grounds of St. Margaret Shrine form a sprawling maze of grottoes, statues, miniature shrines, stonework and gardens inspired partly by European Catholic pilgrimage sites. It feels unexpectedly elaborate for a neighborhood Connecticut shrine and is free to walk during posted hours.', 'open', null, 'https://www.roadsideamerica.com/location/ct', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.stmargaretshrine.org/', null, null, null, 'America/New_York'),
  ('St. Photios Greek Orthodox National Shrine', 'st-photios-greek-orthodox-national-shrine', 'roadside-oddities', 29.89699, -81.31397, 'St. Augustine', 'FL', 'Small shrine interpreting the story of early Greek Orthodox settlers in colonial Florida.', 'limited', null, 'https://stphotios.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Standard Oil Gasoline Station', 'standard-oil-gasoline-station', 'roadside-oddities', 41.00191, -88.52903, 'Odell', 'IL', 'This restored 1932 filling station is one of the most photogenic surviving examples of the small service stations that lined early Route 66.', 'limited', null, 'https://www.nps.gov/places/standard-oil-gasoline-station.htm', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stanley Rehder Carnivorous Plant Garden', 'stanley-rehder-carnivorous-plant-garden', 'roadside-oddities', 34.20578, -77.90728, 'Wilmington', 'NC', 'A protected garden displays native Venus flytraps, pitcher plants, sundews, and other carnivorous species in the region where Venus flytraps naturally occur. The site was also targeted in a notorious flytrap theft that helped draw attention to stronger legal protections for the plants. Current city programming: https://www.wilmingtonnc.gov/Events-directory/Flytrap-Frolic', 'open', null, 'https://www.atlasobscura.com/places/stanley-rehder-carnivorous-plant-garden', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Starlight Inn and Sunset Drive-In', 'starlight-inn-and-sunset-drive-in', 'roadside-oddities', 44.53813, -73.25171, 'Colchester', 'VT', 'This cinema-themed motel sits beside the seasonal Sunset Drive-In and leans fully into old-school movie culture. The combination of themed rooms and a functioning outdoor theater makes it more than a standard roadside motel stop.', 'limited', null, 'https://starlightinnvt.com/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Statue of Jack the Pardoned Turkey', 'statue-of-jack-the-pardoned-turkey', 'roadside-oddities', 41.78282, -72.6599, 'Hartford', 'CT', 'A bronze turkey commemorates Jack, a nineteenth-century bird linked to Abraham Lincoln and the story that helped inspire the presidential turkey-pardoning tradition. The oddly specific monument turns a bit of White House animal lore into a Hartford roadside stop.', 'open', null, 'https://www.atlasobscura.com/places/statue-of-jack-the-pardoned-turkey', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Steam Locomotive and Old Railway Cars', 'steam-locomotive-and-old-railway-cars', 'roadside-oddities', 38.54372, -75.08595, 'Ocean View', 'DE', 'A vintage steam locomotive and old passenger cars remain beside the former train-themed restaurant property in Ocean View. The equipment is fenced, but the preserved train makes an easy roadside visual stop.', 'roadside', null, 'https://www.roadsideamerica.com/location/de', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Steampunk Locomotive Built of Junk', 'steampunk-locomotive-built-of-junk', 'roadside-oddities', 43.60576, -72.98174, 'Rutland', 'VT', 'A full-size locomotive-like sculpture assembled from scrap metal and discarded industrial parts stands near Rutland''s train station. Its deliberately mechanical, steampunk appearance makes the piece look like a fantasy engine built from the remains of real machinery.', 'open', null, 'https://www.roadsideamerica.com/tip/41233', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Steampunk Tree House', 'steampunk-tree-house', 'roadside-oddities', 38.77024, -75.31092, 'Milton', 'DE', 'A 40-foot steel tree built from recycled industrial material rises at Dogfish Head''s Milton brewery. Originally created as a Burning Man art installation, the sculpture later became a private employee drinkhaus and can be seen during eligible brewery visits or tours.', 'limited', null, 'https://www.atlasobscura.com/places/steampunk-tree-house', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.dogfish.com/', null, null, null, 'America/New_York'),
  ('Stephen King’s Former House', 'stephen-kings-former-house', 'roadside-oddities', 44.80231, -68.78504, 'Bangor', 'ME', 'Stephen King’s famous red Victorian mansion and its spider-and-bat iron gate are among Bangor’s most recognizable landmarks. King no longer lives here; this is a private property stop, so view it only from the public sidewalk or street.', 'private', null, 'https://www.atlasobscura.com/places/stephen-kings-house', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stephens Gap Callahan Cave Preserve', 'stephens-gap-callahan-cave-preserve', 'roadside-oddities', 34.67688, -86.22833, 'Woodville', 'AL', 'Stephens Gap is famous for a dramatic open pit and natural bridge that can be seen from the permitted approach, while technical cave routes require proper equipment and experience. Southeastern Cave Conservancy permits are mandatory; use SCCi’s directions rather than navigating cross-country to the coordinate.', 'limited', null, 'https://saveyourcaves.org/visit.html', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Stevens Point Sculpture Park', 'stevens-point-sculpture-park', 'roadside-oddities', 44.54273, -89.57575, 'Stevens Point', 'WI', 'Large contemporary sculptures are scattered along wooded walking trails, so pieces appear unexpectedly between trees rather than inside a gallery. The free outdoor park blends a nature walk with an evolving public-art collection.', 'open', null, 'https://stevenspoint.com/435/Sculpture-Park', '2026-09-09T13:02:00.307533+00:00', null, 'https://stevenspoint.com/435/Sculpture-Park', null, null, null, 'America/Chicago'),
  ('Stew Leonard''s — World''s Largest Dairy Store', 'stew-leonards-worlds-largest-dairy-store', 'roadside-oddities', 41.12247, -73.40186, 'Norwalk', 'CT', 'Stew Leonard''s original Norwalk store grew from a small dairy shop into a maze-like food market filled with singing animatronics, costumed characters and theatrical displays. Guinness once recognized it as the world''s largest dairy store.', 'open', null, 'https://www.roadsideamerica.com/story/2052', '2026-09-08T19:51:22.001704+00:00', null, 'https://www.stewleonards.com/', null, null, null, 'America/New_York'),
  ('Stone Quarry Hill Art Park', 'stone-quarry-hill-art-park', 'roadside-oddities', 42.91344, -75.83343, 'Cazenovia', 'NY', 'Large contemporary sculptures are scattered across more than 100 acres of fields, woods and trails at this outdoor art park founded in 1991. Visitors can wander the grounds from dawn to dusk and encounter the work as part of the landscape rather than inside a conventional gallery.', 'open', null, 'https://sqhap.org/visit', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('Stone Tower', 'stone-tower', 'roadside-oddities', 43.95061, -71.5049, 'Waterville Valley', 'NH', 'This stone tower looks like the romantic ruin of an ancient structure, but that appearance was intentional from the beginning. Reverend J.M. Buckley reportedly decided the valley had nearly every scenic feature except a ruin and built one to complete the landscape. A trail from the Waterville Valley area reaches the deliberately fake relic.', 'open', null, 'https://www.atlasobscura.com/places/the-stone-tower', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Storybook Land', 'storybook-land', 'roadside-oddities', 39.42325, -74.59139, 'Egg Harbor Township', 'NJ', 'Opened in 1955, this family amusement park fills wooded grounds with three-dimensional scenes based on nursery rhymes and children''s stories. Its vintage fiberglass characters and storybook structures preserve the atmosphere of a classic mid-century roadside fairy-tale park.', 'limited', null, 'https://storybookland.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sugarbush Farm Tiny Church', 'sugarbush-farm-tiny-church', 'roadside-oddities', 43.66508, -72.46732, 'Woodstock', 'VT', 'A tiny rustic chapel sits along the walking route at Sugarbush Farm, tucked among the woods and maple-sugaring landscape. The small structure adds an unexpected roadside miniature to a working Vermont farm that is open to visitors.', 'open', null, 'https://sugarbushfarm.com/hours-directions/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Summersville Lake Lighthouse', 'summersville-lake-lighthouse', 'roadside-oddities', 38.19965, -80.86446, 'Mount Nebo', 'WV', 'Built from a recycled wind-turbine tower and dedicated in 2012, this 104-foot lighthouse is an intentionally landlocked oddity overlooking Summersville Lake. The tower can be climbed during its operating season, while off-season access may require a reservation and is weather dependent.', 'limited', null, 'https://www.atlasobscura.com/places/summersville-lake-lighthouse', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sunny the Sunfish', 'sunny-the-sunfish', 'roadside-oddities', 43.89211, -91.23917, 'Onalaska', 'WI', 'A huge bluegill/sunfish statue overlooks Lake Onalaska from a public park. The oversized fish celebrates the area''s angling culture and makes an easy stop along the Mississippi River corridor.', 'open', null, 'https://www.explorelacrosse.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.explorelacrosse.com/', null, null, null, 'America/Chicago'),
  ('Sunsphere', 'sunsphere', 'roadside-oddities', 35.9617, -83.9232, 'Knoxville', 'TN', 'The gold-glass sphere built for the 1982 World''s Fair still rises above downtown Knoxville like a retro-futurist relic. Its observation level and surviving fairground context make it one of Tennessee''s most recognizable pieces of abandoned-future architecture.', 'limited', null, 'https://www.worldsfairpark.org/sunsphere', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Super Cow — Guida''s Dairy Mascot', 'super-cow-guidas-dairy-mascot', 'roadside-oddities', 41.66552, -72.76964, 'New Britain', 'CT', 'A costumed superhero cow appears to leap across the roof of the Guida''s Dairy building. The airborne bovine is a wonderfully literal dairy mascot and one of New Britain''s easiest drive-by oddities.', 'roadside', null, 'https://www.roadsideamerica.com/tip/33135', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Superior Dome', 'superior-dome', 'roadside-oddities', 46.56042, -87.39379, 'Marquette', 'MI', 'Northern Michigan University''s enormous geodesic stadium has a 536-foot span and is recognized for the remarkable size of its wooden dome. The structure uses hundreds of massive Douglas-fir beams and can hold thousands of spectators, but interior access depends on university schedules and events.', 'limited', null, 'https://www.atlasobscura.com/places/superior-dome', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Superman Statue', 'superman-statue', 'roadside-oddities', 37.15231, -88.73267, 'Metropolis', 'IL', 'A 15-foot bronze-painted Superman dominates the courthouse square in the Illinois town officially promoted as the adopted home of the Man of Steel.', 'open', null, 'https://www.metropolistourism.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Swannanoa Palace', 'swannanoa-palace', 'roadside-oddities', 37.9614, -78.8542, 'Afton', 'VA', 'Built beginning in 1912 as a lavish marble estate for James and Sallie Dooley, Swannanoa resembles a European palace unexpectedly planted atop Virginia''s Blue Ridge. The property is privately owned and is not a normal daily attraction, but occasional scheduled tours and open-house dates have allowed public access; do not enter outside an advertised event.', 'limited', null, 'https://www.atlasobscura.com/places/swannanoa-palace', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Sweeney Punch Bowl', 'sweeney-punch-bowl', 'roadside-oddities', 40.10422, -80.66643, 'Wheeling', 'WV', 'This enormous cut-glass punch bowl was produced in the 1840s and weighs roughly 225 pounds, with a height of about five feet when assembled. It spent decades associated with the Sweeney family grave before being moved to the Oglebay Glass Museum in 1949, where it can now be seen indoors.', 'open', null, 'https://www.atlasobscura.com/places/sweeney-punch-bowl', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Synchronous Fireflies of the Great Smoky Mountains', 'synchronous-fireflies-of-the-great-smoky-mountains', 'roadside-oddities', 35.6552, -83.5817, 'Elkmont', 'TN', 'Each late spring, Photinus carolinus fireflies in the Elkmont area flash in coordinated waves, creating one of the Smokies'' strangest natural spectacles. The National Park Service controls peak-event access through a lottery and timed-entry system, so this is a seasonal, permit-dependent stop rather than a casual nighttime pull-off.', 'limited', null, 'https://www.nps.gov/grsm/learn/nature/fireflies.htm', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('TABASCO Factory Tour & Museum', 'tabasco-factory-tour-museum', 'roadside-oddities', 29.90977, -91.90245, 'Avery Island', 'LA', 'The self-guided TABASCO experience follows pepper sauce from mash aging through bottling and includes a museum devoted to the brand''s history. The factory''s global product is still made on the same salt-dome island.', 'open', null, 'https://www.tabasco.com/visit-avery-island/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tail of the Dragon — Tree of Shame', 'tail-of-the-dragon-tree-of-shame', 'roadside-oddities', 35.46672, -83.92025, 'Deals Gap', 'NC', 'The North Carolina end of the famous Tail of the Dragon sits beside the Tree of Shame, where broken motorcycle parts are hung as warnings and trophies from crashes on the road’s 318 curves. The famed 11-mile route continues into Tennessee; this pin marks the North Carolina gathering point and roadside display.', 'open', null, 'https://tailofthedragon.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Talcott Basalt Lava Pillows', 'talcott-basalt-lava-pillows', 'roadside-oddities', 41.5532, -72.81591, 'Meriden', 'CT', 'An exposed rock face behind a shopping area preserves rounded basalt structures formed when ancient lava encountered water. The strange pillow-like shapes are remnants of volcanic activity roughly 200 million years old hiding in an otherwise ordinary commercial landscape.', 'open', null, 'https://www.atlasobscura.com/places/talcott-basalt-lava-pillows', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('Taliesin', 'taliesin', 'roadside-oddities', 43.1411, -90.0704, 'Spring Green', 'WI', 'Frank Lloyd Wright''s home, studio and architectural laboratory evolved over decades on a Wisconsin hillside. Fires, rebuilding and Wright''s unconventional personal history make the estate as complicated as its celebrated architecture.', 'limited', null, 'https://www.taliesinpreservation.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.taliesinpreservation.org/', null, null, null, 'America/Chicago'),
  ('Talula the Elk Rapids Swan', 'talula-the-elk-rapids-swan', 'roadside-oddities', 44.89617, -85.40957, 'Elk Rapids', 'MI', 'This roughly 15-foot swan began life as a parade float built in 1966 to carry Miss Elk Rapids before eventually becoming a permanent landmark outside the local Chamber of Commerce. Students have helped maintain and repaint Talula over the years, and the oversized bird remains an easy roadside photo stop.', 'roadside', null, 'https://www.atlasobscura.com/places/talula-the-elk-rapids-swan', '2026-09-08T15:31:15.588137+00:00', null, 'https://www.elkrapidschamber.org/', null, null, null, 'America/Detroit'),
  ('Taylor Prayer Chapel', 'taylor-prayer-chapel', 'roadside-oddities', 39.34318, -87.38212, 'Farmersburg', 'IN', 'This tiny roadside chapel sits beside US 41 near the Vigo-Sullivan county line and was built as a quiet place where travelers could stop to pray or rest. Its miniature scale has also earned it a place in roadside-attraction guides, and visitor reports describe it as open to the public.', 'open', null, 'https://www.roadsideamerica.com/tip/12639', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Tear Drop Memorial', 'tear-drop-memorial', 'roadside-oddities', 40.66377, -74.06984, 'Bayonne', 'NJ', 'Officially titled To the Struggle Against World Terrorism, this nearly 100-foot monument consists of a split steel tower holding a huge stainless-steel teardrop. The Russian-designed 9/11 memorial stands on the Bayonne waterfront facing New York Harbor.', 'open', null, 'https://www.atlasobscura.com/places/tear-drop-memorial', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Teenage Mutant Ninja Turtles Birthplace Marker', 'teenage-mutant-ninja-turtles-birthplace-marker', 'roadside-oddities', 43.18942, -70.87109, 'Dover', 'NH', 'Kevin Eastman and Peter Laird created the Teenage Mutant Ninja Turtles in Dover in 1983, sketching the first turtle as a joke before developing the idea into a comic. A public marker and themed manhole cover now commemorate the city''s unexpected role in launching the franchise. It is a compact but legitimate pop-culture pilgrimage stop.', 'open', null, 'https://www.atlasobscura.com/places/teenage-mutant-ninja-turtles-birthplace', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Telephone Pole Farm', 'telephone-pole-farm', 'roadside-oddities', 40.79402, -74.6682, 'Chester Township', 'NJ', 'Rows of old utility poles stand upright in an open field at Highlands Ridge Park, creating the eerie appearance of a forest made entirely from telephone infrastructure. The unusual landscape is publicly accessible within the park.', 'open', null, 'https://www.atlasobscura.com/places/telephone-pole-farm', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Temple of Tolerance', 'temple-of-tolerance', 'roadside-oddities', 40.56866, -84.18397, 'Wapakoneta', 'OH', 'Jim Bowsher began assembling the Temple of Tolerance from enormous stones, found objects and historic artifacts in his Wapakoneta backyard in 1981. Despite looking like a private residential property from the street, the stone sanctuary is intentionally open to the public for free; visitors should use the designated entrance and stay within the areas opened for guests.', 'open', null, 'https://jimbowsher.com/visit/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ten Chimneys', 'ten-chimneys', 'roadside-oddities', 42.96854, -88.36758, 'Genesee Depot', 'WI', 'Broadway stars Alfred Lunt and Lynn Fontanne turned this estate into a theatrical retreat filled with highly personal rooms, art and stage-world connections. The preserved property feels more like stepping into an eccentric private set than touring a conventional historic house.', 'limited', null, 'https://www.tenchimneys.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.tenchimneys.org/', null, null, null, 'America/Chicago'),
  ('Tennessee Safari Park', 'tennessee-safari-park', 'roadside-oddities', 35.7677, -89.12577, 'Alamo', 'TN', 'A drive-through route brings visitors past camels, zebras, antelope and other animals in rural West Tennessee. The surreal roadside contrast of exotic species against farmland makes the park a memorable route stop; follow all posted feeding and vehicle rules.', 'limited', null, 'https://tennesseesafaripark.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The American Spirit Lincoln Statue', 'the-american-spirit-lincoln-statue', 'roadside-oddities', 42.88335, -73.20945, 'Bennington', 'VT', 'A monumental Abraham Lincoln stands outside the Bennington Museum in an unusually theatrical composition that also includes a small nude figure. Clyde du Vernet Hunt''s sculpture, known as The American Spirit, has become locally famous for Lincoln''s distinctive hat and imposing pose.', 'limited', null, 'https://www.roadsideamerica.com/story/32720', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Antlers Restaurant', 'the-antlers-restaurant', 'roadside-oddities', 46.49446, -84.32919, 'Sault Ste. Marie', 'MI', 'More than 200 animal mounts crowd the walls and ceiling of this long-running restaurant near the Soo Locks. The overwhelming collection of antlers, taxidermy and North Woods memorabilia makes eating here feel closer to dining inside an eccentric hunting museum.', 'open', null, 'https://www.michigan.org/property/antlers-restaurant', '2026-09-08T14:53:55.160019+00:00', null, 'https://sooantlers.com/', null, null, null, 'America/Detroit'),
  ('The Awakening', 'the-awakening', 'roadside-oddities', 38.78512, -77.01723, 'National Harbor', 'MD', 'J. Seward Johnson Jr.''s enormous sculpture depicts a giant apparently clawing his way out of the earth, with separate head, hand, arm, knee and foot emerging from the sand. The work was moved from Washington, D.C. to National Harbor in 2008 and is freely accessible on the waterfront.', 'open', null, 'https://www.atlasobscura.com/places/the-awakening-dc', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Basin', 'the-basin', 'roadside-oddities', 44.12108, -71.68295, 'Lincoln', 'NH', 'A powerful whirlpool of water and stone carved this large, smooth granite pothole at the foot of a cascade in Franconia Notch. Nineteenth-century visitors compared its near-perfect rounded walls to an enormous natural basin. It is reached by a short public trail from the parkway. Secondary source: https://www.atlasobscura.com/places/the-basin', 'open', null, 'https://www.nhstateparks.org/find-parks-trails/franconia-notch-state-park', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Bayville Dinosaur', 'the-bayville-dinosaur', 'roadside-oddities', 39.90932, -74.15487, 'Berkeley Township', 'NJ', 'A large old-school dinosaur statue stands beside Route 9 in Bayville, surviving decades of changing businesses around it. Its hand-built roadside-attraction look makes it feel like a leftover from an earlier era of highway tourism.', 'roadside', null, 'https://www.roadsideamerica.com/tip/11872', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Big Chair', 'the-big-chair', 'roadside-oddities', 35.882914, -80.082031, 'Thomasville', 'NC', 'Thomasville’s current Big Chair was erected in 1950 as a steel-and-concrete replacement for an earlier wooden giant chair built in 1922. The 30-foot landmark stands in the downtown Town Common and continues to symbolize Thomasville’s long furniture-manufacturing history.', 'roadside', null, 'https://files.nc.gov/ncdcr/nr/DV0696.pdf', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Big Duck', 'the-big-duck', 'roadside-oddities', 40.90694, -72.62306, 'Flanders', 'NY', 'Built in 1931 to sell ducks and eggs, this roughly 20-foot-tall duck-shaped building became such a famous example of novelty architecture that similar buildings are sometimes called "ducks." It is now owned by Suffolk County and operates as a visitor center and gift shop, generally open seven days a week.', 'open', null, 'https://www.suffolkcountyny.gov/Departments/Parks/Historic-Sites/The-Big-Duck', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Big Mo Drive-In', 'the-big-mo-drive-in', 'roadside-oddities', 33.85247, -81.59898, 'Monetta', 'SC', 'Originally opened in 1951, this rural drive-in theater was revived after years of closure and now operates multiple screens. A giant peach structure houses projection equipment and concessions, giving the already nostalgic theater an unmistakably South Carolina roadside centerpiece.', 'limited', null, 'https://thebigmo.com/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Big Peach', 'the-big-peach', 'roadside-oddities', 38.78835, -87.47035, 'Bruceville', 'IN', 'A giant peach rises beside this seasonal farm market in southern Indiana, a deliberately oversized symbol for a business promoting locally grown fruit. The market traditionally operates during the warmer growing season, so the sculpture is best treated as a seasonal business stop rather than guaranteed year-round access.', 'limited', null, 'https://visitindiana.in.gov/blog/post/roadside-attractions/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Vincennes'),
  ('The Big Twigs', 'the-big-twigs', 'roadside-oddities', 37.05867, -87.03109, 'Dunmor', 'KY', 'Lake Malone State Park is home to a growing family of enormous wooden characters known as the Big Twigs. The 10-to-17-foot sculptures are scattered around park trails and recreation areas in scenes involving fishing, camping, reading and wildlife.', 'open', null, 'https://visitmuhlenberg.com/big-twigs/', '2026-09-08T14:15:10.228298+00:00', null, 'https://visitmuhlenberg.com/big-twigs/', null, null, null, 'America/Chicago'),
  ('The Boat Building', 'the-boat-building', 'roadside-oddities', 41.76526, -72.67053, 'Hartford', 'CT', 'Hartford''s former Phoenix Mutual Life Insurance building curves into a long lens-like shape that resembles a boat or football from above. Its unusual geometry is often described as one of the earliest major two-sided office-building designs.', 'roadside', null, 'https://www.atlasobscura.com/places/the-boat-building', '2026-09-08T18:47:23.721893+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Broken Kilometer', 'the-broken-kilometer', 'roadside-oddities', 40.72408, -74.00211, 'New York', 'NY', 'Walter De Maria arranged 500 polished brass rods in five precisely spaced rows inside this SoHo storefront, creating a total combined length of one kilometer. The 1979 installation remains permanently maintained by Dia Art Foundation and is free to visit during posted hours.', 'open', null, 'https://www.diaart.org/visit/visit-our-locations-sites/walter-de-maria-the-broken-kilometer-new-york-united-states', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Can Opener — Gregson Street Overpass', 'the-can-opener-gregson-street-overpass', 'roadside-oddities', 35.9992, -78.91004, 'Durham', 'NC', 'This railroad bridge became internet-famous for repeatedly peeling roofs from trucks that ignored its low-clearance warnings, earning nicknames including the “Can Opener.” The clearance has since been increased, but the bridge’s long catalog of recorded crashes remains part of Durham folklore.', 'open', null, 'https://www.atlasobscura.com/places/truck-decapitating-bridge', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Caverns', 'the-caverns', 'roadside-oddities', 35.33173, -85.82505, 'Pelham', 'TN', 'A large cave has been transformed into a concert venue where audiences watch performers beneath limestone ceilings. Shows, cave tours and access are ticketed, combining geology with one of the country''s most unusual live-music rooms.', 'limited', null, 'https://www.thecaverns.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Cider Barrel', 'the-cider-barrel', 'roadside-oddities', 39.19008, -77.24192, 'Germantown', 'MD', 'This barrel-shaped building is a surviving example of novelty roadside architecture from the era when businesses were designed to look like the products they sold. The former cider stand is no longer a normal walk-in attraction, but the oversized barrel remains visible from public roadside areas.', 'roadside', null, 'https://www.roadsideamerica.com/location/md/all', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Colgate Clock', 'the-colgate-clock', 'roadside-oddities', 40.71203, -74.03389, 'Jersey City', 'NJ', 'A massive octagonal clock faces Manhattan from the Jersey City waterfront, surviving from the former Colgate-Palmolive factory complex. Its enormous illuminated face has remained a local landmark even after most of the industrial site around it disappeared.', 'open', null, 'https://www.atlasobscura.com/places/colgate-clock', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Crying Giant', 'the-crying-giant', 'roadside-oddities', 39.76537, -75.56518, 'Wilmington', 'DE', 'Tom Otterness''s ten-foot bronze figure sits hunched and weeping in the Delaware Art Museum''s sculpture garden. The strange oversized form was created as a maquette related to a proposed 9/11 memorial.', 'open', null, 'https://www.atlasobscura.com/places/the-crying-giant', '2026-09-08T18:31:51.932734+00:00', null, 'https://delart.org/', null, null, null, 'America/New_York'),
  ('The Daniels House', 'the-daniels-house', 'roadside-oddities', 42.52297, -70.88682, 'Salem', 'MA', 'A remarkably old First Period house dating to the seventeenth century now operates as an inn and tour location. Its uneven rooms, massive fireplaces and centuries of alterations provide a much more intimate experience of old Salem than a reconstructed attraction.', 'limited', null, 'https://www.atlasobscura.com/places/the-daniels-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Dinosaur Place', 'the-dinosaur-place', 'roadside-oddities', 41.43198, -72.22254, 'Oakdale', 'CT', 'A wooded trail system is populated by dozens of life-size dinosaur models, including towering sauropods and animatronic creatures. The attraction is seasonal and ticketed, but its huge prehistoric figures make it one of Connecticut''s strongest intentionally weird roadside destinations.', 'limited', null, 'https://naturesartvillage.com/the-dinosaur-place/', '2026-09-08T18:47:23.721893+00:00', null, 'https://naturesartvillage.com/', null, null, null, 'America/New_York'),
  ('The Doors of Fame', 'the-doors-of-fame', 'roadside-oddities', 38.72503, -75.08581, 'Rehoboth Beach', 'DE', 'Three old doors preserved by the Rehoboth Art League carry hundreds of signatures left by artists and local cultural figures over many decades. The doors are fragile and are not guaranteed to be on continuous display, so this is a check-ahead stop rather than a permanent walk-up exhibit.', 'limited', null, 'https://www.atlasobscura.com/places/the-doors-of-fame-rehoboth-beach-delaware', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.rehobothartleague.org/', null, null, null, 'America/New_York'),
  ('The Dutch House', 'the-dutch-house', 'roadside-oddities', 42.33581, -71.11228, 'Brookline', 'MA', 'A convincing Dutch Renaissance-style building sits among Brookline homes because it was originally constructed as a cocoa-company pavilion for the 1893 World''s Columbian Exposition in Chicago, then moved east. It remains private property and should be viewed only from public space.', 'private', null, 'https://www.atlasobscura.com/places/the-dutch-house', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Emergency Ark', 'the-emergency-ark', 'roadside-oddities', 43.97864, -83.12342, 'Port Austin', 'MI', 'Artist Scott Hocking transformed a collapsing nineteenth-century barn into a huge ship-like sculpture in 2015. The resulting ''barnboat'' appears stranded in a field near Port Austin and is best treated as a roadside art stop rather than an invitation to enter the surrounding property.', 'roadside', null, 'https://www.atlasobscura.com/places/emergency-ark-port-austin-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('The Fantastic Umbrella Factory', 'the-fantastic-umbrella-factory', 'roadside-oddities', 41.37749, -71.6617, 'Charlestown', 'RI', 'Despite the name, this rambling rural attraction is not an umbrella factory. The property grew into a collection of small shops, gardens, wandering animals, sculptures and quirky structures spread through a wooded setting. It has the loose, handmade character of an old-school roadside attraction rather than a conventional shopping center.', 'open', null, 'https://www.atlasobscura.com/places/the-fantastic-umbrella-factory', '2026-09-09T04:49:27.913704+00:00', null, 'https://www.fantasticumbrellafactory.com/', null, null, null, 'America/New_York'),
  ('The Feet and the Wave', 'the-feet-and-the-wave', 'roadside-oddities', 41.48413, -71.31491, 'Newport', 'RI', 'At the entrance to Newport''s Brick Market area, two giant bronze feet appear to step out of a curling wave embedded in the pavement. The surreal sculpture is easy to miss among the shops, but its disembodied scale makes it one of downtown Newport''s stranger pieces of public art.', 'open', null, 'https://www.roadsideamerica.com/tip/72753', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Finger', 'the-finger', 'roadside-oddities', 44.64177, -73.01529, 'Westford', 'VT', 'Three enormous wooden middle fingers rise beside Route 128 as the product of a long-running local zoning dispute. The display sits on private property, but a roadside pull-off allows visitors to see the deliberately confrontational sculptures without entering the property.', 'roadside', null, 'https://www.atlasobscura.com/places/the-finger', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Fist — Joe Louis Monument', 'the-fist-joe-louis-monument', 'roadside-oddities', 42.32874, -83.04455, 'Detroit', 'MI', 'Robert Graham''s 24-foot bronze arm and clenched fist was installed in 1987 as a monument to heavyweight champion Joe Louis. Suspended beneath a pyramidal frame near Woodward and Jefferson, the sculpture has become one of Detroit''s most unmistakable pieces of public art.', 'open', null, 'https://www.atlasobscura.com/places/giant-boxing-arm-of-joe-louis', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('The Free Stamp', 'the-free-stamp', 'roadside-oddities', 41.5055, -81.69245, 'Cleveland', 'OH', 'Claes Oldenburg and Coosje van Bruggen designed this enormous steel office stamp for Standard Oil of Ohio in the 1980s, but it spent years in storage before finally being installed in Willard Park. The sculpture measures roughly 28 feet tall and 48 feet long and spells out "FREE," making it one of downtown Cleveland''s easiest oversized-object stops.', 'open', null, 'https://clevelandhistorical.org/items/show/571', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Gay Dolphin', 'the-gay-dolphin', 'roadside-oddities', 33.69324, -78.8783, 'Myrtle Beach', 'SC', 'Opened in 1946, this enormous oceanfront souvenir store is a maze of rooms crammed with seashells, odd gifts, statues, toys, pirate merchandise, fossils, and beach kitsch. Its sprawling inventory and decades-old atmosphere make shopping here feel like exploring a commercial cabinet of curiosities.', 'open', null, 'https://www.atlasobscura.com/places/the-gay-dolphin', '2026-09-09T05:53:13.784429+00:00', null, 'https://www.gaydolphin.com/', null, null, null, 'America/New_York'),
  ('The Glass House', 'the-glass-house', 'roadside-oddities', 41.14242, -73.52939, 'New Canaan', 'CT', 'Architect Philip Johnson''s nearly transparent 1949 home reduces a house to a glass rectangle exposed on every side. The property also contains a collection of experimental buildings and landscape structures; entry is available only through scheduled tours.', 'limited', null, 'https://www.roadsideamerica.com/tip/42971', '2026-09-08T19:51:22.001704+00:00', null, 'https://theglasshouse.org/', null, null, null, 'America/New_York'),
  ('The Gumball Machine Utility Box', 'the-gumball-machine-utility-box', 'roadside-oddities', 39.75605, -75.56047, 'Wilmington', 'DE', 'A utility box in Trolley Square has been transformed into an oversized old-fashioned gumball machine, complete with painted candy, coin slot and dispensing tray. Artist Remi Poindexter created the illusion as part of a larger neighborhood public-art project.', 'open', null, 'https://www.atlasobscura.com/places/the-gumball-machine-wilmington', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Heidelberg Project', 'the-heidelberg-project', 'roadside-oddities', 42.35892, -83.0215, 'Detroit', 'MI', 'Artist Tyree Guyton began transforming vacant lots and abandoned houses on Heidelberg Street in 1986 using painted dots, discarded objects, shoes, clocks and other found material. The result became an internationally known outdoor art environment spread through a real Detroit neighborhood.', 'open', null, 'https://www.heidelberg.org/', '2026-09-08T14:53:55.160019+00:00', null, 'https://www.heidelberg.org/', null, null, null, 'America/Detroit'),
  ('The Hewer', 'the-hewer', 'roadside-oddities', 37.0054, -89.1764, 'Cairo', 'IL', 'George Grey Barnard''s muscular bronze laborer, first exhibited at the 1904 St. Louis World''s Fair, stands in Halliday Park as an unexpectedly monumental sculpture.', 'open', null, 'https://www.loc.gov/pictures/item/2020721588/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The House on the Rock', 'the-house-on-the-rock', 'roadside-oddities', 43.10016, -90.13577, 'Spring Green', 'WI', 'Alex Jordan Jr.''s sprawling complex combines impossible-looking architecture with rooms packed with automated music machines, model ships, armor, giant creatures, circus displays and the enormous indoor carousel. Few American attractions match its scale of deliberate sensory overload.', 'limited', null, 'https://www.thehouseontherock.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.thehouseontherock.com/', null, null, null, 'America/Chicago'),
  ('The Kentucky Castle', 'the-kentucky-castle', 'roadside-oddities', 38.04676, -84.65311, 'Versailles', 'KY', 'A full-scale modern castle rises unexpectedly above the horse farms along US 60 outside Lexington. Construction began decades ago, the property sat unfinished for years and later suffered a major fire before being transformed into an operating hotel, restaurant and event destination.', 'limited', null, 'https://www.thekentuckycastle.com/', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.thekentuckycastle.com/', null, null, null, 'America/New_York'),
  ('The Lady and the Winds of Change', 'the-lady-and-the-winds-of-change', 'roadside-oddities', 38.2862, -85.7413, 'Jeffersonville', 'IN', 'In an industrial corner of Jeffersonville, a large welded-metal female figure is paired with poetry and environmental elements designed to make the piece more than a conventional statue. The unexpected placement and scale turn the installation into a particularly strange public-art stop.', 'open', null, 'https://www.atlasobscura.com/places/the-lady-and-the-winds-of-change', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('The Leash Sculpture', 'the-leash-sculpture', 'roadside-oddities', 43.60644, -72.97962, 'Rutland', 'VT', 'Patrick Villiers Farrow''s bronze sculpture shows a dog straining against an invisible leash attached to an old-style parking meter. The surreal downtown piece has been a Rutland landmark since the 1980s and now stands in Depot Park.', 'open', null, 'https://siris-artinventories.si.edu/ipac20/ipac.jsp?uri=full%3D3100001~%21309420%210', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Little Village', 'the-little-village', 'roadside-oddities', 40.19536, -78.64417, 'Pleasantville', 'PA', 'A miniature roadside settlement of tiny buildings includes a school, diner, filling station and other hand-built structures beside Route 56. The display sits on private residential property, so admire it from the public roadside and do not enter the lawn unless the owners explicitly invite visitors in.', 'private', null, 'https://www.atlasobscura.com/places/little-village-pennsylvania', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Lost Sea', 'the-lost-sea', 'roadside-oddities', 35.53493, -84.43198, 'Sweetwater', 'TN', 'Craighead Caverns contains a vast underground lake explored by guided boat tour. The commercial cave mixes unusual geology, Civil War-era history and an enormous subterranean body of water, making it one of Tennessee''s strongest true roadside-underground attractions.', 'limited', null, 'https://thelostsea.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Man-Killing Clam at Sea Shell City', 'the-man-killing-clam-at-sea-shell-city', 'roadside-oddities', 45.63439, -84.63352, 'Cheboygan', 'MI', 'Sea Shell City has displayed an enormous giant-clam shell weighing hundreds of pounds as its famous "Man-Killing Clam" for decades. The label is classic roadside-showmanship rather than biology, but the shell remains a memorable centerpiece inside this seasonal northern Michigan tourist stop.', 'limited', null, 'https://www.atlasobscura.com/places/the-man-killing-clam', '2026-09-08T15:12:49.285859+00:00', null, 'https://www.seashellcitymi.com/', null, null, null, 'America/Detroit'),
  ('The Milk Can Building', 'the-milk-can-building', 'roadside-oddities', 41.96267, -71.4955, 'North Smithfield', 'RI', 'Built in the late 1920s, this giant milk-can-shaped structure once sold dairy products and ice cream beside Route 146. The building was later moved and has spent decades unused, but its oversized novelty architecture still makes it unmistakable from the highway corridor. It is private property and should be viewed only from a safe public location.', 'roadside', null, 'https://www.roadsideamerica.com/tip/8599', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Mother Vine', 'the-mother-vine', 'roadside-oddities', 35.925, -75.6684, 'Manteo', 'NC', 'A massive scuppernong grapevine on Roanoke Island may be centuries old and is often described as one of North America’s oldest cultivated grapevines. Historical documentation securely traces the vine back at least to the colonial era; it grows on private residential property whose owners have historically accommodated respectful visitors.', 'private', null, 'https://northcarolinahistory.org/encyclopedia/mother-vine/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Mushroom Shop', 'the-mushroom-shop', 'roadside-oddities', 42.39251, -71.10038, 'Somerville', 'MA', 'A shop devoted almost entirely to fungi sells unusual edible mushrooms, cultivation kits, tinctures, books and mushroom-themed objects. It functions as a small mycological gallery and community hub for people fascinated by the hidden world of fungi.', 'open', null, 'https://www.atlasobscura.com/places/the-mushroom-shop', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Mystery Hole', 'the-mystery-hole', 'roadside-oddities', 38.123751, -81.141022, 'Ansted', 'WV', 'Guided tours through a tilted building where a ball rolls uphill and standing straight feels wrong, run since 1973 beside Route 60 with a Volkswagen Beetle embedded in the wall. Fifteen or twenty minutes, seasonal hours, no cameras inside, and entirely committed to the bit.', 'limited', null, 'http://www.mysteryhole.com/', '2026-09-06T01:56:28.154232+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Nations Silo', 'the-nations-silo', 'roadside-oddities', 36.16462, -86.84974, 'Nashville', 'TN', 'A towering former industrial silo is covered by a monumental mural, turning a remnant of Nashville''s working landscape into a neighborhood landmark. Its scale is difficult to appreciate until standing beneath it.', 'open', null, 'https://www.atlasobscura.com/places/nations-silo', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The New York Earth Room', 'the-new-york-earth-room', 'roadside-oddities', 40.72598, -73.99975, 'New York', 'NY', 'Walter De Maria filled a second-floor SoHo loft with roughly 250 cubic yards of earth in 1977, turning an ordinary interior into a permanent room of dark soil. Dia Art Foundation maintains the installation and allows visitors to see it for free during posted weekly hours.', 'open', null, 'https://www.diaart.org/visit/visit-our-locations-sites/walter-de-maria-the-new-york-earth-room-new-york-united-states', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Odd', 'the-odd', 'roadside-oddities', 35.58191, -82.60404, 'Asheville', 'NC', 'Taxidermy, animal skulls, jarred creatures, dolls’ heads, unusual memorabilia, and a 17th-century bezoar are integrated directly into the decor of this Asheville bar and performance space. It feels closer to an oddities cabinet crossed with a music venue than a normal neighborhood bar.', 'open', null, 'https://www.atlasobscura.com/places/odditorium', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Old Man of Shore Road', 'the-old-man-of-shore-road', 'roadside-oddities', 43.61389, -70.21403, 'Cape Elizabeth', 'ME', 'A coastal rock formation creates the profile of an old man’s face when seen from the correct angle along Shore Road. The naturally occurring silhouette has been compared to New Hampshire’s lost Old Man of the Mountain, though it is much easier to miss.', 'roadside', null, 'https://www.atlasobscura.com/places/the-old-man-of-shore-road', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Only Swayzee in the World', 'the-only-swayzee-in-the-world', 'roadside-oddities', 40.5071, -85.8254, 'Swayzee', 'IN', 'Swayzee proudly advertises itself as the "Only Swayzee in the World," a slogan tied to a local story that a wartime postcard addressed only to "Swayzee" still reached its destination. The claim appears on town signage and has become the tiny community''s defining roadside identity.', 'roadside', null, 'https://www.in.gov/towns/swayzee/about/', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('The Paper House', 'the-paper-house', 'roadside-oddities', 42.67289, -70.63459, 'Rockport', 'MA', 'Mechanical engineer Elis Stenman built a summer house using layers of newspaper, glue and varnish instead of conventional wall material. He then continued the experiment by constructing newspaper furniture, including a desk, chairs and a piano covering. The seasonal attraction still operates on an old-fashioned honor system.', 'limited', null, 'https://www.roadsideamerica.com/story/2109', '2026-09-09T04:43:56.902716+00:00', null, 'https://paperhouserockport.com/', null, null, null, 'America/New_York'),
  ('The Parthenon', 'the-parthenon', 'roadside-oddities', 36.14975, -86.81316, 'Nashville', 'TN', 'Nashville built a full-scale replica of the ancient Parthenon for the 1897 Tennessee Centennial Exposition and later rebuilt it permanently in concrete. Inside stands a colossal Athena statue, making the structure one of the country''s most improbable pieces of civic architecture.', 'open', null, 'https://www.nashville.gov/departments/parks/parthenon', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Poky Dot', 'the-poky-dot', 'roadside-oddities', 39.47057, -80.155, 'Fairmont', 'WV', 'The Poky Dot was a famously colorful Fairmont diner known for enormous desserts, including a nine-pound banana split, and an interior that looked more like a carnival than a conventional restaurant. The business is now permanently closed, so this is a record of a vanished roadside institution; view the former location only from public ground and do not attempt to enter.', 'closed', null, 'https://www.atlasobscura.com/places/the-poky-dot', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Puking Pig', 'the-puking-pig', 'roadside-oddities', 44.53612, -72.01268, 'Lyndon Center', 'VT', 'A bronze pig fountain spits a stream of water from its mouth, giving the otherwise decorative animal its memorable local nickname. Dedicated in 1912, the sculpture is modeled on the famous Florentine Porcellino tradition.', 'open', null, 'https://www.roadsideamerica.com/tip/21367', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('The River Guardian', 'the-river-guardian', 'roadside-oddities', 44.765, -85.62064, 'Traverse City', 'MI', 'Artist Dewey Blocksma built this approximately 12-foot figure beside the Boardman River from old canoes and other found materials. The towering assemblage appears to guard the riverbank, turning discarded watercraft into one of downtown Traverse City''s strangest pieces of public art.', 'open', null, 'https://www.atlasobscura.com/places/the-river-guardian', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('The Rock and Fossil and Dinosaur Shop', 'the-rock-and-fossil-and-dinosaur-shop', 'roadside-oddities', 42.50012, -72.60924, 'Deerfield', 'MA', 'A roadside geology shop surrounds visitors with dinosaur replicas, fossils, minerals and a backyard ''Dinosaur Forest'' that even includes a UFO-and-alien scene. It is part educational rock shop and part old-school roadside attraction.', 'limited', null, 'https://www.atlasobscura.com/places/the-rock-and-fossil-and-dinosaur-shop-deerfield-massachusetts', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Ruins at Holliday Park', 'the-ruins-at-holliday-park', 'roadside-oddities', 39.87082, -86.16339, 'Indianapolis', 'IN', 'Three massive stone figures from the demolished St. Paul Building in New York City were rescued and incorporated into a strange architectural installation in Holliday Park. The sculptures now rise from a deliberately ruined-looking structure that combines public art with pieces of a vanished skyscraper.', 'open', null, 'https://www.atlasobscura.com/places/the-ruins-indianapolis-indiana', '2026-09-08T13:34:34.826362+00:00', null, 'https://www.hollidaypark.org/', null, null, null, 'America/Indiana/Indianapolis'),
  ('The Sacred Cod', 'the-sacred-cod', 'roadside-oddities', 42.35878, -71.06381, 'Boston', 'MA', 'A large carved wooden cod hangs inside the Massachusetts State House as a symbol of the fishing industry''s importance to the Commonwealth. The object has been stolen as a prank more than once, making it one of America''s stranger pieces of official government decor.', 'limited', null, 'https://www.atlasobscura.com/places/the-sacred-cod', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Secret Chamber House of Oddities and Artwork', 'the-secret-chamber-house-of-oddities-and-artwork', 'roadside-oddities', 39.82179, -84.02197, 'Fairborn', 'OH', 'The Secret Chamber is an oddities shop and gallery packed with sideshow-style specimens, skeletons, unusual taxidermy, purported haunted objects and macabre artwork. It opened in 2017 and remains a public retail stop, making it an easy detour for travelers who want something stranger than a conventional museum.', 'open', null, 'https://www.atlasobscura.com/places/the-secret-chamber-house-of-oddities-and-artwork', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Sewer Drain That Inspired “IT”', 'the-sewer-drain-that-inspired-it', 'roadside-oddities', 44.80512, -68.78521, 'Bangor', 'ME', 'A storm drain at the corner of Union and Jackson streets is locally identified as an inspiration for the infamous sewer imagery in Stephen King’s IT. It is an ordinary piece of city infrastructure, so this is a quick public-street stop rather than an attraction to enter or disturb.', 'roadside', null, 'https://www.atlasobscura.com/places/the-sewer-drain-from-it', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Singing Bridge', 'the-singing-bridge', 'roadside-oddities', 41.27786, -72.46758, 'Westbrook', 'CT', 'The bridge over the Patchogue River became famous for the musical hum produced as vehicle tires crossed its metal roadway. Rebuilding altered the original structure, but the town preserved the bridge''s unusual open-grate character and its long-running ''singing'' identity.', 'roadside', null, 'https://www.atlasobscura.com/places/the-singing-bridge', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Singing Oak', 'the-singing-oak', 'roadside-oddities', 29.9859, -90.0902, 'New Orleans', 'LA', 'Wind chimes tuned to a pentatonic scale hang high in a live oak near Big Lake in City Park, creating shifting music whenever the breeze moves through the branches. The installation is outdoors and freely viewable during park access.', 'open', null, 'https://neworleanscitypark.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Tepee', 'the-tepee', 'roadside-oddities', 42.80784, -74.68453, 'Cherry Valley', 'NY', 'This giant concrete-and-steel tepee has stood beside U.S. Route 20 since the 1950s as a surviving piece of classic American roadside architecture. It still operates as a gift shop and overlook, so visitors can stop rather than simply photograph it while driving past.', 'open', null, 'https://www.atlasobscura.com/places/the-tepee', '2026-09-08T02:40:05.196871+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Tridge', 'the-tridge', 'roadside-oddities', 43.61116, -84.24902, 'Midland', 'MI', 'Built in 1981, the Tridge is a three-way pedestrian bridge centered at the meeting of the Chippewa and Tittabawassee rivers. Three wooden spans radiate from one central support, allowing travelers to cross between three separate riverbanks from a single junction.', 'open', null, 'https://www.atlasobscura.com/places/tridge-michigan', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('The Walking Dead Mural', 'the-walking-dead-mural', 'roadside-oddities', 38.38853, -84.29633, 'Cynthiana', 'KY', 'Cynthiana native Tony Moore co-created The Walking Dead comic, giving the small Kentucky town a direct connection to the franchise. Portuguese artist Sergio Odeith painted an enormous 3D-style undead mural beside Rohs Opera House in 2016, turning downtown into a destination for comic and horror fans.', 'open', null, 'https://www.roadsideamerica.com/location/ky/all', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Weeping Glass', 'the-weeping-glass', 'roadside-oddities', 40.42162, -79.994, 'Pittsburgh', 'PA', 'Pittsburgh''s long-running oddities shop sells and displays taxidermy, bones, funeral objects, anatomical pieces, strange artwork and other macabre curiosities. It operates as a normal storefront on East Warrington Avenue during posted weekly hours, so visitors can browse without an appointment.', 'open', null, 'https://www.visitpittsburgh.com/blog/occult-shops/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Whispering Statue — Youth Triumphant', 'the-whispering-statue-youth-triumphant', 'roadside-oddities', 44.19716, -72.50146, 'Barre', 'VT', 'This 1924 war memorial includes a curved granite bench with an acoustic trick: a whisper at one end can be heard clearly at the other. The effect makes the solemn monument double as one of Barre''s strangest interactive landmarks.', 'open', null, 'https://www.waymarking.com/waymarks/wmC9VB_The_Whispering_Statue_Youth_Triumphant_Barre_Vermont', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('The Witches of Eastwick Filming Sites', 'the-witches-of-eastwick-filming-sites', 'roadside-oddities', 42.2426, -70.80339, 'Cohasset', 'MA', 'Several locations around Cohasset stood in for the fictional New England town in the 1987 supernatural comedy ''The Witches of Eastwick.'' The compact town center makes it possible to connect real streets and buildings with the film''s witchy setting.', 'open', null, 'https://www.atlasobscura.com/places/the-witches-of-eastwick-filming-sites', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thelma and Louise — Giant Pink and Gray Elephants', 'thelma-and-louise-giant-pink-and-gray-elephants', 'roadside-oddities', 32.2762, -81.08203, 'Hardeeville', 'SC', 'Two enormous fiberglass elephants known as Thelma and Louise have long served as roadside mascots for Crazy Joe’s fireworks businesses. The pair have moved over the years; this pin reflects their current Hardeeville-area home rather than an older location still repeated by some travel listings.', 'roadside', null, 'https://www.roadsideamerica.com/location/sc', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Third Man Records', 'third-man-records', 'roadside-oddities', 36.1522, -86.7782, 'Nashville', 'TN', 'Jack White''s Nashville complex combines a record shop, performance space, studio and novelty-minded vinyl culture under one roof. Its unusual releases, machines and obsession with physical recording formats make it more than a conventional music store.', 'open', null, 'https://thirdmanrecords.com/pages/nashville-store', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Thomas Edison Concrete Houses', 'thomas-edison-concrete-houses', 'roadside-oddities', 40.8378, -74.2119, 'Montclair', 'NJ', 'Thomas Edison experimented with a system for pouring entire houses from concrete as an inexpensive, durable form of mass housing. Several examples survive in Montclair, but they are private residences and should be appreciated only from public streets.', 'private', null, 'https://www.atlasobscura.com/places/thomas-edisons-concrete-houses', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thomas Edison Memorial Tower', 'thomas-edison-memorial-tower', 'roadside-oddities', 40.56306, -74.33889, 'Edison', 'NJ', 'A 131-foot Art Deco tower topped by an enormous light bulb marks the site of Thomas Edison''s Menlo Park laboratory. The nearby museum interprets the experiments conducted here, including work that helped develop recorded sound and practical electric lighting.', 'limited', null, 'https://www.menloparkmuseum.org/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thomas Wolfe’s Angel', 'thomas-wolfes-angel', 'roadside-oddities', 35.31933, -82.47518, 'Hendersonville', 'NC', 'A marble angel in Oakdale Cemetery became famous because of its association with Thomas Wolfe’s novel Look Homeward, Angel. The sculpture was carved in Italy and sold by Wolfe’s father, whose monument shop inspired major elements of the novel.', 'open', null, 'https://www.atlasobscura.com/places/thomas-wolfes-angel', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Thorny Mountain Fire Tower', 'thorny-mountain-fire-tower', 'roadside-oddities', 38.31345, -79.94589, 'Dunmore', 'WV', 'The 65-foot Thorny Mountain Fire Tower rises above Seneca State Forest and has been converted into one of West Virginia''s strangest overnight accommodations. It can be reserved during the May–October season, with a climb to a small elevated cab and wraparound views of the forest.', 'limited', null, 'https://wvstateparks.com/wp-content/uploads/2020/07/WVSP_InspirationGuide.pdf', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Three Sisters Lighthouses', 'three-sisters-lighthouses', 'roadside-oddities', 41.85947, -69.9571, 'Eastham', 'MA', 'Three small nineteenth-century lighthouse towers stand together in the woods after being retired and moved inland. Their original arrangement along the coast supposedly resembled three women in white dresses with black hats, earning them the nickname ''Three Sisters.''', 'open', null, 'https://www.nps.gov/caco/learn/historyculture/three-sisters-lighthouses.htm', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Three Sisters Sanctuary', 'three-sisters-sanctuary', 'roadside-oddities', 42.47086, -72.80926, 'Goshen', 'MA', 'A private art environment has grown into acres of mosaics, stones, metal figures, towers, dragons, glass and gardens merging into the surrounding woodland. The handmade sanctuary is still evolving and is open to paying visitors during posted hours.', 'open', null, 'https://threesisterssanctuary.com/', '2026-09-09T04:43:56.902716+00:00', null, 'https://threesisterssanctuary.com/', null, null, null, 'America/New_York'),
  ('Tiki Cheesehead', 'tiki-cheesehead', 'roadside-oddities', 44.47259, -88.45045, 'Black Creek', 'WI', 'A giant carved figure combines Wisconsin''s cheesehead identity with exaggerated tiki-style roadside art. It is a deliberately goofy photo stop that works best as a short roadside detour.', 'roadside', null, 'https://www.roadsideamerica.com/location/wi/all', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/location/wi/all', null, null, null, 'America/Chicago'),
  ('Tiki Murph — Highway Tikis', 'tiki-murph-highway-tikis', 'roadside-oddities', 38.96761, -75.43227, 'Milford', 'DE', 'A roadside yard filled with large hand-carved tiki figures, including pieces made from logs with exaggerated faces and personalities. The attraction operates seasonally, making it a better planned stop than a year-round guaranteed sight.', 'limited', null, 'https://www.roadsideamerica.com/tip/70210', '2026-09-08T18:31:51.932734+00:00', null, 'https://tikimurph.com/', null, null, null, 'America/New_York'),
  ('Tillie at The Wonder Bar', 'tillie-at-the-wonder-bar', 'roadside-oddities', 40.22329, -73.99929, 'Asbury Park', 'NJ', 'A large grinning Tillie face overlooks the exterior of The Wonder Bar, preserving Asbury Park''s long-running connection with the strange smiling mascot once associated with Palace Amusements. The present face is a tribute rather than the original mural, but it remains an easy public-roadside stop.', 'roadside', null, 'https://www.roadsideamerica.com/story/13017', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tinglewood Carvings at Orr Park', 'tinglewood-carvings-at-orr-park', 'roadside-oddities', 33.09716, -86.85862, 'Montevallo', 'AL', 'Local artist Tim Tingle carved faces, animals and fantasy creatures into dead cedar trees throughout Orr Park, leaving living trees unharmed. The result is a public walking trail filled with dozens of unexpected wooden figures.', 'open', null, 'https://www.cityofmontevallo.com/OrrPark.aspx', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tiny Church — Bardwell City Park', 'tiny-church-bardwell-city-park', 'roadside-oddities', 36.87094, -89.01056, 'Bardwell', 'KY', 'A miniature white church stands in Bardwell City Park between downtown and the railroad tracks, accompanied by an equally tiny lighthouse. The little structure is one of Kentucky''s classic miniature roadside churches and can be visited from the public park.', 'open', null, 'https://www.roadsideamerica.com/tip/10263', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tishomingo State Park Swinging Bridge', 'tishomingo-state-park-swinging-bridge', 'roadside-oddities', 34.60503, -88.17953, 'Tishomingo', 'MS', 'A suspended pedestrian bridge crossing Bear Creek amid sandstone outcrops and forest in Tishomingo State Park. The bridge is a real public park feature and a visually unusual stop rather than a generic scenic overlook.', 'open', null, 'https://www.mdwfp.com/parks-destinations/tishomingo', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Titanic Museum Attraction', 'titanic-museum-attraction', 'roadside-oddities', 35.82055, -83.57894, 'Pigeon Forge', 'TN', 'A large ship-shaped museum rises beside the Pigeon Forge strip, recreating portions of RMS Titanic and displaying artifacts connected with the disaster. Its deliberately theatrical half-scale exterior makes it one of the state''s most visually unmistakable roadside museums.', 'limited', null, 'https://titanicattraction.com/pigeon-forge', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tolstoy Park — Henry Stuart House', 'tolstoy-park-henry-stuart-house', 'roadside-oddities', 30.5568, -87.89413, 'Montrose', 'AL', 'Henry Stuart, diagnosed with tuberculosis, built this tiny round domed concrete home by hand in the 1920s as part of a simple-life experiment he called Tolstoy Park. The preserved hut now sits improbably within a modern office complex.', 'open', null, 'https://npgallery.nps.gov/NRHP/AssetDetail/90ed8e92-f403-4285-8799-4a871a0ab88f/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tomb of the Unknown Slave', 'tomb-of-the-unknown-slave', 'roadside-oddities', 29.9653, -90.0663, 'New Orleans', 'LA', 'A small memorial outside St. Augustine Church honors unnamed enslaved people who died in New Orleans. The marker is a compact but powerful physical stop tied to the city''s history of slavery and remembrance.', 'open', null, 'https://staugchurch.org/', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Topiary Park', 'topiary-park', 'roadside-oddities', 39.96115, -82.98762, 'Columbus', 'OH', 'Topiary Park recreates Georges Seurat''s painting A Sunday Afternoon on the Island of La Grande Jatte using sculpted shrubs instead of paint. More than 50 human figures along with boats, animals and landscape forms fill the public park, which can be walked during normal park hours.', 'open', null, 'https://www.atlasobscura.com/places/the-topiary-park', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Touchdown Jesus — Word of Life Mural', 'touchdown-jesus-word-of-life-mural', 'roadside-oddities', 41.70211, -86.23448, 'Notre Dame', 'IN', 'Millard Sheets'' enormous 1964 "Word of Life" mosaic on the Hesburgh Library depicts Christ with raised arms directly beyond Notre Dame Stadium. Students quickly nicknamed it "Touchdown Jesus" because the pose resembles a referee signaling a touchdown and the mural is visible from inside the stadium.', 'open', null, 'https://www.atlasobscura.com/places/the-word-of-life-mural-at-the-university-of-notre-dame', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Towanda Route 66 Parkway', 'towanda-route-66-parkway', 'roadside-oddities', 40.55902, -88.90805, 'Towanda', 'IL', 'A walking trail follows abandoned Route 66 pavement past interpretive signs, old alignments, roadside relics, and recreated historic signage.', 'open', null, 'http://route66towanda.org/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tower of History', 'tower-of-history', 'roadside-oddities', 46.49857, -84.34068, 'Sault Ste. Marie', 'MI', 'This stark 210-foot tower was built by the Catholic Church in 1968 as part of a proposed religious complex before becoming a public museum and observation tower. Its high viewing decks overlook the Soo Locks and passing freighters, while the unusual concrete structure dominates the city''s otherwise low skyline.', 'limited', null, 'https://www.atlasobscura.com/places/tower-of-history-2', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Traveler Restaurant — Free Books With Your Meal', 'traveler-restaurant-free-books-with-your-meal', 'roadside-oddities', 42.02533, -72.13991, 'Union', 'CT', 'A roadside restaurant on the Massachusetts line where every diner is invited to leave with free used books. Shelves crowd the dining room and thousands more books are stored throughout the property, turning a highway meal into an unusually literal food-and-books stop.', 'open', null, 'https://www.atlasobscura.com/places/traveler-restaurant', '2026-09-08T18:47:23.721893+00:00', null, 'https://travelerrestaurant.com/', null, null, null, 'America/New_York'),
  ('Travelers Chapel', 'travelers-chapel', 'roadside-oddities', 33.80261, -79.00689, 'Conway', 'SC', 'This miniature roadside church was built as a quiet place for travelers to stop, pray, or simply look inside. Only a handful of people can fit in the tiny sanctuary at once, making it look like a full-size church that has somehow been shrunk. Current status: https://www.roadsideamerica.com/location/sc/all', 'limited', null, 'https://www.atlasobscura.com/places/tavelers-chapel', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Travelers Giant Red Umbrella', 'travelers-giant-red-umbrella', 'roadside-oddities', 41.86067, -72.68379, 'Windsor', 'CT', 'A roughly 30-foot version of Travelers Insurance''s red umbrella logo stands outside the company''s Claim University campus. The giant corporate symbol was moved from Hartford to Windsor and is visible from the public approach even when the facility is closed.', 'roadside', null, 'https://www.roadsideamerica.com/tip/92907', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tree of Life — Audubon Park', 'tree-of-life-audubon-park', 'roadside-oddities', 29.921, -90.1294, 'New Orleans', 'LA', 'This enormous live oak is one of the most recognizable trees in Audubon Park, with massive low branches spreading close to the ground. Its age, scale and sculptural form make it a strong natural OddWay landmark.', 'open', null, 'https://audubonnatureinstitute.org/audubon-park', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tree on the Decatur County Courthouse Tower', 'tree-on-the-decatur-county-courthouse-tower', 'roadside-oddities', 39.33703, -85.48312, 'Greensburg', 'IN', 'Trees have mysteriously managed to grow from the courthouse tower high above Greensburg since the nineteenth century, with successive trees replacing earlier ones over time. The living courthouse-top tree became such a local symbol that Greensburg adopted the nickname "Tree City."', 'roadside', null, 'https://www.roadsideamerica.com/location/in/all', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Tree With Car and Bicycles', 'tree-with-car-and-bicycles', 'roadside-oddities', 40.42375, -85.6504, 'Fairmount', 'IN', 'A dead tree outside a Fairmount residence has been turned into a vertical junk-art display with a Volkswagen Beetle and bicycles lodged high among its branches. The installation is on private property at 819 N. Morton Street and should be viewed only from the public road.', 'private', null, 'https://www.roadsideamerica.com/tip/79265', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Tri-State Peak', 'tri-state-peak', 'roadside-oddities', 36.60136, -83.67525, 'Middlesboro', 'KY', 'A marker atop Tri-State Peak identifies the meeting point of Kentucky, Tennessee and Virginia. Visitors reach it by trail from Cumberland Gap National Historical Park, allowing them to stand at the junction of three states on the same hike.', 'open', null, 'https://www.nps.gov/cuga/planyourvisit/hiking-trails.htm', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tripod Rock', 'tripod-rock', 'roadside-oddities', 40.95189, -74.39186, 'Kinnelon', 'NJ', 'An enormous glacial boulder appears improbably balanced on three much smaller stones at Pyramid Mountain. The formation is natural, but its precise-looking supports have inspired repeated speculation about whether people altered or used it in the distant past.', 'open', null, 'https://www.atlasobscura.com/places/tripod-rock', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Tuckaleechee Caverns', 'tuckaleechee-caverns', 'roadside-oddities', 35.65806, -83.77419, 'Townsend', 'TN', 'These privately operated caverns take visitors beneath the Smokies through large rooms, unusual formations and an underground waterfall. The cave has been a long-running Tennessee roadside attraction and remains accessible only through posted tour operations.', 'limited', null, 'https://tuckaleecheecaverns.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tunnel Hill State Trail Railroad Tunnel', 'tunnel-hill-state-trail-railroad-tunnel', 'roadside-oddities', 37.52366, -88.83868, 'Tunnel Hill', 'IL', 'The trail''s namesake old railroad tunnel cuts through the ridge along a converted rail line now used by hikers and cyclists.', 'open', null, 'https://dnr.illinois.gov/parks/park.tunnelhill.html', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Tunnelvision', 'tunnelvision', 'roadside-oddities', 34.0072, -81.03252, 'Columbia', 'SC', 'Artist Blue Sky painted a remarkably convincing tunnel entrance on the flat wall of a downtown building. The perspective and painted roadway create an optical illusion that can briefly make the brick wall look like an actual passage through the structure.', 'open', null, 'https://www.atlasobscura.com/places/tunnelvision', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Turnip Rock', 'turnip-rock', 'roadside-oddities', 44.06847, -82.91931, 'Port Austin', 'MI', 'Wave erosion carved this Lake Huron sea stack into a top-heavy shape resembling a giant turnip, with trees growing from its narrow summit. The surrounding shoreline is private, so legitimate access is by water—most commonly kayak or boat—and visitors should never attempt to cross private land to reach it.', 'limited', null, 'https://www.atlasobscura.com/places/turnip-rock', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Turtle Hospital', 'turtle-hospital', 'roadside-oddities', 24.73057, -81.0385, 'Marathon', 'FL', 'Former motel converted into a working sea-turtle hospital with educational tours.', 'limited', null, 'https://www.turtlehospital.org/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Twisted House', 'twisted-house', 'roadside-oddities', 39.87778, -86.14379, 'Indianapolis', 'IN', 'Artist John McNaughton created this warped cedar sculpture to look like a small house twisting upward as though caught in a vortex. It stands on the grounds of the Indianapolis Art Center and can be viewed as part of the center''s outdoor sculpture environment.', 'open', null, 'https://www.atlasobscura.com/places/twisted-house-sculpture', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Two-Faced Dog Rock', 'two-faced-dog-rock', 'roadside-oddities', 41.41873, -73.44998, 'Danbury', 'CT', 'A roadside boulder has been painted as a cartoon dog with a different expression on each visible side. The rock was repainted in 2016, transforming one formerly snarling face into a sadder and friendlier-looking dog.', 'roadside', null, 'https://www.roadsideamerica.com/tip/86255', '2026-09-08T19:51:22.001704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Two-Story Outhouse', 'two-story-outhouse', 'roadside-oddities', 43.40332, -84.9746, 'Cedar Lake', 'MI', 'Cedar Lake''s famous double-decker privy traces back to an 1875 home and store whose upper floor was once connected to the outhouse by a walkway. The surviving structure is a reconstructed/restored version of the historic oddity and sits on private property, so visitors should view it from the roadside rather than attempting to use or enter it.', 'roadside', null, 'https://www.atlasobscura.com/places/two-story-outhouse-cedar-lake', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('U-505 Submarine', 'u-505-submarine', 'roadside-oddities', 41.79188, -87.58125, 'Chicago', 'IL', 'The only German U-boat captured by the United States during World War II is displayed indoors beneath the Museum of Science and Industry.', 'limited', null, 'https://www.msichicago.org/explore/whats-here/exhibits/u-505-submarine/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('UF Bat Houses', 'uf-bat-houses', 'roadside-oddities', 29.64539, -82.34569, 'Gainesville', 'FL', 'Two enormous bat houses that can hold hundreds of thousands of bats and produce dramatic evening emergences.', 'limited', null, 'https://bats.ufl.edu/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Union Watersphere', 'union-watersphere', 'roadside-oddities', 40.69327, -74.26205, 'Union Township', 'NJ', 'A spherical water tank perched on an exceptionally tall narrow column rises more than 200 feet beside major highways in Union. Long promoted as the world''s tallest watersphere, the peculiar tower looks like a giant white ball balanced on a stick.', 'roadside', null, 'https://www.roadsideamerica.com/tip/896', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Uniroyal Tire (World''s Largest Tire)', 'uniroyal-tire-world-s-largest-tire', 'roadside-oddities', 42.270523, -83.209012, 'Allen Park', 'MI', 'The Giant Uniroyal Tire began life as a 96-passenger Ferris wheel at the 1964–65 New York World’s Fair. It was moved to Allen Park in 1966 and converted into the stationary 80-foot tire landmark that still towers beside I-94; it is best viewed from public roads and nearby legal stopping points rather than approached directly.', 'roadside', null, 'https://www.uniroyaltires.com/auto/news/giant-uniroyal-tire-reaches-60-year-milestone', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Detroit'),
  ('United Fruit Company Building', 'united-fruit-company-building', 'roadside-oddities', 29.95104, -90.07055, 'New Orleans', 'LA', 'Fruit motifs carved into the facade reveal this building''s former connection to the United Fruit Company and the banana trade. The exterior is the attraction; do not treat the interior as a public museum.', 'roadside', null, 'https://www.atlasobscura.com/places/united-fruit-company-building', '2026-09-09T13:02:15.154818+00:00', null, null, null, null, null, 'America/Chicago'),
  ('United Record Pressing', 'united-record-pressing', 'roadside-oddities', 36.1431, -86.7699, 'Nashville', 'TN', 'One of the world''s best-known vinyl pressing plants has produced records for generations of major artists. Tours and public access vary, making this a check-ahead stop tied to the physical machinery behind Nashville''s music business.', 'limited', null, 'https://www.urpressing.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Unsettling Hand Sculptures', 'unsettling-hand-sculptures', 'roadside-oddities', 37.56872, -84.29613, 'Berea', 'KY', 'Berea''s 2003 Show of Hands public-art project scattered a dozen roughly six-foot fiberglass hands around town, each decorated differently by an artist. Several still survive in the Old Town area, and the visitor center at 3 Artist Circle is the best starting point for finding them.', 'open', null, 'https://www.roadsideamerica.com/tip/51090', '2026-09-08T14:42:00.461026+00:00', null, 'https://visitberea.com/', null, null, null, 'America/New_York'),
  ('Upended Cadillac', 'upended-cadillac', 'roadside-oddities', 38.32072, -85.74691, 'Clarksville', 'IN', 'A vintage Cadillac is buried nose-first into the pavement outside the former Couch''s Body Shop location on Blackiston Mill Road. A mannequin once sat dramatically on the exposed rear of the car and later reports described it being replaced by other props, but the half-buried automobile itself remains the core attraction.', 'roadside', null, 'https://www.roadsideamerica.com/tip/454', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Upper Room Chapel', 'upper-room-chapel', 'roadside-oddities', 35.06235, -80.90259, 'Fort Mill', 'SC', 'This chapel survives from the enormous Heritage USA televangelist complex once operated by Jim and Tammy Faye Bakker. Modeled after the traditional Upper Room in Jerusalem, it continues to host worship services even though most of the surrounding Christian theme-park empire disappeared. Current services: https://www.btbab.net/about-1', 'limited', null, 'https://upperroomchapel.com/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Uranus Fudge Factory & General Store', 'uranus-fudge-factory-general-store', 'roadside-oddities', 40.06145, -85.70098, 'Anderson', 'IN', 'Indiana''s first Uranus Fudge Factory opened in Anderson in 2022 and commits completely to its deliberately ridiculous name through signs, jokes, photo opportunities and a general store built around fudge. The active business also includes ice cream and seasonal mini golf, making it a modern roadside attraction rather than merely a novelty sign.', 'open', null, 'https://uranusindiana.com/anderson/', '2026-09-08T13:20:58.818667+00:00', null, 'https://uranusindiana.com/', null, null, null, 'America/Indiana/Indianapolis'),
  ('U.S. Army Airborne & Special Operations Museum', 'us-army-airborne-special-operations-museum', 'roadside-oddities', 35.05594, -78.88555, 'Fayetteville', 'NC', 'This large Army museum traces airborne and special-operations history through full-size aircraft, vehicles, weapons, parachuting displays, immersive scenes, and major artifacts. Exhibits include equipment ranging from World War II gliders to modern special-operations hardware. Official Army listing: https://history.army.mil/Army-Museum-Enterprise/Find-an-Army-Museum/Airborne-and-Special-Operations-Museum/', 'limited', null, 'https://www.asomf.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('USS Albacore', 'uss-albacore', 'roadside-oddities', 43.08225, -70.76696, 'Portsmouth', 'NH', 'USS Albacore was an experimental submarine whose streamlined hull helped shape later generations of U.S. Navy submarines. The vessel now sits permanently on land, allowing visitors to climb inside its cramped compartments and control spaces. The museum operates most of the year but closes during part of the winter.', 'limited', null, 'https://www.ussalbacore.org/', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.ussalbacore.org/', null, null, null, 'America/New_York'),
  ('USS Kearsarge Stone Ship Memorial', 'uss-kearsarge-stone-ship-memorial', 'roadside-oddities', 47.26935, -88.42012, 'Kearsarge', 'MI', 'Workers built this ship-shaped stone veterans memorial during the 1930s, naming it for the Civil War-era USS Kearsarge. A mining drill stands in for a naval gun on the unusual landlocked vessel, tying Copper Country industry to naval and military remembrance.', 'open', null, 'https://www.waymarking.com/waymarks/WMCEKY_USS_Kearsarge_Ship_of_Stones_Kearsarge_MI', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('USS Yorktown', 'uss-yorktown', 'roadside-oddities', 32.7919, -79.90943, 'Mount Pleasant', 'SC', 'The enormous Essex-class aircraft carrier USS Yorktown is permanently docked at Patriots Point and open for exploration. Visitors can walk through crew spaces, hangar areas, the flight deck, and exhibits filled with historic aircraft.', 'limited', null, 'https://www.patriotspoint.org/exhibits/uss-yorktown/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vanadu Art House', 'vanadu-art-house', 'roadside-oddities', 38.96074, -76.95407, 'Hyattsville', 'MD', 'Artist and conservator Clarke Bedford transformed his home and vehicles into dense assemblages of metal, found objects, antlers, machine parts and architectural fragments. It is a private residence: admire it from the public street unless the owner is present and explicitly welcomes visitors onto the grounds.', 'private', null, 'https://www.atlasobscura.com/places/vanadu-art-house', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vasehenge', 'vasehenge', 'roadside-oddities', 39.93945, -82.01552, 'Zanesville', 'OH', 'Vasehenge was a circle of enormous painted ceramic vases installed as a tribute to Zanesville''s pottery heritage. The installation has been removed and is no longer accessible, but the former location is worth recording as a closed OddWay stop rather than sending travelers there expecting the giant vases to remain.', 'closed', null, 'https://www.atlasobscura.com/places/vasehenge', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Veal''s Ice Tree', 'veals-ice-tree', 'roadside-oddities', 39.67528, -85.96343, 'Acton', 'IN', 'Since 1961, the Veal family has used pond water and winter weather to build an enormous naturally frozen sculpture beside their home. Pipes and sprinklers add layer after layer until the "tree" becomes a towering mass of icicles, but it only appears when sustained cold makes construction possible.', 'limited', null, 'https://vealsicetree.wixsite.com/vealsicetree', '2026-09-08T13:53:25.695107+00:00', null, 'https://vealsicetree.wixsite.com/vealsicetree', null, null, null, 'America/Indiana/Indianapolis'),
  ('Venus Flytraps at Lewis Ocean Bay Heritage Preserve', 'venus-flytraps-at-lewis-ocean-bay-heritage-preserve', 'roadside-oddities', 33.80624, -78.88964, 'Conway', 'SC', 'Wild Venus flytraps grow naturally in this protected landscape near Myrtle Beach, within the plant’s remarkably small native range in the Carolinas. Visitors must stay on legitimate access routes and never remove or disturb the carnivorous plants.', 'limited', null, 'https://www.dnr.sc.gov/mlands/managedland?p_id=105', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vermontasaurus', 'vermontasaurus', 'roadside-oddities', 43.88636, -72.25079, 'Thetford', 'VT', 'This enormous dinosaur-like folk sculpture was assembled from scrap lumber near the Post Mills Airport. The roughly 122-foot-long creature became locally famous after a dispute over whether something this large counted as art or as a building requiring a permit.', 'limited', null, 'https://www.atlasobscura.com/places/vermontasaurus', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vermont''s Marble Mansions', 'vermonts-marble-mansions', 'roadside-oddities', 43.59395, -73.26772, 'Fair Haven', 'VT', 'Fair Haven''s marble industry left the town with several striking homes built or faced with the same stone that made the region famous. The unusual cluster gives ordinary residential architecture the appearance of small civic monuments; most buildings should be viewed from public streets.', 'roadside', null, 'https://www.atlasobscura.com/places/vermonts-marble-mansions', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vicksburg Riverfront Murals', 'vicksburg-riverfront-murals', 'roadside-oddities', 32.35213, -90.88338, 'Vicksburg', 'MS', 'A long series of large painted panels on the Mississippi River floodwall depicting episodes from Vicksburg''s history, river culture and local legends. The outdoor location makes the murals an easy walkable stop immediately beside downtown river attractions.', 'open', null, 'https://www.vicksburg.org/things-to-do/attractions/vicksburg-riverfront-murals/', '2026-09-09T12:59:48.572362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Victor Victori''s Multiplism Statues', 'victor-victoris-multiplism-statues', 'roadside-oddities', 40.82578, -74.10561, 'Rutherford', 'NJ', 'Artist Victor Victori filled the lawn around his home with a crowd of expressive white figures tied to his ''multiplism'' style. The sculptures are on private residential property, so travelers should view them only from the public sidewalk or street.', 'roadside', null, 'https://www.roadsideamerica.com/tip/13376', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vietnam Experience at Patriots Point', 'vietnam-experience-at-patriots-point', 'roadside-oddities', 32.78956, -79.9056, 'Mount Pleasant', 'SC', 'Patriots Point recreates a Vietnam-era brown-water Navy support base and Marine artillery position with bunkers, helicopters, vehicles, equipment, and immersive environments. The land-based exhibit can easily be overlooked by visitors focused only on the nearby ships.', 'limited', null, 'https://www.patriotspoint.org/exhibits/vietnam-experience/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Viking Golf — Trolls and Two-Headed Dragon', 'viking-golf-trolls-and-two-headed-dragon', 'roadside-oddities', 38.45262, -75.05367, 'Fenwick Island', 'DE', 'A Viking-themed miniature-golf course populated by oversized Norse figures, trolls and a large two-headed dragon. It is a commercial attraction rather than folklore history, but the sculptural theming makes it a strong visual OddWay stop during its operating season.', 'limited', null, 'https://www.roadsideamerica.com/tip/50777', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.fenwickfun.com/', null, null, null, 'America/New_York'),
  ('Vincelette Futuro House', 'vincelette-futuro-house', 'roadside-oddities', 38.92018, -75.51445, 'Houston', 'DE', 'Another surviving Futuro House — one of the distinctive prefabricated flying-saucer homes designed in the late 1960s — stands on Deep Grass Lane. It is a private residence and should be treated strictly as a public-road viewing stop.', 'private', null, 'https://npgallery.nps.gov/AssetDetail/NRIS/100006880', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vintage Car on Top of a Laundromat', 'vintage-car-on-top-of-a-laundromat', 'roadside-oddities', 34.22685, -80.70115, 'Lugoff', 'SC', 'An old automobile sits on the roof of a laundromat at the former Boykin Studebaker building. The car was restored to the roof after local residents missed the landmark when it was temporarily removed, preserving an eccentric piece of the building’s automotive past.', 'roadside', null, 'https://www.roadsideamerica.com/tip/30265', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Virgin Falls Pocket Wilderness', 'virgin-falls-pocket-wilderness', 'roadside-oddities', 35.84676, -85.31158, 'Sparta', 'TN', 'A strenuous trail leads through sinkhole and cave-country terrain to a waterfall that emerges from one cave opening and disappears into another. State-owned caves in the area may be closed to protect bats; stay on the designated trail and obey all cave restrictions.', 'limited', null, 'https://www.atlasobscura.com/places/virgin-falls-pocket-wilderness', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Vollis Simpson Whirligig Park', 'vollis-simpson-whirligig-park', 'roadside-oddities', 35.72268, -77.91245, 'Wilson', 'NC', 'More than two dozen enormous kinetic sculptures by North Carolina folk artist Vollis Simpson fill this downtown park. Built from salvaged industrial parts, reflectors, fans, gears, and metal scraps, the towering whirligigs spin and flash whenever the wind catches them. Archive: https://spacesarchives.org/explore/search-the-online-collection/vollis-simpson-whirligigs/', 'open', null, 'https://www.wilsonwhirligigpark.org/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Vulcan Park & Museum', 'vulcan-park-museum', 'roadside-oddities', 33.49171, -86.79601, 'Birmingham', 'AL', 'The colossal cast-iron statue of Vulcan was created for the 1904 World’s Fair and now overlooks Birmingham from Red Mountain. A museum and observation tower explain the giant figure and the iron industry that created it.', 'open', null, 'https://visitvulcan.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wade Avenue Pumping Station “House”', 'wade-avenue-pumping-station-house', 'roadside-oddities', 35.8006, -78.67835, 'Raleigh', 'NC', 'This convincing suburban-looking house has shutters, columns, and a front-door facade, but no one lives inside. The city deliberately disguised a noisy municipal water pumping station as a residence to make the industrial facility blend into the neighborhood.', 'roadside', null, 'https://www.atlasobscura.com/places/pumping-station-house', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Walk of the Planets', 'walk-of-the-planets', 'roadside-oddities', 45.74583, -87.05293, 'Escanaba', 'MI', 'Escanaba''s downtown contains a 1.3-mile scale model of the solar system beginning with the Sun and continuing past markers for the planets. The distances between the markers are scaled to emphasize just how much empty space separates the worlds in the real solar system.', 'open', null, 'https://www.roadsideamerica.com/tip/82478', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Wally the Stegosaurus', 'wally-the-stegosaurus', 'roadside-oddities', 42.44728, -73.2542, 'Pittsfield', 'MA', 'A life-size stegosaurus named Wally stands outside the Berkshire Museum. The dinosaur has become a local landmark and a preview of the museum''s natural-history collections, appearing unexpectedly along a downtown streetscape rather than in a prehistoric park.', 'open', null, 'https://www.atlasobscura.com/places/wally-the-stegosaurus', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Walterboro Water Tower — Former Jail', 'walterboro-water-tower-former-jail', 'roadside-oddities', 32.90235, -80.6623, 'Walterboro', 'SC', 'This historic water tower has several tiny jail cells built into its base, creating the unusual combination of municipal water infrastructure and lockup. Local stories also claim the cells were later used as emergency lodging for stranded travelers, although that part of the history is less certain.', 'roadside', null, 'https://www.scpictureproject.org/colleton-county/walterboro-water-tower.html', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wangunk Statue', 'wangunk-statue', 'roadside-oddities', 41.56181, -72.64634, 'Middletown', 'CT', 'A monumental stylized stone head stands near the Connecticut River as a memorial connected with the Wangunk people who lived in the region. The oversized sculpture is both a public artwork and an unusual visual landmark.', 'open', null, 'https://www.atlasobscura.com/places/wangunk-statue', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wannalancit Mills Smokestack Christmas Tree', 'wannalancit-mills-smokestack-christmas-tree', 'roadside-oddities', 42.64933, -71.31612, 'Lowell', 'MA', 'Each holiday season, a huge conical framework of lights transforms the top of a mill smokestack into an enormous elevated Christmas tree. The industrial chimney becomes a surreal seasonal landmark visible across Lowell, generally appearing from late fall into winter.', 'limited', null, 'https://www.atlasobscura.com/places/wannalancit-mills-smokestack-christmas-tree', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Warbird Park', 'warbird-park', 'roadside-oddities', 33.66086, -78.92828, 'Myrtle Beach', 'SC', 'Several retired military aircraft are displayed outdoors near the former Myrtle Beach Air Force Base. Interpretive markers connect the jets to the crews and units that operated from the site during the Cold War and later conflicts.', 'open', null, 'https://www.cityofmyrtlebeach.com/departments/parks_recreation_sports_tourism/parks/warbird_park.php', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Warm Mineral Springs Park', 'warm-mineral-springs-park', 'roadside-oddities', 27.05887, -82.261, 'North Port', 'FL', 'Warm, mineral-rich sinkhole spring with deep geological and archaeological history.', 'open', null, 'https://www.northportfl.gov/Community-Recreation/Parks-Facilities/Warm-Mineral-Springs-Park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Washington Island Stavkirke', 'washington-island-stavkirke', 'roadside-oddities', 45.36768, -86.93107, 'Washington Island', 'WI', 'This modern wooden church was inspired by medieval Norwegian stave churches, with steep rooflines, carved details and an interior shaped by Scandinavian religious architecture. It reflects Washington Island''s strong Scandinavian heritage.', 'open', null, 'https://trinitywashingtonisland.org/stavkirke/', '2026-09-09T13:02:00.307533+00:00', null, 'https://trinitywashingtonisland.org/', null, null, null, 'America/Chicago'),
  ('Washington Oaks Gardens Coquina Beach', 'washington-oaks-gardens-coquina-beach', 'roadside-oddities', 29.63221, -81.20503, 'Palm Coast', 'FL', 'Rare exposed coquina formations create a rugged, rock-strewn shoreline unlike most Florida beaches.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/washington-oaks-gardens-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wave Field', 'wave-field', 'roadside-oddities', 42.29318, -83.71162, 'Ann Arbor', 'MI', 'Artist and architect Maya Lin created this 90-by-90-foot field of sculpted earth for the University of Michigan in 1995. The repeating grassy ridges mimic the mathematics and rhythm of water waves, turning an ordinary lawn into a walk-through landscape artwork.', 'open', null, 'https://umma.umich.edu/objects/wave-field-aps1995-1/', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Wayside Chapel', 'wayside-chapel', 'roadside-oddities', 45.18966, -85.34499, 'Atwood', 'MI', 'This tiny roadside chapel measures only about 12 by 8 feet and contains just a few miniature pews. Built in 1968, it remains an unexpectedly small place of worship along US-31 and is easy to miss despite being only a few steps from the highway.', 'open', null, 'https://www.roadsideamerica.com/tip/10506', '2026-09-08T15:31:15.588137+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Wedding Cake House', 'wedding-cake-house', 'roadside-oddities', 43.38145, -70.5172, 'Kennebunk', 'ME', 'Elaborate white Gothic woodwork covers this 19th-century home so densely that it resembles layers of decorative cake icing. The house is privately owned, so this is a look-from-the-public-road stop only.', 'private', null, 'https://www.atlasobscura.com/places/the-wedding-cake-house', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Weeks Estate', 'weeks-estate', 'roadside-oddities', 44.45028, -71.57111, 'Lancaster', 'NH', 'Former U.S. senator John Wingate Weeks built this mountaintop estate with a mansion, stone observation tower and carefully planned grounds overlooking the White Mountains. The house preserves period rooms and collections while the tower provides a striking landmark above Lancaster. Vehicle access, house tours and tower openings follow a seasonal state-park schedule, while trail access is broader.', 'limited', null, 'https://www.nhstateparks.org/find-parks-trails/weeks-state-park', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wegner Grotto', 'wegner-grotto', 'roadside-oddities', 44.08774, -90.84236, 'Cataract', 'WI', 'Paul and Matilda Wegner covered concrete forms with glass, ceramics and found materials to build a miniature chapel, fanciful structures and sculptural monuments. The preserved environment looks like a mosaic dream hidden among rural fields.', 'limited', null, 'https://www.monroecountyhistory.org/wegner-grotto', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.monroecountyhistory.org/', null, null, null, 'America/Chicago'),
  ('Welcome to 1979', 'welcome-to-1979', 'roadside-oddities', 36.1607, -86.84501, 'Nashville', 'TN', 'This recording and mastering studio deliberately cultivates an analog environment filled with vintage gear and record-making technology. Public visits are not guaranteed, so OddWay should treat it as an appointment, event or check-ahead music-industry stop.', 'limited', null, 'https://www.welcometo1979.com/', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wells Dinosaur Haven', 'wells-dinosaur-haven', 'roadside-oddities', 41.49196, -72.09998, 'Uncasville', 'CT', 'A private backyard has been transformed into a homemade dinosaur park filled with large hand-built prehistoric creatures. Visitors have historically been welcomed with permission, but this is residential property: ask first and never wander onto the grounds uninvited.', 'private', null, 'https://www.atlasobscura.com/places/wells-dinosaur-haven', '2026-09-08T18:39:47.144889+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wes Skiles Peacock Springs State Park', 'wes-skiles-peacock-springs-state-park', 'roadside-oddities', 30.12562, -83.12819, 'Live Oak', 'FL', 'One of the longest mapped underwater cave systems in the continental United States.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/wes-skiles-peacock-springs-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('West Quoddy Head Light — Easternmost Point', 'west-quoddy-head-light-easternmost-point', 'roadside-oddities', 44.81511, -66.95047, 'Lubec', 'ME', 'The red-and-white striped West Quoddy Head Light stands beside the easternmost point of the contiguous United States. The lighthouse, cliffs, trails, and international views make the geographic superlative worth a stop even apart from the lighthouse itself.', 'limited', null, 'https://www.roadsideamerica.com/tip/44921', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wetumpka Impact Crater — Bald Knob Viewpoint', 'wetumpka-impact-crater-bald-knob-viewpoint', 'roadside-oddities', 32.53308, -86.19422, 'Wetumpka', 'AL', 'This marked viewpoint sits on the rim of an approximately 85-million-year-old impact crater created by a meteor or asteroid. The public sign is part of Wetumpka’s self-guided crater route; much surrounding land is private, so stay on public roads and marked viewpoints.', 'roadside', null, 'https://www.wetumpkaal.gov/365/Wetumpka-Impact-Crater-Commission', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Whale Dance', 'whale-dance', 'roadside-oddities', 43.94253, -72.62638, 'Randolph', 'VT', 'Two enormous bronze whale tails rise from the landscape in Jim Sardonis''s Whale Dance. The sculpture echoes the artist''s better-known granite whale tails near Burlington while creating another deliberately oceanic landmark in landlocked Vermont.', 'open', null, 'https://www.roadsideamerica.com/tip/66176', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Whimzeyland', 'whimzeyland', 'roadside-oddities', 27.99127, -82.69213, 'Safety Harbor', 'FL', 'Private-home folk-art environment covered in bowling balls, bright mosaics, and recycled objects.', 'roadside', null, 'https://whimzeyland.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('White Mana Diner', 'white-mana-diner', 'roadside-oddities', 40.74706, -74.06157, 'Jersey City', 'NJ', 'This tiny stainless-steel diner began as a futuristic building displayed at the 1939 New York World''s Fair before being moved to Jersey City. Its compact circular form and counter-only interior preserve a distinctive piece of early roadside diner architecture.', 'open', null, 'https://www.atlasobscura.com/places/white-mana-diner', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('White Squirrels of Olney', 'white-squirrels-of-olney', 'roadside-oddities', 38.73557, -88.09397, 'Olney', 'IL', 'Olney is famous for a protected population of white eastern gray squirrels, with City Park one of the best-known places to look for them.', 'open', null, 'https://www.ci.olney.il.us/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wichahpi Commemorative Stone Wall', 'wichahpi-commemorative-stone-wall', 'roadside-oddities', 34.9473, -87.82267, 'Florence', 'AL', 'Tom Hendrix spent decades building a winding stone wall in memory of his Yuchi ancestor Te-lah-nay, who family tradition says returned to Alabama after forced removal. The hand-laid wall incorporates stones sent from around the world.', 'open', null, 'https://www.spacesarchives.org/explore/search-the-online-collection/tom-hendrix/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Wiggly Bridge', 'wiggly-bridge', 'roadside-oddities', 43.13645, -70.64768, 'York', 'ME', 'This tiny suspension footbridge stretches about 75 feet across a tidal inlet and noticeably bounces and sways underfoot. It is often promoted as one of the smallest suspension bridges in the world and connects into the Steedman Woods trail system.', 'open', null, 'https://www.atlasobscura.com/places/wiggly-bridge', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wigwam Village No. 2', 'wigwam-village-no-2', 'roadside-oddities', 37.14528, -85.9455, 'Cave City', 'KY', 'Built in 1937, Wigwam Village No. 2 is one of the few surviving examples of America''s once-widespread concrete tipi motel chain. Fifteen individual cone-shaped motel rooms surround a larger central structure, and travelers can still book an overnight stay.', 'limited', null, 'https://www.atlasobscura.com/places/wigwam-village-2', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.historicwigwamvillage.com/', null, null, null, 'America/Chicago'),
  ('Wild Blueberry Land', 'wild-blueberry-land', 'roadside-oddities', 44.64847, -67.70708, 'Columbia Falls', 'ME', 'A giant blueberry-shaped building rises beside U.S. Route 1 in Maine’s major wild-blueberry region. The seasonal attraction sells blueberry products and leans fully into its oversized-fruit roadside identity.', 'limited', null, 'https://www.wildblueberryland.com/contact/', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wild Geese: Flock Together', 'wild-geese-flock-together', 'roadside-oddities', 40.59749, -77.57718, 'Lewistown', 'PA', 'Five-foot fiberglass geese painted by local artists are scattered around the Juniata River Valley in honor of the region''s Goose Day tradition. This pin marks one of the public sculptures in Lewistown, and a separate tracker map can be used to hunt down the rest of the flock.', 'roadside', null, 'https://www.atlasobscura.com/places/geese-flock-together', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wildwood Inn Tropical Dome and Theme Suites', 'wildwood-inn-tropical-dome-and-theme-suites', 'roadside-oddities', 38.98558, -84.64825, 'Florence', 'KY', 'This operating motel has spent decades leaning into elaborate fantasy lodging, with rooms themed around caves, pirate ships, the 1950s, Venice, jungles and other over-the-top environments. A tropical indoor dome and novelty architecture make the property feel like a surviving piece of old roadside honeymoon-motel culture.', 'limited', null, 'https://www.wildwoodinnky.com/hotel-rooms-theme-based-wildwood-inn-florence-ky.html', '2026-09-08T14:42:00.461026+00:00', null, 'https://www.wildwoodinnky.com/', null, null, null, 'America/New_York'),
  ('William Kent Charitable Foundation', 'william-kent-charitable-foundation', 'roadside-oddities', 41.44697, -72.72748, 'Durham', 'CT', 'The former home and studio of reclusive artist William Kent preserves a huge body of woodcuts, sculptures and other unconventional work. The farmhouse functions more like a time capsule of an intensely personal artistic world than a conventional gallery, with visits generally arranged in advance.', 'limited', null, 'https://www.atlasobscura.com/places/william-kent-charitable-foundation', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.williamkentfoundation.org/', null, null, null, 'America/New_York'),
  ('Williamson Coal House', 'williamson-coal-house', 'roadside-oddities', 37.67194, -82.27778, 'Williamson', 'WV', 'Built in 1933 from roughly 65 tons of local bituminous coal, this small downtown building is quite literally constructed from blocks of coal. It survived a damaging 2010 fire, was restored and now houses the Tug Valley Chamber of Commerce and visitor information center.', 'open', null, 'https://wvtourism.com/town-guide-williamson/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Willingboro Futuro House', 'willingboro-futuro-house', 'roadside-oddities', 40.0269, -74.90915, 'Willingboro', 'NJ', 'A rare Futuro House—Matti Suuronen''s 1960s prefabricated flying-saucer-shaped building—survives beside Beverly Rancocas Road. The fiberglass pod is one of only a limited number of Futuros still known to exist and should be viewed from public areas.', 'roadside', null, 'https://thefuturohouse.com/Futuro-Willingboro-New-Jersey-USA.html', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wilson Muffler Man', 'wilson-muffler-man', 'roadside-oddities', 35.7168, -77.90636, 'Wilson', 'NC', 'A classic fiberglass advertising giant stands outside White’s Tire Service holding a tire and waving to passing traffic. It is one of the surviving examples of the mass-produced Muffler Men that once lined American highways. Location: https://www.whitestireservice.com/Contact/Find-Us', 'roadside', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('Windley Key Fossil Reef Geological State Park', 'windley-key-fossil-reef-geological-state-park', 'roadside-oddities', 24.95131, -80.60375, 'Islamorada', 'FL', 'Walk through exposed fossilized coral quarries once used to build the Overseas Railroad.', 'open', null, 'https://www.floridastateparks.org/parks-and-trails/windley-key-fossil-reef-geological-state-park', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('Windows of Aurora — Abandoned Building Murals', 'windows-of-aurora-abandoned-building-murals', 'roadside-oddities', 39.05718, -84.90144, 'Aurora', 'IN', 'Artist Cindy Crofoot transformed boarded windows on a deteriorating downtown building into a series of painted faces and characters rather than leaving the facade blank. The installation became part of Aurora''s broader public-art effort and can be viewed from the public sidewalk without entering the building.', 'roadside', null, 'https://www.roadsideamerica.com/tip/61267', '2026-09-08T13:53:25.695107+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Winnekenni Castle', 'winnekenni-castle', 'roadside-oddities', 42.78794, -71.06374, 'Haverhill', 'MA', 'A Victorian stone castle rises above Kenoza Lake inside Winnekenni Park. Built in the 1870s as a private summer retreat, it now serves as an event and community space while the surrounding trails remain public. Check ahead if seeing the interior matters.', 'limited', null, 'https://www.atlasobscura.com/places/winnekenni-castle', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wire Bridge', 'wire-bridge', 'roadside-oddities', 44.92526, -70.02246, 'New Portland', 'ME', 'This rural bridge combines a wooden deck and towers with an unusual wire-cable suspension system dating to the 1800s. It is commonly described as the last surviving bridge of its particular construction type in Maine.', 'open', null, 'https://www.atlasobscura.com/places/wire-bridge', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wisconsin Concrete Park', 'wisconsin-concrete-park', 'roadside-oddities', 45.67136, -90.39039, 'Phillips', 'WI', 'Fred Smith spent years covering concrete figures with glass, mirrors, stones and found objects, creating a roadside environment populated by lumberjacks, animals, historical figures and scenes from local life. The preserved sculpture park is one of Wisconsin''s major vernacular-art environments.', 'open', null, 'https://www.wisconsinconcretepark.org/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.wisconsinconcretepark.org/', null, null, null, 'America/Chicago'),
  ('Wisteria Vine, Worlds Largest Blossoming Plant', 'wisteria-vine-worlds-largest-blossoming-plant', 'roadside-oddities', 34.170884, -118.05739, 'Sierra Madre', 'CA', 'Sierra Madre’s enormous Chinese wistaria vine began as a one-gallon plant purchased by Alice Brugman in April 1894 and eventually spread across neighboring residential properties. Because the vine grows on private homes, travelers normally see it only during the city’s annual Wistaria Festival/open-house period rather than as a daily walk-up attraction.', 'limited', null, 'https://www.sierramadreca.gov/life-wellness/library/sierra-madre-historical-archives/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Witches Gulch', 'witches-gulch', 'roadside-oddities', 43.66739, -89.78874, 'Wisconsin Dells', 'WI', 'A narrow slot-like sandstone gorge winds through mossy walls, boardwalks and unusual erosion forms. The property is generally experienced through Upper Dells boat tours rather than as a free independent hiking destination.', 'limited', null, 'https://www.dellsboats.com/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.dellsboats.com/', null, null, null, 'America/Chicago'),
  ('Wonder House', 'wonder-house', 'roadside-oddities', 27.87493, -81.83394, 'Bartow', 'FL', 'Hand-built four-story concrete home with underground levels, homemade inventions, secretive design touches, and early climate-control experiments.', 'limited', null, 'https://www.wonderhousebartow.com/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('WonderWorks Orlando', 'wonderworks-orlando', 'roadside-oddities', 28.4337, -81.47145, 'Orlando', 'FL', 'Iconic upside-down laboratory building housing an interactive odd-science attraction.', 'roadside', null, 'https://www.wonderworksonline.com/orlando/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('WonderWorks Upside-Down Building', 'wonderworks-upside-down-building', 'roadside-oddities', 33.71686, -78.88433, 'Myrtle Beach', 'SC', 'WonderWorks looks as though a giant laboratory was ripped from the ground, flipped upside down, and dropped onto Broadway at the Beach. The inverted facade leads into an interactive science-and-amusement attraction filled with optical illusions and hands-on exhibits.', 'limited', null, 'https://www.wonderworksonline.com/myrtle-beach/location-info/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Woods Bay State Park', 'woods-bay-state-park', 'roadside-oddities', 33.94599, -79.99285, 'Olanta', 'SC', 'This state park protects one of the mysterious elliptical depressions known as Carolina bays. The origin of the thousands of similarly shaped wetlands scattered across the coastal plain has inspired scientific debate and fringe theories for generations.', 'open', null, 'https://southcarolinaparks.com/woods-bay', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Woodward Cave', 'woodward-cave', 'roadside-oddities', 40.88944, -77.38819, 'Haines Township', 'PA', 'Woodward Cave contains large limestone rooms, active cave formations and the roughly 14-foot Tower of Babel, described as Pennsylvania''s largest known free-standing stalagmite. Guided tours operate seasonally, and visitors cannot enter the cave outside the attraction''s tour schedule.', 'limited', null, 'https://www.atlasobscura.com/places/woodward-cave', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Woolly Mammoth Antiques & Oddities', 'woolly-mammoth-antiques-oddities', 'roadside-oddities', 41.97608, -87.66898, 'Chicago', 'IL', 'Taxidermy, bones, medical pieces, strange antiques, and unconventional art make this long-running Andersonville shop feel more cabinet of curiosities than store.', 'limited', null, 'https://www.woollymammothchicago.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Worden''s Ledges', 'wordens-ledges', 'roadside-oddities', 41.20362, -81.71882, 'Hinckley Township', 'OH', 'Hidden among sandstone ledges in Hinckley Reservation are faces, animals, religious imagery and other figures carved into the rock by Noble Stuart in the mid-twentieth century. The carvings are reached on a short wooded trail, so this is a hike rather than a roadside pull-off.', 'limited', null, 'https://www.atlasobscura.com/places/wordens-ledges', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('World Peace Bell', 'world-peace-bell', 'roadside-oddities', 39.09227, -84.49574, 'Newport', 'KY', 'Cast in 1998 and installed for the arrival of the year 2000, Newport''s enormous World Peace Bell weighs roughly 66,000 pounds and is about 12 feet across. It was the world''s largest functioning free-swinging bell when dedicated and remains an outsized downtown monument.', 'open', null, 'https://www.towerbells.org/data/NAOtherGreatBells.html', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Biggest Frying Pan', 'world-s-biggest-frying-pan', 'roadside-oddities', 46.349034, -124.054282, 'Long Beach', 'WA', 'Long Beach’s giant frying pan was commissioned by the local chamber of commerce and forged in 1941 for the town’s Razor Clam Festival. It has since been surpassed by larger pans elsewhere, but the 14-foot-long landmark remains a free downtown roadside photo stop and one of the classic oddities of the Washington coast.', 'roadside', null, 'https://www.roadsideamerica.com/story/2972', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Nome Giant Gold Pan', 'world-s-biggest-gold-pan', 'roadside-oddities', 64.500439, -165.408315, 'Nome', 'AK', 'Nome’s giant metal gold pan is roughly 20 feet across and stands with the Three Lucky Swedes statues as a tribute to the 1898 gold discovery that launched the Nome Gold Rush. The exact installation year is not well documented in current sources; today it is a free outdoor photo stop at Bering Street and Seppala Road, and Visit Nome describes it as the largest metal gold pan in the United States.', 'roadside', null, 'https://www.visitnomealaska.com/summer', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Nome'),
  ('Casey Big Pencil', 'world-s-biggest-pencil', 'roadside-oddities', 39.299277, -87.993148, 'Casey', 'IL', 'Casey’s Big Pencil is a deliberately oversized teacher-style pencil created as part of the town’s Big Things Small Town project. The city explicitly says it is often mistaken for the world’s largest but is only a supersized replica, and visitors can see it free at 8 West Main Street along with Casey’s cluster of giant objects.', 'roadside', null, 'https://www.bigthingssmalltown.com/yardstick-pencil', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Casey Big Yardstick', 'world-s-biggest-yard-stick', 'roadside-oddities', 39.299351, -87.992062, 'Casey', 'IL', 'Casey’s Big Yardstick is a 36-foot-long yardstick with every inch enlarged to a foot, built as part of Jim Bolin’s town-wide Big Things project. It is not presented by Casey as a current Guinness record holder, but it remains a free outdoor stop at 3 East Main Street within walking distance of the town’s other oversized objects.', 'roadside', null, 'https://www.bigthingssmalltown.com/yardstick-pencil', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Amish Chair', 'world-s-largest-amish-chair', 'roadside-oddities', 34.843965, -83.935105, 'Blairsville', 'GA', 'This oversized Amish-style chair was built in March 2013 outside Owltown Market south of Blairsville. It remains a free roadside photo stop beside the market, although visitors are asked not to climb or sit on the chair.', 'roadside', null, 'https://www.roadsideamerica.com/tip/38152', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Apple', 'world-s-largest-apple', 'roadside-oddities', 39.186615, -78.166452, 'Winchester', 'VA', 'Winchester’s giant red apple began as a parade float for the Shenandoah Apple Blossom Festival before being permanently placed on the lawn of the historic Sheridan’s Headquarters property. The exact fabrication year is not clearly documented in current sources, but the apple has become a longstanding symbol of the region’s orchard industry and remains visible from the downtown street.', 'roadside', null, 'https://www.roadsideamerica.com/story/4032', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Apple Basket', 'world-s-largest-apple-basket', 'roadside-oddities', 40.1355, -82.083138, 'Frazeysburg', 'OH', 'Longaberger built this huge apple-filled basket at its Homestead property in 1999 as another supersized expression of the company’s basket-making identity. The commercial village later closed and the property became restricted; the basket was repainted in 2022 and is still visible, but travelers should remain on public/access roads and respect barriers and no-trespassing signs.', 'private', null, 'https://www.roadsideamerica.com/tip/2586', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Ball of Sisal Twine', 'world-s-largest-ball-of-sisal-twine', 'roadside-oddities', 39.509227, -98.433692, 'Cawker City', 'KS', 'This community-grown ball is in Cawker City, not Osborne. Farmer Frank Stoeber began rolling discarded sisal twine into a ball on Christmas Eve 1953, and the town later took over the tradition; visitors now find it beneath a roadside shelter and the community continues adding twine during special events.', 'roadside', null, 'https://www.cawkercitykansas.com/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Ball of Twine Made By One Man', 'world-s-largest-ball-of-twine-made-by-one-man', 'roadside-oddities', 45.096339, -94.410164, 'Darwin', 'MN', 'This famous ball is in Darwin, not Dassel. Francis A. Johnson wound sisal twine continuously from 1950 until 1979, creating a 17,400-pound ball later protected inside a glass gazebo; travelers can see it from outside at any time and visit the adjacent museum when it is open.', 'roadside', null, 'https://www.darwintwineball.com/twineball.html', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Basket', 'world-s-largest-basket', 'roadside-oddities', 40.12397, -82.012013, 'Dresden', 'OH', 'Dresden’s giant Longaberger Market Basket was built from hardwood maple and dedicated in 1980. Measuring 48 feet long, 11 feet wide and 23 feet high, it still stands at Fifth and Main streets as a free downtown photo stop tied to the town’s basket-making history.', 'roadside', null, 'https://destinationdresden.com/worlds-largest-basket/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Bowie Knife', 'world-s-largest-bowie-knife', 'roadside-oddities', 33.547184, -97.832162, 'Bowie', 'TX', 'Bowie’s enormous steel knife was created as a civic landmark and earned Guinness recognition in April 2016. The 20-foot sculpture remains at the south entrance to town as a free roadside photo stop celebrating both the city name and the famous Bowie knife.', 'roadside', null, 'https://cityofbowietx.com/384/Worlds-Largest-Bowie-Knife', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Buffalo', 'world-s-largest-buffalo', 'roadside-oddities', 46.889295, -98.698575, 'Jamestown', 'ND', 'Jamestown’s 26-foot, 60-ton concrete buffalo was created by sculptor Elmer Petersen in 1959 and received the name Dakota Thunder in a public contest in 2010. It still overlooks the Frontier Village and is open year-round as a free-will-donation public attraction.', 'roadside', null, 'https://discoverjamestownnd.com/fun-things-to-do-in-jamestown-nd/all-things-buffalo/worlds-largest-buffalo-monument/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Bullhead', 'world-s-largest-bullhead', 'roadside-oddities', 43.225496, -93.790098, 'Crystal Lake', 'IA', 'The giant bullhead is actually in Crystal Lake, Iowa, not Forest City. Carl Frick and Rush Gabrilson built the 12-foot fish in 1958, and it was restored in 2007; today it sits by Crystal Lake as a free lakeside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/4339', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Catsup Bottle', 'world-s-largest-catsup-bottle', 'roadside-oddities', 38.662906, -89.982241, 'Collinsville', 'IL', 'Collinsville’s 170-foot Brooks catsup-bottle water tower was built in 1949 by Caldwell Tanks for the G.S. Suppiger catsup plant. Saved from demolition and restored by a community preservation campaign in 1995, it remains beside Route 159 as one of America’s best-known roadside landmarks and can be photographed from nearby public areas.', 'roadside', null, 'https://www.catsupbottle.com/index.html', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Cherry Pie - Pan', 'world-s-largest-cherry-pie-pan', 'roadside-oddities', 44.736254, -85.625162, 'Traverse City', 'MI', 'Traverse City’s giant pie pan is the surviving hardware from the city’s July 25, 1987 attempt to bake the world’s largest cherry pie, which weighed more than 28,000 pounds. The pan remains outdoors as a roadside monument to the event, giving travelers a quick photo stop tied directly to northern Michigan’s cherry industry.', 'roadside', null, 'https://sanweb.lib.msu.edu/DMC/MFN/1987/1987-10.pdf', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Detroit'),
  ('World''s Largest Chest of Drawers', 'world-s-largest-chest-of-drawers', 'roadside-oddities', 35.96358, -80.008257, 'High Point', 'NC', 'High Point’s oversized furniture landmark began in 1926 as a giant “Bureau of Information” promoting the city’s furniture industry. It was completely redesigned in 1996 into the present 38-foot chest of drawers with giant socks hanging out, and travelers can still view and photograph the exterior from the surrounding streets.', 'roadside', null, 'https://www.roadsideamerica.com/story/2148', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Chile Pepper', 'world-s-largest-chile-pepper', 'roadside-oddities', 32.311858, -106.807619, 'Las Cruces', 'NM', 'Las Cruces’ giant concrete chile pepper was built in 2010–2011 by the owners of the Big Chile Inn as a deliberately oversized symbol of southern New Mexico’s chile culture. The 47-foot sculpture remains outside the motel property and is an easy roadside photo stop.', 'roadside', null, 'https://lascrucesdirectory.com/places/worlds-largest-chili-pepper', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Denver'),
  ('World''s Largest Christmas Pickle', 'world-s-largest-christmas-pickle', 'roadside-oddities', 35.312973, -94.332372, 'Barling', 'AR', 'This giant Christmas pickle began life as an oversized Chili’s pepper before artist Eric Brown repainted and repurposed it as a pickle wearing a Santa hat. The current artwork was in place by 2021 and stands outdoors along Wells Lake Road near Barling/Fort Smith as a quick roadside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/78502', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Collection of the World''s Smallest Versions of the World''s Largest Things', 'world-s-largest-collection-of-the-world-s-smallest-versions-of-the-world-s-large', 'roadside-oddities', 39.057611, -98.537771, 'Lucas', 'KS', 'Artist Erika Nelson created this deliberately tongue-twisting collection of miniature replicas of famous giant roadside attractions, turning the idea of “world’s largest” inside out. The collection now has a home at the Roadside Sideshow Expo in Lucas, where travelers can self-tour during the April-through-October season and see tiny versions of oversized American landmarks.', 'limited', null, 'https://www.travelks.com/listing/worlds-largest-collection-of-the-worlds-smallest-versions-of-the-worlds-largest-things-roadside-attraction-%26-museum/1709/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Corn Cob', 'world-s-largest-corn-cob', 'roadside-oddities', 44.776084, -95.005925, 'Olivia', 'MN', 'Olivia’s 25-foot fiberglass corn cob stands in Memorial Park as a playful symbol of the community’s official “Corn Capital of the World” identity. The exact installation year is not clearly documented in current reliable sources, but the cob remains an easy public park photo stop along Highway 212.', 'roadside', null, 'https://www.cbsnews.com/minnesota/news/best-roadside-attractions-in-minnesota-part-2/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s largest covered wagon', 'world-s-largest-covered-wagon', 'roadside-oddities', 40.148572, -89.387311, 'Lincoln', 'IL', 'Lincoln’s Railsplitter Covered Wagon was built by David Bentley and donated to the city in January 2007. The 25-foot-tall, 40-foot-long wagon carries an oversized seated Abraham Lincoln and remains a free Route 66 photo stop; its canvas cover is removed during winter and returned in spring.', 'roadside', null, 'https://www.lincolnil.gov/lincoln-route-66', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('The Giant Justins', 'world-s-largest-cowboy-boots', 'roadside-oddities', 29.519994, -98.493982, 'San Antonio', 'TX', 'These are Bob “Daddy-O” Wade’s “The Giant Justins,” created in 1979 for the Washington Project for the Arts. The 40-foot boots moved permanently to North Star Mall in San Antonio in 1980, where they remain an easy exterior photo stop and one of the city’s best-known pieces of oversized public art.', 'roadside', null, 'https://www.northstarmall.com/en/events/39974/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Cuckoo Clock', 'world-s-largest-cuckoo-clock', 'roadside-oddities', 40.503106, -81.640582, 'Sugarcreek', 'OH', 'This giant animated clock was built in 1972 for the Alpine-Alpa restaurant near Wilmot and later donated to Sugarcreek. It was moved and restored downtown in 2012, where travelers can still watch its cuckoo bird, mechanical band and dancing figures perform on a regular schedule.', 'roadside', null, 'https://visitsugarcreek.com/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Czech Egg', 'world-s-largest-czech-egg', 'roadside-oddities', 38.824102, -98.472706, 'Wilson', 'KS', 'The giant Czech egg is in Wilson, Kansas, not Ellsworth. The project began around 2003, the fiberglass egg arrived in 2012, local artist Christine Slechta and community volunteers painted it over the following years, and it was formally dedicated July 29, 2016; travelers now find the 20-foot hand-painted egg in Shiroky Park.', 'roadside', null, 'https://wilsonkschamber.com/worlds-largest-czech-egg/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Drumsticks', 'world-s-largest-drumsticks', 'roadside-oddities', 41.235693, -80.818786, 'Warren', 'OH', 'Warren’s giant drumsticks were carved from two roughly 23-foot poplar logs by local artist Joel Eggert and installed as part of Dave Grohl Alley in 2013. They remain outdoors with murals and other Grohl-themed artwork celebrating the Foo Fighters frontman’s Warren birthplace.', 'roadside', null, 'https://www.roadsideamerica.com/story/32170', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Easel', 'world-s-largest-easel', 'roadside-oddities', 39.338009, -101.7049, 'Goodland', 'KS', 'Goodland’s giant easel is part of artist Cameron Cross’s international Van Gogh Project and carries a 24-by-32-foot reproduction of Van Gogh’s “Three Sunflowers in a Vase.” It was installed in Pioneer Park on June 19, 2001 and remains a free roadside artwork visible from Business Highway 24.', 'roadside', null, 'https://goodlandks.gov/news/high-plains-museum-news/goodlands-treasures/2011/10/art-in-a-big-way-goodlands-big-easel/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Denver'),
  ('World''s Largest Egg', 'world-s-largest-egg', 'roadside-oddities', 46.493327, -122.937891, 'Winlock', 'WA', 'Winlock’s giant egg tradition began in 1923 when the first oversized egg was built for a parade celebrating the Pacific Highway bridge and the local poultry industry. Several replacements followed as earlier versions deteriorated, and today a later fiberglass incarnation stands in Vern Zander Memorial Park as the town’s signature roadside landmark.', 'roadside', null, 'https://en.wikipedia.org/wiki/Winlock_Egg', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World''s Largest Egg', 'world-s-largest-egg-mentone', 'roadside-oddities', 41.1734, -86.0349, 'Mentone', 'IN', 'Mentone''s approximately ten-to-twelve-foot concrete egg was built in 1946 to advertise the community''s egg industry and festival. It still stands downtown emblazoned with "The Egg Basket of the Midwest," preserving a wonderfully literal piece of small-town promotional history.', 'open', null, 'https://www.roadsideamerica.com/tip/471', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('World''s Largest Fork', 'world-s-largest-fork', 'roadside-oddities', 37.145369, -93.323274, 'Springfield', 'MO', 'The giant fork is in Springfield, not Battlefield. Noble & Associates created the 35-foot, roughly 11-ton stainless-steel fork in 1990 for a restaurant, and after the restaurant closed it was moved to its current office-property setting at 2215 W. Chesterfield Street; visitors can pull in for a quick photo.', 'roadside', null, 'https://www.springfieldmo.org/blog/post/visit-these-fun-quirky-locations-around-springfield/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Crabbie, the World''s Largest Horseshoe Crab', 'world-s-largest-horseshoe-crab', 'roadside-oddities', 31.36, -87.06, 'Lenox', 'AL', 'A sixty-seven foot fibreglass horseshoe crab, hollow enough to stand inside, built in the 1990s for a maritime attraction in Baltimore''s Inner Harbor that closed before it opened. It has moved four times since: to a creationist museum in Kentucky, then a church car park in Blanchester, Ohio, then a private lawn near Hillsboro, and since roughly 2021 to a private attraction north of Lenox in Conecuh County, Alabama. Our coordinates are approximate — placed from directions rather than a survey — and the site is private, so check before turning up.', 'private', null, 'https://en.wikipedia.org/wiki/World%27s_Largest_Horseshoe_Crab', '2026-09-07T01:44:25.054929+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kaatskill Kaleidoscope', 'world-s-largest-kaleidoscope', 'roadside-oddities', 42.049237, -74.286949, 'Mount Tremper', 'NY', 'The Kaatskill Kaleidoscope is a roughly 60-foot silo converted into an immersive walk-in kaleidoscope at the Emerson Resort in Mount Tremper, not Shokan proper. It opened in 1996, and visitors today buy admission to stand inside while projected imagery and sound transform the silo interior.', 'limited', null, 'https://emersonresort.com/worlds-largest-kaleidoscope/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('Former World''s Largest Knitting Needles', 'world-s-largest-knitting-needles', 'roadside-oddities', 39.299502, -87.992594, 'Casey', 'IL', 'Casey’s giant knitting needles were created by Jim Bolin and officially held the world-record title from 2013 to 2017. They are 13.75 feet long and are now presented as the former world’s largest, displayed with the town’s giant crochet hook at 2 East Main Street.', 'roadside', null, 'https://www.bigthingssmalltown.com/knitting-needles-and-crocket-hook', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Lobster Trap', 'world-s-largest-lobster-trap', 'roadside-oddities', 44.648972, -67.708151, 'Addison', 'ME', 'This enormous lobster trap is a roadside-scale tribute to Maine’s lobster industry in the Addison area. I could not find a reliable published construction year or maker for this specific installation, so the safest description is an oversized local photo stop rather than attaching an unsupported record history to it.', 'roadside', null, 'https://www.openstreetmap.org/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Mineral Hot Spring', 'world-s-largest-mineral-hot-spring', 'roadside-oddities', 43.65636, -108.197973, 'Thermopolis', 'WY', 'The Big Spring at Hot Springs State Park is a natural geothermal feature rather than something built, with hot mineral water feeding the terraces and bathhouse system at Thermopolis. An 1897 agreement reserved part of the spring water for free public bathing, and travelers today can view the spring from boardwalks and use the park’s free bathhouse during posted hours.', 'roadside', null, 'https://npgallery.nps.gov/GetAsset/0c2763ad-9455-4707-9804-b3b07b7587c9', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Denver'),
  ('World''s Largest Mosquito', 'world-s-largest-mosquito', 'roadside-oddities', 63.341491, -143.078154, 'Tok', 'AK', 'This oversized metal mosquito is part of the deliberately odd collection around Mukluk Land outside Tok, a seasonal roadside attraction and museum filled with unusual exhibits and games. The exact construction year of the mosquito is not well documented, but the sculpture is still mapped beside Mukluk Land; visitors should expect the surrounding attraction itself to keep limited seasonal hours.', 'limited', null, 'https://muklukland.com/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Anchorage'),
  ('World''s Largest Olive', 'world-s-largest-olive', 'roadside-oddities', 36.204887, -119.105308, 'Lindsay', 'CA', 'Lindsay’s giant concrete black olive originally stood at the local olive-packing cooperative, reflecting the town’s history as a major olive-processing center. After the plant closed it was rescued and moved to the former Olive Tree Inn around 1999–2000, and today travelers find it in the parking lot of the property now operated as a Super 8.', 'roadside', null, 'https://www.roadsideamerica.com/story/4022', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World''s Largest Oyster', 'world-s-largest-oyster', 'roadside-oddities', 46.666338, -123.810894, 'South Bend', 'WA', 'South Bend’s giant oyster is a concrete shell monument celebrating the Willapa Bay oyster industry and sits in Robert Bush Memorial Park. The exact installation year is not well documented in reliable current sources, but travelers today can walk up to the oversized shell in the public riverfront park.', 'roadside', null, 'https://www.atlasobscura.com/places/the-world-s-largest-oyster', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World''s Largest "Paper" Cup', 'world-s-largest-paper-cup', 'roadside-oddities', 34.006539, -117.339255, 'Riverside', 'CA', 'Riverside’s giant concrete cup was built as advertising for the paper-cup factory that operated here under Lily-Tulip and later Sweetheart Cup; the adjacent plant produced cups from 1958 to 1997. The exact construction year of the monument is poorly documented, but the cup still stands behind a fence at the former industrial site and is best treated as a roadside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/203', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Durant Giant Peanut', 'world-s-largest-peanut', 'roadside-oddities', 33.992736, -96.378405, 'Durant', 'OK', 'Durant’s molded-aluminum peanut monument was dedicated on November 15, 1974 to Bryan County’s peanut growers and processors. Although larger peanut sculptures now exist elsewhere, the original local claim remains on the monument, which sits on the City Hall lawn and is viewable 24 hours a day.', 'roadside', null, 'https://www.travelok.com/listings/view.profile/id.22732', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Peanut Monument', 'world-s-largest-peanut-monument', 'roadside-oddities', 31.706373, -83.635334, 'Ashburn', 'GA', 'Ashburn’s giant peanut monument was originally erected in 1975 to celebrate the local peanut-processing industry. Hurricane Michael destroyed the earlier peanut in 2018, and a new steel-supported monument was completed in 2023 after a community fundraising effort; travelers now see the rebuilt peanut as a roadside landmark.', 'roadside', null, 'https://www.worldrecordacademy.org/2023/9/worlds-largest-peanut-monument-world-record-in-ashburn-georgia-423347', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('Seguin Giant Pecan', 'world-s-largest-pecan', 'roadside-oddities', 29.628837, -97.969628, 'Seguin', 'TX', 'The giant pecan associated with this record is at the Texas Agricultural Education & Heritage Center in Seguin, not Geronimo. Seguin unveiled the 16-foot-long fiberglass pecan in 2011 to regain a “world’s largest” title, although a still larger Texas pecan surpassed it in 2025; travelers can see the monument on the Big Red Barn grounds during public access.', 'limited', null, 'https://www.roadsideamerica.com/tip/33385', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Penny', 'world-s-largest-penny', 'roadside-oddities', 45.895118, -89.700177, 'Woodruff', 'WI', 'Woodruff’s giant concrete penny commemorates the 1953 “Million Penny Parade,” when local schoolchildren and supporters collected more than a million cents to help fund a hospital. The monument was dedicated May 29, 1954 and remains beside the road as a permanent tribute to the campaign.', 'roadside', null, 'https://www.roadsideamerica.com/story/2255', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Pheasant', 'world-s-largest-pheasant', 'roadside-oddities', 44.370001, -98.200075, 'Huron', 'SD', 'Huron’s enormous pheasant was built in 1959 as a tribute to South Dakota’s celebrated pheasant-hunting culture. The roughly 28-foot-tall bird still stands beside U.S. Highway 14 on the east side of town, where travelers can pull off for photos.', 'roadside', null, 'https://www.roadsideamerica.com/tip/3320', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kriz Farm Horseshoe Pile', 'world-s-largest-pile-of-horseshoes', 'roadside-oddities', 41.399241, -73.042863, 'Bethany', 'CT', 'The Kriz family’s enormous horseshoe pile is the accumulation of generations of farrier work, with the current pile begun after a 1955 flood washed away an earlier collection. It was moved to the Kriz Farm in Bethany in 1978 and continues to grow, but it is on a working private farm rather than a public roadside attraction, so visitors should not enter without permission.', 'private', null, 'https://www.farmshow.com/a_article.php?aid=22639', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Popcorn Ball', 'world-s-largest-popcorn-ball', 'roadside-oddities', 42.422549, -94.99997, 'Sac City', 'IA', 'Sac City’s current popcorn ball was built by community volunteers in 2016 and weighs 9,370 pounds, replacing earlier record attempts by the town. It is protected inside its own transparent display building near the Sac City Museum Village, allowing travelers to see the giant snack even when the museum itself is closed.', 'roadside', null, 'https://www.traveliowa.com/places/sac-city-museum-village-and-world-s-largest-popcorn-ball/51/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Potato Masher', 'world-s-largest-potato-masher', 'roadside-oddities', 44.444892, -89.521939, 'Plover', 'WI', 'Plover installed its nearly 39-foot, roughly three-ton potato masher on May 19, 2023 outside the Food + Farm Exploration Center. The giant utensil was designed specifically as a selfie landmark celebrating central Wisconsin agriculture, and travelers can photograph the exterior sculpture even if they are not touring the center.', 'roadside', null, 'https://spmetrowire.com/potd-the-worlds-largest-potato-masher/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Route 66 Red Rocker', 'world-s-largest-rocker', 'roadside-oddities', 38.037444, -91.469595, 'Cuba', 'MO', 'This 42-foot steel chair was erected at Fanning on April 1, 2008 and once held the Guinness title for the world’s largest rocking chair. Casey, Illinois later surpassed it, and it was repainted red and renamed the Route 66 Rocker; travelers still find it beside old Route 66 west of Cuba as a free roadside landmark.', 'roadside', null, 'https://www.visitmo.com/things-to-do/route-66-red-rocker', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Rocking Chair', 'world-s-largest-rocking-chair-franklin', 'roadside-oddities', 39.41789, -85.99979, 'Franklin', 'IN', 'A gigantic wooden rocking chair survives outside a furniture business along US 31. An equally oversized chest of drawers once accompanied it but was destroyed in a fire, leaving the giant chair as the property''s solitary oversized landmark.', 'roadside', null, 'https://fotospot.com/attractions/indiana/worlds-largest-rocking-chair', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('World''s Largest Round Barn', 'world-s-largest-round-barn', 'roadside-oddities', 44.652396, -90.174269, 'Marshfield', 'WI', 'Marshfield’s enormous round barn was built in 1916 to house purebred livestock and measures about 150 feet across and 70 feet high. It still serves its original agricultural purpose during the Central Wisconsin State Fair, while interior tours outside events require advance arrangement with the fair office.', 'limited', null, 'https://visitmarshfield.com/business/worlds-largest-round-barn/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Sandhill Crane', 'world-s-largest-sandhill-crane', 'roadside-oddities', 46.861697, -99.913138, 'Steele', 'ND', '“Sandy,” Steele’s 40-foot metal sandhill crane, was built in 1998–99 by self-taught ironworker James Miller. The bird stands in a landscaped area just off I-94 and remains an easy roadside stop celebrating the large crane migrations through central North Dakota.', 'roadside', null, 'https://www.roadsideamerica.com/tip/1834', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Six-Pack', 'world-s-largest-six-pack', 'roadside-oddities', 43.802842, -91.253231, 'La Crosse', 'WI', 'La Crosse’s “six-pack” is actually six 54-foot beer storage tanks built by G. Heileman Brewing Company in 1969 and painted as giant Old Style cans in 1970. The working brewery tanks have changed branding several times and returned to Old Style imagery in 2023; travelers view them from the surrounding public streets rather than touring the industrial tanks themselves.', 'roadside', null, 'https://wi101.wisc.edu/object-history-worlds-largest-six-pack/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Quinault Big Sitka Spruce', 'world-s-largest-spruce', 'roadside-oddities', 47.477977, -123.829595, 'Quinault', 'WA', 'This is the Quinault Big Sitka Spruce near Lake Quinault, not in Hoquiam itself. The natural tree is roughly 191 feet tall with a circumference approaching 59 feet and is estimated to be around a thousand years old; travelers reach it on a short trail managed from the Rain Forest Resort Village area.', 'roadside', null, 'https://www.nps.gov/places/000/quinault-big-sitka-spruce-tree.htm', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World''s Largest Spur', 'world-s-largest-spur', 'roadside-oddities', 31.051275, -98.182169, 'Lampasas', 'TX', 'Lampasas’ giant spur was forged by ironsmith Waylon Dobbs for local businesswoman Leah Caruthers and installed on March 14, 2016. The roughly 35-foot steel, copper and iron sculpture earned Guinness recognition and remains visible from U.S. 281 with parking available for photos.', 'roadside', null, 'https://www.lampasas.org/m/newsflash/home/detail/432', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Strawberry', 'world-s-largest-strawberry', 'roadside-oddities', 42.682731, -91.534686, 'Strawberry Point', 'IA', 'Strawberry Point’s 15-foot fiberglass strawberry was dedicated in the late 1960s and has stood outside City Hall for more than half a century. Restored again in 2025, it remains an easy public photo stop and one of the town’s defining landmarks.', 'roadside', null, 'https://www.roadsideamerica.com/story/4035', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s largest surfboard', 'world-s-largest-surfboard', 'roadside-oddities', 33.65928, -118.000959, 'Huntington Beach', 'CA', 'Huntington Beach’s enormous surfboard was built for the Epic Big Board Ride on June 20, 2015, when 66 people successfully rode it and Guinness certified it as the world’s largest surfboard. The 42-foot board was subsequently placed on display at the International Surfing Museum, so visitors see it as part of the museum rather than as a freestanding roadside object.', 'limited', null, 'https://www.guinnessworldrecords.com/news/2015/6/worlds-largest-surfboard-66-catch-a-wave-and-ride-their-way-to-a-record-video-386094', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World''s Largest Sweet Tea', 'world-s-largest-sweet-tea', 'roadside-oddities', 33.01869, -80.176746, 'Summerville', 'SC', 'Summerville created a giant batch of sweet tea on June 10, 2016, filling a custom oversized Mason jar with more than 2,500 gallons to set a Guinness record. The permanent jar remains near Town Hall as a roadside monument to the record attempt and the town’s claim as the birthplace of sweet tea.', 'roadside', null, 'https://www.visitsummerville.com/sweet-tea/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Teapot', 'world-s-largest-teapot', 'roadside-oddities', 40.616118, -80.557208, 'Chester', 'WV', 'Chester’s giant teapot began as an oversized Hires Root Beer keg before William “Babe” Devon bought it in 1938, added a handle, spout and lid, and turned it into a teapot-shaped concession stand promoting the region’s pottery industry. Restored and relocated over the years, it now stands on a landscaped roadside site as one of West Virginia’s classic oversized attractions.', 'roadside', null, 'https://www.roadsideamerica.com/story/11259', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Teeter-Totter', 'world-s-largest-teeter-totter', 'roadside-oddities', 39.299713, -87.990597, 'Casey', 'IL', 'Casey’s enormous teeter-totter is another piece of the Big Things Small Town project, built as a functioning oversized playground object and certified as a world-record attraction. It is visible outdoors for free beside Casey’s other giants, while opportunities to actually ride it are restricted to scheduled dates during the tourism season.', 'roadside', null, 'https://www.bigthingssmalltown.com/list', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Tiger Muskie', 'world-s-largest-tiger-muskie', 'roadside-oddities', 46.964471, -94.842047, 'Nevis', 'MN', 'The giant tiger muskie is actually in Nevis, just east of Park Rapids. The community erected the fish in 1949 as a tourism symbol for its lake country, and today the oversized muskie remains a public landmark near the center of town and the Heartland Trail.', 'roadside', null, 'https://cityofnevismn.gov/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Turkey', 'world-s-largest-turkey', 'roadside-oddities', 46.72275, -95.710257, 'Frazee', 'MN', 'Frazee’s current giant turkey, Big Tom II, was installed on September 19, 1998 after the original statue accidentally burned while workers were removing it. The fiberglass bird stands more than 20 feet tall in Lions Park and remains a free roadside photo stop overlooking the entrance to town.', 'roadside', null, 'https://www.roadsideamerica.com/story/2130', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Windchime', 'world-s-largest-windchime', 'roadside-oddities', 39.299581, -87.991057, 'Casey', 'IL', 'Casey’s first major world-record project was the giant wind chime, whose steel framework went up November 17, 2011 and whose chimes were installed on December 15 that year. The 54-foot structure still stands downtown and visitors can pull the rope to make the huge chimes sound.', 'roadside', null, 'https://www.bigthingssmalltown.com/wind-chime', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Smallest City Block', 'world-s-smallest-city-block', 'roadside-oddities', 31.225372, -85.38923, 'Dothan', 'AL', 'Dothan’s tiny triangular block sits at the meeting of North Appletree, North College and East Troy streets. The Camellia Garden Club marked it on May 1, 1964 after Ripley’s recognition, and travelers today find a tiny traffic island with street signs and a granite marker that can be viewed from the surrounding public streets.', 'roadside', null, 'https://www.atlasobscura.com/places/worlds-smallest-city-block', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Tallest Filing Cabinet', 'world-s-tallest-filing-cabinet', 'roadside-oddities', 44.455837, -73.217221, 'Burlington', 'VT', 'Burlington artist Bren Alvarez created “File Under So. Co., Waiting for…” in 2002 from stacked filing cabinets as a joke about decades of paperwork surrounding the long-delayed Southern Connector highway. The sculpture was moved and revised in 2020 and now stands at an art park outside 208 Flynn Avenue, where visitors can view it freely from the public-facing site.', 'roadside', null, 'https://www.burlingtoncityarts.org/so-co-file-under', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Tallest Free Standing Redwood Chainsaw Carving', 'world-s-tallest-free-standing-redwood-chainsaw-carving', 'roadside-oddities', 39.919097, -123.764318, 'Piercy', 'CA', 'This approximately 44-foot carving was cut upright from a dead redwood at Confusion Hill, making it a freestanding chainsaw carving rather than a totem carved horizontally and raised later. Confusion Hill says the carving itself took about three months to make; its exact year is not well documented, and travelers now find it in the attraction’s parking area at Piercy.', 'limited', null, 'https://www.confusionhill.com/faqs', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Jackson Creek Giant Sugar Pine', 'world-s-tallest-sugarpine', 'roadside-oddities', 42.961233, -122.703101, 'Shady Cove', 'OR', 'This is a natural giant sugar pine in the southern Oregon forest rather than a man-made attraction, so there is no construction date; the famous tree is several centuries old. The Jackson Creek-area specimen long carried a “world’s tallest” reputation but newer measurements have identified taller living sugar pines elsewhere, and reaching this one requires forest roads and a woodland approach rather than a simple highway pull-off.', 'limited', null, 'https://conifers.org/pi/Pinus_lambertiana.php', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World''s Tallest Thermometer', 'world-s-tallest-thermometer', 'roadside-oddities', 35.266485, -116.072778, 'Baker', 'CA', 'Baker’s 134-foot electric thermometer was created by businessman Willis Herron to commemorate the 134°F temperature recorded in nearby Death Valley. The first version was built in 1991 but toppled in high winds before opening, and the rebuilt structure was illuminated in October 1992; it remains a prominent I-15 roadside landmark.', 'roadside', null, 'https://www.pbssocal.org/history-society/return-of-the-desert-wayfinder-worlds-tallest-thermometer-in-baker-ca', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('World Traveler Signpost', 'world-traveler-signpost', 'roadside-oddities', 44.24434, -70.78508, 'Lynchville', 'ME', 'At a rural Maine crossroads, a cluster of signs points toward nearby towns with names borrowed from places around the world, including Norway, Paris, Denmark, Sweden, and Mexico. The result looks like an international directional sign dropped into the Maine woods.', 'roadside', null, 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/world-traveler-signpost', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('World’s Largest 1911 Pistol', 'worlds-largest-1911-pistol', 'roadside-oddities', 36.3073, -79.27759, 'Mebane', 'NC', 'A huge wooden reproduction of an M1911 pistol stands at Distinguished Pistol Outdoor Shooting Range. Built at roughly twelve times normal scale, the sculpture measures more than eight feet long and turns a familiar handgun silhouette into an oversized roadside object.', 'open', null, 'https://www.strangecarolinas.com/2024/06/ncs-biggest-1911-pistol-mebane-nc.html', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Air-Insulated Van de Graaff Generator', 'worlds-largest-air-insulated-van-de-graaff-generator', 'roadside-oddities', 42.36762, -71.07073, 'Boston', 'MA', 'The Museum of Science operates an enormous Van de Graaff generator capable of producing spectacular indoor lightning. Built around machinery created by Robert Van de Graaff, the towering apparatus is used in live electricity demonstrations rather than sitting silently behind glass.', 'limited', null, 'https://www.atlasobscura.com/places/worlds-largest-airinsulated-van-de-graaff-generator', '2026-09-09T04:43:56.902716+00:00', null, 'https://www.mos.org/visit/live-presentations/lightning', null, null, null, 'America/New_York'),
  ('World''s Largest Badger', 'worlds-largest-badger', 'roadside-oddities', 44.99042, -89.20452, 'Birnamwood', 'WI', 'A huge badger statue towers beside the highway in Birnamwood, turning Wisconsin''s state nickname into a literal roadside giant. The fiberglass figure is a simple but highly visible photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/1425', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/tip/1425', null, null, null, 'America/Chicago'),
  ('Worlds Largest Ball Of Paint', 'worlds-largest-ball-of-paint', 'roadside-oddities', 40.258859, -85.709091, 'Alexandria', 'IN', 'Mike Carmichael began the Ball of Paint on January 1, 1977 by repeatedly coating a baseball, eventually turning it into a multiton object with tens of thousands of paint layers. The Alexandria attraction is still an active family project, and visitors who arrange a visit can add their own coat of paint and receive a certificate.', 'limited', null, 'https://www.worldslargestballofpaint.com/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Giant Joe Tinker Baseball', 'worlds-largest-baseball', 'roadside-oddities', 39.551224, -95.521726, 'Muscotah', 'KS', 'The giant baseball is in Muscotah, not Horton, and was created from a large former water tank as a tribute to Hall of Fame shortstop and Muscotah native Joe Tinker. The local baseball-themed project developed in the 2010s; today the oversized stitched ball sits as a public roadside monument, although the “world’s largest” claim is local rather than a well-documented current record.', 'roadside', null, 'https://ksbaseballhof.com/tinker-joe/', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Baseball Bat', 'worlds-largest-baseball-bat', 'roadside-oddities', 38.2571, -85.76471, 'Louisville', 'KY', 'A 120-foot steel baseball bat leans against the Louisville Slugger Museum & Factory, modeled after a bat used by Babe Ruth. The enormous object weighs tens of thousands of pounds and functions as one of downtown Louisville''s easiest-to-spot landmarks.', 'open', null, 'https://www.sluggermuseum.com/', '2026-09-08T14:15:10.228298+00:00', null, 'https://www.sluggermuseum.com/', null, null, null, 'America/Kentucky/Louisville'),
  ('worlds largest bluebird', 'worlds-largest-bluebird', 'roadside-oddities', 47.65853, -96.092313, 'Fosston', 'MN', 'An oversized bluebird sculpture is mapped in Polk County, Minnesota, but the current map data places it in Woodside Township rather than clearly inside Fosston. I could not find a dependable published construction date or record history, so it is best described simply as a giant roadside bird sculpture until the exact local provenance can be confirmed.', 'roadside', null, 'https://mapcarta.com/N8832130003', null, null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Brown Trout', 'worlds-largest-brown-trout', 'roadside-oddities', 43.89733, -85.85157, 'Baldwin', 'MI', 'Artist Ivan Iler built this roughly 25-foot metal trout to commemorate Baldwin''s connection to the first recorded stocking of brown trout in American waters. Installed downtown in 2018, the fish was intentionally made large enough to surpass another giant brown trout sculpture in New Zealand.', 'open', null, 'https://www.atlasobscura.com/places/world-s-largest-brown-trout-sculpture', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('World''s Largest Butter Knife and Sculpture Park', 'worlds-largest-butter-knife-and-sculpture-park', 'roadside-oddities', 36.75864, -86.52423, 'Franklin', 'KY', 'Franklin-Simpson High School welding students built the 24-foot "Cutting Edge of Simpson County" in 2021 after previously creating the town''s giant fork. The rural sculpture park also contains other oversized student projects, including a space capsule and additional metal creations. Address: 4433 Blackjack Rd., Franklin, KY', 'open', null, 'https://www.roadsideamerica.com/tip/74601', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Candle', 'worlds-largest-candle', 'roadside-oddities', 39.8589, -84.9924, 'Centerville', 'IN', 'Warm Glow Candle Company turned its headquarters into a roadside landmark with an enormous candle-shaped structure visible from Interstate 70. The oversized candle rises from the shop complex and gives travelers a straightforward stop built around one of Indiana''s most conspicuous giant-object attractions.', 'open', null, 'https://visitindiana.in.gov/listing/giant-candle/19529/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('World''s Largest Cedar Bucket', 'worlds-largest-cedar-bucket', 'roadside-oddities', 35.8438, -86.3962, 'Murfreesboro', 'TN', 'A massive wooden bucket built by a local cooperage became a Murfreesboro landmark and was later rebuilt after a fire. The absurdly oversized container is preserved in Cannonsburgh Village as a piece of old-fashioned promotional craftsmanship.', 'open', null, 'https://www.murfreesborotn.gov/2476/Worlds-Largest-Cedar-Bucket', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Corkscrew', 'worlds-largest-corkscrew', 'roadside-oddities', 46.45071, -90.19623, 'Hurley', 'WI', 'An enormous corkscrew sculpture rises outside a Hurley business along U.S. 2. Its exaggerated spiral silhouette makes a strange punctuation mark along a Northwoods highway better known for mines, forests and snow.', 'roadside', null, 'https://www.roadsideamerica.com/tip/12354', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.roadsideamerica.com/tip/12354', null, null, null, 'America/Chicago'),
  ('World''s Largest Engagement Ring', 'worlds-largest-engagement-ring', 'roadside-oddities', 39.43733, -76.62572, 'Timonium', 'MD', 'Smyth Jewelers unveiled this enormous stainless-steel-and-acrylic engagement ring outside its Timonium showroom in 2015. The sculpture stands 17 feet tall and 14 feet wide, was designed as a permanent landmark, and is meant to be approached for photos from the store''s public frontage.', 'open', null, 'https://www.prnewswire.com/news-releases/smyth-jewelers-and-uneek-fine-jewelry-create-worlds-largest-engagement-ring-300161337.html', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Frying Pan', 'worlds-largest-frying-pan', 'roadside-oddities', 38.67251, -75.37705, 'Georgetown', 'DE', 'A gigantic frying pan, about ten feet across and roughly eighteen feet long including its handle, is displayed at the Marvel Carriage Museum. It was built for a chicken-frying event and fits neatly with Sussex County''s poultry history.', 'limited', null, 'https://www.roadsideamerica.com/story/13356', '2026-09-08T18:31:51.932734+00:00', null, 'https://www.georgetownhistoricalsociety.org/', null, null, null, 'America/New_York'),
  ('World''s Largest Gavel', 'worlds-largest-gavel', 'roadside-oddities', 39.9595, -83.0022, 'Columbus', 'OH', 'A giant stainless-steel gavel lies beside the Thomas J. Moyer Ohio Judicial Center in downtown Columbus. The oversized public sculpture is commonly promoted as the world''s largest gavel and can be viewed from the public plaza without entering the court building.', 'open', null, 'https://www.worldrecordacademy.org/2023/5/worlds-largest-steel-gavel-sculpture-world-record-in-columbus-ohio-423215', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Golf Tee', 'worlds-largest-golf-tee', 'roadside-oddities', 39.30661, -87.98131, 'Casey', 'IL', 'A roughly 30-foot wooden golf tee stands at a local golf course as another of Casey''s Guinness-recognized oversized objects.', 'open', null, 'https://www.bigthingssmalltown.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World’s Largest Highboy', 'worlds-largest-highboy', 'roadside-oddities', 35.97229, -79.92485, 'Jamestown', 'NC', 'Furnitureland South incorporates an enormous highboy dresser into its architecture, creating an approximately 85-foot monument to the Piedmont furniture industry. The giant drawers and broken-pediment top make the building look like furniture scaled for a giant.', 'roadside', null, 'https://www.roadsideamerica.com/story/15625', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('World’s Largest Horseshoe Crab — Dinosaur Adventure Land', 'worlds-largest-horseshoe-crab-dinosaur-adventure-land', 'roadside-oddities', 31.35554, -87.17535, 'Repton', 'AL', 'The giant fiberglass-and-foam horseshoe crab nicknamed Crabbie has moved through several states and now resides at Dinosaur Adventure Land in Conecuh County. It measures roughly 67 feet long and remains a bizarre oversized roadside sculpture; check the property’s current visitor rules before arriving.', 'limited', null, 'https://drdino.com/', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest In-Situ Celtic Cross', 'worlds-largest-in-situ-celtic-cross', 'roadside-oddities', 37.91714, -86.66565, 'Cannelton', 'IN', 'Sculptor Greg Harris spent 23 months carving a High Celtic Cross directly through a massive natural sandstone slab on the Blue Heron Vineyard property. The owners describe it as the largest known in-situ Celtic Cross, meaning it was carved from stone still naturally embedded in the hillside; access follows the winery''s property hours.', 'limited', null, 'https://www.blueheronvines.com/celtic-cross.html', '2026-09-08T13:20:58.818667+00:00', null, 'https://www.blueheronvines.com/', null, null, null, 'America/Chicago'),
  ('World''s Largest M', 'worlds-largest-m', 'roadside-oddities', 42.76371, -90.40667, 'Platteville', 'WI', 'A huge white letter M built from limestone sits on a hillside overlooking Platteville. University of Wisconsin-Platteville students created the monument to represent the region''s mining heritage, and trails allow visitors to approach the giant letter.', 'open', null, 'https://www.uwplatt.edu/', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.uwplatt.edu/', null, null, null, 'America/Chicago'),
  ('Worlds Largest Mailbox', 'worlds-largest-mailbox', 'roadside-oddities', 39.298807, -87.993631, 'Casey', 'IL', 'Casey’s enormous mailbox was built to satisfy Guinness requirements as a genuinely functional mailbox: visitors can climb the stairs inside and mail letters that raise its working red flag. Created during Casey’s mid-2010s Big Things expansion, it remains a free downtown attraction at 19 West Main Street.', 'roadside', null, 'https://www.bigthingssmalltown.com/mailbox', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World’s Largest Non-Stick Frying Pan', 'worlds-largest-non-stick-frying-pan', 'roadside-oddities', 44.7792, -69.37758, 'Pittsfield', 'ME', 'Pittsfield owns a roughly 10-foot-wide non-stick frying pan associated with the Central Maine Egg Festival. Unlike a permanent roadside giant, the pan is normally kept in storage and brought to Manson Park around festival time, so this stop should be treated as an event-dependent OddWay location.', 'limited', null, 'https://www.roadsideamerica.com/tip/10801', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('World’s Largest Office Chair', 'worlds-largest-office-chair', 'roadside-oddities', 33.65257, -85.82956, 'Anniston', 'AL', 'Built in 1981 to advertise Miller’s Office Furniture, the enormous chair towers above the street at roughly three stories high. It remains an easy exterior photo stop and a classic example of oversized roadside advertising.', 'roadside', null, 'https://alabama.travel/places-to-go/world-s-largest-office-chair', '2026-09-09T12:59:35.538091+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World’s Largest Operational Frying Pan', 'worlds-largest-operational-frying-pan', 'roadside-oddities', 34.82632, -78.02188, 'Rose Hill', 'NC', 'Rose Hill’s enormous frying pan was built to cook massive quantities of poultry during community events. Unlike many oversized roadside objects, this pan was designed to actually function, giving its “operational” claim a practical basis.', 'roadside', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Our Lady of Guadalupe Statue', 'worlds-largest-our-lady-of-guadalupe-statue', 'roadside-oddities', 41.56818, -80.99522, 'Windsor', 'OH', 'The Servants of Mary Center for Peace is home to a roughly 50-foot statue of Our Lady of Guadalupe rising above the rural grounds. The religious complex welcomes visitors to its outdoor devotional areas, making the towering figure a publicly accessible roadside destination rather than something that needs to be viewed from private land.', 'open', null, 'https://www.atlasobscura.com/places/servants-of-mary-center-for-peace', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Pin', 'worlds-largest-pin', 'roadside-oddities', 37.71856, -85.87687, 'Elizabethtown', 'KY', 'The Transit Authority of Central Kentucky turned its acronym—TACK—into a literal landmark by building an enormous pushpin outside its headquarters. Guinness World Records certified the approximately 21-foot-7-inch structure as the world''s largest pin in 2024.', 'open', null, 'https://www.atlasobscura.com/places/transit-authority-of-central-kentucky-tack-headquarters', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Pitchfork', 'worlds-largest-pitchfork', 'roadside-oddities', 39.31554, -87.9788, 'Casey', 'IL', 'An enormous metal pitchfork planted outside a farm-themed business continues Casey''s townwide obsession with making ordinary objects absurdly huge.', 'open', null, 'https://www.bigthingssmalltown.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Pocketknife', 'worlds-largest-pocketknife', 'roadside-oddities', 37.79756, -85.91228, 'Radcliff', 'KY', 'Outside Red Hill Cutlery stands an enormous folding pocketknife with a roughly 20-foot handle and a 17-foot-plus blade. Built in 2019, the several-thousand-pound knife is theoretically functional but requires heavy equipment to open or close.', 'open', null, 'https://www.atlasobscura.com/places/worlds-largest-pocketknife', '2026-09-08T14:30:49.642487+00:00', null, 'https://redhillcutlery.com/', null, null, null, 'America/New_York'),
  ('World''s Largest Pumpkin Water Tower', 'worlds-largest-pumpkin-water-tower', 'roadside-oddities', 39.58834, -82.94297, 'Circleville', 'OH', 'Circleville''s one-million-gallon water tower was painted in 1997 to resemble a giant orange pumpkin, reflecting the city''s famous annual Pumpkin Show. The tower remains part of the working water system and is best viewed and photographed from surrounding public streets rather than approached as a walk-in attraction.', 'roadside', null, 'https://www.atlasobscura.com/places/worlds-largest-pumpkin-water-tower', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Railsplitter Covered Wagon', 'worlds-largest-railsplitter-covered-wagon', 'roadside-oddities', 40.1483, -89.3645, 'Lincoln', 'IL', 'A 40-foot covered wagon carries a giant Abraham Lincoln; it moved to 120 N. Kickapoo Street in 2026, so older map pins are obsolete.', 'open', null, 'https://www.loc8nearme.com/illinois/lincoln/worlds-largest-railsplitter-covered-wagon/8455703/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Worlds Largest Rocking Chair', 'worlds-largest-rocking-chair', 'roadside-oddities', 39.300014, -87.99111, 'Casey', 'IL', 'Casey’s 56-foot, 46,200-pound rocking chair took two years to complete and officially claimed its record on October 20, 2015 after ten people demonstrated that it could actually rock. It is now fixed in place and remains a free outdoor centerpiece of Casey’s walkable collection of giant objects.', 'roadside', null, 'https://www.bigthingssmalltown.com/rocking-chair', '2026-09-06T21:21:44.179039+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Route 66 Shield & Big Ron', 'worlds-largest-route-66-shield-big-ron', 'roadside-oddities', 39.71295, -89.6472, 'Springfield', 'IL', 'Motorheads'' exterior now features an enormous Route 66 shield and a 30-foot Muffler Man called Big Ron, both built for oversized roadside impact.', 'open', null, 'https://66motorheads.com/', '2026-09-09T13:01:50.8603+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Rubik''s Cube', 'worlds-largest-rubiks-cube', 'roadside-oddities', 35.96119, -83.9225, 'Knoxville', 'TN', 'A giant motorized Rubik''s Cube created for the 1982 World''s Fair survives in Knoxville as a piece of oversized puzzle history. Its continued presence gives the former fairgrounds another distinctly retro-futurist artifact.', 'open', null, 'https://www.atlasobscura.com/places/rubiks-cube', '2026-09-09T12:59:24.207387+00:00', null, null, null, null, null, 'America/Chicago'),
  ('World''s Largest Sassafras Tree', 'worlds-largest-sassafras-tree', 'roadside-oddities', 37.76147, -87.11158, 'Owensboro', 'KY', 'This enormous sassafras at Frederica Street and Maple Avenue has a trunk circumference of roughly 21 feet and is believed to be several centuries old. Local lore says homeowner Grace Rash once confronted road crews with a shotgun to prevent the tree from being cut down during a highway-widening project.', 'open', null, 'https://www.roadsideamerica.com/tip/7879', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Worlds Largest Shopping Cart', 'worlds-largest-shopping-cart', 'roadside-oddities', 39.294044, -74.971378, 'Laurel Lake', 'NJ', 'This oversized shopping-cart sculpture is mapped in Maurice River Township in Cumberland County, closer to the Laurel Lake/Port Elizabeth area than to a formal town center. I could not find a reliable published maker or construction date, so the defensible OddWay description is a large roadside cart installation that can be viewed from the road, not a documented Guinness attraction.', 'roadside', null, 'https://www.openstreetmap.org/', null, null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Soup Kettle', 'worlds-largest-soup-kettle', 'roadside-oddities', 45.56485, -88.75746, 'Laona', 'WI', 'An enormous metal kettle beside U.S. 8 is a relic of Laona''s lumber-camp identity and has long been promoted as the world''s largest soup kettle. Its exaggerated scale makes it an easy old-school roadside photo stop.', 'roadside', null, 'https://www.roadsideamerica.com/tip/1426', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.laonawisconsin.info/', null, null, null, 'America/Chicago'),
  ('World’s Largest Strawberry', 'worlds-largest-strawberry', 'roadside-oddities', 35.04103, -79.76723, 'Ellerbe', 'NC', 'The Berry Patch is topped by an enormous strawberry-shaped building that functions as one of the most conspicuous roadside fruit monuments in the Carolinas. The giant berry advertises the farm market below it and is visible directly from the highway.', 'roadside', null, 'https://www.strangecarolinas.com/', '2026-09-09T05:34:33.398594+00:00', null, null, null, null, null, 'America/New_York'),
  ('World’s Largest Telephone', 'worlds-largest-telephone', 'roadside-oddities', 44.3785, -70.64621, 'Bryant Pond', 'ME', 'A roughly 14-foot-tall telephone commemorates Bryant Pond’s place in telecommunications history as the home of the last hand-cranked telephone exchange in the United States. The giant phone stands as a roadside monument to the town’s unusually late survival of operator-connected service.', 'roadside', null, 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/worlds-largest-telephone', '2026-09-09T04:54:23.476824+00:00', null, null, null, null, null, 'America/New_York'),
  ('World’s Largest Ten Commandments — Fields of the Wood', 'worlds-largest-ten-commandments-fields-of-the-wood', 'roadside-oddities', 35.12071, -84.25019, 'Murphy', 'NC', 'A massive rendering of the Ten Commandments covers a mountainside at Fields of the Wood, a religious park operated by the Church of God of Prophecy. Visitors can climb the hillside among enormous letters and other large-scale biblical monuments.', 'limited', null, 'https://www.roadsideamerica.com/location/nc', '2026-09-09T05:34:33.398594+00:00', null, 'https://www.fieldsofthewoodbiblepark.com/', null, null, null, 'America/New_York'),
  ('World''s Largest Tomato Soup Can', 'worlds-largest-tomato-soup-can', 'roadside-oddities', 41.40161, -84.10084, 'Napoleon', 'OH', 'A huge Campbell''s tomato-soup-can water tower rises above the company''s Napoleon-area processing plant and is commonly promoted as the world''s largest representation of the familiar can. The tower is inside an active industrial property, so photograph it from a safe public roadside location and do not enter the factory grounds without permission.', 'roadside', null, 'https://www.ohiomagazine.com/ohio-life/article/giant-tomato-soup-can', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Transistor Monument', 'worlds-largest-transistor-monument', 'roadside-oddities', 40.372, -74.1597, 'Holmdel Township', 'NJ', 'The giant three-legged water tower at Bell Works was deliberately shaped like an early transistor, the revolutionary device invented at Bell Laboratories. Its saucer-like form makes the scientific tribute look more like a machine from a vintage alien-invasion film.', 'roadside', null, 'https://www.roadsideamerica.com/tip/8180', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Washboard', 'worlds-largest-washboard', 'roadside-oddities', 39.53993, -82.41385, 'Logan', 'OH', 'A giant washboard measuring roughly two stories tall is mounted on the Columbus Washboard Company building in Logan, advertising a factory that still produces traditional washboards. The exterior landmark can be seen at any time from public ground, while the factory store and any interior access follow business hours.', 'open', null, 'https://www.atlasobscura.com/places/worlds-largest-washboard', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Largest Weathervane', 'worlds-largest-weathervane', 'roadside-oddities', 43.41608, -86.35457, 'Montague', 'MI', 'Montague''s enormous working weathervane rises roughly 48 feet above Ellenwood Park and is topped by a detailed schooner. The ship represents the Ella Ellenwood, a lumber schooner associated with the area''s nineteenth-century maritime trade.', 'open', null, 'https://www.whitelake.org/business/worlds-largest-weathervane-and-ellenwood-park/', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('World''s Most Nearly Perfect Sphere', 'worlds-most-nearly-perfect-sphere', 'roadside-oddities', 42.25275, -71.00232, 'Quincy', 'MA', 'A polished granite ball six feet in diameter and weighing about 9.5 tons sits near Quincy City Hall. The 1925 monument was once promoted by Ripley''s Believe It or Not as the ''most nearly perfect sphere in the world,'' an absurdly precise claim for an enormous stone ball left outdoors for a century.', 'open', null, 'https://www.roadsideamerica.com/tip/21365', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Second Largest Seated Lincoln', 'worlds-second-largest-seated-lincoln', 'roadside-oddities', 37.66528, -82.78144, 'Prestonsburg', 'KY', 'A gigantic seated Abraham Lincoln originally commissioned by disgraced attorney Eric C. Conn now overlooks Middle Creek National Battlefield. The statue was deliberately built slightly smaller than the Lincoln Memorial figure in Washington and was relocated to the battlefield in 2021 after Conn''s fraud conviction. Address: 2968 KY-114, Prestonsburg, KY', 'open', null, 'https://www.roadsideamerica.com/story/27035', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Smallest Police Station', 'worlds-smallest-police-station', 'roadside-oddities', 29.85141, -84.66514, 'Carrabelle', 'FL', 'Phone-booth-sized police station replica commemorating Carrabelle''s famously tiny 1963 police call station.', 'roadside', null, 'https://www.mycarrabelle.com/visitors/worlds-smallest-police-station/', '2026-09-09T13:54:54.613604+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Tallest Crucifix', 'worlds-tallest-crucifix', 'roadside-oddities', 37.76694, -85.48333, 'Bardstown', 'KY', 'A roughly 60-foot stainless-steel crucifix rises above St. Thomas Cemetery south of Bardstown. Built in 1986, the unusually skeletal wire-frame figure of Jesus is visible above the cemetery and has long been promoted as one of the tallest crucifixes of its type.', 'open', null, 'https://www.roadsideamerica.com/story/11447', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('World''s Tallest Grandfather Clock', 'worlds-tallest-grandfather-clock', 'roadside-oddities', 44.46012, -87.50378, 'Kewaunee', 'WI', 'A four-faced clock tower built to resemble an enormous grandfather clock stands near the Kewaunee harbor. The whimsical structure functions as public art, a timepiece and one of the city''s signature landmarks.', 'open', null, 'https://www.kewaunee.org/grandfather-clock', '2026-09-09T13:02:00.307533+00:00', null, 'https://www.kewaunee.org/', null, null, null, 'America/Chicago'),
  ('World''s Tallest Uncle Sam Statue', 'worlds-tallest-uncle-sam-statue', 'roadside-oddities', 41.3979, -73.4501, 'Danbury', 'CT', 'A gigantic fiberglass Uncle Sam towers over the Danbury Railway Museum property. The roughly 38-foot figure is a classic product of the giant roadside-statue era and returned to Danbury after spending years at other locations.', 'open', null, 'https://www.roadsideamerica.com/story/2510', '2026-09-08T18:39:47.144889+00:00', null, 'https://www.danburyrail.org/', null, null, null, 'America/New_York'),
  ('Yankee Siege Trebuchet', 'yankee-siege-trebuchet', 'roadside-oddities', 42.95431, -71.92173, 'Greenfield', 'NH', 'This giant six-story trebuchet was built to hurl pumpkins hundreds of feet during the era of competitive pumpkin chunking. Yankee Siege retired from regular operation in 2010 but remains an enormous reminder of one of New England''s stranger engineering hobbies. It is on private property with no-trespassing restrictions, so OddWay should treat it as roadside-view-only.', 'private', null, 'https://www.atlasobscura.com/places/yankee-siege-trebuchet', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yin Yu Tang: A Chinese Home', 'yin-yu-tang-a-chinese-home', 'roadside-oddities', 42.52211, -70.89289, 'Salem', 'MA', 'An entire late-Qing-dynasty merchant family''s house was dismantled in China, shipped to Massachusetts and reconstructed inside the Peabody Essex Museum complex. The furnished house preserves generations of domestic architecture in an extraordinary transplanted setting.', 'limited', null, 'https://www.pem.org/yin-yu-tang-a-chinese-home', '2026-09-09T04:43:56.902716+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yogi Bear and Jellystone Characters', 'yogi-bear-and-jellystone-characters', 'roadside-oddities', 38.87437, -75.36025, 'Lincoln', 'DE', 'A cluster of restored vintage Yogi Bear/Jellystone character figures survives at the campground on Brick Granary Road. The figures preserve the look of mid-century family roadside attractions, but they sit on active campground property.', 'limited', null, 'https://www.roadsideamerica.com/tip/71127', '2026-09-08T18:31:51.932734+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yogi Bear’s Honey Fried Chicken', 'yogi-bears-honey-fried-chicken', 'roadside-oddities', 34.36918, -80.07085, 'Hartsville', 'SC', 'Nearly every location in the short-lived Yogi Bear fast-food chain disappeared decades ago, but Hartsville still has the last operating Yogi Bear’s Honey Fried Chicken restaurant. The surviving cartoon-branded restaurant is an improbable piece of 1960s and 1970s franchise history that remains open in 2026.', 'open', null, 'https://visithartsvillesc.com/listings/eat/eat-family-restaurants/', '2026-09-09T05:53:13.784429+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yoken''s Whale Neon Sign', 'yokens-whale-neon-sign', 'roadside-oddities', 43.0451, -70.77305, 'Portsmouth', 'NH', 'A restored neon whale once advertised Yoken''s restaurant, a longtime Portsmouth-area seafood landmark. Although the restaurant itself disappeared, the glowing whale was preserved and returned to the old property as a piece of roadside Americana. It is especially striking after dark and can be viewed from public roadside areas.', 'roadside', null, 'https://www.roadsideamerica.com/tip/61603', '2026-09-09T04:49:39.808526+00:00', null, null, null, null, null, 'America/New_York'),
  ('Young Boulder — Rhode Island Troll Trail', 'young-boulder-rhode-island-troll-trail', 'roadside-oddities', 41.5592, -71.68773, 'Richmond', 'RI', 'Young Boulder is a giant recycled-wood troll hidden near Browning Mill Pond in the Arcadia Management Area. Added in 2025, the sculpture requires a woodland walk and turns the search itself into part of the attraction. Follow current trail rules and do not climb on the sculpture.', 'open', null, 'https://www.southcountyri.com/thomas-dambo-trolls/', '2026-09-09T04:49:27.913704+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ypsilanti Water Tower', 'ypsilanti-water-tower', 'roadside-oddities', 42.24555, -83.62469, 'Ypsilanti', 'MI', 'Built in 1890 from local stone, Ypsilanti''s tall cylindrical water tower has become famous far beyond its engineering history because of its unmistakably suggestive shape. The National Register-listed structure remains an exterior roadside landmark; the tower itself is not a normal walk-in attraction.', 'roadside', null, 'https://www.us12heritagetrail.com/asset.asp?aid=135&ait=av', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Zanesville Y-Bridge', 'zanesville-y-bridge', 'roadside-oddities', 39.94042, -82.01431, 'Zanesville', 'OH', 'Zanesville''s bridge over the confluence of the Licking and Muskingum rivers splits into three directions, creating the unusual Y shape that has defined the crossing for generations. The current structure is the fifth bridge at the location and can be driven across or viewed from nearby public riverfront areas.', 'roadside', null, 'https://www.atlasobscura.com/places/zanesville-ybridge', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Zimmerman House', 'zimmerman-house', 'roadside-oddities', 43.02172, -71.46287, 'Manchester', 'NH', 'Frank Lloyd Wright designed the Zimmerman House as a compact Usonian home tailored closely to its owners, furnishings and landscape. The Currier Museum of Art now operates guided tours, giving visitors a rare chance to enter an intact Wright residence rather than only viewing it from outside. Tours are ticketed and depart under museum procedures; do not wander the residential neighborhood expecting independent access.', 'limited', null, 'https://www.currier.org/frank-lloyd-wright', '2026-09-09T04:49:39.808526+00:00', null, 'https://www.currier.org/frank-lloyd-wright', null, null, null, 'America/New_York'),
  ('Zinc Miner Statue', 'zinc-miner-statue', 'roadside-oddities', 41.11331, -74.58838, 'Franklin', 'NJ', 'A bronze miner holding a pick stands near the Franklin Mineral Museum entrance, representing generations who worked the area''s exceptionally mineral-rich zinc deposits. The figure wears a carbide lamp and stands on a pile of rock as a memorial to Franklin''s mining workforce.', 'open', null, 'https://www.roadsideamerica.com/story/40021', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York')
